INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (1,'Workflow_100031_Contact_ECP001','$invoiceType = \"PurchaseInvoice\"\n$name = \"Euro Car Parts Limited.\"\n$currency = \"GBP\"\n\n// Get vat number by finding the line with the label \'VAT:\'\n$vatNumber = get line starting \"VAT:\" => skip words 1 => get text\n\n// Get invoice number by finding the box it is inside\n$invoiceNumber = get text in box 580 560 470 540 => get text\n\n// Get invoice date by finding the box it is inside\n$invoiceDate = get text in box 615 600 340 400 => get date \"dd/MM/yyyy\"\n\n// Clear tax info that is not vertically aligned with figures\n@rateTop = get line containing \"Rate Goods Vat\" => top\ndelete text in box @rateTop page.bottom 0 page.middleX\n\n$net = get line starting \"Subtotal\" => take last words 1 => get decimal\n$tax = get line starting \"Vat\" => take last words 1 => get decimal\n$total = get line starting \"Total (GBP)\" => take last words 1 => get decimal\n\n// Find the top of the line items table\n@lineItemsTop = get line containing \"Line Qty Part no.\" => top\n// Find the bottom of the line items table\n@lineItemsBottom = get line starting \"Subtotal\" => top\n// Read the line items table\n$lineItems = get table @lineItemsTop @lineItemsBottom page.left 80 120 220 380 425 490 540 page.right => describe table true - #Units Code Details - - #Price *#Net\n','2019-02-12 09:33:47',0);
