INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (13,'Workflow_80045_Contact_1','$invoiceType = \"PurchaseInvoice\"\n$currency = \"GBP\"\n$name = \"Student Finance England\"\n\n// Get invoice number by finding the line with the label \'Invoice Reference Number:\'\n$invoiceNumber = get line starting \"Invoice Reference Number:\" => skip words 3 => get text\n\n// Get vat number by finding the line with the label \'VAT Number:\'\n$vatNumber = get line starting \"VAT Number:\" => take last words 1 => get text\n\n// Get invoice date by finding the line with the label \'Invoice Date:\'\n$invoiceDate = get line containing \"Invoice Date:\" => take last words 1 => get date \"dd/MMM/yy\"\n\n$description = get line starting \"A2B Assessments\" => get text\n\n$total = get line containing \"Total £\" => take last words 1 => get decimal\n\n// Find the top of the line items table\n@lineItemsTop = get line containing \"Amount Inc. VAT\" => top\n// Find the bottom of the line items table\n@lineItemsBottom = get line containing \"Total £\" => top\n// Read the line items table\n$lineItems = get table @lineItemsTop @lineItemsBottom page.left 160 250 340 430 page.right => describe table true Details #Units #Net #Tax **#Total\n','2019-03-14 15:15:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (14,'RBSNatWest1','$source = \"RBS/NatWest UK\"\n\n// Discard XXXX Statement in top left of page 1 as it gets in the way of finding the account number\n@dropBottom = subtract page.top 50\ndelete text in box page.top @dropBottom page.left page.middleX\n\n// Get account name and number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\"  => take words 1 => get text\n//$accountNumber = get line containing \"Account number:\" => take words 1 => get text\n$accountName = get line starting \"Branch Details\" => top => get line above => get text\n\n// Get period from/to\n@period = get line containing \"Period\" => take last words 7\n$periodFrom = take words @period 3 => get date \"d MMM yyyy\"\n//$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n\n\n// Discard addresses as they get in the way of the balances\n@dropTop = get line starting \"Branch Details\" => bottom\n@dropBottom = get line containing \"New Balance\" => bottom\ndelete text in box @dropTop @dropBottom page.left page.middleX\n\n// Get opening and closing balances\n$openingBalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\n//$closingBalance = get line containing \"New Balance\" => take last words 1 => get decimal\n@broughtForward = get line starting \"Date Type Description\"\n\n@period = get last line containing \"Period\" => take last words 7\n$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n$closingBalance = get last line containing \"New Balance\" => take last words 1 => get decimal\ngo to page 1\n\n// Get start of table\n@transactionsTop = bottom @broughtForward => get line below\n\n// Discard header and footer\nbottom @broughtForward => ignore header above\ndelete all lines starting \"BROUGHT FORWARD\"\ndelete all lines starting \"CONTINUED\"\nget last line starting \"©\" => top => ignore footer below\n// Some statements have extra text, but this text is higher than some transaction rows so delete below and then delete the line\n//get last line starting \"Deposit Guarantee Scheme Information\" => bottom => ignore footer below\ndelete all lines starting \"Deposit Guarantee Scheme Information\"\ndelete all lines containing \"under the Financial Services Compensation Scheme (FSCS).\"\ndelete all lines containing \"For further information\"\n\n//get last line starting \"Your interest rate for\" => bottom => ignore footer below\ndelete all lines starting \"Your interest rate for\"\ndelete all lines starting \"©\"\n\ndelete all lines containing \"Your interest rate for BUSINESS RESERVE ACCOUNT\"\ndelete all lines containing \"Your interest rate is\"\ndelete all lines containing \"This is based on your balance from the closing date of this statement period\"\ndelete all lines containing \"For more information on your product or any conditions\"\ndelete all lines starting \"Deposit Guarantee Scheme Information\"\ndelete all lines starting \"This is an eligible deposit\"\ndelete all lines containing \"www.ulsterbank\"\ndelete all lines containing \"Your deposit is eligible for protection under the Financial Services Compensation Scheme\"\ndelete all lines containing \"For further information about the compensation provided by the FSCS\"\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line above 0\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 86 187 340 420 490 570 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit *#Balance','2023-03-01 11:20:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (15,'RBS/NatWest Transactions','$source = \"RBS/NatWest UK Transactions\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\nset negative marker \"Dr\"\n// Discard headings in top left of page 1\n@dropBottom = get line starting \"Your transactions\" => bottom\ndelete text in box page.top @dropBottom page.left page.middleX\n\n// Get account name and number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => get text\n$accountName = get line starting \"Account name:\" => skip words 2 => get text\n\n// Discard addresses as they get in the way of the balances\n@dropTop = get line starting \"Branch Details\" => bottom\n@dropBottom = get line containing \"New Balance\" => bottom\ndelete text in box @dropTop @dropBottom page.left page.middleX\n\n// Discard footer\n//get line starting \"Page\" => top => ignore footer below\n\n@transactionsfirstTop = get line starting \"Date Type Description\" => bottom => get line below => top\n//@transactionsfirstBottom = get line starting \"Date Type Description\" => bottom => get line below => bottom\n@transactionsfirstBottom = get line starting \"Date Type Description\" => bottom => get line below => bottom => get line below => bottom\n//$openingBalance = get text in box @transactionsfirstTop @transactionsfirstBottom 460 560 => get decimal\n$openingBalance = get text in box @transactionsfirstTop @transactionsfirstBottom 460 560 => take words 1 => get decimal\n//$periodTo = get text in box @transactionsfirstTop @transactionsfirstBottom 0 100 => get date \"d MMM yyyy\"\n$periodTo = get text in box @transactionsfirstTop @transactionsfirstBottom 0 105 => take words 3 => get date \"d MMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line starting \"Date Type Description\" => bottom => get line below\n//@transactionsBottom = get line containing \"©\" => if not found then blank => top => get line above\n@transactionsBottom = get last line containing \"©\" => top => get line above\n\n// Get period from/to - Not all pdfs include period dates so use dates in transaction list\n//@transactionsLastBottom = get line starting \"©\" => top => get line above => bottom\n@transactionsLastBottom = get last line starting \"©\" => top => get line above => bottom\n//$periodFrom = get text in box page.top @transactionsLastBottom 0 100 => take last words 3 => get date \"d MMM yyyy\"\n$periodFrom = get text in box page.top @transactionsLastBottom 0 105 => take last words 3 => get date \"d MMM yyyy\"\n\n// Get opening and closing balances - Currently unreliable as not all pdfs include the first balance\n$closingBalance = get text in box page.top @transactionsLastBottom 460 560 => take last words 1 => get decimal\n\ndelete all lines containing \"Account type:\"\ndelete all lines containing \"Account number:\"\ndelete all lines containing \"Sort code:\"\ndelete all lines containing \"Account name:\"\ndelete all lines containing \"Date:\"\ndelete all lines containing \"Your transactions\"\ndelete all lines containing \"Showing\"\ndelete all lines containing \"Date Type Description\"\ndelete all lines containing \"downloaded from the NatWest\"\ndelete all lines containing \"registered in England and Wales\"\ndelete all lines containing \"natwest.co.uk for more information\"\nignore footer below 95\n\ndelete all lines starting \"Page\"\n\n// Read the transactions  \n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 150 320 390 460 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit *#Balance\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 5 0 105 150 330 400 470 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 4.5 0 104 150 330 400 470 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance','2023-09-06 10:42:38',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (16,'HSBC','$source = \"HSBC UK\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Discard hidden text\ndelete white words\ndelete all pages containing \"Lost and stolen cards\"\ngo to page 1\n\n// Get account name and number\n@accountLine = get line starting \"Account Name\" => bottom => get line below\n$accountNumber = take last words @accountLine 2 => take words 1 => get text\n@accountNameTop = top @accountLine\n@accountNameRight = take last words @accountLine 3 => left\n@accountNameBottom = bottom @accountLine\n$accountName = get text in box @accountNameTop @accountNameBottom 0 @accountNameRight => get text\n\n@headerlineRight = take last words @accountLine 1 => left\n@NameLine = get text in box @accountNameTop @accountNameBottom 0 @headerlineRight => get text\n@transHeader = get line starting \"Account Name Sortcode\" => bottom => get line below => bottom => get line below => get text\n\n// Get period from\n@periodBottom = get line starting \"Account Name\" => top\n@periodTop = add @periodBottom 80\n@period = get text in box @periodTop @periodBottom 0 page.middleX\n//$periodFrom = take words @period 2 => get date \"d MMMM\"\n\n//@periodFromtop = get line containing \"BALANCE BROUGHT FORWARD\" => top\n//$periodFrom = get text in box @periodFromtop 10 0 130 => take words 3 => get date \"dd MMM yy\"\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => take words 3 => get date \"dd MMM yy\"\n\n//$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n\n// Discard the address as it interferes with the balance block\n@pointerbalance = get line containing \"Opening Balance\"\ndelete text in box page.top @periodTop page.left page.middleX\n\n// Get opening and closing balances\n@openingBalanceRaw = get line containing \"Opening Balance\" => skip words 2\n$openingBalance = get decimal @openingBalanceRaw\n$openingBalanceText = get text @openingBalanceRaw\n//@closingBalanceRaw = get line containing \"Closing Balance\" => skip words 2\n//$closingBalance = get decimal @closingBalanceRaw\n//$closingBalanceText = get text @closingBalanceRaw\n@balanceBroughtForwardRaw = get line containing \"BALANCE BROUGHT FORWARD\" => skip words 3\n$balanceBroughtForward = get decimal @balanceBroughtForwardRaw\n$balanceBroughtForwardText = get text @balanceBroughtForwardRaw\n\ndelete all lines starting \"Your HSBC\"\n// Get period to\n@periodtoBottom = get last line starting \"Account Name\" => top\n@periodtoTop = add @periodtoBottom 80\n$periodTo = get text in box @periodtoTop @periodtoBottom 0 page.middleX => take last words 3 => get date \"d MMMM yyyy\"\n\n\n// Discard the address as it interferes with the balance block\n@pointerclbalance = get last line containing \"Closing Balance\"\ndelete text in box page.top @periodTop page.left page.middleX\n@closingBalanceRaw = get last line containing \"Closing Balance\" => skip words 2\n$closingBalance = get decimal @closingBalanceRaw\n$closingBalanceText = get text @closingBalanceRaw\n\n\n// Get end of table before discarding marker text\n@transactionsBottom = get last line containing \"BALANCE CARRIED FORWARD\" => top => get line above\n\n// Get start of table before discarding marker text\n\ngo to page 1\n@transactionsTop = get line containing \"Date Payment type and details Paid out Paid in Balance\" => bottom => get line below\n@topblanklinetop = get line containing \"Date Payment type and details Paid out Paid in Balance\" => bottom\n@topblanklinebottom = get line containing \"BALANCE BROUGHT FORWARD\" => top\ndelete text in box @topblanklinetop @topblanklinebottom page.left page.right\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\n\n@dateCoor = get line containing \"Date Payment type\" => get words after \"Date\" => left\n@balanceCoor = get line containing \"Paid in Balance\" => take last words 1 => right\n@dateCoor = subtract @dateCoor 7\n@balanceCoor = add @balanceCoor 15\n\n@debitleft = get line containing \"Date Payment type and details Paid out Paid in Balance\" => get words after \"details\" => left\n@debitleft = subtract @debitleft 25\n\n@creditleft = get line containing \"Date Payment type and details Paid out Paid in Balance\" => get words before \"Paid in\" => right\n@creditleft = add @creditleft 15\n\n@Balanceleft = get line containing \"Date Payment type and details Paid out Paid in Balance\" => get words before \"Balance\" => right\n@Balanceleft = add @Balanceleft 15\n\n// Discard page footer\ngo to page 1\nget line above 0 => top => ignore footer below\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\ndelete all lines containing \"BALANCE CARRIED\"\ndelete all lines starting \"FORWARD\"\n\n\ndelete all lines containing \"Most deposits made by HSBC\"\ndelete all lines containing \"For further information\"\ndelete all lines containing \"call into your nearest branch\"\ndelete all lines containing \"available on our website\"\n\ndelete all lines containing \"Your deposit is eligible for\"\ndelete all lines containing \"refer to the FSCS website\"\ndelete all lines containing \"Further details can be\"\ndelete all lines containing \"on our website\"\n\ndelete all lines starting @NameLine\n//delete all lines starting @transHeader\n\ndelete all lines ending \"AER\"\ndelete all lines ending \"EAR\"\ndelete all lines containing \"Credit inte re s t is not applied\"\ndelete all lines starting \"upto\"\ndelete all lines starting \"ove r 2\"\ndelete all lines starting \"Credit Inte\"\ndelete all lines starting \"Credit inte\"\ndelete all lines starting \"Inte re st Rate s balance\"\ndelete all lines starting \"Interest Rates balance\"\ndelete all lines starting \"Debit inte re\"\n\ndelete all lines starting \"ove r 1\"\ndelete all lines starting \"ove r 2\"\ndelete all lines starting \"ove r 3\"\ndelete all lines starting \"ove r 4\"\ndelete all lines starting \"ove r 5\"\ndelete all lines starting \"ove r 6\