INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (58,'Handelsbanken_Ascending','$source = \"Handelsbanken_Ascending\"\n\n// Discard hidden text\ndelete white words\ndelete tiny words\n\n// Get account name\n$accountName = get line starting \"Customer:\" => skip words 2 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account:\" => skip words 1 => get text\n\n// Opening and Closing Balance\n@OpeningBalanceText = get line containing \"Opening balance\" => take last words 1\n$OpeningBalance = take last words @OpeningBalanceText 1 => get decimal\n\n\n//PeriodFrom and PeriodTo\n$PeriodFromText = get line starting \"Value date range:\" => skip words 3 \n$PeriodFrom =  get words before $PeriodFromText \"-\" => get date \"dd MMM yyyy\"\n$PeriodTo =  get words after $PeriodFromText \"-\" => get date \"dd MMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line starting \"Value date Particulars Debit Credit Balance\" => bottom => get line below => bottom => get line below => bottom => get line below\n\n// Discard page header\nget last line containing \"Page\" => bottom => ignore header above\n\n// Get end of table\n@transactionsBottom = get last line containing \"Transactions list\" => top => get line above\n\n// Get Closing Balance\n@pageFooter = get last line starting \"Transactions list\" => top\n@infoLast = get text in box page.top @pageFooter 490 570\n$closingBalanceText = take last words @infoLast 1 => get text\n$ClosingBalance = take last words @infoLast 1 => get decimal\n\ndelete all lines containing \"Opening balance\"\ndelete all lines starting \"Transactions list\"\n\n// Discard page footer\nignore footer below 40\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 270 380 480 565 => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance','2022-06-30 05:06:31',0);
