page table @transactionsTop @transactionsBottom 0 110 407 455 500 580 => describe table false \"Date[d MMM]\" Details #Credit[0,000.00] #Debit *#Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 110 428 407 455 500 580 => describe table false \"Date[d MMM]\" Details - #Credit[0,000.00] #Debit *#Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 110 428 403.5 455 500 580 => describe table false \"Date[d MMM]\" Details - #Credit[0,000.00] #Debit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 110 428 398 455 500 580 => describe table false \"Date[d MMM]\" Details - #Credit[0,000.00] #Debit *#Balance','2024-04-30 08:21:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (60,'NationWide_UK','$source = \"NationWide_UK\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 5\n\n// Discard hidden text\n//delete white words\ndelete tiny words\n\n// Get account name\n$accountName = get text in box 700 650 page.left page.middleX => get text\n\n// Get Account Number\n@panelTop = get line containing \"Sort code\" => top => get line above  => top\n@panelLeft = get line containing \"Sort code\" => get words before \"code\" => take last words 1 => left => subtract 3\n@panelBottom = get line containing \"End balance\" => bottom\n@panelWords = get text in box @panelTop 0 @panelLeft page.right\n$accountNumber = get words after @panelWords \"Account no\" => take words 1 => get text\n\n//Get opening and closing balances\n$openingBalance = get words after @panelWords \"Start balance\" => take words 1 => get decimal\n$closingBalance = get words after @panelWords \"End balance\" => take words 1 => get decimal\ndelete text in box on every page page.top page.bottom @panelLeft page.right\n\n// Get period from/to\n@firsttransactionyear = get line containing \"Balance from statement\" => take words 1 => get text\n@periodFromText = get line containing \"Balance from statement\" => skip words 6\n$periodFrom = take words @periodFromText 1 => get date \"dd/MM/yyyy\"\n@periodToText = get line containing \"Statement date:\" => skip words 4\n//$periodTo = take words @periodToText 3 => get date \"dd MMMM yyyy\"\n@periodBotom = get line containing \"Balance from statement\" => top\n$periodTo = get text in box @panelTop @periodBotom 340 @panelLeft => take words 3 =>  get date \"dd MMMM yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Description\" => bottom => get line below\n@DateLeft = get line containing \"Date Description\" => get words before \"Description\" => left => subtract 6\n@DescLeft = get line containing \"Date Description\" => get words after \"Date\" => left => subtract 4\n@DescRight = get line containing \"Date Description\" => get words after \"Description\" => take words 1 => right => add 25\n@OutLeft = get line containing \"Date Description\" => get words after \"Description\" => left => subtract 10\n@InLeft = get line containing \"Date Description\" => get words after \"Out\" => left => subtract 12\n@BalanceLeft = get line containing \"Date Description\" => get words after \"In\" => left => subtract 12\n\n\n// Discard page header\n//get last line containing \"transactions (continued)\" => bottom => ignore header above\n//get last line containing \"Date Description £ Out £ In £ Balance\" => bottom => ignore header above\nget line containing \"Nationwide Building Society\" => top => ignore footer below\n\n\n//Page Footer\n//@transactionsBottom = get last line starting \"Please check your statement\" => top => get line above => top => get line above\n@transactionLastTable = get last line containing \"Date Description £ Out £ In £ Balance\" => top\n@transactionLastLine = get text in box @transactionLastTable page.bottom page.left page.right => bottom\n@transactionsBottom = get line at @transactionLastLine\ndelete text in box on every page page.top page.bottom @panelLeft page.right\n\n//go to page 1\ndelete all lines containing \"transactions (continued)\"\ndelete text in box on every page page.top 760 page.left page.right\n\n\n// Discard unwanted lines\ndelete all lines starting @firsttransactionyear\ndelete all lines containing \"Balance from statement\"\ndelete all lines containing \"Nationwide Building Society is authorised\"\ndelete all lines containing \"Your FlexPlus\"\ndelete all lines containing \"Date Description £ Out £ In £ Balance\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 240 304 375 => describe table false \"Date[dd MMM]\" Details *#Debit *#Credit\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 244 304 375 => describe table false \"Date[dd MMM]\" Details *#Debit *#Credit\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 246 304 375 => describe table false \"Date[dd MMM]\" Details *#Debit *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @DescLeft @DescRight @OutLeft @InLeft @BalanceLeft => describe table false \"Date[dd MMM]\" Details - *#Debit *#Credit','2025-02-12 08:12:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (61,'AIB_BusinessBanking','$source = \"AIB_BusinessBanking\"\n$features = \"NO_OPENING_BALANCE\"\n\nset negative marker \"dr\"\n\n// Get Account Details\n$accountNumberText = get line containing \"Account No:\" => get words after \"Account No:\"\n$accountNumber = take words $accountNumberText 1 => get text\n$accountNameText = get line containing \"Account No:\" => get words before \"Account No:\"\n$accountName = get text $accountNameText\n\n//Get Closing Balance\ngo to last page\n@infoLast = get text in box page.top 25 410 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\n// Get PeriodTo\ngo to page 1\n//@bottomHeader = get line containing \"Statement of Account with Allied Irish Banks\" => top\n @bottomHeader = get line containing \"Statement of Account with Allied Irish\" => top\n$periodToText = get text in box page.top @bottomHeader page.middleX page.right => take last words 2\n$periodTo = take words $periodToText 1 =>  get date \"dd/MM/yyyy\"\n\n// Get start of table\n@transactionsTop = get line containing \"Debit Credit Balance\" => bottom => get line below\n\n// Get PeriodFrom\n$PeriodFromText = take words @transactionsTop 1 =>  get text\n$PeriodFrom = take words @transactionsTop 1 =>  get date \"dd/MM/yyyy\"\n\n// Discard page header\n// get last line containing \"Debit Credit Balance\" => bottom => ignore header above\n\n// Get end of table\n//@transactionsBottom = get last line containing \"https://ibusinessbanking.aib.ie/ibb/controller\" => top => get line above\n  @transactionsBottom = get last line containing \"https://\" => top => get line above\n  delete all lines starting \"https://\"\n\ndelete all lines containing \"Debit Credit Balance\"\ndelete all lines containing \"Statement of Account\"\ndelete all lines containing  \"https://ibusinessbanking.aib.ie/ibb/controller\"\n\n// Discard page footer\nignore footer below 20\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 100 258 340 410 500 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance','2021-11-22 05:56:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (62,'FirstTrustBank','$source = \"FirstTrustBank\"\n\nset negative marker \"dr\"\n\n\n// Get left panel area\n@panelTop = get line containing \"Account name\" => Top\n@panelBottom = get line containing \"Account number\" => bottom => get line below => bottom\n$panelWords = get text in box @panelTop @panelBottom 435 page.right\n\n\n\n// Get account name and number\n$accountNumber = take last words $panelWords 1 => get text\n$accountName = get words after $panelWords \"Account name\" => take words 2 => get text\n\n\n// Get Balance Forward\n$BalanceForwardText = get line containing \"BALANCE FORWARD\" => take words 6\n\n\n// Get period from\n$periodFrom = take words $BalanceForwardText 3 => get date \"d MMM yyyy\"\n\n\n// Get opening balances\n$openingBalance = take last words $BalanceForwardText 1 => get decimal\n\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Details Debit\" => bottom => get line below\n\n\n\n// Get period to\n$statementPeriod = get line containing \"Period of statement\" => bottom => get line below\n$periodToText = take last words $statementPeriod 3 => get text\n$periodTo = take last words $statementPeriod 3 => get date \"d MMM yyyy\"\n\n\n\n//Get Closing Balance\n@LastBalanceForwardText = get last line containing \"BALANCE FORWARD\" => top\n@LastPageFooter = get last line starting \"Interest on unauthorised debit balances\" => top\n$infoLast = get text in box @LastBalanceForwardText @LastPageFooter page.middleX 440\n$closingBalance = take last words $infoLast 1 => get decimal\n\n\ndelete text in box on every page page.top page.bottom 435 page.right\n\n\n@tableHeader = get line containing \"Date Details Debit\" => bottom\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n\n\n// Get end of table\n@transactionsBottom = get last line starting \"Interest on unauthorised debit balances\" => top => get line above\n\ndelete all lines containing \"This is an eligible deposit under the Financial Services\"\n\n// delete all lines containing \"BALANCE FORWARD\"\n\ngo to page 1\n@footerTobeDeleted = get line containing \"Interest on unauthorised debit balances\" => top\ndelete text in box on every page @footerTobeDeleted page.bottom page.left page.right\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 95 230 300 350 440 => describe table false \"*Date[d MMM yyyy]\" Details *#Debit *#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 95 230 298 350 440 => describe table false \"*Date[d MMM yyyy]\" Details *#Debit *#Credit #Balance','2025-07-24 06:50:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (63,'ClydesdaleBank_iOS_Version','$source = \"ClydesdaleBank_iOS_Version\"\n \n\n // Discard headings in top left of page 1\n @panelTop = get line starting \"Account number\" => bottom\n @panelBottom = get line starting \"Date Description Type\" => top\n $panelData = get text in box @panelTop @panelBottom page.left page.right\n \n // Get account name and number\n $accountNumber = take words $panelData 1 => get text\n $accountName = get text in box 800 @panelTop page.left page.middleX => take words 3 => get text\n \n // Get period from/to\n @statementPeriod = take last words  $panelData 7\n $periodFrom = take words @statementPeriod 3 => get date \"dd MMM yy\"\n $periodTo = take last words @statementPeriod 3 => get date \"dd MMM yy\"\n delete text in box @panelTop @panelBottom page.left page.right\n \n // Get opening and closing balances\n \n @openingBalance = get last line containing \"Opening Balance\" =>  get words after \"Opening Balance\"\n $openingBalance = get decimal @openingBalance\n $openingBalanceText = get text @openingBalance\n @closingBalance = get line containing \"Closing balance\"  =>  get words after \"Closing balance\"\n $closingBalance = get decimal @closingBalance\n $closingBalanceText = get text @closingBalance\n \n // Get start of table\n go to page 1\n @transactionsTop = get line starting \"Date Description Type\" => bottom => get line below\n @transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n \n delete all lines starting \"Total debits\"\n delete all lines starting \"Total credits\"\n delete all lines containing \"Closing balance\"\n delete all lines containing \"Opening Balance\"\n delete all lines starting \"Date Description Type\"\n delete all lines containing \"https://internet-banking\"\ndelete all lines containing \"Statement\"\n \n // Read the transactions\n $transactions = get multi page table @transactionsTop @transactionsBottom 0 85 261 375 435 530 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance','2021-08-06 05:47:55',0);
