 80 300 420 600 700 810 => describe table false \"Date[dd MMM yy]\" Details TransactionType #Debit #Credit *#Balance\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 265 350 430 497 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance','2021-08-06 05:47:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (66,'CommonWealthBank','$source = \"CommonWealthBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\nset negative marker \"DR\"\n\n// Delete vertical text\n//delete rotated words\ndelete white words\n\n// Discard headings in top left of page 1\n@panelTop = get line starting \"Your Statement\" => bottom => get line below => bottom\n@panelBottom = get line containing \"Enquiries\" => top\n$panelData = get text in box @panelTop @panelBottom 350 page.right\n\n// Discard rotated text on the left\n$panelData11 = delete text in box on every page page.top page.bottom 0 40 => get text\n\n// Get account number\n$accountNumber = get words after $panelData \"Account Number\" => take words 3 => get text\n$accountName = get text in box @panelTop @panelBottom page.left 150 => take words 3 => get text\n\n// Get period from/to\n@statementPeriod = get words after $panelData \"Period\" => take words 7\n$periodFrom = take words @statementPeriod 3 => get date \"d MMM yyyy\"\n$periodto = get words after @statementPeriod \"-\" => take words 3 => get date \"d MMM yyyy\"\n\n//@ENQvarText = get last line containing \"Enquiries\" => top => get line above => top => get line above => get words after \"-\"\n//$periodto = take words @ENQvarText 3 => get date \"d MMM yyyy\"\n\n@panelToplast = get last line starting \"Your Statement\" => bottom => get line below => bottom\n@panelBottomlast = get last line starting \"Enquiries\" => top\n$panelDatalast = get text in box @panelToplast @panelBottomlast page.left page.right\n@statementPeriodLast = get words after $panelDatalast \"Period\" => take words 7\n\n// Get closing balances\n//@closingBalance =  get words after $panelDatalast \"Closing Balance\" => take words 2\n@closingBalance = get last line containing \"CLOSING BALANCE\" => take last words 2\n$closingBalance = get decimal @closingBalance\n$closingBalanceText = get text @closingBalance\n\ngo to page 1\ndelete text in box @panelTop @panelBottom page.left page.right\n\n// Get opening balance\ngo to page 1\n@openingBalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\"\n$openingBalance = get decimal @openingBalance\n$openingBalanceText = get text @openingBalance\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Transaction Debit Credit Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\n//Discard unwanted heraders and footers(multi-periods)\ngo to page 1\n@panelTopOB = get line containing \"Debit Credit\" => bottom => get line below => bottom\ndelete text in box page.top @panelTopOB page.left page.right\n\n@panelMidOB = get line containing \"OPENING BALANCE\" => if not found then blank => top\ndelete text in box page.top @panelMidOB page.left page.right\n\n$tablefooter = get line starting \"Transaction Summary\" => if not found then blank => top =>  get line above => get text\n@tablefooter = get line starting \"Transaction Summary\" => if not found then blank => top => get line above => top\n@tablefooterBottom = get line containing \"Account Fee\" => if not found then blank => top\ndelete text in box @tablefooter @tablefooterBottom page.left page.right\n\n@panelBottomlastOP = get last line containing \"OPENING BALANCE\" => bottom\n@panelToplastOP = get last line starting \"Your Statement\" => if not found then blank => bottom => get line below => bottom\ndelete text in box @panelToplastOP @panelBottomlastOP page.left page.right\n\ndelete all lines containing \"CLOSING BALANCE\"\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"Date Transaction Debit Credit Balance\"\ndelete all lines starting \"Statement\"\ndelete all lines starting \"Opening balance - Total debits\"\ndelete all lines starting \"$\"\ndelete all lines starting \"Account Number\"\ndelete all lines starting \"Statement\"\ndelete all lines starting \"Transaction Summary\"\ndelete all lines starting \"Account Fee\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 90 87 305 395 380 455 550 => describe table false \"*Date[dd MMM]\" - Details #Debit - #Credit #Balance','2025-07-24 06:51:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (67,'WellsFargoUS_FeePeriod','$source = \"WellsFargoUS_FeePeriod\"\n$features = \"NO_TRANSACTION_YEAR NO_OPENING_BALANCE\"\n\n@summaryLine = get line containing \"Account number:\" => get words after \"Account number:\"\n$accountNumber = take words @summaryLine 1 => get text\n\n@summaryTop = get line containing \"Account number:\" => get words before \"number:\" => take last words 1 => top\n@summaryBottom = get line containing \"Account number:\" => get words before \"number:\" => take last words 1 => top => subtract 80\n@summaryLeft = get line containing \"Account number:\" => get words before \"number:\" => take last words 1 => left\n@summary = delete text in box @summaryTop @summaryBottom @summaryLeft page.right\n\n$closingBalance = get line starting \"Ending balance on\" => get words after \"Ending balance on\" => skip words 1 => get decimal\n\n@endingSummaryLineTop = get line starting \"Ending balance on\" => top\n@endingSummaryLineBottom = get line starting \"Ending balance on\" => bottom\n@endingSummary = delete text in box @endingSummaryLineTop @endingSummaryLineBottom page.left page.right\n\n// Get period from/to\n$statementPeriod = get line starting \"Fee period\" => get words after \"Fee period\" => take words 3\n$periodFrom = take words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n$periodTo = get words after $statementPeriod \"-\" => get date \"MM/dd/yyyy\"\n\n// Get account name\n$accountName = \"Wells_Fargo_user\"\n\n// Get opening balances\n//$closingBalance = get last line starting \"Ending balance on\" => skip words 4 => get decimal\n\n// Get start of transactions table\ngo to page 1\n@transactionsTop = get line starting \"Date Number Description\" => if not found then blank => bottom => get line below\n\n\n// Get end of transactions table\n@getlast = get last line containing \"Date Number Description\"\n//@transactionsBottom = get line starting \"Ending balance\" => if not found then blank => top => get line above\n//@transactionsBottom = get line starting \"Ending balance\" => if not found then blank => top => get line above\n@transactionsBottom = get line starting \"Totals\" => top => get line above\n\n// below lines are used to delete all the text lines after last transaction\n@getlast = get last line containing \"Date Number Description\"\n@ending = get line containing \"Ending balance\" => top\n@ending2 = get line starting \"Totals\" => top\ndelete text in box @ending 0 0 page.right\ndelete all lines containing \"Ending balance\"\ndelete text in box @ending2 0 0 page.right\n\n// Remove unwanted lines that appear in middle of transactions\nignore header above 740\ndelete all lines starting \"Account number\"\ndelete all lines starting \"Primary account number:\"\ndelete all lines starting \"Sheet\"\ndelete all lines starting \"Transaction history (continued)\"\ndelete all lines containing \"Transaction History (continued)\"\ndelete all lines starting \"Check Deposits/ Withdrawals/ Ending daily\"\ndelete all lines starting \"Date Number Description\"\ndelete all lines containing \"■ Page\"\n\n// Get end of transactions table\n//@transactionsBottom = get line starting \"Ending balance\" => if not found then blank => top => get line above\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 150 380 440 510 600 => describe table false \"*Date[M/d]\" #ChequeNumber Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 380 440 510 600 => describe table false \"*Date[M/d]\" Details #Credit #Debit #Balance','2025-06-25 11:52:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (68,'ChaseBank_US','$source = \"ChaseBank_US\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Delete vertical text\ndelete rotated words\ndelete white words\ndelete tiny words\n\ngo to page 1\n$deleteleftpanel = delete text in box on every page page.top page.bottom 0 20 => get text\n\ngo to page 1\n$deleterightpanel = delete text in box on every page page.top page.bottom 590 800 => get text\n\ngo to page 1\n// Get Account Number\n@accountNumberText = get line containing \"Account Number:\" => get words after \"Account Number:\"\n$accountNumber = take words @accountNumberText 1 => get text\n\n// Get bank details\n\n@summaryLine = get line containing \"CUSTOMER SERVICE INFORMATION\" => top\n//$panelDetails = get text in box page.top @summaryLine page.left page.right\n$panelDetails = get text in box page.top @summaryLine 270 page.right\n$accountName = take words @accountNumberText 1 => get text\n//$accountName = get words before $panelDetails \"Acccount Number:\" => skip words 7 => take words 3 => get text\n$statementPeriod = get words before $panelDetails \"Acccount Number:\" => take words 7\n$PeriodFrom =  get words before $statementPeriod \"through\" => get date \"MMMM dd,yyyy\"\n$PeriodTo =  get words after $statementPeriod \"through\" => get date \"MMMM dd,yyyy\"\ndelete text in box @panelTop @summaryLine page.left page.right\n\n// Get opening and closing balances\n$openingBalanceText = get line starting \"Beginning Balance\" => skip words 2\n$openingBalance = get decimal $openingBalanceText\n//$closingBalanceText = get line starting \"Ending Balance\" => take last words 1\n$closingBalanceText = get last line starting \"Ending Balance\" => take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get start & end of credits table\ngo to page 1\n@creditsTop = get line starting \"DEPOSITS AND ADDITIONS\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line starting \"Total Deposits and Additions\" => if not found then blank => top => get line above\n\n// Get start & end of checks tables\ngo to page 1\n@checksTop = get line starting \"CHECKS PAID\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Total Checks Paid\" => if not found then blank => top => get line above\n\n// Get start & end of ATM withdrawals table\ngo to page 1\n@ATMDebitsTop = get line starting \"ATM & DEBIT CARD WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@ATMDebitsBottom = get line starting \"Total ATM & Debit Card Withdrawals\" => if not found then blank => top => get line above\n\n\n// Get start & end of debits table\ngo to page 1\n@debitsTop = get line starting \"ELECTRONIC WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get line starting \"Total Electronic Withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of other withdrawals table\ngo to page 1\n@otherDebitsTop = get line starting \"OTHER WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherDebitsBottom = get line starting \"Total Other Withdrawals\" => if not found then blank => top => get line above\n\n\n// Get start & end of service fees\ngo to page 1\n@feesTop = get line starting \"FEES\" => if not found then blank => bottom => get line below\n@feesBottom = get line starting \"Total Fees\" => if not found then blank => top => get line above\n\n// Discard page header\ngo to page 2\nget line below page.top => bottom => ignore header above\n\n// Discard page footer\nget line above 0 => top => ignore footer below\n\n// Remove unwanted lines\ndelete all lines starting \"DEPOSITS AND ADDITIONS\"\ndelete all lines starting \"Total Deposits and Additions\"\ndelete all lines starting \"CHECKS PAID\"\ndelete all lines starting \"Total Checks Paid\"\ndelete all lines starting \"ELECTRONIC WITHDRAWALS\"\ndelete all lines starting \"Total Electronic Withdrawals\"\ndelete all lines starting \"OTHER WITHDRAWALS\"\ndelete all lines starting \"Total Other Withdrawals\"\ndelete all lines starting \"DATE DESCRIPTION AMOUNT\"\ndelete all lines starting \"DAILY ENDING BALANCE\"\ndelete all lines starting \"CHECK NO. DESCRIPTION PAID AMOUNT\"\ndelete all lines starting \"*end\"\ndelete all lines starting \"*start\"\ndelete all lines containing \"DEBIT CARD WITHDRAWALS\"\ndelete all lines containing \"(continued\"\n\n\n// Read the transactions\n@credits = get multi page table @creditsTop @creditsBottom 0 80 480 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n@checks = get multi page table @checksTop @checksBottom 0 80 480 580 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@ATMDebits = get multi page table @ATMDebitsTop @ATMDebitsBottom 0 70 480 580 => describe table false \"Date[MM/dd]\" Details *#Debit\n@debits = get multi page table @debitsTop @debitsBottom 0 68 480 580 => describe table false \"*Date[MM/dd]\" Details #Debit\n@otherDebits = get multi page table @otherDebitsTop @otherDebitsBottom 0 68 480 580 => describe table false \"Date[MM/dd]\" Details *#Debit\n@Fees = get multi page table @feesTop @feesBottom 0 68 480 580 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n\n$transactions = combine described tables @credits @checks @ATMDebits @debits @otherDebits  @Fees','2024-03-11 10:52:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (69,'AIB_BusinessBanking_PageOf','$source = \"AIB_BusinessBanking\"\n$features = \"NO_OPENING_BALANCE\"\n\nset negative marker \"dr\"\n\n// Get Account Details\n$accountNumberText = get line containing \"Account No:\" => get words after \"Account No:\"\n$accountNumber = take words $accountNumberText 1 => get text\n$accountNameText = get line containing \"Account No:\" => get words before \"Account No:\"\n$accountName = get text $accountNameText\n\n//Get Closing Balance\ngo to last page\n@infoLast = get text in box page.top 25 410 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\n// Get PeriodTo\ngo to page 1\n@bottomHeader = get line containing \"Statement of Account with Allied Irish Banks\" => top\n$periodToText = get text in box page.top @bottomHeader page.middleX page.right => take last words 2\n$periodTo = take words $periodToText 1 =>  get date \"dd/MM/yyyy\"\n\n// Get start of table\n@transactionsTop = get line containing \"Debit Credit Balance\" => bottom => get line below\n\n// Get PeriodFrom\n$PeriodFromText = take words @transactionsTop 1 =>  get text\n$PeriodFrom = take words @transactionsTop 1 =>  get date \"dd/MM/yyyy\"\n\n// Discard page header\n// get last line containing \"Debit Credit Balance\" => bottom => ignore header above\n\n// Get end of table\n@transactionsBottom = get last line containing \"of\" => top => get line above\n\ndelete all lines containing \"Debit Credit Balance\"\ndelete all lines containing \"Statement of Account\"\ndelete all lines containing  \"https://ibusinessbanking.aib.ie/ibb/controller\"\n\n// Discard page footer\nignore footer below 20\n\n// Read the transactions\n $transactions = get multi page table @transactionsTop @transactionsBottom 30 100 258 345 410 500 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance