INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (70,'DankseUK_BookedBalance','$source = \"DankseUK_BookedBalance\"\n$periodBufferDays = 14\n\n// Delete vertical text\ndelete rotated words\n\n// Get account number\n$accountNumber = get line containing \"Amount withdrawn\" => take words 2 => get text\n\n// Get account name\n$accountName = get line starting \"Account holder:\" => skip words 2 => take words 4 => get text\n\n// Get period from/to\n@period = get line starting \"Period:\"\n//$periodFrom = skip words @period 1 => take words 1 => get date \"dd.MM.yyyy\"\n//$periodTo = take last words @period 1 => get date \"dd.MM.yyyy\"\n$periodFrom = skip words @period 1 => take words 1 => get date \"ddMMyyyy\"\n$periodTo = take last words @period 1 => get date \"ddMMyyyy\"\n\n// Get opening and closing balances\n@openingBalanceText = get line starting \"Account:\" => get words after \"Balance at:\" => skip words 1\n$openingBalance = get decimal @openingBalanceText\n//@closingBalanceText = get line starting \" BIC/SWIFT\" => get words after \"Balance at:\" => skip words 1\n@closingBalanceText = get line starting \" BIC/SWIFT\" => get words after \"Balance\" => take last words 1\n$closingBalance = get decimal @closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Booked and Text Amount\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Page\" => top => get line above\n\n// Discard page header\nget last line starting \"Booked and Text Amount\" => bottom => ignore header above\n\ndelete all lines starting \"interest GBP\"\ndelete all lines starting \"date\"\n\n// Discard page footer\nignore footer below 70\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 320 440 580 => describe table false \"*Date[dd.MM.yyyy]\" Details #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 320 440 580 => describe table false \"*Date[ddMMyyyy]\" Details #Credit #Balance','2023-07-10 16:13:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (71,'ANZ_Bank','$source = \"ANZ_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"DR\"\ndelete rotated words\n\n// Get statement period\n$statementPeriod = get line starting \"STATEMENT NUMBER\" => bottom => get line below\n$periodFrom = take words $statementPeriod 3 => get date \"dd MMMM yyyy\"\n//$periodTo = take last words $statementPeriod 3 => get date \"dd MMMM yyyy\"\n\n$get_lastPeriod = get last line starting \"STATEMENT NUMBER\" => bottom => get line below\n$periodTo = take last words $get_lastPeriod 3 => get date \"dd MMMM yyyy\"\n\ngo to page 1\n// Get account name\n$accountName = get line starting \"STATEMENT NUMBER\" => bottom => get line below => bottom => get line below => get text\n\n// Get account number\ngo to page 2\n$accountNumberText = get line starting \"Account Number\" => get words after \"Account Number\"\n$accountNumber = take words $accountNumberText 1 => get text\n\ngo to page 1\n// Get opening and closing balances\n@openingBalanceRaw = get line containing \"OPENING BALANCE\" => skip words 4\n$openingBalanceText = get text @openingBalanceRaw\n$openingBalance = get decimal @openingBalanceRaw\n//@closingBalanceRaw = get line starting \"TOTALS AT END OF PERIOD\" => skip words 7\n\n@closingBalanceRaw = get last line starting \"TOTALS AT END OF PERIOD\" => skip words 7\n$closingBalanceText = get text @closingBalanceRaw\n$closingBalance = get decimal @closingBalanceRaw\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line containing \"OPENING BALANCE\" => bottom => get line below\n\n//@transactionsBottom = get last line containing \"TOTALS AT END OF PERIOD\" => top => get line above\n\n@transactionsBottom = get last line containing \"TOTALS AT END OF PAGE\" => top => get line above\n\n\ngo to page 1\n@get_text = get line containing \"IMPORTANT INFORMATION\" => top\n$getting_my_text = delete text in box @get_t