INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10074,'ChaseBank_CreditCard_Spanish','$source = \"ChaseBank_CreditCard_Spanish\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Parse dates in Spanish\nset culture \"es-US\"\n\n// Delete Unwanted top panel\ndelete text in box page.top 800 page.left page.right\n\n// Get account name\n$accountName = get text in box 110 85 60 190 => get text\n\n// Get account number\n$accountNumber = get line starting \"Número de Cuenta:\" => skip words 3 => get text\n\n// Opening and Closing Balance\n@OpeningBalanceText = get line starting \"Saldo Anterior\" => skip words 2\n$OpeningBalance = take last words @OpeningBalanceText 1 => get decimal\n@ClosingBalanceText = get line starting \"Nuevo Saldo\" => skip words 2\n$ClosingBalance = take last words @ClosingBalanceText 1 => get decimal\n\n//PeriodFrom and PeriodTo\n@PeriodFromText = get line starting \"Fecha de apertura/cierre\" => skip words 3\n$PeriodFrom =  get words before @PeriodFromText \"-\" => get date \"MM/dd/yy\"\n$PeriodTo =  get words after @PeriodFromText \"-\" => get date \"MM/dd/yy\"\n\n// Get start of table\nGo to page 3\n@transactionsTop = get line starting \"Transacción Descripción de la Transacción $ Cantidad\" => bottom => get line below\n\n// Discard page header\nget last line containing \"Transacción Descripción de la Transacción $ Cantidad\" => bottom => ignore header above\n\n// Get end of table\n@transactionsBottom = get last line containing \"Los totales hasta la fecha en\" => top => get line above\n\nget line containing \"Página\" => bottom => ignore footer below\ndelete all lines containing \"Página\"\n\ndelete all lines starting \"Transacción Descripción de la Transacción $ Cantidad\"\ndelete all lines containing \"Los totales hasta la fecha en\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 430 500 => describe table false \"Date[MM/dd]\" Details *#Credit','2020-08-17 10:54:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10075,'BankOfAmerica_CreditCard','$source = \"BankOfAmerica_CreditCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Delete Unwanted top panel\ndelete text in box page.top 800 page.left page.right\n\n// Get account name\n$accountName = get text in box 110 85 60 190 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account#\" => skip words 1 => get text\n\n//PeriodFrom and PeriodTo\n//@PeriodFromText = get line starting \"Account#\" => top => get line above\n//$PeriodFrom =  get words before @PeriodFromText \"-\" => get date \"MMMM d\"\n//$PeriodTo =  get words after @PeriodFromText \"-\" => get date \"MMMM dd, yyyy\"\n\n// Opening and Closing Balance\n//@OpeningBalanceText = get line starting \"Previous Balance\" => skip words 2\n@OpeningBalanceText = get last line starting \"Previous Balance\" => skip words 2\n$OpeningBalance = take words @OpeningBalanceText 1 => get decimal\ngo to page 1\n//$ClosingBalance = take last words @OpeningBalanceText 1 => get decimal\n$ClosingBalance = get line containing \"New Balance Total\" => get words after \"New Balance Total\" => take words 1 => get decimal\n\n\n//PeriodFrom and PeriodTo\n//go to page 2\n//@PeriodText = get line below page.top => bottom => get line above\n//@PeriodFromText = take last words @PeriodText 6\n//$PeriodFrom =  get words before @PeriodFromText \"-\" => get date \"MMMM d\"\n////$PeriodTo = get words after @PeriodFromText \"-\" => get date \"MMMM dd, yyyy\"\n//$PeriodTo = get words after @PeriodFromText \"-\" => get date \"MMMM d, yyyy\"\n\ngo to page 2\n@Datesbottom = get line containing \"Account #\" => bottom\n@Dates = get text in box page.top @Datesbottom 0 480 => take last words 6\n$periodFrom = get words before @Dates \"-\" => get date \"MMMM d\"\n$periodTo = get words after @Dates \"-\" => get date \"MMMM d, yyyy\"\n\n$transTop = get line starting \"IMPORTANT INFORMATION ABOUT THIS ACCOUNT\" => top\n$transTopFromText = delete text in box $transTop page.bottom page.left page.right => get text\n\n// Get start & end of credits table\ngo to page 2\n@creditsTop = get line starting \"Payments and Other Credits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"TOTAL PAYMENTS AND OTHER CREDITS FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Get start & end of Finance Charge table\ngo to page 2\n@financeTop = get line starting \"Finance Charge\" => if not found then blank => bottom => get line below\n@financeBottom = get line starting \"TOTAL FINANCE CHARGE FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Get start & end of debits table\ngo to page 2\n@debitsTop = get line starting \"Purchases and Adjustments\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"TOTAL PURCHASES AND ADJUSTMENTS FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Get start & end of Bank Cash Advances table\ngo to page 2\n@CashAdvancesTop = get line starting \"Bank Cash Advances\" => if not found then blank => bottom => get line below\n@CashAdvancesBottom = get line starting \"TOTAL BANK CASH ADVANCES FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Get start & end of service fees\ngo to page 2\n@feesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\n@feesBottom = get line starting \"TOTAL FEES FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Get start and end of Interest Charged\ngo to page 2\n@interestChargedTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below\n@interestChargedBottom = get line starting \"TOTAL INTEREST CHARGED FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n// Discard page header\ngo to page 2\nget line below page.top => bottom => ignore header above\n\n// Discard page footer\n//get last line containing \"Totals Year-to-Date\" => top => ignore footer below\n\n// Remove unwanted lines\ndelete all lines starting \"Payments and Other Credits\"\ndelete all lines starting \"TOTAL PAYMENTS AND OTHER CREDITS FOR THIS PERIOD\"\ndelete all lines starting \"Finance Charge\"\ndelete all lines starting \"TOTAL FINANCE CHARGE FOR THIS PERIOD\"\ndelete all lines starting \"Purchases and Adjustments\"\ndelete all lines starting \"TOTAL PURCHASES AND ADJUSTMENTS FOR THIS PERIOD\"\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"TOTAL INTEREST CHARGED FOR THIS PERIOD\"\ndelete all lines containing \"Totals Year-to-Date\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"continued on next page\"\ndelete all lines containing \"Date Description Number\"\ndelete all lines starting \"Transaction Posting Reference\"\ndelete all lines starting \"continued on next page..\"\ndelete all lines containing \"Continued\"\ndelete all lines starting \"Bank Cash Advances\"\ndelete all lines starting \"TOTAL BANK CASH ADVANCES FOR THIS PERIOD\"\n\n\n// Read the transactions\n@credits = get multi page table @creditsTop @creditsBottom 70 105 450 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n@finances = get multi page table @financeTop @financeBottom 60 90 350 480 600 => describe table false \"Date[MM/dd]\" Details TransactionType *#Credit\n@debits = get multi page table @debitsTop @debitsBottom 70 105 450 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n@CashAdvances = get multi page table @CashAdvancesTop @CashAdvancesBottom 70 105 450 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n@fees = get multi page table @feesTop @feesBottom 70 105 450 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n@interestCharged = get multi page table @interestChargedTop @interestChargedBottom 70 105 450 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n\n$transactions = combine described tables @credits @finances @debits @CashAdvances @fees @interestCharged','2025-07-24 06:50:03',0);
