600 => describe table false \"Date[MM/dd]\" - Details TransactionType *#Credit\n\n//********End of Interest Charged\n\n// Discard page header\ngo to page 2\nget line below page.top => bottom => ignore header above\n\n// Discard page footer\n//get last line containing \"Finance Charge Calculation\" => top => ignore footer below\n@lastfotterTop = get last line containing \"Finance Charge Calculation\" => top\ndelete text in box @lastfotterTop page.bottom page.left page.right\n\n// Remove unwanted lines\n@bottom = get line starting \"Posting Transaction\" => bottom\n@delete_HeaderAbove = delete text in box on every page page.top @bottom page.left page.right\ndelete all lines starting \"Transaction\"\ndelete all lines starting \"Date Date\"\ndelete all lines starting \"Posting Transaction\"\n\ndelete all lines starting \"Payments and Other Credits\"\ndelete all lines starting \"TOTAL PAYMENTS AND OTHER CREDITS FOR THIS PERIOD\"\ndelete all lines starting \"Finance Charge\"\ndelete all lines starting \"TOTAL FINANCE CHARGE FOR THIS PERIOD\"\ndelete all lines starting \"Purchases and Other Charges\"\ndelete all lines starting \"TOTAL PURCHASES AND OTHER CHARGES FOR THIS PERIOD\"\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"TOTAL INTEREST CHARGED FOR THIS PERIOD\"\ndelete all lines containing \"Finance Charge Calculation\"\n\ndelete all lines starting \"Fees\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"Date Date\"\ndelete all lines starting \"Account Number:\"\ndelete all lines starting \"Posting Transaction\"\ndelete all lines starting \"Payments and Other Credits\"\ndelete all lines starting @accountHolder0\ndelete all lines starting @accountholder1\ndelete all lines starting @accountholder2\nignore header above 703\n\ngo to page 1\n\n// Read the transactions\n$transactions = combine described tables @credits @creditsTable2 @creditsTable3 @creditsTable4 @creditsTable5 @creditsTable6 @debits @debitsTable2 @debitsTable3 @debitsTable4 @debitsTable5 @debitsTable6 @cash @cashTable2 @cashTable3 @cashTable4 @finances @financesTable2 @financesTable3 @financesTable4  @fees @feesTable2 @feesTable3 @feesTable4 @interestCharged @interestChargedTable2 @interestChargedTable3 @interestChargedTable4\n','2025-01-23 08:25:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10077,'Barclays_Card_WithoutSummary','$source = \"Barclays_Card_WithoutSummary\"\n//$features = \"CREDIT_CARD NO_OPENING_BALANCE NO_TRANSACTION_YEAR\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Discard hidden text\ndelete white words\ndelete tiny words\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get account name\n$accountName = get text in box page.top 600 page.left page.middleX => take words 2  => get text\n\n// Get account number\n$accountNumber = get line containing \"Card number:\" => get words after \"Card number:\" => take words 4 => get text\n\n// Get periodto\n//$periodTo =  get line containing \"Statement date:\" => get words after \"Statement date:\" => take words 3 => get date \"d MMMM yyyy\"\n\n\n//delete left part of summary part of all pages\n@summbottom = get line containing \"Monthly spend limit:\" => bottom => get line below => top\ndelete text in box on every page page.top @summbottom 0 260\n\ndelete all lines containing \"Page number:\"\n\ngo to page 1\n@spentLimitTop = get line containing \"Monthly spend limit\" => top\n@spentLimitbottom = get line containing \"Monthly spend limit\" => bottom\ndelete text in box @spentLimitTop @spentLimitbottom  380 600\n\n//below code to fail multi card no statement to force periodTo by taking in incorrect form\ngo to page 1\nget last line containing \"Monthly spend limit\"\n@periodfromTop = get line containing \"Statement date:\" => top\n@periodToBottom = get line containing \"Monthly spend limit:\" => bottom\n$periodTo = get text in box @periodfromTop @periodToBottom 380 600 => get date \"d MMMM yyyy\"\n\n@lastFootertop = get line containing \"Total of spending.\" => top\ndelete text in box @lastFootertop page.bottom page.left page.right\n\n// Get closing balances\n//$closingBalanceText = get line containing \"Total of spending.\" => get words after \"Total of spending.\"  => get text\n//$closingBalance = get line containing \"Total of spending.\" => get words after \"Total of spending.\"  => get decimal\n\n// Get start & end of debits table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n//@transactionsBottom = get last line containing \"Total of spending.\" => if not found then blank => top => get line above\n@LastTransactionPage = get last line starting \"Date Description Amount\"\n//@transactionsBottom = get line above 150\n@transactionsBottom = get line above 70\n\n@LastbalrowTop = bottom @LastTransactionPage\n//@lastFootertop1 = get text in box @LastbalrowTop 150 390 540 => take last words 1 => bottom => subtract 45\n@lastFootertop1 = get text in box @LastbalrowTop 88 390 540 => take last words 1 => bottom => subtract 45\ndelete text in box @lastFootertop1 page.bottom page.left page.right\n\n//we do not have opening and closiing balance previously we taken balance from line - (Total of spending) which is not readable in new statements\n$openingBalance = 0\n$closingBalance = 0\n\n//go to page 1\ndelete text in box on every page page.top 730 page.left page.right\n\n// Get periodFrom\n$periodFrom = take words @transactionsTop 3 => get date \"d MMM yyyy\"\n\n// Discard page header\n//get line below page.top => bottom => ignore header above\nget line below page.top => top => ignore header above\n\n// Discard page footer\ngo to page 1\n@panelBottom = get line containing \"Continued on next page\" => top\ndelete text in box @panelBottom 0 page.left page.right\n\n// Remove unwanted lines\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Total of spending.\"\ndelete all lines starting \"Continued on next page\"\n\ndelete all lines containing \"Barclays Bank PLC. Registered\"\ndelete all lines containing \"Registered Office\"\ndelete all lines starting \"Fax:\"\ndelete all lines starting \"Online:\"\n//ignore footer below 160\nignore footer below 25\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 92 390 540 => describe table false \"Date[d MMM]\" Details *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 88 390 540 => describe table false \"Date[d MMM]\" Details *#Credit','2025-06-25 11:52:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10078,'BarclaysBusinessCurrentAccount','$source = \"BarclaysBusinessCurrentAccount\"\n\n$features = \"NO_TRANSACTION_YEAR FROM_ONLY_DAY\"\n\n// Get account name\n$accountName = get line starting \"Account name\" => get words after \"Account name\" => take words 2 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get period from/to\n@statementPeriod = get line starting \"Account name\" => take last words 6\n$periodFrom = take words @statementPeriod 2 => get date \"d MMM\"\n$periodFromText = get words before @statementPeriod \"-\" => get text\n$periodTo = get words after @statementPeriod \"-\" => take words 3 => get date \"d MMM yyyy\"\n\n// Get opening and closing balances\n$openingBalanceText = get line containing \"Balance brought forward\" => get words after \"Balance brought forward\"\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get last line containing \"Balance carried forward\" => get words after \"Balance carried forward\"\n$closingBalance = get decimal $closingBalanceText\n\n//go to page 1\n@panelBottom = get line starting \"Date Description Payments Receipts Balance\" => top\ndelete text in box on every page page.top @panelBottom page.left page.right\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Payments Receipts Balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Balance carried forward\" => top => get line above\n\n// Discard unwanted lines\ngo to page 1\ndelete all lines starting \"Interim balance carried forward\"\nget line starting \"Continued\" => top => ignore footer below\ndelete all lines starting \"Continued\"\ndelete all lines containing \"Balance brought forward\"\ndelete all lines starting \"Date Description Payments Receipts Balance\"\n\n// Discard page footer\nignore footer below 50\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 92 325 425 500 580 => describe table false \"Date[d MMM]\" Details **#Debit **#Credit **#Balance','2020-09-29 14:22:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10079,'MBNA_CreditCard','$source = \"MBNA_CreditCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Transactions with CR text are negative\r\nset negative marker \"CR\"\r\n\r\n//Get Period To\r\n$periodToText = get text in box 580 550 page.left 200\r\n$PeriodTo = take last words $periodToText 3 => get date \"dd MMMM yyyy\"\r\n\r\ndelete text in box 580 550 page.left 200\r\n\r\n// Get right panel details\r\n@accountDetails = get text in box 730 530 page.middleX page.right\r\n\r\n// Get account number\r\n$accountNumber = get words after @accountDetails \"umber\" => take words 4 => get text\r\n\r\n// Get account name\r\n$accountName = get words after @accountDetails \"Cardholder\" => take words 4 => get text\r\n\r\n// Get opening and closing balances\r\n$openingBalanceText = get words after @accountDetails \"Previous balance\" => get words between \"Previous balance\" \"Payments received\" => get text\r\n$openingBalance = get words after @accountDetails \"Previous balance\" => get words between \"Previous balance\" \"Payments received\" => get decimal\r\n$closingBalanceText = get words after @accountDetails \"Your new balance\" => get words between \"Your new balance\" \"Minimum payment\" => get text\r\n$closingBalance = get words after @accountDetails \"Your new balance\" => get words between \"Your new balance\" \"Minimum payment\" => get decimal\r\n\r\n//Delete AccountDetails box\r\ndelete text in box 730 530 page.middleX page.right\r\ndelete all lines containing \"BALANCE FROM PREVIOUS STATEMENT\"\r\n\r\n// Dynamic Coordinates\r\ngo to page 1\r\n@dateLeft = get line containing \"Date of transaction Date entered\" => get words before \"of\" => take last words 1 => left => subtract 10\r\n@date1Left = get line containing \"Date of transaction Date entered\" => get words after \"of\" => take words 1 => right => add 2\r\n@details1Left = get line containing \"Date of transaction Date entered\" => get words before \"Amount\" => take last words 1 => left => subtract 10\r\n@AmountLeft = get line containing \"Date of transaction Date entered\" => get words after \"Description\" => take words 1 => left => subtract 20\r\n\r\n//Get period from\r\ngo to page 1\r\n@statementDateTop = get line containing \"Date of transaction Date entered Description Amount £\" => bottom\r\n@statementDateBottom = get line containing \"Date of transaction Date entered Description Amount £\" => bottom => get line below => bottom\r\n$periodFrom = get text in box @statementDateTop @statementDateBottom @dateLeft @date1Left => get date \"dd MMMM\"\r\n\r\n// Get start & end of transactions table\r\n@transactionsTop = get line containing \"Date of transaction Date entered Description Amount £\"  => bottom => get line below\r\n@transactionsBottom = get last line containing \"New balance\" => top => get line above\r\n\r\n// Discard page header\r\nget line containing \"Date of transaction Date entered Description Amount £\" => bottom => ignore header above\r\n\r\n// Discard page footer\r\nget line above 0 => top => ignore footer below\r\n\r\n// Remove unwanted lines\r\ndelete all lines containing \"Date of transaction Date entered Description Amount £\"\r\ndelete all lines containing \"New balance\"\r\n\r\n// Read the transactions\r\n$transactions  = get multi page table @transactionsTop @transactionsBottom @dateLeft @date1Left @details1Left @AmountLeft 580 => describe table false \"Date[dd MMMM]\" - Details *#Credit','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10080,'StandardBank_SA_CurrentAccount','$source = \"StandardBank_SA_CurrentAccount\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 45\n\n// Get account number\n$accountNumber = get line starting \"Account\" => get words after \"Account\" => take words 1 => get text\n\n// Get account name\n$accountName = get line starting \"Account\" => skip words 2 => take words 3 => get text\n\n// Get Period from and Period To\n//$periodFrom = get line containing \"Statement For\" => get words after \"Statement For\" => take words 1 => get date \"yyyyMMdd\"\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => skip words 7 => take words 1 => get date \"yyyyMMdd\"\n\n// Get opening balances\n@openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => skip words 8\n$openingBalanceText = get text @openingBalance\n$openingBalance = get decimal @openingBalance\n\n// Get start & end of transactions table\ngo to page 1\n@transactionsTop = get line containing \"Details Service Fee Debit Credit Date Balance\"  => bottom => get line below\n@transactionsBottom = get last line containing \"END OF REPORT\" => top => get line above\n\ngo to page 1\n// Discard page header\n@pageHeader = get line containing \"STATEMENT DETAILS\" => bottom\ndelete text in box on every page page.top @pageHeader page.left page.right\ndelete all lines containing \"Details Service Fee Debit Credit Date Balance\"\ndelete all lines starting \"14.51.01\"\ndelete all lines starting \"DATE\"\n\n\n//Get Closing Balance\ngo to last page\n@pageFooter = get last line containing \"END OF REPORT\" => top => get line above => bottom\n@infoLast = get text in box page.top @pageFooter 410 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n@periodToText = take last words @infoLast 2\n$periodTo = take words @periodToText 1 => get date \"yyyyMMdd\"\n\ndelete all lines containing \"CLOSING BALANCE\"\ndelete all lines containing \"END OF REPORT\"\n\n// Remove unwanted lines\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\nset negative marker \"-\"\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 45 200 245 330 410 450 550 => describe table false Details - *#Debit *#Credit \"Date[yyyyMMdd]\"','2024-10-17 08:41:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10081,'AIB_Current_Account','$source = \"AIB_Current_Account\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n// Get account name and number\n$accountNumber = get line starting \" Account Number:\" => skip words 2 => get text\n$accountName = get line starting \"IBAN:\" => bottom => get line below => get text\n\n//Get Closing Balance\ngo to last page\n@pageFooter = get last line starting \"Page\" => top\n@lastTransaction = get last line starting \"Page\" => top\n@infoLast = get text in box page.top @pageFooter page.middleX page.right\n//$closingBalance = take last words @infoLast 1 => get decimal\n//$periodFrom = take words @lastTransaction 1 => get date \"dd-MMM-yy\"\n$periodFrom = get text in box  page.top @lastTransaction 30 98 => take last words 1 => get date \"dd-MMM-yy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Type Payment Description\" => bottom => get line below\n@transactionsBottom = get last line starting \"Page\" => top => get line above\n\n//Get cordinates of Description left side\ngo to page 1\n\n@description_left = get line containing \"Date Type Payment Description\" => get words after \"Type\" => take words 1 => left\n@description_left = subtract @description_left 3.5\n\n@debit_right = get line containing \"Date Type Payment Description\" => get words after \"Description\" => take words 2 => take last words 1 => right\n@debit_right = add @debit_right 5\n\ngo to page 1\n@DelMainAccountName = get line starting \"Date Type Payment Description\"\n@DelMainAccountNameL1 = top @DelMainAccountName => get line above => take words 4 => get text\n@DelMainAccountNameL2 = top @DelMainAccountName => get line above => top => get line above => take words 3 => get text\n@DelMainAccountNameL3 = top @DelMainAccountName => get line above => top => get line above => top => get line above => take words 3 => get text\n@DelMainAccountNameL4 = top @DelMainAccountName => get line above => top => get line above => top => get line above => top => get line above => take words 3 => get text\n@DelMainAccountNameL5 = top @DelMainAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 3 => get text\n@DelMainAccountNameL6 = top @DelMainAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 3 => get text\n\ndelete all lines starting @DelMainAccountNameL1\ndelete all lines starting @DelMainAccountNameL2\ndelete all lines starting @DelMainAccountNameL3\ndelete all lines starting @DelMainAccountNameL4\ndelete all lines starting @DelMainAccountNameL5\ndelete all lines starting @DelMainAccountNameL6\n\n// Get closingBalance\ngo to page 1\n@pageHeader = get line containing \"Date Type Payment Description\" => bottom\n$infoFirstPage = get text in box @pageHeader page.bottom 480 page.right\n$closingBalance = take words $infoFirstPage 1 => get decimal\n$periodTo = take words @transactionsTop 1 => get date \"dd-MMM-yy\"\n\n// Discard footer\nget line starting \"Page\" => top => ignore footer below\n\ndelete all lines containing \"Account Number:\"\ndelete all lines containing \"IBAN:\"\ndelete all lines containing \"Date:\"\ndelete all lines containing \"Account Number:\"\ndelete all lines containing \"Account details\"\ndelete all lines containing \"Bank Sort Code:\"\n\ndelete all lines starting \"Date Type Payment Description\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Allied Irish Banks\"\ndelete all lines containing \"Interest Rate Lending @\"\n\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 98 140 340 415 480 => describe table false \"*Date[dd-MMM-yy]\" TransactionType Details #Debit #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 98 @description_left 340 @debit_right 480 => describe table false \"*Date[dd-MMM-yy]\" TransactionType Details #Debit #Credit','2024-08-22 05:51:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10082,'ChaseSavingsBank','$source = \"ChaseSavingsBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n//$periodBufferDays = 14\n\ndelete white words\ndelete tiny words\ndelete rotated words\n\ngo to page 1\n$deleteleftpanel = delete text in box on every page page.top page.bottom 0 20 => get text\ndelete all lines starting \"*start*\"\ndelete all lines starting \"*end*\"\n\ngo to page 1\n$dd = delete text in box on every page page.top page.bottom 545 800 => get text\n\ngo to page 1\n// Get account name\n$accountName = get text in box 650 628 page.left 230 => take words 5 => get text\n\n// Get account number\n@accountNumberText = get line containing \"Account Number:\" => get words after \"Account Number:\"\n$accountNumber = take words @accountNumberText 1 => get text\n\n// Opening and Closing Balance\n@OpeningBalanceText = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\"\n$OpeningBalance = take last words @OpeningBalanceText 1 => get decimal\n@ClosingBalanceText = get line containing \"Ending Balance\" => get words after \"Ending Balance\"\n$ClosingBalance = take last words @ClosingBalanceText 1 => get decimal\n\n//PeriodFrom and PeriodTo\n@statementPeriod = get line containing \"Account Number:\" => top => get line above\n$PeriodFrom =  get words before @statementPeriod \"through\" => get date \"MMMM d, yyyy\"\n$PeriodTo =  get words after @statementPeriod \"through\" => get date \"MMMM d, yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"DATE DESCRIPTION AMOUNT BALANCE\" => bottom => get line below\n\n\n// Discard page header\nget last line containing \"DATE DESCRIPTION AMOUNT BALANCE\" => bottom => ignore header above\n\n// Get end of table\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\ngo to page 1\n//get last line containing \"Ending Balance\" => bottom => ignore footer below\n@LastFooter = get last line containing \"Ending Balance\" => bottom\ndelete text in box @LastFooter page.bottom page.left page.right\n//$get = get text in box @LastFooter page.bottom page.left page.right\n\nignore footer below 29\ndelete all lines starting \"DATE DESCRIPTION AMOUNT BALANCE\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"*end*transaction detail\"\n\n\n// Read the transactions\ngo to page 1\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 70 415 480 550 => describe table false \"Date[MM/dd]\" Details *#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 70 410 478 550 => describe table false \"Date[MM/dd]\" Details *#Credit #Balance','2023-08-04 03:33:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10083,'RegionsBankUS','$source = \"RegionsBankUS\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 28\n\n// Get account number\n\n@summaryLine = get line containing \"ACCOUNT #\"\n\n$accountNumber = get words after @summaryLine \"ACCOUNT #\" => get text\n\n\n@statementPeriod = get line starting \"SUMMARY\" => top => get line above\n\n$PeriodFrom =  get words before @statementPeriod \"through\" => get date \"MMMM d, yyyy\"\n\n$PeriodTo =  get words after @statementPeriod \"through\" => get date \"MMMM d, yyyy\"\n\n\n// Get account name\n//$accountName = get line starting \" Regions Bank\" => bottom => get line below => get text\n$accountName = get text in box 675 625 page.left page.middleX => take words 2 => get text\n\ngo to page 1\n\n\n// Get opening and closing balances\n$openingBalanceText = get line starting \"Beginning Balance\" => get words between \"Beginning Balance\" \"Minimum\"\n$openingBalance = get decimal $openingBalanceText\n\n$closingBalanceText = get last line starting \"Ending Balance\" => get words after \"Ending Balance\"\n$closingBalance = get decimal $closingBalanceText\n\n// Get start & end of credits table\n\ngo to page 1\n@creditsTop = get line starting \"DEPOSITS & CREDITS\" => if not found then blank => bottom => get line below\n//@creditsBottom = get line starting \"Total Deposits & Credits\" => if not found then blank => top => get line above\n@creditsBottom = get line starting \"WITHDRAWALS\" => if not found then blank => top => get line above\n\n\n// Get start & end of debits table\n\ngo to page 1\n@debitsTop = get line starting \"WITHDRAWALS\" => if not found then blank => bottom => get line below\n\n//@debitsBottom = get line starting \"Total For This\" => if not found then blank => top => get line above\n@debitsBottom = get line starting \"Total Withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of service fees\n\n//go to page 1\n//@feesTop = get line starting \"FEES\" => if not found then blank => top => get line below\n//@feesBottom = get line starting \"FEES\" => if not found then blank => top => get break below => get line at\n@feesTop = get line starting \"FEES\" => if not found then blank => bottom => get line below\n@feesBottom = get line starting \"FEES\" => if not found then blank => bottom => get break below => get line at\n\ngo to page 1\n// Get start & end of Returned check table\n//@returnedchecksTop = get line starting \"RETURNED CHECKS\" => if not found then blank => top => get line below\n//@returnedchecksBottom = get line starting \"RETURNED CHECKS\" => if not found then blank => top => get break below => get line at\n@returnedchecksTop = get line starting \"RETURNED CHECKS\" => if not found then blank => bottom => get line below\n@returnedchecksBottom = get line starting \"RETURNED CHECKS\" => if not found then blank => bottom => get break below => get line at\n\n\ndelete all lines starting \"Total Fees\"\ndelete all lines starting \"FEES\"\n\n// Get start & end of fees table\n\n@checksmerchanttop = get line starting \"CHECKS CONVERTED BY MERCHANT TO ELECTRONIC WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksmerchantbottom = get line containing \"Checks that are converted by a merchant\" => if not found then blank => top => get line above\n\n// Get start & end of checks tables\n\ngo to page 1\ndelete all lines starting \"CHECKS CONVERTED BY MERCHANT TO ELECTRONIC WITHDRAWALS\"\ndelete all lines starting \"Total Checks\"\ndelete all lines starting \"* Break In Check Number\"\n\n@checksTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below => bottom => get line below\n//@checksBottom = get line starting \"Total Checks\" => if not found then blank => top => get line above\n@checksBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\n\n// Interest Table\n@InterestTop  = get line starting \"INTEREST\" => if not found then blank => bottom => get line below\n@InterestBottom = get line starting \"INTEREST\"  => if not found then blank => bottom => get break below => get line at\n\n\n// Delete headers and footers\ngo to page 1\n@footertop = get line containing \"For all your banking\" => top\n@footerbottom = get line containing \"All loans subject to credit approval.\" => bottom\ndelete text in box @footertop @footerbottom page.left page.right\n\ngo to page 2\n\n@pageHeader = get line starting \"Page\" => top\ndelete text in box on every page page.top @pageHeader page.left page.right\n\n// Remove unwanted lines\n\ndelete all lines starting \"DEPOSITS & CREDITS\"\ndelete all lines starting \"DEPOSITS & CREDITS (CONTINUED)\"\ndelete all lines starting \"Total Deposits & Credits\"\ndelete all lines starting \"WITHDRAWALS\"\n\ndelete all lines starting \"WITHDRAWALS (CONTINUED)\"\ndelete all lines starting \"Total Withdrawals\"\n\ndelete all lines starting \"FEES\"\n\ndelete all lines starting \"FEES (CONTINUED)\"\ndelete all lines starting \"Total Fees\"\n\ndelete all lines starting \"Page\"\n\ndelete all lines starting \"CHECKS\"\n\ndelete all lines starting \"CHECKS (CONTINUED)\"\ndelete all lines starting \"Date Check No. Amount\"\n\ndelete all lines starting \"Total Checks\"\n\ndelete all lines starting \"Enclosures\"\n\ndelete all lines starting \"Date Check No. Description of Check Payment\"\ndelete all lines starting \"Total Interest\"\n\ndelete all lines starting \"Thank You For Banking With Regions!\"\ndelete all lines containing \"Regions Bank Member FDIC\"\ndelete all lines containing \"All loans subject to credit approval\"\n\n// Read the transactions\n\n@credits = get multi page table @creditsTop @creditsBottom 0 90 500 600 => describe table false \"Date[MM/dd]\" Details *#Credit\n\n@debits = get multi page table @debitsTop @debitsBottom 0 90 500 600 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n@fees = get multi page table @feesTop @feesBottom 0 90 500 600 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n@returncheck = get multi page table @returnedchecksTop @returnedchecksBottom 0 90 500 600 => describe table false \"Date[MM/dd]\" Details *#Credit\n\n@checks1 = get multi page table @checksTop @checksBottom 0 90 200 300 => describe table false \"Date[MM/dd]\" ChequeNumber *#Debit\n\n@checks2 = get multi page table @checksTop @checksBottom 300 400 500 600 => describe table false \"Date[MM/dd]\" ChequeNumber *#Debit\n\n@checksmerchant = get multi page table @checksmerchanttop @checksmerchantbottom 0 80 450 600 => describe table false \"*Date[MM/dd]\" Details #Debit\n\n@Interest = get multi page table @InterestTop @InterestBottom 0 90 500 600 => describe table false \"Date[MM/dd]\" Details *#Credit\n\n\n//$transactions = combine described tables @credits @debits @fees @returncheck @checks1 @checks2 @checksmerchant\n$transactions = combine described tables @credits @debits @fees @returncheck @checks1 @checks2 @checksmerchant @Interest','2025-10-29 06:17:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10084,'TescoCreditCard','$source = \"TescoCreditCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n// Get right panel details\n@pageHeader = get line starting \"Trans Post Description Amount\" => top\n@accountDetails = get text in box page.top @pageHeader page.middleX page.right\n\n// Get account number\n$accountNumber = get words after @accountDetails \"MasterCard number\" => take words 4 => get text\n\n// Get account name\n$accountName = get words after @accountDetails \"Cardholder\" => take words 4 => get text\n\n@statementPeriod = get line starting \"Trans Post Description Amount\" => top => get line above\n$PeriodFrom =  take words @statementPeriod 2 => get date \"d MMMM\"\n$PeriodTo =  get words after @statementPeriod \"-\" => get date \"d MMMM yyyy\"\n\n// Get opening and closing balances\n$openingBalanceText = get line starting \"BALANCE FROM PREVIOUS STATEMENT\" => get words after \"BALANCE FROM PREVIOUS STATEMENT\"\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get last line starting \"NEW BALANCE\" => get words after \"NEW BALANCE\"\n$closingBalance = get decimal $closingBalanceText\n\n//Delete AccountDetails box\ndelete text in box on every page page.top @pageHeader page.left page.right\n\n// Get start & end of transactions table\ngo to page 1\n@transactionsTop = get line containing \"Trans Post Description Amount\"  => bottom => get line below\n@transactionsBottom = get last line containing \"NEW BALANCE\" => top => get line above\n\n// Discard page footer\nget line above 0 => top => ignore footer below\n\n// Remove unwanted lines\ndelete all lines containing \"BALANCE FROM PREVIOUS STATEMENT\"\ndelete all lines containing \"Trans Post Description Amount\"\ndelete all lines containing \"NEW BALANCE\"\ndelete all lines containing \"Date Date\"\ndelete all lines containing \"Balance brought forward\"\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 110 150 210 460 580 => describe table false \"Date[dd MMM]\" - TransactionType Details *#Credit','2021-01-04 09:38:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10085,'TideBank','$source = \"TideBank\"\n$features = \"REVERSE_ORDER\"\n\n$periodBufferDays = 10\n\n//set negative marker \"-\"\n\n// Get account number\n$accountnumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n\n// Get account name\n@accountbottom = get line containing \"Page\" => top\n$accountname = get text in box page.top @accountbottom page.middleX page.right => take words 2 => get text\n\n// Get Period\n@periodtotext = get line containing \"Total paid out\" => bottom => get line below\n$periodto = get words after @periodtotext \"on\" => take words 3 => get date \"d MMMM yyyy\"\n//$periodto = get words after @periodtotext \"Balance on\" => take words 3 => get date \"d MMMM yyyy\"\n\n@periodfromtext = get last line containing \"Total paid in\" => top => get line above\n$periodfrom = get  words after @periodfromtext \"on\" => take words 3 => get date \"d MMMM yyyy\"\n//$periodfrom = get words after @periodfromtext \"Balance on\" => take words 3 => get date \"d MMMM yyyy\"\n//@periodtotext = get line containing \"Total paid out\" => bottom => get line below\n\n//Get opening and closing balance\n//@closingbalancetext = get words after @periodfromtext \"Balance on\" => take words 3 => get text\n@closingbalancetext = get words after @periodfromtext \"on\" => take words 3 => get text\n$closingbalance = get words after @periodfromtext @closingbalancetext => take words 1 => get decimal\n\ngo to page 1\n//@openingbalancetext = get words after @periodtotext \"Balance on\" => take words 3 => get text\n@openingbalancetext = get words after @periodtotext \"on\" => take words 3 => get text\n$openingbalance = get words after @periodtotext @openingbalancetext => take words 1 => get decimal\n\nset negative marker \"-\"\n\n// Get start and end of table\n@transactionstop = get line containing \"Total paid out\" => bottom => get line below\n\n//@lastTranpage = get last line starting \"Page\"\n@lastTranpage = get last line containing \"Details Paid\"\n@transactionsbottom = get line above 0\n\n//@transactionstop = get line starting \"Transactions\" => if not found then blank => bottom => get line below => bottom => get line below\n//@transactionsbottom = get last line starting \"Your Tide account\" => if not found then blank => top => get line above\n\ngo to page 1\n// Delete headers and footer\nget line starting \"Your Tide account\" => top => ignore footer below\nget line containing \"Page\" => bottom => ignore header above\ndelete all lines starting \"Date Transaction type Details\"\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"To be billed on\"\ndelete all lines starting \"Transaction fees for this period\"\ndelete all lines starting \"Bank Account Legal\"\ndelete all lines starting \"No transaction fees\"\ndelete all lines starting \"Date Transaction Type Details\"\ndelete all lines containing \"Balance on\"\ndelete all lines containing \"Available on\"\ndelete all lines starting \"Credit line:\"\n\n\ndelete all lines starting \"Card payments\"\ndelete all lines starting \"Cash withdrawals\"\ndelete all lines starting \"Cash deposits\"\ndelete all lines starting \"Transfers in\"\ndelete all lines starting \"No transactions\"\ndelete all lines starting \"Transfers out\"\ndelete all lines starting \"Date Transac\"\ndelete all lines containing \"Transac*ons\"\ndelete all lines containing \"To be billed on\"\ndelete all lines containing \"fees for this period\"\n\ndelete all lines starting \"Account number:\"\ndelete all lines starting \"Sort code:\"\ndelete all lines starting \"Statement for:\"\ndelete all lines starting \"No transaction fees for this period\"\ndelete all lines starting \"No transactions in the period\"\ndelete all lines starting \"Bank statement\"\ndelete all lines starting \"Bank account legal\"\ndelete all lines starting \"Page\"\n\n\n//Read the transactions\n//$transactions = get multi page table @transactionstop @transactionsbottom 20 110 180 360 420 500 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Debit *#Credit\n\n//$transactions = get multi page table @transactionstop @transactionsbottom 20 110 188 362 420 500 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Debit *#Credit\n\n//$transactions = get multi page table @transactionstop @transactionsbottom 20 100 183 357 420 500 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Debit *#Credit -\n//$transactions = get multi page table @transactionstop @transactionsbottom 20 107 95 183 357 420 500 600 => describe table false \"Date[d MMM yyyy]\" - TransactionType Details *#Debit *#Credit -\n$transactions = get multi page table @transactionstop @transactionsbottom 20 107 95 191 390 370 431 500 600 => describe table false \"Date[d MMM yyyy]\" - TransactionType Details - *#Debit *#Credit -','2023-03-30 08:08:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10086,'StGeorgeBank','$source = \"StGeorgeBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodto = get line starting \"Statement Period\" => take last words 1 => get date \"dd/MM/yyyy\"\n\n$accountnumber = get line starting \"Account Number\" => skip words 2 => get text\n\n$periodfrom = get line starting \"Statement Period\" => skip words 2 => take words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n//@accountNameTop = get line starting \"Statement No\" => bottom\n//@accountNameBottom = get line starting \"Account Summary\" => top\n//$accountname = get text in box @accountNameTop @accountNameBottom page.left 250 => get text\n$accountname = get line starting \"Account Summary\" => top => get line above => take words 4 => get text\n\n//$openingbalance = get line starting \"Opening Balance\" => bottom => get line below => take words 1 => get decimal\n$openingbalance = get line starting \"Opening Balance\" => bottom => get line below => take words 2 => get decimal\n\n//$closingbalance = get line starting \"Opening Balance\" => bottom => get line below => take last words 1 => get decimal\n$closingbalance = get line starting \"Opening Balance\" => bottom => get line below => take last words 2 => get decimal\n\n@transactionsTop = get line starting \"Date Transaction Description\" => top => get line above\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\n@accountDetailsBottom = get line starting \"Statement No.\" => bottom\ndelete text in box on every page page.top @accountDetailsBottom page.left page.right\n\ngo to page 1\ndelete all lines starting \"Transaction Details\"\ndelete all lines starting \"Date Transaction Description\"\ndelete all lines starting \"SUB TOTAL CARRIED\"\ndelete all lines starting \"Statement No.\"\ndelete all lines starting \"St.George Bank - A Division of Westpac Banking\"\ndelete all lines containing \"OPENING BALANCE\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 73 330 400 470 560 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit #Balance','2025-05-22 07:20:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10087,'ABSABank','$source = \"ABSABank\"\n\n$periodto = get line starting \"Statement for Period\" => take last words 1 => get date \"yyyy-MM-dd\"\n\n$periodfrom = get line starting \"Statement for Period\" => skip words 3 => take words 1 => get date \"yyyy-MM-dd\"\n\n\n$accountnumber = get line ending \"ABSA\" => bottom => get line below => take last words 1 => get text\n\n$accountname = get line ending \"ABSA\" => get words before \"ABSA\" => get text\n\n$openingbalance = get line starting \"Balance Brought Forward\" => take last words 1 => get decimal\n$closingbalance = get line starting \"Balance Carried Forward\" => take last words 1 => get decimal\n\ngo to page 1\n$DescLeft = get line containing \"Transaction Description\" => take words 2 => take last words 1 => left\n$DescLeft = subtract $DescLeft 5\n$AmontLeft = get line containing \"Transaction Description\" => get words after \"Description\" => take words 1 => left\n$AmontLeft = subtract $AmontLeft 25\n$BalanceLeft = get line containing \"Transaction Description\" => get words after \"Description\" => take words 1 => right\n$BalanceLeft = add $BalanceLeft 10\n\ndelete all lines containing \"Page \"\ndelete all lines starting \"Date: Transaction Description\"\n\ngo to page 1\n@transactionsTop = get line starting \"Balance Brought Forward\" => bottom => get line below\n@transactionsBottom = get line starting \"Balance Carried Forward\" => top => get line above\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 340 470 600 => describe table false \"Date[yyyy-MM-dd]\" Details #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 $DescLeft $AmontLeft $BalanceLeft 650 => describe table false \"Date[yyyy-MM-dd]\" Details #Credit *#Balance','2023-05-19 11:18:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10088,'CynergyBank','$source = \"CynergyBank\"\n$periodBufferDays = 14\n\n//$periodto = get line ending \"Statement date\" => bottom => get line below => take last words 3 => get date \"dd MMM yyyy\"\n\n// Get Account Number\n@acctext = get line starting \"Name of account\" => top => get line above\n$accountnumber = get words between @acctext \"Account number\" \"Statement date\" => take last words 1 => get text\n//$accountnumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n//$accountnumber = get line starting \"Account number\" => skip words 2 => get words before \"Paid\" => get text\n\ngo to page 1\n$periodto = get line starting \"Previous statement date\" => top => get line above => take last words 3 => get date \"dd MMM yyyy\"\n$periodfrom = get line starting \"Previous statement date\" => bottom => get line below => get date \"dd MMM yyyy\"\n$accountname = get line starting \"Name of account\" => skip words 3 => get text\n\ngo to page 1\n$openingbalance = get line containing \"Opening balance\" => take last words 1 => get decimal\n//$closingbalance = get line containing \"Closing balance\" => take last words 1 => get decimal\n$closingbalance = get last line starting \"CLOSING BALANCE\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Posting date Value date\"\n@transactionsBottom = get line starting \"CLOSING BALANCE\"\n\ndelete all lines starting \"Page\"\ndelete all lines starting \"Sort code\"\ndelete all lines starting \"Account number\"\ndelete all lines starting \"Name of account\"\ndelete all lines containing \"Posting date Value date\"\ndelete all lines starting \"CLOSING BALANCE\"\ndelete all lines containing \"BROUGHT FORWARD\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 70 145 200 320 420 49