INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10089,'CapitalOnTap','$source = \"CapitalOnTap\"\n\n$periodto = get line starting \"Statement Summary\" => bottom => get line below => take last words 1 => get date \"dd/MM/yyyy\"\n$periodfrom = get line starting \"Statement Summary\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n$accountnumber = get line containing \"Customer Reference\" => take last words 1 => get text\n$accountname = get line containing \"Customer Reference\" => get words before \"Customer Reference\" => get text\n$openingbalance = get line starting \"Opening Balance\" => bottom => get line below => take words 1 => get decimal\n$closingbalance = get line starting \"Opening Balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n@footerTop = get line starting \"©NewWaveCapital\" => top\ndelete text in box on every page @accountDetailsBottom page.bottom page.left page.right\n\ngo to page 1\n@transactionsTop = get line starting \"Date Type Card\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 160 210 430 510 580 => describe table false \"Date[dd/MM/yyyy]\" - - Details #Credit *#Balance\n','2022-03-25 16:31:08',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10090,'VirginMoney','$source = \"VirginMoney\"\n\n$periodBufferDays = 10\n// Get account name and number\n@accountDetails = get line starting \"Date Description\" => top => get line above\n$accountNumber = take words @accountDetails 1 => get text\n$accountName = get line starting \"Account number\" => top => get line above => get text\n\n\n// Get period from/to\n@period = take last words @accountDetails 7\n$periodFrom = take words @period 3 => get date \"dd MMM yy\"\n$periodTo = take last words @period 3 => get date \"dd MMM yy\"\n\n// Discard addresses as they get in the way of the balances\n@dropTop = get line starting \"Branch Details\" => bottom\n@dropBottom = get line containing \"New Balance\" => bottom\n$get_text = delete text in box @dropTop @dropBottom page.left page.middleX => get text\n\n\n// Get opening and closing balances\n$openingBalanceText = get line containing \"Opening Balance\" => get words after \"Opening Balance\"\n$openingBalance = get decimal $openingBalanceText\n//$closingBalanceText = get last line containing \"Closing balance\" => get words after \"Closing balance\"\n$closingBalanceText = get last line starting \"Closing\" => get words after \"Closing\" => take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type Debits Credits Balance\" => bottom => get line below\n\n//ignore footer below 9\n// Get end of table\n//go to last page\n\n//navigate to last closing balance page\nget last line starting \"Closing\"\n//@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n@transactionsBottom = get last line starting \"Closing\" => top => get line above\n\ngo to page 1\n$Date_left = get line containing \"Date Description Type Debits\" => get words before \"Description\" => take words 1 => left => subtra