ending \"7 Statement\"\ndelete all lines ending \"8 Statement\"\ndelete all lines ending \"9 Statement\"\n\ngo to page 1\n@top = get last line starting \"Closing\" => top\n$extraText_delete = delete text in box @top 0 page.left page.right => get text\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 265 350 430 497 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 263 350 430 497 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 263 350 430 500 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 263 350 $Debits_rght $Credits_rght 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 $Date_rght $Description_rght $Type_rght $Debits_rght $Credits_rght $Balance_rght => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 4.5 0 $Date_rght $Description_rght $Type_rght $Debits_rght $Credits_rght $Balance_rght => describe table false \"Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 4.8 0 $Date_rght $Description_rght $Type_rght $Debits_rght $Credits_rght $Balance_rght => describe table false \"Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 4.52 0 $Date_rght $Description_rght $Type_rght $Debits_rght $Credits_rght $Balance_rght => describe table false \"Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance','2025-05-06 06:26:44',0);
