INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10092,'AIB_VisaCard','$source = \"AIB_VisaCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 30\r\nset negative marker \"CR\"\r\n\r\n// Get Account Details\r\n@accountNoLinebottom = get line containing \"Credit Limit:\" => top\r\n@accountNoLinetop = add @accountNoLinebottom 34\r\n//$accountNumber = get text in box @accountNoLinetop @accountNoLinebottom 436 540 => take last words 4 => get decimal\r\n$accountNumber = get text in box @accountNoLinetop @accountNoLinebottom 417 540 => get text\r\n\r\n@accountNameDetails = get line containing \"Card Number\" => top => get line above => top => get line above\r\n$accountName = take words @accountNameDetails 3 => get text\r\n\r\n// Get opening and closing balances\r\n$openingBalanceText = get line containing \"Previous Balance\" => get words after \"Previous Balance\"\r\n$openingBalance = get decimal $openingBalanceText\r\n$closingBalanceText = get last line containing \"New Balance\" => get words after \"New Balance\"\r\n$closingBalance = get decimal $closingBalanceText\r\n\r\n// Get period to\r\ngo to page 1\r\n@periodTo = get last line containing \"Account Statement -\" => get words after \"Account Statement -\"\r\n$periodToText = take words @periodTo 3 => get text\r\n$periodTo = take words @periodTo 3 => get date \"d MMMM, yyyy\"\r\n\r\n// Get start of table\r\ngo to page 1\r\n@header = get line containing \"Transaction Posting\"\r\n@dateleft = get words before @header \"Details and Amount\" => take last words 1 => left => subtract 1\r\n@dateright = get words before @header \"Details and Amount\" => take last words 1 => right => add 3\r\n@amountleft = get words after @header \"Details and\" => take words 1 => left => subtract 20\r\n@amountright = get words after @header \"Details and\" => take words 1 => right => add 5\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Date Reference Number €\" => bottom => get line below\r\n$periodFrom = take words @transactionsTop 2 => get date \"d MMM\"\r\n\r\ngo to page 1\r\ndelete text in box on every page page.top page.bottom @amountright page.right\r\n\r\n// Deleting the top panel from all the pages to avoid unnecessary data\r\ngo to page 1\r\n@tableHeader = get line containing \"Payment Due Date\" => top\r\ndelete text in box on every page page.top @tableHeader page.left page.right\r\n\r\n// Delete extra lines\r\ngo to page 1\r\n//get line containing \"Purchases on your\" => top => ignore footer below\r\n//get line starting \"Continued on next page\" => top => ignore footer below\r\nget line starting \"Continued on next page\" => bottom => ignore footer below\r\ndelete all lines containing \"Purchases on your\"\r\ndelete all lines containing \"Continued on next page\"\r\ndelete all lines containing \"Date Date Reference Number €\"\r\ndelete all lines containing \"Transaction Posting Details and\"\r\ndelete all lines containing \"page\"\r\n\r\ndelete all lines starting \"Purchases\"\r\ndelete all lines starting \"Start Date\"\r\ndelete all lines starting \"End Date\"\r\ndelete all lines starting \"Unpaid Fee\"\r\ndelete all lines starting \"Continued\"\r\ndelete all lines containing \"TO ALLOW\"\r\ndelete all lines starting \"Continued\"\r\n\r\n//delete all pages containing \"Summary Box\"\r\n\r\n// Get end of table\r\ngo to last page\r\n@transactionsBottom = get line above 0\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateleft @dateright @amountleft @amountright => describe table false \"*Date[d MMM]\" Details #Credit','2026-09-08 10:16:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10093,'AIB_BusinessCard','$source = \"AIB_BusinessCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\nset negative marker \"CR\"\n\n// Get Account Details\n@accountNoDetails = get line containing \"Payment Due Date\" => get words after \"Payment Due Date\"\n$accountNumber = take words @accountNoDetails 4 => get text\n@accountNameDetails = get line containing \"Account Name\" => bottom => get line below\n$accountName = take last words @accountNameDetails 3 => get text\n\n// Get opening and closing balances\n$openingBalanceText = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\"\n$openingBalance = get decimal $openingBalanceText\n@closingBalanceText = get last line containing \"THE BALANCE WILL BE DEDUCTED FROM YOUR ACCOUNT\" => top => get line above\n$closingBalanceText = take last words @closingBalanceText 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get period to\ngo to page 1\n@periodTo = get line containing \"Account Number\" => get words before \"Account Number\"\n$periodToText = take words @periodTo 3 => get text\n$periodTo = take words @periodTo 3 => get date \"d MMMM, yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"PREVIOUS BALANCE\" => bottom => get line below\n$periodFrom = take words @transactionsTop 1 => get date \"d MMM\"\n\n// Deleting the top panel from all the pages to avoid unnessary data\ngo to page 1\n//@tableHeader = get line containing \"Page Number\" => bottom\n@tableHeader = get line containing \"Page Number\" => bottom => get line below => bottom\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n// Get end of table\n@transactionsBottom = get last line starting \"THE BALANCE WILL BE DEDUCTED FROM YOUR ACCOUNT BY DIRECT DEBIT\" => top => get line above => top => get line above\n\n// Delete extra lines\ngo to page 1\ndelete all lines containing \"PREVIOUS BALANCE\"\ndelete all lines containing \"THE BALANCE WILL BE DEDUCTED FROM YOUR ACCOUNT BY DIRECT DEBIT\"\ndelete all lines containing \"Continued overleaf\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 51 85 500 600 => describe table false \"*Date[d MMM]\" - Details #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 51 85 500 600 => describe table false - \"*Date[d MMM]\" Details #Credit','2025-05-06 06:26:57',0);
