p => get line above => top => get line above => top => get line above => top => get line above => bottom\n//$closingBalance = get text in box page.top @clossingbottom 470 600 => take last words 1 => get decimal\n\n@clossingbottom = get last line containing \"Page\" => top => get line above => top => get line above => top => get line above => bottom\n$closingBalance = get text in box page.top 0 470 600 => take last words 1 => get decimal\n\n// Discard header and footer\nignore header above 695\nget line containing \"Page\" => top => ignore footer below\ndelete all lines containing \"Balance at Period Start\"\n\n\ngo to page 3\n@get_top = get line containing \"Account Summary\" => top\n@get_bottom = get line containing \"Currency :\" => bottom\n$del_multi_header = delete text in box @get_top @get_bottom page.left page.right\ndelete all lines starting \"Unpaid Direct Debit 0.00\"\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 125 335 470 600 => describe table false \"Date[dd MMM yy]\" Details #Credit *#Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 125 347 340.79 470 600 => describe table false \"Date[dd MMM yy]\" Details - #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 125 347 325 470 600 => describe table false \"Date[dd MMM yy]\" Details - #Credit[0,000.00] *#Balance','2025-05-29 06:49:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10095,'TD_Bank_US','$source = \"TD_Bank_US\"\n$features = \"NO_TRANSACTION_YEAR NO_OPENING_BALANCE\"\n$periodToRegex = \".*-(.*)\"\n$inputDateFormat = \"dd/MMMM/YY\"\n\ngo to page 1\n@dropTop = get line containing \"How to Balance your Account\" => top\n@dropBottom = get line containing \"total finance charge\" => bottom\ndelete text in box @dropTop 30 page.left page.right\n\ngo to page 1\n// Get Account Number and Account Name\n@accountNumberText = get line containing \"Account #\" => get words after \"Account #\"\n$accountNumber = take words @accountNumberText 1 => get text\n@accountNameText = get line containing \"Statement Period:\" => get words before \"Statement Period:\"\n$accountName = take words @accountNameText 2 => get text\n\n// Get statementPeriod\n@statementPeriodText = get line containing \"Statement Period:\" => get words after \"Statement Period:\"\n$statementPeriodText = take words @statementPeriodText 5\n$statementPeriodText1 = get text @statementPeriodText\n$PeriodFrom =  take words @statementPeriodText 2 => get date \"MMM d\"\n$PeriodToText =  take last words @statementPeriodText 3 => get text\n$PeriodTo =  take last words @statementPeriodText 3 => get date \"MMM d YYYY\"\n\n// Get opening and closing balances\ngo to page 1\n$openingBalanceText = get line starting \"Statement Balance as of\" => skip words 5\n//$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get last line starting \"Statement Balance as of\" => take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\nGo to page 1\n@transactionsTop = get line containing \"DATE DESCRIPTION DEBIT CREDIT BALANCE\" => bottom => get line below\n\n// Discard page header\nget last line containing \"DATE DESCRIPTION DEBIT CREDIT BALANCE\" => bottom => ignore header above\n\n//go to page 1\n// Get end of table\n@transactionsBottom = get last line containing \"Indicates break in serial sequence\" => top => get line above\n\ngo to page 1\ndelete all lines starting \" DATE DESCRIPTION DEBIT CREDIT BALANCE\"\ndelete all lines containing \"Bank-by-Phone services\"\ndelete all lines containing \"Bank Deposits FDIC Insured\"\n//get last line containing \"INTEREST SUMMARY\" => bottom => ignore footer below\n//delete all lines containing \"INTEREST SUMMARY\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 90 385 460 520 600 => describe table false \"*Date[MM/dd]\" Details #Debit #Credit #Balance','2021-02-19 14:05:42',0);
