INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10099,'SantanderCurrentAccount','$source = \"SantanderCurrentAccount\"\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n$accountname = \"Anonymous\"\n\n$accountnumber = get line containing \"Account number:\" => get words after \"Account number:\" => get text\n\n@daterange = get line containing \"Date Range:\" => get words after \"Date Range:\"\n\n//$periodfrom = take words @daterange 1 => get date \"ddMMyyyy\"\n\n//$periodto = take last words @daterange 1 => get date \"ddMMyyyy\"\n\n// Get period from and period to\ngo to page 1\n$periodToTexttop = get line containing \"Date Narrative\" => bottom\n$periodToTextBottom = get line containing \"Date and time of generation\" => top\n$periodTo = get text in box $periodToTexttop $periodToTextBottom 50 138 => take words 1 => get date \"dd/MM/yyyy\"\n\n$periodFromTexttop = get last line containing \"Date Narrative\" => bottom\n$periodFromTextBottom = get last line containing \"Date and time of generation\" => top\n$periodFrom = get text in box $periodFromTexttop $periodFromTextBottom 50 138 => take last words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n//first page header delete\n//@firstHeaderbottom = get line starting \"Date Narrative\" => top\n//delete text in box page.top @firstHeaderbottom page.left page.right\n\n@transactionstop = get line starting \"Date Narrative\" => bottom => get line below\n@transactionsbottom = get last line containing \"Date and time of generation of the document\" => top => get line above\n\n$openingbalance = take last words @transactionstop 1 => get decimal\n\n//@lineabovebottom = top @transactionsbottom => get line above\n//$closingbalance = take last words @lineabovebottom 1 => get decimal\n\n@lasttransactionTop = get last line starting \"Date Narrative\" => bottom\n@lasttransactionbottom = get last line containing \"Date and time of generation of the document\" => top => get line above => bottom\n$closingbalance = get text in box @lasttransactionTop @lasttransactionbottom 650 755 => take last words 1 => get decimal\n\ndelete all lines starting \"Date Narrative\"\ndelete all lines starting \"Transaction Details\"\ndelete all lines starting \"Last statement date:\"\ndelete all lines starting \"Currency:\"\ndelete all lines starting \"Account type:\"\ndelete all lines starting \"Sort code:\"\ndelete all lines starting \"Account Details\"\ndelete all lines starting \"Account Activity\"\n\nignore header above 435\nignore footer below 60\n\n//$transactions = get multi page table @transactionstop @transactionsbottom page.left 135 345 440 550 650 page.right => describe table false \"Date[dd/MM/yyyy]\" Details TransactionType #Debit #Credit *#Balance\n$transactions = get multi page table @transactionstop @transactionsbottom 50 120 345 455 550 650 755 => describe table false \"Date[dd/MM/yyyy]\" Details TransactionType #Debit #Credit *#Balance','2025-04-15 05:12:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10100,'MetrobankPersonalCurrentAccount','$source = \"MetrobankPersonalCurrentAccount\"\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n$accountname = get line starting \"ACCOUNT NAME:\" => get words after \":\" => get text\n\n$accountnumber = get line containing \"Account No:\" => get words after \"Account No:\" => get text\n\n@period = get line starting \"Current Statement Period:\" => get words after \"Current Statement Period:\"\n$periodfrom =  take words @period 3 => get date \"dd MMM yyyy\"\n//$periodto =  take last words @period 3 => get date \"dd MMM yyyy\"\n\n@periodLst = get last line starting \"Current Statement Period:\" => get words after \"Current Statement Period:\"\n$periodto =  take last words @periodLst 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n$openingbalance = get line starting \"Opening Balance:\" => get words after \"Opening Balance:\" => get decimal\n\n//$closingbalance = get line starting \"Closing Balance:\" => get words after \"Closing Balance:\" => get decimal\n$closingbalance = get last line starting \"Closing Balance:\" => get words after \"Closing Balance:\" => get decimal\n\n//delete extra pages for clear transactions\ndelete all pages containing \"If your details have changed or your card is lost or stolen\"\n\n\ngo to page 1\n@topSumm = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm @bottomSumm page.left page.right\n\n@topSumm2 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm2 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm2 @bottomSumm2 page.left page.right\n\n@topSumm3 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm3 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm3 @bottomSumm3 page.left page.right\n\n@topSumm4 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm4 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm4 @bottomSumm4 page.left page.right\n\n@topSumm5 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm5 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm5 @bottomSumm5 page.left page.right\n\n@topSumm6 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm6 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm6 @bottomSumm6 page.left page.right\n\n@topSumm7 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm7 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm7 @bottomSumm7 page.left page.right\n\n@topSumm8 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm8 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm8 @bottomSumm8 page.left page.right\n\n@topSumm9 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm9 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm9 @bottomSumm9 page.left page.right\n\n@topSumm10 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm10 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm10 @bottomSumm10 page.left page.right\n\n@topSumm11 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm11 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm11 @bottomSumm11 page.left page.right\n\n@topSumm12 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm12 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm12 @bottomSumm12 page.left page.right\n\n@topSumm13 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm13 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm13 @bottomSumm13 page.left page.right\n\n@topSumm14 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm14 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm14 @bottomSumm14 page.left page.right\n\n@topSumm15 = get line containing \"ACCOUNT SUMMARY\" => top\n@bottomSumm15 = get line starting \"ACCOUNT NAME:\" => bottom\ndelete text in box @topSumm15 @bottomSumm15 page.left page.right\n\ngo to page 1\n@topfoot1 = get line containing \"Important Information about compensation\" => top\ndelete text in box @topfoot1 page.bottom page.left page.right\n\n@topfoot2 = get line containing \"Important Information about compensation\" => top\ndelete text in box @topfoot2 page.bottom page.left page.right\n\n@topfoot3 = get line containing \"Important Information about compensation\" => top\ndelete text in box @topfoot3 page.bottom page.left page.right\n\n@topfoot4 = get line containing \"Important Information about compensation\" => top\ndelete text in box @topfoot4 page.bottom page.left page.right\n\ngo to page 1\n@transactionsTop = get line starting \"Balance brought forward\" => bottom => get line below\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\n\ndelete all lines containing \"Your deposit is classed as an eligible deposit\"\ndelete all lines starting \"Your transactions\"\ndelete all lines starting \"DATE TRANSACTION\"\ndelete all lines starting \"Balance brought forward\"\ndelete all lines starting \"Closing Balance\"\ndelete all lines starting \"*Does\"\ndelete all lines starting \"**The rate\"\ndelete all lines starting \"you not less\"\ndelete all lines starting \"***Interest\"\nignore header above 730\nignore footer below 86\n//ignore header above 90\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 120 330 410 500 570 => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance','2025-05-06 06:26:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10101,'TSBCreditCard_AccountNumber','$source = \"TSBCreditCard_AccountNumber\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n$periodbufferdays = 28\n\nset negative marker \"CR\"\n\n// Period to\ngo to page 1\n@periodtotop = get line containing \"Your credit card statement\" => top => subtract 10\n@periodbottom = get line containing \"Your credit card statement\" => bottom => add 3\n\n$periodto = get text in box @periodtotop @periodbottom page.left 315 => take words 3 => get date \"dd MMMM yyyy\"\n\ngo to page 1\ndelete text in box page.top 0 0 315\n\n// Account name\n$accountname = get line containing \"Cardholder\" => get words after \"Cardholder\" => get text\n\n// Account number\n$accountnumber = get line containing \"Account number\" => get words after \"Account number\" => get text\n\n// Opening balance\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => get decimal\n\n// Closing balance\n$closingbalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => get decimal\n\n// Period from\n$periodfrom = get line containing \"BALANCE FROM PREVIOUS STATEMENT\" => bottom => get line below => take words 2 => get date \"dd MMMM\"\n\n// Transactions\n@transactionstop = get line containing \"BALANCE FROM PREVIOUS STATEMENT\" => bottom => get line below => top\n\n@transactionsbottom = get last line containing \"New balance\" => top => get line above => bottom\n\n$transactions = get table @transactionstop @transactionsbottom 0 140 230 500 page.right => describe table false \"*Date[dd MMMM]\" - Details #Credit','2024-11-21 07:14:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10102,'TSBCreditCard_CardNumber','$source = \"TSBCreditCard_AccountNumber\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n$periodbufferdays = 28\n\nset negative marker \"CR\"\n\n// Account name\n$accountname = get line containing \"Cardholder\" => get words after \"Cardholder\" => get text\n\n// Account number\n$accountnumber = get line containing \"Mastercard [M] Card Number\" => get words after \"Mastercard [M] Card Number\" => get text\n\n// Opening balance\n$openingbalance = get line containing \"Previous balance\" => skip words 2 => take words 1 => get decimal\n\n// Closing balance\n$closingbalance = get line containing \"Your new balance\" => skip words 3 => take words 1 => get decimal\n\n// Period from\n$periodfrom = get line containing \"BALANCE FROM PREVIOUS STATEMENT\" => bottom => get line below => skip words 11 => take words 2 => get date \"dd MMMM\"\n\n// Period to\ngo to page 1\n@periodtotop = get line containing \"Your credit card statement\" => top => subtract 10\n@periodbottom = get line containing \"Your credit card statement\" => bottom => add 3\n\n$periodto = get text in box @periodtotop @periodbottom page.left 315 => take words 3 => get date \"dd MMMM yyyy\"\n\n// Transactions\n@transactionstop = get line containing \"BALANCE FROM PREVIOUS STATEMENT\" => bottom => get line below => top\n\n@transactionsbottom = get last line containing \"New balance\" => top => get line above => bottom\n\n$transactions = get table @transactionstop @transactionsbottom page.left 140 230 500 page.right => describe table false - \"Date[dd MMMM]\" Details #Credit','2021-03-10 15:21:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10104,'NationwideCreditCard','$source = \"NationwideCreditCard\"\n$features = \"CREDIT_CARD\"\n\nset negative marker \"CR\"\n\n// Get Account Details\n@accountDetailstop = get line containing \"Nationwide Credit Card Services\" => top\n@accountDetailsbottom = get line containing \"Summary as at\" => top\n@accountDetails = get text in box @accountDetailstop @accountDetailsbottom page.left 380\n$accountNumber = get words after @accountDetails \"Credit Card\" => get words between \"Credit Card\" \"Name\" => get text\n$accountName = get words after @accountDetails \"Name\" => take words 2 => get text\n\n// Get opening and closing balances\n//@openingBalanceText = get line containing \"Balance from previous statement\" => take last words 1\n\n@openingBalanceText = get line containing \"Balance from previous statement\" => get words after \"Balance from previous statement\" => take words 1\n$openingBalance = get decimal @openingBalanceText\n@closingBalanceText = get line containing \"Closing Balance\" => take last words 1\n$closingBalance = get decimal @closingBalanceText\n\n// Get period to\ngo to page 1\n@periodTo = get line containing \"Summary as at\" => get words after \"Summary as at\"\n$periodTo = take words @periodTo 3 => get date \"dd MMMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line containing \"Date Ref no. Description\" => bottom => get line below\n\n// Get Period from\n$periodFrom = bottom @transactionsTop => get line below => take words 1 => get date \"dd/MM/yy\"\n\n@DateLeft = get line containing \"Date Ref no. Description\" => get words before \"Ref\" => left => subtract 7\n@RefLeft = get line containing \"Date Ref no. Description\" => get words after \"Date\" => left => subtract 9\n@AmountLeft = get line containing \"Date Ref no. Description\" => get words after \"Description\" => left => subtract 15\n\n// Get end of table\n@transactionsBottom = get line containing \"TOTAL BALANCE\" => top => get line above\n\ngo to page 1\nget line starting \"Date Ref no. Description\" => bottom => ignore header above\n\n//go to page 1\n//@tableFooter = get line containing \"Page\" => top\n//delete text in box on every page @tableFooter page.bottom page.left page.right\n\nget line starting \"Page\" => top => ignore footer below\ndelete all lines starting \"Continued\"\ndelete all lines containing \"Balance from previous statement\"\ndelete all lines containing \"TOTAL BALANCE\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 170 500 600 => describe table false \"Date[dd/MM/yy]\" - Details *#Credit\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 500 600 => describe table false \"Date[dd/MM/yy]\" Details *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @RefLeft @AmountLeft 650 => describe table false \"Date[dd/MM/yy]\" Details *#Credit','2025-01-09 08:36:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10105,'CitiBusinessBankUS','$source = \"CitiBusinessBankUS\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n@accountnameline = get line starting \"Statement\" => bottom => get line below\n@accountnametop = top @accountnameline\n@accountnamebottom = bottom @accountnameline\n@accountnameright = take last words @accountnameline 6 => left\n\n//$accountname = get text in box @accountnametop @accountnamebottom 0 @accountnameright => get text\n$accountname = get line starting \"Statement\" => bottom => get line below => take words 3 => get text\n\n@delRight = get line containing \"Statement Period\" => get words before \"Period\" => take last words 1 => left\n@delbottom = get line containing \"Statement Period\" => get words before \"Period\" => take last words 1 => bottom => subtract 80\ndelete text in box page.top @delbottom page.left @delRight\n\n// Get account number and period from/to\n@accounttopline = get line starting \"Account\" => bottom => get line below\n@accounttop = top @accounttopline\n@accountbottomline = get line containing \"Relationship Manager\" => top => get line above\n@accountbottom = bottom @accountbottomline\n@accountleft = take words @accounttopline 1 => left\n@accountinfo = get text in box @accounttop @accountbottom @accountleft page.right\n\n$accountnumber = take words @accountinfo 1 => get text\n//$periodto = take last words @accountinfo 3 => get date \"MMM dd yyyy\"\n//$periodfrom = skip words @accountinfo 3 => take words 2 => get date \"MMM dd\"\n//$periodto = get line containing \"Statement Period\" => top => get line below => take last words 3 => get date \"MMM d yyyy\"\n//$periodfrom = get line containing \"Statement Period\" => top => get line below => take last words 6 => take words 2 => get date \"MMM d\"\n$periodto = get line containing \"Statement Period\" => top => get line below => take last words 3 => get date \"MMMd,yyyy\"\n$periodfrom = get line containing \"Statement Period\" => top => get line below => take last words 6 => take words 2 => get date \"MMMd\"\n\n\n// Get opening and closing balances\n//$openingbalance = get line containing \"Beginning Balance:\" => take last words 1 => get decimal\n//$closingbalance = get line containing \"Ending Balance:\" => take last words 1 => get decimal\n$openingbalance = get line containing \"Beginning Balance:\" => get words after \"Beginning Balance:\" => take words 1 => get decimal\n$closingbalance = get line containing \"Ending Balance:\" => get words after \"Ending Balance:\" => take words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total Debits/Credits\" => top => get line above\n\n// Discard header and footer\n//delete all lines containing $accountname\nget last line starting \"Date Description\" => top => ignore header above\ndelete all lines starting \"Statement Period:\"\ndelete all lines starting \"CHECKING ACTIVITY\"\ndelete all lines starting \"Date Description\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom page.left 75 300 420 500 600 => describe table false \"Date[MM/dd]\" Details #Debit #Credit *#Balance','2025-05-06 06:26:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10106,'AfricanBarclays_ACCOUNT','$source = \"AfricanBarclays\"\n//$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account name and number\n$accountnumber = get line containing \"CHEQUE ACCOUNT NUMBER:\" => take last words 1 => get text\n@accounttopline = get line containing \"STAATNR.\"\n@accounttop = bottom @accounttopline\n@accountbottomline = get line containing \"FOR PERIOD:\"\n@accountbottom = top @accountbottomline\n@accountinfo = get text in box @accounttop @accountbottom page.left page.middleX\n$accountname = get text @accountinfo\n\n// Get period to/from\n\n$periodto = skip words @accountbottomline 7 => take words 1 => get date \"dd/MM/yyyy\"\n$periodfrom = skip words @accountbottomline 5 => take words 1 => get date \"dd/MM/yyyy\"\n\n// Get opening balances\n$openingbalance = get line containing \"BAL BROUGHT FORWARD\" => take last words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line starting \"DATUM TRANSAKSIEBESKRYWING\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"SERVICE FEE:\" => top => get line above\n\n// Get closing balance\n//@closingbottom = top @transactionsBottom\n@closingbottom = get last line starting \"SERVICE FEE:\" => top\n@infoLast = get text in box page.top @closingbottom 470 page.right\n\n\n$closingBalance = take last words @infoLast 1 => get decimal\n\n\n// Discard header and footer\nget last line starting \"DATUM TRANSAKSIEBESKRYWING\" => bottom => ignore header above\nget last line starting \"CASH, CHEQUE & ATM\" => top => ignore footer below\n\ndelete all lines containing \"BAL BROUGHT FORWARD\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom page.left 90 310 310 400 500 600 => describe table false \"Date[d/MM/yyyy]\" Details - #Debit #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 89 335 332 400 500 600 => describe table false \"Date[d/MM/yyyy]\" Details - #Debit #Credit *#Balance','2023-06-22 08:34:34',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10107,'AfricanBarclays','$source = \"AfricanBarclays\"\n//$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Parse amounts in SouthAfrica\n\nset culture \"en-ZA\"\n\n\n// Get opening and closing balances\n$openingbalance = get line containing \"Balance Brought Forward\" => skip words 3 => get decimal\n//@closingbalanceline = get line starting \"Charge\" => bottom => get line below\n//$closingbalance = skip words @closingbalanceline 1 => get decimal\n//$closingbalance = get last line starting \"Charge\" => bottom => get line below => skip words 1 => get decimal\n\n@Summarytop = get last line containing \"Balance Brought Forward\" => bottom\n@SummaryBottom = get line starting \"Date Transaction Description\" => top => get line above => top\n@SummaryBox = get text in box @Summarytop @SummaryBottom page.left page.right => get words after \"Balance\" => take words 1\n@closingtop = top @SummaryBox => add 2\n@closingBottom = bottom @SummaryBox => subtract 2\n$closingbalance = get text in box @closingtop @closingBottom 470 page.right => get decimal\n\ngo to page 1\n// Parse the amount in English for values in the table\nset culture \"en\"\n\n\n// Get account name and number\n//$accountnumber = get line containing \"Cheque Account Number:\" => get words after \"Cheque Account Number:\" => take words 3 => get text\n$accountnumber = get line containing \"Cheque Account Number:\" => get words after \"Cheque Account Number:\" => get text\n//$accountnumber = get line containing \"Cheque Account Number:\" => take last words 1 => get text\n@accounttopline = get line containing \"Cheque Account Number:\"\n@accounttop = bottom @accounttopline\n@accountbottomline = get line containing \"Cheque account statement\"\n@accountbottom = top @accountbottomline\n//@accountinfo = get text in box @accounttop @accountbottom page.left page.middleX\n@accountinfo = get text in box @accounttop @accountbottom page.left page.middleX => take words 2\n\n$accountname = get text @accountinfo\n\n// Get period to/from\n@accountperiodinfo = bottom @accountbottomline => get line below\n//$periodto = take last words @accountperiodinfo 3 => get date \"d MMM yyyy\"\n$periodfrom = take words @accountperiodinfo 3 => get date \"d MMM yyyy\"\n\n//$periodto = get last line containing \"Cheque account statement\" => bottom => get line below => take last words 3 => get date \"d MMM yyyy\"\n\n@Periodtop = get last line containing \"Cheque account statement\" => bottom\n@PeriodBottom = get last line containing \"Cheque account statement\" => bottom => get line below => bottom => subtract 2\n$periodto = get text in box @Periodtop @PeriodBottom page.left page.right => get words after \"to\" => get date \"d MMM yyyy\"\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Transaction Description\" => bottom => get line below\n\n@DateRight = get line starting \"Date Transaction Description\" => get words after \"Date\" => take words 1 => left => subtract 1\n@DetailLeft = get line starting \"Date Transaction Description\" => get words after \"Date\" => take words 1 => left => subtract 5\n\n\n// Get end of table\n//@transactionsBottom = get last line starting \"SERVICE FEE:\" => top => get line above\n@transactionsBottom = get last line starting \"Page\"\n\ndelete all lines starting \"* = VAT\"\ndelete all lines starting \"CHARGE: A\"\ndelete all lines starting \"Important\"\ndelete all lines starting \"which are not\"\ndelete all lines starting \"CREDIT INTEREST RATE\"\ndelete all lines starting \"ABSA\"\ndelete all lines containing \"PLEASE CONTACT YOUR RELATIONSHIP\"\ndelete all lines containing \"VISIT ABSA.CO.ZA.\"\ndelete all lines containing \"Bal Brought Forward\"\n\n\n$lastBottom = get last line starting \"YOUR PRICING PLAN :\" => top\ndelete text in box $lastBottom page.bottom page.left page.right\n\n$lastBottom2 = get last line starting \"SERVICE FEE:\" => top\ndelete text in box $lastBottom2 page.bottom page.left page.right\n\n// Discard header and footer\nget last line starting \"Date Transaction Description\" => bottom => ignore header above\nget last line starting \"Page\" => top => ignore footer below\n\ndelete all lines containing \"Date Transaction Description\"\n\ngo to page 1\n@top1 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top1 page.left page.right\n\n@top2 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top2 page.left page.right\n\n@top3 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box page.top @top3 page.left page.right\n\n@top4 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box page.top @top4 page.left page.right\n\n@top5 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top5 page.left page.right\n\n@top6 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top6 page.left page.right\n\n@top7 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top7 page.left page.right\n\n@top8 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top8 page.left page.right\n\n@top9 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top9 page.left page.right\n\n@top10 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top10 page.left page.right\n\n@top11 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top11 page.left page.right\n\n@top12 = get line containing \"Overdraft Limit\" => if not found then blank => bottom => get line below  => top\ndelete text in box  page.top @top12 page.left page.right\n\n\ngo to page 1\n@bt1 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt1 page.bottom page.left page.right\n\n@bt2 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt2 page.bottom page.left page.right\n\n@bt3 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt3 page.bottom page.left page.right\n\n@bt4 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt4 page.bottom page.left page.right\n\n@bt5 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt5 page.bottom page.left page.right\n\n@bt6 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt6 page.bottom page.left page.right\n\n@bt7 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt7 page.bottom page.left page.right\n\n@bt8 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt8 page.bottom page.left page.right\n\n@bt9 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt9 page.bottom page.left page.right\n\n@bt10 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt10 page.bottom page.left page.right\n\n@bt11 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt11 page.bottom page.left page.right\n\n@bt12 = get line containing \"YOUR PRICING PLAN :\" => top\ndelete text in box @bt12 page.bottom page.left page.right\n\ndelete all lines containing \"YOUR PRICING PLAN\"\ndelete all lines starting \"Your transactions\"\ndelete all lines containing \"Notific Fee Sms\"\ndelete all lines containing \"Sms Notification\"\ndelete all lines containing \"Our Privacy Notice has been updated\"\n\ndelete all lines containing \"TO ASSIST YOU IN EFFECTIVELY MANAGING YOUR ACCOUNT\"\ndelete all lines containing \"PROVIDES YOU WITH A FASTER AND MUCH MORE CONVENIENT\"\ndelete all lines containing \"YOU MORE TIME TO FOCUS ON YOUR CORE BUSINESS\"\ndelete all lines containing \"POSTED STATEMENTS IN FAVOUR OF EMAILED STATEMENTS FROM\"\ndelete all lines containing \"DEBIT INTEREST RATE AS AT\"\ndelete all lines containing \"EXCESS INTEREST RATE AS AT\"\ndelete all lines containing \"ABSA.CO.ZA\"\ndelete all lines containing \"MANAGEMENT FEE:\"\ndelete all lines ending \"%\"\ndelete all lines containing \"YOUR BANKING EXPERIENCE\"\ndelete all lines containing \"CHARGE DIGITAL TRANSACTION\"\ndelete all lines containing \"FOR MORE INFORMATION\"\n\n// delete some lines having no debit/credit\ndelete all lines containing \"Proof Of Paymt Sms\"\ndelete all lines containing \"Archive Stmt Enq\"\ndelete all lines containing \"Proof Of Pmt Email\"\ndelete all lines containing \"Decl Pos Tran Fee\"\ndelete all lines starting \"Amount :\"\ndelete all lines containing \"Dig Bnk Stmt Email\"\ndelete all lines containing \"proof of SMS and email\"\ndelete all lines containing \"Stamped Statement Settlement\"\ndelete all lines containing \"Cap: New Management F Ee\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 75 280 300 400 490 600 => describe table false \"Date[d/MM/yyyy]\" Details - #Debit #Credit *#Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 75 340 400 490 600 => describe table false \"Date[d/MM/yyyy]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @DateRight @DetailLeft 340 400 490 600 => describe table false \"Date[d/MM/yyyy]\" - Details #Debit #Credit *#Balance','2025-03-20 07:08:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10108,'USBank','$source = \"USBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\n\n//remove page 2\n@delPagetop = get line starting \"BALANCE YOUR ACCOUNT\" => top\n$DLTP = delete text in box @delPagetop page.bottom page.left page.right => get text\n\n//Remove QR\ngo to page 1\n@QRbottom = get line containing \"Page\" => bottom\n$DLTQR = delete text in box page.top @QRbottom page.middleX 455 => get text\n\ngo to page 1\n// Get account name, number, period to and from\n@accounttopline = get line containing \"Account Number:\"\n@accounttop = top @accounttopline\n\n@accountbottomline = get line containing \"Page\"\n@accountbottom = top @accountbottomline\n@accountinfo = get text in box @accounttop @accountbottom 455 page.right\n\n$accountnumber = get words between @accountinfo \"Account Number:\" \"Statement Period:\" => get text\n\n$periodfrom = get words between @accountinfo \"Statement Period:\" \"through\" => get date \"MMM d, yyyy\"\n$periodto = get words after @accountinfo \"through\" => take words 3 => get date \"MMM d, yyyy\"\n\n//$accountname = get text in box 655 646 80 360 => get text\n$accountname = get text in box 655 627 80 360 => get text\n\n// Get opening and closing balances\ngo to page 1\n@openingbalanceline = get line containing \"Beginning Balance\"\n@openTop = top @openingbalanceline\n@openbottom = bottom @openingbalanceline\n$openingbalance = get text in box @openTop @openbottom page.left page.middleX => take last words 1 => get decimal\n\n@closingbalanceline = get line containing \"Ending Balance\"\n@closeTop = top @closingbalanceline\n@closebottom = bottom @closingbalanceline\n$closingbalance = get text in box @closeTop @closebottom page.left page.middleX => take last words 1 => get decimal\nset negative marker \"-\"\n\n// Delete Account Summary\n@summarytop = get line containing \"Account Summary\" => bottom\n@summarybottom = get line containing \"Ending Balance\" => bottom\n$DelSu = delete text in box @summarytop @summarybottom page.left page.right => get text\n\n// Get start & end of Deposits / Credits table\n@DepositsCreditstop = get line starting \"Deposits / Credits\" => if not found then blank => bottom => get line below\n//Dynamics\n@Descriptionleft3 = get line containing \"Date Description of Transaction\" => get words after \"Date\" => left\n@Descriptionleft3 = subtract @Descriptionleft3 5\n@RefNumberleft3 = get line containing \"Date Description of Transaction\" => get words after \"Transaction\" => left\n@RefNumberleft3 = subtract @RefNumberleft3 2\n@Amountleft3 = get line containing \"Date Description of Transaction\" => get words before \"Amount\" => right\n@Amountleft3 = add @Amountleft3 20\n//Dynamics\n@DepositsCreditsbottom = get line starting \"Total Deposits / Credits\" => if not found then blank => top => get line above\ngo to page 1\n// Get start & end of customer deposits table\n@customertop = get line starting \"Number Date\" => if not found then blank => bottom => get line below\n@customerbottom = get line starting \"Total Customer Deposits\" => if not found then blank => top => get line above\n\n// Get start and end of other deposits table\n@othertop = get line starting \"Other Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n//Dynamics\n@Descriptionleft = get line containing \"Date Description of Transaction\" => get words after \"Date\" => left\n@Descriptionleft = subtract @Descriptionleft 5\n@RefNumberleft = get line containing \"Date Description of Transaction\" => get words after \"Transaction\" => left\n@RefNumberleft = subtract @RefNumberleft 2\n@Amountleft = get line containing \"Date Description of Transaction\" => get words before \"Amount\" => right\n@Amountleft = add @Amountleft 20\n//Dynamics\n@otherbottom = get line starting \"Total Other Deposits\" => if not found then blank => top => get line above\n\n// Get start and end of card deposits table\n@carddeptop = get line starting \"Card Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n//Dynamics\n@Descriptionleft0 = get line containing \"Date Description of Transaction\" => get words after \"Date\" => left\n@Descriptionleft0 = subtract @Descriptionleft0 5\n@RefNumberleft0 = get line containing \"Date Description of Transaction\" => get words after \"Transaction\" => left\n@RefNumberleft0 = subtract @RefNumberleft0 2\n@Amountleft0 = get line containing \"Date Description of Transaction\" => get words before \"Amount\" => right\n@Amountleft0 = add @Amountleft0 20\n//Dynamics\n@carddepbottom = get line starting \"Total Card Deposits\" => if not found then blank => top => get line above\n\n// Get start and end of card withdrawals table\n@cardtop = get line starting \"Card Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n//Dynamics\n@Descriptionleft1 = get line containing \"Date Description of Transaction\" => get words after \"Date\" => left\n@Descriptionleft1 = subtract @Descriptionleft1 5\n@RefNumberleft1 = get line containing \"Date Description of Transaction\" => get words after \"Transaction\" => left\n@RefNumberleft1 = subtract @RefNumberleft1 2\n@Amountleft1 = get line containing \"Date Description of Transaction\" => get words before \"Amount\" => right\n@Amountleft1 = add @Amountleft1 20\n//Dynamics\n@cardbottom = get line starting \"Total Card Withdrawals\" => if not found then blank => top => get line above => top => get line above\n\n// Get start and end of other withdrawals table\n@otherwithtop = get line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n//Dynamics\n@Descriptionleft2 = get line containing \"Date Description of Transaction\" => get words after \"Date\" => left\n@Descriptionleft2 = subtract @Descriptionleft2 5\n@RefNumberleft2 = get line containing \"Date Description of Transaction\" => get words after \"Transaction\" => left\n@RefNumberleft2 = subtract @RefNumberleft2 2\n@Amountleft2 = get line containing \"Date Description of Transaction\" => get words before \"Amount\" => right\n@Amountleft2 = add @Amountleft2 20\n//Dynamics\n@otherwithbottom = get line starting \"Total Other Withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of checks table\n@checkstop = get line starting \"Checks Presented Conventionally\" => if not found then blank => bottom => get line below\n@checksbottom = get line containing \"Conventional Checks Paid\" => if not found then blank => top => get line above\n\n// Get start & end of Checks Presented Electronically table\n@ElectronicCheckstop = get line starting \"Checks Presented Electronically\" => if not found then blank => bottom => get line below\n//Dynamics\n@Dateleft4 = get line containing \"Ref Number Amount Description of Transaction\" => get words after \"Check\" => left\n@Dateleft4 = subtract @Dateleft4 5\n@RefNumberleft4 = get line containing \"Ref Number Amount Description of Transaction\" => get words after \"Date\" => left\n@RefNumberleft4 = subtract @RefNumberleft4 2\n@Amountleft4 = get line containing \"Ref Number Amount Description of Transaction\" => get words after \"Ref Number\" => left\n@Amountleft4 = subtract @Amountleft4 20\n@Descriptionleft4 = get line containing \"Ref Number Amount Description of Transaction\" => get words after \"Amount\" => left\n@Descriptionleft4 = subtract @Descriptionleft4 2\n//Dynamics\n@ElectronicChecksbottom = get line containing \"Electronic Checks Paid\" => if not found then blank => top => get line above\n\n//Delete headers and footers\nignore header above 660\n\n// Remove unwanted lines\ndelete all lines starting \"U.S. Bank National Association\"\ndelete all lines starting \"Customer Deposits\"\ndelete all lines starting \"Total Customer Deposits\"\ndelete all lines starting \"Number Date\"\ndelete all lines starting \"Other Deposits (continued)\"\ndelete all lines starting \"Other Deposits\"\ndelete all lines starting \"Total Other Deposits\"\ndelete all lines starting \"Date Description of Transaction\"\ndelete all lines starting \"Member FDIC\"\ndelete all lines starting \"BALANCE YOUR ACCOUNT\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"Card Withdrawals\"\ndelete all lines containing \"Withdrawals Subtotal\"\ndelete all lines starting \"Other Withdrawals\"\ndelete all lines starting \"Total Other Withdrawals\"\ndelete all lines starting \"Checks Presented Conventionally\"\ndelete all lines starting \"Check Date\"\ndelete all lines starting \"Card Deposits\"\ndelete all lines containing \"Deposit Subtotal\"\ndelete all lines containing \"BUSINESS CHECKING\"\ndelete all lines containing \"(CONTINUED)\"\ndelete all lines starting \"Deposits / Credits\"\ndelete all lines containing \"Total Deposits / Credits\"\ndelete all lines starting \"Checks Presented Electronically\"\ndelete all lines containing \"Electronic Checks Paid\"\ndelete all lines containing \"Total Checks Paid\"\ndelete all lines starting \"Products and services available in U.S. only\"\ndelete all lines starting \"call 800-872-2657\"\n\n//@DepositsCredits = get multi page table @DepositsCreditstop @DepositsCreditsbottom 0 40 390 450 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Credit\n$DepositsCredits = get multi page table @DepositsCreditstop @DepositsCreditsbottom 0 @Descriptionleft3 @RefNumberleft3 @Amountleft3 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Credit\n\n$customerdepositsleft = get multi page table @customertop @customerbottom 0 65 120 180 300 => describe table false - \"*Date[MMM d]\" Details #Credit\n\n$customerdepositsright = get multi page table @customertop @customerbottom page.middleX 360 410 480 600 => describe table false - \"*Date[MMM d]\" Details #Credit\n\n//@otherdeposits = get multi page table @othertop @otherbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Credit\n//@otherdeposits = get multi page table @othertop @otherbottom 0 40 395 450 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Credit\n$otherdeposits = get multi page table @othertop @otherbottom 0 @Descriptionleft @RefNumberleft @Amountleft 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Credit\n\n//@carddeposits = get multi page table @carddeptop @carddepbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Credit\n$carddeposits = get multi page table @carddeptop @carddepbottom 0 @Descriptionleft0 @RefNumberleft0 @Amountleft0 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Credit\n\n//@cardwithdrawals = get multi page table @cardtop @cardbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Debit\n//@cardwithdrawals = get multi page table @cardtop @cardbottom 0 40 390 450 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Debit\n$cardwithdrawals = get multi page table @cardtop @cardbottom 0 @Descriptionleft1 @RefNumberleft1 @Amountleft1 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Debit\n\n//@otherwithdrawals = get multi page table @otherwithtop @otherwithbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Debit\n//@otherwithdrawals = get multi page table @otherwithtop @otherwithbottom 0 40 390 450 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Debit\n$otherwithdrawals = get multi page table @otherwithtop @otherwithbottom 0 @Descriptionleft2 @RefNumberleft2 @Amountleft2 600 => describe table false \"Date[MMM d]\" Details TransactionType *#Debit\n\n$checksleft = get multi page table @checkstop @checksbottom 0 65 120 180 300 => describe table false ChequeNumber \"*Date[MMM d]\" Details #Debit\n\n$checksright = get multi page table @checkstop @checksbottom page.middleX 360 410 480 600 => describe table false ChequeNumber \"*Date[MMM d]\" Details #Debit\n\n//@ElectronicChecks = get multi page table @ElectronicCheckstop @ElectronicChecksbottom 0 65 120 180 279 570 => describe table false ChequeNumber \"*Date[MMM d]\" TransactionType #Debit Details\n$ElectronicChecks = get multi page table @ElectronicCheckstop @ElectronicChecksbottom 0 @Dateleft4 @RefNumberleft4 @Amountleft4 @Descriptionleft4 570 => describe table false ChequeNumber \"*Date[MMM d]\" TransactionType #Debit Details\n\n\n$transactions = combine described tables $customerdepositsleft $customerdepositsright $otherdeposits $carddeposits $cardwithdrawals $otherwithdrawals $checksleft $checksright $DepositsCredits $ElectronicChecks','2025-08-20 07:24:37',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10109,'PayPal','$source = \"PayPal\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get account name and number\n@accounttopline = get line containing \"Statement Period:\" \n@accounttop = top @accounttopline\n@accountbottomline = get line containing \"Balance Summary*\" => top => get line above\n@accountbottom = bottom @accountbottomline\n@accountinfo = get text in box @accounttop @accountbottom page.left page.middleX\n$accountnumber = get words after @accountinfo \"Email (PayPal Account ID):\" => get text\n$accountname = get words before @accountinfo \"Email (PayPal Account ID):\" => get text\n\n// Get period to/from\n@accountperiodinfo = get text in box @accounttop @accountbottom page.middleX page.right\n$periodto = take last words @accountperiodinfo 3 => get date \"MMMM dd, yyyy\"\n$periodfrom = skip words @accountperiodinfo 2 => take words 3 => get date \"MMMM d, yyyy\"\n\n$openingbalance = get line containing \"Beginning Balance\" => take last words 1 => get decimal\n$closingbalance = get line containing \"Ending Balance\" => take last words 1 => get decimal\n\n// Get start of table\n@transactionstop = get line starting \"Date Description Currency\" => bottom => get line below \n\n// Get end of table\n@transactionsbottom = get last line containing \"*The difference between your Beginning and Ending Balances\" => top => get line above\n\n// Discard header and footer\nget last line starting \"Date Description\" => bottom => ignore header above\ndelete all lines containing \"Page\"\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom page.left 90 340 400 480 500 600 => describe table false \"Date[MM/dd/yyyy]\" Details - - - *#Credit\n\n','2021-03-10 15:30:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10110,'BarclaysOnline','$source = \"BarclaysOnline\"\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n$accountname = \"Anonymous\"\n\n$accountnumber = get line containing \"e-Payments Plan\" => take last words 1 => get text\n\n@period = get line containing \"transactions between\" => get words after \"between\"\n\n$periodfrom = take words @period 1 => get date \"dd/MM/yyyy\"\n\n$periodto = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n$openingbalance = get line starting \"Date Description Money In Money Out Balance\" => bottom => get line below => take last words 1 => get decimal\n\n$closingbalance = get last line containing \"Don\'t recognise a transaction?\" => top => get line above => take last words 1 => get decimal\n\ngo to page 1\n\n@transactionstop = get line starting \"Date Description Money In Money Out Balance\" => bottom => get line below\n\n@transactionsbottom = get last line containing \"Don\'t recognise a transaction?\" => top => get line above\n\ndelete all lines starting \"Export All Download all (PDF) Print page Don\'t recognise a transaction?\"\ndelete all lines starting \"https://bank.barclays.co.uk/olb/balances/PersonalFinancialSummary.action\"\ndelete all lines containing \"Statements - Barclays Online Banking\"\ndelete all lines starting \"Date Description Money In Money Out Balance\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 50 170 320 400 480 550 => describe table false *Date[dd/MM/yyyy] Details #Credit #Debit[-£0,000.00] #Balance\n\n\n','2021-03-10 15:31:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10119,'TDVisaUS','$source = \"TDVisaUS\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\ndelete tiny words\ndelete rotated words\n\n@accountnameandnumber = get text in box 680 670 45 360\n\n// Account number\n@accountnumber = take last words @accountnameandnumber 4\n$accountnumber = get text @accountnumber \n\n// Account name\ndelete words @accountnumber\n$accountname = get text in box 680 670 45 360 => get text\n\n// Period from\n$periodfrom = get line containing \"STATEMENT PERIOD:\" => get words after \":\" => take words 3 => get date \"MMMM dd, yyyy\"\n\n// Period to\n$periodto = get line containing \"STATEMENT PERIOD:\" => get words after \"to\" => get date \"MMMM dd, yyyy\"\n\n// Opening balance\n$openingbalance = get line containing \"Previous Balance\" => take last words 1 => get decimal\n\n// Closing balance\n$closingbalance = get line containing \"NEW BALANCE\" => get words after \"NEW BALANCE\" => take words 1 => get decimal\n\n\n//$transactionstop = get line containing \"PREVIOUS STATEMENT BALANCE\" => bottom => get line below => get text\n//$transactionsbottom = get line containing \"NET AMOUNT OF MONTHLY\" => top => get line above => get text\n@transactionstop = get line containing \"PREVIOUS STATEMENT BALANCE\" => bottom => get line below\n@transactionsbottom = get line containing \"NET AMOUNT OF MONTHLY\" => top => get line above\n\nremove page 2\n\ngo to page 1\ndelete text in box 271 page.bottom page.left page.right\ndelete text in box page.top page.bottom 360 page.right\nignore header above 610\n\n$transactions = get multi page table @transactionstop @transactionsbottom 45 80 130 290 350 => describe table false - \"Date[MMM d]\" Details *#Credit\n\n\n\n','2022-06-08 08:01:57',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10120,'TDBankUSCheckingAccount','$source = \"TDBankUSCheckingAccount\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodToRegex = \".*-(.*)\"\n$inputDateFormat = \"dd/MMMM/YY\"\n\n// Get Account Number and Account Name\n@accountNumberText = get line containing \"Account #\" => get words after \"Account #\"\n$accountnumber = take words @accountNumberText 1 => get text\n\n$accountname = get line containing \"Page:\" => get words before \"Page:\" => get text\n\n// Get statementPeriod\n@statementPeriodText = get line containing \"Statement Period:\" => get words after \"Statement Period:\"\n//$periodfrom =  take words @statementPeriodText 2 => get date \"MMM d\"\n$periodfrom =  take words @statementPeriodText 2 => get date \"MMM dd\"\n$PeriodToText =  take last words @statementPeriodText 3 => get text\n$PeriodTo =  take last words @statementPeriodText 3 => get date \"MMM d YYYY\"\n\n\n// Get opening and closing balances\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\nremove page 2\n\n// remove header from first page\ngo to page 1\n@headerBottom = get line starting \"Ending Balance\" => bottom => get line below => top\ndelete text in box page.top @headerBottom page.left page.right\n\n// Get start & end of Deposits\ngo to page 1\n@depositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@depositsBottom = get line starting \"Subtotal:\" => if not found then blank => top => get line above\n\ngo to page 1\n@Subtotaltop1 = get line starting \"Electronic Deposits\" => bottom => get line below => if not found then blank => top => get line above  => top => get line above  => top\n@Subtotalbottom1 = get line starting \"Electronic Deposits\" => bottom => get line below => if not found then blank => top => get line above => top\ndelete text in box @Subtotaltop1 @Subtotalbottom1 page.left page.right\n\n\n// Get start & end of Electronic Deposits\ngo to page 1\n$creditsTop = get line starting \"Electronic Deposits\" => if not found then blank => bottom => get line below => bottom => get line below => get text\n$creditsBottom = get last line starting \"Electronic Deposits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at => get text\n\ngo to page 1\n@creditsTop = get line starting \"Electronic Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n//@creditsBottom = get last line starting \"Electronic Deposits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n$creditsBottom2 = get last line starting \"Electronic Deposits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at => get text\n@creditsBottom = get line starting \"Subtotal:\" => if not found then blank => top => get line above\n\n// Get start & end of Checks Paid\ngo to page 1\n$checksTop = get line starting \"Checks Paid\" => if not found then blank => bottom => get line below => bottom => get line below => get text\n$checksBottom = get last line starting \"Checks Paid\" => if not found then blank => bottom => get break below => get line at => get text\ngo to page 1\n@checksTop = get line starting \"Checks Paid\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get last line starting \"Checks Paid\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\n\n// Get start & end of Electronic Payments\ngo to page 1\n@debitsTop = get line starting \"Electronic Payments\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get last line starting \"Electronic Payments\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n//@debitsBottom2 = get last line starting \"Electronic Payments\" => if not found then blank => bottom => get line below\n//$debitsBottom = get line starting \"Subtotal:\" => if not found then blank => top => get line above\n\n// Get start & end of Other Withdrawals\ngo to page 1\n$OtherWithtop = get line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n$OtherWithbottom = get last line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\ngo to page 1\n$OtherWithtopd = get line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom\n$OtherWithbottomd = get last line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get break below => get line at => bottom\n\n\n// Get start & end of Service Charges\ngo to page 1\n@serviceChargesTop = get line starting \"Service Charges\" => if not found then blank => bottom => get line below => bottom => get line below\n@serviceChargesBottom = get last line starting \"Service Charges\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\ngo to page 1\n@serviceChargesTopD = get line starting \"Service Charges\" => if not found then blank => bottom => get line below => bottom\n//@serviceChargesBottomD = get last line starting \"Service Charges\" => if not found then blank => bottom => get line below => bottom => get break below => get line at => bottom\n@serviceChargesBottomD = get line starting \"Service Charges\" => if not found then blank => bottom => get break below => get line at => bottom\n\n// Get start & end of Other Credits\ngo to page 1\n\n@Subtotaltop2 = get line starting \"Other Credits\" => if not found then blank  => bottom => get line below => top => get line above  => top => get line above  => top\n@Subtotalbottom2 = get line starting \"Other Credits\" => if not found then blank => bottom => get line below => top => get line above => top\n$DeleteSubtotal_Above_OtherCredits = delete text in box @Subtotaltop2 @Subtotalbottom2 page.left page.right => get text\n\n@OtherCreditsTop = get line starting \"Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@OtherCreditsBottom = get line starting \"Subtotal:\" => if not found then blank => top => get line above\n//@OtherCreditsBottom =  get last line starting \"Other Credits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\n\ngo to page 1\ndelete all lines containing \"DAILY ACCOUNT ACTIVITY\"\ndelete all lines containing \"Deposits\"\ndelete all lines containing \"POSTING DATE DESCRIPTION\"\ndelete all lines containing \"Checks Paid (continued)\"\ndelete all lines containing \"DATE SERIAL NO. AMOUNT\"\ndelete all lines containing \"Subtotal:\"\ndelete all lines containing \"www.tdbank.com\"\n//delete all lines containing \"TD Bank, N.A.\"\ndelete all lines containing \"Electronic Deposits\"\ndelete all lines starting \"Electronic Payments\"\ndelete all lines containing \"Service Charges\"\ndelete all lines starting \"Other Withdrawals\"\ndelete all lines containing \"Other Credits\"\nignore header above 650\nignore footer below 35\n\n// Read the transactions\ngo to page 1\n\n@serviceCharges = get multi page table @serviceChargesTop @serviceChargesBottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Debit\ndelete text in box @serviceChargesTopD @serviceChargesBottomD page.left page.right\n\n@OtherWithdrawals = get multi page table $OtherWithtop $OtherWithbottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Debit\ndelete text in box $OtherWithtopd $OtherWithbottomd page.left page.right\n\n@deposits = get multi page table @depositsTop @depositsBottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n@credits = get multi page table @creditsTop @creditsBottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Debit\n@checksLeft = get multi page table @checksTop @checksBottom 60 120 220 320 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n@checksRight = get multi page table @checksTop @checksBottom 325 420 520 600 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n\ngo to page 1\n//$checksTopD = get line starting \"Checks Paid No.\" => if not found then blank => bottom => get line below => top\n$checksTopD = get line starting \"Checks Paid No.\" => bottom => get line below => top\n$checksBottomD = get line starting \"Checks Paid\" => if not found then blank => bottom => get line below => bottom => get break below => get line at => bottom\n$delcheck = delete text in box $checksTopD $checksBottomD page.left page.right => get text\ndelete all lines containing \"Checks Paid\"\n\n@OtherCredits = get multi page table @OtherCreditsTop @OtherCreditsBottom 60 140 520 600 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n//$transactions = combine described tables  @deposits @credits @checksLeft @checksRight @debits @OtherWithdrawals @serviceCharges @OtherCredits\n$transactions = combine described tables  @deposits @credits @debits @OtherWithdrawals @serviceCharges @OtherCredits @checksLeft @checksRight','2024-12-11 08:10:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10121,'USBankCard','$source = \"USBankCard\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountname = get text in box 655 648 80 360 => get text\n\n$accountnumber = get line starting \"Account Number:\" => bottom => get line below => take words 4 => get text\n\n$periodfrom = get line containing \"Statement Period:\" => bottom => get line below => take last words 3 => get date \"MMM d, yyyy\"\n\n$periodto = get line containing \"through\" => bottom => get line below => take last words 3 => get date \"MMM d, yyyy\"\n\n$openingbalance = get line starting \"Beginning Balance on\" => take last words 1 => get decimal\n\n$closingbalance = get line starting \"Ending Balance on\" => take last words 1 => get decimal\n\n@closingbalancebottom = get line starting \"Ending Balance on\" => bottom\ndelete text in box page.top @closingbalancebottom page.left page.right\n\nremove page 2\n\ngo to page 1\n@customerdepositstop = get line starting \"Customer Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@customerdepositsbottom = get line starting \"Total Customer Deposits\" => if not found then blank => top => get line above\n\n@customerdepositslefttable = get multi page table @customerdepositstop @customerdepositsbottom 0 60 120 210 290 => describe table false  - \"*Date[MMM d]\" - #Credit\n@customerdepositsrighttable = get multi page table @customerdepositstop @customerdepositsbottom 295 360 410 510 590 => describe table false  - \"*Date[MMM d]\" - #Credit\n\ngo to page 1\n@otherdepositstop = get line starting \"Other Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherdepositsbottom = get line starting \"Total Other Deposits\" => if not found then blank => top => get line above\n\n@otherdepositstable = get multi page table @otherdepositstop @otherdepositsbottom 0 40 400 600 => describe table false \"*Date[MMM d]\" Details #Credit\n\ngo to page 1\n@cardwithdrawalstop = get line starting \"Card Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n@cardwithdrawalsbottom = get line containing \"Withdrawals Subtotal\" => if not found then blank => top => get line above\n\n@cardwithdrawalstable = get multi page table @cardwithdrawalstop @cardwithdrawalsbottom 0 40 400 600 => describe table false \"*Date[MMM d]\" Details \"#Debit[0,000.00-]\"\n\ngo to page 1\n@otherwithdrawalstop = get line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherwithdrawalsbottom = get line starting \"Total Other Withdrawals\" => if not found then blank => top => get line above\n\n@otherwithdrawalstable = get multi page table @otherwithdrawalstop @otherwithdrawalsbottom 0 40 400 600 => describe table false \"*Date[MMM d]\" Details \"#Debit[0,000.00-]\"\n\ngo to page 1\n@checkstop = get line starting \"Checks Presented Conventionally\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksbottom = get line containing \"Conventional Checks Paid\" => if not found then blank => top => get line above\n\n@checkslefttable = get multi page table @checkstop @checksbottom 0 60 120 210 290 => describe table false  CheckNumber \"*Date[MMM d]\" - #Debit\n@checksrighttable = get multi page table @checkstop @checksbottom 295 360 410 510 590 => describe table false  CheckNumber \"*Date[MMM d]\" - #Debit\n\n\n$transactions = combine described tables @customerdepositslefttable @customerdepositsrighttable @otherdepositstable @cardwithdrawalstable @otherwithdrawalstable @checkslefttable @checksrighttable','2022-03-10 13:40:39',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10122,'SantanderOnlineCard','$source = \"SantanderOnlineCard\"\n\n$features = \"CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n$periodbufferdays = 14\n\n$accountname = \"Anonymous\"\n\n$accountnumber = get line starting \"Card number:\" => get words after \"number:\" => get text\n\n@period = get line starting \"Transaction date:\" => get words after \"date:\"\n\n$periodfrom = take words @period 1 => get date \"dd/MM/yyyy\"\n\n$periodto = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n$openingbalance = get line containing \"INITIAL BALANCE\" => take last words 1 => get decimal\n\n$closingbalance = 0\n\n$Description_left = get line starting \"Date Card Number Description Money In Money Out\" => get words after \"Card Number\" => take words 1 => left => subtract 8\n$Description_right = get line starting \"Date Card Number Description Money In Money Out\" => get words after \"Description\" => take words 1 => left => add 5\n$Moneyin_Left = get line starting \"Date Card Number Description Money In Money Out\" => get words after \"Description\" => take words 1 => left => subtract 5\n\n//@transactionstop = get line containing \"INITIAL BALANCE\" => bottom => get line below\n@transactionstop = get line containing \"Date Card Number Description Money In Money Out\" => bottom => get line below\n\n@transactionsbottom = get last line starting \"Page\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"Page\"\ndelete all lines starting \"Date Card Number Description\"\ndelete all lines starting \"Card number:\"\ndelete all lines starting \"Transaction date:\"\nignore header above 734\ndelete all lines containing \"INITIAL BALANCE\"\n\n//$transactions = get multi page table @transactionstop @transactionsbottom 30 100 198 375 460 530 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Debit\n//$transactions = get multi page table @transactionstop @transactionsbottom 30 100 198 375 460 530 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Debit #Credit\n$transactions = get multi page table @transactionstop @transactionsbottom 30 100 $Description_left $Description_right $Moneyin_Left 460 530 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details - #Debit #Credit','2025-02-12 08:09:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10123,'BarclayCard','$source = \"BarclayCard\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n$periodbufferdays = 31\n\n$accountname = get line starting \"barclaycard.co.uk/login\" => bottom => get line below => bottom => get line below => bottom => get line below => get text\n\n$accountnumber = get line starting \"Number\" => get words after \"Number\" => get text\n\n//$periodfrom = get line starting \"At a glance\" => get words after \"glance\" => get date \"dd MMMM yyyy\"\n\n$periodto = get line starting \"At a glance\" => get words after \"glance\" => get date \"dd MMMM yyyy\"\n\nset negative marker \"CR\"\ndelete text in box page.top page.bottom page.middleX page.right\n$openingbalance = get line starting \"Your previous balance:\" => get words after \"balance:\" => take words 1 => get decimal\n\n//$closingbalance = get line starting \"Your new balance:\" => get words after \"balance:\" => take words 1 => get decimal\n$closingbalance = get last line starting \"Your new balance:\" => get words after \"balance:\" => take words 1 => get decimal\n\ngo to page 2\n\ndelete text in box page.top page.bottom 300 page.right\n\nget line starting \"Ways to pay\" => top => ignore footer below\n\nremove original page 3\nremove original page 4\n\n@paymentstop = get line starting \"Payments towards your account\" => bottom => get line below\n\n@paymentsbottom = get line starting \"Transactions, interest and charges\" => top => get line above\n\n@transactionstop = get line starting \"How you\'ve used your card\" => bottom => get line below\n$periodfrom = take words @transactionstop 2 => get date \"dd MMM\"\n\n@transactionsbottom = get line starting \"Promotional transactions\" => top => get line above\n\n@promotionaltop = get line starting \"Promotional transactions\" => bottom => get line below\n\n@promotionalbottom = get line starting \"Interest and charges\" => top => get line above\n\n@chargestop = get line starting \"Interest and charges\" => bottom => get line below\n\n@chargesbottom = get line starting \"Your new balance\" => top => get line above\n\ndelete all lines containing \"no payment transactions\"\ndelete all lines containing \"no transactions\"\ndelete all lines containing \"no promotional transactions\"\ndelete all lines containing \"no charges or interest transactions\"\n\n//set negative marker \"CR\"\n\n@paymentstable = get multi page table @paymentstop @paymentsbottom 40 80 220 300 => describe table false \"*Date[dd MMM]\" Details #Debit\n@transactionstable = get multi page table @transactionstop @transactionsbottom 40 80 220 300 => describe table false \"*Date[dd MMM]\" Details #Credit\n@promotionaltable = get multi page table @promotionaltop @promotionalbottom 40 80 220 300 => describe table false \"*Date[dd MMM]\" Details #Debit\n@chargestable = get multi page table @chargestop @chargesbottom 40 80 220 300 => describe table false \"*Date[dd MMM]\" Details #Credit\n\n$transactions = combine described tables @paymentstable @transactionstable @promotionaltable @chargestable','2025-01-09 08:35:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10124,'StandardBankSA','$source = \"StandardBankSA\"\n$features = \"NO_OPENING_BALANCE\"\n\n//$periodBufferDays = 45\n$periodBufferDays = 100\n\n// Get account name and number\n@accounttopline = get line containing \"Account number:\"\n@accounttop = top @accounttopline\n@accountbottomline = get line containing \"Product name:\" => top => get line above\n@accountbottom = bottom @accountbottomline\n@accountinfo = get text in box @accounttop @accountbottom page.left page.middleX\n\n@top_accnt = get line containing \"Account number\" => top\n@bottom_accnt = get line containing \"Account number\" => bottom\n$accountname = get text in box @top_accnt @bottom_accnt page.left 175 => get words after \"Account number\" => get text\n$accountnumber = get text in box @top_accnt @bottom_accnt page.left 175 => get words after \"Account number\" => get text\n\n// Get period from/to\n@periodfromline = get line containing \"From:\"\n$periodfrom = skip words @periodfromline 1 => take words 3 => get date \"dd MMM yy\"\n@periodtoline = get line containing \"To:\"\n$periodto = skip words @periodtoline 1 => take words 3 => get date \"dd MMM yy\"\n\n//get date column dynamic_coordinates\ngo to page 1\n$date_left = get line containing \"Date Description\" => get words before \"Description\" => left => subtract 8\n$date_right = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 8\n//$debit_left = get line containing \"Date Description\" => get words before \"Deposits\" => take last words 1 => left => subtract 8\n$debit_left = get line containing \"Date Description\" => get words before \"Deposits\" => take last words 1 => left => subtract 20\n$debit_right = get line containing \"Date Description\" => get words before \"Deposits\" => take last words 1 => right => add 10\n\n//get balance column dynamic_coordinates\n$balance_left = get line containing \"Date Description\" => get words after \"Payments\" => take words 1 => right => add 10\n$balance_right = get line containing \"Date Description\" => get words after \"Deposits\" => right => add 20\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n\n// Discard header and footer\n//get last line starting \"Date Description\" => bottom => ignore header above\nignore header above 650\n\ndelete all lines containing \"STATEMENT OPENING BALANCE\"\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Transaction details\"\ndelete all lines containing \"Please verify all transactions\"\ndelete all lines containing \"Statement Summary\"\ndelete all lines containing \"debits have not yet been paid\"\ndelete all lines starting \"Payments -R\"\ndelete all lines starting \"Deposits R\"\nget last line containing \"We subscribe to the Code\"\n\ndelete all lines starting \"We subscribe to the Code\"\ndelete all lines containing \"The Standard Bank of South Africa Limited\"\n\n// Get end of table\n@transactionsBottom = get line above 30\n\n// Get closing balance\n//@closingbottom = bottom @transactionsBottom\n@closingbottom = top @transactionsBottom => get line above => bottom => subtract 40\n@infoLast = get text in box page.top @closingbottom 470 page.right\n$closingBalance = take last words @infoLast 1 => get decimal\nset negative marker \"-\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 80 345 420 500 600 => describe table false \"Date[dd MMM yy]\" Details #Debit #Credit *Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom $date_left $date_right $debit_left $debit_right $balance_left $balance_right => describe table false \"Date[dd MMM yy]\" Details #Debit #Credit *Balance','2025-07-24 06:51:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10125,'AmericanExpressUKOtherAccTrans','$source = \"AmericanExpressUKOtherAccTrans\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 49\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get account name\n$accountName = get line starting \"Private & Confidential\" => bottom => get line below => get text\n\n// Get account number\n$accountNumber = get text in box 745 730 270 370 => get text\n\n// Get period from/to\n@period = get line starting \"Statement Period\" => skip words 3\n$periodFrom = take words @period 2 => get date \"d MMMM\"\n$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n// Get opening and closing balances\n$openingBalanceText = get text in box 685 660 90 180\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get text in box 685 660 400 490\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\n@transactionsTop = get line starting \"Date Date Transaction Details\" => bottom => get line below\n\n// Discard page header\nget last line starting \"Date Date Transaction Details\" => bottom => ignore header above\n\n// Discard page footer\ngo to page 1\nget line starting \"(Continued on next page)\" => top => ignore footer below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total of other account transactions\" => top => get line above\n\n// Discard info on page 1\ngo to page 1\nget line starting \"American Express Services Europe Limited has its registered office\" => top => delete text in box 0 page.left page.right\n\n// Discard info on page 2\ngo to page 1\nget line starting \"How you can pay your statement\" => top => delete text in box 0 page.left page.right\n\n// Discard unwanted text\ndelete all lines starting \"Transaction Process\"\ndelete all lines starting \"Date Date Transaction Details\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"New Transactions for\"\ndelete all lines starting \"Total new spend\"\ndelete all lines starting \"OTHER ACCOUNT TRANSACTIONS\"\ndelete all lines starting \"Total of other account transactions\"\ndelete all lines starting \"Total Cash Withdrawals for\"\ndelete all lines starting \"Total debits for\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 105 140 380 490 600 => describe table false \"TransDate[MMM d]\" \"*Date[MMM d]\" Details - #Credit','2024-05-14 10:48:24',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10126,'BOIBusinessCreditCard','$source = \"BOIBusinessCreditCard\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n$periodbufferdays = 31\n\nset negative marker \"CR\"\n\ndelete rotated words\ndelete tiny words\n\n$accountnumber = get line containing \"Account Number:\" => skip words 2 => get text\n\n$accountname = get line containing \"Cardholder:\" => skip words 1 => get text\n\n$periodfrom = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 3 => get date \"dd MMMM yyyy\"\n$periodto = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 3 => get date \"dd MMMM yyyy\"\n\n$openingbalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\n$closingbalance = get line containing \"Statement Balance\" => get words after \"Statement Balance\" => take words 1 => get decimal\n\n@transactiondetailstop = get line containing \"Transaction Details\" => top\ndelete text in box page.top @transactiondetailstop page.left page.right\ndelete text in box @transactiondetailstop page.bottom page.left 180\n\n// delete left column for up to 3 pages\ngo to page 1\n@leftcolumn = get line containing \"Account Number\" \ndelete text in box page.top page.bottom page.left 180\n\ngo to page 1\n@leftcolumn = get line containing \"Account Number\" \ndelete text in box page.top page.bottom page.left 180\n\ngo to page 1\n@leftcolumn = get line containing \"Account Number\" \ndelete text in box page.top page.bottom page.left 180\n\ngo to page 1\n@transactionstop = get line containing \"Transaction Details\" => bottom => get line below\n\ndelete all lines containing \"Business Credit Card\"\ndelete all lines containing \"Statement\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"Other Transactions\"\n\ngo to page 1\n@transactionsbottom = get last line containing \"Balance\" => top => get line above\n\ngo to page 1\n\ndelete all lines containing \"Balance\"\ndelete all lines containing \"Total Transactions\"\ndelete all lines containing \"Continued\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 180 230 491 580 => describe table false \"*Date[dd MMM]\" Details #Credit','2021-11-22 05:55:28',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10127,'MonzoBank','$source = \"MonzoBank\"\n\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n$periodBufferDays = 14\n\n@TextBoxBottom = get line containing \"Total balance\" => top => get line above => top\n@textBox = get text in box page.top @TextBoxBottom page.middleX page.right\n\n// Get statement period\n$periodto = get words after @textBox \"-\" => get date \"dd/MM/yyyy\"\n$accountnumber = get line starting \"Account\" => get words after \":\" => take words 1 => get text\n$periodfrom = get words before @textBox \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\n\n// Get account name\n@TextBoxBottom2 = get line containing \"Sort code:\" => top\n$accountname = get text in box page.top @TextBoxBottom2 0 page.middleX => take words 3 => get text\n\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n@transactionsBottom = get last line starting \"Monzo Bank Limited\" => top => get line above\n\n//Get closingBalance\ngo to page 1\n@closingtop = top @transactionsTop\n@infoLast = get text in box @closingtop page.bottom 480 page.right\n@closingBottom = take words @infoLast 1 => bottom\n$closingBalance = get text in box @closingtop @closingBottom 480 page.right => get decimal\n\n//get date column dynamic_coordinates\ngo to page 1\n@date_right = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 10\n\n//delete all lines starting \"Monzo Bank Limited\"\n//get line starting \"Monzo Bank Limited\" => top => ignore footer below\ndelete all lines starting \"Date Description\"\ndelete all lines containing \"(GBP)\"\ndelete all lines starting \"2AG\"\ndelete all lines starting \"Authority. Our Financial\"\n\nignore footer below 60\ndelete all lines starting \"Monzo Bank Limited (https://monzo.com)\"\ndelete all lines starting \"Square, London, EC2A\"\ndelete all lines starting \"Financial Conduct Authority and the Prud\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 65 120 400 480 550 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit *#Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 65 124 390 480 550 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit *#Balance\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 17.5 65 124 390 480 550 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 17.5 65 @date_right 402 390 480 550 => describe table false \"Date[dd/MM/yyyy]\" Details - #Credit #Balance','2025-05-22 07:20:24',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10128,'CydesdaleBankCurrentAccount','$source = \"ClydesdaleBankCurrentAccount\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 5\n\nset negative marker \"OD\"\ndelete rotated words\ndelete tiny words\n\n@accountdetailstop = get line containing \"Statement date\" => top\n@accountdetailsbottom = get line containing \"Current limit\" => bottom\n//@accountdetails = get text in box @accountdetailstop @accountdetailsbottom 440 page.right\n@accountdetails = get text in box @accountdetailstop 383 440 page.right\n\n@previousstatement = get line containing \"Previous statement\"\n\n$accountname = get words after @accountdetails \"Account name\" => get words before \"Sort Code\" => get text\n\n$accountnumber = get words after @accountdetails \"Account number\" => take words 1 => get text\n\n//$periodfrom = take words @previousstatement 3 => get date \"dd MMM yyyy\"\n\n$periodto = get words after @accountdetails \"Statement date\" => take words 3 => get date \"dd MMMM yyyy\"\n\n//$openingbalance = get words after @previousstatement \"Previous statement\" => take words 2 => get decimal\n\n//$closingbalance = get words after @accountdetails \"Current balance\" => get words before \"Current limit\" => get decimal\n$closingbalance = get words after @accountdetails \"Current balance\" => take words 2 => get decimal\n\n@transactionstop = get line containing \"Previous statement\" => bottom => get line below\n$getdeletext = delete text in box 180 page.bottom page.left page.right\n\nremove page 2\n\ngo to page 1\ndelete text in box on every page page.top page.bottom 430 page.right\ndelete text in box on every page page.top page.bottom page.left 40\n\ngo to page 1\n//Delete Left scan words also delete right text on right side of page\n\n$openingbalance = get line containing \"Previous statement\" => take last words 2 => get decimal\n$periodfrom = get line containing \"Previous statement\" => take words 3 => get date \"dd MMM yyyy\"\n\n\n\n// go to last page\nget last line containing \"Balance brought forward from previous page\"\n\n@transactionsbottom = get line above page.bottom\n\ngo to page 1\n\ndelete all lines containing \"Clydesdale Bank PLC\"\ndelete all lines containing \"other than regulated mortgages\"\ndelete all lines containing \"Registered Office:\"\ndelete all lines containing \"Balance brought forward from previous page\"\ndelete all lines containing \"Statement No:\"\ndelete all lines containing \"Date Description\"\n\n//$transactions = get multi page table @transactionstop @transactionsbottom 20 90 115 250 305 355 420 => describe table false \"Date[dd MMM]\" TransactionType Details **#Debit **#Credit -\n$transactions = get multi page table @transactionstop @transactionsbottom 20 90 118 115 250 305 355 420 => describe table false \"Date[dd MMM]\" TransactionType - Details **#Debit **#Credit -','2022-12-12 07:49:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10129,'NationalBankOfCanada','$source = \"NationalBankOfCanada\"\r\n\r\n//$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\ndelete tiny words\r\n\r\n@Summarytop = get line containing \"Period from\" => top\r\n@Summarybottom = get line containing \"Account no.\" => bottom\r\n@Summary = get text in box @Summarytop @Summarybottom page.middleX 600\r\n\r\n$periodFrom = get words after @Summary \"Period from\" => get words between \"from\" \"to\" => get date \"yyyy-MM-d\"\r\n$periodTo = get words after @Summary \"to\" => get words between \"to\" \"Page\" => get date \"yyyy-MM-d\"\r\n$accountNumber = get words after @Summary \"Account no.\" => get words between \"Account no.\" \"Branch no.\" => get text\r\n$accountName = get text in box @Summarybottom page.middleY 0 page.middleX => take words 3 => get text\r\n\r\n$openingbalance =  get line containing \"PREVIOUS BALANCE\" => get words after \"BALANCE\" => get decimal\r\n\r\n//$closingbalance = 0\r\n\r\ngo to page 1\r\n@ClosingBalanceTop = get last line starting \"MM DD DESCRIPTION DEBIT\" => bottom => get line below => top\r\ngo to page 1\r\n@ClosingBalanceBottom = get last line starting \"MM DD DESCRIPTION DEBIT\" => bottom => get break below => get line at => bottom\r\n$closingbalance = get text in box @ClosingBalanceTop @ClosingBalanceBottom 520 page.right => take last words 1 => get decimal\r\n\r\n// transaction table start\r\ngo to page 1\r\n$transactionstop = get line containing \"PREVIOUS BALANCE\" => bottom => get line below\r\n//@transactionsbottom = get line containing \"TRANSACTIONS UNIT FEE\" => top => get line above\r\n\r\ngo to page 1\r\n@get_top = get line containing \"TRANSACTIONS UNIT FEE\" => if not found then blank => top => get line above => bottom\r\n$get_del_text = delete text in box @get_top page.bottom page.left page.right => get text\r\n\r\ngo to page 1\r\n@get_footer_top = get line containing \"INFORMATION ON LINE OF CREDIT\" => if not found then blank => top => get line above => bottom\r\n@get_footer_bottom = get line containing \"AVAILABLE CREDIT\" => if not found then blank => bottom => get line below => top\r\n$get_del_footer_text = delete text in box @get_footer_top @get_footer_bottom page.left page.right => get text\r\n\r\n// transaction table end\r\ngo to page 1\r\n//@get_transaction_bottom = get last line containing \"MM DD DESCRIPTION DEBIT\" => bottom\r\n//@transactionsbottom = get line above 0\r\n$transactionsBottom = get last line starting \"MM DD DESCRIPTION DEBIT\" => bottom => get break below => get line at\r\n\r\n//ignore header\r\n//get last line starting \"MM DD  DESCRIPTION DEBIT CREDIT BALANCE\" => bottom => ignore header above\r\nget last line starting \"MM DD  DESCRIPTION DEBIT\" => bottom => ignore header above\r\n\r\nignore footer below 28\r\n\r\n// delete footer line\r\ngo to page 1\r\ndelete all lines starting \"Please check this statement as soon as possible.\"\r\ndelete all lines starting \"NUMBER TOTAL AMOUNT\"\r\ndelete all lines starting \"TRANSACTIONS DEBIT\"\r\ndelete all lines starting \"MM DD DESCRIPTION DEBIT\"\r\ndelete all lines containing \"OUR BANKING PACKAGES FOR BUSINESSES\"\r\ndelete all lines containing \"FIND OUT MORE ABOUT\"\r\ndelete all lines containing \"ALL THE DETAILS ON THE CHANGES\"\r\ndelete all lines containing \"NBC.CA/BUSINESS-ACCOUNTS\"\r\n\r\n//$transactions = get multi page table $transactionstop $transactionsBottom 40 110 390 445 510 600 => describe table false \"*Date[MM dd]\" Details #Debit #Credit #Balance\r\n$transactions = get multi page table $transactionstop $transactionsBottom 40 90 370 450 520 600 => describe table false \"*Date[MM dd]\" Details #Debit #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10130,'CapitalOnTapCreditCard','$source = \"CapitalOnTapCreditCard\"\n\n$features = \"CREDIT_CARD\"\n\n$accountname = get text in box 800 690 0 400 => get text\n\n$accountnumber = get text in box 745 725 400 700 => get text\n\n@period = get line starting \"Statement Summary\" => bottom => get line below\n//$periodfrom = take words @period 1 => get date \"dd/MM/yyyy\"\n//$periodto = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n@balance = get line starting \"Opening Balance\" => bottom => get line below\n$openingbalance = take words @balance 1 => get decimal\n$closingbalance = take last words @balance 1 => get decimal\n\ngo to page 1\n@transactionstop = get last line containing \"Opening Balance\" => bottom => get line below\n$periodfrom = get last line containing \"Opening Balance\" => take words 1 => get date \"dd/MM/yyyy\"\n@transactionsbottom = get last line containing \"Closing Balance\" => top => get line above\n$periodto = get last line containing \"Closing Balance\" => take words 1 => get date \"dd/MM/yyyy\"\n\ndelete all lines starting \"© New Wave Capital Limited\"\ndelete all lines starting \"Wave Capital Limits\"\ndelete all lines starting \"Interest on card\"\nignore footer below 50\n\n//$transactions = get multi page table @transactionstop @transactionsbottom  20 105 160 210 440 500 570 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType - Details #Credit #Balance\n$transactions = get multi page table @transactionstop @transactionsbottom  20 93 157 435 510 570 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Credit','2023-05-31 08:31:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10131,'VirginAtlanticCard','$source = \"VirginAtlanticCard\"\r\n$features = \"CREDIT_CARD\"\r\n\r\n$periodBufferDays = 5\r\n\r\n// Get account number\r\n$accountnumber =  get line containing \"Your account number:\" => get words after \"Your account number:\" => take words 4 => get text\r\n@todelete = get line containing \"Your account number:\" => get words after \"Your account number:\" => take words 2 => get text\r\n\r\n// get account name\r\ngo to page 1\r\n$accountname = get text in box 710 540 page.left 180 => take words 2 => get text\r\n//get line containing \"Your new balance\" => get words before \"Your new balance\" => get text\r\n\r\n// get account period\r\n@period = get line containing \"Statement period:\"\r\n$periodfrom = get words after @period \"Statement period:\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodto = get words after @period \"-\" => get date \"dd/MM/yyyy\"\r\n\r\n// get opening and closing balance\r\n$openingbalance = get line starting \"Balance from your previous statement\" => take last words 1 => get decimal\r\n//$closingbalance = get line starting \"Your new balance\" => take last words 1 => get decimal\r\n$closingbalance = get last line starting \"Your new balance\" => take last words 1 => get decimal\r\n\r\n// delete summary details\r\ngo to page 1\r\n@summarytop = get line containing \"Your credit card\" => bottom\r\n@summarybottom = get line containing \"Available to spend\" => top\r\ndelete text in box @summarytop @summarybottom page.middleX page.right\r\n\r\n// get table start and end\r\ngo to page 1\r\n@paymentstart = get line starting \"Payments made\" => bottom => get line below => bottom => get line below\r\n@paymentend = get line starting \"Spending on your card\" => top => get line above\r\n@spendingstart = get line starting \"Spending on your card\" => bottom => get line below => bottom => get line below\r\n@spendingend = get line starting \"Interest, fees and charges\" => top => get line above\r\n@intereststart = get line starting \"Interest, fees and charges\" => bottom => get line below => bottom => get line below\r\n@interestend = get line starting \"Your new balance\" => top => get line above\r\n\r\n//get date column dynamic_coordinates\r\ngo to page 1\r\n$Amount_left = get line containing \"Transaction date Post date Description Amount\" => get words after \"Description\" => left => subtract 5\r\n$Amount_right = get line containing \"Transaction date Post date Description Amount\" => get words after \"Description\" => right => add 30\r\n\r\n\r\n\r\nignore footer below 75\r\n\r\n// delete headers and footers\r\ndelete all lines containing \"virginatlantic.com\"\r\ndelete all lines containing \"Transaction date Post date Description\"\r\ndelete all lines starting \"Spending on your card\"\r\ndelete all lines starting \"Payments made\"\r\ndelete all lines starting \"Total\"\r\ndelete all lines starting \"Interest, fees and charges\"\r\ndelete all lines starting \"No interest and charges on this statement\"\r\ndelete all lines containing @todelete\r\n//delete all lines starting \"No interest and charges on this statement\"\r\ndelete all lines starting \"No spending on this statement\"\r\n\r\ndelete all lines starting \"Description\"\r\ndelete all lines starting \"Your credit card balance\"\r\ndelete all lines starting \"Your instalmentbalance\"\r\n\r\n\r\n//@payments = get multi page table @paymentstart @paymentend 50 130 200 450 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n//@spendings = get multi page table @spendingstart @spendingend 50 130 200 450 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n//@interest = get multi page table @intereststart @interestend 50 130 200 450 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n//@payments = get multi page table @paymentstart @paymentend 50 130 200 467 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n//@spendings = get multi page table @spendingstart @spendingend 50 130 200 467 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n//@interest = get multi page table @intereststart @interestend 50 130 200 467 600 => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n\r\n@payments = get multi page table @paymentstart @paymentend 50 130 200 $Amount_left $Amount_right => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n@spendings = get multi page table @spendingstart @spendingend 50 130 200 $Amount_left $Amount_right => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n@interest = get multi page table @intereststart @interestend 50 130 200 $Amount_left $Amount_right => describe table false - \"*Date[dd MMM yy]\" Details *#Credit\r\n\r\n$transactions = combine described tables @payments @spendings @interest','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10132,'SiliconValleyBank','$source = \"SiliconValleyBank\"\n\n// Get account number\n$accountnumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\n\n// Get account name\n$accountname = get line starting \"IBAN:\" => bottom => get line below => get text\n\n// Get Period\n$periodfrom = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get date \"dd-MMM-yyyy\"\n$periodto = get line starting \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get date \"dd-MMM-yyyy\"\n\n// Get opening and closing balance\n$openingbalance = get line starting \"Opening Balance\" => take last words 1 => get decimal\n$closingbalance = get line starting \"Closing Balance\" => take last words 1 => get decimal\n\n// Get transaction table start and end\n@transactionstop = get line starting \"Date Reference Number\" => bottom => get line below\n@transactionsbottom = get line starting \"Your deposit is eligible for protection\" => top => get line above\n\nget line starting \"Silicon Valley Bank is registered in England\" => top => ignore footer below\nget line starting \"Silicon Valley Bank UK Limited\" => top => ignore footer below\ndelete all lines starting \"Date Reference Number\"\nignore header above 821\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom page.left 75 85 320 420 500 600 => describe table false \"Date[dd-MMM-yyyy]\" - Details #Debit #Credit *#Balance','2024-07-31 07:20:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10133,'Revolut_IBAN','$source = \"Revolut_IBAN\"\n \n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n\n@accountdetails = get line containing \"Date\"\n$accountname = bottom @accountdetails => get line below => get text\n\n$periodfrom = get words between @accountdetails \"Date:\" \"to\" => get date \"d MMM yyyy\"\n$periodto = get words after @accountdetails \"to\" => get date \"d MMM yyyy\"\n\n@accountnametop = get line containing \"IBAN\" => top\n@accountnamebottom = get line containing \"BIC\" => top\n$accountnumber = get text in box @accountnametop @accountnamebottom page.left page.middleX => get words after \"IBAN\" => get text\n\n$closingbalance = get line containing \"Total Balance as of\" => take last words 1 => get decimal\n\n@transactiontop = get line starting \"Completed Date Description Paid Out\" => bottom => get line below\n@transactionbottom = get line containing \"Revolut Ltd (Company No. 08804411)\" => top => get line above\n\ndelete all lines starting \"Completed Date Description Paid Out\"\ndelete all lines starting \"EUR Pockets\"\ndelete all lines starting \"No Transactions\"\n\n$transactions = get multi page table @transactiontop @transactionbottom 30 100 320 420 490 570 => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit *#Balance','2021-04-01 07:58:21',0);
