ses\" => top => get line above => top => get line above\n@purchasestart = get line starting \"Purchases\" => bottom => get line below => bottom => get line below\n@purchaseend = get line starting \"Other Withdrawals\" => top => get line above => top => get line above\n@otherstart = get line starting \"Other Withdrawals\" => bottom => get line below => bottom => get line below\n@otherend = get line starting \"Information and Banking Office Services\" => top => get line above => top => get line above\n\n// delete headers and footers\ndelete all lines starting \"Page\"\ndelete all lines starting \"Statement Number:\"\ndelete all lines starting @periodfromtext \ndelete all lines starting \"Additions\"\ndelete all lines containing \"Date Description/Location\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"Checks\"\ndelete all lines starting \"Number Date\"\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Purchases\"\ndelete all lines starting \"Other Withdrawals\"\n\n@additions = get multi page table @additionstart @additionend 140 190 440 490 600 => describe table false \"Date[M/d]\" Details - *#Credit\n@checksleft = get multi page table @checksstart @checksend 140 180 210 270 350 => describe table false ChequeNumber \"Date[M/d]\" Details *#Debit\n@checksright = get multi page table @checksstart @checksend 390 430 460 510 590 => describe table false ChequeNumber \"Date[M/d]\" Details *#Debit\n@payments = get multi page table @paymentstart @paymentend 140 190 440 490 600 => describe table false \"Date[M/d]\" Details - *#Debit\n@purchases = get multi page table @purchasestart @purchaseend 140 190 440 490 600 => describe table false \"Date[M/d]\" Details - *#Debit\n@others = get multi page table @otherstart @otherend 140 190 440 490 600 => describe table false \"Date[M/d]\" Details - *#Debit\n$transactions = combine described tables @additions @checksleft @checksright @payments @purchases @others \n\n','2021-04-05 05:46:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10144,'StarlingBank','$source = \"StarlingBank\"\n\ndelete rotated words\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get account name\n$accountname = get line containing \"Account Name:\" => get words before \"Account Name:\" => get text\n\n// Get Period\n@periodtext = get line containing \"END OF DAY\" => top => get line above\n$periodfrom = get words before @periodtext \"-\" => take words 1 => get date \"dd/MM/yyyy\"\n//$periodto = get words after @periodtext \"-\" => take words 1 => get date \"dd/MM/yyyy\"\n@lastperiodtext = get last line containing \"END OF DAY\" => top => get line above\n$periodto = get words after @lastperiodtext \"-\" => take words 1 => get date \"dd/MM/yyyy\"\n\n// Get Opening balance\ngo to page 1\n$openingbalance = get line starting \"OPENING BALANCE\" => take last words 1 => get decimal\n\n// get table start and end\n@transactionstop = get line starting \"OPENING BALANCE\" => if not found then blank => bottom => get line below\n//@transactionsbottom = get line containing \"Date range applicable\" => top => get line above\n//@transactionsbottom = get last line containing \"Date range applicable\" => top => get line above\n@lastbottom = get last line containing \"Date range applicable:\"\n@transactionsbottom = get line containing \"We charge interest\" => top => get line above\n\n// delete headers and footers\ngo to page 1\n//@vartopLine = get line starting \"Your deposit is eligible\" => if not found then blank => top => get line below => get text\n\n//@vartopLineAcc = get line containing \"Account Number:\" => if not found then blank => top => get line below => get text\n//delete all lines containing \"@vartopLineAcc\"\n\n\n