et line below => bottom\ndelete text in box $deldatetop1 $deldatebottom1 page.left page.right\n\n$deldatetop2 = get line containing \"Account Name:\" => top\n$deldatebottom2 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop2 $deldatebottom2 page.left page.right\n\n$deldatetop3 = get line containing \"Account Name:\" => top\n$deldatebottom3 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop3 $deldatebottom3 page.left page.right\n\n$deldatetop4 = get line containing \"Account Name:\" => top\n$deldatebottom4 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop4 $deldatebottom4 page.left page.right\n\n$deldatetop5 = get line containing \"Account Name:\" => top\n$deldatebottom5 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop5 $deldatebottom5 page.left page.right\n\n$deldatetop6 = get line containing \"Account Name:\" => top\n$deldatebottom6 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop6 $deldatebottom6 page.left page.right\n\n$deldatetop7 = get line containing \"Account Name:\" => top\n$deldatebottom7 = get line containing \"END OF DAY\" => if not found then blank => bottom => get line below => bottom\ndelete text in box $deldatetop7 $deldatebottom7 page.left page.right\n\n\ndelete all lines containing \"Account Number:\"\ndelete all lines containing \"Account Name:\"\n\ndelete all lines starting \"Interest will be payable\"\ndelete all lines containing \"We charge interest each\"\n//delete all lines containing \"@vartopLine\"\n\ndelete all lines containing \"Date range applicable\"\ndelete all lines containing \"Interest rate paid on\"\ndelete all lines containing \"on Account Balance\"\ndelete all lines containing \"information about our interest rates\"\ndelete all lines containing \"www.starlingbank.com/legal\"\ndelete all lines starting \"OPENING BALANCE\"\ndelete all lines containing \"Your deposit is eligible\"\ndelete all lines containing \"NN3 9EF\"\ndelete all lines containing \"Your deposit is eligible\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 20 90 181 390 450 510 650 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Credit #Debit #Balance','2023-09-15 05:08:36',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10145,'Natwest_CreditCard_NoSummary','$source = \"Natwest_CreditCard_NoSummary\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR NO_OPENING_BALANCE\"\n\n$periodBufferDays = 10\n\n$accountName = get text in box 760 600 page.left page.middleX => take words 3  => get text\n\n$accountnumber = get last line containing \"Page\" => get words before \"Page\" => get text\n\ngo to page 1\n@period = get line starting \"Post Tran\" => top => get line above\n$periodfrom = get words before @period \"-\" => get date \"dd MMMM\"\n$periodto = get words after @period \"-\" => take words 3 => get date \"dd MMMM yyyy\"\n\n$closingbalance = get line starting \"TOTAL ACTIVITY\" => take last words 1 => get decimal\n$openingbalance = 0\n\ngo to page 1\n@transactiontop = get line starting \"Date Date Reference\" => bottom => get line below\n@transactionbottom = get last line starting \"TOTAL ACTIVITY\" => top => get line above\n\n//get line containing \"Saturday: 09.00 - 13.00\" => bottom => ignore header above\nget line containing \"Monday - Friday:\" => bottom => ignore header above\ndelete all lines containing \"Saturday:\"\ndelete all lines starting \"TOTAL ACTIVITY\"\ndelete all lines starting \"Date Date Reference\"\ndelete all lines starting \"Post Tran\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"onecard\"\n\n// Read the transactions\n//$transactions  = get multi page table @transactiontop @transactionbottom 50 120 160 230 300 510 580 => describe table false \"Date[dd MMM]\" - - - Details *#Credit\n$transactions  = get multi page table @transactiontop @transactionbottom 50 120 160 510 580 => describe table false \"Date[dd MMM]\" - Details *#Credit','2024-09-10 08:18:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10146,'NABBank','$source = \"NABBank\"\n//$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\nset negative marker \"Dr\"\n\n// Delete vertical text\ndelete rotated words\ndelete white words\ndelete tiny words\n\n// Get balances and periods panel\n@panelBottom = get line containing \"Statement ends\" => bottom\n@panelWords = get text in box page.top @panelBottom 340 570\n\n$openingbalance = get words after @panelWords \"Opening balance\" => get words before \"Total credits\" => get decimal\n$closingbalance = get words after @panelWords \"Closing balance\" => get words before \"Statement starts\" => get decimal\n\n$periodfrom = get words after @panelWords \"Statement starts\" => get words before \"Statement ends\" => get date \"d MMMM yyyy\"\n$periodto = get words after @panelWords \"Statement ends\" => get date \"d MMMM yyyy\"\n\n//$periodfrom = get line containing \"Statement starts\" => take last words 3 => get date \"d MMMM yyyy\"\n\n//$periodto = get line containing \"Statement ends\" => take last words 3 => get date \"d MMMM yyyy\"\n\n$accountnumber = get line starting \"Account number\" => skip words 2 => take words 1 => get text\n\n@accountNameTop = get line containing \"Account Details\" => bottom\n//@accountNameBottom = get line containing \"BSB number\" => top\n@accountNameBottom = get line containing \"BSB\" => top\n$accountname = get text in box @accountNameTop @accountNameBottom 300 page.right => get text\n\n@accountNameBottomDlt1 = get line containing \"BSB\" => top => get line above => top\n@accountnameDel1 = get text in box @accountNameTop @accountNameBottomDlt 300 page.right => take words 3 => get text\n@accountnameDel2 = get text in box @accountNameBottomDlt1 @accountNameBottom 300 page.right => take words 3 => get text\n\ndelete all lines starting @accountnameDel1\ndelete all lines starting @accountnameDel2\n\n//@accountTop = get line containing \"Account Details\" => top\n//@accountBottom = get line containing \"BSB number\" => bottom\n//delete text in box @accountTop @accountBottom 300 page.right => get text\n\n//$openingbalance = get line containing \"Total credits\" => top => get line above => take last words 2 => get decimal\n\n//$closingbalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Date Particulars Debits\" => bottom => get line below\n@transactionsBottom = get last line containing \"Summary of Government Charges\" => top => get line above\n\n//go to page 1\n//@headerbottom = get last line containing \"Transaction Details (continued)\" => top\n//@headertop = get last line containing \"Account Details\" => bottom\n//delete text in box @headertop @headerbottom page.left page.right\n\n//delete non-transactional blocks from transactions one after another\ngo to page 1\n@TRANSACTIONSUMMARYTop0 = get line containing \"TRANSACTION SUMMARY QUANTITY\" => top\n@TotalFeesChargedBottom0 = get line containing \"Total Fees\" => bottom\ndelete text in box @TRANSACTIONSUMMARYTop0 @TotalFeesChargedBottom0 100 page.right\n\n@TRANSACTIONSUMMARYTop1 = get line containing \"TRANSACTION SUMMARY QUANTITY\" => top\n@TotalFeesChargedBottom1 = get line containing \"Total Fees\" => bottom\ndelete text in box @TRANSACTIONSUMMARYTop1 @TotalFeesChargedBottom1 100 page.right\n\n@TRANSACTIONSUMMARYTop2 = get line containing \"TRANSACTION SUMMARY QUANTITY\" => top\n@TotalFeesChargedBottom2 = get line containing \"Total Fees\" => bottom\ndelete text in box @TRANSACTIONSUMMARYTop2 @TotalFeesChargedBottom2 100 page.right\n\n@TRANSACTIONSUMMARYTop3 = get line containing \"TRANSACTION SUMMARY QUANTITY\" => top\n@TotalFeesChargedBottom3 = get line containing \"Total Fees\" => bottom\ndelete text in box @TRANSACTIONSUMMARYTop3 @TotalFeesChargedBottom3 100 page.right\n\ngo to page 1\ndelete all lines containing \"continued\"\ndelete all lines containing \"Statement number\"\ndelete all lines containing \"NAB Classic Banking\"\ndelete all lines containing \"Account Details\"\ndelete all lines containing $accountname\ndelete all lines containing \"Date Particulars Debits\"\ndelete all lines containing \"Brought forward\"\ndelete all lines containing \"Carried forward\"\n\ndelete all lines containing \"Identifying a transaction made\"\ndelete all lines containing \"select the CREDIT button\"\ndelete all lines containing \"phone, the Particulars\"\ndelete all lines containing \"followed by the last\"\ndelete all lines containing \"which you initiated\"\ndelete all lines containing \"NAB Business\"\ndelete all lines containing \"BSB Number\"\n\ndelete all lines containing \"Banker Assisted\"\ndelete all lines containing \"Transaction Fees\"\ndelete all lines containing \"Account Service Fee\"\ndelete all lines containing \"Total Fees\"\ndelete all lines containing \"Less Fee\"\n\ndelete all lines containing \"TRANSACTION SUMMARY QUANTITY\"\ndelete all lines starting \"Electronic Deposit\"\ndelete all lines starting \"Electronic Withdrawal\"\ndelete all lines starting \"Flat Monthly Fee\"\ndelete all lines starting \"Less Free\"\n\n// Discard page footer\nignore footer below 37\n\ngo to page 1\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 100 350 400 470 => describe table false \"Date[d MMM yyyy]\" Details **#Debit **#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 100 380 346 400 470 570 => describe table false \"Date[d MMM yyyy]\" Details - **#Debit **#Credit #Balance','2023-11-07 06:03:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10147,'TDCanadaTrust_French','$source = \"TDCanadaTrust_French\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Delete vertical text\ndelete rotated words\ndelete white words\ndelete tiny words\n\nset negative marker \"DC\"\n// Parse dates in Dutch\nset culture \"nl-BE\"\n\n// Get account number\n$accountNumber = get text in box 515 500 110 200 => get text\n\n\n// Get period from/to\n@period = get text in box 540 520 400 550\n$periodFrom = take words @period 3 => get date \"dd MMM yy\"\n$periodTo = take last words @period 3 => get date \"dd MMM yy\"\n\n// Parse dates in French\n//set culture \"fr-CA\"\n\n// Get opening balance\n@balanceBroughtForwardLine = get line \"DESCRIPTION RETRAITS DEPOTS DATE SOLDE\" => bottom => get line below\n//@openingBalanceWords = take last words @balanceBroughtForwardLine 1\n//$openingBalanceText = get text @openingBalanceWords\n//$balanceBroughtForward = get decimal @openingBalanceWords\n//$openingBalance = get decimal @openingBalanceWords\n\n@openingtop = get line starting \"SOLDE REPORTE\" => top\n@openingbottom = get line starting \"SOLDE REPORTE\" => bottom\n$openingBalance = get text in box @openingtop @openingbottom 435 560 => get decimal\n\n// Get account name\ngo to page 1\n$accountName = get line starting \"TDCDA\" => bottom => get line below => get text\n\n// Get start of table\n@transactionsTop = bottom @balanceBroughtForwardLine => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"No.\" => top => get line above\n//@closingBalanceWords = take last words @transactionsBottom 1\n//$closingBalanceText = get text @closingBalanceWords\n//$closingBalance = get decimal @closingBalanceWords\n\n@closingtop = get last line containing \"No.\" => top => get line above => top\n@closingbottom = get last line containing \"No.\" => top\n$closingBalance = get text in box @closingtop @closingbottom 435 560 => get decimal\n\n// Discard page header\nbottom @balanceBroughtForwardLine => ignore header above\n\n// Discard page footer\n//get line ending \"No.\" => top => ignore footer below\nignore footer below 185\n\n\ndelete all lines starting \"SOLDE REPORTE\"\ndelete all lines containing \"No. Montant\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 190 300 400 435 560 => describe table false Details #Debit #Credit \"*Date[MMMdd]\" #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 190 300 400 435 560 => describe table false Details #Debit #Credit \"*Date[ddMMM]\" #Balance','2023-04-07 08:38:02',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10148,'RBSNatWestUlster_ReverseTransactions','$source = \"RBSNatWestUlster_ReverseTransactions\"\r\n$features = \"REVERSE_ORDER\"\r\n\r\n// Discard hidden text\r\ndelete white words\r\ndelete tiny words\r\ndelete rotated words\r\n\r\n// Get statement period from and to\r\n//@statementPeriod = get line starting \"Transactions from\" => get words after \"Transactions from\" => take words 3\r\n//$periodFrom = take words @statementPeriod 1 => get date \"dd-MMM-yyyy\"\r\n//$periodTo = take last words @statementPeriod 1 => get date \"dd-MMM-yyyy\"\r\n\r\n@statementPeriod = get line starting \"Transactions from\" => get words after \"Transactions from\"\r\n$periodFrom = get words before @statementPeriod \"to\" => get date \"ddMMMyyyy\"\r\n$periodTo = get words after @statementPeriod \"to\" => get date \"ddMMMyyyy\"\r\n\r\n// Get account name and number\r\n@accountDetails = get line starting \"Account name\" => bottom => get line below\r\n$accountName = take words @accountDetails 3 => get text\r\n//@accountNumber = take last words @accountDetails 3\r\n//$accountNumber = take words @accountNumber 1 => get text\r\n\r\n@acctop = get line starting \"Account name\" => bottom => get line below => top\r\n@accleft = get line starting \"Account name\" => get words before \"number\" => take last words 1 => left => subtract 5\r\n@accright = get line starting \"Account name\" => get words after \"number\" => take words 1 => left => subtract 5\r\n@accbottom = get line containing \"Current cleared\" => top => get line above => bottom\r\n$accountNumber = get text in box @acctop @accbottom @accleft @accright => get text\r\n\r\n// Get opening and closing balances\r\n$openingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\r\n$closingBalance = get last line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\r\n\r\ngo to page 1\r\n@Header = get line starting \"Date Type Transaction details Debit Credit Balance\"\r\n@DateLeft = take words @Header 1 => left => subtract 5\r\n@TypeLeft = get words after @Header \"Date\" => take words 1 => left => subtract 2\r\n@DescLeft = get words after @Header \"Type\" => take words 1 => left => subtract 2\r\n\r\n@Desc = get line starting \"Closing balance\"\r\n@DescRight = get words after @Desc \"Closing\" => take words 1 => right => add 5\r\n@DebitLeft = get words after @Desc \"Closing\" => take words 1 => right => subtract 1\r\n\r\n@CreditRight = get words after @Header \"Credit\" => take words 1 => left => subtract 2\r\n@BalanceLeft = get words after @Header \"Debit\" => take words 1 => right => add 2\r\n@BalanceRight = get words after @Header \"Credit\" => take words 1 => right => add 50\r\n\r\n//set negative marker \"-\"\r\n\r\ngo to page 1\r\n@unclearedbottom = get line starting \"Closing balance\" => top\r\ndelete text in box page.top @unclearedbottom page.left page.right\r\n\r\ngo to page 1\r\n// Get start of table\r\n//@transactionsTop = get line starting \"Date Type Transaction details Debit Credit Balance\" => bottom => get line below\r\n@transactionsTop = get line starting \"Closing balance\" => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Opening balance\" => top => get line above\r\n\r\ndelete all lines containing \"Closing balance\"\r\ndelete all lines containing \"Page\"\r\ndelete all lines containing \"Transactions from\"\r\ndelete all lines containing \"Date Type Transaction\"\r\ndelete all lines containing \"Opening balance\"\r\ndelete all lines starting \"Totals\"\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 105 140 330 395 460 560 => describe table false \"Date[dd-MMM-yyyy]\" TransactionType Details #Debit #Credit *#Balance\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 105 140 328 395 460 560 => describe table false \"Date[dd-MMM-yyyy]\" TransactionType Details #Debit #Credit *#Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @TypeLeft @DescLeft @DescRight @DebitLeft @CreditRight @BalanceLeft @BalanceRight => describe table false \"Date[dd-MMM-yyyy]\" TransactionType Details - #Credit - *#Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10149,'WindWard_Iceland_Bank','$source = \"WindWard_Iceland_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT#\" => get words after \"ACCOUNT#\" => get text\n\n// Get account name\n$accountName = get line containing \"Statement of Your\" => top => get line above => top => get line above => get text\n\n//Get Period\n@TEXTBOXTop = get line containing \"Statement Period\" => top\n@TEXTBOXBottom = get line containing \"Statement Period\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 300 540\n\n// Get Period To\n$periodTo = get words after @TEXTBOX \"Statement Period\" => take words 3 => get date \"MMMMM dd yyyy\"\n\n// Delete extra headers and footers\ngo to page 1\n@tableHeader = get line starting \"Page\" => top => get line above  => top\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n// Parse amounts in netherlands\nset culture \"nl-NL\"\ngo to page 1\n\n// Get Opening balance\n$openingBalance = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\" => get decimal\n\n//Get Period From\n$periodFrom = get line containing \"PREVIOUS BALANCE\" => get words before \"PREVIOUS BALANCE\" => get date \"dd/MM\"\n\n// Get table start and end\n//transaction header for ref - DATE DEBIT AMOUNT CREDIT AMOUNT REF. DESCRIPTION BALANCE D/M (Withdrawal) (Deposit)\n@transactionstop = get line containing \"PREVIOUS BALANCE\" => bottom => get line below\n@DateLeft = get line containing \"DATE DEBIT AMOUNT\" => get words before \"DEBIT AMOUNT\" => left\n@DateLeft = subtract @DateLeft 3\n@DateRight = get line starting \"DATE DEBIT AMOUNT\" => get words before \"DEBIT AMOUNT\" => take words 1 => right\n@DateRight = add @DateRight 10\n@TypeRight = get line starting \"DATE DEBIT AMOUNT\" => get words before \"DESCRIPTION\"  => take last words 1 => right\n@TypeRight = add @TypeRight 15\n@DetailsRight = get line starting \"DATE DEBIT AMOUNT\" => get words before \"CREDIT AMOUNT\" => take last words 2 => left\n@DetailsRight = subtract @DetailsRight 5\n@DebitRight = get line starting \"DATE DEBIT AMOUNT\" => get words before \"CREDIT AMOUNT\" => take last words 2 => right\n@DebitRight = add @DebitRight 10\n@CreditRight = get line starting \"DATE DEBIT AMOUNT\" => get words before \"REF. DESCRIPTION\" => take last words 2 => right\n@CreditRight = add @CreditRight 10\n@BalanceRight = get line starting \"DATE DEBIT AMOUNT\" => get words after \"DESCRIPTION\" => take words 1 => right\n@BalanceRight = add @BalanceRight 30\n@transactionsbottom = get last line containing \"TOTAL DEBITS/CREDITS\" => top => get line above\n\n// Get closing Balance\n$closingBalance = take last words @transactionsbottom 1 => get decimal\n\ngo to page 1\ndelete all lines containing \"Page\"\ndelete all lines containing \"Statement Period\"\ndelete all lines containing \"DATE DEBIT AMOUNT CREDIT AMOUNT\"\ndelete all lines containing \"PREVIOUS BALANCE\"\ndelete all lines containing \"Please examine this statement promptly\"\ndelete all lines containing \"within 30 days\"\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom @DateLeft @DateRight @TypeRight @DetailsRight @DebitRight @CreditRight @BalanceRight => describe table false \"Date[dd/MM]\" TransactionType Details #Debit #Credit *#Balance','2025-04-15 05:12:36',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10150,'AIB_VISA_CARD','$source = \"AIB_VISA_CARD\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 58\nset negative marker \"CR\"\n\n//Get Account details\n$accountname   = get line containing \"Visa Card\" => top => get line below => top => get line below => get text   \n\n//Get Period\ngo to page 1\n$periodTo = get line containing \"Account Statement\" => get words after \"Account Statement -\" => get date \"d MMMM, yyyy\"\n@periodFromtext = get line containing \"Transaction Posting\" => bottom => get line below => bottom => get line below\n$periodFrom = take words  @periodFromtext 6 =>  get words after \"Purchases\" => get date \"d MMM\"\n\n//Get Opening & Closing balance\ngo to page 2\n$accountNumber = get line containing \"Card Number\" => top => get line below  =>  get text  \n$openingbalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => get decimal\n$closingbalance = get line containing \"New Balance\" => get words after \"New Balance\" =>  get decimal\n\ngo to page 1\n@transactionstop = get line containing \"Transaction\" => bottom  => get line below => bottom  => get line below\n@transactionsbottom = get last line containing \"If you do not pay your balance in full we will allocate your payments\" => top => get line above\n\n$transactions = get multi page table @transactionstop @transactionsbottom 15 80 110 370 450  => describe table false TransactionDate \"Date[d MMM]\" Details *#Credit ','2021-06-09 08:14:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10151,'HSBC_MasterCard',' $source = \"HSBC_MasterCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\n//$accountname = get line containing \"Statement of Your\" => top => get line above => top => get line above => get text\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\n@periodtext = get line containing \"Billing Date\" => get words after \"Billing Date\"\n$periodTo = take words @periodtext 3 =>  get date \"MMMM d yyyy\"\n\n$periodFrom = take words @periodtext 3 =>  get date \"MMMM d yyyy\"\n\n$closingbalance = get line containing \"Total Balance in Use\" =>  get words after \"Total Balance in Use\" => get text\n@openingbalancetext = get line containing \"Previous Balance\" => get words after \"Previous Balance\"\n$openingbalance = take words  @openingbalancetext 1 =>  get text\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Date Brand Number\" => top => get line below\n\n// Delete extra lines\ngo to page 1\ndelete all lines containing \"page\"\n\n// Get end of table\ngo to last page\n@transactionsBottom = get last line containing \"TOTAL\" => top => get line above\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 55 85 230 450 600  => describe table false \"TranDate[MM/dd]\" \"Date[MM/dd]\" TransactionType Details *#Credit ','2021-06-09 08:15:30',0);
