INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10161,'CommonWealthBankCreditCard','$source = \"CommonWealthBankCreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n$deleteleftpanel = delete text in box on every page page.top page.bottom 0 40 => get text\ndelete all lines containing \"Origin Krs Design Energy Dapto Holdin Adelaide\"\n//delete all lines containing \"NetBank\"\n//delete all lines containing \"CommBank app\"\n//delete all lines containing \"commbank.com.au\"\n//delete all lines containing \"Statement Date\"\n//delete all lines containing \"Biller code\"\n//delete all lines containing \"pay via BPAY\"\n\n//go to page 1\n//$accountname = get text in box 705 685 page.left page.middleX => take words 4 => get text\n//@var = get last line containing \"Credit Card\" => bottom => get line below => get text\n//$accountNumber = get line starting \"Transactions\" => bottom => get line below => get words after \"Account\" => get text\n//delete all lines containing @var\n\n//go to page 1\n//@openingbalanceText = get line containing \"Opening balance at\" => get words after \"Opening balance at\" =>  skip words 2\n//$openingbalance = take words @openingbalanceText 1 => get decimal\n//@closingbalanceText = get line containing \"Closing balance at\" => get words after \"Closing balance at\"  => skip words 2\n//$closingbalance = take words @closingbalanceText 1 => get decimal\n\n//go to page 1\n//$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => get words between \"Statement Period\" \"-\" => get date \"d MMM yyyy\"\n//$periodTo = get line containing \"Statement Period\" => get words after \"-\" => get date \"d MMM yyyy\"\n//@vardate = get line containing \"Statement Period\" => get words after \"-\" => get text\n\ngo to page 1\n$accountname = get text in box 705 685 page.left page.middleX => take words 4 => get text\n\n@OpenbalTop = get line containing \"Opening balance\" => top\n@OpenbalBottom = get line containing \"Opening balance\" => bottom\n@OpenBalbox = get text in box @OpenbalTop @OpenbalBottom page.left page.middleX\n\n$openingBalance = get words after @OpenBalbox \"Opening balance\" => get words after \"Opening balance\" => take last words 1 => get decimal\n\n@ClosebalTop = get line containing \"Closing balance\" => top\n@ClosebalBottom = get line containing \"Closing balance\" => bottom\n@CloseBalbox = get text in box @ClosebalTop @ClosebalBottom page.left page.middleX\n\n$ClosingBalance = get words after @CloseBalbox \"Closing balance\" => get words after \"Closing balance\" => take last words 1 => get decimal\n\n@Date_right = get line containing \"Date Transaction\" => get words after \"Date\" => take words 1 => left\n@Date_right = subtract @Date_right 5\n\ngo to page 2\n$accountNumber = get line starting \"Transactions\" => bottom => get line below => get words after \"Account\" => get text\n@periodTxt = get line starting \"Transactions\" => bottom => get line below => bottom => get line below\n$periodFrom = take words @periodTxt 3 => get date \"d MMM yyyy\"\n$periodTo = take last words @periodTxt 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n@transactionsTop = get line containing \"Date Transaction\" => top => get line below\n@transactionsBottom = get line containing \"Please check your transactions listed on this statement\" => bottom => get line above\n\ngo to page 1\n@footTop = get line starting \"How to pay\" => top\n$delfoter = delete text in box @footTop 0 0 page.right => get text\n\nget line containing \"Page\" => top => ignore header above\n\ndelete all lines containing \"Please check your transactions listed on this statement\"\n//delete all lines containing \"Account\"\ndelete all lines containing \"Transactions\"\n//delete all lines containing @vardate\n//delete all lines containing \"How to pay\"\ndelete all lines containing \"here to help\"\ndelete all lines containing \"Date Transaction details\"\ndelete all lines containing \"Date Transaction Details\"\n\ndelete all lines containing \"Expense codes\"\ndelete all lines containing \"Transactions continued\"\ndelete all lines containing \"# Transaction shown\"\ndelete all lines containing \"IMPORTANT GST INFORMATION\"\ndelete all lines containing \"You will need to obtain a tax invoice\"\ndelete all lines starting \"Page\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 45 91 500 600 => describe table false \"Date[dd MMM]\" Details *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 @Date_right 500 600 => describe table false \"Date[dd MMM]\" Details *#Credit','2025-05-29 06:48:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10162,'HSBC_Card_Canada','$source = \"HSBC_Card_Canada\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\n\n$accountname = get line containing \"PFDPHSBC\" => get words after \"Payment\" => skip words 2 => get text\ngo to page 1\n$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\n$openingbalance = get last line containing \"Previous Balance\" => get words after \"Previous Balance\" => get words before \"Account Number\" => get decimal\n$closingbalance = get line containing \"New Balance\" => get words after \"New Balance\" => get words before \"Payment Due\" => get decimal\n\n\n@periodText = get line containing \"Statement Period\" => get words after \"Statement Period\"  \n$periodto = take words @periodText 1 => get date \"MM dd yyyy\"\n$periodfrom = take last words @periodText 1 => get date \"MM dd yyyy\"\n\n\n@transactionsTop = get line starting \"Tran Date Post Date Reference Number\" => bottom => get line below\n@transactionsBottom = get last line containing \"The HSBC Commercial MasterCard Card is a business purposes only account issued by HSBC Bank Canada\" => top => get line above \n\ndelete all lines starting \"Tran Date Post Date Reference Number\"\ndelete all lines starting \"(Continued on next page)\"\ndelete all lines starting \" FINANCE CHARGE RATES SUMMARY QUESTIONS\"\ndelete all lines starting \" Periodic Rate\"\ndelete all lines starting \"Toll Free\"\ndelete all lines starting \"Annual Percentage Rate\"\ndelete all lines starting \"Outside Canada/U.S.\"\ndelete all lines starting \"Correspondence\"\ndelete all lines starting \"Account Number:\"\ndelete all lines starting \"Suite\"\ndelete all lines starting \"Toronto\"\ndelete all lines starting \"Canada\"\ndelete all lines starting \"P O BOX\"\ndelete all lines starting \"Payments HSBC Bank Canada\"\n\n\n\n$transactions = get multi page t