INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10163,'HSBC_Corporate_Card','$source = \"HSBC_Corporate_Card\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\n\nset negative marker \"CR\"\n\n@Summarytop = get line containing \"Previous Balance\" => top\n@Summarybottom = get line containing \"Received By Us\" => top\n@Summary = get text in box @Summarytop @Summarybottom page.middleX 600\n\n$accountname = get text in box 740 @Summarytop 0 page.middleX => take words 2 => get text\n$accountNumber = get words after @Summary \"Card Number\" => get text\n\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Debits\" => get decimal\n$closingBalance = get words after @Summary \"New Balance\" => get words between \"New Balance\" \"Card Number\" => get decimal\n\n$periodTo = get text in box @Summarytop @Summarybottom 0 page.middleX  => get words after \"Statement Date\" => take words 3 => get date \"dd MMM yyyy\"\n@periodfromText = get line containing \"Received By Us Transaction Date\" => bottom => get line below\n@periodfrom1 = take words @periodfromText 6\n$periodfrom = take last words @periodfrom1 3 => get date \"dd MMM yyyy\"\n\n@transactionsTop = get line starting \"Received By Us Transaction Date\" => bottom => get line below\n@transactionsBottom = get last line containing \"THIS STATEMENT IS FOR INFORMATION PURPOSES ONLY. PLEASE RETAIN\" => top => get line above\n\ndelete all lines starting \"Received By Us Transaction Date\"\ndelete all lines starting \"THIS STATEMENT IS FOR INFORMATION PURPOSES ONLY. PLEASE RETAIN\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 180 500 570 => describe table false \"Date[dd MMM yyyy]\" \"TransactionDate[dd MMM yyyy]\" Details *#Credit','2025-07-24 06:51:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10164,'Citi_Bank_UK','$source = \"Citi_Bank_UK\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\nset negative marker \"DR\"\n\ndelete all lines containing \"Page\"\n\ngo to page 1\n$accountname = get line containing \"Relationship report for\" => get words after \"Relationship report for\" => get text\n$accountNumber = get last line containing \"STERLING CURRENT ACCOUNT\" => get words between \"STERLING CURRENT ACCOUNT\" \"GBP\" => get text\n\ngo to page 1\n$periodFrom = get line containing \"Statement Period\" => get words between \"Statement Period\" \"-\" => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"Statement Period\" => get words after \"-\" => get date \"dd/MM/yyyy\"\n\n\ngo to page 1\n$openingbalance = get line containing \"Date Description Withdrawals\" =>  bottom => get line below => get words after \"OPENING BALANCE\" => get decimal\n$closingbalance = get line containing \"TOTAL\" => top => get line above => get words after \"CLOSING BALANCE\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Description Withdrawals\" =>  bottom => get line below => bottom => get line below \n//@transactionsBottom = get line containing \"US DOLLAR CURRENT ACCOUNT\" => top => get line above => top => get line above => top => get line above \n@transactionsBottom = get line containing \"TOTAL\" => top => get line above => top => get line above \n\n\n\ndelete all lines containing \"Current Accounts\"\ndelete all lines containing \"continued from previous\"\ndelete all lines containing \"Transactions\"\n\n\n\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 90 300 400 480 600 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit #Balance\n\n','2022-01-18 13:30:43',1);
