INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10166,'TCF_Bank','$source = \"TCF_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\ngo to page 1\n@accountnameBottom = get line containing \"ACCOUNT NUMBER\" => top\n@accountnameText = get text in box 620 @accountnameBottom page.left page.right\n$accountname = take words @accountnameText 2 => get text\n\ngo to page 1\n$accountnumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => get text\n\ngo to page 1\n$periodfrom = get line containing \"STATEMENT PERIOD\" => get words between \"STATEMENT PERIOD\" \"THROUGH\" => get date \"MM-dd-yy\"\n$periodto = get line containing \"STATEMENT PERIOD\" => get words after \"THROUGH\" => get date \"MM-dd-yy\"\n\ngo to page 1\n@openingbalanceText = get line containing \"CHECKS/WITHDRAWALS DEPOSITS/ADDITIONS\" => bottom => get line below => bottom => get line below\n$openingbalance = take words @openingbalanceText 1 => get decimal\n$closingbalance = take last words @openingbalanceText 1 => get decimal\n\nignore header above 550\n\ngo to page 1\n@transactionsTopCheque = get line containing \"CHECKS PAID\" => bottom => get line below\n@transactionsBottomCheque = get line containing \"OTHER WITHDRAWALS AND CHARGES\" => bottom => get line above\n\ngo to page 1\n@TransactionsChequeLeft = get multi page table @transactionsTopCheque @transactionsBottomCheque 20 58 130 158 197 => describe table false ChequeNumber *#Debit \"Date[MMdd]\" TransactionType\ngo to page 1\n@TransactionsChequeMiddle = get multi page table @transactionsTopCheque @transactionsBottomCheque 206 243 312 340 380 => describe table false ChequeNumber *#Debit \"Date[MMdd]\" TransactionType\ngo to page 1\n@TransactionsChequeRight = get multi page table @transactionsTopCheque @transactionsBottomCheque 388 425 495 524 570 => describe table false ChequeNumber *#Debit \"Date[MMdd]\" TransactionType\n\ngo to page 1\n@transactionsTopDebit = get line containing \"OTHER WITHDRAWALS AND CHARGES\" => bottom => get line below \n@transactionsBottomDebit =  get line containing \"DEPOSITS AND OTHER ADDITIONS\" => top => get line above \n\ngo to page 1\n@TransactionsDebitleft = get multi page table @transactionsTopDebit @transactionsBottomDebit 25 60 125 200 => describe table false \"Date[MMdd]\" *#Debit Details \n\ngo to page 1\n@TransactionsDebitRight = get multi page table @transactionsTopDebit @transactionsBottomDebit 302 340 405 480 => describe table false \"Date[MMdd]\" *#Debit Details\n\ngo to page 1 \n@transactionsTopCredit =  get line containing \"DEPOSITS AND OTHER ADDITIONS\" => top => get line below\n@transactionsBottomCredit = get line containing \"TOTAL OVERDRAFT FEES\" => top => get line above => top => get line above\n\ngo to page 1\n@TransactionsCreditleft = get multi page table @transactionsTopCredit @transactionsBottomCredit 25 60 125 200 => describe table false \"Date[MMdd]\" *#Credit Details \n\ngo to page 1\n@TransactionsCreditRight = get multi page table @transactionsTopCredit @transactionsBottomCredit 302 340 405 480 => describe table false \"Date[MMdd]\" *#Credit Details\n\n$transactions = combine described tables @TransactionsChequeLeft @TransactionsChequeMiddle @TransactionsChequeRight @TransactionsDebitleft @TransactionsDebitRight @TransactionsCreditleft @TransactionsCreditRight\n','2021-07-06 08:01:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10167,'Scotia_Bank_Credit_Card','$source = \"Scotia_Bank_Credit_Card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 14\n\nset negative marker \"CR\"\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\ngo to page 1\n//$periodfrom = get line containing \"Statement Period\" => get words between \"Statement Period\" \"-\" => get date \"MMM dd, yyyy\"\n//$periodto = get line containing \"Statement Period\" => get words after \"-\" => get date \"MMM dd, yyyy\"\n\n$periodfrom = get line containing \"Statement Period\" => get words between \"Statement Period\" \"-\" => get date \"MMM d, yyyy\"\n$periodto = get line containing \"Statement Period\" => get words after \"-\" => get date \"MMM d, yyyy\"\n\n$accountnumber = get line containing \"Account #\" => get words after \"Account #\" => get text\ndelete all lines containing \"SBVGED\"\n@top = get line starting \"Borrowers on this account;\" => top\n@bottom = get line starting \"Borrowers on this account;\" => bottom\ndelete text in box @top @bottom page.left page.middleX\n\ngo to page 1\n@accountnameTextTop = get line containing \"This statement covers transactions posted to your account during the Statement Period\" => top\n@accountnametext = get text in box 635 @accountnameTextTop 30 190\n$accountname = take words @accountnametext 2 => get text\n\n// deleted left side summary to grab balances from right side panel\n@openingbalanceLeft = get line containing \"Previous balance\" => get words before \"balance\" => take last words 1 => left => subtract 10\n@SummaryBottom = get line containing \"DATE DATE DETAILS AMOUNT($)\" => top\ndelete text in box page.top @SummaryBottom 0 @openingbalanceLeft\n\ngo to page 1\n@openingbalanceText = get line containing \"Previous balance\" => get words after \"Previous balance\"\n$openingbalance = take last words @openingbalanceText 1 => get decimal\n\n//$closingbalance = get line containing \"New balance\" => get words after \"New balance\" => get decimal\n//$closingbalance = get line containing \"New balance\" => get words after \"New balance\" => take last words 1 => get decimal\n//$closingbalance = get line containing \"New balance\" => get words after \"New balance =\" => take words 1 => get decimal\n//$closingbalance = get line containing \"New balance\" => get words after \"New balance =\" => get decimal\n$closingbalance = get line containing \"New\" => get words after \"alance =\" => get decimal\n\ndelete text in box on every page page.top page.bottom 370 600\n\ngo to page 1\n@AccountTop = get line containing \"DATE DATE DETAILS AMOUNT($)\" => bottom => get line below\n\n$DateRight = get line containing \"DATE DATE DETAILS AMOUNT($)\" => get words after \"DATE DATE\" => take words 1 => left => subtract 5\n\n@AccountBottom = get last line containing \"SUB-TOTAL CREDITS\" => top => get line above\n\ngo to page 1\n//@InterestBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD:\" => if not found then blank => top => get line above\n//@InterestTop = get line containing \"Cash advances/cheques\"\n//@InterestBottom = get line containing \"Cash advances/cheques\" => bottom => get break below => get line at\n\n@InterestTop = get line containing \"Cash advances/cheques\"\n@InterestBottom = get line starting \"Special rate offers\" => bottom => get line below\n\n\ndelete all lines containing \"SUB-TOTAL CREDITS\"\ndelete all lines containing \"SUB-TOTAL DEBITS\"\ndelete all lines containing \"page\"\ndelete all lines containing \"SUB-TOTAL\"\ndelete all lines starting \"Transactions since\"\ndelete all lines starting \"Transactions\"\ndelete all lines ending $accountnumber\ndelete all lines containing \"REF.# DATE DATE DETAILS\"\ndelete all lines containing \"TRANS. POST\"\ndelete all lines starting \"MRS\"\ndelete all lines starting \"MR\"\ndelete all lines starting \"MS \"\ndelete all lines containing \"As per your instruction,\"\ndelete all lines containing \"debited from your designated\"\n\ngo to page 1\n@Interestchargespostedtop = get line containing \"Interest charges posted on statement date\" => top\n$Dlt = delete text in box @Interestchargespostedtop page.bottom 0 page.right => get text\n\ngo to page 1\n//@summaryTop = get line containing \"INFORMATION ABOUT YOUR SCOTIABANK STATEMENT\" => if not found then blank => top\n$summaryTop = get line containing \"INFORMATION ABOUT YOUR SCOTIABANK STATEMENT\" => top\n//delete text in box @summaryTop page.bottom page.left page.right\ndelete text in box $summaryTop page.bottom page.left page.right\nignore header above 660\n\n\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 69\n\ngo to page 1\n@extratext = get line starting \"We have not yet received\" => top\ndelete text in box @extratext page.bottom page.left page.right\n\n//@InterestTransactions = get multi page table @InterestTop @InterestBottom 65 165 215 => describe table false  Details *#Credit\n\n//@inttop = top @InterestTop\n//@intbotoom = bottom @InterestBottom\n//delete text in box @inttop @intbotoom page.left page.right\n\ngo to page 1\n//@AccountTransactions = get multi page table @AccountTop @AccountBottom 80 100 128 152 320 365 => describe table false TransactionType \"TranDate[MMM d]\" \"*Date[MMM d]\" Details *#Credit\n//@AccountTransactions = get multi page table @AccountTop @AccountBottom 70 94 126 151 320 365 => describe table false TransactionType \"*Date[MMM d]\" - Details *#Credit\n//@AccountTransactions = get multi page table @AccountTop @AccountBottom 70 94 127 155 320 365 => describe table false TransactionType - \"*Date[MMM d]\" Details *#Credit\n\n//@AccountTransactions = get multi page table @AccountTop @AccountBottom 70 94 122.5 151 320 365 => describe table false TransactionType - \"*Date[MMM d]\" Details *#Credit\n//@AccountTransactions = get multi page table @AccountTop @AccountBottom 70 94 127 120 155 151.5 320 365 => describe table false TransactionType - - \"*Date[MMM d]\" - Details *#Credit\n@AccountTransactions = get multi page table @AccountTop @AccountBottom 70 94 127 120 $DateRight 151.5 320 375 => describe table false TransactionType - - \"*Date[MMM d]\" - Details *#Credit\n\n//$transactions = combine described tables @AccountTransactions @InterestTransactions\n$transactions = combine described tables @AccountTransactions','2025-10-29 06:16:41',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10168,'JPMorgan','$source = \"JPMorgan\"\n\n$periodBufferDays = 114\n// Get account number\n@accountNumbertemp = get line containing \"Account Number:\" => get words after \"Account Number:\" => get words before \"Page\"\n$accountNumber = take words @accountNumbertemp 1 => get text\n// Get account name\n\n$accountname = take words @accountNumbertemp 1 => get text\n\n@openingbalancetemp = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" \n$openingbalance = take last words @openingbalancetemp 1 => get decimal\n\n@closingbalancetemp = get last line containing \"Settled Transactions\" => get words after \"Settled Transactions\" \n$closingbalance = take last words @closingbalancetemp 1 => get decimal\n\n// Get Period\n@periodText = get line containing \"Page\" => get words before \"Page\"\n@periodFinalText = take last words @periodText 6 \n$periodto = take last words @periodFinalText 3 => get date \"dd MMMM yyyy\" \n$periodfrom = take words @periodFinalText 2 => get date \"dd MMMM\"\n\n\ngo to page 1\n@transactionsTop = get line starting \"Booking Date Settlement Date Type Reference Description Credits / Debits Credits / Debits Value in GBP\" => bottom => get line below\n@transactionsBottom = get last line containing \"Settled Transactions\" \n\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"CAPITAL POUND STERLING\"\ndelete all lines containing \"Settled Transactions\"\ndelete all lines containing \"FX Gain/Loss\"\ndelete all lines containing \"FX GAIN/LOSS\"\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 90 145 280 660 730 810 => describe table false \"Date[dd MM yyyy]\" \"SettlementDate[dd MM yyyy]\" TransactionsType Details #Credit *#Amount','2021-07-06 08:06:42',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10169,'Investec_Specialist_Bank','$source = \"Investec_Specialist_Bank\"\r\n\r\n$periodBufferDays = 30\r\n\r\n// Get account details\r\ngo to page 1\r\n\r\n//$accountname = get line containing \"Private Bank Account Statement\" => bottom => get line below => take words 3 => get text\r\n//$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\r\n\r\n$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n$accountname = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\ngo to page 1\r\n\r\n//$periodto = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodfrom = get line containing \"Transaction Description Debit\" => bottom => get line below => bottom => get line below => take words 3 => get date \"d MMM yyyy\"\r\n$periodto = get last line containing \"Closing Balance\" => top => get line above => take words 3 => get date \"d MMM yyyy\"\r\ngo to page 1\r\n\r\n//$openingbalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\r\n//$closingbalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n$openingbalance = get line containing \"Balance brought forward\" => get words after \"Balance brought forward\" => get decimal\r\n$closingbalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@header = get line containing \"Transaction Description Debit\"\r\n@dateleft = take words @header 1 => left => subtract 4\r\n@dateright = skip words @header 2 => take words 1 => left => subtract 3\r\n@descsleft = get words before @header \"Description\" => take last words 1 => left => subtract 3\r\n@debitleft = get words after @header \"Description\" => take words 1 => left => subtract 35\r\n@creditleft = get words after @header \"Description\" => take words 1 => right => add 3\r\n@balanceleft = get words after @header \"Debit\" => take words 1 => right => add 3\r\n@balanceright = get words after @header \"Credit\" => take words 1 => right => add 5\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Transaction Description Debit\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get line containing \"Description Fees Debit\" => top => get line above\r\n\r\n//ignore header above 675\r\n//ignore header above 665\r\ngo to page 1\r\nget last line containing \"Transaction Description Debit\" => bottom => ignore header above\r\n\r\ndelete all lines containing \"Statement Date\"\r\ndelete all lines containing \"Account Number\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines containing \"Online Banking payments, deposits and interest\"\r\ndelete all lines containing \"Online payments, deposits, fees and interest\"\r\ndelete all lines containing \"Closing Balance\"\r\ndelete all lines containing \"Balance brought forward\"\r\ndelete all lines containing \"Transaction Description Debit\"\r\ndelete all lines containing \"Investec Specialist Bank, a division\"\r\ndelete all lines containing \"Investec Private Banking, a division\"\r\ndelete all lines containing \"Ombudsman for Banking Services\"\r\ndelete all lines containing \"Ombudsman\'s details are available\"\r\ndelete all lines containing \"NCRCP9\"\r\ndelete all lines containing \"100 Grayston Drive\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateleft @dateright @descsleft @debitleft @creditleft @balanceleft @balanceright => describe table false \"*Date[d MMM yyyy]\" - Details #Debit #Credit *#Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10170,'RBCBank_US','$source = \"RBCBank_US\"\n$periodBufferDays = 31\n\ndelete rotated words\ndelete white words\ndelete tiny words\ndelete text in box on every page page.top page.bottom page.left 50\n\n// Get account name and number\ngo to page 1\n\n@accountNumbertext = get last line containing \"Account Summary\" => bottom => get line above => get words after \"Checking\"\n$accountNumber = take words @accountNumbertext 1 => get text\n\n//@accountNametext = get line containing \"Account Statement For:\" => bottom => get line below => take words 6\n\n$accountName = get line containing \"Account Statement For:\" => bottom => get line below => bottom => get line below => get text\n\n// Get period from\n$periodFrom = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => get words before \"-\" => get date \"MMMM d, yyyy\"\n\n// Get period to\n$periodto = get line containing \"Statement Period:\" => get words after \"-\" => get date \"MMMM d, yyyy\"\n\n//Get Opening & Closing balance\n@openingbalancetext = get line containing \"Balance Last Statement\" => get words after \"Balance Last Statement\"\n$openingbalance = take last words @openingbalancetext 1 => get decimal\n\n@closingbalancetext = get line containing \"Closing Balance\" => get words after \"Closing Balance\"\n$closingbalance = take last words @closingbalancetext 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Debits Credits Balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Closing Balance\" => bottom => get line above\n\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Page\"\n//delete all lines containing \"Closing Balance\"\n//delete all lines containing \"Transactions\"\n\ndelete all lines containing \"FRBCDS\"\ndelete all lines containing \"(continued)\"\n\ngo to page 1\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 53 110 340 425 505 585 => describe table false \"Date[MM/dd/yyyy]\" Details #Debit #Credit *#Balance\n\n\n','2021-07-06 08:08:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10171,'Co-operative_Bank','$source = \"Co-operative_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\nset negative marker \"OD\"\n\n\ngo to page 1\n@VarText = get text in box 535 260 page.left 154\n$accountname = take words @VarText 15 => get words between \"Account name\" \"Sort code\" => get text\n$accountnumber = take words @VarText 25 => get words between \"Account number\" \"Statement date\" => get text\n$periodto = take words @VarText 25 => get words after \"Statement date\" => take words 3 => get date \"d MMMM yy\"\n\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 154\n\ngo to page 1\n$openingbalance = get line containing \"BROUGHT FORWARD\" => get words after \"BROUGHT FORWARD\" => get decimal\n$closingbalance = get last line containing \"Statement closing balance\" => get words after \"Statement closing balance\" => get decimal\n\ngo to page 1\n$periodfrom = get line containing \"Date Description Moneyout\" => bottom => get line below => take words 2 => get date \"dd MMMM\"\n//@periodTextTop = get line containing \"Date Description Moneyout\" => bottom\n//@periodTextBottom = get last line containing \"Statement closing balance\" => Top\n//@periodtext = get text in box @periodTextTop @periodTextBottom 169 232\n//@periodtext = get text in box @periodTextTop @periodTextBottom 169 232\n//$periodto = take last words @periodtext 2 => get date \"dd MMMM\"\n\n\nignore header above 560\n//ignore footer below 100\nignore footer below 165\ndelete all lines containing \"Abbreviations: S Sub Total\"\ndelete all lines containing \"Details of overdraft charges\"\ndelete all lines containing \"available on request.\"\ndelete all lines containing \"*Please see the reverse of\"\ndelete all lines containing \"Charges for the period\"\ndelete all lines containing \"Debit Interest:\"\ndelete all lines containing \"Date Description Moneyout\"\n\ngo to page 1\n@transactionsTop = get line containing \"BROUGHT FORWARD\" => bottom => get line below\n@transactionsBottom = get last line containing \"Statement closing balance\" => top => get line above\n\ndelete all lines containing \"BROUGHT FORWARD\"\ndelete all lines containing \"Statement closing balance\"\n\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 169 233 350 420 480 560  => describe table false \"*Date[dd MMMM]\" Details #Debit #Credit #Balance','2021-10-14 08:11:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10172,'BankofAmerica_Commercial','$source = \"BankofAmerica_Commercial\"\r\n$periodBufferDays = 14\r\nset negative marker \"DR\"\r\n\r\n$accountname = get line containing \"Currency:\" => bottom => get line below => get words before \"This Statement Date\" => get text\r\n$accountnumber = get line containing \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => get text\r\n\r\ngo to page 1\r\n$openingbalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\r\n$closingbalance = get last line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => get decimal\r\n\r\n@periodToText = get line containing \"This Statement Date:\" => get words after \"This Statement Date:\"\r\n$periodto = take words @periodToText 1 => get date \"ddMMMyy\"\r\n@periodFromText = get line containing \"Statement Type:\" => get words after \"Statement Type:\"\r\n$periodfrom = take words @periodFromText 1 => get date \"ddMMMyy\"\r\n\r\ngo to page 1\r\n@transactionsTop = get line starting \"OPENING BALANCE\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\r\n\r\ngo to page 1\r\nget line starting \"OPENING BALANCE\" => top => ignore header above\r\nget line starting \"TOTAL DEBITS\" => bottom => ignore footer below\r\n\r\ndelete all lines starting \"OPENING BALANCE\"\r\ndelete all lines starting \"CLOSING BALANCE\"\r\ndelete all lines starting \"ENDING BALANCE\"\r\ndelete all lines starting \"TOTAL DEBITS\"\r\ndelete all lines starting \"TOTAL CREDITS\"\r\ndelete all lines starting \"Posted Int Trn Description/Reference\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 86 119 133 392 478 628 => describe table false \"PostedDate[ddMMMyy]\" \"Date[ddMMMyy]\" TransactionType Details *#Credit #Balance','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10173,'Natwest_Interim_Bank','$source = \"Natwest_Interim_Bank\"\n$periodBufferDays = 31\n\ndelete all lines containing \"Page\"\ngo to page 1\n$accountname = get line containing \"Account No.\" => bottom => get line above => get text\n$accountnumber = get line containing \"Account No.\" => get words after \"Account No.\" => get text\n\ngo to page 1 \n$periodfrom = get line containing \"Date Description and relevant calculations\" => bottom => get line above => get words before \"to\" => get date \"dd MMMM yyyy\"\n@periodtoText = get line containing \"Date Description and relevant calculations\" => bottom => get line above => get words after \"to\" \n$periodto = take words @periodtoText 3 => get date \"dd MMMM yyyy\"\n\ngo to page 1\n$openingbalance = get line containing \"Date Description and relevant calculations\" => bottom => get line below => get words after \"Opening Balance\" => get decimal\n@closingbalanceTextBottom = get line containing \"Total Debits, Credits & Closing Balance\" => bottom\n@closingbalanceText = get text in box page.top @closingbalanceTextBottom 574 page.right\n$closingbalance = take last words @closingbalanceText 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Description and relevant calculations\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get line containing \"Total Debits, Credits & Closing Balance\" => top => get line above\n\ngo to page 2\nignore header above 485\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 70 130 560 645 740 840 => describe table false \"Date[dd MMM yy]\" Details #Debit #Credit #Balance','2021-07-06 08:14:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10174,'HSBC_USA_BANK','$source = \"HSBC_USA\"\n\n// Discard XXXX Statement in top left of page 1 as it gets in the way of finding the account number\n@dropBottom = subtract page.top 200\ndelete text in box page.top @dropBottom page.left page.right\n\n// Get account number and name\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => take last words 1 => get text\n$accountName = get line starting \"BEGINNING BALANCE\" => top => get line above => get text\n\n// Get period from/to\n@period = get line containing \"STATEMENT PERIOD\" => take last words 3\n$periodFrom = take words @period 1 => get date \"MM/dd/yy\"\n$periodTo = take last words @period 1 => get date \"MM/dd/yy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => get decimal\n$closingBalance = get line starting \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" =>  get decimal\n\n// Get start of table\n@transactionsTop = get line containing \"OPENING BALANCE\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\n\n// Discard extra lines\ndelete all lines containing \"OPENING BALANCE\"\n//get line containing \"CONTINUED ON NEXT PAGE\" => bottom => ignore footer below\ndelete all lines containing \"CONTINUED ON NEXT PAGE\"\ndelete all lines containing \"Please examine your\"\ndelete all lines containing \"HSBC Bank USA, N.A.\"\ndelete all lines containing \"CONTINUED FROM PREVIOUS PAGE\"\n@Boxtop = get last line containing \"ENDING BALANCE\" => top\ndelete text in box @Boxtop page.bottom page.left page.right\ndelete all lines containing \"ENDING BALANCE\"\ndelete all lines starting \"All deposited items are\"\nignore footer below 45\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 35 85 375 430 530 600 => describe table false \"Date[MM/dd/yy]\" Details #Credit #Debit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 85 375 430 515 600 => describe table false \"Date[MM/dd/yy]\" Details #Credit #Debit *#Balance','2023-04-27 08:26:36',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10175,'Handelsbanken_Ascending_A/cNO',' $source = \"Handelsbanken_Ascending_A/cNO\"\n\n $PeriodTo = get line containing \"DATE PRODUCED:\" => get words after \"DATE PRODUCED:\" => get date \"ddMMMyy\"\n $PeriodFrom =  get line containing \"PREVIOUS STATEMENT DATE:\" => get words after \"PREVIOUS STATEMENT DATE:\" => get date \"ddMMMyy\"\n\n // Get account number\n $accountNumber = get line starting \"A/C NO:\" => get words after \"A/C NO:\" => get text\n \n // Get account name\n $accountName = get line containing \"A/C NO:\" => bottom => get line below => take words 2 => get text\n \n // Opening Balance\n $OpeningBalance = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => get decimal\n\n\n // Clossing balance\n @CTop = get last line starting \"VALUE DATE DETAILS PAYMENT (DEBITS)\" => bottom\n @Cbottom = get last line containing \"Your deposit is eligible\" => top \n $ClosingBalance = get text in box @CTop @Cbottom 460 520 => take last words 1 => get decimal\n \n go to page 1\n get line containing \"VALUE DATE DETAILS PAYMENT (DEBITS) RECEIPTS (CREDITS) BALANCE\" => top => get line above => bottom => ignore header above\n\n delete all lines containing \"BALANCE BROUGHT FORWARD\"\n delete all lines containing \"Handelsbanken within 30 days\"\n \n // Discard page footer\n get line containing \"Please refer any enquiries\" => bottom => ignore footer below\n delete all lines containing \"Please refer any enquiries concerning\"\n\n\n // Get start of table\n @transactionsTop = get line starting \"VALUE DATE DETAILS PAYMENT (DEBITS) RECEIPTS (CREDITS) BALANCE\" => bottom => get line below => bottom => get line below\n \n // Get end of table\n @transactionsBottom = get last line containing \"Your deposit is eligible for protection\" => top => get line above\n \n $transactions = get multi page table @transactionsTop @transactionsBo