INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10183,'FirstTrustBank_OpeningBalance','$source = \"FirstTrustOpeningBalance\"\n\nset negative marker \"dr\"\n\n// Get left panel area\n@panelTop = get line containing \"Account name\" => Top\n@panelBottom = get line containing \"Account number\" => bottom => get line below => bottom \n$panelWords = get text in box @panelTop @panelBottom 435 page.right\n\n// Get account name and number\n$accountNumber = take last words $panelWords 1 => get text\n$accountName = get words after $panelWords \"Account name\" => take words 2 => get text\n\n// Get Opening Balance \n$OpeningBalanceText = get line containing \"OPENING BALANCE\" => take words 6\n\n// Get opening balances\n$openingBalance = take last words $OpeningBalanceText 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Details Debit\" => bottom => get line below\n\n// Get period to and from\n$statementPeriod = get line containing \"Period of statement\" => bottom => get line below\n$periodToText = take last words $statementPeriod 3 => get text\n$periodFrom = take words $statementPeriod 3 => get date \"d MMM yyyy\"\n$periodTo = take last words $statementPeriod 3 => get date \"d MMM yyyy\"\n\n//Get Closing Balance\n@LastOpeningBalanceText  = get last line containing \"OPENING BALANCE\" => top\n@LastPageFooter = get last line starting \"Interest on unauthorised debit balances\" => top\n$infoLast = get text in box @LastOpeningBalanceText @LastPageFooter page.middleX 440\n$closingBalance = take last words $infoLast 1 => get decimal\n\ndelete text in box on every page page.top page.bottom 435 page.right\n\n@tableHeader = get line containing \"Date Details Debit\" => bottom\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n// Get end of table\n@transactionsBottom = get last line starting \"Interest on unauthorised debit balances\" => top => get line above\ndelete all lines containing \"This is an eligible deposit under the Financial Services\"\ndelete all lines containing \"OPENING BALANCE\"\n\nignore footer below 75\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 95 230 300 350 440 => describe table false \"*Date[d MMM yyyy]\" Details *#Debit *#Credit #Balance\n\n','2021-07-28 06:13:02',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10184,'AIB_NI','$source = \"AIB_NI\"\n\nset negative marker \"dr\"\n\n//Get left panel area\n@panelTop = get line containing \"Account name\" => Top\n@panelBottom = get line containing \"Account number\" => bottom => get line below => bottom\n@panelWords = get text in box @panelTop @panelBottom 415 page.right\n\n// Get account name and number\n$accountNumber = take last words @panelWords 1 => get text\n$accountName = get words after @panelWords \"Account name\" => take words 2 => get text\n\ngo to page 1\n$dateleft = get line containing \"Date Details Debit\" => take words 1 => left => subtract 5\n$dateright = get line containing \"Date Details Debit\" => get words after \"Date\" => take words 1 => left => subtract 2.5\n$re_dateright = get line containing \"Date Details Debit\" => get words after \"Date\" => take words 1 => left => subtract 7\n$detailsright = get line containing \"Date Details Debit\" => get words after \"Details\" => take words 1 => left => subtract 9\n\n//$debitright = get line containing \"Date Details Debit\" => get words after \"Debit £\" => take words 1 => left => subtract 3\n//$creditright = get line containing \"Date Details Debit\" => get words after \"Credit £\" => take words 1 => left => add 3\n//$balanceright = get line containing \"Date Details Debit\" => get words after \"Credit £\" => take words 1 => right => add 60\n\n$debitright = get line containing \"Date Details Debit\" => get words after \"Debit\" => take words 2 => take last words 1 => left => subtract 3\n$creditright = get line containing \"Date Details Debit\" => get words after \"Credit\" => take words 2 => take last words 1 => left => add 3\n$balanceright = get line containing \"Date Details Debit\" => get words after \"Credit\" => take words 2 => take last words 1 => right => add 60\n\n\ndelete text in box on every page page.top page.bottom 445 page.right\n\n// Get Balance Forward\n@BalanceForwardText = get line containing \"BALANCE FORWARD\" => take words 6\n\n//Get period from and Period To\n//$periodFrom = get line containing \"Period of statement\" => bottom => get line below => take words 3 => get date \"dd MMM yyyy\"\n//$periodTo = get line containing \"Period of statement\" => bottom => get line below => take last words 3 => get date \"dd MMM yyyy\"\n\n@firsttranTop = get line containing \"Date Details Debit\" => bottom\n@firsttranBottom = get line above 100 => bottom\n$periodFrom = get text in box @firsttranTop @firsttranBottom 30 95 => take words 3 => get date \"d MMM yyyy\"\n\n//Get opening balances\n$openingBalance = take last words @BalanceForwardText 1 => get decimal\n\n//Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Details Debit\" => bottom => get line below\n\n//Get Closing Balance\n//@LastBalanceForwardText = get last line containing \"BALANCE FORWARD\" => bottom\n//@LastPageFooter = get last line starting \"Interest on unauthorised debit balances\" => top\n//@infoLast = get text in box @LastBalanceForwardText @LastPageFooter page.middleX 440\n//$closingBalance = take last words @infoLast 1 => get decimal\n\n//Get end of table\n//@transactionsBottom = get last line starting \"Interest on unauthorised debit balances\" => top => get line above\n@lasttranPage = get last line containing \"Date Details Debit\"\n@transactionsBottom = get line above 80\n\ndelete all lines containing \"This is an eligible deposit under the Financial Services\"\n//delete all lines containing \"BALANCE FORWARD\"\n\ngo to page 1\n@lineendtrans = get line containing \"Interest on unauthorised debit balances\" => top\ndelete text in box on every page @lineendtrans page.bottom page.left page.right\ndelete all lines containing \"important information about\"\ndelete all lines containing \"marketing information.\"\n\nignore footer below 85\n\n@PeriodtoTop = get last line starting \"Date Details Debit\"  => bottom\n@lastPanelWords = get text in box @PeriodtoTop 100 30 95\n$periodTo = take last words @lastPanelWords 3 => get date \"d MMM yyyy\"\n//$closingBalance =  get text in box @PeriodtoTop 100 350 440 => take last words 1 => get decimal\n$closingBalance =  get text in box @PeriodtoTop 100 $creditright $balanceright => take last words 1 => get decimal\n\n@tableHeader = get line containing \"Date Details Debit\" => bottom\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n//Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 95 90 220 285 350 440 => describe table false \"*Date[d MMM yyyy]\" - Details *#Debit *#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom $dateleft $dateright $re_dateright $detailsright $debitright $creditright $balanceright => describe table false \"*Date[d MMM yyyy]\" - Details *#Debit *#Credit #Balance','2025-06-25 11:51:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10185,'BOI_CreditCard',' \n$source = \"BOI_CreditCard\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 31\n\ngo to page 1\n$accountnumber = get line containing \"Credit Limit\" => top => get line above => get words between \"Credit Card\" \"Next Payment\" => get text\n$accountname = \"Bank Of Ireland\"\n\ngo to page 1 \n$openingbalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => get decimal\ngo to last page \n$closingbalance = get line containing \"New Balance\" => get words after \"New Balance\" => get decimal\n\ngo to page 1\n$periodfrom = get line containing \"Date Details Debit Credit\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n@periodTop = get last line containing \"Date Details Debit Credit\" => bottom\n@periodBottom = get last line containing \"Transaction Summary\" => top\n@text = get text in box @periodTop @periodBottom 50 100\n$periodto = take last words @text 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n@transactionsTop = get line containing \"Date Details Debit Credit\" => bottom => get line below \n@transactionsBottom = get last line containing \"Transaction Summary\" => top => get line above \n\ndelete all lines containing \"https://www.365online.com/\"\ndelete all lines containing \"Statements & Documents\"\ndelete all lines containing \"Details Debit Credit\"\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 310 380 450 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit \n\n','2021-07-28 06:20:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10186,'VirginMoneyIOS','$source = \"VirginMoneyIOS\"\n\n$features = \"NO_OPENING_BALANCE\"\n// Get account name and number\n@accountDetails = get line starting \"Date Description\" => top => get line above\n$accountNumber = take words @accountDetails 1 => get text\n$accountName = get line starting \"Account number\" => top => get line above => get text\n\n// Get period from/to\n@period = take last words @accountDetails 7\n$periodFrom = take words @period 3 => get date \"dd MMM yy\"\n$periodTo = take last words @period 3 => get date \"dd MMM yy\"\n\n// Discard addresses as they get in the way of the balances\n@dropTop = get line starting \"Branch Details\" => bottom\n@dropBottom = get line containing \"New Balance\" => bottom\ndelete text in box @dropTop @dropBottom page.left page.middleX\n\n// Get opening and closing balances\n$openingBalanceText = get line containing \"Opening Balance\" => get words after \"Opening Balance\"\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get last line containing \"Closing balance\" => get words after \"Closing balance\"\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type Debits Credits Balance\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\n// Discard header and footer\ndelete all lines containing \"Date Description Type Debits Credits Balance\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Total debits\"\ndelete all lines containing \"Total credits\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"https://\"\ndelete all lines containing \"Statement\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 95 262 350 430 497 600 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 260 360 440 520 600 => describe table false \"Date[dd MMM yy]\" Details TransactionType #Debit #Credit *#Balance','2024-08-07 06:24:23',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10187,'RBSNatWest1_Empty_ProducerCreator','$source = \"RBSNatWest1_Empty_ProducerCreator\"\n \n // Discard XXXX Statement in top left of page 1 as it gets in the way of finding the account number\n @dropBottom = subtract page.top 50\n delete text in box page.top @dropBottom page.left page.middleX\n \n // Get account name and number\n $accountNumber = get line containing \"Account number:\" => get words after \"Account number:\"  => take words 1 => get text\n //$accountNumber = get line containing \"Account number:\" => take words 1 => get text\n $accountName = get line starting \"Branch Details\" => top => get line above => get text\n \n // Get period from/to\n @period = get line containing \"Period\" => take last words 7\n $periodFrom = take words @period 3 => get date \"d MMM yyyy\"\n $periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n \n // Discard addresses as they get in the way of the balances\n @dropTop = get line starting \"Branch Details\" => bottom\n @dropBottom = get line containing \"New Balance\" => bottom\n delete text in box @dropTop @dropBottom page.left page.middleX\n \n // Get opening and closing balances\n $openingBalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\n $closingBalance = get line containing \"New Balance\" => take last words 1 => get decimal\n @broughtForward = get line starting \"Date Type Description\"\n \n // Get start of table\n @transactionsTop = bottom @broughtForward => get line below\n \n // Discard header and footer\n bottom @broughtForward => ignore header above\n delete all lines starting \"BROUGHT FORWARD\"\n delete all lines starting \"CONTINUED\"\n get last line starting \"©\" => top => ignore footer below\n // Some statements have extra text, but this text is higher than some transaction rows so delete below and then delete the line\n get last line starting \"Deposit Guarantee Scheme Information\" => bottom => ignore footer below\n delete all lines starting \"Deposit Guarantee Scheme Information\"\n get last line starting \"Your interest rate for\" => bottom => ignore footer below\n delete all lines starting \"Your interest rate for\"\n delete all lines starting \"©\"\n \n // Get end of table\n go to last page\n @transactionsBottom = get line above 0\n \n // Read the transactions\n $transactions = get multi page table @transactionsTop @transactionsBottom 20 86 204 352 420 490 570 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit *#Balance','2021-08-06 05:49:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10188,'Westpac_TRANSACTION_DESCRIPTION','$source = \"Westpac_TRANSACTION_DESCRIPTION\"\r\n\r\n// Get period from/to\r\n@period = get line containing \"Statement Period\" => bottom => get line below\r\n$periodFrom = take words @period 3 => get date \"dd MMMM yyyy\"\r\n$periodTo = take last words @period 3 => get date \"dd MMMM yyyy\"\r\n\r\n// Get account name and number\r\n$accountName = get line containing \"Account Name\" => get words after \"Account Name\" => get text\r\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => take last words 2 => get text\r\n\r\n// Get opening and closing balance\r\n$openingBalance = get line starting \"Opening Balance\" => take last words 2 => get decimal\r\n$closingBalance = get last line starting \"Closing Balance\" => take last words 2 => get decimal\r\n\r\ngo to page 1\r\n// Get start and end of table\r\n@transactionsTop = get line containing \"STATEMENT OPENING BALANCE\" => bottom => get line below\r\n@transactionsBottom = get line containing \"CLOSING BALANCE\" => top => get line above\r\n\r\n// Discard header and footer\r\ngo to page 1\r\n@text = get last line containing \"Customer ID\" => bottom => get line below => take words 2 => get text\r\n@text1 = get last line containing \"Customer ID\" => bottom => get line below => bottom => get line below => take words 2 => get text\r\n@text2 = get last line containing \"Customer ID\" => bottom => get line below => bottom => get line below => bottom => get line below => take words 2 => get text\r\n@text3 = get last line containing \"Customer ID\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => take words 2 => get text\r\n@text4 = get last line containing \"Customer ID\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => take words 2 => get text\r\n\r\ngo to page 1\r\ndelete all lines containing @text\r\ndelete all lines containing @text1\r\ndelete all lines containing @text2\r\ndelete all lines containing @text3\r\ndelete all lines containing @text4\r\n\r\ngo to page 1\r\n@text5 = get line containing \"Account Number\" => bottom => get line below => get text\r\ndelete all lines containing @text5\r\n\r\n@lastpage = get last line containing \"Customer ID\"\r\n@text6 = top @lastpage => get line above => take words 3 => get text\r\n@text7 = top @lastpage => get line above => top => get line above => take words 3 => get text\r\ndelete all lines containing @text6\r\ndelete all lines containing @text7\r\n\r\n\r\ndelete all lines containing \"Customer ID\"\r\ndelete all lines containing \"BSB Account Number\"\r\ndelete all lines containing \"Opening Balance\"\r\ndelete all lines containing \"Total Credits\"\r\ndelete all lines containing \"Total Debits\"\r\ndelete all lines starting \"Closing Balance\"\r\ndelete all lines containing \"We wish to advise you\"\r\ndelete all lines containing \"have been forwarded to\"\r\ndelete all lines containing \"Please check all entries on this statement\"\r\ndelete all lines starting \"DATE TRANSACTION DESCRIPTION DEBIT\"\r\ndelete all lines containing \"STATEMENT OPENING BALANCE\"\r\ndelete all lines containing \"CLOSING BALANCE\"\r\ndelete all lines ending $accountNumber\r\nignore header above 721\r\nignore footer below 110\r\n\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 110 340 420 480 570 => describe table false \"Date[dd/MM/yy]\" Details **#Debit **#Credit #Balance','2026-05-14 09:56:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10189,'TCF National Bank','$source = \"TCF National Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\nset negative marker \"-\"\n\n$accountName = get text in box 677 658 75 210 => take words 3 => get text\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\n\n go to page 1\n$PeriodFrom = get line containing \"Last statement\" => get words after \"Last statement\" => get date \"MMMM dd, yyyy\"\n$periodTo = get line containing \"This statement\" => get words after \"This statement\" => get date \"MMMM dd, yyyy\"\n\ngo to page 1 \n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => get decimal\n$closingBalance = get line containing \"Ending totals\" => get words after \"Ending totals\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Beginning balance\" => bottom => get line below\n@transactionsBottom = get line containing \"Ending totals\" => top => get line above\n\ndelete all lines containing \"Page\"\ndelete all lines containing $accountNumber\ndelete all lines containing \"Date Description Additions\"\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 90 135 305 370 480 580 => describe table false \"Date[MM-dd]\" Details #Credit #Debit *#Balance\n\n\n ','2021-08-11 10:28:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10190,'FNBCreditCard_Enterprise','$source = \"FNBCreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 28\n\n// Transactions with CR text are negative\nset negative marker \"Cr\"\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\n// Get account name\n$accountName = get text in box 720 660 0 400 => take words 3  => get text\n\n// Get period from/to\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dd MMMM yyyy\"\n@top = get line containing \"Date Facility Facility\" => bottom\n$periodFrom = get text in box @top page.bottom 0 50 => take words 2 => get date \"dd MMM\"\n\n// Get opening and closing balances\ngo to page 1\n\n@openingBalanceTop = get line containing \"Balance Brought Forward\" => top\n@openingBalanceBottom = get line containing \"Balance Brought Forward\" => bottom\n@openingBalancebox = get text in box @openingBalanceTop @openingBalanceBottom 0 page.right\n$openingBalance = get words between @openingBalancebox \"Forward\" \"Balance\" => get decimal\n\n@pageHeader = get line containing \"First National Bank, a division of FirstRand Bank Limited\" => top => get line above => top\n@pageFooter = get line containing \"First National Bank, a division of FirstRand Bank Limited\" => top\n@infoLast = get text in box @pageHeader @pageFooter 50 450\n$closingBalanceText = get words after @infoLast \"Balance\" => get text\n$closingBalance = get words after @infoLast \"Balance\" => get decimal\n\ngo to page 1\n// Delete extra box\ndelete all lines containing \"Transaction Total\"\ndelete all lines containing \"Balance Brought Forward\"\ndelete all lines containing \"An Authorised Financial Services Provider\"\ndelete all lines containing \"NCA Registration Number\"\ndelete all lines starting \"Page\"\n\ndelete all lines containing \"Important Notice: The use\"\ndelete all lines containing \"available on FNB website\"\ndelete all lines containing \"FirstRand Group reserves the right\"\ndelete all lines containing \"thereof will be indicated on\"\ndelete all lines containing \"and Conditions\"\ndelete all lines containing \"Closing Balance\"\n\n\ngo to page 1\n// Get start of table\n@transactionTop = get line containing \"Transaction Details\" => bottom => get line below\n\n// Get end of table\n@transationBottom = get line containing \"a division of FirstRand Bank Limited\" => top => get line above\n\ndelete all lines containing \"Total Transactions\"\ndelete all lines containing \"Total Card Balance\"\ndelete all lines containing \"Amount Due (Transferred)\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"Total Outstanding Balance\"\ndelete all lines containing \"First National Bank, a division of FirstRand Bank Limited.\"\ndelete all lines containing \"(Revolver)\"\ndelete all lines containing \"(Transactor)\"\ndelete all lines containing \"Transaction Details\"\nignore footer below 50\n\n// Read the transactions\n$transactions = get multi page table @transactionTop @transationBottom 0 345 450 => describe table false Details *#Credit','2025-04-15 05:12:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10191,'BBT','$source = \"BBT\"\n$periodBufferDays = 14\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountname = get line containing \"Your account statement\" => top => get line above  => top => get line above  => top => get line above  => get text\ngo to page 1\n@accountnumberText = get line starting \"Account summary\" => top => get line above\n$accountnumber = take last words @accountnumberText 1 => get text\n\n//openingbalance = get line containing \"Your previous balance as of\" => get words after \"Your previous balance as of\" => skip words 1 => get decimal\n$openingbalance = get line containing \"Your previous balance as of\" => get words after \"Your previous balance as of\" => skip words 1 => take words 1 => get decimal\n$closingbalance = get line containing \"Your new balance as of\" => get words after \"Your new balance as of\" => skip words 1 => get decimal\n\n\n@periodtoText = get line containing \"Your new balance as of\" => get words after \"Your new balance as of\"\n$periodto = take words @periodtoText 1 => get date \"MM dd yyyy\"\n@periodfromText = get line containing \"Your previous balance as of\" => get words after \"Your previous balance as of\"\n$periodfrom = take words @periodfromText 1 => get date \"MM dd yyyy\"\n\n\ngo to page 1\n@ChecksTop = get line starting \"Your new balance as of\" => bottom => get line below\n@ChecksBottom = get line containing \"DATE DESCRIPTION AMOUNT\" => top => get line above\n\ngo to page 1\n@DebitTop = get line starting \"DATE DESCRIPTION AMOUNT\" => bottom => get line below\n@DebitBottom = get last line containing \"Total other withdrawals, debits and service charges\" => top => get line above\n\n@CreditTop = get last line containing \"Total other withdrawals, debits and service charges\" => bottom => get line below\n@CreditBottom = get last line containing \"Total deposits, credits and interest\" => top => get line above\n\ndelete all lines containing \"PAGE\"\ndelete all lines starting \"Checks\"\ndelete all lines containing \"indicates a skip in sequential check numbers above this item\"\ndelete all lines containing \"Total checks\"\ndelete all lines starting \"DATE DESCRIPTION AMOUNT\"\ndelete all lines starting \"Other withdrawals, debits and service charges\"\ndelete all lines starting \"continued\"\ndelete all lines starting \"BUSINESS VALUE\"\ndelete all lines starting \"Toll Free\"\ndelete all lines starting \"Annual Percentage Rate\"\ndelete all lines starting \"Outside Canada/U.S.\"\ndelete all lines starting \"Total other withdrawals, debits and service charges\"\ndelete all lines starting \"Deposits, credits and interest\"\ndelete all lines starting \"DATE CHECK # AMOUNT\"\ndelete all lines starting \"Total deposits, credits and interest\"\ndelete all lines containing \"ยง\"\ndelete all lines starting \"continued\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"TN\"\ndelete all lines containing \"(continued)\"\ndelete all lines starting \"TRUIST SIMPLE BUSINESS\"\ndelete all lines starting \"AMOUNT($)\"\ndelete all lines ending $accountnumber\n\n@checksTransactionsLeft = get multi page table @ChecksTop @ChecksBottom 0 60 120 205 => describe table false \"Date[MM dd]\" #ChequeNumber *#Debit\n@checksTransactionsMiddle = get multi page table @ChecksTop @ChecksBottom 206 255 300 400 => describe table false \"Date[MM dd]\" #ChequeNumber *#Debit\n@checksTransactionsRight = get multi page table @ChecksTop @ChecksBottom  405 445 500 600 => describe table false \"Date[MM dd]\" #ChequeNumber *#Debit\n@DebitTransactions = get multi page table @DebitTop @DebitBottom 0 55 520 610 => describe table false \"Date[MM dd]\" Details  *#Debit\n@CreditTransactions = get multi page table @CreditTop @CreditBottom 0 55 520 610 => describe table false \"Date[MM dd]\" Details  *#Credit\n\n$transactions = combine described tables @DebitTransactions @CreditTransactions @checksTransactionsLeft @checksTransactionsMiddle @checksTransactionsRight','2025-10-29 06:17:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10192,'DBS_CurrentAccount','$source = \"DBS_CurrentAccount\"\n$periodBufferDays = 14\n\n//Discard hidden text\ndelete white words\ndelete tiny words\ndelete rotated words\n\n$accountname = get line starting \"Account Statement\" => bottom => get line below  => bottom => get line below => get text\n$accountnumber = get line containing \"Account No:\" => get words after \"Account No:\" => get text\n\n\n\n//@periodText = get line starting \"Details Of Your DBS\" => bottom => get line below => get words before \"Account No:\"\n@periodText = get line containing \"Account No:\" => get words before \"Account No:\"\n//$periodto = take last words @periodText 1 => get date \"dd MMM yyyy\"\n$periodfrom = take words @periodText 1 => get date \"dd MMM yyyy\"\n\n$periodto = get last line containing \"Account No:\" => get words before \"Account No:\" => take last words 1 => get date \"dd MMM yyyy\"\n\n\ngo to page 1\n$openingbalance = get line starting \"Balance Brought Forward\" => get words after \"Balance Brought Forward\" => get decimal\n$closingbalance = get last line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => get decimal\n\ngo to page 1\ndelete all lines starting \"Page\"\n@gettexttop1 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop1\n@gettexttop2 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop2\n@gettexttop3 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop3\n@gettexttop4 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop4\n@gettexttop5 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gette