INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10193,'Bank_of_Melbourne','$source = \"Bank_of_Melbourne\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Delete footer lines\ndelete all lines containing \"Melbourne - A Division\"\ndelete all lines containing \"Division ofWestpac Banking\"\n\n// Delete left panel\ndelete text in box on every page page.top page.bottom page.left 20\n\ngo to page 1\n// Get Account Name\n$accountName = get line containing \"Account Summary\" => top => get line above => get text\n//$accountName = get line containing \"BSB Number\" => get words before \"BSB Number\" => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\n// Get Balances\n$openingBalance = get line containing \"Opening Balance Total Credits Total Debits\" => bottom => get line below => get words before \"+\" => get decimal\n$closingBalance = get line containing \"Opening Balance Total Credits Total Debits\" => bottom => get line below => get words after \"=\"  => get decimal\n\ngo to page 1\n// Get Period From/To datesmicrosoft-edge://?source=Windows.Widgets&muid=04EFAF3BB7AF64F0120AB94CB6B465CC&url=https%3A%2F%2Fwww.msn.com%2Fen-in%2Fhealth%2Fother%2Fneurologist-breaks-down-how-much-sleep-you-need-by-age-we-fact-check%2Far-AA1LgbzM&timestamp=1765261932190\n$periodFrom = get line containing \"Statement Period\" => get words between \"Statement Period\" \"to\" => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"Statement Period\" => get words after \"to\" => get date \"dd/MM/yyyy\"\n\ngo to page 1\n// Get top and bottom of transactions table\n@transactionsTop = get line starting \"Date Transaction Description Debit Credit\" => bottom => get line below\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\n// Remove unwanted lines\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"Account Number\"\ndelete all lines containing \"Statement Period\"\ndelete all lines containing \"Statement No\"\ndelete all lines containing \"SUB TOTAL CARRIED FORWARD TO NEXT PAGE\"\ndelete all lines containing \"SUB TOTAL CARRIED FORWARD FROM PREVIOUS PAGE\"\ndelete all lines containing \"Transaction Description\"\ndelete all lines containing \"Transaction Details continued\"\n// ignore footer below 50\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 74 310 400 470 580 => describe table false \"Date[dd MMM]\" Details #Debit #Credit *#Balance','2026-01-07 06:33:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10194,'SantanderOnlineBussinessBanking','$source = \"SantanderOnlineBussinessBanking\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n//$periodBufferDays = 114\n// Get account number\n@accountNumbertemp = get line containing \"Account:\" => get words after \"Account:\" \n$accountNumber = take last words @accountNumbertemp 1 => get text\n// Get account name\n\n$accountname = take words @accountNumbertemp 1 => get text\n\n//go to last page\n@openingbalancetemp1 = get last line containing \"DATE DESCRIPTION MONEY IN MONEY OUT BALANCE\" => bottom\n@openingbalancetemp = get last line containing \"transactions\" => top\n\n//@openingbalancetemp2 = get text in box @openingbalancetemp1 @openingbalancetemp 420 page.right\n\n//$openingbalance = take last words @openingbalancetemp2 1 => get decimal\n\ngo to page 1\n@closingbalancetemp1 = get line containing \"DATE DESCRIPTION MONEY IN MONEY OUT BALANCE\" => bottom => get line below\n$closingbalance = take last words @closingbalancetemp1 1 => get decimal\n\n// Get Period\n\n$periodto = take words @closingbalancetemp1 1 => get date \"dd/MM/yyyy\"\ngo to last page\n@periodfromtemp2 = get text in box @openingbalancetemp1 @openingbalancetemp 50 100\n$periodfrom = take last words @periodfromtemp2 1  => get date \"dd/MM/yyyy\"\n\ngo to page 1\n@transactionsTop = get line starting \"DATE DESCRIPTION MONEY IN MONEY OUT BALANCE\" => bottom => get line below\n@transactionsBottom = get last line containing \"transactions\" => top => get line above\ndelete all lines containing \"DATE DESCRIPTION MONEY IN MONEY OUT BALANCE\"\ndelete all lines containing \"https://business.santander.co.uk\"\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 290 360 420 490 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit #Balance','2021-08-23 07:10:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10195,'StandardBank_Card',' $source = \"StandardBank_Card\"\n $features = \"CREDIT_CARD\"\n $periodBufferDays = 14\n	\n // Get period from and periodto\n  $periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"d MMM yy\"\n  $periodTo = get line containing \"Statement Period\" => get words after \"Statement Period\" => get words after \"to\" => take words 3 => get date \"d MMM yy\"\n     \n // Get account name and account number\n @nametop = get line containing \"Statement details\" => bottom\n @namebottom = get line containing \"Important Contact Information\" => top \n  \n  $accountName = get text in box @nametop @namebottom page.left page.middleX => take words 3 => get text\n  $accountNumber = get line containing \"Account Summary Account\" => get words after \"Account Summary Account\" => get text\n   \n // Get opening and closing balances\n  $OpeningBalance = get line starting \"Balance brought forward\" => take last words 1 => get decimal\n  $ClosingBalance = get line starting \"Closing balance\" => take last words 1 => get decimal\n  \n  \n  // Discard header on Credit page only\n  go to page 1\n  @headerfirst = get line containing \"Date Description Amount\" => bottom \n  delete text in box page.top @headerfirst page.left page.right\n   \n \n // Discard page footer on every page\n  ignore footer below  220\n\n \n // Get start and end of Credit table\n  go to page 1\n  @CredittransactionsTop = get line starting \"Credits\" => bottom => get line below\n  @CredittransactionsBottom = get line starting \"Debit\" => top => get line above\n \n   \n  // Discard Credit page Footer only\n  @topcreditfooter = get line starting \"Debit\" => top \n  delete text in box @topcreditfooter page.bottom page.left page.right\n  \n delete all lines starting \"*\"\n delete all lines starting \"PLEASE VISIT OUR WEBSITE\"\n delete all lines starting \"CONDITIONS THAT\"\n delete all lines starting \"Debit\"\n delete all lines starting \"Credit\"\n delete all lines starting \"PLEASE NOTE THAT\"\n delete all lines starting \"CREDIT CARD WILL\"\n delete all lines starting \"LET\'S SMARTEN UP\"\n delete all lines starting \"NOW YOU CAN ENJOY\"\n delete all lines starting \"TECHNOLOGY. TO\"\n delete all lines starting \"PIN\"\n delete all lines starting \"STANDARD BANK\"\n delete all lines starting \"THE DETAILS\"\n delete all lines starting \"DEBIT ORDERS PROVIDE MORE CONTROL\"\n delete all lines starting \"METHOD OF PAYMENT.\"\n delete all lines starting \"OR DEBI CHECK.\"\n delete all lines starting \"PLEASE CONTACT US FOR MORE INFORMATION OR TO SET UP A DEBIT ORDER.\"\n delete all lines starting \"P O BOX\"\n \n delete all lines containing \"Balance Brought Forward\"\n\n  // Read the Credit transactions\n  @CreditLefttransactions = get multi page table @CredittransactionsTop @CredittransactionsBottom 25 85 240 293 => describe table false \"Date[d MMM yy]\" Details *#Credit \n  @CreditRighttransactions = get multi page table @CredittransactionsTop @CredittransactionsBottom 300 345 500 565 => describe table false \"Date[d MMM yy]\" Details *#Credit \n  \n\n // Discard header on every page\n  ignore header above 400\n \n  \n // Get start and end of Debit tables\n  @DebitLefttransactionsTop = get line starting \"Date Description Amount\" => bottom => get line below \n  @DebitLefttransactionsBottom = get last line containing \"Balance transferred to\" => top => get line above \n \n delete all lines containing \"Date Description Amount\"\n delete all lines containing \"Balance transferred to\"\n\n  @DebitLefttransactions   = get multi page table @DebitLefttransactionsTop @DebitLefttransactionsBottom 25 85 240 293 => describe table false \"Date[d MMM yy]\" Details *#Credit \n  @DebitRighttransactions  = get multi page table @DebitLefttransactionsTop @DebitLefttransactionsBottom 300 345 500 565 => describe table false \"Date[d MMM yy]\" Details *#Credit \n  \n  $transactions = combine described tables   @CreditLefttransactions @CreditRighttransactions @DebitLefttransactions @DebitRighttransactions  ','2021-08-16 06:52:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10196,'Clarke_County_Checks','$source = \"Clarke_County\"\n\n\ndelete all lines containing \"Descci11tioa\"\ndelete all lines containing \"Descciption\"\n@accountNumberTop = get line containing \"Summary of Accounts\" => bottom => get line below => bottom\n$accountNumber = get text in box @accountNumberTop 470 350 415 => get text\n\ngo to page 1\n@deleteTop = get line containing \"Account Summary\" => top\n@deleteBottom = get line containing \"Deposits\" => top\n$deleteText = delete text in box @deleteTop @deleteBottom 340 page.right\n\ngo to page 1 \n$openingBalance = get line containing \"Date Description\" => bottom => get line below => get words after \"Balance\" => get decimal\n$closingBalance = get line containing \"Debit(s) This Period\" => top => get line below => get words after \"Balance\" => get decimal\ngo to page 1\n@data = get line containing \"Account Summary\" => bottom => get line below => get words after \"Date\" => take words 1 \n\n\ngo to page 1\n$accountName = get text in box 655 630 50 210 => take words 2 => get text\n\ngo to page 1\n$PeriodFrom = get line containing \"Date Description\" => bottom => get line below => get words before \"Beginning\" => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Debit(s) This Period\" => top => get line below => get words before \"Ending\" => get date \"MM/dd/yyyy\"\n\ndelete all lines containing \"Statement Ending\"\ndelete all lines containing \"Page\"\n\ndelete all lines containing \"Description\"\n\n\n\ndelete words @data\ndelete all lines containing \"continued\"\n\n\ngo to page 1\nignore footer below 85\n\ngo to page 1\n@TransactiondepositsTop = get line containing \"Deposits\" => bottom => get line below\n@TransactiondepositsBottom = get line containing \"Electronic Credits\" => top => get line above\n\ndelete all lines containing \"Deposits\"\n\n\ngo to page 1\n@TransactiondepositsElectronicT