INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10208,'MandT','$source = \"MandT\"\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n\n$periodtop = get line containing \"ACCOUNT NUMBER\" => bottom\n$periodleft = get line containing \"ENDING BALANCE\" => bottom\n$periodtext = get text in box $periodtop $periodleft 365 page.right\n$accountName = take words $periodtext 1 => get text\n$accountnumber = take words $periodtext 1 => get text\n$periodfrom = take words $periodtext 2 => skip words 1 => get date \"M/d/yy\"\n\n$openingBalance = get words after $periodtext \"BEGINNING BALANCE\" => take words 1 => get decimal\n$periodto = get last line containing \"ACCOUNT NUMBER\" => bottom => get line below => take words 4 => take last words 1 => get date \"M/d/yy\"\n$closingBalance = get last line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" =>  take words 1 => get decimal\n\ngo to page 1\n//get line starting \"ACCOUNT ACTIVITY\"\n@transactionsTop = get line containing \"TRANSACTION DESCRIPTION\" => bottom => get line below\n@transactionsBottom = get last line starting \"NUMBER OF DEPOSITS/CHECKS PAID\" => top => get line above\ngo to page 1\n$dlttop = get line starting \"EFFECTIVE\" => top\n$dltbot = get line containing \"DICUSS THIS CHANGE\" => bottom\n$dlteff = delete text in box $dlttop $dltbot page.left page.right\n\n$dlttop1 = get line starting \"EFFECTIVE\" => top\n$dltbot1 = get line containing \"DICUSS THIS CHANGE\" => bottom\n$dlteff1 = delete text in box $dlttop1 $dltbot1 page.left page.right\n\n$dlttop2 = get line containing \"EFFECTIVE\" => top\n$dltbot2 = get line containing \"SUMMARY OF CHANGES\" => bottom\n$dlteff2 = delete text in box $dlttop2 $dltbot2 page.left page.right\n\n$dlttop3 = get line containing \"EFFECTIVE\" => top\n$dltbot3 = get line containing \"SUMMARY OF CHANGES\" => bottom\n$dlteff3 = delete text in box $dlttop3 $dltbot3 page.left page.right\n\n$dlttop4 = get line containing \"IMPORTANT INFORMATION\" => top\n$dltbot4 = get line containing \"VISIT YOUR BRANCH\" => bottom\n$dlteff4 = delete text in box $dlttop4 $dltbot4 page.left page.right\n\ndelete all lines containing \"DATE CREDITS (+) OTHER DEBITS\"\ndelete all lines containing \"NUMBER OF DEPOSITS/CHECKS PAID\"\ndelete all lines containing \"BEGINNING BALANCE\"\ndelete all lines containing \"WE HAVE REVISED OUR\"\ndelete all lines containing \" AND PRODUCT TERMS AND\"\ndelete all lines containing \"YOUR USE OF TM SERVICES\"\ndelete all lines containing \"WILL BE GOVERNED\"\ndelete all lines containing \"INCLUDING A SUMMARY OF\"\ndelete all lines containing \"THE REVISED TM AGREEMENT\"\ndelete all lines containing \"TM SERVICES ARE GOVERNED\"\ndelete all lines containing \"TM AGREEMENTS DATED PRIOR\"\ndelete all lines containing \"TREASURY MANAGEMENT AND COMMERCIAL\"\ndelete all lines containing \"PRICING IS CHANGING\"\ndelete all lines containing \"INSERT WITH THE CHANGES\"\ndelete all lines containing \"SEPARATE MAILING\"\ndelete all lines containing \"CHANGES SPECIFIC TO\"\ndelete all lines starting \"COMMUNICATIONS\"\ndelete all lines starting \"ACCOUNT ACTIVITY\"\n\nignore header above 620\nignore footer below 48\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 70 325 410 493 575 => describe table false \"*Date[M/d/yyyy]\" Details #Credit #Debit #Balance','2025-07-24 06:49:53',0);
