INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10215,'CapitalOneCard_leftTrans','$source = \"CapitalOneCard_leftTrans\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n$accountnumber = get line containing \"Account Ending in\" => take last words 1 => get text\n\n@period = get line starting \"Payment Information\" => top => get line above\n$periodfrom = take words @period 3 => get date \"MMM dd yyyy\"\n$periodto = take words @period 7 => get words after \"-\" => get date \"MMM dd yyyy\"\n\n//Opening and closing balance\n@summaryTop = get line ending \"Account Summary\" => bottom\n@summaryBottom = get line containing \"Credit Limit\" => top\n@summarybox = get text in box @summaryTop @summaryBottom page.middleX page.right\n\n$openingbalance = get words after @summarybox \"Previous Balance\" => take words 1 => get decimal\n$closingbalance = get words after @summarybox  \"New Balance\" => take last words 1 => get decimal\n\n$accountname = get text in box 120 80 page.left page.middleX => take words 2 => get text\n@accountHolname = get text in box 120 80 page.left page.middleX => take words 1 => get text\n\ngo to page 1\n//@transactionstop = get line starting \"Transactions\" => bottom => get line below\n//@transactionsbottom = get last line starting \"Total Fees for This Period\" => top => get line above\n@transactionstopleft = get line starting \"Transactions\" => bottom => get line below\n@transactionsbottomleft = get last line starting \"Total Fees for This Period\" => top => get line above\n\ngo to page 1\n//delete right part transactions not supported\ndelete text in box on every page page.top page.bottom 320 page.right\n\ndelete all lines starting @accountHolname\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"Total Fees for This Period\"\ndelete all lines starting \"Total Transactions for This Period\"\ndelete all lines starting \"Visit www.capitalone.com\"\n\n@transactionstopInterset = get last line starting \"Interest Charged\" => bottom => get line below\n@transactionsbottomInterest = get last line starting \"Total Interest for This Period\" => top => get line above\n\n// reading the transactions\n@transactionsleft = get multi page table @transactionstopleft @transactionsbottomleft 30 75 240 312 => describe table false \"Date[MMM d]\" Details *#Credit\n@transactionsinterest = get multi page table @transactionstopInterset @transactionsbottomInterest 40 250 315 => describe table false \"Details\" *#Credit\n\n// combining the transactions\n$transactions = combine described tables @transactionsleft @transactionsinterest','2023-02-15 09:24:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10217,'FirstNationalBank_WithoutSummary','$source = \"FirstNationalBank_WithoutSummary\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Transactions with CR text are negative\nset negative marker \"Dr\"\n\n// Get account name\n$accountName = get text in box 720 660 0 400 => take words 5  => get text\n$accountnumber = get line starting \"Customer VAT Registration\" => take last words 1 => get text\n\n@periodText = get line starting \"Statement Period :\" => get words after \"Statement Period :\"\n$periodfrom = take words @periodText 3 => get date \"d MMMM yyyy\"\n$periodto = take last words @periodText 3 => get date \"d MMMM yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$closingBalance = get line starting \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\n\nset negative marker \"Cr\"\n\n// Get start of table\n//@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\n@transactionsTop = get line starting \"Transactions in\" => bottom => get line below\n\n// Discard page footer\nignore footer below 60\n\n// Get end of table\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\n\ndelete all lines starting \"ACCOUNT:\"\ndelete all lines starting \"Opening Balance\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"Tax Invoice/Statement Number :\"\ndelete all lines starting \"Transactions in\"\n\n// Delete Some extra lines\ndelete all lines containing \"Reference Amount Fee\"\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Intercompany/ Intergroup\"\ndelete all lines starting \"Receipts Via Other Banks\"\ndelete all lines containing \"Electronic Collections\"\ndelete all lines containing \"FNB Customers\"\ndelete all lines containing \"Debit Orders\"\ndelete all lines starting \"Payments Through Stop Orders\"\ndelete all lines starting \"Bank Charges\"\ndelete all lines starting \"Miscellaneous\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 37 420 482 => describe table false \"*Date[dd MMM]\" Details #Debit\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 37 420 520 => describe table false \"*Date[dd MMM]\" Details #Debit','2024-01-31 08:00:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10218,'CaliforniaBankofCommerce','$source = \"CaliforniaBankofCommerce\"\n\ndelete white words\ndelete tiny words\ndelete rotated words\n\n// Get account number\n@accountNumbertext = get line starting \"Account Type Account Number Ending Balance\" => bottom => get line below\n$accountNumber = get words after @accountNumbertext \"Interest Checking\" => take words 1 => get text\n\n// Get account name\n$accountname = get line starting \"Branch Name\" => bottom => get line below => get words before \"Phone Number\" => get text\n\n// Get Period\n//@periodtext = get line containing \"END OF DAY\" => top => get line above\n$periodfrom = get last line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/dd/yyyy\"\n$periodto = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => get date \"MM/dd/yyyy\"\n\n// Get Opening & Closing balance\n$openingbalance = get last line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\n// get table top & bottom\ngo to page 1\n@transactionstop = get line starting \"Post Date Description Debits Credits Balance\" => bottom => get line below => bottom => get line below\n@transactionsbottom = get last line containing \"Ending Balance\" => top => get line above\n\ndelete all lines starting \"Statement Ending\"\ndelete all lines containing \"Savings Account Statements\"\ndelete all lines containing \"(continued)\"\ndelete all lines starting \"Post Date Description Debits Credits\"\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 20 85 345 420 495 590 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2021-09-06 06:18:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10219,'StandardBankAccountHolder','$source = \"StandardBankAccountHolder\"\n$features = \"NO_OPENING_BALANCE NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 45\n\n// Get account name and number\n$accountnumber = get line starting \"Account:\" => take last words 1 => get text\n$accountname = get line starting \"Account holder:\" => get words after \"Account holder:\" => get text\n\n// Get period from/to\n$periodfrom = get line starting \"Transaction date range:\" => get words after \"Transaction date range:\" => get words before \"-\" => get date \"d MMMM yyyy\"\n$periodto = get line starting \"Transaction date range:\" => get words after \"Transaction date range:\" => get words after \"-\" => get date \"d MMMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below => bottom => get line below\n\nget last line starting \"Date Description\" => bottom => ignore header above\n\n// Get end of table\n@transactionsBottom = get last line containing \"# These fees are zero rated\" => top => get line above\n\n// Get closing balance\n@closingbottom = bottom @transactionsBottom\n@closingtop = top @transactionsBottom\n$closingBalance = get text in box @closingtop @closingbottom 480 page.right => get decimal\n\nset negative marker \"-\"\n\n// Discard header and footer\ndelete all lines containing \"## These fees include VAT at the applicable\"\ndelete all lines containing \"Please verify all transactions reflected\"\ndelete all lines containing \"The Standard Bank of South Africa Limited\"\ndelete all lines starting \"Banking Practice of the Banking Association South Africa\"\ndelete all lines starting \"# These fees are zero rated\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 80 290 370 460 500 600 => describe table false \"Date[dd MMM]\" Details #Credit #Debit 