INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10220,'StandardBank_SouthAfrica_DailyFrequency','$source = \"StandardBank_SouthAfrica_DailyFrequency\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Parse amounts in SouthAfrica\nset culture \"en-ZA\"\n\n// Get account name\n$accountName = get text in box 735 670 0 210 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => take last words 4 => get text\n\n// Get Period from and Period To\n$statementPeriod = get line starting \"Statement from\" => take last words 7\n$periodFromText = take words $statementPeriod 3 => get text\n$periodFrom = take words $statementPeriod 3 => get date \"dd MMMM yyyy\"\n$periodToText = skip words $statementPeriod 4\n$periodTo = skip words $statementPeriod 4 => get date \"dd MMMM yyyy\"\n\n// Get opening balances\n@openingBalance = get line starting \"BALANCE BROUGHT FORWARD\" => skip words 5\n$openingBalanceText = get text @openingBalance\n$openingBalance = get decimal @openingBalance\n\ngo to page 1\n$DateLeft = get line containing \"Credits\" => get words after \"Credits\" => take words 1 => left\n$DateLeft = subtract $DateLeft 5\n\ngo to page 1\n$DebitsLeft = get line containing \"Debits\" => get words before \"Debits\" => get text\n$ActualDebitsLeft = get line containing $DebitsLeft => get words after $DebitsLeft => take words 1 => left\n$DebitsLeft = subtract $ActualDebitsLeft 20\n\ngo to page 1\n$ServiceLeft = get line containing \"Credits Date Balance\" => get words after \"Service\" => get text\n$ActualServiceLeft = get line containing $ServiceLeft => get words before $ServiceLeft => take last words 1 => left\n\n// Get start & end of transactions table\n@transactionsTop = get line starting \"BALANCE BROUGHT FORWARD\"  => bottom => get line below\n\n@transactionsBottom = get last line starting \"Please note that\" => top => get line above\n\n\n//Get Closing Balance\ngo to last page\n@pageFooter = get last line starting \"Please note that\" => top\n//@infoLast = get text in box page.top @pageFooter 470 page.right\n@infoLast = get text in box page.top @pageFooter 460 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\n// Discard page header\nget last line starting \"BALANCE BROUGHT FORWARD\" => top => ignore header above\n\nget line starting \"Please verify all transactions\" => bottom => ignore footer below\ndelete all lines containing \"These fees\"\n\n\n// Remove unwanted lines\ndelete all lines starting  \"Please note that\"\ndelete all lines starting \"Credits Date Balance\"\ndelete all lines containing \"Fee Debits\"\ndelete all lines containing \"Details Service Date Balance Debits Credits Fee\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines starting \"We subscribe to the Code\"\ndelete all lines starting \"through the Ombudsman\"\ndelete all lines starting \"The Standard Bank of South Africa Limited\"\ndelete all lines starting \"VAT Reg No.\"\n\n//Delete Service Column\n$DeleteServicePanel = delete text in box on every page page.top 0 $ActualServiceLeft $ActualDebitsLeft => get text\n\n// Read the transactions\n//$transactions  = get multi page table @transactionsTop @transactionsBottom 35 330 415 460 530 => describe table false Details #Credit \"Date[MM dd]\" *#Balance\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 $DebitsLeft $DateLeft 460 530 => describe table false Details #Credit \"Date[MM dd]\" *#Balance','2024-01-04 06:32:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10221,'StandardBank_Tiered','$source = \"StandardBank_Tiered\"\n\n// Get account name\n$accountName = get line starting \"Name of account:\" => get words after \"Name of account:\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number:\" => get words after \"Account number:\" => get text\n\n// Get Period from\n$periodFrom = get line containing \"Statement opening balance\" => get words before \"Statement opening balance\" => get date \"yyyy MM dd\"\n\n// Get opening balances\n//$openingBalance = get line containing \"Statement opening balance\" => get words after \"Statement opening balance\"  => skip words 2 => get decimal\n$openingBalance = get line containing \"Statement opening balance\" => get words after \"Statement opening balance\"  => take last words 1 => get decimal\n\n//Get period to\n//$periodTo = get last line containing \"Month end balance\" => get words before \"Month end balance\" => get date \"yyyy MM dd\"\n$periodTo = get last line containing \"Balance as at\" => get words after \"Balance as at\" => take words 3 => get date \"dd MMMM yyyy\"\n\n//Get Closing Balance\n//$closingBalance = get last line containing \"Month end balance\" => get words after \"Month end balance\" => skip words 1 => get decimal\n$closingBalance = get last line containing \"Balance as at\" => get words after \"Balance as at\" => take last words 2 => get decimal\n\ngo to page 1\ndelete all lines containing \"Month end balance\"\ndelete all lines containing \"Rate changed\"\n\n// Get start & end of transactions table\n@transactionsTop = get line containing \"Statement opening balance\"  => bottom => get line below\n//@transactionsBottom = get last line containing \"Month end balance\"\n@transactionsBottom = get last line containing \"Balance as at\" => top => get line above\n\n// Discard page header\ngo to page 1\nget line containing \"Statement opening balance\" => top => ignore header above\n\nget line starting \"Please verify all transactions\" => bottom => ignore footer below\ndelete all lines starting \"Please verify all transactions\"\n//delete all lines starting \"Balance as at\"\ndelete all lines starting \"## These fees include VAT\"\ndelete all lines starting \"Interest payment details\"\n\n// Remove unwanted lines\ndelete all lines containing \"Date Transaction description\"\ndelete all lines containing \"Statement opening balance\"\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 60 108 275 360 425 480 560 => describe table false \"*Date[yyyy MM dd]\" Details #Debit #Credit - #Balance','2025-06-25 11:51:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10222,'PostFinance_French','$source = \"PostFinance\"\n\ndelete text in box on every page page.top page.bottom page.left 50\n\n$periodfrom = get line starting \"Extrait de compte\" => get words between \"Extrait de compte\" \"-\" => get date \"dd.MM.yyyy\"\n$periodto = get line starting \"Extrait de compte\" => get words after \"-\" => take words 1 => get date \"dd.MM.yyyy\"\n\n$accountnumber = get line containing \"Numéro de compte\" => get words after \"Numéro de compte\" => get text\n$accountname = get text in box 650 615 55 132 => take words 2 => get text\n\ngo to page 1\n$openingbalance = get line containing \"Etat de compte\" => get words after \"Etat de compte\" => get decimal\n$closingbalance = get last line containing \"Etat de compte\" => get words after \"Etat de compte\" => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Date Texte Crédit Débit\" => bottom => get line below\n@transactionsBottom = get last line containing \"Etat de compte\" => top => get line above\n\ndelete all lines containing \"Etat de compte\"\ndelete all lines containing \"Total\"\ndelete all lines containing \"Extrait de compte\"\ndelete all lines containing \"IBAN\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"Date Texte Crédit Débit\" \n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 105 290 370 445 490 580 => describe table false \"Date[dd.MM.yy]\" Details *#Credit *#Debit - #Balance','2021-09-14 06:44:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10223,'SainsBury_CreditCard','$source = \"SainsBury_CreditCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 30\nset negative marker \"CR\"\n\ngo to page 1\n$accountName = get line containing \"Account name:\" => get words after \"Account name:\"  => take words 2 => get text\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 4 => get text\n\ngo to page 1\n$periodTo = get line containing \"Your credit card statement\" => get words after \"Your credit card statement\"  => take words 3 => get date \"d MM yyyy\"\n\ngo to page 1\n// Get opening and closing balances\n@openingBalanceTop = get line containing \"Previous balance\" => top\n@openingBalanceBottom = get line containing \"Previous balance\" => bottom\n$openingBalance = get text in box @openingBalanceTop @openingBalanceBottom page.middleX page.right => get words after \"Previous balance\" => get words before \"Payments\" => get decimal\n$closingBalance = get line starting \"Your closing balance\" => get words after \"Your closing balance\" => get decimal\n\n@transactionsTop = get line starting \"Debit date Description Amount\" => bottom => get line below => bottom => get line below\n@top1 = get line starting \"Debit date Description Amount\" => bottom\n@UserTop = get line starting \"Debit date Description Amount\" => bottom => get line below => top\n@UserBottom = get line starting \"Debit date Description Amount\" => bottom => get line below => bottom\n$delete1 = delete text in box @UserTop @UserBottom page.left page.right => get text\n\n@UserTop2 = get line ending \"CR\" => top => get line above => top\n@UserBottom2 = get line ending \"CR\" => top => get line above => bottom\n$delete2 = delete text in box @UserTop2 @UserBottom2 page.left page.right => get text\n\n@transactionsBottom = get last line containing \"Dispute resolution\" => top => get line above\n\nignore footer below 75\nignore header above 695\ndelete all lines starting \"Debit date Description Amount\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 59 105 470 580 630  => describe table false \"Date[dd MMM]\" Details *#Credit\n\ngo to page 1\ndelete all lines ending \"CR\"\ngo to page 2\n$periodFrom = get line below @top1 => take words 2 => get date \"dd MMM\"','2025-01-23 08:25:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10224,'SuncorpBank_Aus','$source = \"SuncorpBank_Aus\"\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n// Get account name and number\n\n\n//@accountNumbertext = get line starting \"Account Number\" => get words after \"Account Number\"\n//$accountNumber = take words @accountNumbertext 1 => get text\n\n@accountNumberTop = get line containing \"Account Number\" => top\n@accountNumberBottom = get line containing \"Account Number\" => bottom\n$accountNumber = get text in box @accountNumberTop @accountNumberBottom 0 page.middleX => get words after \"Account Number\" => take words 1 => get text\n\n//$accountName = get line containing \"suncorp.com.au\" => if not found then blank => bottom => get line below => get text\ndelete all lines starting \"Business Premium Statement\"\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n\n// Get period from\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => get words before \"-\" => get date \"d/MM/yyyy\"\n\n// Get period to\n$periodTo = get line containing \"Statement Period\" => take last words 1 => get date \"d/MM/yyyy\"\n\n//Get Opening & Closing balance\n@openingbalancetext = get line starting \"Opening Balance\" => get words after \"Opening Balance\"\n$openingbalance = take words @openingbalancetext 1 => get decimal\n\n@closingbalancetext = get line starting \"Closing Balance\" => get words after \"Closing Balance\"\n$closingbalance = take words @closingbalancetext 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line starting \"Date Transaction Details Withdrawal\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"CLOSING BALANCE\" => top => get line above\n\n// delete random top line number\ngo to page 1\n//delete text in box on every page page.top 790 page.left page.right\ndelete text in box on every page page.top 790 0 page.right\n\ndelete all lines starting \"Opening Balance\"\ndelete all lines starting \"BALANCE CARRIED FORWARD\"\ndelete all lines starting \"Details are continued\"\ndelete all lines starting \"Statement No:\"\ndelete all lines starting \"Date Transaction Details\"\ndelete all lines starting \"BALANCE BROUGHT FORWARD\"\ndelete all lines starting \"suncorp.com.au\"\ndelete all lines starting \"Opening Balance\"\ndelete all lines containing \"Account Transactions Continued\"\ndelete all lines starting \"Statement No:\"\ndelete all lines containing \"Details are continued on the back of this page\"\ndelete all lines starting \"Suncorp Bank (Norfina Limited\"\ndelete all lines starting \"The SUNCORP brand and Sun Logo\"\ndelete all lines starting \"part of the Suncorp Group\"\ndelete all lines starting \"INTEREST RATE OF\"\ndelete all lines starting \"TO DEBIT BALANCE FROM\"\nignore footer below 65\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 100 295 400 490 580 => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit *#Balance','2025-05-06 06:26:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10225,'Citi_Bank_CreditCard_Promo','$source = \"Citi_Bank_CreditCard_Promo\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\n\n$accountNumber = get line containing \"Account number ending in\" => get words after \"Account number ending in:\" => take words 1 => get text\n\ngo to page 1\n$accountname = get line containing \"Account number ending in\" => top => get line above => take words 2 => get text\n\n$periodto = get line containing \"New balance as of\" => get words after \"New balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\ndelete text in box 660 560 page.left 385\n\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"New balance\" => get words after \"New balance\" => get decimal\n\n\ndelete all lines containing \"Page\"\ndelete all lines containing \"services\"\n\ngo to page 2\ndelete text in box page.top page.bottom 410 page.right\n$standard = get line starting \"Promo Purchase-Offer\" => bottom \n$standard2 = get line starting \"Promo Purchase-Offer\" => bottom => get line below => bottom\n$periodfrom = get text in box $standard $standard2 10 150 => take words 1 => get date \"MM/dd\"\n\ngo to page 1\n$name1 = get line containing \"New Charges\" => bottom => get line below => get words before \"Card\" => get text\n\n\ngo to page 1\n$transactionstop = get line containing \"Payments, Credits and Adjustments\" => top => get line below\n$transactionsbottom = get line containing \"totals year-to-date\" => top => get line above\n\ndelete text in box on every page page.top 700 page.left page.right\n\ndelete all lines containing \"Description\"\ndelete all lines containing \"Trans. Post\"\ndelete all lines containing \"Purchase-Offer\"\ndelete all lines containing \"Fees charged\"\ndelete all lines containing \"Interest Charged\"\ndelete all lines containing \"Fees charged\"\ndelete all lines containing \"Interest charged\"\ndelete all lines containing \"TOTAL\"\ndelete all lines containing \"Total\"\ndelete all lines containing $name1\ndelete all lines containing $accountname\ndelete all lines containing \"No Activity\"\n\n\n$transactions = get multi page table $transactionstop $transactionsbottom 50 93 137 130 325 410 => describe table false \"*TransDate[MM/dd]\" \"*Date[MM/dd]\" - Details #Credit','2021-10-04 06:56:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10226,'Citi_Bank_CreditCard_Standard','$source = \"Citi_Bank_CreditCard_Standard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 31\r\n\r\n//Get Account Number and Name\r\n$accountNumber = get line containing \"Account number ending in\" => get words after \"Account number ending in:\" => take words 1 => get text\r\ngo to page 1\r\n$accountName = get line containing \"Account number ending in\" => top => get line above => take words 2 => get text\r\n\r\n// Get Period TO\r\n$PeriodTo = get line containing \"New balance as of\" => get words after \"New balance as of\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n//Get Opening and Closing Balance\r\ndelete text in box 660 430 page.left 385\r\ndelete text in box on every page page.top page.bottom 0 40\r\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"New balance\" => get words after \"New balance\" => get decimal\r\n\r\ndelete text in box on every page page.top page.bottom 410 page.right\r\ndelete all lines containing \"Page\"\r\ndelete all lines containing \"services\"\r\n\r\n//Get Period From\r\ngo to page 2\r\ndelete text in box page.top page.bottom 410 page.right\r\n$standard = get line starting \"Standard Purchases\" => bottom\r\n$standard2 = get line starting \"Standard Purchases\" => bottom => get line below => bottom\r\n$standard3 = get line starting \"Standard Purchases\" => get words before \"Purchases\" => take words 1 => right => add 35\r\n$PeriodFrom = get text in box $standard $standard2 10 $standard3 => take words 1 => get date \"MM/dd\"\r\n\r\n// Dynamic Coordinates\r\n$DateRight = get text in box $standard $standard2 80 137 => take words 1 => right => add 12\r\n\r\ngo to page 1\r\n$name1 = get line containing \"New Charges\" => bottom => get line below => get words before \"Card\" => get text\r\n\r\n@Deltxt1 = get line starting \"NOTICE OF CHANGES\" => top\r\n@Deltxt2 = get line starting \"Account Summary\" => top\r\ndelete text in box @Deltxt1 @Deltxt2 0 410\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Payments, Credits and Adjustments\" => top => get line below\r\n@transactionsBottom = get last line starting \"Fees\" => top => get line above\r\n\r\n@Feestop = get last line starting \"Fees\" => bottom => get line below\r\n@InterestBottom =  get line containing \"totals year-to-date\" => top => get line above\r\n\r\ndelete text in box on every page page.top 715 page.left page.right\r\n\r\ndelete all lines containing \"Payments, Credits and Adjustments\"\r\ndelete all lines containing \"Description\"\r\ndelete all lines containing \"Trans. Post\"\r\ndelete all lines containing \"Purchase-Offer\"\r\ndelete all lines containing \"Fees Charged\"\r\ndelete all lines containing \"Interest Charged\"\r\ndelete all lines containing \"Fees charged\"\r\ndelete all lines containing \"Interest charged\"\r\n\r\n\r\n//delete all lines containing \"TOTAL\"\r\n//delete all lines containing \"Total\"\r\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\r\ndelete all lines containing \"TOTAL INTEREST FOR THIS PERIOD\"\r\ndelete all lines containing \"Total fees charged in\"\r\ndelete all lines containing \"Total interest charged in\"\r\ndelete all lines starting \"Cash Advances\"\r\ndelete all lines containing $name1\r\ndelete all lines containing $accountName\r\ndelete all lines containing \"No Activity\"\r\ndelete all lines containing \"Purchases Prior to\"\r\ndelete all lines containing \"Standard Purchases\"\r\n\r\nignore header above 715\r\n\r\n// Read the transactions\r\n//@transactions = get multi page table @transactionstop @transactionsbottom 50 93 137 130 329 410 => describe table false \"*TransDate[MM/dd]\" \"*Date[MM/dd]\" - Details #Credit\r\n@transactions = get multi page table @transactionsTop @transactionsBottom 50 90 $DateRight 125 329 410 => describe table false \"*TransDate[MM/dd]\" \"*Date[MM/dd]\" - Details #Credit\r\n@FeeInterestTable = get multi page table @Feestop @InterestBottom 50 93 $DateRight 115 329 410 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" - Details #Credit\r\n\r\n// combine the transactions\r\n$transactions = combine described tables @transactions @FeeInterestTable','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10227,'Citi_Bank_CreditCard_promo_Standard','$source = \"Citi_Bank_CreditCard_promo_Standard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\n\n$accountNumber = get line containing \"Account number ending in\" => get words after \"Account number ending in:\" => take words 1 => get text\n\ngo to page 1\n$accountname = get line containing \"Account number ending in\" => top => get line above => take words 2 => get text\n\n$periodto = get line containing \"New balance as of\" => get words after \"New balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\ndelete text in box 660 560 page.left 385\n\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"New balance\" => get words after \"New balance\" => take words 1 => get decimal\n\n\ndelete all lines containing \"Page\"\ndelete all lines containing \"services\"\n\n\n\ngo to page 2\ndelete text in box page.top page.bottom 410 page.right\n$standard = get line containing \"Payments, Credits and Adjustments\" => bottom\n$standard2 = get line containing \"Payments, Credits and Adjustments\"  => bottom => get line below => bottom\n$periodfrom = get text in box $standard $standard2 10 150 => take words 1 => get date \"MM/dd\"\n\ngo to page 1\n$name1 = get line containing \"New Charges\" => bottom => get line below => get words before \"Card\" => get text\n\ngo to page 1\n$transactionstop = get line containing \"Payments, Credits and Adjustments\" => top => get line below\n$transactionsbottom = get line starting \"Fees\" => top => get line above\n\n@Feestop = get last line starting \"Fees\" => bottom => get line below\n@Intrestbottom =  get line containing \"totals year-to-date\" => top => get line above\n\ndelete text in box on every page page.top 700 page.left page.right\n\ndelete all lines containing \"Description\"\ndelete all lines containing \"Trans. Post\"\ndelete all lines containing \"Purchase-Offer\"\ndelete all lines containing \"Fees charged\"\ndelete all lines containing \"Interest Charged\"\ndelete all lines containing \"Fees charged\"\ndelete all lines containing \"Interest charged\"\ndelete all lines containing \"TOTAL\"\ndelete all lines containing \"Total\"\ndelete all lines containing $name1\ndelete all lines containing $accountname\ndelete all lines containing \"No Activity\"\ndelete all lines starting \"Balance Transfer-Offer\"\n\n\n@transactions = get multi page table $transactionstop $transactionsbottom 50 93 137 130 325 410 => describe table false \"*TransDate[MM/dd]\" \"*Date[MM/dd]\" - Details #Credit\n\n@FeeIntresttable = get multi page table @Feestop @Intrestbottom 50 93 137 115 329 410 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" - Details #Credit\n$transactions = combine described tables @transactions @FeeIntresttable','2025-04-15 05:12:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10228,'Public_Bank','$source = \"Public_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n$accountName = get line containing \"PENYATA AKAUN\" => take words 2 => get text\r\n\r\n@HeaderBottom = get line starting \"DATE TRANSACTION DEBIT CREDIT BALANCE\" => top\r\ndelete text in box page.top @HeaderBottom page.left page.middleX\r\n\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n\r\ngo to page 1\r\n// Get periodFrom and periodTo\r\n$periodFrom = get line containing \"Balance From Last Statement\" => bottom => get line below => take words 1 => get date \"d MM\"\r\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\"  => take words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening and closing balances\r\n$openingBalanceText = get line containing \"Balance From Last Statement\" => get words after \"Balance From Last Statement\"\r\n$openingBalance = get decimal $openingBalanceText\r\n$closingBalanceText = get line containing \"Closing Balance\" => get words after \"Closing Balance\"\r\n$closingBalance = get decimal $closingBalanceText\r\n\r\ngo to page 1\r\n@transactionsTop = get line starting \"DATE TRANSACTION DEBIT CREDIT BALANCE\" => bottom => get line below\r\n\r\n// Delete header\r\nget last line containing \"DATE TRANSACTION DEBIT\" => top => ignore header above\r\n\r\n//@tableHeader = get line containing \"Statement Date\" => bottom\r\n//delete text in box on every page page.top @tableHeader page.left page.right\r\n\r\ndelete all lines containing \"Statement Date\"\r\ndelete all lines containing \"Page\"\r\ndelete all lines starting \"DATE TRANSACTION DEBIT CREDIT BALANCE\"\r\ndelete all lines containing \"Balance From Last Statement\"\r\ndelete all lines containing \"Balance B/F\"\r\ndelete all lines containing \"Balance C/F\"\r\ndelete all lines starting \"Penyata ini dicetak\"\r\ndelete all lines starting \"TARIKH URUS NIAGA DEBIT\"\r\n\r\ngo to last page\r\n@transactionsBottom = get last line starting \"Closing Balance In This Statement\" => top => get line above\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 85 310 305 360 440 540 600 => describe table false \"Date[d MM]\" Details - #Debit #Credit *#Balance','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10229,'Public_Bank_enterprise','$source = \"Public_Bank_enterprise\"\n\n$accountName = get line containing \"Account No.\" => get words after \"Account No. / Name:\" => take words 4 => get text \n$accountNumber = get line starting \"Account No.\" => get words after \"Account No. / Name:\" => take words 1 => get text \n\ngo to page 1\n$periodFrom = get line containing \"From Date\" => get words after \"From Date\" => take words 3 => get date \"d MM yyyy\"\n\n$periodTo = get line containing \"To Date\" => get words after \"To Date\" => take words 3 => get date \"d MM yyyy\"\n\n// Get opening and closing balances\n$openingBalanceText = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" \n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\"\n$closingBalance = get decimal $closingBalanceText\n\n\ngo to page 1\n@transactionsTop = get line starting \"Transaction Date Transaction Description\" => bottom => get line below\n\n//@tableHeader = get line containing \"Statement Date\" => bottom\n//delete text in box on every page page.top @tableHeader page.left page.right\n\n\ndelete all lines starting \"Transaction Date Transaction Description\"\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines starting \"Copyright ©\"\ndelete all lines starting \"Note: This is a computer\"\ndelete all lines containing \"CLOSING BALANCE\"\ndelete all lines starting \"Printed Date\"\n\n\n\ngo to last page\n@transactionsBottom = get last line starting \"CLOSING BALANCE\" => top => get line above\n\n// Read the transactions\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 98 298 387 474 560 600 => describe table false \"Date[d MM yyyy]\" Details #Debit #Credit *#Balance','2021-09-21 03:59:34',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10230,'CIBC_Card','$source = \"CIBC_Card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\ndelete rotated words\nset negative marker \"CR\"\n\n@info = get text in box page.top 610 380 page.right\n\n// Get account name and number\n$accountName = get words before @info \"Account number\" => get text\n//$accountNumber = get words after @info \"Account number\" => get words before \"Statement Date\" => get text\n@AcTop = get words after @info \"Account number\" => take words 1 => top => add 2\n@AcBottom = get words after @info \"Account number\" => take words 1 => bottom => subtract 2\n@AcLeft = get words after @info \"Account number\" => take words 1 => left => subtract 2\n$accountNumber = get text in box @AcTop @AcBottom @AcLeft page.right => get text\n\n// Get period from/to\n//$periodFrom = get words after @info \"statement period\" => take words 2 => get date \"MMMM d\"\n//$periodTo = get words after @info \"Statement Date\" => take words 3 => get date \"MMMM d, yyyy\"\n$periodFrom = get line containing \"Transactions from\" => get words after \"Transactions from\" => take words 2 => get date \"MMMM d\"\n$periodTo = get line containing \"Transactions from\"  => take last words 3 => get date \"MMMM d, yyyy\"\n\ngo to page 1\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n//$closingBalance = get last line containing \"Total balance =\" => get words after \"Total balance =\" => take words 1 => get decimal\n$closingBalance = get last line containing \"balance =\" => get words after \"balance =\" => take words 1 => get decimal\n\ngo to page 1\n//delete extra lines\ndelete all lines starting \"Trans Post\"\ndelete all lines starting \"date date Description\"\n\n//payments table\n@paymentTransactionTop = get line starting \"Your payments\" => if not found then blank => bottom => get line below\n@paymentTransactionBottom = get line starting \"Total payments\" => if not found then blank => top => get line above\n\n//payment transactions\n@paymentTransactions = get multi page table @paymentTransactionTop @paymentTransactionBottom 25 70 115 480 580 => describe table false - \"Date[MMM d]\" Details *#Debit\n\n\n//interest table\n@interestTransactionTop = get line starting \"Your interest\" => if not found then blank => bottom => get line below\n@interestTransactionBottom = get line starting \"Total interest this period\" => if not found then blank => top => get line above\n\n//interest transactions\n@interestTransactions = get multi page table @interestTransactionTop @interestTransactionBottom 25 70 115 330 450 580 => describe table false - \"Date[MMM d]\" Details - *#Credit\n\ndelete all lines starting \"Page\"\ndelete all lines starting \"Card number\"\ndelete all lines starting \"Total for\"\ndelete all lines containing \"Identifies Cash Back Multiplier transactions\"\ndelete all lines containing \"same rate(s)\"\ndelete all lines containing \"** Denotes transaction in foreign currency\"\n\ndelete all lines containing \"Identifies Bonus Aeroplan\"\ndelete all lines containing \"Any returns/credits\"\ndelete all lines containing \"Aeroplan points\"\ndelete all lines ending \"same rate.\"\n\n//new charges and credits table\n@newTransactionTop = get line starting \"Your new charges and credits\" => if not found then blank => bottom => get line below\n@newTransactionBottom = get line starting \"Information about your\" => if not found then blank => top => get line above\n//@newTransactionBottom = get last line starting \"Total for\" => top => get line above\n\n//delete extra lines\n@footerBelow = get line starting \"Information about your\" => top\ndelete text in box @footerBelow page.bottom page.left page.right\n//ignore footer below @footerBelow\nignore footer below 25\n\n//delete all lines starting \"Information about your\"\n//delete all lines starting \"Your new charges and credits\"\ndelete all  lines containing \"Account number\"\ndelete all lines Containing \"transactions that have earned\"\ndelete all lines Containing \"are deducted at the same rate\"\n\n//transactions\n@newTransactions = get multi page table @newTransactionTop @newTransactionBottom 25 70 115 330 480 600 => describe table false - \"Date[MMM d]\" Details - *#Credit\n\n//Your new charges and credits (continued) table 1\n//@new1TransactionTop = get line starting \"Your new charges and credits (continued)\" =>  bottom => get line below\n//@new1TransactionBottom = get last line starting \"Total for\" => top => get line above\n@new1Trans = get line starting \"Your new charges and credits (continued)\" => top\n@new1TransactionTop = get line starting \"Your new charges and credits (continued)\" => if not found then blank =>  bottom => get line below\n@new1TransactionBottom = get line above 25\n\n@new1Transactions = get multi page table @new1TransactionTop @new1TransactionBottom 60 105 150 360 520 600 => describe table false - \"Date[MMM d]\" Details - *#Credit\ndelete text in box @new1Trans page.bottom page.left page.right\n\n//Your new charges and credits (continued) table 2\n@new2Trans = get line starting \"Your new charges and credits (continued)\" => top\n@new2TransactionTop = get line starting \"Your new charges and credits (continued)\" => if not found then blank =>  bottom => get line below\n@new2TransactionBottom =  get line above 25\n@new2Transactions = get multi page table @new2TransactionTop @new2TransactionBottom 25 70 115 330 480 600 => describe table false - \"Date[MMM d]\" Details - *#Credit\ndelete text in box @new2Trans page.bottom page.left page.right\n\n//Your new charges and credits (continued) table 3\n@new3Trans = get line starting \"Your new charges and credits (continued)\" => top\n@new3TransactionTop = get line starting \"Your new charges and credits (continued)\" => if not found then blank =>  bottom => get line below\n@new3TransactionBottom =  get line above 25\n@new3Transactions = get multi page table @new3TransactionTop @new3TransactionBottom 60 105 150 360 520 600 => describe table false - \"Date[MMM d]\" Details - *#Credit\ndelete text in box @new3Trans page.bottom page.left page.right\n\n//remove extra bottom\n@extraBottom = get line starting \"CIBC CreditSmartTM* Spend Report\" => top\ndelete text in box @extraBottom page.bottom page.left page.right\n\n//all transactions\n$transactions = combine described tables @paymentTransactions @interestTransactions @newTransactions @new1Transactions @new2Transactions @new3Transactions','2024-10-17 08:41:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10231,'BBVA_US_PDFium','$source = \"BBVA_US_PDFium\"\n $features = \"NO_TRANSACTION_YEAR\"\n $periodBufferDays = 31\n\n \n // Get account name and number\n $accountNumber = get last line containing \"Account Number:\" => get words after \"Account Number:\" => get words before \"-\" => get text\n $accountName = get last line containing \"Account Number:\" => get words after \"-\" => get text\n \n // Get period from\n $periodFrom = get line containing \"Beginning\" => get words after \"Beginning\" => get words before \"- Ending\" => get date \"MMMM d, yyyy\"\n \n // Get period to\n //$periodTo = get line containing \"Ending\" => get words after \"Ending\" => get date \"MMMM d, yyyy\"\n @periodToText = get line containing \"Ending\" => get words after \"Ending\"\n $periodTo = take words @periodToText 3 => get date \"MMMM dd, yyyy\"\n \n //Get Opening & Closing balance\n @openingbalancetext = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\"  => get words before \"Interest paid this\"\n $openingbalance = take last words @openingbalancetext 1 => get decimal\n \n @closingbalancetext = get line containing \"Ending Balance on\" => get words after \"Ending Balance on\"\n $closingbalance = take last words @closingbalancetext 1 => get decimal\n \n // Get start of table\n go to page 1\n @transactionsTop = get line containing \"Credits Debits Balance\" => bottom => get line below\n \ndelete all lines starting \"Page\"\ndelete all lines starting \"Primary Account\"\ndelete all lines starting \"Beginning\"\ndelete all lines containing \"Check/ Deposits\"\ndelete all lines starting \"Date * Serial\"\n\n\n // Get end of table\n @transactionsBottom = get last line containing \"Ending Balance on\" => top => get line above\n \n // Read the transactions\n \n //$transactions = get multi page table @transactionsTop @transactionsBottom  0 85 130 330 390 430 500 => describe table false \"*Date[M/d]\"  Serial  Description #Credit #Debit #Balance\n\n $transactions = get multi page table @transactionsTop @transactionsBottom  0 85 120 337 390 440 505 => describe table false \"*Date[M/d]\" ChequeNumber Details #Credit #Debit #Balance\n\n ','2025-07-31 08:11:06',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10232,'HSBC_Commercial_Credit_Card','$source = \"HSBC_Commercial_Credit_Card\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 30\nset negative marker \"CR\"\n\n$accountname = get text in box page.top 600 page.left 300 => take words 3 => get text\n\ngo to page 1\n$openingbalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n$closingbalance = get line containing \"New Balance\" => get words after \"New Balance\" => get decimal\n\n$periodto = get line containing \"Statement Date\" => get words after \"Statement Date\"  => get words before \"Account number\" => get date \"dd MMMM yyyy\"\n\ngo to page 2\n$accountnumber = get text in box 480 465 340 440 => get text\n//$cardnumber = get line containing \"Card number\" => bottom => get line below => get text\n$cardnumber = get line containing \"Card number\" => top => get line above => bottom => get line below => bottom => get line below => get text\n\ngo to page 1\n@IntrestTableTop = get line starting \"Summary Of Interest On This Statement\" => if not found then blank => bottom => get line below\n@IntrestTableBottom = get line starting \"TOTAL INTEREST CHARGED ON THIS STATEMENT\" => if not found then blank => top => get line above\n$transactionsIntrest = get multi page table @IntrestTableTop @IntrestTableBottom 0 170 470 580 => describe table false - Details *#Credit\n\n@transactionsTopTable1 = get line containing \"Received By Us Transaction Date Details\" => bottom => get line below\n@transactionsBottomTable1 = get last line containing \"Summary Of Employee Details\" => top => get line above\n\ndelete all lines starting \"Summary Of Interest On This Statement\"\ndelete all lines starting \"Statement Date\"\ndelete all lines starting \"NO INTEREST CHARGED ON THIS STATEMENT\"\ndelete all lines starting \"Estimated interest - next month\"\ndelete all lines starting \"Interest on Standard Balance (Cash) at\"\ndelete all lines starting \"Interest on Standard Balance (Purchases) at\"\ndelete all lines containing \"We now provide more information about\"\ndelete all lines containing \"If you would like to know more about how the cost\"\ndelete all lines containing \"Exchange Rate(s) issued by the\"\ndelete all lines containing \"https://www.hsbc.co.uk/international/using-your-card-abroad\"\ndelete all lines containing $accountnumber\ndelete all lines containing \"Card number\"\ndelete all lines containing $cardnumber\n//ignore header above 770\ndelete all lines starting \"Mr\"\ndelete all lines starting \"Mrs\"\ndelete all lines starting \"MR\"\ndelete all lines starting \"MRS\"\ndelete all lines starting \"Ms\"\ndelete all lines starting \"MS\"\ndelete all lines starting \"Miss\"\ndelete all lines containing \"Sheet number\"\ndelete all lines containing \"Your Commercial Card Statement\"\ndelete all lines containing \"NOT TO BE ACCEPTED AS PERSONAL IDENTIFICATION\"\ndelete all lines containing \"Contact\"\ndelete all lines containing \"From Overseas\"\ndelete all lines containing \"Lost and Stolen Cards\"\ndelete all lines containing \"From Overseas\"\ndelete all lines containing \"Text Phone\"\ndelete all lines containing \"www.hsbc.co.uk\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Debits\"\ndelete all lines containing \"Credits\"\ndelete all lines containing \"New Balance\"\ndelete all lines containing \"Your Credit Limit\"\ndelete all lines containing \"used by deaf or speech\"\ndelete all lines containing \"Account Summary\"\ndelete all lines containing \"UK tel:\"\ndelete all lines containing \"(24 Hrs)\"\n\ngo to page 1\n$transactions1 = get multi page table @transactionsTopTable1 @transactionsBottomTable1 0 110 170 430 580 => describe table false \"Date[dd MMM yy]\" \"TransactionDate[dd MMM yy]\" Details *#Credit\n\ngo to page 1\n@periodfromText = get line containing \"Received By Us Transaction Date\" => bottom => get line below\n@periodfrom1 = take words @periodfromText 6\n$periodfrom = take last words @periodfrom1 3 => get text\n\ngo to page 2\n//$deleteSummary =  get line containing \"Your Transaction Details\" => top\n$deleteSummary = get line containing \"Your Transaction Details\" => bottom => get line below => bottom\n$D1 = delete text in box $deleteSummary page.bottom page.left page.right => get text\n$deleteSummary1 = get line containing \"Payment Summary\" => top\n$D2 = delete text in box $deleteSummary1 page.bottom page.left page.right => get text\n\n@transactionsTopTable2 = get line containing \"Received By Us Transaction Date Details\" => bottom => get line below\n@transactionsBottomTable2 = get line containing \"Summary Box\" => top => get line above\n\ngo to page 1\n$delSummary2 = get line containing \"Summary Box\" => top\n$D3 = delete text in box $delSummary2 page.bottom page.left page.right => get text\n\n//go to page 1\n//@periodfromText = get line containing \"Received By Us Transaction Date\" => bottom => get line below\n//@periodfrom1 = take words @periodfromText 6\n//$periodfrom = take last words @periodfrom1 3 => get text\n\ndelete all lines starting \"Received By Us Transaction Date\"\ndelete all lines starting \"Your Transaction Details\"\nignore header above 770\n\n$transactions2 = get multi page table @transactionsTopTable2 @transactionsBottomTable2 0 110 170 430 580 => describe table false \"Date[dd MMM yy]\" \"TransactionDate[dd MMM yy]\" Details *#Credit\n$transactions = combine described tables $transactions1 $transactionsIntrest $transactions2','2025-05-22 07:20:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10233,'Silicon_Valley_Bank','$source = \"Silicon_Valley_Bank\"\n\nset negative marker \"-\"\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n// Get account number\n$accountnumber = get line containing \"Account Summary\" => top => get line above => take last words 1 => get text\n\n// Get account name\n//$accountname = get line containing \"Toll-Free:\" => get words before \"Toll-Free:\" => get text\n@accountnametop = get line containing \"Managing Your Accounts\" => bottom => get line below => bottom\n@accountnamebottom = get line containing \"Managing Your Accounts\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => bottom\n$accountname  = get text in box @accountnametop @accountnamebottom page.left page.middleX => get text\n\n// Get Period\n$periodfrom = get last line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM dd yyyy\"\n$periodto = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => get date \"MM dd yyyy\"\n\n// Get opening and closing balance\n$openingbalance = get last line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => get decimal\n$closingbalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\n// Get transaction table start and end\ngo to page 1\n//@transactionstop = get line starting \"Transaction Date Description Debits\" => bottom => get line below\n@transactionstop = get line containing \"Description Debits\" => bottom => get line below\n@transactionsbottom = get last line containing \"Ending Balance\" => top => get line above\n\n// delete random top line text\ngo to page 1\ndelete text in box on every page 16 6.5 page.left page.right\n//$delete = get text in box 16 6.5 page.left page.right => get text\ndelete text in box on every page 760 735 page.left page.right\n//$delete = get text in box 760 735 page.left page.right => get text\n\ndelete all lines containing \"Beginning Balance\"\ndelete all lines starting \"Transaction Date Description Debits\"\ndelete all lines starting \"Reporting Activity\"\ndelete all lines containing \"(continued)\"\n\nremove page 2\n\n// Read the transactions\n//$transactions = get multi page table @transactionstop @transactionsbottom 0 95 310 405 489 565 => describe table false \"Date[MM dd yyyy]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionstop @transactionsbottom 0 95 310 410 489 580 => describe table false \"Date[MM dd yyyy]\" Details #Debit #Credit *#Balance','2023-08-18 07:51:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10234,'AmericanExpress_Au','$source = \"AmericanExpress_Au\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 30\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get account name\n$actop = get line starting \"Prepared for\" => bottom\n$acbottom = get line starting \"Prepared for\" => bottom => get line below => bottom\n$accountName = get text in box $actop $acbottom page.left 200 => get text\n\n@DelMainAccountName = get line starting \"Prepared for\"\n@DelMainAccountNameL1 = bottom @DelMainAccountName => get line below => take words 3 => get text\n@DelMainAccountNameL2 = bottom @DelMainAccountName => get line below => bottom => get line below => take words 3 => get text\n@DelMainAccountNameL3 = bottom @DelMainAccountName => get line below => bottom => get line below => bottom => get line below => take words 3 => get text\n@DelMainAccountNameL4 = bottom @DelMainAccountName => get line below => bottom => get line below => bottom => get line below => bottom => get line below => take words 3 => get text\n\ngo to page 1\n// Get period from/to\n//$periodFrom = get line starting \"New Transactions for\" => bottom => get line below => bottom => get line below => take words 2 => get date \"MMMM d\"\n//$periodTo = get line starting \"Prepared for\" => bottom => get line below => take last words 3 => get date \"MMMM d,yyyy\"\n@Datestop = get line containing \"Statement Period\" => top\n@Datesbottom = get line containing \"Statement Period\" => bottom\n@Dates = get text in box @Datestop @Datesbottom 160 330\n$periodFrom = get words after @Dates \"From\" => get words between \"From\" \"to\" => get date \"MMMM d\"\n$periodTo = get words after @Dates \"to\"  => take words 3 => get date \"MMMM d yyyy\"\n\ngo to page 1\n// Get account number\n//$accountNumber = get text in box $actop $acbottom 215 315  => get text\n@topAcc = get line containing \"Membership Number Date\" => top\n@bottomAcc = get line containing \"XXX\" => bottom => get line below => top\n$accountNumber = get text in box @topAcc @bottomAcc page.left 400 => take last words 1 => get text\n\n// Get opening and closing balances\ngo to page 1\n@linedel = get line starting \"Opening Balance\"\n@leftbal = left @linedel => add -20\n@topline = bottom @linedel\n@botline = bottom @linedel => get line below => bottom\ndelete text in box @topline @botline page.left @leftbal\n\n@bal = get line starting \"Opening Balance\" => bottom => get line below\n$openingBalance = take words @bal 1 => get decimal\n$closingBalance = take last words @bal 2 => take words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@firsttop = get line starting \"American Express Australia Limited ABN\" => top\ndelete text in box @firsttop page.bottom page.left page.right\n\n@summaryTOP = get line starting \"Please check all transactions carefully\" => top\ndelete text in box @summaryTOP page.bottom page.left page.right\n\ngo to page 1\n//@transactionsTop = get line starting \"Details Foreign Spending Amount $\" => bottom => get line below\n@transPayTop = get line starting \"Payments Section\" => if not found then blank => bottom => get line below\n@transPayBottom = get line starting \"Total of Payments\" => if not found then blank => top => get line above\n\n@transactionsTop = get line starting \"New Transactions for\" => bottom => get line below => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total of new transactions for\" => top => get line above\n\n@transotherTop = get line starting \"OTHER ACCOUNT TRANSACTIONS\" => if not found then blank => bottom => get line below\n@transotherBottom = get line starting \"Total of other account transactions\" => if not found then blank => top => get line above\n\n@transotherTop1 = get line starting \"OTHER ACCOUNT TRANSACTIONS\" => if not found then blank => bottom => get line below\n@transotherBottom1 = get line starting \"Total of Other Account Transactions\" => if not found then blank => top => get line above\n\ndelete all lines ending \"UNITED KINGDOM POUND STERLIN\"\ndelete all lines ending \"UNITED STATES DOLLAR\"\ndelete all lines ending \"EUROPEAN UNION EURO\"\ndelete all lines starting \"AUD\"\ndelete all lines starting \"Total of new transactions for\"\ndelete all lines starting \"New Transactions for\"\ndelete all lines starting \"Card Number\"\ndelete all lines containing \"Foreign Spending Amount $\"\ndelete all lines starting @DelMainAccountNameL1\ndelete all lines starting @DelMainAccountNameL2\ndelete all lines starting @DelMainAccountNameL3\ndelete all lines starting @DelMainAccountNameL4\n\nignore header above 720\nignore footer below 46\n\n// Read the transactions\n$transactionspay = get multi page table @transPayTop @transPayBottom 0 79 410 480 550 => describe table false \"*Date[MMMM d]\" Details - #Credit\n$transactionsdebit = get multi page table @transactionsTop @transactionsBottom 0 79 410 480 550 => describe table false \"*Date[MMMM d]\" Details - #Credit\n$transactionsother = get multi page table @transotherTop @transotherBottom 0 79 410 480 550 => describe table false \"*Date[MMMM d]\" Details - #Credit\n$transactionsother1 = get multi page table @transotherTop1 @transotherBottom1 0 79 410 480 550 => describe table false \"*Date[MMMM d]\" Details - #Credit\n\n$transactions = combine described tables $transactionspay $transactionsdebit $transactionsother $transactionsother1','2025-07-31 08:11:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10235,'FirstNationalBank_Loan','\n$source = \"FirstNationalBank\"\n$periodBufferDays = 14\nset negative marker \"Dr\"\n\n// Get account name\n$accountName = get text in box 720 660 0 400 => take words 5  => get text\n$accountnumber = get line starting \"Account Number :\" => get words after \"Account Number :\" => get words before \"Page\" => get text\n\n$openingbalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n$closingbalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\n$periodfrom = get line containing \"Opening Balance\" => get words before \"Opening Balance\"  => get date \"dd MMM yyyy\"\n$periodto = get last line containing \"Closing Balance\" => get words before \"Closing Balance\" => get date \"dd MMM yyyy\"\n\n\n@transactionsTop = get line starting \"Transaction Description Debits\" => bottom => get line below\n\n// Discard page footer\nignore footer below 60\n\n// Get end of table\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\ndelete all lines starting \"Account Number :\"\ndelete all lines starting \"Date R R R\"\ndelete all lines starting \"Transaction Description Debits\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines starting \"Transactions in\"\ndelete all lines containing \"Set Poi Status Mega\"\ndelete all lines containing \"Rate Change\"\ndelete all lines containing \"Set Paid Off Status\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"Interest 0.00Dr\"\ndelete all lines containing \"Interest 0.00Cr\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 325 385 470 575 => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 321 385 470 575 => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance\n','2025-05-22 07:20:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10236,'Oriental_Bank','$source = \"Oriental_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 30\n\n// Get period from/to\n$periodFrom = get line starting \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMMM dd, yyyy\"\n$periodTo = get line starting \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMMM dd, yyyy\"\n\n// Get account name\n$accountName = get text in box 620 570 90 195 => take words 3 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take words 1 => get decimal\n\n\n//get checks table left\n@leftChecksTransactionTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below \n@leftChecksTransactionBottom = get line starting \"DEBITS\" => top => get line above\n\ndelete all lines starting \"Number Date Amount\"\n\n//get debits transactions\n@transactionsLeftChecks = get multi page table @leftChecksTransactionTop @leftChecksTransactionBottom 90 160 240 310 => describe table false Details \"*Date[MM-dd]\" #Debit\n\n\n//get checks table right\n@rightChecksTransactionTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below \n@rightChecksTransactionBottom = get line starting \"DEBITS\" => top => get line above\n\ndelete all lines containing \"Skip in check sequence\"\n\n//get debits transactions\n@transactionsRightChecks = get multi page table @rightChecksTransactionTop @rightChecksTransactionBottom 290 360 440 520 => describe table false Details \"*Date[MM-dd]\" #Debit\n\n\n//delete extra texts\n@topText = get line containing \"Ending balance\" => bottom\ndelete text in box page.top @topText page.left page.right\ndelete all lines starting \"Date Description\"\nignore header above 635\nignore footer below 80\n\n//get debits table\n@debitTransactionTop = get line starting \"DEBITS\" => if not found then blank => bottom => get line below \n@debitTransactionBottom = get line starting \"CREDITS\" => top => get line above\n\ndelete all lines starting \"DEBITS\"\n@bottomText = get line starting \"DAILY BALANCES\" => bottom\ndelete text in box @bottomText page.bottom page.left page.right\n\ngo to page 1\n//get debits transactions\n@transactionsDebit = get multi page table @debitTransactionTop @debitTransactionBottom 90 140 440 530 => describe table false \"*Date[MM-dd]\" Details #Debit\n\n//get credits table\n@creditTransactionTop = get line starting \"CREDITS\" => if not found then blank => bottom => get line below \n@creditTransactionBottom = get line starting \"DAILY BALANCES\" => top => get line above\n\ndelete all lines starting \"CREDITS\"\ndelete all lines starting \"DAILY BALANCES\"\n\n//get credits transactions\n@transactionsCredit = get multi page table @creditTransactionTop @creditTransactionBottom 90 140 440 530 => describe table false \"*Date[MM-dd]\" Details #Credit\n\n//all transactions \n$transactions = combine described tables @transactionsLeftChecks @transactionsRightChecks @transactionsDebit @transactionsCredit\n','2021-09-27 06:30:12',0);
