t\n\n\n//delete extra texts\n@topText = get line starting \"DEBITS\" => top\ndelete text in box page.top @topText page.left page.right\ndelete all lines starting \"Date Description\"\nignore header above 635\nignore footer below 80\n\n//get debits table\n@debitTransactionTop = get line starting \"DEBITS\" => if not found then blank => bottom => get line below \n@debitTransactionBottom = get line starting \"CREDITS\" => top => get line above\n\ndelete all lines starting \"DEBITS\"\n@bottomText = get line starting \"DAILY BALANCES\" => bottom\ndelete text in box @bottomText page.bottom page.left page.right\n\ngo to page 1\n//get debits transactions\n@transactionsDebit = get multi page table @debitTransactionTop @debitTransactionBottom 90 120 435 530 => describe table false \"*Date[MM-dd]\" Details #Debit\n\n//get credits table\n@creditTransactionTop = get line starting \"CREDITS\" => if not found then blank => bottom => get line below \n@creditTransactionBottom = get line starting \"DAILY BALANCES\" => top => get line above\n\ndelete all lines starting \"CREDITS\"\ndelete all lines starting \"DAILY BALANCES\"\n\n//get credits transactions\n@transactionsCredit = get multi page table @creditTransactionTop @creditTransactionBottom 90 120 435 530 => describe table false \"*Date[MM-dd]\" Details #Credit\n\n//all transactions \n$transactions = combine described tables @transactionsLeftChecks @transactionsRightChecks @transactionsDebit @transactionsCredit\n','2021-09-27 06:30:41',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10238,'RevolutBusiness_AccNumber','$source = \"RevolutBusiness\"\n$features = \"REVERSE_ORDER\"\n\ndelete white words\ndelete rotated words\n\ngo to page 1\n@a = get last line containing \"Money sent (MOS) Money received (MOR)\" => top\n@b = get last line containing \"ATM Withdrawals\" => bottom => get line below => bottom\n$try = get text in box @a @b page.left page.right\ndelete text in box @a @b page.left page.right\n\ngo to page 1\n$accountname = get line containing \"Account name\" => get words after \"Account name\" => get text\ndelete all lines containing \"name\"\n@accountnumberFooter = get line containing \"Sort code\" => top\n@accountnumberHeader = get line containing \"Account\" => top\n@infoLast = get text in box @accountnumberHeader @accountnumberFooter page.middleX page.right\n$accountnumber = take last words @infoLast 1 => get text\n\n$periodfrom = get line containing \"Transactions from\" => get words before \"to\" => take last words 3 => get date \"MMM d, yyyy\"\n$periodto = get last line containing \"Transactions from\" => get words after \"to\" => take words 3 => get date \"MMM d, yyyy\"\n\ngo to page 1\n$closingbalance = get last line starting \"Opening balance\" => get words after \"Opening balance\" => get decimal\n$openingbalance = get line starting \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\ngo to page 1\n@transactiontop = get line starting \"Date Description\" => bottom => get line below\ngo to last page\n@transactionbottom = get last line containing \"Transaction types\" => top => get line above\n\ngo to page 1\n//get line containing \"Revolut Payments UAB\" => top => ignore footer below\nignore footer below 80\ndelete all lines containing \"FX Rate\"\ndelete all lines starting \"Transactions from\"\ndelete all lines starting \"Transaction types\"\ndelete all lines containing \"Generated on\"\n\n\n//$transactions = get multi page table @transactiontop @transactionbottom 20 90 400 465 515 650 => describe table false \"*Date[MMM d, yyyy]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactiontop @transactionbottom 20 90 415 405 480 465 520 650 => describe table false \"*Date[MMM d, yyyy]\" Details -  #Debit - #Credit *#Balance','2022-04-13 06:03:22',0);
