INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10241,'PNC_Bank','$source = \"PNC_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n// Get period from/to\r\n$period = get line containing \"For the Period\" => get words after \"For the Period\" => take words 3\r\n$periodFrom = take words $period 1 => get date \"MM dd yyyy\"\r\n$periodTo = take last words $period 1 => get date \"MM dd yyyy\"\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"For the Period\" => get words after \"Primary Account Number:\" => take words 1 => get text\r\n\r\n// Get account name\r\n$accountName = get text in box 750 690 100 500 => take words 3 => get text\r\n\r\nget line starting \"Balance Summary\"\r\n$openingBalance = get line starting \"balance other additions deductions balance\" => bottom => get line below => take words 1 => get decimal\r\n$closingBalance = get line starting \"balance other additions deductions balance\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n//Remove summary\r\ngo to page 1\r\n@delBottom4 = get line containing \"Daily Balance\" => top\r\n$del4 = delete text in box page.top @delBottom4 0 page.right => get text\r\n\r\n// Remove extra summary text\r\ngo to page 1\r\n@delSummaryTop2 = get line containing \"Balance Summary\" => bottom\r\n@delSummaryBottom2 = get line containing \"Total\" => top\r\n$delSummary2 = delete text in box @delSummaryTop2 @delSummaryBottom2 0 page.right => get text\r\n\r\nignore header above 730\r\n\r\n//go to page 1\r\n// Checks table\r\n@checksTransactionTop = get line containing \"Checks and Substitute Checks\" => if not found then blank => bottom => get line below => bottom => get line below => bottom => get line below\r\n@checksTransactionBottom = get line starting \"Debit Card Purchases\" => top => get line above\r\n\r\n//get checks left transactions\r\n$checksLeftTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 30 55 130 175 205 => describe table false \"*Date[MM/dd]\" Details #Debit TransactionType\r\n\r\n//get checks mid transactions\r\n$checksMidTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 206 230 315 355 385 => describe table false \"*Date[MM/dd]\" Details #Debit TransactionType\r\n\r\n//get checks right transactions\r\n$checksRightTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 388 410 495 535 570 => describe table false \"*Date[MM/dd]\" Details #Debit TransactionType\r\n\r\ngo to page 1\r\n@delTop1 = get line containing \"Checks and Substitute Checks\" => if not found then blank => bottom\r\n@delBottom1 = get line containing \"Debit Card Purchases\" => top\r\n$del1 = delete text in box @delTop1 @delBottom1 0 page.right => get text\r\n\r\ngo to page 1\r\n// POS Purchases table\r\n@POSPurchaseTop = get line starting \"POS Purchases\" => if not found then blank =>  bottom => get line below => bottom => get line below\r\n\r\n@POSPurchaseBottom = get line starting \"ACH Deductions\" => top => get line above\r\ndelete all lines starting \"posted\"\r\n\r\n//get POS Purchases transactions\r\n$POSPurchaseTransactions = get multi page table @POSPurchaseTop @POSPurchaseBottom 30 135 190 450 570 => describe table false \"*Date[MM/dd]\" #Debit Details TransactionType\r\n\r\ngo to page 1\r\n@delTop3 = get line containing \"POS Purchases\" => if not found then blank => bottom\r\n@delBottom3 = get line containing \"ACH Deductions\" => top\r\n$del3 = delete text in box @delTop3 @delBottom3 0 page.right => get text\r\ndelete all lines starting \"POS Purchases\"\r\n\r\ngo to page 1\r\n// DebitCard table\r\n@debitCardTransactionTop = get line starting \"Debit Card Purchases\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@debitCardTransactionBottom = get line starting \"ACH Deductions\" => top => get line above\r\ndelete all lines starting \"posted\"\r\ndelete all lines containing \"Debit Card Purchases continued on next page\"\r\ndelete all lines starting \"Date\"\r\ndelete all lines starting \"posted\"\r\n\r\n//get debit Card transactions\r\n$debitCardTransactions = get multi page table @debitCardTransactionTop @debitCardTransactionBottom 30 100 155 450 570 => describe table false \"*Date[MM/dd]\" #Debit Details TransactionType\r\n\r\ngo to page 1\r\n@delTop2 = get line containing \"Debit Card Purchases\" => if not found then blank => bottom\r\n@delBottom2 = get line containing \"ACH Deductions\" => top\r\n$del2 = delete text in box @delTop2 @delBottom2 0 page.right => get text\r\n\r\ngo to page 1\r\n@delTop7 = get line containing \"Debit Card Purchases\" => if not found then blank => bottom\r\n@delBottom7 = get last line containing \"Debit Card Purchase\" => bottom => get line below => bottom\r\n$del7 = delete text in box @delTop7 @delBottom7 0 page.right => get text\r\n\r\ndelete all lines starting \"Date\"\r\ndelete all lines starting \"posted\"\r\ndelete all lines starting \"ACH Additions\"\r\ndelete all lines containing \"continued on next page\"\r\ndelete all lines starting \"Business Checking Account Number\"\r\ndelete all lines containing \"continued\"\r\n\r\ngo to page 1\r\n//Credits table\r\n@creditsTop = get line starting \"Deposits and Other Additions\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get last line starting \"Checks and Other Deductions\" => top => get line above\r\ndelete all lines starting \"Deposits\"\r\ndelete all lines starting \"Other Additions\"\r\ndelete all lines containing \"* Gap in check sequence\"\r\n//get ACH Additions transactions\r\n$creditsTransaction = get multi page table @creditsTop @creditsBottom 30 135 190 450 570 => describe table false \"*Date[MM/dd]\" #Credit Details TransactionType\r\n\r\ngo to page 1\r\n//debits table\r\n@debitsTop = get line starting \"Checks and Other Deductions\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@debitsBottom = get last line starting \"Detail of Services Used\" => top => get line above\r\ndelete all lines containing \"* Gap in check sequence\"\r\ndelete all lines starting \"Service Charges and Fees\"\r\ndelete all lines starting \"Other Deductions\"\r\ndelete all lines starting \"Debit Card Purchases\"\r\ndelete all lines starting \"ACH Deductions\"\r\n//get ACH Additions transactions\r\n$debitsTransaction = get multi page table @debitsTop @debitsBottom 30 135 190 450 570 => describe table false \"*Date[MM/dd]\" #Debit Details TransactionType\r\n\r\n//all transactions\r\n$transactions = combine described tables $creditsTransaction $debitsTransaction $checksLeftTransactions $checksMidTransactions $checksRightTransactions $debitCardTransactions $POSPurchaseTransactions','2026-09-15 10:10:56',0);
