INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10243,'ArvestBank','$source = \"ArvestBank\"\n\n$accountNumber = get line containing \"Customer Number:\" => get words after \"Customer Number:\" => take words 1 => get text\n\n$accountName = get line containing \"Customer Number:\" => top => get line above =>  take words 2 => get text\n\ngo to page 1\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"M d yyyy\"\n//go to page 1\n$periodTo = get line containing \"Statement Ending\" => get words after \"Statement Ending\" => take words 1 => get date \"M d yyyy\"\n\ngo to page 1\n// Get opening and closing balances\n$openingBalanceText = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\"\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get line containing \"FREE BUSINESS CHECKING\" => get words after \"FREE BUSINESS CHECKING\" =>  take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n//remove page 2\n@InfoTop = get line containing \"Get account information any time\" => top => get line above => top\n@InfoBottom = get line containing \"Member FDIC\" => bottom\n$deleteInfo = delete text in box @InfoTop @InfoBottom page.left page.right => get text\n\ngo to page 1\n// Get start & end of Deposits\n@depositsTop = get line containing \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@depositsBottom = get line containing \"Electronic Credits\" => if not found then blank => top => get line above\n\n// Get start & end of Electronic Credits\ngo to page 1\n\n@creditsTop = get line containing \"Electronic Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line containing \"Electronic Debits\" => if not found then blank => top => get line above\n\n// Get start & end of Electronic Debits\ngo to page 1\n\n@debitsTop = get line containing \"Electronic Debits\" => if not found then blank => bottom => get line below => bottom => get line below\n//@debitsBottom = get line containing \"Other Debits\" => if not found then blank => top => get line above\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\n// Get start & end of CHECKS\ngo to page 1\n\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\ndelete all lines containing \"* Indicates skipped \"\n\n//go to page 1\n//@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n//@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\n//go to page 1\n//@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n//@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Check Nbr Date Amount\"\n@checkconttop = get line starting \"Checks Cleared (continued)\" => top\ndelete all lines containing \"(continued)\"\n\n$checksLeft = get multi page table @checksTop @checksBottom 38 90 145 210 => describe table false ChequeNumber \"*Date[MM dd yyyy]\" #Debit\n\n$checksRight = get multi page table @checksTop @checksBottom 220 275 325 394 => describe table false  ChequeNumber \"*Date[MM dd yyyy]\" #Debit\n\n$checksLastRight = get multi page table @checksTop @checksBottom 405 457 508 577 => describe table false  ChequeNumber \"*Date[MM dd yyyy]\" #Debit\ndelete text in box @checkconttop page.bottom page.left page.right\ngo to page 1\n@checktop = get line starting \"Checks Cleared\" => top\ndelete text in box @checktop page.bottom page.left page.right\n\n@headerBottomm = get line containing \"Statement Ending\" => bottom\n\ndelete text in box on every page page.top @headerBottomm page.left page.right\nignore footer below 25\n\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Savings Account Statements\"\ndelete all lines containing \"Check Nbr Date\"\ndelete all lines containing \"Deposits\"\ndelete all lines containing \"Electronic Credtis\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Electronic Debits\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"* Indicates skipped \"\ndelete all lines containing \"Statement Ending\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"continued\"\ndelete all lines containing \"Customer Number:\"\ndelete all lines containing \"FREE BUSINESS CHECKING\"\ndelete all lines containing \"B85869B435C1264AA260190310BB5E69\"\n\ngo to page 1\n\n$deposits = get multi page table @depositsTop @depositsBottom 0 90 500 600 => describe table false \"*Date[MM dd yyyy]\" Details #Credit\n\n$credits = get multi page table @creditsTop @creditsBottom 0 90 500 600 => describe table false \"*Date[MM dd yyyy]\" Details #Credit\n\n$debits = get multi page table @debitsTop @debitsBottom 0 90 500 600 => describe table false \"*Date[MM dd yyyy]\" Details #Credit\n\n$transactions = combine described tables $deposits $credits  $debits  $checksLeft $checksRight $checksLastRight','2025-01-23 08:29:47',0);
