" => top\ndelete text in box @topfooter page.bottom page.left page.right\n\nignore header above 670\n//ignore footer below 400\nignore footer below 280\ndelete all lines starting \"Balance from previous page\"\ndelete all lines starting \"Continued on next page\"\ndelete all lines containing \"Plan Code\"\n\n//get all transactions\n//$transactions = get multi page table @transactionTop @transactionBottom 0 75 120 170 390 450 => describe table false - \"*Date[dd MMM yy]\" TransactionType Details #Credit\n$transactions = get multi page table @transactionTop @transactionBottom 0 75 130 170 390 460 => describe table false - \"*Date[dd MMM yy]\" TransactionType Details #Credit','2025-08-20 07:26:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10246,'Llyods_InternetBanking_securebusiness2','$source = \"Llyods_bank_account_statement\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n$accountName = get line containing \"Account number\" => get words before \"Sort code\" => get text\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\n\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type In\" => bottom => get line below\n\n// Get openingBalance\n$openingBalance = take last words @transactionsTop 1 => get decimal\n$periodTo = take words @transactionsTop 3 => get date \"dd MMM yy\"\n\ngo to page 1\n@deleteTop = get line starting \"BGC Bank Giro Credit\" => top\n@deleteBottom = get line containing \"Registered in England\" => top \ndelete text in box @deleteTop @deleteBottom page.left page.right\n\n//Get Closing Balance\ngo to last page\n@pageFooter = get last line containing \"Registered in England\" => top \n\n@infoLast = get text in box page.top @pageFooter 480 page.right\n$closingBalance = take last words @infoLast 1 => get decimal\n\n\n//Get Period From\n@periodFromText = bottom @infoLast => get line below\n$periodFromText = bottom @infoLast => get line below\n$lastTransaction = bottom @periodFromText => get line above\n$PeriodFrom = take words $lastTransaction 3 => get date \"dd MMM yy\"\n\n//End of the table\n//@transactionsBottom =  bottom @periodFromText => get line above\n@transactionsBottom = get last line containing \"Registered in England\" => top => get line above\n\nignore footer below 40\ndelete all lines containing \"Lloyds Bank - Print Friendly Statement\"\ndelete all lines containing \"https://securebusiness.lloydsbank.co.uk\"\ndelete all lines containing \"https://secure.lloydsbank.co.uk\"\ndelete all lines containing \"Date Description Type\"\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 100 460 500 600 685 800 => describe table false \"Date[dd MMM yy]\" Details TransactionType #Credit #Debit *#Balance\n\n\n\n\n\n\n','2021-10-14 08:07:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10247,'LloydsBankofScotland_IOS','$source = \"Lloyds/Bank of Scotland UK\"\n $features = \"NO_OPENING_BALANCE\"\n \n $periodBufferDays = 14\n \n // Discard hidden text\n delete white words\n delete tiny words\n \n // Get account name\n $accountName = get text in box 760 735 0 300 => get text\n \n // Discard address in top left of page 1\n @dropBottom = get line starting \"Money In\" => top\n delete text in box page.top @dropBottom page.left page.middleX\n \n // Get account number\n $accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n \n // Get period from/to\n @period = get line starting \"Money In\" => top => get line above => take last words 7\n $periodFrom = take words @period 3 => get date \"dd MMMM yyyy\"\n @periodto = get last line starting \"Money In\" => top => get line above => take last words 7\n $periodTo = take last words @periodto 3 => get date \"dd MMMM yyyy\"\n \n // Get opening and closing balances\n //$openingBalanceText = get line starting \"Money In\" => take last words 1\n //$openingBalance = get decimal $openingBalanceText\n $closingBalanceText = get last line starting \"Money Out\" => take last words 1\n $closingBalance = get decimal $closingBalanceText\n \n // Get start of table\n go to page 1\n @transactionsTop = get line starting \"Date Description Type\" => bottom => get line below\n \n // Discard page header\n get line containing \"Page 1 of\" => bottom => ignore header above\n //get last line starting \"Date Description Type Money In (£) Money Out (£) Balance (£)\" => bottom => ignore header above\n //ignore header above 677\n ignore header above 692\n \n delete all lines starting \"(Continued on next page)\"\n delete all lines containing \"Bill Payments\"\n delete all lines containing \"Cashpoint\"\n delete all lines containing \"Fixed Service\"\n delete all lines containing \"Mobile Payment Out\"\n delete all lines containing \"TFR Transfer\"\n delete all lines starting \"Money In\"\n delete all lines starting \"Money Out\"\n delete all lines starting \"BUSINESS ACCOUNT\"\n delete all lines starting \"CLASSIC\"\n delete all lines containing \"(Address last updated\"\n delete all lines containing \"Your Transactions\"\n delete all lines containing \"iption\"\n delete all lines starting \"Date Description Type\"\n \n // Discard page footer\n ignore footer below 80\n \n // Get end of table\n @transactionsBottom = get last line starting \"Transaction types\" => top => get line above\n delete all lines starting \"Transaction types\"\n \n \n // Read the transactions\n $transactions = get multi page table @transactionsTop @transactionsBottom 0 110 270 300 390 470 560 => describe table false \"Date[dd MMM yy]\" Details TransactionType **#Credit **#Debit #Balance\n\n','2023-09-15 05:08:40',1);
