INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10249,'BankOfIreland_CardLeftSumm','$source = \"BankOfIreland_LeftSummary\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\nset negative marker \"cr\"\n\n// Get account number and account name\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => take words 1 => get text\n$accountName = get text in box 760 730 page.left 195 => take words 2 => get text\n\n// Get period from and period to\n$periodTotxt = get line containing \"Statement Date\"\n@periodToTop = top $periodTotxt\n@periodTobottom = bottom $periodTotxt => get line below => bottom\n$periodTo = get text in box @periodToTop @periodTobottom page.left 125 => take last words 3 => get date \"d MMM yyyy\"\n\n@headerTop = get line containing \"ransactions\" => bottom\n@periodlinebottom = get line below @headerTop => bottom\n$periodFrom = get text in box @headerTop @periodlinebottom 198 232 => take words 2 => get date \"d MMM\"\n\n//Opening and closing balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Balance\" => get words after \"Balance\" => get decimal\n\n//delete left of every page\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 197\n\ngo to page 1\nignore header above 785\ndelete text in box page.top @headerTop page.left page.right\n\n@firstFotter = get line containing \"continued\" => top\ndelete text in box @firstFotter page.bottom page.left page.right\n\n\ngo to page 1\n// Get Start of Transaction\n@transactiontop = get line below @headerTop\n// Get end of Transaction\n@transactionsBottom = get last line containing \"Payment Due\" => top => get line above => top => get line above\n\n//delete footer of last page\n@lastFooter = get last line containing \"Payment Due\" => top\ndelete text in box @lastFooter page.bottom page.left page.right\n\ndelete all lines containing \"Total transactions this period\"\ndelete all lines starting \"Previous Balance\"\ndelete all lines containing \"continued\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Payment Due\"\ndelete all lines containing \"Balance\"\ndelete all lines containing \"Transactions continued\"\ndelete all lines containing \"Other transactions\"\ndelete all lines containing \"Total transactions\"\ndelete all lines containing \"Overdue Payment\"\ndelete all lines containing \"Min. Payment\"\n\n\n//Read the transactions\n$transactions = get multi page table @transactiontop @transactionsBottom 198 234 500 565 => describe table false \"Date[d MMM]\" Details *#Credit','2022-11-15 07:15:20',0);
