INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10251,'Coutts_Accounts','$source = \"Coutts_Accounts\"\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account name and number\n@accountName = get line starting \"Account transactions for\"\n$accountName = get words after @accountName \"Account transactions for\" => skip words 2 => get words before \", sort\" => get text\n$accountNumber = get line starting \"Account transactions for\" => take last words 1 => get text\n\n// Get statement period from and to\n//@periodFmTop = get last line starting \"Date Description Debit GBP\" => bottom\n@periodFmTop = get last line starting \"Date Description Debit\" => bottom\n@periodFmBottom = get line starting \"Transactions with today\" => top => get line above => bottom\n\ngo to page 1\n//@periodToTop = get line starting \"Date Description Debit GBP\" => bottom\n@periodToTop = get line starting \"Date Description Debit\" => bottom\n@periodToBottom = get line starting \"Printed on\" => top\n$periodTo = get text in box @periodToTop @periodToBottom 40 100 => take words 3 => get date \"dd MMM yyyy\"\n\n//Get opening and closing balance\ngo to page 1\n//$closingBalance = get text in box @periodToTop @periodToBottom 750 820 => take words 1 => get decimal\n$openingbalance = get text in box @periodToTop @periodToBottom 750 820 => take words 1 => get decimal\n\ngo to page 1\n//@transactionsTop = get line starting \"Date Description Debit GBP\" => bottom => get line below\n//@transactionsBottom = get line starting \"Transactions with today\" => top => get line above\n@transactionsTop = get line starting \"Date Description Debit\" => bottom => get line below\n@transactionsBottom = get last line starting \"Transactions with today\" => top => get line above\n\n//@clossingbalbottom = get last line starting \"Transactions with today\" => top\n@clossingbalbottom = get last line starting \"Transactions with today\" => top => get line above => bottom\n\n@footerBelow = get line starting \"Printed on\" => top\nignore footer below @footerBelow\ndelete all lines starting \"Date Description Debit GBP\"\ndelete all lines starting \"Transactions with today\"\ndelete all lines containing \"provide an indicative position for interest\"\n\ndelete all lines containing \"Account transactions for\"\ndelete all lines containing \"Cleared balances provide\"\ndelete all lines ending \"Account\"\ndelete all lines starting \"Date Description Debit\"\ndelete all lines starting \"Debit and credit\"\n\n$closingBalance = get text in box 500 @clossingbalbottom 750 820 => take last words 1 => get decimal\n$periodFrom = get text in box @periodFmTop @periodFmBottom 40 100 => take last words 3 => get date \"dd MMM yyyy\"\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 130 570 670 750 820 => describe table false \"**Date[dd MMM yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 130 570 660 750 820 => describe table false \"**Date[dd MMM yyyy]\" Details #Debit #Credit #Balance','2024-02-16 04:37:12',0);
