INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10254,'BankOZK','$source = \"BankOZK\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//Get account number & account name\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n$accountName = get line containing \"Statement Date:\" => bottom => get line below =>  take words 2 => get text\n\ngo to page 1\n//Get statement period\n$periodFrom = get line starting \"PREVIOUS STATEMENT\" => get words after \"PREVIOUS STATEMENT BALANCE AS OF\" => take words 1 => get date \"MM dd yy\"\n$periodTo = get line starting \"CURRENT STATEMENT\" => get words after \"CURRENT STATEMENT BALANCE AS OF\" => take words 1 => get date \"MM dd yy\"\n\ngo to page 1\n// Get opening and closing balances\n$openingBalanceText = get line starting \"PREVIOUS STATEMENT\" => get words after \"PREVIOUS STATEMENT\" => take last words 1\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get line containing \"CURRENT STATEMENT\" => get words after \"CURRENT STATEMENT\" =>  take last words 1\n$closingBalance = get decimal $closingBalanceText\n\nremove page 2\n// Get start & end of CHECKS\ngo to page 1\n\n@checksTop = get line starting \"CHECK TRANSACTIONS\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"OTHER TRANSACTIONS\" => if not found then blank => top => get line above\n\ngo to page 1\n@checksTop = get line starting \"CHECK TRANSACTIONS\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"OTHER TRANSACTIONS\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of OTHER TRANSACTIONS\n@otherTop = get line starting \"OTHER TRANSACTIONS\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherBottom = get line starting \"BALANCE BY DATE\" => if not found then blank => top => get line above\n\ndelete text in box on every page page.top 687 page.left page.right\ndelete text in box on every page page.top page.bottom 10 43\n\ndelete all lines containing \"TOTAL FOR THIS PERIOD\"\ndelete all lines containing \"PAGE\"\ndelete all lines containing \"TOTAL OVERDRAFT FEES\"\ndelete all lines containing \"TOTAL RETURNED ITEM FEES\"\ndelete all lines containing \"DATE DESCRIPTION DEBITS\"\ndelete all lines containing \"PLEASE SEE REVERSE\"\ndelete all lines containing \"OTHER TRANSACTIONS\"\ndelete all lines containing \"ITEMIZATION OF SERVICE CHARGE PAID THIS PERIOD\"\ndelete all lines containing \"TOTAL CHARGE FOR PER ITEM FEE\"\n\ngo to page 1\n@checksLeft = get multi page table @checksTop @checksBottom 40 80 130 225 => describe table false Details \"Date[MM dd]\" *#Debit\n@checksRight = get multi page table @checksTop @checksBottom 385 420 475 570 => describe table false  Details \"Date[MM dd]\" *#Debit\n@other = get multi page table @otherTop @otherBottom 42 80 430 490 570 => describe table false \"*Date[MM dd]\" Details #Debit #Credit\n\n$transactions = combine described tables @checksLeft @checksRight @other','2024-10-17 08:41:23',0);
