INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10256,'USBank_VisaCard','$source = \"USBank_VisaCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\nset negative marker \"CR\"\r\n\r\n@deleteleftpanel = delete text in box on every page page.top page.bottom 0 58 => get text\r\ndelete all pages containing \"What To Do If You Think\"\r\n\r\ngo to page 1\r\n\r\n//remove page 2\r\n@accountnameLine = get line starting \"New Balance\" => top => get line above\r\n$accountname = take words @accountnameLine 3 => get text\r\n//$accountnumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\r\n$accountnumber = get line containing \"Account\" => get words after \"Account\" => take last words 4 => get text\r\n\r\n$periodfrom = get line containing \"Open Date:\" => get words after \"Open Date:\" => get words before \"Closing Date:\" => get date \"MM dd yyyy\"\r\n//$periodto = get line containing \"Closing Date:\" => get words after \"Closing Date:\" => get words before \"Account:\" => get date \"MM dd yyyy\"\r\n$periodto = get line containing \"Closing Date:\" => get words after \"Closing Date:\" => get words before \"Account\" => get date \"MM dd yyyy\"\r\n\r\ngo to page 1\r\n@deleteleftsummarypanel = delete text in box page.top page.middleY 0 page.middleX\r\n\r\n@Summarytop = get line containing \"Previous Balance\" => top\r\n@Summarybottom = get last line starting \"New Balance\" => bottom\r\n@Summary = get text in box @Summarytop @Summarybottom page.middleX 600\r\n$openingbalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => get decimal\r\n$closingbalance = get words after @Summary \"New Balance\" => get decimal\r\n\r\n// Dynamic co-ordinates\r\n@transTypeleft = get line containing \"Date Date Ref\" => get words before \"Ref\" => take last words 1 => right => add 5\r\n@detailsleft = get line containing \"Date Ref # Transaction\" => get words before \"Transaction\" => take last words 1 => right => add 4\r\n\r\n@TransactionTop = get line starting \"Date Date Ref \" => bottom => get line below\r\n@TransactionBottom = get last line containing \"Totals Year-to-Date\" => top => get line above\r\n\r\n//@CreditTop = get line starting \"Payments and Other Credits\" => if not found then blank => bottom => get line below\r\n//@CreditBottom = get line starting \"Purchases and Other Debits\" => if not found then blank => top => get line above\r\n\r\n//@DebitTop = get line starting \"Purchases and Other Debits\" => if not found then blank => bottom => get line below\r\n//@DebitBottom = get last line starting \"TOTAL THIS PERIOD\" => if not found then blank => top => get line above\r\n\r\n// @FeeTop = get line starting \"Fees\" => if not found then blank =>  bottom => get line below\r\n//@FeeBottom = get last line starting \"TOTAL FEES THIS PERIOD\" => if not found then blank => top => get line above\r\n\r\n// @InterestTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below\r\n//@InterestBottom = get last line starting \"TOTAL INTEREST THIS PERIOD\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Payments and Other Credits\"\r\ndelete all lines starting \"Transactions\"\r\ndelete all lines starting \"Post Trans\"\r\ndelete all lines starting \"Date Date Ref # Transaction\"\r\ndelete all lines starting \"TOTAL THIS PERIOD\"\r\ndelete all lines starting \"Continued on Next Page\"\r\ndelete all lines containing \"Cardmember Service\"\r\ndelete all lines containing \" Transaction Description\"\r\ndelete all lines starting \"Post\"\r\ndelete all lines starting \"Date Transaction Description\"\r\ndelete all lines containing \"Purchases and Other Debits\"\r\ndelete all lines containing \"Date Date Ref\"\r\ndelete all lines starting \"Fees\"\r\n\r\ndelete all lines containing \"Total for Account\"\r\ndelete all lines starting \"Other Credits\"\r\ndelete all lines containing \"FOR THIS PERIOD\"\r\ndelete all lines containing \"THIS PERIOD\"\r\ndelete all lines starting \"Interest Charged\"\r\n\r\n//ignore header above 693\r\nignore header above 665\r\n\r\n\r\n//@CreditTransactions = get multi page table @CreditTop @CreditBottom 60 100 135 168 430 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit\r\n//@DebitTransactions  = get multi page table @DebitTop  @DebitBottom 60 100 135 168 430 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit\r\n//@FeeTransactions  = get multi page table @FeeTop  @FeeBottom 60 100 135 168 450 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit\r\n//@InterestTransactions  = get multi page table @InterestTop  @InterestBottom 60 100 450 600 => describe table false \"*Date[MM/dd]\" Details *#Credit\r\n// $transactions = combine described tables @CreditTransactions @DebitTransactions @FeeTransactions @InterestTransactions\r\n\r\n//$transactions = get multi page table @TransactionTop  @TransactionBottom 60 100 135 167 430 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit\r\n//$transactions = get multi page table @TransactionTop  @TransactionBottom 60 100 @transTypeleft @detailsleft 430 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit\r\n$transactions = get multi page table @TransactionTop  @TransactionBottom 60 100 @transTypeleft @detailsleft 420 600 => describe table false \"*Date[MM/dd]\" \"TransDate[MM/dd]\" TransactionType Details *#Credit','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10257,'USBank_NoExclusion','$source = \"USBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//remove page 2\n\nset negative marker \"-\"\n\n// Get account name, number, period to and from\n@accounttopline = get line containing \"Business Statement\" \n@accounttop = bottom @accounttopline\n@accountleft = left @accounttopline\n\n@accountbottomline = get line containing \"Page\"\n@accountbottom = top @accountbottomline\n@accountinfo = get text in box @accounttop @accountbottom @accountleft page.right\n\n$accountnumber = get words between @accountinfo \"Account Number:\" \"Statement Period:\" => get text\n$periodfrom = get words between @accountinfo \"Statement Period:\" \"through\" => get date \"MMM d, yyyy\"\n$periodto = get words after @accountinfo \"through\" => get date \"MMM d, yyyy\"\n\n@accountnametext = get last line containing \"Business Statement\"\n$accountname = get words before @accountnametext \"Business Statement\" => get text\n\n// Get opening and closing balances\ngo to page 1\n@openingbalanceline = get line containing \"Beginning Balance\" \n$openingbalance = take last words @openingbalanceline 1 => get decimal\n@closingbalanceline = get line containing \"Ending Balance\" \n$closingbalance = take last words @closingbalanceline 1 => get decimal\n\n// Delete Account Summary\n//go to page 1\n \n@summarytop = get line containing \"Account Summary\" => bottom \n@summarybottom = get line containing \"Ending Balance\" => bottom\ndelete text in box @summarytop @summarybottom page.left page.right\n\n// Get start & end of customer deposits table\n \n \n@customertop = get line starting \"Number Date\" => if not found then blank => bottom => get line below\n@customerbottom = get line starting \"Total Customer Deposits\" => if not found then blank => top => get line above\n \n \n\n// Get start and end of other deposits table \n@othertop = get line starting \"Other Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherbottom = get line starting \"Total Other Deposits\" => if not found then blank => top => get line above\n \n \n\n// Get start and end of card deposits table \n@carddeptop = get line starting \"Card Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@carddepbottom = get line starting \"Total Card Deposits\" => if not found then blank => top => get line above\n \n\n// Get start and end of card withdrawals table\n@cardtop = get line starting \"Card Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n@cardbottom = get line starting \"Total Card Withdrawals\" => if not found then blank => top => get line above => top => get line above\n\n\n// Get start and end of other withdrawals table\n@otherwithtop = get line starting \"Other Withdrawals\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherwithbottom = get line starting \"Total Other Withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of checks table\n \n \n@checkstop = get line starting \"Check Date\" => if not found then blank => bottom => get line below\n@checksbottom = get line containing \"Conventional Checks Paid\" => if not found then blank => top => get line above\n\n\n// Delete headers and footers\nget last line starting \"SILVER BUSINESS CHECKING\" => bottom => ignore header above\n\n// Remove unwanted lines\n \ndelete all lines starting \"U.S. Bank National Association\"\n \ndelete all lines starting \"Customer Deposits\"\ndelete all lines starting \"Total Customer Deposits\"\n\ndelete all lines starting \"Number Date\"\n\ndelete all lines starting \"Other Deposits (continued)\"\n \ndelete all lines starting \"Other Deposits\"\n \ndelete all lines starting \"Total Other Deposits\"\n \ndelete all lines starting \"Date Description of Transaction\"\n \ndelete all lines starting \"Member FDIC\"\ndelete all lines starting \"BALANCE YOUR ACCOUNT\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"Card Withdrawals\"\n\ndelete all lines containing \"Withdrawals Subtotal\"\ndelete all lines starting \"Other Withdrawals\"\ndelete all lines starting \"Total Other Withdrawals\"\n \ndelete all lines starting \"Checks Presented Conventionally\"\ndelete all lines starting \"Check Date\"\ndelete all lines starting \"Card Deposits\"\ndelete all lines containing \"Deposit Subtotal\"\n \n \n@customerdepositsleft = get multi page table @customertop @customerbottom 0 65 120 180 300 => describe table false - \"*Date[MMM d]\" Details #Credit\n \n@customerdepositsright = get multi page table @customertop @customerbottom page.middleX 360 410 480 600 => describe table false - \"*Date[MMM d]\" Details #Credit\n@otherdeposits = get multi page table @othertop @otherbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Credit\n \n@carddeposits = get multi page table @carddeptop @carddepbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Credit\n@cardwithdrawals = get multi page table @cardtop @cardbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Debit\n@otherwithdrawals = get multi page table @otherwithtop @otherwithbottom 0 40 420 440 600 => describe table false \"Date[MMM d]\" Details - *#Debit\n@checksleft = get multi page table @checkstop @checksbottom 0 65 120 180 300 => describe table false ChequeNumber \"*Date[MMM d]\" Details #Debit\n \n@checksright = get multi page table @checkstop @checksbottom page.middleX 360 410 480 600 => describe table false ChequeNumber \"*Date[MMM d]\" Details #Debit\n$transactions = combine described tables @customerdepositsleft @customerdepositsright @otherdeposits @carddeposits @cardwithdrawals @otherwithdrawals @checksleft @checksright','2022-03-10 13:40:39',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10258,'ScotlandBank_InternetBanking_securebusiness','$source = \"Scotland_bank_account_statement\"\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\n\r\n$accountName = get line containing \"Account number\" => get words before \"Sort code\" => get text\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\r\n\r\n@descLeft = get line starting \"DATE DESCRIPTION TYPE IN\" => get words after \"DATE\" => left\r\n@descLeft = subtract @descLeft 3\r\n@TypeLeft = get line starting \"DATE DESCRIPTION TYPE IN\" => get words after \"DATE DESCRIPTION\" => left\r\n@TypeLeft = subtract @TypeLeft 1\r\n@TypeRight = get line starting \"DATE DESCRIPTION TYPE IN\" => get words after \"DATE DESCRIPTION\" => take words 1 => right\r\n@TypeRight = add @TypeRight 10\r\n@INRight = get line starting \"DATE DESCRIPTION TYPE IN\" => get words before \"OUT\" => take last words 1 => right\r\n@INRight = add @INRight 10\r\n@OUTRight = get line starting \"DATE DESCRIPTION TYPE IN\" => get words before \"BALANCE\" => take last words 1 => right\r\n@OUTRight = add @OUTRight 10\r\n@BALANCERight = get line starting \"DATE DESCRIPTION TYPE IN\" => take last words 1 => right\r\n@BALANCERight = add @BALANCERight 20\r\n\r\ngo to page 1\r\n@transactionsTop = get line starting \"DATE DESCRIPTION TYPE IN\" => bottom => get line below\r\n\r\n// Get openingBalance\r\n$openingBalance = take last words @transactionsTop 1 => get decimal\r\n$periodTo = take words @transactionsTop 3 => get date \"dd MMM yy\"\r\n\r\ndelete all lines containing \"Bank of Scotland - Print Friendly Statement\"\r\ndelete all lines containing \"https://secure-business.bankofscotland.co.uk\"\r\ndelete all lines containing \"https://secure.lloydsbank.co.uk\"\r\ndelete all lines containing \"DATE DESCRIPTION TYPE IN\"\r\n\r\n//Get Closing Balance\r\ngo to last page\r\n@pageFooter = get last line containing \"Registered in Scotland\" => top => get line above => bottom\r\n@infoLast = get text in box page.top @pageFooter 480 page.right\r\n$closingBalance = take last words @infoLast 1 => get decimal\r\n\r\n//Get Period From\r\n@periodFromText = bottom @infoLast => get line below\r\n$lastTransaction = bottom @periodFromText => get line above\r\n$PeriodFrom = take words $lastTransaction 3 => get date \"dd MMM yy\"\r\n\r\n//End of the table\r\n@transactionsBottom = get last line containing \"Bank of Scotland plc\" => top => get line above\r\n\r\n// Read the transactions\r\ngo to page 1\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 478 505 625 720 820 => describe table false \"Date[dd MMM yy]\" Details TransactionType #Credit #Debit *#Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @descLeft @TypeLeft @TypeRight @INRight @OUTRight @BALANCERight => describe table false \"Date[dd MMM yy]\" Details TransactionType #Credit #Debit *#Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10259,'ChaseBank_US_Spanish','$source = \"ChaseBank_US_Spanish\"\n$features = \"NO_TRANSACTION_YEAR\"\n\nset culture \"es-US\"\n\n// Delete vertical text\ndelete rotated words\n\n// Get Account Number\n@accountNumberText = get line containing \"Número De Cuenta:\" => get words after \"Número De Cuenta:\"\n$accountNumber = take words @accountNumberText 1 => get text\n\n// Get bank details\n@summaryLine = get line containing \"INFORMACIÓN PARA ATENCIÓN AL CLIENTE\" => top\n$panelDetails = get text in box page.top @summaryLine page.left page.right\n$accountName = get words before $panelDetails \"Número De Cuenta:\" => skip words 7 => take words 3 => get text\n$statementPeriod = get words before $panelDetails \"Número De Cuenta:\" => take words 7\n$PeriodFrom =  take words $statementPeriod 3 => get date \"MMMM dd,yyyy\"\n$PeriodTo = take last words $statementPeriod 3 => get date \"MMMM dd,yyyy\"\ndelete text in box @panelTop @summaryLine page.left page.right\n\n// Get opening and closing balances\n$openingBalanceText = get line starting \"Saldo inicial\" => skip words 2\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get line starting \"Saldo final\" => take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n\n// Get start & end of credits table\ngo to page 1\n@creditsTop = get line starting \"DEPÓSITOS Y ADICIONES\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line starting \"Total de depósitos y adiciones\" => if not found then blank => top => get line above\n\n// Get start & end of checks tables\ngo to page 1\n@checksTop = get line starting \"CHEQUES PAGADOS\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Total de cheques pagados\" => if not found then blank => top => get line above\n\n// Get start & end of ATM withdrawals table\ngo to page 1\n@ATMDebitsTop = get line starting \"RETIROS DE CAJEROS AUTOMÁTICOS\" => if not found then blank => bottom => get line below => bottom => get line below\n@ATMDebitsBottom = get line starting \"Total de retiros de cajeros automáticos\" => if not found then blank => top => get line above\n\ngo to page 1\n@debitsTop = get line starting \"RETIROS ELECTRÓNICOS\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get line starting \"Total de retiros electrónicos\" => if not found then blank => top => get line above\n\ngo to page 1\n@otherDebitsTop = get line starting \"OTROS RETIROS\" => if not found then blank => bottom => get line below => bottom => get line below\n@otherDebitsBottom = get line starting \"Total Otros retiros\" => if not found then blank => top => get line above\n\ngo to page 1\n@chagesdebitTop = get line starting \"CARGOS\" => if not found then blank => bottom => get line below => bottom => get line below\n@chagesdebitBottom = get line starting \"Total Comisiones\" => if not found then blank => top => get line above\n\n\n// Discard page header\ngo to page 2\nget line below page.top => bottom => ignore header above\n\n// Discard page footer\nget line above 0 => top => ignore footer below\n\n// Remove unwanted lines\ndelete all lines starting \"Depósitos y Adiciones\"\ndelete all lines starting \"Total de depósitos y adiciones\"\ndelete all lines starting \"CHEQUES PAGADOS\"\ndelete all lines starting \"Total de cheques pagados\"\ndelete all lines starting \"RETIROS ELECTRÓNICOS\"\ndelete all lines starting \"Total de retiros electrónicos\"\ndelete all lines starting \"OTROS RETIROS\"\ndelete all lines starting \"Total Otros retiros\"\ndelete all lines starting \"FECHA DESCRIPCIÓN CANTIDAD\"\ndelete all lines starting \"SALDO FINAL DIARIO\"\ndelete all lines starting \"CHEQUE Núm. DESCRIPCIÓN DE PAGO CANTIDAD\"\ndelete all lines starting \"*end\"\ndelete all lines starting \"*start\"\ndelete all lines starting \"Página\"\ndelete all lines containing \"continuación\"\ndelete all lines containing \"FECHA\"\n\n\n\n\n// Read the transactions\n@credits = get multi page table @creditsTop @creditsBottom 0 65 480 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 0 65 480 580 => describe table false \"*Date[MM/dd]\" Details *#Debit\n@checks = get multi page table @checksTop @checksBottom 0 80 380 480 580 => describe table false ChequeNumber Details \"*Date[MM/dd]\" #Debit\n@otherDebits = get multi page table @otherDebitsTop @otherDebitsBottom 0 65 480 580 => describe table false \"Date[MM/dd]\" Details *#Debit\n@ATMebits = get multi page table @ATMDebitsTop @ATMDebitsBottom 0 65 480 580 => describe table false \"Date[MM/dd]\" Details *#Debit\n@chagesdebit = get multi page table @chagesdebitTop @chagesdebitBottom 0 65 470 550 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n//$transactions = combine described tables @credits @checks @debits @otherDebits @ATMebits\n$transactions = combine described tables @credits @checks @debits @otherDebits @ATMebits @chagesdebit','2023-05-19 11:14:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10260,'CountingUP_Bank','$source = \"CountingUP_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\nset negative marker \"-\"\r\n\r\n// Get Account Details\r\n@AcctTop = get line containing \"Business account summary\" => bottom\r\n@AcctBottom = get line containing \"Transactions\" => top\r\n$accountName = get text in box @AcctTop @AcctBottom page.left 285 => take words 2 => get text\r\n$accountNumber = get text in box @AcctTop @AcctBottom page.left 285 => get words after \"number\" => take words 1 => get text\r\n\r\n// Delete unwanted Text\r\ndelete text in box @AcctTop @AcctBottom page.left 285\r\n\r\n// Get opening and closing balances\r\ngo to page 1\r\n$openingBalance = get line containing \"Balance on\" => get words after \"on\" => take last words 1 => get decimal\r\n$closingBalance = get last line containing \"Balance on\" => get words after \"on\" => take last words 1 => get decimal\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"Balance on\" => get words after \"on\" => take words 3 => get date \"d MMMM yyyy\"\r\n$periodto = get last line containing \"Balance on\" => get words after \"on\" => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get table coordinates\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date Details Out\" => bottom => get line below\r\n@DateRight = get line starting \"Date Details Out\" => get words before \"Details Out\" => take words 1 => right\r\n@DateRight = add @DateRight 40\r\n@DetailsRight = get line starting \"Date Details Out\" => get words before \"In\" => take last words 1 => left\r\n@DetailsRight = subtract @DetailsRight 60\r\n@DebitRight = get line starting \"Date Details Out\" => get words before \"In\" => take last words 1 => right\r\n@DebitRight = add @DebitRight 15\r\n@CreditRight = get line starting \"Date Details Out\" => get words before \"Balance\" => take last words 2 => right\r\n@CreditRight = add @CreditRight 15\r\n@BalanceRight = get line starting \"Date Details Out\" => get words after \"In (£)\" => take words 1 => right\r\n@BalanceRight = add @BalanceRight 30\r\n@transactionsBottom = get last line starting \"© Counting Ltd trading as Countingup\" => top => get line above\r\n\r\n// Delete unwanted text\r\ndelete all lines starting \"Date Details Out\"\r\ndelete all lines containing \"Counting Ltd trading\"\r\ndelete all lines starting \"The Countingup business\"\r\ndelete all lines starting \"institution authorised by\"\r\ndelete all lines starting \"equivalent to the money\"\r\ndelete all lines starting \"The Countingup Mastercard\"\r\ndelete all lines starting \"Page\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @DateRight @DetailsRight @DebitRight @CreditRight @BalanceRight => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit *#Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10261,'First_Republic_Bank','$source = \"First_Republic_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete rotated words\n\n@panelTop = get line containing \"Statement Period:\" => top\n@panelBottom = get line containing \"Account Number:\" => bottom\n@dropBottom = subtract @panelBottom 60\n$panel = get text in box @panelTop @dropBottom page.middleX page.right\n\n$accountnumber = get words after $panel \"Account Number:\" => take words 1 => get text\n//$accountname = get text in box 656 635 35 page.middleX => get text\n$accountname = get text in box 656 615 35 page.middleX => get text\n\n$periodFrom = get words after $panel \"Statement Period:\" => take words 3 => get date \"MMMM dd, yyyy\"\n//$periodto = get words after $panel \"Statement Period:\" => skip words 3 => take words 3 => get date \"MMMM dd, yyyy\"\n$periodto = get words after $panel \"Statement Period:\" => get words before \"Account Number:\" => take last words 3 => get date \"MMMM dd, yyyy\"\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingbalance = get line starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\ndelete text in box on every page page.top page.bottom page.left 50\n\ngo to page 1\n@deleteTextBottom = get line containing \"Ending Balance\" => bottom\ndelete text in box page.top @deleteTextBottom page.left page.right\n\nremove page 2\n\n//if (Checks table when \"CHECKS PAID\" is header)\ngo to page 1\n@transactionsTopCheck = get line starting \"CHECKS PAID\" => if not found then blank => bottom => get line below\n@transactionsBottomCheck = get line containing \"ACCOUNT ACTIVITY\" =>  if not found then blank => top => get line above\n\n//else (Checks table when \"Checks Paid\" is header)\ngo to page 1\n@transactionsTopChecksLowerCase = get line starting \"Checks Paid\" => if not found then blank => bottom => get line below\n@transactionsBottomChecksLowerCase = get line containing \"Account Activity\" =>  if not found then blank => top => get line above\n\ngo to page 1\n@transactionsTopCredit = get line starting \"Deposits and Credits\" => if not found then blank => bottom => get line below\n@transactionsBottomCredit = get last line containing \"Total Deposits and Credits\" => top => get line above\n\ngo to page 1\n@transactionsTopDebit = get line containing \"Withdrawals and Debits\" => if not found then blank => bottom => get line below\n@transactionsBottomDebit = get last line starting \"Total Withdrawals and Debits\" => top => get line above\n\ngo to page 1\nignore header above 550\ngo to page 1\nignore footer below 45\n\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"(Continued)\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"DATE DESCRIPTION\"\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"NUMBER DATE\"\ndelete all lines containing \"Number Date\"\n\n// Read the transactions\n$TransactionsCheckLeft = get multi page table @transactionsTopCheck @transactionsBottomCheck 80 160 235 325 => describe table false ChequeNumber \"*Date[MM/dd]\"  #Debit\n$TransactionsCheckRight = get multi page table @transactionsTopCheck @transactionsBottomCheck 325 410 490 580 => describe table false ChequeNumber \"*Date[MM/dd]\"  #Debit\n\n$TransactionsChecksLowerCaseLeft = get multi page table @transactionsTopChecksLowerCase @transactionsBottomChecksLowerCase 80 125 185 300 => describe table false ChequeNumber \"*Date[MM/dd]\"  #Debit\n$TransactionsChecksLowerCaseRight = get multi page table @transactionsTopChecksLowerCase @transactionsBottomChecksLowerCase 300 390 450 570 => describe table false ChequeNumber \"*Date[MM/dd]\"  #Debit\n\n//$TransactionsCredit = get multi page table @transactionsTopCredit @transactionsBottomCredit 50 105 500 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n$TransactionsCredit = get multi page table @transactionsTopCredit @transactionsBottomCredit 50 105 495 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n//$TransactionsDebit = get multi page table @transactionsTopDebit @transactionsBottomDebit 50 105 500 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n$TransactionsDebit = get multi page table @transactionsTopDebit @transactionsBottomDebit 50 105 495 580 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n// combine the transactions\n$transactions = combine described tables $TransactionsCredit $TransactionsDebit $TransactionsCheckLeft $TransactionsCheckRight $TransactionsChecksLowerCaseLeft $TransactionsChecksLowerCaseRight','2025-05-29 06:48:43',0);
