INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10271,'SantanderUK_WithoutSummary','$source = \"SantanderUK_WithoutSummary\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\n// Get account name\n//$accountName = get line starting \"Account name:\" => skip words 2 => get text\n$accountName = get line starting \"Account number:\" => skip words 2 => take words 1 => get text\n$accountNumber = get line starting \"Account number:\" => skip words 2 => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below => take last words 1 => get decimal\n$closingBalance = get line containing \"Current statement balance\" => take last words 1 => get decimal\n\n// Remove unwanted info side bar\ndelete all lines starting \"Brought forward balance\"\ndelete all lines starting \"Previous statement balance\"\n\ngo to page 1\n// Get period from/to\n//$periodFrom = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below => take words 2 => get date \"dd MMM\"\n//$periodTo = get line containing \"Current statement balance\" => take words 2 => get date \"dd MMM\"\n$periodFrom = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below => take words 2 => get date \"d MMM\"\n$periodTo = get line containing \"Current statement balance\" => take words 2 => get date \"d MMM\"\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below\n\n@Descleft = get line containing \"Date Description Credits Debits Balance\" => get words after \"Date\" => take words 1 => left\n@Descleft = subtract @Descleft 7\n\n@creditleft = get line containing \"Date Description Credits Debits Balance\" => get words after \"Description\" => take words 1 => left\n@creditleft = subtract @creditleft 12\n\n@debitleft = get line containing \"Date Description Credits Debits Balance\" => get words after \"Description\" => take words 1 => right\n@debitleft = add @debitleft 12\n\n@Balanceleft = get line containing \"Date Description Credits Debits Balance\" => get words before \"Balance\" => take last words 1 => right\n@Balanceleft = add @Balanceleft 7\n\n@BalanceRight = get line containing \"Date Description Credits Debits Balance\" => get words after \"Debits\" => take words 1 => right\n@BalanceRight = add @BalanceRight 30\n\n// Get end of table\n//@transactionsBottom = get line containing \"Current statement balance\" => top => get line above\n@transactionsBottom = get last line containing \"Current statement balance\" => top => get line above\n\n// Discard page header\ngo to page 1\nget line \"Date Description Credits Debits Balance\" => bottom => ignore header above\n\n// Discard page footer\n//ignore footer below 50\nignore footer below 42\n\n// Discard unwanted lines\ndelete all lines starting \"Date Description Credits Debits Balance\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 110 345 410 470 600 => describe table false \"*Date[dd MMM]\" Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @Descleft @creditleft @debitleft @Balanceleft @BalanceRight => describe table false \"*Date[d MMM]\" Details #Credit #Debit #Balance','2024-08-22 05:51:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10272,'AmericanExpressUKOtherAccTrans_Balance','$source = \"American Express\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 14\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get account name\n$accountName = get line starting \"Private & Confidential\" => bottom => get line below => get text\n\n// Get account number\n$accountNumber = get text in box 745 730 270 370 => get text\n\n// Get period from/to\n@period = get line starting \"Statement Period\" => skip words 3\n$periodFrom = take words @period 2 => get date \"d MMMM\"\n$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n// Get opening and closing balances\n$openingBalanceText = get text in box 660 640 90 180\n$openingBalance = get decimal $openingBalanceText\n$closingBalanceText = get text in box 660 640 400 490\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\n@transactionsTop = get line starting \"Date Date Transaction Details\" => bottom => get line below\n\n// Discard page header\nget last line starting \"Date Date Transaction Details\" => bottom => ignore header above\n\n// Discard page footer\ngo to page 1\nget line starting \"(Continued on next page)\" => top => ignore footer below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total of other account transactions\" => top => get line above\n\n// Discard info on page 1\ngo to page 1\nget line starting \"American Express Services Europe Limited has its registered office\" => top => delete text in box 0 page.left page.right\n\n// Discard info on page 2\ngo to page 1\nget line starting \"How you can pay your statement\" => top => delete text in box 0 page.left page.right\n\n// Discard unwanted text\ndelete all lines starting \"Transaction Process\"\ndelete all lines starting \"Date Date Transaction Details\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"New Transactions for\"\ndelete all lines starting \"Total new spend\"\ndelete all lines starting \"OTHER ACCOUNT TRANSACTIONS\"\ndelete all lines starting \"Total of other account transactions\"\ndelete all lines starting \"Total Cash Withdrawals for\"\ndelete all lines starting \"Total debits for\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 105 140 380 490 600 => describe table false \"*Date[MMM d]\" - Details - #Credit','2021-11-22 05:50:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10273,'BarclaysMasterCard','$source = \"BarclaysMasterCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = \"30\"\n\n// Transactions with CR text are negative\n//set negative marker \"Cr\"\n\n// Get account name and number\n$accountName = get line containing \"| Account Ending\" => get words before \"| Account Ending\" => get text\n$accountnumber = get line containing \"| Account Ending\" => get words after \"| Account Ending\" => take words 1 => get text\n\n// Get period from/to\n\n$periodFrom = get line starting \"Previous Balance as of\" => get words after \"Previous Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line starting \"Statement Balance as of\" => get words after \"Statement Balance as of\" => take words 1 => get date \"MM/dd/yy\"\ndelete text in box page.top page.bottom 260 page.right\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Previous Balance as of\" => get words after \"Previous Balance as of\" => skip words 1 => take words 1 => get decimal\n$closingBalance = get line starting \"Statement Balance as of\" => take last words 1 => get decimal\n\n@transactionsTop = get line starting \"Transaction Date Posting Date Description Amount\" => bottom => get line below\n@transactionsBottom = get last line starting \"Total interest for this period\" => top => get line above\ndelete text in box on every page page.top page.bottom 590 page.right\nget line containing \"Account Ending\" => bottom => ignore header above\n\ndelete all lines starting \"No Payment Received\"\ndelete all lines starting \"No Transaction Activity at This Time\"\ndelete all lines starting \"Total payments for this period\"\ndelete all lines starting \"Purchase Activity for\"\ndelete all lines starting \"Total purchase activity for this period\"\ndelete all lines starting \"To see activity after this statement period,\"\ndelete all lines starting \"Fees and Interest\"\ndelete all lines starting \"Fees Charged\"\ndelete all lines starting \"No fees charged for this period\"\ndelete all lines starting \"Total fees for this period\"\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"No interest charged for this period\"\ndelete all lines starting \"Total interest for this period\"\ndelete all lines starting \"Transaction Date Posting Date Description Amount\"\ndelete all lines starting \"Payments\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 110 180 520 580 => describe table false \"*Date[MMM d]\" - Details #Credit\n','2021-11-22 05:53:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10274,'AmericanExpressUKNewTrans','$source = \"AmericanExpressUKNewTrans\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get account name\n$accountName = get line starting \"Private & Confidential\" => bottom => get line below => get text\n\n// Get account number\n$accountNumber = get line containing \"Membership Number\" => top => get line below => take words 1 => get text\n\n// Get period from/to\n$periodFrom = get line starting \"New Transactions for\" => bottom => get line below => bottom => get line below => take words 2 => get date \"d MMM\"\n$periodTo = get line containing \"Membership Number Statement Date\" => bottom => get line below => skip words 1 => take words 1 => get date \"dd-MMM-yyyy\"\n\n\n$openingBalance = get line containing \"Balance Credits Charges Balance\" => top => get line below => take words 1 => get decimal\n$closingBalance = get line containing \"Balance Credits Charges Balance\" => top => get line below => take last words 2 => skip words 1 => get decimal\n\ngo to page 1\n@deletetext = get line containing \"Private & Confidential\" => top\ndelete text in box @deletetext page.bottom page.left page.right\ngo to page 1\n@deletetext2 = get line containing \"Payment Methods and Correspondence\" => top\ndelete text in box @deletetext2 page.bottom page.left page.right\n\n//ignore header above 720\n\ngo to page 1\n@transactionsTop1 = get line starting \"Date Date Amount\" => if not found then blank => bottom => get line below\n@transactionsBottom1 = get last line starting \"Total of New Transactions\" => top => get line above\n\ngo to page 2\n@transactionsTop2 = get last line starting \"Other Account Transactions\" => if not found then blank => bottom => get line below\n@transactionsBottom2 = get last line starting \"Total of other account transactions\" => if not found then blank => bottom => get line above\n\nignore header above 720\ndelete all lines containing \"Total payments\"\ndelete all lines containing \"New Transactions for\"\ndelete all lines containing $accountNumber\ndelete all lines containing \"American Express Services Europe Limited\"\ndelete all lines containing \"England and Wales\"\ndelete all lines containing \"Conduct Authority\"\ndelete all lines containing \"Other Account Transactions\"\n\n$transactions1 = get multi page table @transactionsTop1 @transactionsBottom1 5 53 90 460 506 488 550 => describe table false \"TransDate[d MMM]\" \"*Date[d MMM]\" Details TransactionType - #Credit\n$transactions2 = get multi page table @transactionsTop2 @transactionsBottom2 5 53 90 460 550 => describe table false \"TransDate[d MMM]\" \"*Date[d MMM]\" Details #Credit\n\n$transactions = combine described tables $transactions1 $transactions2','2025-10-29 06:17:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10275,'MS_CreditCard','$source = \"MS_CreditCard\"\n\n$periodBufferDays = 28\n$features = \"CREDIT_CARD\"\nset negative marker \"CR\"\n\n//@pannelBottom = get line starting \"Your Avantcard\" => top\n// Get account name\n$accountName = get line ending \"Account Number:\" => get words before \"Account Number:\" => take words 3 => get text\n\n// Get account number\n$accountNumber = get line ending \"Account Number:\" => bottom => get line below => take last words 4 => get text\n\n// Get period to\n$periodTo = get line ending \"Statement Date:\" => bottom => get line below => take last words 3 => get date \"dd MMMM yyyy\"\n\ndelete text in box on every page page.top page.bottom 440 page.right\ndelete text in box on every page page.top page.bottom 0 50\n\ngo to page 1\n// Get period from\n$periodFrom = get line containing \"Balance from previous statement\" => bottom => get line below => take words 3 => get date \"dd MMM yy\"\n\nignore header above 592\nignore footer below 300\n\ngo to page 1\n//Get opening/closing balance\n$openingBalance = get line containing \"Balance from previous statement\" => get words after \"Balance from previous statement\" => take words 1 => get decimal\n//$closingBalance = get last line starting \"Present balance\" => get words after \"Present balance\" => take last words 1 => get decimal\n$closingBalance = get last line starting \"Present balance\" => get words after \"Present balance\" => take last words 2 => get decimal\n\ngo to page 1\n@transactionTop = get line containing \"Balance from previous statement\" => bottom =>  get line below\n@transactionBottom = get last line starting \"Present balance\" => top => get line above\n\ndelete all lines starting \"Balance from previous page\"\ndelete all lines containing \"Continued on next page\"\ndelete all lines starting \"Present balance\"\ndelete all lines containing \"Continued from previous page\"\n\n//get all transactions\n\n//$transactions = get multi page table @transactionTop @transactionBottom 55 105 155 350 420 => describe table false - \"*Date[dd MMM yy]\" Details #Credit\n$transactions = get multi page table @transactionTop @transactionBottom 55 105 155 350 420 => describe table false - \"Date[dd MMM yy]\" Details *#Credit','2025-07-24 06:50:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10276,'NedBank_Business','$source = \"NedBank_Business\"\n$periodBufferDays = \"45\"\n\n// Get account name\n$accountName = get line starting \"Account description:\" => skip words 2 => take words 3 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number:\" => skip words 2 => get text\n\n// PeriodFrom and PeriodTo\n$PeriodFrom = get line containing \"BROUGHT FORWARD\" => skip words 1 => take words 1 => get date \"dd/MM/yyyy\"\n$PeriodTo =  get last line containing \"CARRIED FORWARD\" => skip words 1 => take words 1 => get date \"dd/MM/yyyy\"\n\n\ngo to page 1\n// Opening and Closing Balance\n$OpeningBalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\n$ClosingBalance = get last line containing \"CARRIED FORWARD\" => take last words 1 => get decimal\n\ngo to page 1\n// Get start/end of table\n@dateRight = get line containing \"BROUGHT FORWARD\" => get words before \"BROUGHT\" => take last words 1 => right => add 5\n//$dateRight1 = get line containing \"BROUGHT FORWARD\" => get words before \"FORWARD\" => take last words 1 => left => subtract 5\n\n\n@dateLeft = get line containing \"BROUGHT FORWARD\" => get words before \"BROUGHT\" => take last words 1 => left => subtract 5\n\n\n@transactionsTop = get line containing \"BROUGHT FORWARD\" => bottom => get line below\n@transactionsBottom = get last line containing \"CARRIED FORWARD\" => top => get line above\n\ndelete all lines starting \"Profile name:\"\ndelete all lines starting \"Profile number:\"\ndelete all lines starting \"https://nedbankbusinesshub.nedbank.co.za/businessbanking/casastatementprint.bank?RequestFromPopUp=true\"\ndelete all lines containing \"BROUGHT FORWARD\"\ndelete all lines containing \"CARRIED FORWARD\"\ndelete all lines containing \"PROVISIONAL STATEMENT\"\ndelete all lines containing \"Statement Date Transactions Debit Credit Balance\"\ndelete all lines starting \"Date:\"\ndelete all lines starting \"Account description:\"\ndelete all lines starting \"Account number:\"\ndelete all lines starting \"Statement Enquiry\"\ndelete all lines containing \"https://businessbanking.nedbank.co.za\"\ndelete all lines containing \"Statements Print\"\nignore footer below 35\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 150 300 360 435 515 => describe table false - \"*Date[dd/MM/yyyy]\" Details #Debit[-0,000.00] #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 98 150 300 360 435 517 => describe table false - \"*Date[dd/MM/yyyy]\" Details #Debit[-0,000.00] #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 75 146 130 300 385 450 550 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit[-0,000.00] #Credit #Balance\n\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @dateRight 300 385 450 550 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit[-0,000.00] #Credit #Balance','2025-01-09 08:35:42',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10277,'NorthEaston_SavingsBank','$source = \"NorthEaston_SavingsBank\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n@summarytop = get line containing \"Statement\" => top\n@summaryBottom = get line containing \"Number\" => bottom\n@Summarybox = get text in box @summarytop @summaryBottom page.middleX page.right\n\n// Get Period from and Period to\n$periodFrom = get words after @Summarybox \"Statement\" => take words 3 => get date \"MMM dd yyyy\"\n$periodTo = get words after @Summarybox \"Period\" => take words 3 => get date \"MMM dd yyyy\"\n\n//Get account number Account and Ac name\n$accountNumber = get words after @Summarybox \"Account\" => take words 1 => get text\n$accountName = get text in box @summarytop @summaryBottom page.left page.middleX => take words 2 => get text\n\n//Get opening and closing balances\n@balance = get line containing \"Balance Deposits Paid\" => bottom => get line below\n$openingBalance =  take words @balance 1 => get decimal\n$closingBalance = take last words @balance 1 =>  get decimal\n\n//Get start of table\ngo to page 1\n@HeaderTop = get line starting \"Date Description Withdrawals Deposits Balance\" => bottom\n@transactionsTop = get line below @HeaderTop \ndelete text in box page.top @HeaderTop page.left page.right\n\n//Get end of table\n@transactionsBottom = get last line containing \"Overdraft and Returned\" => top => get line above\n\n@lastfooter = get last line containing \"Overdraft and Returned\" => top\ndelete text in box @lastfooter page.bottom page.left page.right\ndelete all lines starting \"Date Description Withdrawals Deposits Balance\"\ndelete all lines containing \"Starting Balance\"\n\n@lastfooter2 = get last line starting \"Interest Summary\" => top\ndelete text in box @lastfooter2 page.bottom page.left page.right\n\n@lastfooter3 = get last line starting \"Rate Changes\" => top\ndelete text in box @lastfooter3 page.bottom page.left page.right\n\n@lastfooter4 = get last line starting \"Balance for Period Yield Paid\" => top\ndelete text in box @lastfooter4 page.bottom page.left page.right\n\ndelete all lines containing \"Balance for Period Yield Paid\" \ndelete all lines containing \"Daily Balance in\"\ndelete all lines starting \"Total Returned Item\"\ndelete all lines starting \"$\"\n\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 110 330 410 475 550 => describe table false \"Date[MMM dd]\" Details #Debit #Credit *#Balance','2021-11-22 05:57:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10278,'SunTrust_bank','$source = \"SunTrust_bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n@Acdetails = get line containing \"Account Number Statement Period\" => bottom => get line below => take last words 4\n\n@accountDetailstop = get line containing \"Account Number Statement Period\" => bottom\n@accountDetailsbottom = get line containing \"Amount Description Amount\" => top\n\n$accountNumber = get text in box @accountDetailstop @accountDetailsbottom 270 380 => get text\n\n@Dates = get text in box @accountDetailstop @accountDetailsbottom 380 600\n\n$periodFrom = get words before @Dates \"-\" => get date \"MM/dd/yyyy\"\n$periodTo =  get words after @Dates \"-\" => get date \"MM/dd/yyyy\"\n\n//Get account name and number\n$accountName =  get text in box 640 600 page.left page.middleX => take words 2 => get text\n//$accountNumber = take words @Acdetails 1 => get text\n\n\n//Get Period from and Period to\n//$periodFrom = take last words @Acdetails 3 => take words 1  => get date \"MM/dd/yyyy\"\n//$periodTo = take last words @Acdetails 1  =>  get date \"MM/dd/yyyy\"\n\n//Get opening and closing balances\n$openingBalance =  get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n//Get start & end of debits table\ngo to page 1\n@creditsTop = get line starting \"Deposits/ Date Amount Serial\" => if not found then blank => bottom => get line below\n@creditsBottom = get last line starting \"Deposits/Credits:\" => if not found then blank => top => get line above\n\n// Get start & end of credits table\ngo to page 1\n@ChecksTop = get line containing \"Check Amount Date\" => if not found then blank => bottom => get line below\n@ChecksBottom = get last line starting \"Checks:\" => if not found then blank => top => get line above\n\n//Get start & end of credits table\ngo to page 1\n@debitsTop = get line starting \"Withdrawals/ Date Amount Serial\" => if not found then blank => bottom => get line below\n@debitsBottom = get last line starting \"Withdrawals/Debits:\" => if not found then blank => top => get line above\n\n@lastfotterTop = get line containing \"Date Balance Collected\" => top\ndelete text in box @lastfotterTop page.bottom page.left page.right\ndelete all lines containing \"Date Amount Serial\"\ndelete all lines starting \"Withdrawals/Debits:\"\ndelete all lines starting \"Debits Paid\"\ndelete all lines starting \"Deposits/Credits:\"\ndelete all lines starting \"Debits Paid\"\ndelete all lines containing \"Check Amount Date\"\ndelete all lines starting \"Checks:\"\ndelete all lines starting \"Number Paid \"\ndelete all lines containing \"Number Paid Number Paid Number Paid\"\ndelete all lines containing \"next page\"\ndelete all lines containing \"Indicates break in\"\ndelete all lines containing \"Continued on next page\"\n\ngo to page 1\n$DLT = delete text in box on every page page.top page.bottom page.left 80 => get text\n//ignore footer below 30\nignore footer below 20\nignore header above 650\n\n//$ChecksL = get multi page table @ChecksTop @ChecksBottom  80 150 224 250 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n//$ChecksM = get multi page table @ChecksTop @ChecksBottom  255 300 390 420 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n//$ChecksR = get multi page table @ChecksTop @ChecksBottom  420 480 555 585 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n\n//$ChecksL = get multi page table @ChecksTop @ChecksBottom  80 150 229 258 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n$ChecksL = get multi page table @ChecksTop @ChecksBottom  80 150 226 258 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n$ChecksM = get multi page table @ChecksTop @ChecksBottom  255 300 392 422 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n$ChecksR = get multi page table @ChecksTop @ChecksBottom  420 480 558 590 => describe table false ChequeNumber *#Debit \"Date[MM/dd]\"\n\n$debits = get multi page table @debitsTop @debitsBottom  80 140 215 270 500 => describe table false \"Date[MM/dd]\" *#Debit - Details\n$credits = get multi page table @creditsTop @creditsBottom 80 140 215 270 500 => describe table false \"Date[MM/dd]\" *#Credit - Details\n\n$transactions = combine described tables $debits $credits $ChecksL $ChecksM $ChecksR','2025-03-20 06:59:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10279,'StanbicBankStatement','$source = \"StanbicBankStatementStanbicBankStatement\"\n\n// Get account number\n$accountNumber = get line containing \"Account Number :\" => get words after \"Account Number :\" => get text\n\n// Get account name\n@accountNametext = get line starting \"Transaction Value Date Transaction\"  => top => get line above\n$accountName = get words after @accountNametext \"Account\" => get words before \"Previous\" => get text\n\n// Get period from/to\n$periodFrom = get line starting \"Statement from :\" => get words after \"Statement from :\" => get words before \"to\" => get date \"dd MM yyyy\"\n$periodto = get line starting \"Statement from :\" => get words after \"to\" => get date \"dd MM yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Description Fee Debits Credits\" => bottom => get line below => take last words 1 => get decimal\n//get line starting \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => get decimal\n\ngo to page 1\n@top = get line containing \"# These fees are inclusive\" => top\n$del_text = delete text in box @top page.bottom page.left page.right => get text\n\ngo to last page\n@pageFooter = get line above 0 => top => get line above => bottom\n@infoLast = get text in box page.top @pageFooter 510 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Transaction Value Date Transaction Description\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line above 0 => top => get line above\n\n// Discard page header and  footer\nignore footer below 26\nignore header above 577\n\ndelete all lines starting \"Transaction Value Date Transaction Description\"\ndelete all lines starting \"BALANCE BROUGHT FORWARD\"\ndelete all lines starting \"STATEMENT OPENING BALANCE\"\ndelete all lines starting \"Account Type\"\ndelete all lines starting \"BANK STATEMENT / TAX INVOICE\"\ndelete all lines starting \"BALANCE AS AT\"\ndelete all lines starting \"# These fees are inclusive\"\ndelete all lines ending \"Previous Account Number :\"\n\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 75 122 295 340 402 490 570 => describe table false \"*Date[dd-MM-yyyy]\" - Details - #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 75 122 295 340 402 490 => describe table false \"*Date[dd-MM-yyyy]\" - Details - #Debit #Credit','2025-07-02 05:35:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10280,'Westpac_Card','$source = \"Westpac_Card\"\n$features = \"CREDIT_CARD\"\n$periodbufferdays = 14\n\n@Summarytop = get line containing \"Account Number\" => bottom\n@Summarybottom = get line containing \"Closing Balance\" => bottom => get line below => bottom\n@Summary = get text in box @Summarytop @Summarybottom 410 590\n\n// Get closing balance\n$closingBalance = get words after @Summary \"Closing Balance\" => get decimal\n\n// Get account number\n$accountNumber = get words after @Summary \"Account Number\" => get words before \"Due Date\" => get text\n\n// Get account name\n$accountName = get line starting \"Cardholder Name\" => bottom => get line below => take words 4 => get text\n\n// Get period from/to\n@period = get line starting \"No. of Days in Statement Cycle\" => bottom => get line below\n$periodFrom = skip words @period 1 => take words 3 => get date \"d MMM yy\"\n$periodTo =  skip words @period 4 => take words 3 => get date \"d MMM yy\"\n\n// Get opening balance\n$openingBalance = skip words @period 11 => get decimal\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line starting \"Transaction\" => bottom => get line below\n//@transactionsBottom = get line starting \"Transaction\" => bottom => get line below => top => get break below => get line at\n@transactionsBottom = get last line containing \"Description Debits\" => bottom => get line below => bottom => get line below => top => get break below => get line at\n\ngo to page 1\ndelete all lines starting \"Page\"\ndelete all lines starting \"Westpac Altitude Qantas\"\ndelete all lines starting \"Transaction\"\ndelete all lines containing \"Description Debits\"\ndelete all lines containing \"Westpac Banking Corporation ABN\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 104 450 590 => describe table false \"*Date[d MMM yy]\" Details #Credit','2025-05-06 06:26:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10281,'Community_Bank','$source = \"Community_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get words before \"Statement\" => get text\n$accountName = get line containing \"Primary Account\" => get words before \"Primary Account\" => get text\n\n$openingBalance =  get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n$periodFrom = get line containing \"Statement Dates\" => get words between \"Dates\" \"thru\" => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => get words before \"Previous\" => get date \"M/dd/yy\"\n\ngo to page 1\n@transactionsTopCredit = get line starting \"Deposits and Other Credits\" => bottom => get line below\n@transactionsBottomCredit = get line containing \"Checks and Withdrawals\" => top => get line above\n\ngo to page 1\n@transactionsTopDebit = get line containing \"Checks and Withdrawals\" => bottom => get line below\n@transactionsBottomDebit = get line containing \"CHECKS IN NUMBER ORDER\" => top => get line above\n\n@transactionsTopChecks = get line containing \"CHECKS IN NUMBER ORDER\" => bottom => get line below\n@transactionsBottomChecks = get line starting \"Daily Balance Information\" => top => get line above\n\ndelete all lines containing \"Deposits and Other Credits\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"Checks and Withdrawals\"\ndelete all lines containing \"CHECKS IN NUMBER ORDER\"\ndelete all lines containing \"Check No\"\ndelete all lines containing \"Daily Balance Information\"\ndelete all lines starting \"Date Check\"\ndelete all lines containing \"Denotes missing check numbers\"\n\ngo to page 1\nignore header above 450\n\n$transactionsCredit = get multi page table @transactionsTopCredit @transactionsBottomCredit 12 68 260 400 => describe table false \"*Date[M/dd]\" Details #Credit\n$transactionsDebit = get multi page table @transactionsTopDebit @transactionsBottomDebit 12 60 260 400 => describe table false \"*Date[M/dd]\" Details #Credit\n$transactionsLeft = get multi page table @transactionsTopChecks @transactionsBottomChecks 12 50 100 174 => describe table false \"*Date[M/dd]\" Details #Debit\n$transactionsMiddle = get multi page table @transactionsTopChecks @transactionsBottomChecks 180 215 270 343 => describe table false \"*Date[M/dd]\" Details #Debit\n$transactionsRight = get multi page table @transactionsTopChecks @transactionsBottomChecks 348 380 450 510 => describe table false \"*Date[M/dd]\" Details #Debit\n$transactions = combine described tables $transactionsCredit $transactionsDebit $transactionsLeft $transactionsMiddle $transactionsRight','2021-12-06 08:54:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10282,'Fifth_Third_Bank','$source = \"Fifth_Third_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\ndelete white words\r\n\r\ngo to page 2\r\n@navigate_to_summary = get line containing \"Date Amount Description\"\r\n@top0 = get line containing \"Internet Banking &\" => top\r\n@bottom0 = get line containing \"Date Amount Description\" => top => get line above => top\r\n@check_text = get line containing \"Date Amount Description\"  => if not found then blank => top => get line above => top\r\n$Deleted_Text = delete text in box @top0 @bottom0 0 page.right => get text\r\n\r\ngo to page 2\r\n@navigate_to_summary = get line containing \"Date Amount Description\"\r\n@top1 = get line containing \"Internet Banking &\" => top\r\n@bottom1 = get line containing \"Date Amount Description\" => top => get line above => top\r\n@check_text1 = get line containing \"Date Amount Description\"  => if not found then blank => top => get line above => top\r\n$Deleted_Text1 = delete text in box @top1 @bottom1 0 page.right => get text\r\n\r\ngo to page 2\r\n@navigate_to_summary = get line containing \"Date Amount Description\"\r\n@top2 = get line containing \"Internet Banking &\" => top\r\n@bottom2 = get line containing \"Date Amount Description\" => top => get line above => top\r\n@check_text2 = get line containing \"Date Amount Description\"  => if not found then blank => top => get line above => top\r\n$Deleted_Text2 = delete text in box @top2 @bottom2 0 page.right => get text\r\n\r\ngo to page 1\r\n$deleteText1 = get text in box page.top 695 page.left page.right => take last words 3 => get text\r\n\r\ngo to page 1\r\n$deleteText = get line containing \"Business Banking Support\" => bottom => get line below => get text\r\ndelete all lines containing $deleteText\r\ndelete all lines containing $deleteText1\r\n\r\ngo to page 1\r\n$accountName = \"Fifth_Third_Bank_user\"\r\n$accountNumber = get line containing \"Account Summary\" => get words after \"Account Summary\" => skip words 1 => take words 1 => get text\r\n\r\nset negative marker \"(\"\r\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\r\n\r\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@top3 = get line containing \"Beginning Balance\" => top\r\n@bottom3 = get line containing \"Ending Balance\" => bottom\r\n$Deleted_Text3 = delete text in box @top3 @bottom3 0 page.right => get text\r\n\r\n$periodfrom = get line containing \"Statement Period Date\" => get words between \"Statement Period Date\" \"-\" => get date \"M/d/yyyy\"\r\n$periodto = get line containing \"Statement Period Date\" => get words after \"-\" => take words 1 => get date \"M/d/yyyy\"\r\n\r\ndelete all lines starting \"Page\"\r\ndelete all lines containing \"Business Banking Support\"\r\n\r\ndelete all lines containing \"Banking Center\"\r\n\r\ngo to page 1\r\ndelete all lines containing \"continued\"\r\ndelete all lines starting \"/\"\r\n\r\ngo to page 1\r\n@transactionstopCheck = get line containing \"Number Date Paid Amount\" => if not found then blank => bottom => get line below\r\n@transactionsbottomCheck = get line starting \"Withdrawals / Debits\" => top => get line above\r\n\r\nignore header above 720\r\nignore footer below 35\r\n\r\ndelete all lines containing \"Withdrawals / Debits - continued\"\r\ndelete all lines containing \"Withdrawals / Debits\"\r\n\r\n$transactionsCheckLeft = get multi page table @transactionstopCheck @transactionsbottomCheck 10 90 140 215 => describe table false Details \"Date[MM/dd]\" *#Debit\r\n$transactionsCheck = get multi page table @transactionstopCheck @transactionsbottomCheck 210 273 310 390 => describe table false Details \"Date[MM/dd]\" *#Debit\r\n$transactionsCheckRight = get multi page table @transactionstopCheck @transactionsbottomCheck 390 455 500 580 => describe table false Details \"Date[MM/dd]\" *#Debit\r\n\r\n@transactionstopDebit = get line containing \"Date Amount Description\" => bottom => get line below\r\ndelete all lines containing \"Date Amount Description\"\r\n@transactionsbottomDebit = get line starting \"Deposits / Credits\" => top => get line above\r\n\r\n$transactionsDebit = get multi page table @transactionstopDebit @transactionsbottomDebit 10 80 185 600 => describe table false \"*Date[MM/dd]\" #Debit Details\r\n\r\n@transactionstopCredit = get line starting \"Deposits / Credits\" => bottom => get line below\r\ndelete all lines starting \"Deposits\"\r\n\r\ndelete all lines containing \"Date Amount Description\"\r\n@transactionsbottomCredit = get line starting \"Daily Balance Summary\" => top => get line above\r\n\r\n$transactionsCredit = get multi page table @transactionstopCredit @transactionsbottomCredit 10 80 185 600 => describe table false \"Date[MM/dd]\" *#Credit Details\r\n\r\n$transactions = combine described tables $transactionsCheckLeft $transactionsCheck $transactionsCheckRight $transactionsDebit $transactionsCredit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10283,'HSBC_CommercialCard_Summary','$source = \"HSBC_CommercialCard_Summary\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\n\nset negative marker \"CR\"\n\n$accountname = get text in box 1060 1020 page.left 200 => take words 2 => get text\n\n@accountnoTop = get line containing \"PLEASE QUOTE THIS NUMBER\" => bottom => get line below => top\n@accountnoBottom = get line containing \"PLEASE QUOTE THIS NUMBER\" => bottom => get line below => bottom\n$accountnumber = get text in box @accountnoTop @accountnoBottom 380 480 => get text\n\n$periodto = get line containing \"STATEMENT DATE:\" => get words after \"STATEMENT DATE:\" => get date \"dd MMMM yyyy\"\n\n$openingbalance = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\" => take words 1 => get decimal\n//$closingbalance = get line containing \"THE BALANCE DUE ON\" => take last words 1 => get decimal\n@closingbalancetop = get line containing \"DESCRIPTION/CARDHOLDER LIMIT\" => bottom\n@closingbalancebottom = get line above 0 => bottom\n@infoLast = get text in box @closingbalancetop @closingbalancebottom 678 850\n$closingbalance = take last words @infoLast 1 => get decimal\n\n@periodfromText = get line containing \"BY US DATE\" => bottom => get line below\n$periodfrom = take words @periodfromText 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n@CreditEntryTop = get line containing \"DIRECT DEBIT PAYMENT - THANK YOU\"\n@CreditEntryBottom = get line containing \"DIRECT DEBIT PAYMENT - THANK YOU\"\n\ngo to page 1\n@transactionsTop = get line starting \"BY US DATE\" => bottom => get line below\n@transactionslast = get last line starting \"BY US DATE\"\n@transactionsBottom  = get line above 0\n\ndelete all lines starting \"RECEIVED TRANSACTION \"\ndelete all lines starting \"BY US DATE\"\ndelete all lines containing \"TOTAL\"\ndelete all lines containing \"PREVIOUS BALANCE\"\nignore header above 1000\n\n//$Creditentry = get multi page table @CreditEntryTop @CreditEntryBottom 0 100 410 678 page.right => describe table false \"Date[dd MMM yyyy]\" - Details *#Debit\n//$DebitEntry = get multi page table @transactionsTop @transactionsBottom 0 100 180 650 page.right => describe table false \"Date[dd MMM yyyy]\" \"TransactionDate[dd MMM yyyy]\" Details *#Credit\n$Creditentry = get multi page table @CreditEntryTop @CreditEntryBottom 0 100 410 678 850 => describe table false \"Date[dd MMM yyyy]\" - Details *#Credit\n$DebitEntry = get multi page table @transactionsTop @transactionsBottom 0 100 180 650 850 => describe table false \"Date[dd MMM yyyy]\" \"TransactionDate[dd MMM yyyy]\" Details *#Credit\n$transactions = combine described tables $Creditentry $DebitEntry','2024-05-08 13:58:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10284,'AtlanticUnionBank','$source = \"AtlanticUnionBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//$accountname = get text in box 700 660 page.left page.middleX => take words 2 => get text\n\n$accounttop = get line containing \"Account Name Account Number\" => bottom\n$accountbtm = get line containing \"Account Name Account Number\" => bottom => get line below => bottom => get line below => bottom\n$accountnumber = get text in box $accounttop $accountbtm 240 340 => take words 1 => get text\n\n$accountname = get text in box 700 660 page.left page.middleX => take words 2 => get text\n\n\n// Get opening and closing balances\n@openingtxt = get line containing \"Beginning Balance\"\n@closingtxt = get line containing \"Ending Balance\"\n\n$openingbalance = get words after @openingtxt \"Beginning Balance\" => take words 2 => take last words 1 => get decimal\n$closingbalance = get words after @closingtxt \"Ending Balance\" => take words 2 => take last words 1 => get decimal\n\n$periodfrom = get words after @openingtxt \"Beginning Balance\" => take words 1 => get date \"M/dd/yy\"\n$PeriodTo =  get words after @closingtxt \"Ending Balance\" => take words 1 => get date \"M/dd/yy\"\n\ngo to page 1\n@firsthead = get line containing \"Date Activity\" => top\ndelete text in box page.top @firsthead page.left page.right\n$transactionsTop = get line containing \"Date Activity\" => bottom => get line below\n@transactionslast = get last line containing \"Date Activity\"\n//\"Date Activity Description Deposits Withdrawals Balance\"\n@transactionsBottom = get line above 0\n\nignore header above 555\ndelete all lines starting \"Transaction\"\ndelete all lines containing \"Date Activity Description\"\ndelete all lines containing \"Date Activity\"\n\n@checkstop = get last line starting \"Checks\" => top\ndelete text in box @checkstop page.bottom page.left page.right\n\n//Read the transactions\n$transactions = get multi page table $transactionsTop @transactionsBottom 50 85 330 415 500 600  => describe table false \"*Date[M/dd]\" Details #Credit #Debit #Balance','2025-04-15 05:12:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10285,'DBS','$source = \"DBS\"\n$periodBufferDays = 14\n\n//Discard hidden text\n//delete white words\n//delete tiny words\n//delete rotated words\n\n@accountnametext = get line containing \"Account Name :\" => get words after \"Account Name :\"\n$accountname = take words @accountnametext 9 => get text\n//$accountnumber = get line containing \"Account No:\" => get words after \"Account No:\"\n// Get account number\n@accountNumberText = get line containing \"Account Number :\" => get words after \"Account Number :\"\n$accountNumber = take words @accountNumberText 1 => get text\n$periodfrom = get line containing \"Opening Balance :\" => get words after \"Opening Balance :\" => take words 2 => take last words 1 => get date \"dd-MMM-yyyy\"\n$periodto = get line containing \"Ledger Balance :\" => get words after \"Ledger Balance :\" => take words 2 => take last words 1 => get date \"dd-MMM-yyyy\"\n\n\n//go to page 1\n@openingbalanceText = get line containing \"Opening Balance :\" => get words after \"Opening Balance :\"\n$openingbalance = take words @openingbalanceText 1 => get text\n@closingbalanceText = get line containing \"Ledger Balance :\" => get words after \"Ledger Balance :\"\n$closingbalance = take words @closingbalanceText 1 => get text\n\n//go to page 1\n@transactionsTop = get line starting \"Date Value Date Transaction Details Debit Credit Running Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Total Debit Count :\" => top => get line above\n\n//ignore header above 640\ndelete all lines starting \"Printed By :\"\ndelete all lines starting \"Printed On :\"\ndelete all lines starting \"Date Value Date Transaction Details Debit Credit Running Balance\"\n//delete all lines containing \"Account No:\"\ndelete all lines starting \"Account Details\"\n//delete all lines containing \"Balance Carried Forward\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 115 165 350 420 500 580 => describe table false \"Date[dd-MMM-yyyy]\" \"ValueDate[dd-MMM-yyyy]\" Details  #Debit #Credit *#Balance','2021-12-06 08:57:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10286,'BFCBank','$source = \"BFCBank\"\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\ndelete tiny words\ndelete white words\n@accountNumberTop = get line containing \"Sort Code Account Number\" => Bottom\n@accountNumberBottom = get line containing \"Sort Code Account Number\" => Bottom => get line below => Bottom\n@accountNumberText = get text in box @accountNumberTop @accountNumberBottom page.middleX page.right\n$accountNumber = take words  @accountNumberText 2  => take last words 1 => get text\n\n@accountNameTop = get line containing \"Statement Period\" => top => get line above => top => get line above => top\n@accountNameBotton = get line containing \"Statement Period\" => top\n$accountName = get text in box @accountNameTop @accountNameBottom  page.left page.middleX => take words 2 => get text   \n\n@accountPeriod = get line containing \"Statement Period\" => get words after \"Statement Period\"\n$periodTo = take words @accountPeriod 3 => take last words 1 => get date \"dd/MM/yyyy\"\n$periodFrom = take words @accountPeriod 1 => get date \"dd/MM/yyyy\"\n\n// Get opening and closing balances \n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$ClosingBalance = get last line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => get decimal\ngo to page 1\n@transactionsTop = get line containing \"Date Value Date Payment Details Paid Out Paid In Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Balance Carried Forward\" => top => get line above\n\ndelete all lines containing \"Date Value Date Payment Details Paid Out Paid In Balance\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Balance Carried Forward\"\ndelete all lines containing \"Balance Brought Forward\"\ndelete all lines containing \"Sheet No.\"\n\n\n//delete text in box on every page page.top 575 page.left page.right \nignore header above 705\nignore footer below 50\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 85 145 320 415 500 585 => describe table false \"Date[dd/MM/yyyy]\" - Details #Debit #Credit *#Balance','2022-01-18 12:18:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10287,'HampdenAndCo','$source = \"HampdenAndCo\"\nset negative marker \"DR\"\ndelete white words\ndelete tiny words\n// Get account number and name\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => get words before \"Currency:\" => get text\n$accountname = get line starting \"Client name:\" => get words after \"Client name:\" => get text\n\n// Get Periods\n$periodfrom = get line starting \"Statement period:\" => get words after \"Statement period:\" => get words before \"-\" => get date \"d MMMM yyyy\"\n$periodto = get last line starting \"Statement period:\" => get words after \"-\" => get words before \"Statement date:\" => get date \"d MMMM yyyy\"\n\n// Get Opening & Closing balance\ngo to page 1\n$openingbalance = get line starting \"Brought Forward\" => get words after \"Brought Forward\" => get decimal\n//$closingBalance = get last line starting \"Carried Forward\" => get words after \"Carried Forward\" => get text\n\n@TEXTBOXTop1 = get last line containing \"Total\" => top\n@TEXTBOXBottom1 = get last line starting \"Carried\" => bottom\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 490 560\n$closingBalance = take last words $TEXTBOX1 2 => get decimal\n//get table top & bottom\ngo to page 1\n@transactionstop = get line starting \"Date Transaction type/detail\" => bottom => get line below => bottom => get line below\n@transactionsbottom = get last line containing \"Total\" => top => get line above\n\n// stripping unwanted records from txns\nget line starting \"Date Transaction type/detail Debit\" => bottom => ignore header above\nget line starting \"Hampden & Co plc Registered\" => top => ignore footer below\ndelete all lines starting \"Brought Forward\"\ndelete all lines starting \"Total Debits/Credits\"\ndelete all lines starting \"Carried Forward\"\n\nignore header above 475\nignore footer below 35\n// Read the transactions\n//$transactions = get multi page table @transactionstop @transactionsbottom 40 95 290 380 470 534 => describe table false \"Date[dd MMM yyyy]\" Details #Debit #Credit *#Balance\n\n$transactions = get multi page table @transactionstop @transactionsbottom 44 115 320 400 480 550 => describe table false \"Date[dd MMM yyyy]\" Details #Debit #Credit *#Balance','2025-05-06 06:26:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10288,'AmericanExpressUS_Card_Amazon','$source = \"AmericanExpressUS_Card_Amazon\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 31\n\nset negative marker \"CR\"\n\n// Get period from/to\n$periodFrom = get line starting \"Closing Date\" => skip words 2 => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line starting \"Closing Date\" => get words after \"Next Closing Date\" => take words 1 =>  get date \"MM/dd/yy\"\n\n//Get account name and number\n$accountNumber = get line containing \"Account Ending\" => get words after \"Account Ending\" => take words 1 => get text\n$accountName = get line starting \"Closing Date\" => top => get line above => get words before \"Customer Care:\" => get text\n\n// Get Opening and Closing Balance\n@panelTop = get line containing \"Account Summary\" => bottom\n@panelWords = get text in box @panelTop page.bottom 390 page.right\n$openingBalanceText = get words after @panelWords \"Previous Balance\" => take words 1 => get text\n$closingBalanceText = get words after @panelWords \"New Balance\" => take words 1 => get text\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\ndelete text in box page.top page.bottom 390 page.right\n\n// Get closing Balance\ngo to page 1\n$closingBalance = get line starting \"Total Balance\" => get words after \"Total Balance\" => take words 1 => get decimal\n\n// Get start & end of credits table\ngo to page 3\n// Get Start of CREDIT transactions\n\n\n@creditsTop = get line starting \"Detail\" => if not found then blank => bottom => get line below\n//@creditsBottom = get last line starting \"New Charges\" => if not found then blank =>  top => get line above\n//@creditsBottom = get last line starting \"New Charges\" => if not found then blank => bottom => get break below => get line at\n\n@creditsBottom = get last line starting \"Total Fees for this Period\" => top => get line above\n\ngo to page 1\n@delTop = get line starting \"New Charges\" => top\n@delbottom = get line starting \"Total New Charges\" => bottom\n$delsum = delete text in box @delTop @delbottom  page.left page.right => get text\n\n\n// Get start & end of debits table\ngo to page 3\n@delName = get line starting \"Closing Date\" => if not found then blank => top => get line above => get text\n\n// Get Start of DEBIT transactions\n@debitsTop = get line starting \"Card Ending\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get last line starting \"Total Fees for this Period\" => if not found then blank => top => get line above\n\n// Get start & end of interest table\ngo to page 3\n\n// Get Start of interest transactions\n@interestTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below => bottom => get line below\n@interestBottom = get last line starting \"Total Interest Charged for this Period\" => if not found then blank => top => get line above\n\n\n\n// Discard page header\ngo to page 3\nget line below page.top => bottom => ignore header above\n\n// Discard page footer\nget line above 0 => top => ignore footer below\n\n\n\n// Remove unwanted lines\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Summary\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"Credits\"\ndelete all lines starting \"Amount\"\ndelete all lines starting \"Detail\"\ndelete all lines starting \"Closing Date\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"Amount\"\ndelete all lines starting \"Interest\"\ndelete all lines starting \"Standard Balance Charges\"\ndelete all lines starting \"New Charges\"\ndelete all lines starting \"Total New Charges\"\ndelete all lines starting \"Card Ending\"\ndelete all lines starting @delName\n\n// Read the transactions\n@credits = get multi page table @creditsTop @creditsBottom 20 90 500 650 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 20 90 500 650 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n@interest = get multi page table @interestTop @interestBottom 20 90 500 650 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n\n//$transactions = combine described tables @credits @debits @interest\n$transactions = combine described tables @credits @interest','2025-03-20 07:08:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10289,'NedBank_Business2','$source = \"NedBank_Business2\"\n\n$periodBufferDays = \"45\"\n\n// Get account name\n$accountName = get line starting \"Account description:\" => skip words 2 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account number:\" => skip words 2 => get text\n\n// PeriodFrom and PeriodTo\n$PeriodFrom = get line containing \"BROUGHT FORWARD\" => take words 1 => get date \"dd/MM/yyyy\"\n$PeriodTo =  get last line containing \"CARRIED FORWARD\" => take words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n// Opening and Closing Balance\n$OpeningBalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\n$ClosingBalance = get last line containing \"CARRIED FORWARD\" => take last words 1 => get decimal\n\ngo to page 1\n// Get start/end of table\n@transactionsTop = get line containing \"BROUGHT FORWARD\" => bottom => get line below\n@transactionsBottom = get last line containing \"CARRIED FORWARD\" => top => get line above\n\ngo to page 1\n@Navigate_to_header = get line containing \"Date Transactions Debit\"\n$date_right = get line containing \"Date Transactions Debit\" => get words before \"Transactions\" => take last words 1 => right => add 8\n$Transactions_right = get line containing \"Date Transactions Debit\" => get words after \"Transactions\" => take words 1 => left => subtract 10\n$Debit_right = get line containing \"Date Transactions Debit\" => get words after \"Debit\" => take words 1 => left => subtract 10\n$Credits_right = get line containing \"Date Transactions Debit\" => get words after \"Credit\" => take words 1 => left => subtract 20\n$Balance_right = get line containing \"Date Transactions Debit\" => get words after \"Credit\" => take words 1 => right => add 35\n\n\ndelete all lines starting \"Profile name:\"\ndelete all lines starting \"Profile number:\"\ndelete all lines containing \"BROUGHT FORWARD\"\ndelete all lines containing \"CARRIED FORWARD\"\ndelete all lines containing \"PROVISIONAL STATEMENT\"\ndelete all lines containing \"Date Transactions Debit Credit Balance\"\ndelete all lines starting \"Statement:\"\ndelete all lines starting \"Date:\"\ndelete all lines starting \"Account description:\"\ndelete all lines starting \"Account number:\"\ndelete all lines starting \"Statement Enquiry\"\ndelete all lines containing \"https://businessbanking.nedbank.co.za\"\ndelete all lines starting \"Notice\"\ndelete all lines containing \"Whilst every effort has been made to\"\ndelete all lines containing \"loss or damage suffered by any person as a result\"\ndelete all lines containing \"verified against the final statement\"\ndelete all lines containing \"# - VAT is applicable for this transaction\"\ndelete all lines containing \"* - Uncleared Effect (ENC) is applicable for this transaction\"\n\n\ndelete all lines containing \"provided by Nedbank to the client.\"\ndelete all lines containing \"suffered by any person as a result of their reliance\"\nignore footer below 35\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 280 360 435 515 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit[-0,000.00] #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 $date_right $Transactions_right $Debit_right $Credits_right $Balance_right => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit[-0,000.00] #Credit #Balance','2025-06-25 11:52:18',0);
