INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10297,'CashPlus_BusinessAcc','$source = \"CashPlus_BusinessAcc\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$periodBufferDays = 30\n\n@accountDetailsbottom = get line containing \"Card ending\" => top\n@accountDetails = get text in box page.top @accountDetailsbottom 0 page.middleX\n$accountName = get words before @accountDetails \"name:\" => take words 2 => get text\n$accountNumber = get words after @accountDetails \"Account number:\" => get words before \"Currency\" => get text\n//$accountname = get line containing \"Account held under company name:\" => get words after \"Account held under company name:\" => take words 3 => get text\n//$accountnumber = get text in box 700 685 page.left 150 => take last words 1 => get text\n\ngo to page 1\n$closingbalanceText = get line containing \"Card ending\" => bottom => get line below => take last words 1 => get text\n$closingbalance = get line containing \"Card ending\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n$Text1 = get line containing $closingbalanceText => bottom\n$Text2 = get line containing \"Amount\" => top\n$textbox = get text in box $Text1 $Text2 450 page.right\n$periodfrom = get words before $textbox \"to\" => take words 1 => get date \"dd/MM/yyyy\"\n//$periodto = get words after $textbox \"to\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodto = get line containing \"Card ending\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n\n@balanceCoor = get line containing \"Card ending\" => take last words 1 => left\n@balanceCoor = subtract @balanceCoor 1.5\n@amountCoor = get line containing \"Card ending\" => get words after \"Description\" => left\n@amountCoor = subtract @amountCoor 7\n@CardendingCoor = get line containing \"Card ending\" => get words before \"ending\" => take last words 1 => left\n@CardendingCoor = subtract @CardendingCoor 2\n//This is included to retrieve the correct dates when the date format follows dd/MM/yyyy hh:mm:ss.\n@DateCoor = get line containing \"Card ending\" => bottom => get line below => take words 1 => right\n@DateCoor = add @DateCoor 2\n\ngo to page 1\n@transactionsTop = get line containing \"Card ending\" => bottom => get line below\n@transactionsBottom = get last line containing \"£\"\n\n// ignore extra header\nget line containing \"Card ending\" => bottom =>  ignore header above\n\ndelete all lines starting \"Cashplus is issued by\"\ndelete all lines containing \"Cards are serviced by\"\ndelete all lines containing \"Registered in England and Wales under company numbers\"\ndelete all lines containing \"this statement can’t be used to provide proof of your address\"\ndelete all lines containing \"Advanced Payment Solutions Limited\"\ndelete all lines containing \"Prudential Regulation Authority\"\ndelete all lines containing \"PRA and regulated by the FCA\"\ndelete all lines containing \"this statement can’t be used to\"\ndelete all lines containing \"Registration No\"\ndelete all lines containing \"subject to approval and affordability\"\ndelete all lines containing \"accounts continue to meet APS credit criteria\"\ndelete all lines containing \"Zempler Bank Ltd is registered in\"\ndelete all lines containing \"Financial Conduct Authority and\"\n\nignore footer below 50\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 76 @amountCoor @balanceCoor 570 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @DateCoor @CardendingCoor @amountCoor @balanceCoor 570 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Balance','2025-01-23 08:29:42',0);
