INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10299,'PNC_Bank_Without_PostedAmount','$source = \"PNC_Bank_Without_PostedAmount\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\nignore footer below 50\n\n// Get period from/to\n$period = get line starting \"For the period\"  => get words after \"For the period\" => take words 3\n$periodFrom = take words $period 1 => get date \"MM dd yyyy\"\n$periodTo = take last  words $period 1 => get date \"MM dd yyyy\"\n\n// Get account number\n$accountNumber = get line starting \"Primary account number:\" => get words after \"Primary account number:\" => take words 1 => get text\n\n\n// Get account name\n$accountName = get text in box 750 690 0 200 => take words 3 => get text\n\nget line starting \"Balance Summary\"\n$openingBalance = get line starting \"balance other additions deductions balance\" => bottom => get line below => take words 1 => get decimal\n$closingBalance = get line starting \"balance other additions deductions balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 2\nget line starting \"Account Number:\" => bottom => ignore header above\n@finalTop = get line containing \"Daily Balance Detail\" => bottom\ndelete text in box @finalTop page.bottom page.left page.right\nget line starting \"Activity Detail\" => bottom\n\n\n//Checks table\ngo to page 1\n@checksTransactionTop = get line containing \"Checks and Substitute Checks\" => if not found then blank => bottom => get line below => bottom => get line below\n//@delTop2 = get line containing \"Checks and Substitute Checks\" => bottom\n//@delBottom2 = get line containing \"Checks and Substitute Checks\" => bottom => get line below => bottom => get line below => bottom\n//delete text in box @delTop2 @delBottom2 page.left page.right\n//@checksTransactionBottom = get line containing \"Date Amount\" => top => get line above => top => get line above\n@checksTransactionBottom = get line containing \"listed totaling\" => top => get line above\n\n@deletecheckTop2 = get line containing \"Checks and Substitute Checks - continued\" => top\ndelete all lines containing \"Checks and Substitute Checks - continued\"\n\ndelete all lines starting \"Check Date Reference\"\ndelete all lines starting \"number Amount paid number\"\n\n\n//get checks left transactions\n//@checksLeftTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 20 130 175 210 260 => describe table false Details #Debit \"*Date[MM/dd]\" TransactionType\n@checksLeftTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 20 127 175 210 260 => describe table false Details #Debit \"*Date[MM/dd]\" TransactionType\n\n//get checks right transactions\n@checksRightTransactions = get multi page table @checksTransactionTop @checksTransactionBottom 270 370 430 460 520 => describe table false Details #Debit \"*Date[MM/dd]\" TransactionType\n\n//deleting check tables\ngo to page 1\n@deletecheckbottom2 = get line containing \"listed totaling\" => top\ndelete text in box @deletecheckTop2 @deletecheckbottom2 0 page.right\ndelete all lines containing \"* Gap in check sequence\"\n\ngo to page 1\n@deletecheckTop = get line containing \"Checks and Substitute Checks\" => top\n@deletecheckbottom = get line containing \"Checks and Substitute Checks\" => bottom => get break below => get line at => bottom\ndelete text in box @deletecheckTop @deletecheckbottom 0 page.right\ndelete all lines containing \"Checks and Substitute Checks\"\n\n\ngo to page 1\n//Deposits table\n@depositesTrandsactionTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@bottom1 = get line containing \"Additions totaling\" => bottom\ndelete text in box page.top @bottom1 380 page.right\n@delTop = get line starting \"Deposits\" => bottom\n@delBottom = get line starting \"Deposits\" => bottom => get line below => bottom\ndelete text in box @delTop @delBottom page.left page.right\n@top = get line starting \"Deposits and Other Additions - continued\" => bottom\n@footer = get line starting \"Deposits and Other Additions - continued\" => if not found then blank =>  bottom => get line below => bottom\ndelete text in box @top @footer page.left page.right\n//@depositesTransactionBottom = get line starting \"Check Date\" => top => get line above => top => get line above\n@depositesTransactionBottom = get line starting \"Banking/\" => top => get line above\n\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Deposits continued on next page\"\n\n//get deposits transactions\n//@depositesTransaction = get multi page table @depositesTrandsactionTop @depositesTransactionBottom 20 110 165 400 => describe table false \"*Date[MM/dd]\" #Credit Details\n@depositesTransaction = get multi page table @depositesTrandsactionTop @depositesTransactionBottom 20 90 165 400 => describe table false \"*Date[MM/dd]\" #Credit Details\n\n\n\n// Banking/Card Purchases table\n@bankingCardTop = get line starting \"Banking/\" => if not found then blank =>  bottom => get line below\ndelete text in box page.top page.bottom 380 page.right\n@delTop3 = get line starting \"Banking/\" => top\n@delBottom3 = get line starting \"Banking/\" => bottom => get line below => bottom\ndelete text in box @delTop3 @delBottom3 page.left page.right\n@top1 = get line starting \"Banking/Check Card Withdrawals and Purchases - continued\" => top\n@footer1 = get line starting \"Banking/Check Card Withdrawals and Purchases - continued\" => if not found then blank => bottom => get line below => bottom\ndelete text in box @top1 @footer1 page.left page.right\n\n\ndelete text in box on every page page.top page.bottom 380 page.right\n@top3 = get line starting \"Banking/\" => top\n@footer3 = get line starting \"Banking/Debit Card Withdrawals and Purchases - continued\" => if not found then blank => bottom => get line below => bottom\ndelete text in box @top3 @footer3 page.left page.right\ndelete text in box page.top page.bottom 380 page.right\n\n@top33 = get line starting \"Banking/Debit Card Withdrawals and Purchases - continued\" => top\n@footer33 = get line starting \"Banking/Debit Card Withdrawals and Purchases - continued\" => if not found then blank => bottom => get line below => bottom\ndelete text in box @top33 @footer33 page.left page.right\ndelete text in box page.top page.bottom 380 page.right\n\n@bankingCardBottom = get line containing \"Date Amount\" => top => get line above => top => get line above\n\ndelete all lines starting \"Banking/\"\n\n//get Banking/Card Purchases transactions\n//@bankingCardTransactions = get multi page table @bankingCardTop @bankingCardBottom 20 110 165 400 => describe table false \"*Date[MM/dd]\" #Debit Details\n@bankingCardTransactions = get multi page table @bankingCardTop @bankingCardBottom 20 90 165 400 => describe table false \"*Date[MM/dd]\" #Debit Details\n\n\n// Online and Electronic Purchases table\n@onlineElectronicTop = get line starting \"Online and Electronic\" => if not found then blank =>  bottom => get line below\ndelete text in box page.top page.bottom 380 page.right\n@delTop4 = get line starting \"Online and Electronic\" => top\n@delBottom4 = get line starting \"Online and Electronic\" => bottom => get line below => bottom\ndelete text in box @delTop4 @delBottom4 page.left page.right\n@top2 = get line starting \"Online and Electronic Banking Deductions - continued\" => bottom\n@footer2 = get line starting \"Online and Electronic Banking Deductions - continued\" => if not found then blank => bottom => get line below => bottom\ndelete text in box @top2 @footer2 page.left page.right\n@onlineElectronicBottom = get line containing \"Date Amount\" => top => get line above => top => get line above\n\ndelete all lines starting \"Online and Electronic\"\n\n//get Banking/Card Purchases transactions\n//@onlineElectronicTransactions = get multi page table @onlineElectronicTop @onlineElectronicBottom 20 110 165 400 => describe table false \"*Date[MM/dd]\" #Debit Details\n@onlineElectronicTransactions = get multi page table @onlineElectronicTop @onlineElectronicBottom 20 90 165 400 => describe table false \"*Date[MM/dd]\" #Debit Details\n\n\n// Other Deductions table\n@otherDeductionsTop = get line starting \"Other Deductions\" => if not found then blank =>  bottom => get line below\ndelete text in box page.top page.bottom 380 page.right\n@delTop5 = get line starting \"Other Deductions\" => top\n@delBottom5 = get line starting \"Other Deductions\" => bottom => get line below => bottom\ndelete text in box @delTop5 @delBottom5 page.left page.right\n@otherDeductionsBottom = get line containing \"Daily Balance Detail\" => top => get line above\n\ndelete all lines containing \"Daily Balance Detail\"\ndelete all lines starting \"Other Deductions\"\n\n//get Other Deductions transactions\n@otherDeductionsTransactions = get multi page table @otherDeductionsTop @otherDeductionsBottom 20 110 165 400 => describe table false \"*Date[MM/dd]\" #Debit Details\n\n//all transactions\n$transactions = combine described tables @depositesTransaction @checksLeftTransactions @checksRightTransactions @bankingCardTransactions @onlineElectronicTransactions @otherDeductionsTransactions','2023-08-04 03:41:37',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10300,'PayPal_Credit_Card','$source = \"PayPal_Credit_Card\"\r\n$features = \"CREDIT_CARD\"\r\nset negative marker \"CR\"\r\n$periodBufferDays = \"60\"\r\n\r\n// Get account name and number\r\n$accountname = get text in box 720 695 0 200 => get text\r\n$accountnumber = get line containing \"Account No.\" => get words after \"Account No.\" => take words 4 => get text\r\n\r\n//Get opening and closing balance\r\n\r\n//$openingbalance = get line starting \"Last Statement Balance\" => take last words 1 => get decimal\r\n$openingbalance = get line containing \"Last Statement Balance\" => get words after \"Last Statement Balance\" => take words 1 => get decimal\r\n$closingbalance = get line starting \"Statement Balance\" => take last words 1 => get decimal\r\n\r\n\r\n// Get period to/from\r\n@period = get line starting \"Period: from\" => get words after \"Period: from\"\r\n$periodfrom = take words @period 3 => get date \"dd MMMM yyyy\"\r\n$periodto = take last words @period 3 => get date \"dd MMMM yyyy\"\r\n\r\n// Get start of table\r\n@transactionstop = get line starting \"Date Description Amount (£)\" => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsbottom = get last line containing \"How to contact us\" => top => get line above\r\n\r\n@top = get line containing \"Summary of Balances - Retail Purchases\" => top\r\ndelete text in box @top page.bottom page.left page.right\r\ndelete all lines starting \"Page\"\r\n\r\ngo to page 1\r\n// Read the transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 20 120 490 600 => describe table false \"Date[dd/MM/yy]\" Details *#Credit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10301,'ABSA_African','$source = \"ABSA_African\"\r\nset culture \"nl\"\r\n// Not supported month - Mar 20 and Des 20\r\n\r\n// Get account name and number\r\n@accountTop = get line containing \"Besoek ons by:\" => top\r\n//$accountName = get line starting \"Tel:\" => bottom => get line below => take words 3 => get text\r\n$accountName = get text in box  @accountTop 580 page.left page.middleX => take words 2 => get text\r\n$accountNumber = get line starting \"Rekeningnommer\" => get words between \"Rekeningnommer\" \"Staatnommer\" => get text\r\n\r\ngo to page 1\r\n// Get period from and to\r\n$periodFrom = get line starting \"Rekeningnommer\" => top => get line above => take words 3 => get date \"d MMM yyyy\"\r\n$periodTo = get line starting \"Rekeningnommer\" => top => get line above => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening and closing balance\r\n$openingBalance = get line containing \"Saldo oorgebring\" => get words after \"Saldo oorgebring\" => get decimal\r\n$closingBalance = get line containing \"Saldo op\" => get words after \"Saldo op\" => skip words 3 => get decimal\r\n\r\n//get transaction top and bottom\r\n@transactionsTop = get line containing \"datum beskrywing transaksiebedrag R\" => bottom => get line below\r\n@transactionsBottom = get line containing \"valutaomsettingsfooi word by oorgrens\" => top => get line above\r\n\r\n// Variable column co-ordinates\r\ngo to page 1\r\n$DateRight = get line containing \"datum beskrywing\" => get words after \"datum\" => take words 1 => left => subtract 1\r\n$DescLeft = get line containing \"datum beskrywing\" => get words after \"datum\" => take words 1 => left => subtract 5\r\n\r\ndelete all lines containing \"Saldo Oorgebring\"\r\ndelete all lines containing \"Indien inskrywings op hierdie\"\r\ndelete all lines containing \"ontvangs met ons in verbinding\"\r\n\r\ngo to page 1\r\n//get line containing \"Absa Bank Beperk\" => top => ignore footer below\r\nget line containing \"Blaai om asseblief\" => bottom => ignore footer below\r\n\r\nignore header above 625\r\n\r\ndelete all lines containing \"Blaai om asseblief\"\r\ndelete all lines  starting \"Transaksiegeskiedenis (vervolg)\"\r\ndelete all lines containing \"datum beskrywing transaksiebedrag R\"\r\ndelete all lines containing \"www.absa.co.za\"\r\n\r\n// used to delete transaction page where \"0 Any\" text came in between dates to stop these type of statements\r\ngo to page 1\r\n@top = get line starting \"0 Any\"\r\ndelete text in box @top page.bottom page.left page.right\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 160 212 400 500 560 => describe table false \"*Date[d MMM yyyy]\" Details *#Credit #Balance\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 160 219 215 400 500 560 => describe table false \"*Date[d MMM yyyy]\" - Details *#Credit #Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 160 $DateRight $DescLeft 400 490 560 => describe table false \"*Date[d MMM yyyy]\" - Details #Credit #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10302,'Lloyds/Bank_Report_With()','$source = \"Lloyds/Bank_Report_With()\"\nset negative marker \"(\"\n// Get account name\n$accountName = get line starting \"Account Number\" => get words after \"Currency Code:\" => get words between \"/\"  \"/\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Currency Code:\" => take words 1 => get text\n\n// Get period from/to\n$periodFrom = get line starting \"Reporting Period:\"  => get words after \"Reporting Period:\" => take words 1 => get date \"dd MMM yyyy\"\n$periodTo = get line starting \"Reporting Period:\"  => get words after \"Reporting Period:\" => take last words 1 => get date \"dd MMM yyyy\"\n\ndelete all lines starting \"Totals\"\ndelete all lines starting \"End of Report Ledger Balance\"\n\ngo to page 1\n// Get opening and closing balances\n$openingBalance = get line containing \"Closing Ledger:\" => get words after \"Closing Ledger:\" => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Posting\" => bottom => get line below\n@transactionsBottom = get last line starting \"Transaction and balance information\" => top => get line above\n\ngo to page 1\n@closingBalanceTop = get last line starting \"Posting\" => bottom\n\n// Discard page header and  footer\nignore header above 692\nignore footer below 70\n\n@closingBalanceBottom = get last line starting \"Transaction and balance information\" => top\n$closingBalance = get text in box @closingBalanceTop @closingBalanceBottom 515 585 => take last words 1 => get decimal\n\n//Discard extra lines\ndelete all lines starting \"Date\"\ndelete all lines starting \"Posting\"\ndelete all lines starting \"Reporting Period:\"\ndelete all lines starting \"Bank Name:\"\ndelete all lines starting \"Account Number\"\ndelete all lines containing \"Closing Ledger:\"\ndelete all lines containing \"No transactions met selection criteria.\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 80 175 315 425 515 585 => describe table false \"*Date[dd MMM yyyy]\" TransactionType Details Type #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 80 315 425 515 585 => describe table false \"*Date[dd MMM yyyy]\" Details TransactionType #Credit #Balance','2025-02-25 07:19:29',0);
