INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10305,'ABSA_AfricanBarclays_Transaksiebeskrywing','$source = \"ABSA_AfricanBarclays_Transaksiebeskrywing\"\r\n\r\n// Get account name and number\r\n$accountnumber = get line containing \"Tjekrekeningnommer:\" => get words after \"Tjekrekeningnommer:\" => get text\r\n@accounttop = get line containing \"Tjekrekeningnommer:\" => bottom\r\n@accountbottom = get line containing \"Tjekrekeningstaat\" => top\r\n$accountname = get text in box @accounttop @accountbottom page.left page.middleX => take words 2 => get text\r\n\r\nset culture \"nb-NO\"\r\n// Get period to\r\n@accountperiodinfo = get line containing \"Tjekrekeningstaat\" => bottom => get line below\r\n$periodto = take last words @accountperiodinfo 3 => get date \"d MMM yyyy\"\r\n//$periodfrom = take words @accountperiodinfo 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening and closing balances\r\n$openingbalance = get line containing \"Saldo oorgedra\" => get words after \"Saldo oorgedra\" => get decimal\r\ndelete all lines containing \"Saldo oorgedra\"\r\n$closingbalance = get line starting \"Saldo\" => get words after \"Saldo\" => get decimal\r\nset culture \"en-US\"\r\n\r\n// delete summary of first page\r\n@Transtop = get line starting \"Datum Transaksiebeskrywing Koste\" => top\r\ndelete text in box page.top @Transtop page.left page.right\r\n\r\n// Get period from\r\n$periodfrom = get line containing \"Saldo Oorgedra\" => get words before \"Saldo Oorgedra\" => take words 1 => get date \"d/MM/yyyy\"\r\n\r\ndelete all lines containing \"Saldo Oorgedra\"\r\n\r\n// Get start of table\r\n@transactionsTop = get line starting \"Datum Transaksiebeskrywing Koste\" => bottom => get line below\r\n\r\n// Get end of table\r\n//@transactionsBottom = get last line starting \"DIENSGELD :\" => top => get line above\r\n@transactionsBottom = get last line starting \"KREDIETRENTE SOOS\" => top => get line above\r\n\r\ndelete all lines containing \"Datum Transaksiebeskrywing Koste\"\r\ndelete all lines Starting \"U transaksies\"\r\ndelete all lines Starting \"Bladsy\"\r\nignore footer below 50\r\nignore header above 555\r\n\r\ndelete all lines Starting \"Ons Privaatheidskennisgewing\"\r\ndelete all lines Starting \"U PRYSPLAN :\"\r\ndelete all lines Starting \"DIENSGELD :\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 75 290 300 420 500 600 => describe table false \"Date[d/MM/yyyy]\" Details - #Debit #Credit *#Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10306,'Santander_BusinessChecking','$source = \"Santander_BusinessChecking\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get period from and To\n@StatementPeriod = get line starting \"Statement Period\" => get words after \"Statement Period\" => take words 3\n$periodfrom = take words @StatementPeriod 1 => get date \"MM/dd/yy\"\n$periodto = take last words @StatementPeriod 1 => get date \"MM/dd/yy\"\n\n// Get account name and number\n$accountnumber = get line containing \"Primary Account #:\" => get words after \"Primary Account #:\" => take words 1 => get text\n$accountname = get text in box page.top 620 page.left 290 => take words 2 => get text\n\n// Get opening and closing balances\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n@DateRight = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below => take words 2 => take last words 1 => left\n@DescLeft = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below => take words 1 => right\n@DebitRight = get line starting \"Date Description Credits Debits Balance\" => get words before \"Balance\" => take last words 1 => right => add 10\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Description Credits Debits Balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n@last = bottom @transactionsBottom\n\ndelete text in box @last page.bottom page.left page.right\ndelete all lines starting \"Account Activity\"\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Beginning Balance\"\n\ndelete all lines containing \"is a Member FDIC\"\ndelete all lines containing \"All rights reserved\"\ndelete all lines containing \"All other trademarks\"\n\nignore footer below 35\nignore header above 690\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 55 88 360 425 500 580 => describe table false \"Date[MM-dd]\" Details #Credit #Debit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 @DateRight @DescLeft 360 425 @DebitRight 580 => describe table false \"Date[MM-dd]\" - Details #Credit #Debit *#Balance','2024-12-10 06:38:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10307,'WellsFargo_Date_Des_Cr_Dr_Bl','$source = \"WellsFargo_Date_Des_Cr_Dr_Bl\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodTo = get line containing \"Page\" => take words 3 => get date \"MMMM d,yyyy\"\n\n// Get Account name and No\n$accountName =  get text in box 650 590 page.left page.middleX => take words 2 => get text\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Beginning balance on\" => get words after \"Beginning balance on\" => skip words 1 => take words 1 => get decimal\n$periodFrom = get line containing \"Beginning balance on\" => get words after \"Beginning balance on\" => take words 1 => get date \"M/d\"\n$closingBalance = get line containing \"Ending balance on\" =>  get words after \"Ending balance on\" => skip words 1 => take words 1 => get decimal\n\n//@statementPeriod = get line starting \"Fee period\" => get words after \"Fee period\" => take words 3\n//$periodFrom = take words @statementPeriod 1 => get date \"MM/dd/yyyy\"\n\n// Get start of transactions table\ngo to page 1\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n\n// Get end of transactions table\n@transactionsBottom = get last line starting \"Ending balance on\" => top => get line above\n\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Ending balance on\"\ndelete all lines containing \"Totals\"\ndelete all lines containing \"Deposits/\"\ndelete all lines Starting \"Transaction\"\ndelete all lines containing \"■ Page\"\nignore header above 670\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 90 380 450 520 600 => describe table false \"*Date[M/d]\" Details #Credit #Debit #Balance','2022-05-04 05:17:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10308,'CapitalOneCard_TransactionDate','$source = \"CapitalOneCard_TransactionDate\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n$accountnumber = get line containing \"ending in\" =>  get words after \"ending in\" => take words 1 => get text\n\n@period = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => take words 7 \n$periodfrom = take words @period 3 => get date \"MMM dd yyyy\"\n$periodto = take words @period 7 => get words after \"-\" => get date \"MMM dd yyyy\"\n\n//Opening and closing balance\n@summaryTop = get line containing \"SUMMARY OF\" => bottom\n@summaryBottom = get line containing \"Credit Limit\" => top\n@summarybox = get text in box @summaryTop @summaryBottom 325 page.right\n\n$openingbalance = get words after @summarybox \"Previous Balance\" => take words 1 => get decimal\n$closingbalance = get words after @summarybox  \"New Balance\" => take last words 1 => get decimal\n\n$accountname = get text in box 120 80 320 page.right => take words 2 => get text\n\ngo to page 1\n@transactionstop = get line containing \"Transaction Date Posting Date\" => bottom => get line below\n@transactionsbottom = get last line containing \"Summary for This Period\" => top => get line above\n\nignore footer below 55\nignore header above 720\n\ndelete all lines starting $accountname\ndelete all lines starting \"Transaction Date Posting Date\"\ndelete all lines starting \"Fees\"\ndelete all lines containing \"Credits & Adjustments\"\ndelete all lines ending \"Transactions\"\ndelete all lines ending \"(Continued)\"\ndelete all lines containing \"ACCOUNT ACTIVITY\"\ndelete all lines containing \"Total Transactions\"\ndelete all lines containing \"OTHER CHARGES\"\n\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 120 165 400 490 560 => describe table false - \"Date[MMM d]\" Details - *#Credit','2022-03-25 16:34:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10309,'CapitalOneCard_TransDate','$source = \"CapitalOneCard_TransDate\"\r\n\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n$accountnumber = get line containing \"ending in\" => take last words 1 => get text\r\n\r\n@period = get line starting \"Payment Information\" => top => get line above\r\n$periodfrom = take words @period 3 => get date \"MMM dd yyyy\"\r\n$periodto = take words @period 7 => get words after \"-\" => get date \"MMM dd yyyy\"\r\n\r\n//Opening and closing balance\r\n@summaryTop = get line ending \"Account Summary\" => bottom\r\n@summaryBottom = get line containing \"Credit Limit\" => top\r\n@summarybox = get text in box @summaryTop @summaryBottom page.middleX page.right\r\n\r\n//$openingbalance = get words after @summarybox \"Previous Balance\" => take words 1 => get decimal\r\n$openingbalance = get words after @summarybox \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => get decimal\r\n$closingbalance = get words after @summarybox  \"New Balance\" => take last words 1 => get decimal\r\n\r\n$accountname = get line containing \"Customer Service:\" => bottom => get line below => take words 2 => get text\r\n\r\ngo to page 1\r\n@transactionstop = get line containing \"Trans Date Post Date\" => bottom => get line below\r\n@transactionsbottom = get last line starting \"Total Fees for This Period\" => top => get line above\r\n\r\n@Intresttop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below\r\n@Intrestbottom = get last line starting \"Total Interest for This Period\" => if not found then blank => top => get line above\r\n\r\nignore footer below 55\r\nignore header above 720\r\n\r\ndelete all lines starting $accountname\r\ndelete all lines starting \"Trans Date Post Date\"\r\ndelete all lines starting \"Fees\"\r\ndelete all lines containing \"Credits and Adjustments\"\r\ndelete all lines ending \"Transactions\"\r\ndelete all lines ending \"Transactions (Continued)\"\r\ndelete all lines starting \"Total Fees for This Period\"\r\ndelete all lines starting \"Total Transactions for This Period\"\r\ndelete all lines containing \"Total Transactions\"\r\n\r\n//@trans = get multi page table @transactionstop @transactionsbottom 35 90 150 530 600 => describe table false - \"Date[MMM d]\" Details *#Credit\r\n@trans = get multi page table @transactionstop @transactionsbottom 35 90 150 525 600 => describe table false - \"Date[MMM d]\" Details *#Credit\r\n@Intrest = get multi page table @Intresttop @Intrestbottom 35 530 600 => describe table false Details *#Credit\r\n$transactions = combine described tables @trans @Intrest','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10311,'AmericanExpress_corporateCard','$source = \"AmericanExpress_corporateCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n\n$periodBufferDays = 30\nset negative marker \"CR\"\n\n//Get account name\n@actop = get line starting \"Prepared for\" => bottom\n@acbottom = get line starting \"Prepared for\" => bottom => get line below => bottom\n$accountName = get text in box @actop @acbottom page.left 200 => take words 2 => get text\n\n//Get period to\ndelete text in box page.top 640 360 page.right\n$periodTo = get line starting \"Prepared for\" => bottom => get line below => take last words 1 => get date \"dd/MM/yy\"\n\n//Get account number\n$accountNumber = get text in box @actop @acbottom 175 290  => get text\n\n//Get period opening and closingBalance\n@bal = get line starting \"Previous Balance\" => bottom => get line below\n//$openingBalance = take words @bal 1 => get decimal\n$openingBalance = get words before @bal \"-\" => get decimal\n\n@cltop = get line containing \"Amount due in\" => bottom\n@clBottom = get line containing \"Amount due in\" => bottom => get line below => bottom\n$closingBalance = get text in box @cltop @clBottom 210 310 => get decimal\n\n//Get period from\n$periodFrom = get line containing \"New transactions for\" => bottom => get line below => bottom => get line below => take words 2 => get date \"d MMM\"\n\ngo to page 1\n@tophead = get line containing \"Transaction Details Amount\" => top\ndelete text in box page.top @tophead page.left page.right\n\n//Get transaction table\n@transactionsTop = get line containing \"Transaction Details Amount\" => bottom => get line below => bottom => get line below\n\n@firsttop = get line starting \"American Express Services Europe Limited\" => top\ndelete text in box @firsttop page.bottom page.left page.right\n\n@summaryTOP = get line starting \"PAYMENT OPTIONS\" => top\ndelete text in box @summaryTOP page.bottom page.left page.right\n\n\n@transactionsBottom = get last line starting \"Sum of new transactions for\" => top => get line above\n\ndelete all lines containing \"New transactions for\"\ndelete all lines ending $accountNumber\nignore header above 695\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 70 106 400 480 570 => describe table false \"*Date[d MMM]\" - Details - #Credit','2024-01-18 09:55:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10312,'LlyodsTSB_InternetBanking_Page','$source = \"LlyodsTSB_InternetBanking_Page\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account name\n$accountName = get line containing \"Account number:\" => get words before \"Sort\" => get text\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => take last words 1 => get decimal\n\n@DescLeft = get line starting \"Date Description Type In\" => get words after \"Date\" => take words 1 => left\n@DescLeft = subtract @DescLeft 10\n\n@TypeLeft = get line starting \"Date Description Type In\" => get words after \"Description\" => take words 1 => left\n@TypeLeft = subtract @TypeLeft 5\n\n@TypeRight = get line starting \"Date Description Type In\" => get words after \"Description\" => take words 1 => Right\n@TypeRight = add @TypeRight 10\n\n@InRight = get line starting \"Date Description Type In\" => get words after \"In\" => take words 1 => Right\n@InRight = add @InRight 5\n\n@OutRight = get line starting \"Date Description Type In\" => get words after \"Out\" => take words 1 => Right\n@OutRight = add @OutRight 5\n\n@BalanceRight = get line starting \"Date Description Type In\" => get words after \"Balance\" => take words 1 => Right\n@BalanceRight = add @BalanceRight 10\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type In\" => bottom => get line below\n\n//Get openingBalance\n$openingBalance = take last words @transactionsTop 1 => get decimal\n\n$periodTo = take words @transactionsTop 1 => get date \"yyyy-MM-dd\"\n\n//End of the table\n@transactionsBottom = get last line containing \"ATM Cash machine\" => top  => get line above\n\ngo to page 1\n// Discard page header\nignore header above 800\n\nget line containing \"https://businessinternetbanking.tsb.co.uk\" => top => ignore footer below\n\n//Get Closing Balance\n@pageFooter = get last line containing \"ATM Cash machine\" => top => get line above => bottom\n@infoLast = get text in box page.top @pageFooter @OutRight @BalanceRight\n$closingBalance = take last words @infoLast 1 => get decimal\n\n//Get Period From\n$PeriodFrom = get text in box page.top @pageFooter 0 @DescLeft => take last words 1 => get date \"yyyy-MM-dd\"\n\ndelete all lines starting \"https://businessinternetbanking.tsb.co.uk\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 90 205 235 290 350 420 => describe table false \"Date[yyyy-MM-dd]\" Details TransactionType #Credit #Debit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @DescLeft @TypeLeft @TypeRight @InRight @OutRight @BalanceRight => describe table false \"Date[yyyy-MM-dd]\" Details TransactionType #Credit #Debit *#Balance','2024-10-17 08:41:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10314,'Synovus_US','$source = \"Synovus_US\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodbufferdays = 14\n\n// Get Account Number & Name\n@accountNumberText = get last line containing \"Account Number\" => get words after \"Account Number\"\n$accountNumber = take words @accountNumberText 1 => get text\n\n@summaryLine = get line starting \"Summary of Account\" => top\n$panelDetails = get text in box page.top @summaryLine page.left page.right\n$accountName = get words after $panelDetails \"Direct inquiries to:\" => take last words 12 => take words 4 => get text\n\n// Get period to\n$PeriodFrom = get line starting \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMMM d,yyyy\"\n$PeriodTo = get line containing \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMMM d,yyyy\"\n\ndelete text in box @panelTop @summaryLine page.left page.right\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Beginning balance\" => get words after \"Beginning balance\" => get decimal\n$closingBalance = get line starting \"Ending balance\" => get words after \"Ending balance\" => take words 1 => get decimal\n\ngo to page 1\ndelete text in box on every page 781 630 page.left page.right\n\n// Get start & end of checks tables\ngo to page 1\n@checksTop = get line starting \"Checks\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Other Debits\" => if not found then blank => top => get line above\n\n// Get start & end of debits table\ngo to page 1\n@debitsTop = get line starting \"Other Debits\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get line starting \"Deposits/Other Credits\" => if not found then blank => top => get line above\n\n// Get start & end of credits table\ngo to page 1\n@creditsTop = get line starting \"Deposits/Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line starting \"Balance Summary\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Date Transaction Type\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Deposits/Other Credits\"\ndelete all lines starting \"Checks\"\ndelete all lines containing \"(continued)\"\ndelete all lines starting \"Number Date Amount\"\n\n// Read the transactions\n@checksleft = get multi page table @checksTop @checksBottom 80 155 230 290 => describe table false #ChequeNumber \"Date[MM dd]\" *#Debit\ndelete all lines containing \"Skip in check sequence\"\ndelete all lines containing \"R-Check has been returned\"\n@checksright = get multi page table @checksTop @checksBottom 330 390 462 530 => describe table false #ChequeNumber \"Date[MM dd]\" *#Debit\n\n@debits = get multi page table @debitsTop @debitsBottom 38 86 195 490 570 => describe table false \"*Date[MM-dd]\" TransactionType Details #Debit\n@credits = get multi page table @creditsTop @creditsBottom 38 86 195 490 570 => describe table false \"*Date[MM-dd]\" TransactionType Details #Credit\n\n$transactions = combine described tables @debits @credits @checksleft @checksright','2025-07-31 08:11:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10315,'Revolut_Account_E-Money','$source = \"Revolut_Account_E-Money\"\n\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n//$accountname = get line containing \"IBAN\" => top => get line above => get text\n$accountname = get text in box 674 650 page.left page.middleX => get text\n$accountnumber = get line containing \"IBAN\" => get words after \"IBAN\" => take words 1 => get text\n\n//$openingbalance = get line starting \"Total\" => get words after \"Total\" => take words 1 => get decimal\n$openingbalance = get line starting \"Account (\" => get words after \")\" => take words 1 => get decimal\n\n//$closingbalance = get last line starting \"Total\" => take last words 1 => get decimal\n\n//delete summary and header for multiperiod\ngo to page 1\n@Summary_bottom1 = get line starting \"Balance summary\" => if not found then blank => bottom => get line below => top\n$Summary_1 = delete text in box page.top @Summary_bottom1 page.left page.right => get text\n\n@Summary_bottom2 = get line starting \"Balance summary\" => if not found then blank => bottom => get line below => top\n$Summary_2 = delete text in box page.top @Summary_bottom2 page.left page.right => get text\n\n@Summary_bottom3 = get line starting \"Balance summary\" => if not found then blank => bottom => get line below => top\n$Summary_3 = delete text in box page.top @Summary_bottom3 page.left page.right => get text\n\n\ngo to page 1\n// deleted pending table\n@get_top = get line containing \"Pending from\" => top\n@get_bottom = get line containing \"Account transactions\" => top\n$pending_tbl = delete text in box @get_top @get_bottom page.left page.right => get text\n\n\n//delete Reverted table\ngo to page 1\n//deleted reverted transaction row only those who are merged with Personal and Group Vaults table\n@navigateto_perosonaltransaction = get line containing \"Personal and Group Vaults transactions\"\n@personal_top = get line containing \"Start date Description\" => top\n@personal_bottom = get line containing \"Personal and Group Vaults transactions\" => bottom\n$deleted_merged_transaction = delete text in box @personal_top @personal_bottom page.left page.right => get text\n\n\ngo to page 1\n@navigateto_perosonaltransaction = get line containing \"Personal and Group Vaults transactions\"\n@personal_top1 = get line containing \"Start date Description\" => top\n@personal_bottom1 = get line containing \"Personal and Group Vaults transactions\" => bottom\n$deleted_merged_transaction1 = delete text in box @personal_top1 @personal_bottom1 page.left page.right => get text\n\n\ngo to page 1\n@navigateto_perosonaltransaction = get line containing \"Personal and Group Vaults transactions\"\n@personal_top2 = get line containing \"Start date Description\" => top\n@personal_bottom2 = get line containing \"Personal and Group Vaults transactions\" => bottom\n$deleted_merged_transaction2 = delete text in box @personal_top2 @personal_bottom2 page.left page.right => get text\n\n\ngo to page 1\n@top = get line containing \"Start date Description\" => top\n$top = get line containing \"Start date Description\" => top => get line above => get text\n@bottom = get line containing \"Report lost or stolen card\" => top\n$Reverted_01 = delete text in box @top @bottom page.left page.right => get text\n\n\n\n@top1 = get line containing \"Start date Description\" => top\n@bottom1 = get line containing \"Report lost or stolen card\" => top\n$Reverted_02 = delete text in box @top1 @bottom1 page.left page.right => get text\n\n@top2 = get line containing \"Start date Description\" => top\n@bottom2 = get line containing \"Report lost or stolen card\" => top\n$Reverted_03 = delete text in box @top2 @bottom2 page.left page.right => get text\n\n\ngo to page 1\n//@closing_top = get last line containing \"Date Description Money\" => bottom\n@closing_top = get last line containing \"Description Money out Money in Balance\" => bottom\n//@closing_bottom = get last line containing \"Report lost or stolen card\" => top\n//$closingbalance = get text in box @closing_top @closing_bottom 480 565 => take last words 1 => get decimal\n$closingbalance = get text in box @closing_top 107 480 565 => take last words 1 => get decimal\n\ngo to page 1\n//$periodfrom = get line containing \"transactions from\" => get words before \"to\" => take last words 3 => get date \"d MMMM yyyy\"\n@getperiod = get line containing \"transactions from\" => get words after \"from\"\n$periodfrom = take words @getperiod 3 => get date \"d MMMM yyyy\"\n\n//$periodto = get line containing \"transactions from\" => get words after \"to\" => take words 3 => get date \"d MMMM yyyy\"\n$periodto = get last line containing \"transactions from\" => get words after \"from\" => take last words 3 => get date \"d MMMM yyyy\"\n\n\ngo to page 1\n@transactiontop = get line starting \"Date Description\" => bottom => get line below\n//@transactionbottom = get last line containing \"Revolut Payments UAB\" => top => get line above\n//@transactionbottom = get last line containing \"Report lost or stolen card\" => top => get line above\n\ngo to last page\n@transactionbottom = get line above 0\n\n\n\n\ngo to page 1\n//ignore footer below 100\nignore footer below 105\nignore header above 710\n//delete all lines starting \"Date Description\"\ndelete all lines starting \"Revolut Rate\"\ndelete all lines starting \"£\"\ndelete all lines starting \"Fee:\"\ndelete all lines starting \"445.13 PLN\"\ndelete all lines starting \"2,336.15 PLN\"\n\ngo to page 2\n@headerTop_del = get line containing \"Account Number\" => top\n@headerBottom_del = get line containing \"Date Description Money\" => top\n//$delete_multi_header = delete text in box @headerTop_del @headerBottom_del page.left page.right\ndelete all lines starting \"Date Description\"\ndelete all lines starting \"€\"\ndelete all lines starting \"$\"\ndelete all lines starting \"Personal and Group\"\ndelete all lines containing \"Sort Code\"\n\n\ndelete all lines containing \"To Rosaleen Goodman\"\ndelete all lines starting \"Reverted from\"\ndelete all lines starting \"IBAN\"\ndelete all lines starting \"BIC\"\ndelete all lines starting \"Account transactions from\"\ndelete all lines starting \"The balance on your statement might differ from\"\ndelete all lines starting \"Total €\"\ndelete all lines starting \"Account (\"\ndelete all lines starting \"Where your transactions are remitted\"\ndelete all lines starting \"Product Opening balance Money out\"\ndelete all lines containing \"Opening balance\"\n\n\ndelete all lines starting \"AU$\"\ndelete all lines ending \"0 MAD\"\ndelete all lines ending \"1 MAD\"\ndelete all lines ending \"2 MAD\"\ndelete all lines ending \"3 MAD\"\ndelete all lines ending \"4 MAD\"\ndelete all lines ending \"5 MAD\"\ndelete all lines ending \"6 MAD\"\ndelete all lines ending \"7 MAD\"\ndelete all lines ending \"8 MAD\"\ndelete all lines ending \"9 MAD\"\ndelete all lines starting \"Pending from\"\n\n\ndelete all lines starting \"Personal and Group Vaults\"\n\ndelete all lines starting \"6,835.26 RSD\"\n\n\n//$transactions = get multi page table @transactiontop @transactionbottom 30 90 320 385 480 565 => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactiontop @transactionbottom 30 320 385 480 565 => describe table false Details *#Debit *#Credit','2025-01-23 08:29:46',0);
