INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10319,'ATB_Financial_Mastercard','$source = \"ATB_Financial_Mastercard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n\r\n$periodBufferDays = 10\r\n\r\ndelete rotated words\r\n\r\n// Account Details\r\n$accountName = get line starting \"Account Number:\" => top => get line above => get text\r\n$accountnumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 4 => get text\r\n\r\n// Statement Period\r\n$periodfrom = get line starting \"Payments made from\" => get words after \"from\" => get words before \"to\" => get date \"MMM dd\"\r\n$periodto = get line containing \"Statement date:\" => get words after \"date:\" => take words 3 => get date \"MMM dd, yyyy\"\r\n\r\n// Balances\r\n$openingBalance = get line containing \"Your previous balance\" => get words after \"balance\" => take words 1 => get decimal\r\n$closingbalance = get line starting \"Your new balance\" => get words after \"balance\" => take words 1 => get decimal\r\n\r\n// Deleting the right most panel from all the pages to avoid unnecessary data\r\ngo to page 1\r\ndelete text in box on every page page.top page.bottom 400 page.right\r\n\r\n// Get start & end of Credits table\r\ngo to page 2\r\n@creditsTop = get line starting \"PAYMENTS AND CREDITS\" => if not found then blank => bottom => get line below => bottom => get line below\r\n//ignore header above 718\r\n@creditsBottom = get line starting \"Total payments and credits\" => if not found then blank => top => get line above\r\n\r\n// Get start & end of debits table\r\ngo to page 2\r\n@debitsTop = get line starting \"Date Charged Date Posted\" => if not found then blank => bottom => get line below\r\ndelete all lines starting \"Total payments and credits\"\r\ndelete all lines containing \"xxxx xxxx\"\r\ndelete all lines starting \"PURCHASES AND RETURNS\"\r\ndelete all lines starting \"Date Charged Date Posted\"\r\ndelete all lines containing \"(continued on next page)\"\r\ndelete all lines starting \"Balance Type Interest Charged\"\r\n//ignore footer below 230\r\ngo to page 2\r\ndelete text in box 230 page.bottom page.left page.right\r\n\r\n\r\n@debitsBottom = get line starting \"Total purchases and returns\" => if not found then blank => top => get line above\r\n\r\n// Get start & end of fees table\r\n@feesTop = get line starting \"FEES AND ADJUSTMENTS\" => if not found then blank => bottom => get line below\r\n@feesBottom = get line starting \"Total fees and adjustments\" => if not found then blank => top => get line above\r\n\r\n$feesTop = get line starting \"FEES AND ADJUSTMENTS\"\r\n$feesBottom = get line starting \"Total fees and adjustments\"\r\n\r\n// Get start & end of Interest table\r\n@interestTop = get line starting \"INTEREST CHARGES\" => if not found then blank => bottom => get line below\r\n@interestBottom = get line starting \"Total interest charges\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Date Posted Description Amount\"\r\n\r\n@periodtopLine = get last line containing \"MONTHLY STATEMENT\" => bottom => get line below => get text\r\ndelete all lines starting \"INTEREST CHARGES (continued)\"\r\ndelete all lines starting \"MONTHLY STATEMENT\"\r\ndelete all lines starting @periodtopLine\r\n\r\n\r\n// Get start & end of Interest table\r\ngo to page 1\r\n@CASHADVANCESTop = get line starting \"CASH ADVANCES AND MASTERCARD CHEQUES\" => if not found then blank => bottom => get line below\r\n@CASHADVANCESBottom = get line starting \"Total cash advances and MasterCard cheques\" => if not found then blank => top => get line above\r\n\r\n// Read the transactions\r\n@fees = get multi page table @feesTop @feesBottom 60 110 290 380 => describe table false \"Date[MMM dd]\" Details *#Credit\r\n//@interest = get multi page table @interestTop @interestBottom 60 270 300 => describe table false \"Details\" *#Credit\r\n@interest = get multi page table @interestTop @interestBottom 60 255 300 => describe table false \"Details\" *#Credit\r\n@CASHADVANCES = get multi page table @CASHADVANCESTop @CASHADVANCESBottom 60 100 140 325 380 => describe table false - \"Date[MMM dd]\" Details *#Credit\r\n\r\nignore header above 718\r\n@credits = get multi page table @creditsTop @creditsBottom 60 110 290 380 => describe table false \"Date[MMM dd]\" Details *#Credit\r\n@debits = get multi page table @debitsTop @debitsBottom 60 100 143 325 380 => describe table false - \"Date[MMM dd]\" Details *#Credit\r\n\r\n// Final transactions\r\n//$transactions = combine described tables @credits @debits @fees @interest\r\n$transactions = combine described tables @credits @debits @fees @interest @CASHADVANCES','2026-08-17 09:11:00',0);
