INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10323,'MBNA_CreditCard_Canada','$source = \"MBNA_CreditCard_Canada\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 28\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n// Removing left vertical text\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 50\n\n// Boxing Account details\ngo to page 1\n@Detailstop = get line starting \"Statement Period:\" => top\n@AllDetails = get text in box @Detailstop 568 422 600\n\n// Account Detials\n$accountName = get words after @AllDetails \"Primary Cardholder:\" => take words 2 => get text\n$accountNumber = get words after @AllDetails \"Account Number:\" => take words 4 => get text\n\n// Statement Period\n@periodtext = get line starting \"Statement Period:\" => take last words 3\n$periodFrom = get words before @periodtext \"to\" => take words 1 => get date \"MM/dd/yy\"\n$PeriodTo = get words after @periodtext \"to\" => take words 1 => get date \"MM/dd/yy\"\n\n// Balances\n$openingBalance = get line starting \"Previous statement balance\" => get words after \"Previous statement balance\" => get decimal\ngo to page 1\n//$closingbalance = get line starting \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n$closingbalance = get line starting \"New Balance\" => get words before \"Account Number:\" => take last words 1 => get decimal\n\n// Get start & end of transactions table\n@transactionsTop = get line containing \"Date Date Description AIR\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line starting \"Subtotal of Activity\" => top => get line above => top => get line above\n\n// Discard page header\nget line starting \"Details of your transactions\" => bottom => ignore header above\n\n// Remove unwanted lines\ndelete all lines starting \"Total\"\ndelete all lines starting \"PURCHASES\"\ndelete all lines starting \"PAYMENTS\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Previous statement balance\"\ndelete all lines containing \"continued\"\ndelete all lines containing \"Trans Posting Promotional\"\ndelete all lines containing \"Date Date Description\"\ndelete all lines containing \"continued on next page\"\ndelete all lines starting \"Page\"\n\n// Delete user details\ngo to page 1\n$Delete1 = get line starting \"Subtotal of Activity\" => bottom => get line below => get text\ngo to page 1\n$Delete2 = get line starting \"Subtotal of Activity\" => bottom => get line below => bottom => get line below => get text\ndelete all lines starting $Delete1\ndelete all lines starting $Delete2\ndelete all lines containing \"Subtotal of Activity\"\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 55 100 150 520 600 => describe table false \"*Date[MM/dd/yy]\" - Details #Credit','2025-01-09 08:35:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10324,'TDCanadaTrust_DESCRIPTION','$source = \"TDCanadaTrust_DESCRIPTION\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"OD\"\n\ndelete text in box on every page page.top page.bottom page.left 60 \ngo to page 1\n\n// Get account name\n$accountName = get text in box 650 630 80 235 => get text\n\n// Get account number\n@accTop = get line containing \"Account No.\" => bottom\n@accBottom = get line starting \"DESCRIPTION\" => top\n$accountNumber = get text in box @accTop @accBottom 120 210 => get text\n\n// Get period from/to\n@periodtop = get line containing \"Statement From\" => bottom\n@periodbottom = get line containing \"Page 1\" => top\n@period = get text in box @periodtop @periodbottom 415 540\n$periodFrom = take words @period 2 => get date \"MMM dd/yy\"\n$periodTo = take last words @period 2 => get date \"MMM dd/yy\"\n\n// Get opening balance and Cloasing balance\n$openingBalance = get line containing \"DESCRIPTION WITHDRAWALS DEPOSITS\" => bottom => get line below => take last words 1 => get decimal\n\n@pageFooter = get last line starting \"Account/Transaction Type\" => top => get line above => top\n@infoLast = get text in box page.top @pageFooter 480 570\n$closingBalance = take last words @infoLast 1 => get decimal\n\n// Get start of table\ngo to page 1\n@header = get line containing \"DESCRIPTION WITHDRAWALS DEPOSITS\" => top\n@transactionsTop = get line containing \"DESCRIPTION WITHDRAWALS DEPOSITS\" => bottom => get line below => bottom => get line below\n \n// Get end of table\n@transactionsBottom = get last line starting \"Account/Transaction Type\" => top => get line above => top => get line above\n\n//Discard page header and footer\nignore header above @header\nget line starting \"Account/Transaction Type\" => top => get line above => top => ignore footer below\ndelete all lines containing \"DESCRIPTION WITHDRAWALS\"\ndelete all lines containing \"BALANCE FORWARD\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 200 310 400 445 570 => describe table false Details #Debit #Credit \"*Date[MMMdd]\" #Balance\n \n \n','2022-06-23 08:31:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10325,'Scotiabank_day-to-Day Banking','$source = \"Scotiabank_day-to-Day Banking\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$PeriodBufferDays = 31\n\ndelete text in box on every page page.top page.bottom page.left 60\n\n$accountname = get line containing \"Questions?\" => top => get line above => top => get line above => top => get line above => top => get line above => get text\n\n$accountnumber = get line containing \"Your account number:\" => bottom => get line below => take last words 3 => get text\n\n//$periodfrom = get text in box 508 496 160 260 => get date \"MMMM d, yyyy\"\n$periodfrom = get line containing \"Opening Balance on\" => get words after \"Opening Balance on\" => take words 3 => get date \"MMMM d, yyyy\"\n\n//$periodto = get text in box 460 448 160 260 => get date \"MMMM d, yyyy\"\n$periodto = get line containing \"Closing Balance on\" => get words after \"Closing Balance on\" => take words 3 => get date \"MMMM d, yyyy\"\n$periodText =  get line containing \"Opening Balance on\" => get words after \"Opening Balance on\" => take words 3 => take last words 1 => get text\n$periodText1 =  get line containing \"Closing Balance on\" => get words after \"Closing Balance on\" => take words 3 => take last words 1 => get text\n\n//$openingbalance = get text in box 508 496 380 440 => get decimal\n$openingbalance = get line containing \"Opening Balance on\" => get words after \"Opening Balance on\" => take last words 1 => get decimal\n\n\n//$closingbalance = get text in box 460 448 380 440 => get decimal\n$closingbalance = get line containing \"Closing Balance on\" => get words after \"Closing Balance on\" => take last words 1 => get decimal\n\n\n@transactionsTop = get line containing \"Date Transactions withdrawn\"\n\n@transactionsBottom =  get last line containing \"Balance\"\n\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 60\