INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10326,'Clydesdale_VirginMoney_myStatement','$source = \"Clydesdale_VirginMoney_myStatement\"\n\n// Discard headings in top left of page 1\n@panelTop = get line starting \"Account number\" => bottom\n@panelBottom = get line starting \"Date Description Type\" => top\n$panelData = get text in box @panelTop @panelBottom page.left page.right\n\n// Get account name and number\n$accountNumber = take words $panelData 1 => get text\n$accountName = get line starting \"Account number\" => top => get line above => top => get line above => get text\n//get text in box 1620 @panelTop page.left page.middleX => take words 3 => get text\n\n// Get period from/to\n@statementPeriod = take last words  $panelData 7\n$periodFrom = take words @statementPeriod 3 => get date \"dd MMM yy\"\n$periodTo = take last words @statementPeriod 3 => get date \"dd MMM yy\"\ndelete text in box @panelTop @panelBottom page.left page.right\n\n// Get opening and closing balances\n\n@openingBalance = get last line containing \"Opening Balance\" =>  get words after \"Opening Balance\"\n$openingBalance = get decimal @openingBalance\n$openingBalanceText = get text @openingBalance\n@closingBalance = get line containing \"Closing balance\"  =>  get words after \"Closing balance\"\n$closingBalance = get decimal @closingBalance\n$closingBalanceText = get text @closingBalance\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\ndelete all lines starting \"Total debits\"\ndelete all lines starting \"Total credits\"\ndelete all lines containing \"Closing balance\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines starting \"Date Description Type\"\ndelete all lines containing \"https://internet-banking\"\ndelete all lines containing \"Statement\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 135 562 655 900 1055 1235 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Debit #Credit #Balance','2022-12-14 12:35:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10327,'Triangle_ctfs_Card','$source = \"Triangle_ctfs_Card\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n// Get periods\r\n@period = get line containing \"For the period:\" => get words after \"For the period:\" => take words 7\r\n$periodfrom = take words @period 3 => get date \"MMMM d,yyyy\"\r\n$periodto = take last words @period 3 => get date \"MMMM d,yyyy\"\r\n\r\n//Get Account Number\r\n$accountNumber = get line starting \"Account number:\" => get words after \"Account number:\" => take words 4 => get text\r\n\r\n// Get account details\r\ngo to page 1\r\n$accountName = get text in box 115 78 74 page.middleX => take words 2 => get text\r\n\r\n// Get opening and closing balances\r\n@openingBalanceRaw = get line containing \"Balance from your last statement\" => get words after \"Balance from your last statement\" => take words 1\r\n$openingBalance = take words @openingBalanceRaw 1 => get decimal\r\n@closingBalanceRaw = get line containing \"Your New Balance\" => get words after \"Your New Balance\" => take words 1\r\n$closingBalance = take words @closingBalanceRaw 1 => get decimal\r\ndelete text in box on every page page.top page.bottom 410 page.right\r\n\r\n// Get start & end of Payments table\r\ngo to page 1\r\n@transStart = get line containing \"TRANSACTION DESCRIPTION\"\r\ndelete text in box page.top 0 370 page.right\r\n@transactionsTop1 = get line containing \"TRANSACTION DESCRIPTION\" => bottom => get line below\r\n@transactionsBottom1 = get line starting \"continued on next page\" => top => get line above\r\n@transactionsTop2 = get line starting \"Details of your account summary (continued)\" => if not found then blank => bottom => get line below\r\n@transactionsBottom2 = get line starting \"Other details about your account\" => top => get line above\r\n\r\n\r\n// Discard page header\r\nignore header above 685\r\n\r\n// Discard page footer\r\n@panelBottom = get line containing \"continued on next page\" => top\r\ndelete text in box @panelBottom 0 page.left page.right\r\n@panelBottom1 = get line containing \"Other details about your account\" => top\r\ndelete text in box @panelBottom1 0 page.left page.right\r\n\r\ngo to page 1\r\n@footer1 = get line containing \"continued on next page\" => top\r\ndelete text in box @footer1 0 page.left page.right\r\n\r\n// Discard unwanted lines\r\ndelete all lines starting \"DATE DATE TRANSACTION DESCRIPTION AMOUNT ($)\"\r\ndelete all lines containing \"Total payments received\"\r\ndelete all lines containing \"Returns and other credits\"\r\ndelete all lines containing \"Total returns and credits\"\r\ndelete all lines containing \"Purchases - Card\"\r\ndelete all lines containing \"Total purchases\"\r\ndelete all lines containing \"continued on next page\"\r\ndelete all lines containing \"WAYS TO PAY\"\r\n//delete all lines containing \"Online\"\r\n//delete all lines containing \"banking\"\r\ndelete all lines containing \"Please allow enough time for your payment to reach us by the due date\"\r\ndelete all lines containing \"New address\"\r\ndelete all lines containing \"Let us know by visiting us online at ctfs.com\"\r\ndelete all lines containing \"Details of your interest charges\"\r\ndelete all lines containing \"ANNUAL INTEREST\"\r\ndelete all lines containing \"Cash Transactions and Fees\"\r\ndelete all lines containing \"Total interest charges\"\r\ndelete all lines containing \"Purchases (continued)\"\r\ndelete all lines containing \"TRANSACTION POSTING\"\r\ndelete all lines containing \"Details of your Canadian Tire store purchases\"\r\ndelete all lines starting \"For more information,\"\r\ndelete all lines starting \"Cash transactions\"\r\ndelete all lines starting \"Total cash transactions\"\r\ndelete all lines starting \"Total fees\"\r\n\r\n// Read the transactions\r\n@transactions1 = get multi page table @transactionsTop1 @transactionsBottom1 40 83 123 315 370 => describe table false - \"Date[MMM dd]\" Details *#Credit\r\n@transactions2 = get multi page table @transactionsTop2 @transactionsBottom2 70 110 150 345 400 => describe table false - \"Date[MMM dd]\" Details *#Credit\r\n$transactions = combine described tables @transactions1 @transactions2','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10328,'UFCU_UniversityFedralCreditUnion','$source = \"UFCU_UniversityFedralCreditUnion\"\n\n$features = \"CREDIT_CARD\"\n\n$periodBufferDays = 40\n\n// Get account name\n$accountName = get text in box 613 585 45 page.middleX => get text\n\n// Get account number\n$accountNumber = get line starting \"Member Number\" => bottom => get line below => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Previous Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n// Get period from/to\n@periodTop = get line starting \"Statement Period\" => bottom\n@period = get text in box @periodTop 739 380 485\n$periodFrom = get words before @period \"-\" => get date \"MM/dd/yyyy\"\n$periodTo = get words after @period \"-\" => get date \"MM/dd/yyyy\"\n\n// Get start & end of Debits/Credits Table\n@transactionsTop = get line starting \"Post Date Trans Date Reference\" => bottom => get line below\n@transactionsBottom = get last line starting \"TOTAL PAYMENTS OR ADJUSTMENTS\" => top => get line above\n\nignore header above 721\ndelete all lines starting \"Post Date Trans Date Reference\"\ndelete all lines starting \"Payments, Adjustments and Others\"\ndelete all lines starting \"TOTAL PAYMENTS OR ADJUSTMENTS\"\ndelete all lines starting \"No activity for Payments\"\n\n@TransactionsDrCr = get multi page table @transactionsTop @transactionsBottom 37 88 145 259 514 574 => describe table false \"Date[MM/dd/yyyy]\" - TransactionType Details *#Credit\n\n// Get start & end of Interest Charged table\n@InterestTop = get line starting \"Description Amount\" => if not found then blank => bottom => get line below\n@InterestBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD:\" => if not found then blank => top => get line above\n\ndelete all lines starting \"No activity\"\n\n@Interest = get multi page table @InterestTop @InterestBottom 35 480 574 => describe table false Details *#Credit\n\n// Combining the transactions\n$transactions = combine described tables @TransactionsDrCr @Interest','2022-12-14 12:35:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10329,'ING_Bank','$source = \"ING\"\n\nset negative marker \"-\"\n\n// Get period from/to\n$periodfrom = get line containing \"Period:\" => get words after \"Period:\" => take words 1 => get date \"dd-MM-yyyy\"\n$periodto = get line containing \"Period:\" => get words after \"until\" => take words 1 => get date \"dd-MM-yyyy\"\n\n// Get Account Name\n$Accountname = get line containing \"Holder(s):\" => bottom => get line below => get text\n\n// Get Account Number\n$Accountnumber = get line starting \"Current account :\" => get words after \"Current account :\" => take words 6 => take last words 2 => get text\n\nset culture \"fr-CA\"\n\n// Get opening/closing Balance\n$openingbalance = get line containing \"Previous balance on\" => take last words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line containing \"Date Reference Type of transaction\" => bottom => get line below\n$closingbalance = get line containing \"New balance on\" => take last words 1 => get decimal\n\ndelete all lines starting \"Previous balance on\"\ndelete all lines starting \"Current account :\"\ndelete all lines containing \"Date Reference Type of transaction\"\ndelete all lines containing \"Intermediary balance\"\n\n// Get end of table\n@transactionsBottom = get line starting \"New balance on\" => top => get line above\nignore header above 748\nignore footer below 90\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 92 375 430 500 575 => describe table false \"*Date[dd-MM-yyyy]\" Details - #Debit #Credit','2022-12-14 12:35:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10330,'Kabbage','$source = \"Kabbage\"\n\n// Get Account Name\n$AccountName = get text in box 732 685 page.left page.middleX => take words 2 => get text\n\n// Get Account Number\n@AccountNumbertext = get line containing \"ACCOUNT NUMBER\" => top\n$AccountNumber = get text in box @AccountNumbertext 680 490 page.right => take last words 1 => get text\n\n$periodfrom = get line containing \"Days in Statement Period\" => get words before \"to\" => take last words 1 => get date \"MM/dd/yyyy\"\n$periodto = get line containing \"Days in Statement Period\" => get words after \"to\" => take words 1 => get date \"MM/dd/yyyy\"\n\n// Get Opening/Closing Balance\n$openingbalance = get line starting \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => take last words 1 => get decimal\n$closingbalance = get last line starting \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => take last words 1 => get decimal\ngo to page 1\n\n// Get start of table\n@transactionsTop  = get line containing \"DATE DESCRIPTION AMOUNT\" => bottom => get line below\n//$periodfrom = take words @transactionsTop 1 => get date \"MM/dd/yyyy\"\n\nignore footer below 80\nignore header above 665\ndelete all lines starting \"Banking services provided by\"\ndelete all lines containing \"DATE DESCRIPTION AMOUNT\"\n\n// Get end of table\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 105 530 590 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit','2022-12-14 12:35:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10331,'Mercury','$source = \"Mercury\"\r\n$periodToRegex = \".*-(.*)\"\r\n$inputDateFormat = \"d/MMM/yyyy\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n//Get dates\r\n@Datestop = get line containing \"days)\" => top\r\n@Datesbottom = get line containing \"days)\" => bottom\r\n@Dates = get text in box @Datestop @Datesbottom page.middleX page.right\r\n\r\n$PeriodToText = take words @Dates 4 => get text\r\n$PeriodTo =  take words @Dates 4 => get date \"ddMMyyyy\"\r\n\r\n// Get Account Name\r\n$AccountName = get text in box 682 630 page.left page.middleX => take words 3 => get text\r\n\r\n// Delete text\r\ngo to page 1\r\n@deletebottom = get line starting \"Statement\" => bottom\r\ndelete text in box page.top @deletebottom 0 280\r\n\r\n// Get Account Number\r\n$AccountNumber = get line starting \"Routing\" => top => get line above => take last words 1 => get text\r\n\r\n//Get Balances\r\n//@Summarytop = get line starting \"Beginning\" => top\r\n//@Summarybottom = get line starting \"Statement\" => bottom\r\n//@Summary = get text in box @Summarytop @Summarybottom 280 page.right\r\n\r\n//$OpeningBalance = get words after @Summary \"Beginning\" => skip words 1 => get words before \"Total withdrawals\" => get decimal\r\n\r\n$OpeningBalance = get line containing \"Account activity\" => bottom => get line below => take last words 1 => get decimal\r\n$ClosingBalance = get last line containing \"Total\" => get words after \"Total\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@TypeL = get line containing \"Type Amount End of Day Balance\" => get words before \"Amount\" => take last words 1 => left => subtract 10\r\ngo to page 1\r\n@AmountL = get line containing \"Type Amount End of Day Balance\" => get words before \"End\" => take last words 1 => left => subtract 30\r\ngo to page 1\r\n@BalanceL = get line containing \"Type Amount End of Day Balance\" => get words after \"Amount\" => take words 1 => left => subtract 5\r\ngo to page 1\r\n@DateR = get line containing \"Type Amount End of Day Balance\" => bottom => get line below => take words 1 => right => add 25\r\ngo to page 1\r\n@DateL = get line containing \"Type Amount End of Day Balance\" => bottom => get line below => take words 1 => left => subtract 15\r\n\r\nignore footer below 38\r\n\r\n// Get top of table\r\n@transactionsTop = get line containing \"Type Amount End of Day Balance\" => bottom => get line below\r\n$PeriodFrom =  take words @transactionsTop 2 => get date \"MMM d\"\r\n\r\nignore header above 765\r\ndelete all lines containing \"Type Amount End of Day Balance\"\r\ndelete all lines containing \"All Transactions\"\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Total\" => top => get line above\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 60 95 300 397 470 600 => describe table false \"Date[MMM d]\" Details - *#Credit #Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateL @DateR @TypeL @AmountL @BalanceL 600 => describe table false \"Date[MMM d]\" Details - *#Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10332,'LlyodsTSB_InternetBanking_SkiaPDF','$source = \"LlyodsTSB_InternetBanking_SkiaPDF\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n\n// Get account name\n$accountName = get line containing \"Account number:\" => get words before \"Sort\" => get text\n\n// Discard address in top left of page 1\n@dropBottom = get line starting \"Date Description Type In\" => top\ndelete text in box page.top @dropBottom page.left page.middleX\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => take last words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type In\" => bottom => get line below\n\n// Get openingBalance\n$openingBalance = take last words @transactionsTop 1 => get decimal\n$periodTo = take words @transactionsTop 1 => get date \"yyyy-MM-dd\"\n\n// End of the table\n@transactionsBottom = get last line containing \"ATM Cash machine\" => top => get line above\n\n// Discard page footer\nget line containing \"https://businessinternetbanking.tsb.co.uk\" => top => ignore footer below\ndelete all lines starting \"https://businessinternetbanking.tsb.co.uk\"\n\n@transactionsBottom0 = get last line containing \"ATM Cash machine\" => top\ndelete text in box @transactionsBottom0 page.bottom page.left page.right\n\n// Get Period From\n@LastPageTop =  get last line starting \"Date Description Type In\" => bottom\n$PeriodFrom = get text in box @LastPageTop page.bottom 25 118 => take last words 1 => get date \"yyyy-MM-dd\"\n\n// Get Closing Balance\n@infoLast = get text in box @LastPageTop page.bottom 480 page.right\n$closingBalance = take last words @infoLast 1 => get decimal\n\n\n// Discard page header\nget line starting \"Date Description Type In\" => top => ignore header above\ndelete all lines containing \"Date Description Type\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 118 280 332 412 495 565 => describe table false \"Date[yyyy-MM-dd]\" Details TransactionType #Credit #Debit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 118 280 332 414 495 490 580 => describe table false \"Date[yyyy-MM-dd]\" Details TransactionType #Credit #Debit - *#Balance','2025-02-12 08:12:48',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10333,'FirstNationalBank_TransHistory','$source = \"FirstNationalBank_TransHistory\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get Account Name\n$accountname = get line containing \"Nickname:\" => get words after \"Nickname:\" => take last words 3 => get text\n\n// Get Account Number\n$accountnumber = get line containing \"Account:\" => get words after \"Account:\" => take last words 1 => get text\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description Service Fee\" => bottom => get line below\n$openingbalance = take last words @transactionsTop 2 => get decimal\n$periodTo = take words @transactionsTop 3 => get date \"dd MMM yyyy\"\n\n// Get end of table\n@lastline = get last line containing \"Date Description Service Fee\"\n@transactionsBottom = get line above 60\n\n@toptxt = bottom @lastline\n@bottomtxt = bottom @transactionsBottom\n@periodfromtxt = get text in box @toptxt @bottomtxt 30 106\n@closingbaltxt = get text in box @toptxt @bottomtxt 465 565\n\n$periodFrom = take last words @periodfromtxt 3 => get date \"dd MMM yyyy\"\n$closingbalance = take last words @closingbaltxt 2 => get decimal\n\nignore footer below 36\ndelete all lines starting \"Date Description Service Fee\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 106 260 348 465 565 => describe table false \"*Date[dd MMM yyyy]\" Details - #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 106 260 335 455 565 => describe table false \"*Date[dd MMM yyyy]\" Details - #Credit #Balance','2024-07-03 06:20:59',0);
