 in Table\n//$transactions = get multi page table @transactionsTop @transactionsBottom 45 90 315 400 485 560 => describe table false \"*Date[dd MMM]\" Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 90 315 485 560 => describe table false \"*Date[dd MMM]\" Details #Credit #Balance','2023-12-14 06:45:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10335,'MaybankIslamic','$source = \"MaybankIslamic\"\n\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"DR\"\n\n\n$accountName = get text in box 664 655 420 page.right => take words 1 => get text\n\n$accountNumber = get text in box 664 655 420 page.right => take words 1 => get text\n\n$openingBalance = get line starting \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => get decimal\n\n$closingBalance = get line starting \"ENDING BALANCE :\" => get words after \"ENDING BALANCE :\" => get decimal\n\ngo to page 1\n\n$periodFrom = get line starting \"BEGINNING BALANCE\" => bottom => get line below => take words 1  => get date \"dd/MM\"\n\n@transactionsTop = get line starting \"ENTRY DATE VALUE DATE TRANSACTION DESCRIPTION TRANSACTION AMOUNT STATEMENT BALANCE\" => bottom => get line below\n\n@transactionsBottom = get line starting \"ENDING BALANCE :\" => top => get line above\n\n@footerLast = bottom @transactionsBottom\n\n$periodTo = get line starting \"STATEMENT DATE\" => top => get line above => take last words 1  => get date \"dd/MM/yy\"\n\ndelete all lines starting \"BEGINNING BALANCE\"\n\ndelete all lines containing \"TRANSACTION DESCRIPTION\"\n\nignore footer below 126\n\nignore header above 575\n\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 80 320 400 485 570 => describe table false \"Date[dd/MM]\" - Details #Credit *#Balance','2023-05-19 11:16:36',0);
