INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10338,'Danske_SE_BookedBalance','$source = \"Danske_SE_BookedBalance\"\n$features = \"REVERSE_ORDER\"\n$periodBufferDays = 5\n\nset culture \"sv-SE\"\n\n// Get account number\n$accountNumber = get line containing \"Account:\" => bottom => get line below => take words 1 => get text\n\n// Get account name\n$accountName = get line starting \"Account holder:\" => skip words 2 => take words 2 => get text\n\n// Get period from/to\n@period = get line starting \"Period:\"\n$periodFrom = skip words @period 1 => take words 1 => get date \"yyyyMMdd\"\n$periodTo = take last words @period 1 => get date \"yyyyMMdd\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Account:\" => get words after \"Balance at:\" => skip words 1 => get decimal\n$closingBalance = get line starting \"BIC/SWIFT\" => get words after \"Balance at:\" => skip words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Booked and\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get last line containing \"Print from\" => top => get line above\n\n// Discard page header\nget last line containing \"Booked and\" => bottom => ignore header above\n\ndelete all lines containing \"Booked and\"\ndelete all lines Containing \"Amount in SEK\"\ndelete all lines Containing \"Amount in EUR\"\ndelete all lines starting \"interest SEK\"\ndelete all lines starting \"interest EUR\"\ndelete all lines starting \"date\"\n\n// Discard page footer\nignore footer below 70\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 280 440 580 => describe table false \"*Date[yyyyMMdd]\" Details #Credit #Balance','2022-12-14 12:37:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10339,'HSBC_PREMIER_PLC','$source = \"HSBC_PREMIER_PLC\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n\n$accountName = get line starting \"My accounts\" => top => get line above => take words 1 => get text\n\n\n$accountNumber  = get text in box 698 686 110 195 => get text\n\n$statementPeriod = get line containing \"Balance brought forward\" => take words 2\n$periodFromText = take words $statementPeriod 2 => get text\n$periodFrom = take words $statementPeriod 2 => get date \"dd MMM\"\n\n$periodTo = get line starting \"Statement date:\" => bottom => get line below => get date \"dd MMM yyyy\"\n\ngo to page 1\n$openingBalance = get line containing \"Balance brought forward\" => take last words 1 => get decimal\n\n\n$closingBal = get line containing \"Balance carried forward\" => get words after \"Balance carried forward\"\n$closingBalanceText = take words $closingBal 1 => get text\n$closingBalance = take words $closingBal 1 => get decimal\n\n\n\ngo to page 1\n@transactionsTop = get line containing \"Balance brought forward\" => bottom => get line below\n@transactionBottom = get line containing \"Balance carried forward\" => top => get line above\n\ndelete all lines containing \"Balance brought forward\"\ndelete all lines containing \"Balance carried forward\"\ndelete all lines starting \"Date Type Description\"\ndelete all lines containing \"Previous statements\"\n\nignore header above 808\n\n\ngo to page 1\n//$transactions = get multi page table @transactionsTop @transactionBottom 25 70 110 250 305 358 420 => describe table false \"*Date[dd MMM]\" TransactionType Details #Debit #Credit #Balance\n\n$transactions = get multi page table @transactionsTop @transactionBottom 25 70 110 260 320 305 375 358 450 => describe table false \"*Date[dd MMM]\" TransactionType Details #Debit - #Credit - #Balance\n','2022-12-14 12:37:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10340,'PonceBank','$source = \"Ponce Bank\"\n\n// get account name\n$accountName = get line starting \"Statement Ending\" => bottom => get line below => take words 3 => get text\n\n// get account number\n$accountNumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// get Period From/To\n$periodFrom = get line containing \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get last line containing \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n// get opening/closing\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\n// non transactional page discards\nremove page 2\ngo to page 1\n\n// Get start & end of deposits table\n@depositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@depositsBottom = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n//@depositsBottom = get line starting \"Electronic Credits\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of Elc-credits table\n@creditsTop = get line starting \"Electronic Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line starting \"Electronic Debits\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of Elc-debits table\n@debitsTop = get line starting \"Electronic Debits\" =>  if not found then blank => bottom => get line below => bottom => get line below\n//@debitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of cheques table\n@chequeTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"* Indicates skipped check number\" => if not found then blank => top => get line above\n\n\ndelete all lines starting \"Check Nbr Date Amount\"\n@checkconttop = get line starting \"Checks Cleared (continued)\" => top\ndelete all lines containing \"(continued)\"\n\nignore footer below 12\nignore header above 700\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 60 90 150 215 => describe table false #ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n@chequeMiddle = get multi page table @chequeTop @chequebottom 245 275 340 400 => describe table false #ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 430 458 530 580 => describe table false #ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n\ndelete text in box @checkconttop page.bottom page.left page.right\ngo to page 1\n@checktop = get line starting \"Checks Cleared\" => top\ndelete text in box @checktop page.bottom page.left page.right\n\ndelete all lines containing \"Date Description Amount\"\ndelete all lines starting \"Other Debits\"\ndelete all lines containing \"RETURNED\"\n\n// reading the transactions\n@deposits = get multi page table @depositsTop @depositsBottom 30 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n@credits = get multi page table @creditsTop @creditsBottom 30 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 30 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\n\n\n// combining the transactions\n$transactions = combine described tables @deposits @credits @debits @chequeLeft @chequeMiddle @chequeRight','2022-12-14 12:37:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10341,'Investec_Specialist_Desc_Amt_Bal','$source = \"Investec_Specialist_Desc_Amt_Bal\"\n$periodBufferDays = 30\n\n// Transactions with DR text are negative\nset negative marker \"DR\"\n\n//Get Account Number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get account details\n//$accountName = get text in box 790 780 400 page.right => take words 2 => get text\n$accountName = get text in box 700 660 page.left page.middleX => take words 2 => get text\n\n// Get Dates\n//$periodfrom = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dMMMyyyy\"\n$periodfrom = get line containing \"Date Description Amount\" => bottom => get line below => take words 1 => get date \"dMMMyyyy\"\n$periodto = get line containing \"Statement date\" => get words after \"Statement date\" => take words 3 => get date \"dMMMyyyy\"\n\n// Get opening and closing balances\ngo to page 1\n$openingbalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\n//$closingbalance = get line containing \"CLOSING BALANCE INCLUDING INTEREST\" => get words after \"CLOSING BALANCE INCLUDING INTEREST\" => take words 1 => get decimal\n\n@closingbottom = get last line containing \"CLOSING BALANCE\" => bottom\n$closingbalance = get text in box page.top @closingbottom 260 330 => take last words 1 => get decimal\n\nset negative marker \"CR\"\n\ngo to page 1\n@top = get line containing \"Should you disagree with the information\" => top\n@bottom = get line containing \"Australia Botswana Canada\" => bottom\ndelete text in box on every page @top @bottom page.left page.right\ngo to page 1\n@top1 = get line containing \"Grow your savings with\" => top\n@bottom1 = get line containing \"A registered credit provider\" => bottom\ndelete text in box on every page @top1 @bottom1 page.left page.right\n\nignore header above 600\n\ngo to page 1\n@transactionsTop = get line containing \"OPENING BALANCE\" => bottom => get line below\n//@transactionsBottom = get line containing \"CLOSING BALANCE\" => top => get line above\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"INTEREST ADVISED\"\ndelete all lines containing \"REVISED INTEREST\"\ndelete all lines containing \"Date Description Amount\"\n\ndelete all lines containing \"CLOSING BALANCE\"\n//delete all lines containing \"Account Number\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 38 82 220 280 338 383 425 500  => describe table false \"*Date[dMMMyyyy]\" Details - #Balance - - *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 38 82 190 260  => describe table false \"*Date[dMMMyyyy]\" Details #Debit','2025-06-25 11:52:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10342,'RepublicBank','$source = \"RepublicBank\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n$accountNumber  = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n\n$accountName = get text in box 492 484 50 260 => get text\n\n\n$statementPeriod = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 3\n$periodFromText = take words $statementPeriod 1 => get text\n$periodFrom = take words $statementPeriod 1 => get date \"M/dd/yy\"\n$periodTo = take last words $statementPeriod 1 => get date \"M/dd/yy\"\n\n//get Opening and Closing Balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\n$closingBalance = get line containing \"Current Balance \" => get words after \"Current Balance \" => take words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Description Credits\" => bottom => get line below\n@transactionBottom = get line containing \"CHECKS IN NUMBER ORDER\" => top => get line above\n\ndelete all lines starting \"Date Description Credits\"\n\nignore header above 393\n\ngo to page 1\n\n$transactions = get multi page table @transactionsTop @transactionBottom 10 43 252 245 330 420 520 => describe table false \"*Date[M/dd]\" Details - #Credit #Debit #Balance\n','2022-12-14 12:37:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10343,'UOB_CreditCard','$source = \"UOB_CreditCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 30\nset negative marker \"CR\"\n\n$accountNumberText = get line containing \"Post Trans Description\" => top => get line above\n$accountNumber = take words $accountNumberText 1 => get text\n$accountName = take words $accountNumberText 3 => skip words 1 => get text\n\n$PeriodFromText = get line containing \"PREVIOUS BALANCE\" => top => get line below\n$PeriodFrom = take words $PeriodFromText 2 => get date \"dd MMM\"\n$PeriodToText = get line containing \"Statement Date\" => get words after \"Statement Date\"\n$PeriodTo = take words $PeriodToText 3 => get date \"dd MMM yyyy\"\n\n//Opening and Closing Balance\n@OpeningBalanceText = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\"\n$OpeningBalance = take words @OpeningBalanceText 2 => get decimal\n@ClosingBalanceText = get line containing \"SUB TOTAL\" => get words after \"SUB TOTAL\"\n$ClosingBalance = take last words @ClosingBalanceText 2 => get decimal\n\ngo to page 1\nignore header above  695\n@transactionsTop = get line containing \"Post Trans Description\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line containing \"SUB TOTAL\" => top => get line above\ndelete all lines starting \"Date Date\"\ndelete all lines starting \"PREVIOUS BALANCE\"\nignore footer below 52\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 95 140 460 570 => describe table false \"Date[dd MMM]\" - Details *#Credit\n','2022-12-14 12:37:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10344,'Academy_Bank','$source = \"Academy_Bank\"\n\nset negative marker \"-\"\n\n// Get Account Name\n$AccountName = get text in box 675 642 page.left page.middleX => take words 4 => get text\n\n// Get Account Number\n//@acctop = get line containing \"Account Type Account Number\" => bottom\n//$Accountnumber = get text in box @acctop 425 370 490 => get text\n@accnumtxt = get line containing \"Account Type Account Number\" => bottom => get line below\n$accountNumber = take last words @accnumtxt 2 => take words 1 => get text\n\nRemove Page 2\ngo to page 1\n\n@transactionsTop = get line containing \"Transaction Date Description Debits Credits Balance\" => bottom => get line below\n\n// Get Opening/Closing Balance\n$openingbalance = take last words @transactionsTop 1 => get decimal\n$closingbalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\n$periodfrom = take words @transactionsTop 1 => get date \"MM/dd/yyyy\"\n$periodto = get last line containing \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\nignore header above 650\ndelete all lines containing \"Transaction Date Description Debits Credits Balance\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Checking Account Statements\"\n\n// Get end of table\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 120 350 420 500 560 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 120 345 420 500 560 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2025-06-25 11:52:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10345,'Bendigo_Bank_au','$source = \"Bendigo_Bank_au\"\r\n\r\n@transTop = get line containing \"Date Transaction Withdrawals\" => top\r\ndelete text in box page.top @transTop page.left page.middleX\r\n\r\ndelete text in box on every page page.top page.bottom page.left 35\r\n\r\n// get account name and number\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\r\n$accountName = get line containing \"Account title\" => get words after \"Account title\" => get text\r\n\r\n// get Period from and to\r\n@period = get line containing \"Statement period\" => get words after \"Statement period\" => take words 7\r\n$periodFrom = take words @period 3 => get date \"d MMM yyyy\"\r\n$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\r\n\r\n// get opening and closing balance\r\n$openingBalance = get line containing \"Opening balance on\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Closing Balance on\" => take last words 1 => get decimal\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transaction Withdrawals Deposits Balance\" => bottom => get line below => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\nignore header above 720\r\nignore footer below 40\r\n\r\ndelete all lines containing \"Date Transaction\"\r\ndelete all lines starting \"Bendigo Everyday Account\"\r\ndelete all lines starting \"Statement period\"\r\ndelete all lines starting \"Statement number\"\r\ndelete all lines containing \"continued overleaf\"\r\n\r\ndelete all lines containing \"Monthly Transaction Summary\"\r\ndelete all lines containing \"Total Transaction Fees\"\r\ndelete all lines containing \"Total Rebates\"\r\ndelete all lines containing \"Net Transaction Fees for\"\r\ndelete all lines containing \"Interest Rate\"\r\n\r\n//Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 90 360 440 510 page.right => describe table false \"*Date[d MMM yy]\" Details #Debit #Credit #Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 90 360 440 510 page.right => describe table false \"Date[d MMM yy]\" Details *#Debit *#Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10346,'Vancity_Bank','$source = \"Vancity_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\ndelete tiny words\n\n// Removing left vertical text\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 50\n\n// Account Detials\ngo to page 1\n$accountName = get text in box 658 620 110 page.middleX => get text\n$accountNumber = get line containing \"ACCOUNT #\" => get words after \"ACCOUNT\" => take words 1 => get decimal\n\n// Statement Period\n$periodFrom = get line starting \"STATEMENT PERIOD:\" => get words after \"PERIOD:\" => get words before \"to\" => get date \"dd MMM yyyy\"\n$PeriodTo = get line starting \"STATEMENT PERIOD:\" => get words after \"to\" => get date \"dd MMM yyyy\"\n\n// Get Opening Balance\n$openingBalance = get line starting \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\n\n// Get Closing Balance\n@columnHeader = get line starting \"DATE DESCRIPTION WITHDRAWALS\" => get text\n@balance_left =  get line containing @columnHeader => take last words 1 => left => subtract 5\n@balance_right =  get line containing @columnHeader => take last words 1 => right => add 5\n@balance_bottom =  get line containing @columnHeader => take last words 1 => top\n$closingbalance =  get text in box page.top @balance_bottom @balance_left @balance_right => take last words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line containing \"DATE DESCRIPTION WITHDRAWALS\" => bottom => get line below\ndelete all lines starting \"OPENING BALANCE\"\n\n// Get end of table\n@transactionsBottom = get last line starting \"Please review your statement and report\" => top => get line above\n\n// Discard page header\ngo to page 1\n//get last lines starting \"DATE DESCRIPTION WITHDRAWALS\" => bottom => ignore header above\n\n$last_summerybottom =  get last line starting \"vancity.com\" => if not found then blank => top\n$delLast_summery = delete text in box page.top $last_summerybottom 0 page.right => get text\n\ngo to page 1\n@shareTop = get last line starting \"SHARES\" => if not found then blank => bottom\n@shareBottom = get last line starting \"Please review your statement and report\" => top\n$share_ftdel = delete text in box @shareTop @shareBottom 0 page.right => get text\n\ngo to page 1\n@lastFt_top = get last line starting \"Please review your statement and report\" => if not found then blank => bottom\n$lastFt_del = delete text in box @lastFt_top 0 0 page.right => get text\n\ndelete all lines starting \"INDEPENDENT BUSINESS ACCOUNT\"\ndelete all lines starting \"SHARES\"\ndelete all lines starting \"OPENING BALANCE\"\ndelete all lines starting \"Note: Shares\"\ndelete all lines starting \"CLASS\"\ndelete all lines starting \"Please review your statement and report\"\ndelete all lines starting \"DATE DESCRIPTION WITHDRAWALS\"\n// Discard page footer\nignore footer below 50\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 102 355 440 505 570 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit #Balance','2025-07-24 06:50:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10347,'Vancity_Bank_Card','$source = \"Vancity_Bank_Card\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 28\r\n\r\n// Get account name\r\n$accountName = get text in box 116 80 90 page.middleX => get text\r\n\r\n// Get account number\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number:\" => take last words 4 => get text\r\n@delaccountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 2 => get text\r\n\r\n// Statement Period\r\n@period = get line starting \"Statement period:\" => get words after \"period:\" => take words 6\r\n\r\n$periodFrom = take words @period 2 => get date \"MMMM d\"\r\n\r\n$periodTo = skip words @period 3 => get date \"MMMM d, yyyy\"\r\n\r\n// Get Opening Balance\r\n$openingBalance = get line starting \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\r\n\r\n$closingBalance = get line containing \"Statement balance\" => get words after \"Statement balance\" => get decimal\r\n\r\n// Removing left vertical text\r\ndelete text in box on every page page.top 0 400 700\r\n\r\ngo to page 1\r\n@TransactionsHeader = get line containing \"Trans. Post Description Amount\"\r\n@IgnoreHeader = bottom @TransactionsHeader\r\n@AmountLeft = get words after @TransactionsHeader \"Description\" => take words 1 => left => subtract 16\r\n@AmountRight = get words after @TransactionsHeader \"Description\" => take words 1 => right => add 5\r\n\r\n// Get start & end of transactions table\r\n@transactionsTop = get line containing \"Trans. Post Description Amount\" => bottom => get line below  => bottom => get line below\r\n\r\n@transactionslast = get last line containing \"Trans. Post Description Amount\"\r\n\r\n@transactionsBottom = get line above 0\r\n\r\ndelete all lines starting \"Page\"\r\ndelete all lines ending \"personal\"\r\ndelete all lines containing @delaccountNumber\r\nignore header above @IgnoreHeader\r\n\r\n// Read the transactions\r\n$transactions  = get multi page table @transactionsTop @transactionsBottom 55 95 132 345 @AmountLeft @AmountRight => describe table false \"Date[MMM dd]\" - Details - *#Credit','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10348,'Home_Bank','$source = \"Home_Bank\"\n\n// Get Account Name\n$AccountName = get text in box 620 590 page.left page.middleX => take words 4 => get text\n\n// Get opening/closing balance Or Periodfrom/Periodto\n$OpeningBalance = get line containing \"BALANCE LAST STATEMENT\" => get words after \"STATEMENT\" => take words 1 => get decimal\n$periodfrom = get line containing \"BALANCE LAST STATEMENT\" => get words before \"BALANCE\" => take words 1 => get date \"MM/dd/yy\"\n$ClosingBalance = get line containing \"BALANCE THIS STATEMENT\" => get words after \"STATEMENT\" => take words 1 => get decimal\n$periodto = get line containing \"BALANCE THIS STATEMENT\" => get words before \"BALANCE\" => take words 1 => get date \"MM/dd/yy\"\n\nRemove Page 2\ngo to page 1\n\n// Get start of table\n@transactionsTop = get line containing \"Date Description Debits Credits\" => bottom => get line below\n\n// Get Account Number\n$AccountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 1 => get text\n\nignore footer below 35\nignore header above 725\ndelete all lines starting \"Transactions\"\ndelete all lines containing \"Date Description Debits Credits\"\ndelete all lines containing \"BALANCE LAST STATEMENT\"\ndelete all lines containing \"BALANCE THIS STATEMENT\"\n\n// Get end of table\n@transactionsBottom = get line starting \"Checks\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 80 430 480 528 590 => describe table false \"*Date[MM/dd/yy]\" Details #Debit #Credit #Balance','2022-12-14 12:44:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10349,'EasternBank','$source = \"EasternBank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n$accountName = get text in box 643 600 75 page.middleX => get text\n\n// Get account number\n$accountNumber = get line starting \"Account Number:\" => get words after \"Number:\" => get text\n\n// Get periods\n$periodFrom = get line starting \"Statement Period:\" => get words after \"Period:\" => get words before \"thru\" => get date \"MMM dd yyyy\"\n$periodTo = get line starting \"Statement Period:\" => get words after \"thru\" => get date \"MMM dd yyyy\"\n\n// Get balances\n$openingBalance = get line starting \"STARTING BALANCE\" => get words after \"STARTING BALANCE\" => get decimal\n\n//remove page 2\n\nignore header above 675\nignore footer below 20\n\n// Get start and end of transactions and  Cheque table\n@transactionstxnTop = get line starting \"Date Transaction Description Withdrawal\" => bottom => get line below\ndelete all lines starting \"STARTING BALANCE\"\ndelete all lines starting \"Date Transaction Description Withdrawal\"\n@transactionstxnBottom = get last line starting \"Starting Balance:\" => top => get line above\n\n$closingBalance = get line starting \"Ending Balance:\" => get words after \"Ending Balance:\" => take words 1 => get decimal\n\n@transactionstxn = get multi page table @transactionstxnTop @transactionstxnBottom 46 76 375 440 510 575 => describe table false \"*Date[MMM d]\" Details #Debit #Credit #Balance\n\n@chequeTop = get line starting \"Check No. Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Indicates a skip in sequence\" => if not found then blank => top => get line above\n\n@checksLeft = get multi page table @chequeTop @chequebottom 46 100 153 170 222 => describe table false ChequeNumber \"Date[MM/dd]\" - *#Debit\n@checksMiddle = get multi page table @chequeTop @chequebottom 230 280 332 347 400 => describe table false ChequeNumber \"Date[MM/dd]\" - *#Debit\n@checksRight = get multi page table @chequeTop @chequebottom 410 450 510 525 580 => describe table false ChequeNumber \"Date[MM/dd]\" - *#Debit\n\n$transactions = combine described tables @transactionstxn @checksLeft @checksMiddle @checksRight','2023-06-16 07:42:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10350,'BankofSantaClarita','$source = \"BankofSantaClarita\"\n\n// Get account name\n$accountName = get text in box 602 572 75 page.middleX => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Number:\" => get text\n\ngo to page 1\n@TEXTBOXTop = get line containing \"Previous balance\" => top\n@TEXTBOXBottom = get line containing \"Ending balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 40 290\n\n// Get periods\n$periodFrom = get words after @TEXTBOX \"Previous balance\" => take words 1 => get date \"MM/dd/yyyy\"\n//$periodFrom = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n$periodTo = get words after @TEXTBOX \"Ending balance\" => take words 1 => get date \"MM/dd/yyyy\"\n//$periodTo = get line containing \"Ending balance\" => get words after \"Ending balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n// Get balances\n$openingBalance = get words after @TEXTBOX \"Previous balance\" => skip words 1 => take words 1 => get decimal\n//$openingBalanceText = get line containing \"Previous balance\" => get words after \"Previous balance\" => skip words 1 => take words 1\n//$openingBalance = get decimal $openingBalanceText\n\n$closingBalance = get words after @TEXTBOX \"Ending balance\" => skip words 1 => take words 1 => get decimal\n//$closingBalancetext = get line containing \"Ending balance\" => get words after \"Ending balance\" => skip words 1 => take words 1\n//$closingBalance = get decimal $closingBalancetext\n\nignore header above 632\n\n// Get start & end of credits table\n@creditsTop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line containing \"Total Deposits\" => if not found then blank => top => get line above\n\n// Get start & end of debits table\n@debitsTop = get line starting \"WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get line containing \"Total Withdrawals\" => if not found then blank => top => get line above\n\n// Get start and end of Cheques table\n@chequeTop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Total Amount of Checks\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"(continued)\"\n\n@credits = get multi page table @creditsTop @creditsBottom 40 110 500 572 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@debits = get multi page table @debitsTop @debitsBottom 40 110 500 572 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\n@chequeLeft = get multi page table @chequeTop @chequebottom 40 80 145 210 => describe table false ChequeNumber \"Date[MM/dd/yy]\" *#Debit\n@chequeMiddle = get multi page table @chequeTop @chequebottom 220 250 325 395 => describe table false ChequeNumber \"Date[MM/dd/yy]\" *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 400 430 505 575 => describe table false ChequeNumber \"Date[MM/dd/yy]\" *#Debit\n\n$transactions = combine described tables @credits @debits @chequeLeft @chequeMiddle @chequeRight','2022-12-14 12:44:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10351,'NewMillenniumBank','$source = \"NewMillenniumBank\"\n\ndelete white words\n\n// Get account deatils\n$accountName = get text in box 665 642 54 page.middleX => get text\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get opening balance\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => get decimal\n\n// Get period from\ngo to page 1\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/dd/yyyy\"\n\n// Get period to\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => get date \"MM/dd/yyyy\"\n\n// Get closing balance\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\ngo to page 1\n\n// Get start and end of table\n@transactionsTop = get line starting \"Post Date Description Debits\" => bottom => get line below\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\nignore header above 668\nignore footer below 16\n\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"(continued)\"\ndelete all lines starting \"Post Date Description Debits\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 85 345 410 495 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2022-12-14 12:44:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10352,'Modulr','$source = \"Modulr\"\n\n$features = \"REVERSE_ORDER\"\n\n// Get account details\n$accountName = get line starting \"STATEMENT\" => bottom => get line below => take words 2 => get text\n\n@TEXTBOXTop1 = get line starting \"Our details\" => top => get line above => top\n@TEXTBOXBottom1 = get line starting \"Our details\" => top\n$accountNumber = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 75 page.middleX => get text\n\n//$accountNumber = get line containing \"Account number\" => bottom => get line below => take last words 1 => get text\n\n@TEXTBOXTop = get line containing \"Period\" => top\n@TEXTBOXBottom = get line starting \"Date Reference Details Paid\" => top\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 330 560\n\n// Get periods\n$periodFrom = get words after @TEXTBOX \"Period\" => get words before \"-\" => get date \"d MMM\"\n$periodTo = get words after @TEXTBOX \"Period\" => get words after \"-\" => take words 3 => get date \"d MMM yyyy\"\n\n// Get balances\n$closingBalance = get words after @TEXTBOX \"Previous balance\" => take words 2 => get decimal\n$openingBalance = get words after @TEXTBOX \"BALANCE\" => take words 2 => get decimal\n\n// Get start and end of table\n@transactionsTop = get line starting \"Date Reference Details Paid in\" => bottom => get line below\n@transactionsBottom = get last line starting \"Modulr accounts are provided by Modulr\" => top => get line above\n\n// discards\nignore header above 725\nignore footer below 96\ndelete all lines starting \"PAGE\"\ndelete all lines starting \"Date Reference Details Paid\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 330 400 480 560 => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 98 350 422 495 562 => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Debit #Balance','2025-06-25 11:51:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10353,'BankofTexas','$source = \"BankofTexas\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete tiny words\ndelete rotated words\ndelete white words\n\n// discarding right bar/Qr codes\ndelete text in box on every page page.top 0 0 80\n\n// Get account name\ngo to page 1\n$accountName = get text in box 661 635 80 page.middleX => get text\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT:\" => get words after \"ACCOUNT:\" => get text\n\n// Get period from\n$periodFrom = get line containing \"Statement Period from\" => get words after \"Period from\" => get words before \"through\" => get date \"MM-dd-yy\"\n\n// Get period to\n$periodTo = get line containing \"Statement Period from\" => get words after \"through\" => get date \"MM-dd-yy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Starting Balance\" => get words after \"Starting Balance\" => get decimal\n\n// Get closing balance\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\ngo to page 1\n// header and footer discards\nignore header above 570\nignore footer below 50\n\n// non transactional page discards\nremove page 2\n\n// Get start & end of credits table\n@creditsTop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line starting \"WITHDRAWALS\" => if not found then blank => top => get line above\n\n// Get start & end of debits table\n@debitsTop = get line starting \"WITHDRAWALS\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get line starting \"CHECKS\" => if not found then blank => top => get line above\n\n// Get start & end of cheques table\n@chequeTop = get line starting \"Date Number Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"DAILY ACCOUNT BALANCE\" => if not found then blank => top => get line above\n\n// non transactional rows discards\ndelete all lines containing \"(cont.)\"\ndelete all lines starting \"Date Amount\"\ndelete all lines starting \"WITHDRAWALS\"\ndelete all lines starting \"DEPOSITS\"\ndelete all lines starting \"CHECKS\"\ndelete all lines containing \"RTND Indicates\"\ndelete all lines containing \"Date Number Amount\"\n\n// reading the transactions\n@credits = get multi page table @creditsTop @creditsBottom 85 119 480 565 => describe table false \"Date[MM-dd]\" Details *#Credit\n@debits = get multi page table @debitsTop @debitsBottom 85 119 480 565 => describe table false \"Date[MM-dd]\" Details *#Debit\n@chequeLeft = get multi page table @chequeTop @chequebottom 85 130 220 310 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 315 370 460 555 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit\n\n// combining the transactions\n$transactions = combine described tables @credits @debits @chequeLeft @chequeRight','2025-01-09 08:36:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10354,'RMB_Private_Bank','$source = \"RMB_Private_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get Account Name\n$AccountName = get text in box 720 660 page.left page.middleX => take words 3 => get text\n\n// Get Period From/To\n$periodFrom = get line starting \"Statement Period :\" => get words after \"Statement Period :\" => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = get line starting \"Statement Period :\" => take last words 3 => get date \"d MMMM yyyy\"\n\n// Get Account Number\n$AccountNumber = get line containing \"Account\" => get words after \"Account\" => take last words 1 => get text\n\n// Get Top of the table\ngo to page 1\n\n$Date_left = get line containing \"Date Description Amount\" => get words before \"Description \" => left => subtract 6\n$Description_left = get line containing \"Date Description Amount\" => get words before \"Description \" => right => add 5\n$Description_right = get line containing \"Date Description Amount\" => get words after \"Description\" => left => subtract 15\n$Paidout_right = get line containing \"Date Description Amount\" => get words after \"Amount\" => left => subtract 15\n$Balance_right = get line containing \"Date Description Amount\" => get words after \"Balance\" => left => subtract 9\n\n\n@transactionsTop = get line starting \"Date Description Amount Balance\" => bottom => get line below\n\ndelete all lines starting \"Accrued\"\ndelete all lines starting \"Charges\"\ndelete all lines containing \"Date Description Amount Balance\"\nset negative marker \"Dr\"\n\n// Get opening/closing balance\n\n$openingbalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$closingbalance = get last line starting \"Closing Balance\" => get words after \"Closing Balance\" => take last words 2 => get decimal\n\nset negative marker \"Cr\"\ndelete all lines starting \"Opening Balance\"\nignore footer below 65\n\n// Get End of the table\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 46 370 450 520 => describe table false \"*Date[dd MMM]\" Details #Debit #Balance\n//set negative marker \"Cr\"\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Description_left $Description_right $Paidout_right $Balance_right   => describe table false \"*Date[dd MMM]\" Details #Debit ','2025-10-29 06:16:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10355,'Close Brothers','$source = \"Close Brothers\"\n\n//Get Account Name\n$accountname = get text in box 750 710 page.left 200 => take words 2 => get text\n$features = \"CREDIT_CARD\"\nset negative marker \"(\"\n\n//Get Account Number\n@accnbrtop = get line starting \"Current Account\" => top\n@accnbrbottom = get line starting \"Invoice\" => top\n$accountNumber = get text in box @accnbrtop @accnbrbottom page.left 160 => get words after \"Current Account\" => get text\n//get line containing \"Current Account\" => get words after \"Current Account\" => take words 1 => get text\n\n//Get First and Last Statemengt date\n$periodFrom = get line starting \"Opening Balance\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line starting \"Closing Balance\" => top => get line above => take words 1 => get date \"dd/MM/yyyy\"\n\n//Get First Transection\ngo to page 1\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\n\n//Get Opening and Closing Balance Amount\n$openingBalance = get last line containing \"Opening Balance\" => take last words 1 => get decimal\n$closingBalance  = get last line containing \"Closing Balance\" => take last words 1 => get decimal\n\nignore footer below 90\ndelete all lines starting \"Date Transaction Reference\"\nignore header above 745\n\n//Get Last Transection\n@transactionsBottom = get line starting \"Closing Balance\" => top => get line above\n\n//Get all Transection in Table\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 87 320 400 470 560 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit -','2022-12-14 12:44:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10356,'Scotia_Bank_French','$source = \"Scotia_Bank_French\"\r\n\r\n// Get account number/name\r\n$accountname = get text in box 690 675 16 225 => get text\r\n$accountnumber = get line starting \"Relevé de: Numéro de compte:\" => bottom => get line below => take words 5 => take last words 3 => get text\r\n\r\n// Get statement period from\r\n$periodfrom = get line starting \"Date Description Retraits/Débits ($)\" => bottom => get line below => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening balance\r\n$openingbalance = get line starting \"Date Description Retraits/Débits ($)\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n@gettop = get last line starting \"Date Description Retraits/Débits ($)\" => bottom\r\n@getlast = get last line starting \"Nombre de débits Total - Débits\" => top\r\n\r\n// Get statement period to\r\n$periodto = get text in box @gettop @getlast 15 65 => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get closing balance\r\n@closingLeft = get last line starting \"Date Description Retraits/Débits\" => get words before \"Solde\" => take last words 1 => right => add 10\r\n$closingbalance = get text in box @gettop @getlast @closingLeft 597 => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@topdel = get line starting \"Sommaire du compte pour cette période:\" => top\r\n@headerBottom = get line starting \"Détails du compte:\" => top\r\ndelete text in box @topdel @headerBottom page.left page.right\r\n\r\n// Get the start and end of the transaction\r\n@transactionsTop = get line starting \"Date Description Retraits/Débits ($)\" => bottom => get line below\r\ndelete all lines containing \"REPORT\"\r\n@transactionsBottom = get last line starting \"Nombre de débits Total - Débits\" => top => get line above\r\n\r\n// Discard header and footer\r\nignore footer below 50\r\nignore header above 635\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Date Description Retraits/Débits ($)\"\r\ndelete all lines starting \"Nombre de débits Total - Débits\"\r\ndelete all lines starting \"0 $\"\r\ndelete all lines starting \"1 $\"\r\ndelete all lines starting \"2 $\"\r\ndelete all lines starting \"3 $\"\r\ndelete all lines starting \"4 $\"\r\ndelete all lines starting \"5 $\"\r\ndelete all lines starting \"6 $\"\r\ndelete all lines starting \"7 $\"\r\ndelete all lines starting \"8 $\"\r\ndelete all lines starting \"9 $\"\r\ndelete all lines starting \"10 $\"\r\ndelete all lines starting \"11 $\"\r\ndelete all lines starting \"12 $\"\r\ndelete all lines starting \"13 $\"\r\ndelete all lines starting \"14 $\"\r\ndelete all lines starting \"15 $\"\r\ndelete all lines starting \"16 $\"\r\ndelete all lines starting \"17 $\"\r\ndelete all lines starting \"18 $\"\r\ndelete all lines starting \"19 $\"\r\ndelete all lines starting \"20 $\"\r\ndelete all lines starting \"21 $\"\r\ndelete all lines starting \"22 $\"\r\ndelete all lines starting \"23 $\"\r\ndelete all lines starting \"24 $\"\r\ndelete all lines starting \"25 $\"\r\n\r\n// Get all Transactions in Table\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 75 300 410 500 600 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10357,'NedBank_SouthAfrica','$source = \"NedBank_SouthAfrica\"\r\n\r\ndelete rotated words\r\n\r\n$accountname = get text in box page.top 720 page.left 230 => get text\r\n\r\n$periodfrom = get line containing \"From :\" => take last words 3 => get date \"d MMMM yyyy\"\r\n$periodto = get line containing \"Statement date :\" => get words after \"date :\" => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n$accountnumber = get line containing \"Account number:\" => get words after \"number:\" => take words 1 => get text\r\n\r\ngo to page 1\r\n$openingbalance = get line containing \"Opening Balance\" => take last words 1 => get decimal\r\n$closingbalance = get line containing \"Closing Balance\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line starting \"Tran List No Date Description/Narrative\" => bottom => get line below\r\n\r\ngo to last page\r\n@transactionsbottom = get line above page.bottom\r\n\r\nignore header above 716\r\ndelete all lines containing \"Opening Balance\"\r\ndelete all lines containing \"Balance Carried Forward\"\r\ndelete all lines containing \"Balance Brought Forward\"\r\nignore footer below 20\r\n\r\n$transactions = get multi page table @transactionstop @transactionsbottom 88 130 300 340 420 500 570 => describe table false *Date[dd/MM/yyyy] Details - #Debit #Credit #Balance','2026-08-25 09:33:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10358,'CapitalOneCard_PaidIn_Out','$source = \"CapitalOneCard_PaidIn_Out\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n// get Account Name\n$accountname = get line containing \"Account No.\" => top => get line above => take words 3 => get text\n\n// get Account Number\n$accountnumber = get line containing \"Account No.\" => take last words 1 => get text\n\n// get Opening/Closing Balance\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Your new balance\" => take last words 1 => get decimal\n\ngo to page 1\n@top = get line containing \"continued on next page\" => bottom\n$deletefotterTxt = delete text in box @top page.bottom page.left page.right => get text\n@deletextra = delete text in box @top page.bottom page.left page.right\n\n\n// get Start of the table\n@transactionsTop = get line containing \"Your transaction details Paid in Paid out\" => bottom => get line below\n\n// get Period From/To\n$periodfrom = take words @transactionsTop 2 => get date \"dd MMM\"\n//$periodto = get line containing \"STATEMENT TOTALS\" => take words 2 => get date \"dd MMM\"\ngo to page 1\n//$periodto = get line containing \"Available to spend\" =>  get words after \"at\" => take words 1 => get date \"dd/MM/yy\"\n\n@periodTopBox = get line containing \"Available to spend\" => top\n\n@periodbox = get text in box @periodTopBox page.bottom page.middleX page.right\n$periodto  = get words after @periodbox \"at\" => take words 1 => get date \"dd/MM/yy\"\n\ngo to page 1\n//get line containing \"continued on next page...\" => top => ignore footer below\n//go to page 1\n\ndelete all lines starting \"continued\"\ndelete all lines starting \"Your transaction details Paid in Paid out\"\n//ignore header above 670\n\ngo to page 1\n// get End of the table\n@transactionsBottom = get line containing \"STATEMENT TOTALS\" => top => get line above\n\nignore header above 670\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 72 300 350 400 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit','2024-12-11 08:10:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10359,'FNB_WealthCreditCard','$source = \"FNB_WealthCreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 28\n\n// Transactions with CR text are negative\nset negative marker \"Cr\"\n\n// Get Account Name\n$accountname = get text in box 712 660 page.left page.middleX => take words 3  => get text\n\n// Get Account Number\n//$accountNumber = get line containing \"CREDIT CARD\" => get words after \"CREDIT CARD\" => take words 5 => get text\n$accountNumber = get line containing \"CREDIT\" => get words after \"CREDIT\" => take last words 4 => get text\n\n// Get Opening/Closing & From/To Period\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dd MMM yyyy\"\n\n//$openingbalance = get last line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$openingbalance = get last line starting \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n\n$closingbalance = get last line starting \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\n$periodFrom = get last line containing \"Opening Balance\" => bottom => get line below => bottom => get line below => take words 2 => get date \"dd MMM\"\n\ngo to page 1\ndelete all lines containing \"FNB PRIVATE\"\ndelete all lines containing \"Items marked #\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Card No.\"\ndelete all lines containing \"Card Total\"\ndelete all lines containing \"SUP\"\ndelete all lines containing \"Page\"\n\n// Get start of the table\n@transactionsTop = get line containing \"Tran Straight Budget Transaction Details\" => bottom => get line below\n\n// Get end of the table\n@transactionsBottom = get line containing \"Closing Balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 55 310 375 => describe table false \"*Date[dd MMM]\" Details #Credit','2024-07-31 07:20:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10360,'ColumbiaCreditUnion','$source = \"ColumbiaCreditUnion\"\n$features = \"NO_TRANSACTION_YEAR\"\n// Get account details\n$accountName = get text in box 650 600 100 page.middleX => take words 2 => get text\n@AccRight =  get line starting \"Date Transaction Description\" => top => get line above => left\n@AccBottom = get line containing \"Date Transaction Description Debits Credits Balance\" => Top\n$accountNumber = get text in box 660 @AccBottom page.left @AccRight => take last words 1 => get text\n\n// Get balances\n@Balance = get line starting \"Date Transaction Description\" => top => get line above\n$openingBalance = take words @Balance 1 => get decimal\n$closingBalance = take last words @Balance 1 => get decimal\n\n// Get periods\n@period = get text in box page.top 690 500 page.right\n$periodFrom = take words @period 1 => get date \"MM/dd/yyyy\"\n$periodTo = take words @period 2 => take last words 1 =>  get date \"MM/dd/yyyy\"\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Transaction Description Debits Credits Balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total Credits\" => top => get line above\n\n// Discard page header\nget last line containing \"Date Transaction Description Debits Credits Balance\" => bottom => ignore header above\n\n// Discard unwanted lines\ndelete all lines starting \"Date Transaction Description Debits Credits Balance\"\ndelete all lines containing \"Total Credits\"\nignore header above 645\nignore Footer below 15\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 10 95 90 380 442 520 620 => describe table false \"*Date[MM/dd]\" - Details #Debit #Credit #Balance\n','2022-12-14 12:44:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10361,'Monzo_PaidIn_Out','$source = \"Monzo_PaidIn_Out\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\nset negative marker \"-\"\n\n// Get Account Name\n$accountName = get text in box 710 650 page.left page.middleX => take words 4 => get text\n\n// Get Period/From\n$periodFrom = get line containing \"Account statement\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"Account statement\" => bottom => get line below => take last words 1 => get date \"dd/MM/yyyy\"\n\n// Get Account Number\n$accountNumber = get line starting \"Account number:\" => get words after \"Account number:\" => take last words 1 => get text\n\n// Get Opening/Closing Balance\n//$closingBalance = get line containing \"Total balance\" => top => get line above => take last words 1 => get decimal\n$closingBalance = get line containing \"Account balance\" => top => get line above => take last words 1 => get decimal\n$openingBalance = get line containing \"Description Paid in Paid out Balance\" => bottom => get line below => take last words 1 => get decimal\n\n// Get start of transaction table\n@transactionsTop = get line containing \"Description Paid in Paid out Balance\" => bottom => get line below\n\ndelete all lines containing \"//business.monzo.com\"\ndelete all lines containing \"Monzo_bank_statement\"\ndelete all lines containing \"Description Paid in Paid out Balance\"\n\n// Get end of transaction table\n@transactionsBottom = get line starting \"Monzo Bank Limited\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 110 360 430 500 560 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit #Balance','2023-01-17 08:29:34',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10362,'VirginMoneyOnline','$source = \"VirginMoneyOnline\"\n\n$features = \"NO_OPENING_BALANCE REVERSE_ORDER\"\n$periodBufferDays = 5\nset negative marker  \"-\"\n$accountname = get line below page.top => bottom => get line below => get text\n$accountnumber = get line starting \"Business Access Account Issue\" => bottom => get line below => take words 3 => take last words 1 => get text\n\n@gettop = get line starting \"Date Details Money out\" => bottom\n@getlast = get last line starting \"CARE OF NORTH SOUTH DESIGN LTD\" => top\n$periodfrom = get text in box @gettop @getlast 50 110 => take last words 1 => get date \"dd/MM/yyyy\"\n//$openingbalance = get line starting \"Date Details Money out\" => bottom => get line below => take last words 1 => get decimal\n\n$periodto = get line starting \"Date Details Money out\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n@top = get line starting \"Date Details Money out\" => bottom\n@bottom = get line starting \"Date Details Money out\" => bottom => get line below => bottom\n$closingbalance = get text in box @top @bottom 450 page.right => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Date Details Money out\" => bottom => get line below\n\ngo to last page\n@transactionsBottom = get last line starting \"CARE OF NORTH SOUTH DESIGN LTD\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 110 245 350 420 510 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance','2022-12-14 12:44:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10363,'WebsterBank','$source = \"WebsterBank\"\n\nset negative marker \"-\"\n\n// Get Account Name\n$accountName = get text in box 665 645 page.left page.middleX => take words 4 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => take last words 2 => take words 1 => get text\n\n// Get opening/closing balance\n$closingBalance = get line containing \"ENDING BALANCE\" => bottom => get line below => take last words 1 => get decimal\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n\n// Get period From/To\n$periodFrom = get line containing \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get last line containing \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n@transactionsTop = get line starting \"Transaction Date Description Debits Credits\" => bottom => get line below => bottom => get line below\n\nremove page 2\nignore footer below 15\nignore header above 635\ndelete all lines starting \"Transaction Date Description Debits Credits\"\n\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\n//$transactions  = get multi page table @transactionsTop @transactionsBottom 35 120 350 430 500 560 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit *#Credit #Balance\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 120 350 415 500 560 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit *#Credit #Balance','2025-10-29 06:16:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10364,'BNP_Paribas','$source = \"BNP_Paribas\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Parse dates and amount in French\nset culture \"fr-CA\"\n\n\n// Get Account Name\n@AcNameTop = get line containing \"RIB\" => top\n@AcNameBottom = get line containing \"RIB\" => bottom\n$AccountName = get text in box @AcNameTop @AcNameBottom page.middleX page.right => get text\n\n// Get Account Number\n$AccountNumber = get text in box @AcNameTop @AcNameBottom page.left page.middleX => get words after \"RIB :\" => get text\n\n// Get opening/closing balance Or Periodfrom/Periodto\n@OpeningBalanceTop = get line containing \"SOLDE CREDITEUR AU\" => top\n@OpeningBalanceBottom = get line containing \"SOLDE CREDITEUR AU\" => bottom\n$OpeningBalance = get text in box @OpeningBalanceTop @OpeningBalanceBottom page.middleX page.right => get decimal\n\n$periodfrom = get line containing \"SOLDE CREDITEUR AU\" => get words after \"AU\" => take words 1 => get date \"dd.MM.yyyy\"\n@ClosingBalanceTop = get last line starting \"SOLDE\" => top\n@ClosingBalanceBottom = get last line starting \"SOLDE\" => bottom\n$ClosingBalance = get text in box @ClosingBalanceTop @ClosingBalanceBottom page.middleX page.right => get decimal\n$periodto = get last line starting \"SOLDE\" => get words after \"AU\" => take words 1 => get date \"dd.MM.yyyy\"\n\ngo to page 1\n\n// Get start of table\n@transactionsTop = get line containing \"Date Nature des\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line starting \"TOTAL DES OPERATIONS\" => top => get line above\n\nignore footer below 80\nignore header above 740\ndelete all lines containing \"Date Nature des\"\ndelete all lines containing \"SOLDE CREDITEUR AU\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 60 300 400 480 550 => describe table false \"*Date[dd.MM]\" Details \"Valeur[dd.MM]\" #Debit #Credit','2023-01-05 09:51:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10365,'SalemFive','$source = \"SalemFive\"\n\n$accountName = get text in box 661 650 55 200 => get text\n$accountNumberText = get line starting \"Account Type Account Number Ending Balance\" => bottom => get line below => skip words 3\n$accountNumber = take words $accountNumberText 1 => get text\n\n//get line starting \"Account Activity\" => top => ignore header above\n\n//$PeriodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n//$PeriodTo = get line containing \"Ending Balance\" => get words before \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n@acctop = get line starting \"Date Description Amount\" => bottom\ndelete all lines starting \"Service Charges\"\n@accbottom = get line starting \"Account Activity\" => top\n\n$accdetails = get text in box @acctop @accbottom 30 345\n\n$PeriodFrom = get words before $accdetails \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\n\n$PeriodTo =  get words before $accdetails \"Ending Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\n\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n\n//$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n$closingBalance = take last words $accdetails 1 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line containing \"Post Date Description Debits Credits\" => bottom => get line below\n@transactionBottom = get line containing \"Daily Balances\" => top => get line above\n\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\n\nignore footer below 80\n// Discard info on page 2\ngo to page 2\nget line starting \"Important: Please notify us \" => top => delete text in box 0 page.left page.right\nignore header above 705\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionBottom 30 85 350 410 490 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2023-01-05 09:51:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10366,'TowneBank','$source = \"TowneBank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete tiny words\ndelete rotated words\ndelete white words\n\n// discarding right bar/Qr codes\ndelete text in box on every page page.top page.bottom page.left 50\n\n// Get account name\ngo to page 1\n$accountName = get text in box 659 647 50 page.middleX => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Number:\" => get text\n\n// Get balances and periods panel\n@panelTop = get line containing \"Beginning Balance as of\" => top\n@panelBottom = get line containing \"Ending Balance as of\" => bottom\n@panelWords = get text in box @panelTop @panelBottom 50 570\n\n$periodFrom = get words after @panelWords \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\n$openingBalance = skip words @panelWords 5 => take words 1 => get decimal\n\n$periodTo = get words after @panelWords \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\n$closingBalance = get words after @panelWords \"Ending Balance as of\" => take last words 1 => get decimal\n\nset negative marker \"-\"\n\n// header and footer discards\nignore header above 635\nignore footer below 17\n\n// non transactional page discards\nremove page 2\n\n// Get start & end of cheques table\n@chequeTop = get line starting \"Date Check# Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"Transaction Detail\" => if not found then blank => top => get line above\n\n// Get start & end of Transaction\n@TransactionsTop = get line starting \"Date Description Deposits\" => if not found then blank => bottom => get line below\n@TransactionsBottom = get line starting \"Balance By Date\" => if not found then blank => top => get line above\n\n// non transactional rows discards\ndelete all lines containing \"Transaction Detail\"\ndelete all lines starting \"(Continued)\"\ndelete all lines starting \"Date Description Deposits\"\n\n// reading the transactions\n@TransactionsTable = get multi page table @TransactionsTop @TransactionsBottom 50 90 380 480 570 => describe table false \"*Date[MMMdd]\" Details #Credit #Debit\n@chequeLeft = get multi page table @chequeTop @chequebottom 50 105 155 222 => describe table false \"Date[MMMdd]\" ChequeNumber *#Debit\n@chequeCenter = get multi page table @chequeTop @chequebottom 222 265 330 396 => describe table false \"Date[MMMdd]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 396 454 510 570 => describe table false \"Date[MMMdd]\" ChequeNumber *#Debit\n\n// combining the transactions\n$transactions = combine described tables @TransactionsTable @chequeLeft @chequeCenter @chequeRight','2023-01-05 09:51:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10367,'FirstNationalBank_EffectiveDate','$source = \"FirstNationalBank_EffectiveDate\"\n\n// Get account name\n$accountName = get line containing \"Name :\" => get words after \"Name :\" => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number :\" => get words after \"Account Number :\" => take words 1 => get text\n\n// Get Period\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dd MMM yyyy\"\n\n// Get Opening/Closing balance\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\n// Get top of transaction table\n@transactionsTop = get line containing \"Effective Date Description\" => bottom => get line below\n$periodFrom = take words @transactionsTop 3 => get date \"dd MMM yyyy\"\n\n// Get bottom of transaction table\n@transactionsBottom = get last line containing \".\"\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 125 420 520 620 680 => describe table false \"*Date[dd MMM yyyy]\" Details - #Credit #Balance','2023-01-05 09:51:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10368,'HoaresBank','$source = \"HoaresBank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n$accountName = get line containing \"Account number\" =>  get words after \"Account number\" => take words 1 => get text\n$accountNumber  = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n$statementPeriodTo = get line containing \"Statement date\" => get words after \"Statement date\"\n$periodToText = take words $statementPeriodTo 3 => get text\n$periodTo = take words $statementPeriodTo 3 => get date \"d MMMM yyyy\"\n\n\n$statementPeriod = get line containing \"Last Statement date\" => get words after \"Last Statement date\"\n$periodFromText = take words $statementPeriod 3 => get text\n$periodFrom = take words $statementPeriod 3 => get date \"d MMMMM yyyy\"\n\n$openingBalance = get line containing \"Brought forward\" => take last words 1 => get decimal\n//$closingBalance = get line containing \"C. Hoare & Co. is covered\" => top => get line above => take last words 1 => get decimal\n$closingBalance = get last line containing \"C. Hoare & Co. is covered\" => top => get line above => take last words 1 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line containing \"Date Type Particulars\" => bottom => get line below\n//@transactionBottom = get line containing \"C. Hoare & Co. is covered\" => top => get line above\n@transactionBottom = get last line containing \"C. Hoare & Co. is covered\" => top => get line above\n\ndelete all lines containing \"Brought forward\"\n\nignore header above 522\nignore footer below 102\n\ngo to page 1\n\n$transactions = get multi page table @transactionsTop @transactionBottom 40 86 120 350 400 472 550 => describe table false \"*Date[dd MMM yy]\" TransactionType Details #Debit #Credit #Balance','2024-03-11 10:52:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10369,'CaterAllen_Reserve','$source = \"CaterAllen_Reserve\"\n\nset negative marker \"-\"\n\n// Get account Name\n$accountName = get line starting \"Account Name:\" => get words after \"Account Name:\" => take words 4 => get text\n\n// Get account Number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get period From/To\n@periodText = get line starting \"Date Description Payments\" => top => get line above\n$periodFrom = take last words @periodText 7 => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = take last words @periodText 3 => get date \"d MMMM yyyy\"\n\n@transactionsTop = get line starting \"Date Description Payments(£) Receipts(£)\" => bottom => get line below => bottom => get line below\n\n$openingBalance = get line containing \"Balance brought forward\" => take last words 1 => get decimal\n$closingBalance = get line containing \"Balance carried forward\" => take last words 1 => get decimal\n\n@transactionsBottom = get last line containing \"Balance carried forward\" => top => get line above\ngo to page 1\ndelete all lines starting \"Date Description Payments(£) Receipts(£)\"\nignore header above 740\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 120 350 450 530 580 => describe table false \"*Date[dd MMMM yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 120 350 438 500 580 => describe table false \"*Date[dd MMMM yyyy]\" Details #Debit #Credit #Balance','2024-04-30 08:21:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10370,'TheBankOfCommerce','$source = \"TheBankOfCommerce\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete tiny words\ndelete white words\n\n// Get account number\n$accountNumber = get line containing \"Acct:\" => get words after \"Acct:\" => take words 1 => get text\n\n// Get account name\n$accountName = get line containing \"Acct:\" => take last words 4 => get text\n\n// Get balances and periods panel\n@panelTop = get line containing \"Beginning Balance\" => top\n@panelBottom = get line containing \"Ending Balance\" => bottom\n@panelWords = get text in box @panelTop @panelBottom 45 500\n\n$periodFrom = get words after @panelWords \"Beginning Balance\" => take words 1 => get date \"M/d/yy\"\n\n$openingBalance = skip words @panelWords 3 => get words before \"Deposits / Misc\" => get decimal\n\n$periodTo = get words after @panelWords \"Ending Balance\" => take words 1 => get date \"M/d/yy\"\n\n$closingBalance = get words after @panelWords \"Ending Balance\" => skip words 1 => get decimal\n\n// header and footer discards\nignore header above 614\nignore footer below 17\n\ngo to page 1\n\n// Get start & end of Credits\n@CreditsTop = get line starting \"Date Deposits Activity\" => if not found then blank => bottom => get line below\n@CreditsBottom = get line containing \"Other Debits and Withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of Debits\n@DebitsTop = get line starting \"Date Withdrawals Activity\" => if not found then blank => bottom => get line below\n@DebitsBottom = get line containing \"Daily Balance Summary\" => if not found then blank => top => get line above\n\n// Get start & end of cheques table\n@chequeTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"indicates break in check number\" => if not found then blank => top => get line above\n\n// Remove Checks when read in Debits already\ngo to page 1\n@RemovechequeTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom\n@Removechequebottom = get line containing \"indicates break in check number\" => if not found then blank => bottom\n\n// non transactional rows discards\ndelete all lines containing \"Date Deposits Activity\"\ndelete all lines containing \"Date Withdrawals Activity\"\ndelete all lines containing \"Date Check No Amount\"\ndelete all lines starting \"Deposits and Other Credits\"\ndelete all lines starting \"Other Debits and Withdrawals\"\ndelete all lines starting \"Checks\"\ndelete all lines containing \"indicates a break in check\"\ndelete all lines starting \"Images\"\n\n// reading the transactions\n@CreditsTable = get multi page table @CreditsTop @CreditsBottom 45 85 170 580 => describe table false \"*Date[M/d]\" #Credit Details\n@chequeLeft = get multi page table @chequeTop @chequebottom 45 85 145 223 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n@chequeCenter = get multi page table @chequeTop @chequebottom 223 265 335 401 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 401 440 515 580 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n\n$DELETECHECK = get text in box @RemovechequeTop @Removechequebottom 45 580 => get text\ndelete text in box @RemovechequeTop @Removechequebottom 45 580\n\n@DebitsTable = get multi page table @DebitsTop @DebitsBottom 45 85 170 580 => describe table false \"*Date[M/d]\" #Debit Details\n\n// combining the transactions\n$transactions = combine described tables @CreditsTable @DebitsTable @chequeLeft @chequeCenter @chequeRight','2023-01-05 09:51:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10371,'StifelBank','$source = \"StifelBank\"\n\ngo to page 3\n$accountName = get line containing \"Statement Ending\" => bottom => get line below => take words 2 => get text\n$accountNumber  = get line containing \"Customer Number\"  => get words after \"Customer Number\" => take words 1 => get text\n\n$statementPeriod = get line containing \"Statement Ending\" => get words after \"Statement Ending\" => take words 1\n$periodToText = take words $statementPeriod 1 => get text\n$periodTo = take words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n@top = get line starting \"Account Summary\" => bottom\n@bottom = get line starting \"statements@stifelbank.com\" => top\n$data = delete text in box @top @bottom page.left page.right => get text\n\n// Get start & end of all Credits table\n\n@deopositsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@depositaBottom = get line starting \"Electronic Debits\" => if not found then blank => top => get line above\n\n// Get start & end of all Debits table\n@debitsTop = get line starting \"Electronic Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Electronic Credits\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"Electronic Debits\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Date Description Amount\"\n\nignore header above 732\nignore footer below 36\n\n// Read the transactions\n@deposits = get multi page table @deopositsTop @depositaBottom 30 85 515 585 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@debits = get multi page table @debitsTop @debitsBottom 30 85 515 585 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\n\n$transactions = combine described tables @deposits @debits','2023-01-05 09:51:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10372,'AmericanExpress_UK_card','$source = \"AmericanExpress_UK_card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 30\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n@baltop = get line containing \"Standard Balance Due\" => top\n@balbottom = get line containing \"Standard Balance Due\" => top => get line below => bottom\n\ndelete text in box @baltop @balbottom 450 page.right\n\n// Get account name\n$accountName = get line starting \"Private & Confidential\" => bottom => get line below => get text\n\n// Get account number\n@ccnotop = get line containing \"Membership Number\" => bottom\n@accbottom = get line containing \"Membership Number\" => bottom => get line below => bottom\n$accountNumber = get text in box @ccnotop @accbottom 270 385 => get text\n\ngo to page 1\n// Get opening and closing balances\n@baltop = get line starting \"Previous\" => bottom\n@balbottom = get line starting \"Previous\" => bottom => get line below => bottom\n$openingBalance = get text in box @baltop @balbottom 70 140 => get decimal\n$closingBalance = get line starting \"Previous\" => bottom => get line below => get words after \"=\" => get decimal\n\n//@baltop = get line starting \"Previous Balance\" => bottom\n//@balbottom = get line starting \"Previous Balance\" => bottom => get line below => bottom\n//$openingBalance = get text in box @baltop @balbottom 70 140 => get decimal\n//$closingBalance = get line starting \"Previous Balance\" => bottom => get line below => get words after \"=\" => get decimal\n\n// Get period from/to\n//@period = get line starting \"Statement Period\" => skip words 3\n@period = get line containing \"ment Period From\" => get words after \"From\"\n$periodFrom = take words @period 2 => get date \"d MMMM\"\n$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line containing \"Transaction Details Foreign Spend\" => bottom => get line below\n\n// Discard page header\nget last line containing \"Transaction Details Foreign Spend\" => bottom => ignore header above\n\n// Discard page footer\ngo to page 1\nignore footer below 50\n\n// Get end of table\n@transactionsBottom = get last line starting \"Total new spend\" => top => get line above\n\n// Get table withdrwal\n@withdrawTop = get line starting \"Cash Withdrawals for\" => if not found then blank => bottom => get line below\n@withdrawBottom = get line starting \"Total Cash Withdrawals for\" => if not found then blank => top => get line above\n\n// Get table 2\n@transactionsTop2 = get line starting \"OTHER ACCOUNT TRANSACTIONS\" => if not found then blank => bottom => get line below\n@transactionsBottom2 = get last line starting \"Total of other account transactions\"  => if not found then blank => top => get line above\n\n// Discard info on page 1\ngo to page 1\nget line starting \"American Express Services Europe Limited has its registered office\" => top => delete text in box 0 page.left page.right\n\n// Discard info on page 2\ngo to page 2\nget line starting \"How you can pay your statement\" => top => delete text in box 0 page.left page.right\n\n// Discard unwanted text\ndelete all lines starting \"Transaction Process\"\ndelete all lines starting \"Date Date Transaction Details\"\ndelete all lines containing \"Transaction Details Foreign Spend\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"New Transactions for\"\ndelete all lines starting \"Total new spend\"\ndelete all lines starting \"OTHER ACCOUNT TRANSACTIONS\"\ndelete all lines starting \"Total of other account transactions\"\ndelete all lines starting \"Total debits for\"\ndelete all lines starting \"Cash Withdrawals\"\ndelete all lines starting \"Card Number xxxx-\"\ndelete all lines starting \"Total Cash Withdrawals\"\n\n// Read the transactions\n@transactions = get multi page table @transactionsTop @transactionsBottom 0 50 90 344 475 560 => describe table false - \"*Date[MMM d]\" Details - #Credit\n@transactions2 = get multi page table @transactionsTop2 @transactionsBottom2 0 50 90 344 475 560 => describe table false - \"*Date[MMM d]\" Details - #Credit\n@withdrawtrans = get multi page table @withdrawTop @withdrawBottom 0 50 90 344 475 560 => describe table false - \"*Date[MMM d]\" Details - #Credit\n\n$transactions = combine described tables @transactions @transactions2 @withdrawtrans','2024-04-15 08:05:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10376,'RepublicBank_TransactionActivity','$source = \"RepublicBank_TransactionActivity\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n// Get Account Name\n$accountName = get line containing \"Account:\" => bottom => get line below => take words 4 => get text\n\n// Get Account Number\n$accountNumber  = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get Period\n@statementPeriod = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 3\n$periodFrom = take words @statementPeriod 1 => get date \"M/dd/yy\"\n$periodTo = take last words @statementPeriod 1 => get date \"M/dd/yy\"\n\n//get Opening and Closing Balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance \" => get words after \"Current Balance \" => take words 1 => get decimal\n\n@transactionsTop = get line containing \"Date Description Debits Credits\" => bottom => get line below\n@transactionBottom = get line containing \"Daily Balance\" => top => get line above\n\ndelete all lines starting \"Date Description Debits Credits\"\ndelete all lines containing \"Transaction Activity\"\ndelete all lines containing \"Page:\"\ndelete all lines containing \"Statement Date:\"\ndelete all lines containing \"Primary Account:\"\ndelete all lines starting \"Continued on Next Page\"\n\n$transactions = get multi page table @transactionsTop @transactionBottom 60 85 382 452 525 565 => describe table false \"*Date[M/dd]\" Details #Debit #Credit #Balance','2023-01-10 07:50:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10377,'Popular','$source = \"Popular\"\n\n$periodBufferDays = 10\n$features = \"NO_TRANSACTION_YEAR\"\n\nset negative marker \"-\"\ndelete white words\n\n// Get account name\n$accountname = get text in box 630 585 page.left page.middleX => get text\n\n// Get account number\n$accountnumber = get line containing \"Commercial Checking\" => bottom => get line below => get words after \"Account number\" => get text\n\n// Get Period\n$periodfrom = get line starting \"Last statement:\" => get words after \"statement:\" => take words 3 => get date \"MMMM dd, yyyy\"\n$periodto =  get line starting \"This statement:\" => get words after \"statement:\" => take words 3 => get date \"MMMM dd, yyyy\"\n\n// Get opening and closing balance\n$openingbalance = get line containing \"Beginning balance\" => get words after \"balance\" => get decimal\n@getlast = get last line starting \"Date Description Additions Subtractions Balance\" => bottom => get line below\n$closingbalance = get line containing \"Ending Totals\" => take last words 1 => get decimal\n\n\n// Get start and end of table\ngo to page 1\n@transactionstop = get line starting \"Date Description Additions Subtractions\" => bottom => get line below\n\n@getbottom = get last line starting \"Date Description Additions Subtractions Balance\"\n@transactionsbottom = get line starting \"CHECKS\" => top => get line above\n\ngo to page 1\nignore header above 670\ndelete all lines containing \"Beginning balance\"\ndelete all lines containing \"page\"\ndelete all lines starting \"Thank you for banking with Popular\"\ndelete all lines containing \"Ending Totals\"\ndelete all lines starting \"Date Description Additions\"\n\ngo to page 2\n$gettext = get line containing \"\'Preauthorized Wd\" => top => get line above => get text\n\n//Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 110 142 320 300 350 440 520 => describe table false \"*Date[MM-dd]\" Details - #Credit #Debit #Balance','2023-01-17 08:27:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10378,'Marcus_BusinessCard','$source = \"Marcus_BusinessCard\"\n$features = \"CREDIT_CARD\"\n$periodbufferdays = 14\n\n$accountNumber = get line containing \"Card Ending in\" => get words after \"Card Ending in\" => take words 1 => get text\n\n@periodtext = get line containing \"Card Ending in\" => top => get line above\n$periodFrom = take words @periodtext 2 => get date \"MMMM d\"\n$periodTo = take words @periodtext 6 => take last words 3 => get date \"MMMM d, yyyy\"\n\n$accountName = get text in box 125 86 page.left page.middleX => take words 2 => get text\n\n$openingBalance = get line starting \"Previous Balance\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Statement Balance\" => take last words 1 => get decimal\n\n@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\n\nignore header above 670\nignore footer below 45\ndelete all lines starting \"Total payments for this period\"\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"Date Description Amount\"\n\n@transactionsBottom = get line starting \"Total charges, credits and returns\" => top => get line above\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 100 530 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit','2023-01-17 08:30:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10379,'DanskeIE_BookedBalance','$source = \"DanskeIE_BookedBalance\"\n\n$periodBufferDays = 14\n\n// Delete vertical text\ndelete rotated words\n\n// Get account number\n$accountNumber = get line starting \"IBAN:\" => take words 7 => take last words 4 => get text\n\n// Get account name\n$accountName = get line starting \"Account holder:\" => skip words 2 => take words 4 => get text\n\n// Get period from/to\n@period = get line starting \"Period:\"\n$periodFrom = skip words @period 1 => take words 1 => get date \"MMddyyyy\"\n$periodTo = take last words @period 1 => get date \"MMddyyyy\"\n\n// Get opening and closing balances\n@openingBalanceText = get line starting \"Account:\" => get words after \"Balance at:\" => skip words 1\n$openingBalance = get decimal @openingBalanceText\n@closingBalanceText = get line starting \" BIC/SWIFT\" => get words after \"Balance at:\" => skip words 1\n$closingBalance = get decimal @closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Booked and\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Page\" => top => get line above\n\n// Discard page header\nget last line starting \"Booked and\" => bottom => ignore header above\n\ndelete all lines starting \"interest\"\ndelete all lines starting \"date\"\ndelete all lines starting \"Booked and\"\n\n// Discard page footer\nignore footer below 70\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 320 440 580 => describe table false \"*Date[MMddyyyy]\" Details #Credit #Balance','2023-02-02 07:57:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10380,'DBS_Foreign_Current','$source = \"DBS_Foreign_Current\"\n\n@accountnametext = get line containing \"Account Name :\" => get words after \"Account Name :\"\n$accountname = take words @accountnametext 9 => get text\n\n// Get account number\n@accountNumberText = get line containing \"Account Number :\" => get words after \"Account Number :\"\n$accountNumber = take words @accountNumberText 1 => get text\n$periodfrom = get line starting \"From\" => get words after \"From\" => take words 1 => get date \"dd-MMM-yyyy\"\n$periodto = get line starting \"From\" => get words after \"To\" => take words 1 => get date \"dd-MMM-yyyy\"\n\n\n//go to page 1\n@openingbalanceText = get line containing \"Opening Balance :\" => get words after \"Opening Balance :\"\n$openingbalance = take words @openingbalanceText 1 => get text\n@closingbalanceText = get line containing \"Ledger Balance :\" => get words after \"Ledger Balance :\"\n$closingbalance = take words @closingbalanceText 1 => get text\n\n//go to page 1\n@transactionsTop = get line containing \"Trans. Date Value Date Transaction Details Debits\" => bottom => get line below\n@transactionsBottom = get last line starting \"Printed On\" => top => get line above\n\n//ignore header above 640\ndelete all lines starting \"Printed By :\"\ndelete all lines starting \"Printed On :\"\ndelete all lines starting \"Trans. Date Value Date Transaction Details Debits Credits Running Balance\"\ndelete all lines starting \"Account Details\"\ndelete all lines containing \"Total Debit Count\"\ndelete all lines containing \"Total Credit Count\"\ndelete all lines starting \"From\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 145 280 370 470 580 => describe table false \"Date[dd-MMM-yyyy]\" \"ValueDate[dd-MMM-yyyy]\" Details  #Debit #Credit *#Balance','2023-02-02 08:00:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10381,'MetroBankOnline','$source = \"MetroBankOnline\"\n$features = \"NO_OPENING_BALANCE REVERSE_ORDER\"\n$periodBufferDays = \"45\"\n//set negative marker \"-\"\n// Get account name\n$accountName = get line starting \"Account Name:\" => get words between \"Account Name:\" \"Date searched from:\" => get text\n$accountNumber = get line starting \"Account Number:\" => get words between \"Account Number:\" \"Date searched to:\" => get text\n\n$periodTo = get line starting \"Date Value Date Description\" => bottom => get line below => take words 3 => get date \"dd MMM yy\"\n$closingBalance = get line starting \"Date Value Date Description\" => bottom => get line below => take last words 1 => get decimal\n\nget line starting \"Metro Bank PLC is registered in England and\" => top => ignore footer below\n\n@periodFromTop = get last line starting \"Date Value Date Description\" => bottom\n$periodFrom = get text in box @periodFromTop 0 0 80 => take last words 3 => get date \"dd MMM yy\"\n\ngo to page 1\n@transactionsTop = get line starting \"Date Value Date Description\" => bottom => get line below\nget last line starting \"Date Value Date Description\" => bottom\n@transactionsBottom = get line above 0\n\ndelete all lines starting \"Date Value Date Description\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 80 140 330 400 500 560 => describe table false \"*Date[dd MMM yy]\" - Details #Debit[-0,000.00] #Credit[0,000.00] #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 80 140 330 500 560 => describe table false \"*Date[dd MMM yy]\" - Details #Credit[0,000.00] #Balance','2024-09-10 08:18:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10382,'Lloyds/Bank_TransactionReport','$source = \"Lloyds/Bank_TransactionReport\"\n\n$features = \"REVERSE_ORDER\"\n\nset negative marker \"(\"\n\n// Get account name\n$accountName = get line starting \"Account Number\" => get words after \"Currency Code:\" => get words between \"/\"  \"/\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Currency Code:\" => take words 1 => get text\n\n// Get period from/to\n$periodFrom = get line starting \"Reporting Period:\" => get words after \"Reporting Period:\" => take words 1 => get date \"dd MMM yyyy\"\n$periodTo = get line starting \"Reporting Period:\" => get words after \"Reporting Period:\" => take last words 1 => get date \"dd MMM yyyy\"\n\n// Get opening and closing balances\n@BalancesTop = get last line starting \"Start of Report Balance\" => bottom\ngo to page 1\n@BalancesBottom = get line starting \"Start of Report Balance\" => bottom => get line below => bottom\n$closingBalance = get text in box @BalancesTop @BalancesBottom 140 763 => take words 1 => get decimal\n$openingBalance = get text in box @BalancesTop @BalancesBottom 140 763 => get words after \"=\" => get decimal\n\n// Get start & end of Debit Transactions\n@DebitTransactionsTop = get line starting \"Debit Transactions Posting Date\" => if not found then blank => bottom => get line below\n@DebitTransactionsBottom = get line starting \"Total Debits\" => if not found then blank => top => get line above\n\n// Get start & end of Credit Transactions\ngo to page 1\n@CreditTransactionsTop = get line starting \"Credit Transactions Posting Date\" => if not found then blank => bottom => get line below\n@CreditTransactionsBottom = get last line starting \"Transaction and balance information\" => if not found then blank => top => get line above\n\n// non transactional rows discards\ndelete all lines containing \"Total Debits\"\ndelete all lines containing \"Total Credits\"\ndelete all lines starting \"Credit Transactions Posting Date\"\ndelete all lines starting \"Debit Transactions Posting Date\"\n\n// Discard page header and  footer\nignore header above 468\nignore footer below 59\n\n// reading the transactions\n@DebitTransactionsTable = get multi page table @DebitTransactionsTop @DebitTransactionsBottom 15 265 350 510 763 => describe table false Details \"*Date[dd MMM yyyy]\" #Debit TransactionType\n@CreditTransactionsTable = get multi page table @CreditTransactionsTop @CreditTransactionsBottom 15 265 350 510 763 => describe table false Details \"*Date[dd MMM yyyy]\" #Credit TransactionType\n\n// combining the transactions\n$transactions = combine described tables @DebitTransactionsTable @CreditTransactionsTable','2023-03-06 07:57:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10383,'Dragon_PURN','$source = \"Dragon_PURN\"\n$periodBufferDays = 15\n//$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$features = \"NO_OPENING_BALANCE CREDIT_CARD\"\n\n// Get account number\n$accountNumber = get line containing \"PURN =\" => get words after \"PURN =\" => take words 1 => get text\n\n// Get account name\n$accountName = get line containing \"PURN =\" => get words after \"PURN =\" => take words 1 => get text\n\n// Get period from/to\n@period = get line starting \"Transaction Date\" => bottom => get line below\n$periodFrom = take words @period 1 => get date \"dd/MM/yyyy\"\n\n$periodTo = get last line containing \"Statement Date\" => get words after \"Statement Date\" => take words 1 => get date \"dd/MM/yyyy\"\n$closingBalance = get last line starting \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\ngo to page 1\n\n// Get opening balances\n//$openingBalance = 0\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"PURN =\"\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line above 10\n\n// Discard page header\nignore header above 805\n\n// Discard page footer  - because need page no in transaction\n//ignore footer below 50\n\ndelete all lines starting \"interest SEK\"\ndelete all lines starting \"PURN =\"\ndelete all lines starting \"Miniumum Payment Due\"\ndelete all lines starting \"PPI Charged\"\ndelete all lines containing \"Transaction Date Details\"\ndelete all lines starting \"Totals\"\n\n//as per requirement we didn’t deleted  Statement Date, Credit Limit and New Balance\n//delete all lines starting \"Statement Date\"\n//delete all lines starting \"Credit Limit\"\n//delete all lines starting \"New Balance\"\n\n\nset negative marker \"-\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 170 225 363 420 480 562 => describe table false \"*Date[ddMMyyyy]\" Details #Credit #Debit *ChequeNumber\n$transactions = get multi page table @transactionsTop @transactionsBottom 130 225 218 367 363 420 480 => describe table false *ChequeNumber - Details - #Debit #Credit','2023-03-01 10:04:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10384,'USAAfederal','$source = \"USAAfederal\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountName = get line containing \"PAGE \" => bottom => get line below => take words 2 => get text\n$accountNumber  = get line containing \"ACCOUNT NUMBER\"  => bottom => get line below => take words 1 => get text\n\ndelete text in box page.top 535 page.left 395\n$statementPeriod = get line containing \"STATEMENT PERIOD\"  => bottom => get line below => take words 3\n$periodFromText = take words $statementPeriod 1 => get text\n$periodFrom = take words $statementPeriod 1 => get date \"MM/dd/yy\"\n$periodTo =  take last words $statementPeriod 1 => get date \"MM/dd/yy\"\n\n$openingBalance = get line containing \"Please examine immediately\" => top => get line above => take words 1 => get decimal\n$closingBalance = get line containing \"Please examine immediately\" => top => get line above => take last words 1 => get decimal\n\nremove page 2\n\nignore header above 530\ngo to page 1\n$deletebottomrighttext = delete text in box on every page 30 0 514 600\n\n// Get start & end of Check table\ngo to page 1\n@checksTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below\n@checksBottom = get line starting \"OTHER DEBITS\" => if not found then blank => top => get line above\n@checksLeft = get multi page table @checksTop @checksBottom 75 120 172 280 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n@checksRight = get multi page table @checksTop @checksBottom 281 330 400 500 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n\ndelete all lines starting \"DATE..........AMOUNT.TRANSACTION\"\n\n// Removing checks as sometimes the checks table is missing\ngo to page 1\n@RemovechequeTop = get line starting \"CHECKS\" => if not found then blank => bottom\n@Removechequebottom = get line containing \"OTHER DEBITS\" => if not found then blank => top => get line above => bottom\n$DELETEchecks = delete text in box @RemovechequeTop @Removechequebottom 75 500 => get text\n\ndelete all lines starting \"CHECKS\"\ndelete all lines starting \"DATE..CHECK NO\"\n\n// Get start & end of DEPOSITS AND OTHER CREDITS table\ngo to page 1\n@deopositsTop = get line starting \"DEPOSITS AND OTHER CREDITS\" => if not found then blank => bottom => get line below\n@depositsBottom = get line starting \"OTHER DEBITS\" => if not found then blank => top => get line above\n\n// Get start & end of all Debits table\n@debitsTop = get line starting \"OTHER DEBITS\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"ACCOUNT BALANCE SUMMARY\" => if not found then blank => top => get line above\n\ndelete all lines starting \"DEPOSITS AND OTHER CREDITS\"\ndelete all lines containing \"All transactions are subject\"\ndelete all lines containing \"OTHER DEBITS\"\ndelete all lines starting \"FOREIGN TRANSACTION FEES INCURRED\"\ndelete all lines starting \"TRANSACTIONS OCCURRING ON THE\"\ndelete all lines starting \"PERIOD WERE INCLUDED ON\"\n\n// Read the transactions\n@deposits = get multi page table @deopositsTop @depositsBottom 75 125 210 200 527 => describe table false \"*Date[MM/dd]\" #Credit - Details\n@debits = get multi page table @debitsTop @debitsBottom 75 125 210 200 527 => describe table false \"*Date[MM/dd]\" #Debit - Details\n\n$transactions = combine described tables @deposits @checksLeft @checksRight @debits','2023-05-11 08:27:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10385,'UnionBank_WithSummary','$source = \"UnionBank_WithSummary\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountName = get text in box 620 590 page.left page.middleX => take words 3 => get text\n\n$periodFrom = get line containing \"Statement Number:\" => take last words 3 => take words 1 => get date \"M/d/yy\"\n$periodTo = get line containing \"Statement Number:\" => take last words 3 => take last words 1 => get date \"M/d/yy\"\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n@openingBalanceText = get line containing \"Days in statement period\" => bottom => get line below => get words after \"Balance on\"\n@closingBalanceText = get line containing \"Statement Average Ledger\" => top => get line above => get words after \"Balance on\"\n$openingBalance = take last words @openingBalanceText 1 => get decimal\n$closingBalance = take last words @closingBalanceText 1 => get decimal\n\n//Check Table\nignore header above 720\n\n@checkTop = get line starting \"Number Date Reference Amount\" => if not found then blank => bottom => get line below\n//$checkbottom = get line containing \"Payments online and electronic banking\" => top => get line above\n@checkbottom = get line containing \"Number Date Reference Amount\" => if not found then blank => bottom => get break below => get line at\n\n@DcheckTop = get line starting \"Number Date Reference Amount\" => top\n@Dcheckbottom = get line containing \"Payments online and electronic banking\" => top => get line above => top\ndelete all lines starting \"Total\"\ndelete all lines containing \"Checks missing in sequence\"\ndelete all lines containing \"Number Date Reference Amount\"\n\n@checkLeft = get multi page table @checkTop @checkbottom 140 175 212 263 350 => describe table false #ChequeNumber \"*Date[M/d]\" Details #Debit\n@checkright = get multi page table @checkTop @checkbottom 380 425 458 510 590 => describe table false #ChequeNumber \"*Date[M/d]\" Details #Debit\n\ndelete text in box @DcheckTop @Dcheckbottom 0 650\n\ngo to page 1\n//credit table\n@transactionTopCredit = get line starting \"Date Description/Location Reference Amount\" => bottom => get line below\n@transactionBottomCredit = get line starting \"Payments online and electronic banking\" => top => get line above\n\n\ndelete text in box on every page 770 730 page.left page.right\n\n// online debit transactions table\n@transactionTopDebit = get line starting \"Payments online and electronic banking\" => bottom => get line below\n@transactionBottomDebit = get line starting \"Purchases ATM card and Debit\" => top => get line above\n\n// online ATM/debit card transactions table\n@transactionTopDebit2 = get line starting \"Purchases ATM card and Debit\" => bottom => get line below\n//@transactionBottomDebit2 = get last line containing \"Recurring Debit Card Payment\" => top => get line above\n@transactionBottomDebit2 = get line containing \"ATM withdrawals\" => top => get line above\n\n\n// online ATM withdrawls transactions table\n//@transactionTopDebit3 = get line containing \"Recurring Debit Card Payment\" => bottom => get line below\n@transactionTopDebit3 = get line containing \"ATM withdrawals\" => bottom => get line below\nget last line starting \"Date Description/Location Reference Amount\" => bottom\n@transactionBottomDebit3 = get line above 0\n\n\ndelete all lines starting \"Date Description/Location Reference Amount\"\ndelete all lines starting \"Payments online and electronic banking\"\ndelete all lines starting \"Purchases ATM card and Debit\"\ndelete all lines starting \"ATM withdrawals\"\ndelete all lines starting \"Other Withdrawals\"\ndelete all lines containing \"Debit Card Authorization(s)\"\ndelete all lines containing \"your balance available\"\ndelete all lines starting \"debits\"\ndelete all lines starting \"and other debits.\"\ndelete all lines starting \"other debits.\"\ndelete all lines starting \"Overdraft Fee\"\ndelete all lines starting \"Total Overdraft\"\ndelete all lines containing \"Recurring Debit Card Payment\"\n\n\n// reading the transactions\n@credits = get multi page table @transactionTopCredit @transactionBottomCredit 145 182 525 590 => describe table false \"*Date[M/d]\" Details #Credit\n@debits1 = get multi page table @transactionTopDebit @transactionBottomDebit 145 182 525 590 => describe table false \"*Date[M/d]\" Details #Debit\n@debits2 = get multi page table @transactionTopDebit2 @transactionBottomDebit2 145 182 525 590 => describe table false \"*Date[M/d]\" Details #Debit\n@debits3 = get multi page table @transactionTopDebit3 @transactionBottomDebit3 145 182 525 590 => describe table false \"*Date[M/d]\" Details #Debit\n\n// combining the transactions\n//$transactions = combine described tables @credits @debits1 @debits2 @debits3\n$transactions = combine described tables @credits @debits1 @debits2 @debits3 @checkLeft @checkright','2023-07-10 16:13:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10386,'AccountScore','$source = \"AccountScore\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n$periodbufferdays = 15\n\n//$accountName = get line containing \"Customer Name:\" => get words after \"Customer Name:\" => take words 2 => get text\n\n// regex to commented because dd/mm in TO-date swap automatically on SR while correct in VB\n//$periodToRegex = \".*-(.*)\"\n//$inputDateFormat = \"dd/MM/yyyy\"\n//@stPeriodtop = get line containing \"Transaction Date\" => get words after \"Transaction Date\" => top\n//@stPeriodbottom = get line containing \"Transaction Date\" => get words after \"Transaction Date\" => bottom\n//@statementPeriod = get text in box @stPeriodtop @stPeriodbottom 433 page.right\n//$periodTo = get words after @statementPeriod \"-\" => get date \"dd/MM/yyyy\"\n//$PeriodToText = take last words @statementPeriod 1 => get text\n$periodTo = get last line containing \"Generated on\" => get words after \"Generated on\" => get date \"dd MMMM yyyy\"\ngo to page 1\nignore footer below 30\n\n//$accountNumber = get line containing \"(Open Banking)\" => take words 2 => get text\n$accountNumber = get line containing \"Sub Category Breakdown Credits\" => top => get line above => take words 2 => get text\n//$accountName = get line containing \"(Open Banking)\" => take words 2 => get text\n$accountName = get line containing \"Sub Category Breakdown Credits\" => top => get line above => take words 2 => get text\n\n$closingbalance = get line containing \"Bank Accounts Balance\" => bottom => get line below => take last words 1 => get decimal\n\n@openingtop = get line starting \"Date Description Amount Balance\" => bottom\n@openingbottom = get line starting \"Date Description Amount Balance\" => bottom => get line below => bottom\n//$openingbalance = get text in box @openingtop @openingbottom 520 580 => get decimal\n//$openingbalance = get text in box @openingtop @openingbottom 515 580 => get decimal\n@periodfrombot0 = subtract @openingbottom 10\n$openingbalance = get text in box @openingtop @periodfrombot0 515 580 => get decimal\n\n//@periodfrombot = subtract @openingbottom 20\n@periodfrombot = subtract @openingbottom 17\n\n//Get start of table\n@transactionsTop = get line starting \"Date Description Amount Balance\" => bottom => get line below\n@transCoor = get line starting \"Date Description Amount Balance\"\n\n@amountcol = get words after @transCoor \"Date Description\" =>  left\n@amountcol = subtract @amountcol 16\n\n@Desccol = get words after @transCoor \"Date\" =>  left\n@Desccol = subtract @Desccol 4\n\n@balcol = get words after @transCoor \"Date Description\" => take words 1 => right\n@balcol = add @balcol 4\n\n$periodFrom = get text in box @openingtop @periodfrombot  20 @Desccol => get date \"ddMMMMyyyy\"\n\n//Get end of table\n@lastTrns = get last line starting \"Date Description Amount Balance\"\n\ndelete all lines starting \"Page\"\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Full Transaction List\"\nignore header above 785\n//ignore footer below 30\n\n@transactionsBottom = get line above 35\n\n@lastPeriodbottom = bottom @transactionsBottom\n@periodTobottom = get text in box page.top @lastPeriodbottom 20 @Desccol => take last words 1 => bottom\n\n@PeriodTotop = add @periodTobottom 20\n@periodTobottom = subtract @periodTobottom 5\n//$periodTo = get text in box @PeriodTotop @periodTobottom 20 @Desccol => get date \"ddMMMMyyyy\"\n\n\n//Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 @Desccol @amountcol @balcol 580  => describe table false \"Date[ddMMMMyyyy]\" Details #Credit *#Balance\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 8.5 20 @Desccol @amountcol @balcol 580 => describe table false \"Date[ddMMMMyyyy]\" Details #Credit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 7.9 20 @Desccol @amountcol @balcol 580 => describe table false \"Date[ddMMMMyyyy]\" Details #Credit #Balance','2025-05-29 06:49:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10387,'Coutts','$source = \"Coutts\"\n\n// Get account name and number\n$accountNumber = get line containing \"Account No.\" => get words after \"No.\" => take words 1 => get text\n//$accountName = get text in box page.top 493 72 130 => get text\n$accountName = get text in box 545 510 page.left page.middleX => take words 3 => get text\n\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 72\ndelete text in box on every page page.top page.bottom 818 page.right\ndelete all lines containing \"Page\"\n\n//Get periodfrom & periodTo\n//@getperiod = get text in box 465 430 page.left page.right\n//$periodFrom = get words before @getperiod \"to\" => take last words 3 => get date \"dd MMMM yyyy\"\n//$periodTo = get words after @getperiod \"to\" => take words 3 => get date \"dd MMMM yyyy\"\n\n@getperiod = get text in box 465 430 page.left page.middleX\n$periodFrom = get words before @getperiod \"to\" => take words 3 => get date \"dd MMMM yyyy\"\n$periodTo = get words after @getperiod \"to\" => take last words 3 => get date \"dd MMMM yyyy\"\n\n//Get opening & closing balance\ngo to page 1\n$openingbalance = get line containing \"Opening Balance\" => get words after \"Balance\" => take words 1 => get decimal\nignore footer below 60\n\n@gettop = get last line containing \"Date Description and relevant\" => bottom\n@getbottom = get line containing \"Credits &\" => bottom\n$closingBalance = get text in box @gettop @getbottom 765 816 => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Description and relevant calculations\" => bottom => get line below\n\ndelete all lines containing \"Opening Balance\"\n\n@last = get last line containing \"Description and relevant calculations\"\n@transactionsBottom = get line containing \"Credits &\" => bottom => get line below\n\n@getheader =  get last line containing \"Description and relevant calculations\" => bottom\ndelete text in box on every page page.top @getheader page.left page.right\ndelete all lines starting \"Coutts & Co.\"\ndelete all lines starting \"Registered office\"\ndelete all lines starting \"Calls may be\"\ndelete all lines containing \"Credits &\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 72 115 520 620 720 816 => describe table false \"*Date[dd MMM yy]\" Details #Debit #Credit #Balance','2025-01-09 08:36:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10388,'NedBank_Private','$source = \"NedBank_Private\"\n\n//set negative value\nset negative marker \"-\"\n\n//get account name\n$accountname = get text in box 700 665 page.left page.middleX => get text\n\n//get account number\n$accountnumber = get line containing \"Account Number\" => get words after \"Number\" => take words 1 => get text\n\n//get statement periodfrom\n$periodfrom = get line containing \"BROUGHT FORWARD\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n\n//get periodto from given period\ngo to page 1\n$periodto = get line containing \"Date Narrative Debit\" => top => get line above => get words before \"was\" => take last words 1 => get date \"dd-MMM-yyyy\"\n\n\n//get opening balance\n$openingbalance = get line containing \"BROUGHT FORWARD\" => get words after \"FORWARD\" => take words 1 => get decimal\n\n\n//get top of transactions table\ngo to page 1\n@transactionstop = get line containing \"BROUGHT FORWARD\" => bottom => get line below\n\ngo to page 1\n@navigate_to_last = get last line starting \"Date Narrative Debit\"\n@transactionsbottom = get line above 0\n\n\n//footer and remove unwanted lines or texts\n\ndelete all lines starting \"Total\"\ndelete all lines starting \"BROUGHT FORWARD\"\nignore footer below 70\n\n//get closing balance\ngo to page 1\n$closint_top = get last line containing \"Date Narrative\" => bottom\n$closint_top1 = get last line containing \"Date Narrative\" => bottom => get line below => get text\n$closingbalance = get text in box $closint_top page.bottom 500 560 => take last words 1 => get decimal\n\n//ignore header\nignore header above 530\ndelete all lines starting \"Date Narrative\"\n\n\n//get whole transactions\ngo to page 1\n$transactions = get multi page table @transactionstop @transactionsbottom 30 75 360 430 500 560 => describe table false *Date[dd/MM/yyyy] Details #Debit #Credit #Balance','2024-12-11 08:10:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10389,'Monzo_Accountnumber','$source = \"Monzo_Accountnumber\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n\n//$periodFrom = get line containing \"statement\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n//$periodTo = get line containing \"statement\" => bottom => get line below => take last words 1 => get date \"dd/MM/yyyy\"\n\n//go to last page\n//@getlast = get last line containing \"Account number\"\n//$periodFrom = get line containing \"statement\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n\n\n//$accountName = get line containing \"statement\" => bottom => get line below => bottom => get line below => get words before \"£\" => get text\n$accnt_top = get line containing \"statement\" => bottom => get line below => bottom => get line below => top\n$accnt_bottom = get line containing \"statement\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom\n$accountName = get text in box $accnt_top $accnt_bottom page.left page.middleX => get text\n\n\n\n//$accountNumber = get line starting \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n\n$transactionsTop = get line starting \"Date Description\" => bottom => get line below\n@closingtop = top $transactionsTop\n//@infoLast = get text in box @closingtop page.bottom 480 page.right\n@infoLast = get text in box @closingtop page.bottom 470 page.right\n$openingbalance = take words @infoLast 1 => get decimal\n\n@periodToinfoFirst = get text in box @closingtop page.bottom 65 150\n$periodTo = take words @periodToinfoFirst 1 => get date \"dd/MM/yyyy\"\n\n@Bottom = get last line starting \"Date Description\"\n$transactionsBottom = get line starting \"Monzo Bank Limited\" => top => get line above\n\n//@closingbottom = get line starting \"Monzo Bank Limited\" => top\n//$closingbalance = get text in box page.top @closingbottom 480 530 => take last words 1 => get decimal\n\n\ngo to page 1\nget last line starting \"Date Description\"\n//@closing_top = get line starting \"Monzo Bank Limited\" => top => get line above => top => get line above => top => get line above => top\n@closing_top = get line starting \"Monzo Bank Limited\" => top => get line above => top => get line above => top\n@closing_bottom = get line starting \"Monzo Bank Limited\" => top => get line above => bottom\n$closingbalance = get text in box @closing_top @closing_bottom 470 530 => take last words 1 => get decimal\n\n\n//@periodFromtop = get text in box page.top @closingbottom 470 530 => take last words 1 => top => get line above => bottom\n//$periodFrom = get text in box @periodFromtop @closingbottom 65 150 => get date \"dd/MM/yyyy\"\n\n\ngo to page 1\n$date_left = get line starting \"Date Description\" => take words 1 => left => subtract 5\n$date_right = get line starting \"Date Description\" => get words after \"Date\" => left => subtract 4\n//$debit_left = get line starting \"Date Description\" => get words after \"Description\" => left => add 5\n//$debit_left = get line starting \"Date Description\" => get words after \"Description\" => left => subtract 5\n$debit_left = get line starting \"Date Description\" => get words after \"Description\" => left => subtract 13\n$debit_right = get line starting \"Date Description\" => take last words 1 => left => subtract 18\n$balance_right = get line starting \"Date Description\" => take last words 1 => right => add 8\n\ngo to page 1\nget last line starting \"Date Description\"\n//@Periodfrom_top = get line starting \"Monzo Bank Limited\" => top => get line above => top => get line above => top => get line above => top\n@Periodfrom_top = get line starting \"Monzo Bank Limited\" => top => get line above => top => get line above => top\n@Periodfrom_bottom = get line starting \"Monzo Bank Limited\" => top => get line above => bottom\n$periodFrom = get text in box @Periodfrom_top @Periodfrom_bottom 65 150 => take last words 1 => get date \"dd/MM/yyyy\"\n\n//ignore footer below 100\ndelete all lines starting \"Date Description\"\ndelete all lines containing \"Monzo Bank Ltd is authorised\"\ndelete all lines containing \"Authority and the Prudential Regulation\"\ndelete all lines starting \"Monzo Bank Limited (https://monzo.com)\"\n\ndelete all lines starting \"The deposits in this account\"\ndelete all lines starting \"information sheet and exclu\"\ndelete all lines starting \"https://monzo.com/legal/business-account-fscs-information\"\ndelete all lines containing \"For further information about\"\ndelete all lines containing \"FSCS, refer to the FSCS website at\"\n\ndelete all lines starting \"is\"\n\n\ndelete all lines ending \"about the FSCS can be found at\"\ndelete all lines ending \"The information sheet and\"\ndelete all lines ending \"Financial Conduct Authority and the\"\ndelete all lines starting \"(GBP) (GBP)\"\ndelete all lines ending \"Register number is 730427.\"\ndelete all lines ending \"website at https://www.fscs.org.uk.\"\n\n\n\ndelete all lines containing \"The information sheet and exclusion list that provide\"\ndelete all lines ending \"found at\"\n\n\n\n// Read the transactions\n//$transactions = get multi page table $transactionsTop $transactionsBottom 65 150 390 480 475 530 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit - *#Balance\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 19 65 150 390 480 530 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 18.5 65 150 390 480 530 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 18.5 65 150 390 470 530 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance\n\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 18.1 65 150 $debit_left $debit_right 530 => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance\n$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 18.1 $date_left $date_right $debit_left $debit_right $balance_right => describe table false \"Date[dd/MM/yyyy]\" Details #Credit #Balance','2025-02-12 08:13:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10390,'MorganStanley','$source = \"MorganStanley\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n//$periodBufferDays = 10\r\n\r\nset negative marker \"(\"\r\n\r\n//Get period from/to\r\n@period = get line containing \"OPENING CASH, BDP, MMFs\" => top => get line above => get words after \"as of\" => take words 4\r\n$periodFrom = take words @period 1 => get date \"M/dd/yy\"\r\n$periodTo = take last words @period 1 => get date \"M/dd/yy\"\r\n\r\n$openingBalance = get line containing \"OPENING CASH\" => take last words 2 => take words 1 => get decimal\r\n$closingBalance = get line containing \"CLOSING CASH, BDP, MMFs\" => take last words 2  => take words 1 => get decimal\r\n\r\n//Get account name\r\n//$accountName = get line containing \"Active Assets Account\" => get words after \"Assets Account\" => get text\r\n$accountName = get line containing \"Account Summary\" => top => get line above => take last words 4 => get text\r\n\r\n//Get account number\r\n$accountNumber = get line containing \"Account Summary\" => get words after \"Summary\" => take words 1 => get text\r\n\r\n//Get period from/to\r\n//$periodFrom = get line starting \"Date Date Activity Type\" => bottom => get line below => take words 1 => get date \"M/d\"\r\n//$periodTo = get line containing \"For the Period\" => get words after \"Period\" => take words 3 => take last words 2 => get date \"M-dd, yyyy\"\r\n\r\n// Get start of table\r\n$test = get line starting \"ACTIVITY\"\r\n//$closingBalance = get line containing \"Cash, BDP, MMFs\" => get words after \"MMFs\" => take words 1 => get decimal\r\n@transactionsTop = get line starting \"Date Date Activity Type\" => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsBottom = get line containing \"NET CREDITS/(DEBITS)\" => top => get line above\r\n\r\n//ignore header above 340\r\n$checking = get line starting \"ACTIVITY\"\r\n@gettop = get line starting \"CLIENT STATEMENT\" => top\r\n@getbottom = get line starting \"CASH FLOW ACTIVITY BY DATE\" => bottom\r\ndelete text in box @gettop @getbottom page.left page.right\r\ndelete all lines starting \"Activity Settlement\"\r\ndelete all lines starting \"Date Date Activity Type Description\"\r\ndelete all lines starting \"NET CREDITS/(DEBITS)\"\r\ndelete all lines starting \"CLIENT STATEMENT\"\r\ndelete all lines starting \"Account Detail\"\r\ndelete all lines starting \"Active Assets Account\"\r\ndelete all lines starting \"CASH FLOW ACTIVITY BY DATE\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Date Date Activity Type Description Comments\"\r\n\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 60 105 361 510 700 780 => describe table false \"Date[M/d]\" - Details TransactionType - *#Credit\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 60 105 361 510 700 780 => describe table false \"Date[M/d]\" - TransactionType Details - *#Credit','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10391,'RBS_Ulster_Natwest_Current_Account','$source = \"RBS_Ulster_Natwest_Current_Account\"\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE SKIP_MISSING_CLOSING_BALANCE_CHECK NO_TRANSACTION_YEAR\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n@periodfrom = get line starting \"From To\" => bottom => get line below => take last words 2 => take words 1 => get text\n$periodfrom = get line starting \"From To\" => bottom => get line below => take last words 2 => take words 1 => get date \"dd/MM/yyyy\"\n\n$periodto = get line starting \"From To\" => bottom => get line below => take last words 1 => get date \"dd/MM/yyyy\"\n\n//$accountnumber = get line starting \"Account details\" => bottom => get line below => get words before \"|\" => take last words 1 => get text\n@topAccNum = get line starting \"Account details\" => bottom => get line below => top\n@bottomAccNum = get line starting \"Your transactions\" => top => get line above => bottom\n$accountnumber = get text in box @topAccNum @bottomAccNum page.left 85 => get text\n\n$accountname = get line starting \"From To\" => bottom => get line below => get words before @periodfrom => get text\n\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n@transactionsBottom = get line starting \"©\" => top => get line above\n\n// closing balance required even if SKIP_MISSING_CLOSING_BALANCE_CHECK is used\n$closingbalance = 0\n// REVERSE_ORDER feature swaps opening/closing balance, so opening balace required too\n$openingbalance = 0\n\ndelete all lines starting \"Transaction\"\ndelete all lines starting \"Your transactions\"\ndelete all lines starting \"Date Description\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 100 273 405 482 592 => describe table false \"Date[dd MMM]\" Details TransactionType *#Credit *#Debit\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 95 265 405 482 592 => describe table false \"Date[dd MMM]\" Details TransactionType *#Credit *#Debit','2025-05-22 07:20:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10392,'SalemFiveChecks','$source = \"SalemFiveChecks\"\n\ngo to page 1\n$accountName = get text in box 661 650 55 200 => get text\n$accountNumberText = get line starting \"Account Type Account Number Ending Balance\" => bottom => get line below => skip words 3\n$accountNumber = take words $accountNumberText 1 => get text\n\n@acctop = get line starting \"Date Description Amount\" => bottom\n@accbottom = get line starting \"Other Credits\" => top\n\n$accdetails = get text in box @acctop @accbottom 30 345\n\n$PeriodFrom = get words before $accdetails \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\n\n$PeriodTo =  get words before $accdetails \"Ending Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n\n$closingBalance = take last words $accdetails 1 => get decimal\n\nremove page 2\n// Get start & end of credits table\n\n@creditsTop = get line starting \"Other Credits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Other Debits\" => if not found then blank => top => get line above\n\n// Get start & end of debits table\n\n@debitsTop = get line starting \"Other Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n\n// Get start & end of CHECKS\n\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ngo to page 1\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Check Nbr Date\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Savings Account\"\n\ndelete all lines containing \"Indicates skipped check number\"\nignore header above 680\n\ngo to page 1\n\n@credits = get multi page table @creditsTop @creditsBottom 25 85 500 600 => describe table false \"*Date[MM dd yyyy]\" Details #Credit\n\n@debits = get multi page table @debitsTop @debitsBottom 25 85 500 600 => describe table false \"*Date[MM dd yyyy]\" Details #Debit\n\n@checksLeft = get multi page table @checksTop @checksBottom 60 120 190 300 => describe table false ChequeNumber \"*Date[MM dd yyyy]\" #Debit\n\n@checksRight = get multi page table @checksTop @checksBottom 340 420 480 590 => describe table false  ChequeNumber \"*Date[MM dd yyyy]\" #Debit\n\n$transactions = combine described tables @credits  @debits @checksLeft @checksRight','2023-03-06 07:57:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10393,'CREDIT INDUSTRIEL ET COMMERCIAL','$source = \"CREDIT INDUSTRIEL ET COMMERCIAL\"\n\nset culture \"fr-CA\"\n$periodBufferDays = 10\ndelete text in box on every page page.top page.bottom page.left 45 => get text\n\n//Get Account Name\n$accountname = get text in box 680 640 page.left page.right => take words 2 => get text\n$accountNumber = get line starting \"€ C/C Contrat Pro\" => get words after \"N°\" => take words 1 => get text\n\n//Get opening or closing\n$openingbalance =  get line starting \"SOLDE CREDITEUR\" => take last words 1 => get decimal\n$closingbalance =  get last line containing \"SOLDE CREDITEUR AU\" => take last words 1 => get decimal\n\ngo to page 1\n//Get Period from to Period to\n$periodfrom = get line starting \"Date Date valeur\" => bottom => get line below => bottom => get line below => take words 1 =>  get date \"dd/MM/yyyy\"\n$periodto = get line starting \"RELEVE ET INFORMATIONS\" => bottom => get line below => take words 3 => get date \"dd MMM yyyy\"\n\n//Get First Transection\ngo to page 1\n@transactionsTop = get line starting \"SOLDE CREDITEUR\" => bottom => get line below\n\n\n//Get Last Transection\n@transactionsBottom = get line starting \"IBAN :\" => top => get line above => top => get line above\n\ngo to page 1\n//get last line starting \"Date Date valeur\" => bottom => ignore header above\n@deltoptext = get line starting \"CIC PARIS MALESHERBES 48\" => bottom => get line below => get text\ndelete all lines starting \"@deltoptext\"\n@deltoptext1 = get line starting \"RELEVE ET INFORMATIONS BANCAIRES\" => bottom => get line below => get text\ndelete all lines starting \"@deltoptext1\"\nignore header above 750\ndelete all lines starting \"€ C/C Contrat Pro\"\ndelete all lines starting \"Total des mouvements\"\ndelete all lines starting \"Date Date valeur\"\ndelete all lines starting \"RELEVE ET INFORMATIONS BANCAIRES\"\ndelete all lines starting \"<<Suite au verso>>\"\ndelete all lines starting \"Information sur la protection des comptes :\"\ndelete all lines starting \"(GE) : protégé par la Garantie de\"\ndelete all lines starting \"(GD) : protégé par la Garantie des Dépôts\"\ndelete all lines starting \"www.garantiedesdepots.fr\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"CREDIT INDUSTRIEL ET COMMERCIAL\"\ndelete all lines starting \"Crédit Industriel et Commercial\"\ndelete all lines starting \"SOLDE CREDITEUR AU\"\ndelete all lines containing \"Information la des\"\n\nignore footer below 57\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 104 145 390 470 550 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit #Credit','2023-03-06 07:57:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10394,'AIB_Transactions_Statement','$source = \"AIB_Transactions_Statement\"\n\n$features = \"NO_OPENING_BALANCE\"\n\n$periodBufferDays = 7\n\n$accountName = get line starting \"Account Name\" => get words after \"Account Name\" => get text\n\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n\n@transactionsTop = get line starting \"Date Who Description\" => bottom => get line below\n\n$periodFrom = take words @transactionsTop 1 => get date \"ddMMyyyy\"\n\ngo to last page\n@transactionsBottom = get line above 0\n\n@pendingtop_LastPage = get line starting \"Pending\" => top => get line above => if not found then blank => bottom\n$Del_Pendings_LastPage = delete text in box @pendingtop_LastPage page.bottom page.left page.right => get text\n\ngo to page 1\n@pendingtop_PreviousPage = get line starting \"Pending\" => top => get line above => if not found then blank => bottom\n$Del_Pendings_PreviousPage = delete text in box @pendingtop_PreviousPage page.bottom page.left page.right => get text\n\nignore footer below 50\ndelete all lines containing \"Date Who Description\"\ndelete all lines starting \"Pending\"\n\ngo to last page\n@test = get line above 0 => bottom\n$infoLast = get text in box page.top @test 507 570\n\n$closingBalanceText = take last words $infoLast 1 => get text\n$closingBalance = take last words $infoLast 1 => get decimal\n\n$infoLastperiodTo = get text in box page.top @test 25 80\n$periodTo = take last words $infoLastperiodTo 1 => get date \"ddMMyyyy\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 390 444 505 566 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Debit #Credit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 390 507 570 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 390 515 507 570 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit - #Balance','2024-07-03 06:20:57',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10395,'AIB_Transactions_Statement_NoBalances','$source = \"AIB_Transactions_Statement_NoBalances\"\n\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK REVERSE_ORDER\"\n\n$periodBufferDays = 7\n\n// Get account details\n$accountName = get line starting \"Account Name\" => get words after \"Account Name\" => get text\n\n@accountNoTop = get line starting \"Account Name\" => bottom\n@accountNoBottom = get line starting \"Date Description Money Out\" => top => get line above => top\n$accountNumber = get text in box @accountNoTop @accountNoBottom 105 350 => get text\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description Money Out\" => bottom => get line below\n\n// Get period to\n$periodTo = take words @transactionsTop 1 => get date \"ddMMyyyy\"\n\n// Get balances\n$openingbalance = 0\n\n$closingbalance = 0\n\n// Get end of table\n@translast = get last line starting \"Date Description Money Out\"\n@transactionsBottom = get line above 0\n\n// Get period from\n@translastbottom = get last line starting \"Date Description Money Out\" => bottom\n$infoLastperiodTo = get text in box @translastbottom page.bottom 20 90\n$PeriodFrom = take last words $infoLastperiodTo 1 => get date \"ddMMyyyy\"\n\n// discards\nignore footer below 38\ndelete all lines containing \"Date Description Money Out\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 375 525 => describe table false \"*Date[ddMMyyyy]\" Details #Credit','2023-03-30 08:00:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10396,'LloydsBankInternational','$source = \"LloydsBankInternational\"\n$features = \"NO_OPENING_BALANCE\"\n$periodBufferDays = 14\n\n// Discard hidden text\ndelete white words\ndelete tiny words\n\n// Get account name\n@getaccnttop = get line containing \"Your Account\" => bottom\n@getaccntbottom = get line containing \"Your Account\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom\n$accountName = get text in box @getaccnttop @getaccntbottom 0 page.middleX => get text\n\n@extraTextTop1 = get line starting \"Money In\" => top => get line above => top\n@extraTextBottom1 = get line starting \"Money In\" => top => get line above => bottom\n@extraText = get text in box @extraTextTop1 @extraTextBottom1 page.left page.middleX => get text\n\n// Discard address in top left of page 1\n@dropBottom = get line starting \"Money In\" => top\ndelete text in box page.top @dropBottom page.left page.middleX\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n\n// Get period from/to\n@period = get line starting \"Money In\" => top => get line above => take last words 7\n$periodFrom = take words @period 3 => get date \"dd MMMM yyyy\"\n@periodto = get last line starting \"Money In\" => top => get line above => take last words 7\n$periodTo = take last words @periodto 3 => get date \"dd MMMM yyyy\"\n\n// Get opening and closing balances\n$closingBalanceText = get last line starting \"Money Out\" => take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type\" => bottom => get line below\n\n// Discard page header\nget line containing \"Page 1 of\" => bottom => ignore header above\n\n//ignore header above 692\n@AccBottom = get line containing \"Account Number\" => bottom\nignore header above @AccBottom\n\ndelete all lines starting \"(Continued on next page)\"\ndelete all lines containing \"Bill Payments\"\ndelete all lines containing \"Cashpoint\"\ndelete all lines containing \"Fixed Service\"\ndelete all lines containing \"Mobile Payment Out\"\ndelete all lines containing \"TFR Transfer\"\ndelete all lines starting @extraText\ndelete all lines starting \"Money In\"\ndelete all lines starting \"Money Out\"\ndelete all lines starting \"BUSINESS ACCOUNT\"\ndelete all lines containing \"(Address last updated\"\ndelete all lines containing \"Your Transactions\"\ndelete all lines ending \"iption\"\ndelete all lines containing \"iption lance\"\ndelete all lines containing \"lumn\"\ndelete all lines starting \"Date Description Type\"\ndelete all lines starting \"Transaction types\"\ndelete all lines starting \"If you think something is incorrect,\"\ndelete all lines starting \"Account Number\"\ndelete all lines starting \"Lloyds Bank Corporate\"\n\n// Get end of table\n@transactionsBottom = get last line containing \"Prudential Regulation Authority\" => top => get line above => top => get line above\n\n// Discard page footer\nignore footer below 175\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 124 118 270 300 390 470 560 => describe table false \"Date[dd MMM yy]\" - Details TransactionType **#Credit **#Debit #Balance','2024-09-10 08:18:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10397,'FNB_CashflowSummary','$source = \"FNB_CashflowSummary\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 14\n\n// Transactions with CR text are negative\nset negative marker \"Cr\"\n\n// Get account name\n@getacntnamebottom = get line containing \"Cashflow\" => top => get line above => top => get line above => top\n//$accountName = get text in box 720 660 0 400 => take words 5  => get text\n$accountName = get text in box page.top @getacntnamebottom 0 page.middleX => take words 5 => get text\n\n// Get account number\n$accountnumber = get line containing \"ACCOUNT :\" => take last words 1 => get text\n\n// Get Period\n//$periodFrom =  get line containing \"VAT Charged:\" => bottom => get line below => take words 3 => get date \"dd MMMM yyyy\"\n//$periodTo =  get line containing \"VAT Charged:\" => bottom => get line below => take last words 3 => get date \"dd MMMM yyyy\"\n@statementperiodtop = get line containing \"Cashflow\" => top => get line above => top => get line above => top => get line above => top => get line above => top\n@statementperiodbottom = get line containing \"Cashflow\" => top\n@getperiod = get text in box @statementperiodtop @statementperiodbottom page.middleX page.right\n@statementperiod = take last words @getperiod 7\n$periodFrom = take words @statementperiod 3 => get date \"dd MMMM yyyy\"\n$periodTo = take last words @statementperiod 3 => get date \"dd MMMM yyyy\"\n\n\n// Get Opening/Closing balance\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\n\ndelete all lines starting \"Opening Balance\"\ndelete all lines containing \"ACCOUNT:\"\ndelete all lines containing \"Tax Invoice/Statement Number :\"\n\n// Get start of table\n@transactionsTop = get line containing \"Date Description Amount Balance\" => bottom => get line below => bottom => get line below\n\n// Discard page footer\nignore footer below 60\n\ndelete all lines starting \"Date Description Amount Balance\"\n\n// Get bottom of table\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 48 380 460 => describe table false \"*Date[dd MMM]\" Details #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 51 380 460 => describe table false \"*Date[d MMM]\" Details #Credit','2023-05-31 08:31:04',0);
