0 page.right => get text\n//delete text in box @del_up2 480 0 page.right\ndelete text in box @del_up2 @del_down2 0 page.right\n\n\ngo to page 1\n@del_footer1 = get line starting \"Ending balance on\" => top\ndelete text in box @del_footer1 page.bottom 0 page.right\n\n@del_footer2 = get line starting \"Ending balance on\" => top\ndelete text in box @del_footer2 page.bottom 0 page.right\n\n\n\n//detele headers\ngo to page 1\n//@del_upr1 = get line containing \"Account number:\" => bottom => get line below => top\n@del_upr1 = get line containing \"Account number:\" => bottom => get line below => top => get line above => top\ndelete text in box page.top @del_upr1 0 page.right\n\ngo to page 3\n@del_upr2 = get line containing \"Account number:\" => bottom => get line below => top => get line above => top\ndelete text in box page.top @del_upr2 0 page.right\n\n\n\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"Ending balance on\"\ndelete all lines containing \"Wells Fargo Prime Checking\"\ndelete all lines containing \"Totals\"\ndelete all lines containing \"Deposits/\"\ndelete all lines Starting \"Transaction history\"\ndelete all lines containing \"■ Page\"\ndelete all lines starting \"Balance on\"\ndelete all lines containing \"Deposits/Additions\"\ndelete all lines containing \"Withdrawals/Subtractions\"\ndelete all lines containing \"Date Number Description\"\ndelete all lines containing \"Check Deposits/ Withdrawals\"\n\ndelete all lines containing \"Beginning balance on\"\ndelete all lines containing \"Deposits/Credits\"\ndelete all lines containing \"Withdrawals/Debits\"\ndelete all lines containing \"Routing Number (RTN):\"\ndelete all lines containing \"Overdraft Protection\"\ndelete all lines containing \"This account is not currently covered\"\ndelete all lines containing \"visit your Wells Fargo branch.\"\ndelete all lines containing \"Credit Card -\"\ndelete all lines containing \" Page \"\ndelete all lines containing \"For Wir