INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10414,'Santander UK 2','$source = \"Santander UK 2\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\n// Remove unwanted info side bar\ndelete text in box page.top 0 370 page.right\n\n// Get period from/to\n@period = get line \"Your account summary for\" => bottom => get line below\n$periodFrom = take words @period 3 => get date \"d MMM yyyy\"\n$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n\n// Get account name\n$accountName = get line starting \"Account name:\" => skip words 2 => get text\n$accountNumber = get line starting \"Account number:\" => skip words 2 => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Previous statement balance\" => take last words 1 => get decimal\n$closingBalance = get line containing \"Current statement balance\" => take last words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Previous statement balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Current statement balance\" => top => get line above\n\n// Discard page header\ngo to page 1\n//get line \"Date Description Credits Debits Balance\" => bottom => ignore header above\nignore header above 730\n\n// Discard page footer\nignore footer below 40\n\n// Discard unwanted lines\ndelete all lines starting \"Date Description Credits Debits Balance\"\ndelete all lines starting \"Brought forward balance\"\ndelete all lines starting \"Santander UK plc. Registered Office\"\ndelete all lines starting \"www.santander.co.uk. Telephone\"\ndelete all lines starting \"Authority and the Prudential\"\ndelete all lines starting \"website www.fca.org.uk\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 120 355 425 495 600 => describe table false \"*Date[dd MMM]\" Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 117 355 450 438 500 600 => describe table false \"*Date[d MMM]\" Details #Credit - #Debit #Balance','2023-11-20 05:07:34',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10415,'RBSNatWestUlster_AmountsBottomAligned','$source = \"RBSNatWestUlster_AmountsBottomAligned\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\nset negative marker \"OD\"\r\n\r\n// Get account details\r\n@AccountDetailsTop = get line starting \"Account Name Account No\" => bottom\r\n@accountNumberBottom = get line containing \"Account Name Account No\" => bottom => get line below => bottom\r\n@accountNameBottom = get line starting \"Account Name Account No\" => bottom => get line below => bottom => get line below => bottom\r\n\r\n@AccountnoLeft = get line starting \"Account Name Account No\" => get words after \"Account Name\" => take words 1 => left\r\n@AccountnoLeft = subtract @AccountnoLeft 5\r\n\r\n//$accountNumber = get text in box @AccountDetailsTop @accountNumberBottom 200 395 => take words 1 => get text\r\n$accountNumber = get text in box @AccountDetailsTop @accountNumberBottom @AccountnoLeft 395 => take words 1 => get text\r\n$accountName = get text in box @AccountDetailsTop @accountNameBottom 50 200 => get text\r\n\r\n// Get periods & balances\r\n@SummaryPanelBottom = get line containing \"New Balance\" => bottom\r\n@SummaryPanel = get text in box page.top @SummaryPanelBottom page.middleX 550\r\n\r\n$periodFrom = get words after @SummaryPanel \"Period Covered\" => take words 3 => get date \"dd MMM yyyy\"\r\n$periodTo = get words after @SummaryPanel \"Period Covered\" => take words 7 => skip words 4 => get date \"dd MMM yyyy\"\r\n\r\n$openingBalance = get words after @SummaryPanel \"Previous Balance\" => get words before \"Paid In\" => get decimal\r\n$closingBalance = get words after @SummaryPanel \"New Balance\" => get words after \"New Balance\" => get decimal\r\n\r\n// Discards\r\ngo to page 1\r\nignore header above 750\r\nignore footer below 63\r\n\r\ngo to page 1\r\n@DateRight = get line starting \"Date Description Paid In(£)\" => get words after \"Date\" => take words 1 => left => subtract 15\r\n\r\n// Get start & end of the table\r\n@transactionsTop = get line starting \"Date Description Paid In(£)\" => bottom => get line below\r\n@lastpage = get last line starting \"Date Description Paid In(£)\"\r\n@transactionsBottom = get line above 0\r\n\r\n// Discards\r\n@footer01 = get line starting \"Debit interest details\" => top\r\ndelete text in box @footer01 page.bottom 0 page.right => get text\r\n\r\ndelete all lines starting \"Date Description Paid In(£)\"\r\ndelete all lines containing \"BROUGHT FORWARD\"\r\ndelete all lines starting \"Debit interest details\"\r\ndelete all lines starting \"Overdraft Limit\"\r\ndelete all lines starting \"Overdraft Rate\"\r\ndelete all lines starting \"Interest (variable) we currently pay you\"\r\ndelete all lines starting \"We do not pay credit interest on this account\"\r\n\r\n// Footer Discards\r\n@InterestVariableTop = get line starting \"Interest (variable) you currently pay\" => top\r\ndelete text in box @InterestVariableTop page.bottom 0 page.right => get text\r\n\r\n@CurrentInterestRatesTop = get line starting \"The current interest rates for this account\" => top\r\n$CIR_del = delete text in box @CurrentInterestRatesTop page.bottom 0 page.right => get text\r\n\r\n@OverdraftArrangementsTop = get line starting \"Overdraft Arrangements\" => top\r\n$OA_del = delete text in box @OverdraftArrangementsTop page.bottom 0 page.right => get text\r\n\r\ndelete all lines starting \"National Westminster Bank Plc. Registered\"\r\ndelete all lines containing \"Ulster Bank, a business name of National\"\r\ndelete all lines containing \"Authorised by the Prudential Regulation Authority and regulated\"\r\ndelete all lines starting \"Registered Office:\"\r\ndelete all lines containing \"The Royal Bank of Scotland International\"\r\ndelete all lines containing \"Regulated by the Jersey Financial Services Commission\"\r\n\r\n// Reading the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 108 95 348 398 455 542 => describe table false \"Date[dd MMM]\" - Details #Credit #Debit **#Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 @DateRight 95 340 396.5 455 542 => describe table false \"Date[dd MMM]\" - Details #Credit #Debit **#Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10416,'NABBank_TransactionListing','$source = \"NABBank_TransactionListing\"\r\n\r\nset negative marker \"DR\"\r\n\r\ndelete white words\r\n// Get Account Name\r\n$accountName = \"Anonymous\"\r\n\r\n// Get Opening/Closing Balance\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\r\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\r\n\r\n// Get Period From/To\r\n$periodFrom = get line containing \"Transaction Listing starts\" => get words after \"Transaction Listing starts\" => take words 3 => get date \"dd MMMM yyyy\"\r\n//$periodTo = get line containing \"Transaction Listing ends\" => get words after \"Transaction Listing ends\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodTo = get line containing \"Transaction Listing ends\" => get words after \"Transaction Listing ends\" => get date \"dd MMMM yyyy\"\r\n\r\n// Dynamic co-ordinate\r\n@detailsRight = get line containing \"Date Particulars Debits Credits\" => get words before \"Credits\" => take last words 1 => left => add 10\r\n@debitsLeft = get line containing \"Date Particulars Debits Credits\" => get words before \"Credits\" => take last words 1 => left => subtract 8\r\n\r\n// Get Account Number\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n\r\nget line starting \"Important\" => top => ignore footer below\r\n\r\ngo to page 1\r\n//get transaction top/bottom\r\n@transactionsTop = get line containing \"Date Particulars Debits\" => bottom => get line below\r\n@lastTranpage = get last line containing \"Date Particulars Debits\"\r\n@transactionsBottom = get line above 0\r\n\r\ngo to page 1\r\ndelete all lines starting \"Transaction Details\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Date Particulars Debits\"\r\n\r\n//Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 361 338 408 492 580 => describe table false \"Date[dd MMM yy]\" Details - *#Debit *#Credit #Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 @detailsRight @debitsLeft 410 492 580 => describe table false \"Date[dd MMM yy]\" Details - *#Debit *#Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10417,'ANZ_BusinessCard','$source = \"ANZ_BusinessCard\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\n\ndelete rotated words\ndelete tiny words\n\n// Transactions with CR text are negative\nset negative marker \"CR\"\n\n// Get statement period\n@statementPeriod = get line starting \"STATEMENT PERIOD:\" => get words after \"STATEMENT PERIOD:\"\n$periodFrom = take words @statementPeriod 1 => get date \"dd/MM/yy\"\n$periodTo = take last words @statementPeriod 1 => get date \"dd/MM/yy\"\n\n// Get account number\n@accountNumberText = get line starting \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\"\n$accountNumber = take words @accountNumberText 1 => get text\n\n// Get account name\n@accountSummaryTop = get line starting \"ACCOUNT SUMMARY\" => top\n$accountName = get text in box 700 @accountSummaryTop page.left page.middleX => take words 4 => get text\n\n// Get Opening/Closing Balance\n$openingBalance = get line starting \"Opening Balance\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Closing balance\" => take last words 1 => get decimal\n\n// Get start and end of table\n@transactionsTop = get line starting \"Date Description Amount Default GST\" => bottom => get line below\n\ndelete all lines starting \"Cardholder Name:\"\ndelete all lines starting \"Cardholder Number:\"\ndelete all lines starting \"Spend Cap:\"\ndelete all lines containing \"GST calculation\"\ndelete all lines containing \"**The actual GST amount\"\ndelete all lines containing \"Particulars:\"\ndelete all lines containing \"Bank Branch\"\ndelete all lines containing \"Stamp Signature\"\ndelete all lines starting \"$\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Total GST payable\"\ndelete all lines containing \"Sub-total\"\n\n@transactionsBottom = get last line containing \"Closing Account Balance\" => top => get line above\n\nget line starting \"* The calculation is an estimate\" => top => ignore footer below\ndelete all lines containing \"Account Number:\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines starting \"ACCOUNT NUMBER:\"\ndelete all lines starting \"ANZ BUSINESS\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 90 350 410 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit','2023-06-16 07:42:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10418,'ServisFirstBank','$source = \"ServisFirstBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodbufferdays = 14\n\n// Get Account Name\n$accountName = get text in box 630 590 page.left page.middleX => take words 4 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1  => get text\n\n// Get Period From/To\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n// Get Opening/Closing\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n// Get start & end of cheques table\n@chequeTop = get line containing \"Date Check No Amount\" => if not found then blank => bottom =>  get line below\n@chequebottom = get line containing \"Indicates Serial Number Out of Sequence\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 75 120 168 225 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n@chequeMiddle = get multi page table @chequeTop @chequebottom 225 268 315 375 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 372 415 465 520 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n\n@gettop =  get line containing \"Date Check No Amount\" => top\n@getbottom = get line containing \"Indicates Serial Number Out of Sequence\" => bottom\ndelete text in box @gettop @getbottom page.left page.right\n\nignore header above 542\n\ngo to page 1\n// Get start & end of Credit table\n@creddebitsTop = get line starting \"DEPOSITS AND OTHER CREDITS\" => bottom => get line below\n@creddebitsBottom = get line starting \"DAILY BALANCES\" => top => get line above\n\ndelete all lines containing \"WITHDRAWALS AND DEBITS\"\ndelete all lines containing \"DEPOSITS AND OTHER CREDITS\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"CHECKS\"\ndelete all lines containing \"Date Check No Amount\"\ndelete all lines containing \"(Continued)\"\ndelete all lines containing \"NOTICE:\"\ndelete all lines containing \"IMPORTANT INFORMATION\"\ndelete all lines containing \"MEMBER FDIC\"\n\n// reading the transactions\n@creddebits = get multi page table @creddebitsTop @creddebitsBottom 75 120 350 410 => describe table false \"*Date[M/dd]\" Details #Credit\n\n// combining the transactions\n$transactions = combine described tables @creddebits @chequeLeft @chequeMiddle @chequeRight','2023-06-22 08:34:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10419,'CentralStateBank','$source = \"CentralStateBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\ndelete white words\ndelete tiny words\n\n$accountName = get text in box 690 625 0 page.middleX => get text\n$accountnumber = get line starting \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => get text\n\n@openingbalanceTop = get line starting \"PREVIOUS STATEMENT BALANCE AS OF\" => top\n@openingbalanceBottom = get line starting \"PREVIOUS STATEMENT BALANCE AS OF\" => bottom\n$openingbalance = get text in box @openingbalanceTop @openingbalanceBottom 435 page.right => get decimal\n\n@closingbalanceTop = get line starting \"CURRENT STATEMENT BALANCE AS OF\" => top\n@closingbalanceBottom = get line starting \"CURRENT STATEMENT BALANCE AS OF\" => bottom\n$closingbalance = get text in box @closingbalanceTop @closingbalanceBottom 435 page.right => get decimal\n\n$periodfrom = get line starting \"PREVIOUS STATEMENT BALANCE AS OF\" => get words after \"PREVIOUS STATEMENT BALANCE AS OF\" => get words before \"..\" => get date \"MM/dd/yy\"\n$periodto = get line starting \"CURRENT STATEMENT BALANCE AS OF\" => get words after \"CURRENT STATEMENT BALANCE AS OF\" => get words before \"..\" => get date \"MM/dd/yy\"\n\ngo to page 1\n@ChecksTop = get line starting \"SERIAL DATE AMOUNT\" => bottom => get line below\n@ChecksBottom = get line starting \"DATE DESCRIPTION DEBITS CREDITS\" => top => get line above => top => get line above\n\ngo to page 1\n@DebitCreditTop = get line starting \"DATE DESCRIPTION DEBITS CREDITS\" => bottom => get line below\n@DebitCreditBottom = get line containing \"BALANCE BY DATE\" => top => get line above\n\nignore header above 625\ndelete all lines starting \"SERIAL DATE AMOUNT\"\ndelete all lines starting \"CHECK TRANSACTIONS\"\ndelete all lines starting \"DATE DESCRIPTION DEBITS CREDITS\"\ndelete all lines starting \"CHECKING ACCOUNT TRANSACTIONS\"\n\n@checksTransactionsLeft = get multi page table @ChecksTop @ChecksBottom 105 155 195 290 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@checksTransactionsRight = get multi page table @ChecksTop @ChecksBottom  295 345 385 470 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@DebitCreditTransactions = get multi page table @DebitCreditTop @DebitCreditBottom 105 158 341 403 500 => describe table false \"*Date[MM/dd]\" Details #Debit #Credit\n\n$transactions = combine described tables @DebitCreditTransactions @checksTransactionsLeft @checksTransactionsRight','2023-06-22 08:34:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10420,'Revolut_IBAN 2','$source = \"Revolut_IBAN 2\"\n\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n\n// get statement Period\n@getperiod = get line starting \"Transaction\" => bottom => get line below => take last words 7\n$periodfrom = take words @getperiod 3 => get date \"MMM d, yyyy\"\n$periodto = take last words @getperiod 3 => get date \"MMM d, yyyy\"\n\n// get account name\n@accntnametop = get line starting \"Transaction\" => bottom\n@accntnamebottom = get line starting \"IBAN\" => top => get line above => top\n$accountname = get text in box @accntnametop @accntnamebottom 30 page.middleX => get text\n\n\n// get account number\n//$accountnumber = get last line starting \"IBAN\" => get words after \"IBAN\" => take words 2  => take last words 1 => get text\n$accountnumber = get line containing \"IBAN\" => top => get line above => take words 1 => get text\n\n\ndelete all lines starting \"date\"\n\ngo to page 1\n// get closing balance\n@closingtop = get line containing \"Paid out Paid in\" => bottom\n@closingbottom = get line containing \"Paid out Paid in\" => bottom => get line below => bottom => get line below => top\n$closingbalance = get text in box @closingtop @closingbottom 512 580 => take words 1 => get decimal\n\n\ngo to page 1\n@transactiontop = get line containing \"Paid out Paid in\" => bottom => get line below\n@transactionbottom = get last line containing \"©\" => top => get line above\n\nignore footer below 75\ndelete all lines starting \"Completed date Reference\"\ndelete all lines starting \"FX Rate\"\ndelete all lines starting \"Fee\"\ndelete all lines starting \"FX\"\n\n$transactions = get multi page table @transactiontop @transactionbottom 30 90 398 458 512 590 => describe table false \"*Date[MMM d, yyyy]\" Details #Debit #Credit #Balance','2023-06-22 08:34:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10421,'FirstUnitedBank','$source = \"FirstUnitedBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodbufferdays = 14\n\ndelete rotated words\n\n// non transactional page discards\nremove page 2\n\ngo to page 1\n// Get Account Name\n$accountName = get text in box 615 590 page.left page.middleX => take words 5 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1  => get text\n\n// Get Period From/To\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n// Get Opening/Closing\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n@DateRight = get line containing \"Date Description Amount\" => get words before \"Description\" => right => add 3\n\n// Get start & end of cheques table\n@chequeTop = get line containing \"Date Check Number Amount\" => if not found then blank => bottom =>  get line below\n\ngo to page 1\n@gettopDailyB =  get line containing \"Daily Balance Summary\" => bottom\n$d3 = delete text in box @gettopDailyB 0 page.left page.right => get text\n\ndelete all lines containing \"Denotes skip in check numbers\"\n//delete all lines containing \"Checks\"\ndelete all lines containing \"Date Check Number Amount\"\n\nignore header above 685\n\n@lastChkpage = get last line containing \"Date Check Number Amount\"\n@chequebottom = get line above 0 => top => get line above\n\n$chequeLeft = get multi page table @chequeTop @chequebottom 0 128 230 310 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n$chequeRight = get multi page table @chequeTop @chequebottom 290 380 480 580 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n\ngo to page 1\n// Get start & end of Credit table\n@creddebitsTop = get line starting \"Credit Transactions\" => bottom => get line below\n@creddebitsBottom = get line starting \"Daily Balance Summary\" => top => get line above\n\ngo to page 1\n@gettopChecks =  get line starting \"Checks\" => top\n$d1 = delete text in box @gettopChecks 0 page.left page.right => get text\n\ndelete all lines containing \"Debit Transactions\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Credit Transactions\"\n\n// reading the transactions\n$creddebits = get multi page table @creddebitsTop @creddebitsBottom 0 @DateRight 490 580 => describe table false \"*Date[M/dd]\" Details #Credit\n\n// combining the transactions\n$transactions = combine described tables $creddebits $chequeLeft $chequeRight','2025-10-29 06:16:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10422,'RevolutBusiness_without_accntnbr','$source = \"RevolutBusiness_without_accntnbr\"\n\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n\n\ndelete white words\ndelete rotated words\n\n// get account name & number\ngo to page 1\n$accountname = get line containing \"Account name\" => get words after \"Account name\" => get text\n//$accountnumber = get last line containing \"IBAN\" => get words after \"IBAN\" => take words 1 => get text\n$accountnumber = get line containing \"IBAN\" => get words after \"IBAN\" => take words 3 => get text\n\n// get period from & to\n$periodfrom = get line starting \"Transactions from\" => get words after \"Transactions from\" => take words 3 => get date \"d MMM yyyy\"\n$periodto = get last line starting \"Transactions from\" => get words after \"Transactions from\" => take last words 3 => get date \"d MMM yyyy\"\n\n\n//opening balance\n$openingbalance = 0\n\n\n// get closing balance\ngo to page 1\n@closingtop = get line starting \"Date (UTC) Description\" => bottom\n@closingbottom = get line starting \"Date (UTC) Description\" => bottom => get line below => bottom\n$closingbalance = get text in box @closingtop @closingbottom 510 560 => get decimal\n\n\n// get transection top & bottom\ngo to page 1\n//@transactiontop = get line containing \"Date (UTC) Description Money out\" => bottom => get line below\n@transactiontop = get line containing \"Generated on\" => bottom => get line below\n\n//go to last page\n@transactionbottom = get last line containing \"Report lost or stolen card\" => top => get line above\n\n\ngo to page 1\n@top = get line containing \"Transaction types\" => if not found then blank => bottom\n@bottom = get line containing \"Report lost or stolen card\" => if not found then blank => top\n$Get_delete_text = delete text in box @top @bottom page.left page.right => get text\n\ndelete all lines starting \"Transaction types\"\n\ngo to page 1\n$Del_h1 = get line containing \"Currency\" => if not found then blank => bottom => get line below => get text\ndelete all lines starting $Del_h1\n$Del_h2 = get line containing \"Currency\" => if not found then blank => top => get line above => get text\ndelete all lines starting $Del_h2\n$Del_h3 = get line containing \"Currency\" => if not found then blank => top => get line above => get text\ndelete all lines starting $Del_h3\n$Del_h4 = get line containing \"Currency\" => if not found then blank => top => get line above => get text\ndelete all lines starting $Del_h4\n$Del_h5 = get line containing \"Currency\" => if not found then blank => top => get line above => get text\ndelete all lines starting $Del_h5\n\n\n\ngo to page 1\nignore footer below 80\ndelete all lines starting \"FX Rate\"\ndelete all lines starting \"Fee:\"\ndelete all lines starting \"€\"\ndelete all lines starting \"-€\"\ndelete all lines starting \"Card payments (CAR)\"\ndelete all lines starting \"ATM Withdrawals (ATM)\"\ndelete all lines starting \"Transactions from\"\n//delete all lines starting \"Transaction types\"\ndelete all lines starting \" Ireland IBAN\"\ndelete all lines containing \"Generated on\"\n\n\n\ndelete all lines containing \"Account name Main\"\ndelete all lines starting \"Sort code\"\ndelete all lines starting \"BIC\"\ndelete all lines starting \"Intermediary BIC\"\ndelete all lines starting \"Opening balance\"\ndelete all lines starting \"Money in\"\ndelete all lines starting \"Money out\"\ndelete all lines containing \"Type International\"\ndelete all lines containing \"Type Local\"\ndelete all lines containing \"Currency\"\ndelete all lines containing \"Monthly statement\"\ndelete all lines starting \"Closing balance\"\ndelete all lines starting \"Your funds are held and protected\"\ndelete all lines starting \"Date (UTC) Description\"\ndelete all lines starting \"There were no transactions during this period\"\ndelete all lines starting \"€\"\ndelete all lines starting \"- €\"\ndelete all lines containing \"Routing number\"\ndelete all lines containing \"Wire routing number\"\ndelete all lines starting \"SWIFT / BIC\"\ndelete all lines containing \"This currency account has been\"\ndelete all lines containing \"linked with some of your other currency\"\ndelete all lines containing \"Account name\"\ndelete all lines starting \"0.00 CHF\"\ndelete all lines starting \"to Main to recover negative balance £\"\ndelete all lines starting \"FX rate\"\ndelete all lines starting \"R&D 2\"\ndelete all lines starting \"video ₹\"\ndelete all lines starting \"tech ₹\"\ndelete all lines starting \"Certified copy by Revolut Business\"\ndelete all lines ending \"balance £10.00\"\ndelete all lines containing \"Ireland BIC\"\ndelete all lines starting \"$\"\ndelete all lines starting \"- $\"\ndelete all lines ending \"to recover negative\"\ndelete all lines starting \"₹\"\ndelete all lines starting \"- ₹\"\n\n\ndelete all lines starting \"Balance summary\"\n\n// get Table\n//$transactions = get multi page table @transactiontop @transactionbottom 20 85 330 410 510 580 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance\n//$transactions = get multi page table @transactiontop @transactionbottom 20 87 330 410 510 580 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance\n\n\n$transactions = get multi page table @transactiontop @transactionbottom 20 330 410 514 => describe table false Details *#Debit *#Credit','2025-03-20 07:08:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10423,'RevolutBusiness_with_accntnbr','$source = \"RevolutBusiness_with_accntnbr\"\n\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n//set culture \"en-IE\"\n\n// get account name & number\n\ngo to page 1\n$accountname = get line containing \"Account name\" => get words after \"Account name\" => get text\n$accountnumber = get last line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// get period from & to\n//$periodfrom = get line starting \"Transactions from\" => get words after \"Transactions from\" => take words 3 => get date \"d MMM yyyy\"\n//$periodto = get last line starting \"Transactions from\" => get words after \"Transactions from\" => take last words 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n$periodfrom = get line containing \"ransactions from\" => get words after \"ransactions from\" => take words 3 => get date \"d MMM yyyy\"\n$periodto = get last line containing \"ransactions from\" => get words after \"ransactions from\" => take last words 3 => get date \"d MMM yyyy\"\n@bottom_nav = get line containing \"ransactions from\" => top\n\ngo to page 1\n$Date_rght = get line containing \"Date (UTC) Description\" => get words before \"(UTC)\" => left => subtract 5\n$Date_left = get line containing \"Date (UTC) Description\" => get words before \"Description\" => right => add 5\n//$Description_rght = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 1 => left => subtract 10\n$Description_rght = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 1 => left => subtract 12\n$Description_rght_text = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 1 => get text\n//$Moneyout_rght = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 2 => take last words 1 => right => add 5\n$Moneyout_rght = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 3 => take last words 1 => left => subtract 10\n$Moneyout_rght_check = get line containing \"Date (UTC) Description\" => get words after \"Description\" => take words 3 => take last words 1 => get text\n//$Moneyin_rght = get line containing \"Date (UTC) Description\" => get words before \"Balance\" => take last words 1 => right => add 5\n$Moneyin_rght = get line containing \"Date (UTC) Description\" => get words before \"Balance\" => take last words 1 => right => add 33.5\n$Moneyin_rght_check = get line containing \"Date (UTC) Description\" => get words before \"Balance\" => take last words 1 => get text\n$Balance_rght = get line containing \"Date (UTC) Description\" => get words after \"in\" => take words 1 => right => add 5\n\n\n//opening balance\n$openingbalance = 0\n\ngo to page 1\n@closingtop = get line starting \"Date (UTC) Description\" => bottom\n@closingbottom = get line starting \"Date (UTC) Description\" => bottom => get line below => bottom\n//$closingbalance = get text in box @closingtop @closingbottom 510 560 => get decimal\n$closingbalance = get text in box @closingtop @closingbottom $Moneyin_rght $Balance_rght => get decimal\n\n\ngo to page 1\n//@transactiontop = get line containing \"Date (UTC) Description Money out\" => bottom => get line below\n@transactiontop = get line containing \"Generated on the\" => bottom => get line below\n\n//go to last page\n@transactionbottom = get last line containing \"Report lost or stolen card\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"- £\"\ndelete all lines starting \"£\"\ndelete all lines starting \"$\"\ndelete all lines starting \"- $\"\ndelete all lines starting \"ATM Withdrawals (ATM)\"\ndelete all lines starting \"Invoice 48720\"\ndelete all 