delete all lines starting \"Your funds are held and protected\"\ndelete all lines starting \"Transactions from\"\ndelete all lines starting \"Date (UTC) Description\"\ndelete all lines starting \"There were no transactions during this period\"\ndelete all lines starting \"€\"\ndelete all lines starting \"- €\"\ndelete all lines containing \"Routing number\"\ndelete all lines containing \"Wire routing number\"\ndelete all lines starting \"FX Rate\"\ndelete all lines starting \"Fee:\"\ndelete all lines starting \"SWIFT / BIC\"\ndelete all lines containing \"This currency account has been\"\ndelete all lines containing \"linked with some of your other currency\"\ndelete all lines containing \"Account name\"\n\ndelete all lines starting \"Filtered transactions\"\n\ngo to page 1\n//@bottom_nav = get line containing \"Balance summary\" => top\ndelete text in box page.top @bottom_nav page.left page.middleX\n\ndelete all lines starting \"Balance summary\"\n\n//$transactions = get multi page table @transactiontop @transactionbottom $Date_rght $Date_left $Description_rght $Moneyout_rght $Moneyin_rght $Balance_rght => describe table false \"*Date[D MMM yyyy]\" Details #Debit #Credit #Balance\n//$transactions = get multi page table @transactiontop @transactionbottom $Date_rght $Date_left $Description_rght $Moneyout_rght $Moneyin_rght $Balance_rght => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactiontop @transactionbottom $Date_rght $Description_rght $Moneyout_rght $Moneyin_rght => describe table false Details *#Debit *#Credit','2025-07-24 06:50:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10424,'NatWestBank_ITEM_PARTICULARS','$source = \"NatWestBank_ITEM_PARTICULARS\"\n\nset negative marker \"DR\"\n\n//Get account name and number\n$accountNumber = get line containing \"OPENING BALANCE\" => take words 2 => take last words 1 => get text\n$accountName =  get line containing \"OPENING BALANCE\" => take words 2 => take last words 1 => get text\n\n//Get opening\n$openingBalance = get line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n\n//Get period From\n$periodFrom = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" =>  take words 1 => get date \"ddMMMyy\"\n\ndelete all lines starting \"Customer Service Team\"\nignore footer below 95\n\n//get closing balances\n//@lastbottom = get last line containing \"Bottom of Data\" => top\n@lastbottom = get last line containing \"Bottom of Data\" => top => get line above => bottom\n$closingBalance = get text in box page.top @lastbottom 410 480 => take last words 1 => get decimal\n\n//get period To\n$periodTo = get text in box page.top @lastbottom 353 410 => take last words 1 => get date \"ddMMMyy\"\n\n//Get start of table\ngo to page 1\n@transactionsTop = get line containing \"ITEM PARTICULARS DEBITED CREDITED DATED BALANCE\" => bottom => get line below\n@headertop = top @transactionsTop\ndelete text in box page.top @headertop page.left page.right\n\n@transactionsBottom = get last line containing \"Bottom of Data\" => top => get line above\n\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"ITEM PARTICULARS DEBITED CREDITED DATED BALANCE\"\ndelete all lines containing \"Bottom of Data\"\ndelete all lines containing \"National Westminster Bank Plc,\"\nignore header above 740\n//delete all lines starting \"Customer Service Team\"\n//ignore footer below 95\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 70 230 295 353 397 480 => describe table false Details #Debit #Credit \"Date[ddMMMyy]\" *#Balance','2024-11-12 06:44:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10425,'F&M_Bank','$source = \"F&M_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n@getpage = get line starting \"Y O U R C H E C K S S E Q U E N C E D\"\n@texttop = get line starting \"Y O U R C H E C K S S E Q U E N C E D\" => bottom\n@textbottom = get line starting \"* Indicates break in\" => top\ndelete text in box @texttop @textbottom page.left page.right\n@texttop1 = get last line starting \"Y O U R C H E C K S S E Q U E N C E D\" => bottom\n@textbottom1 = get last line starting \"* Indicates break in\" => top\ndelete text in box @texttop1 @textbottom1 page.left page.right\ndelete all lines starting \"Y O U R C H E C K S S E Q U E N C E D\"\ndelete all lines starting \"* Indicates break in\"\n\ngo to page 1\n// Get account name\n$accountName = get text in box page.top 460 page.left page.middleX => get text\n\n// Get account number\n@accountNumberText = get line starting \"ACCOUNT NUMBER\" => bottom => get line below\n$accountNumber = take words @accountNumberText 1 => get text\n\n// get PeriodFrom and PeriodTo\n@statementPeriod = get line containing \"Statement Dates\" => get words after \"Dates\"\n$PeriodFrom =  take words @statementPeriod 1 => get date \"M/d/yy\"\n$PeriodTo =  take last words @statementPeriod 1 => get date \"M/d/yy\"\n\n// get Opening and Closing Balance\n@OpeningBalanceText = get line containing \"Previous Balance\" => get words after \"Balance\"\n@closingBalanceText = get line containing \"Current Balance\" => get words after \"Balance\"\n$OpeningBalance = take words @OpeningBalanceText 1 => get decimal\n$ClosingBalance = take words @closingBalanceText 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"DATE DESCRIPTION\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"ALTHOUGH YOU RECEIVED A FULL\" => top => get line above\n\n\nignore header above 375\ndelete all lines starting \"DATE DESCRIPTION AMOUNT\"\n\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 10 43 245 385 520 => describe table false \"*Date[M/d]\" Details #Credit #Balance','2023-06-30 15:55:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10426,'USAAFederalClassic','$source = \"USAAFederalClassic\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//Account details & periods\n$accountname = get text in box 700 615 0 160 => take words 4 => get text\n\n@toprightpaneltop = get line containing \"Account Number:\" => top\n@toprightpanelbottom = get line containing \"Statement Period:\" => bottom\n@toprightpanel = get text in box @toprightpaneltop @toprightpanelbottom page.middleX page.right\n\n$accountnumber = get words after @toprightpanel \"Account Number:\" => get words before \"Statement\" => get text\n\n$periodfrom = get words after @toprightpanel \"Statement Period:\" => get words before \"to\" => get date \"MM/dd/yyyy\"\n$periodto = get words after @toprightpanel \"to\" => get date \"MM/dd/yyyy\"\n\n//Balances\n$openingbalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => get decimal\n$closingbalance = get line starting \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\n//Transactions top and bottom\ngo to page 1\n@transactionsTop = get line starting \"Date Description Debits Credits\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\n//discards\ngo to page 1\nignore header above 715\nignore footer below 78\n\ndelete all lines containing \"Beginning Balance\"\ndelete all lines starting \"Date Description Debits Credits\"\ndelete all lines containing \"continued on next page\"\n\ndelete white words\ndelete tiny words\n\n$transactions = get multi page table @transactionsTop @transactionsBottom  30 70 340 400 475 550 => describe table false \"*Date[MM/dd]\" Details #Debit #Credit #Balance','2023-06-30 15:55:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10427,'Discovery_Bank','$source = \"Discovery_Bank\"\n\n$accountNumber = get line containing \"Closing balance on\" => bottom => get line below => take last words 1 => get text\n@acnametop =  get line containing \"INVOICE\" => bottom => get line below => top\n@acnamebottom =  get line containing \"INVOICE\" => bottom => get line below => bottom\n$accountname =  get text in box @acnametop @acnamebottom 20 150 => get text\n\n@custdetail = get line containing \"Your account summary\" => top\ndelete text in box page.top @custdetail 10 250\n\n$periodfrom = get line containing \"Statement period\" => get words after \"Statement period\" => take words 3 => get date \"d MMM yyyy\"\n$periodto = get line containing \"Statement period\" => get words after \"Statement period\" => take last words 3 => get date \"d MMM yyyy\"\n\n@openingtop = get last line containing \"Opening balance on\" => top\n@openingbottom = get last line containing \"Opening balance on\" => bottom\n$openingbalance = get text in box @openingtop @openingbottom 480 600 => get decimal\n\n@closingtop = get last line Starting \"Closing balance on\" => top\n@closingbottom = get last line Starting \"Closing balance on\" => bottom\n$closingbalance = get text in box @closingtop @closingbottom 480 600 => get decimal\n\ngo to page 1\n@transactionstop = get line containing \"Date Type Details Amount Balance\" => bottom => get line below => bottom => get line below\n@transactionsbottom = get last line Starting \"Closing balance\" => top => get line above\n\nignore footer below 90\nignore header above 755\ndelete all lines containing \"Date Type Details Amount Balance\"\n\n//Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 25 90 155 400 480 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Credit #Balance','2023-06-30 15:55:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10428,'Revolut_IBAN_with_accntnbr','$source = \"Revolut_IBAN_with_accntnbr\"\n\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n\n// get statement Period\n@getperiod = get line starting \"Transaction\" => bottom => get line below => take last words 7\n$periodfrom = take words @getperiod 3 => get date \"MMM d, yyyy\"\n$periodto = take last words @getperiod 3 => get date \"MMM d, yyyy\"\n\n// get account name\n@accntnametop = get line starting \"Transaction\" => bottom\n@accntnamebottom = get line starting \"IBAN\" => top => get line above => top\n$accountname = get text in box @accntnametop @accntnamebottom 30 page.middleX => get text\n\n\n// get account number\n$accountnumber = get line containing \"Account number\" => get words after \"number\" => take words 1 => get text\n\n\ndelete all lines starting \"date\"\n\ngo to page 1\n// get closing balance\n@closingtop = get line containing \"Paid out Paid in\" => bottom\n@closingbottom = get line containing \"Paid out Paid in\" => bottom => get line below => bottom => get line below => top\n$closingbalance = get text in box @closingtop @closingbottom 512 580 => take words 1 => get decimal\n\n\ngo to page 1\n@transactiontop = get line containing \"Paid out Paid in\" => bottom => get line below\n@transactionbottom = get last line containing \"©\" => top => get line above\n\nignore footer below 75\ndelete all lines starting \"Completed date Reference\"\ndelete all lines starting \"FX Rate\"\ndelete all lines starting \"Fee\"\ndelete all lines starting \"FX\"\n\n$transactions = get multi page table @transactiontop @transactionbottom 30 90 398 458 512 590 => describe table false \"*Date[MMM d, yyyy]\" Details #Debit #Credit #Balance','2023-06-30 15:56:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10429,'ChaseBank_UK','$source = \"ChaseBank_UK\"\n\n// Get account name\n//@accntbottom = get line containing \"Benjamin\'s\" => top => get line above => top\n@accntbottom = get line containing \"Account statement\" => top => get line above => top\n$accountName = get text in box page.top @accntbottom page.left page.middleX => take words 2 => get text\n\n// Get account number\n@accountNumberText = get line containing \"Account number:\" => get words after \"Account number:\"\n$accountNumber = take words @accountNumberText 1 => get text\n\ndelete all lines starting \"+\"\ndelete all lines starting \"-\"\n\n// get Opening and Closing Balance\n@OpeningBalanceText = get line containing \"Opening balance\" => bottom => get line below\n$OpeningBalance = take words @OpeningBalanceText 1 => get decimal\n$ClosingBalance = take last words @OpeningBalanceText 1 => get decimal\n\n// get PeriodFrom and PeriodTo\n@statementPeriod = get line containing \"Sort code\" => bottom => get line below => take words 7\n$PeriodFrom =  take words @statementPeriod 3 => get date \"d MMMM yyyy\"\n$PeriodTo =  take last words @statementPeriod 3 => get date \"d MMMM yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get last line containing \"Opening balance\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\nignore header above 650\ndelete all lines starting \"Date Transaction\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Opening balance\"\n\n// Read the transactions\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 108 360 480 600 => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Balance','2024-07-25 07:50:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10430,'Capitec_Bank','$source = \"Capitec_Bank\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n$periodBufferDays = 10\n\ndelete rotated words\n\n$accountNumber = get line starting \"Account\" => get words after \"Account\" => take last words 2 => get decimal\n$accountname =  get line containing \"Account Statement\" => bottom => get line below => take words 3 => get text\n\n//go to page 1\n//$periodfrom = get line containing \"From Date:\" => get words after \"From Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n//$periodto =  get line containing \"To Date:\" => get words after \"To Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n//go to page 1\n//$transactionstop = get line containing \"Transaction Description Money In (R)\" => bottom => get line below => bottom => get line below\n//$transactionstop1 = get line containing \"Transaction Description Money In (R)\" => bottom\n//$transactionsbottom1 = get line containing \"capitecbank.co.za\" => top\n//@openingbalanceT = get text in box $transactionstop1 $transactionsbottom1 510 page.right => take words 1 => top\n//@openingbalanceB = get text in box $transactionstop1 $transactionsbottom1 510 page.right => take words 1 => bottom\n//$openingbalance = take last words $transactionstop 2 => get decimal\n//$openingbalance = get text in box @openingbalanceT @openingbalanceB 0 700 => get text\ngo to page 1\n$transactionstop = get line containing \"Description\" => bottom => get line below => bottom => get line below\n$transactionstop1 = get line starting \"Date\" => bottom\n$openingbalanceT = get text in box $transactionstop1 0 510 600 => take words 2 => top\n$openingbalanceB = subtract $openingbalanceT 10\n$openingbalance = get text in box $openingbalanceT $openingbalanceB 510 page.right => get decimal\ngo to page 1\n//$periodfrom = get line containing \"From Date:\" => get words after \"From Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodfrom = get line containing \"Description\" => bottom => get line below => bottom => get line below => take words 2 => take last words 1 => get date \"dd/MM/yyyy\"\ndelete all lines starting \"End\"\ndelete all lines starting \"Transactions not yet\"\ndelete all lines starting \"There are no Unprocessed\"\ndelete all lines starting \"Cheques not yet processed\"\n\n\ndelete all lines containing \"24hr Client Care\"\ndelete all lines containing \"Unique Document No\"\ndelete all lines containing \"Capitec Bank is an authorised\"\n\n@top1 = get line containing \"Description Amount (R)\" => top\n@bottom2 = get line containing \"* Transactions\" => bottom\n$deletexyz = delete text in box @top1 @bottom2 page.left page.right => get text\n\ndelete all lines containing \"Description Amount (R)\"\ndelete all lines starting \"* Transactions\"\nignore footer below 50\n\n\n@closingbottom = get last line starting \"Available Balance\" => top => get line above => bottom\n@closingtop = get text in box page.top @closingbottom 505 page.right => take last words 1 => top\n$closingbalance = get text in box @closingtop @closingbottom 510 page.right => get decimal\n@PeriodtoTop = get text in box page.top @closingbottom 505 page.right => take last words 1 => top => add 1\n$PeriodtoBottom = get text in box @closingtop @closingbottom 510 page.right => bottom => subtract 1\n$periodto = get text in box @PeriodtoTop $PeriodtoBottom 85 145 => get date \"dd/MM/yyyy\"\n@transactionsbottom = get last line starting \"Available Balance\" => top => get line above\n\ndelete all lines containing \"Available Balance\"\n\ngo to page 1\n$Detail_Right = get line containing \"Transaction Description Money In\" => get words after \"Description\" => take words 1 => left => subtract 10\n\n$Amount_Right = get line containing \"Transaction Description Money In\" => get words after \"Out\" => take words 1 => right => add 5\n\n$Balance_Right = get line containing \"Transaction Description Money In\" => get words after \"Money Out (R)\" => take last words 1 => right => add 50\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 145 $Detail_Right $Amount_Right $Balance_Right => describe table false \"Date[dd/MM/yyyy]\" \"tranDate[dd/MM/yyyy]\"  Details #Credit *#Balance\n$transactions = get multi page table $transactionstop @transactionsbottom 20 85 143 $Detail_Right $Amount_Right $Balance_Right => describe table false \"PostingDate[dd/MM/yyyy]\" \"*Date[dd/MM/yyyy]\" Details #Credit #Balance\n','2025-02-12 08:13:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10431,'FirstHorizonBank','$source = \"FirstHorizonBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodbufferdays = 7\r\n\r\ndelete rotated words\r\ndelete white words\r\ndelete tiny words\r\n\r\n// Non-transactional page discards\r\nget last line starting \"PAGE\" => top => ignore footer below\r\ndelete all lines containing \"PAGE\"\r\ndelete all lines containing \"DAILY BALANCE SUMMARY (continued)\"\r\n\r\ngo to page 1\r\n// Get account name\r\n$accountName = get text in box 665 625 page.left page.middleX => take words 3 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"NEW BALANCE\" => get words after \"NEW BALANCE\" => take last words 1 => get decimal\r\n\r\n// Get period from/to\r\n$periodFrom = get line containing \"PERIOD FROM\" => get words after \"PERIOD FROM\" => take words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get line containing \"PERIOD FROM\" => get words after \"THROUGH\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\ngo to page 2\r\n@gettop2 = get line containing \"STATEMENT DATE\" => bottom => subtract 15\r\n@deletebox1 = delete text in box on every page page.top @gettop2 page.left page.right => get text\r\n\r\ndelete all lines containing \"STATEMENT DATE\"\r\ndelete all lines containing \"ACCOUNT NUMBER\"\r\n\r\nget last line starting \"ACCOUNT HISTORY\" => top => ignore header above\r\ndelete all lines starting \"ACCOUNT HISTORY\"\r\n\r\ngo to page 1\r\n@headerTop = get line containing \"DATE DESCRIPTION\" => top\r\n@deleteIstheader  = delete text in box page.top @headerTop 0 page.right => get text\r\n\r\ngo to page 1\r\n@dateLeft = get line starting \"DATE DESCRIPTION\" => get words before \"DESCRIPTION\" => take last words 1 => left => subtract 2\r\n@deleteLeftRotatedWords = delete text in box on every page page.top 0 0 @dateLeft => get text\r\n\r\ngo to page 1\r\n// Get credit/debit table\r\n@transactionsTop = get line starting \"DATE DESCRIPTION DEPOSIT WITHDRAWAL\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"DAILY BALANCE SUMMARY\" => top => get line above\r\n\r\ngo to page 1\r\ndelete all lines starting \"CHECKING ACCOUNT MONTHLY SUMMARY\"\r\ndelete all lines starting \"MINIMUM LEDGER BALANCE:\"\r\ndelete all lines starting \"AVERAGE LEDGER BALANCE:\"\r\ndelete all lines starting \"DEPOSITS:\"\r\ndelete all lines starting \"ITEMS DEPOSITED:\"\r\ndelete all lines starting \"WITHDRAWALS:\"\r\ndelete all lines starting \"CASH DEPOSITED\"\r\ndelete all lines starting \"TRANSACTIONS COUNTED TOWARD LIMIT:\"\r\ndelete all lines starting \"TRANSACTIONS IN EXCESS\"\r\ndelete all lines starting \"CURRENCY DEPOSITED\"\r\nignore footer below 15\r\n\r\ngo to page 1\r\n// Get start and end of cheques table\r\n@chequeTop = get last line containing \"DATE CHECK # AMOUNT\" => if not found then blank => bottom => get line below\r\n@chequebottom = get last line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\r\n\r\n@chequeLeft = get multi page table @chequeTop @chequebottom 55 115 170 230 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n@chequeMiddle = get multi page table @chequeTop @chequebottom 230 290 340 405 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n@chequeRight = get multi page table @chequeTop @chequebottom 408 460 520 578 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n\r\n// Delete last cheques table\r\ngo to page 1\r\n@chksTop = get last line starting \"DATE CHECK # AMOUNT\" => top\r\n@delchecks = delete text in box @chksTop 0 0 page.right => get text\r\n\r\n// Get start and end of first cheques table\r\ngo to page 1\r\n@chequeTop1 = get line containing \"DATE CHECK # AMOUNT\" => if not found then blank => bottom => get line below\r\n@chequebottom1 = get line above 0\r\n\r\n@chequeLeft1 = get multi page table @chequeTop1 @chequebottom1 55 115 170 230 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n@chequeMiddle1 = get multi page table @chequeTop1 @chequebottom1 230 290 340 405 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n@chequeRight1 = get multi page table @chequeTop1 @chequebottom1 408 460 520 578 => describe table false \"*Date[MM/dd]\" #ChequeNumber #Debit\r\n\r\n// Delete first cheques table\r\ngo to page 1\r\n@chksTop_ = get line containing \"DATE CHECK # AMOUNT\" => top\r\n@delchecks1 = delete text in box @chksTop_ 0 0 page.right => get text\r\n\r\ndelete all lines containing \"DATE CHECK # AMOUNT\"\r\ndelete all lines starting \"CHECKING ACCOUNT TRANSACTIONS\"\r\ndelete all lines starting \"DATE DESCRIPTION DEPOSIT WITHDRAWAL\"\r\ndelete all lines containing \"ACCOUNT HISTORY\"\r\ndelete all lines containing \"PAGE\"\r\ndelete all lines starting \"CHECKS PAID SUMMARY\"\r\ndelete all lines containing \"BIZESSENTIALS\"\r\ndelete all lines starting \"PDF\"\r\n\r\n// Read the transactions\r\n@creditdebs = get multi page table @transactionsTop @transactionsBottom 55 105 400 470 530 => describe table false \"*Date[MM/dd]\" Details #Credit #Debit\r\n\r\n// Combine the transactions\r\n$transactions = combine described tables @creditdebs @chequeLeft1 @chequeMiddle1 @chequeRight1 @chequeLeft @chequeMiddle @chequeRight','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10432,'Discovery_Card','$source = \"Discovery_Card\"\n$periodBufferDays = 10\n\n$accountNumber = get line containing \"Closing balance on\" => bottom => get line below => take last words 1 => get text\n@acnametop =  get line containing \"INVOICE\" => bottom => get line below => top\n@acnamebottom =  get line containing \"INVOICE\" => bottom => get line below => bottom\n$accountname =  get text in box @acnametop @acnamebottom 20 150 => get text\n\ngo to page 1\n//$periodfrom = get line containing \"Statement period\" => get words after \"Statement period\" => take words 3 => get date \"d MMM yyyy\"\n$periodto = get line containing \"Statement period\" => get words after \"Statement period\" => take last words 3 => get date \"d MMM yyyy\"\n\n@openingtop = get last line containing \"Opening balance on\" => top\n@openingbottom = get last line containing \"Opening balance on\" => bottom\n$openingbalance = get text in box @openingtop @openingbottom 490 600 => get decimal\n\n@closingtop = get last line Starting \"Closing balance on\" => top\n@closingbottom = get last line Starting \"Closing balance on\" => bottom\n$closingbalance = get text in box @closingtop @closingbottom 490 600 => get decimal\n\ngo to page 1\n@transactionstop = get line containing \"Date Card no. Type Details Amount\" => bottom => get line below => bottom => get line below\n\n@periodfromTop = top @transactionstop\n$periodfrom = get text in box @periodfromTop 100 30 92 => take words 3 => get date \"d MMM yyyy\"\n\n@transactionsbottom = get last line Starting \"Closing balance\" => top => get line above\n\nignore footer below 100\nignore header above 755\ndelete all lines containing \"Date Card no. Type Details Amoun\"\ndelete all lines starting \"Straight Budget\"\n\n//Read the transactions\n//$transactions = get multi page table @transactionstop @transactionsbottom 30 92 210 390 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Credit\n$transactions = get multi page table @transactionstop @transactionsbottom 30 92 207 390 600 => describe table false \"Date[d MMM yyyy]\" TransactionType Details *#Credit','2025-05-06 06:26:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10433,'TDBusinessVisaCardUS','$source = \"TDBusinessVisaCardUS\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\nset negative marker \"CR\"\n\n//Account details & periods\n@toprightpanelbottom = get line containing \"Account Number Ending in:\" => bottom => get line below => bottom\n@toprightpanel = get text in box page.top @toprightpanelbottom page.middleX page.right\n\n$accountname = get words before @toprightpanel \"Account Number Ending in:\" => get text\n$accountNumber = get words after @toprightpanel \"Account Number Ending in:\" => take words 1 => get text\n\n@period = take last words @toprightpanel 7\n$periodFrom = take words @period 3 => get date \"MMMM d, yyyy\"\n$periodTo = take last words @period 3 => get date \"MMMM d, yyyy\"\n\n//Balances\n@balancespaneltop =  get line containing \"Previous Balance\" => top\n@balancespanelbottom =  get last line starting \"New Balance\" => bottom\n@balancespanel = get text in box @balancespaneltop @balancespanelbottom 0 300\n\n$openingbalance = get words after @balancespanel \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => get decimal\n$closingbalance = get words after @balancespanel \"New Balance\" => get decimal\n\n//Transactions top and bottom\n@transactionstop = get line starting \"Activity Date Post Date\" => bottom => get line below\n@transactionsbottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\n//discards\ngo to page 1\nignore header above 722\ndelete all lines containing \"Card Number Ending in\"\ndelete all lines starting \"Activity Date Post Date\"\ndelete all lines containing \"Page\"\ndelete all lines starting \"TD BUSINESS SOLUTIONS VISA® CARD\"\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"Interest Charged\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 125 182 505 492 575 => describe table false \"Date[MMM dd]\" Details - *#Credit','2024-11-21 06:59:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10434,'USAACreditCard','$source = \"USAACreditCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 30\r\n\r\n//Account details\r\n$accountName = get text in box 920 850 page.middleX page.right => take words 4 => get text\r\n$DeleteAccountName = delete text in box 920 850 page.middleX page.right\r\n\r\n@accountNumbertop = get line starting \"Account Number\" => top\r\n@accountNumberbottom = get line starting \"Account Number\" => bottom\r\n$accountNumber = get text in box @accountNumbertop @accountNumberbottom 0 page.middleX => get words after \"Account Number\" => get text\r\n\r\n//Delete extra lines with accountNumber from details\r\n$dltAccount = get text in box @accountNumbertop @accountNumberbottom 0 page.middleX => get words after \"Account Number\" => take words 3 => get text\r\ndelete all lines containing $dltAccount\r\n//Period to\r\n$periodTo = get line containing \"Statement Closing Date\" => get words after \"Statement Closing Date\" => get date \"MM/dd/yy\"\r\n\r\n//Balances\r\n@balancespaneltop =  get line starting \"Previous Balance\" => top\r\n@balancespanelbottom =  get line containing \"New Balance\" => bottom\r\n@balancespanel = get text in box @balancespaneltop @balancespanelbottom 0 page.right\r\n\r\n$openingBalance = get words after @balancespanel \"Previous Balance\" => get words between \"Previous Balance\" \"New Balance\" => get decimal\r\n$closingBalance = get words after @balancespanel \"New Balance\" => get decimal\r\n\r\n//Transactions top\r\n@transactionstop = get line starting \"Trans Date Post Date\" => bottom => get line below\r\n\r\n//Discarding Summary on top of page 2\r\n@SummaryTop = get line starting \"Payment Conditions. Payments\" => top\r\n@SummaryBottom = get line starting \"we confirm receipt of good funds\" => bottom\r\n$DeleteSummary = delete text in box @SummaryTop @SummaryBottom 0 page.right\r\n\r\ndelete all lines starting \"Account Settlements. You cannot\"\r\ndelete all lines starting \"Balance (for example if you dispute\"\r\ndelete all lines containing \"and we must agree in writing. Otherwise, we\"\r\ndelete all lines starting \"paying the remaining unpaid balance or result\"\r\n\r\n//Cardholders name\r\ngo to page 1\r\n@User1 = get line starting \"Total Transactions For\" => get words after \"Total Transactions For\" => get words before \"$\" => get text\r\n@User2 = get last line starting \"Total Transactions For\" => get words after \"Total Transactions For\" => get words before \"$\" => get text\r\n\r\n//Discards\r\ndelete all lines starting \"Transactions\"\r\ndelete all lines starting \"Trans Date Post Date\"\r\ndelete all lines starting \"Total Transactions For\"\r\ndelete all lines starting \"Total Payments And Credits For This Period\"\r\ndelete all lines starting \"Total Fees For This Period\"\r\ndelete all lines containing \"Statement Closing\"\r\ndelete all lines containing \"Account Number\"\r\ndelete all lines containing \"Payment Due\"\r\ndelete all lines containing \"Account Summary\"\r\n\r\nignore footer below 35\r\n//old\r\n//ignore header above 940\r\n//new\r\nignore header above 976\r\n\r\n//Period from\r\ngo to page 1\r\n$periodFrom = get line starting @User1 => bottom => get line below => skip words 1 => take words 1 => get date \"MM/dd\"\r\n\r\n//Transactions bottom\r\n@transactionsbottom = get line starting \"Total Interest For This Period\" => top => get line above\r\n\r\ndelete all lines starting @User1\r\ndelete all lines starting @User2\r\n\r\n//Transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 80 120 250 520 600 => describe table false \"Date[MM/dd]\" TransactionType Details *#Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10435,'MandT_WithSummary','$source = \"MandT_WithSummary\"\n$periodbufferdays = 10\n\n// Get Account Name\n$accountName = get text in box 655 625 page.left page.middleX => take words 3 => get text\n\n// Get Opening/Closing\n$openingBalance = get line containing \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => take words 1 => get decimal\n$closingBalance = get line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => take words 1 => get decimal\n\n// Get Period From/To\n@TopTable = get line containing \"TRANSACTION DESCRIPTION\" => bottom => get line below\n$periodFrom = take words @TopTable 1 => get date \"MM/dd/yyyy\"\n$periodTo = get last line containing \"ENDING BALANCE\" => top => get line above => take words 1 => get date \"MM/dd/yyyy\"\n\n// Get Account Number\n@accountnumtxt = get line containing \"ACCOUNT NUMBER\" => bottom => get line below\n$accountNumber = take words @accountnumtxt 1 => get text\n\ngo to page 1\n@transactionsTop = get line containing \"TRANSACTION DESCRIPTION\" => bottom => get line below\n\nignore header above 565\ndelete all lines containing \"BEGINNING BALANCE\"\ndelete all lines starting \"TRANSACTION DESCRIPTION\"\ndelete all lines starting \"PAGE\"\n\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 75 350 440 520 590 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit #Debit #Balance','2023-07-10 16:13:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10436,'UlsterBankRBSNatWest_AlignedCenter','$source = \"UlsterBankRBSNatWest_AlignedCenter\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n// Get account name and number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\"  => take words 1 => get text\n$accountName = get line starting \"Branch Details\" => top => get line above => get text\n// Get period from/to\n@period = get line containing \"Period\" => take last words 7\n$periodFrom = take words @period 3 => get date \"d MMM yyyy\"\n$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n// Get opening and closing balances\n$openingBalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\n$closingBalance = get line containing \"New Balance\" => take last words 1 => get decimal\n// Detect last header\n@lastPageWithTransactions = get last page number with line starting \"Date Type Description\"\ngo to page @lastPageWithTransactions\n@lastHeaderBottom = get line starting \"Date Type Description\" => bottom\ngo to page 1\n@firstHeader = get line starting \"Date Type Description\"\n@firstHeaderBottom = get line starting \"Date Type Description\" => bottom\n// Get start of table\n@transactionsTop = top @firstHeader => get line below\n// Discard headers and footer\ndelete all lines starting \"BROUGHT FORWARD\"\ndelete all lines starting \"Please note: We do not charge\"\ndelete all lines starting \"a personal current account.\"\ndelete all lines starting \"Dispute resolution for agreed overdrafts\"\ndelete all lines starting \"If you have a problem with\"\ndelete all lines starting \"which we handled your complaint\"\ndelete all lines starting \"up your problem with us first you\"\ndelete all lines starting \"Ombudsman.\"\ndelete all lines starting \"Deposit Guarantee Scheme Information\"\ndelete all lines starting \"Your eligible deposits with\"\ndelete all lines starting \"with one or more of\"\ndelete all lines starting \"An FSCS Information Sheet\"\ndelete all lines starting \"compensation provided\"\n\n//---deleted some more footer line\ndelete all lines containing \"please try to resolve it\"\ndelete all lines containing \"you may be able to complain\"\ndelete all lines containing \"complain to the Ombudsman\"\ndelete all lines containing \"how to contact the\"\n\ndelete all lines containing \"This means that all deposits\"\ndelete all lines containing \"also trades under\"\ndelete all lines containing \"under the same FSCS limit\"\ndelete all lines containing \"An FSCS Information Sheet\"\ndelete all lines containing \"For further information about\"\ndelete all lines starting \"www.FSCS.org.uk\"\ndelete all lines containing \"refer to the website\"\n\ndelete all lines containing \"Your interest rate\"\ndelete all lines containing \"This is based on your balance\"\ndelete all lines containing \"For more information on your product\"\ndelete all lines containing \"Please note:\"\ndelete all lines containing \"on a personal current account\"\ndelete all lines containing \"Please see your\"\n\nignore header above on page range @lastHeaderBottom 2 @lastPageWithTransactions\n//ignore header above on page range @firstHeaderBottom 1 1\n\nget line starting \"©\" => top => ignore footer below\n// Get end of table\ngo to page @lastPageWithTransactions\n@transactionsBottom = get line above 0\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 8 0 107 195 360 425 490 555 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance','2024-05-14 10:48:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10437,'Wells Fargo_Spanish','$source = \"Wells Fargo_Spanish\"\n\n\n$features = \"NO_TRANSACTION_YEAR NO_OPENING_BALANCE\"\n\n// Parse dates in Spanish\nset culture \"es-US\"\n\n@summaryLine = get line containing \"Número de cuenta:\" => get words after \"Número de cuenta:\"\n$accountNumber = take words @summaryLine 1 => get text\n\n// Get period from/to\n//$statementPeriod = get line starting \"Período correspondiente al cargo\" => get words after \"correspondiente al cargo\" => take words 3\n$statementPeriod = get line containing \"Cargo mensual por servicio estándar\" => skip words 4 => take words 3\n$periodFrom = take words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n//$periodTo = get words after $statementPeriod \"-\" => get date \"MM/dd/yyyy\"\n$periodTo = take last words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n\n// Get account name\n$accountName = \"Wells_Fargo_user\"\n\n// Get closing balances\n//$closingBalance =get last line starting \"Saldo final al\" => skip words 4 => get decimal\n@getlast = get last line containing \"Fecha Número\"\n$closing_bottom = get line starting \"Totales\" => if not found then blank => top\n$closingBalance = get text in box page.top $closing_bottom 510 600 => take last words 1 => get decimal\n\n\n// Get start of transactions table\ngo to page 1\n//@transactionsTop = get line starting \"(mes/dia\" => if not found then blank => bottom => get line below\n@transactionsTop = get line starting \"Fecha Número\" => if not found then blank => bottom => get line below => bottom => get line below\n\n\n// Get end of transactions table\n@getlast = get last line containing \"Fecha Número\"\n//@transactionsBottom = get line starting \"Saldo final al\" => if not found then blank => top => get line above\n@transactionsBottom = get line starting \"Totales\" => if not found then blank => top => get line above\n\n\n// Remove unwanted lines that appear in middle of transactions\nignore header above 740\ndelete all lines starting \"Número de cuenta\"\ndelete all lines starting \"Número de cuenta principal:\"\ndelete all lines starting \"Hoja\"\ndelete all lines starting \"Historial de transacciones (continuación)\"\ndelete all lines starting \"Fecha\"\ndelete all lines starting \"(mes/dia\"\ndelete all lines starting \"Date Number Description\"\ndelete all lines containing \"■ Página\"\ndelete all lines containing \"Página\"\nignore footer below 15\n\ndelete all lines containing \"Saldo final al\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 150 380 440 510 600 => describe table false \"*Date[M/d]\" #ChequeNumber Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 100 150 100 380 440 510 600 => describe table false \"*Date[M/d]\" #ChequeNumber - Details #Credit #Debit #Balance','2025-08-20 07:24:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10438,'EBay_FundsSummary','$source = \"EBay_FundsSummary\"\n$features = \"NO_TRANSACTION_YEAR REVERSE_ORDER\"\n$periodbufferdays = 29\n\n// Get Account Name\n$accountname = get line containing \"eBay username\" => bottom => get line below => bottom => get line below => take words 1 => get text\n\n// Get Account Number\n$accountnumber = \"Not_Available\"\n\n// Get Period From/To\n$periodFrom = get line containing \"Date range:\" => get words after \"Date range:\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line containing \"Date range:\" => get words after \"-\" => take words 3 => get date \"dd MMM yyyy\"\n\n// Get Opening/Closing balance\n$closingBalance = get line containing \"Opening funds\" => get words after \"Opening funds\" => skip words 3 => take words 1 => get decimal\n$openingBalance = get line containing \"Closing funds\" => get words after \"Closing funds\" => skip words 4 => take words 1 => get decimal\n\n@transactionsTop = get line containing \"Date ID Details Type\" => bottom => get line below\n@transactionsBottom = get last line containing \"Total payouts:\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"eBay S.à r.l.\"\ndelete all lines starting \"The rest of this page\"\ndelete all lines starting \"Payout details\"\ndelete all lines starting \"Date ID Details Type\"\ndelete all lines starting \"Total other fees:\"\ndelete all lines starting \"Other fees\"\ndelete all lines starting \"Total orders:\"\ndelete all lines containing \"Net total:\"\ndelete all lines containing \"eBay Commerce UK Ltd.\"\ndelete all lines containing \"Total refunds:\"\ndelete all lines containing \"Refunds\"\ndelete all lines containing \"Charges\"\ndelete all lines containing \"Total charges:\"\ndelete all lines starting \"Claims\"\ndelete all lines starting \"Transfers\"\ndelete all lines containing \"Total transfers:\"\ndelete all lines containing \"Total claims:\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 110 182 480 520 570 => describe table false \"Date[dd MMM]\" TransactionType Details - *#Credit','2023-08-04 03:33:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10439,'EBay_WithoutFundsSummary','$source = \"EBay_WithoutFundsSummary\"\r\n//$features = \"NO_TRANSACTION_YEAR REVERSE_ORDER\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodbufferdays = 29\r\n\r\n// Get Account Name\r\n$accountname = get line containing \"eBay username\" => bottom => get line below => take words 2 => get text\r\n\r\n// Get Account Number\r\n$accountnumber = \"Not_Available\"\r\n\r\n// Get Period From/To\r\n$periodFrom = get line containing \"Date range:\" => get words after \"Date range:\" => take words 1 => get date \"dd/MM/yy\"\r\n$periodTo = get line containing \"Date range:\" => get words after \"-\" => take words 1 => get date \"dd/MM/yy\"\r\n\r\n// Get Opening/Closing balance\r\n//$closingBalance = get line containing \"Opening funds\" => take last words 2 => get decimal\r\n//$closingBalance = get line containing \"Opening funds\" => get words after \")\" => take words 1 => get decimal\r\n//$openingBalance = get line containing \"Closing funds\" => take last words 2 => get decimal\r\n$openingBalance = get line containing \"Opening funds\" => get words after \")\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Closing funds\" => take last words 2 => get decimal\r\n@transactionsTop = get line containing \"Date ID Details Type\" => bottom => get line below\r\n//@transactionsBottom = get last line containing \"Total payouts:\" => top => get line above\r\n@transactionsBottom = get last line containing \"Total\" => top => get line above\r\n\r\ngo to page 1\r\n// Remove some unwanted lines\r\ndelete all lines starting \"eBay S.à r.l.\"\r\ndelete all lines starting \"The rest of this page\"\r\ndelete all lines starting \"Payout details\"\r\ndelete all lines starting \"Date ID Details Type\"\r\ndelete all lines starting \"Total other fees:\"\r\ndelete all lines starting \"Other fees\"\r\ndelete all lines starting \"Total orders:\"\r\ndelete all lines containing \"Net total:\"\r\ndelete all lines containing \"eBay Commerce UK Ltd.\"\r\ndelete all lines containing \"Total refunds:\"\r\ndelete all lines containing \"Refunds\"\r\ndelete all lines containing \"Charges\"\r\ndelete all lines containing \"Total charges:\"\r\ndelete all lines starting \"Claims\"\r\ndelete all lines starting \"Transfers\"\r\ndelete all lines containing \"Total transfers:\"\r\ndelete all lines containing \"Total claims:\"\r\n\r\n// Remove Some more unwanted lines\r\ndelete all lines starting \"Postage labels\"\r\ndelete all lines starting \"Date ID Details\"\r\ndelete all lines starting \"Total postage labels:\"\r\ndelete all lines containing \"page is intentionally blank\"\r\ndelete all lines starting \"Adjustment\"\r\ndelete all lines starting \"Total adjustments:\"\r\ndelete all lines starting \"*Exchange rate\"\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 110 182 480 520 570 => describe table false \"Date[dd MMM]\" TransactionType Details - *#Credit\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 110 335 450 500 570 => describe table false \"Date[dd MMM]\" Details TransactionType - *#Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10440,'HSBC_UK_Reverse_centeralign','$source = \"HSBC_UK_Reverse_centeralign\"\n\n$features = \"REVERSE_ORDER\"\n$periodBufferDays = 30\nset negative marker \"DR\"\n\n// Get account number and name\n$accountNumber = get text in box 750 640 0 185 => skip words 1 => take words 1 => get text\n$accountName = get text in box 750 625 0 170 => skip words 4 => take words 2 => get text\n\n\n// Get Period from and opening balance\n//$openingBalance = get line contaning \"Balance brought forward\" => get words after \"Balance brought forward\" => get text\n\n//go to page 1\n//$closingBalance = get line contaning \"Balance carried forward\" => get words after \"Balance brought forward\" => get text\n\n\n// Get Period from and opening balance\n@top = get line containing \"Balance carried\" => top\n@openingBottom = get line containing \"Balance carried\" => bottom\n$periodTo = get text in box @top 100 0 115 => take words 3 => get date \"dd MMM yyyy\"\n//$openingBalance = get text in box @top @openingBottom 480 580 => get decimal\n$openingBalance = get text in box @top @openingBottom 475 580 => get decimal\n\n// Get Period to and closing balance\n@bottom = get line containing \"Balance brought\" => bottom\n@closingbottom = subtract @bottom 5\n@closingtop = get line containing \"Balance brought\" => top\n//$periodFrom = get text in box page.top @bottom 0 115 => take last words 3 => get date \"dd MMM yyyy\"\n//$closingBalance = get text in box @closingtop @closingbottom 480 580 => get decimal\n$closingBalance = get text in box @closingtop @closingbottom 475 580 => get decimal\n\n\ngo to page 1\n//get transactions top and bottom\n@transactionsTop = get line containing \"Balance carried\" => bottom => get line below\n@transactionsBottom = get line containing \"Balance brought\" => top => get line above\n\ngo to page 1\n$Paidout_left = get line containing \"Description Paid \" => get words after \"Description\" => take words 1 => left => subtract 10\n$Paidin_left = get line containing \"Description Paid \" => get words before \"in\" => take last words 1 => left => subtract 10\n$Balance_left = get line containing \"Description Paid \" => take last words 1 => left => subtract 25\n$Balance_rihgt = get line containing \"Description Paid \" => take last words 1 => right => add 15\n\n\ngo to page 1\n$del = get line containing \"© Copyright HSBC Group\" => top => get line above => top\n$del_text = delete text in box $del page.bottom page.left page.right => get text\ndelete all lines containing \"https://online-banking.business\"\ndelete all lines starting \"Last updated\"\n\n//get periodfrom\ngo to page 1\n@nav_bottom = get last line containing \"Description Paid\" => bottom\n//$periodFrom = get text in box page.top @nav_bottom 0 115 => take last words 3 => get text\n$periodFrom = get text in box @nav_bottom page.bottom 0 102 => take last words 3 => get date \"dd MMM yyyy\"\ndelete all lines containing \"Balance brought\"\n\n\ngo to page 1\n$del_header = get line containing \"Balance carried\" => top => get line above => get text\ndelete all lines ending $del_header\n\n\n//ignore header above 790\n//ignore header above 800\nignore header above 822\ndelete all lines containing \"Description Paid out\"\n\ndelete all lines containing \"Balance carried\"\n//delete all lines containing \"Balance brought\"\ndelete all lines containing \"Recent transactions\"\ndelete all lines containing \"Description Paid \"\ndelete all lines starting \"Date Type Description Paid\"\ndelete all lines starting \"Last updated\"\ndelete all lines ending \"Recent transactions\"\n\n//ignore footer below 25\ndelete all lines containing \"Balance brought\"\ndelete all lines starting \"© Copyright HSBC Group\"\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 8 0 100 140 320 385 455 548 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Debit #Credit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 8 0 100 140 $Paidout_left $Paidin_left $Balance_left $Balance_rihgt => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Debit #Credit #Balance','2025-05-06 06:26:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10441,'RCB_Bank','$source = \"RCB_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 10\n\nset negative marker \"CR\"\n\ndelete text in box page.top page.bottom page.left 30\n\n//Get left panel area\n@panelTop = get line containing \"Credit card statement\" => bottom\n@panelBottom = get line containing \"Account Number\" => bottom\n\n// Get account name and number\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => take last words 1 => get text\n@getaccountNumber = get line containing \"Account Number\" => bottom => get line below => take last words 1 => get text\ndelete all lines starting @getaccountNumber\n$accountName = get text in box @panelTop @panelBottom page.left page.middleX => get text\n\n$periodto = get line starting \"DATE OF\" => top => get line above => take words 1 => get date \"dd/MM/yyyy\"\n$periodfrom = get line starting \"TRANS POST\" => bottom => get line below => take words 2 => take last words 1 => get date \"ddMM\"\n\ngo to page 1\n$OpeningBalance = get line containing \"PREVIOUS BALANCE\" => bottom => get line below => take words 1 => get text\n$ClosingBalance = get line containing \"PREVIOUS BALANCE\" => bottom => get line below => take last words 1 => get text\n\n//Get start of table\ngo to page 1\n@transactionsTop = get line starting \"TRANS POST\" => bottom => get line below\n\n@transactionsBottom = get last line containing \"YOUR BRANCH OF RBC ROYAL BANK\" => top => get line above\n\ngo to page 1\n@upertextdeltop = get line starting \"Congratulations\" => bottom\n@upertextdelbottom = get line containing \"Reminder - Forex credit card\" => top\ndelete text in box @upertextdeltop @upertextdelbottom page.left page.right\n\n@deletetop = get line containing \"Reminder - Forex credit card\" => bottom\ndelete text in box @deletetop page.bottom page.left page.right\ndelete all lines starting \"TRANS POST\"\ndelete all lines starting \"DATE OF\"\ndelete all lines starting \"Reminder - Forex credit card limits\"\nignore footer below 135\n\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 85 118 490 590 => describe table false \"*Date[ddMM]\" Details #Credit','2023-08-04 03:33:42',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10442,'LloydsBank_PaidIn_PaidOut','$source = \"LloydsBank_PaidIn_PaidOut\"\nset negative marker \"OD\"\n\n// Get Account Name\n$accountName = get text in box 725 660 page.left page.middleX => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n\n// Get PeriodFrom and PeriodTo\n$periodFrom = get line starting \"Total Paid In\" => top => get line above => get words after \"Balance On\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line starting \"Total Paid Out\" => bottom => get line below => get words after \"Balance On\" => take words 3 => get date \"dd MMM yyyy\"\n\n// Get Opening/Closing balance\n//@PeriodFromText = get line containing \"STATEMENT OPENING BALANCE\"\n//@PeriodToText = get line containing \"STATEMENT CLOSING BALANCE\"\n\n//$openingBalance = get words after @PeriodFromText \"STATEMENT OPENING BALANCE\" => take words 1 => get decimal\n//$closingBalance = get words after @PeriodToText \"STATEMENT CLOSING BALANCE\" => take last words 1 => get decimal\n\n@OpeningTop = get line containing \"STATEMENT OPENING BALANCE\" => top\n@Openingbottom = get line containing \"STATEMENT OPENING BALANCE\" => bottom\n$openingBalance = get text in box @OpeningTop @Openingbottom 500 590 => get decimal\n\n@Closingtop = get line containing \"STATEMENT CLOSING BALANCE\" => top\n@Closingbottom = get line containing \"STATEMENT CLOSING BALANCE\" => bottom\n$closingBalance = get text in box @Closingtop @Closingbottom 500 590 => get decimal\n\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line containing \"Details Paid In (£)\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"STATEMENT CLOSING BALANCE\" => top => get line above\n\nignore header above 745\ndelete all lines starting \"Your Account activity is continued\"\ndelete all lines containing \"STATEMENT OPENING BALANCE\"\ndelete all lines containing \"STATEMENT CLOSING BALANCE\"\ndelete all lines containing \"Details Paid In (£)\"\ndelete all lines containing \"Page\"\n\n// Discard page footer\nignore footer below 35\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 130 340 420 500 560 => describe table false \"Date[dd MMM yy]\" TransactionType Details *#Credit *#Debit #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 130 340 420 500 590 => describe table false \"Date[dd MMM yy]\" TransactionType Details *#Credit *#Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 130 343 420 500 590 => describe table false \"Date[dd MMM yy]\" TransactionType Details *#Credit *#Debit #Balance','2024-07-25 07:50:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10443,'Paypal_AlignedCenter','$source = \"Paypal_AlignedCenter\"\n\n$periodToRegex = \".*-(.*)\"\n$inputDateFormat = \"dd/MMMM/YY\"\n\n$accountnumber = get line containing \"Merchant Account ID:\" => get words after \"Merchant Account ID:\" => get words before \"PayPal ID:\" => get text\n\n$accountname = get line starting \"Statement for\" => bottom => get line below => get text\n\n@period = get line starting \"Balance Summary\" => get words after \"Balance Summary\"\n$periodFrom = take words @period 1 => get date \"M/d/yy\"\n$periodto = get words after @period \"-\" => get date \"M/d/yy\"\n\n$openingbalance = get line starting \"Beginning Available Balance\" => get words after \"Beginning Available Balance\" => get decimal\n$closingbalance = get line starting \"Ending Available Balance\" => get words after \"Ending Available Balance\" => get decimal\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Description Name\" => bottom => get line below\n\ngo to page 1\nignore header above 710\n//ignore footer below 43\nignore footer below 117\n\n// Get end of table\n//go to page @lastPageWithTransactions\n@lastTranpage = get last line starting \"Date Description Name\"\n@transactionsBottom = get line above 0\n\ndelete all lines starting \"Date Description Name\"\n\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 40 90 240 410 502 560 => describe table false \"Date[M/d/yy]\" Details TransactionType - #Credit','2023-08-08 09:24:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10444,'Barclays_CentreAlign','$source = \"Barclays_CentreAlign\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n$accountNumber = get line starting \"Transactions\" => bottom => get line below =>  take last words 1 => get text\n$accountName = get line starting \"Transactions\" => top => get line above => get text\n\n@Period = get line containing \"transactions between\" => get words after \"transactions between\" => take words 3\n$periodFrom = take words @Period 1 => get date \"ddMMyyyy\"\n$periodTo = take last words @Period 1 => get date \"ddMMyyyy\"\n\nignore footer below 25\n\n@Desc_Left = get line containing \"Date Description Money in Money out Balance\" => get words after \"Date\" => take words 1 => left\n@Desc_Left = subtract @Desc_Left 5\n\n@Credit_Left = get line containing \"Date Description Money in Money out Balance\" => get words after \"Date Description\" => take words 1 => left\n@Credit_Left = subtract @Credit_Left 5\n\n//@openingBalanceTop = get line containing \"Date Description Money in Money out Balance\" => bottom\n@openingBalanceTop = get line containing \"Date Description Money in Money out Balance\" => bottom => get line below => top\n//$openingBalance = get text in box @openingBalanceTop 30 455 550 => take words 1 => get decimal\n$openingBalance = get text in box @openingBalanceTop 30 452 550 => take words 1 => get decimal\n\n$closingBalbottom = get last line containing \"Need to view older transactions\" => top => get line above => bottom\n//$closingBalance = get text in box page.top $closingBalbottom 455 550 => take last words 1 => get decimal\n$closingBalance = get text in box page.top $closingBalbottom 452 550 => take last words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Description Money in Money out Balance\" => bottom => get line below\n\n//Get end of table\n@transactionsBottom = get last line containing \"Need to view older transactions\" => top => get line above\n\ndelete all lines containing \"Date Description Money in Money out Balance\"\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 9 60 140 @Credit_Left 470 456 550 => describe table false \"Date[ddMMyyyy]\" Details #Credit - #Balance\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 9 60 140 @Credit_Left 470 452 550 => describe table false \"Date[ddMMyyyy]\" Details #Credit - #Balance\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 9 60 140 @Credit_Left 472 452 550 => describe table false \"Date[ddMMyyyy]\" Details #Credit - #Balance\n\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 9 60 @Desc_Left @Credit_Left 472 452 550 => describe table false \"Date[ddMMyyyy]\" Details #Credit - #Balance','2023-12-14 06:45:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10445,'PaypalTransactions_AlignedCenter','$source = \"PaypalTransactions_AlignedCenter\"\n\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n$periodBufferDays = 7\n\n// Get account details\n$accountName = get line starting \"Date Description Status\" => top => get line above => top => get line above => get text\n$accountnumber = \"Not_Available\"\n\n$periodFrom = get line starting \"Transaction History\" => bottom => get line below => get words before \"through\" => get date \"MMMMdd,yyyy\"\n$periodTo = get line starting \"Transaction History\" => bottom => get line below => get words after \"through\" => get date \"MMMMdd,yyyy\"\n\n// Get balances\n$openingbalance = 0\n$closingbalance = 0\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description Status\" => bottom => get line below\n\n// Get end of table\n@translast = get last line starting \"Date Description Status\"\n@transactionsBottom = get line above 0\n\n// discards\nignore header above 725\nignore footer below 44\ndelete all lines containing \"Date Description Status\"\n\n// Read the transactions\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 30 83 287 503 560 => describe table false \"Date[dd/MM/yyyy]\" Details - #Credit\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 30 83 287 350 400 503 560 => describe table false \"Date[dd/MM/yyyy]\" Details - TransactionType - #Credit','2024-08-22 05:50:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10446,'Amex_Bank','$source = \"Amex_Bank\"\n\n// Discard hidden text\ndelete white words\ndelete tiny words\n\n// Get account name and number\n$accountName = get line containing \"Summary of My Accounts\" => top => get line above => top => get line above => top => get line above => top => get line above => get text\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => get text\n\n\n//get statements period\n@getperiod = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => take words 7\n$periodFrom = take words @getperiod 3 => get date \"MMMM d, yyyy\"\n$periodTo = take last words @getperiod 3 => get date \"MMMM d, yyyy\"\n\n\n// Get opening and closing balance\n$openingBalance = get line containing \"Beginning Balance\" => take last words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => take last words 1 => get decimal\n\n\n// Get transaction table start and end\ngo to page 1\n@transactionsTop = get line containing \"Beginning Balance\" => bottom => get line below\n\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\n\ndelete all lines containing \"Date Transactions\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 110 330 430 510 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit #Credit #Balance','2023-08-18 07:51:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10447,'TideBank_AlignedCenter','$source = \"TideBank_AlignedCenter\"\n$features = \"REVERSE_ORDER\"\n\n// Get account number\n//$accountnumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n//Since Account Number field is mostly encrypted Hence passing the hardcoded value\n$accountnumber = \"Incorrect_Account\"\n\n// Get account name\n@Top = get line starting \"Account number:\" => top\n$accountname = get text in box page.top @Top page.middleX page.right => take words 6 => get text\n\n//Balances\n@balancespanelbottom =  get line containing \"Date Transaction type Details Paid in (£)\" => top\n@balancespanel = get text in box @Top @balancespanelbottom 270 560\n\n$closingbalance = get words after @balancespanel \"Balance on\" => skip words 3 => get words before \"Total paid in\" => get decimal\n$periodFrom = get words after @balancespanel \"Balance on\" => take words 3 => get date \"d MMM yyyy\"\n\n//$openingbalance = take last words @balancespanel 1 => get decimal\n$openingbalance = get words after @balancespanel \"Balance on\" => get words after \"Balance on\" => skip words 3  => take words 1 => get decimal\n$periodTo = get words after @balancespanel \"Total paid out\" => skip words 3 => take words 3 => get date \"d MMM yyyy\"\n\n// Get start of tableDOC-38606\n@transactionsTop = get line starting \"Date Transaction type Details Paid in (£) Paid out (£)\" => bottom => get line below\n\n@transCoor = get line starting \"Date Transaction type Details Paid in (£) Paid out (£)\"\n@CreditsCol = get words after @transCoor \"Date Transaction type Details\" => left\n@CreditsCol = subtract @CreditsCol 5\n\n// Get end of table\n@translast = get last line starting \"Date Transaction type Details Paid in (£) Paid out (£)\"\n@transactionsBottom = get line above 0\n\ngo to page 1\n@TopFooter = get line starting \"Your Tide account\" => top\ndelete text in box on every page @TopFooter page.bottom page.left page.right\n\n// discards\nignore header above 690\n//ignore footer below 132\ndelete all lines containing \"Date Transaction type Details Paid in (£)\"\ndelete all lines starting \"To be billed on or after\"\ndelete all lines containing \"Transaction fees for this period\"\ndelete all lines starting \"Your Tide account is a bank account provided by\"\ndelete all lines starting \"Bank account legal\"\ndelete all lines containing \"The deposit account is attached to a card issued\"\ndelete all lines containing \"The card is a prepaid electronic money product\"\ndelete all lines containing \"loads for the prepaid card funded\"\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 14 35 100 192 394 440 495 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 14 35 100 192 @CreditsCol 440 495 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance','2024-09-10 08:18:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10448,'AnnaBank','$source = \"AnnaBank\"\r\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\r\n\r\n// Get account details\r\ngo to page 1\r\n$accountName = get line starting \"Account\" => get words after \"Account\"  => take words 2 => get text\r\n@accNumberTop = get line containing \"Account number:\" => top\r\n@accNumberBottom = get line containing \"Account number:\" => bottom\r\n$accountNumber = get text in box @accNumberTop @accNumberBottom page.left page.middleX => get words after \"Account number:\" => take words 1 => get text\r\n\r\n// Delete unwanted text\r\ngo to page 1\r\ndelete text in box page.top 561 54 135\r\n\r\n// Get statement period\r\n@getperiod = get text in box page.top page.middleY page.middleX page.right\r\n$periodFrom = get words before @getperiod \"-\" => take last words 3 => get date \"d MMM yyyy\"\r\n$periodTo = get words after @getperiod \"-\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line starting \"Processed on Created on Type Transaction\" => bottom => get line below\r\n\r\n// Get closing balance\r\n@closingBalTop1 = get line starting \"Processed on Created on Type Transaction\" => bottom\r\n$closingBalance = get text in box @closingBalTop1 0 475 550 => take words 1 => get decimal\r\n\r\n// Get table bottom\r\ngo to last page\r\n@transactionsBottom = get last line containing \"Nonsense Admin Ltd\" => top => get line above\r\n\r\n// Discard unwanted text\r\ngo to page 1\r\nget line containing \"Absolutely No Nonsense\" => top => ignore footer below\r\ndelete all lines containing \"Processed on Created on Type\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned  @transactionsTop @transactionsBottom 18.5 40 115 200 250 352 415 475 550 => describe table false \"Date[d MMM yyyy]\" - TransactionType Details #Debit #Credit #Balance','2026-07-22 09:18:02',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10449,'CapitalOnTap_ClearedDate','$source = \"CapitalOnTap_ClearedDate\"\r\n$features = \"CREDIT_CARD\"\r\n\r\n// Get Account Name\r\n$accountname = get text in box 800 690 0 400 => get text\r\n\r\n// Get Account Number\r\n//$accountnumber = get text in box 745 708 400 700 => take last words 1 =>  get text\r\n$accountnumber = get last line containing \"Capital on Tap Points Accrued\" => top => get line above => take last words 1 => get text\r\n\r\ngo to page 1\r\n@period = get line starting \"Statement Summary\" => bottom => get line below\r\n\r\n@balance = get line starting \"Opening Balance\" => bottom => get line below\r\n$openingbalance = take words @balance 1 => get decimal\r\n$closingbalance = take last words @balance 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get last line containing \"Opening Balance\" => bottom => get line below\r\n$periodfrom = get last line containing \"Opening Balance\" => take words 2 => take last words 1 => get date \"dd/MM/yyyy\"\r\n@transactionsbottom = get last line containing \"Closing Balance\" => top => get line above\r\n$periodto = get last line containing \"Closing Balance\" => take words 2 => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\ngo to page 1\r\n@ClearedDateleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 3 => take words 1 => left\r\n//@ClearedDateleft = get line starting \"Authorised Date Cleared Date\" => get words after \"Authorised Date\" => left\r\n@ClearedDateleft = subtract @ClearedDateleft 15\r\n//@Typeleft = get line starting \"Authorised Date Cleared Date\" => get words after \"Cleared Date\" => left\r\n@Typeleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 2 => take words 1 => left\r\n@Typeleft = subtract @Typeleft 15\r\n//@CardDescriptionleft = get line starting \"Authorised Date Cleared Date\" => get words after \"Type\" => left\r\n@CardDescriptionleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 1 => left\r\n@CardDescriptionleft = subtract @CardDescriptionleft 15\r\n//@Amountleft = get line starting \"Authorised Date Cleared Date\" => get words after \"Description\" => left\r\n@Amountleft = get last line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => left\r\n@Amountleft = subtract @Amountleft 35\r\n//@Balanceleft = get line starting \"Authorised Date Cleared Date\" => get words after \"Amount (£)\" => left\r\n@Balanceleft = get last line containing \"Opening Balance\" => get words after \"Opening Balance\" => take last words 1 => left\r\n@Balanceleft = subtract @Balanceleft 10\r\n\r\ndelete all lines starting \"© New Wave Capital Limited\"\r\ndelete all lines starting \"Wave Capital Limits\"\r\ndelete all lines starting \"Interest on card\"\r\ndelete all lines starting \"Authorised Date Cleared Date\"\r\ndelete all lines starting \"Type Card Description Date Date\"\r\ndelete all lines starting \"Authorised Cleared Amount Balance\"\r\nignore footer below 58\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionstop @transactionsbottom  20 93 157 214 462 457 520 => describe table false - \"*Date[dd/MM/yyyy]\" TransactionType Details - #Credit\r\n$transactions = get multi page table @transactionstop @transactionsbottom @ClearedDateleft @Typeleft @CardDescriptionleft @Amountleft @Balanceleft => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Credit','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10450,'Investec_Specialist_Post_Val_Desc','$source = \"Investec_Specialist_Post_Val_Desc\"\n\n// Get Account Name\n$accountName = get text in box 674 615 page.left page.middleX => take words 4 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"account number\" => get words after \"account number\" => take words 1 => get text\n\n// Get Period From/To\n@Periodtxt = get line containing \"Statement period\" => get words after \"Statement period\"\n$periodFrom = take words @Periodtxt 2 => get date \"dd MMM\"\n$periodTo = take last words @Periodtxt 3 => get date \"dd MMM yyyy\"\n\n// Get Opening/Closing balance\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => take words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Description Debit Credit Balance\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get line containing \"Closing balance\" => top => get line above\n\nignore footer below 75\nignore header above 525\ndelete all lines containing \"Opening balance\"\ndelete all lines containing \"Description Debit Credit Balance\"\ndelete all lines containing \"date date\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 135 290 395 490 575 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit #Credit #Balance','2023-09-15 05:08:38',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10451,'NewBankUSA','$source = \"NewBankUSA\"\n\n$accountNameWords = get line starting \"Account Number\" => get words after \"Account Number\"\n$accountName = take words $accountNameWords 2 => skip words 1 => get text\n\n$accountNumber = take words $accountNameWords 2 => skip words 1 => get text\n\n\n@acctop = get line starting \"Previous Balance\" => top\n@accbottom = get line starting \"Interest Paid\" => bottom\n\n$accdetails = get text in box @acctop 363 30 305\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 2 => get decimal\n$closingBalance = take last words $accdetails 2 => get decimal\n\n\ngo to page 1\n\n@Statementperiod = get line containing \"Statement Dates\" => get words after \"Statement Dates\"\n$periodFromText = take words @Statementperiod 3 => get text\n$periodFrom = take words @Statementperiod 1 => get date \"M/dd/yy\"\n\n$PeriodTo = take last words @Statementperiod 1 => get date \"M/dd/yy\"\n\ngo to page 1\n// Get start & end of Deposit and Additions table\n\n@creditsTop = get line starting \"Deposits and Additions\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Checks and Withdrawal\" => if not found then blank => top => get line above\n\n\n// Get start & end of Checks and Withdrawal table\n\n@withTop = get line starting \"Checks and Withdrawals\" => if not found then blank => bottom => get line below\n@withBottom = get line starting \"Checks in Serial Number Order\" => if not found then blank => top => get line above\n\n\n// Get start & end of Left CHECKS\n\n@checksTop = get line starting \"Checks in Serial Number Order\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Daily Balance Information\" => if not found then blank => top => get line above\n\n\ndelete all lines containing \"Deposits and Additions\"\n\ndelete all lines containing \"Date Description\"\ndelete all lines containing \"*Indicates Skip in Check Number\"\n\ndelete all lines containing \"*********\"\ndelete all lines containing  \"Date Check No. Amount\"\n\nignore header above 490\nignore footer below 87\n\n\ngo to page 1\n@deposits = get multi page table @creditsTop @creditsBottom 70 110 310 440 => describe table false \"*Date[M/dd]\" Details  #Credit\n@checksLeft = get multi page table @checksTop @checksBottom 70 99 175 290 => describe table false \"*Date[M/dd]\" Details #Debit\n@withdrawal = get multi page table @withTop @withBottom 70 110 310 440 => describe table false \"*Date[M/dd]\" Details #Debit\n@checksRight = get multi page table @checksTop @checksBottom 300 335 410 530 => describe table false \"*Date[M/dd]\" Details #Debit\n\n$transactions = combine described tables @deposits  @withdrawal  @checksLeft @checksRight ','2023-09-15 05:08:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10452,'Centennial_Bank','$source = \"Centennial_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodbufferdays = 10\n\n// Get account name\n$accountName = get text in box 685 640 page.left page.middleX => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\n\n// Get period & balances\n$periodFrom = get line containing \"PREVIOUS STATEMENT BALANCE\" => get words after \"PREVIOUS STATEMENT BALANCE\" => skip words 2 => take words 1 => get date \"MM/dd/yy\"\n$openingBalance = get line containing \"PREVIOUS STATEMENT BALANCE\" => take last words 1 => get decimal\n$periodTo = get line containing \"CURRENT STATEMENT BALANCE\" => get words after \"CURRENT STATEMENT BALANCE\" => skip words 2 => take words 1 => get date \"MM/dd/yy\"\n$closingBalance = get line containing \"CURRENT STATEMENT BALANCE\" => take last words 1 => get decimal\n\n// Checks table top & Bottom\n@checkstop = get line starting \"SERIAL\" => if not found then blank => bottom => get line below\n@checksbottom = get line containing \"ACCOUNT TRANSACTIONS\" => top => get line above\n\n// Transactions table top & Bottom\n@transactionsTop = get line containing \"DESCRIPTION DEBITS\" => bottom => get line below\n@transactionsBottom = get line containing \"BALANCE BY\" => top => get line above\n\nignore header above 530\ndelete all lines containing \"DESCRIPTION DEBITS\"\ndelete all lines containing \"ACCOUNT TRANSACTIONS\"\n\n// Read the transactions\n@checksleft = get multi page table @checkstop @checksbottom 45 82 150 200 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@checksmiddle = get multi page table @checkstop @checksbottom 238 275 340 392 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@checksright = get multi page table @checkstop @checksbottom 428 465 532 585 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n@othertrans = get multi page table @transactionsTop @transactionsBottom 70 104 290 392 455 => describe table false \"*Date[MM/dd]\" Details #Debit #Credit\n\n$transactions = combine described tables @othertrans @checksleft @checksmiddle @checksright','2023-09-15 05:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10453,'Fifth_Third_Bank_CreditCard','$source = \"Fifth_Third_Bank_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n\ndelete rotated words\n\n// Get Account Name\n$accountName = get text in box 160 130 page.left page.middleX => take words 3 => get text\n\ngo to page 1\n// Get Account Number\n$accountnumber = get line starting \"Account Number Ending\" => take last words 1 => get text\n\n// get period From/To\n@periodtxt = get line starting \"Account Number Ending\" => bottom => get line below => get words before \"Page\"\n$periodFrom = take last words @periodtxt 7 => take words 3 => get date \"MMMM d,yyyy\"\n$periodTo = take last words @periodtxt 7 => take last words 3 => get date \"MMMM d,yyyy\"\n\n// Get Opening/Closing Balance\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n\n// Transactions table top & Bottom\n@transactionsTop = get line starting \"Reference Number Trans Date Post Date\" => bottom => get line below\n@transactionsBottom = get line containing \"Total Purchases, Cash Advances\" => top => get line above\n\n// Remove unwanted lines\nignore header above 725\ndelete all lines starting \"Transactions (cont.)\"\ndelete all lines containing \"XXXX XXXX\"\ndelete all lines containing \"Payments & Credits\"\ndelete all lines starting \"Purchases, Cash Advances & Other\"\n\n// Fees table top & Bottom\n@FeesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\n@FeesBottom = get last line containing \"TOTAL FEES FOR THIS PERIOD\" => top => get line above\n\n// Interest table top & Bottom\n@InterestTop = get last line starting \"Trans Date Post Date Description\" => if not found then blank => bottom => get line below\n@InterestBottom = get last line containing \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\ndelete all lines containing \"Trans Date Post Date Description of Transaction\"\n\n// Read the transactions\n@trans = get multi page table @transactionsTop @transactionsBottom 25 120 170 235 500 600 => describe table false TransactionType - \"*Date[MM/dd]\" Details #Credit\n@Feetrans = get multi page table @FeesTop @FeesBottom 130 180 240 500 600 => describe table false - \"*Date[MM/dd]\" Details #Credit\n@Interesttrans = get multi page table @InterestTop @InterestBottom 130 180 240 500 600 => describe table false - \"*Date[MM/dd]\" Details #Credit\n\n$transactions = combine described tables @trans @Feetrans @Interesttrans','2023-09-15 05:08:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10454,'AmericanExpress_AccountActivity','$source = \"AmericanExpress_AccountActivity\"\n\n// Get Account Name\n$accountName = get text in box 655 620 page.left page.middleX => take words 3 => get text\n\n// Get statement periods\n@periodtxt = get line starting \"Statement Period\" => bottom => get line below\n$periodFrom = take words @periodtxt 1 => get date \"MM/dd/yyyy\"\n$periodTo = take last words @periodtxt 1 => get date \"MM/dd/yyyy\"\n\n// Get Account number\n$accountNumber = get line starting \"Account Ending\" => take last words 1 => get text\n\n// Get opening/closing\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n// Get top of the table\n@transactionsTop = get line starting \"Date Description Credits Debits\" => bottom => get line below\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\ngo to page 1\nignore header above 627\ndelete all lines containing \"Account Activity\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines starting \"Date Description Credits Debits\"\ndelete all lines containing \"continued on next page\"\ndelete all lines containing \"24/7 Account Access\"\ndelete all lines containing \"American Express National Bank.\"\ndelete all lines containing \"SingleStatement\"\ndelete all lines containing \"[PAGE INTENTIONALLY LEFT BLANK]\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 105 345 420 500 560 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit #Debit #Balance','2023-10-25 12:33:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10455,'MetroBank_CreditCardNo','$source = \"MetroBank_CreditCardNo\"\n\n// Get account name\n$accountName = get line starting \"Your account summary\" => get words after \"Your account summary\" => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get Period From/To\n@summtxt = get line starting \"Your account summary\" => bottom => get line below\n$periodFrom = get words after @summtxt \"From:\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get words after @summtxt \"From:\" => take words 7 => take last words 3 => get date \"dd MMM yyyy\"\n\n// Get opening/closing\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\n// Get top of transaction table\n@transactionsTop = get line starting \"Date Credit Card No. Transaction\" => bottom => get line below\n@lastTranspage = get last line starting \"Date Credit Card No. Transaction\"\n@transactionsBottom = get line above 0\n\ngo to page 1\nignore header above 810\ndelete all lines containing \"Balance brought forward\"\ndelete all lines starting \"Date Credit Card No. Transaction\"\ndelete all lines starting \"Your transactions\"\ndelete all lines containing \"Financial Services Compensation Scheme\"\ndelete all lines containing \"FSCS\"\n\n@toptxt = get line containing \"Important Information about compensation\" => top\n@bottomtxt = get line containing \"Account Summary section\" => bottom\ndelete text in box @toptxt @bottomtxt page.left page.right\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 125 180 340 420 495 535 => describe table false \"Date[dd MMM yyyy]\" TransactionType Details *#Debit *#Credit #Balance\n','2023-10-25 12:34:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10456,'DivvyBank','$source = \"DivvyBank\"\n\n$accountName = get line containing \"Account\" => get words after \"Account\" => take words 1 => get text\n$accountNumber = get line containing \"Account\" => get words after \"Account\" => take words 1 => get text\n\n$openingBalance = get line starting \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Statement balance\" => get words after \"Statement balance\" => take last words 1 => get decimal\n$statementPeriod = get line starting \"Statement:\" => get words after \"Statement:\"\n$periodFromText = take words $statementPeriod 3 => get text\n$periodFrom = take words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n$periodTo = take last words $statementPeriod 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n// Get start & end of Payment table\n@payTop = get line starting \"DATE TYPE AMOUNT\" => if not found then blank => bottom => get line below\n@payBottom = get line starting \"Fees\" => if not found then blank => top => get line above\n\n// Get start & end of Fees table\n@feesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\n@feesBottom = get line starting \"Adjustments\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of Transactions table\n@creditsTop = get line starting \"DATE CARD MERCHANT AMOUNT NAME\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Legal\" => if not found then blank => top => get line above\n\n\ndelete all lines starting \"Fees\"\ndelete all lines starting \"DATE TYPE AMOUNT\"\ndelete all lines starting \"Adjustments\"\ndelete all lines starting \"No adjustments were made\"\ndelete all lines starting \"No fees were applied\"\ndelete all lines starting \"Total\"\ndelete all lines containing \"CARD MERCHANT\"\ndelete all lines containing \"foreign fee\"\ndelete all lines containing \"Statement:\"\n\nignore footer below 30\n\n\ngo to page 1\n@payment = get multi page table @payTop @payBottom 0 95 360 430 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\n@fees = get multi page table @feesTop @feesBottom 0 95 360 430 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n@trans = get multi page table @creditsTop @creditsBottom 0 90 360 425 510 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit TransactionType\n\n$transactions = combine described tables @payment @fees @trans','2023-11-20 05:07:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10457,'KBC_Card','$source = \"KBC_Card\"\n\n$features = \"CREDIT_CARD NO_OPENING_BALANCE\"\n\n// amounts in SouthAfrica\nset culture \"nl-NL\"\n\n// get accountName\n$accountName = get text in box 720 650 page.left page.middleX => get text\n\n// get accountNumber\n$accountNumber = get line starting \"Kaartnummer(s):\" => get words after \"Kaartnummer(s):\" => get text\n\n\n// get statement period\n@get_period = get line starting \"Overzicht van je verrichtingen van\" => get words after \"verrichtingen van\" => take words 7\n$periodFrom = take words @get_period 1 => get date \"d-MM-yyyy\"\n$periodTo = take last words @get_period 1 => get date \"d-MM-yyyy\"\n\n\n// get closing balance\n@get_closing = get line containing \"Afrekening via je bank\"\n@closing_top = get line containing \"Totaal bedrag van\" => top\n@closing_bottom = get line containing \"Afrekening via je bank\" => bottom\n$closingBalance = get text in box @closing_top @closing_bottom 410 550 => take last words 2 => get decimal\n\n\n// get start of table\ngo to page 1\n@trans_top = get line starting \"verrichting verrekening\" => bottom\n@trans_bottom = get line above 0 => bottom\n@get_toptrns_text = get text in box @trans_top @trans_bottom 55 180 => take words 2 => get text\n@transactionsTop = get line starting @get_toptrns_text => top => get line above => bottom => get line below\n\n\n// get end of table\n@transactionsBottom = get line containing \"Kaart blokkeren:\" => top => get line above\n\n// delete extra text\ndelete all lines starting \"Vorig saldo\"\ndelete all lines starting \"Totaal bedrag\"\ndelete all lines starting \"Afrekening via je bank op\"\n\ngo to page 1\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 55 110 190 410 550 => describe table false \"Date[d-MM-yyyy]\" - Details *#Credit','2023-11-20 05:07:31',0);
