INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10459,'ABSA_Date_Description_Site','$source = \"ABSA_Date_Description_Site\"\n\n\n// Get period from\n$periodFrom = get line starting \"Start Date\" => get words after \"Start Date\" => take words 1 => get date \"yyyyMMdd\"\n$periodTo = get line containing \"End Date\" => get words after \"End Date\" => take words 1 => get date \"yyyyMMdd\"\n\n// Get account name\n$accountName = get line starting \"Account\" => skip words 2 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account\" => get words after \"Account\" => take words 1 => get text\n\n\n// Get opening and closing balances\n$openingBalance = get line containing \"BALANCE B/FORWARD\" => take last words 1 => get decimal\ngo to page 1\n@closingtop = get last line containing \"Site Amount Balance\" => bottom\n@closingbottom = get line above 0 => top\n$closingBalance = get text in box @closingtop @closingbottom 530 580 => take last words 1 => get decimal\n\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line containing \"Site Amount Balance\" => bottom => get line below\n\n\n// Get end of table\n@navigate_to_last_page = get last line containing \"Site Amount Balance\"\n@transactionsBottom = get line above 0\n\n\n// Discard page header\nget line containing \"Site Amount Balance\" => top => ignore header above\n\n// Discard unwanted lines\ndelete all lines starting \"Page\"\ndelete all lines containing \"BALANCE B/FORWARD\"\ndelete all lines containing \"Site Amount Balance\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 58 90 400 500 580 => describe table false \"Date[yyMMdd]\" Details #Credit *#Balance','2023-11-20 05:07:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10460,'MissionLaneCard','$source = \"MissionLaneCard\"\n\ngo to page 1\n//set negative marker \"-\"\n\n//$features = \"NO_TRANSACTION_YEAR\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n\nremove page 2\n$accountNumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 4  => get text\n$accountName = get line starting \"Account Number:\" => top => get line above => take words 1 => get text\n\n@Datestop = get line containing \"Period:\" => bottom\n@Datesbottom = get line containing \"Period:\" => bottom => get line below => bottom\n@Dates = get text in box @Datestop @Datesbottom page.middleX page.right\n\n$PeriodFrom = get words before @Dates \"-\" => get date \"MMMM d, yyyy\"\n$PeriodTo = get words after @Dates \"-\" => get date \"MMMM d, yyyy\"\n\n@acctop = get line starting \"Summary of Account Activity\" => bottom\n@accbottom = get line containing \"Credit Limit\" => top\n//$accdetails = get text in box @acctop @accbottom 0 298\n$accdetails = get text in box @acctop @accbottom 0 300\n\n$openingbalance = get words after $accdetails \"Previous Balance\" => take words 2 => get decimal\n$closingBalance = get words after $accdetails \"NEW BALANCE\" => take words 2 =>  get decimal\n\nset negative marker \"-\"\n//$PeriodFromText = get line containing \"Cash Back Earned\" => get words after \"Cash Back Earned\" => take words 3\n//$PeriodFrom =  take words $PeriodFromText 1 => get date \"MM/dd/yy\"\n//$PeriodTo =   take last words $PeriodFromText 1 => get date \"MM/dd/yy\"\n\n// Get start & end of Payments, Adjustments and Other table\n@paymentsTop = get line starting \"Payments, Adjustments and Other\" => if not found then blank => bottom => get line below\n@paymentsBottom = get line starting \"TOTAL PAYMENTSOR ADJUSTMENTS\" => if not found then blank => top => get line above\n\ngo to page 2\n// Get start & end of Purchases table\n@purchaseTop = get line starting \"Purchases\" => if not found then blank => bottom => get line below\n@purchaseBottom = get line starting \"TOTAL PURCHASES AND OTHER DEBITS\" => if not found then blank => top => get line above\n\ngo to page 2\n// Get start & end of Fees table\n@feesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\n@feesBottom = get line starting \"TOTAL FEES FOR THIS PERIOD\" => if not found then blank => top => get line above\n\ngo to page 2\n// Get start & end of Interest Charged table\n@intTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below\n@intBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => if not found then blank => top => get line above\n\n\ndelete all lines starting \"Payments, Adjustments and Other\"\ndelete all lines starting \"TOTAL PAYMENTSOR ADJUSTMENTS\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines starting \"Totals Year-to-Date\"\n\ngo to page 1\n\n@payments = get multi page table @paymentsTop @paymentsBottom 97 125 252 500 575 => describe table false \"*Date[MM/dd]\" TransactionType Details #Debit\n@purchase = get multi page table @purchaseTop @purchaseBottom 97 125 252 500 575 => describe table false \"*Date[MM/dd]\" TransactionType Details #Credit\n@fees = get multi page table @feesTop @feesBottom 97 125 252 500 575 => describe table false \"*Date[MM/dd]\" TransactionType Details #Credit\n@int = get multi page table @intTop @intBottom 97 125 252 500 575 => describe table false \"*Date[MM/dd]\" TransactionType Details #Credit\n\ngo to page 1\n$transactions = combine described tables @payments @purchase @fees @int','2024-10-17 08:41:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10461,'BankOfMontreal_CreditCard','$source = \"BankOfMontreal_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n\nset negative marker \"CR\"\n\n@Summarytop = get line containing \"Card number\" => top => get line above => top\n@Summarybottom = get line containing \"Statement period\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 360 610\n\n// Get Account Name\n$accountName = get words before @Summary \"Card number\" => get text\n\n// Get Card number\n$accountNumber = get words after @Summary \"Card number\" => get words between \"Card number\" \"Statement date\" => get text\n\n// Get Statement periods\n$periodFrom = get words after @Summary \"Statement period\" => get words between \"Statement period\" \"-\" =>  get date \"MMM d,yyyy\"\n$periodTo = get words after @Summary \"Statement Period\" => get words after \"-\" => get date \"MMM d,yyyy\"\n\n// Get opening/closing Balance\n@openingBalancetop = get line containing \"balance,\" => top\n@openingBalancebottom = get line containing \"balance,\" => bottom\n$openingBalance = get text in box @openingBalancetop @openingBalancebottom 0 360 => get words after \"balance,\" => skip words 3 => get decimal\n\n@pageHeader = get last line containing \"Total for card number\" => top\n@pageFooter = get last line containing \"Total for card number\" => bottom\n$closingBalance = get text in box @pageHeader @pageFooter 350 420 => get decimal\n\ngo to page 1\n// Get top of the transaction table\n@transactionsTop = get line containing \"DATE DESCRIPTION AMOUNT\" => bottom => get line below\n\ndelete text in box page.top page.bottom 420 page.right\nignore header above 705\ndelete all lines containing \"(continued on next page)\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Transactions since your\"\ndelete all lines containing \"DATE DESCRIPTION AMOUNT\"\ndelete all lines containing \"Card number:\"\ndelete all lines starting \"TRANS POSTING\"\n\n// Get bottom of the transaction table\n@transactionsBottom = get last line starting \"Subtotal for\" => top => get line above\ndelete all lines starting \"Subtotal for\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 85 130 350 420 => describe table false - \"*Date[MMM d]\" Details #Credit','2025-01-09 08:35:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10462,'QudosBank','$source = \"QudosBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get Account Name\n$accountName = get text in box 652 625 page.left page.middleX => take words 5 => get text\n\n// Get period From/To\n$periodFrom = get line containing \"Statement Begins\" => get words after \"Statement Begins\" => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = get line containing \"Statement Ends\" => get words after \"Statement Ends\" => take words 3 => get date \"dd MMMM yyyy\"\n\n// Get account number\n$accountNumber = get line containing \"AC No:\" => get words after \"AC No:\" => take words 1 => get text\n\n// Get opening/closing Balance\n$openingBalance = get line containing \"Opening Balance\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Closing Balance\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Transaction Details Debit Credit\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\nignore footer below 68\nignore header above 725\ndelete all lines containing \"Transaction Details Debit Credit\"\ndelete all lines starting \"Please retain this statement for taxation purposes\"\ndelete all lines containing \"Opening Balance\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 90 135 390 455 520 580 => describe table false \"*Date[d MMM]\" - Details #Debit #Credit #Balance','2023-12-14 06:45:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10463,'HSBC_Aus_Card','$source = \"HSBC_Aus_Card\"\n$features = \"CREDIT_CARD\"\n$periodbufferdays = 7\n\n@toptxt = get line starting \"Credit Cards Online Direct Debit\" => top\n@bottomtxt = get line containing \"HSBC receives your payment\" => bottom\ndelete text in box @toptxt @bottomtxt page.left page.right\n\ngo to page 1\n// Get account name\n$accountname = get text in box 662 625 page.left page.middleX => take words 4 => get text\n\n@numperiodtxt = get line starting \"Account Number Statement Period\" => bottom => get line below\n\n// Get Account number\n$accountnumber = take words @numperiodtxt 4 => get text\n\n// Get period From/To\n$periodFrom = skip words @numperiodtxt 4 => take words 3 => get date \"dd MMM yy\"\n$periodTo = skip words @numperiodtxt 4 => get words after \"to\" => take words 3 => get date \"dd MMM yy\"\n\n// Get opening/closing balance\n$openingBalance = get line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"CLOSING BALANCE\" => take last words 1 => get decimal\n\ngo to page 1\n// get top of the table\n@transactionsTop = get line containing \"Transaction Date Card Used\" => bottom => get line below\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"Email_EStatement\"\ndelete all lines containing \"HSBC Classic Credit Card\"\ndelete all lines starting \"Page\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 125 500 570 => describe table false \"Date[d/MM/yy]\" Details **#Credit','2023-12-14 06:45:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10464,'BMO_Financial_Bank','$source = \"BMO_Financial_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Get account name\r\n$accountName = get text in box 630 608 page.left page.middleX => take words 3 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => take words 1 => get text\r\n\r\n// Get Period From/To\r\n//deleted extra words from left side of the page to pick Statement Periods\r\ndelete text in box page.top 610 page.left 395\r\n$periodFromtxt = get line containing \"Statement Period\" => bottom => get line below\r\n//$periodFrom = get words before $periodFromtxt \"TO\" => skip words 1 => take words 1 => get date \"MM/dd/yy\"\r\n$periodFrom = get words before $periodFromtxt \"TO\" => take last words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get words after $periodFromtxt \"TO\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n// Get opening/closing\r\n$openingBalance = get line containing \"Previous Balance as of\" => get words after \"Previous Balance as of\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take last words 1 => get decimal\r\n\r\n// Get credits table\r\n@credtop = get line containing \"Deposits and Other Credits\" => if not found then blank => bottom => get line below\r\n@credbottom = get line containing \"Withdrawals and Other Debits\" => if not found then blank => top => get line above\r\n\r\n@debtop = get line containing \"Withdrawals and Other Debits\" => bottom => get line below\r\n@debbottom = get line containing \"Daily Balance Summary\" => top => get line above\r\n\r\ndelete all lines containing \"Indicates break in check sequence\"\r\ngo to page 1\r\n@chktbl_top = get line containing \"Date Serial # Amount\" => if not found then blank => bottom => get line below\r\n@chktbl_bottom = get line containing \"Daily Balance Summary\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Date Amount Description\"\r\nignore header above 605\r\n\r\n\r\n// Read the transactions\r\n//@credtrans = get multi page table @credtop @credbottom 45 160 215 570 => describe table false \"*Date[MMM dd]\" #Credit Details\r\n@credtrans = get multi page table @credtop @credbottom 45 150 215 570 => describe table false \"*Date[MMM dd]\" #Credit Details\r\n@checktrans_1 = get multi page table @chktbl_top @chktbl_bottom 45 95 190 295 => describe table false \"*Date[MMM dd]\" #ChequeNumber #Debit\r\n@checktrans_2 = get multi page table @chktbl_top @chktbl_bottom 305 370 450 570 => describe table false \"*Date[MMM dd]\" #ChequeNumber #Debit\r\n\r\ngo to page 1\r\n@del_chktbltop = get line containing \"Checks by Serial Number\" => bottom\r\n$Chkdeletetext = delete text in box @del_chktbltop page.bottom page.left page.right => get text\r\n\r\ndelete all lines containing \"Checks by Serial Number\"\r\ndelete all lines starting \"Date Serial\"\r\ndelete all lines starting \"FORM:G30039\"\r\ndelete all lines starting \"________________________\"\r\ndelete all lines containing \"LLC PAGE\"\r\n\r\n//@debtrans = get multi page table @debtop @debbottom 45 160 215 570 => describe table false \"*Date[MMM dd]\" #Debit Details\r\n@debtrans = get multi page table @debtop @debbottom 45 150 215 570 => describe table false \"*Date[MMM dd]\" #Debit Details\r\n\r\n//$transactions = combine described tables @credtrans @debtrans\r\n$transactions = combine described tables @credtrans @debtrans @checktrans_1 @checktrans_2','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10465,'NAB_Card','$source = \"NAB_Card\"\n\n\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\ndelete rotated words\nset negative marker \"CR\"\n\n\n// Delete extra text from left or right side\ngo to page 1\n$deleteLeftText = delete text in box on every page page.top page.bottom 0 43 => get text\n$deleteRightText = delete text in box on every page page.top page.bottom 552 page.right => get text\ndelete text in box on every page page.top page.bottom 0 43\ndelete text in box on every page page.top page.bottom 552 page.right\n\n\n// Get period from/to\n$getperiod = get line starting \"Statement Period\" => get words after \"Statement Period\" => get words before \"-\" => get text\n$periodFrom = get line starting \"Date Date\" => bottom => get line below => take words 2 => take last words 1 => get date \"d/MM/yy\"\n$periodTo = get line containing \"How to identify\" => top => get line above => take words 1 => get date \"d/MM/yy\"\n\n\n// Get account name\ngo to page 1\n$accountName = get text in box 700 620 0 page.middleX => take words 6  => get text\n\n// Get account number\n$accountNumber = get line containing \"Visa Account Number\" => get words after \"Visa Account Number\" => take words 4 => get text\n\n\n// Get opening and closing balances\ngo to page 1\n@openingtop = get line containing \"Account summary\" => bottom\n@openingbottom = get line containing \"Payments & other credits\" => top\n$getopening = get text in box @openingtop @openingbottom 225 295 => get words after \"Opening balance\" => get text\n$openingBalance = get text in box @openingtop @openingbottom 225 295 => get words after \"Opening balance\" => get decimal\n\n@closingtop = get line containing \"Interest /& other charges\" => bottom\n@closingbottom = get line containing \"Interest /& other charges\" => Bottom => get line below => bottom\n$getclosing1 = get text in box @closingtop @closingbottom 225 295 => get words after \"Closing\" => get text\n$closingBalance = get text in box @closingtop @closingbottom 225 295 => get words after \"Closing\" => get decimal\n\n\n// Get start of table\n@transactionTop = get line containing \"processed transaction\" => bottom => get line below\n\n\n// Get end of table\n@transationBottom = get last line containing \"How to identify the card used\" => top => get line above\n\n\n// delete header, footer or delete extra text\ngo to page 1\n@deletetext = get line containing \"Visa Account Number\" => get words after \"Visa Account Number\" => take words 4 => get text\ndelete all lines containing \"@deletetext\"\n\ndelete all lines containing \"Detach here\"\ndelete all lines containing \"Date Date of Card\"\ndelete all lines containing \"processed transaction\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"Transaction details\"\n\ngo to page 1\n@footertopdel = get line starting \"Cheque Particulars\" => bottom\ndelete text in box @footertopdel page.bottom 0 page.right\ndelete all lines starting \"Cheque Particulars\"\n\nignore header above 770\n\n\n\n// Read the transactions\n$transactions = get multi page table @transactionTop @transationBottom 42 95 180 430 490 554 => describe table false \"*Date[d/MM/yy]\" - Details - #Credit','2023-12-14 06:45:21',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10466,'MCB_Bank','$source = \"MCB_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 30\n//Get statement period\n$periodTo =  get line containing \"Statement Period\" => get words after \"Period\" => take words 3 => get date \"MMMM dd yyyy\"\n$periodFrom = get line containing \"PREVIOUS BALANCE\" => get words before \"PREVIOUS\" => take words 1 => get date \"dd/MM\"\n\nset negative marker \"DR\"\n\n// Parse dates in Dutch\nset culture \"nl-NL\"\n\n\n// Get account name\n@getaccnttop = get line containing \"Statement of Your\" => bottom => get line below => bottom\n@getaccntbottom = get line containing \"Statement of Your\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom\n$accountName = get text in box @getaccnttop @getaccntbottom 0 page.middleX => get text\n\n// Get account number\n$accountNumber = get line containing \"CURRENT ACCOUNT#\" => take last words 1 => get decimal\n\n\n//Get opening closing balance\n$openingbalance = get line containing \"PREVIOUS BALANCE\" => get words after \"BALANCE\" => take words 1 => get decimal\n//$closingBalance = get line containing \"TOTAL DEBITS/CREDITS\" => top => get line above => take last words 1 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"PREVIOUS BALANCE\" => bottom => get line below\n\n//go to page 1\n//@dateCoorRght = get line containing \" DATE DEBIT AMOUNT\" => get words before \"DESCRIPTION\" => take last words 1 => right\n//@dateCoorRght = add @dateCoorRght 4\n\n@dateleft = get line containing \" DATE DEBIT AMOUNT\" => get words before \"DEBIT\" => take words 1 => right\n@dateleft = subtract @dateleft 5\n\n@daterght = get line containing \" DATE DEBIT AMOUNT\" => get words before \"DESCRIPTION\" => take last words 1 => right\n@daterght = subtract @daterght 5\n\n@descrptnCoorleft = get line containing \" DATE DEBIT AMOUNT\" => get words before \"DESCRIPTION\" => take last words 1 => right\n@descrptnCoorleft = add @descrptnCoorleft 10\n\n@descrptnCoorRght = get line containing \" DATE DEBIT AMOUNT\" => get words after \"DATE\" => take words 1 => left\n@descrptnCoorRght = subtract @descrptnCoorRght 2\n\n@debitright = get line containing \" DATE DEBIT AMOUNT\" => get words before \"AMOUNT\" => take last words 1 => left\n@debitright = subtract @debitright 2\n\n@creditrght = get line containing \" DATE DEBIT AMOUNT\" => get words after \"CREDIT\" => take words 1 => right\n@creditrght = add @creditrght 5\n\n\n@Balncrght = get line containing \" DATE DEBIT AMOUNT\" => get words after \"DESCRIPTION\" => take words 1 => right\n@Balncrght = add @Balncrght 30\n\n//go to page 1\n//@closing_bottom = get line containing \"TOTAL DEBITS/CREDITS\" => top\n//$closingBalance = get text in box page.top @closing_bottom @creditrght @Balncrght => take last words 1 => get decimal\n\ngo to page 1\n$top_del1 = get line containing \"PREVIOUS BALANCE\" => top => get line above => get text\n//delete all lines starting @top_del1\n\n$top_del2 = get line containing \"PREVIOUS BALANCE\" => top => get line above => top => get line above => get text\n//delete all lines starting @top_del2\n\n$top_del3 = get line containing \"PREVIOUS BALANCE\" => top => get line above => top => get line above => top => get line above => get text\n//delete all lines starting @top_del3\n\n@top_del4 = get line containing \"PREVIOUS BALANCE\" => top\ndelete text in box page.top @top_del4 page.left page.right\n\ngo to page 2\n@header = get line containing \"DATE DEBIT AMOUNT\" => bottom\n\ndelete all lines starting $top_del1\ndelete all lines starting $top_del2\ndelete all lines ending $top_del3\n\n// Discard page header\n//ignore header above 765\n\ndelete all lines containing \"DATE DEBIT AMOUNT\"\ndelete all lines containing \"D/M (Withdrawal) (Deposit)\"\ndelete all lines containing \"Statement of Your\"\n//delete all lines containing \"STATIA UTILITY COMPANY\"\ndelete all lines containing \"CURRENT ACCOUNT#\"\ndelete all lines containing \"Statement Period\"\n//delete all lines starting \"ST. EUSTATIUS\"\ndelete all lines starting \"Page\"\n//ignore footer below 78\nignore footer below 82\n\nignore header above @header\n\n@closing_bottom = get line containing \"TOTAL DEBITS/CREDITS\" => top => get line above\n$closingBalance = get text in box page.top 82 @creditrght @Balncrght => take last words 1 => get decimal\n\n// Get end of table\n@transactionsBottom = get last line containing \"TOTAL DEBITS/CREDITS\" => top => get line above\n\ndelete all lines containing \"TOTAL DEBITS/CREDITS\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 65 105 340 425 508 600 => describe table false \"*Date[dd/MM]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @daterght @descrptnCoorleft @descrptnCoorRght @debitright @creditrght @Balncrght => describe table false \"*Date[dd/MM]\" - Details #Debit #Credit #Balance','2025-05-06 06:26:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10467,'PBK_Bank','$source = \"PBK_Bank\"\n\n$accountname = get text in box 640 580 20 page.middleX => take words 2 => get text\n$accountnumber = get line containing \"Account No.:\" => get words after \"Account No.:\" => take words 1 => get text\n\n$openingbalance = get line starting \"Balance Forward From\" => take last words 1 => get decimal\n$closingbalance =  get line starting \"Ending Balance On\" => take last words 1 => get decimal\n\n$periodfrom = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" =>  take words 1  => get date \"MM/dd/yy\"\n$periodto = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" =>  take words 1 => get date \"MM/dd/yy\"\n\n// header deleted to avoid grab service charge word in service transaction\n@headerbottom = get line starting \"Ending Balance On\" => bottom\ndelete text in box page.top @headerbottom page.left page.right\n\n//CREDIT ACTIVITY Deposit Table\n@Deposittop = get line starting \"Date Type Amount\" => if not found then blank  => bottom => get line below\n@Depositbottom = get line starting \"Date Description Amount\" => if not found then blank  => top => get line above\n\n//Credit Table\n@Credittransactiontop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@Credittransactionbottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line above\n\ngo to page 1\n//Sevice Charge line Table\n@Servicechargetop = get line containing \"SERVICE CHARGE\" => if not found then blank => top => get line above => bottom => get line below\n@Servicechargebottom = get line containing \"SERVICE CHARGE\" => if not found then blank => bottom => get line below => top => get line above\n@Servicecharge = get multi page table @Servicechargetop @Servicechargebottom 30 100 510 580 => describe table false \"Date[MM/dd/yy]\" Details *#Debit\ndelete all lines containing \"SERVICE CHARGE\"\n\ngo to page 1\n//Check Table\n@Checktop = get line starting \"CHECKS AND OTHER DEBITS\" => if not found then blank => bottom => get line below\n@Checkbottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Statement Date:\"\ndelete all lines containing \"Account No.\"\ndelete all lines starting \"Date Type Amount\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Continued\"\ndelete all lines starting \"ALL CREDIT ACTIVITY\"\ndelete all lines starting \"Date Check # Amount\"\ndelete all lines starting \"CHECKS AND OTHER DEBITS (cont.)\"\n\nignore header above 550\n\n//Check Tables\n@Checklefttransactions = get multi page table @Checktop @Checkbottom  30 100 165 225 => describe table false \"Date[MM/dd/yy]\" #ChequeNumber *#Debit\n@Checkmiddletransactions = get multi page table @Checktop @Checkbottom 215 270 335 400 => describe table false \"Date[MM/dd/yy]\" #ChequeNumber *#Debit\n@CheckRighttransactions = get multi page table @Checktop @Checkbottom 380 442 510 580 => describe table false \"Date[MM/dd/yy]\" #ChequeNumber *#Debit\n\ngo to page 1\n@ChecktopDel1 = get line starting \"CHECKS AND OTHER DEBITS\" => top\ndelete text in box @ChecktopDel1 page.bottom page.left page.right\n\n@ChecktopDel3 = get line starting \"DAILY BALANCE SUMMARY\" => top\ndelete text in box @ChecktopDel3 page.bottom page.left page.right\n\n//Debit Table\ngo to page 1\n@Debittransactiontop = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line below\n@lastDebitPage = get last line starting \"ELECTRONIC DEBITS\"\n@Debittransactionbottom = get line above 50\n\ndelete all lines starting \"CHECKS AND OTHER DEBITS\"\ndelete all lines starting \"ELECTRONIC DEBITS\"\ndelete all lines starting \"DAILY BALANCE SUMMARY\"\n\n//Deposit Tables\n@Depositlefttransactions = get multi page table @Deposittop @Depositbottom  30 100 165 225 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n@Depositmiddletransactions = get multi page table @Deposittop @Depositbottom  215 268 335 400 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n@DepositRighttransactions = get multi page table @Deposittop @Depositbottom  380 442 510 580 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n\n@Credittransactions = get multi page table @Credittransactiontop @Credittransactionbottom  30 100 510 580 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n\n@Debittransactions = get multi page table @Debittransactiontop @Debittransactionbottom  30 100 510 580 => describe table false \"Date[MM/dd/yy]\" Details *#Debit\n\n$transactions = combine described tables @Depositlefttransactions @Depositmiddletransactions @DepositRighttransactions @Credittransactions @Debittransactions @Checklefttransactions @Checkmiddletransactions @CheckRighttransactions @Servicecharge','2025-08-20 07:26:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10468,'NewEnglandBank','$source = \"NewEnglandBank\"\n\n$accountName = get line containing \"Account Type Account Number\" => bottom => get line below  => skip words 2 => take words 1 => get text\n$accountNumber = get line containing \"Account Type Account Number\" => bottom => get line below  => skip words 2 => take words 1 => get text\n\n@acctop = get line starting \"Account Summary\" => bottom\n@accbottom = get last line containing \"Ending Balance\" => bottom\n\n$accdetails = get text in box @acctop @accbottom 30 400\n\n$PeriodFrom = get words before $accdetails \"Beginning Balance\" => take last words 1  => get date \"MM/dd/yyyy\"\n\n$PeriodTo =  get words before $accdetails \"Ending Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\ngo to page 3\n// Get start & end of Deposits and Other Credits table\n@creditsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Other Debits\" => if not found then blank => top => get line above\n\n\n// Get start & end of Other Debits table\n@otherDebitsTop = get line starting \"Other Debits\" => if not found then blank => bottom => get line below\n@otherDebitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n\n\n// Get start & end of CHECKS\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"* Indicates skipped check\" => if not found then blank => top => get line above\n\n// Get start & end of 1st right CHECKS\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"* Indicates skipped check\" => if not found then blank => top => get line above\n\n// Get start & end of 1st right CHECKS\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"* Indicates skipped check\" => if not found then blank => top => get line above\n\n\ndelete all lines starting \"Deposits\"\ndelete all lines containing \"continued\"\ndelete all lines containing \"Statement Ending\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Checking Account Statements\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Checks Cleared\"\ndelete all lines containing \"* Indicates skipped check number\"\n\nignore header above 670\n\n@deposits = get multi page table @creditsTop @creditsBottom 30 85 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n\n@otherdebits = get multi page table @otherDebitsTop @otherDebitsBottom 30 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\n\n@checksLeft = get multi page table @checksTop @checksBottom 38 90 143 215 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n\n@checksRight = get multi page table @checksTop @checksBottom 230 274 325 395 => describe table false  ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n\n@checksRightSec = get multi page table @checksTop @checksBottom 415 458 510 580 => describe table false  ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n\n\ngo to page 1\n$transactions = combine described tables @deposits @otherdebits @checksLeft @checksRight @checksRightSec ','2024-01-18 09:57:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10469,'BBVA_UK','$source = \"BBVA_UK\"\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get account name\n@Top = get line containing \"Customer Information\" => top\n@Bottom = get line containing \"Account Number\" => top => get line above => top\n$accountName = get text in box @Top @Bottom page.left 200 => take words 5 => get text\n\n// Get Statementperiod\n$periodTo = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 3 => get date \"d MMM yyyy\"\n\n$periodFrom = get line containing \"Opening Balance\" => get words before \"Opening\" => take words 3 => get date \"dd MMM yyyy\"\n\n\n\n// Get opening and closing balances\ngo to page 1\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take last words 1 => get decimal\n\n$closingBalance = get line starting \"Current Balance\" => get words after \"Balance\" => get decimal\n\n// Get start of transactions table\ngo to page 1\n\n@transactionsTop = get line containing \"Date Particulars Value\" => bottom => get line below => bottom => get line below\n\n\n// Get end of transactions table\n@transactionsBottom = get line starting \"Current Balance\" => top => get line above\n\n\n// Remove unwanted lines that appear in middle of transactions\nignore header above -180\ndelete all lines starting \"Date Particulars\"\ndelete all lines starting \"Balance B/F\"\ndelete all lines starting \"Balance C/F\"\ndelete all lines starting \"Current Balance\"\ndelete all lines containing \"Opening Balance\"\nignore footer below -678\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 94 245 338 400 455 530 => describe table false \"*Date[d MMM yyyy]\" Details - #Debit #Credit #Balance','2024-01-31 08:00:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10470,'Crédit_Agricole','$source = \"Crédit_Agricole\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Delete vertical text\ndelete rotated words\n\n// Get account number\n$accountNumber = get line containing \"Branch number\" => top => get line above => take last words 3 => take words 1 => get text\n\n// Get account name\n$accountName = get text in box 760 600 page.left 200 => take words 5 => get text\n\n// Parse dates in French\nset culture \"fr-FR\"\n\n// Get Statement_periods\n$periodFrom = get line containing \"SALDO INIZIALE\" => take words 1 => get date \"dd.MM.yy\"\n\n$periodTo = get last line containing \"SALDO FINALE\" => take words 1 => get date \"dd.MM.yy\"\n\n// Get opening and closing balances\ngo to page 1\n$openingBalance = get line containing \"SALDO INIZIALE\" => get words before \"SALDO\" => take last words 1 => get decimal\n\n$closingBalance = get last line containing \"SALDO FINALE\" => get words before \"SALDO\" => take last words 1 => get decimal\n\n\n// Get start of transactions table\ngo to page 1\n\n@transactionsTop = get line containing \"Date Value Debit\" => bottom => get line below => bottom => get line below\n\n\n// Get end of transactions table\n@transactionsBottom = get line containing \"SALDO FINALE\" => top => get line above\n\n\n// Remove unwanted lines that appear in middle of transactions\nignore header above 745\ndelete all lines starting \"Crédit Agricole FriulAdria\"\ndelete all lines starting \"01369030935, aderente\"\ndelete all lines starting \"Garanzia. Società soggetta\"\ndelete all lines starting \"Imposta di bollo assolta in\"\ndelete all lines containing \"Date Value Debit\"\n\nignore footer below 42\n\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 60 110 190 250 490 => describe table false \"*Date[dd.MM.yy]\" - #Debit #Credit Details','2024-01-31 08:00:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10471,'Santander_Investment Bank','$source = \"Santander_Investment Bank\"\n\n\n// Get account name & number\n$accountName = get text in box page.top 680 page.left page.middleX => get text\n$accountNumber = get line starting \"Account Number:\" => get words after \"Number:\" => take last words 1 => get text\n\n\n// Get period from/to\n@period = get line containing \"Statement Period :\" => get words after \"Period :\" => take words 3\n$periodFrom = take words @period 1 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Opening Balance:\" => get words after \"Opening Balance:\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" => take words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line containing \"Date Value Dt. Description\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"In case of query, please contact\" => top => get line above\n\n\n//ignore headers & footer\nget line containing \"Date Value Dt. Description\" => top => ignore header above\n\nignore footer below 83\n\n// Remove unwanted lines\ndelete all lines starting \"In case of query, please\"\ndelete all lines starting \"For further information about the compensation\"\ndelete all lines starting \"Date Value Dt.\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 85 125 280 395 485 550 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit[0,000.00] #Credit[0,000.00] #Balance','2024-01-31 08:00:34',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10472,'CitiBank_multiaccnt','$source = \"CitiBank_multiaccnt\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get account name\n$accountname = get text in box 710 678 0 page.middleX => get text\n\n// Get account number\n$accountnumber = get line containing \"Statement Period\" => top => get line above  => get text\n\n// Get start & end of saving table for account number\ngo to page 1\n@savingaccntnbr_top = get line starting \"SAVINGS ACTIVITY\" => if not found then blank => bottom => get line below\n@savingaccntnbr_bottom = get line starting \"SAVINGS ACTIVITY\" => if not found then blank => bottom => get line below => bottom => get line below\n@get_saving_accntnbr = get multi page table @savingaccntnbr_top @savingaccntnbr_bottom 40 360 565 => describe table false Details **TransactionType\n\n//go to page 1\n//@del_bottom = get line starting \"CITIBANK ACCOUNT AS\" => top\n//$del_textbox = delete text in box page.top @del_bottom page.left 335 => get text\n\n\n// Get statement period\ngo to page 1\n//@period = get line containing \"Statement Period\" => get words after \"Period\"\n@period = get line containing \"Statement Period\" => get words after \"Period\" => take last words 6\n$periodto = take last words @period 3 => get date \"MMM dd, yyyy\"\n$periodfrom = take words @period 2 => get date \"MMM dd\"\n\n\n@get_Checking_Table = get line starting \"CHECKING ACTIVITY\"\n// Get opening and closing balances\n$openingbalance = get line containing \"Beginning Balance:\" => get words after \"Beginning Balance:\" => take words 1 => get decimal\n$closingbalance = get last line containing \"Ending Balance:\" => get words after \"Ending Balance:\" => get decimal\n\n// get checking table account number\ngo to page 1\n@chk_accnbr_top = get line containing \"CHECKING ACTIVITY\" => bottom => get line below\n@chk_accnbr_bottom = get line starting \"CHECKING ACTIVITY\" => bottom => get line below => bottom => get line below\n@get_checking_accntnbr = get multi page table @chk_accnbr_top @chk_accnbr_bottom 40 360 565 => describe table false Details **TransactionType\n\ndelete all lines containing \"Ending Balance:\"\nignore header above 720\n// get checking table transactions\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Description\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line starting \"Total Subtracted/Added\" => top => get line above\n\ndelete all lines containing \"Date Description\"\n@checking_trns = get multi page table @transactionsTop @transactionsBottom 40 340 405 490 565 => describe table false Details *#Debit *#Credit Balance\ndelete all lines containing \"Ultimate Savings Account (USA)\"\ndelete all lines containing \"Beginning Balance:\"\n\n// Get start & end of saving table transactions\ngo to page 1\n@getsavinglast = get last line starting \"SAVINGS ACTIVITY\"\n@savingTop = get last line starting \"SAVINGS ACTIVITY\" => if not found then blank => bottom => get line below\n@savingBottom = get line starting \"CUSTOMER SERVICE INFORMATION\" => top => get line above\ndelete all lines containing \"Total Subtracted/Added\"\ndelete all lines containing \"based on Eastern Time\"\n\n@delTop1 = get line containing \"LOANS ACTIVITY\" => if not found then blank => bottom\n@delBottom1 = get line containing \"(v) - variable rate.\" => top\n$del3 = delete text in box @delTop1 @delBottom1 0 page.right => get text\ndelete all lines containing \"(v) - variable rate.\"\ndelete all lines containing \"LOANS ACTIVITY\"\n\n@saving = get multi page table @savingTop @savingBottom 40 340 405 490 => describe table false Details *#Debit *#Credit\n\n// Read the transactions\n$transactions = combine described tables @get_checking_accntnbr @checking_trns @get_saving_accntnbr @saving','2025-03-20 06:59:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10473,'TheHomeDepot_Card','$source = \"TheHomeDepot_Card\"\n$features = \"CREDIT_CARD\"\n$periodBufferdays = 14\n\nset negative marker \"CR\"\n\n$deletepages0 = delete all pages containing \"Important Information about\"\n$deletepages1 = delete all pages containing \"Information about Purchases and Grace Periods\"\n\n@firstTop = get line containing \"NOTICE: SEE REVERSE\" => top\ndelete text in box @firstTop page.bottom page.left page.right\n\ngo to page 1\n//Get Account details\n@accountDetailsbottom = get line containing \"Account Number:\" => bottom\n@accountDetails = get text in box page.top @accountDetailsbottom 400 page.right\n\n$accountNumber = get words after @accountDetails \"Account Number:\" => get text\n$accountName = get words before @accountDetails \"Account Number:\" => skip words 4 => get text\n\n//Get Balances\n@Summarytop = get line containing \"Summary of Account Activity\" => bottom\n@Summarybottom = get line starting \"New Balance\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 0 290\n\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => get decimal\n$closingBalance = get words after @Summary \"New Balance\" => get decimal\n\n//Get dates\n@Datestop = get line containing \"Statement Period\" => top\n@Datesbottom = get line containing \"Days in Billing Period\" => top\n@Dates = get text in box @Datestop @Datesbottom 295 page.right\n\n$periodFrom = get words after @Dates \"Statement Period\" => get words between \"from\" \"to\" => get date \"dd MMM yyyy\"\n$periodTo = get words after @Dates \"Statement Period\"  => take last words 3 => get date \"dd MMM yyyy\"\n\n//Get start and end of table\n@transactionsTop = get line starting \"Trans Date Posting Date\" => bottom => get line below\n\n//$delSummarytop = get line starting \"CREDIT CHARGE SUMMARY\" => top\n//$delSummarybottom = get line starting \"PURCHASE HISTORY\" => top\n$delSummarytop = get line containing \"CHARGE SUMMARY\" => top\n$delSummarybottom = get line containing \"CREDIT PLAN\" => bottom\n$delSummary = delete text in box $delSummarytop $delSummarybottom 0 page.right => get text\n\ngo to page 1\n@transactionsBottom = get last line starting \"PURCHASE HISTORY\" => top => get line above\n\ndelete all lines starting \"Page\"\ndelete all lines starting \"PAYMENTS, CREDITS, FEES AND ADJUSTMENTS\"\ndelete all lines starting \"CARD ENDING\"\ndelete all lines starting \"TOTAL CARD ENDING\"\ndelete all lines containing \"NOTICE: SEE REVERSE SIDE FOR\"\ndelete all lines containing \"Please detach this portion\"\ndelete all lines containing \"Trans Date Posting Date\"\ndelete all lines containing \"Past Due Balance\"\n\n// Ignore all content above vertical position 732 (PDF coordinate for header region)\nignore header above 732\n\n// Ignore all content below vertical position 209 (PDF coordinate for footer region)\n//ignore footer below 209\n\n//Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 85 138 379 520 580 => describe table false \"*Date[dd MMM yy]\" Details TransactionType #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 85 138 382 379 520 580 => describe table false \"*Date[dd MMM yy]\" TransactionType - Details #Credit','2025-10-29 06:17:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10474,'Central_National_Bank','$source = \"Central_National_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\ndelete rotated words\n\n// Get account number\n$accountnumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\n\n// Get account name\n$accountname = get text in box 620 590 130 page.middleX => take words 2 => get text\n\n// Get Period\n$periodfrom = get line containing \"Statement Dates\" => get words before \"thru\" => take last words 1 => get date \"M/dd/yy\"\n$periodto = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n$openingbalance = get line containing \"Previous Stmt Balance\" => get words after \"Previous Stmt Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Current Stmt Balance\" => get words after \"Current Stmt Balance\" => take words 1 => get decimal\n\n\n// Get start and end of table\n@transactionstop = get line containing \"Date Description Amount\" => bottom => get line below\n@lastTransaction = get last line containing \"Date Description Amount\"\n@transactionsbottom = get line above 20\n//@transactionsbottom = get line starting \"DATE BALANCE DATE\" => top => get line above => top => get line above\n\nignore header above 600\ndelete all lines containing \"OTHER DEDUCTIONS\"\ndelete all lines containing \"DEPOSITS AND OTHER ADDITIONS\"\ndelete all lines containing \"Date Description Amount\"\n\ngo to page 1\n//Check Table\n@Checktop = get line starting \"Date Check Amount\" => if not found then blank => bottom => get line below\n@Checkbottom = get line starting \"DATE BALANCE DATE\" => if not found then blank => top => get line above\n\ndelete all lines containing \"CHECKS CLEARED (continued)\"\ndelete all lines containing \"Checks Cleared (continued)\"\ndelete all lines containing \"Listed in numerical order\"\ndelete all lines containing \"(*) indicates gap in sequence\"\ndelete all lines containing \"Daily Ending Balance\"\ndelete all lines containing \"Date Check Amount\"\ndelete all lines containing \"DAILY BALANCE SUMMARY\"\n\n//Check Tables\n@Checklefttransactions = get multi page table @Checktop @Checkbottom 35 95 230 315 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n@CheckRighttransactions = get multi page table @Checktop @Checkbottom 300 370 505 650 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n\n//delete Check Table\ngo to page 1\n@ChecktopDel = get line starting \"CHECKS CLEARED\" => if not found then blank => top => get line at => top\ndelete text in box @ChecktopDel page.bottom page.left page.right\n\ngo to page 1\n@ChecktopDel2 = get line starting \"Checks Cleared\" => if not found then blank => top => get line at => top\ndelete text in box @ChecktopDel2 page.bottom page.left page.right\n\n// Delete Daily balance\ngo to page 1\n@DailybalTop = get line starting \"DATE BALANCE DATE\" => if not found then blank => top => get line at => top\ndelete text in box @DailybalTop page.bottom page.left page.right\n\ndelete all lines containing \"CHECKS CLEARED\"\ndelete all lines containing \"Checks Cleared\"\ndelete all lines starting \"Base Fee in Service Charge\"\n\n\n//75 coordinate of date is last,if increase then first word of detail get merge in date and make new row\n\n//@DbCrtransactions = get multi page table @transactionstop @transactionsbottom 15 75 62 510 650 => describe table false \"*Date[M/dd]\" - Details #Credit\n//@DbCrtransactions = get multi page table @transactionstop @transactionsbottom 15 76.50 62 510 650 => describe table false \"*Date[M/dd]\" - Details #Credit\n@DbCrtransactions = get multi page table @transactionstop @transactionsbottom 15 76.41 62 510 650 => describe table false \"*Date[M/dd]\" - Details #Credit\n$transactions = combine described tables @DbCrtransactions @Checklefttransactions @CheckRighttransactions','2025-02-25 07:19:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10475,'ValleyFirst_Bank','$source = \"ValleyFirst_Bank\"\n\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n\n// get account name\n$accountName = get line containing \"Valley First\" => bottom => get line below => take last words 3 => get text\n\ngo to page 1\n// get account number\n$accountNumber = get line containing \"Member Card Number\" => get words after \"Member Card Number\" => get text\n\n\n// get opening and closing balances\n\n$openingBalance = get line containing \"Date Description Amount\" => bottom => get line below => take last words 1 => get decimal\n\ngo to last page\n$closingBalance = get text in box page.top page.bottom 530 580 => take last words 1 => get decimal\n\n// get statement period\n$periodFrom = get text in box page.top page.bottom 32 93 => take last words 1 => get date \"dd-MMM-yyyy\"\n\ngo to page 1\n$periodTo = get line containing \"Date Description Amount\" => bottom => get line below => take words 1 => get date \"dd-MMM-yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line above 0\n\n// ignore footer header\nignore header above 710\nignore footer below 48\n\ndelete all lines containing \"Date Description Amount\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 100 400 490 590 => describe table false \"Date[dd-MMM-yyyy]\" Details #Credit *#Balance','2024-02-06 12:10:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10476,'BNP_Paribas_UK','$source = \"BNP_Paribas_UK\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get Account Name\n$accountName = get text in box 710 670 page.left page.middleX => take words 4 => get text\n\n// Get Period From/To\n$periodFrom = get line starting \"Statement from\" => get words after \"Statement from\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line starting \"Statement from\" => get words after \"to\" => take words 1 => get date \"dd/MM/yyyy\"\n\n// Get Account Number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\n\n// Get Opening/Closing Balance\n$openingBalance = get line starting \"Previous balance on\" => take last words 1 => get decimal\n$closingBalance = get last line starting \"Closing balance on\" => take last words 1 => get decimal\n\ngo to page 1\n// Get Top of the transaction table\n@transactionsTop = get line containing \"Post date Transaction details\" => bottom => get line below\n\nignore header above 602\ndelete all lines starting \"Previous balance on\"\ndelete all lines starting \"Previous page balance\"\ndelete all lines starting \"Post date Transaction details\"\ndelete all lines starting \"Total transactions amount\"\n\n// Get bottom of the transaction table@\n@transactionsBottom = get line containing \"Closing balance on\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 60 250 360 430 510 580 => describe table false \"*Date[dd/MM]\" Details - #Debit #Credit #Balance','2024-02-06 12:11:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10477,'ScotiaBank_PostedTrans','$source = \"ScotiaBank_PostedTrans\"\n$features = \"REVERSE_ORDER SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get Account name\n$accountname = \"Anonymous\"\n\n// Get Account number\n$accountnumber = get line containing \"Page created on\" => bottom => get line below => get words after \"-\" => get text\n\n// Get period From/To\n$periodfrom = get line containing \"range:\" => get words before \"to\" => take last words 1 => get date \"MM/dd/yyyy\"\n$periodto = get line containing \"range:\" => get words after \"to\" => take words 1 => get date \"MM/dd/yyyy\"\n\n\n// closing balance required even if SKIP_MISSING_CLOSING_BALANCE_CHECK is used\n$closingbalance = 0\n// REVERSE_ORDER feature swaps opening/closing balance, so opening balace required too\n$openingbalance = 0\n\n@transactionsTop = get line starting \"Date Transaction description\" => bottom => get line below\n\n// delete extra lines\ndelete all lines containing \"scotiabank.com\"\ndelete all lines containing \"Account Activity\"\n\n@transactionsBottom = get last line starting \"Totals for\" => top => get line above\n\ngo to page 1\n@del1 = get line containing \"range:\" => bottom\n$data = delete text in box page.top @del1 page.left page.right\ndelete all lines containing \"Transaction description\"\n\n// Read the Transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 120 425 510 570 => describe table false \"Date[MMM d,yyyy]\" Details *#Debit *#Credit','2024-02-16 04:37:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10478,'RBC_personal_banking','$source = \"RBC_personal_banking\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n\ndelete rotated words\n\n\ngo to page 1\n@get_line = get line containing \"0000*\"\n$Get_delete_barcode = delete text in box page.top page.bottom page.left 40 => get text\n\ngo to page 1\n@get_line1 = get line containing \"0000*\"\ndelete text in box page.top page.bottom page.left 40\n\ngo to page 1\n@get_line2 = get line containing \"0000*\"\ndelete text in box page.top page.bottom page.left 40\n\ngo to page 1\n@get_line3 = get line containing \"0000*\"\ndelete text in box page.top page.bottom page.left 40\n\ngo to page 1\n@get_line4 = get line containing \"0000*\"\ndelete text in box page.top page.bottom page.left 40\n\ndelete text in box on every page page.top page.bottom page.left 24\n\n\ngo to page 1\n$get_text = delete text in box on every page page.top page.bottom 590 700 => get text\n\n\n// get account name & account number\ngo to page 1\ndelete text in box page.top page.bottom page.left 40\n$accountName = get text in box 700 630 page.left page.middleX => take last words 5 => get text\n//$accountNumber = get line containing \"Your account number:\" => get words after \"number:\" => take words 1 => get text\n\n\n\n// Get statement period\ngo to page 1\n@period = get line containing \"account statement\" => bottom => get line below => get words after \"From\"\n$periodFrom =  take words @period 3 => get date \"MMMM d, yyyy\"\n$periodto = take last words @period 3 => get date \"MMMM d, yyyy\"\n\n@accountNumberTop = get line containing \"number:\" => top\n@accountNumberBottom = get line containing \"number:\" => bottom\n@accountNumberbox = get text in box @accountNumberTop @accountNumberBottom 510 600\n$accountNumber = get words after @accountNumberbox \"number:\" => get text\n\n//Get Opening & Closing balance\n$openingbalance = get line containing \"Date Description Withdrawals\" => bottom => get line below => take last words 2 => get decimal\n$closingbalance = get last line containing \"Closing Balance\" => take last words 2 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Description Withdrawals\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Closing Balance\" => bottom => get line above\n\n// remove header\nignore header above 655\n\n\n//remove footer\nignore footer below 95\n\n// delete extra words\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"Date Description Withdrawals\"\ndelete all lines containing \"Details of your account activity\"\n\n\n\n\ngo to page 1\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 73 60 300 390 500 593 => describe table false \"Date[d MMM]\" - Details **#Debit **#Credit #Balance','2024-05-14 10:48:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10479,'CIBC_US_French','$source = \"CIBC_US_French\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n\n// Parse dates in French\nset culture \"fr-CA\"\n\n// Get period from/to\n@info = get text in box page.top 580 380 page.right\n$periodFrom = skip words @info 1 => take words 2 => get date \"d MMM\"\n$periodTo = get words after @info \"au\" => take words 3 => get date \"d MMM yyyy\"\n\n// Get account number\n$accountNumber = get words after @info \"Numéro de compte\" => get text\n\n// Delete unwanted panel\n@deleteBottom = get line starting \"Détail de vos opérations\" => top\ndelete text in box page.top @deleteBottom 380 page.right\n\n// Get account name\n$accountName = get text in box 650 600 page.left page.right => get text\n\n// Get opening and closing balances\n\n//$openingBalance = get line starting \"Solde d\'ouverture le\" => take last words 3 => get decimal\n$openingBalance = get line starting \"Date Description Retraits ($) Dépôts ($) Solde\" => bottom => get line below => get words after \"Solde d\'ouverture\" => get decimal\n\n//$closingBalance = get line starting \"Solde de clôture le\" => take last words 3 => get decimal\n\n$closingBalance = get last line starting \"Solde de clôture\" => get words after \"Solde de clôture\" => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line \"Date Description Retraits ($) Dépôts ($) Solde ($)\" => bottom => get line below => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line starting \"Solde de clôture\" => top => get line above\n\n// Discard page header\nget last line starting \"Date Description Retraits ($) Dépôts ($) Solde ($)\" => bottom => get line below => bottom => ignore header above\n\n// Discard page footer\nignore footer below 50\n\n// Discard unwanted lines\ndelete all lines starting \"(suite à la page suivante)\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 90 300 400 495 565 => describe table false \"Date[d MMM]\" Details #Debit #Credit *#Balance','2024-12-11 08:10:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10480,'BankOfMontreal_French_CreditCard','$source = \"BankOfMontreal_French_CreditCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodbufferdays = 15\r\n\r\nset negative marker \"CR\"\r\n\r\n// set culture\r\nset culture \"fr-CA\"\r\n\r\n// Get Account Name\r\n$accountName = get text in box 110 75 page.left page.middleX => take words 3 => get text\r\n\r\n// Get Card number\r\n$accountNumber = get line containing \"No de carte\" => get words after \"No de carte\" => take words 4 => get text\r\n\r\ngo to page 1\r\n@Summarytop = get line containing \"précédent,\" => top\r\n@Summarybottom = get line containing \"précédent,\" => bottom\r\n@Summaryright = get line containing \"Période couverte\" => get words before \"couverte\" => take last words 1 => left\r\n@Summary = get text in box @Summarytop @Summarybottom 0 @Summaryright\r\n\r\n// Get Statement periods\r\n$periodfrom = get words after @Summary \"précédent,\"  => take words 3 => get date \"d MMM yyyy\"\r\n$periodto = get line containing \"Période couverte\" => get words after \"Période couverte\" => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening/closing Balance\r\n$openingBalance = get words after @Summary \"précédent,\" => skip words 3 => get decimal\r\n$closingBalance = get last line containing \"Total pour le numéro de carte\" => get words after \"Total pour le numéro de carte\" => skip words 4 => get decimal\r\n\r\ngo to page 1\r\n// Get top of the transaction table\r\n@transactionsTop = get line containing \"D’AFFICHE DESCRIPTION MONTANT\" => bottom => get line below\r\n\r\n// delete some extra text\r\ndelete text in box page.top page.bottom 420 page.right\r\nignore header above 705\r\ndelete all lines containing \"(continued on next page)\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines containing \"Transactions depuis votre dernier\"\r\ndelete all lines containing \"ATION D’AFFICHE DESCRIPTION MONTANT\"\r\ndelete all lines containing \"No de carte :\"\r\ndelete all lines starting \"DATE DE\"\r\ndelete all lines starting \"L’OPÉR\"\r\ndelete all lines starting \"ATION DATE D’AFFICHE DESCRIPTION\"\r\n\r\n// Get bottom of the transaction table\r\n@transactionsBottom = get last line starting \"Sous-total pour\" => top => get line above\r\ndelete all lines starting \"Sous-total pour\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 88 130 350 420 => describe table false \"*Date[d MMM]\" - Details #Credit','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10481,'RegentBank','$source = \"RegentBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountName = get line containing \"Enclosures\" => bottom => get line below  => take words 2 => get text\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\n\n$PeriodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$PeriodTo = get last line containing \"Statement Dates\" => get words after \"Statement Dates\" => take last words 1 => get date \"M/dd/yy\"\n\ngo to page 1\n// Get start & end of Deposits and Credits table\n@creditsTop = get line containing \"*Deposits and Credits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line containing \"Electronic Items and Charges\" => if not found then blank => top => get line above\n\n// Get start & end of Electronic Items and Charges table\n@chargesTop = get line containing \"*Electronic Items and Charges\" => if not found then blank => bottom => get line below\n@chargesBottom = get line containing \"*Summary By Check Number\" => if not found then blank => top => get line above\n\n// Get start & end of Checks Left table\n@checkLeftTop = get line containing \"Date Check # Amount\" => if not found then blank => bottom => get line below\n@checkLeftBottom = get line containing \"*Daily Balance Section\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of Checks Right table\n@checkRightTop = get line containing \"Date Check # Amount\" => if not found then blank => bottom => get line below\n@checkRightBottom = get line containing \"*Daily Balance Section\" => if not found then blank => top => get line above\n\n\ndelete all lines containing \"Deposits and Credits\"\ndelete all lines containing \"Electronic Items and Charges\"\ndelete all lines containing \"* Indicates Skip\"\ndelete all lines containing \"Summary By Check Number\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Date Check # Amount\"\n\n\nignore header above 372\n//ignore footer below 53\n\n@deposits = get multi page table @creditsTop @creditsBottom 5 60 300 470 => describe table false \"*Date[M/dd]\" Details #Credit\n\n@otherdebits = get multi page table @chargesTop @chargesBottom 5 60 300 470 => describe table false \"*Date[M/dd]\" Details #Debit\n\n@checksLeft = get multi page table @checkLeftTop @checkLeftBottom 5 55 120 242 => describe table false \"*Date[M/dd]\" ChequeNumber #Debit\n\n@checksRight = get multi page table @checkRightTop @checkRightBottom  260 295 370 495 => describe table false \"*Date[M/dd]\" ChequeNumber #Debit\n\n\ngo to page 1\n$transactions = combine described tables @deposits @otherdebits @checksLeft @checksRight','2024-02-26 14:32:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10482,'Novo','$source = \"Novo\"\n$features = \"NO_TRANSACTION_YEAR\"\ndelete rotated words\ndelete tiny words\n$accountName = get line containing \"Customer Info\" => bottom => get line below  => take words 2 => get text\n$accountNumber = get line containing \"Account Number\" => bottom => get line below  => take words 2 => get text\n\n$dlt = delete text in box page.top 570 page.left 425 => get text\n@GetPeriodFromText = get text in box 605 573 420 580\n//@PeriodFromText = get words after @GetPeriodFromText \"Statement Date\"\n$PeriodFrom = take words @GetPeriodFromText 3 => get date \"MMM dd, yyyy\"\n$PeriodTo = take last words @GetPeriodFromText 3 => get date \"MMM dd, yyyy\"\n\n\n$openingBalance = get line starting \"Starting Balance\" => bottom => get line below => take words 2 => get decimal\n$closingBalance = get line starting \"Starting Balance\" => bottom => get line below => take last words 2 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line starting \"Date Description Type\" => bottom => get line below\n\n@transactionsBottom = get last line starting \"Page\" => top => get line above\n\ndelete all lines containing \"Date Description Type\"\nignore footer below 42\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 80 415 490 570 => describe table false \"*Date[MMM dd]\" Details TransactionType #Credit','2024-02-26 14:33:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10483,'Aqua_CreditCard','$source = \"Aqua_CreditCard\"\n$features = \"CREDIT_CARD\"\n\n$periodbufferdays = 30\n\n// Get account name\n$accountName = get line containing \"Available to spend\" => bottom => get line below  => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 4 => get text\n\ngo to page 2\ndelete all lines containing \"Your monthly statement\"\n\n// Get dates and opening/closing balances\n$PeriodFrom = get line starting \"Opening Balance\" => bottom => get line below  => take words 3 => get date \"dd MMM yyyy\"\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$PeriodTo = get last line starting \"Your new balance\" => top => get line above => take words 3 => get date \"dd MMM yyyy\"\n$closingBalance = get last line containing \"Your new balance\" => get words after \"Your new balance\" => take last words 1 => get decimal\n\n//ignore footer below 150\ndelete all lines containing \"Your account in detail\"\n\ngo to page 1\n// Get top of the transaction table\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\n\n// Get bottom of the transaction table\n@transactionsBottom = get line starting \"Your new balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 500 580 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit','2025-01-23 08:25:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10484,'KeyBank_Card','$source = \"KeyBank_Card\"\n$features = \"CREDIT_CARD REVERSE_ORDER\"\n\n@accountDetailstop = get line containing \"Account Number:\" => top\n@accountDetailsbottom = get line containing \"Account Number:\" => bottom\n@accountDetails = get text in box @accountDetailstop @accountDetailsbottom 0 page.right\n\n$accountNumber = get words after @accountDetails \"Account Number:\" => get text\n\n@Summarytop = get line containing \"*Previous Balance\" => top\n@Summarybottom = get line containing \"Statement Closing Date\" => top\n@Summary = get text in box @Summarytop @Summarybottom 0 295\n\n$closingBalance = get words after @Summary \"*Previous Balance\" => get words between \"*Previous Balance\" \"Payments\" => get decimal\n$OpeningBalance = get words after @Summary \"*New Balance\" => get words between \"*New Balance\" \"Credit Limit\" => get decimal\n\n$accountName = get text in box @accountDetailsbottom @Summarytop 0 page.middleX => take words 6 => get text\n\n@Dates = get text in box @accountDetailsbottom @Summarytop page.middleX page.right\n\n$periodFrom = get words before @Dates \"through\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get words after @Dates \"through\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get start and end of tables\n@INTERESTTop = get line starting \"INTEREST CHARGED\" => if not found then blank => bottom => get line below\n@INTERESTBottom = get line starting \"Total Interest Adjustment for this Period\" => if not found then blank => top => get line above\n\n@FeesTop = get line starting \"Fees From\" => if not found then blank => bottom => get line below\n@FeesBottom = get line starting \"Total Fee Adjustment for this Period\" => if not found then blank => top => get line above\n\n@TransactionActivityTop = get line starting \"Transaction Activity\" => bottom => get line below\n@lastTranpage = get last line starting \"Date Effective Date Description\"\n@TransactionActivityBottom = get line above 0\n\ndelete all lines starting \"Date Effective Date Description\"\ndelete all lines starting \"Total Interest for this Period\"\ndelete all lines starting \"Total Fees for this Period\"\ndelete all lines starting \"No activity for this period\"\n\n//Read the transactions\n@INTEREST = get multi page table @INTERESTTop @INTERESTBottom 160 390 570 => describe table false Details *#Credit\n@Fee = get multi page table @FeesTop @FeesBottom 160 390 570 => describe table false Details *#Credit\n@TransactionActivity = get multi page table @TransactionActivityTop @TransactionActivityBottom 100 160 370 465 570 => describe table false \"*Date[MM/dd/yy]\" Details - #Debit\n\n$transactions = combine described tables @INTEREST @Fee @TransactionActivity','2024-03-11 10:52:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10485,'StandardBank_SouthAfrica_Privaat','$source = \"StandardBank_SouthAfrica_Privaat\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Parse amounts in  Afrikaans\nset culture \"af-AF\"\n\n// Get account name\n$accountName = get text in box 735 690 0 210 => get text\n\n// Get account number\n$accountNumber = get line containing \"Rekeningnommer\" => take last words 4 => get text\n\n// Get Period from and Period To\n$statementPeriod = get line starting \"Staat van\" => take last words 7\n$periodFrom = take words $statementPeriod 3 => get date \"dd MMMM yyyy\"\n@statementPeriodTo = get last line starting \"Staat van\" => take last words 7\n$periodTo = skip words @statementPeriodTo 4 => get date \"dd MMMM yyyy\"\n\n\ngo to page 1\n// Get start & end of transactions table\n@transactionsTop = get line starting \"SALDO OORGEBRING\"  => bottom => get line above\n\n// set english culture for amounts\nset culture \"en-US\"\n\ngo to page 1\n// Get opening balances\n$openingBalance = get line starting \"SALDO OORGEBRING\" => take last words 1 => get decimal\n\n// Get Closing Balance\ngo to last page\n@pageFooter = get last line starting \"## Hierdie fooie\" => top\n@infoLast = get text in box page.top @pageFooter 450 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\n\ngo to page 1\n@transactionsBottom = get last line starting \"## Hierdie fooie sluit\" => top => get line above\n\n// Discard page header\n\ngo to page 2\nget last line starting \"SALDO OORGEBRING\" => top => ignore header above\nget line starting \"Die Standard Bank van\" => top => ignore footer below\ndelete all lines starting \"## Hierdie fooie\"\ndelete all lines containing \"Verifieer asseblief alle transaksies\"\ndelete all lines containing \"asseblief ons webwerf by\"\ndelete all lines containing \"www.standardbank.co.za\"\n\n\n\ngo to page 1\n// Remove unwanted lines\ndelete all lines starting \"Besonderhede Diensgeld\"\ndelete all lines starting \"Krediete Datum Saldo\"\ndelete all lines containing \"Besonderhede Diensgeld Debiete Krediete Datum Saldo\"\ndelete all lines containing \"SALDO OORGEBRING\"\n\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 195 250 385 450 520 => describe table false Details - #Credit \"Date[MM dd]\" *#Balance','2024-03-11 10:52:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10486,'SumUp_Payments','$source = \"SumUp_Payments\"\n$periodBufferDays = 5\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get account name\n$accountName = get line starting \"Merchant ID\" => top => get line above => take words 2 => get text\n\n// Get period from/to\n$periodFrom = get line starting \"Time period\" => get words after \"Time period\" => take words 3 => take words 1 => get date \"dd-MM-yyyy\"\n$periodTo = get line starting \"Time period\" => get words after \"Time period\" => take words 3 => take last words 1 => get date \"dd-MM-yyyy\"\n\n// Get account No\n@AccNoTop = get line containing \"Payout No.\" => bottom\n@AccNobottom = get line containing \"Payouts received in\" => top\n$accountNumber = get text in box @AccNoTop @AccNobottom page.left page.right => get words after \"your bank account\" => take words 1 => get text\n\n// Get opening and closing balances\n$openingBalance = 0\n//$closingBalance = 0\n$closingBalance = get last line starting \"PAYOUT NO\" => bottom => get line below => take last words 1 => get decimal\n\n// Get Payout credit table\n//@CreditTop = get line starting \"TOTAL\"\n//@CreditBottom = get line starting \"TOTAL\"\n//$CreditTable = get multi page table @CreditTop @CreditBottom 290 320 490 560 => describe table false Details - *#Credit\n\ngo to page 1\n// Get Transaction debit table\n@transactionsTop = get line containing \"DATE & TIME TRANSACTION ID\" => bottom => get line below\n@transactionsBottom = get last line starting \"PAYOUT NO\" => top => get line above\n\n// Discard page footer\nignore footer below 30\n\ndelete all lines starting \"DATE & TIME TRANSACTION ID DESCRIPTION\"\ndelete all lines starting \"PAYOUT NO\"\ndelete all lines containing \"that are not yet paid out\"\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 130 270 490 560 => describe table false \"*Date[dd-MM-yyyy]\" - Details - #Debit','2024-04-30 08:21:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10487,'Clear_Bank','$source = \"Clear_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\n\n// Discard hidden text\ndelete white words\ndelete tiny words\n\n// Get account name\n$accountName = get line containing \"Account name\" => get words after \"name\" => get text\n\n// Get account number\n$accountNumber = get line containing \"Account number\" => get words after \"number\" => take words 1 => get text\n\n// Get period from/to\n$periodFrom = get line containing \"Statement period\" => get words after \"period\" => take words 2 => get date \"dd MMM\"\n$periodTo = get line containing \"Statement period\" => get words after \"period\" => take last words 3 => get date \"dd MMM yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Opening balance\" => bottom => get line below => take words 1 => get decimal\n$closingBalance = get line starting \"Opening balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Date Type Description\" => bottom => get line below\n\n@get_last = get last line containing \"Date Type Description\"\n@transactionsBottom = get line containing \"Closing balance\" => top => get line above\n\nignore header above 680\nignore footer below 90\n\ndelete all lines starting \"Date Type Description\"\ndelete all lines starting \"Your transactions\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 18 50 120 320 430 515 580 => describe table false \"Date[dd MMM]\" TransactionType Details #Debit #Credit *#Balance','2024-10-17 08:41:21',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10488,'CitizensBank','$source = \"CitizensBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n$accountName = get text in box 650 630  page.left page.middleX => take words 3 => get text\n\n// Get From/To period\n$periodFrom = get line starting \"Beginning\" => get words after \"Beginning\" => take words 3 => get date \"MMMM dd,yyyy\"\n$periodTo = get line starting \"through\" => get words after \"through\" => take words 3 => get date \"MMMM dd,yyyy\"\n\n// Get account number\n//$accountNumber = get line containing \"ACCOUNT ENDING\" => get words after \"ACCOUNT ENDING\" => get text\n@acctext = get line starting \"Balance Calculation\" => top => get line above\n$accountNumber = take last words @acctext 1 => get text\n\ngo to page 1\n// Get opening/closing balance\n//$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => get decimal\n//$closingBalance = get line starting \"Current Balance\" => get words after \"Current Balance\" => skip words 1 => get decimal\n\n@Summarytop = get line containing \"Previous Balance\" => top\n@Summarybottom = get line containing \"Current Balance\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 25 305\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Checks\" => get decimal\n$closingBalance = get words after @Summary \"Current Balance\" => skip words 1 => get decimal\n\n// Get checks table\n@checksTop = get line starting \"Check # Amount Date\" => if not found then blank => bottom => get line below\n@checksBottom = get line starting \"Debits **\" => if not found then blank => top => get line above\n\ndelete all lines containing \"Please See Additional Information\"\ndelete all lines ending \"Continued\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"**May include checks\"\ndelete all lines starting \"ATM/Purchases\"\ndelete all lines starting \"Date Amount Description\"\n\n@checkslefttable = get multi page table @checksTop @checksBottom 35 108 190 225 => describe table false  #ChequeNumber #Debit \"*Date[MM/dd]\"\n@checksrighttable = get multi page table @checksTop @checksBottom 240 330 400 430 => describe table false  #ChequeNumber #Debit \"*Date[MM/dd]\"\n\n// Get Credits table\n@credTop = get line starting \"Deposits & Credits\" => if not found then blank => bottom => get line below\n@credBottom = get line starting \"Daily Balance\" => if not found then blank => top => get line above\ndelete all lines containing \"Total Interest Paid\"\ndelete all lines containing \"Credits (Continued)\"\n@credTransactions = get multi page table @credTop @credBottom 35 90 155 440 => describe table false \"*Date[MM/dd]\" #Credit Details\n\ngo to page 1\n// Get Debits table\n@debitsTop = get line starting \"Debits **\" => bottom => get line below\n//@debitsBottom = get line starting \"Daily Balance\" => top => get line above\nget last line starting \"Debits (\"\n@debitsBottom = get line above 40\n\ndelete all lines starting \"Debits (Continued) **\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Other Debits (Continued)\"\ndelete all lines containing \"Date Amount Description\"\ndelete all lines containing \"MONEY MARKET ACCOUNT ENDING\"\n\n@depcredtop = get line starting \"Deposits & Credits\" => top\ndelete text in box @depcredtop page.bottom page.left page.right\n\n@dailyBaltop = get line starting \"Daily Balance\" => top\ndelete text in box @dailyBaltop page.bottom page.left page.right\n\n@debTransactions = get multi page table @debitsTop @debitsBottom 35 90 155 440 => describe table false \"*Date[MM/dd]\" #Debit Details\n\n// combining the transactions\n$transactions = combine described tables @debTransactions @credTransactions @checkslefttable @checksrighttable','2025-05-29 06:48:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10489,'AmericanExpress_Australia','$source = \"AmericanExpress_Australia\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\n// Transactions with CR text are negative\r\nset negative marker \"CR\"\r\n\r\n// Get account name\r\n$actop = get line starting \"Prepared for\" => bottom\r\n$acbottom = get line starting \"Prepared for\" => bottom => get line below => bottom\r\n$accountName = get text in box $actop $acbottom page.left 200 => get text\r\n\r\n// Get period from/to\r\n$periodFrom = get line starting \"New Payments\" => bottom => get line below => take words 2 => get date \"MMMM d\"\r\n$periodTo = get line starting \"Prepared for\" => bottom => get line below => get words before \"PAGE\" => take last words 3 => get date \"MMMM d,yyyy\"\r\n\r\ngo to page 1\r\n// Get account number\r\n$accountNumber = get line containing \"Closing Standard Balance\" => top => get line above => take last words 1 => get text\r\n\r\n// Get opening and closing balances\r\ngo to page 1\r\n@linedel = get line starting \"OPENING BALANCE\"\r\n@leftbal = left @linedel => add -20\r\n@topline = bottom @linedel\r\n@botline = bottom @linedel => get line below => bottom\r\ndelete text in box @topline @botline page.left @leftbal\r\n\r\ngo to page 1\r\n@bal = get line starting \"OPENING BALANCE\" => bottom => get line below\r\n$openingBalance = take words @bal 1 => get decimal\r\n@header = get line containing \"CLOSING BALANCE\"\r\n@closingBalancetop = get line containing \"CLOSING BALANCE\" => bottom\r\n@closingBalancebottom = get line containing \"CLOSING BALANCE\" => bottom => get line below => bottom\r\n@closingBalanceleft = get words after @header \"DEBITS\" => take words 1 => left => subtract 5\r\n@closingBalanceright = get words after @header \"CLOSING\" => take words 1 => right => add 20\r\n$closingBalance = get text in box @closingBalancetop @closingBalancebottom @closingBalanceleft @closingBalanceright => get decimal\r\n\r\ngo to page 1\r\n@del_top = get line containing \"Total New Payments\" => bottom\r\n@del_bottm = get line containing \"Total New Payments\" => bottom => get line below => bottom\r\n$Get_del_Text = delete text in box @del_top @del_bottm page.left page.right => get text\r\ndelete all lines starting \"Total New Payments\"\r\n\r\n@transactionsTop = get line starting \"New Payments\" => bottom => get line below\r\n\r\n// Get end of table\r\n@Navigate_Last = get last line starting \"TRANSACTION DATE TRANSACTION DETAILS\"\r\n@transactionsBottom = get line above 0\r\n\r\ndelete all lines starting \"New Standard Transactions for\"\r\ndelete all lines starting \"New Payments\"\r\ndelete all lines starting \"TRANSACTION DATE TRANSACTION DETAILS\"\r\ndelete all lines starting \"Card Number\"\r\ndelete all lines containing \"XXXX-XXXXXX-\"\r\ndelete all lines starting \"Prepared for\"\r\ndelete all lines starting \"Account Charges\"\r\ndelete all lines starting \"Total Account Charges\"\r\ndelete all lines starting \"Total of New Standard\"\r\ndelete all lines starting \"AUD 46.78 includes\"\r\ndelete all lines starting \"AUD 7.74 includes\"\r\ndelete all lines starting \"NEW ZEALAND DOLLAR\"\r\ndelete all lines containing \"includes conversion commission of AUD\"\r\ndelete all lines containing \"TRANSACTION DETAILS\"\r\n\r\nignore header above 715\r\nignore footer below 45\r\n\r\ngo to page 1\r\n@getfooter_top = get line starting \"Please check all transactions carefully\" => bottom\r\ndelete text in box @getfooter_top page.bottom page.left page.right\r\ndelete all lines starting \"Please check all transactions carefully and immediately\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 78 345 480 550 => describe table false \"*Date[MMMM d]\" Details - #Credit','2026-09-15 10:10:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10490,'Discover_Card','$source = \"Discover_Card\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n//Get Account Number\n$accountNumber = get line containing \"Account number ending in\" => get words after \"ending in\"  => take words 1 => get text\n\n//Get dates\n$periodFrom = get line starting \"Open Date:\" => get words between \"Open Date:\" \"Close\" => get date \"MMM d yyyy\"\n$periodTo = get line starting \"Open Date:\" => get words after \"Close Date:\" => get date \"MMM d yyyy\"\n\n//Get Balances\n@Summarytop = get line containing \"ACCOUNT SUMMARY\" => bottom\n@Summarybottom = get line starting \"New Balance\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 0 255\n\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n//$closingBalance = get words after @Summary \"New Balance\" => get decimal\n$closingBalance = get words after @Summary \"New Balance\" => take words 1 => get decimal\n\nignore header above 718\n\n//Get start and end of table\n@transactionsTop = get line starting \"Trans. Date Post Date\" => bottom => get line below\n\n//Get Account Name\n@accountnameTop = get line starting \"Trans. Date Post Date\" => bottom\n@accountnameBottom = get line starting \"Account number ending in\" => top\n$accountname = get text in box @accountnameTop @accountnameBottom 0 page.middleX => get text\n\n//Deleting Account Name to read the transactions\n$delete_accountname = get text in box @accountnameTop @accountnameBottom 0 page.middleX => get text\n\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines containing \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines containing \"Totals Year-to-Date\"\ndelete all lines containing \"TOTAL FEES CHARGED IN\"\ndelete all lines containing \"TOTAL INTEREST CHARGED IN\"\ndelete all lines starting \"Interest Charge Calculation\"\ndelete all lines starting \"Your Annual Percentage Rate (APR)\"\ndelete all lines starting \"Finance Charge Summary\"\ndelete all lines containing \"ANNUAL Periodic Transaction Fee\"\ndelete all lines containing \"Daily Periodic PERCENTAGE FINANCE\"\ndelete all lines containing \"RATES CHARGES\"\n\ndelete all lines containing \"Total of New Activity for\"\ndelete all lines containing \"NOTICE: SEE REVERSE SIDE FOR\"\ndelete all lines containing \"Trans. Date\"\ndelete all lines containing \"Account number ending in\"\nignore footer below 30\n\n//@transactionsBottom = get last line starting \"Finance Charge Summary\" => top => get line above\n@transactionsBottom = get last line starting \"Current Billing Period\" => top => get line above\n\n//Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 200 250 500 600 => describe table false \"Date[MMM d]\" Details *#Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 200 245 240 500 600 => describe table false \"Date[MMM d]\" - Details *#Credit','2025-02-25 07:19:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10491,'Lloyds_Classic_Confi','$source = \"Lloyds_Classic_Confi\"\n\nset negative marker \"DR\"\n\n// Get account name and number\n$accountnumber = get line containing \"Account no:\" => get words after \"Account no:\" => get text\n$accountname = get line containing \"Account no:\" => get words after \"Account no:\" => get text\n\n// Get period from/to\n$periodfrom = get line containing \"Date Activity Paid out Paid in Balance\" => bottom => get line below => take words 1 => get date \"ddMMMyy\"\n//$periodto =  get last line containing \"TOTAL PAYMENTS/RECEIPTS:\" => top => get line above => take words 1 => get date \"ddMMMyy\"\n//delete all lines ending \"Date issued:\"\n$periodto =  get last line containing \"Date issued:\" => take last words 1 => get date \"dd/MM/yyyy\"\n\n// Get opening and closing balance\n//go to page 1\n//$openingBalance = get line containing \"Date Activity Paid out Paid in Balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Activity Paid out Paid in Balance\" => bottom => get line below\n\n@balanceLeft = get line starting \"Date Activity Paid out Paid in Balance\" => get words before \"Balance\" => take last words 1 => right => add 12\n$balanceLeft = get line starting \"Date Activity Paid out Paid in Balance\" => get words before \"Balance\" => take last words 1 => right => add 12\n\n@openingBalTop = get line containing \"Date Activity Paid out Paid in Balance\" => bottom => get line below => top\n@openingBalBottom = get line containing \"Date Activity Paid out Paid in Balance\" => bottom => get line below => bottom\n$openingBalance = get text in box @openingBalTop @openingBalBottom @balanceLeft 550 => get decimal\n\n// Get end of table\n@transactionsBottom = get last line containing \"TOTAL PAYMENTS/RECEIPTS:\" => top => get line above\n\n//ignore header above 770\n\ndelete all lines containing \"Sheet:\"\ndelete all lines containing \"Date issued:\"\ndelete all lines starting \"Renewal date:\"\ndelete all lines starting \"Account overdraft:\"\n\ngo to page 1\n//$AcHoderName = get line containing \"Date Activity\" => top => get line above => get text\n//$AddressLine1 = get line containing \"account statement\" => top => get line above => get text\n$AddressLine2 = get line containing \"account statement\" => top => get line above => top => get line above => get text\n$AddressLine3 = get line containing \"account statement\" => top => get line above => top => get line above => top => get line above => get text\n$AccType = get line containing \"account statement\" => bottom => get line below => get text\n\n$AddressLine4 = get line containing \"Branch Name:\" => bottom => get line below => get text\n$AddressLine5 = get line containing \"Branch Name:\" => bottom => get line below => bottom => get line below => get text\n$AddressLine6 = get line containing \"Branch Name:\" => bottom => get line below => bottom => get line below => bottom => get line below => get text\n//$AddressLine7 = get line containing \"Branch Name:\" => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => get text\n//$AddressLine8 = get line containing \"Account\" => get words before \"Account\" => get text\n\n\n//delete all lines starting $AcHoderName\n//delete all lines starting $AddressLine1\ndelete all lines starting $AddressLine2\ndelete all lines starting $AddressLine3\ndelete all lines starting $AddressLine4\ndelete all lines starting $AddressLine5\ndelete all lines starting $AddressLine6\n//delete all lines starting $AddressLine7\n//delete all lines ending $AddressLine8\ndelete all lines starting $AccType\n\n\ndelete all lines containing \"Branch Name:\"\ndelete all lines containing \"Sort Code:\"\ndelete all lines containing \"Account no:\"\ndelete all lines ending \"no:\"\n\n//delete all lines containing \"BGC-Bank\"\ndelete all lines containing \"CSH-Cash\"\ndelete all lines containing \"EUR-Euro\"\ndelete all lines containing \"PAY-Counter\"\ndelete all lines containing \"PSV-Paysave\"\ndelete all lines containing \"SDR-Reversal\"\ndelete all lines containing \"SUR-Excess\"\ndelete all lines containing \"Management Reversal\"\ndelete all lines starting \"Reversal\"\n\n\ndelete all lines starting \"BUSINESS ACCOUNT\"\ndelete all lines starting \"Classification: Confidential\"\n\ndelete all lines containing \"ACCOUNT CHARGES FOR THE PERIOD\"\ndelete all lines starting \"O/DRAFT INTEREST\"\ndelete all lines starting \"RETURNED\"\ndelete all lines starting \"UNAUTH\'D BORR. FEE\"\ndelete all lines starting \"UNPAID LOAN\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"These charges will be debited\"\n\n\n//$clossingtop = get last line containing \"Date Activity\" => bottom\n//$closingBalance = get text in box $clossingtop 20 450 550 => take last words 1 => get decimal\n\n@lastfooter = get last line containing \"TOTAL PAYMENTS/RECEIPTS:\" => bottom\ndelete text in box @lastfooter 0 page.left page.right\n@lastpage = get last line containing \"TOTAL PAYMENTS/RECEIPTS:\" => top => get line above => top => get line above => top => get line above\n//$closingBalance = get text in box page.top 20 450 550 => take last words 1 => get decimal\n@closingBalTop = get text in box page.top 20 @balanceLeft 550 => take last words 1 => top => add 2\n@closingBalbottom = get text in box page.top 20 @balanceLeft 550 => take last words 1 => bottom => subtract 2\n$closingBalance = get text in box @closingBalTop @closingBalbottom @balanceLeft 550 => get decimal\n\n\ndelete all lines starting \"TOTAL PAYMENTS/RECEIPTS:\"\n\n//delete all lines containing \"account statement\"\n//delete all lines containing \"Date Activity\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 300 370