INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10492,'TESCOBank','$source = \"TESCOBank\"\n\n//Discard Annual statement top and bottom to fetch the same for Monthly statement\n@Annualstatementstop = get line containing \"Annual statement\" => bottom\n@Annualstatementsbottom = get line starting \"Your annual account summary\" => top\n$DeleteAnnualSummary = delete text in box @Annualstatementstop @Annualstatementsbottom 0 560 => get text\n\n//Get Summary\n@Summarytop = get line containing \"Monthly statement\" => bottom\n@Summarybottom = get line containing \"Statement date:\" => bottom => get line below => bottom\n\n//Get Account Name\n$accountName = get text in box @Summarytop @Summarybottom 0 250 => take words 6 => get text\n\n//Get dates and Account No.\n@Summary = get text in box @Summarytop @Summarybottom 250 560\n\n$accountNumber = get words after @Summary \"Account number:\" => get words between \"Account number:\" \"Statement date:\" => get text\n\n@period = take last words @Summary 7\n$periodFrom = take words @period 3 => get date \"d MMMM yyyy\"\n$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n//Get start and end of table\n@transactionsTop = get line starting \"Date Description Money in\" => bottom => get line below\n\n$OpeningBalance = get line containing \"BALANCE BROUGHT FORWARD FROM PREVIOUS STATEMENT\" => get words after \"BALANCE BROUGHT FORWARD FROM PREVIOUS STATEMENT\" => get decimal\n\ndelete all lines containing \"BALANCE BROUGHT FORWARD FROM PREVIOUS STATEMENT\"\ndelete all lines starting \"Date Description Money in\"\n\n$closingbalance = get last line containing \"END BALANCE\" => get words after \"END BALANCE\" => take words 1 => get decimal\n\n@transactionsBottom = get last line containing \"END BALANCE\" => top => get line above\n\nignore header above 810\nignore footer below 47\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 315 385 480 560 => describe table false \"*Date[d/MM/yy]\" Details #Credit #Debit #Balance','2024-05-08 13:58:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10493,'Kreissparkasse_MasterCard','$source = \"Kreissparkasse_MasterCard\"\n$features = \"CREDIT_CARD\"\n\n// Parse amount in German\nset culture \"de-DE\"\n\n// Get Period From/To\n$periodFrom = get line starting \"Ihre\" => get words before \"bis\" => take last words 1 => get date dd.MM.yyyy\n$periodTo = get line starting \"Ihre\" => get words after \"bis\" => take words 1 => get date dd.MM.yyyy\n\n// Get Account Number\n$accountNumber = get line containing \"Nummer:\" => get words after \"Nummer:\" => take words 4 => get text\n\n// Get Account Name\n$accountName = get line containing \"Karteninhaber:\" => get words after \"Karteninhaber:\" => take words 2 => get text\n\n// Get opening/closing balance\n$openingBalance = get line containing \"Saldo letzte Abrechnung\" => get words after \"Saldo letzte Abrechnung\" => take words 2 => get decimal\n$closingBalance = get line starting \"Neuer Saldo\" => get words after \"Neuer Saldo\" => take words 2 => get decimal\n\ngo to page 1\n// Get top of the transaction table\n@transactionTop = get line containing \"Beleg Buchung Verwendungszweck\" => bottom => get line below\n\ndelete all lines containing \"Saldo letzte Abrechnung\"\n\n// Get Bottom of the transaction table\n@transactionBottom = get line starting \"Neuer Saldo\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionTop @transactionBottom 40 80 120 530 582 => describe table false \"*Date[ddMMyy]\" - Details #Credit','2024-05-08 13:58:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10494,'BNP_Paribas_Bank_Polska','$source = \"BNP_Paribas_Bank_Polska\"\n$features = \"REVERSE_ORDER\"\n\nset culture \"pl-PL\"\n\n//Get Account details\n@Accounttop = get line starting \"Nazwa / Numer rachunku\" => bottom\n@Accountbottom = get line starting \"Nazwa / Numer rachunku\" => bottom => get line below => bottom\n$accountName = get text in box @Accounttop @Accountbottom 0 190 => get text\n\n@AccountNobottom = get line starting \"Nazwa firmy\" => top\n$accountNumber = get text in box @Accountbottom @AccountNobottom 0 190 => get text\n\n//Get Period and Balances\n@Summarytop = get line containing \"Saldo początkowe\" => top\n@Summarybottom = get line starting \"Saldo końcowe\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 0 200\n\n$periodFrom = get words after @Summary \"początkowe\" => take words 1 => get date \"dd.MM.yyyy\"\n$periodTo = get words after @Summary \"końcowe\" => take words 1 => get date \"dd.MM.yyyy\"\n\n$closingBalance = get words after @Summary \"początkowe\" => skip words 1 => get words before \"Saldo końcowe\" => get decimal\n$OpeningBalance = get words after @Summary \"końcowe\" => skip words 1 => take last words 4 => get decimal\n\n//Get start and end of table\n@transactionsTop = get line starting \"Lp. Data Kontrahent Opis Kwota\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line starting \"Niniejszy dokument sporządzono na podstawie art.\" => top => get line above\n\ndelete all lines containing \"Lp. Data Kontrahent\"\ndelete all lines containing \"Typ transakcji\"\nignore header above 762\nignore footer below 49\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 100 270 515 600 => describe table false \"*Date[dd.MM.yyyy]\" TransactionType Details #Credit','2024-05-08 13:58:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10495,'CIBC','$source = \"CIBC\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account number\n@accountDetailstop = get line containing \"ACCOUNT NUMBER\" => bottom\n@accountDetailsbottom = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => bottom\n$accountNumber = get text in box @accountDetailstop @accountDetailsbottom 380 500 => get text\n\n// Get account name\n$accountName = get text in box @accountDetailsbottom 650 0 page.middleX => take words 4 => get text\n\n// Get period from/to\n$periodTo = get line containing \"DATE DESCRIPTION DEBITS CREDITS\" => top => get line above => take last words 1 => get date \"yyyy-MM-d\"\n$periodFrom = get line containing \"BALANCE FORWARD\" => get words before \"BALANCE FORWARD\" => get date \"MMMd\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"BALANCE FORWARD\" => get words after \"BALANCE FORWARD\" => skip words 2 => get decimal\n\n@get_lastpage = get last line containing \"DATE DESCRIPTION DEBITS\"\n$closingBalance = get line starting \"THIS PAGE\" => take last words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"DATE DESCRIPTION DEBITS\" => bottom => get line below => bottom => get line below\n\ndelete all lines containing \"BALANCE FORWARD\"\n\n// Get end of table\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n$transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above => top => get line above => get text\n\ngo to page 1\n@descright = get line containing \"DATE DESCRIPTION DEBITS CREDITS BALANCE\" => get words before \"CREDITS\" => take last words 1 => left => subtract 25\n@debitright = get line containing \"DATE DESCRIPTION DEBITS CREDITS BALANCE\" => get words before \"CREDITS\" => take last words 1 => right => add 10\n@creditright = get line containing \"DATE DESCRIPTION DEBITS CREDITS BALANCE\" => get words before \"BALANCE\" => take last words 1 => right => add 15\n\n// Discard page header\nignore header above 615\n\n// Discard page footer\nignore footer below 50\n\n// Discard unwanted lines\ndelete all lines starting \"STARTING BALANCE\"\ndelete all lines starting \"THIS PAGE\"\ndelete all lines starting \"THIS STATEMENT\"\ndelete all lines containing \"DATE DESCRIPTION\"\ndelete all lines containing \"DEBITS CREDIT\"\ndelete all lines containing \"COUNT AMOUNT COUNT\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 20 60 100 350 420 515 600 => describe table false \"Date[MMMd]\" - Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 60 100 @descright @debitright @creditright 600 => describe table false \"Date[MMMd]\" - Details #Debit #Credit *#Balance','2025-08-20 07:26:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10496,'BankOfMontrealFrench','$source = \"BankOfMontrealFrench\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 30\n\nset culture \"fr-CA\"\n\n$periodto = get line starting \"Période terminée le\" => take last words 3 => get date \"d MMMM yyyy\"\n\n$periodfrom = get line containing \"Solde d\'ouverture\" => bottom => get line below => take words 2 => get date \"d MMMM\"\n$periodfrom00 = get line containing \"Solde d\'ouverture\" => bottom => get line below => take words 2 => get text\n\n$accountnumber = get line containing \"Date Description de votre compte\" => bottom => get line below => get words after \"#\" => get text\n$accountname = get text in box 645 620 page.left page.middleX => take words 2 => get text\n\ngo to page 1\n@openingbalanceText1 = get line containing \"Solde d\'ouverture\" => top => get line above => bottom\n@openingbalanceText2 = get line containing \"Solde d\'ouverture\" => bottom => get line below => top\n$openingbalance = get text in box @openingbalanceText1 @openingbalanceText2 480 550 => get decimal\n\n@closingbalance1 = get line containing \"Totaux à la fermeture\" => top => get line above => top\n@closingbalance2 = get line containing \"Totaux à la fermeture\" => top\n$closingbalance = get text in box @closingbalance1 @closingbalance2 480 550 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line containing \"Solde d\'ouverture\" => bottom => get line below\n@transactionsBottom = get last line containing \"Totaux à la fermeture\" => top => get line above\n\ngo to page 1\n@footerTop = get line starting \"Page\" => top\ndelete text in box on every page @footerTop page.bottom page.left page.right\n\ndelete all lines containing \"Nombre d\'artìcles traités\"\ndelete all lines containing \"Solde d\'ouverture\"\ndelete all lines starting \"Date Description de votre\"\ndelete all lines starting \"Compte d\'entreprise #\"\ndelete all lines starting \"Détails des transactions\"\ndelete all lines starting \"Suite à la page suivante\"\ndelete all lines containing \"les mouvements de votre compte\"\ndelete all lines starting \"Compte de chèques\"\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 90 300 400 470 560 => describe table false \"Date[d MMMM]\" Details #Debit #Credit *#Balance','2024-05-14 10:48:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10497,'MetroBank_InOut','$source = \"MetroBank_InOut\"\n$features = \"NO_OPENING_BALANCE REVERSE_ORDER\"\n$periodBufferDays = 31\n\n// Get account name\n$accountName = get line starting \"Account Type\" => get words after \"Account Type\" => get text\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n\n// Get period From/To\n$periodFrom = get line starting \"Transaction details\" => get words after \"from\" => take words 2 => get date \"ddMMMM\"\n$periodTo = get line starting \"Transaction details\" => take last words 3 => get date \"ddMMMMyyyy\"\n\n// Get top of the transaction table\n@transactionsTop = get line starting \"Date Details Transaction Type\" => bottom => get line below\n\n$closingBalance = take last words @transactionsTop 1 => get decimal\n\n@transactionsBottom = get last line starting \"Page\" => top => get line above\n\ngo to page 1\n//dynamic_coordinates\n$date_left = get line starting \"Date Details Transaction Type\" => get words before \"Details\" => left => subtract 7\n$Details_right = get line starting \"Date Details Transaction Type\" => get words before \"Transaction\" => take last words 1 => left => subtract 20\n$detail_right = get line starting \"Date Details Transaction Type\" => get words before \"Type\" => take last words 1 => left => subtract 9\n$TransactionType_right = get line starting \"Date Details Transaction Type\" => get words before \"In(\" => take last words 1 => right => add 32\n$In_right = get line starting \"Date Details Transaction Type\" => get words after \"In( £ )\" => take words 1 => left => subtract 4\n$out_right = get line starting \"Date Details Transaction Type\" => get words after \"Out( £ )\" => take words 1 => take words 1 => left => subtract 16\n$balance_right = get line starting \"Date Details Transaction Type\" => take last words 1 => right => add 5\n\n\n\ngo to page 1\ndelete all lines starting \"Page\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 105 240 365 415 460 525 => describe table false \"*Date[ddMMMyyyy]\" Details TransactionType #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom $date_left $Details_right $detail_right $TransactionType_right $In_right $out_right $balance_right => describe table false \"*Date[ddMMMyyyy]\" Details TransactionType #Credit #Debit #Balance','2025-08-20 07:24:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10498,'Revolut_Account_E-Money_AccNo','$source = \"Revolut_Account_E-Money_AccNo\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n//$accountname = get text in box 674 650 page.left page.middleX => get text\n@accountnametop = get text in box 720 650 page.left page.middleX => take words 1 => top => add 10\n@accountnameBottom = get text in box 720 650 page.left page.middleX => take words 1 => bottom => subtract 10\n$accountname = get text in box @accountnametop @accountnameBottom page.left page.middleX => get text\n\n$accountnumber = get line containing \"IBAN\" => get words after \"IBAN\" => take words 1 => get text\n\n//$openingbalance = get line starting \"Account (\" => get words after \")\" => take words 1 => get decimal\n$openingbalance = get line containing \"Product Opening balance\" => bottom => get line below => take last words 4 => take words 1 => get decimal\n\ndelete all lines starting \"For transactions to and from\"\ndelete all lines starting \"This has no impact on you\"\ndelete all lines starting \"to our customer support\"\ndelete all lines containing \"BIC\"\ndelete all lines containing \"Sort Code\"\n\n@closing_top = get last line containing \"Date Description Money\" => bottom\n@closing_bottom = get last line containing \"Report lost or stolen card\" => top\n$closingbalance = get text in box @closing_top @closing_bottom 480 565 => take last words 1 => get decimal\n\ngo to page 1\n@getperiod = get line containing \"transactions from\" => get words after \"from\"\n$periodfrom = take words @getperiod 3 => get date \"d MMMM yyyy\"\n\n$periodto = get last line containing \"transactions from\" => get words after \"from\" => take last words 3 => get date \"d MMMM yyyy\"\n\ngo to page 1\n$DebitRight = get line starting \"Date Description Money out Money in Balance\" => get words before \"Money in\" => take last words 2 => take words 1 => right\n$credi