e 1\n//deleted reverted transaction row only those who are merged with Personal and Group Vaults table\n@navigateto_perosonaltransaction = get line containing \"Personal and Group Vaults transactions\"\n@personal_top = get line containing \"Start date Description\" => if not found then blank => top => get line above => bottom => get line below => bottom\n$personal_top1 = get line containing \"Start date Description\" => if not found then blank => top => get line above => bottom => get line below => bottom => get line below => get text\n@personal_bottom = get line containing \"Personal and Group Vaults transactions\" => top\n$personal_bottom_01 = get line containing \"Personal and Group Vaults transactions\" => top\n$deleted_merged_transactions = delete text in box $personal_top @personal_bottom page.left page.right => get text\n\ndelete all lines starting \"Personal and Group Vaults €\"\n\n\ngo to page 1\n//$headTop1word = get line containing \"Sort Code\" => if not found then blank => top => get line above\n$PersonalHeadTop1 = get line containing \"Personal and Group Vaults transactions from\" => if not found then blank => top => get line above => bottom\n$PersonalHeadbottom1 = get line containing \"Personal and Group Vaults transactions from\" => bottom\n$P1 = delete text in box $PersonalHeadTop1 $PersonalHeadbottom1 385 800 => get text\n\n//$transactions = get multi page table @transactiontop @transactionbottom 30 90 320 385 480 565 => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit *#Balance\n\n$transactionMain = get multi page table @transactiontop @transactionbottom 30 320 385 565 => describe table false Details *#Debit *#Credit\n$transactions = combine described tables $transactions0 $transactionMain','2025-02-12 08:12:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10499,'RepublicBank_withSummary','$source = \"RepublicBank_withSummary\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get Account name\n$accountName = get text in box 682 640 page.left page.middleX => take words 3 => get text\n\n// Get Account number\n$accountNumber = get line starting \"ACCOUNT #:\" => get words after \"CHQ\" => take words 2 => take last words 1 => get text\n\n// Get opening/closing\n@openbaltext = get line starting \"Beginning Balance\" => bottom => get line below\n@closbaltext = get line starting \"Ending Balance\" => bottom => get line below\n$openingbalance = take last words @openbaltext 1 => get decimal\n$closingbalance = take last words @closbaltext 1 => get decimal\n\n// Get period From/To\n$periodFrom = take words @openbaltext 3 => take last words 1 => get date \"dd/MM/yyyy\"\n$periodTo = take words @closbaltext 3 => take last words 1 => get date \"dd/MM/yyyy\"\n\n// Get top and bottom of the transaction table\n@transactionsTop = get line starting \"Date Cheque # Description\" => bottom => get line below\n@transactionsBottom = get last line starting \"Page:\" => top => get line above\n\ngo to page 1\n// Delete some unwanted lines\nignore header above 615\ndelete all lines starting \"Date Cheque # Description\"\ndelete all lines starting \"Page:\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 70 120 330 420 510 => describe table false \"Date[dd/MM]\" TransactionType Details **#Credit #Balance','2024-05-23 06:57:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10500,'RBC_VisaCard_French','$source = \"RBC_VisaCard_French\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n\n// Parse dates in French\nset culture \"fr-CA\"\n//set culture \"fr-BE\"\n//set culture \"fr-CH\"\n//set culture \"fr-FR\"\n//set culture \"en-GB\"\n\n// Transactions with ( or ) text are negative\nset negative marker \"(\"\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\n\ngo to page 1\n$accountNumberText = get line containing \"DESCRIPTION DE L\'OPÉRATION MONTANT\" => top => get line above\n$accountnumber = take words $accountNumberText 4 => get text\n\n@Cltop = get line containing \"DATE D\'ÉCHÉANCE MONTANT PAYÉ\" => top\n@clbottom = get line containing \"DATE D\'ÉCHÉANCE MONTANT PAYÉ\" => bottom\n@Clbox = get text in box @Cltop @clbottom 230 330\n$closingbalance = get words after @Clbox \"COURANT\" => take words 2 => get decimal\n\ngo to page 1\n//$periodfrom = get line containing \"Relevé du\" => get words between \"Relevé du\" \"au\" => take words 2 => get date \"dd MMM\"\n//$periodto = get last line containing \"Relevé du\" => get words after \"au\" => take words 3 => get date \"dd MMM yyyy\"\n\n$periodfrom = get line containing \"é du\" => get words between \"é du\" \"au\" => take words 2 => get date \"dd MMM\"\n$periodto = get line containing \"é du\" => get words after \"au\" => take words 3 => get date \"dd MMM yyyy\"\n\n\ngo to page 1\n$get_text = delete text in box on every page page.top page.bottom 385 page.right\n\n$accountname = get line containing $accountnumber => get words before $accountnumber => get text\n\n@d1 = get line containing \"Relevé du\" => top => get line above => get text\n\ngo to page 1\n//$openingbalance = get line containing \"VÉ PRÉCÉDENT\" => get words after \"VÉ PRÉCÉDENT\" =>  take words 1 => get decimal\n$openingbalance = get line containing \"VÉ PRÉCÉDENT\" => get words after \"VÉ PRÉCÉDENT\" => get decimal\n\nignore header above 610\n\ngo to page 1\n@transactionsTop = get line containing \"DE L\'OPÉRATION MONTANT\" => bottom => get line below\n\n//@transactionsBottom = get last line containing \"SOUS-TOTAL DES OPÉRATIONS POUR LE MOIS\" => bottom => get line below\n@transactionsBottom = get last line starting \"SOLDE \" => top => get line above\n\ngo to page 1\ndelete text in box 190 page.bottom page.left page.right\ndelete all lines containing \"DATE D\'ÉCHÉANCE MONTANT PAYÉ\"\n\ndelete all lines containing \"CENTRE DES PAIEMENTS DE CARTES DE CRÉDIT\"\ndelete all lines containing \"C.P. 4016, SUCCURSALE\"\ndelete all lines containing \"suite\"\ndelete all lines containing \"SOUS-TOTAL DES OPÉRATIONS POUR LE MOIS\"\ndelete all lines containing \"SOUS-TOTAL\"\ndelete all lines containing \"SOLDE COURANT\"\ndelete all lines containing \"SOLDE DU RELEVÉ PRÉCÉDENT\"\ndelete all lines containing \"DE L\'OPÉRATION MONTANT\"\ndelete all lines containing \"Avion® VisaJ\"\ndelete all lines containing \"Façons rapides, pratiques\"\ndelete all lines containing \"RBC Banque en direct\"\ndelete all lines containing \"RBC0190000_5058348_036-175421\"\ndelete all lines containing \"DANRO ENTREPRENEUR PEINTRE\"\ndelete all lines containing \"DANIEL IOAN ROGOZEA\"\ndelete all lines containing \"465 TOUZIN\"\ndelete all lines containing \"DORVAL QC H\"\ndelete all lines containing \"TORONTO, ONTARIO\"\n\ndelete all lines containing \"** ****\"\ndelete all lines starting @d1\ndelete all lines starting $accountname\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 90 125 306 300 360  => describe table false \"TransactionDate[dd MMM]\" \"Date[dd MMM]\" Details - *#Credit','2026-01-07 06:33:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10501,'TideBank_AlignedCenter_NarrowerGaps','$source = \"TideBank_AlignedCenter_NarrowerGaps\"\n$features = \"REVERSE_ORDER\"\n\n// Delete Insert history table\n@topHead = get line containing \"Interest rate history\" => top\n@bottomHead = get line containing \"Transactions\" => bottom\ndelete text in box @topHead @bottomHead page.left page.right => get text\n\ndelete all lines containing \"Any interest accrued\"\n\n// Get account number (Since Account Number field is mostly encrypted Hence passing the hardcoded value)\n$accountnumber = \"Incorrect_Account\"\n\n// Get account name\n//@Top = get line starting \"Account number:\" => top\n@Top = get line starting \"Account\" => top\n$accountname = get text in box page.top @Top page.middleX page.right => take words 6 => get text\n\n//Balances\n@balancespanelbottom =  get line containing \"Date Transaction type Details Paid in (£)\" => top\n@balancespanel = get text in box @Top @balancespanelbottom 270 560\n\n//$closingbalance = get words after @balancespanel \"Balance on\" => skip words 3 => get words before \"Total paid in\" => get decimal\n//$periodFrom = get words after @balancespanel \"Balance on\" => take words 3 => get date \"d MMM yyyy\"\n$closingbalance = get words after @balancespanel \"on\" => skip words 3 => get words before \"Total paid in\" => get decimal\n$periodFrom = get words after @balancespanel \"on\" => take words 3 => get date \"d MMM yyyy\"\n\n$openingbalance = take last words @balancespanel 1 => get decimal\n//$periodTo = get words after @balancespanel \"Total paid out\" => skip words 3 => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get words after @balancespanel \"Total paid out\" => get words after \"on\" => take words 3 => get date \"d MMM yyyy\"\n\n// Get start of table\n@transactionsTop = get line starting \"Date Transaction type Details Paid in (£) Paid out (£)\" => bottom => get line below\n\n@transCoor = get line starting \"Date Transaction type Details Paid in (£) Paid out (£)\"\n@CreditsCol = get words after @transCoor \"Date Transaction type Details\" => left\n@CreditsCol = subtract @CreditsCol 5\n\n@TypeCol = get words after @transCoor \"Date Transaction type\" => left\n@TypeCol = subtract @TypeCol 5\n\ngo to page 1\n$date_left = get line starting \"Date Transaction type\" => get words before \"Transaction\" => left => subtract 6\n$date_rght = get line starting \"Date Transaction type\" => get words before \"type\" => take last words 1 => left => subtract 8\n$paidIn = get line starting \"Date Transaction type\" => get words after \"in\" => take words 1 => right => add 7\n$paidOut = get line starting \"Date Transaction type\" => get words after \"out\" => take words 1 => right => add 5\n$balance = get line starting \"Date Transaction type\" => get words after \"Balance\" => right => add 13\n\n// Get end of table\n@translast = get last line starting \"Date Transaction type Details Paid in (£) Paid out (£)\"\n@transactionsBottom = get line above 0\n\n// discards\nignore header above 817\nignore footer below 82\ndelete all lines containing \"Date Transaction type Details Paid in (£)\"\ndelete all lines starting \"To be billed on or after\"\ndelete all lines containing \"Transaction fees for this period\"\ndelete all lines starting \"Your Tide account is a bank account provided by\"\ndelete all lines starting \"Bank account legal\"\ndelete all lines containing \"The deposit account is attached to a card issued\"\ndelete all lines containing \"The card is a prepaid electronic money product\"\ndelete all lines containing \"loads for the prepaid card funded\"\ndelete all lines containing \"tide.co/regulation\"\ndelete all lines containing \"Authority under registration number\"\ndelete all lines containing \"authorised by the\"\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 7 35 95 @TypeCol @CreditsCol 440 495 560 => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 7 $date_left $date_rght @TypeCol @CreditsCol $paidIn $paidOut $balance => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit #Balance','2025-07-24 06:51:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10502,'HorizonBank','$source = \"HorizonBank\"\n\ndelete white words\ndelete tiny words\ndelete rotated words\n\n// Get Account Name\n$accountName = get text in box 616 590 page.left page.middleX => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account No.:\" => get words after \"Account No.:\" => take words 1 => get text\n\n// Get Period From/To\n//@periodfromtxt = get line containing \"Balance Forward From\" => get words after \"Balance Forward From\"\n//$periodFrom = take words @periodfromtxt 1 => get date \"MM/dd/yy\"\n@periodfromtxt = get line containing \"Category Number Amount\" => bottom => get line below\n$periodFrom = skip words @periodfromtxt 3 => take words 1 => get date \"MM/dd/yy\"\n\n@periodtotxt = get line containing \"Ending Balance On\" => get words after \"Ending Balance On\"\n$periodTo = take words @periodtotxt 1 => get date \"MM/dd/yy\"\n\n// Get opening/closing balance\n$openingBalance = take last words @periodfromtxt 1 => get decimal\n$closingBalance = take last words @periodtotxt 1 => get decimal\n\n//delete all lines starting \"Date Description\"\ndelete all lines containing \"Continued\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Statement Date:\"\n\n@credTypetop = get line containing \"Date Type Amount\" => if not found then blank => bottom => get line below\n@credTypebottom = get line containing \"Date Description Amount\" => top => get line above\n\n// Get credit table Top and Bottom\n@creditTop = get line containing \"Date Description Amount\" => if not found then blank => bottom => get line below\n@creditBottom = get line containing \"ELECTRONIC DEBITS\" => top => get line above\n\ndelete all lines starting \"Date Description\"\n\n// Get debit table Top and Bottom\n@debitsTop = get line containing \"ELECTRONIC DEBITS\" => bottom => get line below\n@debitsBottom = get line containing \"CHECKS\" => top => get line above\n\n// Get check table Top and Bottom\n@checkTop = get line containing \"Date Check # Amount\" => bottom => get line below\n@checkBottom = get line containing \"DAILY BALANCE SUMMARY\" => top => get line above\n\n@credTypeleft = get multi page table @credTypetop @credTypebottom 50 90 160 225 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n@credTypemiddle = get multi page table @credTypetop @credTypebottom 230 268 355 402 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n@credTyperight = get multi page table @credTypetop @credTypebottom 405 445 520 580 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n\n@credtrans = get multi page table @creditTop @creditBottom 0 90 505 595 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n@debittrans = get multi page table @debitsTop @debitsBottom 0 90 505 595 => describe table false \"*Date[MM/dd/yy]\" Details #Debit\n\n@checkleft = get multi page table @checkTop @checkBottom 15 58 130 195 => describe table false \"*Date[MM/dd/yy]\" #ChequeNumber #Debit\n@checkmiddle = get multi page table @checkTop @checkBottom 196 235 320 370 => describe table false \"*Date[MM/dd/yy]\" #ChequeNumber #Debit\n@checkright = get multi page table @checkTop @checkBottom 374 412 490 550 => describe table false \"*Date[MM/dd/yy]\" #ChequeNumber #Debit\n\n// Read the transactions\n$transactions = combine described tables @credTypeleft @credTypemiddle @credTyperight @credtrans @debittrans @checkleft @checkmiddle @checkright','2024-06-13 07:33:24',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10503,'BNP_BankOfTheWest','$source = \"BNP_BankOfTheWest\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//delete text in box on every page page.top page.bottom 0 35\ndelete text in box on every page page.top page.bottom 0 40\n\n// Get account number and account name\n//$accountNumber = get line containing \"ACCOUNT SUMMARY\" => top => get line above => top => get line above => take last words 1 => get text\n$accountNumber = get line containing \"BUSINESS CHECKING\" => get words after \"CHECKING\" => take words 1 => get text\n$accountName = get line containing \"ACCOUNT SUMMARY\" => top => get line above => take words 2 => get text\n\n// Get period from and period to\n$periodFrom = get line containing \"Account Statement\"  => bottom => get line below => take words 3 => get date \"MMMM d, yyyy\"\n$periodTo = get line containing \"Account Statement\"  => bottom => get line below => take last words 3 => get date \"MMMM d, yyyy\"\n\n//Get opening and closing balances\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\ndelete all lines containing \"Description\"\ndelete all lines containing \"Number Date paid Amount\"\ndelete all lines containing \"Date Amount\"\n\n@topfooter = get line starting \"bankofthewest.com\" => top\ndelete text in box on every page @topfooter page.bottom page.left page.right\n\n// Credit table\ngo to page 1\n@CreditTop = get line starting \"Credits\"  => if not found then blank => bottom => get line below\n//@CreditBottom = get line containing \"credits for a total of\" => top => get line above\n@CreditBottom =  get line starting \"Credits\" => if not found then blank => bottom => get break below => get line above\ndelete all lines containing \"credits for a total of\"\ndelete all lines containing \"credit for a total of\"\n$CreditTable = get multi page table @CreditTop @CreditBottom 35 80 145 550 => describe table false \"Date[MM/dd]\" *#Credit Details\n\n// Deposits table\ngo to page 1\n@DepositsTop = get line starting \"Deposits\" => if not found then blank =>  bottom => get line below\n//$DepositsBottom = get line containing \"deposits for a total of\" => top => get line above\n@DepositsBottom =  get line starting \"Deposits\" => if not found then blank =>  bottom => get break below => get line above\ndelete all lines containing \"deposit for a total of\"\ndelete all lines containing \"deposits for a total of\"\n$DepositsTableLeft = get multi page table @DepositsTop @DepositsBottom 35 80 140 200 => describe table false  \"Date[MM/dd]\" - *#Credit\n$DepositsTableMiddle = get multi page table @DepositsTop @DepositsBottom 220 285 340 400 => describe table false \"Date[MM/dd]\" - *#Credit\n$DepositsTableRight = get multi page table @DepositsTop @DepositsBottom 420 480 525 590 => describe table false \"Date[MM/dd]\" - *#Credit\n\n@topheader = get line starting \"ACCOUNT DETAIL\" => bottom\ndelete text in box on every page page.top @topheader page.left page.right\n\n// Withdrawals table\ngo to page 1\n@WithdrawalsTop = get line starting \"Withdrawals\" => bottom => get line below\n@WithdrawalsBottom = get line containing \"withdrawals for a total of\" => top => get line above\n$WithdrawalsTable = get multi page table @WithdrawalsTop @WithdrawalsBottom 35 80 145 550 => describe table false \"Date[MM/dd]\" *#Debit Details\n\n// Checks table\n@CheckTop = get line starting \"Checks Paid\" => if not found then blank => bottom  => get line below\n@CheckBottom = get last line containing \"paid for a total of\" => if not found then blank => top => get line above\ndelete all lines containing \"checks paid for a total of\"\ndelete all lines containing \"check paid for a total of\"\n$ChecksTableLeft = get multi page table @CheckTop @CheckBottom 35 80 140 200 => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n$ChecksTableMiddle = get multi page table @CheckTop @CheckBottom 220 285 340 400 => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n$ChecksTableRight = get multi page table @CheckTop @CheckBottom 420 480 525 590  => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n\n// Read the transactions\n$transactions = combine described tables $CreditTable $DepositsTableLeft $DepositsTableMiddle $DepositsTableRight $WithdrawalsTable $ChecksTableLeft $ChecksTableMiddle $ChecksTableRight','2025-06-25 11:52:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10504,'ScotiaBankCard','$source = \"ScotiaBankCard\"\n$features = \"CREDIT_CARD\"\n\ndelete white words\ndelete rotated words\ndelete tiny words\n\n@CNtext = get line containing \"Credit Card Statement Period\" => top => get line below\n\n// Get line containing Period From/To\n$periodFrom = get words before @CNtext \"-\" => take last words 2 => get date \"MMM dd\"\n$periodTo = get words after @CNtext \"-\" => take words 3 => get date \"MMM dd,yyyy\"\n\n// Get account number\n$accountNumber = take words @CNtext 1 => get text\n\n// Get account name\n@accnametxt = get line containing \"CARD HOLDER (PRIMARY) CARD NUMBER\" => top => get line below\n$accountName = take words @accnametxt 2 => get text\n\ngo to page 1\n// Get opening/closing\n$openingBalance = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\" => take words 1 => get decimal\n$closingBalance = get line containing \"NEW BALANCE\" => get words after \"NEW BALANCE\" => take words 1 => get decimal\n\n// Get Top of the Transaction table\n@transactionsTop = get line starting \"TRANSACTION DATE POSTING DATE REFERENCE\" => top => get line below\n\ndelete all lines starting \"TRANSACTION DATE POSTING DATE\"\ndelete all lines containing \"Credit Card Statement Period Pay\"\ndelete all lines containing \"Transactions Summary\"\ndelete all lines starting \"CARD HOLDER (PRIMARY) CARD NUMBER\"\ndelete all lines containing \"***\"\ndelete all lines starting \"TTD\"\n\n@transactionsBottom  = get line containing \"Scotia Caribbean Mobile\" => bottom => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 130 200 300 500 575 => describe table false \"Date[dd-MMM-yyyy]\" TransactionType Details *#Credit','2024-07-03 06:18:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10505,'RBC_Business','$source = \"RBC_Business\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//get account Name\n$accountName = get text in box 680 650 65 210 => take words 3 => get text\n\n//get Account Number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 2 => get text\n\n//get statement period\n@period = get line containing \"Business Loans\" => get words after \"For\"\n//$PeriodFrom = take words @period 3 => get date \"MMMM dd,yyyy\"\n//$PeriodTo = take last words @period 3 => get date \"MMMM dd,yyyy\"\n$PeriodFrom = take words @period 3 => get date \"MMMM d,yyyy\"\n$PeriodTo = take last words @period 3 => get date \"MMMM d,yyyy\"\n\ndelete all lines containing \"Opening Principal Balance (\"\n\n//get Opening and Closing Balance\n$openingBalance = get line containing \"Opening Principal Balance\" => get words after \"Opening Principal Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Closing Principal Balance\" => get words after \"Closing Principal Balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get start and end of table\n@transactionsTop = get line containing \"Transaction Amount Balance\" => bottom => get line below => bottom => get line below\n\n@transactionsBottom = get last line containing \"Closing Principal Balance\" => top => get line above\n\nget line starting \"Your Account Activity\" => top => ignore header above\ndelete all lines containing \"Opening Principal\"\ndelete all lines containing \"Transaction Amount Balance\"\ndelete all lines containing \"Interest Payment\"\ndelete all lines containing \"Insurance Payment\"\ndelete all lines containing \"Your Account Activity\"\ndelete all lines containing \"Page\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 58 100 155 300 480 500 570 => d