INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10506,'NavyFedrel_CreditUnion','$source = \"NavyFedrel_CreditUnion\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodbufferdays = 30\n\n// Get Account name\n$accountName = get text in box 642 620 345 413 => take words 3 => get text\n\n// Get Account number\n$accountNumber = get line starting \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 4 => get text\n\n// Get opening/closing balance\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Previous Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n// Get Period From/To\n$periodTo = get line containing \"Statement Closing Date\" => get words after \"Statement Closing Date\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodFrom = get line starting \"Trans Date Post Date Reference No.\" => bottom => get line below => take words 1 => get date \"MM/dd/yy\"\n\nremove page 2\n\ngo to page 1\ndelete all lines starting \"Visa Business\"\ndelete all lines containing \"Page\"\ndelete all lines starting \"PAYMENTS AND CREDITS\"\nignore header above 720\n\n// Get top of the credit transaction table\n@credTop = get line containing \"Reference No. Description Submitted By\" => bottom => get line below\n@credBottom = get last line starting \"TOTAL PAYMENTS AND CREDITS\" => top => get line above\n\ndelete all lines containing \"Reference No. Description Submitted By\"\n\n$credtrans = get multi page table @credTop @credBottom 115 160 370 480 550 => describe table false \"*Date[MM/dd/yy]\" TransactionType Details #Debit\n\ngo to page 1\n//@debTop = get line containing \"Reference No. Description Amount\" => bottom => get line below\n@debTop = get line containing \"Reference No. Description Amount\" => if not found then blank => bottom => get line below\n\n@deltext = get line containing \"Reference No. Description Amount\" => top => get line above => take words 2 => get text\ndelete all lines starting @deltext\n\n//@deltext2 = get line starting \"CARD LIMIT\" => top => get line above => take words 2 => get text\n//delete all lines starting @deltext2\n\ndelete all lines containing \"xxxx xxxx\"\ndelete all lines starting \"TRANSACTIONS\"\ndelete all lines starting \"PAYMENTS AND CREDITS\"\ndelete all lines containing \"Reference No. Description Amount\"\ndelete all lines starting \"CARD LIMIT\"\n\n@debbottom = get last line starting \"TOTAL New Activity for\" => top => get line above\n\ndelete all lines containing \"TOTAL New Activity for\"\n$debtrans = get multi page table @debTop @debbottom 115 160 480 550 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n\n// Get Top and Bottom of Fee table\n@FeeTop = get line starting \"FEE\" => if not found then blank => bottom =>  get line below\n@FeeBottom = get last line starting \"TOTAL FEES\" => if not found then blank => top => get line above\n$feetrans = get multi page table @FeeTop @FeeBottom 115 160 480 550 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n\ndelete all lines starting \"Description Amount\"\n\n// Get Top and Bottom of Interest table\n@InterestTop = get line starting \"INTEREST CHARGED\" => if not found then blank => bottom => get line below\n@InterestBottom = get last line starting \"TOTAL INTEREST\" => if not found then blank => top => get line above\n$InterestTrans = get multi page table @InterestTop @InterestBottom 115 160 480 550 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\n\n// Read the transactions\n$transactions = combine described tables $credtrans $debtrans $feetrans $InterestTrans','2025-05-29 06:49:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10507,'FlagstarBankUS','$source = \"FlagstarBankUS\"\n$features = \"NO_TRANSACTION_YEAR\"\n\nset negative marker \"-\"\n\n// Get Account Name\n$accountName = get text in box 675 640 page.left page.middleX => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\n\n// Get period From and To\n@periodtxt = get line containing \"ACCOUNT NUMBER\" => top => get line below\n$periodFrom = get words after @periodtxt \"PERIOD\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get words after @periodtxt \"PERIOD\" => take last words 1 => get date \"MM/dd/yy\"\n\n// Get Opening and Closing Balance\n@baltxt = get line starting \"Beginning Balance Deposits\" => top => get line below\n$openingBalance = take words @baltxt 1 => get decimal\n$closingBalance = take last words @baltxt 1 => get decimal\n\n// Credits transaction table\n@credTop = get line containing \"Post Date Description\" => top => get line below\n\nignore footer below 58\nremove page 2\nignore header above 702\ndelete all lines starting \"Deposits and Other Credits(Continued)\"\ndelete all lines starting \"DEPOSITS\"\ndelete all lines starting \"Trans\"\ndelete all lines containing \"Post Date Description\"\ndelete all lines starting \"Total deposits this period:\"\ndelete all lines starting \"Total electronic credits this period:\"\ndelete all lines starting \"Total other credits this period:\"\ndelete all lines starting \"No activity this statement period\"\ndelete all lines starting \"ELECTRONIC CREDITS\"\n\ngo to page 1\n@credBottom = get line starting \"Checks and Other Debits\" => if not found then blank => bottom => get line above\n//@credBottom = get line starting \"CHECKS CLEARED\" => if not found then blank => bottom => get line above\n@credtrans = get multi page table @credTop @credBottom 30 80 130 510 590 => describe table false \"Date[MM/dd]\" - Details *#Credit\n\n// Checks transaction table\n@checksTop = get line starting \"Checks and Other Debits\" => if not found then blank => top => get line below\n@checksbottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line above\ndelete all lines starting \"Check Nbr Date Amount\"\ndelete all lines starting \"CHECKS CLEARED\"\n\n@checkleft = get multi page table @checksTop @checksbottom 50 100 150 210 => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n@checkmiddle = get multi page table @checksTop @checksbottom 235 290 330 390 => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n@checkright = get multi page table @checksTop @checksbottom 420 470 520 575 => describe table false #ChequeNumber \"Date[MM/dd]\" *#Debit\n\n// Debits transaction table\n@debTop = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line below\n@debBottom = get last line starting \"Total other debits this period:\" => if not found then blank => bottom => get line above\n\ndelete all lines starting \"ELECTRONIC DEBITS\"\ndelete all lines starting \"OTHER DEBITS\"\ndelete all lines starting \"Total electronic debits this period:\"\n\n@debTrans = get multi page table @debTop @debBottom 30 80 130 510 590 => describe table false \"Date[MM/dd]\" - Details *#Debit\n\n// Combine and Read the Transactions\n$transactions = combine described tables @credtrans @checkleft @checkmiddle @checkright @debTrans','2024-07-03 06:20:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10508,'AIB_Transactions_Statement_REVERSE','$source = \"AIB_Transactions_Statement_REVERSE\"\n$features = \"NO_OPENING_BALANCE REVERSE_ORDER\"\n\n$accountName = get line starting \"Account Name\" => get words after \"Account Name\" => get text\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => get text\n\n@firstTransaction = get line starting \"Date Who Description Money Out Money In Balance\"\n@transactionsTop = get line starting \"Date Who Description Money Out Money In Balance\" => bottom => get line below\n\n// delete pending transaction\n@pendingbottom = get last line starting \"Pending\" => bottom\n@pendingtop = get line starting \"Pending\" => top\ndelete text in box @pendingtop @pendingbottom page.left page.right\n\n//set dynamic coordinates for debit/credit column\ngo to page 1\n$date_right = get line containing \"Date Who Description\" => get words after \"Date\" => left => subtract 5\n$who_right = get line containing \"Date Who Description\" => get words after \"Who\" => left => subtract 7\n$debit_left = get line containing \"Date Who Description\" => get words after \"Description\" => left => subtract 7\n$credit_right = get line containing \"Date Who Description\" => get words before \"Balance\" => take last words 1 => right => add 20\n$balance_lft = get line containing \"Date Who Description\" => get words before \"Balance\" => take last words 1 => right => add 13\n$balance_rght = get line containing \"Date Who Description\" => get words after \"Money In\" => take last words 1 => right => add 34\n\n\ngo to page 1\n//delete pending transaction for page 1\n@pendingbottom0 = get last line starting \"Pending\" => bottom\n@pendingtop0 = get line starting \"Pending\" => top\ndelete text in box @pendingtop0 @pendingbottom0 page.left page.right\n\n\n@periodtoTop =  bottom @firstTransaction => get line below => top\n@Pendinglinebottom = get text in box @periodtoTop 50 25 80 => take words 1 => top\ndelete text in box page.top @Pendinglinebottom page.left page.right\n\n\n//$periodTo = get text in box @periodtoTop 50 25 80 => take words 1 => get date \"ddMMyyyy\"\n$periodTo = get text in box @periodtoTop 50 25 $date_right => take words 1 => get date \"ddMMyyyy\"\n//$closingBalance = get text in box @periodtoTop 50 507 570 => take words 1 => get decimal\n//$closingBalance = get text in box @periodtoTop 50 507 580 => take words 1 => get decimal\n$closingBalance = get text in box @periodtoTop 50 $balance_lft $balance_rght => take words 1 => get decimal\n\ngo to last page\n@transactionsBottom = get line above 0\n\nignore footer below 50\ndelete all lines containing \"Date Who Description\"\ndelete all lines starting \"Pending\"\n\ngo to last page\n@test = get line above 0 => bottom\n\n//$periodFrom = get text in box page.top @test 25 80 => take last words 1 => get date \"ddMMyyyy\"\n$periodFrom = get text in box page.top @test 25 $date_right => take last words 1 => get date \"ddMMyyyy\"\n\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 390 515 507 570 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit - #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 390 515 507 580 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit - #Balance\n//$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 235 $debit_left $credit_right 507 580 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit - #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 $date_right $who_right $debit_left $credit_right 507 580 => describe table false \"*Date[ddMMyyyy]\" TransactionType Details #Credit - #Balance','2024-11-12 06:44:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10509,'BankOfAmerica_multi','$source = \"BankOfAmerica_multi\"\r\n\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n\r\n// Get account name\r\n$accountName = get text in box 635 610 page.left page.middleX => get text\r\n\r\n// Get period from/to (have to do extra check for to in case of OcTOber)\r\n@getPeriod = get line containing \"Your combined statement\" => bottom => get line below\r\n//$getPeriod = get line containing \"Your combined statement\" => bottom => get line below => get text\r\n$periodFrom = take words @getPeriod 4 => take last words 3 => get date \"MMMM d, yyyy\"\r\n$periodTo = take last words @getPeriod 3 => get date \"MMMM d, yyyy\"\r\n\r\n// Get account number\r\ngo to page 1\r\n@Summary_Page = get line containing \"Account summary\"\r\n@summaryLine = get line containing \"Account number\"\r\n$accountNumber = get words after @summaryLine \"Account number\" => get text\r\n\r\ngo to page 1\r\n// Get opening and closing balances (text changes so use lines below Your account summary)\r\n$openingBalance = get line starting \"Beginning balance on\" => skip words 6 => take words 1 => get decimal\r\n$closingBalance = get last line starting \"Ending balance on\" => skip words 6 => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@linetop = get line containing \"Your account has overdraft protection provided by deposit account number\" => top\r\n@linebottom = get line containing \"Your account has overdraft protection provided by deposit account number\" => top => subtract 22\r\ndelete text in box @linetop @linebottom page.left page.right\r\n\r\n// Get start & end of credits table\r\ngo to page 1\r\n@summary_navigate = get line containing \"Account summary\"\r\n//@transactionsTop = get line starting \"Deposits and other additions\" => if not found then blank => bottom => get line below => bottom => get line below\r\n//@transactionsTop1 = get line sta