ining \"Account summary\"\r\n//@get_bottom1 = get line ending \"Deposits and other additions\" => if not found then blank => top => get line above => top\r\n@get_bottom1 = get line ending \"Deposits and other additions\" => if not found then blank => top\r\n$get_bottom1_Text_3 = get line ending \"Deposits and other additions\" => if not found then blank => top => get line above => top\r\n$delete_summary_3 = delete text in box 715 @get_bottom1 page.left page.right => get text\r\n\r\n@summary_top = get line containing \"Beginning balance on\" => top => get line above => top\r\n@summary_bottom = get line containing \"Beginning balance on\" => top\r\n$chk_del = delete text in box @summary_top @summary_bottom page.left page.right => get text\r\n\r\ngo to page 1\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Total deposits\"\r\ndelete all lines starting \"Withdrawals and other\"\r\ndelete all lines starting \"ATM and debit\"\r\ndelete all lines starting \"Other subtractions\"\r\ndelete all lines starting \"Deposits and other\"\r\ndelete all lines starting \"Total ATM and debit\"\r\ndelete all lines starting \"Total other subtractions\"\r\ndelete all lines starting \"This page intentionally left blank\"\r\ndelete all lines containing \"Put your savings account to work\"\r\ndelete all lines containing \"There is no cost to upgrade and\"\r\ndelete all lines containing \"or to upgrade your account, please call us at\"\r\ndelete all lines containing \"an appointment online at bankofamerica.com/time.\"\r\ndelete all lines containing \"continued on the next page\"\r\ndelete all lines containing \"Date Transaction description\"\r\ndelete all lines containing \"Note your Ending Balance already reflects the subtraction\"\r\ndelete all lines starting \"Service fees\"\r\ndelete all lines starting \"Total service fees\"\r\ndelete all lines starting \"Put your savings account to work for you. As a\"\r\ndelete all lines starting \"Total withdrawals\"\r\n\r\n\r\ndelete all lines starting \"Ending balance on\"\r\ndelete all lines starting \"1380 3890 1062.\"\r\ndelete all lines starting \"Online and Mobile Banking.\"\r\ndelete all lines starting \"Your account has overdraft protection\"\r\ndelete all lines starting \"Your account is enrolled in overdraft protection\"\r\ndelete all lines containing \"protection preferences, including linked accounts,\"\r\ndelete all lines containing \"Braille and Large Print Request - You can request\"\r\ndelete all lines containing \"enter Visually Impaired Access from the home page\"\r\ndelete all lines containing \"Interest Paid Year To Date\"\r\ndelete all lines containing \"including by phone, email, and social media. Learn more\"\r\n\r\ndelete all lines starting \"Date Description\"\r\n//delete all pages starting \"This page intentionally left blank\"\r\n\r\ndelete all lines containing \"Our Deposit Agreement and Disclosures\"\r\ndelete all lines containing \"section of our Deposit Agreement at\"\r\n\r\ngo to page 1\r\n@FeesSummaryTop = get line containing \"Your Overdraft and NSF: Returned Item fees for this statement period\" => top\r\n@FeesSummaryBottom = get line containing \"Delivery of alerts may be affected or delayed\" => if not found then blank => top\r\ndelete text in box @FeesSummaryTop @FeesSummaryBottom page.left page.right\r\ndelete all lines containing \"Delivery of alerts may be affected or delayed\"\r\n\r\ndelete all lines containing \"Order foreign currency before you travel\"\r\ndelete all lines containing \"Use our Mobile Banking app\"\r\ndelete all lines containing \"delivered to your home\"\r\ndelete all lines containing \"Scan the code to learn more or visit\"\r\ndelete all lines containing \"Mobile Banking requires that you download\"\r\ndelete all lines containing \"data rates may apply.\"\r\n\r\ngo to page 1\r\n// get tables\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 85 553 534 580 => describe table false \"Date[MM/dd/yy]\" Details - *#Credit\r\n\r\n@first_table = get multi page table @transactionsTop1 @transactionsBottom1 0 553 530 580 => describe table false Details - *#Credit\r\n@second_table = get multi page table @transactionsTop2 @transactionsBottom2 0 553 530 580 => describe table false Details - *#Credit\r\n\r\n// get Ac no fortables\r\n@AC_NO1 = get multi page table @transactionAC_NO1 @transactionAC_NO1 0 553 => describe table false *Details\r\n@AC_NO2 = get multi page table @transactionAC_NO2 @transactionAC_NO2 0 553 => describe table false *Details\r\n\r\ngo to page 1\r\n// Read the transactions\r\n$transactions = combine described tables @AC_NO1 @first_table @AC_NO2 @second_table','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10510,'ChaseSavings_Multiaccount','$source = \"ChaseSavings_Multiaccount\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n$deleteleftpanel = delete text in box on every page page.top page.bottom 0 20 => get text\n\ndelete all lines starting \"*start*\"\ndelete all lines starting \"*end*\"\n\ngo to page 1\n$deletepanel2 = delete text in box on every page page.top page.bottom 530 700 => get text\n\ngo to page 1\n// Get account name\n$accountName = get text in box 650 628 page.left 230 => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"Primary Account:\" => get words after \"Primary Account:\" => take words 1 => get text\n\n// Get period From/To\n$periodFrom = get line containing \"through\" => get words before \"through\" => get date \"MMMM dd,yyyy\"\n$periodTo = get line containing \"through\" => get words after \"through\" => take words 3 => get date \"MMMM dd,yyyy\"\n\n// Get opening/closing balance\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance =  get last line starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n\ngo to page 1\ndelete text in box on every page page.top page.bottom 465 550\ndelete all lines containing \"Primary Account:\"\ndelete all lines containing \"TRANSACTION DETAIL\"\ndelete all lines containing \"CHECKING SUMMARY\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines starting \"AMOUNT\"\ndelete all lines containing \"through\"\ndelete all lines starting  \"Deposits and Additions\"\ndelete all lines starting  \"Electronic Withdrawals\"\ndelete all lines starting \"ATM & Debit Card Withdrawals\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Stop in today\"\ndelete all lines containing \"your balances to Chase today!\"\ndelete all lines starting \"Annual Percentage Yield\"\ndelete all lines starting \"Interest Paid\"\ndelete all lines starting \"Interest paid\"\ndelete all lines starting \"Your account ending in\"\n\ngo to page 1\n//@transactionsTop = get line containing \"CHASE TOTAL CHECKING\" => bottom => get line below\n@transactionsTop = get line containing \"Account Number:\" => bottom => get line below => top => get line above\n\n@transactionsBottom = get last line starting \"Ending Balance\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"TRANSACTION DETAIL\"\ndelete all lines containing \"WANT TO AVOID PAYING A MONTHLY\"\ndelete all lines containing \"A Monthly Service Fee\"\ndelete all lines containing \"this fee during any statement period\"\ndelete all lines containing \"Have electronic deposits made\"\ndelete all lines containing \"ACH network,\"\ndelete all lines containing \"Visa or Mastercard network\"\ndelete all lines containing \"(You did not have an electronic deposit\"\ndelete all lines containing \"(Your total electronic deposits\"\ndelete all lines containing \"statement)\"\ndelete all lines containing \"OR,\"\ndelete all lines containing \"Your lowest beginning day balance\"\ndelete all lines containing \"Your average beginning day balance\"\ndelete all lines containing \"(iii) third party services\"\ndelete all lines starting \"investments.\"\n\ndelete all lines containing \"monthly Service Fee\"\ndelete all lines containing \"average qualifying deposit\"\ndelete all lines containing \"(You do not have a qualifying Chase mortgage)\"\ndelete all lines containing \"CHASE PREMIER\"\ndelete all lines containing \"SAVINGS SUMMARY\"\ndelete all lines containing \"monthly service fee\"\ndelete all lines starting \"account.\"\ndelete all lines containing \"Talk to a banker about\"\n\ndelete all lines starting \"CHASE TOTAL CHECKING\"\ndelete all lines starting \"DATE DESCRIPTION\"\ndelete all lines containing \"fee during any statement period\"\ndelete all lines starting \"Ending Balance\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 32 422 480 445 550 => describe table false Details *#Credit - *TransactionType\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 416 480 445 550 => describe table false Details *#Credit - *TransactionType','2024-09-10 08:18:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10511,'HSBC_UK_Pound','$source = \"HSBC_UK_Pound\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Discard hidden text\ndelete white words\n\ndelete all pages containing \"Lost and stolen cards\"\ngo to page 1\n\n// Get account name and number\n@accountLine = get line starting \"Account Name\" => bottom => get line below\n$accountNumber = take last words @accountLine 2 => take words 1 => get text\n@accountNameTop = top @accountLine\n@accountNameRight = take last words @accountLine 3 => left\n@accountNameBottom = bottom @accountLine\n$accountName = get text in box @accountNameTop @accountNameBottom 0 @accountNameRight => get text\n\n@headerlineRight = take last words @accountLine 1 => left\n@NameLine = get text in box @accountNameTop @accountNameBottom 0 @headerlineRight => get text\n@transHeader = get line starting \"Account Name Sortcode\" => bottom => get line below => bottom => get line below => get text\n\n// Get period from\n@periodBottom = get line starting \"Account Name\" => top\n@periodTop = add @periodBottom 80\n//@period = get text in box @periodTop @periodBottom 0 page.middleX\n//$periodFrom = take words @period 2 => get date \"d MMMM\"\n\n//@periodFromtop = get line containing \"BALANCE BROUGHT FORWARD\" => top\n//$periodFrom = get text in box @periodFromtop 10 0 130 => take words 3 => get date \"dd MMM yy\"\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => take words 3 => get date \"dd MMM yy\"\n\n//$periodTo = take last words @period 3 => get date \"d MMMM yyyy\"\n\n\n// Discard the address as it interferes with the balance block\n@pointerbalance = get line containing \"Opening Balance\"\ndelete text in box page.top @periodTop page.left page.middleX\n\n// Get opening and closing balances\n@openingBalanceRaw = get line containing \"Opening Balance\" => skip words 2\n$openingBalance = get decimal @openingBalanceRaw\n$openingBalanceText = get text @openingBalanceRaw\n//@closingBalanceRaw = get line containing \"Closing Balance\" => skip words 2\n//$closingBalance = get decimal @closingBalanceRaw\n//$closingBalanceText = get text @closingBalanceRaw\n@balanceBroughtForwardRaw = get line containing \"BALANCE BROUGHT FORWARD\" => skip words 3\n$balanceBroughtForward = get decimal @balanceBroughtForwardRaw\n$balanceBroughtForwardText = get text @balanceBroughtForwardRaw\n\ndelete all lines starting \"Your HSBC\"\n// Get period to\n@periodtoBottom = get last line starting \"Account Name\" => top\n@periodtoTop = add @periodtoBottom 80\n$periodTo = get text in box @periodtoTop @periodtoBottom 0 page.middleX => take last words 3 => get date \"d MMMM yyyy\"\n\n\n// Discard the address as it interferes with the balance block\n@pointerclbalance = get last line containing \"Closing Balance\"\ndelete text in box page.top @periodTop page.left page.middleX\n@closingBalanceRaw = get last line containing \"Closing Balance\" => skip words 2\n$closingBalance = get decimal @closingBalanceRaw\n$closingBalanceText = get text @closingBalanceRaw\n\n\n// Get end of table before discarding marker text\n@transactionsBottom = get last line containing \"BALANCE CARRIED FORWARD\" => top => get line above\n\n// Get start of table before discarding marker text\n\ngo to page 1\n@transactionsTop = get line containing \"Date Payment type and details £ Paid out £ Paid in £ Balance\" => bottom => get line below\n@topblanklinetop = get line containing \"Date Payment type and details £ Paid out £ Paid in £ Balance\" => bottom\n@topblanklinebottom = get line containing \"BALANCE BROUGHT FORWARD\" => top\ndelete text in box @topblanklinetop @topblanklinebottom page.left page.right\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\n\n@dateCoor = get line containing \"Date Payment type\" => get words after \"Date\" => left\n@balanceCoor = get line containing \"Paid in £ Balance\" => take last words 1 => right\n@dateCoor = subtra