INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10532,'AIB_Historical_Transactions','$source = \"AIB_Historical_Transactions\"\n\n$features = \"NO_OPENING_BALANCE\"\n\n\nset negative marker \"-\"\n\n//get account name\n$accountName = get line starting \"Balance:\" => top => get line above => take words 2 => get text\n\n//get account number\n$accountNumber = get line starting \"Account Number\" => bottom => get line below => take words 1 => get text\n\n\n//set dynamic coordinates for getting whole transactions rows in main table\n$Date_left = get line containing \"Date Description Paid Out\" => get words before \"Description\" => left => subtract 2\n$Description_left = get line containing \"Date Description Paid Out\" => get words after \"Date\" => left => subtract 2\n$Description_right = get line containing \"Date Description Paid Out\" => get words after \"Description\" => left => subtract 10\n$Paidout_right = get line containing \"Date Description Paid Out\" => get words after \"Out\" => left => subtract 10\n$Paidin_right = get line containing \"Date Description Paid Out\" => get words before \"Balance\" => right => add 6\n$Balance_right = get line containing \"Date Description Paid Out\" => get words after \"In\" => right => add 6\n\n\n//get statement periodfrom\n$top_period = get line containing \"Date Description Paid Out\" => bottom\n$periodFrom = get text in box $top_period 0 $Date_left $Description_left => take words 1 => get date \"dd/MM/yyyy\"\n\ndelete all lines starting \"©\"\ndelete all lines starting \"Allied Irish Banks, p.l.c. is regulated\"\ndelete all lines starting \"https://onlinebanking.aib\"\ndelete all lines starting \"Page\"\n\n//get statement periodfrom\ngo to last page\n$periodTo = get text in box page.top 0 $Date_left $Description_left => take last words 1 => get date \"dd/MM/yyyy\"\n\n\ngo to page 1\n//get transaction table top\n@transactionsTop = get line containing \"Date Description Paid Out\" => bottom => get line below\n\ngo to last page\n\n//get transaction table bottom\n@transactionsBottom = get line above 0\n\n//get closing balance\n$closingBalance = get text in box page.top 0 $Paidin_right $Balance_right => take last words 1 => get decimal\n\n\ngo to page 1\n//get all transactions in main table\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Description_left $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"Date[dd/MM/yyyy]\" Details **#Debit **#Credit #Balance','2024-09-26 07:55:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10533,'TBKBank','$source = \"TBKBank\"\n\ndelete tiny words\ndelete rotated words\ndelete white words\n\n@TEXTBOXBottom = get line containing \"Summary of Accounts\" => top\n// Get account name\n$accountName = get text in box 700 @TEXTBOXBottom 0 348 => take words 3 => get text\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => get words before \"$\" => take last words 1 => get text\ngo to page 1\ndelete all lines ending \"Ending Balance\"\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\n@TEXTBOXBottom1 = get line containing \"Ending Balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom1 0 350\n\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\n\nremove page 2\ngo to page 1\n// Get start & end of Deposits table\n@DepositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@DepositsBottom = get line ending \"Electronic Credits\" => if not found then blank => top => get line above\n\n// Get start & end of credits table\n@creditsTop = get line starting \"Electronic Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line ending \"Other Credits\" => if not found then blank => top => get line above\n\n@creditsTop1 = get line starting \"Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom1 = get line ending \"Debits\" => if not found then blank => top => get line above\n\n\nignore header above 736\ndelete all lines starting \"Date Description\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Electronic Credits\"\n//delete all lines containing \"RETURNED STOP PAY ITEM\"\n\n\n@Deposits = get multi page table @DepositsTop @DepositsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@credits = get multi page table @creditsTop @creditsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@creditother = get multi page table @creditsTop1 @creditsBottom1 35 90 510 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n\n// Get start & end of debits table\n@debitsTop = get line starting \"Electronic Debits\" => bottom => get line below\n@debitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\ndelete all lines containing \"Other Debits\"\n\n@debits = get multi page table @debitsTop @debitsBottom 35 90 515 580 => describe table false \"Date[M/d/yyyy]\" Details *#Debit\n\n// Get start & end of cheques table\ngo to page 1\n@chequeTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ndelete all lines starting \"* Indicates skipped check number\"\ndelete all lines starting \"Check Nbr Date Amount\"\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 55 91 150 210 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n@chequeMiddle = get multi page table @chequeTop @chequebottom 210 273 335 410 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 410 459 515 580 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n\n$transactions = combine described tables @Deposits @credits @creditother @debits @chequeLeft @chequeMiddle @chequeRight','2025-05-29 06:48:57',0);
