INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10535,'River_citi_Bank','$source = \"River_citi_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 30\n\n// get account name\ngo to page 1\n$accountname = get text in box page.top 630 page.left page.middleX => get text\n\n//get account number\n$accountnumber = get last line containing \"Account Number\" => get words after \"Ending\" => take words 1 => get text\n\ngo to page 1\n// get period from & to\n@period = get line containing \"Statement Dates\"\n$periodfrom = get words after @period \"Statement Dates\" => take words 1 => get date \"M/d/yy\"\n$periodto = get words after @period \"Statement Dates\" => take words 3 => take last words 1 => get date \"M/d/yy\"\n\n// get opening and closing balance\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take last words 1 => get decimal\n\n// get transection top & bottom\ngo to page 1\n@transactiontop = get line containing \"Date Description Check\" => bottom => get line below\n\n//navigate to last transaction page\n@navigate_lastTransaction = get last line containing \"Date Description Check\"\n@transactionbottom = get line above 0\n\n//ignore header\nget last line containing \"ACTIVITY IN DATE ORDER\" => top => ignore header above\n\ngo to page 1\n//delete unwanted text or lines\ndelete all lines starting \"ACTIVITY IN DATE ORDER\"\ndelete all lines starting \"Date Description Check\"\ndelete all lines starting \"BUSINESS REG CHECKING\"\ndelete all lines starting \"- Overdraft\"\n\n// delete balance info table\ngo to page 1\n@top_info = get line starting \"DAILY BALANCE INFORMATION\" => top\n$delete_balnc = delete text in box @top_info page.bottom page.left page.right\n\n// delete check table\ngo to page 1\n@top = get line starting \"CHECKS IN NUMBER ORDER\" => top\n$delete_chk = delete text in box @top page.bottom page.left page.right\n\n// delete STATEMENT CODE SUMMARY table\ngo to page 1\n@top_SCS = get line starting \"STATEMENT CODE SUMMARY\" => top\ndelete text in box @top_SCS page.bottom page.left page.right\n\ndelete all lines starting \"STATEMENT CODE SUMMARY\"\ndelete all lines starting \"Code Description\"\ndelete all lines ending \"(Continued)\"\n\n// get all transactions\n$transactions = get multi page table @transactiontop @transactionbottom 30 60 290 390 480 => describe table false \"*Date[M/d]\" Details #Credit #Balance','2026-01-07 06:33:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10536,'CommonWealthBank_BSB_Amt_Bal','$source = \"CommonWealthBank_BSB_Amt_Bal\"\r\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\r\n\r\ngo to page 1\r\n// Get account name\r\n//$accountName  = get line containing \"Account name\" => get words after \"Account name\" => get text\r\n@accountDetailstop = get line containing \"Account Number\" => top => get line above => bottom => get line below => top\r\ngo to page 1\r\n@accountDetailsbottom = get line containing \"Account name\" => top\r\n$accountName = get text in box @accountDetailstop @accountDetailsbottom 0 page.middleX => take words 3 => get text\r\n\r\ngo to page 1\r\n// Get Period From\r\n@periodtxt = get line containing \"Date Transaction details Amount Balance\" => bottom => get line below\r\n$periodFrom = take words @periodtxt 3 => get date \"dd MMM yyyy\"\r\n\r\n// Get opening balance\r\n$openingBalance = take last words @periodtxt 1 => get decimal\r\n\r\n// Get Period To\r\n@top = get last line containing \"Date Transaction details Amount Balance\" => bottom\r\n@bottom = get line containing \"Any pending transactions\" => top\r\n$periodTo = get text in box @top @bottom 55 118 => take last words 3 => get date \"dd MMM yyyy\"\r\n\r\n// Get closing balance\r\n$closingBalance = get text in box @top @bottom 485 540 => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get top of transaction table\r\n@transactionsTop = get line containing \"Date Transaction details Amount Balance\" => bottom => get line below\r\n\r\n@TableHeader = get line containing \"Date Transaction details Amount Balance\"\r\n@DateLeft = get words before @TableHeader \"Transaction\" => take words 1 => left => subtract 2\r\n@DetailLeft = get words after @TableHeader \"Date\" => take words 1 => left => subtract 2\r\n@AmountLeft = get words after @TableHeader \"details\" => take words 1 => left => subtract 30\r\n@AmountRight = get words after @TableHeader \"details\" => take words 1 => right => add 2\r\n@BalanceRight = get words after @TableHeader \"Amount\" => take words 1 => right => add 10\r\n\r\n@footTop = get line starting \"Created\" => top\r\ndelete text in box on every page @footTop page.bottom page.left page.right\r\ndelete all lines starting \"Account Number\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Date Transaction details\"\r\n\r\n@transactionsBottom = get line containing \"Any pending transactions\" => top => get line above\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 55 118 400 485 540 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit #Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @DetailLeft @AmountLeft @AmountRight @BalanceRight => describe table false \"*Date[dd MMM yyyy]\" Details #Credit #Balance','2026-05-21 09:43:20',0);
