INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10538,'N26_Bank','$source = \"N26_Bank\"\n$periodBufferDays = 7\nset culture \"de-de\"\n\n//set negative marker \"DR\"\n//Get account name\n\n@TextBox = get text in box 80 0 0 350\n\n//Get accountName & accountNumber\n$accountName = take words @TextBox 2 => get text\n$accountNumber = get words after @TextBox \"IBAN:\" => take words 1 => get text\n\n//Get statement period\n@getperiod = get line containing \"Description Booking Date Amount\" => top => get line above\n$periodfrom = get words before @getperiod \"until\" => get date \"dd.MM.yyyy\"\n$periodto = get words after @getperiod \"until\" => get date \"dd.MM.yyyy\"\n\n//Get opening & closing balance\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => get decimal\n$closingbalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Description Booking Date Amount\" => bottom => get line below\n@transactionsBottom = get line containing \"Previous balance\" => top => get line above\n\nget line starting \"Description\" => bottom => ignore header above\nignore footer below 80\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 360 475 565 => describe table false Details \"Date[dd.MM.yyyy]\" *#Credit','2024-10-17 08:41:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10539,'AmericanExpress_AccountActivity_EarnedPeriod','$source = \"AmericanExpress_AccountActivity_EarnedPeriod\"\n\n// Get Account Name\n$accountName = get line containing \"Account Name\" => take last words 2 => get text\n\n// Get statement periods\n@periodTxt = get line containing \"Days in Statement Period\" => top => get line above\n$periodFrom = take last words @periodTxt 2 => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = take last words @periodTxt 1 => get date \"MM/dd/yyyy\"\n\n// Get Account number\n$accountNumber = get line containing \"Account Ending:\" => get words after \"Account Ending:\" => take words 2 => get text\n\n// Get opening/closing\n$openingBalance = get line containing \"Date Description Credits\" => bottom => get line below => take last words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get top of the table\n@transactionsTop = get line starting \"Date Description Credits Debits\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\ngo to page 1\n@topfooter = get line containing \"Continued on reverse\" => top\ndelete text in box @topfooter page.bottom page.left page.right\n\nget line starting \"Statement Date:\" => top => ignore header above\ndelete all lines containing \"Account Activity\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines starting \"Date Description Credits Debits\"\ndelete all lines containing \"Continued on next page\"\ndelete all lines containing \"American Express National Bank.\"\ndelete all lines containing \"Statement Date:\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 120 345 425 505 585 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit #Debit #Balance','2025-05-29 06:48:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10540,'NavyFederal_Bank','$source = \"NavyFederal_Bank\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\ndelete all lines containing \"Joint Owner(s):\"\ndelete all lines containing \"No Transactions This Period\"\ndelete all lines containing \"Continued from previous page\"\n@TextBoxtop = get line starting \"Statement of Account\" => bottom\n@TextBoxtbottom = get line starting \"Date Transaction Detail Amount($)\" => top\n@TextBox = get text in box @TextBoxtop @TextBoxtbottom 0 250\n@TextBoxPeriodTop = get line starting \"Statement of Account\" => top\n@TextBoxtPeriodbottom = get line starting \"Statement Period\" => bottom\n@TextBoxPeriod = get text in box @TextBoxtop @TextBoxtbottom 250 600\n\n//Get account name & number\n@accountNumbertop = get line starting \"Date Transaction Detail Amount($)\" => top => get line above => top\n@accountNumberbottom = get line starting \"Date Transaction Detail Amount($)\" => top => get line above => bottom\n$accountNumber = get text in box @accountNumbertop @accountNumberbottom page.left page.middleX => take last words 1 => get text\n$accountName = get text in box @accountNumbertop @accountNumberbottom page.left page.middleX => take last words 1 => get text\n\n//Get period\n$periodfrom = get words after @TextBoxPeriod \"Statement Period\" => take words 1 => get date \"MM/dd/yy\"\n$periodto = get words after @TextBoxPeriod \"-\" => take words 1 => get date \"MM/dd/yy\"\n\ngo to page 1\n//Get opening & closing balance\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => get decimal\n$closingbalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\n\ngo to page 1\n@TextBoxTop1 = get line containing \"Summary of your deposit accounts\" => bottom\n@TextBoxBottom1 = get line starting \"Totals\" => top\n$DeleteTextBox1 = delete text in box @TextBoxTop1 @TextBoxBottom1 page.left page.right => get text\n\ngo to page 1\n@SummaryTop = get line containing \"REMITTANCE RECEIVED AFTER STATEMENT PERIOD WILL APPEAR ON YOUR NEXT STATEMENT\" => top\ndelete text in box @SummaryTop page.bottom page.left page.right\n\n@transactionsTop = get line starting \"Checking\" => bottom => get line below\n@transactionsBottom = get line containing \"Ending Balance\" => top => get line above\n\n//get line starting \"Date Transaction Detail Amount($)\" => bottom => ignore header above\nignore header above 725\n//delete all lines containing \"Date Transaction Detail Amount($)\"\ndelete all lines containing \"Beginning Balance\"\nignore footer below 70\n\n// Read the transactions\n$transactions1 = get multi page table @transactionsTop @transactionsBottom 0 410 525 600 => describe table false Details **#Credit\ngo to page 1\n@DeleteBeginning1 = get line containing \"Beginning Balance\" => top\n@DeleteBeginning1Bottom = get line containing \"Beginning Balance\" => bottom\n$DeleteBeg1 = delete text in box @DeleteBeginning1 @DeleteBeginning1Bottom page.left page.right => get text\n\n@DeleteEnding1 = get line containing \"Ending Balance\" => top\n@DeleteEnding1Bottom = get line containing \"Ending Balance\" => bottom\n$DeleteEnd1 = delete text in box @DeleteEnding1 @DeleteEnding1Bottom page.left page.right => get text\n\n@transactionsTop1 = get line starting \"Savings\" => bottom => get line below\n@transactionsBottom1 = get line containing \"Ending Balance\" => top => get line above\n\n$transactions2 = get multi page table @transactionsTop1 @transactionsBottom1 0 410 525 600 => describe table false Details **#Credit\ngo to page 1\n@DeleteBeginning2 = get line containing \"Beginning Balance\" => top\n@DeleteBeginning2Bottom = get line containing \"Beginning Balance\" => bottom\n$DeleteBeg2 = delete text in box @DeleteBeginning2 @DeleteBeginning2Bottom page.left page.right => get text\n\n@DeleteEnding2 = get line containing \"Ending Balance\" => top\n@DeleteEnding2Bottom = get line containing \"Ending Balance\" => bottom\n$DeleteEnd2 = delete text in box @DeleteEnding2 @DeleteEnding2Bottom page.left page.right => get text\n\n$transactions = combine described tables $transactions1 $transactions2','2025-04-15 05:12:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10542,'KCB_Bank','$source = \"KCB_Bank\"\nset negative marker \"-\"\n\n//Get account number\n$accountName = get line starting \"Account:\" => get words after \"Account:\" => skip words 1 => take words 2 => get text\n$accountNumber = get line starting \"Account:\" => get words after \"Account:\" => take words 1 => get text\n\n//Get period From\n$periodfrom = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => get words before \"-\" => get date \"dd MMM yyyy\"\n\n//Get period To\nignore header above 5325\ndelete all lines containing \"= = =\"\ndelete all lines containing \"===\"\n@TextBoxtbottom = get last line containing \"BALANCE AT PERIOD\" => top => get line above => bottom\n$periodto = get text in box page.top @TextBoxtbottom 20 450 => take last words 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n//Get opening & closing balance\n$openingbalance = get line containing \"Balance at Period Start\" => get words after \"Balance at Period Start\" => take words 1 => get decimal\n$closingbalance = get last line containing \"Balance at Period End:\" => get words after \"Balance at Period End:\" => take words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"TXN DATE DESCRIPTION VALUE DATE\" => bottom => get line below\n@transactionsBottom = get last line containing \"BALANCE AT PERIOD E\" => top => get line above\n\ndelete all lines starting \"TXN DATE DESCRIPTION VALUE DATE\"\ndelete all lines containing \"Balance at Period\"\ndelete all lines containing \"BALANCE AT PERIOD\"\ndelete all lines containing \"ND:\"\n\ndelete all lines starting \"Statement Period\"\ndelete all lines starting \"Account\"\ndelete all lines starting \"Customer\"\ndelete all lines starting \"Account Statement\"\ndelete all lines starting \"Product\"\n\nignore footer below 330\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 450 1250 1850 2500 3000 3400 => describe table false \"Date[dd MMM yyyy]\" Details - #Debit #Credit *#Balance','2024-11-12 06:44:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10543,'BOK_Financial','$source = \"BOK_Financial\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete text in box on every page page.top page.bottom 0 50\n\ngo to page 1\nremove page 2\ngo to page 1\n\n@TextBoxtop = get line containing \"Direct Inquiries To:\" => top\n@TextBoxtbottom = get line starting \"BUSINESS ADVANTAGE\" => top\n@TextBox = get text in box @TextBoxtop @TextBoxtbottom 0 375\n\n//Get account number\n$accountName = take words @TextBox 3 => get text\n$accountNumber = get line containing \"PRIMARY ACCOUNT\" => bottom => get line below => take last words 1 => get text\n\n//Get statement period\n$periodfrom = get line containing \"Statement Period from\" => get words after \"from\" => get words before \"through\" => get date \"MM-dd-yy\"\n$periodto = get line containing \"Statement Period from\" => get words after \"through\" => get date \"MM-dd-yy\"\n\n//Get opening & closing balance\n$openingbalance = get line containing \"Starting Balance\" => get words after \"Starting Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\ngo to page 1\n@transactionsTop1 = get line starting \"DEPOSITS\" => bottom => get line below\n@transactionsBottom1 = get line starting \"WITHDRAWALS\" => top => get line above\n\ndelete all lines starting \"BUSINESS ADVANTAGE\"\ndelete all lines starting \"DEPOSITS\"\ndelete all lines starting \"Date Amount\"\ndelete all lines containing \"(cont.)\"\n\nignore header above 574\nignore footer below 60\n\ngo to page 1\n//Credit table\n@credits = get multi page table @transactionsTop1 @transactionsBottom1 60 120 475 580 => describe table false \"*Date[MM-dd]\" Details #Credit\n\n@transactionsTop2 = get line starting \"WITHDRAWALS\" => bottom => get line below\n@transactionsBottom2 = get line starting \"CHECKS\" => top => get line above\ndelete all lines starting \"WITHDRAWALS\"\n\n//Debit table\n@debits = get multi page table @transactionsTop2 @transactionsBottom2 60 120 475 580 => describe table false \"*Date[MM-dd]\" Details #Debit\n\n//Get start & end of cheques table\n@chequeTop = get line starting \"Date Number Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"DAILY ACCOUNT BALANCE\" => if not found then blank => top => get line above\n\ndelete all lines starting \"CHECKS\"\ndelete all lines containing \"Indicates a RETURNED CHECK\"\ndelete all lines containing \"break in check number\"\ndelete all lines containing \"Date Number Amount\"\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 60 130 210 310 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 310 380 460 560 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit\n\n//Combine all the tables\n$transactions = combine described tables @credits @debits @chequeLeft @chequeRight','2025-07-24 06:51:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10544,'AfrasiaBank','$source = \"AfrasiaBank\"\n\n$periodBufferDays = 10\n\n//get account name\n$accountName = get line containing \"ACCOUNT NAME:\" => get words before \"ACCOUNT NAME:\"  => take words 3 => get text\n\n//get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER:\" => get words before \"ACCOUNT NUMBER:\"  => take words 1 => get text\n\n//get statement period in one veriable\n@period = get line containing \"Statement between\" => get words after \"Statement between\" => take words 3\n\n//get period from\n$PeriodFrom = take words @period 1 => get date \"yyyy-MM-d\"\n\n//get period to\n$PeriodTo = take last words @period 1 => get date \"yyyy-MM-d\"\n\n//get opening balance\n$openingBalance = get line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n\n//get closing balance\n$closingBalance = get last line containing \"CLOSING BALANCE\" => take last words 1 => get decimal\n\n\n//get transactions from top\ngo to page 1\n@transactionsTop = get line starting \"Transaction Dat ValueDate \" => bottom => get line below => bottom => get line below\n\n//get transactions to bottom\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\n\n//navigate to page number 2 for removing header\ngo to page 2\nget line starting \"Transaction Dat ValueDate \" => top => ignore header above\n\n//delete extra lines or extra words\ndelete all lines starting \"Page Number\"\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"CLOSING BALANCE\"\ndelete all lines containing \"Transaction Dat ValueDate\"\n\n\n//get all transactions in single table\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 10 60 130 520 610 675 750 825 => describe table false \"*Date[d/MM/yyyy]\" - TransactionType Details #Debit #Credit #Balance','2024-11-12 06:44:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10545,'KeyBank_Privilege_Smart_Checking','$source = \"KeyBank_Privilege_Smart_Checking\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n//Get Account Number\n$accountNumber = get line containing \"Account number ending:\" => get words after \"Account number ending:\" => get text\n\n// Get account Name\n@TEXTBOXAcctBottom = get line containing \"Account Summary\" => top\n$accountName = get text in box 725 @TEXTBOXAcctBottom 0 175 => take words 2 => get text\n\n// Get Period From/To\n@statementPeriod = get line containing \"Account number ending:\" => bottom => get line below\n$periodFrom = take words @statementPeriod 3 => get date \"MMMM d yyyy\"\n$periodTo = take last words @statementPeriod 3 => get date \"MMMM d yyyy\"\n\n// Get Opening/Closing balance\n@TEXTBOXTop = get line containing \"Account Summary\" => bottom\n@TEXTBOXBottom = get line containing \"Ending Balance on\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 0 350\n\n$openingBalance = get words before @TEXTBOX \"Deposits (Money In)\" => take last words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take last words 1 => get decimal\n\nignore header above 750\nignore footer below 31\n\n// Get start & end of credits table\ngo to page 2\n@creditsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Total Deposits\" => if not found then blank => top => get line above\ndelete all lines containing \"Date Description Amount\"\n@credits = get multi page table @creditsTop @creditsBottom 0 70 450 590 => describe table false \"Date[MM/dd]\" Details *#Credit\n\ngo to page 2\n// Get start & end of debits table\n@debitsTop = get line starting \"Withdrawals\" => if not found then blank => bottom => get line below\n@debitsBottom = get last line starting \"Total Withdrawals\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Debit/ATM Withdrawals\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Other Withdrawals (continued)\"\ndelete all lines starting \"Withdrawals (continued)\"\ndelete all lines starting \"Total Debit/ATM Withdrawals\"\ndelete all lines starting \"Total Other Withdrawals\"\ndelete all lines starting \"Other Withdrawals\"\n\n@debits = get multi page table @debitsTop @debitsBottom 0 85 450 590 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n// Cheques table\n@chequeTop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"Total Checks\" => if not found then blank => top => get line above\n@cheques = get multi page table @chequeTop @chequebottom 25 75 175 300 => describe table false ChequeNumber \"Date[MM/dd]\" *#Debit\n\n// Fees table\n@FeesTop = get line containing \"Date Service Charge\" => if not found then blank => bottom => get line below\n@FeesBottom = get line containing \"Total All Fees and Charges\" => if not found then blank => top => get line above\ndelete all lines starting \"Date Service Charge\"\n@Fees = get multi page table @FeesTop @FeesBottom 0 70 450 590 => describe table false \"Date[MM/dd]\" Details *#Debit\n\n// combine the transactions\n$transactions = combine described tables @credits @debits @cheques @Fees','2024-11-21 06:59:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10547,'HSBC_UK_COMMERCIAL','$source = \"HSBC_UK_COMMERCIAL\"\n\n$accountName = get line containing \"HSBC UK COMMERCIAL\" => bottom => get line below => take words 1 => get text\n\n@topAcno = get line containing \"IBAN:\" => bottom => get line below => bottom\n@bottomAcno = get line containing \"BALANCE BROUGHT FORWARD\" => top => get line above => top => get line above => top\n@RightAcno = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => take words 1 => left => subtract 50\n\n//$accountNumber = get line containing \"CURRENT ACCOUNT\" => top => get line above => top => get line above  => take last words 2 => take words 1 => get text\n$accountNumber = get text in box @topAcno @bottomAcno page.middleX @RightAcno => take words 1 => get text\n\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => get words before \"BALANCE BROUGHT FORWARD\" => take words 1 => get date \"ddMMMyyyy\"\n$openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => get decimal\n\n$periodTo = get last line containing \"BALANCE CARRIED FORWARD\" => bottom => get line below => take last words 1 => get date \"ddMMMyyyy\"\n$closingBalance = get last line containing \"BALANCE CARRIED FORWARD\" => get words after \"BALANCE CARRIED FORWARD\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n//@transactionBottom = get line containing \"CLOSING AVAILABLE BALANCE\" => top => get line above\n@transactionBottom = get last line containing \"CLOSING AVAILABLE BALANCE\" => top => get line above\n\ngo to page 1\nget line containing \"BALANCE BROUGHT FORWARD\" => top => ignore header above\nignore footer below 90\n\ndelete all lines starting \"WITHDRAWALS\"\ndelete all lines starting \"DEPOSITS\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\n\ndelete all lines containing \"AS AT\"\ndelete all lines starting \"DEPOSITS\"\ndelete all lines containing \"CLOSING AVAILABLE BALANCE\"\ndelete all lines containing \"Rates Shown are applicable\"\ndelete all lines containing \"Credit Interest Rates\"\ndelete all lines containing \"All credit balances\"\n\ndelete all lines containing \"Important information about compensation\"\ndelete all lines containing \"Your deposit may be eligible\"\ndelete all lines containing \"eligible for compensation\"\ndelete all lines containing \"(via www.hsbc.co.uk)\"\ndelete all lines containing \"For further information about\"\ndelete all lines ending \"www.fscs.org.uk\"\n\n//$transactions = get multi page table @transactionsTop @transactionBottom 50 114 100 160 150 315 380 480 570 => describe table false \"Date[ddMMMyyyy]\"  - secondDate - Details **#Debit **#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionBottom 50 114 100 160 150 307 380 480 570 => describe table false \"Date[ddMMMyyyy]\"  - secondDate - Details **#Debit **#Credit #Balance','2025-04-15 05:12:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10548,'WebsterFive_Bank','$source = \"WebsterFive_Bank\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n//Get account number\n$accountNumber = get line c\nontaining \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//Get account name\n@AcctBottom = get line containing \"TRANSACTION INFORMATION\" => top\n$accountName = get text in box 640 @AcctBottom page.left 330 => take words 3 => get text\n\n//Get opening Balance\ngo to page 1\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n//Get periodTo\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n// Get start of table\n@transactionsTop = get line starting \"TRANSACTION INFORMATION\" => bottom => get line below\n\n@DelLeft = get line containing \"Statement Dates\" => get words before \"Dates\" => take last words 1 => left\n@DelTop = get line containing \"Statement Dates\" => top\n@DelBottom = get line containing \"Statement Dates\" => bottom\ndelete text in box @DelTop @DelBottom @DelLeft page.right\n\n// Get end of table\n@transactionsBottom = get line containing \"CHECKS IN NUMBER ORDER\" => top => get line above\n\n// ignore footer header\nignore header above 615\n\ngo to page 1\n\ndelete all lines containing \"GoChecking for Business\"\ndelete all lines containing \"Previous Balance\"\ndelete all lines containing \"Deposits/Credits\"\ndelete all lines containing \"Checks/Debits\"\ndelete all lines containing \"Service Charge\"\ndelete all lines containing \"Interest Paid\"\ndelete all lines containing \"Current Balance\"\ndelete all lines containing \"ACTIVITY IN DATE ORDER\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"(Continued)\"\ndelete all lines containing \"We have lending options\"\ndelete all lines starting \"Total For\"\ndelete all lines starting \"This Period\"\ndelete all lines starting \"Overdraft item\"\ndelete all lines starting \"Return item\"\n\n// Read the transactions\n@transactions1 = get multi page table @transactionsTop @transactionsBottom 30 300 425 590 => describe table false Details *#Credit #Balance\n\n//Account 2 Transactions\n@transactionsTop1 = get line starting \"Account Title:\" => bottom => get line below\nget last line starting \"GoSavings for Business\"\n@transactionsBottom1 = get line above 10\n\ndelete all lines containing \"GoSavings for Business\"\ndelete all lines containing \"Previous Balance\"\ndelete all lines containing \"Deposits/Credits\"\ndelete all lines containing \"Checks/Debits\"\ndelete all lines containing \"Service Charge\"\ndelete all lines containing \"Interest Paid\"\ndelete all lines containing \"Ending Balance\"\n\n//go to page 1\n@transactions2 = get multi page table @transactionsTop1 @transactionsBottom1 30 300 425 => describe table false Details *#Credit\n\n//combine transactions\n$transactions = combine described tables @transactions1 @transactions2','2024-12-10 06:38:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10549,'HSBC_Historic','$source = \"HSBC_Historic\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\nset negative marker \"D\"\n\n//delete white words  (tried for unwanted garbage value and spaces but not helpfulp)\n//delete tiny words\n//delete rotated words\n\n$accountname = get line containing \"Account Name\" => bottom => get line below => take words 1 => get text\n$accountnumber = get line containing \"Account Number\" => bottom => get line below => take last words 2 => take words 1 => get text\n\n$DelAcnumLine = get line containing \"Account Number\" => bottom => get line below => take last words 3 => take words 2 => get text\n\n$openingbalance = get line containing \"BALANCE BROUGHT FORWARD\" => take last words 1 => get decimal\n\n$periodfrom = get line containing \"BALANCE BROUGHT FORWARD\" => get words before \"BALANCE BROUGHT FORWARD\" => take words 1  => get date \"ddMMMyy\"\n\n$closingbalance =  get last line containing \"BALANCE CARRIED FORWARD\" => take last words 1 => get decimal\n\n$periodto =  get last line containing \"BALANCE CARRIED FORWARD\" => get words before \"BALANCE CARRIED FORWARD\" =>  take words 1  => get date \"ddMMMyy\"\n\ngo to page 1\n//Transaction Table\n@transactiontop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n@transactionbottom = get last line containing \"BALANCE CARRIED FORWARD\" => top => get line above\n\n\ndelete all lines containing \"Historic statements -\"\ndelete all lines starting \"Duplicate Statement\"\ndelete all lines starting \"Account Name\"\ndelete all lines starting \"Your Business\"\ndelete all lines containing \"Payment Type and Details\"\ndelete all lines containing $DelAcnumLine\n\ndelete all lines containing \"https://libap-eul-sy.systems.uk.hsbc\"\n\ngo to page 1\n$DelAddress = get line containing \"BALANCE CARRIED FORWARD\" => bottom => get line below => get text\ndelete all lines containing $DelAddress\n\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\n\nignore footer below 30\nignore header above 770\n\n//$transactions = get multi page table @transactiontop @transactionbottom 30 100 330 380 355 420 520  => describe table false \"*Date[ddMMMyy]\" Details #Debit - #Credit #Balance\n$transactions = get multi page table @transactiontop @transactionbottom 30 100 330 420 330 380 => describe table false \"*Date[ddMMMyy]\" Details TransactionType - #Debit','2024-12-10 06:38:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10550,'Agility_Bank','$source = \"Agility_Bank\"\n\n//Get account name\n@AccountNameBottom = get line containing \"Account Number:\" => top\n$accountName = get text in box page.top @AccountNameBottom 0 page.middleX => take words 4 => get text\n\n//Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\n\n//Get text box\n@TEXTBOXTop = get line containing \"Previous balance\" => top\n@TEXTBOXBottom = get line containing \"Ending balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 0 page.middleX\n\n//Get statement period\n$periodFrom = get line starting \"Date Description Debits Credits Balance\" => bottom => get line below => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get words after @TEXTBOX \"Ending balance\"  => take words 1 => get date \"MM/dd/yyyy\"\n\n//Get opening & closing balance\n$openingBalance = get words before @TEXTBOX \"Deposits\" => take last words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending balance\" => skip words 1 => take words 1 => get decimal\n\n//Get start & end of table\n@transactionsTop = get line starting \"Date Description Debits Credits Balance\" => bottom => get line below\nget last line starting \"Date Description Debits Credits Balance\"\n@transactionsBottom = get line above 10\n\n@ChecksTop = get line starting \"CHECKS\" => top\ndelete text in box @ChecksTop 0 0 page.right\n@DailyBalanceTop = get line starting \"DAILY BALANCE SUMMARY\" => top\ndelete text in box @DailyBalanceTop 0 0 page.right\n\n//Ignore footer header\nignore header above 620\ndelete all lines containing \"Date Description Debits\"\ndelete all lines containing \"Previous Balance\"\ndelete all lines containing \"CHECKS\"\ndelete all lines containing \"DAILY BALANCE SUMMARY\"\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 87 335 415 500 590 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance\n','2024-12-10 06:38:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10551,'FirstNationalBank_WithoutSummary_ScannedDescription','$source = \"FirstNationalBank_WithoutSummary_ScannedDescription\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Transactions with CR text are negative\nset negative marker \"Dr\"\n\n// Get account name\n$accountName = get text in box 720 660 0 400 => take words 5  => get text\n$accountnumber = get line starting \"Customer VAT Registration\" => take last words 1 => get text\n\n@periodText = get line starting \"Statement Period :\" => get words after \"Statement Period :\"\n$periodfrom = take words @periodText 3 => get date \"d MMMM yyyy\"\n$periodto = take last words @periodText 3 => get date \"d MMMM yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$closingBalance = get line starting \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\n\nset negative marker \"Cr\"\n\n// Get start of table\n//@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\n@transactionsTop = get line starting \"Transactions in\" => bottom => get line below\n\n// Discard page footer\nignore footer below 60\n\n// Get end of table\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\n\ndelete all lines starting \"ACCOUNT:\"\ndelete all lines starting \"Opening Balance\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"Tax Invoice/Statement Number :\"\ndelete all lines starting \"Transactions in\"\n\n// Delete Some new lines\ndelete all lines containing \"Reference Amount Fee\"\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Intercompany/ Intergroup\"\ndelete all lines starting \"Receipts Via Other Banks\"\ndelete all lines containing \"Electronic Collections\"\ndelete all lines containing \"FNB Customers\"\ndelete all lines containing \"Debit Orders\"\ndelete all lines starting \"Payments Through Stop Orders\"\ndelete all lines starting \"Bank Charges\"\ndelete all lines starting \"Miscellaneous\"\ndelete all lines starting \"Automated Teller Machine\"\ndelete all lines starting \"Bills And Foreign Exchange\"\ndelete all lines starting \"Point Of Sale\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 37 420 482 => describe table false \"*Date[dd MMM]\" Details #Debit\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 37 420 520 => describe table false \"*Date[dd MMM]\" Details #Debit','2024-12-10 06:38:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10552,'Danske_Bank_UK','$source = \"Danske_Bank_UK\"\n$periodBufferDays = 14\n\n// Delete vertical text\ndelete rotated words\n\n// Get account number\n$accountNumber = get line containing \"Amount withdrawn\" => take words 2 => get text\n\n// Get account name\n$accountName = get line starting \"Account holder:\" => skip words 2 => take words 4 => get text\n\n// Get period from/to\n@period = get line starting \"Period:\"\n$periodFrom = skip words @period 1 => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = take last words @period 1 => get date \"MM/dd/yyyy\"\n\n// get opening balance\n@openingBalanceText = get line starting \"Account:\" => get words after \"Balance at:\" => skip words 1\n$openingBalance = get decimal @openingBalanceText\n\n// get closing balance\n//@closingBalanceText = get line starting \" BIC/SWIFT\" => get words after \"Balance\" => take last words 1\n//$closingBalance = get decimal @closingBalanceText\n\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Booked and Text Amount\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Page\" => top => get line above\n\n\n\n// Discard page header\n//get last line starting \"Booked and Text Amount\" => bottom => ignore header above\n\ndelete all lines starting \"interest GBP\"\ndelete all lines starting \"interest EUR\"\ndelete all lines starting \"interest USD\"\ndelete all lines starting \"date\"\n\n// Discard page footer\nignore footer below 70\n\ngo to last page\n@closingBalnclist = get text in box page.top 0 440 580\n$closingBalance = take last words @closingBalnclist 1 => get decimal\n\n\n// Discard page header\nget last line starting \"Booked and Text Amount\" => bottom => ignore header above\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 320 440 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit #Balance','2025-02-12 08:13:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10553,'TriodosBank','$source = \"TriodosBank\"\n\nset negative marker \"-\"\n@accountNumText = get line starting \"Account number\" => bottom => get line below\n$accountNumber = take words @accountNumText 1 => get text\n$accountName = take words @accountNumText 3 => skip words 1 => get text\n\n$periodfromtext = get line starting \"Account number\" => bottom => get line below => take last words 2\n$periodfrom = take words $periodfromtext 1 => get date \"dd/MM/yyyy\"\n$openingBalance = take last words $periodfromtext 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Code Date Details Paid out\" => bottom => get line below\n//@transactionBottom = get line starting \"Overview of the charges\" => top => get line above\n@transactionsBottom = get last line containing \"Statement number Account type\" => top => get line above\n\ngo to page 1\n@periodToText = get line starting \"Statement number Account type\" => bottom\ndelete all lines containing \"Information on the Financial Services\"\n\ngo to page 1\n@top = get line starting \"Statement number Account type\" => bottom\n@bottom = get line starting \"Information on the\" => top\n$periodto = get text in box @top @bottom 385 520 => get date \"dd/MM/yyyy\"\n\ndelete all lines containing \"Continued on next page\"\n\n@topOver = get line containing \"Overview of the charges\" => bottom\n@bottomTotal = get line containing \"Total charge this period\" => bottom\n$datadlt = delete text in box @topOver @bottomTotal  page.left page.right => get text\n\n@top1 = get line containing \"Important information \" => bottom\n@bottom1 = get line containing \"Printed on\" => top\n$dataImp = delete text in box @top1 @bottom1 page.left page.right => get text\n\ndelete all lines containing \"Overview of the charges\"\ndelete all lines containing \"Code Date Details Paid out\"\nignore header above 355\n\nget last line containing \"Statement number Account type\" => top => get line above\n$closingBalance = get text in box 355 60 500 550 => take last words 1 => get decimal\n\nignore footer below 60\ndelete all lines containing \"that will be deducted\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 35 75 125 300 385 500 560 => describe table false TransactionType \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 75 125 305 385 500 560 => describe table false TransactionType \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance','2025-02-25 07:19:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10554,'OakStar_Bank_Checking','$source = \"OakStar_Bank_CheckingAccount\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\ndelete text in box on every page page.top page.bottom 0 70\n\n// Get account name\n$accountName = get line starting \"Account Title:\" => get words after \"Account Title:\" => take words 2 => get text\n$accountNumber = get line containing \"Account Number\" => get words after \"Acct Ending\" => take words 1 => get text\n\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n// Get start & end of cresits table\ngo to page 1\n@creditsTop = get line containing \"DATE DESCRIPTION TRACE\" => bottom => get line below\n\n@TEXTBOXTop = get line containing \"Check Detail\" => top\n@TEXTBOXBottom = get line containing \"Daily Balance Summary\" => top\ndelete text in box @TEXTBOXTop @TEXTBOXBottom page.left page.right\n\n@creditsBottom = get line starting \"Daily Balance Summary\" => if not found then blank => top => get line above\n\nignore footer below 40\nignore header above 530\ndelete all lines containing \"DATE DESCRIPTION\"\nremove page 2\n\n$transactions = get multi page table @creditsTop @creditsBottom 72 98 375 430 560 => describe table false \"*Date[M/dd]\" Details #Credit #Balance','2024-12-11 08:10:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10555,'Pinnacle_Bank_Horizon150','$source = \"Pinnacle_Bank_Horizon150\"\n$features = \"NO_TRANSACTION_YEAR\"\n\nremove page 2\n\n//Get account name\n@AcctBottom = get line containing \"Horizon\" => top\n$accountName = get text in box page.top @AcctBottom 400 page.right => get words after \"Account\" => take words 3 => get text\n\n//Get account number\n$accountNumber = get text in box page.top @AcctBottom 400 page.right => take last words 1 => get text\n\n//Get opening Balance\n@BalanceTop = get line containing \"Statement of Account\" => bottom\n@BalanceBottom = get line containing \"Credit Transactions\" => top\n@TextBox = get text in box @BalanceTop @BalanceBottom page.left 230\n$openingBalance = skip words @TextBox 3 => take words 1 => get decimal\n$closingBalance = take last words @TextBox 1 => get decimal\n\n//Get periodTo\n$periodFrom = skip words @TextBox 1 => take words 1 => get date \"M/dd/yy\"\n$periodTo = skip words @TextBox 5 => take words 1 => get date \"M/dd/yy\"\n\n$deleteleftpanel = delete text in box @BalanceTop 0 550 600 => get text\n\n@CreditsTop = get line starting \"Credit Transactions\" => bottom => get line below => bottom => get line below\n@CreditsBottom = get line containing \"Debit Transactions\" => top => get line above\ndelete all lines starting \"Total Credits\"\n\nignore footer below 30\n\n// Read the transactions\n$transactions1 = get multi page table @CreditsTop @CreditsBottom 0 100 325 580 => describe table false \"*Date[M/dd]\" Details #Credit\n\ngo to page 1\n@DebitsTop = get line starting \"Debit Transactions\" => bottom => get line below\n@DebitsBottom = get line starting \"Page 1 of\" => if not found then blank => bottom => get line above\n\ndelete all lines starting \"Page\"\ndelete all lines starting \"Other Debits\"\n$transactions2 = get multi page table @DebitsTop @DebitsBottom 0 100 325 580 => describe table false \"*Date[M/dd]\" Details #Debit\n\n//go to page 1\n@DebitsTop2 = get line starting \"Account Number:\" => bottom => get line below\ngo to page 1\n@delName = get line starting \"Debit Transactions\" => top => get line above => get text\ndelete all lines starting @delName\ndelete all lines starting \"Debit Transactions\"\n@DebitsBottom2 = get line starting \"Checks\" => top => get line above\n\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Page\"\n//delete all lines starting \"Debit Transactions\"\ndelete all lines containing \"Account Number:\"\n$transactions3 = get multi page table @DebitsTop2 @DebitsBottom2 0 100 500 580 => describe table false \"*Date[M/dd]\" Details #Debit\n\n@ChecksTop = get line starting \"Checks\" => bottom => get line below\n@ChecksBottom = get line containing \"Total Debits\" => top => get line above\ndelete all lines containing \"Account Number:\"\ndelete all lines starting \"Page\"\n$transactions4 = get multi page table @ChecksTop @ChecksBottom 0 100 500 580 => describe table false \"*Date[M/dd]\" Details #Debit\n\n$transactions = combine described tables $transactions1 $transactions2 $transactions3 $transactions4\n','2024-12-11 08:10:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10556,'Lloyds_CommericalMultipay_Card','$source = \"Lloyds_CommericalMultipay_Card\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 45\n\nset negative marker \"CR\"\n\n$deleteleftpanel = delete text in box on every page page.top 0 0 40 => get text\n\ngo to page 1\n@StatementdateTop = get line containing \"Statement date\" => top\n\n$accountName = get text in box page.top @StatementdateTop 0 page.middleX => skip words 1 => take words 3  => get text\n\n@TableHeaderTop = get line containing \"Reference Description Amount\" => top\n\n@Summary = get text in box @StatementdateTop @TableHeaderTop 0 580\n\n$periodTo = get words after @Summary \"Statement date\" => get words between \"Statement date\" \"Previous balance\" => get date \"ddMMyyyy\"\n\n$OpeningBalance = get words after @Summary \"Previous balance\" => get words between \"Previous balance\" \"Transaction refunds\" => get decimal\n\n$accountNumber = get words after @Summary \"Account number\" => take words 1 => get text\n\n$closingBalance = get words after @Summary \"Current balance\" => get decimal\n\n$periodFrom = get line starting \"XXXX-XXXX\" => bottom => get line below => take words 1 => get date \"ddMMyyyy\"\n\ngo to page 1\n@transactionsTop = get line containing \"Reference Description Amount\" => bottom => get line below\n\n@transactionsBottom = get last line starting \"Payment is due by\" => top => get line above\n\ngo to page 1\n@DelAccountName = get line containing \"Statement date\" => top => get line above\n$DelAccountNameL1 = top @DelAccountName => get line above => take words 2 => get text\n$DelAccountNameL2 = top @DelAccountName => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL3 = top @DelAccountName => get line above => top => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL4 = top @DelAccountName => get line above => top => get line above => top => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL5 = top @DelAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL6 = top @DelAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL7 = top @DelAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 2 => get text\n$DelAccountNameL8 = top @DelAccountName => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above => take words 2 => get text\n\ndelete all lines starting $DelAccountNameL1\ndelete all lines starting $DelAccountNameL2\ndelete all lines starting $DelAccountNameL3\ndelete all lines starting $DelAccountNameL4\ndelete all lines starting $DelAccountNameL5\ndelete all lines starting $DelAccountNameL6\ndelete all lines starting $DelAccountNameL7\ndelete all lines starting $DelAccountNameL8\n\ndelete all lines starting \"XXXX-XXXX\"\ndelete all lines starting \"Payment is due by\"\ndelete all lines starting \"Payment will be collected by\"\ndelete all lines containing \"Reference Description Amount\"\ndelete all lines starting \"2024.\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"date\"\n\nignore header above 762\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 110 477 580 => describe table false \"*Date[ddMMyyyy]\" Details #Credit','2024-12-11 08:10:31',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10557,'StandardBank_Afrikaans_without_ServiceFee','$source = \"StandardBank_Afrikaans_without_ServiceFee\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Parse amounts in  Afrikaans (South Africa)\nset culture \"af-ZA\"\n\n\n// Get account name\n$accountName = get text in box 700 660 0 page.middleX => get text\n\ngo to page 1\n// Get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => take last words 4 => get text\n\ngo to page 1\n// Get opening balances\n$openingBalance = get line starting \"BALANCE BROUGHT FORWARD\" => take last words 1 => get decimal\n\n// get closing balance\n$closingBalance = get last line containing \"## These fees include VAT\" => top => get line above => take last words 1 => get decimal\n\n// Get Period from\ngo to page 1\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BROUGHT FORWARD\" => take words 2 => get date \"MM dd\"\n\n\ngo to page 1\n// Get start & end of transactions table\n@transactionsTop = get line starting \"BALANCE BROUGHT FORWARD\"  => bottom => get line above\n\n// set english culture for periodTo\nset culture \"en-US\"\n\n//get period to in english culture\n$periodTo = get line starting \"Rates Payable as at\" => get words after \"Payable as at\" => take words 3 => get date \"dd MMM yyyy\"\n\n\ngo to page 1\n@transactionsBottom = get last line starting \"## These fees include VAT\" => top => get line above\n\ngo to page 1\n$delete_text = get line starting \"## These fees include\" => bottom => get line below => take words 1 => get text\ndelete all lines starting $delete_text\n\n\n// Discard page header/footer\ngo to page 2\nignore header above 500\nget line starting \"## These fees include\" => bottom => ignore footer below\n\n\ngo to page 1\n// Remove unwanted lines\ndelete all lines starting \"Details Debit Credit\"\ndelete all lines starting \"## These fees include\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines starting \"INTEREST APPLICABLE\"\n\nset culture \"af-ZA\"\ngo to page 1\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 195 250 445 470 560 => describe table false Details - #Credit \"Date[MM dd]\" *#Balance','2024-12-11 08:10:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10558,'ScotiaCorporateCard','$source = \"ScotiaCorporateCard\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n// get account name & number\ngo to page 1\n$accountname = get line containing \"Current balance\" => top => get line above => take last words 1 => get text\n$accountnumber = get line containing \"Current balance\" => top => get line above => take last words 1 => get text\n\n// get period from & to\n\n$periodto = get line containing \"Date Description\" => bottom => get line below => take words 4 => skip words 1 => get date \"MMM d, yyyy\"\n$getline = get last line containing \"https://secure.scotiabank.com\" => top\n$gettext = get text in box page.top $getline page.left 150\n$periodfrom = take last words $gettext 3 => get date \"MMM d, yyyy\"\n\n//$Date_right = get line containing \"Date Description Amount\" => get words before \"(UTC)\" => left => subtract 5\n$Date_left = get line containing \"Date Description Amount\" => get words before \"Description\" => take words 1 => left => subtract 10\n$Description_right = get line containing \"Date Description Amount\" => get words after \"Description\" => take words 1 => left => subtract 15\n$Amount_right = get line containing \"Date Description Amount\" => get words after \"Amount\" => take words 1 => left => subtract 105\n$Balance_right = get line containing \"Date Description Amount\" => get words after \"Amount\" => right\n\ngo to page 1\n$closingbalance = get line containing \"Date Description Amount\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n@transactionstop = get line starting \"Date Description Amount\" => bottom => get line below\n@transactionsbottom = get last line containing \"https://secure.scotiabank.com\" => top => get line above\n\nignore header above 745\nignore footer below 25\n\ngo to page 1\n\n$transactions = get multi page table @transactionstop @transactionsbottom $Date_left 140 $Description_right $Amount_right $Balance_right => describe table false \"*Date[ddd, MMM d, yyyy]\" Details #Credit\n','2025-01-09 08:35:36',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10559,'ScotiaCorporateCardStatus','$source = \"ScotiaCorporateCardStatus\"\n$features = \"REVERSE_ORDER CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// get account name & number\ngo to page 1\n$accountname = get line containing \"Current balance\" => top => get line above => take last words 1 => get text\n$accountnumber = get line containing \"Current balance\" => top => get line above => take last words 1 => get text\n\n// get period from & to\n\n$periodto = get line containing \"Date Description\" => bottom => get line below => take words 4 => skip words 1 => get date \"MMM d, yyyy\"\n$getline = get last line containing \"https://secure.scotiabank.com\" => top\n$gettext = get text in box page.top $getline page.left 150\n$periodfrom = take last words $gettext 3 => get date \"MMM d, yyyy\"\n\n$Date_left = get line containing \"Date Description Status\" => get words before \"Description\" => take words 1 => left => subtract 10\n$Description_right = get line containing \"Date Description Status\" => get words after \"Description\" => take words 1 => left => subtract 15\n$Status_right = get line containing \"Date Description Status\" => get words after \"Description\" => take words 1 => right => add 25\n$Balance_right = get line containing \"Date Description Status\" => get words after \"Status\" => right\n\ngo to page 1\n$openingbalance = 0\n$closingbalance = 0\n//get line starting \"Current balance\" => get words after \"Current balance\" => take words 1 => get decimal\n\ngo to page 1\n@transactionstop = get line starting \"Date Description Status\" => bottom => get line below\n@transactionsbottom = get last line containing \"https://secure.scotiabank.com\" => top => get line above\n\n\ndelete all lines containing \"Date Description Status\"\ndelete all lines starting \"Page created on\"\ndelete all lines starting \"Scotia Momentum\"\ndelete all lines starting \"Current balance\"\ndelete all lines starting \"Document delivery Print\"\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"Filters\"\ndelete all lines containing \"Custom filters\"\n\nignore header above 745\nignore footer below 25\n\n\ngo to page 1\n\n$transactions = get multi page table @transactionstop @transactionsbottom $Date_left 140 $Description_right $Status_right $Balance_right => describe table false \"*Date[ddd, MMM d, yyyy]\" Details - #Credit','2025-03-20 07:08:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10560,'ANZ_Plus_Bank','$source = \"ANZ_Plus_Bank\"\r\n$features = \"REVERSE_ORDER NO_TRANSACTION_YEAR\"\r\n\r\n// Get Account Name\r\n$accountName = get line starting \"Account Name\" => bottom => get line below => take words 3 => get text\r\n\r\n// Get period/from To\r\n@periodtxt = get line starting \"Account Statement\" => bottom => get line below\r\n$periodFrom = take words @periodtxt 3 => get date \"d MMMM yyyy\"\r\n$periodTo = get words after @periodtxt \"-\" => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get Account number\r\n@textaccnumBal = get line containing \"Branch Number (BSB) Account Number\" => bottom => get line below\r\n$accountNumber = take words @textaccnumBal 5 => take last words 3 => get text\r\n\r\n// Get opening/closing balance\r\n$closingbalance = take last words @textaccnumBal 2 => take words 1 => get decimal\r\n$openingbalance = take last words @textaccnumBal 1 => get decimal\r\n\r\n@TransactionsHeader = get line starting \"Date Description Credit Debit Balance\"\r\n\r\n@DateLeft = get words before @TransactionsHeader \"Description\" => take last words 1 => left => subtract 4\r\n@DescLeft = get words after @TransactionsHeader \"Date\" => take words 1 => left => subtract 4\r\n@CreditLeft = get words after @TransactionsHeader \"Description\" => take words 1 => left => subtract 45\r\n@CreditRight = get words after @TransactionsHeader \"Description\" => take words 1 => right => add 4\r\n@DebitRight = get words after @TransactionsHeader \"Credit\" => take words 1 => right => add 4\r\n@BalanceRight = get words after @TransactionsHeader \"Debit\" => take words 1 => right => add 4\r\n\r\n// Get top of the transaction table\r\n@transactionsTop = get line starting \"Date Description Credit Debit Balance\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"Opening Balance\" => top => get line above\r\n\r\ndelete all lines containing \"ANZ Plus\"\r\ndelete all lines containing \"Account Statement\"\r\ndelete all lines starting \"Date Description Credit Debit\"\r\ndelete all lines starting \"Australia and New Zealand Banking\"\r\ndelete all lines containing \"Credit License No.\"\r\n\r\n// Read the transactions\r\n//$transactions = get multi page table @transactionsTop @transactionsBottom 40 95 345 430 510 570 => describe table false \"*Date[dd MMM]\" Details #Credit #Debit *#Balance\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @DescLeft @CreditLeft @CreditRight @DebitRight @BalanceRight => describe table false \"*Date[dd MMM]\" Details #Credit #Debit *#Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10561,'ProvidenceBank','$source = \"ProvidenceBank\"\n\nset negative marker \"+\"\n$accountName = get line starting \"Account No. Sub Acct.\" => bottom => get line below => take words 1 => get text\n$accountNumber = get line starting \"Account No. Sub Acct.\" => bottom => get line below => take words 1 => get text\n\n$PeriodFromText = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\"\n$PeriodFrom = take words $PeriodFromText 1 => get date \"MM/d/yy\"\n$openingBalance = take last words $PeriodFromText 1 => get decimal\n\n$PeriodToText = get line starting \"Ending Balance\" => get words after \"Ending Balance On\"\n$PeriodTo = take words $PeriodToText 1 => get date \"MM/d/yy\"\n$closingBalance = take last words $PeriodToText 1 => get decimal\n\n$Date_left = get line containing \"Date Description Amount\" => get words before \"Description\" => take words 1 => left => subtract 10\n$Date_right = get line containing \"Date Description Amount\" => get words after \"Date\" => left => subtract 15\n$Description_right = get line containing \"Date Description Amount\" => get words after \"Description\" => left => subtract 10\n$Amount_right = get line containing \"Date Description Amount\" => get words after \"Description\" => right => add 30\n\n$topCh = get line starting \"ITEMIZED SERVICE CHARGE\" => top\n$botCh = get line starting \"TOTAL SERVICE CHARGE :\" => bottom\n$dlt = delete text in box $topCh $botCh page.left page.right => get text\n\ngo to page 1\n// Get start & end of Posted table\n@transactionstop = get line starting \"ALL POSTED ACTIVITY\" => if not found then blank => bottom => get line below\n@transactionsbottom = get line starting \"This Statement Cycle Reflects\" => if not found then blank => top => get line above\n\n\ndelete all lines containing \"Date Description\"\ndelete all lines starting \"ALL POSTED ACTIVITY\"\ndelete all lines containing \"Description\"\n\nignore header above 533\nignore footer below 35\n\ngo to page 1\n$transactions = get multi page table @transactionstop @transactionsbottom $Date_left $Date_right $Description_right $Amount_right => describe table false \"*Date[MM/d/yy]\" Details #Debit','2025-01-09 08:35:38',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10562,'Parkland_Settlement','$source = \"Parkland_Settlement\"\n$periodBufferDays = 14\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\nset negative marker \"-\"\n\n//Get account details\n@TEXTBOXTop = get line containing \"To:\" => bottom\n@TEXTBOXBottom = get line containing \"Document Date Document # Remarks\" => top\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom page.left 300\n\n$accountName = get text in box @TEXTBOXTop @TEXTBOXBottom page.left 300 => take words 3 => get text\n$accountNumber = get line containing \"ACCOUNT #\" => get words after \"ACCOUNT #\" => take words 1 => get text\n\n//Statement Period\n$periodFrom = get line containing \"Document Date Document # Remarks\" => bottom => get line below => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line containing \"SETTLEMENT DATE:\" => get words after \"SETTLEMENT DATE:\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get opening balance\n$openingBalance = 0\n\n//Get closing balance\n$closingBalance = 0\n\n//Get start & end of table\n@debitsTop = get line containing \"Document Date Document # Remarks\" => bottom => get line below\n@debitsBottom = get line starting \"Invoice Summary with Load Date \" => if not found then blank => top => get line above\n\nignore footer below 70\nignore header above 670\ndelete all lines containing \"Document Date Document # Remarks\"\ndelete all lines starting \"Page\"\n\n$transactions = get multi page table @debitsTop @debitsBottom 30 103 430 515 580 => describe table false \"*Date[MM/dd/yy]\" Details #Debit #Credit','2025-01-09 08:35:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10563,'Marcus_Bank','$source = \"Marcus_Bank\"\n\n\n//get accountnumber\n$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//get accountname\n$accountname = get line containing \"Account Name\" => get words after \"Account Name\" => take words 1 => get text\n\n//get statement period in single veriable\n@period = get line containing \"Beginning Balance\" => get words after \"Statement Period\" => take words 3\n\n//get statement periodFrom\n$periodfrom = take words @period 1 => get date \"MM/dd/yyyy\"\n\n//get statement periodTo\n$periodto = take last words @period 1 => get date \"MM/dd/yyyy\"\n\n\n//get opening balance\n$openingBalance = get line Starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n\n//get closing balance\n$closingbalance = get line Starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n\ngo to page 1\n//get transactions table top\n@transactiontop = get line containing \"Date Description Credits Debits\" => bottom => get line below => bottom => get line below\n\n//get transactions table bottom\n@transactionbottom = get last line containing \"Ending Balance\" => top => get line above\n\n//ignore header\ngo to page 1\nget line containing \"Date Description Credits Debits\" => bottom => ignore header above\n\n//delete extra lines and extra text\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\n\n//ignore footer\nget last line containing \"Ending Balance\" => bottom => ignore footer below\n\n\ngo to page 1\n//get whole transactions in a single table\n$transactions = get multi page table @transactiontop @transactionbottom 30 90 365 430 510 590 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit #Debit #Balance','2025-01-09 08:35:41',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10564,'UOB_Bank_CenterAlign','$source = \"UOB_Bank_CenterAlign\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account name\n@AccountTop = get line starting \"Company / Account\" => bottom\n@AccountBottom = get line starting \"Account Details\" => top\n@TextBox = get text in box @AccountTop @AccountBottom 0 page.middleX\n$AccountName = get words after @TextBox \"Company\" => get words before \"Account\" => get text\n\n// Get account number\n$accountNumber = take last words @TextBox 1 => get text\n\n// Get Period from and Period To\n@statementPeriod = get line starting \"Account Transactions\" => bottom => get line below => bottom => get line below => take last words 3\n$periodFrom = get words before @statementPeriod \"-\" => get date \"dd/MM/yyyy\"\n$periodTo = get words after @statementPeriod \"-\" => get date \"dd/MM/yyyy\"\n\n// Get Opening Balance\ngo to page 1\n@OpeningBalanceTop = get line containing \"Statement Date Transaction Date Description\" => bottom\n@OpeningBalanceBottom = get line above 0 => top\n//@TextBox2 = get text in box @OpeningBalanceTop @OpeningBalanceBottom 525 572\n@TextBox2 = get text in box @OpeningBalanceTop @OpeningBalanceBottom 520 572\n\n$OpeningBalance = take words @TextBox2 1 => get decimal\n\n@DeleteTop = get line containing \"Total Deposits(SGD)\" => top\n@DeleteBottom = get line containing \"Date of Export\" => top\ndelete text in box @DeleteTop @DeleteBottom page.left page.right\n\n// Get Closing Balance\ngo to page 1\n@ClosingBalanceTop = get last line containing \"Statement Date Transaction Date Description\" => bottom\n@ClosingBalanceBottom = get line containing \"Date of Export\" => top\n//$closingBalance = get text in box @ClosingBalanceTop @ClosingBalanceBottom 525 572 => take last words 1 => get decimal\n$closingBalance = get text in box @ClosingBalanceTop @ClosingBalanceBottom 520 572 => take last words 1 => get decimal\n\ngo to page 1\nignore footer below 60\n@transactionsTop = get line containing \"Statement Date Transaction Date Description\" => bottom => get line below\nget last line containing \"Statement Date Transaction Date Description\" => bottom\n@transactionsBottom = get line containing \"Date of Export\" => top => get line above\n\ndelete all lines starting \"Account Activities\"\ndelete all lines starting \"Statement Date Transaction Date Description\"\ndelete all lines starting \"Date of Export:\"\n\n// Read the transactions\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 9 0 70 185 315 385 470 572 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Debit #Balance','2025-08-20 07:24:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10565,'GaboroneBank','$source = \"GaboroneBank\"\n\n\n// Get account name\n$accountName = get text in box 725 650 0 page.middleX => get text\n\n// Get account number\n$accountNumber = get line containing \"Account No:\" => take last words 1 => get text\n\n\n//get period\n$period = get line containing \"Period:\" => take last words 3\n\n//get statement_periodfrom\n$PeriodFrom = take words $period 1 => get date \"dd/MM/yyyy\"\n\n//get statement_periodTo\n$PeriodTo = take last words $period 1 => get date \"dd/MM/yyyy\"\n\n\ngo to page 1\n//get opening balance\n$openingbalance = get last line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n\n//get closing balance\n$closingbalance = get last line containing \"CHARGES CARRIED FORWARD\" => top => get line above => take last words 1 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get last line containing \"OPENING BALANCE\" => bottom => get line below\n\n\n// Get end of table\n@transactionsBottom = get last line containing \"CHARGES CARRIED FORWARD\" => top => get line above\n\n// Discard unwanted lines\ndelete all lines starting \"Page\"\ndelete all lines starting \"Business Cheque Account\"\ndelete all lines starting \"Date Description\"\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 95 290 370 430 495 565 => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit #Balance','2025-01-09 08:36:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10566,'Kiwi_Bank','$source = \"Kiwi_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = \"45\"\n\n// Get account name\n$accountName = get line starting \"ACCOUNT NAME ACCOUNT NUMBER\" => top => get line below => take words 4 => get text\n\n\n// Get account number\n$accountNumber = get line starting \"ACCOUNT NAME ACCOUNT NUMBER\" => top => get line below => skip words 4 => take words 1 => get text\n\n\n//PeriodFrom and PeriodTo\n\n//$PeriodFrom = get line containing \"FOR THE PERIOD\" => top => get line below => get words before \"TO\" => get date \"d MMMM yyyy\"\n\n$PeriodFrom = get line containing \"FOR THE PERIOD\" => top => get line below => take words 3 => get date \"d MMMM yyyy\"\n\n//$PeriodTo = get line containing \"FOR THE PERIOD\" => top => get line below => get words after \"TO\" => get date \"d MMMM yyyy\"\n\n$PeriodTo = get line containing \"FOR THE PERIOD\" => top => get line below => take last words 3 => get date \"d MMMM yyyy\"\n\n// Opening and Closing Balance\n\n$OpeningBalance = get line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n$ClosingBalance = get last line containing \"CLOSING BALANCE\" => take last words 1 => get decimal\n\n// Get start and end of table\n@transactionsTop = get line containing \"Date Value Date Particulars Withdrawals\" => bottom => get line below\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\n\nignore header above 414\nignore footer below 22\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 48 122 490 600 720 870 => describe table false \"*Date[d MMM]\" \"TransactionDate[d MMM]\" Details #Debit #Credit #Balance','2025-01-09 08:36:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10567,'PaypalTransactions_TransactionID','$source = \"PaypalTransactions_TransactionID\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 7\n\n// Get account name\n$accountName = get line starting \"Merchant account ID:\" => get words after \"Merchant account ID:\" => take words 1 => get text\n\n// Get account number\n$accountnumber = get line starting \"Merchant account ID:\" => bottom => get line below => take words 3 => get text\n\n// Get Period From and To\n$periodFrom = get line starting \"Transaction details:\" => get words after \"Transaction details:\" => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get line starting \"Transaction details:\" => get words after \"Transaction details:\" => take last words 3 => get date \"d MMM yyyy\"\n\n// Get balances\n$openingbalance = 0\n$closingbalance = 0\n\n// Get start of table\n@transactionsTop = get line starting \"Date Type Transaction ID\" => bottom => get line below\n\n// Get end of table\n@translast = get last line starting \"Date Type Transaction ID\"\n@transactionsBottom = get line above 0\n\ndelete all lines starting \"Date Type Transaction ID\"\ndelete all lines containing \"Address line\"\ndelete all lines starting \"Merchant account ID:\"\ndelete all lines starting \"PayPal Inc.\"\ndelete all lines starting \"Page\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 75 135 440 485 530 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details - #Credit','2025-01-09 08:36:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10568,'Danske_card','$source = \"Danske_card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = \"10\"\n\n//set negative marker\nset negative marker \"-\"\n\n//delete extra text\ndelete rotated words\ndelete tiny words\n\n// Get account name\n$accountName = get text in box page.top 670 0 page.middleX => get text\n\n// Get account number\n$accountNumber = get line starting \"Account\" => take last words 1 => get text\n\n//get period\n$period = get line starting \"Period to which this statement\" => take last words 3\n\n//get statement_periodfrom\n$PeriodFrom = take words $period 1 => get date \"dd.MM.yyyy\"\n\n//get statement_periodTo\n$PeriodTo = take last words $period 1 => get date \"dd.MM.yyyy\"\n\ngo to page 1\n\n//set opening balance zero\n$openingbalance = get line containing \"Trans Interest\" => bottom => get line below => bottom => get line below => take last words 1 => get decimal\n\n//get closing balance\n$closingbalance = get line containing \"Balance to calculate this month\" => get words after \"s payment\" => take words 2 => get decimal\n\n//go to page 1\n//$top_credit = get line starting \"Card no.\" => bottom\n//$botttom_credit = get line \"Card transactions\" => top\n//$delete_credit_footer = delete text in box $top_credit $botttom_credit page.left page.right => get text\n\ngo to page 1\n//delete all lines starting \"Card no.\"\n\n//credit_table_top\n@transactionsTop1 = get line containing \"Trans Interest\" => bottom => get line below => bottom => get line below\n\n//credit_table_bottom\n@transactionsBottom1 = get line containing \"Card transactions\" => top => get line above\n\ngo to page 1\n$top_credit1 = get line containing \"xxxx xxxx\" => top\n$botttom_bal = get line containing \"xxxx xxxx\" => bottom => get line below => bottom\n$delete = delete text in box $top_credit1 $botttom_bal page.left page.right => get text\n\n$top_credit2 = get line containing \"xxxx xxxx\" => top\n$botttom_bal2 = get line containing \"xxxx xxxx\" => bottom => get line below => bottom\n$delete = delete text in box $top_credit2 $botttom_bal2 page.left page.right => get text\n\n$top_credit3 = get line containing \"xxxx xxxx\" => top\n$botttom_bal3 = get line containing \"xxxx xxxx\" => bottom => get line below => bottom\n$delete = delete text in box $top_credit3 $botttom_bal3 page.left page.right => get text\n\nignore header above 672\n\ndelete all lines starting \"Balance at\"\ndelete all lines starting \"Mastercard Corporate\"\ndelete all lines starting \"Period to which\"\n\n\ngo to page 1\n$transactions_credit = get multi page table @transactionsTop1 @transactionsBottom1 50 85 140 305 390 480 => describe table false \"*Date[dd.MM]\" - Details #Credit #Debit\ngo to page 1\n// Get start and end of table\n@transactionsTop = get line containing \"Date Date Date\" => bottom => get line below\n\n//get transaction bottom\n@transactionsBottom = get last line containing \"Total of Transactions\" => top => get line above\n\ngo to page 1\n//ignore headers\n//get line starting \"Period to which\" => top => ignore header above\n\nignore header above 672\n\n//ignore footer below 22\n\n//delete extra text\ndelete all lines starting \"Card no. 5434 xxxx xxxx 5004\"\ndelete all lines starting \"Purchase Trans\"\ndelete all lines starting \"Date Date\"\ndelete all lines starting \"Trans Interest\"\ndelete all lines starting \"Total of Transactions\"\ndelete all lines containing \"Card no.\"\n\ngo to page 1\n\n$transactions_debit = get multi page table @transactionsTop @transactionsBottom 90 128 190 500 580 => describe table false \"*Date[dd.MM]\" - Details #Credit\n\n//combine transactions\n$transactions = combine described tables $transactions_debit $transactions_credit','2025-03-20 07:00:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10569,'CapitalOne_CATEGORY','$source = \"CapitalOne_CATEGORY\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = \"15\"\n\n//Account Details\n\n//$accountNumber = get line containing \"Simply Checking -\" => get words after \"Simply Checking -\" => take words 1 => get text\n//$accountName = get text in box 670 630 page.left 170 => take words 2 => get text\n$accountName = get line containing \"All Accounts\" => bottom => get line below => take last words 1 => get text\n$accountNumber = get line containing \"All Accounts\" => bottom => get line below => take last words 1 => get text\n\n// Opening and Closing Balance\n\n$OpeningBalance = get line containing \"Opening Balance\" => take last words 1 => get decimal\n$ClosingBalance = get last line containing \"Closing Balance\" => take last words 1 => get decimal\n\n//PeriodFrom and PeriodTo\n\n$PeriodFrom = get last line containing \"STATEMENT PERIOD\" => top => get line below => get words before \"-\" => get date \"MMM d\"\n$PeriodTo = get last line containing \"STATEMENT PERIOD\" => top => get line below => get words after \"-\" => get date \"MMM dd yyyy\"\ngo to page 1\n@transactionsTop = get line containing \"CATEGORY AMOUNT BALANCE\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\nignore header above 680\nignore footer below 65\n\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"DATE DESCRIPTION CATEGORY AMOUNT BALANCE\"\ndelete all lines containing \"Interest Rate Change from\"\n\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 95 335 380 485 570 => describe table false \"*Date[MMM d]\" Details TransactionType #Credit #Balance','2025-01-23 08:25:21',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10570,'bnz_kiwiBank','$source = \"bnz_kiwiBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = \"45\"\n\n@TEXTBOXTop = get line containing \"STATEMENT\" => top\n@TEXTBOXBottom = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom page.left 145\n// Get account name\n//$accountName = get line starting \"ACCOUNT NAME\" => top => get line below => take words 1 => get text\n\n$accountName = get words after @TEXTBOX \"ACCOUNT NAME\" => take words 1 => get text\n\n// Get account number\n\n//$accountNumber = get line containing \"ACCOUNT NUMBER\" => take last words 1 => get text\n\n$accountNumber = get words after @TEXTBOX \"ACCOUNT NUMBER\" => take words 1 => get text\n\n//PeriodFrom and PeriodTo\n\n$PeriodFrom = get words after @TEXTBOX \"PERIOD\" => take words 2 => get date \"d MMMM\"\n\n\n//$periodFrom = get words after @TEXTBOX \"PERIOD\" => get words before \"TO\" => get date \"d MMMM\"\n\n//$periodTo = get words after @TEXTBOX \"TO\" => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = get words before @TEXTBOX \"ACCOUNT NAME\" => take last words 3 => get date \"d MMMM yyyy\"\n\n// Opening and Closing Balance\n\n$OpeningBalance = get line containing \"OPENING BALANCE\" => take last words 1 => get decimal\n$ClosingBalance = get last line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => take words 1 => get decimal\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line containing \"Date Particulars Type Withdrawals Deposits\" => bottom => get line below\n@transactionsBottom = get last line containing \"CLOSING BALANCE\" => top => get line above\n\ngo to page 1\ndelete text in box on every page @TEXTBOXTop @TEXTBOXBottom page.left 145\nignore header above 474\nignore footer below 55\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 140 189 450 482 580 680 820 => describe table false \"*Date[d MMM]\" Details TransactionType #Debit #Credit #Balance','2025-05-06 06:26:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10571,'MetroBankUK_DATE_TRANSACTION','$source = \"MetroBankUK_DATE_TRANSACTION\"\n\n// Get account name\n$accountName = get line starting \"ACCOUNT NAME:\" => get words after \"ACCOUNT NAME:\" => get text\n\n// Get account number (text changes so use line below Your account summary)\n@yourAccountSummary = get line starting \"Your account summary\"\n$accountNumber = bottom @yourAccountSummary => get line below => take last words 1 => get text\n\n// Get period from/to (sometimes in period lin have word - From:  at the start and sometimes not)\n// Need to remove the account number to be able to pick last 7 words of period line\n@dropTop = bottom @yourAccountSummary\n@dropBottom = subtract @dropTop 50\ndelete text in box @dropTop @dropBottom page.middleX page.right\n@period = get line below @dropTop => take last words 7\n$periodFrom = take words @period 3 => get date \"dd MMM yyyy\"\n$periodTo = take last words @period 3 => get date \"dd MMM yyyy\"\n\n//Get opening and closing balances\n$openingBalance = get line starting \"Balance brought forward\" => get words after \"Balance brought forward\"  => get decimal\n$closingBalance = get line starting \"Your transactions\" => top => get line above => take last words 1 => get decimal\n\n//Dynamic Coordinates for transaction table\n@Date_left = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words before \"TRANSACTION\" => left => subtract 10\n@Description_left = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words after \"DATE\" => left => subtract 5\n@Description_right = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words after \"TRANSACTION\" => left => subtract 5\n@Paidout_right = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words after \"MONEY OUT\" => left => subtract 10\n@Paidin_right = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words before \"BALANCE\" => right => add 15\n@Balance_right = get line containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\" => get words after \"MONEY IN\" => right => add 10\n\n// Transaction table top and bottom\n@transactionsTop = get line starting \"Balance brought forward\" => bottom => get line below\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\n\nignore header above 730\n\n//Discard page footer\nignore footer below 50\n\ndelete all lines containing \"DATE TRANSACTION MONEY OUT MONEY IN BALANCE\"\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @Date_left @Description_left @Description_right @Paidout_right @Paidin_right @Balance_right => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance','2025-01-23 08:25:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10572,'Hsbc_card_HongKong','$source = \"Hsbc_card_HongKong\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodbufferdays = 15\nset negative marker \"CR\"\n\n// Get account name\n@accountNumbertOP = get line containing \"Account number\" => bottom\n@accountNumberbottom = get line containing \"Account number\" => bottom => get line below => bottom\n$accountNumber = get text in box @accountNumbertOP @accountNumberbottom 340 page.right => get text\n\n@periodTotOP = get line containing \"Statement date\" => bottom\n@periodTobottom = get line containing \"Statement date\" => bottom => get line below => bottom\n$periodTo = get text in box @periodTotOP @periodTobottom 320 490 => take words 3 => get date \"dd MMM yyyy\"\n\n$openingBalance = get line containing \"PREVIOUS BALANCE\" => get words after \"PREVIOUS BALANCE\" => get decimal\n$closingBalance = get line starting \"TOTAL ACCOUNT BALANCE\" => take last words 1 => get decimal\n\ngo to page 1\n@DateRight = get line starting \"Post date Trans date Description of transaction Amount\" => get words after \"Post date\" => take words 1 => left\n@DescLeft = get line starting \"Post date Trans date Description of transaction Amount\" => get words after \"Trans\" => take words 1 => right => subtract 5\n\n@MaintransactionsTop = get line starting \"Post date Trans date Description of transaction Amount\" => bottom => get line below\n@MaintransactionsBottom = get last line containing \"*For credit card\"\n\ngo to page 1\n@FinancetransactionsTop = get last line starting \"REWARDCASH EXPIRING IN\" => if not found then blank => bottom => get line below\n@FinancetransactionsBottom = get last line starting \"STATEMENT BALANCE\" => if not found then blank => top => get line above\n\ngo to page 1\n@periodFromTop = get line starting $accountNumber => bottom\n$periodFrom = get text in box @periodFromTop 100 45 @DateRight => take words 1 => get date \"ddMMM\"\n\n$accountName = get line starting $accountNumber => get words after $accountNumber => get text\n\n@footer1Top = get line containing \"Minimum payment summary\" => top\ndelete text in box @footer1Top 0 page.left page.right\n\n@footer1Top = get line containing \"*For credit card transactions\" => top\n@footer1Bottom = get last line starting \"REWARDCASH EXPIRING IN\" => top\ndelete text in box @footer1Top @footer1Bottom page.left page.right\n\n@footer2Top = get line containing \"REWARDCASH EARNINGS FROM PROMOTIONS\" => top\n@footer2Bottom = get last line starting \"OVERSEAS ONLINE 2X REWARDS\" => bottom\ndelete text in box @footer2Top @footer2Bottom page.left page.right\n\nignore header above 655\nignore footer below 97\n\ndelete all lines containing \"Post date Trans date Description of transaction Amount\"\ndelete all lines containing \"PREVIOUS BALANCE\"\ndelete all lines starting $accountNumber\ndelete all lines starting \"*For credit card transactions\"\n\n@Maintransactions = get multi page table @MaintransactionsTop @MaintransactionsBottom 45 @DateRight @DescLeft 490 580 => describe table false \"*Date[ddMMM]\" - Details #Credit\n\n@Financetransactions = get multi page table @FinancetransactionsTop @FinancetransactionsBottom 45 @DateRight @DescLeft 490 580 => describe table false \"*Date[ddMMM]\" - Details #Credit\n\n$transactions = combine described tables @Maintransactions @Financetransactions','2025-10-29 06:16:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10573,'JohnLewisCC','$source = \"JohnLewisCC\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 14\n//set negative marker \"+\"\n\ngo to page 1\n$accountname = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n$accountnumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n$openingBalance = get line containing \"Balance last month\" => get words after \"Balance last month\" => take words 1 => get decimal\n$closingBalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => take words 1 => get decimal\n\ngo to page 1\n$periodfromText = get line starting \"Opening Balance\" => bottom => get line below\n$periodfrom = take words $periodfromText 3 => get date \"d MMM yyyy\"\n\n//ignore footer below 150\n$pointstop = get line starting \"Your points\" => top\n$dlt = delete text in box $pointstop page.bottom page.left page.right\n\nignore header above 790\n\n//$periodToText = get last line starting \"Your new balance\" => top => get line above\n//$periodTo = take words $periodToText 3 => get date \"d MMM yyyy\"\ngo to page 1\n$periodTo = get line starting \"Statement date:\" => get words after \"Statement date:\" => take words 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\n@transactionBottom = get last line starting \"Your new balance\" => top => get line above\n\n\ndelete all lines starting \"Opening Balance\"\ndelete all lines containing \"Your monthly statement\"\n//ignore footer below 150\n//ignore header above 790\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionBottom  22 90 145 90 490 580 => describe table false \"*Date[d MMM yyyy]\" - - Details #Credit','2025-06-25 11:52:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10574,'CapitalOnTapCreditCard_TransactionDate','$source = \"CapitalOnTapCreditCard_TransactionDate\"\n$periodbufferdays = 30\n$features = \"CREDIT_CARD\"\n\n$accountname = get text in box 800 690 0 400 => get text\n\n$accountnumber = get text in box 745 725 400 700 => get text\n\n@period = get line starting \"Statement Summary\" => bottom => get line below\n//$periodfrom = take words @period 1 => get date \"dd/MM/yyyy\"\n//$periodto = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n@period1 = get last line containing \"Opening Balance\" => bottom => get line below\n//@period2 = get last line containing \"Closing Balance\" => top => get line above\n\n@balance = get line starting \"Opening Balance\" => bottom => get line below\n$openingbalance = take words @balance 1 => get decimal\n$closingbalance = take last words @balance 1 => get decimal\n\ngo to page 1\n@transactionstop = get last line containing \"Opening Balance\" => bottom => get line below\n//$periodfrom = get last line containing \"Opening Balance\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodfrom = take words @period1 1 => get date \"MM/dd/yyyy\"\n@transactionsbottom = get last line containing \"Closing Balance\" => top => get line above\n//$periodto = get last line containing \"Closing Balance\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodto = take last words @period 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n@ClearedDateleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 3 => take words 1 => left\n\n@ClearedDateleft = subtract @ClearedDateleft 15\n\n@Typeleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 2 => take words 1 => left\n@Typeleft = subtract @Typeleft 15\n\n@CardDescriptionleft = get last line containing \"Opening Balance\" => get words before \"Opening Balance\" => take last words 1 => left\n@CardDescriptionleft = subtract @CardDescriptionleft 15\n\n@Amountleft = get last line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => left\n@Amountleft = subtract @Amountleft 35\n\n@AmountRight = get last line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => right\n@AmountRight = add @AmountRight 15\n\ndelete all lines starting \"© New Wave Capital Limited\"\ndelete all lines starting \"Wave Capital Limits\"\ndelete all lines starting \"Interest on card\"\ndelete all lines containing \"Card Description Amount\"\nignore footer below 50\n\n\n//$transactions = get multi page table @transactionstop @transactionsbottom  20 135 200 525 569 => describe table false \"*Date[MM/dd/yyyy]\" TransactionType Details #Credit\n$transactions = get multi page table @transactionstop @transactionsbottom @ClearedDateleft @Typeleft @CardDescriptionleft @Amountleft @AmountRight => describe table false \"*Date[MM/dd/yyyy]\" TransactionType Details #Credit','2025-01-23 08:25:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10575,'AmericanExpress_BritishAirways_Card','$source = \"AmericanExpress_BritishAirways_Card\"\n$features = \"REVERSE_ORDER CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n@accountDetailsbottom = get line containing \"Card Activity from\" => bottom\n@accountDetails = get text in box page.top @accountDetailsbottom 0 300\n$accountNumber = get words after @accountDetails \"ACCOUNT ENDING -\" => take words 1 => get text\n\n$periodFrom = get words after @accountDetails \"Card Activity from\" => get words between \"from\" \"to\" => get date \"d MMM yyyy\"\n$periodTo = get words after @accountDetails \"to\"  => take words 3 => get date \"d MMM yyyy\"\n\n@accountNameBox = get text in box page.top @accountDetailsbottom 300 590\n$accountName = get words after @accountNameBox \"CARD MEMBER\" => get text\n\n$openingbalance = 0\n$closingbalance = 0\n\ngo to page 1\n@transactionstop = get line starting \"DATE STATUS DESCRIPTION\" => bottom => get line below\n@lasttransactionspage = get last line starting \"DATE STATUS DESCRIPTION\" => bottom\n@transactionsbottom = get line above 0\n\nignore header above 805\nignore footer below 30\ndelete all lines starting \"DATE STATUS DESCRIPTION\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 20 100 190 490 590 => describe table false \"*Date[d MMM yyyy]\" - Details #Credit','2025-01-23 08:25:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10576,'Umpqua_Bank','$source = \"Umpqua_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Get account name & account number\n@AccountTop = get line starting \"Customer Service:\" => bottom\n@AccountBottom = get line starting \"Last statement:\" => top\n$accountName = get text in box @AccountTop @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get statement period\n$periodFrom = get line starting \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMMM d yyyy\"\n$periodTo = get line starting \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMMM d yyyy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => get decimal\nignore header above 715\nignore footer below 50\ndelete all lines starting \"Date Description Subtractions\"\ndelete all lines starting \"Date Description Additions\"\n\n\n// Deposits/ Additions table\ngo to page 1\n@creditsTop_ = get line starting \"Deposits/Additions\" => if not found then blank => bottom => get line below\n@creditsBottom_ = get line starting \"Total Additions\" => if not found then blank => top => get line above\n@credits_ = get multi page table @creditsTop_ @creditsBottom_ 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Credit\n\n\n// Deposits/ Additions table\n//Other Deposits/ Additions\ngo to page 1\n@creditsTop = get line starting \"Other Deposits/ Additions\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Total Other Deposits/ Additions\" => if not found then blank => top => get line above\n@credits = get multi page table @creditsTop @creditsBottom 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Credit\n\n// ACH and Electronic Payments/Subtractions table\ngo to page 1\n@DebitsTop = get line starting \"ACH and Electronic Payments/Subtractions\" => if not found then blank => bottom => get line below\n@DebitsBottom = get line starting \"Total ACH and Electronic Payments/Subtractions\" => if not found then blank => top => get line above\n@Debits1 = get multi page table @DebitsTop @DebitsBottom 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Debit\n\n// ACH and Electronic Deposits/Additions table\ngo to page 1\n@creditsTop2 = get line starting \"ACH and Electronic Deposits/Additions\" => if not found then blank => bottom => get line below\n@creditsBottom2 = get line starting \"Total ACH and Electronic Deposits/Additions\" => if not found then blank => top => get line above\n@credits2 = get multi page table @creditsTop2 @creditsBottom2 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Credit\n\n// Card Transactions/Withdrawals table\ngo to page 1\n@DebitsTop1 = get line starting \"Card Transactions/Withdrawals\" => if not found then blank => bottom => get line below\n@DebitsBottom1 = get line starting \"Total Card Transactions/Withdrawals\" => if not found then blank => top => get line above\n@Debits2 = get multi page table @DebitsTop1 @DebitsBottom1 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Debit\n\n// Card Deposits/Additions table\ngo to page 1\n@Card_DepositsTop = get line starting \"Card Deposits/Additions\" => if not found then blank => bottom => get line below\n@Card_DepositsBottom = get line starting \"Total Card Deposits/Additions\" => if not found then blank => top => get line above\n@Card_Deposits = get multi page table @Card_DepositsTop @Card_DepositsBottom 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Credit\n\n\n// Other Withdrawals/Subtractions table\ngo to page 1\n@DebitsTop2 = get line starting \"Other Withdrawals/Subtractions\" => if not found then blank => bottom => get line below\n@DebitsBottom2 = get line starting \"Total Other Withdrawals/Subtractions\" => if not found then blank => top => get line above\n@Debits3 = get multi page table @DebitsTop2 @DebitsBottom2 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Debit\n\n//Automated Sweep Transfers/Subtractions\n\ngo to page 1\n@DebitsTop3 = get line starting \"Automated Sweep Transfers/Subtractions\" => if not found then blank => bottom => get line below\n@DebitsBottom3 = get line starting \"Total Automated Sweep Transfers/Subtractions\" => if not found then blank => top => get line above\n@Debits4 = get multi page table @DebitsTop3 @DebitsBottom3 35 128 465 560 => describe table false \"Date[MM-dd]\" Details *#Debit\n\n// Get start & end of cheques table\n@chequeTop = get line starting \"Check # Amount Date\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Skip in check sequence\" => if not found then blank => top => get line above\n@chequeLeft = get multi page table @chequeTop @chequebottom 55 165 255 310 => describe table false ChequeNumber *#Debit \"Date[MM-dd]\"\n@chequeRight = get multi page table @chequeTop @chequebottom 310 400 485 560 => describe table false ChequeNumber *#Debit \"Date[MM-dd]\"\n\n$transactions = combine described tables @credits_ @credits @Card_Deposits @Debits1 @credits2 @Debits2 @Debits3 @Debits4 @chequeLeft @chequeRight','2025-10-29 06:16:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10577,'Amex_HongKong','$source = \"Amex_HongKong\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodbufferdays = 14\n\nset negative marker \"CR\"\n\n@baltop = get line containing \"Payment Due HK$\" => top\n@balbottom = get line containing \"Payment Due HK$\" => top => get line below => bottom\n\ndelete text in box @baltop @balbottom 430 page.right\n\n@toptxt = get line containing \"American Express International, Inc\" => top\n@bottomtxt = get line starting \"HONG KONG\" => bottom\ndelete text in box @toptxt @bottomtxt page.left page.right\n\n@topfooter = get line starting \"#The All-Inclusive exchange rate\" => top\ndelete text in box @topfooter page.bottom page.left page.right\n\ngo to page 1\n@acctxt = get line starting \"Cardmember Name Account Number\" => bottom => get line below\n$accountNumber = take last words @acctxt 4 => take words 1 => get text\n$accountName = take words @acctxt 2 => get text\n@accountName = take words @acctxt 2 => get text\n\n// Get opening/closing balances\n@baltxt = get line starting \"Previous Balance New Credits\" => bottom => get line below\n$openingBalance = get words before @baltxt \"-\" => get decimal\n$closingBalance = get words after @baltxt \"=\" => get decimal\n\n// Get Dates\n@periodtxt = get line starting \"STATEMENT PERIOD\" => get words after \"From\"\n$periodFrom = take words @periodtxt 2 => get date \"MMMM d\"\n$periodTo = take last words @periodtxt 3 => get date \"MMMM dd,yyyy\"\n\n// Get top & bottom of transaction table\n@transactionsTop = get line starting \"DETAILS FOREIGN SPEND AMOUNT HK$\" => bottom => get line below\n@transactionsBottom = get last line starting \"Total of New Transactions\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"New Transactions for\"\ndelete all lines starting \"Card Number\"\ndelete all lines starting \"Cardmember Name Account Number\"\ndelete all lines starting \"DETAILS FOREIGN SPEND AMOUNT HK$\"\ndelete all lines starting \"Total of New Transactions for\"\ndelete all lines starting \"Total of new transactions for\"\ndelete all lines starting \"Statement of Account\"\ndelete all lines starting \"#The All-Inclusive exchange rate\"\ndelete all lines containing \"Important Information section of the statement\"\ndelete all lines starting @accountName\ndelete all lines containing \"XXXXXXXXXXX\"\n\n@OthersTop = get line starting \"Other Account Transactions\" => if not found then blank => bottom => get line below\n@OthersBottom = get last line starting \"Total of Other Account Transactions\" => if not found then blank => top => get line above\n\nignore header above 702\ndelete all lines starting \"Total of other account transactions\"\n\n// Read the transactions\n@Fixtransactions = get multi page table @transactionsTop @transactionsBottom 10 80 290 265 450 550 => describe table false \"*Date[MMM d]\" TransactionType - Details #Credit\n@othertransactions = get multi page table @OthersTop @OthersBottom 10 80 290 265 450 550 => describe table false \"*Date[MMM d]\" TransactionType - Details #Credit\n\n// Combine the transactions\n$transactions = combine described tables @Fixtransactions @othertransactions','2025-07-24 06:50:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10578,'DIME_Bank','$source = \"DIME_Bank\"\n\n// Get account name and number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take last words 1 => get text\n\n$accountName = get text in box 754 732 page.middleX page.right => take words 3 => get text\n\n//Get Periods\n$periodTop = get line containing \"Account Summary\" => bottom => get line Below => bottom\n\n$periodBottom =  get last line containing \"Ending Balance\" => bottom\n\n$periodTextBox = get text in box $periodTop $periodBottom  page.left 455\n\n$periodFrom =  get words before $periodTextBox \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n$periodTo = get words before $periodTextBox \"Ending Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\n\n//Get Opening and Closing Balances\n$openingBalance = get words after $periodTextBox \"Beginning Balance\" => take words 1 => get decimal\n\n$closingBalance = get words after $periodTextBox \"Ending Balance\" => take words 1 => get decimal\n\ngo to page 1\n\n//delete Account Summary transactions\ndelete text in box  $periodTop $periodBottom  page.left page.right => get text\n\n// Get start & end of all Credits table\n\n@creditsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Electronic Debits\" => if not found then blank => top => get line above\n\n// Get start & end of all Debits table\n\n@debitsTop = get line starting \"Electronic Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n\n//get start and end check\n@chequeTop = get line containing \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Daily Balances\" => if not found then blank => top => get line above\n\nremove page 2\n//delete all pages containing \"You do not have\"\ndelete all lines containing \"Non Personal Checking\"\ndelete all lines containing \"Business Advantage Checking\"\ndelete all lines containing \"(continued)\"\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Electronic Credits\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"Electronic Debits\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines ending \"Member FDIC\"\ndelete all lines starting \"Check Nbr Date Amount\"\ndelete all lines containing \"Indicates skipped check number\"\n\nignore header above 729\n\nignore footer below 30\n\n// Read the transactions\n@credits = get multi page table @creditsTop @creditsBottom 30 85 515 585 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@debits = get multi page table @debitsTop @debitsBottom 30 85 515 585 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\n@checksleft = get multi page table @chequeTop @chequebottom 54 126 220 300 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" *#Debit\n@checksright = get multi page table @chequeTop @chequebottom 325 414 500 585 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" *#Debit\n\n$transactions = combine described tables @credits @debits @checksleft @checksright','2025-01-23 08:29:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10579,'PayPalSummary_MasterCard','$source = \"PayPalSummary_MasterCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodbufferdays = 30\n\ndelete tiny words\ndelete rotated words\n\n// Get Account name\n$accountName = get line containing \"Account number:\" => top => get line above => take last words 2 => get text\n\n// Get Account number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take last words 1 => get text\n\n// Get Dates\n@periodFromtxt = get line containing \"Previous balance as of\" => get words after \"Previous balance as of\"\n$periodFrom = take words @periodFromtxt 1 => get date \"MM/dd/yyyy\"\n@periodTotxt = get line containing \"New balance as of\" => get words after \"New balance as of\"\n$periodTo = take words @periodTotxt 1 => get date \"MM/dd/yyyy\"\n\n// Get Opening/closing\n$openingBalance = take words @periodFromtxt 2 => take last words 1 => get decimal\n$closingBalance = take words @periodTotxt 2 => take last words 1 => get decimal\n\n// Get top of the transaction table\n@transactionsTop = get line starting \"Date Reference # Description\" => bottom => get line below\n@transactionsBottom = get line containing \"Year to date fees and interest\" => top => get line above\n\ngo to page 1\nget line containing \"(Continued on next page)\" => top => ignore footer below\n\n// delete some extra lines\nignore header above 912\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Purchases and Other Debits\"\ndelete all lines starting \"Total Fees Charged This Period\"\ndelete all lines starting \"Total Interest Charged This Period\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"Date Reference # Description\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 70 170 420 500 => describe table false \"*Date[MM/dd]\" TransactionType Details #Credit','2025-01-23 08:29:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10580,'Westchester_Bank','$source = \"Westchester_Bank\"\n\n// Get Account number\n$accountNumber = get line containing \"Summary of Accounts\" => bottom => get line below => bottom => get line below => get words before \"$\" => take last words 1 => get text\n\n// Get Account name\n@TEXTBOXAcctTop = get line containing \"ADDRESS SERVICE REQUESTED\" => bottom\n@TEXTBOXAcctBottom = get line containing \"Summary of Accounts\" => top\n$accountName = get text in box @TEXTBOXAcctTop @TEXTBOXAcctBottom 0 250 => take words 3 => get text\n\n// Get opening & closing Balance\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Account Activity\" => top => get line above => get words after \"Ending Balance\" => get decimal\n\n// Get statement period\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/dd/yyyy\"\n$periodTo = get line starting \"Account Activity\" => top => get line above => get words before \"Ending Balance\"  => get date \"MM/dd/yyyy\"\n\ngo to page 1\n@transactionsTop = get line starting \"Post Date Description Debits\" => bottom => get line below\nremove page 2\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\nignore header above 672\nignore footer below 20\n\ndelete all lines starting \"Post Date Description Debits\"\ndelete all lines containing \"Beginning Balance\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 350 425 520 580  => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance\n','2025-01-23 08:29:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10581,'CapitalOne_Bank','$source = \"CapitalOne_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = \"45\"\n\n// Get account name\n$accountName = get text in box 635 570 page.left page.middleX => take words 2 => get text\n\n// Get account number\n\n$accountNumber = \"Incorrect AccountNumber\"\n\n// Opening and Closing Balance\n\n@TEXTBOXTop = get line containing \"Previous\" => top\n@TEXTBOXBottom = get line starting \"Ending Balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom page.left page.middleX\n\n$openingBalance = get words after @TEXTBOX \"Previous Balance\" => take words 2 => take last words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take last words 1 => get decimal\n\n// Get periods\n$periodFrom = get line containing \"FOR PERIOD\" => get words before \"-\" => take last words 3 => get date \"MMMM dd,yyyy\"\n$periodTo = get line containing \"FOR PERIOD\" => get words after \"-\" => take last words 3 => get date \"MMMM dd,yyyy\"\n\nremove page 2\ngo to page 1\n@transactionsTop = get line containing \"Date Description Deposits/Credits Withdrawals/Debits Resulting Balance\" => bottom => get line below\n\ndelete all lines containing \"PAGE\"\ndelete all lines containing \"Products and services are offered\"\ndelete all lines containing \"All rights reserved.\"\ndelete all lines containing \"ACCOUNT DETAIL\"\ndelete all lines containing \"Date Description\"\n\n@transactionsBottom = get line starting \"Total\" => top => get line above\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 85 67 290 390 500 600 => describe table false \"Date[MM/dd]\" - Details #Credit #Debit *#Balance\n\n','2025-01-23 08:29:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10582,'Lloyds_BankofScotland_ProductDetails','$source = \"Lloyds_BankofScotland_ProductDetails\"\n\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n@accountDetailsbottom = get line containing \"Current balance\" => top\n@accountDetails = get text in box 780 @accountDetailsbottom 0 300\n\n$accountName = get words before @accountDetails \"Current balance\" => take words 3 => get text\n$accountNumber = get words before @accountDetails \"View IBAN\" => take last words 1 => get text\n\ndelete all lines starting \"DATE DESCRIPTION\"\n\n//$closingbalance = get line starting \"Out\" => bottom => get line below => take last words 1 => get decimal\n@closingTop = get line starting \"Out\" => bottom\n@closingBottom = get text in box @closingTop 0 322 400 => take words 1 => bottom => get line below => top\n$closingbalance =  get text in box @closingTop @closingBottom 322 400  => get decimal\n\n//$PeriodTo = get line starting \"Out\" => bottom => get line below => take words 3 => get date \"d MMM yy\"\n@periodToBottom = get text in box @closingTop 0 35 90 => take words 1 => bottom => get line below => top\n$periodTo = get text in box @closingTop @periodToBottom 35 90 => get date \"dMMMyy\"\n\nignore footer below 12\n\ngo to page 1\n\n@transactionstop = get line starting \"Out\" => bottom => get line below\n\n@openingBottom = get line starting \"You have no more transactions to display\" => top\n//@openingTop = get text in box page.top @openingBottom 322 400 => take last words 1 => top => get line above => bottom\n//$openingbalance =  get text in box @openingTop @openingBottom 322 400 => get decimal\n\n@periodFromtop = get text in box page.top @openingBottom 35 90 => take last words 1 => top => get line above => bottom\n$periodFrom = get text in box @periodFromtop @openingBottom 35 90 => get date \"dMMMyy\"\n\n@transactionsbottom = get last line starting \"You have no more transactions to display\" => top => get line above\n\ndelete all lines starting \"https://securebusiness\"\ndelete all lines containing \"- View Product Details\"\n\n//$transactions = get multi page table @transactionstop @transactionsbottom 35 90 207 190 225 290 265 322 400 => describe table false \"*Date[dMMMyy]\" Details - TransactionType #Credit - #Debit #Balance\n$transactions = get multi page table @transactionstop @transactionsbottom 35 90 207 195 225 290 265 322 400 => describe table false \"*Date[dMMMyy]\" Details - TransactionType #Credit - #Debit #Balance','2025-02-12 08:09:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10583,'UBS_WealthManagement','$source = \"UBS_WealthManagement\"\nset negative marker \"DR\"\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get Account Name\n$accountName = get line containing \"Account Name:\" => get words after \"Account Name:\" => take words 2 => get text\n\n// Get statement Period\n$periodFrom = get line containing \"Opening Balance as at\" => get words after \"Opening Balance as at\" => take words 3 => get date \"dd MMM yyyy\"\n@TextBoxTop = get last line containing \"Date Value Date Entry Details\" => bottom\n@TextBoxBottom = get line containing \"Closing Balance\" => top\n@TextBox = get text in box @TextBoxTop @TextBoxBottom 0 110\n$periodTo = take last words @TextBox 3 => get date \"dd MMM yyyy\"\n\n// Get opening & closing Balance\ngo to page 1\n$openingBalance = get line containing \"Opening Balance as at\" => get words after \"Opening Balance as at\" => skip words 3 => get decimal\n$closingBalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\n// Get start & end of Transactions\ngo to page 1\n@TransactionTop = get line containing \"Date Value Date Entry Details\" => bottom => get line below => bottom => get line below\n@TransactionBottom = get line containing \"Closing Balance\" => top => get line above\n\nignore header above 420\nignore footer below 100\ndelete all lines containing \"Date Value Date Entry Details\"\n\n// Transactions\n$transactions = get multi page table @TransactionTop @TransactionBottom 0 110 170 230 500 625 700 780 => describe table false \"*Date[dd MMM yyyy]\" - TransactionType Details #Debit #Credit #Balance','2025-02-12 08:09:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10584,'FMB_RG_Bank','$source = \"FMB_RG_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n$accountname = get line starting \"Account Title\" => bottom => get line below => take words 1 => get text\n@summarytop = get line starting \"Account Number\" => top\n@summarybottom = get line starting \"Ending Balance\" => bottom\n$summary = get text in box @summarytop @summarybottom page.left 300\n$accountNumber = get words after $summary \"Account Number\" => take words 1 => get text\n\n$openingBalance = get words after $summary \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get words after $summary \"Ending Balance\" => take words 1 => get decimal\n\ngo to page 1\n$periodFromText = get line containing \"Statement Dates\" => get words after \"Statement Dates\"\n$periodFrom = take words $periodFromText 1 => get date \"M/d/yy\"\n$periodTo = take last words $periodFromText 1 => get date \"M/d/yy\"\n\n\n// Get start & end of Deposits table\ngo to page 1\n@depositsTop = get line starting \"Deposits and Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@depositsBottom = get line starting \"Checks and Other Debits\" => if not found then blank => top => get line above\n\n// Get start & end of Checks and Other Debits table\ngo to page 1\n@debitsTop = get line starting \"Checks and Other Debits\" => if not found then blank => bottom => get line below => bottom => get line below\n@debitsBottom = get last line starting \"Checks and Other Debits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\n// Get start & end of Checks table\ngo to page 1\n@checks1Top = get line starting \"Checks In Number Order\" => if not found then blank => bottom => get line below => bottom => get line below\n@checks1Bottom = get line starting \"* Denotes missing check numbers\" => if not found then blank => top => get line above\ngo to page 1\n@checks2Top = get line starting \"Checks In Number Order\" => if not found then blank => bottom => get line below => bottom => get line below\n@checks2Bottom = get line containing \"Denotes missing check numbers\" => if not found then blank => top => get line above\ngo to page 1\n@checks3Top = get line starting \"Checks In Number Order\" => if not found then blank => bottom => get line below => bottom => get line below\n@checks3Bottom = get line containing \"Denotes missing check numbers\" => if not found then blank => top => get line above\n\n$delpage = delete all pages containing \"UPDATING YOUR CONTACT INFORMATION:\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Date Check#\"\ndelete all lines containing \"Deposits and Other Credits\"\ndelete all lines containing \"Checks and Other Debits\"\ndelete all lines containing \"Checks In Number Order\"\ndelete all lines containing \"Denotes missing check numbers\"\n\nignore header above 655\nignore footer below 80\n// Read the transactions\n@deposits = get multi page table @depositsTop @depositsBottom 50 100 490 560 => describe table false \"*Date[M/d]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 50 100 490 560 => describe table false \"*Date[M/d]\" Details #Debit\n@checksleft = get multi page table @checks1Top @checks1Bottom 50 100 150 215 => describe table false \"*Date[M/d]\" Details #Debit\n@checksright1 = get multi page table @checks2Top @checks2Bottom 230 270 320 390 => describe table false \"*Date[M/d]\" Details #Debit\n@checksright2 = get multi page table @checks3Top @checks3Bottom 410 440 470 560 => describe table false \"*Date[M/d]\" Details #Debit\n\n$transactions = combine described tables @deposits @debits @checksleft @checksright1 @checksright2','2025-02-12 08:12:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10585,'Discover_Card_MERCHANT_CATEGORY','$source = \"Discover_Card_MERCHANT_CATEGORY\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodbufferdays = 30\n\n//Get Account Number\n$accountNumber = get line containing \"CARD ENDINGIN\" => take last words 1 => get decimal\n//$accountNumber = get line containing \"DISCOVER IT\" => get words after \"DISCOVER IT\" => take last words 1 => get decimal\n\n//Get dates\n$periodFrom = get line starting \"Account Summary\" => get words after \"Account Summary\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line starting \"Account Summary\" => get words after \"-\" => take words 1 => get date \"MM/dd/yyyy\"\n\n//Get Balances\n@Summarytop = get line containing \"Account Summary\" => top\n@Summarybottom = get line starting \"New Balance:\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 0 280\n//$Summary = get text in box @Summarytop @Summarybottom 0 280 => get text\n\n$openingBalance = get words after @Summary \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get words after @Summary \"New Balance:\" => get words after \"New Balance:\" => take words 1 => get decimal\n\n//Get Account Name\n$accountname = get line containing \"OPEN TO CLOSE DATE:\" => take words 2 => get text\n\n//Get start and end of table\n//@transactionsTop = get line containing \"PAYMENTS AND CREDITS AMOUNT\" => bottom => get line below\n\n//@topbox = get line containing \"Cashback Bonus\" => top\n//@bottombox = get line containing \"see Information For You section\" => bottom\n//delete text in box @topbox @bottombox 410 page.right\n\n//to delete right side text\n@PointertoPage = get line containing \"TRANS.\" => top\ndelete text in box page.top page.bottom 410 page.right\n\n//Get Credit table\n@transactionsTopCredit = get line containing \"PAYMENTS AND CREDITS\" => if not found then blank => bottom => get line below\n@transactionsBottomCredit = get line containing \"DATE PURCHASES MERCHANT CATEGORY\" => top => get line above\n\n//Get Debit table\n@transactionsTopDebit = get line containing \"DATE PURCHASES MERCHANT CATEGORY\" => if not found then blank => bottom => get line below\n@transactionsBottomDebit = get line starting \"Fees and Interest Charged\" => top => get line above\n\nignore header above 720\ndelete all lines containing \"TRANS.\"\ndelete all lines containing \"PURCHASES MERCHANT CATEGORY\"\ndelete all lines containing \"Transactions continued\"\ndelete all lines containing \"OPEN TO CLOSE DATE:\"\ndelete all lines containing \"CARD ENDINGIN\"\ndelete all lines starting \"Continued on next page\"\n\n@InterestTop = get line starting \"Fees and Interest Charged\" => bottom => get line below\n@InterestBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines containing \"Fees and Interest Charged continued\"\ndelete all lines containing \"INTEREST CHARGED FOR THIS PERIOD\"\ndelete all lines containing \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines containing \"FEES FOR THIS PERIOD\"\n\ndelete all lines containing \"INTEREST CHARGE ON CASH ADVANCES $0.00\"\ndelete all lines containing \"INTEREST CHARGE ON BALANCE TRANSFERS $0.00\"\n\n// Read the transactions\n@transactionsDebit = get multi page table @transactionsTopDebit @transactionsBottomDebit 15 65 58 255 235 340 330 410 => describe table false \"*Date[MM/dd]\" - TransactionType - Details - #Credit\n@IntTrans = get multi page table @InterestTop @InterestBottom 15 300 410 => describe table false Details #Credit\n\n//to delete Footer on last page to avoid grab into credit table\n@Feetop =  get line starting \"Fees and Interest Charged\" => top\ndelete text in box @Feetop page.bottom 0 page.right\n\n@transactionsCredit = get multi page table @transactionsTopCredit @transactionsBottomCredit 15 65 58 255 235 350 410 => describe table false \"*Date[MM/dd]\" - TransactionType - Details #Credit\n\n//combine the transactions\n$transactions = combine described tables @transactionsDebit @IntTrans @transactionsCredit','2025-05-29 06:49:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10586,'Skrill_Bank_ID_TransactionID_Date_Type_TransactionDetails','$source = \"Skrill_Bank_ID_TransactionID_Date_Type_TransactionDetails\"\n//$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n@accountBottom  = get line starting \"Transaction Report\" => top\n$accountName = get text in box page.top @accountBottom page.left page.middleX => get text\n$accountNumber = get line containing \"ID\" => get words after \"ID\" => take words 1 => get text\n\n$openingBalance = get line containing \"Start Balance\" => get words after \"Start Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"End Balance\" => get words after \"End Balance\" => take words 1 => get decimal\n\n$periodFrom = get line containing \"Start Balance\" => bottom => get line below => take words 2 => take words 1 => get date \"d.MM.yy\"\n\n@PeriodTextTotop = get line containing \"End Balance\" => bottom => get line below => top\n@PeriodTextTobottom = get line containing \"End Balance\" => bottom => get line below => bottom\n$periodTo = get text in box @PeriodTextTotop @PeriodTextTobottom  page.middleX page.right => take words 1 => get date \"d.MM.yy\"\n\ngo to  page 1\n@summeryBottom = get line containing \"Date Type Transaction details\" => top\n$deleteSummery = delete text in box page.top @summeryBottom page.left page.right => get text\n\ngo to page 1\n@GetAllColumnFromLine  = get line containing \"Date Type Transaction details\"  => get text\n\n@dateLeft =  get line containing @GetAllColumnFromLine => get words before \"Type\" => take last words 1 => left => subtract 3\n@TypeLeft =  get line containing @GetAllColumnFromLine => get words before \"Transaction details\" => take last words 1 => left => subtract 3\n@detailsLeft =  get line containing @GetAllColumnFromLine => get words after \"Type\" => take words 1 => left => subtract 5\n@creditLeft =  get line containing @GetAllColumnFromLine => get words after \"Transaction details\" => take  words 1 => left => subtract 3\n@debitLeft =  get line containing @GetAllColumnFromLine => get words after \"Transaction details\" => take  words 4 =>  take last words 2 => take words 1 => left => subtract 5\n@debitRight =  get line containing @GetAllColumnFromLine => get words before \"FX Rate\" => take last words 1 => left => subtract 5\n@balanceLeft =  get line containing @GetAllColumnFromLine => take last words 1 => left => subtract 3\n@balanceRight =  get line containing @GetAllColumnFromLine => take last words 1 => right => add 10\n\ngo to page 1\n@transactionTop = get line containing \"Date Type Transaction details\" => if not found then blank => bottom => get line below\n@transactionbottom = get last line containing \"www.skrill.com\" => if not found then blank => top => get line above\n\ndelete all lines starting \"ID Transaction ID Date\"\ndelete all lines starting \"SKRILL ID Date Type\"\ndelete all lines starting \"PRIVATE AND CONFIDENTIAL\"\ndelete all lines starting \"PRIVATE AND CONFIDENTIAL | www.skrill.com\"\ndelete all lines containing \"Date Type Transaction details\"\n\n//ignore header above 517\nignore footer below 25\n\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @TypeLeft @detailsLeft @creditLeft @debitLeft @debitRight @balanceLeft => describe table false \"*Date[MM/d/yy]\" TransactionType Details #Credit #Debit -\n//$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @TypeLeft @detailsLeft @creditLeft @debitLeft @debitRight @balanceLeft @balanceRight => describe table false \"*Date[MM/d/yy]\" TransactionType Details #Credit #Debit - #Balance\n\n','2025-02-12 08:12:45',0);
