  get line containing @GetAllColumnFromLine => get words after \"Transaction details\" => take  words 1 => left => subtract 3\n@debitLeft =  get line containing @GetAllColumnFromLine => get words after \"Transaction details\" => take  words 4 =>  take last words 2 => take words 1 => left => subtract 5\n@debitRight =  get line containing @GetAllColumnFromLine => get words before \"FX Rate\" => take last words 1 => left => subtract 5\n@balanceLeft =  get line containing @GetAllColumnFromLine => take last words 1 => left => subtract 3\n@balanceRight =  get line containing @GetAllColumnFromLine => take last words 1 => right => add 10\n\ngo to page 1\n@transactionTop = get line containing \"Date Type Transaction details\" => if not found then blank => bottom => get line below\n@transactionbottom = get last line containing \"www.skrill.com\" => if not found then blank => top => get line above\n\ndelete all lines starting \"ID Transaction ID Date\"\ndelete all lines starting \"SKRILL ID Date Type\"\ndelete all lines starting \"PRIVATE AND CONFIDENTIAL\"\ndelete all lines starting \"PRIVATE AND CONFIDENTIAL | www.skrill.com\"\ndelete all lines containing \"Date Type Transaction details\"\n\n//ignore header above 517\nignore footer below 25\n\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @TypeLeft @detailsLeft @creditLeft @debitLeft @debitRight @balanceLeft => describe table false \"*Date[d.MM.yy]\" TransactionType Details #Credit #Debit -\n//$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @TypeLeft @detailsLeft @creditLeft @debitLeft @debitRight @balanceLeft @balanceRight => describe table false \"*Date[d.MM.yy]\" TransactionType Details #Credit #Debit - #Balance\n\n','2025-02-12 08:12:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10588,'BanqueNationalDuCanada_Bank_MasterCard','$source = \"BanqueNationalDuCanada_Bank_MasterCard\"\n\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n//$PeriodBufferDays = 51\n\n$topfooter1 = get last line containing  \"POINTS PLAN RECOMPENSES\" => bottom\n$deletefooter1 = delete text in box  $topfooter1 page.bottom page.left page.right => get text\n\ngo to page 1\n$periodto = get line containing \"$\" => take words 3 => get date \"yy MM dd\"\n$accountBottom = get line containing \"001 $\" => top => get line above => top\n$accountname  = get text in box 675 $accountBottom page.left page.middleX => get text\ngo to page 1\n$accountnumber  = get line containing \"001 $\" => take words 3 => get text\n//Get Balances\n$openingbalance = get line containing \"001 $\" => take last words 1 => get decimal\ngo to page 1\n$closingbalance  = get line containing \"$\" => take words 4 => take last words 1 => get decimal\n\ngo to page 1\n//Get PeriodsFrom\n$periodLineGet =  get line starting \"**** ****** **\" => get text\n$periodfrom = get line containing $periodLineGet => bottom => get line below => take words 2 => get date \"MM dd\"\n\ngo to page 1\n\ndelete all lines starting \"SOMMAIRE\"\ndelete all lines starting \"Limite de\"\ndelete all lines starting \"Limite de crédit\"\ndelete all lines starting \"Limite de crédit inc\"\ndelete all lines starting \"Limite de crédit avances\"\ndelete all lines starting \"Transactions du\"\ndelete all lines starting \"Transactions du mois\"\ndelete all lines starting \"Paiements\"\ndelete all lines starting \"Paiements / crédits du mois\"\ndelete all lines starting \"******\"\ndelete all lines starting \"**** ****** **\"\n\n// Get Transactions\ngo to page 1\n@transactionsTop = get line containing \"001 $\" => bottom => get line below\n@transactionsBottom = get last line containing \"POINTS PLAN RECOMPENSES\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"POINTS PLAN RECOMPENSES\"\ndelete all lines starting \"000\"\ndelete all lines starting \"0000000000\"\ndelete all lines starting \"POINTS PLAN\"\ndelete all lines starting \"POINTS PLAN RECOMPENSES A LA CARTE\"\ndelete all lines starting \"SOLDE REPORTE DE POINTS :\"\ndelete all lines starting \"POINTS ECHANGES CE MOIS :\"\ndelete all lines starting \"POINTS ACCUMULES CE MOIS :\"\ndelete all lines starting \"NOUVEAU SOLDE DE POINTS :\"\nignore header above 480\nignore footer below 150\n\n$footerTop = get last line containing  \"VEUILLEZ NE PAS EFFECTUER DE PAIEMENT\" => top\n$deletefooter = delete text in box  $footerTop page.bottom page.left page.right => get text\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 14 60 131 170 437 415 500  => describe table false \"tranDate[MM dd]\" TransactionType \"*Date[MM dd]\" Details - #Credit','2025-02-12 08:12:47',0);
