age.left page.bottom => get text\n\ngo to page 1\n\n$accountnumberbottom = get line starting \"Account number:\" => top\n$deleteBelowIaccountnumberbottomAllLines = delete text in box $accountnumberbottom page.bottom page.left page.right => get text\n\n$Interestrates = get line starting \"Interest rates\" =>  if not found then blank => bottom\n$deleteBelowInterestratesAllLines = delete text in box $Interestrates page.bottom page.left page.right => get text\n\n$trnsbottom = get last line starting \"Sub total\" => bottom\n$deleteLasttrnsbottom = delete text in box $trnsbottom page.bottom page.left page.bottom => get text\n\ndelete all lines containing \"Account activity Amount\"\ndelete all lines starting \"Sub total\"\ndelete all lines starting \"Total payment activity\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"Interest rates\"\ndelete all lines starting \"Account number:\"\ndelete all lines starting \"President\"\ndelete all lines starting \"4847\"\n\n\nignore header above $accountSummerytop\nignore footer below $accountnumberbottom\n\n$transactions = get multi page table $transactionsTop $transactionsBottom 37 91 132 328 380  => describe table false \"tranDate[d MM]\" \"*Date[d MM]\" Details #Credit\n','2025-02-12 08:12:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10598,'BankPlus_BankUS','$source = \"BankPlus_BankUS\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ngo to page 1\n@pagecount = delete all pages containing \"SUGGESTIONS TO HELP YOU BALANCE YOUR BANK STATEMENT\"\n\ngo to page 1\n//Get Accounts\n$accountname =   get line containing \"PAGE\" => bottom => get line below => bottom => get line below => get text\n$accountnumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//Get Periods\n$periodfrom = get line containing \"Statement Dates\" => get words before \"thru\" => take last words 1 => get date \"M/d/yy\"\n$periodto = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/d/yy\"\n\n\n//Get Balance\n$openingbalance =  get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingbalance = get line starting \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n\n@Checktop = get line starting \"Date Serial Amount\" => if not found then blank => bottom => get line below\n@Checkbottom = get last line containing \"Denotes missing check numbers\" => if not found then blank => top => get line above\ndelete all lines starting \"Check Transactions\"\n\n//Check Tables\n@Checklefttransactions = get multi page table @Checktop @Checkbottom 50 90 190 290 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\n@CheckRighttransactions = get multi page table @Checktop @Checkbottom 291 323 450 525 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\n\ngo to page 1\n//delete check table1\n@checktopLine  = get line starting \"Date Serial Amount\" => top\n@checkbottomLine = get line containing \"Denotes missing check numbers\" => bottom\n@delectCheckBox = delete text in box @checktopLine @checkbottomLine page.left page.right => get text\n\n\ngo to page 1\n//Delete First transaction above\n@trnstop = get line starting \"Date Description Amount\" => top\n@deletetrnstop = delete text in box page.top @trnstop page.left page.right => get text\n\n// Get Transactions\ngo to page 1\n@transactionsTop = get line starting \"Date Description Amount\" =>  if not found then blank => bottom => get line below\n@transactionsBottom = get last line containing \"Balance By Date\" => if not found then blank => top => get line above\n\n//Set dynamic Co-Ordinate\ngo to page 1\n@CordinateAll = get line starting \"Date Description Amount\" => get text\n@dateLeft = get line containing @CordinateAll => take words 1 => left => subtract 5\n@DetailLeft = get line containing @CordinateAll =>  get words after \"Date\" => take words 1 =>  left => subtract 3\n@AmountLeft = get line containing @CordinateAll => get words after \"Description\" => take words 1 =>  left => subtract 20\n@AmountRight = get line containing @CordinateAll => get words after \"Description\" => take words 1 => right => add 10\n\n\n//Delete last transaction footer bottom\n@lastTrnsFooter =  get last line starting \"Balance By Date\" => top\n@deletelastTrnsFooter = delete text in box @lastTrnsFooter page.bottom page.left page.right => get text\n\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Balance By Date\"\ndelete all lines starting \"Deposits and Additions\"\ndelete all lines starting \"Checks and Withdrawals\"\ndelete all lines starting \"Check Transactions\"\ndelete all lines starting \"Date Serial Amount\"\ndelete all lines containing \"Denotes missing check numbers\"\ndelete all lines starting \"***CHECKING**\"\ndelete all lines starting \"VALUEPLUS BUSINESS\"\n//ignore header above 468\n\nignore footer below 60\n@DbCrtransactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @DetailLeft @AmountLeft @AmountRight => describe table false \"*Date[M/d]\" Details #Credit\n$transactions = combine described tables @DbCrtransactions @Checklefttransactions @CheckRighttransactions','2025-02-12 08:13:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10599,'ATB_Transaction_history','$source = \"ATB_Transaction_history\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW REVERSE_ORDER\"\n$periodBufferDays = \"45\"\n\n\n// Get account name\n$accountName = \"ATB_Transaction_history\"\n\n\n// Get account number\ngo to page 1\n$accountNumber = get line containing \"Filters applied:\" => top => get line above => take words 1 => get text\n\n//PeriodFrom and PeriodTo\n\n$PeriodFrom = get line containing \"Date (from)\" => top => get line below => take words 3 => get date \"MMM dd yyyy\"\n\n$PeriodTo = get line containing \"Date (from)\" => top => get line below => take words 6 => take last words 3 => get date \"MMM dd yyyy\"\n\n// Opening and Closing Balance\n\n$OpeningBalance = get line containing \"Debit Credit Running balance\" => top => get line below => take last words 1 => get decimal\n\n@closingbottom = get last line containing \"Page\" => top\n@closingtop = get text in box page.top @closingbottom 500 page.right => take last words 1 => top\n\n$closingbalance = get text in box @closingtop @closingbottom 500 page.right => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Description Type Debit Credit Running balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Page\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"Date Description Type Debit Credit Running balance\"\ndelete all lines containing \"Page\"\n\nignore header above 850\nignore footer below 22\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 5 85 230 300 400 500 600 => describe table false \"*Date[MMM dd yyyy]\" Details - #Debit #Credit #Balance','2025-02-12 08:13:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10600,'HSBC_DateDetailPaidout','$source = \"HSBC_DateDetailPaidout\"\n\ndelete white words\n\n// Get account name and number\n@accountNumberLeft = get line containing \"Account number\" => get words before \"number\" => take last words 1 => left => subtract 5\n@accountNumberRight = add @accountNumberLeft 100\n@accountLine = get line containing \"Account number\" => bottom => get line below\n@accountNameTop = top @accountLine\n@accountNameBottom = bottom @accountLine\n\n$accountName = get text in box @accountNameTop @accountNameBottom 20 200 => get text\n$accountNumber = get text in box @accountNameTop @accountNameBottom @accountNumberLeft @accountNumberRight => get text\n\n// Get period from\n@periodBottom = get line containing \"Account number\" => top\n@periodTop = add @periodBottom 80\n//$period = get text in box @periodTop @periodBottom 0 page.middleX\n//$periodTo = take last words $period 3 => get date \"dd MMM yyyy\"\n\n$periodFrom = get line containing \"BALANCE BROUGHT\" => get words before \"BALANCE BROUGHT\" => take last words 3 => get date \"dd MMM yyyy\"\n\n// Discard the address as it interferes with the balance block\n@pointerbalance = get line containing \"Opening Balance\"\ndelete text in box page.top @periodTop page.left page.middleX\n\n// Get opening and closing balances\n//$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\ngo to page 1\n@dateRight = get line containing \"Date Detail Paid out Paid in Balance\" => get words after \"Date\" => take words 1 => left => subtract 10\n\n@debitleft = get line containing \"Date Detail Paid out Paid in Balance\" => get words after \"Detail\" => take words 1 => left => subtract 25\n\n@creditleft = get line containing \"Date Detail Paid out Paid in Balance\" => get words before \"Paid in\" => take last words 1 => right => add 15\n\n@Balanceleft = get line containing \"Date Detail Paid out Paid in Balance\" => get words before \"Balance\" => take last words 1 => right => add 15\n\n@balanceRight = get line containing \"Date Detail Paid out Paid in Balance\" => take last words 1 => right => add 15\n\n// Get start of table before discarding marker text\n@transactionsTop = get line containing \"Date Detail Paid out Paid in Balance\" => bottom => get line below\n\n@topblanklinetop = get line containing \"Date Detail Paid out Paid in Balance\" => bottom\n$openingBalance = get line containing \"BALANCE BROUGHT\" => take last words 1 => get decimal\n\n// delete hidden text in first page\n@topblanklinebottom = get line containing \"BALANCE BROUGHT\" => top\ndelete text in box @topblanklinetop @topblanklinebottom page.left page.right\n\n@transactionsBottom = get last line containing \"BALANCE CARRIED FORWARD\" => top => get line above\n\n$periodToTop = get line containing \"BALANCE CARRIED\" => top => add 1\n$periodToBottom = get line containing \"BALANCE CARRIED\" => bottom => subtract 1\n$periodTo = get text in box $periodToTop $periodToBottom 0 @dateRight => get date \"dd MMM yyyy\"\n\n// Discard page header and footer\nget last line starting \"Date Detail Paid out Paid in Balance\" => top => ignore header above\n\n//Discard page footer\ngo to page 1\nget line above 0 => top => ignore footer below\n\ndelete all lines containing \"Date Detail Paid out Paid in Balance\"\ndelete all lines containing \"BALANCE BROUGHT\"\ndelete all lines starting \"FORWARD\"\n\n// delete hidden text in first line of transaction table of every page\ndelete all lines starting \"s\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 0 @dateRight @debitleft @creditleft @Balanceleft @balanceRight => describe table false \"Date[dd MMM yyyy]\" Details *#Debit *#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @dateRight @debitleft @creditleft @Balanceleft => describe table false \"Date[dd MMM yyyy]\" Details *#Debit *#Credit','2025-02-12 08:13:50',0);
