INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10606,'Farmers State Bank','$source = \"Farmers State Bank\"\n\n$accountNumber = get line starting \"Statement Date:\" => get words after \"Account No.:\" => take words 1 => get text\n$accountname = get line starting \"Statement Date:\" => get words after \"Account No.:\" => take words 1 => get text\n\n$openingBalanceText = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\"\n$periodFrom = take words $openingBalanceText 1 => get date \"MM/d/yy\"\n$openingBalance = take last words $openingBalanceText 1 => get decimal\n\n$closingBalanceText = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\"\n$periodTo = take words $closingBalanceText 1 => get date \"MM/d/yy\"\n$closingBalance = take last words $closingBalanceText 1 => get decimal\n\n// Get start & end of Credit table\ngo to page 1\n@creditTop = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\n@creditBottom = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\n\ngo to page 1\n@creditTop2 = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\n@creditBottom2 = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\n\ngo to page 1\n@creditTop3 = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\n@creditBottom3 = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of Credit second table\ngo to page 1\n@credit2Top = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@credit2Bottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line above\n\n// Get start & end of Debit table\ngo