INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10608,'AmericanExpress_HighYield','$source = \"AmericanExpress_HighYield\"\r\n\r\n// Get account details\r\n$accountName = get line starting \"Account Summary\" => top => get line above => take last words 1 => get text\r\n$accountNumber = get line starting \"Account Summary\" => top => get line above => take last words 1 => get text\r\n\r\n// Get statement period\r\ngo to page 1\r\n$periodFrom = get last line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/d/yyyy\"\r\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => get date \"MM/d/yyyy\"\r\n\r\n// Get opening & closing balance\r\ngo to page 1\r\n$openingBalance = get last line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance =  get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// Table coordinates\r\ngo to page 1\r\n$Date_left = get line containing \"Date Transactions Debits\" => get words before \"Transactions\" => left => subtract 10\r\n$Description_left = get line containing \"Date Transactions Debits\" => get words after \"Date\" => left => subtract 5\r\n$Description_right = get line containing \"Date Transactions Debits\" => get words after \"Transactions\" => left => subtract 50\r\n$Paidout_right = get line containing \"Date Transactions Debits\" => get words before \"Credits\" => right => add 20\r\n$Paidin_right = get line containing \"Date Transactions Debits\" => get words before \"Balance\" => right => add 30\r\n$Balance_right = get line containing \"Date Transactions Debits\" => get words after \"Credits\" => right => add 20\r\n\r\n// Table top & bottom\r\ngo to page 1\r\n$transactionsTop = get line containing \"Date Transactions Debits\" => bottom => get line below\r\n$transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\r\n\r\n// Delete extra text\r\ndelete all lines starting \"Date Transactions Debits\"\r\ndelete all lines containing \"Beginning Balance\"\r\ndelete all lines containing \"Ending Balance\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines containing \"Accounts offered by\"\r\ndelete all lines containing \"Account Owner(s):\"\r\nignore footer below 40\r\nignore header above 600\r\n\r\n// Get transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Description_left $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"*Date[MM/d/yyyy]\" Details #Debit #Credit #Balance','2026-09-08 10:16:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10609,'RBCOnlineBanking','$source = \"RBCOnlineBanking\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$periodBufferDays = 30\n\n// Get account name\n$accountName = get text in box page.top 740 480 page.right => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Available Balance\" => top => get line above => take last words 1 => get text\n\n//Get dates\n$periodFrom = get line starting \"Date Range:\" => get words after \"Date Range:\" => take words 3 => get date \"MMM d,yyyy\"\n$periodTo = get line starting \"Date Range:\" => get words after \"-\" => take words 3 => get date \"MMM d, yyyy\"\n\n//Closing Balance\n$closingbalance = get line containing \"Description\" => bottom => get line below =>  take last words 1 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line containing \"Date Description Withdrawals\" => bottom => get line below\n@transactionsBottom = get last line containing \"Royal Bank of Canada Website\" => top => get line above\n\nignore header above 770\nignore footer below 40\n\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 115 320 510 570 => describe table false \"*Date[MMM d, yyyy]\" Details #Credit #Bal','2025-03-20 06:59:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10610,'ComericaBank_CommercialAccount','$source = \"ComericaBank_CommercialAccount\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Get account name\r\n$accountName = get text in box 685 650 page.left page.middleX => take words 3 => get text\r\n\r\n// Get Account number\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\r\n\r\n// Get Dates\r\n@periodtxt = get line containing \"Account number\" => top => get line above\r\n$periodFrom = take words @periodtxt 3 => get date \"MMMM d, yyyy\"\r\n$periodTo = take last words @periodtxt 3 => get date \"MMMM dd, yyyy\"\r\n\r\n// remove text from right side panel\r\ndelete text in box page.top page.bottom 355 page.right\r\n\r\n// get balances\r\n@BalTop = get line containing \"Beginning balance\" => top\r\n@BalBottom = get line containing \"Ending balance\" => bottom\r\n\r\n$openingbalance = get text in box @BalTop @BalBottom 295 350 => take words 1 => get decimal\r\n$closingbalance = get text in box @BalTop @BalBottom 295 350 => take last words 1 => get decimal\r\n\r\nignore header above 645\r\n\r\n// Checks table 2 top & bottom\r\ngo to page 1\r\n@checkTop2 = get line containing \"Check Amount Date\" => if not found then blank => bottom => get line below\r\n@checkBottom2 = get line starting \"Total checks paid this statement period:\" => if not found then blank => top => get line above\r\n\r\n// remove unwanted lines\r\ndelete all lines starting \"Date Amount Activity\"\r\ndelete all lines starting \"Date Amount ($) Activity\"\r\ndelete all lines starting \"Date Amount ($) Customer Bank\"\r\ndelete all lines starting \"Bank\"\r\ndelete all lines starting \"reference\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"continued next page\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines starting \"Reference numbers\"\r\ndelete all lines containing \"Symbol indicates\"\r\nignore header above 640\r\n\r\n// Electronic Deposits table\r\ngo to page 1\r\n@depositTop = get line starting \"Electronic deposits this statement period\" => if not found then blank => bottom => get line below\r\n@depositBottom = get line starting \"Total Electronic Deposits:\" => if not found then blank => top => get line above\r\n@TransDeposit = get multi page table @depositTop @depositBottom 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Checks table\r\ngo to page 1\r\n@checkTop = get line containing \"Check Amount ($)\" => if not found then blank => bottom => get line below\r\n@checkBottom = get line starting \"Total checks paid this statement period:\" => if not found then blank => top => get line above\r\n@checkleft = get multi page table @checkTop @checkBottom 60 130 200 300 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n@checkright = get multi page table @checkTop @checkBottom 320 390 455 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// other account\r\ngo to page 1\r\n@otheraccTop = get line containing \"Transfer from other accounts this statement period\" => if not found then blank => bottom => get line below\r\n@otheraccBottom = get line containing \"Total Transferred from Other Accounts:\" => if not found then blank => top => get line above\r\n@TransfromOtheraccount = get multi page table @otheraccTop @otheraccBottom 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Checks table 2\r\n@checkleft2 = get multi page table @checkTop2 @checkBottom2 60 130 200 245 320 => describe table false ChequeNumber #Credit \"*Date[MMMdd]\" TransactionType\r\n@checkright2 = get multi page table @checkTop2 @checkBottom2 320 390 460 500 570 => describe table false ChequeNumber #Credit \"*Date[MMMdd]\" TransactionType\r\n\r\n// Other deposit table\r\ngo to page 1\r\n@OtherdepositTop = get line starting \"Other deposits this statement period\" => if not found then blank => bottom => get line below\r\n@OtherdepositBottom = get line starting \"Total Other Deposits:\" => if not found then blank => top => get line above\r\n@TransOtherDeposit = get multi page table @OtherdepositTop @OtherdepositBottom 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Paper deposit table\r\ngo to page 1\r\n@depositTop2 = get line starting \"Paper deposits this statement period\" => if not found then blank => bottom => get line below\r\n@depositBottom2 = get line starting \"Total Paper Deposits:\" => if not found then blank => top => get line above\r\n\r\n@TransDepositleft = get multi page table @depositTop2 @depositBottom2 60 130 190 305 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n@TransDepositright = get multi page table @depositTop2 @depositBottom2 320 390 450 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// ATM transaction table\r\ngo to page 1\r\n@ATMDebitTop  = get line containing \"ATM/Debit Card transactions this statement period\" => if not found then blank =>  bottom => get line below\r\n@ATMDebitBottom = get line containing \"Total ATM/Debit Card Withdrawals:\" => if not found then blank => top => get line above\r\n\r\n@TransATMDebit = get multi page table @ATMDebitTop @ATMDebitBottom 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Electronic debits table\r\ngo to page 1\r\n@debitsTop = get line containing \"Electronic withdrawals this statement period\" => if not found then blank => bottom => get line below\r\n@debitsBottom = get line containing \"Total Electronic Withdrawals:\" => if not found then blank => top => get line above\r\n@TransDebits = get multi page table @debitsTop @debitsBottom 60 130 196 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Other withdrawals table\r\ngo to page 1\r\n@debitsTop2 = get line containing \"Other withdrawals this statement period\" => if not found then blank => bottom => get line below\r\n@debitsBottom2 = get line containing \"Total Other Withdrawals\" => if not found then blank => top => get line above\r\n@TransDebits2 = get multi page table @debitsTop2 @debitsBottom2 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Fee table\r\ngo to page 1\r\n@FeeTop = get line containing \"Fees and service charges this statement period\" => if not found then blank => bottom => get line below\r\n@FeeBottom = get line containing \"Total Fees and Service Charges:\" => if not found then blank => top => get line above\r\n@TransFee = get multi page table @FeeTop @FeeBottom 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// Transfer to other acc table\r\ngo to page 1\r\n@otheraccToptrans = get line containing \"Transfers to other accounts this statement period\" => if not found then blank => bottom => get line below\r\n@otheraccBottomtrans = get line containing \"Total Transferred to Other Accounts:\" => if not found then blank => top => get line above\r\n@TransToOtheraccount = get multi page table @otheraccToptrans @otheraccBottomtrans 60 130 205 580 => describe table false \"*Date[MMMdd]\" #Credit Details\r\n\r\n// combining the transactions\r\n$transactions = combine described tables @TransDeposit @checkleft @checkright @TransfromOtheraccount @checkleft2 @checkright2 @TransOtherDeposit @TransDepositleft @TransDepositright @TransATMDebit @TransDebits @TransDebits2 @TransFee @TransToOtheraccount','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10611,'AmericanMonument','$source = \"AmericanMonument\"\n\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n\n// get account name\n\n@top = get line containing \"Customer Security Awareness\" => bottom\n@bottom = get line containing \"American Momentum Bank will never\" => top\n\n//get account name\n$accountName = get text in box @top @bottom page.left page.middleX => take words 4 => get text\n\n\n//get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Acct Ending\" => take words 1 => get text\n\n// Get opening balances\n$openingBalance = get line containing \"Previous Balancing\" => get words after \"Previous Balancing\" => take words 1 => get decimal\n\n//get closing balances\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n\n// get Statement period from/to\n$period = get line containing \"Statement Dates\" =>  get words after \"Statement Dates\" => take words 3\n$periodFrom = take words $period 1 => get date \"M/dd/yy\"\n\n$periodTo = take last words $period 1 => get date \"M/dd/yy\"\n\n\n// Get start of table\ngo to page 1\n@credit_top = get line starting \"Date Description Amount\" => bottom => get line below\n@debit_closing = get line starting \"SUMMARY BY CHECK NUMBER\" => top => get line above\n\ngo to page 2\nget line containing \"Date Description Amount\" => top => ignore header above\n\n\ndelete all lines starting \"Date Description\"\ndelete all lines starting \"DEBITS AND OTHER WITHDRAWALS\"\n\n$credit_debit = get multi page table @credit_top @debit_closing 30 70 275 390 => describe table false \"Date[M/dd]\" Details  *#Credit\n\n\n\n\n//get transactions bottom\n@check_top = get line starting \"SUMMARY BY CHECK NUMBER\" => bottom => get line below\n@check_bottom = get line starting \"* Indicates Break in Check Order Sequence\" => top => get line above\n\n\ndelete all lines starting \"SUMMARY BY CHECK NUMBER\"\ndelete all lines containing \"SUMMARY BY CHECK NUMBER\"\n\n\n$check_1 = get multi page table @check_top @check_bottom 30 70 165 260 => describe table false \"Date[M/dd]\" ChequeNumber *#Debit\n$check_2 = get multi page table @check_top @check_bottom 261 290 390 500 => describe table false \"Date[M/dd]\" ChequeNumber *#Debit\n\n\n\n$transactions = combine described tables $credit_debit $check_1 $check_2','2025-03-20 07:00:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10612,'FirstFinancialBank','$source = \"FirstFinancialBank\"\n$features = \"NO_TRANSACTION_YEAR\"\ndelete rotated words\n\n$summaryTop = get line starting \"ACCOUNT SUMMARY\" => bottom => get line below => top\n$summarybottom = get line starting \"Ending Balance\" => bottom\n$getsummary = get text in box $summaryTop $summarybottom page.left page.right\n$periodFrom = get words after $getsummary \"Statement Dates\" => take words 1 => get date \"M/d/yy\"\n$periodTo = get words after $getsummary \"thru\" => take words 1 => get date \"M/d/yy\"\n$accountName = get words after $getsummary \"Account Number\" => take words 1 => get text\n$accountNumber = get words after $getsummary \"Account Number\" => take words 1 => get text\n$openingBalance = get words after $getsummary  \"Previous Balance\" => take words 1 => get decimal\n$closingBalance =  take last words $getsummary 1 => get decimal\n\ngo to page 1\n$Date_left = get line containing \"Date Description Amount\" => get words before \"Description\" => take last words 1 => left => subtract 10\n$Description_left = get line containing \"Date Description Amount\" => get words after \"Date\" => left => subtract 5\n$Description_right = get line containing \"Date Description Amount\" => get words after \"Description\" => left => subtract 50\n$Amount_right = get line containing \"Date Description Amount\" => get words after \"Description \" => right => add 40\n\ngo to page 1\n$transactionsTop = get line containing \"Date Description Amount\" => if not found then blank => bottom => get line below\n$transactionsBottom = get line containing \"MISCELLANEOUS DEBITS\" => if not found then blank => top => get line above\n\ngo to page 1\n\n$transactionsTop1 = get line containing \"MISCELLANEOUS DEBITS\" => if not found then blank => bottom => get line below\n//$transactionsBottom1 = get line containing \"DAILY ENDING BALANCE\" => if not found then blank => top => get line above\n$transactionsBottom1 = get last line containing \"MISCELLANEOUS DEBITS\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\n$ChecksTop1 = get line containing \"CHECKS IN SERIAL NUMBER ORDER\" => if not found then blank => bottom => get line below\n$ChecksBottom1 = get line containing \"DAILY ENDING BALANCE\" => if not found then blank => top => get line above\n\nignore header above 568\ndelete all lines containing \"Denotes missing\"\ndelete all lines containing \"CHECKS IN SERIAL NUMBER ORDER\"\ndelete all lines containing \"Check Number\"\ndelete all lines containing \"DAILY ENDING BALANCE\"\n\n$checktransL = get multi page table $ChecksTop1 $ChecksBottom1 35 97 170 311 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n$checktransR = get multi page table $ChecksTop1 $ChecksBottom1 312 371 440 590 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n\n\ndelete all lines containing \"MISCELLANEOUS CREDITS\"\ndelete all lines containing \"MISCELLANEOUS DEBITS\"\ndelete all lines containing \"Date Description\"\n\n\n$transactionscredit = get multi page table $transactionsTop $transactionsBottom $Date_left $Description_left $Description_right $Amount_right => describe table false \"Date[M/d]\" Details *#Credit\n$transactionsdebit = get multi page table $transactionsTop1 $transactionsBottom1 20 85 424 520 => describe table false \"Date[M/d]\" Details *#Credit\n\n$transactions = combine described tables $transactionsdebit $transactionscredit $checktransL $checktransR','2025-03-20 07:00:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10613,'VirginMoney_Clydesdale_PLC','$source = \"VirginMoney_Clydesdale_PLC\"\n\n\n$features = \"NO_TRANSACTION_YEAR\"\n//set negative marker \"OD\"\n\n//deleted garbage values\n//delete rotated words\ndelete text in box on every page page.top 0 0 40\ndelete white words\ndelete tiny words\n\n// get account name\n$accountName = get text in box page.top 735 page.left page.middleX => get text\n\n\n//get account number\n$accountNumberleft = get line containing \"Account number\" => get words before \"number\" => take last words 1 => left => subtract 3\n$accountNumberright = get line containing \"Account number\" => get words after \"Account\" => take words 1 => right => add 5\n$accountNumbertop = get line containing \"Account number\" => bottom\n$accountNumberbottom = get line containing \"Account number\" => bottom => get line below => bottom\n$accountNumber = get text in box $accountNumbertop $accountNumberbottom $accountNumberleft $accountNumberright => get text\n\n//get account number\n//$accountNumber = get line containing \"Account number\" => bottom => get line below => take last words 1 => get text\n\n// get Statement period from/to\n$periodTo = get line containing \"Statement date\" => bottom => get line below => take last words 3 => get date \"dd MMM yyyy\"\n//$periodFrom = get line containing \"Previousstatement\" => get words before \"Previousstatement\" => take words 3 => get date \"dd MMM yyyy\"\n$periodFrom = get line containing \"Previousstatement\" => get words before \"Previousstatement\" => take last words 3 => get date \"dd MMM yyyy\"\n\n\n//get closing balnce\n//@closingtop = get line containing \"Current balance\" => top\n//@closingbottom = get line containing \"DD=DirectDebit\" => bottom\n//$closingBalance = get text in box @closingtop @closingbottom 440 page.right => get decimal\n\n\n//delete all left texts\ngo to page 1\n$del_text = delete text in box on every page page.top 0 440 page.right\nRemove page 2\n\n// Get opening balances\n$openingBalance = get line containing \"Previousstatement\" => get words after \"Previousstatement\" => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Debits Credits Balance\" => bottom => get line below => bottom => get line below\n\n//get transactions bottom\nget last line containing \"Date Description Debits\"\n@transactionsBottom = get line above 0\n\n//ignore headers\ngo to page 1\n$del_text1 = get last line containing \"Date Description Debits\" => top => ignore header above => get text\n\n//delete all lines containing \"Date Description Debits\"\ndelete all lines containing \"Balance brought\"\ndelete all lines containing \"Continued overleaf...\"\ndelete all lines starting \"Clydesdale Bank PLC (trading as VirginMoney)\"\ndelete all lines starting \"Conduct Authority and the Prudential Regulation\"\ndelete all lines starting \"regulatedmortgages and regulated credit agreements\"\ndelete all lines starting \"registered in Scotland (No. SC001111). Registered\"\n\n//ignore footer\nignore footer below 55\n\n//delete extra lines and texts\ndelete all lines containing \"Clydesdale Bank PLC (which also\"\ndelete all lines containing \"Financial Conduct Authority and the Prudential\"\ndelete all lines containing \"mortgages and regulated credit agreements are not\"\ndelete all lines containing \"Office: 177 Bothwell Street, Glasgow G2 7ER.\"\ndelete all lines containing \"we stopped charging the\"\ndelete all lines containing \"Funds Fee on this account. No other\"\ndelete all lines containing \"or pop into a Store for copies\"\ndelete all lines containing \"updated and can be found at virginmoney.com\"\ndelete all lines containing \"Have a think about your options\"\ndelete all lines containing \"To make sure your account and the\"\ndelete all lines containing \"You can learn about other accounts at virginmoney.com\"\ndelete all lines containing \"which also trades as Yorkshire Bank and Virgin Money\"\ndelete all lines containing \"which also trades as Yorkshire Bank\"\ndelete all lines ending \"Money Store.\"\n\n//get closing balance\ngo to page 1\n@last_transaction = get last line containing \"Date Description Debits Credits Balance\"\n@last_top = get last line containing \"Date Description Debits Credits Balance\" => bottom\n@last_bottom = get line above 0 => bottom\n$closingBalance = get text in box @last_top @last_bottom 375 435 => take last words 1 => get decimal\n\n\ndelete all lines containing \"Date Description Debits\"\n\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 45 95 210 310 375 435 => describe table false \"Date[dd MMM]\" Details **#Debit **#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 95 210 310 375 => describe table false \"Date[dd MMM]\" Details **#Debit **#Credit','2026-01-07 06:33:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10614,'UMB_Bank','$source = \"UMB_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\ndelete rotated words\ndelete white words\ndelete tiny words\n\n// Get account name\n\n$accountName = get text in box 665 630 60 page.middleX => take words 3 => get text\n\n// Get account number\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n\n//Get TextInBOx\n@TEXTBOXTop = get line containing \"Beginning Balance as of\" => top\n\n@TEXTBOXBottom = get line starting \"Ending Balance as of\" => bottom\n\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 60 330\n\n// Opening and Closing Balance\n\n$openingBalance = get words after @TEXTBOX \"Beginning Balance as of\" => take words 2 => take last words 1 => get decimal\n\n$closingBalance = get words after @TEXTBOX \"Ending Balance as of\" => take words 2 => take last words 1 => get decimal\n\n// Get periods\n\n$periodFrom = get words after @TEXTBOX \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\n\n$periodTo = get words after @TEXTBOX \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\ndelete text in box on every page page.top page.bottom page.left 65\nremove page 2\n\nignore header above 720\n\nignore footer below 55\n\ngo to page 1\n\n@transactionsTop = get line containing \"Date Description Deposits Withdrawals\" => bottom => get line below\n@transactionsBottom = get last line starting \"Totals\" => top => get line above\ndelete all lines containing \"Totals\"\ndelete all lines containing \"Date Description Deposits Withdrawals\"\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 105 440 520 600 => describe table false \"*Date[MMM d]\" Details #Credit #Debit','2025-04-15 05:12:24',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10615,'NationWide_Saving','$source = \"NationWide_Saving\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n$accountName = get text in box 700 650 page.left page.middleX => get text\n\n@leftsummaryTop = get line containing \"Date Details Payments Receipts Balance\" => top\ndelete text in box page.top @leftsummaryTop page.left page.middleX\n\n// Get Account Number\n//$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get decimal\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take last words 1 => get text\n\n//Get opening and closing balances\n$openingBalance = get line containing \"Balance from statement\" => take last words 1 => get decimal\n\n//naigate to last balance for geting closing balance\n//@navigate_for_closing = get last line containing \"AER stands for Annual\" => top\n//$closingBalance = get text in box page.top @navigate_for_closing 510 570 => take last words 1 => get decimal\n\n//get period from\n$periodFrom = get line containing \"Balance from statement\" => bottom => get line below => bottom => get line below => take words 2 => get date \"dd MMM\"\n\n//get periodTo\n$periodTo = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 5 => get date \"d-MM-yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Balance from statement\" => bottom => get line below => bottom => get line below\n\n@detailLeft = get line containing \"Balance from statement\" => get words before \"from statement\" => take last words 1 => left => subtract 4\n\n@footer1 = get line containing \"AER stands for Annual Equivalent\" => top\ndelete text in box @footer1 page.bottom page.left page.right\n\n//get transactions bottom\n//@transactionsBottom = get last line containing \"AER stands for Annual Equivalent\" => top => get line above\nget last line containing \"Date Details Payments Receipts Balance\"\n@transactionsBottom = get line above 0\n\n$closingBalance = get text in box page.top 50 510 570 => take last words 1 => get decimal\n\n//Ignore footer\n//get line containing \"AER stands for Annual Equivalent\" => top => ignore footer below\n\ndelete all lines containing \"AER stands for Annual Equivalent\"\ndelete all lines containing \"Date Details Payments Receipts Balance\"\ndelete all lines containing \"Previous\"\n\ngo to page 1\n//get all transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 35 80 325 415 485 570 => describe table false \"Date[dd MMM]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 @detailLeft 325 415 485 570 => describe table false \"Date[dd MMM]\" Details #Debit #Credit *#Balance','2025-07-24 06:51:02',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10616,'FirstCommonWealth_Bank','$source = \"FirstCommonWealth_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n@dateright = get line containing \"Date Description Debit Credit Balance\" => get words before \"Description\" => take last words 1 => left => subtract 3\n@deleteLeft_rotatedWords = delete text in box on every page page.top page.bottom page.left @dateright => get text\n\ngo to page 1\n// Get Accounts\n$accountNumber = get line containing \"Account #\"  => bottom => get line below => take words 1 => get text\n@account_top = get line containing \"Account #\" => bottom\n@account_bottom = get line containing \"CHECKING ACCOUNTS\" => bottom => get line below => bottom\n$accountName = get text in box @account_top @account_bottom page.left page.right => take last words 4 => get text\n\n//Get Periods\n@periodText = get line Containing \"Statement Dates\" => get text\n$periodFrom = get line Containing @periodText => get words before \"thru\" => take last words 1 => get date \"M/d/yy\"\n$periodTo = get line Containing @periodText => get words after \"thru\" => take words 1 => get date \"M/d/yy\"\n\n// Get Balances\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line Starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n@AllColumns = get line containing \"Date Description Debit Credit\" => get text\n@dateLeft =  get line containing @AllColumns => get words before \"Description\" => take last words 1 => left => subtract 5\n@detailsLeft = get line containing @AllColumns => get words after \"Date\" => take words 1 => left => subtract 3\n@debitLeft = get line containing @AllColumns => get words after \"Description\" => take words 1 => left => subtract 30\n@debitRight = get line containing @AllColumns => get words after \"Description\" => take words 1 => right => add 10\n@creditRight = get line containing @AllColumns => take last words 2 => take words 1 => right => add 10\n@BalanceRight = get line containing @AllColumns => take last words 1 => right => add 20\n\n@CheckSummeryText = get last line containing \"CHECKS PAID SUMMARY\" => top\n@deleteCheckSummeryFooter = delete text in box @CheckSummeryText page.bottom page.left page.right => get text\n\ngo to page 1\n// Get Transactions\n@transactionsTop = get line containing \"Date Description Debit Credit\" => if not found then blank => bottom => get line below\n$gotolastpage = get last line containing \"Date Description Debit Credit\" => bottom\n@transactionsBottom = get line above 0\n\ndelete all lines containing \"Date Description Debit Credit\"\ndelete all lines starting \"Business Checking\"\ndelete all lines containing \"Activity in Date Order\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Continued\"\ndelete all lines starting \"Hometown Checking\"\n\n\nignore header above 600\nignore footer below 20\n\nset negative marker \"-\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailsLeft @debitLeft @debitRight @creditRight @BalanceRight => describe table false \"*Date[M/d]\" Details #Debit #Credit #Balance\n\n\n','2025-03-20 07:08:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10617,'FirstCommonWealth_CreditCard','$source = \"FirstCommonWealth_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR\"\n//set negative marker \"-\"\n@dateright = get line containing \"Date Description Amount Balance\" => get words before \"Description\" => take last words 1 => left => subtract 3\n@deleteLeft_rotatedWords = delete text in box on every page page.top page.bottom page.left @dateright => get text\n\ngo to page 1\n// Get Accounts\n$accountNumber = get line containing \"Account #\"  => bottom => get line below => take words 1 => get text\n@account_top = get line containing \"Account #\" => bottom\n@account_bottom = get line containing \"CHECKING ACCOUNTS\" => bottom => get line below => bottom\n$accountName = get text in box @account_top @account_bottom page.left page.right => take last words 4 => get text\n\n//Get Periods\n@periodText = get line Containing \"Statement Dates\" => get text\n$periodFrom = get line Containing @periodText => get words before \"thru\" => take last words 1 => get date \"M/d/yy\"\n$periodTo = get line Containing @periodText => get words after \"thru\" => take words 1 => get date \"M/d/yy\"\n\n// Get Balances\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line Starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n@AllColumns = get line containing \"Date Description Amount Balance\" => get text\n@dateLeft =  get line containing @AllColumns => get words before \"Description\" => take last words 1 => left => subtract 5\n@detailsLeft = get line containing @AllColumns => get words after \"Date\" => take words 1 => left => subtract 3\n@amountLeft = get line containing @AllColumns => get words after \"Description\" => take words 1 => left => subtract 35\n@amountRight = get line containing @AllColumns => take last words 2 => take words 1 => right => add 10\n@BalanceRight = get line containing @AllColumns => take last words 1 => right => add 20\n\n$CheckSummeryText = get last line containing \"CHECKS PAID SUMMARY\" => top\n$deleteCheckSummeryFooter = delete text in box $CheckSummeryText page.bottom page.left page.right => get text\n\ngo to page 1\n// Get Transactions\n@transactionsTop = get line containing \"Date Description Amount Balance\" => if not found then blank => bottom => get line below\n$gotolastpage = get last line containing \"Date Description Amount Balance\" => bottom\n@transactionsBottom = get line above 0\n\ndelete all lines containing \"Date Description Amount Balance\"\ndelete all lines starting \"Business Checking\"\ndelete all lines containing \"Activity in Date Order\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Continued\"\ndelete all lines starting \"Hometown Checking\"\n\n\nignore header above 600\nignore footer below 20\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailsLeft @amountLeft @amountRight @BalanceRight => describe table false \"*Date[M/d]\" Details #Credit #Balance\n\n\n','2025-03-20 07:08:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10618,'Flagstar_Bank','$source = \"Flagstar_Bank\"\n\n// Get Account number\n$accountNumber = get line containing \"Summary of Accounts\" => bottom => get line below => bottom => get line below => get words before \"$\" => take last words 1 => get text\n\n// Get Account name\n@TEXTBOXAcctTop = get line containing \"Managing Your Accounts\" => bottom\n@TEXTBOXAcctBottom = get line containing \"Online Access\" => top\n$accountName = get text in box @TEXTBOXAcctTop @TEXTBOXAcctBottom 0 250 => take words 3 => get text\n\n// Get opening & closing Balance\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n// Get statement period\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/dd/yyyy\"\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => get date \"MM/dd/yyyy\"\n\nignore header above 685\ndelete all lines containing \"Savings Account Statements\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Electronic Credits\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"Other Debits\"\ndelete all lines containing \"Indicates skipped check number\"\n\n// Delete extra details\n@TEXTBOXAcctTop = get line starting \"Description Items Amount\" => if not found then blank => bottom\n@TEXTBOXAcctBottom = get line starting \"Total\" => top\n@deleteText1 = delete text in box @TEXTBOXAcctTop @TEXTBOXAcctBottom 0 page.right => get text\n\n// Get checks table\ngo to page 1\n@checksTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get line containing \"Interest Rate Changes\" => top => get line above\n\ndelete all lines starting \"Check Nbr Date Amount\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Indicates skipped check number\"\ndelete all lines containing \"Savings Account Statements\"\n\n@checksLeft = get multi page table @checksTop @checksBottom 60 120 200 300 => describe table false Details \"*Date[MM/dd/yyyy]\" #Debit\n@checksRight = get multi page table @checksTop @checksBottom 300 425 500 580 => describe table false Details \"*Date[MM/dd/yyyy]\" #Debit\n\n// Get Debits table\ngo to page 1\n@debitsTop = get line starting \"Electronic Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get last line containing \"item(s) totaling\" => top => get line above\ndelete all lines containing \"item(s) totaling\"\n@debits = get multi page table @debitsTop @debitsBottom 20 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\n\n// Get Credits table\ngo to page 1\n@creditsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Electronic Debits\" => if not found then blank => top => get line above\n@credits = get multi page table @creditsTop @creditsBottom 20 90 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n\n$transactions = combine described tables @credits @debits @checksLeft @checksRight\n','2025-03-20 07:08:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10619,'SagicorBank','$source = \"SagicorBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountNumber = get line starting \"BALANCE BROUGHT FORWARD\" => top => get line above => take last words 1 => get text\n$accountname = get line starting \"BALANCE BROUGHT FORWARD\" => top => get line above => take last words 1 => get text\n\ngo to page 1\n//REGISTRATION NO.\n$periodTexttop = get line starting \"JMD\" => bottom\n$periodTextbottom = get line starting \"JMD\" => bottom => get line below => bottom => get line below => bottom\n$getperiod = get text in box $periodTexttop $periodTextbottom 370 467\n$periodFrom = take words $getperiod 1 => get date \"d/MM/yy\"\n$periodTo = take last words $getperiod 1 => get date \"d/MM/yy\"\n\ngo to page 1\n$openingBalance = get line starting \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => take last words 1 => get decimal\n$closingBalance = get line starting \"BALANCE IN YOUR FAVOUR\" => get words after \"BALANCE IN YOUR FAVOUR\" => take last words 1 => get decimal\n\ngo to page 1\n$transactionsTop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n$transactionsBottom = get last line containing \"BALANCE IN YOUR FAVOUR\" => top => get line above\n\ndelete all lines starting \"Page\"\ndelete all lines starting \"In case of\"\ndelete all lines starting \"For information\"\nignore header above 532\n\n$transactions = get multi page table $transactionsTop $transactionsBottom 25 70 230 290 390 475 590 => describe table false \"*Date[d-MMM]\" Details ChequeNumber #Debit #Credit #Balance','2026-01-07 06:33:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10620,'Viva_Bank','$source = \"Viva_Bank\"\n$periodBufferDays = 45\n\ngo to page 1\n// Get Account Name\n$accountName = get text in box page.top 640 295 page.right => take words 2 => get text\n\n// Get account number\n//$accountNumber = get line containing \"Account ID :\" => get words after \"Account ID :\" => take words 1 => get text\n$accountNumber = get line containing \"Period from\" => bottom => get line below => get words after \":\" => take words 1 => get text\n\n\n// Get Period/From To\n$periodfrom = get line containing \"Period from\" => get words between \"Period from\" \"to\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodto = get last line containing \"Period from\" => get words after \"to\" => take words 1 => get date \"dd/MM/yyyy\"\n\n\n//get openingbalance closingbalance\n//$openingbalance = get line containing \"Balance Brought Forward\" => get words after \"Balance Brought Forward\" =>  take words 1 => get decimal\n\ngo to page 1\n@openingTop = get line containing \"A m o u n t B a l a n c e\" => bottom\n@openingBottom = get line containing \"F o r w a r d\" => bottom => get line below => top\n$openingbalance = get text in box @openingTop @openingBottom 495 page.right => get decimal\n\n//$closingbalance = get last line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => take words 1 => get decimal\n//$closingbalance = get last line containing \"Balance Carried Forward\" => top => get line above => take last words 1 => get decimal\n\n//@closingBottom = get last line containing \"Balance Carried Forward\" => top\n//$closingbalance = get text in box page.top @closingBottom 504 page.right => get text => take last words 1 => get decimal\n@closingBottom = get last line containing \"Balance Carried Forward\" => top => get line above => bottom\n$closingbalance = get text in box @closingBottom page.bottom 495 page.right => get decimal\n\n\ngo to page 1\n//@TransDateleft = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words before \"Value\" => take words 1 => left\n@TransDateleft = get line containing \"Description Amount Balance\" => take words 1 => left\n$TransDateleft = get line containing \"Description Amount Balance\" => get words before \"Value\" => take words 1 => get text\n@TransDateleft = subtract @TransDateleft 15\n\n//@ValueDateleft = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words after \"Transaction\" => take words 1 => left\n@ValueDateleft = get line containing \"Description Amount Balance\" => get words after \"Transaction\" => take words 1 => left\n@ValueDateleft = subtract @ValueDateleft 17\n\n//@ValueDateRight = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words after \"Transaction\" => take words 1 => right\n@ValueDateRight = get line containing \"Description Amount Balance\" => get words before \"Description\" => take last words 1 => right\n//@ValueDateRight = Add @ValueDateRight 20\n//@ValueDateRight = Add @ValueDateRight 5\n@ValueDateRight = Add @ValueDateRight 15\n\n//@AmountLeft = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words after \"Description\" => take words 1 => left\n@AmountLeft = get line containing \"Description Amount Balance\" => get words after \"Description\" => take words 1 => left\n@AmountLeft = subtract @AmountLeft 10\n\n//@AmountRight = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words after \"Description\" => take words 1 => right\n@AmountRight = get line containing \"Description Amount Balance\" => get words after \"Description\" => take words 1 => right\n@AmountRight = Add @AmountRight 15\n\n\n//@BalanceRight = get line containing \"Transaction Value Date Date Description Amount Balance\" => get words after \"Amount\" => take words 1 => right\n@BalanceRight = get line containing \"Description Amount Balance\" => get words after \"Amount\" => take words 1 => right\n@BalanceRight = Add @BalanceRight 10\n\nignore header above 790\nignore footer below 35\n\ngo to page 1\n//@transactionsTop = get line containing \"Balance Brought Forward\" => top => get line below\n@transactionsTop = get line containing \"Forward\" => top => get line below\n@transactionsBottom = get line starting \"Balance Carried Forward\" => bottom => get line above\n\ndelete all lines containing \"Balance Brought Forward\"\ndelete all lines containing \"Balance Carried Forward\"\ndelete all lines containing \"Transaction Value Date Date Description Amount Balance\"\n\n\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 6.5 @TransDateleft @ValueDateleft @ValueDateRight @AmountLeft @AmountRight @BalanceRight => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Balance\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 6.5 @TransDateleft 147 @ValueDateRight @AmountLeft @AmountRight @BalanceRight => describe table false \"Date[dd/MM/yyyy]\" - Details #Credit #Balance','2026-01-07 06:33:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10621,'HSBC_UK_COMMERCIAL_Date_ValueDate','$source = \"HSBC_UK_COMMERCIAL_Date_ValueDate\"\n\n$accountName = get text in box 800 670 page.left page.middleX => take words 2 => get text\n\n@topAcno = get line containing \"Type Of Account Account Number\" => bottom\n@bottomAcno = get line containing \"Type Of Account Account Number\" => bottom => get line below => bottom\n@RightAcno = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => take words 1 => left => subtract 50\n\n//$accountNumber = get line containing \"CURRENT ACCOUNT\" => top => get line above => top => get line above  => take last words 2 => take words 1 => get text\n$accountNumber = get text in box @topAcno @bottomAcno page.middleX @RightAcno => get text\n\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => get words before \"BALANCE BROUGHT FORWARD\" => take words 1 => get date \"ddMMMyyyy\"\n$openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BALANCE BROUGHT FORWARD\" => get decimal\n\n$periodTo = get last line containing \"BALANCE CARRIED FORWARD\" => bottom => get line below => take last words 1 => get date \"ddMMMyyyy\"\n$closingBalance = get last line containing \"BALANCE CARRIED FORWARD\" => get words after \"BALANCE CARRIED FORWARD\" => get decimal\n\ngo to page 1\n@ValuedateLeft = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => get words after \"Date\" => take words 1 => left => subtract 2\n@ValuedateRight = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => get words after \"Value Date\" => take words 1 => left => subtract 5\n@debitLeft = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => get words after \"Details\" => left => subtract 2\n@creditLeft = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => get words after \"Details\" => take words 1 => right => add 2\n@BalLeft = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => get words after \"Deposits\" => left => subtract 15\n\n@transactionsTop = get line containing \"Date Value Date Details Withdrawals Deposits Balance\" => bottom => get line below\n@transactionBottom = get line containing \"CLOSING AVAILABLE BALANCE\" => top => get line above\n\ngo to page 1\nget line containing \"BALANCE BROUGHT FORWARD\" => top => ignore header above\nignore footer below 90\n\ndelete all lines containing \"Date Value Date Details Withdrawals Deposits Balance\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\n\ndelete all lines containing \"AS AT\"\ndelete all lines containing \"CLOSING AVAILABLE BALANCE\"\ndelete all lines containing \"Rates Shown are applicable\"\ndelete all lines containing \"Credit Interest Rates\"\ndelete all lines containing \"All credit balances\"\n\ndelete all lines containing \"Important information about compensation\"\ndelete all lines containing \"Your deposit may be eligible\"\ndelete all lines containing \"eligible for compensation\"\ndelete all lines containing \"(via www.hsbc.co.uk)\"\ndelete all lines containing \"www.hsbc.co.uk)\"\ndelete all lines containing \"For further information about\"\ndelete all lines ending \"www.fscs.org.uk\"\n\n$transactions = get multi page table @transactionsTop @transactionBottom 0 @ValuedateLeft @ValuedateRight @debitLeft @creditLeft @BalLeft 590 => describe table false \"Date[ddMMMyyyy]\" - Details **#Debit **#Credit #Balance','2025-10-29 06:17:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10622,'BBT_Bank_TRUISTCard','$source = \"BBT_Bank_TRUISTCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n// Get Accounts\r\n$accountNumber = get line Containing \"Account number\"  => get words after \"Account number\" => take last words 1 => get text\r\n$accountName = get text in box page.top page.bottom page.left page.middleX => take words 3 => get text\r\n\r\n//Get Periods\r\n@periodText = get line Containing \"Account number\" => top => get line above => get text\r\n$periodFrom = get line Containing @periodText => get words before \"-\" => take last words 1 => get date \"M/d/yy\"\r\n$periodTo = get text in box page.top page.bottom page.middleX page.right =>  get words after \"-\" => take words 1 => get date \"M/d/yy\"\r\n\r\n// Get Balances\r\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"New balance\" => get words after \"New balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@getAllColumns = get line containing \"Transaction description Amount\" => get text\r\n@dateLeft = get line containing @getAllColumns => take words 1 => left => subtract 10\r\n@date1Left = get line containing @getAllColumns => take words 2 => take last words 1 =>  left => subtract 10\r\n@RefLeft = get line containing @getAllColumns => get words before \"Transaction description\" => take last words 1 => left => subtract 10\r\n@DetailsLeft = get line containing @getAllColumns => get words before \"Amount\" => take last words 2 => left => subtract 5\r\n@AmountLeft = get line containing @getAllColumns => get words after \"Transaction description\" => take last words 1 => left => subtract 40\r\n@AmountRight = get line containing @getAllColumns => get words after \"Transaction description\" => take last words 1 => right => add 20\r\n\r\n@Toptext = get line containing \"Transaction description Amount\" => top\r\n@deleteHeaderAbove = delete text in box page.top @Toptext page.left page.right => get text\r\n\r\n@Toptext1 = get line starting \"Please detach bottom portion\" => top\r\n$deletefotterAbove = delete text in box @Toptext1 page.bottom page.left page.right => get text\r\n\r\n@Toptext2 = get line starting \"Interest charge calculation\" => top\r\n@deletefotterAbove = delete text in box @Toptext2 page.bottom page.left page.right => get text\r\ndelete all lines starting \"- B\"\r\ngo to page 1\r\n\r\n// Get Transactions\r\n@transactionsTop = get line containing \"Transaction description Amount\" => if not found then blank => bottom => get line below\r\n//$transactionsBottom = get last line starting \"Interest charge calculation\" => if not found then blank => top => get line above\r\n\r\n$gotolastpage = get last line containing \"Transaction description Amount\" => bottom\r\n@transactionsBottom = get line above 0\r\n\r\ndelete all lines containing \"Transaction description Amount\"\r\ndelete all lines starting \"Interest charge calculation\"\r\ndelete all lines starting \"Cardholder activity\"\r\ndelete all lines starting \"Tran\"\r\ndelete all lines starting \"- B\"\r\ndelete all lines starting \"- A\"\r\ndelete all lines containing \"on your Account\"\r\ndelete all pages containing \"Wemaymake additional adjustments\"\r\n\r\n\r\nignore header above 650\r\n//ignore footer below 70\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @date1Left @RefLeft @DetailsLeft @AmountLeft @AmountRight => describe table false \"tranDate[M/d]\" \"*Date[M/d]\" TransactionType Details #Credit','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10623,'Allica_Bank','$source = \"Allica_Bank\"\r\n\r\n// Get account name\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get opening & closing balance\r\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take words 1 => get decimal\r\n$closingBalance = get last line containing \"Closing balance\" => get words after \"Closing balance\" => take words 1 => get decimal\r\n\r\n// Get statement period\r\ngo to page 1\r\n@periodText = get line containing \"Account Details\"\r\n@periodLeft = get words before @periodText \"Details\" => take last words 1 => left\r\n@periodBottom = get words before @periodText \"Details\" => take last words 1 => top\r\n$periodFrom = get text in box page.top @periodBottom @periodLeft page.right => get words before \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get text in box page.top @periodBottom @periodLeft page.right => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Delete statement period line\r\ngo to page 1\r\n@deleteBottom = get line containing \"Account Details\" => top\r\n@deletePeriodLine = delete text in box page.top @deleteBottom page.left page.right => get text\r\n\r\n// Get account number\r\ngo to page 1\r\n@accountTop = get words before @periodText \"Details\" => take last words 1 => bottom\r\n@accountBottom = get line containing \"Sort code\" => top\r\n$accountNumber = get text in box @accountTop @accountBottom @periodLeft page.right => get words after \"Account number\" => take words 1 => get text\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line containing \"Date Transaction type Details Amount\" => bottom => get line below\r\n@transactionBottom = get last line containing \"Financial Services Compensation Scheme\" => top => get line above\r\n\r\n// Discard header and footer\r\nignore footer below 95\r\nget last line containing \"Date Transaction type Details Amount\" => top => ignore header above\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Date Transaction type Details Amount\"\r\ndelete all lines starting \"Statement\"\r\ndelete all lines starting \"Transactions\"\r\ndelete all lines starting \"Allica Bank Limited\"\r\ndelete all lines starting \"Authority and regulated\"\r\ndelete all lines starting \"Prudential Regulation\"\r\ndelete all lines starting \"Registered\"\r\ndelete all lines ending \"customer.services@allica.bank\"\r\ndelete all lines ending \"Contact us\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionTop @transactionBottom 9 0 100 200 424 500 572 => describe table false \"Date[dd/MM/yyyy]\" TransactionType Details #Credit #Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10624,'BANQUE_POPULAIRE_Bank','$source = \"BANQUE_POPULAIRE_Bank\"\nset culture \"fr-CH\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\ngo to page 1\n// Get Account Name\n$accountName = get text in box 777 660 page.middleX page.right => take words 2 => get text\n// Get account number\n$accountNumber = get line containing \"VOTRE COMPTE COURANT N°\" => get words after \"VOTRE COMPTE COURANT N°\" => take words 1 => get text\n\n// Get Period/From To\n$periodfrom = get line containing \"LIBELLE/REFERENCE\" => bottom => get line below => get words after \"AU\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodto = get last line containing \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => take words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n$openingbalance = get line containing \"LIBELLE/REFERENCE\" => bottom => get line below => get words after \"AU\" => skip words 1 => get decimal\n$closingbalance = get last line containing \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => skip words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"LIBELLE/REFERENCE COMPTA OPERATION\" => top => get line below\n@transactionsBottom = get last line containing \"SOLDE CREDITEUR AU\" => bottom => get line above\n\nignore header above 730\nignore footer below 60\n\ndelete all lines containing \"LIBELLE/REFERENCE\"\ndelete all lines containing \"SOLDE CREDITEUR AU\"\ndelete all lines containing \"VOTRE COMPTE\"\ndelete all lines containing \"TOTAL DES MOUVEMENTS\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 82 265 342 432 500 590 => describe table false \"*Date[dd/MM]\" Details TransactionType - #Debit #Credit ','2025-03-20 07:08:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10625,'BNP_PARIBAS_BankOfTheWest','$source = \"BNP_PARIBAS_BankOfTheWest\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\n\ndelete rotated words\ndelete white words\ndelete tiny words\n\nset negative marker \"-\"\n\n// Get period from and period to\n\n\n//$periodFrom = get line containing \"Statement\"  => bottom => get line below => take words 3 => get date \"MMMM d, yyyy\"\n//$periodTo = get line containing \"Statement\"  => bottom => get line below => take last words 3 => get date \"MMMM d, yyyy\"\n\n$top = get line containing \"Statement\"  => bottom\n$bottom =  get line containing \"Page\"  => top\n$periodFromtext = get text in box $top $bottom 390 560\n$periodFrom = take words $periodFromtext 3 => get date \"MMMM d, yyyy\"\n$periodTo = take last words $periodFromtext 3 => get date \"MMMM d, yyyy\"\n\ndelete text in box on every page page.top page.bottom 0 42\n\ndelete text in box on every page page.top page.bottom 580 page.right\ngo to page 1\n// Get Account Name\n//$accountName = get text in box 648 639 44 200 => take words 2 => get text\n\n// Get account number\n$top = get line containing \"CHECKING\" => top\n$bottom = get line containing \"ACCOUNT SUMMARY\" => bottom\n@acctxt = get text in box $top $bottom page.left page.middleX\n\n$accountNumber = get line containing \"CHECKING\" => get words after \"CHECKING\" => take words 1 => get text\n$accountName = get line containing \"CHECKING\" => get words after \"CHECKING\" => take words 1 => get text\n//$accountNumber = get words after @acctxt \"CHECKING\" => take words 1 => get text\n\n\n//Get opening and closing balances\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n\ngo to page 1\n\n@transactionsTop = get line containing \"Date Description Deposits Withdrawals Balance\" => top => get line below\n@transactionsBottom = get last line containing \"Ending Balance\" => bottom => get line above\n\ngo to page 1\n\n\nignore header above 717\nignore footer below 37\n\n//delete all lines containing \"Date Description Deposits Withdrawals Balance\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Totals\"\ndelete all lines containing \"Ending Balance\"\ndelete all lines containing \"Detail\"\ndelete all lines containing \"bankofthewest.com\"\ndelete all lines containing \"continued\"\ndelete all lines containing \"Description\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"bankofthewestsomfmeatth \"\ndelete all lines containing \"A trade name\"\ndelete all lines containing \"xxx-xx\"\n\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 68 410 470 535 590 => describe table false \"*Date[M/dd]\" Details #Credit #Debit #Balance','2025-07-31 08:11:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10626,'CommunityFirst_Bank','$source =  \"CommunityFirst_Bank\"\n$PeriodBufferDays = 45\n$features = \"NO_TRANSACTION_YEAR\"\n// Get account Name and Number\n$accountNumber = get line Containing \"Account Number\" => bottom => get line below => take last words 1 => get text\n@accountBottom  = get line Containing \"Account Number\" => bottom => get line below => bottom\n$accountName = get text in box 750  @accountBottom page.left page.middleX => take words 3 => get text\n@periodText = get line Containing \"previous balance\" => get text\n$periodFrom = get line Containing @periodText => get words after \"previous balance on\" => take words 1 => get date \"M/d/yy\"\n$openingBalance = get line Containing @periodText => take last words 1 => get decimal\n$periodTo = get line Containing \"through\" => get words after \"through\" => take words 1 => get date \"M/d/yy\"\n$closingBalance =  get line Containing \"new balance\" => get words after \"new balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get start & end of all Credits table\n$getDetailLeft0 = get line containing \"Date Amount Transaction description\" => get words before \"description\" =>  take last words 1 => left\n$getDetailLeft = subtract $getDetailLeft0 5\n\n\n$getAmountLeft = get line containing \"Date Amount Transaction description\" => get words before \"Transaction\" =>  take last words 1 => left => subtract 24.24\n\n@creditsTop = get line starting \"Date Amount Transaction description\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Other debits and withdrawals\" => if not found then blank => top => get line above\n\n// Get start & end of all Debits table\n@debitsTop = get line starting \"Other debits and withdrawals\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"Check# Date Amount\" => if not found then blank => top => get line above\n\n//get start and end check\n@chequeTop = get line containing \"Check# Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Indicates break in sequence\" => if not found then blank => top => get line above\n\n@leftcheck_CheckLeft = get line starting \"Check# Date Amount\" =>  take words 1 => left => subtract 20\n@leftcheck_CheckRight = get line starting \"Check# Date Amount\" => take words 1 => right => add 5.79\n@leftcheckdateRight = get line starting \"Check# Date Amount\" => take words 2 => take last words 1 => right => add 5\n@leftcheckamountRight = get line starting \"Check# Date Amount\" => take words 3 => take last words 1 => right => add 5\n\n@middlecheck_CheckLeft = get line starting \"Check# Date Amount\" => take words 6 => get words after \"Amount\" => take words 1 => left\n@middlecheck_CheckRight = get line starting \"Check# Date Amount\" => take words 6 => get words after \"Amount\" => take words 1 => right => add 5.79\n@middlecheckdateRight = get line starting \"Check# Date Amount\" => take words 6 => get words after \"Amount\" => take words 2 => take last words 1 => right => add 5\n@middlecheckamountRight = get line starting \"Check# Date Amount\" => take words 6 => get words after \"Amount\" => take words 3 => take last words 1 => right => add 5\n\n@rightcheck_CheckLeft = get line starting \"Check# Date Amount\" => take words 9 => take last words 3 => take words 1 => left\n@rightcheck_CheckRight = get line starting \"Check# Date Amount\" => take words 9 => take last words 3 => take words 1 => right => add 5.79\n@rightcheckdateRight = get line starting \"Check# Date Amount\" => take words 9 => take last words 3 => take words 2 => take last words 1 => right => add 5\n@rightcheckamountRight = get line starting \"Check# Date Amount\" => take words 9 => take last words 3 => take words 3 => take last words 1 => right => add 5\nremove page 2\ndelete all lines starting \"Date Amount Transaction description\"\ndelete all lines starting \"Deposits and other credits\"\ndelete all lines starting \"Other debits and withdrawals\"\ndelete all lines starting \"Check# Date Amount\"\n\ndelete all lines starting \"----------Checks\"\ndelete all lines starting \"------Checks\"\ndelete all lines containing \"Indicates break in sequence\"\n\nignore header above 530\nignore footer below 70\n\n// Read the transactions\n@checksleft = get multi page table @chequeTop @chequebottom @leftcheck_CheckLeft @leftcheck_CheckRight @leftcheckdateRight @leftcheckamountRight => describe table false ChequeNumber \"Date[M/dd]\" #Debit\n@checksMiddle = get multi page table @chequeTop @chequebottom @middlecheck_CheckLeft @middlecheck_CheckRight @middlecheckdateRight @middlecheckamountRight => describe table false ChequeNumber \"*Date[M/dd]\" *#Debit\n@checksright = get multi page table @chequeTop @chequebottom @rightcheck_CheckLeft @rightcheck_CheckRight @rightcheckdateRight @rightcheckamountRight => describe table false ChequeNumber \"*Date[M/dd]\" *#Debit\n\n@credits = get multi page table @creditsTop @creditsBottom 0 $getAmountLeft $getDetailLeft0 $getDetailLeft 1000 => describe table false \"*Date[M/dd/yy]\" #Credit - Details\n@debits = get multi page table @debitsTop @debitsBottom 0 $getAmountLeft $getDetailLeft0 $getDetailLeft 1000 => describe table false \"*Date[M/dd/yy]\" #Debit - Details\n\n$features = \"NO_TRANSACTION_YEAR\"\n$transactions = combine described tables @checksleft @checksMiddle @checksright @credits @debits\n','2025-03-20 07:08:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10627,'VyStar_Bank','$source = \"VyStar_Bank\"\n\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n\nset negative marker \"-\"\n\n//delete extra texts or scanner for supporting transactions\n$scanner_del = delete text in box on every page page.top page.bottom page.left 53 => get text\n\n//delete extra pages\ndelete all pages containing \"COMBINED STATEMENT DISCLOSURE\"\n\n\n//get statements_periods\n$periodFrom = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => take last words 1 => get date \"MM/dd/yyyy\"\n\n\n// Get account name\n$accountName = get line containing \"Account Type Account Number\" => bottom => get line below => take words 2 => get text\n\n//get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n//get opening/closing\n$openingBalance = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 2 => take last words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 2 => take last words 1 => get decimal\n\n\n//get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Deposits\" => bottom => get line below => bottom => get line below\n\n//navigate to last summary page\n@navigateToSummarypage = get last line containing \"Balance Summary\"\n@page_top = get last line containing \"Balance Summary\" => top\n@page_bottom = get last line ending \"Transactional Detail\" => bottom => get line below => bottom\n$summayDel = delete text in box @page_top @page_bottom page.left page.right => get text\n\n\n// Discard header and footer\ndelete all lines starting \"Transactional Detail\"\ndelete all lines containing \"Account Number:\"\ndelete all lines starting \"Account Owner(s): LSC LOGISTIX LLC\"\n\n//get end of table transactions\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\n\n//delete extra texts or garbage values\ndelete all lines containing \"Ending Balance\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"00127855 0736834 0001-0003\"\ndelete all lines starting \"Date Description Deposits\"\n\n//ignore header part\nignore header above 600\n\n//ignore footer part\nignore footer below 22\n\ngo to page 1\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 53 80 300 410 500 600 => describe table false \"Date[MM/dd]\" Details #Credit #Debit *#Balance','2025-04-15 05:12:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10628,'Crystal_Lake_Bank','$source = \"Crystal_Lake_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete text in box on every page page.top page.bottom 0 57\n\ngo to page 1\n// Get Account Name\n$accountName = get text in box 658 647 100 page.middleX => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get Period/From To\n$periodFrom = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get TextInBOx\n@TEXTBOXTop = get line containing \"Beginning Balance as of\" => top\n@TEXTBOXBottom = get line starting \"+ Deposits and Credits\" => top\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 55 330\n$openingBalance = take last words @TEXTBOX 1 => get decimal\n\n@TEXTBOXTop1 = get last line containing \"- Withdrawals and Debits\" => bottom\n@TEXTBOXBottom1 = get last line starting \"Ending Balance as of\" => bottom\n@TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 55 330\n$closingBalance = take last words @TEXTBOX1 1 => get decimal\n\ndelete all lines containing \"Account Number:\"\ndelete all lines containing \"Account Number\"\ndelete all lines containing \"Page:\"\ndelete all lines containing \"Statement Ending:\"\ndelete all lines containing \"Last Statement:\"\ndelete all lines containing \"Statement Date:\"\n\n// Get start & end of transaction Table\ngo to page 1\n@TransactionTop = get line starting \"Date Description\" => bottom => get line below\ndelete all lines containing \"Date Description\"\n@TransactionBottom = get line containing \"Daily Balances\" => top => get line above\n\ndelete all lines containing \"Date Description\"\ndelete all lines starting \"Credits\"\ndelete all lines starting \"Debits\"\n\n//ignore header above 650\nignore header above 625\nignore footer below 20\n\n$transactions = get multi page table @TransactionTop @TransactionBottom 54 95 530 590 => describe table false \"*Date[MMM d]\" Details #credit','2025-05-29 06:49:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10629,'TriCountries_Bank','$source = \"TriCountries_Bank\"\n\n$accountNumberText = get line starting \"Account Type Account Number\" => bottom => get line below\n$accountNumber = take last words $accountNumberText 2 => take words 1 => get text\n$accountName = take last words $accountNumberText 2 => take words 1 => get text\n\ngo to page 1\n@accountDetailstop = get line starting \"Account Summary\" => bottom\n@accountDetailsbottom = get line starting \"Service Charges\" => bottom\n\n$accountDetails = get text in box @accountDetailstop @accountDetailsbottom 20 340\n$periodFrom = get words before $accountDetails \"Beginning Balance\" => take last words 1 => get date \"MM/d/yyyy\"\n\n$openingBalance =  get words after $accountDetails \"Beginning Balance\" => take words 1 => get decimal\n$periodTo = get words before $accountDetails \"Ending Balance\" => take last words 1 => get date \"MM/d/yyyy\"\n$closingBalance = get words after $accountDetails \"Ending Balance\" => take words 1 => get decimal\n\n\n//Get start & end of Deposits table\ngo to page 1\n@depositTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@depositsBottom = get last line starting \"Electronic Credits\" => if not found then blank => top => get line above\n\n//Get start & end of Electronic Credit table\ngo to page 1\n@eCreditsTop = get line starting \"Electronic Credits\" => if not found then blank => bottom => get line below\n@eCreditsBottom = get line starting \"Electronic Debits\" => if not found then blank => top => get line above\n\n//Get start & end of Electronic Debit table\ngo to page 1\n@eDebitsTop = get line starting \"Electronic Debits\" => if not found then blank => bottom => get line below\n@eDebitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n\ngo to page 1\n@ChecksTop = get line containing \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@ChecksBottom = get line starting \"* Indicates skipped check\" => if not found then blank => top => get line above\n\ngo to page 1\nremove page 2\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Savings Account\"\ndelete all lines containing \"Deposits (continued)\"\ndelete all lines containing \"Electronic Credits\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Electronic Debits\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Check Nbr Date\"\ndelete all lines containing \"Checks Cleared\"\ndelete all lines starting \"Start Up\"\n\nignore header above 688\n\n$deposits = get multi page table @depositTop @depositsBottom 30 85 500 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit\n$credits = get multi page table @eCreditsTop @eCreditsBottom 30 85 500 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit\n$debits = get multi page table @eDebitsTop @eDebitsBottom 30 85 500 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit\n\n$ChecksL = get multi page table @ChecksTop @ChecksBottom 30 91 142 215 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n$ChecksM = get multi page table @ChecksTop @ChecksBottom  245 274 325 394 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n$ChecksR = get multi page table @ChecksTop @ChecksBottom  420 458 510 578 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n\n$transactions = combine described tables $deposits $credits $debits $ChecksL $ChecksM $ChecksR','2025-04-15 05:12:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10630,'ME_Bank','$source = \"ME_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Get account name\n$accountName = get text in box 700 685 0 page.middleX => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n//Get dates\n$periodFrom = get line containing \"Statement period\" => bottom => get line below => get words before \"-\" => take words 3 => get date \"d MMM yy\"\n$periodTo = get line containing \"Statement period\" => bottom => get line below => get words after \"-\" => take words 3 => get date \"d MMM yy\"\n\n// Opening and Closing Balance\ngo to page 1\n@TEXTBOXTop = get line containing \"Date Processed Description Debits ($) Credits ($) Balance ($)\" => bottom\n$TEXTBOX = get text in box @TEXTBOXTop page.bottom 450 page.right\n$openingBalance = take words $TEXTBOX 1 => get decimal\n$closingbalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Your migrated\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line starting \"Closing Balance\" => bottom => get line above\n\nignore header above 675\nignore footer below 18\n\ngo to page 1\ndelete all lines containing \"Date Processed Description Debits ($) Credits ($) Balance ($)\"\ndelete all lines containing \"Please check your statement\"\ndelete all lines containing \"dispute resolution\"\ndelete all lines containing \"Bank of Queensland Limited\"\ndelete all lines containing \"mebank.com.au\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines starting \"201\"\ndelete all lines starting \"202\"\ndelete all lines starting \"203\"\ndelete all lines containing \"Statement continues over\"\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 95 170 280 450 570 => describe table false \"Date[dd-MMM]\" - Details *#Credit #Balance','2025-04-15 05:12:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10631,'HSBC_Bank_Australia','$source = \"HSBC_Bank_Australia\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete rotated words\n$accountName = get line starting \"AUD DAY TO DAY ACCOUNT\" => get words after \"Account No\"  => take words 1 =>  get text\n$accountNumber = get line starting \"AUD DAY TO DAY ACCOUNT\" => get words after \"Account No\"  => take words 1 =>  get text\n\n$openingBalance = get line containing \"Balance Brought Forward\" => take last words 1 => get decimal\n\n//$closingBalance = get last line containing \"BALANCE\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"DAY TO DAY ACCOUNT\" => take last words 1 => get decimal\n\ngo to page 1\n$periodFromText = get line starting \"STATEMENT PERIOD\" => get words after \"STATEMENT PERIOD\"\n$periodFrom = take words $periodFromText 3 => get date \"d MMM yyyy\"\n$periodTo = take last words $periodFromText 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n\n$Date_left = get line containing \"Date Transaction Details\" => get words before \"Transaction\" => left => subtract 10\n$Description_left = get line containing \"Date Transaction Details\" => get words after \"Date\" => left => subtract 5\n$Description_right = get line containing \"Date Transaction Details\" => get words after \"Details\" => left => subtract 40\n$Paidout_right = get line containing \"Date Transaction Details\" => get words after \"Details\" => take words 1 => right => add 20\n$Paidin_right = get line containing \"Date Transaction Details\" => get words after \"Debit\" => take words 1 => right => add 30\n$Balance_right = get line containing \"Date Transaction Details\" => get words after \"Credit\" => take words 1 => right => add 15\n\n\n@transactionsTop = get line starting \"Date Transaction Details Debit\" => bottom => get line below\n@transactionBottom = get last line containing \"Transaction Total\" => top => get line above\n\nignore header above 658\nignore footer below 80\ndelete all lines containing \"Balance Brought Forward\"\ndelete all lines containing \"BALANCE\"\n\ngo to page 1\n//$transactions = get multi page table @transactionsTop @transactionBottom 50 80 345 382 470 545 => describe table false \"Date[d MMM]\" Details **#Debit **#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionBottom $Date_left $Description_left $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"Date[d MMM]\" Details **#Debit **#Credit #Balance','2025-04-15 05:12:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10632,'UnitedBank','$source = \"UnitedBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n$accountName = get text in box 645 610 page.left page.middleX => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Previous Balance\" => top => get line above => take last words 1 => get text\n\n// Get dates\n@periodtxt = get line containing \"Previous Balance\" => top => get line above => top => get line above\n$periodFrom = take words @periodtxt 3 => get date \"MMMM dd,yyyy\"\n$periodTo = get words after @periodtxt \"thru\" => get date \"MMMM dd,yyyy\"\n\n// Get balances\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n// Discard non-transactional page\nremove page 2\n\ngo to page 1\n// Check table\n@checksTop = get line containing \"Checks In Number Order\" => if not found then blank => bottom => get line below\n@checkBottom = get line containing \"* Denotes missing check numbers\" => if not found then blank => top => get line above\n\ndelete all lines containing \"DATE CHECK NO AMOUNT\"\n\n@chequeLeft = get multi page table @checksTop @checkBottom 30 55 100 196 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n@chequemiddle = get multi page table @checksTop @checkBottom 225 250 300 390 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n@chequeright = get multi page table @checksTop @checkBottom 420 440 500 590 => describe table false \"*Date[M/dd]\" #ChequeNumber #Debit\n\n@Top = get line containing \"Checks In Number Order\" => top\n@bottom = get line containing \"* Denotes missing check numbers\" => bottom\n$del = delete text in box @Top @bottom page.left page.right => get text\n\ngo to page 1\n// Get top of the transaction table\n@transactionsTop = get line starting \"DATE DESCRIPTION AMOUNT\" => if not found then blank => bottom => get line below\n\nignore header above 725\nignore footer below 25\ndelete all lines starting \"Checks and Withdrawals\"\ndelete all lines starting \"DATE DESCRIPTION AMOUNT\"\n\n@transactionsBottom = get line starting \"Daily Balance Information\" => if not found then blank => top => get line above\n@debcred = get multi page table @transactionsTop @transactionsBottom 30 70 500 590 => describe table false \"*Date[M/dd]\" Details #Credit\n\n// combine the transactions\n$transactions = combine described tables @debcred @chequeLeft @chequemiddle @chequeright','2025-04-15 05:12:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10633,'Equaze','$source = \"Equaze\"\n$periodBufferDays = 30\n// Get Account Name\n$accountName = get text in box 745 735 60 page.middleX => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => take last words 1 => get text\n\n// Get Period/From To\n$periodFrom = get line containing \"Period:\" => get words after \"Period:\" => take words 1 => get date \"d-MMMM-yyyy\"\n$periodTo = get line containing \"Period:\" => get words after \"Period\" => take words 3 => take last words 1 => get date \"d-MMMM-yyyy\"\n\n// Opening and Closing Balance\n$opening = get text in box 665 650 page.middleX page.right\n$openingbalance = take last words $opening 1 => get decimal\n\n$closing = get text in box 625 610 page.middleX page.right\n$closingbalance = take last words $closing 1 => get decimal\n\ngo to page 1\n\n@transactionsTop = get line containing \"Date Type Name and Account Details\" => bottom => get line below\n\ndelete all lines containing \"Date Type Name and Account Details\"\n\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"Opening Balance\"\nignore header above 745\nignore footer below 65\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 120 300 405 480 => describe table false \"*Date[d-MMMM-yyyy]\" Details - #Credit\n','2025-04-15 05:12:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10634,'KBC_BANK','$source = \"KBC_BANK\"\n$features = \"NO_OPENING_BALANCE\"\ndelete rotated words\n\ngo to page 1\n$accountNumber = get text in box 453 444 174 216 => get text\n$accountname = get text in box 453 444 174 216 => get text\n\nignore header above 760\n$closingBalanceText = get line containing \"IMPORTANT INFORMATION\" => top => get line above\n//=> take last words 1 => get decimal\n$closingBalance = get text in box page.top 50 465 545 => take last words 1 => get decimal\n\n\ngo to page 1\n$periodFromText = get line containing \"Current Account\" => bottom => get line below => bottom => get line below\n$periodFrom = take words $periodFromText 3 => get date \"d MMM yyyy\"\n$periodTo = take last words $periodFromText 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n$transactionsTop = get line below 402\n$transactionsBottom = get last line containing \"IMPORTANT INFORMATION\" => top => get line above\n\ndelete all lines starting \"KBC Bank Ireland plc is regulated\"\ndelete all lines containing \"Directors: Luc Popelie\"\ndelete all lines containing \"Christine Van Rijsseghem (Belgian).\"\ndelete all lines containing \"Company Secretary:\"\n\n\n$transactions = get multi page table $transactionsTop $transactionsBottom 50 115 310 400 465 545 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance','2025-04-15 05:12:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10635,'Bidvest_Bank','$source = \"Bidvest_Bank\"\r\n// Get Account\r\n$accountNumber = get line containing \"Account No\" => get words after \"Account No\" => take words 1 => get text\r\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 2 => get text\r\n// Get Opening & Closing Balances\r\n@getLineBroughtFoward = get line containing \"Transaction Description Reference\" => bottom => get line below => get text\r\n@openingtop = get line containing @getLineBroughtFoward => top\r\n@openingbottom = get line containing @getLineBroughtFoward => bottom\r\n@openingleft = get line containing \"Transaction Description Reference\" => get words before \"Balance\" => take  last words 1 => right => add 7\r\n$openingbalance = get text in box @openingtop @openingbottom @openingleft page.right => get decimal\r\n\r\ngo to page 1\r\n$closingbalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" => take words 2 => get decimal\r\n\r\n//Get Period\r\n$periodFrom  =  get line starting \"Statement for the period\" => get words after \"period\" => take words 1 => get date \"yyyy/MM/d\"\r\n$periodTo  =  get line starting \"Statement for the period\" => get words after \"to\" => take words 1 => get date \"yyyy/MM/d\"\r\n\r\ngo to page 1\r\n@dateLeft = get line containing \"Transaction Description Reference\" => take words 1 => left => subtract 5\r\n@date1Left = get line containing \"Transaction Description Reference\" => take words 2 => take last words 1 => left => subtract 5\r\n@detailLeft = get line containing \"Transaction Description Reference\" => get words before \"Description\" => take last words 1 => left => subtract 3\r\n@referenceLeft = get line containing \"Transaction Description Reference\" => get words after \"Description\" => take words 1 => left => subtract 3\r\n@balanceLeft = get line containing \"Transaction Description Reference\" => get words before \"Balance\" => take  last words 1 => right => add 10\r\n@balanceright  = get line containing \"Transaction Description Reference\" => get words after \"Amount\" => take  words 1 => right => add 20\r\n\r\ngo to page 1\r\n// Get Transactions\r\n@transactionstop = get line containing \"Transaction Description Reference\" => bottom => get line below\r\nget last line containing \"Transaction Description Reference\"\r\n@transactionsbottom = get line starting \"Note:\" => top => get line above\r\n\r\ngo to page 1\r\ndelete all lines containing \"Transaction Description Reference\"\r\ndelete all lines starting \"Transaction Effective\"\r\ndelete all lines containing \"Statement Opening Balance\"\r\ndelete all lines containing \"Balance Brought Forward\"\r\ndelete all lines starting \"Transaction Note:\"\r\nignore header above 790\r\n@footer = get last line containing \"Note:\" => top\r\nignore footer below @footer\r\n$transactions = get multi page table @transactionstop @transactionsbottom @dateLeft @date1Left @detailLeft @referenceLeft 440 @balanceLeft @balanceright => describe table false *Date[yyyy/MM/d] \"tranDate[yyyy/MM/d]\"  Details TransactionType #Credit #Balance\r\n//$transactions = get multi page table @transactionstop @transactionsbottom @dateLeft @date1Left @detailLeft @referenceLeft 450 @openingleft @balanceright => describe table false *Date[yyyy/MM/d] \"tranDate[yyyy/MM/d]\"  Details TransactionType #Credit #Balance','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10636,'ASB_Bank','$source = \"ASB_Bank\"\n\n\n// Get account name and number\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n$accountName = get line containing \"Name:\" => get words after \"Name:\" => take words 2 => get text\n\n\n// Get period from/to\n@period = take last words @accountDetails 7\n$periodFrom = get line containing \"From Date:\" => get words after \"Date:\" => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get line containing \"To Date:\" => get words after \"To Date:\" => take words 3 => get date \"d MMM yyyy\"\n\n//get opening/closing\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Transaction Description\" => bottom => get line below => bottom => get line below\n\n\n//navigate to last closing balance page\nget last line starting \"Date Transaction Description\"\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n\n// Discard header and footer\ndelete all lines containing \"ASB FastNet: Statements\"\ndelete all lines containing \"Date Transaction Description\"\ndelete all lines starting \"https://online.asb.co.nz/fnc\"\n\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 90 310 430 510 580 => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit **#Balance','2025-04-15 05:12:24',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10637,'PayPalCard_DescriptionofTransaction','$source = \"PayPalCard_DescriptionofTransaction\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodbufferdays = 14\n\nset negative marker \"(\"\n\n@top = get line containing \"Payment Information\" => top\n@bottom = get line containing \"If you would like information about\" => bottom\ndelete text in box @top @bottom 260 page.right\n\n// Get account name\n$accountName = get line containing \"Account Number\" => top => get line above => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 4 => get text\n\n// Get balances\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n// Get Period To date\n$periodTo = get line containing \"Statement Closing Date\" => get words after \"Statement Closing Date\" => get date \"MM/dd/yyyy\"\n\ndelete all lines starting \"FEES\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"INTEREST CHARGED\"\n\n// Get period from date\n$periodFrom = get line containing \"Description of Transaction or Credit Amount\" => bottom => get line below => take words 1 => get date \"MM/dd\"\n\n// Get top and bottom of the transaction table\n@transactionsTop = get line containing \"Description of Transaction or Credit Amount\" => bottom => get line below\n@transactionsBottom = get last line starting \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 80 115 400 500 => describe table false \"*Date[MM/dd]\" Details #Credit','2025-04-15 05:12:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10638,'VISION_ENCOMPASS_CREDITUNION','$source = \"VISION_ENCOMPASS_CREDITUNION\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n@headerText = get line starting \"Date Description Debits\" => get text\n@acountbottom = get line starting @headerText => top => get line above => top\n$accountname = get text in box page.top @acountbottom 0 page.middleX => take words 3 => get text\n$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 =>  get text\n\n$periodfrom = get line containing \"Period Beginning\" => get words after \"Beginning\" =>  get date \"MMM d,yyyy\"\n@periodto_left = get line containing \"Period Beginning\" => get words after \"Period\" => take words 1 => right\n@periodto_top  = get line containing \"Ending\" => top\n@periodto_bottom = get line containing \"Ending\" => bottom\n\n$periodto = get text in box @periodto_top @periodto_bottom @periodto_left page.right => get date \"MMM d,yyyy\"\ngo to page 1\n@openingText = get line starting @headerText => bottom => get line below => bottom => get line below => get text\n$openingbalance = get line starting @openingText => take last words 1 => get decimal\n\n//$periodfrom1 = get line starting @openingText =>  take words 1 => get text\n\n@closingleft = get line starting @headerText => take last words 1 => left => subtract 20\n@closingbottom = get last line starting \"Total Debits\" => top\n$closingbalance = get text in box page.top @closingbottom @closingleft page.right => take last words 1 =>  get decimal\n\nset negative marker \"-\"\ngo to page 1\n@dateLeft = get line starting @headerText  => take words 1 => left => subtract 20\n@detailLeft = get line starting @headerText  => take words 2 => take last words 1 => left => subtract 20\n@debitLeft = get line starting @headerText  => get words after \"Description\" => take words 1 => left => subtract 50\n@debitRight = get line starting @headerText  => get words after \"Description\" => take words 1 => right => add 10\n@creditRight = get line starting @headerText  => get words before \"Balance\"  => take last words 1 => right => add 10\n@balanceRight = get line starting @headerText  => take last words 1 => right => add 30\n\n@transactionstop = get line containing \"Balance Forward\" => bottom => get line below\n@transactionsbottom = get last line starting \"Total Debits\" => top => get line above\n\ngo to page 1\n@top_inquiries = get line starting \"For loan inquiries\" => if not found then blank => bottom\n$del_top_inquiries = delete text in box @top_inquiries 0 0 page.right => get text\n\ngo to page 1\n@encompasscu = get line starting \"encompasscu.ca\" => if not found then blank => bottom\n$del_encompasscu = delete text in box @encompasscu 0 0 page.right => get text\n\ngo to page 1\n@for_aLost = get line starting \"For a Lost\" => if not found then blank => bottom\n$del_for_aLost = delete text in box @for_aLost 0 0 page.right => get text\n\ndelete all lines starting \"Date Description Debits\"\ndelete all lines starting \"Interest Principal\"\ndelete all lines containing \"Interest Principal\"\ndelete all lines containing \"Balance Forward\"\ndelete all lines starting \"Total Debits\"\ndelete all lines starting \"Total Credits\"\ndelete all lines starting \"For loan inquiries\"\ndelete all lines starting \"encompasscu.ca\"\ndelete all lines starting \"For a Lost\"\ndelete all lines starting \"eChoice Electronic Access ACCOUNT\"\n\nignore header above 715\nignore footer below 65\n$transactions = get multi page table @transactionstop @transactionsbottom @dateLeft @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false *Date[MMMd] Details #Debit #Credit #Balance\n\n','2025-04-15 05:12:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10639,'StandardBank_Card_NETPlus','$source = \"StandardBank_Card_NETPlus\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$periodBufferDays = 90\n\n// Parse amounts in SouthAfrica\nset culture \"en-ZA\"\n\n@data = get line containing \"Main Account Account Holder\" => bottom => get line below\n\n$AccountNumber = take words @data 1 => get text\n\n$AccountName = take words @data 3 => take last words 2 => get text\n\n//Get TextInBOx\n@TEXTBOXTop = get line containing \"Current Balance\" => bottom\n\n@TEXTBOXBottom = get line starting \"Transactions executed between\" => bottom\n\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 300 page.right\n$closingBalance = take words $TEXTBOX 1 => get decimal\n// Get period from and period t0\ngo to page 1\n$periodfrom = get line containing \"Transactions executed between\" => get words between \"Transactions executed between\" \"and\" => get date \"dd-MM-yyyy\"\n$periodto = get last line containing \"Transactions executed between\" => get words after \"and\" => get date \"dd-MM-yyyy\"\n\n\nignore header above 710\nignore footer below 70\ngo to page 1\n\n@transactionsTop = get line containing \"Date Value date Description Amount Balance Currency\" => bottom => get line below\n@transactionsBottom = get last line starting \"In case you need any additional information\" => top => get line above\ndelete all lines containing \"Date Value date Description Amount Balance Currency\"\ndelete all lines containing \"In case you need any additional information\"\n\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 70 130 185 345 430 => describe table false \"Date[dd-MM-yyyy]\" - Details #Credit','2025-04-15 05:12:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10640,'Bank_of_the_Sierra','$source = \"Bank_of_the_Sierra\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n@TEXTBOXAcctTop = get line containing \"page 1 of\" => bottom\n@TEXTBOXAcctBottom = get line containing \"Questions\" => top\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get account name\n//$accountName = get line containing \"Beginning balance\" => top => get line above => bottom => get line below => take words 4 => get text\n\n@TEXTBOXTop = get line containing \"Bank of the Sierra Homepage\" => bottom\n@TEXTBOXBottom = get line starting \"CHECKING ACCOUNT\" => top\n$accountName = get text in box @TEXTBOXTop @TEXTBOXBottom 0 page.middleX => take words 3 => get text\n\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words before \"thru\" => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\nignore header above 595\n//ignore footer below 38\ndelete all lines containing \"Date Description Amount\"\ngo to page 1\n// Get start & end of cheques table\n@chequeTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"* Denotes missing check numbers\" => if not found then blank => top => get line above\ndelete all lines containing \"Date Check No Amount\"\n//delete all lines starting \"CHECKS\"\n\n$chequesLeft = get multi page table @chequeTop @chequebottom 0 60 160 258 => describe table false \"*Date[M/dd]\" ChequeNumber #Debit\n$chequesRight = get multi page table @chequeTop @chequebottom 258 300 400 500 => describe table false \"Date[M/dd]\" ChequeNumber *#Debit\n@DeleteCheckTop = get line containing \"CHECKS IN NUMERICAL ORDER\" => if not found then blank => bottom\n@DeleteCheckBottom = get line containing \"* Denotes missing check numbers\" => if not found then blank => top\n$DeleteCheck = delete text in box @DeleteCheckTop @DeleteCheckBottom 0 page.right => get text\ndelete all lines containing \"Denotes missing check numbers\"\ndelete all lines containing \"CHECKS IN NUMERICAL ORDER\"\n\n// Get start & end of credits table\ngo to page 1\n@creditsTop = get line starting \"DEPOSITS AND CREDITS\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"OTHER DEBITS\" => if not found then blank => top => get line above\ndelete all lines containing \"DEPOSITS AND CREDITS\"\n\n$credits = get multi page table @creditsTop @creditsBottom 0 70 300 400 => describe table false \"Date[M/dd]\" Details *#Credit\n\n@debitsTop = get line starting \"OTHER DEBITS\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"DAILY BALANCE INFORMATION\" => if not found then blank => top => get line above\ndelete all lines containing \"OTHER DEBITS\"\n$debits = get multi page table @debitsTop @debitsBottom 0 70 300 400 => describe table false \"Date[M/dd]\" Details *#Credit\n\n$transactions = combine described tables $credits $debits $chequesLeft $chequesRight','2025-04-15 05:12:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10641,'AnPostMoney','$source = \"AnPostMoney\"\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n$periodBufferDays = 30\n\n// Get account name\n$accountName = get text in box 700 690 0 page.middleX => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"IBAN:\" => get words after \"IBAN:\" => take words 1 => get text\n\n//Get PeriodInBOx\n@PeriodFromTop = get last line containing \"Date Description Money In €\" => bottom\n@PeriodFromBottom = get last line starting \"Terms and conditions apply\" => top\n$PeriodFromBox = get text in box @PeriodFromTop @PeriodFromBottom page.left 110\n$PeriodFrom = take last words $PeriodFromBox 1 => get date \"dd/MM/yyyy\"\ngo to page 1\n@PeriodToTop = get line containing \"Date Description Money In €\" => bottom\n@PeriodTOBottom = get line starting \"Terms and conditions apply\" => top\n$PeriodToBox = get text in box @PeriodToTop @PeriodTOBottom page.left 110\n$PeriodTO = take words $PeriodToBox 1 => get date \"dd/MM/yyyy\"\n\n//Get TextInBOx\n\n@TEXTBOXTop = get line containing \"Date Description Money In €\" => bottom\n@TEXTBOXBottom = get line starting \"Terms and conditions apply\" => bottom\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 500 page.right\n$openingBalance = take words $TEXTBOX 1 => get decimal\n\n@TEXTBOXTop1 = get last line containing \"Date Description Money In €\" => bottom\n@TEXTBOXBottom1 = get last line starting \"Terms and conditions apply\" => top\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 500 page.right\n$closingBalance = take last words $TEXTBOX1 1 => get decimal\n\ngo to page 1\n\n@transactionsTop = get line containing \"Date Description Money In € Money Out € Balance €\" => bottom => get line below\n\n@transactionsBottom = get last line starting \"Terms and conditions apply\" => bottom => get line above\n\nignore header above 800\n\nignore footer below 80\n\n\ndelete all lines containing \"Date Description Money In € Money Out € Balance €\"\n\ndelete all lines containing \"Terms and conditions apply\"\n\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 18 110 330 420 525 580 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit *#Balance\n','2025-04-15 05:12:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10642,'ValleyFirst_Bank_CreditFirst','$source = \"ValleyFirst_Bank_CreditFirst\"\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n//Get account number\n$accountNumber = get line containing \"Member Card Number\" => get words after \"Member Card Number\" => get text\n\n//Get account name\n@AccountNameBox = get text in box page.top 725 300 page.right\n$accountName = take last words @AccountNameBox 3 => get text\n\n//Get opening Balance\ngo to page 1\n$openingBalance = get line containing \"Credits Debits Balance\" => bottom => Get line below => take last words 1 => get decimal\n\n//Get periodTo\n$periodTo = get line containing \"Credits Debits Balance\" => bottom => get line below => take words 1 => get date \"dd-MMM-yyyy\"\n\n\n//Get closing Balance\n//@pageHeader = get last line containing \"Credits Debits Balance\" => bottom\n//@infoLast = get text in box @pageHeader 50 500 page.right\n//$closingBalance = take last words @infoLast 1 => get decimal\n\n//Get periodFrom\n//@PeriodFromBox = get text in box @pageHeader 50 page.left 100\n//$periodFrom = take last words @PeriodFromBox 1 => get date \"dd-MMM-yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Credits\" => bottom => get line below\n\n// Get end of table\ngo to last page\n@transactionsBottom = get line above 0\n\n// ignore footer header\nignore header above 730\nignore footer below 48\n\ndelete all lines containing \"Date Description Credits\"\ndelete all lines starting \"FWCU Membership Shares 0:\"\ndelete all lines starting \"Login ID / Member Card Number\"\n\ngo to last page\n$closingBalance = get text in box page.top page.bottom 500 590 => take last words 1 => get decimal\n$periodFrom = get text in box page.top page.bottom 30 100 => take words 1 => get date \"dd-MMM-yyyy\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 100 325 425 500 590 => describe table false \"*Date[dd-MMM-yyyy]\" Details #Credit #Debit #Balance','2025-10-29 06:16:35',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10643,'StandardCharteredBank','$source = \"StandardCharteredBank\"\n\n$periodBufferDays = 30\n\n// Get account details\ngo to page 1\n$accountname = get text in box 700 660 65 page.middleX => take words 2 => get text\n$accountnumber = get line containing \"Account No:\" => get words after \"Account No:\" => get text\n\n$periodfrom = get line containing \"From Date:\" => get words after \"From Date:\" => get date \"dd/MM/yyyy\"\n$periodto = get line containing \"To Date:\" => get words after \"To Date:\" => get date \"dd/MM/yyyy\"\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"BALANCE B/F\" => get words after \"BALANCE B/F\" => take last words 1 => get decimal\ngo to last page\n$closingBalanceTexttop = get last line containing \"Date Narration\" => bottom\n$closingBalanceTextBottom = get last line containing \"This is an electronic statement\" => top\n$closingbalance = get text in box $closingBalanceTexttop $closingBalanceTextBottom 455 600 => take last words 1 => get decimal\ngo to page 1\n@Dateleft = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words before \"Narration\" => take words 1 => left\n@Dateleft = subtract @Dateleft 5\n@Descriptionleft = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words after \"Date\" => take words 1 => left\n@Descriptionleft = subtract @Descriptionleft 5\n@Debitleft = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words after \"Debit\" => take words 1 => left\n@Debitleft = subtract @Debitleft 5\n@Creditleft = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words after \"Debit\" => take words 2 => take last words 1 => left\n@Creditleft = subtract @Creditleft 5\n@Balanceleft = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words after \"Credit\" => take words 2 => take last words 1 => left\n@Balanceleft = subtract @Balanceleft 5\n@Balanceright = get line containing \"Date Narration Debit Amount Credit Amount Balance Amount\" => get words after \"Balance\" => take words 1 => right\n@Balanceright = Add @Balanceright 50\ngo to page 1\n@transactionsTop = get line containing \"Date Narration Debit Amount\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get last line containing \"This is an electronic statement\" => bottom => get line above\nignore header above 545\nignore footer below 180\ndelete all lines containing \"BALANCE B/F\"\ndelete all lines containing \"Date Narration Debit Amount\"\ndelete all lines containing \"electronic statement\"\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @Dateleft @Descriptionleft @Debitleft @Creditleft @Balanceleft @Balanceright => describe table false \"Date[ddMMMyy]\" Details #Debit #Credit *#Balance','2025-04-15 05:12:38',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10644,'Apple_Card','$source = \"Apple_Card\"\n$periodBufferDays = 29\n$features = \"CREDIT_CARD\"\n$accountNumber = \"Not_Available\"\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 6 => skip words 3  =>  get text\n\ngo to page 1\n$closingText = get line containing \"Payment Due\" => get text\n\n$periodTo = get line containing $closingText => get words after \"as of\" => take words 3 => get date \"MMM d, yyyy\"\n\n$closingBalance =  get line containing \"Payment Due\" => bottom => get line below => take words 1 => get decimal\n\n//$openingText = get line starting \"Previous Total Balance\" => get text\n//$openingBalance = get line containing $openingText => get words after \"Previous Total Balance\" => take words 1 => get decimal\n\n$openingText = get line containing \"Previous Monthly Balance\" => get text\n$openingBalance = get line containing $openingText => get words after \"Previous Monthly Balance\" => take words 1 => get decimal\n\n\n$periodFrom = get line containing $openingText => bottom => get line below => get words after \"as of\" => take words 3 => get date \"MMM d, yyyy\"\n\n//$closingText = get line starting \"Total Balance\" => get text\n//$closingBalance =  get line containing $closingText => get words after \"Total Balance\" => take words 1 => get decimal\n\n//$periodTo = get line containing $closingText => bottom => get line below => get words after \"as of\" => take words 3 => get date \"MMM d, yyyy\"\n\ngo to page 1\n@cardtop = get line containing \"minimum payment\" => if not found then blank => top => get line below\n@cardbot = get line containing \"being charged interest\" => if not found then blank => bottom => get line above\n\n$detailsleft1_ = get line containing \"monthly balance in full every\" => get words after \"monthly balance in full every\" => take words 1 => left => subtract 5\n$detailsright1_ = get line containing \"monthly balance in full every\" => get words after \"Apple Card Monthly Installments\" => take words 1 => left => subtract 5\n$amountrght = get line containing \"monthly balance in full every\" => get words after \"Apple Card Monthly Installments\" => take words 1 => right => add 5\n\n$carddata = get multi page table @cardtop @cardbot $detailsleft1_ $detailsright1_ $amountrght => describe table false Details *#Credit\n\n\n@deleteColumns = get line starting \"Date Description Daily Cash\" => get text\n$DailyCash_left = get line containing @deleteColumns => get words after \"Description\" => take words 1 => left => subtract 10\n$DailyCash_right = get line containing @deleteColumns => take last words 1 => left => subtract 30\ngo to page 1\n@deleteEvery_Box = delete text in box on every page page.top 0 $DailyCash_left $DailyCash_right => get text\ndelete all lines starting \"—\"\ngo to page 1\n\n// Read the transactions\n\n\n\ngo to page 1\n@transtionTop = get line starting \"Date Description\" => bottom => get line below\n$lastTransBottom = get last line starting \"Date Description\"\n@transtionBottom = get last line starting \"Total Daily Cash this month\" => top => get line above\n\ngo to page 1\n\n@InterestChargedTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below\n@InterestChargedBottom = get line starting \"Total interest for this month\" => if not found then blank => top => get line above\n\n\n//@interestChargeColumn = get line starting \"Interest Charged\" => get text\n//@dateleft_ = get line containing @interestChargeColumn => bottom => get line below => take words 1 => left => subtract 10\n\n@detailsleft_ = get line starting \"Interest Charged\" => bottom => get line below => take words 1 => left => subtract 5\n\n@amountleft_  = get line starting \"Interest Charged\" => bottom => get line below => take last words 1 => left => subtract 5\n@amountright_  = get line starting \"Interest Charged\" => bottom => get line below => take last words 1 => right => add 10\n//@InterestCharged = get multi page table @InterestChargedTop @InterestChargedBottom  30 530 580 => describe table false  Details *#Credit\n@InterestCharged = get multi page table @InterestChargedTop @InterestChargedBottom @detailsleft_ @amountleft_ @amountright_ => describe table false  Details *#Credit\n\ngo to page 1\n@dateleft = get line starting \"Date Description\" => take words 1 => left => subtract 12\n@detailsleft = get line starting \"Date Description\" => take words 2 => take last words 1 => left => subtract 12\n@amountleft = get line starting \"Date Description\" => take last words 1 => left => subtract 25\n@amountright = get line starting \"Date Description\" => take last words 1 => right => add 10\n\ndelete all lines starting \"Date Description\"\ndelete all lines starting \"Dates Description\"\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"Apple Card\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"If you have\"\ndelete all lines starting \"Total Daily Cash this month\"\ndelete all lines starting \"Total charges, credits and returns\"\ndelete all lines starting \"Apple Card Monthly Installments\"\ndelete all lines starting \"Total financed\"\ndelete all lines starting \"Total payments and credits\"\ndelete all lines starting \"Total remaining\"\n\ngo to page 1\n@dailyCash = get last line starting \"Daily Cash\" => if not found then blank => bottom\n@deleteLastLine_BottomAll_dailyCash = delete text in box @dailyCash page.bottom 0 page.right => get text\n\n\nignore header above 665\nignore footer below 45\n\n@tranDebitCredit = get multi page table @transtionTop @transtionBottom @dateleft @detailsleft @amountleft @amountright => describe table false \"Date[M/d/yyyy]\" Details *#Credit\n\n$transactions = combine described tables @tranDebitCredit @InterestCharged $carddata','2025-10-29 06:16:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10645,'Me_Bank_accountstatement','$source = \"Me_Bank_accountstatement\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\n\ngo to page 1\n// Get account name\n$accountName = get line containing \"Account Name\" => get words after \"Account Name\" => take words 2 => get text\n\n// Get account number\n\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//OpeningClosingBalance\n\n$openingbalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\n// Get Period/From To\n$periodfrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"d MMM yy\"\n$periodto = get line containing \"Statement Period\" => get words after \"-\" => take words 3 => get date \"d MMM yy\"\n\ngo to page 1\ndelete text in box 260 30 page.left page.right\n\nignore header above 787\n\nignore footer below 30\n\ngo to page 1\n\n@transactionsTop = get line containing \"Date Description Debits($) Credits($) Balance\" => top => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => bottom => get line above\ndelete all lines containing \"Date Description Debits($) Credits($) Balance\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines containing \"Opening Balance at\"\ndelete all lines containing \"Balance Carried Forward\"\ndelete all lines containing \"transactions.\"\ndelete all lines containing \"Account number:.\"\ndelete all lines starting \"Page\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 88 330 405 480 560 => describe table false \"*Date[d MMM]\" Details #Debit #Credit #Balance','2025-05-06 06:26:40',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10646,'ANZ_BANK_GO','$source = \"ANZ_BANK_GO\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ngo to page 1\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n$accountName = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n$periodFromText = get line starting \"Statement period\" => get words after \"Statement period\"\n$periodFrom = take words $periodFromText 3 => get date \"d MMM yyyy\"\n$periodTo = take last words $periodFromText 3 => get date \"d MMM yyyy\"\n\n$openingBalance = get line containing \"Opening balance\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Totals at end of period\" => take last words 1 => get decimal\n\ngo to page 1\n$Date_left = get line containing \"Date Transaction type and details\" => get words before \"Transaction\" => left => subtract 10\n$Description_left = get line containing \"Date Transaction type and details\" => get words after \"Date\" => left => subtract 5\n$Description_right = get line containing \"Date Transaction type and details\" => get words after \"details\" => left => subtract 20\n$Paidout_right = get line containing \"Date Transaction type and details\" => get words after \"details\" => take words 1 => right => add 20\n$Paidin_right = get line containing \"Date Transaction type and details\" => get words after \"Withdrawals\" => take words 1 => right => add 30\n$Balance_right = get line containing \"Date Transaction type and details\" => get words after \"Deposits\" => take words 1 => right => add 15\n\n@transactionsTop = get line starting \"Date Transaction type and details\" => bottom => get line below\n@transactionBottom = get last line starting \"Totals at end of page\" => top => get line above\n\ndelete all lines containing \"Opening balance\"\ndelete all lines containing \"Totals at end of page\"\ndelete all lines starting \"Text\"\ndelete all lines starting \"text\"\ndelete all lines containing \"Go - continued\"\ndelete all lines containing \"Automatic Teller Machine\"\ndelete all lines containing \"International Money Machine\"\ndelete all lines containing \"Date Transaction type and details\"\ndelete all lines starting \"Balance brought forward\"\ndelete all lines starting \"Totals at end of period\"\n\nignore footer below 70\nignore header above 778\n\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionBottom $Date_left $Description_left $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"*Date[d MMM]\" Details #Debit #Credit #Balance','2025-05-06 06:26:42',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10647,'SelfVisaCard','$source = \"SelfVisaCard\"\n$features = \"CREDIT_CARD\"\n$periodbufferdays = 14\n\n// Get account name\n$accountName = get line containing \"Customer service:\" => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"CREDIT CARD NUMBER\" => take last words 1 => get text\n\n// Get balances\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingbalance = get line starting \"New balance\" => bottom => get line below => take words 1 => get decimal\n\ndelete all lines starting \"Payments, credits and adjustments\"\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"No transactions\"\n\ngo to page 1\n// Get dates\n$periodTo = get line containing \"Statement closing date\" => get words after \"Statement closing date\" => take words 1 => get date \"MM/dd/yyyy\"\n\n@top = get line containing \"DATE DESCRIPTION AMOUNT\" => top\n@bottom = get line starting \"Fees\" => top => get line above => bottom\n$periodFrom = get text in box @top @bottom 45 95 => take last words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n@transactionsTop = get line containing \"DATE DESCRIPTION AMOUNT\" => bottom => get line below\n@lastTranspage = get line starting \"Interest charged\"\n@transactionsBottom = get line above 0\n\nignore footer below 85\ndelete all lines starting \"Fees\"\ndelete all lines starting \"Interest charged\"\ndelete all lines starting \"No interest charged\"\ndelete all lines starting \"No fees\"\ndelete all lines starting \"DATE DESCRIPTION AMOUNT\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 100 425 420 500 => describe table false \"*Date[MM/dd/yyyy]\" Details - #Credit','2025-05-06 06:26:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10648,'iBankq_Bank','$source = \"iBankq_Bank\"\n\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n//get statement period\n@top = get line containing \"www.ifxpayments.com\" => bottom\n@bottom = get line containing \"YOUR ACCOUNT\" => top\n// get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n$periodTo = get text in box @top @bottom page.middleX page.right => take words 4 => get date \"dd MMMM yyyy\"\n\n//get statements_periods\n$periodFrom = get line containing \"DATE TYPE DETAILS DEBIT\" => bottom => get line below => take words 3 => get date \"dd MMM yyyy\"\n\n\n\n// Get account name\n$accountName = get line containing \"www.ifxpayments.com\" => bottom => get line below => take words 3 => get text\n\n//get account number\ngo to page 1\n$top_accNumber = get line containing \"Account number\" => top\n$bottom_accNumber = get line containing \"Account number\" => bottom\n$accnt_text_del = delete text in box $top_accNumber $bottom_accNumber 370 450 => get text\n$accountNumber = get text in box $top_accNumber $bottom_accNumber 108 page.right => get text\n\n//get opening/closing\n$openingBalance = get line containing \"Balance brought forward\" => get words after \"Balance brought forward\" => take words 1 => get decimal\n$closingBalance = get line containing \"Balance carried forward\" => get words after \"Balance carried forward\" => take words 1 => get decimal\n\n//get start of table\ngo to page 1\n@transactionsTop = get line starting \"DATE TYPE DETAILS DEBIT\" => bottom => get line below => bottom => get line below\n\ngo to last page\n//ignore Header\nget line starting \"DATE TYPE DETAILS\" => bottom => ignore header above\n\n//ignore footer part\nignore footer below 60\n\n//delete extra texts or garbage values\ndelete all lines containing \"Account statement for\"\ndelete all lines containing \"Account number\"\ndelete all lines containing \"Balance brought forward\"\ndelete all lines starting \"DATE TYPE DETAILS\"\n\n\n//get end of table transactions\n@transactionsBottom = get last line containing \"Balance carried forward\" => top => get line above\n\n\n\ngo to page 1\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 85 370 440 505 570 => describe table false \"Date[dd MMM yyyy]\" Details *#Debit *#Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 85 370 440 505 570 => describe table false \"Date[dd MMM yyyy]\" Details *#Debit *#Credit','2025-05-29 06:48:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10649,'Sunflower_FirstNational_Bank','$source = \"Sunflower_FirstNational_Bank\"\n$periodBufferDays = 28\n//set negative marker \"-\"\n$accountNumber = get line containing \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => take words 2 => get decimal\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 3 => get text\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Current Statement Balance\" => get words after \"Statement Balance\" => take words 1 => get decimal\n$periodTo = get line containing \"STATEMENT DATE:\" => get words after \"STATEMENT DATE:\" => take words 1 => get date \"M/d/yy\"\n$periodFrom = get line starting \"Posted Description Amount\" => bottom => get line below => take words 1 => get date \"M/d/yy\"\ngo to page 1\n\n// Read the transactions\n// Get start & end of cheques table\n@checkColumns = get line starting \"Check Number Date Amount\" => get text\n@left_CheckLeft = get line containing @checkColumns => take words 1 => left => subtract 8\n@left_checkright = get line containing @checkColumns => take words 2 => take last words 1 =>  right => add 3\n@left_dateright = get line containing @checkColumns => take words 3 => take last words 1 => right => add 5\n@left_amountright = get line containing @checkColumns => take words 4 => take last words 1 => right => add 10\n\n@middle_CheckLeft = get line containing @checkColumns => take  last words 4 => take words 1 => left => subtract 5\n@middle_checkright = get line containing @checkColumns => take  last words 4 => take words 2 => take last words 1 =>  right => add 3\n@middle_dateright = get line containing @checkColumns => take last words 4 => take words 3 => take last words 1 => right => add 5\n@middle_amountright = get line containing @checkColumns => take last words 4 => take last words 1 => right => add 10\n\n\n@chequeTop = get line containing @checkColumns => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Indicates a break in check sequence\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom @left_CheckLeft @left_checkright @left_dateright @left_amountright => describe table false  ChequeNumber \"*Date[M/d/yy]\" #Debit\n@chequeCenter = get multi page table @chequeTop @chequebottom @middle_CheckLeft @middle_checkright @middle_dateright @middle_amountright => describe table false ChequeNumber \"Date[M/d/yy]\" *#Debit\n\n\n// Remove Checks\ngo to page 1\n@RemovechequeTop = get line starting @checkColumns => if not found then blank => bottom\n@Removechequebottom = get line containing \"Indicates a break in check sequence\" => if not found then blank => bottom\n@DELETECHECK = delete text in box @RemovechequeTop @Removechequebottom 0 page.right => get text\n\n@dailytrs_top =  get line containing \"Daily Balance Summary\" =>  if not found then blank => bottom\n@dailyBalInfo = delete text in box @dailytrs_top page.bottom 0 page.right => get text\ngo to page 1\ndelete all lines starting \"Check Number Date Amount\"\ndelete all lines containing \"---No Checks Paid Electronically in this statement cycle.---\"\ndelete all lines containing \"Indicates a break in check sequence.\"\ndelete all lines starting \"First National\"\ndelete all lines starting \"Checks Paid\"\ndelete all lines starting \"ACCOUNT NUMBER:\"\ndelete all lines starting \"STATEMENT DATE:\"\ndelete all lines starting \"PAGE\"\ndelete all lines starting \"Daily Balance Summary\"\ndelete all lines starting \"Date Balance Date\"\ngo to page 1\n\n@tranactionColumns = get line starting \"Posted Description Amount\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 8\n@detailsleft = get line containing @tranactionColumns => take words 2 =>  take last words 1 => left => subtract 6\n@amountleft = get line containing @tranactionColumns => take last words 1 => left => subtract 25\n@amountright = get line containing @tranactionColumns => take last words 1 => right => add 20\n\ngo to page 1\n// Get start & end of transactions\n@transtionTop = get line starting \"Posted Description Amount\" => bottom => get line below\n//$transtionBottom = get line containing \"Daily Balance Summary\" => top => get line above\n$lastTransBottom = get last line containing \"Posted Description Amount\"\n@transtionBottom = get line above 0\n\ndelete all lines starting \"Posted Description Amount\"\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Electronic Transactions\"\ndelete all lines starting \"Checks Paid Electronically\"\ndelete all lines starting \"Check Number Date Description\"\ndelete all lines containing \"---No Checks Paid Electronically in this statement cycle.---\"\ndelete all lines starting \"Daily Balance Summary\"\ndelete all lines starting \"Date Balance Date\"\n@creditDebitTable = get multi page table @transtionTop @transtionBottom @dateleft @detailsleft @amountleft @amountright => describe table false \"Date[M/d/yy]\" Details *#Credit\n//$cebitdreditsTable = get multi page table @transtionTop @transtionBottom 43 102 504 600 => describe table false \"Date[M/d/yy]\" Details *#Debit\n\nignore header above 675\nignore footer below 30\n$transactions = combine described tables @creditDebitTable @chequeLeft @chequeCenter ','2025-05-06 06:26:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10650,'WAFD_Bank','$source = \"WAFD_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n//delete rotated words\n$dlttext = delete text in box on every page page.top 0 1 32 => get text\n\ngo to page 1\n$accountTop = get line starting \"Statement End Date\" => top\n$accountbottom = get line starting \"Account Number\" => bottom\n$accountDetails = get text in box $accountTop $accountbottom 355 572\n\n$periodTo = get words after $accountDetails \"End Date\" => take words 3 => get date \"MMM d, yyyy\"\n$periodFrom = get words after $accountDetails \" Begin Date\" => take words 3 => get date \"MMM d, yyyy\"\n$accountNumber = get words after $accountDetails \"Account Number\" => take words 1 => get text\n$accountName = get words after $accountDetails \"Account Number\" => take words 1 => get text\n\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n$accountTop1 = get line starting \"Beginning Balance\" => top\n$accountbottom1 = get line starting \"Ending Balance\" => bottom\n$dlttext = delete text in box $accountTop1 $accountbottom1 page.left page.right\n\n//Get start & end of Interest table\ngo to page 1\n\n@intTop = get line starting \"Interest Earned This Period\" => if not found then blank => bottom => get line below\n@intBottom = get line starting \"Total Interest Earned This Period\" => if not found then blank => top => get line above\n\n//Get start & end of Deposits table\n@depositTop = get line starting \"Deposits and Credits\" => if not found then blank => bottom => get line below\n@depositsBottom = get line containing \"Total Deposits and Credits\" => if not found then blank => top => get line above\n\n//Get start & end of Check table\ngo to page 1\n@checkleftTop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@checkleftBottom = get line containing \"Total Checks Paid\" => if not found then blank => top => get line above\n\n//Get start & end of Check right table\ngo to page 1\n@checkrightTop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@checkrightBottom = get line containing \"Total Checks Paid\" => if not found then blank => top => get line above\n\n//Get start & end of ATM, Electronic and Debit Card Withdrawals table\ngo to page 1\n@debitTop = get line starting \"ATM, Electronic and Debit Card Withdrawals\" => if not found then blank => bottom => get line below\n@debitBottom = get line containing \"Total ATM, Electronic and Debit\" => if not found then blank => top => get line above\n\n//Get start & end of Other table\ngo to page 1\n@otherTop = get line starting \"Other Transactions\" => if not found then blank => bottom => get line below\n@otherBottom = get line containing \"Total Other Transactions \" => if not found then blank => top => get line above\n\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Visa may provide\"\ndelete all lines containing \"You may opt out\"\ndelete all lines containing \"Deposits and Credits\"\ndelete all lines containing \"Total Deposits and Credits\"\ndelete all lines containing \"ATM, Electronic\"\ndelete all lines containing \"Total Credits\"\ndelete all lines containing \"Other Transactions\"\ndelete all lines containing \"Number Date Amount\"\n\nignore footer below 52\nignore header above 625\n\n$interest = get multi page table @intTop @intBottom 33 80 500 572 => describe table false \"Date[MM-d]\" Details *#Credit\n$deposits = get multi page table @depositTop @depositsBottom 33 80 500 572 => describe table false \"Date[MM-d]\" Details *#Credit\n$checksleft = get multi page table @checkleftTop @checkleftBottom 33 75 170 275 => describe table false ChequeNumber \"Date[MMM d]\" *#Debit\n$checkright = get multi page table @checkrightTop @checkrightBottom 320 363 460 562 => describe table false ChequeNumber \"Date[MMM d]\" *#Debit\n$debits = get multi page table @debitTop @debitBottom 33 80 500 572 => describe table false \"Date[MM-d]\" Details *#Debit\n$other = get multi page table @otherTop @otherBottom 33 80 500 572 => describe table false \"Date[MM-d]\" Details *#Debit\n\n$transactions = combine described tables $interest $deposits $checksleft $checkright $debits $other','2025-05-29 06:48:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10651,'ABN-AMRO_Bank','$source = \"ABN-AMRO_Bank\"\n$periodBufferDays = 28\nset culture \"nl-NL\"\n//Get Accounts\n@accountText = get line containing \"Account holder name\" => get words after \"Account holder name\" => get text\n$accountName = get line containing @accountText => get words after \"Account holder name\" => take words  4  => get text\n\n@accountTop = get line containing @accountText => get words after \"Account holder name\" => take words 1 => bottom\n@accountLeft = get line containing @accountText => get words after \"Account holder name\" => take words 1 => left\n$accountNumber = get text in box @accountTop page.middleY @accountLeft page.middleX => take words 1 => get decimal\n\n//Get Periods\n$periodFrom = get line starting \"Date interval\" => get words before \"until\" => take last words 1 => get date \"d-M-yyyy\"\n$periodTo = get line starting \"Date interval\" => get words after \"until\" => take words 1 => get date \"d-M-yyyy\"\n\n//Get Balances\n\n$openingBalance = get line starting \"Balance\" => take words 4 => take last words 1 => get decimal\n$closingBalance = get line starting \"Balance\" => bottom => get line below => take words 4 => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount debited Amount credited\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detailsleft = get line containing @tranactionColumns => take words 2 => take last words 1 => left => subtract 6\n@debitleft = get line containing @tranactionColumns => take words 3 => take last words 1 => left => subtract 12\n@creditleft = get line containing @tranactionColumns => get words after \"debited\" => take words 1 => left => subtract 12\n@creditright = get line containing @tranactionColumns => take last words 1 => right => add 20\n\ngo to page 1\n// Get start & end of transactions\n@transtionTop = get line starting \"Date Description Amount debited Amount credited\" => bottom => get line below\n@transtionBottom = get last line starting \"Number of\" => top => get line above\n\n@footerTop = get line starting \"Number of\" => if not found then blank => bottom\n@delfooter = delete text in box @footerTop page.bottom 0 page.right => get text\n\ndelete all lines starting \"Date Description Amount debited Amount credited\"\ndelete all lines starting \"Number of\"\ndelete all lines starting \"Total amount\"\n\nignore header above 720\nignore footer below 25\n$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detailsleft @debitleft @creditleft @creditright => describe table false \"Date[d-M-yyyy]\" Details *#Debit *#Credit\n','2025-05-06 06:26:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10652,'Carter_Bank&Trust','$source = \"Carter_Bank&Trust\"\n\n// Get Account Name\n$accountName = get text in box 662 653 10 page.middleX => take words 3 => get text\n\n//$abc = get line containing \"Account Summary\" => top => get line above => get text\n// Get account number\n$accountNumber = get line containing \"Account Number Ending Balance\" => bottom => get line below => take last words 2 => take words 1 => get text\n\n// Get Period/From To\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Account Activity\" => top => get line above => take words 1 =>  get date \"MM/dd/yyyy\"\n\n// Get Opening & Closing balance\n\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Account Activity\" => top => get line above => get words after \"Ending Balance\" => take words 1 => get decimal\n\n\ngo to page 1\n@transactionstop = get line starting \"Post Date Description\" => bottom => get line below => bottom => get line below\n@transactionsbottom = get last line containing \"Ending Balance\" => top => get line above\n\n// stripping unwanted records from txns\ndelete all lines containing \"Post Date Description\"\nremove page 2\nignore header above 682\nignore footer below 38\n\n//$transactions = get multi page table center aligned @transactionstop @transactionsbottom 1 30 95 350 425 520 580 => describe table false \"Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionstop @transactionsbottom 30 95 350 425 520 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2025-05-06 06:26:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10653,'Southern_State_Bank','$source = \"Southern_State_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 10\n\n// Account Name\n@accNameBottom = get line starting \"Small Business Checking\" => top\n$accountName = get text in box page.top @accNameBottom 0 300 => take words 3 => get text\n\n// Account Number\n@summaryLine = get line containing \"Account Number\"\n$accountNumber = get words after @summaryLine \"Acct Ending\" => take words 1 => get text\n\n// Get period from/to\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words before \"thru\" => take words 3 => get date \"M/dd/yy\"\n$periodTo =  get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words after \"thru\" => take words 3 => get date \"M/dd/yy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Date Description Amount Balance\" => bottom => get line below\n//@transactionsBottom = get line starting \"CHECKS IN NUMBER ORDER\" => if not found then blank => top => get line above\nget last line containing \"Date Description Amount Balance\"\n@transactionsBottom = get line above 10\n\ngo to page 1\n@ChecksTop = get line starting \"CHECKS IN NUMBER ORDER\" => bottom\n@ChecksBottom = get line containing \"Denotes missing check numbers\" => if not found then blank => top\ndelete text in box @ChecksTop @ChecksBottom 0 page.right\n\nignore header above 590\ndelete all lines containing \"Date Description Amount Balance\"\ndelete all lines containing \"CHECKS IN NUMBER ORDER\"\ndelete all lines containing \"Denotes missing check numbers\"\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 60 280 400 500 => describe table false \"*Date[M/dd]\" Details #Credit #Balance','2025-05-06 06:26:50',0);
