INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10664,'RepublicBank_AccountStatment','$source = \"RepublicBank_AccountStatment\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get Account Name\r\n$accountName = get text in box 686 596 page.left page.middleX => take words 2 => get text\r\n\r\n// Delete summary right side\r\n@headerBottom = get line starting \"End\" => bottom\r\ndelete text in box page.top @headerBottom page.middleX page.right\r\n\r\n// Get Account Number\r\n//$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 1 => get text\r\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 2 => get decimal\r\n\r\n$openingBalance = get line containing \"Beg\" => get words after \"Balance on\" => get words after \"$\" => get decimal\r\n\r\n$periodFrom = get line starting \"Beg\" => get words after \"Balance on\" => take words 2 => get date \"M/d/yy\"\r\n\r\n$closingBalance = get line starting \"End\" => get words after \"Balance on\" => get words after \"$\" => get decimal\r\n\r\n$periodTo = get line starting \"End\" => get words after \"Balance on\" => take words 2 => get date \"M/d/yy\"\r\n\r\n//@headerBottom = get line starting \"Ending Balance on\" => bottom => get line below => top\r\n@headerBottom = get line starting \"End\" => get words after \"Balance on\" => bottom => get line below => top\r\ndelete text in box page.top @headerBottom 0 page.right\r\n\r\n// Delete header text\r\nignore header above 600\r\n\r\n// Get start & end of CreditAmounts\r\ngo to page 1\r\n@checksTop = get line starting \"Check # Date Amount\" => if not found then blank => bottom => get line below\r\n@lastchecks = get last line starting \"Check # Date Amount\" => if not found then blank => bottom\r\n@checksBottom = get last line starting \"Check # Date Amount\" => if not found then blank => bottom => get break below =>