INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10666,'Weatherbys_PrivateBank','$source = \"Weatherbys_PrivateBank\"\n$periodBufferDays = 28\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 =>  get decimal\n$accountName = get text in box page.top page.middleY page.bottom page.middleX => take words 4 => get text\n\n//Get Periods\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => take words 1 => get date \"d/M/yyyy\"\n$periodright = get last line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => take words 2 => take last words 1 => left\n$periodtop = get last line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => bottom\n$periodbottom = get last line starting \"STATEMENT DATE\" => top\n$periodTo = get text in box $periodtop $periodbottom page.left $periodright => take words 1 => get date \"d/M/yyyy\"\n\n//Get Balances\ngo to page 1\n$openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => take last words 2 => get decimal\n$balanceleft = get last line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => take last words 2 => take words 1 => right\n$balancetop = get last line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => bottom\n$balancebottom = get last line starting \"STATEMENT DATE\" => top\n$closingBalance = get text in box $balancetop $balancebottom $balanceleft page.right => take last words 2 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 15\n@detailsleft = get line containing @tranactionColumns => get words after \"DATE\" => take words 1 => left => subtract 5\n@debileft = get line containing @tranactionColumns => get words after \"DETAILS\" => take words 1 => left => subtract 15\n@debitright = get line containing @tranactionColumns => get words after \"DETAILS\" => take words 1 => right => add 8\n@creditright = get line containing @tranactionColumns => take last words 2 => take words 1 => right => add 8\n@balanceright = get line containing @tranactionColumns =>  take last words 1 => right => add 15\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"DATE DETAILS DEBIT CREDIT BALANCE\" => bottom => get line below\n$gotolastTransBottom = get last line starting \"DATE DETAILS DEBIT CREDIT BALANCE\"\n@transtionBottom = get line starting \"STATEMENT DATE\" => top => get line above\n\ndelete all lines starting \"DATE DETAILS DEBIT CREDIT BALANCE\"\ndelete all lines starting \"STATEMENT DATE\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\ndelete all lines containing \"Page\"\n\nignore header above 590\nignore footer below 25\n\n$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detailsleft @debileft @debitright @creditright @balanceright => describe table false \"*Date[d/M/yyyy]\" Details #Debit #Credit #Balance\n\n\n','2025-05-22 07:20:21',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10667,'BOI_CreditCard_WithSummary','$source = \"BOI_CreditCard_WithSummary\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number and account name\r\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 4 => get text\r\n$accountName = get text in box 695 660 page.left page.middleX => take words 2 => get text\r\n\r\n// Get opening/closing balance\r\n//$openingBalance = get line containing \"Previous statement balance\" => get words after \"statement balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Outstanding statement balance\" => get words after \"statement balance\" => take words 1 => get decimal\r\n\r\n// Get period from/to\r\n$periodTo = get line containing \"Statement date:\" => get words after \"Statement date:\" => take words 3 => get date \"dd MMMM yyyy\"\r\n@transpage = get line containing \"Your Transactions\"\r\n@LeftSidetxt = delete text in box page.top page.bottom page.left 160 => get text\r\n$periodFrom = get line containing \"Account number\" => bottom => get line below => take words 4 => take last words 2 => get date \"dd MMM\"\r\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => get decimal\r\n\r\n// Get top & bottom of the transactions table\r\n@transactionsTop = get line containing \"Date Date Description Amount\" => bottom => get line below => bottom => get line below\r\n\r\ndelete all lines starting \"Total for new transactions\"\r\n\r\n@transactionsBottom = get line containing \"Total payments and credits\" => top => get line above\r\n\r\n@DelHeader = get line containing \"Your Transactions\" => bottom\r\nignore header above @DelHeader\r\ndelete all lines starting \"Date Date Description Amount\"\r\ndelete all lines starting \"Transaction Posting\"\r\ndelete all lines starting \"Continued on the next page\"\r\ndelete all lines starting \"Previous Balance\"\r\ndelete all lines containing \"Account number\"\r\n\r\n// Read the transactions\r\n$transactions  = get multi page table @transactionsTop @transactionsBottom 200 240 450 550 => describe table false \"Date[dd MMM]\" Details *#Credit','2026-09-08 10:16:47',0);
