INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10669,'CIBC_Bank_USA','$source = \"CIBC_Bank_USA\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\n\n// Get Account Name\n\n$accountName = get text in box 665 653 100 page.middleX => take words 3 => get text\n\n// Get Account Number\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get Period/From To\n\n$periodFrom = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get TextInBOx\n\n@TEXTBOXTop = get line containing \"Beginning Balance as of\" => top\n@TEXTBOXBottom = get line starting \"+ Deposits and Credits\" => top\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 55 330\n$openingBalance = take last words $TEXTBOX 1 => get decimal\n@TEXTBOXTop1 = get last line containing \"- Withdrawals and Debits\" => bottom\n@TEXTBOXBottom1 = get last line starting \"Ending Balance as of\" => bottom\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 55 330\n$closingBalance = take last words $TEXTBOX1 1 => get decimal\n\n//Checks\n\ngo to page 1\n@checksTop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get line starting \"Number Date Amount\" => if not found then blank => bottom => get break below => get line at\ngo to page 1\nignore header above 650\nignore footer below 35\ndelete all lines containing \"(continued)\"\n$checksLeft = get multi page table @checksTop @checksBottom 55 140 260 308 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\ndelete all lines containing \"Number Date Amount\"\ndelete all lines containing \"Item Count\"\n$checksRight = get multi page table @checksTop @checksBottom 310 395 518 564 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n\n// Get start & end of Debits\n\ngo to page 1\n@DebitsTop = get line starting \"Date Description Subtractions\" => if not found then blank => bottom => get line below\ndelete all lines containing \"Date Description Subtractions\"\ndelete all lines containing \"Thank you for banking with CIBC\"\ndelete all lines starting \"Credits\"\n@DebitsBottom = get line containing \"Date Description Additions\" => if not found then blank => top => get line above\n$Debits = get multi page table @DebitsTop @DebitsBottom 50 100 498 565 => describe table false \"*Date[MM/dd]\" Details #Debit\n\n// Get start & end of Credits\n\ngo to page 1\n@CreditsTop = get line starting \"Date Description Additions\" => if not found then blank => bottom => get line below\ndelete all lines containing \"Date Description Additions\"\ndelete all lines containing \"Thank you for banking with CIBC\"\ndelete all lines containing \"Credits\"\n@CreditsBottom = get line containing \"Daily Balances\" => if not found then blank => top => get line above\n$Credits = get multi page table @CreditsTop @CreditsBottom 50 100 498 565 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n$transactions = combine described tables $Debits $Credits $checksLeft $checksRight','2025-05-22 07:20:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10670,'Tangerine_CreditCard','$source = \"Tangerine_CreditCard\"\r\n$features = \"REVERSE_ORDER CREDIT_CARD\"\r\n\r\ngo to page 1\r\n$Top = get line containing \"Account number\"  => top\r\n$bottom = get line containing \"Fees\" => bottom => get line below => bottom\r\n$getsummary = get text in box $Top $bottom 385 580\r\n\r\n$accountNumber = take words $getsummary 6 => skip words 2 => get text\r\n$accountname = take words $getsummary 6 => skip words 2 => get text\r\n\r\n$periodFrom = get words after $getsummary \"Statement period\" => take words 2 => get date \"MMM d\"\r\n$periodTo = get line containing \"Statement period\" => take last words 3 => get date \"MMM d, yyyy\"\r\n//get words after $getsummary \"Statement period\" => take words 6 => skip words 3 => get date \"MMM d, yyyy\"\r\n\r\n$closingBalance = get words after $getsummary \"Previous balance\" => take words 1 => get decimal\r\n$openingBalance = get words after $getsummary \"New balance\" => take words 1 => get decimal\r\n\r\n\r\n$transactionsTop = get line containing \"Previous Balance\" => bottom => get line below\r\n$transactionsBottom = get line starting \"New Balance\" => top => get line above\r\n\r\n$Date_left = get line containing \"Transaction Posted Description\" => get words before \"Description\" => take last words 1 => left => subtract 5\r\n$Description_left = get line containing \"Transaction Posted Description\" => get words after \"Posted\" => left => subtract 3\r\n$Description_right = get line containing \"Transaction Posted Description\" => get words after \"Description\" => left => subtract 1.9\r\n$category_right = get line containing \"Transaction Posted Description\" => get words after \"Description\" => take words 1 => right => add 1\r\n$Paidout_right = get line containing \"Transaction Posted Description\" => get words after \"Category\" => take words 1 => right => add 3\r\n\r\n$datetop = get line starting \"Date Date\" => top\r\n$datebot = get line containing \"Date Date\" => bottom\r\n$dltdate = delete text in box $datetop $datebot 35 106 => get text\r\n\r\n$deleteext = delete text in box page.top page.bottom 390 580 => get text\r\ndelete all lines containing \"Description\"\r\ndelete all lines containing \"Hotel & Motel\"\r\ndelete all lines containing \"Recurring Bill Payments\"\r\ndelete all lines starting \"New Balance\"\r\n\r\n\r\n//$transactions = get multi page table $transactionsTop $transactionsBottom 35 85 137 256 286 323 => describe table false - \"*Date[d-MMM-yyyy]\" Details - #Credit\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 35 $Date_left $Description_left $Description_right $category_right $Paidout_right => describe table false - \"*Date[d-MMM-yyyy]\" Details - #Credit','2026-04-30 08:38:49',0);
