Top $transactionsBottom 35 85 152 332 600 647 728 805 => describe table false \"*Date[d-MMM-yyyy]\" - TransactionType Details #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10672,'ANZ','$source = \"ANZ\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 45\n//set negative marker \"CR\"\n// Get Account Name\n$accountName = \"ANZ\"\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 2 => get text\n\n//Get PeriodInBOx\ngo to page 1\n@PeriodFromTop = get line containing \"Date Description Debits ($) Credits ($) Balance ($)\" => bottom\n@PeriodFromBottom = get line starting \"Further information in relation to this product\" => top\n$PeriodFromBox = get text in box @PeriodFromTop @PeriodFromBottom page.left 72\n$PeriodFrom = take words $PeriodFromBox 3 => get date \"yyyy dd MMM\"\n$PeriodTo = get last line containing \"STATEMENT NUMBER\" => bottom => get line below => take last words 3 => get date \"dd MMMM yyyy\"\n\n// Opening and Closing Balance\ngo to page 1\n$openingbalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => take words 1 => get decimal\n$closingbalance = get last line containing \"TOTALS AT END OF PERIOD\" => get words after \"TOTALS AT END OF PERIOD\" => take last words 1 => get decimal\ngo to page 1\ndelete all pages containing \"WELCOME TO YOUR ANZ\"\ngo to page 1\n@transactionstop = get line starting \"Date Description Debits ($)\" => bottom => get line below => bottom => get line below\n\n@transactionsbottom = get last line containing \"Further information in relation\" => top => get line above\n\n// stripping unwanted records from txns\n\ndelete all lines containing \"202\"\ndelete all lines containing \"Debits ($) Credits ($) Balance ($)\"\ndelete all lines containing \"Date Description Debits ($)\"\ndelete all lines containing \"TOTALS AT END OF PAGE\"\ndelete all lines containing \"TOTALS AT END OF PERIOD\"\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"relation to this product\"\ndelete all lines containing \"visiting anz.com\"\ndelete all lines containing \"Specialist\"\ndelete all lines containing \"IMPORTANT\"\ndelete all lines containing \"ENTRIES AND CALL\"\ndelete all lines containing \"authorisation and verification\"\ndelete all lines containing \"unresolved issue with\"\ndelete all lines containing \"information in relation\"\ndelete all lines containing \"information by reviewing the terms\"\ndelete all lines containing \"Page\"\n\nignore header above 720\nignore footer below 28\n\n$transactions = get multi page table @transactionstop @transactionsbottom 40 75 335 405 500 580 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit #Balance','2025-05-29 06:48:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10673,'St_Marrys_CreditUnion','$source = \"St_Marrys_CreditUnion\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\nset negative marker \"-\"\nremove page 2\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\n\n// Get account name\n@TEXTBOXTop = get line containing \"RETURN SERVICE REQUESTED\" => bottom\n@TEXTBOXBottom = get line starting \"Date Transaction Description Withdrawal\" => top\n$accountName = get text in box @TEXTBOXTop @TEXTBOXBottom page.left page.middleX => take words 3 => get text\n\n// Get Period To\n$periodTo = get line containing \"Statement Date:\" => get words after \"thru\" => get date \"MMM d, yyyy\"\n\n//Get Period From\n$periodFrom = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => get words before \"thru\" => get date \"MMM d, yyyy\"\n\n// Get Opening balance\n$openingBalance = get line containing \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => get decimal\n\n// Get closing Balance\n$closingBalance = get line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => get decimal\n\ngo to page 1\n// Get table start and end\n@transactionstop = get line containing \"BEGINNING BALANCE\" => bottom => get line below\n\ndelete all lines containing \"Product Account # Ending Balance\"\n@transactionsbottom = get line containing \"ENDING BALANCE\" => top => get line above\n\nignore header above 680\nignore footer below 30\n\ndelete all lines containing \"(Continued)\"\ndelete all lines containing \"Date Transaction Description Withdrawal\"\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 0 80 360 455 525 580 => describe table false \"*Date[MMM d]\" Details #Debit #Credit #Balance','2025-05-29 06:48:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10674,'N26_Bank_French','$source = \"N26_Bank_French\"\n$periodBufferDays = 7\nset culture \"de-de\"\n\n//Get account name\n\n@TextBox = get text in box 80 0 0 350\n\n//Get accountName & accountNumber\n$accountName = take words @TextBox 2 => get text\n$accountNumber = get words after @TextBox \"IBAN:\" => take words 1 => get text\n\n//Get statement period\n@getperiod = get line containing \"Description Date de réservation Montant\" => top => get line above\n$periodfrom = get words before @getperiod \"jusqu\'au\" => get date \"dd.MM.yyyy\"\n$periodto = get words after @getperiod \"jusqu\'au\" => get date \"dd.MM.yyyy\"\n\n//Get opening & closing balance\n$openingbalance = get line containing \"Ancien solde\" => get words after \"Ancien solde\" => get decimal\n$closingbalance = get line containing \"Votre nouveau solde\" => get words after \"Votre nouveau solde\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Description Date de réservation Montant\" => bottom => get line below\n@transactionsBottom = get line containing \"Ancien solde\" => top => get line above\n\nget line starting \"Description\" => bottom => ignore header above\nignore footer below 80\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 360 475 565 => describe table false Details \"Date[dd.MM.yyyy]\" *#Credit','2025-05-29 06:48:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10675,'CitiBANK_AccountStatementReport','$source = \"CitiBANK_AccountStatementReport\"\n$periodBufferDays = 28\n// Get Accounts\n$accountNumber = get line starting \"Account Number\" => get words after \"Name\" => take words 1 => get decimal\n$accountName = get line starting \"Customer Number\" => get words after \"Name\" =>  take words 4 => skip words 1 => get text\n\n//Get Periods\n@periodTop =  get line starting \"Entry Date\" => bottom\n@periodRight = get line starting \"Entry Date\" => get words after \"Entry\" => take words 1 => right => add 10\n$periodFrom =  get text in box @periodTop  0  0 @periodRight => take words 1 => get date \"M/d/yyyy\"\n\n@gotolastTop = get last line starting \"Entry Date\" => bottom\n@gotolastBottom  = get line containing \"Indicates Calculated Balances\" => top\n$periodTo =  get text in box @gotolastTop  @gotolastBottom  0 @periodRight => take last words 1 => get date \"M/d/yyyy\"\n\ngo to page 1\n//Get Balances\n$openingBalance =  get line starting \"Entry Date\" => top => get line above => take words 1 => get decimal\n$closingBalance = get last line starting \"Entry Date\" => top => get line above => take words 2 => take last words 1 => get decimal\n\ndelete all pages containing \"Page Breaks\"\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Entry Date\" => get text\n\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@date1left = get line containing @tranactionColumns => get words after \"Entry Date\" => take words 1 => left => subtract 10\n@typrleft = get line containing @tranactionColumns => get words after \"Value Date\" => take words 1 => left => subtract 5\n@detailleft = get line containing @tranactionColumns => get words after \"Transaction Description\" => take words 1 => left => subtract 5\n@balanceleft = get line containing @tranactionColumns =>  take last words 1 => left => subtract 5\n@balanceright = get line containing @tranactionColumns =>  take last words 1 => right => add 200\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Entry Date\" => bottom => get line below\n$gotolastTransBottom = get last line starting \"Entry Date\"\n@transtionBottom = get line containing \"Indicates Calculated Balances\" => top => get line above\n\ngo to page 1\n@ft_top = get line containing \"Indicates Calculated Balances\" => if not found then blank => top => add 5\n@deleteEvery_Box = delete text in box on every page @ft_top page.bottom 0 page.right => get text\ndelete all lines starting \"Entry Date\"\ndelete all lines starting \"Reference\"\ndelete all lines starting \"=\"\ndelete all lines containing \"Indicates Calculated Balances\"\ndelete all lines starting \"Report Date\"\n\nignore header above 405\nignore footer below 170\n\n$transactions = get multi page table @transtionTop @transtionBottom @dateleft @date1left @typrleft @detailleft @balanceleft @balanceright => describe table false \"*Date[M/d/yyyy]\" - TransactionType Details #Credit\n','2025-05-29 06:48:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10676,'Glacier','$source = \"Glacier\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n//set negative marker for debit amount\nset negative marker \"-\"\n\n\n//get account name\n@bottom = get line containing \"CHECKING ACCOUNTS\" => top\n$accountName = get text in box page.top @bottom page.left page.middleX => take words 3 => get text\n\n//get account number\n$accountNumber = get line containing \"Primary Account\" => get words after \"Primary Account\" => take words 1 => get text\n\n//get statement period\n@period = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 3\n$periodFrom = take words @period 1 => get date \"M/dd/yy\"\n$periodTo = take last words @period 1 => get date \"M/dd/yy\"\n\n//get opening/closing\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n@detailsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 3\n@debitleft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left\n@debitright = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => right => add 20\n//@creditleft = get line containing @tranactionColumns => get words before \"Balance\" => take last words 1 => left => subtract 10\n@creditlright =   get line containing @tranactionColumns => get words before \"Balance\" => take last words 1 => right => add 15\n@balanceright = get line containing @tranactionColumns => take last words 1 => right => add 13\n\n\n//get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Withdrawals\" => bottom => get line below\n\n//get end of table transactions\n@lastpage = get last line starting \"Date Description Withdrawals\"\n@transactionsBottom = get line above 0\n\n//delete extra check table\n//@summary_top = get line containing \"SUMMARY BY CHECK NUMBER\" => bottom\n//$check_del = delete text in box @summary_top page.bottom page.left page.right => get text\n\ngo to page 1\n\n@summary_top = get line containing \"SUMMARY BY CHECK NUMBER\" => if not found then blank => bottom\n$check_del = delete text in box @summary_top page.bottom page.left page.right => get text\n\n@summary_top1 = get line containing \"Summary by Check Number\" => if not found then blank => bottom\n$check_del1 = delete text in box @summary_top1 0 0 page.right => get text\n\n\n//delete extra texts or garbage values\ndelete all lines containing \"SUMMARY BY CHECK NUMBER\"\ndelete all lines containing \"Summary by Check Number\"\n//ignore header\nget last line starting \"Date Description Withdrawals\" => bottom => ignore header above\n\ngo to page 1\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 30 60 250 310 385 475 => describe table false \"*Date[M/dd]\" Details #Debit #Credit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateleft @detailsleft @debitleft @debitright @creditlright @balanceright => describe table false \"*Date[M/dd]\" Details #Debit #Credit #Balance\n','2025-07-24 06:51:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10677,'SG_KleinwortHambros_Bank','$source = \"SG_KleinwortHambros_Bank\"\nset negative marker \"DR\"\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\n\n// Get account name\n@TEXTBOXBottom = get line containing \"Balance Brought Forward\" => top\n$accountName = get text in box page.top @TEXTBOXBottom page.left 220 => take words 3 => get text\n\ndelete all lines starting \"Balance brought forward\"\ndelete all lines starting \"Balance carried forward\"\n\ngo to page 1\n// Get Period From\n$periodFrom = get line containing \"Balance Brought Forward\" => get words before \"Balance\" => take words 1 => get date \"dd-MMM-yyyy\"\n\n//Get Period To\n$periodTo = get last line containing \"Balance Carried Forward\" => get words before \"Balance\" => take words 1 => get date \"dd-MMM-yyyy\"\n\ngo to page 1\n// Get Opening balance\n$openingBalance = get line containing \"Balance Brought Forward\" => take last words 2 => get decimal\n\n// Get closing Balance\n$closingBalance = get last line containing \"Balance Carried Forward\" => take last words 2 => get decimal\n\nignore header above 400\nignore footer below 120\n\ngo to page 1\n// Get table start and end of table\n@transactionstop = get line containing \"Balance Brought Forward\" => bottom => get line below\n@transactionsbottom = get last line containing \"Balance Carried Forward\" => top => get line above\n\ndelete all lines containing \"Balance Brought Forward\"\ndelete all lines containing \"Balance Carried Forward\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 145 350 450 570 690 780 => describe table false \"*Date[dd-MMM-yyyy]\" Details - #Debit #Credit #Balance','2025-05-29 06:48:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10678,'TriodosInternet','$source = \"TriodosInternet\"\n\n\n$features = \"NO_TRANSACTION_YEAR REVERSE_ORDER\"\n\n\n// Get Period From/To\n$periodFrom = get line containing \"Opening balance\" => get words after \"Opening balance\" => take words 1 => get date \"d/MM/yyyy\"\n$periodTo = get line containing \"Closing balance\" => get words after \"Closing balance\" => take words 1 => take last words 1 => get date \"d/MM/yyyy\"\n\n\n//get account name\n@accnt_top = get line containing \"IMPORTANT MESSAGES\" => bottom\n@accnt_bottom = get line containing \"UNLIMITED CHECKING\" => top\n$accountName = \"Triodos Internet\"\n\n//get account number\n$accountNumber = get line containing \"Account Account\" => bottom => get line below => take words 2 => get text\n\n// Get Opening/Closing balance\n$closingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take last words 1 => get decimal\n$openingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => take last words 1 => get decimal\n\n//Get start of table\n@transactionsTop = get line containing \"Account Account Name / Reference\" => bottom => get line below\n\n//delete extra texts/lines\ndelete all lines starting \"https://banking.triodos.co.uk/ib\"\ndelete all lines starting \"Print - Triodos Internet Bankieren\"\n\ngo to last page\n@transactionsBottom = get line above 0\n\n\n//ignore header above 672\n//ignore footer below 38\n\n\n//Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 75 228 358 386 525 570  => describe table false \"Date[d/MM/yyyy]\" - Details TransactionType #Credit *#Balance','2025-05-29 06:48:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10679,'StandardBank_Portfolio','$source = \"StandardBank_Portfolio\"\n\ngo to page 1\n$accountNumber = get line containing \"Account No:\" => get words after \"Account No:\" => take words 1 => get text\n$accountname = get line containing \"Account No:\" => get words after \"Account No:\" => take words 1 => get text\n\n$PeriodFromtext = get line starting \"Statement and Tax Invoice\" => get words after \"Statement and Tax Invoice\"\n$periodfrom = take last words $PeriodFromtext 7 => take words 3 => get date \"d MMM yyyy\"\n$periodto = take last words $PeriodFromtext 3 => get date \"d MMM yyyy\"\n\n$openingbalance = get line containing \"BALANCE B/F\" => take last words 1 => get decimal\n$closingbalance = get line containing \"BALANCE C/F\" => take last words 1 => get decimal\n\ngo to page 1\n$Date_left = get line containing \"Date Transaction Description Amount(R)\" => get words before \"Transaction\" => left => subtract 5\n$Description_left = get line containing \"Date Transaction Description Amount(R)\" => get words after \"Date\" => left => subtract 3\n$Description_right = get line containing \"Date Transaction Description Amount(R)\" => get words after \"Description\" => left => subtract 3\n$Paidout_right = get line containing \"Date Transaction Description Amount(R)\" => get words after \"Amount (R) (-DR/CR)\" => left => subtract 3\n//$Paidin_right = get line containing \"Date Transaction Description Amount(R)\" => get words before \"Balance\" => right => add 30\n$Balance_right = get line containing \"Date Transaction Description Amount(R)\" => get words after \"Amount (R) (-DR/CR)\" => right => add 5\n\n\n$transactionsTop = get line containing \"Date Transaction Description Amount(R)\" => bottom => get line below\n$transactionsBottom = get line containing \"BALANCE C/F\" => top => get line above\n\nignore footer below 68\nignore header above 674\ndelete all lines containing \"BALANCE B/F\"\n\ngo to page 1\n//$transactions = get multi page table $transactionsTop $transactionsBottom 30 85 395 480 565 => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Balance\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Description_left $Description_right $Paidout_right $Balance_right => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Balance','2025-05-29 06:48:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10680,'Global_Bank','$source = \"Global_Bank\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account number\n$accountNumber = get line containing \"CUENTA:\" => get words after \"CUENTA:\" => take words 1 => get text\n\n// Get account name\n$accountName = get line containing \"NOMBRE:\" => get words after \"NOMBRE:\" => take words 3 => get text\n\n@TEXTBOXTop = get last line containing \"FECHA REFERENCIA SUCURSAL\" => bottom\n@TEXTBOXBottom = get line containing \"RESUMEN DEL MES\" => top\n\n//Get Period To\n$periodTo = get text in box @TEXTBOXTop @TEXTBOXBottom page.left 132 => take last words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n// Get Period From\n$periodFrom = get line containing \"FECHA REFERENCIA SUCURSAL\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\n\n// Get Opening balance\n$openingBalance = get line containing \"FECHA REFERENCIA SUCURSAL\" => bottom => get line below => take last words 1 => get decimal\n\n// Get closing Balance\n$closingBalance = get line containing \"SALDO CONTABLE:\" => get words after \"SALDO CONTABLE:\" => get decimal\n\ngo to page 1\n// Get table start and end of table\n@transactionstop = get line starting \"FECHA REFERENCIA SUCURSAL\" => bottom => get line below\n@transactionsbottom = get last line containing \"RESUMEN DEL MES\" => top => get line above\n\nget line containing \"FECHA REFERENCIA SUCURSAL\" => top => ignore header above\ndelete all lines containing \"FECHA REFERENCIA SUCURSAL\"\nget line containing \"RESUMEN DEL MES\" => bottom => ignore footer below\ndelete all lines containing \"RESUMEN DEL MES\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 132 245 290 650 750 885 990 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType - Details #Debit #Credit #Balance','2025-05-29 06:48:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10681,'Wave_CreditCard','$source = \"Wave_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\nset negative marker \"CR\"\n$periodBufferDays = 45\n\n// Get Account Name\n\n$accountName = get text in box 660 653 50 page.middleX => take words 3 => get text\n\n// Get Account Number\n\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 4 => get text\n\n// Get Period/From To\n\n$periodFrom = get line containing \"Your Wave account summary for the period\" => bottom => get line below => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = get line containing \"Your Wave account summary for the period\" => bottom => get line below => take last words 3 => get date \"d MMMM yyyy\"\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"Transaction date Posted date Description Amount\" => bottom => get line below => take last words 1 => get decimal\n$closingbalance = get line containing \"Closing statement balance\" => get words after \"Closing statement balance\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionstop = get line starting \"Transaction date Posted date Description Amount\" => bottom => get line below\n@transactionsbottom = get last line containing \"Closing statement balance\" => top => get line above\n\n// stripping unwanted records from txns\ndelete all lines containing \"Previous statement balance\"\ndelete all lines containing \"Closing statement balance\"\n\nignore header above 695\nignore footer below 70\n\n$transactions = get multi page table @transactionstop @transactionsbottom 110 190 480 565 => describe table false \"*Date[d MMMM]\" Details #Credit','2025-05-29 06:48:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10682,'FirstInternet_Bank','$source = \"FirstInternet_Bank\"\n$periodBufferDays = 45\n\n// Get Account Name\n\n$accountName = get text in box 648 638 100 page.middleX => take words 3 => get text\n\n// Get Account Number\n\n$accountNumber = get line containing \"Business Money Market\" => get words after \"Business Money Market\" => take words 1 => get text\n\n// Get Period/From To\n\n$periodFrom = get line containing \"Statement Start:\" => get words after \"Statement Start:\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Statement End:\" => get words after \"Statement End:\" => take words 1 => get date \"MM/dd/yyyy\"\n\n//Get TextInBOx\n\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\n@TEXTBOXBottom = get line starting \"Deposits / Credits\" => top\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 55 330\n$openingBalance = take last words $TEXTBOX 1 => get decimal\n@TEXTBOXTop1 = get last line containing \"Fees\" => bottom\n@TEXTBOXBottom1 = get last line starting \"Ending Balance\" => bottom\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 55 330\n$closingBalance = take last words $TEXTBOX1 1 => get decimal\n\n\ngo to page 1\n@transactionstop = get line starting \"Date Description Withdrawals\" => bottom => get line below\ndelete all lines containing \"Date Description Debits\"\n@transactionsbottom = get text in box 30 page.bottom page.left page.right => top => get line above\n\ndelete all lines containing \"Beginning Balance\"\nignore header above 550\nignore footer below 50\n\n$transactions = get multi page table @transactionstop @transactionsbottom 45 100 350 455 510 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2025-05-29 06:48:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10683,'ChaseBank_UK_WithoutAccountNo','$source = \"ChaseBank_UK_WithoutAccountNo\"\n\n// Get account name\n@TEXTBOXBottom = get line containing \"Round-up statement\" => top\n$accountName = get text in box page.top @TEXTBOXBottom page.left 220 => take words 2 => get text\n\n// Get account number\n$accountNumber = get text in box page.top @TEXTBOXBottom page.left 220 => take words 2 => get text\n\n\ndelete all lines starting \"Opening balance\"\n\ngo to page 1\n// Get Period From\n$periodFrom = get line containing \"Opening balance\" => get words before \"Opening\" => take words 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n//Get Period To\n$periodTo = get line containing \"Closing balance\" => get words before \"Closing\" => take words 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n// Get Opening balance\n$openingBalance = get line containing \"Opening balance\" => get words after \"balance\" => take last words 1 => get decimal\n\ngo to page 1\n// Get table start and end of table\n@transactionstop = get line containing \"Opening balance\" => bottom => get line below\n@transactionsbottom = get last line containing \"Closing balance\" => top => get line above\n\nget line starting \"Date Transaction details\" => bottom => ignore header above\nignore footer below 120\n\n// Get closing Balance\n$closingBalance = get last line containing \"Closing balance\" => get words after \"balance\" => take last words 1 => get decimal\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 100 380 490 570 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit #Balance','2025-05-29 06:48:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10684,'HSBC_BANK_CANADA','$source = \"HSBC_BANK_CANADA\"\n$periodBufferDays = 45\n\n// Get Account Name\n$accountName = get line containing \"Account Name\" => get words after \"Account Name\" => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get Period/From To\n$periodFrom = get line containing \"STATEMENT PERIOD IS\" => get words after \"STATEMENT PERIOD IS\" => take words 1 => get date \"dMMMyyyy\"\n$periodTo = get line containing \"STATEMENT PERIOD IS\" => bottom => get line below => take words 1 => get date \"dMMMyyyy\"\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => take last words 1 => get decimal\n$closingbalance = get last line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => take last words 1 => get decimal\n\n// Discard addresses as they get in the way of the balances\ngo to page 1\n@dropBottom = get line containing \"Withdrawals\" => top\n$get_text = delete text in box page.top @dropBottom page.middleX page.right => get text\n\n$DeleteLine1 = get line containing \"Date Transaction Details Withdrawals Deposits\" => top => get line above => take words 2 => get text\n$DeleteLine2 = get line containing \"Date Transaction Details Withdrawals Deposits\" => top => get line above => top => get line above => take words 2 => get text\n$DeleteLine3 = get line containing \"Date Transaction Details Withdrawals Deposits\" => top => get line above => top => get line above => top => get line above => take words 2 => get text\n\ngo to page 1\n@transactionstop = get line containing \"OPENING BALANCE\" => bottom => get line below\ndelete all lines containing \"OPENING BALANCE\"\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"Transaction Details\"\ndelete all lines containing \"Account Number\"\ndelete all lines containing \"DR=Debit\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"TORONTO\"\ndelete all lines containing \"STEELES\"\ndelete all lines containing \"HSBC BANK\"\ndelete all lines starting $DeleteLine1\ndelete all lines starting $DeleteLine2\n//delete all lines starting $DeleteLine3\n@transactionsbottom = get last line containing \"CLOSING BALANCE\" => top => get line above\ndelete all lines containing \"CLOSING BALANCE\"\n\nignore header above 668\nignore footer below 88\n\n$transactions = get multi page table @transactionstop @transactionsbottom 30 100 310 400 510 580 => describe table false \"Date[dMMMyyyy]\" Details **#Debit **#Credit #Balance','2025-05-29 06:48:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10685,'Square_Bank','$source = \"Square_Bank\"\r\n$periodBufferDays = 28\r\n// Get Accounts\r\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number\" => take last words 1 => get text\r\n$accountName = get line starting \"Location\" => bottom => get line below => take words 2 => get text\r\n\r\n//Get Periods\r\n$periodFrom = get line containing \"The starting balance\" => get words after \"account on\" =>  take words 3 => get date \"MMMM d, yyyy\"\r\n$periodTo = get line containing \"The ending balance\" => get words after \"account on\" =>  take words 3 => get date \"MMMM d, yyyy\"\r\n\r\n//Get Balances\r\ngo to page 1\r\n$openingBalance = get text in box page.top page.middleY page.middleX page.right => get words after \"Starting balance\" => take words 1 => get decimal\r\n@top = get line containing \"Starting balance\" => bottom\r\n$closingBalance = get text in box @top page.bottom page.middleX page.right => get words after \"Ending balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get transactions Column\r\n@transactionColumns = get line containing \"Activity type Amount Balance\" => get text\r\n@dateleft = get line containing @transactionColumns => take words 1 => left => subtract 10\r\n@detailsleft = get line containing @transactionColumns => get words after \"Date\" => take words 1 => left => subtract 5\r\n@typeleft = get line containing @transactionColumns => get words before \"type\" => take last words 1 => left => subtract 5\r\n@amountleft = get line containing @transactionColumns => get words before \"Balance\" => take last words 1 => left => subtract 5\r\n@balanceleft = get line containing @transactionColumns =>  take last words 1 => left => subtract 5\r\n@balanceright = get line containing @transactionColumns =>  take last words 1 => right => add 50\r\n\r\ngo to page 1\r\n// Read the transactions\r\n@transactionsTop = get line containing \"Activity type Amount Balance\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"Block Inc\" => top => get line above\r\n\r\ngo to page 1\r\n@ft_top = get line starting \"Block Inc\" => top => add 5\r\n@deleteEvery_Box = delete text in box on every page @ft_top page.bottom 0 page.right\r\ndelete all lines starting \"Date Details Activity type\"\r\ndelete all lines starting \"Block Inc\"\r\ndelete all lines starting \"Oakland, CA\"\r\ndelete all lines containing \"squareup.com/help\"\r\ndelete all lines containing \"Activity type Amount\"\r\ndelete all lines containing \"This page not converted\"\r\nignore footer below 75\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateleft @detailsleft @typeleft @amountleft @balanceleft @balanceright => describe table false \"*Date[M/d/yyyy]\" TransactionType Details #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10686,'FirstCahawba_Bank','$source = \"FirstCahawba_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$accountNumber = get line starting \"Account:\" => get words after \"Account:\" => take words 1 =>  get decimal\n$accountName = get text in box page.top page.bottom page.left page.middleX => take words 4 => get text\n\n@Period_BalanceText = get line containing \"Beginning Balance\" => get text\n\n$periodFrom  = get line containing @Period_BalanceText => get words after \"Beginning Balance\" => take words 1 => get date \"M/d/yy\"\n$openingBalance  = get line containing @Period_BalanceText => get words after \"Beginning Balance\" => take words 2 => take last words 1 => get decimal\n\n@periodLeft = get line containing \"Ending\" => left\n@periodTop = get line containing \"Ending\" => top\n@periodBottom = get line containing \"Ending\" => bottom\n\n$periodTo =  get text in box @periodTop @periodBottom @periodLeft page.right => get words after \"Ending\" => take words 1 => get date \"M/d/yy\"\n$closingBalance =  get text in box @periodTop @periodBottom @periodLeft page.right => get words after \"Ending\" => skip words 1 => take words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Activity Description\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detilsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 10\n@creditleft = get line containing @tranactionColumns => get words after \"Activity Description\" => take words 1 => left => subtract 8\n@creditright = get line containing @tranactionColumns => get words after \"Activity Description\" => take words 1 => right => add 8\n@debitright = get line containing @tranactionColumns => get words before \"Balance\" => take last words 1 => right => add 8\n@balanceright = get line containing @tranactionColumns =>  take last words 1 => right => add 20\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Date Activity Description\" => top => get line above\n@transtionBottom = get  line starting \"Daily\" => top => get line above\n\nignore header above 650\nignore footer below 50\n\ndelete all lines starting \"Date Activity Description Deposits\"\ndelete all lines starting \"Miscellaneous\"\n\n$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detilsleft @creditleft @creditright @debitright @balanceright => describe table false \"*Date[M/dd]\" Details #Credit #Debit\n\n','2025-05-29 06:49:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10687,'PenAir_CreditUnion','$source = \"PenAir_CreditUnion\"\n$periodBufferDays = 28\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n//set negative marker \"-\"\n//Get Accounts\n$accountName = get text in box 660 page.middleY page.left page.middleX => take words 3 => get text\n\n@accTop = get line containing \"Account Number:\" => bottom\n@accLeft = get line containing \"Account Number:\" => get words before \"Number:\" => take last words 1 => left\n@accRight = get line containing \"Account Number:\" => get words after \"Account\" => take  words 1 => right\n$accountNumber = get text in box @accTop page.bottom @accLeft @accRight => take words 1 => get text\n\n@periodText = get line containing \"Statement Period:\" => bottom => get line below => get text\n$periodFrom = get line containing  @periodText => get words before \"-\" => take last words 1 => get date \"MM/d/yyyy\"\n$periodTo = get line containing  @periodText => get words after \"-\" => take words 1 => get date \"MM/d/yyyy\"\n\ngo to page 1\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Transaction Description\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detilsright = get line containing @tranactionColumns => get words after \"Transaction Description\" => take words 1 => left => subtract 10\n@creditright = get line containing @tranactionColumns => get words after \"Transaction Description\" => take words 1 => right => add 8\n@debitright = get line containing @tranactionColumns => get words after \"Deposit\" => take words 1 => right => add 8\n@balanceright = get line containing @tranactionColumns =>  take last words 1 => right => add 20\n\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Date Transaction Description\" => top => get line above\n//$gotolastTransBottom = get last line containing \"Date Transaction Description\"\n@transtionBottom = get last line containing \"Ending Balance\" => top => get line above\n\n\ndelete all lines starting \"Date Transaction Description\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\ndelete all lines containing \"There were no transactions for this statement period.\"\ndelete all lines starting \"Statements can be presented electronically\"\ndelete all lines containing \"Withdrawals =\"\ndelete all lines containing \"Deposits =\"\ndelete all lines containing \"0 Dividends Paid YTD:\"\ndelete all lines containing \"1 Dividends Paid YTD:\"\ndelete all lines containing \"2 Dividends Paid YTD:\"\ndelete all lines containing \"3 Dividends Paid YTD:\"\ndelete all lines containing \"4 Dividends Paid YTD:\"\ndelete all lines containing \"5 Dividends Paid YTD:\"\ndelete all lines containing \"6 Dividends Paid YTD:\"\ndelete all lines containing \"7 Dividends Paid YTD:\"\ndelete all lines containing \"8 Dividends Paid YTD:\"\ndelete all lines containing \"9 Dividends Paid YTD:\"\ndelete all lines starting \"Member Number:\"\ndelete all lines starting \"Statement Period:\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"CHECKING (Continued)\"\ndelete all lines containing \"SAVINGS (Continued)\"\n\nignore header above 700\nignore footer below 40\n$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detilsright  @debitright  => describe table false  Details *#Credit\n//$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detilsright @creditright @debitright => describe table false  Details *#Credit *#Debit\n//$transactions = get multi page table @transtionTop @transtionBottom @dateleft @detilsright @creditright @debitright @balanceright => describe table false  Details *#Credit *#Debit #Balance\n\n\n','2025-05-29 06:49:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10688,'JuliusBar','$source = \"JuliusBar\"\n\n$periodBufferDays = 14\ngo to page 1\n$periodto = get line starting \"Account Statement as of\" => get words after \"Account Statement as of\" => take words 1 => get date \"d.M.yyyy\"\n\ngo to page 1\n$accountNumber = get line containing \"Account Account\" => get words after \"Account Account\" => take words 2 => get text\n$accountname = get line containing \"Account Account \" => get words after \"Account Account\" => take words 2 => get text\n\n$PeriodFromtext = get line starting \"Date Booking Text Value date\" => bottom => get line below\n$periodfrom = take words $PeriodFromtext 1 => take words 3 => get date \"d.M.yyyy\"\n\n$openingbalance = take last words $PeriodFromtext 1 => get decimal\n$closingbalance = get last line containing \"Balance\" => take last words 1 => get decimal\n\ngo to page 1\n\n$Date_left = get line containing \"Date Booking Text Value date\" => get words before \"Booking\" => left => subtract 5\n$Description_left = get line containing \"Date Booking Text Value date\" => get words after \"Date\" => left => subtract 3\n$Description_right = get line containing \"Date Booking Text Value date\" => get words after \"Booking Text\" => left => subtract 30\n$valuedate_right = get line containing \"Date Booking Text Value date\" => get words before \"Debit Credit\" => take last words 1 => right => add 10\n$Paidout_right = get line containing \"Date Booking Text Value date\" => get words before \"Credit\" => take last words 1 => right => add 10\n$Paidin_right = get line containing \"Date Booking Text Value date\" => get words before \"Balance\" => right => add 30\n$Balance_right = get line containing \"Date Booking Text Value date\" => get words after \"Credit\" => right => add 10\n\n$transactionsTop = get line containing \"Date Booking Text Value date\" => bottom => get line below\n$transactionsBottom = get line containing \"Remarks\" => top => get line above\n\ndelete all lines containing \"Date Booking Text Value date\"\ndelete all lines containing  \"Balance\"\ndelete all lines starting \"Carried forward\"\n\nignore header above 433\nignore footer below 40\n\ngo to page 1\n//$transactions = get multi page table $transactionsTop $transactionsBottom 115 170 420 486 586 695 780 => describe table false \"*Date[d.M.yyyy]\" Details - #Debit #Credit #Balance\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Description_left $Description_right $valuedate_right $Paidout_right $Paidin_right $Balance_right => describe table false \"*Date[d.M.yyyy]\" Details - #Debit #Credit #Balance','2025-05-29 06:49:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10701,'LibertyBank','$source = \"LibertyBank\"\n\ndelete tiny words\ndelete rotated words\ndelete white words\n\n@TEXTBOXBottom = get line containing \"Summary of Accounts\" => top\n// Get account name\n$accountName = get text in box 700 @TEXTBOXBottom 0 348 => take words 3 => get text\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => get words before \"$\" => take last words 1 => get text\ngo to page 1\ndelete all lines ending \"Ending Balance\"\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\n@TEXTBOXBottom1 = get line containing \"Ending Balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom1 0 350\n\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\n\nremove page 2\ngo to page 1\n// Get start & end of Deposits table\n@DepositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\n@DepositsBottom = get line ending \"Electronic Credits\" => if not found then blank => top => get line above\n\n// Get start & end of credits table\n@creditsTop = get line starting \"Electronic Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line ending \"Other Credits\" => if not found then blank => top => get line above\n\n@creditsTop1 = get line starting \"Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom1 = get line ending \"Debits\" => if not found then blank => top => get line above\n\n\nignore header above 736\ndelete all lines starting \"Date Description\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Electronic Credits\"\n//delete all lines containing \"RETURNED STOP PAY ITEM\"\n\n\n@Deposits = get multi page table @DepositsTop @DepositsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@credits = get multi page table @creditsTop @creditsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@creditother = get multi page table @creditsTop1 @creditsBottom1 35 90 510 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n\ngo to page 1\n@chequeTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ndelete all lines starting \"* Indicates skipped check number\"\ndelete all lines starting \"Check Nbr Date Amount\"\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 55 115 190 292 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n//@chequeMiddle = get multi page table @chequeTop @chequebottom 210 273 335 410 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 348 406 480 580 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\n\ngo to page 1\n// Get start & end of debits table\n@debitsTop = get line starting \"Electronic Debits\" => bottom => get line below\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\ndelete all lines containing \"Other Debits\"\n\n@dltop = get line starting \"Checks Cleared\" => top\n@dltbot = get line containing \"check number\" => bottom\n$dlttopbot = delete text in box @dltop @dlttopbot page.left page.right => get text\n@debits = get multi page table @debitsTop @debitsBottom 35 90 515 580 => describe table false \"Date[M/d/yyyy]\" Details *#Debit\n\n// Get start & end of cheques table\n\n$transactions = combine described tables @Deposits @credits @creditother @debits @chequeLeft @chequeRight','2025-06-25 11:51:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10702,'Eposnow_Bank','$source = \"Eposnow_Bank\"\n\n$features = \"NO_TRANSACTION_YEAR\"\n\n//get account name\n@accntbottom = get line starting \"Sort Code:\" => top\n$accountName = get text in box page.top @accntbottom page.left page.middleX => take words 3 => get text\n\n//account number\n$accountNumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get decimal\n\n\n//get statement_period\n@period = get line containing \"Statement Period:\" => get words after \"Statement Period:\" => take words 7\n$periodfrom = take words @period 3 => get date \"d MMM yyyy\"\n\n$periodTo = take last words @period 3 => get date \"d MMM yyyy\"\n\n//get opening_balance\n$openingbalance = get line containing \"Opening Balance:\" => get words after \"Opening Balance:\" => take words 1 => get decimal\n\n//get closing_balance\n$closingbalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" => take words 1 => get decimal\n\n\n//Get start of table\n@transactionsTop = get line containing \"Date Type Description\" => bottom => get line below\n\n\n//get upto last transaction\n@transactionsBottom = get last line containing \"Totals\" => top => get line above\n\n//ignore header\nget line containing \"Date Type Description\" => bottom => ignore header above\n\n\n//ignore footer\nignore footer below 67\n\n//read transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 65 135 300 490 600 => describe table false \"*Date[d MMM]\" TransactionType Details #Credit #Balance','2025-06-25 11:51:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10703,'Me_Bank_Interim_statement','$source = \"Me_Bank_Interim_statement\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 30\n\n// Get account name\n$accountName = get line containing \"Account Holders:\" => get words after \"Account Holders:\" => take words 2 => get text\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 3 => get text\n\n//Get dates\n$periodFrom = get line containing \"Transaction Period\" => bottom => get line below => get words before \"-\" => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"Transaction Period\" => bottom => get line below => get words after \"-\" => get date \"dd/MM/yyyy\"\n\n//Get TextInBOx\n\n@TEXTBOXTop = get line containing \"Date Description Debits and credits\" => bottom\n@TEXTBOXBottom = get line containing \"Report generated\" => bottom\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 480 page.right\n$openingBalance = \"0\"\n//take words $TEXTBOX 1 => get decimal\n\n@TEXTBOXTop1 = get last line containing \"Date Description Debits and credits\" => bottom\n@TEXTBOXBottom1 = get last line starting \"Report generated\" => top\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 480 page.right\n$closingBalance = take last words $TEXTBOX1 1 => get decimal\n\ngo to page 1\n@transactionstop = get line starting \"Date Description Debits and credits\" => bottom => get line below\n@transactionsbottom = get last line containing \"Report generated\" => top => get line above\ndelete all lines containing \"Date Description Debits and credits\"\ndelete all lines containing \"Report generated\"\nignore header above 720\nignore footer below 100\n$transactions = get multi page table @transactionstop @transactionsbottom 17 80 381 480 550 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Balance','2025-06-25 11:51:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10704,'MeDirect_Bank','$source = \"MeDirect_Bank\"\n$features = \"REVERSE_ORDER\"\n$periodBufferDays = 45\nset negative marker \"‐\"\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\n\n// Get account name\n\n$accountName = get line containing \"ACCOUNT NAME\" => get words after \"ACCOUNT NAME\" => take words 1 => get text\n\n// Opening and Closing Balance\n\n$closingbalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" =>  take words 1 => get decimal\n\n$openingbalance = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" =>  take words 1 => get decimal\n\n\n//Get PeriodInBOx\ngo to page 1\n@PeriodToTop = get line containing \"DATE VALUE DATE DESCRIPTION AMOUNT BALANCE\" => bottom\n@PeriodTOBottom = get line starting \"MeDirect Bank ﴾Malta﴿ plc, company registration\" => top\n$PeriodToBox = get text in box @PeriodToTop @PeriodTOBottom page.left 90\n$PeriodTo = take words $PeriodToBox 1 => take words 1 => get date \"dd MM yyyy\"\n\n\n\n@PeriodFromTop = get last line containing \"DATE VALUE DATE DESCRIPTION AMOUNT BALANCE\" => bottom\n@PeriodFromBottom = get last line starting \"MeDirect Bank ﴾Malta﴿ plc, company registration\" => top\n$PeriodFromBox = get text in box @PeriodFromTop @PeriodFromBottom page.left 90\n$PeriodFrom = take last words $PeriodFromBox 1 => get date \"dd MM yyyy\"\n\ngo to page 1\n@transactionstop = get line starting \"DATE VALUE DATE DESCRIPTION AMOUNT BALANCE\" => bottom => get line below\n\n@transactionsbottom = get last line containing \"MeDirect Bank ﴾Malta﴿ plc, company\" => top => get line above\n\n// stripping unwanted records from txns\n\ndelete all lines containing \"DATE VALUE DATE DESCRIPTION\"\ndelete all lines containing \"MeDirect Bank ﴾Malta﴿ plc, company\"\n\nignore header above 710\nignore footer below 70\n\n$transactions = get multi page table @transactionstop @transactionsbottom 25 150 435 500 => describe table false \"Date[dd MM yyyy]\" Details *#Credit','2025-06-25 11:51:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10705,'Barclays_One_wealth','$source = \"Barclays_One_wealth\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n// Get account name and number\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n$accountName = get line starting \"Holder\" => get words after \"Holder\" => get text\n\n// Get opening and closing balances\n$closingBalance = get line starting \"Date Description Type Money In Money Out Balance\" => bottom => get line below => get words after \"Closing balance\" => take words 1 => get decimal\n//$openingBalance = get last line containing \"Opening balance\" => take last words 1 => get decimal\n\ngo to page 1\n// Get period from and Period to\n$periodFrom = get line starting \"Period\" => get words after \"Period -\" => take words 3 => take words 1 => get date \"dd-MMM-yyyy\"\n$periodTo = get line starting \"Period\" => get words after \"Period -\" => take words 3 => take last words 1 => get date \"dd-MMM-yyyy\"\n\n// Get start of table\n@transactionsTop = get line starting \"Date Description Type Money In Money Out Balance\" => bottom => get line below\n\n@detailright = get line containing \"Date Description Type Money In Money Out Balance\" => get words after \"Description\" => take words 1 => left => subtract 3\n\n// Get end of table\n@transactionsBottom = get last line containing \"Opening balance\" => top => get line above\n\ndelete all lines containing \"Closing balance\"\ndelete all lines containing \"Opening balance\"\ndelete all lines containing \"Date Description Type Money In Money Out Balance\"\ndelete all lines starting \"https://uksecure.barclayswealth.com\"\n\n// Discard page footer\nignore header above 795\nignore footer below 25\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 72 @detailright 425 530 590 => describe table false \"*Date[dd-MMM-yyyy]\" Details TransactionType #Credit #Balance','2025-06-25 11:51:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10706,'BAC_Bank','$source = \"BAC_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n@TEXTBOXBottom = get line containing \"DETALLE DE CUENTA\" => top\n$accountName = get text in box page.top @TEXTBOXBottom page.left 220 => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"DETALLE DE CUENTA\" => bottom => get line below => take words 1 => get text\n\ngo to page 1\n$periodFrom = get line containing \"Saldo Anterior\" => bottom => get line below => take words 1 => get date \"MMM/dd\"\n\ngo to page 1\n// Get Period From\n@periodToBottom = get line starting \"DETALLE\" => top\n$periodTo = get text in box page.top @periodToBottom page.middleX page.right => get date \"MMM/dd/yy\"\n\ngo to page 1\n// Get Opening balance\n$openingBalance = get line containing \"Saldo Anterior\" => get words after \"Anterior\" => take last words 1 => get decimal\n\n// Get closing Balance\n$closingBalance = get last line containing \"Saldo al Corte\" => get words after \"Saldo al Corte\" => take last words 1 => get decimal\n\ngo to page 1\n// Get table start and end of table\n@transactionstop = get line containing \"Saldo Anterior\" => bottom => get line below\n@transactionsbottom = get last line containing \"Saldo al Corte\" => top => get line above\n\nget line starting \"Saldo Anterior\" => top => ignore header above\ndelete all lines starting \"Saldo Anterior\"\nignore footer below 60\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 90 150 350 430 500 580 => describe table false \"*Date[MMM/dd]\" TransactionType Details #Debit #Credit #Balance','2025-06-25 11:51:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10707,'Bank_of_China','$source = \"Bank_of_China\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Account\" => get decimal\n\n@TEXTBOXBottom = get line starting \"Bank of China (UK) Limited\" => top\n// Get account name\n$accountName = get text in box page.top @TEXTBOXBottom 0 350 => take words 3 => get text\n\n@TEXTBOXTop = get last line containing \"Date Date\" => bottom => get line below => bottom\n@TEXTBOXBottom1 = get line containing \"Closing Balance\" => top\n\n//Get Period To\n$periodTo = get text in box @TEXTBOXTop @TEXTBOXBottom1 page.left 60 => take last words 1 => get date \"dd/MM/yy\"\n\ngo to page 1\n// Get Period From\n$periodFrom = get line starting \"Date Date\" => bottom => get line below => bottom => get line below => bottom => get line below => take words 1 => get date \"dd/MM/yy\"\n\n// Get Opening balance\n$openingBalance = get line starting \"Date Date\" => bottom => get line below => bottom => get line below => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n// Get closing Balance\n$closingBalance = get line starting \"Currency Balance\" => bottom => get line below => bottom => get line below => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n// Get table start and end of table\n@transactionstop = get line starting \"Date Date\" => bottom => get line below => bottom => get line below\n@transactionsbottom = get last line containing \"Closing Balance\" => top => get line above\n\nignore footer below 100\nignore header above 675\n\ndelete all lines containing \"Balance Carried\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom 0 60 110 275 360 460 560 => describe table false \"*Date[dd/MM/yy]\" - Details #Debit #Credit #Balance','2025-06-25 11:51:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10708,'CaterAllen_Ascending','$source = \"CaterAllen_Ascending\"\n\ngo to page 1\n$accountName = get line starting \"name:\" => top => get line above => get words after \"Customer\"  => take words 2 => get text\n$accountNumber = get line containing \"Account no\" => get words after \"Account no\" => take words 1 => get text\n\n$periodFrom = get line containing \"Date range\" => get words after \"Date range\" => take words 1 => get date \"dd MM yyyy\"\n\n$periodTo = get line containing \"Date range\" => get words after \"Date range\"  => take last words 1 => get date \"dd MM yyyy\"\n\ngo to page 1\n// Get opening and closing balances\n$OpeningBalanceText = get line starting \"Opening balance\" => get words after \"Opening balance\" => take last words 1\n$openingBalance = get decimal $OpeningBalanceText\n$closingBalanceText = get line containing \"Closing balance\" => get words after \"Closing balance\" =>  take last words 1\n$closingBalance = get decimal $closingBalanceText\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Transaction Value date\" => bottom => get line below\n\n// Discard header and footer\ndelete all lines starting \"Opening balance\"\ndelete all lines starting \"Closing balance\"\ndelete all lines starting \"Transaction Value date\"\ndelete all lines containing \"Particulars\"\n\ngo to last page\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 80 136 330 400 470 570 => describe table false \"Date[dd MM yyyy]\" - Details #Debit #Credit *#Balance','2025-06-25 11:51:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10709,'F&M_BankOfCalifornia','$source = \"F&M_BankOfCalifornia\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name\n$accountName = get text in box 620 590 page.left page.middleX => take words 3 => get text\n\n// Get dates\n$periodFrom = get line containing \"thru\" => get words before \"thru\" => take last words 1 => get date \"M/d/yy\"\n$periodTo = get line containing \"thru\" => get words after \"thru\" => take words 1 => get date \"M/d/yy\"\n\n// Get account number\n$accountNumber = get line starting \"ACCOUNT DATE TRANSACTIONS DEBITS\" => bottom => get line below => take words 1 => get text\n\n// Get balances>\n@balancetxt = get line starting \"ACCOUNT DATE TRANSACTIONS DEBITS\" => top => get line above => top => get line above\n$openingBalance = skip words @balancetxt 1 => take words 1 => get decimal\n$closingBalance = take last words @balancetxt 1 => get decimal\n\n// Get top of the transactions table\n@transactionsTop = get line starting \"ACCOUNT DATE TRANSACTIONS DEBITS\" => bottom => get line below\n\nignore header above 685\ndelete all lines starting \"ACCOUNT DATE TRANSACTIONS DEBITS\"\n\n@transactionsBottom = get last line containing \"Average Daily Balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 100 150 130 370 450 530 620 => describe table false \"Date[dd-MMM]\" - Details *Debit *#Credit #Balance','2025-06-25 11:51:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10710,'BlueVine_Bank','$source = \"BlueVine_Bank\"\n$periodBufferDays = 31\n\n//Get Account\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n$accountNumber = get line starting \"Account Number:\" => bottom => get line below => take words 1 =>  get text\n\n//Get Balances\n//$openingBalance = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Ending balance on\" => get words after \"Ending balance on\" => take last words 1 => get decimal\n\ngo to page 1\n//Get Periods\n//$periodFrom = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take words 1 => get date \"MM/dd/yyyy\"\n\n@periodTop = get line starting \"Beginning Balance on\" => top\n@periodRight = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => right => add 70\n@OpeningLeft = get line starting \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => right => add 50\n@periodBottom = get line starting \"Deposits/credits\" => top\n$periodFrom = get text in box  @periodTop @periodBottom 0 @periodRight => get words after \"Beginning Balance on\" => take words 1 => get date \"MM/dd/yyyy\"\n//get words after \"Beginning Balance on\" => take words 1 => get date \"MM/dd/yyyy\"\n\n$openingBalance = get text in box @periodTop @periodBottom @OpeningLeft page.right => take last words 1 => get decimal\n$periodTo = get line starting \"Ending balance on\" => get words after \"Ending balance on\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 15\n@detailsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 6\n@amountleft  =  get line containing @tranactionColumns => take last words 1 => left => subtract 20\n@amountright =   get line containing @tranactionColumns => take last words 1 => right => add 15\n\ngo to page 1\n// Read the transactions\n@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\n$gotolastTransBottom = get last line containing \"banking.support@bluevine.com\"\n//@transactionsbottom = get last line containing \"banking.support@bluevine.com\" => top => get line above\n@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\n@ft_bottom = get line starting \"The ending balance\" => if not found then blank => bottom\n@del_ft = delete text in box @ft_bottom page.bottom 0 page.right => get text\n\ngo to page 1\n@ft_bottom1 = get line starting \"In case of errors\" => if not found then blank => bottom\n@del_ft1 = delete text in box @ft_bottom1 page.bottom 0 page.right => get text\n\ngo to page 1\n@ft_bottom2 = get line containing \"banking.support@bluevine.com\" => if not found then blank => bottom\n@del_ft2 = delete text in box @ft_bottom2 page.bottom 0 page.right => get text\n\ngo to page 1\n@ft_bottom3 = get line starting \"Banking services provided by\" => if not found then blank => bottom\n@del_ft3 = delete text in box @ft_bottom3 page.bottom 0 page.right => get text\n\ngo to page 1\n@ft_bottom4 = get line starting \"Bluevine Business Checking\" => if not found then blank => bottom\n@del_ft4 = delete text in box @ft_bottom4 page.bottom 0 page.right => get text\n\ngo to page 1\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"The ending balance appearing\"\ndelete all lines starting \"In case of errors\"\ndelete all lines containing \"banking.support@bluevine.com\"\ndelete all lines starting \"Bluevine Business Checking\"\n\nignore header above 780\nignore footer below 60\n\n$transactions = get multi page table @transactionsTop @transactionsbottom @dateleft @detailsleft @amountleft @amountright => describe table false \"Date[MM/dd/yy]\" Details  *#Credit','2026-01-07 06:33:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10711,'118118money_CreditCard','$source = \"118118money_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\nset negative marker \"CR\"\n\n//Get Account\n$accountNumber = get line starting \"Account number\" => get words after \"ending in\" => take words 1 =>  get text\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n\n//Get Balances\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 =>  get decimal\n$closingBalance = get text in box page.top 0 0 320 => get words after \"New Balance\" => take words 1 => get decimal\n\n//Get Periods\ngo to page 1\n$periodFrom = get text in box page.top 0 0 320 => get words after \"Statement period\" =>  get words before \"-\" => take words 3 => get date \"d MMMM yyyy\"\n$periodTo = get text in box page.top 0 0 320 => get words after \"Statement period\" =>  get words after \"-\" => take words 3 => get date \"d MMMM yyyy\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line containing \"date Description Amount\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 15\n@detailsleft = get line containing @tranactionColumns => get words after \"date\" => take words 1 => left => subtract 8\n@amountleft  =  get line containing @tranactionColumns => take last words 1 => left => subtract 20\n@amountright =   get line containing @tranactionColumns => take last words 1 => right => add 70\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line containing \"date Description Amount\" => bottom => get line below\n$gotolastTransBottom = get last line containing \"date Description Amount\"\n@transactionsbottom = get last line starting \"Transaction total\" => top => get line above\n//@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\ndelete all lines starting \"Transaction\"\ndelete all lines containing \"date Description Amount\"\ndelete all lines starting \"Transaction total\"\ndelete all lines starting \"YOUR TRANSACTIONS\"\ndelete all lines containing \"(CONTINUED)\"\ndelete all lines starting \"Account number ending in\"\nignore header above 745\nignore footer below 50\n\n$transactions = get multi page table @transtionTop @transactionsbottom @dateleft @detailsleft @amountleft @amountright => describe table false \"*Date[dd/MM]\" Details  #Credit','2025-06-25 11:51:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10712,'ANB_Bank','$source = \"ANB_Bank\"\n\n$accountNumberText = get line starting \"Account Type Account Number\" => bottom => get line below\n$accountNumber = take last words $accountNumberText 2 => take words 1 => get text\n// Get Account Name\n$accountName = get text in box 663 653 50 page.middleX => take words 3 => get text\n\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/d/yyyy\"\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => take words 1 => get date \"MM/d/yyyy\"\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n//Get start & end of Debit table\ngo to page 1\n$CreditsTop = get line ending \"Credits\" => if not found then blank => bottom => get line below\n$CreditsBottom = get last line ending \"Credits\" => bottom => get break below => get line at\n\n//Get start & end of eDebit table\ngo to page 1\n$eDebitsTop = get line ending \"Electronic Debits\" => if not found then blank => bottom => get line below\n$eDebitsBottom = get last line ending \"Electronic Debits\" => bottom => get break below => get line at\n\n@eDebitsTopD = get line containing \"Electronic Debits\" => top\n@eDebitsBottomD = get line containing \"Electronic Debits\" => if not found then blank => bottom\ndelete text in box @eDebitsTopD @eDebitsBottomD page.left page.right\n\n\n//Get start & end of Debit table\ngo to page 1\n$DebitsTop = get line ending \"Debits\" => if not found then blank => bottom => get line below\n$DebitsBottom = get last line ending \"Debits\" => bottom => get break below => get line at\n\n//Get start & end of Debit table\ngo to page 1\n$cDebitsTop = get line ending \"Other Debits (continued)\" => if not found then blank => bottom => get line below\n$cDebitsBottom = get last line ending \"Other Debits (continued)\" => bottom => get break below => get line at\n\n//Get start & end of Credit table\ngo to page 1\n$DepositsTop = get line ending \"Deposits\" => if not found then blank => bottom => get line below\n$DepositsBottom = get last line ending \"Deposits\" => bottom => get break below => get line at\ngo to page 1\n@ChecksTop = get line containing \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\n@ChecksBottom = get line starting \"* Indicates skipped check\" => if not found then blank => top => get line above\n\ngo to page 1\n//remove page 2\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Savings Account\"\ndelete all lines containing \"Deposits (continued)\"\ndelete all lines containing \"Electronic Credits\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Electronic Debits\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Check Nbr Date\"\ndelete all lines containing \"Checks Cleared\"\ndelete all lines starting \"Start Up\"\n\nignore header above 688\n\n$deposits = get multi page table $DepositsTop $DepositsBottom 35 95 530 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit\n$debits = get multi page table $DebitsTop $DebitsBottom 35 95 530 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit\n$cdebits = get multi page table $cDebitsTop $cDebitsBottom 35 95 530 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit\n$edebits = get multi page table $eDebitsTop $eDebitsBottom 35 95 530 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit\n$Credits = get multi page table $CreditsTop $CreditsBottom 35 95 530 580 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit\n$ChecksL = get multi page table @ChecksTop @ChecksBottom 40 90 165 210 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n$ChecksM = get multi page table @ChecksTop @ChecksBottom  245 274 325 394 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n$ChecksR = get multi page table @ChecksTop @ChecksBottom  420 458 510 578 => describe table false ChequeNumber \"Date[MM/d/yyyy]\" *#Debit\n\n$transactions = combine described tables $deposits $debits $Credits $edebits $cdebits $ChecksL','2025-06-25 11:51:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10713,'StDominic_CU','$source = \"StDominic_CU\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ngo to page 1\n$accountTop = get line starting \" Opening Balance\" => top\n$accountbottom = get line starting \" Closing Balance\" => bottom\n$accountDetails = get text in box $accountTop $accountbottom 540 page.right\n\n$openingBalance = take words $accountDetails  1 => get decimal\n$closingBalance = take last words $accountDetails  1 => get decimal\n\n$periodtop = get line starting \"Account Name\" => top => get line above\n$periodfrom = take words $periodtop 2 => get date \"d MMM\"\n$periodto = take last words $periodtop 3 => get date \"d MMM yyyy\"\n\n$perioddata = get line starting \"Account Name\" => top => get line below\n$accountName = take words $perioddata 2 => get text\n$accountNumber = take last words $perioddata 1 => get text\n\ngo to page 1\n$Date_left = get line containing \"Date Description Paid Out\" => get words before \"Description\" => left => subtract 10\n$Description_left = get line containing \"Date Description Paid Out\" => get words after \"Date\" => left => subtract 5\n$Description_right = get line containing \"Date Description Paid Out\" => get words after \"Description\" => left => subtract 55\n$Paidout_right = get line containing \"Date Description Paid Out\" => get words after \"Paid Out\" => left => subtract 55\n$Paidin_right = get line containing \"Date Description Paid Out\" => get words before \"Balance\" => right => add 30\n$Balance_right = get line containing \"Date Description Paid Out\" => get words after \"Paid in\" => right\n\n@transactionTop = get line containing \"Date Description Paid Out\" => bottom =>  get line below\n@transactionBottom = get last line starting \"Closing Balance\" => top => get line above\n\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Date Description Paid Out\"\nignore header above 490\nignore footer below 62\n\n//$transactions = get multi page table @transactionTop @transactionBottom 20 100 270 320 420 575 => describe table false \"Date[d MMM yy]\" Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionTop @transactionBottom $Date_left $Description_left $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"Date[d MMM yy]\" Details #Debit #Credit *#Balance','2025-06-25 11:52:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10714,'ValleyNationalBank','$source = \"ValleyNationalBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n@DateLeft = get line containing \"Date Description\" => get words before \"Description\" => take last words 1 => left => subtract 2\r\n@DescLeft = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 2\r\n@BalanceRight = get line containing \"Date Description\" => get words after \"Date Description\" => take last words 1 => right => add 5\r\n\r\n$deleteleftpanel = delete text in box on every page page.top 0 0 @DateLeft => get text\r\n$deleterightpanel = delete text in box on every page page.top 0 575 @BalanceRight => get text\r\n\r\ngo to page 1\r\n@Accountstop = get line containing \"THE PERIOD:\" => top => get line above => top\r\n\r\n@Datestop = get line containing \"THE PERIOD:\" => top\r\n@Datesbottom = get line containing \"THE PERIOD:\" => bottom\r\n@Dates = get text in box @Datestop @Datesbottom @DateLeft page.middleX\r\n\r\n$periodFrom = get words after @Dates \"PERIOD:\" => take words 1 => get date \"M d yy\"\r\n$periodTo = get words after @Dates \"PERIOD:\" => skip words 2 => take words 1 => get date \"M d yy\"\r\n\r\n$accountNumber = get text in box @Accountstop @Datestop 20 390 => take last words 1 => get text\r\n$accountName = get text in box @Accountstop @Datestop 20 390 => take last words 1 => get text\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Description\" => bottom => get line below\r\n\r\n$openingBalance = get line containing \"Date Description\" => bottom => get line below => get words after \"Beginning Balance\" => get decimal\r\ndelete all lines starting \"Beginning Balance\"\r\n\r\n@transactionsBottom = get last line starting \"Ending Balance\" => top => get line above\r\n$closingBalance = get last line starting \"Ending Balance\" => get words after \"Ending Balance\" => get decimal\r\n\r\nignore header above 695\r\nignore footer below 50\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines containing \"Have Questions\"\r\n\r\n//Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @DateLeft @DescLeft 335 480 @BalanceRight => describe table false \"*Date[M d]\" Details #Credit #Balance','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10715,'ANZ_Transactions_Reverse','$source = \"ANZ_Transactions_Reverse\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n$periodBufferDays = 28\n\n// Get Account Name\n$accountName = get text in box page.top page.middleY page.left page.middleX => skip words 1 => take words 4 => get text\n\n// Get Account Number\n@accoutBottom =  get line starting \"Date Type Details\" => top\n@accoutRight =  get line starting \"Date Type Details\" => take words 3 => take last words 1 => left\n$accountNumber = get text in box page.top @accoutBottom  0  @accoutRight  => take last words 1 => get text\n\ngo to page 1\n//Get Periods\n$periodTo = get line containing \"Transactions between\" => get words after \"and\" => take words 3 => get date \"dd MMM yyyy\"\n$periodFrom = get line containing \"Transactions between\" => get words before \"and\" => take last words 3 => get date \"dd MMM yyyy\"\n\n//OpeningBalance\n$openingBalance = get  line starting \"Date Type Details\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\nignore footer below 50\ndelete all lines containing \"Page\"\ndelete all lines starting \"Copyright\"\n\nget last line starting \"Date Type Details\" => bottom\n//Closing Balance\n$closingBalance = get line above 0 => top => get line above =>  take last words 1 => get decimal\n\ngo to page 1\n// Get Transactions\n@transactionsTop = get line  starting \"Date Type Details\" => if not found then blank => bottom => get line below\n$gotolastpage = get last line starting \"Date Type Details\" => bottom\n@transactionsBottom = get line above 0\n\ndelete all lines starting \"Date Type Details\"\nignore footer below 50\nignore header above 785\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 33 93 190 400 450 514 570 => describe table false \"*Date[dd MMM yyyy]\" TransactionType Details #Credit #Debit #Balance\n','2025-06-25 11:52:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10716,'JPMorgan_Online','$source = \"JPMorgan_Online\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ndelete text in box on every page page.top page.bottom 750 page.right\n\n// Get account name and account Number\n$accountName = get line containing \"Primary Account:\" => get words after \"Primary Account:\" => take words 1 => get text\n$accountNumber = get line containing \"Primary Account:\" => get words after \"Primary Account:\" => take words 1 => get text\n\n@statementPeriod = get line containing \"For the Period\" => get words after \"For the Period\" => take words 3\n$periodFrom = take words @statementPeriod 1 => get date \"M/d/yy\"\n$periodTo = take last words @statementPeriod 1 => get date \"M/d/yy\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n@summaryBottom = get last line containing \"Ending Balance\" => bottom\ndelete text in box page.top @summaryBottom page.left page.right\n\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"You can view images of the checks\"\n\nignore header above 425\nignore footer below 16\n\ngo to page 1\n// Get Deposits&Credits table\n@transactionsTopCredit = get line starting \"Deposits & Credits\" => if not found then blank => bottom => get line below\n@transactionsBottomCredit = get line starting \"Total Deposits & Credits\" => if not found then blank => top => get line above\ndelete all lines starting \"Deposits & Credits\"\n$transactionsCredit = get multi page table @transactionsTopCredit @transactionsBottomCredit 20 60 660 750 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n// Get Check table (some files have 1 table having width from pageleft to pageright and some files have 3 table in same horizontal position )\n\n//$CheckTop = get line starting \"Number Paid Amount\" => if not found then blank => bottom => get line below\n$CheckTop = get line \"Number Paid Amount\" => if not found then blank => bottom => get line below\ngo to page 1\n$CheckTop1 = get line \"Number Paid Amount Number Paid Amount Number Paid Amount\" => if not found then blank => bottom => get line below\ngo to page 1\n$CheckBottom = get line starting \"Total Checks Paid\" => if not found then blank => top => get line above\ndelete all lines starting \"Checks Paid\"\ndelete all lines starting \"Check Date\"\ndelete all lines starting \"Number Paid Amount\"\n\n$transactionsCheck = get multi page table $CheckTop $CheckBottom 20 60 660 750 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n\n$transactionsCheck1 = get multi page table $CheckTop1 $CheckBottom 20 60 140 250 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n$transactionsCheck2 = get multi page table $CheckTop1 $CheckBottom 250 310 400 490 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n$transactionsCheck3 = get multi page table $CheckTop1 $CheckBottom 490 550 650 750 => describe table false ChequeNumber \"*Date[MM/dd]\" #Debit\n\ngo to page 1\n// Get ATM & Debit Card Transactions table\n@ATMandDebitTop = get line starting \"ATM & Debit Card Transactions\" => if not found then blank => bottom => get line below\n@ATMandDebitBottom = get line starting \"Total ATM & Debit Card Transactions\" => if not found then blank => top => get line above\ndelete all lines starting \"ATM & Debit Card Transactions\"\n$transactionsATMandDebit = get multi page table @ATMandDebitTop @ATMandDebitBottom 20 60 660 750 => describe table false \"*Date[MM/dd]\" Details #Debit\n\ngo to page 1\n// Get payment&transfer Transactions table\n@paymentandTransferTop = get line starting \"Payments & Transfers\" => if not found then blank => bottom => get line below\n@paymentandTransferBottom = get line starting \"Total Payments & Transfers\" => if not found then blank => top => get line above\ndelete all lines starting \"Payments & Transfers\"\n$transactionsPaymentandtransfer = get multi page table @paymentandTransferTop @paymentandTransferBottom 20 60 660 750 => describe table false \"*Date[MM/dd]\" Details #Debit\n\ngo to page 1\n// Get Fees&Charges Transactions table\n@FeesandChargesTop = get line starting \"Fees, Charges & Other Withdrawals\" => if not found then blank => bottom => get line below\n@FeesandChargesBottom = get line starting \"Total Fees, Charges & Other Withdrawals\" => if not found then blank => top => get line above\ndelete all lines starting \"Fees, Charges & Other Withdrawals\"\n@transactionsFeesandCharges = get multi page table @FeesandChargesTop @FeesandChargesBottom 20 60 660 750 => describe table false \"*Date[MM/dd]\" Details #Debit\n\n// combine the transactions\n$transactions = combine described tables $transactionsCredit $transactionsATMandDebit $transactionsPaymentandtransfer $transactionsCheck @transactionsFeesandCharges $transactionsCheck1 $transactionsCheck2 $transactionsCheck3','2025-10-29 06:18:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10717,'MCB_CreditCard','$source = \"MCB_CreditCard\"\n\n$periodBufferDays = 30\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n// Get account name\n$accountName = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get period to\n//$periodTo = get line starting \"Statement Date\" => bottom => get line below => take words 1 => get date \"d-MMM-yy\"\n\n$periodDate = get line starting \"Statement Date\" => bottom => get line below\n$periodTo = take words $periodDate 1 => get date \"d-MMM-yy\"\n\n$openingBalance = take last words $periodDate 1 => get decimal\ngo to page 1\n$closingBalancetop = get last line containing \"Total Charges\" => top\n$closingBalancebot = get last line containing \"Monthly Rate\" => bottom\n$getclosing = get text in box $closingBalancetop $closingBalancebot 466 page.right\n$closingBalance = get words before $getclosing \"Monthly Rate\"  => take last words 1 => get decimal\n\n// Get period from\ngo to page 1\n$periodFrom = get line starting \"Transactions for card number\" => bottom => get line below => take words 1 => get date \"MMM/dd\"\n\ngo to page 1\n@transactionTop = get line containing \"Transaction Date Reference No. Description\" => bottom =>  get line below\n@transactionBottom = get last line containing \"Total Charges Total Credits\" => top => get line above\n\ndelete all lines starting \"Transactions for card\"\ndelete all lines containing \"CONTINUE NEXT\"\nignore header above 587\nignore footer below 263\ndelete all lines containing \"18.00 PAB\"\ndelete all lines containing \"16 93 EUR\"\ndelete all lines containing \"16 93 EUR\"\ndelete all lines containing \"51 00 EUR\"\ndelete all lines containing \"138.71 PAB\"\ndelete all lines containing \"188.87 PAB\"\n\n$transactions = get multi page table @transactionTop @transactionBottom 70 110 203 480 530 600 => describe table false \"*Date[MMM/d]\" Details TransactionType #Credit #Debit','2025-06-25 11:52:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10718,'NorthernTrustBank','$source = \"NorthernTrustBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accountName = get line containing \"Account Number:\" => take last words 1 => get text\n$accountNumber = get line containing \"Account Number:\" => take last words 1 => get text\n$periodtext = get line containing \"Statement Period\" => top => get line below\n\n$periodFrom = take words $periodtext 1 => get date \"M/d/yy\"\n$periodTo = take last words $periodtext 1 => get date \"M/d/yy\"\n\n$openingBalance = get line starting \"Beginning Balance on\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance on\" => take last words 1 => get decimal\n\ngo to page 1\n// Get start & end of Deposits table\n@DepositsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@DepositsBottom = get line starting \"Checks Paid\" => if not found then blank => top => get line above\n\nignore header above 568\nignore footer below 30\ndelete all lines containing \"Date Description Amount\"\ndelete all lines containing \"Deposits and Credits\"\n@Deposits = get multi page table @DepositsTop @DepositsBottom 50 85 490 560 => describe table false \"Date[M-d]\" Details *#Credit\n\n\ngo to page 3\n// Get start & end of Other item table\n@otherTop = get line starting \"Other Items Paid\" => if not found then blank => bottom => get line below\n@otherBottom = get line containing \"Commercial Checking Daily\" => if not found then blank => top => get line above\n\ndelete all lines containing \"Other Items Paid\"\ndelete all lines containing \"check has been\"\n@otherdebits = get multi page table @otherTop @otherBottom 50 85 490 560 => describe table false \"Date[M-d]\" Details *#Debit\n\n// Get start & end of cheques table\ngo to page 1\n@chequeTop = get line containing \"Date Check No. Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get last line containing \"Indicates preceding check\" => if not found then blank => top => get line above\n\n\ndelete all lines containing \"Indicates preceding check\"\ndelete all lines containing \"Check No.\"\nignore header above 568\nignore footer below 30\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 52 80 190 270 => describe table false \"Date[M-d]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 330 400 485 560 => describe table false \"Date[M-d]\" ChequeNumber *#Debit\n\n$transactions = combine described tables @Deposits @chequeLeft @chequeRight @otherdebits','2025-06-25 11:52:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10719,'m_Bank','$source = \"m_Bank\"\n$features = \"REVERSE_ORDER SKIP_MISSING_CLOSING_BALANCE_CHECK\"\nset culture \"sv-SE\"\n$periodBufferDays = 30\n\n// Get account name\n$accountName = get line containing \"Lista operacji za okres\" => top => get line above => take words 2 => get text\n// Get account number\n$accountNumber = get line containing \"eKonto -\" => get words after \"eKonto -\" => take words 1 => get text\n\n//Get dates\n$periodFrom = get line containing \"Lista operacji za okres od\" => get words between \"Lista operacji za okres od\" \"do\" => get date \"yyyy-MM-dd\"\n$periodTo = get line containing \"Lista operacji za okres od\" => get words after \"do\" => get date \"yyyy-MM-dd\"\n\n//Get TextInBOx\n//@TEXTBOXTop = get line containing \"Data operacji Opis operacji Rachunek Kategoria Kwota\" => bottom\n//@TEXTBOXBottom = get line containing \"Strona\" => bottom\n//$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 495 page.right\n$openingBalance = \"0\"\n//take words $TEXTBOX 1 => get decimal\n\n//@TEXTBOXTop1 = get last line containing \"Data operacji Opis operacji Rachunek Kategoria Kwota\" => bottom\n//@TEXTBOXBottom1 = get last line starting \"Strona\" => top\n//$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 495 page.right\n//$closingBalance = take last words $TEXTBOX1 1 => get decimal\n$closingBalance = \"0\"\ngo to page 1\n@transactionstop = get line starting \"Data operacji Opis operacji Rachunek Kategoria Kwota\" => top => get line below\n@transactionsbottom = get last line containing \"Strona\" => top => get line above\ndelete all lines containing \"Data operacji Opis operacji Rachunek\"\ndelete all lines containing \"Strona\"\nignore header above 750\nignore footer below 38\n$transactions = get multi page table @transactionstop @transactionsbottom 40 100 360 430 490 560 => describe table false \"*Date[yyyy-MM-dd]\" Details - TransactionType #Credit','2025-06-25 11:52:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10720,'UBS_Current','$source = \"UBS_Current\"\n$features = \"REVERSE_ORDER\"\n\n//Get Account Number\n$accountNumber = get line containing \"IBAN\" => get words after \"IBAN\" => take last words 3 => take words 2 => get text\n\n// Get Account Name\n$accountName = get line containing \"IBAN\" => get words after \"IBAN\" => take last words 3 => take words 2 => get text\n\n//Get statement Period\n$periodFromtext = get line containing \"Account transactions\"  => bottom => get line below\n$periodFrom = take words $periodFromtext 1 => get date d.MM.yyyy\n$periodTo = take last words $periodFromtext 1 => get date d.MM.yyyy\n\n// Get opening & closing Balance\ngo to page 1\n$openingBalance = get line containing \"Closing balance\" => take last words 1 => get decimal\n$closingBalance  = get last line containing \"Opening balance\" => take last words 1 => get decimal\n\n//Get start & end of Transactions\ngo to page 1\n@TransactionTop = get line containing \"Closing balance\" => bottom => get line below\n@TransactionBottom = get line containing \"Opening balance\" => top => get line above\n\ndelete all lines starting \"Debit Interest\"\ndelete all lines starting \"Balance debit interest\"\ndelete all lines starting \"Total mandate fee\"\ndelete all lines starting \"Exchange rate in the\"\n\nignore header above 705\nignore footer below 29\n//Transactions\n$transactions = get multi page table @TransactionTop @TransactionBottom 35 92 258 322 476 560 => describe table false TransactionType Details #Debit[0\'000.00] #Credit[0\'000.00] *#Balance','2025-06-25 11:52:19',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10721,'Santander_International','$source = \"Santander_International\"\nset negative marker \"-\"\n\n@accountDetailstop = get line containing \"account number\" => top\n@accountDetailsbottom = get line containing \"account number\" => bottom => get line below => bottom\n@accountDetails = get text in box @accountDetailstop @accountDetailsbottom 0 300\n$accountNumber = get words after @accountDetails \"account number is\" => get text\n$accountName = get text in box page.top @accountDetailsbottom 0 300 => take words 2 => get text\n\ndelete text in box page.top page.bottom 0 page.middleX\n\n@Summarytop = get line containing \"Starting balance\" => top\n@Summarybottom = get line containing \"Account balance\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom 300 600\n$OpeningBalance = get words after @Summary \"Starting balance\" => get words between \"Starting balance\" \"Total paid\" => get decimal\n$closingBalance = get words after @Summary \"Account balance\" => get decimal\n\n// Dynamic coordinate\ngo to page 1\n@PostDateLeft = get line containing \"Post date Value date Details\" => get words before \"date Value\" => take last words 1 => left => subtract 20\n@ValueDateLeft = get line containing \"Post date Value date Details\" => get words after \"Post date\" => take words 1 => left => subtract 5\n@DescriptionLeft = get line containing \"Post date Value date Details\" => get words before \"Details\" => take last words 1 => right => add 2\n\n@transactionsTop = get line containing \"Post date Value date Details\" => bottom => get line below\n$periodFrom = get line containing \"STARTING BALANCE\" => get words before \"STARTING BALANCE\" => take words 3 => get date \"dMMMyy\"\n$periodTo = get line containing \"ACCOUNT BALANCE\" => get words before \"ACCOUNT BALANCE\" => take words 3 => get date \"dMMMyy\"\n@transactionsBottom = get last line containing \"ACCOUNT BALANCE\" => top => get line above\n\ndelete all lines containing \"STARTING BALANCE\"\ndelete all lines containing \"CARRIED FORWARD\"\ndelete all lines containing \"BROUGHT FORWARD\"\ndelete all lines containing \"Post date Value date Details\"\n\n// DELETED footer lines manually because footer top coordinate varies\ndelete all lines containing \"Please notify us immediately of any discrepancy\"\ndelete all lines containing \"Santander International is the trading\"\ndelete all lines containing \"Santander Financial Services plc is authorised\"\ndelete all lines containing \"Santander Financial Services plc’s Financial Services\"\ndelete all lines containing \"You can check this on the Financial Services Register\"\ndelete all lines containing \"regulated by the Isle of Man Financial Services Authority\"\ndelete all lines containing \"Financial Services Compensation Scheme established\"\ndelete all lines containing \"authorised by the Prudential Regulation Authority and regulated\"\ndelete all lines containing \"regulated by the Jersey Financial Services Commission\"\n\nignore header above 602\nignore footer below 89\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 65 125 180 340 412 485 600 => describe table false \"Date[dMMMyy]\" - Details #Debit #Credit *#Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom @PostDateLeft @ValueDateLeft @DescriptionLeft 340 412 485 600 => describe table false \"Date[dMMMyy]\" - Details #Debit #Credit *#Balance','2025-10-29 06:17:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10722,'TheFirstNationalBank_TrustCo','$source = \"TheFirstNationalBank_TrustCo\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get decimal\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 3 => get text\n$periodFrom = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Ending\" => get words after \"Ending\" => take last words 2 => take words 1 => get date \"M/dd/yy\"\n\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 2 => take last words 1 => get decimal\n@closing_left = get line containing \"Ending\" => get words after \"Ending\" =>  take words 1 => left\n@closing_top = get line containing \"Ending\" => top\n$closingBalance = get text in box @closing_top page.middleX @closing_left page.right => take words 2 => take last words 1 => get decimal\n\ngo to page 1\n\n// Get start & end of cheques table\n@chequeTop = get line containing \"Date Check No Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"indicates break in check number a sequence\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 48 85 152.4 201  => describe table false   \"*Date[M/dd]\" ChequeNumber #Debit\n@chequeCenter = get multi page table @chequeTop @chequebottom 220.2 280 322 395 => describe table false \"Date[M/dd]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 410 456 516 580  => describe table false \"Date[M/dd]\" ChequeNumber *#Debit\n\n// Remove Checks\ngo to page 1\n@RemovechequeTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom\n@Removechequebottom = get line containing \"indicates break in check number a sequence\" => if not found then blank => bottom\n@DELETECHECK = delete text in box @RemovechequeTop @Removechequebottom 0 page.right => get text\n\n@dailytrs_top =  get line starting \"Daily\" =>  if not found then blank => bottom\n@dailyBalInfo = delete text in box @dailytrs_top page.bottom 0 page.right => get text\n\n\ngo to page 1\ndelete all lines starting \"Date Check No Amount\"\ndelete all lines starting \"Checks in Check Number Order\"\ndelete all lines containing \"indicates a break in check number sequence\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"Account Number:\"\n\ngo to page 1\n@top =  get line starting \"Date Amount Activity Description\" =>  top => get line above  => top\n$deletesummery = delete text in box page.top @top 0 page.right => get text\n\ngo to page 1\n@tranactionColumns = get line starting \"Date Amount Activity Description\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 8\n@amountleft = get line containing @tranactionColumns => take words 2 =>  take last words 1 => left => subtract 5\n@detailsleft = get line containing @tranactionColumns => take words 3 => take last words 1 => left => subtract 3\n\ngo to page 1\n// Get start & end of credits transactions\n@transtionTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@transtionBottom = get line starting \"Withdrawals\" => if not found then blank => top => get line above\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Date Amount Activity Description\"\ndelete all lines starting \"Checks\"\n@credits = get multi page table @transtionTop @transtionBottom @dateleft @amountleft @detailsleft 450 => describe table false \"Date[M/dd]\" *#Credit Details\n\ngo to page 1\n// Get start & end of debits transactions\n@transtionTop1 = get line starting \"Withdrawals\" => if not found then blank => bottom => get line below\n@transtionBottom1 = get line starting \"Daily\" => if not found then blank => top => get line above\ndelete all lines starting \"Withdrawals\"\ndelete all lines starting \"Date Amount Activity Description\"\ndelete all lines starting \"Daily\"\ndelete all lines starting \"Date\"\n@debits = get multi page table @transtionTop1 @transtionBottom1 @dateleft @amountleft @detailsleft 450 => describe table false \"Date[M/dd]\" *#Debit Details\n\nignore header above 610\nignore footer below 50\n\n$transactions = combine described tables @credits @chequeLeft @chequeCenter @chequeRight @debits\n\n','2025-06-25 11:52:26',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10723,'AIB_Account_number','$source = \"AIB_Account_number\"\r\nset negative marker \"dr\"\r\n$periodBufferDays = 30\r\n\r\n// Get left panel area\r\n@panelTop = get line containing \"Account\" => Top\r\n@panelBottom = get line containing \"Date of\" => Top\r\n@panelWords = get text in box @panelTop @panelBottom 420 page.right\r\n\r\n// Get account name and number\r\n$accountNumber = take last words @panelWords 1 => get text\r\n$accountName = get words after @panelWords \"Account\" => take words 4 => get text\r\n\r\n$date_right = get line containing \"Date Details Debit\" => get words after \"Date\" => take words 1 => left\r\n$Detail_left = get line containing \"Date Details Debit\" => get words after \"Date\" => take words 1 => left\r\n$Detail_left = subtract $Detail_left 4\r\n\r\n// Get period from\r\n@firsttranTop = get line containing \"Date Details Debit\" => bottom\r\n@firsttranBottom = get line above 100 => top\r\n$periodFrom = get text in box @firsttranTop @firsttranBottom 25 $date_right => take words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening balances\r\n@openingBalanceTop = get text in box @firsttranTop @firsttranBottom 365 440 => take words 1 => top => add 1\r\n@openingBalanceBottom = get text in box @firsttranTop @firsttranBottom 365 440 => take words 1 => bottom => subtract 1\r\n$openingBalance = get text in box @openingBalanceTop @openingBalanceBottom 365 440 => get decimal\r\n\r\n// Delete some footer lines\r\ndelete all lines starting \"Interest on unauthorised\"\r\ndelete all lines containing \"per month\"\r\ndelete all lines starting \"See overleaf - important\"\r\n\r\n// Get period to\r\n@PeriodToTop = get last line starting \"Date Details Debit\"  => bottom\r\n@PeriodToBottom = get last line containing \"Overdrawn balances are marked\" => top => add 10\r\n$periodTo = get text in box @PeriodToTop @PeriodToBottom 25 $date_right => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date Details Debit\" => bottom => get line below\r\n\r\n$leftSummaryL = get line containing \"Date of\" => get words before \"of\" => take last words 1 => left => subtract 1\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Overdrawn balances are marked\" => top => get line above\r\n@LastPageFooter = get last line containing \"Overdrawn balances are marked\" => top => add 10\r\n\r\n//$deleteTop = get line containing \"Interest on unauthorised debit\" => top\r\n//$DeleteFooter = delete text in box $deleteTop 0 0 page.right => get text\r\n\r\n// deleted right side of summary panel on every page\r\ndelete text in box on every page page.top page.bottom $leftSummaryL 800\r\ndelete text in box on every page page.top page.bottom 441 800\r\n\r\ngo to page 1\r\n//Get Closing Balance\r\n@LastBalanceForwardText = get last line containing \"Date Details Debit\" => top\r\n\r\n$ClosingBalanceTop = get text in box @LastBalanceForwardText @LastPageFooter 365 440 => take last words 1 => top => add 1\r\n$ClosingBalanceBottom = get text in box @LastBalanceForwardText @LastPageFooter 365 440 => take last words 1 => bottom => subtract 1\r\n$closingBalance = get text in box $ClosingBalanceTop $ClosingBalanceBottom 365 440 => get decimal\r\ndelete text in box page.top page.bottom 430 page.right\r\n\r\n// Discard page header\r\nget last line starting \"Date Details Debit\" => bottom => ignore header above\r\n\r\ndelete all lines containing \"Surcharges-See Notice at Branch\"\r\n//delete all lines containing \"BALANCE FORWARD\"\r\n//delete all lines containing \"Interest Rate Lending\"\r\ndelete all lines starting \"Surcharges-See\"\r\ndelete all lines containing \"You can ask us\"\r\n\r\nignore footer below 75\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 $date_right $Detail_left 228 286 346 432 => describe table false \"*Date[d MMM yyyy]\" - Details *#Debit *#Credit #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10724,'FNBO_VisaCard','$source = \"FNBO_VisaCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\nset negative marker \"CR\"\r\ndelete all lines starting \"Debits\"\r\ndelete all lines starting \"Date Date Number\"\r\n//Note :This script supports two formats of FNBO card.\r\n@accountDetailstop = get line containing \"Account Number\" => top\r\n@accountDetailsbottom = get line containing \"Account Number\" => bottom\r\n@accountDetailsrleft = get line containing \"Account Number\" => get words after \"Account\" => take words 1 => right\r\n$accountNumber = get text in box @accountDetailstop @accountDetailsbottom @accountDetailsrleft page.right => get text\r\n$accountName = get text in box 882 850 page.left page.middleX => take words 4 => get text\r\n\r\n@Summarytop = get line containing \"Previous Balance\" => top\r\n@Summaryright = get line containing \"Past Due Amount\" => get words before \"Due\" => take last words 1 => left\r\n@Summarybottom = get line starting \"Statement Closing Date\" => bottom\r\n@Summary = get text in box @Summarytop @Summarybottom 0 @Summaryright\r\n$Summary = get text in box @Summarytop @Summarybottom 0 @Summaryright => get text\r\n\r\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => take last words 1 => get decimal\r\n$closingBalance = get words after @Summary \"New Balance\" => get words between \"New Balance\" \"Statement Closing Date\" => take last words 1 => get decimal\r\n//$periodTo = get words after @Summary \"Statement Closing Date\" => take last words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get words after @Summary \"Statement Closing Date\" => get words before \"Days\" => take last words 1 => get date \"MM/dd/yy\"\r\n\r\ndelete all lines starting \"The following items were transferred\"\r\ngo to page 1\r\n$periodFrom  = get line containing \"Credits (CR)\" => bottom => get line below => take words 1 => get date \"M-dd\"\r\n\r\n//Dynamics\r\n@Postdateleft = get line containing \"Credits (CR)\" => bottom => get line below => skip words 1 => take words 1 => left\r\n@Postdateleft = subtract @Postdateleft 10\r\n@Referenceleft = get line containing \"Credits (CR)\" => bottom => get line below => skip words 2 => take words 1 => left\r\n@Referenceleft = subtract @Referenceleft 10\r\n@CreditLeft = get line containing \"Credits (CR)\" => get words before \"(CR)\" => take last words 1 => left\r\n@CreditLeft = subtract @CreditLeft 10\r\n\r\n//Primary table Common for both the formats\r\ngo to page 1\r\n@transactionsTop = get line containing \"Credits (CR)\" => bottom => get line below\r\n\r\n//Secondary table Unique one format\r\n@FeeInteresttransactionsTop = get line starting \"Fees Charged Interest Charged\" => if not found then blank => bottom => get line below\r\n@FeetransactionsBottom = get line containing \"Total Fees for this\" => if not found then blank => top => get line above\r\n@InteresttransactionsBottom = get line containing \"Total Interest for this\" => if not found then blank => top => get line above\r\n\r\n@fees = get multi page table @FeeInteresttransactionsTop @FeetransactionsBottom 30 180 237 => describe table false Details *#Credit\r\n@Interest = get multi page table @FeeInteresttransactionsTop @InteresttransactionsBottom 237 410 480 => describe table false Details *#Credit\r\n\r\n//@deletetablestop = get line starting \"Fees Charged Interest Charged\" => top\r\n//@deletetablesbottom = get line containing \"Total Interest for this\" => bottom\r\n//$deletetables = delete text in box @deletetablestop @deletetablesbottom 0 480 => get text\r\n\r\n@deletetablestop = get line starting \"Fees Charged Interest Charged\" => top\r\n@deletetablesbottom = get line containing \"Total Fees for this period\" => bottom\r\n$deletetables = delete text in box @deletetablestop @deletetablesbottom 0 238 => get text\r\n\r\n@deletetablesbottom1 = get line containing \"Total Interest for this Period\" => bottom\r\n$deletetables1 = delete text in box @deletetablestop @deletetablesbottom1 239 480 => get text\r\n\r\n@transactionsBottom = get line containing \"Your Annual Percentage Rate\" => top => get line above\r\n\r\n//Secondary table Unique one format\r\n@InterestFromChargesTop = get line containing \"Rate (APR) Purchase APR Expiration Date\" => if not found then blank => bottom => get line below\r\n\r\n//Dynamics\r\n@RateAPRLeft = get line containing \"Rate (APR) Purchase\" => get words before \"(APR) Purchase\" => take last words 1 => left\r\n@RateAPRLeft = subtract @RateAPRLeft 10\r\n\r\n@InterestFromChargesBottom = get line containing \"Total Year-to-Date\" => top => get line above\r\n\r\ngo to page 1\r\ndelete all lines starting $accountNumber\r\ndelete all lines starting  \"Account Number\"\r\ndelete all lines starting  \"Page\"\r\ndelete all lines starting  \"Transaction Detail\"\r\ndelete all lines starting  \"Trans Post Reference\"\r\ndelete all lines starting  \"Date Date Number\"\r\ndelete all lines starting \"Your Annual Percentage Rate (APR)\"\r\ndelete all lines starting \"Charge Annual Percentage Special Offer\"\r\ndelete all lines starting \"Rate (APR) Purchase APR\"\r\ndelete all lines starting \"Trans Date Post Date\"\r\n\r\nignore header above 934\r\nignore footer below 30\r\n\r\n//@gettransactions = get multi page table @transactionsTop @transactionsBottom @Postdateleft @Referenceleft @CreditLeft 500 => describe table false \"*Date[M-dd]\" Details #Credit\r\n@gettransactions = get multi page table @transactionsTop @transactionsBottom @Postdateleft @Referenceleft @CreditLeft 500 => describe table false \"Date[M-dd]\" Details *#Credit\r\n@InterestFromCharges = get multi page table @InterestFromChargesTop @InterestFromChargesBottom 25 @RateAPRLeft @CreditLeft 500 => describe table false Details - *#Credit\r\n\r\n$transactions = combine described tables @gettransactions @fees @Interest @InterestFromCharges','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10725,'Sunwest_Bank','$Source = \"Sunwest_Bank\"\n\n//GetAccounts\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n$accountNumber =  get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//Get Periods\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n//Get Balances\ngo to page 1\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\n$summeryBottom =  get line starting  \"Account Summary\" => bottom => get line below => bottom\n$delSummery = delete text in box page.top $summeryBottom 0 page.right => get text\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount\" => get text\n@dateLeft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detilsLeft = get line containing @tranactionColumns => take words 2 => take last words 1 => left => subtract 3\n//$amountLeft = get line containing @tranactionColumns => take last words 1 => get text\n@amountLeft = get line containing @tranactionColumns => take last words 1 => left => subtract 15\n@amountRight = get line containing @tranactionColumns => take last words 1 => right => add 15\n\ngo to page 1\n// Get start & end of all Credits table\n@depositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below\n@depositsBottom = get line containing \"Debits\" => if not found then blank => top => get line above\n\ngo to page 1\n@creditsTop = get line starting \"Electronic Credits\" => if not found then blank => bottom => get line below\n@creditsBottom = get line containing \"Debits\" => if not found then blank => top => get line above\n\ngo to page 1\n// Get start & end of all Debits table\n@debitsTop = get line containing \"Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\n\ngo to page 1\n@daily_bottom  =  get line starting \"Daily Balances\" => if not found then blank => bottom\n@delDaily = delete text in box  @daily_bottom 0 0 page.right => get text\n\ngo to page 1\n\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Electronic Credits\"\ndelete all lines starting \"Electronic Debits\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Daily Balances\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"BUSINESS CHECKING\"\ndelete all lines containing \"Account Number:\"\ndelete all lines starting \"Account Number:\"\ndelete all lines starting \"Statement Ending\"\n\nignore header above 680\nignore footer below 75\n\n// Read the transactions\n@deposits = get multi page table @depositsTop @depositsBottom @dateLeft @detilsLeft @amountLeft @amountRight => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@credits = get multi page table @creditsTop @creditsBottom @dateLeft @detilsLeft @amountLeft @amountRight => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\n@debits = get multi page table @debitsTop @debitsBottom @dateLeft @detilsLeft @amountLeft @amountRight => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\n$transactions = combine described tables @deposits @credits @debits\n','2025-07-02 05:35:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10726,'Woodforest_National_Bank','$source = \"Woodforest_National_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n$Delete_text = delete text in box on every page page.top page.bottom 0 45 => get text\n\ngo to page 1\n//get account Name\n$accountName = get line containing \"ACCOUNT TYPE AND NUMBER\" => bottom => get line below => bottom => get line below => take last words 1 => get text\n\n//get account number\n$accountNumber = get line containing \"ACCOUNT TYPE AND NUMBER\" => bottom => get line below => bottom => get line below => take last words 1 => get text\n\n//get statement period\n$periodFrom = get line containing \"Statement Period:\" => get words after \"Period:\" => get words before \"-\" => get date \"MMM dd\"\n$periodTo = get line containing \"Statement Period:\" => get words after \"Period:\" => get words after \"-\" => get date \"MMM d, yyyy\"\n\n@TEXTBOXTop1 = get line containing \"FORWARD DEBITS CREDITS BALANCE\" => bottom\n@TEXTBOXBottom1 = get line containing \"FORWARD DEBITS CREDITS BALANCE\" => bottom => get line below => bottom => get line below => top\n\n//get opening & closing balance\n$openingBalance = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 270 page.right => take words 1 => get decimal\n$closingBalance = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 270 page.right => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Credits Debits\" => bottom => get line below\n@transactionsBottom = get last line containing \"Account Summary\" => top => get line above\n\nignore header above 690\nignore footer below 22\n\ndelete all lines containing \"Date Credits Debits\"\ndelete all lines containing \"(continued)\"\n\n@TEXTBOXTop = get line containing \"Checks Cleared\" => if not found then blank => bottom\n@TEXTBOXBottom = get line starting \"Account Summary\" => top\n$Delete_text2 = delete text in box @TEXTBOXTop @TEXTBOXBottom 0 page.right => get text\n\n//get all transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 46 75 160 225 288 590  => describe table false \"*Date[MM-dd]\" #Credit #Debit #Balance Details','2025-07-02 05:35:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10727,'CitizensBank_Card','$dource = \"CitizensBank_Card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 28\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.right => take words 4 => get text\n$accountNumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 4 => get text\n\n//Get Balances\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line starting \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n//Get Periods\n@periodText = get line containing \"Period:\" => get words after \"Period\" => get text\n$periodFrom = get line containing @periodText => get words before \"-\" => take last words 3 => get date \"MMMM d, yyyy\"\n$periodTo = get line containing @periodText => get words after \"-\" => take  words 3 => get date \"MMMM d, yyyy\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Trans Date Post Date Reference Number\" => get text\n\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n@date1left = get line containing @tranactionColumns => get words after \"Trans Date\" => take words 1 => left => subtract 6\n@bankRefleft = get line containing @tranactionColumns => get words after \"Post Date\" => take words 1 => left => subtract 5\n@detailsleft = get line containing @tranactionColumns => get words after \"Reference Number\" => take words 1 => left => subtract 5\n@amountleft  =  get line containing @tranactionColumns => take last words 1 => left => subtract 12\n@amountright =   get line containing @tranactionColumns => take last words 1 => right => add 12\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Trans Date Post Date Reference\" => bottom => get line below\n$gotolastTransBottom = get last line starting \"Trans Date Post Date Reference\"\n@transactionsbottom = get last line containing \"Year-to-Date\" => top => get line above\n//@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\n@ft_bottom = get line containing \"Year-to-Date\" => top\n//@ft_bottom = get line containing \"Year-to-Date\" => if not found then blank => bottom\n@del_ft = delete text in box @ft_bottom page.bottom 0 page.right => get text\n\ngo to page 1\ndelete all lines starting \"Account Activity\"\ndelete all lines starting \"Trans Date Post Date Reference\"\ndelete all lines containing \"Year-to-Date\"\ndelete all lines starting \"Account Number:\"\ndelete all lines containing \"Period:\"\ndelete all lines starting \"PAYMENTS AND CREDITS\"\ndelete all lines starting \"PURCHASES\"\ndelete all lines starting \"INTEREST CHARGED\"\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines starting \"Total fees\"\ndelete all lines starting \"Total interest\"\n\nignore header above 520\nignore footer below 50\n\n$transactions = get multi page table @transtionTop @transactionsbottom @dateleft @date1left @bankRefleft @detailsleft @amountleft @amountright => describe table false \"TransactionDate[MM/dd]\" \"*Date[MM/dd]\" TransactionType Details #Credit','2025-07-02 05:35:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10728,'FirstBank','$source = \"FirstBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n//Get Accounts\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 4 => get text\n@accountText = get line starting \"Account number\" => take words 2 => get text\n@accountLeft = get line containing @accountText => take words 1 => left => subtract 3\n@accountRight = get line containing @accountText => take last words 1 => right\n@accountTop = get line containing @accountText => take words 2 => bottom\n$accountNumber = get text in box @accountTop 0 @accountLeft  @accountRight => take words 1 => get text\n\ngo to page 1\n//get Periods\n$periodFrom = get line starting \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMM d, yyyy\"\n$periodTo = get line starting \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMM d, yyyy\"\n\ngo to page 1\n//Get opening and closing Balances\n$closingBalance = get line containing \"Ending Balance\" => bottom => get line below => take last words 1 => get decimal\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take words 1 => get decimal\n\ngo to page 1\n@checktop = get line containing \"Skip in check sequence\" => top\n@checkbottom = get line containing \"Skip in check sequence\" => bottom\n@deleteskip = delete text in box @checktop @checkbottom 355 550 => get text\n\n// Get start & end of cheques table\n@chequeTop = get line containing \"Number Date Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Date Description\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 70 193 260 330  => describe table false  ChequeNumber \"*Date[MM-dd]\" #Debit\ndelete all lines containing \"* Skip\"\ndelete all lines containing \"Skip in check sequence\"\ndelete all lines starting \"Number Date Amount\"\n@chequeCenter = get multi page table @chequeTop @chequebottom 340 382 475 550 => describe table false ChequeNumber \"*Date[MM-dd]\" #Debit\n\ngo to page 1\ndelete all lines starting \"Number Date Amount\"\ndelete all lines containing \"Beginning balance\"\ndelete all lines containing \"Ending totals\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Additions Subtractions\" => get text\n@dateLeft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detilsLeft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 10\n@creditLeft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 15\n@creditRight = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => right => add 10\n@debitRight = get line containing @tranactionColumns => get words after \"Additions\" => take words 1 => right => add 15\n\n// Get start and end of table\ngo to page 1\n@transtionTop = get line starting \"Date Description Additions Subtractions\" => bottom => get line below\n$gotolastTransBottom = get last line starting \"Date Description Additions Subtractions\" => bottom\n@transactionsbottom = get last line starting \"Total\" => top => get line above\n//@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\ndelete all lines starting \"Date Description Additions Subtractions\"\ndelete all lines starting \"Account\"\ndelete all lines starting \"Commercial Checking\"\ndelete all lines starting \"Total\"\ndelete all lines containing \"Beginning balance\"\ndelete all lines containing \"Total additions\"\ndelete all lines containing \"Total subtractions\"\ndelete all lines containing \"year-to-date\"\ndelete all lines starting \"this period\"\ndelete all lines containing \"Ending totals\"\nignore header above 700\nignore footer below 100\n\nset negative marker \"-\"\n\n@debitCreditTrans = get multi page table @transtionTop @transactionsbottom @dateLeft @detilsLeft @creditLeft @creditRight @debitRight => describe table false  \"*Date[MM-dd]\" Details #Credit #Debit\n$transactions = combine described tables @debitCreditTrans @chequeLeft @chequeCenter\n','2025-07-02 05:35:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10729,'Mercado','$source = \"Mercado\"\n\n// Parse dates in French\nset culture \"fr-CA\"\n\n//get statement periodfrom\n$periodFrom = get line containing \"Fecha Descripción\" => bottom => get line below => bottom => get line below => take words 1 => get date \"d-MM-yyyy\"\n\n\n//get statement periodTo\ngo to last page\n@period_bottom = get line containing \"Fecha de generación\" => top\n$periodTo = get text in box page.top @period_bottom 25 72 => take last words 1 => get date \"d-MM-yyyy\"\n\n\ngo to page 1\n//account name\n$accountName = get line containing \"RESUMEN DE CUENTA\" => bottom => get line below => take words 2 => get text\n\n//account number\n$accountNumber = get line containing \"CVU:\" =>  get words after \"CVU:\" => take words 1 => get text\n\n\n//get opening/closing\n$openingBalance = get line containing \"Saldo inicial: $\" => get words after \"Saldo inicial: $\" => take words 1 => get decimal\n$closingBalance = get line containing \"Saldo final: $\" => get words after \"Saldo final: $\" => take words 1 => get decimal\n\n//get start of table\ngo to page 1\n@transactionsTop = get line containing \"Fecha Descripción\" => bottom => get line below\n\n//delete garbage text/lines\ndelete all lines containing \"Fecha de generación:\"\ndelete all lines containing \"Mercado Libre S.R.L. CUIT\"\ndelete all lines containing \"en: www.mercadopago.com.ar\"\n\n\n\n//get end of table transactions\ngo to last page\n@transactionsBottom = get line above 0\n\n//ignore header above\nignore header above 580\n\n//ignore footer\nignore footer below 15\n\n\ngo to page 1\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 72 270 350 430 => describe table false \"*Date[d-MM-yyyy]\" Details #Credit #Balance','2025-07-02 05:35:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10730,'NBT_Financial','$source = \"NBT_Financial\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n$accounttop = get line containing \"Account Number\" => top\n$accountbottom = get line containing \"Ending Balance\" => bottom\n$accdetails = get text in box $accounttop $accountbottom page.left 460\n$accountName = get words after $accdetails \"Account Number Ending\" => take words 1 => get text\n$accountNumber = get words after $accdetails \"Account Number Ending\" => take words 1 => get text\n$openingBalance = get words after $accdetails \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = take last words $accdetails 1 => get decimal\n\n$periodtext = get line containing \"Statement Dates\" => take last words 3\n$periodfrom = take words $periodtext 1 => get date \"M/d/yy\"\n$periodto = take last words $periodtext  1 => get date \"M/d/yy\"\n\n\ngo to page 1\n// Get start & end of Deposits table\n@DepositsTop = get line starting \"DEPOSITS AND OTHER CREDIT\" => if not found then blank => bottom => get line below\n@DepositsBottom = get line starting \"CHECKS AND OTHER DEBITS\" => if not found then blank => top => get line above\nignore header above 480\nignore footer below 30\n\n\ndelete all lines containing \"DEPOSITS AND OTHER CREDIT\"\ndelete all lines containing \"DATE DESCRIPTION AMOUNT\"\n@Deposits = get multi page table @DepositsTop @DepositsBottom 30 65 300 420 => describe table false \"Date[M/d]\" Details *#Credit\n\n\n// Get start & end of cheques table\ngo to page 1\n@chequeTop = get line containing \"CHECKS BY CHECK NUMBER\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"INDICATES A GAP IN CHECK\" => if not found then blank => top => get line above\n\n//delete all lines containing \"Indicates preceding check\"\ndelete all lines containing \"DATE CHECK # AMOUNT\"\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 30 60 115 178 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n@chequeMiddle = get multi page table @chequeTop @chequebottom 175 205 255 323 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 320 350 400 470 => describe table false \"Date[M/d]\" ChequeNumber *#Debit\n\n// Get start & end of DEBIT table\ngo to page 1\n@debitTop = get line containing \"CHECKS AND OTHER DEBITS\" => if not found then blank => bottom => get line below\n@debitbottom = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\ndelete all lines containing \"CHECKS AND OTHER DEBITS\"\n$dlttop = get line starting \"CHECKS BY CHECK NUMBER\" => top\n$dltbot = get line containing \"DAILY BALANCE SUMMARY\" => bottom\n$dlttopbot = delete text in box $dlttop $dltbot page.left page.right\n\n@debits = get multi page table @debitTop @debitbottom 30 65 300 420 => describe table false \"Date[M/d]\" Details *#Debit\n\n\n$transactions = combine described tables @Deposits @debits @chequeLeft @chequeMiddle @chequeRight','2025-07-02 05:35:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10731,'ConnectFirst_CreditUnion','$source = \"ConnectFirst_Servus_CreditUnion\"\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\nset negative marker \"-\"\n\n// Get account details\n@TEXTBOXBottom1 = get line starting \"Date Description Debits\" => top => get line above => top\n$accountName = get text in box page.top @TEXTBOXBottom1 0 page.middleX => take words 2 => get text\n$accountNumber = get line containing \"Account Number\" => get words after \"Account\" => get text\n\ngo to page 1\n// Get statement period\n$periodFrom = get line containing \"Period Beginning\" => get words after \"Beginning\" => get date \"MMM dd yyyy\"\n$periodTo = get line containing \"Period Ending\" => get words after \"Ending\" => take words 3 => get date \"MMM dd yyyy\"\n\n// Get opening & closing balance\ngo to page 1\n$openingBalance = get line containing \"Balance Forward\" => take last words 1 => get decimal\n$closingBalance = 0\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line containing \"No. of Enclosures\" => bottom => get line below => bottom => get line below\n\n// discards\nignore header above 710\n//ignore footer below 96\ndelete all lines starting \"For a Lost\"\ndelete all lines starting \"If this statement\"\ndelete all lines starting \"Total Debits\"\ndelete all lines starting \"Total Credits\"\ndelete all lines starting \"There is no activity\"\ndelete all lines containing \"Balance Forward\"\ndelete all lines containing \"Date Description Debits\"\ndelete all lines starting \"Interest Principal\"\n\ngo to page 1\n@TEXTBOXTop2 = get line containing \"Unauthorized Overdraft\" => bottom\n@TEXTBOXBottom2 = get line starting \"Common Share ACCOUNT\" => top\n$TEXTBOX2 = delete text in box @TEXTBOXTop2 @TEXTBOXBottom2 0 page.right => get text\ndelete all lines starting \"Unauthorized Overdraft\"\n\n@transactionsBottom1 = get last line starting \"Deposit Account Interest\" => top => get line above\ngo to page 1\n@TEXTBOXTop = get line containing \"Date Rate Date\" => bottom\n@TEXTBOXBottom = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\n$TEXTBOX = delete text in box @TEXTBOXTop @TEXTBOXBottom 0 page.right => get text\n\ndelete all lines starting \"Deposit Account Interest\"\ndelete all lines starting \"Date Rate Date\"\ndelete all lines starting \"Servus and connectFirst\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom1 0 315 420 500 => describe table false Details *#Debit *#Credit','2025-07-02 05:35:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10732,'WellsFargo_VisaCard','$source = \"WellsFargo_VisaCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 31\n\n$accountname = \"Anonymous\"\n\n@accountDetailstop = get line containing \"Account\" => top\n@accountDetailsbottom = get line containing \"Account\" => bottom => get line below => bottom\n@accountDetails = get text in box @accountDetailstop @accountDetailsbottom 100 525\n$accountNumber = get words after @accountDetails \"nding in\" => get words before \"Statement\" => get text\n\n$periodFrom = get words after @accountDetails \"Period\" => get words between \"Period\" \"to\" => get date \"M/d/yyyy\"\n$periodTo = get words after @accountDetails \"to\" =>  get date \"M/d/yyyy\"\n\n$openingbalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingbalance = get line containing \"New Balance\" => get words after \"Balance\" => take words 1 => get decimal\n\n@PostdateLeft = get line containing \"Trans Post Reference Number\" => get words after \"Trans\" => take words 1 =>  left\n@PostdateLeft = subtract @PostdateLeft 5\n@ReferenceLeft = get line containing \"Trans Post Reference Number\" => get words after \"Trans Post\" => take words 1 =>  left\n@ReferenceLeft = subtract @ReferenceLeft 5\n@CreditsLeft = get line containing \"Trans Post Reference Number\" => get words after \"Description\" => take words 1 =>  left\n@CreditsLeft = subtract @CreditsLeft 10\n@ChargesLeft = get line containing \"Trans Post Reference Number\" => get words after \"Credits\" => take words 1 =>  left\n@ChargesLeft = subtract @ChargesLeft 10\n\n@transactionstop = get line containing \"Trans Post Reference Number\" => bottom => get line below\n\ngo to page 1\n@deletetext = get line containing \"= New Balance\" => bottom\n$DLTHDR = delete text in box page.top @deletetext page.left page.right => get text\n\ngo to page 1\n@deleteFooter = get line containing \"Continued\" => top\n$DLTFTR = delete text in box @deleteFooter page.bottom page.left page.right => get text\n\n$pagermv = delete all pages containing \"Written Notice\"\n\ngo to page 2\nignore header above 885\nignore footer below 30\n\ndelete all lines containing \"TOTAL PAYMENTS FOR THIS PERIOD\"\ndelete all lines containing \"TOTAL OTHER CREDITS FOR THIS PERIOD\"\ndelete all lines containing \"TOTAL CASH ADVANCES FOR THIS PERIOD\"\ndelete all lines containing \"TOTAL PURCHASES, BALANCE TRANSFERS\"\ndelete all lines containing \"TOTAL FEES CHARGED FOR THIS PERIOD\"\ndelete all lines containing \"Purchases, Balance Transfers\"\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Fees Charged\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"TOTAL OTHER CREDITS FOR THIS PERIOD\"\ndelete all lines containing \"PAGE\"\ndelete all lines starting \"Fees Charged\"\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"Ending Date Date\"\ndelete all lines starting \"in\"\ndelete all lines containing \"(continued from previous page)\"\ndelete all lines containing \"Trans Post Reference Number\"\n\ngo to page 1\n@transactionsbottom = get line containing \"TOTAL INTEREST CHARGED FOR THIS PERIOD\" => top => get line above\n\n$transactions = get multi page table @transactionstop @transactionsbottom @PostdateLeft @ReferenceLeft @CreditsLeft @ChargesLeft 620 => describe table false \"Date[MM/dd]\" Details *#Debit *#Credit','2025-07-24 06:49:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10733,'Synchrony_Amazon_Card','$source = \"Synchrony_Amazon_Card\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n@accountDetailsbottom = get line containing \"Account Number ending\" => bottom\n@accountDetails = get text in box page.top @accountDetailsbottom 195 page.right\n\n$accountName = get words before @accountDetails \"Account Number\" => get text\n$accountNumber = get words after @accountDetails \"ending in\" => get text\n\n@NewBalancetop = get line containing \"New Balance:\" => top\n@NewBalancebottom = get line containing \"New Balance:\" => bottom\n$ClosingBalance = get text in box @NewBalancetop @NewBalancebottom 0 295 => get words after \"New Balance:\" => get decimal\n\n@PreviousBalancetop = get line containing \"Previous Balance as of\" => top\n@PreviousBalancebottom = get line containing \"Previous Balance as of\" => bottom\n@PreviousBalance = get text in box @PreviousBalancetop @PreviousBalancebottom 0 295\n\n$periodFrom = get words after @PreviousBalance \"Previous Balance as of\" => take words 1 => get date \"MM/d/yyyy\"\n$OpeningBalance = get words after @PreviousBalance \"Previous Balance as of\" => skip words 1 => get decimal\n\n@periodTotop = get line containing \"New Balance as of\" => top\n@periodTobottom = get line containing \"New Balance as of\" => bottom\n$periodTo = get text in box @periodTotop @periodTobottom 0 215 => get words after \"New Balance as of\" => take words 1 => get date \"MM/d/yyyy\"\n\n@transactionsTop = get line starting \"Date Reference\" => bottom => get line below\n@transactionsBottom = get line containing \"Interest Charge Calculation\" => top => get line above\n\ndelete all lines starting \"Payments\"\ndelete all lines starting \"Other Credits\"\ndelete all lines starting \"Purchases and Other Debits\"\ndelete all lines containing \"Continued on next page\"\ndelete all lines containing \"(Continued)\"\ndelete all lines containing \"Date Reference\"\ndelete all lines starting \"Total Fees Charged\"\ndelete all lines starting \"Total Interest Charged\"\ndelete all lines starting \"Total Interest Paid\"\ndelete all lines containing \"Year-to-Date Fees and Interest\"\ndelete all lines starting \"TOTAL\"\n\nignore header above 952\nignore footer below 22\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 60 178 405 490 => describe table false \"*Date[MM/d]\" TransactionType Details #Credit','2025-07-24 06:49:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10734,'RBC_commercial_card','$source = \"RBC_commercial_card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD NO_OPENING_BALANCE\"\n$periodBufferDays = 15\n\n$periodFrom = get line containing \"Statement from\" => get words between \"Statement from\" \"to\" => get date \"MMM dd yyyy\"\n$periodTo = get line containing \"Statement from\" => get words after \"to\" => take words 3 => get date \"MMM dd yyyy\"\n\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n$accountName = get text in box 650 620 50 350 => take words 2 => get text\n\n//$openingBalance = => get decimal\n//$closingBalance = get line starting \"New Balance\" => get words after \"New Balance\" => take last words 1 => get decimal\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take last words 1 => get decimal\n\n$deltxt1 = get line containing \"CARDHOLDER ACTIVITY\" => bottom => get line below => take words 2 => get text\n$deltxt2 = get line containing \"CREDITS TOTAL ACTIVITY\" => top => get line above => take words 2 => get text\n$deltxt3 = get line containing \"CREDITS TOTAL ACTIVITY\" => top => get line above => take words 2 => get text\n$deltxt4 = get last line containing \"CREDITS TOTAL ACTIVITY\" => top => get line above => take words 2 => get text\n\ngo to page 1\n@PostL = get line containing \"Date Date Reference Number Transaction\" => get words before \"Reference\" => take last words 1 => left => subtract 10\n@ReferenceL = get line containing \"Date Date Reference Number Transaction\" => get words before \"Number\" => take last words 1 => left => subtract 10\n@AmountL = get line containing \"Date Date Reference Number Transaction\" => take last words 1 => left => subtract 30\n@AmountR = get line containing \"Date Date Reference Number Transaction\" => take last words 1 => right => add 30\n\ngo to page 1\n@transactionsTop = get line containing \"Date Date Reference Number Transaction\" => bottom => get line below\n@transactionsBottom = get last line starting \"Page\" => top => get line above\n\nignore header above 675\n//ignore footer below 270\n@firstpageFooter = get last line containing \"Please tear payment\" => top\n$dlt0 = delete text in box @firstpageFooter page.bottom page.left page.right => get text\n\n@pageFooter = get last line containing \"You may pay your credit\" => top\n$dlt1 = delete text in box @pageFooter 0 0 page.right => get text\n\ndelete all lines starting $deltxt1\ndelete all lines starting $deltxt2\ndelete all lines starting $deltxt3\ndelete all lines starting $deltxt4\ndelete all lines containing \"CARDHOLDER ACTIVITY\"\ndelete all lines containing \"CREDITS TOTAL ACTIVITY\"\ndelete all lines containing \"Credit Limit\"\ndelete all lines containing \"Tran Post\"\ndelete all lines containing \"Date Date\"\ndelete all lines containing \"ACCOUNT ACTIVITY\"\ndelete all lines containing \"Please tear payment\"\ndelete all lines starting \"Page\"\n\n//Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 50 90 127 520 585 => describe table false transdate \"*Date[MMM dd]\" Details #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom @PostL @ReferenceL @AmountL @AmountR => describe table false \"*Date[MMM dd]\" Details #Credit','2025-07-24 06:49:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10735,'CardOneMoney','$source = \"CardOneMoney\"\n\n$features =  \"NO_OPENING_BALANCE\"\n\n$accountName = get line starting \"Date range:\" => bottom => get line below  => take words 2 => get text\n\n$dltsort = get line containing \"Sort Code:\" => top\n$dlt = delete text in box page.top $dltsort page.left 410 => get text\n$accountNumber = get line containing \"Account Number:\" => bottom => get line below  => take last words 1 => get text\n\ngo to page 1\n$periodFrom = get line starting \"Date Description In(£)\" => bottom => get line below  => take words 1 => get date \"dd MM yyyy\"\n//$periodFrom = get line containing \"Date range:\" => get words after \"Date range:\" => take words 1 => get date \"dd MM yyyy\"\n\ngo to page 1\n$Date_left = get line containing \"Date Description In(£)\" => get words before \"Description \" => left => subtract 6\n$Description_left = get line containing \"Date Description In(£)\" => get words after \"Date\" => left => subtract 5\n$Description_right = get line containing \"Date Description In(£)\" => get words after \"Description \" => left => subtract 10\n$Paidin_right = get line containing \"Date Description In(£)\" => get words after \"In(£)\" => left => subtract 5\n$Paidout_right = get line containing \"Date Description In(£)\" => get words after \"Out(£)\" => left => subtract 5\n$Balance_right = get line containing \"Date Description In(£)\" => get words after \"Out(£)\" => right\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description In(£)\" => bottom => get line below\n\ngo to last page\n//@transactionsBottom = get last line containing \"Transfer\" => get words after \"Transfer\" => take last words 1\n//$closingbalance = take last words @transactionsBottom 1 => get decimal\n@transactionsBottom = get last line containing \"https://secure.cardonemoney\" => top => get line above\n\ndelete all lines containing \"One Money\" => bottom\n$closingbalance = get last line containing \"https://secure.cardonemoney\" => top => get line above => bottom => get line above => take last words 1 => get decimal\n$periodTo = get last line containing \"https://secure.cardonemoney\" => top => get line above => bottom => get line above => take words 1 => get date \"dd/MM/yyyy\"\n\n// Read the transactions\n//$transactions = get multi page table @transactionsTop @transactionsBottom 28 90 330 410 470 550 => describe table false \"Date[dd MM yyyy]\" Details #Credit #Debit\n\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Description_left $Description_right $Paidin_right $Paidout_right $Balance_right => describe table false \"Date[dd MM yyyy]\" Details #Credit #Debit','2025-07-24 06:49:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10736,'TDCanadaTrust_French_CreditCard','$source = \"TDCanadaTrust_French_CreditCard\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 14\n\nset culture \"fr-CA\"\n//set culture \"nl-BE\"\n//set culture \"fr-FR\"\n//set culture \"en-GB\"\n\ndelete rotated words\n\n// Get account number\n$accountNumber = get line starting \"Numéro de compte :\" => skip words 3 => get text\n\n// Delete contact block on right side of page 1\n@tbmr = delete text in box on every page page.top page.bottom 360 page.right => get text\n// Get period from/to\n\n$periodFrom = get line starting \"PÉRIODE DE RELEVÉ :\" => get words after \"du\" => take words 3 => get date \"d MMM yyyy\"\n\n$periodTo = get line starting \"PÉRIODE DE RELEVÉ :\" => get words after \"au\" => take words 3 => get date \"d MMM yyyy\"\n\n// Get opening and closing balances\n@openingBalanceWords = get line starting \"SOLDE DU RELEVÉ PRÉCÉDENT\" => skip words 4\n$openingBalanceText = get text @openingBalanceWords\n$openingBalance = get decimal @openingBalanceWords\n@closingBalanceWords = get line starting \"TOTAL NOUVEAU SOLDE\" => skip words 3\n$closingBalanceText = get text @closingBalanceWords\n$closingBalance = get decimal @closingBalanceWords\n\n// Get account name\ngo to page 1\n$accountName = get line starting \"TDSTM\" => bottom => get line below => get text\n\n$summaryTop = get line containing \"Le présent relevé couvre la période qui y est indiquée\" => top\n$summaryBottom = get line containing \"dans le solde qui figure sur le présent relevé.\" => bottom\n$dbox = delete text in box $summaryTop $summaryBottom page.left page.right\n\n// Deleting the top panel from all the pages to avoid unnessary data\ngo to page 1\n@tableHeader = get line containing \"DATE DE DATE DE\" => top\ndelete text in box on every page page.top @tableHeader page.left page.right\n\n// Get start of table\ngo to page 1\n@transactionsTop = bottom @openingBalanceWords => get line below\n@transactionsBottom = get last line starting \"TOTAL NOUVEAU SOLDE\" => top => get line above\n\ngo to page 1\n$ctrlLast = get line containing \"SOLDE DU RELEVÉ PRÉCÉDENT\"\n$tranbottom1 = get line containing \"Suite\" => bottom\n@b1 = delete text in box $tranbottom1 page.bottom page.left page.right\n\n//@lastbottom = bottom @transactionsBottom\n//$lastfooter = delete text in box @lastbottom page.bottom page.left page.right\ndelete all lines containing \"Suite\"\ndelete all lines containing \"DATE DE DATE DE\"\ndelete all lines containing \"TOTAL NOUVEAU SOLDE\"\ndelete all lines containing \"SOLDE DU RELEVÉ PRÉCÉDENT\"\nignore header above 630\nignore footer below 31\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 92 136 290 345 => describe table false - \"Date[d MMM]\" Details *#Credit','2025-07-24 06:49:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10737,'Albaraka_Bank','$source = \"Albaraka_Bank\"\nset negative marker \"-\"\n$periodBufferDays = 28\n//Get Account Number\n$accountNumber =  get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n$accountName = get text in box 750 0 0 page.right => take words 7 => get text\n\n//Get Periods\n$periodFrom = get line containing \"FROM:\" => get words after \"FROM:\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"TO:\" => get words after \"TO:\" => take words 1 => get date \"dd/MM/yyyy\"\n\n//Get Opening\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening balance\" => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Transaction Description Debit Credit Balance\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n@dateright = get line containing @tranactionColumns =>  take words 1 => right => add 5\n@debitleft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 10\n@creditleft = get line containing @tranactionColumns => get words after \"Debit\" => take words 1 => left => subtract 10\n@balanceleft = get line containing @tranactionColumns => take last words 1 => left => subtract 10\n@balanceright =   get line containing @tranactionColumns => take last words 1 => right => add 50\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Transaction Description Debit Credit Balance\" => bottom => get line below\n$gotolastTransBottom = get last line starting \"Transaction Description Debit Credit Balance\"\n@transactionsbottom = get last line containing \"Transactions on this statement\" => top => get line above\n//@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\ndelete all lines starting \"Transaction Description\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines starting \"Albaraka Bank Limited\"\ndelete all lines starting \"Transaction History\"\ndelete all lines containing \"FROM:\"\ndelete all lines starting \"Client Name\"\ndelete all lines containing \"Account Number\"\ndelete all lines starting \"Statement Date:\"\n\nignore header above 700\n\n$lastTransactionsTop = get last line starting \"Transaction Description Debit Credit Balance\" => bottom\n//Get Closing Balances\n$closingBalance = get last line containing \"Transactions on this statement\" => top => get line above => take last words 1 => get decimal\n\ndelete all lines containing \"Transactions on this statement\"\nignore footer below 40\n\n$transactions = get multi page table @transtionTop @transactionsbottom @dateleft @dateright @debitleft @creditleft @balanceleft @balanceright => describe table false \"*Date[dd/MM/yyyy]\" Details  #Debit #Credit #Balance\n','2025-07-24 06:49:57',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10738,'AlphaBank','$source = \"AlphaBank\"\n\n$features = \"REVERSE_ORDER\"\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get account name\n@top = get line containing \"Statement\" => bottom\n@bottom = get line containing \"IBAN:\" => top\n$accountName = get text in box @top @bottom page.left page.middleX => take words 3 => get text\n\n\n//statement_period\n@period_top = get line containing \"Statement\" => bottom\n@period_bottom = get line containing \"Opening Balance:\" => top\n@period = get text in box @top @bottom page.middleY page.right => take last words 3\n\n//get period_from\n$periodFrom = take words @period 1 => get date \"dd/MM/yyyy\"\n\n//get period_to\n$periodto  = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n\n//get opening/closing balance\n$closingBalance = get line containing \"Opening Balance:\" => get words after \"Opening Balance:\" => get decimal\n\n$openingbalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"DATE ID SENDER REFERENCE\" => bottom => get line below => bottom => get line below\n\n\n// Get end of table\n@transactionsBottom = get last line containing \"Opening Balance\" => top => get line above\n\n\n//ignore header\nget last line containing \"DATE ID SENDER REFERENCE\" => bottom => ignore header above\n\n//ignore footer\nignore footer below 95\n\n\n//delete extra text/line\ndelete all lines starting \"DATE ID SENDER REFERENCE\"\n\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 90 252 375 425 495 580 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Credit #Debit #Balance','2025-07-24 06:49:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10739,'Zenith_Bank','$source = \"Zenith_Bank\"\n\n$periodBufferDays = 28\n\n$periodtop = get line starting \"Account Name Account No\" => bottom\n$periodbot = get line starting \"Create Date Effective Date\" => top\n$periodtext = get text in box $periodtop $periodbot 205 page.right\n$accountName = take words $periodtext 1 => get text\n$accountnumber = take words $periodtext 1 => get text\n$periodfrom = take words $periodtext 2 => skip words 1 => get date \"d/MM/yyyy\"\n$openingBalance = take last words $periodtext 1 => get decimal\n\n$periodto = get line starting \"Cleared balance as at :\" => get words after \"Cleared balance as at :\" => take words 1 => get date \"d/MM/yyyy\"\n$closingBalance = get line containing \"Ending Balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n\n@transactionsTop = get line starting \"Create Date Effective Date\" => bottom => get line below\n@transactionsBottom = get last line starting \"Total Debits :\" => top => get line above\n\ndelete all lines starting \"Create Date Effective Date\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 78 133 180 323 400 480 560 => describe table false - \"*Date[d/MM/yyyy]\" TransactionType Details #Debit #Credit #Balance','2025-07-24 06:49:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10740,'Amegy_Bank_PostingEffectiveDate','$source = \"Amegy_Bank_PostingEffectiveDate\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\n\n// Get account number\n$accountNumber = get line containing \"Last Statement\" => bottom => get line below => take last words 1 => get text\n\n// Get period from/to\n$periodFrom = get line containing \"Last Statement:\" => get words after \"Last Statement:\" => get date \"MMM d, yyyy\"\n$periodTo = get line containing \"This Statement:\" => get words after \"This Statement:\" => get date \"MMM d, yyyy\"\n\n@TextBoxtbottom = get line containing \"Amegy Bank -\" => if not found then blank => top\ndelete text in box page.top @TextBoxtbottom page.middleX page.right\n\n// Get account name\n$accountName = get line below page.top => take words 3 => get text\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Previous Balance\" => bottom => get line below => bottom => get line below => get words after \"Amount:\" => take words 1 => get decimal\n$closingBalance = get line starting \"Previous Balance\" => bottom => get line below => bottom => get line below => get words after \"Amount:\" => take last words 1 => get decimal\n\ndelete all lines containing \".......\"\ndelete all lines containing \"Posting Effective\"\ndelete all lines containing \"Date Date Amount Description\"\n\n// Get start and end of credit table\ngo to page 1\n@transactionsTop1 = get line containing \"DEPOSITS/CREDITS\" => bottom => get line below\n@transactionsBottom1 = get line starting \"CHARGES/DEBITS\" => top => get line above\n\ndelete all lines starting \"There were no transactions\"\n\n// Discard header & footer\nignore footer below 20\nignore header above 675\n\n// Read the credit transactions\n@transactions1 = get multi page table @transactionsTop1 @transactionsBottom1 0 90 130 210 560 => describe table false \"*Date[MM/dd]\" - #Credit Details\n\n// Get start and end of debit table\ngo to page 1\n@transactionsTop2 = get line containing \"CHARGES/DEBITS\" => bottom => get line below\n@transactionsBottom2 = get line containing \"CHECKS PROCESSED\" => top => get line above\n// Read the debit transactions\n@transactions2 = get multi page table @transactionsTop2 @transactionsBottom2 0 90 130 210 560 => describe table false \"*Date[MM/dd]\" - #Debit Details\n\n$transactions = combine described tables @transactions1 @transactions2','2025-07-24 06:49:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10741,'Barclays_AccStatement_Ledger','$source = \"Barclays_AccStatement_Ledger\"\n\n// Get account name\n$accountName = get line containing \"Legal Entity\" => get words after \"Legal Entity\" => take words 3 => get text\n\n// Get account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Name\" => take words 1 => get text\n\n// Get dates\n@periodtxt = get line containing \"Entry Date Transaction Details\" => top => get line above\n$periodFrom = take words @periodtxt 1 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @periodtxt 1 => get date \"dd/MM/yyyy\"\n\n// Get balances\n$openingBalance = get line containing \"Balance Brought Forward\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Balance Carried Forward\" => take last words 1 => get decimal\n\ngo to page 1\n// Get top and bottom of the transactions table\n@transactionsTop = get line containing \"Balance Brought Forward\" => bottom => get line below\n\ndelete all lines starting \"Report Request Date\"\ndelete all lines starting \"Account Statement Report\"\ndelete all lines starting \"Entry Date Transaction Details\"\n\n@transactionsBottom = get last line containing \"Balance Carried Forward\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 90 280 460 560 700 780 => describe table false \"Date[dd/MM/yyyy]\" Details TransactionType *#Debit *#Credit #Balance','2025-07-24 06:50:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10742,'ScotiaBank_CurrentAccount','$source = \"ScotiaBank_CurrentAccount\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW NO_TRANSACTION_YEAR\"\n\n$periodBufferDays = 30\ndelete white words\n// Get Account Name\n//$accountName = get line containing \"Current Account -\" => get words after \"Current Account -\" => take words 1 => get text\n$accountName = get line containing \"Page created on\" => bottom => get line below => get words after \"-\" => take words 1 => get text\n\n// Get Account Number\n//$accountNumber = get line containing \"Current Account -\" => get words after \"Current Account -\" => take words 1 => get text\n$accountNumber = get line containing \"Page created on\" => bottom => get line below => get words after \"-\" => take words 1 => get text\nignore header above 765\n\n//Get PeriodInBOx\n\n@PeriodToTop = get line containing \"Date Description Withdrawals\" => bottom\n$PeriodToBox = get text in box @PeriodToTop 0 page.left 125\n$PeriodTo = take words $PeriodToBox 4 => take last words 3 => get date \"MMM.d,yyyy\"\n\ndelete all lines containing \"https\"\n\ngo to last page\n@test = get line above 0 => top => get line above => bottom\n$infoLast = get text in box page.top 0 0 130\n$PeriodFrom = take last words $infoLast 3 => get date \"MMM.d,yyyy\"\n\n\n//Get PeriodInBOx\n\n//@PeriodFromTop = get last line containing \"Date Description Withdrawals\" => bottom\n//$PeriodFromBox = get text in box @PeriodFromTop 0 page.left 125\n//$PeriodFrom = take last words $PeriodFromBox 3 => get date \"MMM.d,yyyy\"\n//go to page 1\n//@PeriodToTop = get line containing \"Date Description Withdrawals\" => bottom\n//$PeriodToBox = get text in box @PeriodToTop 0 page.left 125\n//$PeriodTo = take words $PeriodToBox 4 => take last words 3 => get date \"MMM.d,yyyy\"\n\n\ngo to page 1\n@TEXTBOXTop = get line containing \"Date Description Withdrawals\" => bottom\n$TEXTBOX = get text in box @TEXTBOXTop 0 500 page.right\n$openingBalance = take words $TEXTBOX 1 => get decimal\n\ngo to last page\n@TEXTBOXTop2 = get line above 0 => top => get line above => bottom\n$infoLast1 = get text in box page.top @test 500 page.right\n$closingBalance = take last words $infoLast1 1 => get decimal\n\ngo to page 1\n@transactionstop = get line starting \"Date Description Withdrawals\" => bottom => get line below\ngo to last page\n@transactionsbottom = get text in box 20 page.bottom page.left page.right => top => get line above\n\ndelete all lines starting \"Account Details | Scotiabank\"\ndelete all lines containing \"Date Description Withdrawals\"\n//ignore header above 680\n\n\n$transactions = get multi page table @transactionstop @transactionsbottom 32 94 115 350 326 526 595 => describe table false \"*Date[MMM.d]\" - Details - #Credit #Balance','2026-01-07 06:33:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10743,'CAESARS_REWARDS_VISA_Card','$source = \"CAESARS_REWARDS_VISA_Card\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 45\n//set negative marker \"-\"\n// Get Account Name\n$accountName = get text in box 110 100 50 page.middleX => take words 2 => get text\n\n// Get Account Number\n$AccountNumber = get line containing \"Account no.\" => get words after \"Account no.\" => take words 1 => get text\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"Previous balance\" => get words after \"Previous balance\" =>  take words 1 => get decimal\n$closingbalance = get line containing \"New balance\" => get words after \"New balance\" =>  take words 1 => get decimal\n\n//Get dates\ngo to page 1\n@PeriodFromTop = get line containing \"TRANS DATE TRANSACTION DESCRIPTION/LOCATION\" => bottom\n$PeriodFromBox = get text in box @PeriodFromTop page.bottom 5 90\n$PeriodFrom = take words $PeriodFromBox 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Statement closing date\" => get words after \"Statement closing date\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n@transactionstop = get line starting \"TRANS DATE TRANSACTION DESCRIPTION/LOCATION AMOUNT\" => bottom => get line below\ndelete all lines containing \"Interest charged\"\ndelete all lines containing \"Total Interest For This Period\"\ndelete all lines containing \"Fees\"\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\n@tranbottom1 = get line containing \"(CONTINUED)\" => top\n@b1 = delete text in box on every page @tranbottom1 page.bottom page.left page.right\n@transactionsbottom = get last line containing \"totals year to date\" => top => get line above\nremove page 2\n// stripping unwanted records from txns\ndelete all lines containing \"TRANS DATE TRANSACTION DESCRIPTION/LOCATION AMOUNT\"\ndelete all lines containing \"totals year to date\"\ndelete all lines containing \"Interest Charge on Cash Advances\"\n\nignore header above 815\nignore footer below 70\n\n$transactions = get multi page table @transactionstop @transactionsbottom  30 95 415 465 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit','2025-07-24 06:50:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10744,'CAF_Bank','$source = \"CAF_Bank\"\r\nset negative marker \"-\"\r\n\r\n@discards = get line containing \"Opening Balance as of\" => top => get line above => take words 5 => get text\r\n\r\n// Discard headings in top left of page 1\r\n@panelBottom = get line containing \"Date Description Type\" => top\r\ndelete text in box page.top @panelBottom 0 200\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n$accountName = get line containing \"Account Name:\" => get words after \"Account Name:\" => take words 3 => get text\r\n\r\n// Get period from/to\r\n$periodFrom = get line containing \"Opening Balance as of\" => get words after \"of\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Closing Balance as of\" => get words after \"of\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get opening and closing balances\r\n$openingBalance = get line containing \"Opening Balance as of\" => get words after \"of\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Closing Balance as of\" => get words after \"of\" => take last words 1 => get decimal\r\n\r\n// Get start and end of credit table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Description Type Money In\" => bottom => get line below\r\n@detailright = get line containing \"Date Description Type Money In\" => get words after \"Description\" => take words 1 => left => subtract 3\r\n@transactionsBottom = get line containing \"Information about\" => top => get line above\r\n\r\nignore header above 730\r\nignore footer below 90\r\ndelete all lines containing \"Closing Balance\"\r\ndelete all lines containing \"Date Description Type Money\"\r\ndelete all lines containing \"Opening Balance\"\r\ndelete all lines starting \"Account Name:\"\r\ndelete all lines starting \"Account Number:\"\r\ndelete all lines starting \"Sort Code:\"\r\ndelete all lines starting \"IBAN:\"\r\ndelete all lines starting @discards\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 51 110 @detailright 295 375 450 540 => describe table false \"*Date[dd/MM/yyyy]\" Details TransactionType #Credit #Debit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10745,'Investec_Transactions_Reverse','$source = \"Investec_Transactions_Reverse\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n// Get Account Name\n$accountName = get text in box page.top page.middleY page.left page.middleX => skip words 1 => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"account:\" => get words after \"account:\" => take words 1 => get text\ngo to page 1\n//Get Periods\n@periodText = get line starting \"Filter:\" => get words after \"Filter:\" => get text\n\n$periodFrom = get line containing @periodText => get words before \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing @periodText => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\n@closingTop = get line starting \"Transaction date Value date\" => bottom\n@closingBottom = get line starting \"Transaction date Value date\" => bottom => get line below => bottom\n@closingleft = get line starting \"Transaction date Value date\" => get words after \"Amount\" => take words 1 => left => subtract 5\n@closingright = get line starting \"Transaction date Value date\" => take last words 1 => right => add 5\n$closingBalance = get text in box @closingTop @closingBottom  @closingleft @closingright => get decimal\n\n//ignore footers\nget last line starting \"Entity:\" => top => ignore footer below\n\ngo to page 1\n@getAllColumns = get line containing \"Transaction date Value date\" => get text\n@dateLeft = get line containing @getAllColumns => take words 1 => left => subtract 10\n@date1Left = get line containing @getAllColumns => get words after \"Transaction date\" => take words 1 =>  left => subtract 5\n@detailsLeft = get line containing @getAllColumns => get words after \"Value date\" => take words 1 => left => subtract 5\n@amountLeft = get line containing @getAllColumns => get words after \"Statement reference\" => take words 1 => left => subtract 35\n$amountLeft1 = get line containing @getAllColumns => get words after \"Statement reference\" => take words 1 => left => subtract 35\n\n@amountRight = get line containing @getAllColumns => get words after \"Statement reference\" => take words 1 => right => add 10\n@balanceRight = get line containing @getAllColumns => take last words 1 => right => add 15\n\ngo to page 1\n// Get Transactions\n@transactionsTop = get line  starting \"Transaction date Value date\" =>  bottom => get line below\n$gotolastpage = get last line starting \"Transaction date Value date\" => bottom\n@transactionsBottom = get line above 0\n\n//ignore header\nget last line starting \"Transaction date Value date\" => top => ignore header above\ndelete all lines starting \"Transaction date Value date\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @date1Left @detailsLeft @amountLeft @amountRight @balanceRight => describe table false \"*Date[dd/MM/yyyy]\" - Details #Credit #Balance\n\n\n\n','2025-07-24 06:50:10',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10746,'BMOInvestorlineBank','$source = \"BMOInvestorlineBank\"\n\n\n$periodBufferDays = 30\n\n//get statement period\ngo to page 1\ndelete all lines starting \"Margin Account\"\n@period_top = get line containing \"Date Activity Description\" => bottom\n$periodfrom = get text in box @period_top page.bottom 60 120 => take words 3 => get date \"MMM d, yyyy\"\n\n$periodto = get line containing \"Closing Cash Balance\" => take words 3 => get date \"MMM dd, yyyy\"\n\ngo to page 1\n//get account number\n$accountnumber = get line containing \"Account:\" => get words after \"Account:\" => get text\n\n//get account name\n@bottom = get line containing \"Your Monthly Investment\" => top\n$accountname = get text in box page.top @bottom page.left page.middleX => take words 3 => get text\n\n\n//get opening/closing balance\n$openingbalance = get line containing \"Opening Cash Balance\" => get words after \"Opening Cash Balance\" => get decimal\n$closingbalance = get line containing \"Closing Cash Balance\" => get words after \"Closing Cash Balance\" => get decimal\n\ngo to page 1\n//get starting of transactions\n@transactionsTop = get line containing \"Opening Cash Balance\" => bottom => get line below\n\n\n//get last of transactions\n@transactionsBottom = get last line containing \"Closing Cash Balance\" => top => get line above\n\n\n\n//ignore header\nget last line containing \"Date Activity Description\" => bottom => ignore header above\n\n//ignore footer\nignore footer below 40\n\n//delete extra lines/text\ndelete all lines containing \"Date Activity Description\"\ndelete all lines containing \"Opening Cash Balance\"\ndelete all lines containing \"Closing Cash Balance\"\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 120 182 340 536 590 => describe table false \"*Date[MMM d, yyyy]\" TransactionType Details - #Credit','2025-07-24 06:50:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10747,'Barclays_Date_Posted_Narrative','$source = \"Barclays_Date_Posted_Narrative\"\n\n// delete extra left side text of summary\n@SummaryBottom = get line starting \"Date Posted Narrative Value Date Debit Credit Balance\" => top\ndelete text in box page.top @SummaryBottom page.left 550\n\n// Get account name and number\n$accountNumber = get line containing \"Account No:\" => get words after \"Account No:\" => take words 1 => get text\n$accountName = get line containing \"Account Title:\" => get words after \"Account Title:\" => get text\n\n// Get period from and Period to\n$periodFrom = get line containing \"Start Date:\" => get words after \"Start Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"End Date:\" => get words after \"End Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n\nset culture \"fr-FR\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\n$closingBalance =  get last line containing \"Closing balance\" => get words after \"Closing balance \" => get decimal\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"Date Posted Narrative Value Date Debit Credit Balance\" => bottom => get line below\n\n@detailLeft = get line containing \"Opening balance\" => get words before \"balance\" => take last words 1 => left => subtract 5\n\n// Get end of table\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\n//Discard page header and footer\nget last line containing \"Date Posted Narrative Value Date Debit Credit Balance\" => top => ignore header above\nignore footer below 85\n\ndelete all lines containing \"Opening balance\"\ndelete all lines containing \"Date Posted Narrative Value Date Debit Credit Balance\"\ndelete all lines containing \"This is an eligible deposit under the Deposit Guarantee Scheme\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 70 @detailLeft 405 475 565 655 750 => describe table false \"*Date[dd/MM/yyyy]\" Details ValueDate #Debit #Credit #Balance','2025-07-24 06:50:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10748,'IS_BANK_AccountCustomer','$source = \"IS_BANK_AccountCustomer\"\n$periodBufferDays = 28\nset negative marker \"-\"\n//set culture \"nl-NL\"\n\n//Get Accounts\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 2 => get text\n\n//Get Balances\n$openingBalance = get line containing \"Start Balance\" => get words after \"Start Balance\" => take words 1 =>  get decimal\n$closingBalance = get line containing \"End Balance\" => get words after \"End Balance\" => take words 1 => get decimal\n\n//Get Periods\n$periodFrom = get line containing \"Transaction Date Debit Credit Balance\" => bottom => get line below => take words 1 => get date \"d/M/yyyy\"\n@TEXTBOXTop1 = get last line containing \"Transaction Date Debit Credit\" => top\n@TEXTBOXBottom1 = get last line containing \"Turkiye Is Bankasi A.S. is authorised\" => top\n$TEXTBOX1 = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 10 115\n$periodTo = take last words $TEXTBOX1 1 => get date \"d/M/yyyy\"\n\ngo to page 1\n// Get start & end of transactions\n@transtionTop = get line containing \"Transaction Date Debit Credit Balance\" => bottom => get line below\n$ctrlLast = get last line containing \"Transaction Date Debit Credit\"\n@transtionBottom = get last line containing \"Page\" => top => get line above\n@tranbottom1 = get line containing \"Turkiye Is Bankasi A.S. is authorised and\" => top\n@b1 = delete text in box on every page @tranbottom1 page.bottom page.left page.right\n\ndelete all lines starting \"Transaction Date Debit Credit Balance\"\ndelete all lines ending \"Page\"\n\nignore header above 800\nignore footer below 50\n$transactions = get multi page table @transtionTop @transtionBottom 25 140 230 325 400 580 => describe table false \"Date[d/M/yyyy]\" *#Debit *#Credit #Balance Details','2025-07-24 06:50:12',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10749,'Firstmark_CreditUnion','$source = \"Firstmark_CreditUnion\"\n\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n//Get accounts\n@accountText = get line containing \"ACCOUNT NO.\" => get text\n@accountTop = get line containing @accountText => bottom\n@accountLeft = get line containing @accountText => get words before \"NO.\" => take last words 1 => left\n@accountRight = get line containing @accountText => get words after \"ACCOUNT\" => take words 1 => right\n$accountNumber = get text in box @accountTop 0 @accountLeft @accountRight => take words 1 => get text\n\ndelete all lines starting \"Return Service Requested\"\ndelete all lines starting \"STATEMENT\"\n$del_ = delete all pages containing \"DEPOSITS NOT CREDITED\"\n$del1_ = delete all pages containing \"ATM/POINT OF SALE\"\ngo to page 1\n$accountName = get text in box page.top 0 0 page.middleX => take words 4 => get text\n//Get Periods\n@periodsText = get line containing \"STATEMENT PERIOD\" => bottom => get line below => get text\n$periodFrom = get line containing @periodsText => get words before \"thru\" => take last words 1 => get date \"MM/dd/yy\"\n$periodTo = get line containing @periodsText => get words after \"thru\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get opening and closing Balances\ngo to page 1\n$openingBalance = get line starting \"BUSINESS\" => bottom =>  get line below => take last words 1 => get text\n$closingBalance = 0.0\ngo to page 1\n// Get start and end of BusinessSaving table\n@transactionsBusinessSavingTop = get line starting \"BUSINESS SAVINGS\" => if not found then blank => bottom => get line below\n@transactionsBusinessSavingBottom = get line containing \"Ending Balance\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Deposits and Other Credits\"\ndelete all lines starting \"BUSINESS SAVINGS\"\ndelete all lines starting \"FIRSTMARK CREDIT UNION\"\ndelete all lines containing \"ACCOUNT NUMBER\"\ndelete all lines containing \"thru\"\ndelete all lines starting \"POSTING\"\ndelete all lines starting \"DATE\"\n// Read the transactions of 1st tables\n\n@transactionsBusinessSaving = get multi page table @transactionsBusinessSavingTop @transactionsBusinessSavingBottom 0 @accountLeft @accountRight 510 => describe table false  Details - *#Credit\n\ngo to page 1\n@top_ = get line containing \"Continued on\" => if not found then blank => bottom\n@del_ = delete text in box @top_ 0 0 page.right => get text\ndelete all lines containing \"Continued on\"\n\ngo to page 1\n\n// Get start and end of table of 2nd tables\n@transactionsBusinessCheckingTop = get line starting \"BUSINESS CHECKING\" => if not found then blank => bottom => get line below\n@transactionsBusinessCheckingBottom = get last line containing \"Ending Balance\" => if not found then blank => top => get line above\n\ndelete all lines starting \"BUSINESS CHECKING\"\ndelete all lines starting \"FIRSTMARK CREDIT UNION\"\ndelete all lines containing \"ACCOUNT NUMBER\"\ndelete all lines containing \"thru\"\ndelete all lines starting \"POSTING\"\ndelete all lines starting \"DATE\"\nignore header above 760\n\n@transactionsBusinessChecking = get multi page table @transactionsBusinessCheckingTop @transactionsBusinessCheckingBottom 0 @accountLeft @accountRight 510 => describe table false  Details - *#Credit\n// Read the transactions\n$transactions = combine described tables @transactionsBusinessSaving @transactionsBusinessChecking\n','2025-07-24 06:50:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10750,'RMB_CreditCard','$source = \"RMB_CreditCard\"\n$periodBufferDays = 30\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\nset negative marker \"Cr\"\n\n$accountName = get line starting \"RMB PRIVATE BANK CREDIT CARD\" => take last words 4 => get text\n$accountNumber = get line starting \"RMB PRIVATE BANK CREDIT CARD\" => take last words 4 => get text\n\n$periodTo = get line starting \"Statement Date\" => take last words 3 => get date \"dd MMM yyyy\"\n\n$periodFromtext = get line starting \"Opening Balance\" => bottom => get line below => bottom\n$periodFrom = get text in box $periodFromtext page.bottom page.left 55 => take words 2 =>  get date \"dd MMM\"\n\ngo to page 1\n//Get opening/closing balance\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 2 => get decimal\n$closingBalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 2 => get decimal\n\ngo to page 1\n@transactionTop = get line starting \"Opening Balance\" => bottom =>  get line below\n@transactionBottom = get last line starting \"Closing Balance\" => top => get line above\n\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Card Total\"\ndelete all lines containing \"Card No. \"\n\n//Transactions\n$transactions = get multi page table @transactionTop @transactionBottom 20 55 300 372 => describe table false  \"Date[d MMM]\" Details *#Credit\n','2025-07-24 06:50:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10751,'MarblesBank','$source = \"MarblesBank\"\r\n\r\n$features = \"CREDIT_CARD\"\r\nset negative marker \"cr\"\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\r\n\r\n// Get account name\r\n@top = get line containing \"Available to spend\" => bottom\r\n@bottom = get line containing \"Statement date:\" => top\r\n$accountName = get text in box @top @bottom page.left page.middleX => take words 3 => get text\r\n\r\n\r\n// Get period from/to\r\n$periodFrom = get line starting \"Opening Balance\" => bottom => get line below => take words 3 => get date \"dd MMM yyyy\"\r\n\r\ngo to page 1\r\n$periodto = get line containing \"Statement date:\" => get words after \"Statement date:\" => take words 3 => get date \"dd MMMM yyyy\"\r\n\r\n//get opening balance\r\n$openingbalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\r\n\r\n//get closing balance\r\n$closingBalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => get decimal\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\r\n\r\n\r\n// Get end of table\r\n@transactionsBottom = get line containing \"Your new balance\" => top => get line above\r\n\r\nignore header above 800\r\nignore footer below 32\r\n\r\ngo to page 1\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 75 350 575 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10752,'StanbicBank','$source = \"StanbicBank\"\n\n@Summarytop = get line containing \"Statement date :\" => top\n@Summarybottom = get line containing \"Account number :\" => bottom\n@Summary = get text in box @Summarytop @Summarybottom page.middleX 600\n\n$periodFrom = get words after @Summary \"Statement date :\" => get words between \"date :\" \"to\" => get date \"dMyyyy\"\n$periodTo = get words after @Summary \"to\" => take words 1 => get date \"dMyyyy\"\n\n$accountNumber = get words after @Summary \"Account number :\" => get text\n\n$accountName = get text in box page.top @Summarytop 0 page.middleX => skip words 4 => take words 2 => get text\n\n@transactionsTop = get line containing \"Opening balance\" => bottom => get line below\n$OpeningBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\n@transactionsBottom = get last line starting \"Closing balance\" => top => get line above\n$ClosingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Opening balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\n\ndelete all lines containing \"Transaction description\"\nignore header above 735\nignore footer below 45\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 72 115 375 437 497 590 => describe table false \"*Date[dMyyyy]\" - Details #Debit #Credit #Balance','2025-07-24 06:50:55',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10753,'Pioneer_Bank','$source = \"Pioneer_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\n\nremove page 2\ndelete text in box on every page page.top page.bottom 0 50\n\n// Get account name\n$accountName = get line containing \"Account Owner(s):\" => get words after \"Account Owner(s):\" => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take last words 1 => get text\n\n// Get period from/to\n$periodFrom = get line starting \"Beginning Balance as of\" => get words after \"of\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line starting \"Ending Balance as of\" => get words after \"of\" => take words 1 => get date \"MM/dd/yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line starting \"Beginning Balance as of\" => get words after \"of\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance as of\" => get words after \"of\" => take last words 1 => get decimal\n\n//get date column dynamic_coordinates\ngo to page 1\n$Date_left = get line containing \"Date Description Deposits Withdrawals Balance\" => get words before \"Description\" => left => subtract 5\n$Detail_left = get line containing \"Date Description Deposits Withdrawals Balance\" => get words after \"Date\" => left => subtract 5\n$Credit_left = get line containing \"Date Description Deposits Withdrawals Balance\" => get words after \"Description\" => left => subtract 2\n$Debit_left = get line containing \"Date Description Deposits Withdrawals Balance\" => get words after \"Deposits\" => left => subtract 2\n$Balance_left = get line containing \"Date Description Deposits Withdrawals Balance\" => get words after \"Withdrawals\" => left => subtract 15\n$Balance_right = get line containing \"Date Description Deposits Withdrawals Balance\" => get words after \"Withdrawals\" => left => add 5\n\n// Get start and end of credit table\ngo to page 1\n@transactionsTop = get line containing \"Date Description Deposits Withdrawals Balance\" => bottom => get line below\n@transactionsBottom = get line containing \"ENDING BALANCE\" => top => get line above\n\nignore header above 670\nignore footer below 25\ndelete all lines containing \"ENDING BALANCE\"\ndelete all lines containing \"Date Description Deposits Withdrawals Balance\"\ndelete all lines containing \"BEGINNING BALANCE\"\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 51 85 325 425 500 580 => describe table false \"*Date[MMM dd]\" Details #Credit #Debit #Balance\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Detail_left $Credit_left $Debit_left $Balance_left $Balance_right => describe table false \"*Date[MMM dd]\" Details #Credit #Debit #Balance','2025-07-31 08:11:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10754,'BELLEVILLE_Bank','$source = \"BELLEVILLE_Bank\"\n$periodBufferDays = 28\n//Get Accounts\n$accountNumber = get line containing \"Account No.:\" => get words after \"Account No.:\" => take words 1 => get decimal\n$accountName = get text in box page.top 0 0 page.right => take words 1 => get text\n\n//Get Periods\n$periodFrom = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" => take words 1 => get date \"MM/dd/yy\"\n\ngo to page 1\n//Get Balances\n$openingBalance = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" =>  take last words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" => take last words 1 => get decimal\n\ngo to page 1\n// Get start & end of all (Date Type columns) - Credits table\n@creditsTypeTop = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\n@creditsTypeBottom = get line starting \"Date Description\" => if not found then blank => top => get line above\n\n@creditsTypeLeft = get multi page table @creditsTypeTop @creditsTypeBottom 35 95 149 218 => describe table false \"*Date[MM/dd/yy]\" Details *#Credit\n@creditsTypeMiddle = get multi page table @creditsTypeTop @creditsTypeBottom 220 267 326 394 => describe table false \"*Date[MM/dd/yy]\" Details *#Credit\n@creditsTypeRight = get multi page table @creditsTypeTop @creditsTypeBottom 395 442 501 575 => describe table false \"*Date[MM/dd/yy]\" Details *#Credit\n\ngo to page 1\nget line starting \"Statement Date\" => top => ignore header above\nget line starting \"Continued\" => top => ignore footer below\ndelete all lines starting \"Statement Date\"\ndelete all lines containing \"Account No\"\ndelete all lines starting \"Continued\"\ndelete all lines starting \"ALL CREDIT ACTIVITY\"\ndelete all lines starting \"ANALYZED CHECKING SUMMARY\"\ndelete all lines starting \"Category\"\ndelete all lines starting \"Balance Forward\"\ndelete all lines starting \"Deposits\"\ndelete all lines starting \"Debits\"\ndelete all lines starting \"Automatic\"\ndelete all lines starting \"Card Activity\"\ndelete all lines starting \"Miscellaneous\"\ndelete all lines starting \"Ending Balance\"\ndelete all lines starting \"Average Balance\"\n\ngo to page 1\n// Get start & end of cheques table\n@chequeTop = get line starting \"Date Check # Amount\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 35 99 152 218 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\n@chequeCenter = get multi page table @chequeTop @chequebottom 220 276 326 393 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\n@chequeRight = get multi page table @chequeTop @chequebottom 395 453 512 575 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\n\ngo to page 1\ndelete all lines starting \"Date Type Amount\"\ndelete all lines starting \"CHECKS AND OTHER DEBITS\"\ndelete all lines containing \"indicates a gap in the check numbers\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount\" => get text\n@dateleft_ = get line containing @tranactionColumns => take words 1 => left => subtract 6\n@dateright = get line containing @tranactionColumns => take words 1 => right => add 25\n@amountleft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => right => subtract 50\n@amountright =   get line containing @tranactionColumns => take last words 1 => right => add 15\n\ngo to page 1\n// Get start & end of all Credits table\n@creditsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line above\ndelete all lines starting \"Date Description Amount\"\n// Read the transactions of credits and debits\n@credits = get multi page table @creditsTop @creditsBottom @dateleft_ @dateright @amountleft @amountright => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n\n// Get start & end of all Debits table\n@debitsTop = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line below\n@Check_top = get line starting \"Date Check # Amount\" => if not found then blank => bottom\n@debitsBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\n// Remove Checks\n@checkdelete = delete text in box  @Check_top 0 0 page.right => get text\ndelete all lines starting \"Date Check # Amount\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"ELECTRONIC DEBITS\"\ndelete all lines starting \"DAILY BALANCE SUMMARY\"\ndelete all lines starting \"CHECKS AND OTHER DEBITS\"\ndelete all lines containing \"indicates a gap in the check numbers\"\n\n@debits = get multi page table @debitsTop @debitsBottom @dateleft_ @dateright @amountleft @amountright  => describe table false \"Date[MM/dd/yy]\" Details *#Debit\n//ignore header above 538\n//ignore footer below 40\n$transactions = combine described tables @credits @debits @creditsTypeLeft @creditsTypeMiddle @creditsTypeRight  @chequeLeft @chequeCenter @chequeRight\n','2025-07-24 06:51:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10755,'Anderson_Brothers_Bank','$source = \"Anderson_Brothers_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n//set negative marker \"-\"\n// Get Account Name\n$accountName = get text in box 648 620 50 page.middleX => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//Get dates\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words before \"thru\" => get date \"MM/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"MM/dd/yy\"\n\n//OpeningClosingBalance\ngo to page 1\n$openingbalance = get last line containing \"Balance Forward\" => get words after \"Balance Forward\" => take words 1 => get decimal\n$closingbalance = get last line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\n//Checks\n\ngo to page 1\n@checksTop = get line containing \"Check No\" => if not found then blank => bottom => get line below\ndelete all lines containing \"* DENOTES\"\n@checksBottom = get last line containing \"Check No\" => if not found then blank => bottom => get break below => get line at\ngo to page 1\nignore header above 500\nignore footer below 5\n\n//delete all lines containing \"Check No\"\n//delete all lines containing \"* DENOTES\"\n$checksLeft = get multi page table @checksTop @checksBottom 18 60 110 160 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\ndelete all lines containing \"* DENOTES\"\n$checksMiddle = get multi page table @checksTop @checksBottom 153 196 235 293 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n$checksRight = get multi page table @checksTop @checksBottom 288 325 385 420 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\ndelete all lines containing \"Check No\"\n// Get start & end of Credits\n\ngo to page 1\n@CreditsTop = get line containing \"Description\" => if not found then blank => bottom => get line below\ndelete all lines containing \"Description\"\ndelete all lines containing \"DEPOSITS AND OTHER CREDITS\"\ndelete all lines containing \"DEBITS\"\n@CreditsBottom = get line containing \"CHECKS POSTED\" => if not found then blank => top => get line above\n$Credits = get multi page table @CreditsTop @CreditsBottom 25 75 260 340 => describe table false \"*Date[MM/dd]\" Details #Credit\n\n$transactions = combine described tables $Credits $checksLeft $checksMiddle $checksRight\n\n','2025-07-24 06:51:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10756,'WesBank','$source = \"WesBank\"\n\nset negative marker \"DR\"\n\n// Get account name\n$accountName = get text in box 695 660 page.left page.middleX => take words 2 => get text\n\n// Get account number\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number :\" => take words 1 => get text\n\n// Get period From/To dates\n$periodFrom = get line containing \"Statement Period :\" => get words after \":\" => take words 1 => get date \"yyyy/MM/dd\"\n$periodTo = get line containing \"Statement Period :\" => get words after \":\" => take last words 1 => get date \"yyyy/MM/dd\"\n\n// Get opening/closing balances\n$openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => take last words 2 => get decimal\n$closingBalance = get line containing \"BALANCE CARRIED FORWARD\" => take last words 2 => get decimal\n\n// Get top and bottom of the transactions table\n@transactionsTop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n\ndelete all lines starting \"DE-ESCALATION\"\ndelete all lines starting \"ESCALATION\"\n\n@transactionsBottom = get line containing \"BALANCE CARRIED FORWARD\" => top => get line above\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 10 250 350 460 560 => describe table false Details \"Date[yyyy/MM/dd]\" *#Credit #Balance','2025-07-24 06:51:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10757,'Westpac_NZ','$source = \"Westpac_NZ\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n\nset negative marker \"OD\"\n\n// Get account name\n$accountName = get line starting \"Account name:\" => get words after \":\" => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => get words after \"number:\" => get text\n\n// Get period from/to\ngo to page 1\n@Datestop = get line containing \"date:\" => top\n@Datesbottom = get line containing \"date:\" => bottom => get line below => bottom\n@Dates = get text in box @Datestop @Datesbottom page.middleX 560\n\n$periodFrom = get words after @Dates \"date:\" => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get words after @Dates \"date:\"  => take last words 3 => get date \"d MMM yyyy\"\n\n\n// Get opening and closing balances\n//$openingBalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => take words 1 => get decimal\n$openingBalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\n//$closingBalance = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => take words 1 => get decimal\n$closingBalance = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => get decimal\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line starting \"DATE TYPE NAME OF OTHER PARTY\" => bottom => get line below\n@transactionsBottom = get line starting \"CLOSING BALANCE\" => top => get line above\n\ndelete all lines starting \"Reconciling your account\"\ndelete all lines starting \"because of unpresented\"\ndelete all lines starting \"this statement and\"\ndelete all lines starting \"You can get a copy\"\ndelete all lines starting \"westpac.co.nz\"\n\n// Discard header & footer\nget last line starting \"DATE TYPE NAME OF OTHER PARTY\" => top => ignore header above\nignore footer below 42\ndelete all lines starting \"DATE TYPE NAME OF OTHER PARTY\"\ndelete all lines starting \"(Units Redeemed)\"\ndelete all lines containing \"OD Overdrawn AP Automatic payment\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 76 200 335 410 480 560 => describe table false \"*Date[dd MMM]\" TransactionType Details *#Debit *#Credit #Balance','2026-01-07 06:33:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10758,'TideBank_Card','$source = \"TideBank_Card\"\n$features = \"REVERSE_ORDER SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get Account Name\n$accountname = get line containing \"account number:\" => top => get line above => take words 2 => get text\n\n// Get Account Number\n$accountnumber = \"Incorrect_Account\"\n\nset negative marker \"-\"\n\n//Get PeriodInBOx\n\n@PeriodFromTop = get last line containing \"Date Transaction type Details Paid in (£)\" => bottom\n@PeriodFromBottom = get last line containing \"Card Legal\" => top\n$PeriodFromBox = get text in box @PeriodFromTop @PeriodFromBottom page.left 115\n$PeriodFrom = take last words $PeriodFromBox 3 => get date \"d MMM yyyy\"\ngo to page 1\n@PeriodToTop = get line containing \"Date Transaction type Details Paid in (£)\" => bottom\n@PeriodToBottom = get line containing \"Card Legal\" => top\n$PeriodToBox = get text in box @PeriodToTop @PeriodToBottom page.left 115\n$PeriodTo = take words $PeriodToBox 3 => get date \"d MMM yyyy\"\n\n$openingbalance = 0\n$closingbalance = 0\n\n//get date column dynamic_coordinates\ngo to page 1\n$Date_left = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words before \"Transaction\" => left => subtract 5\n$Type_left = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words after \"Date\" => left => subtract 5\n$Detail_left = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words after \"Transaction type\" => left => subtract 5\n$Credit_left = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words after \"Details\" => left => subtract 2\n$Debit_left = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words after \"Paid in (£)\" => left => subtract 2\n$Debit_right = get line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => get words after \"Paid in (£)\" => right => add 1\n\ngo to page 1\n$transactionsTop = get line containing \"Date Transaction type Details Paid in (£)\" => bottom => get line below\n\n$ctrlLast = get last line containing \"Card Legal\"\n@tranbottom1 = get line containing \"Card Legal\" => bottom\n$b1 = delete text in box on every page @tranbottom1 page.bottom page.left page.right\n$transactionsBottom = get last line containing \"Card Legal\" => top => get line above\n\nget line containing \"Date Transaction type Details Paid in (£) Paid out (£)\" => bottom => ignore header above\ndelete all lines containing \"Date Transaction type Details Paid\"\ndelete all lines containing \"Card Legal\"\n// Read the transactions\n\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 15.5 35 110 215 460 500 555 => describe table false \"*Date[d MMM yyyy]\" TransactionType Details #Credit #Debit\n//$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 8 35 110 215 438 500 555 => describe table false \"*Date[d MMM yyyy]\" TransactionType Details #Credit #Debit\n$transactions = get multi page table center aligned $transactionsTop $transactionsBottom 7.5 $Date_left $Type_left $Detail_left $Credit_left $Debit_left $Debit_right => describe table false \"Date[d MMM yyyy]\" TransactionType Details #Credit #Debit','2025-07-24 06:51:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10759,'StandardBank_SouthAfrica_BESIGHEIDS','$source = \"StandardBank_SouthAfrica_BESIGHEIDS\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Parse amounts in  Afrikaans\nset culture \"af-ZA\"\n\n// Get account name\n$accountName = get line containing \"Rekeningnommer\" => get words after \"Rekeningnommer\" =>  take words 4 => get text\n\n// Get account number\n$accountNumber = get line containing \"Rekeningnommer\" => get words after \"Rekeningnommer\" =>  take words 4 => get text\n\n// Get Period from and Period To\n$statementPeriod = get line starting \"Staat van\" => take last words 7\n$periodFrom = take words $statementPeriod 3 => get date \"dd MMMM yyyy\"\n@statementPeriodTo = get last line starting \"Staat van\" => take last words 7\n$periodTo = skip words @statementPeriodTo 4 => get date \"dd MMMM yyyy\"\n\ngo to page 1\n// Get start & end of transactions table\n@transactionsTop = get line starting \"SALDO OORGEBRING\"  => bottom => get line below\n\n$detailRight = get line containing \"Besonderhede Diensgeld\" => get words after \"Besonderhede\" => take words 1 => left\n$ServicefeeRight = get line containing \"Besonderhede Diensgeld\" => get words after \"Besonderhede\" => take words 1 => right\n$CreditRight = get line containing \"Datum Saldo\" => get words before \"Saldo\" => take last words 1 => left => subtract 5\n$DateRight = get line containing \"Datum Saldo\" => get words before \"Saldo\" => take last words 1 => right => add 5\n\ngo to page 1\n// Get opening balances\n$openingBalance = get line starting \"SALDO OORGEBRING\" => take last words 1 => get decimal\n\n// Get Closing Balance\ngo to last page\n@pageFooter = get last line starting \"## Hierdie fooie\" => top\n@infoLast = get text in box page.top @pageFooter 450 page.right\n$closingBalanceText = take last words @infoLast 1 => get text\n$closingBalance = take last words @infoLast 1 => get decimal\n\ngo to page 1\n@transactionsBottom = get last line starting \"## Hierdie fooie sluit\" => top => get line above\n\n// Discard page header and footer\nget last line starting \"SALDO OORGEBRING\" => top => ignore header above\nget line starting \"Die Standard Bank van\" => top => ignore footer below\ndelete all lines starting \"## Hierdie fooie\"\ndelete all lines starting \"** Hierdie\"\ndelete all lines containing \"Verifieer asseblief alle transaksies\"\n\n// Remove unwanted lines\ndelete all lines starting \"Besonderhede Diensgeld\"\ndelete all lines starting \"Krediete Datum Saldo\"\ndelete all lines starting \"Debiete\"\ndelete all lines containing \"SALDO OORGEBRING\"\n\n\n// Read the transactions\n$transactions  = get multi page table @transactionsTop @transactionsBottom 35 $detailRight $ServicefeeRight $CreditRight $DateRight 540 => describe table false Details - #Credit \"Date[MM dd]\" *#Balance','2025-07-24 06:51:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10760,'Bankwest_Bank_Creditcard','$source = \"Bankwest_Bank_Creditcard\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 28\n\n// Get account name and number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 4 => get text\n$accountName = get text in box page.top page.middleY 0 page.middleX => take words 4 => get text\n\n//Get Periods\n@periodTop = get line containing \"Account number\" => get words before \"number\" => take last words 1 => bottom\n@periodLeft = get line containing \"Account number\" => get words before \"number\" => take last words 1 => left => subtract 5\n@periodText = get text in box @periodTop 0  @periodLeft page.right => get words after \"Period\"\n$periodFrom = get words before @periodText \"-\" => take words 3 => get date \"dd MMM yy\"\n$periodTo = get words after @periodText \"-\" => take words 3 => get date \"dd MMM yy\"\n\n//Get Opening and Closing Balances\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Debit Credit\" => get text\n$dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n$detailsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 5\n$debitleft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 20\n$debitright = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => right => add 5\n$creditlright =   get line containing @tranactionColumns => take last words 1 => right => add 10\n\ngo to page 1\n// Read the transactions\n@transtionTop = get line starting \"Date Description Debit Credit\" => bottom => get line below\n//$gotolastTransBottom = get last line starting \"Date Description Debit Credit\"\n@transactionsbottom = get last line containing \"Closing balance\" => top => get line above\n//@transactionsbottom = get line above 0 => top => get line above\n\ngo to page 1\ndelete all lines starting \"Date Description\"\ndelete all lines starting \"Opening balance\"\ndelete all lines starting \"Closing balance\"\ndelete all lines starting \"Your transactions\"\n\nignore header above 790\nignore footer below 50\n\n$transactions = get multi page table @transtionTop @transactionsbottom $dateleft $detailsleft $debitleft $debitright $creditlright => describe table false \"*Date[dd MMM yy]\" Details #Credit #Debit\n','2025-07-24 06:51:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10761,'Paypal_AlignedCenter_MultiAccount_French','$source = \"Paypal_AlignedCenter_MultiAccount_French\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get Account Name\n$accountname = get line starting \"Relevé pour\" => bottom => get line below => get text\n\n// Get Account Number\n$accountnumber = get line containing \"Identifiant de compte marchand:\" => get words after \"Identifiant de compte marchand:\" => get words before \"Identifiant PayPal:\" => get text\n\n// Get Period From/To\n@period = get line starting \"Récapitulatif du solde\" => get words after \"Récapitulatif du solde\"\n$periodFrom = take words @period 1 => get date \"M/d/yyyy\"\n$periodto = get words after @period \"-\" => get date \"M/d/yyyy\"\n\nset culture \"fr-CA\"\n\n// Get Opening/Closing balance\n$openingbalance = get line containing \"Solde disponible de début\" => get words after \"Solde disponible de début\" => take words 1 => get decimal\n$closingbalance = get line starting \"Solde disponible de fin\" => get words after \"Solde disponible de fin\" => take words 1 => get decimal\n\n// Get start of table\n@transactionsTop = get line starting \"Historique des transactions\" => bottom => get line below => top => get line above\n\nignore header above 725\nignore footer below 117\n\n// Get end of transactions table\n@lastTranpage = get last line starting \"Date Description\"\n@transactionsBottom = get line above 0\n\ndelete all lines starting \"Date Description\"\n\n// Read the transactions\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 40 90 240 410 502 560 => describe table false \"Date[M/d/yyyy]\" Details TransactionType - #Credit','2025-07-24 06:51:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10762,'Standard_Bank_Online_Banking','$source = \"Standard_Bank_Online_Banking\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE NO_TRANSACTION_YEAR\"\n//OPENING_BALANCE_FROM_FIRST_ROW\n$periodBufferDays = 30\n//set negative marker \"-\"\n// Get Account Name\n$accountName = get line containing \"Name of account holder:\" => get words after \"Name of account holder:\" => take words 2 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 4 => take last words 2 => get text\n\n//Get PeriodInBOx\n$PeriodFrom = get line containing \"Transactions date range:\" => get words after \"Transactions date range:\" => get words before \"-\" => take words 3 => get date \"d MMMM yyyy\"\n$PeriodTo = get line containing \"Transactions date range:\" => get words after \"Transactions date range:\" => get words after \"-\" => take words 3 => get date \"d MMMM yyyy\"\n\n//Get TextInBOx\ngo to page 1\n@TEXTBOXTop1 = get line containing \"(R) (R)\" => bottom\n$TEXTBOX1 = get text in box @TEXTBOXTop1 0 490 page.right\n$closingBalance = take words $TEXTBOX1 2 => get decimal\n//$openingBalance = 0\n\n@TEXTBOXTop = get last line containing \"Standard Bank Online Banking\" => bottom\n@TEXTBOXBottom = get last line containing \"# These fees are zero rated\" => top\n$TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 490 page.right\n//$openingBalance = take last words $TEXTBOX 2 => get decimal\n//$closingBalance = 25589.63\n\ngo to page 1\n@transactionstop = get line containing \"Description In (R)\" => bottom => get line below\n\n@delTop = get line containing \"* Bank\" => top\n@delBottom = get line containing \"bundle\" => bottom => get line below => bottom => get line below  => bottom\n$Delete_1st_Transction = delete text in box @delTop @delBottom 0 page.right => get text\n\n@transactionsbottom = get last line containing \"# These fees are zero rated\" => top => get line above\n\ndelete all lines containing \"Description In (R)\"\ndelete all lines containing \"(R)\"\ndelete all lines containing \"transact\"\ndelete all lines containing \"https://onlinebanking\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"Standard Bank Online Banking\"\ndelete all lines containing \"These fees are zero rated\"\n\nignore header above 815\nignore footer below 50\n// Read the transactions\n\n$transactions = get multi page table center aligned @transactionstop @transactionsbottom 16 0 80 300 440 => describe table false \"Date[dd MMM]\" Details #Credit','2025-07-24 06:51:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10763,'FirstNationalBank_InterestTrans','$source = \"FirstNationalBank_InterestTrans\"\n$periodBufferDays = 14\n\n// Get account name\n$accountName = get text in box 700 660 page.left page.middleX => take words 4  => get text\n\n// Get account Number\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get Period from/To\n$periodfrom = get line containing \"Statement Period\" => get words after \"Period\" => take words 3 => get date \"dd MMMM yyyy\"\n$periodTo = get line containing \"Statement Period\" => get words after \"Period\" => take last words 3 => get date \"dd MMMM yyyy\"\n\n// Get Opening/Closing balances\n$OpeningBalance = get line containing \"Opening Balance as at\" => get words after \"ZAR\" => get decimal\n$ClosingBalance = get line containing \"Closing Balance as at\" => get words after \"ZAR\" => get decimal\n\nset negative marker \"Cr\"\n\ngo to page 1\n// Get start and end of transactions table\n@transactionsTop = get line containing \"Opening Balance as at\" => bottom => get line below\n@transactionsBottom = get line containing \"Closing Balance as at\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 120 320 450 => describe table false \"*Date[ddMMMyyyy]\" Details #Debit','2025-07-24 06:51:10',0);
