INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10767,'FirstState_Bank','$source = \"FirstState_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 28\n\n// Get Accounts\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\ndelete all lines starting \"P O Box\"\n$accountname = get text in box page.top 0 0 page.middleX => take words 3 => get text\n\n//Get Balances\n$openingBalance = get line starting \"Opening balance\" => get words after \"Opening balance on\" => take words 4 => take last words 1 => get decimal\n$closingBalance = get line starting \"Closing balance\" => get words after \"Closing balance on\" => take words 4 => take last words 1 => get decimal\n\ngo to page 1\ndelete all pages containing \"BALANCING YOUR ACCOUNT\"\ndelete all pages containing \"IMPORTANT INFORMATION\"\n\ngo to page 1\n//Get Periods\n$periodFrom = get line starting \"Opening balance\" => get words after \"Opening balance on\" => take words 4 => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get line starting \"Closing balance\" => get words after \"Closing balance on\" => take words 4 => take words 3 => get date \"d MMM yyyy\"\n\ngo to page 1\n@checksTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get line containing \"Indicates Break in Check Number Sequence\" => if not found then blank => top => get line above\n@ChecksL = get multi page table @checksTop @checksBottom 30 90 145 215 => describe table false \"*Date[M/dd]\" ChequeNumber #Debit\n@ChecksM = get multi page table @checksTop @checksBottom 218 280 322 403 => describe table false  \"*Date[M/dd]\" ChequeNumber #Debit\n\n\n@chkTop = get line starting \"Date Check No Amount\" => if not found then blank => bottom\n@chkBottom = get line containing \"Indicates Break in Check Number Sequence\" => if not found then blank => bottom\n@delchecks =  delete text in box @chkTop  @chkBottom 0 page.right => get text\ndelete all lines starting \"Checks in Number Order\"\ndelete all lines starting \"Date Check No Amount\"\ndelete all lines containing \"Indicates Break in Check Number Sequence\"\n\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount\" => get text\n@dateleft =  get line containing @tranactionColumns => take words 1 => left => subtract 5\n@detailsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 5\n@amountleft  = get line containing @tranactionColumns => get words after \"Description\" => left => subtract 35\n@amountright = get line containing @tranactionColumns => get words after \"Description\" => right => add 20\n\n@transtionTop = get line starting \"Date Description Amount\" => bottom => get line below\n@transactionBottom = get line starting \"Daily Balance Information\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"Paper Statement Charge\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Service Charges and Itemized Fees\"\ndelete all lines starting \"Other Debits\"\ndelete all lines starting \"Deposits and Other Credits\"\nignore header above 660\nignore footer below 50\n\n@creditDebitTrans = get multi page table @transtionTop @transactionBottom @dateleft @detailsleft @amountleft @amountright => describe table false \"*Date[M/dd]\" Details #Credit\n$transactions = combine described tables @creditDebitTrans @ChecksL @ChecksM\n','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10768,'RBC_DATE_DATE_CHEQUE_TRANSACTION','$source = \"RBC_DATE_DATE_CHEQUE_TRANSACTION\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account name and number\n$accountName = get text in box 650 620 page.left 340 => take words 1 => get text\n\n//deleted left side text to grab account no\n@SummaryTop = get line containing \"Period From:\" => top\ndelete text in box page.top @SummaryTop page.left 340\n\n$accountNumber = get line containing \"Account Number/Currency\" => bottom => get line below => take last words 2 => take words 1 => get text\n\ndelete text in box on every page page.top page.bottom page.left 55\n\ngo to page 1\n// Get period from and Period to\n$periodFrom = get line containing \"Period From:\" => get words after \"Period From:\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"Period From:\" => get words after \"To:\" => take words 1 => get date \"dd/MM/yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1  => get decimal\n$closingBalance =  get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get start of table\n@transactionsTop = get line starting \"DATE DATE CHEQUE/TRANSACTION NUMBER AMOUNT BALANCE\" => bottom => get line below\n\n// Get end of table\nget last line containing \"DATE DATE CHEQUE/TRANSACTION NUMBER AMOUNT BALANCE\"\n@transactionsBottom = get line above 24\n\n//Discard page header and footer\nget last line containing \"DATE DATE CHEQUE/TRANSACTION NUMBER AMOUNT BALANCE\" => top => ignore header above\nignore footer below 26\n\ndelete all lines containing \"BOOK VALUE DESCRIPTION AND\"\ndelete all lines containing \"DATE DATE CHEQUE/TRANSACTION NUMBER AMOUNT BALANCE\"\ndelete all lines containing \"(dd/mm) (dd/mm)\"\ndelete all lines containing \"This is an eligible deposit under the Deposit Guarantee Scheme\"\n\n@LastFooterTop = get line containing \"Valued clients, you are advised\" => top\ndelete text in box @LastFooterTop page.bottom page.left page.right\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 90 126 385 500 page.right => describe table false \"*Date[ddMM]\" - Details #Credit #Balance','2025-07-31 08:11:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10769,'BBVA_US','$source = \"BBVA_US\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n@accountDetailstop = get line containing \"Account Number:\" => top\n@accountDetailsbottom = get line containing \"Account Number:\" => bottom\n@accountDetails = get text in box @accountDetailstop @accountDetailsbottom 0 page.middleX\n$accountNumber = get words after @accountDetails \"Account Number:\" => get words between \"Number:\" \"-\" => get text\n$accountName = get words after @accountDetails \"-\" => get text\n\n@SummaryTop = get line containing \"Beginning Balance on\" => top\n@SummaryBottom = get line containing \"Ending Balance on\" => bottom\n@Summary = get text in box @SummaryTop @SummaryBottom 0 page.middleX\n\n$periodFrom = get words after @Summary \"Beginning Balance on\" => take words 1 => get date \"M/d/yy\"\n$openingbalance = get words after @Summary \"Beginning Balance on\" => get words between \"Beginning Balance on\" \"Deposits\"  => skip words 1 => get decimal\n$periodTo = get words after @Summary \"Ending Balance on\" => take words 1 => get date \"M/d/yy\"\n$closingbalance = get words after @Summary \"Ending Balance on\" => skip words 1 => get decimal\n\n@Header = get line containing \"Credits Debits Balance\" => get text\n@dateRight = get line containing @Header => take words 2 => right => add 15\n@serialRight = get line containing @Header => take words 3 => right => add 15\n@CredLeft = get line containing @Header => get words before \"Debits\" => take last words 1 => left => subtract 15\n@CredRight = get line containing @Header => get words before \"Debits\" => take last words 1 => right => add 5\n@Debright = get line containing @Header => get words after \"Credits\" => take words 1 => right => add 5\n@Balright = get line containing @Header => get words after \"Debits\" => take words 1 => right => add 10\n\ngo to page 1\n@transactionsTop = get line containing \"Credits Debits Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Ending Balance on\" => top => get line above\n\nignore header above 720\ndelete all lines containing \"Credits Debits Balance\"\ndelete all lines containing \"End of Day\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @dateRight @serialRight @CredLeft @CredRight @Debright @Balright => describe table false \"*Date[M/d]\" ChequeNumber Details #Credit #Debit #Balance','2025-07-31 08:11:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10770,'Old_National_Bank','$source = \"Old_National_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 30\n\n// Get Account Name\n$accountName = get text in box 650 640 65 page.middleX => take words 3 => get text\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 1 => get text\n\n//Get dates\n$periodFrom = get line containing \"Previous Statement Balance\" => get words after \"Previous Statement Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Current Statement Balance\" => get words after \"Current Statement Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\n//Get opening Closing Balance\n$openingBalance = get line containing \"Previous Statement Balance\" => get words after \"Previous Statement Balance\" => take last words 1 => get decimal\n$closingBalance = get line containing \"Current Statement Balance\" => get words after \"Current Statement Balance\" => take last words 1 => get decimal\n// Delete contact block on left side of page 1\n@tbmr = delete text in box on every page page.top page.bottom 0 54 => get text\n//Get start & end of Credit table\ngo to page 1\n@ChecksTop = get line containing \"CHECK NUMBER DATE AMOUNT\" => if not found then blank => bottom => get line below\n@ChecksBottom = get line starting \"* Denotes check paid out of sequence\" => if not found then blank => top => get line above\n\n$ChecksL = get multi page table @ChecksTop @ChecksBottom 55 165 235 290 => describe table false ChequeNumber \"Date[MM/dd]\" *#Debit\n$ChecksR = get multi page table @ChecksTop @ChecksBottom  310 420 490 550 => describe table false ChequeNumber \"Date[MM/dd]\" *#Debit\n$DeleteChecksTop = get line containing \"CHECK NUMBER DATE AMOUNT\" => top\n$DeleteChecksBottom = get line starting \"* Denotes check paid out of sequence\" => bottom\n$d1 = delete text in box $DeleteChecksTop $DeleteChecksBottom page.left page.right\n\ngo to page 1\n\n//$TRANSACTIONTop = get line containing \"DATE TRACER TRANSACTION DESCRIPTIONS AMOUNT\" => if not found then blank => bottom => get line below\n$TRANSACTIONTop = get line containing \"DATE TRACER TRANSACTION DESCRIPTIONS AMOUNT\" => bottom => get line below\n$TRANSACTIONBottom = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\ngo to page 1\n\nremove page 2\ndelete all lines starting \"DATE TRACER TRANSACTION DESCRIPTIONS\"\ndelete all lines starting \"DAILY BALANCE SUMMARY\"\ndelete all lines starting \"DEPOSITS AND OTHER CREDITS (continued)\"\ndelete all lines starting \"DEPOSITS AND OTHER CREDITS\"\ndelete all lines starting \"WITHDRAWALS AND OTHER DEBITS\"\ndelete all lines starting \"CHECKS\"\ndelete all lines starting \"CHECK NUMBER DATE AMOUNT\"\ndelete all lines starting \"* Denotes check\"\n\nignore header above 626\nignore footer below 50\n\n$TRANSACTION = get multi page table $TRANSACTIONTop $TRANSACTIONBottom 55 155 470 550 => describe table false \"Date[MM/dd]\" Details *#Credit\n$transactions = combine described tables $TRANSACTION $ChecksL $ChecksR','2025-08-20 07:24:39',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10771,'Polski_Bank','$source = \"Polski_Bank\"\n//$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n//$periodBufferDays = 28\n$accountNumber = get line starting \"numer rachunku:\" => get words after \"numer rachunku:\" => take words 1 => get text\n$accountName = get line starting \"właściciele:\" => get words after \"właściciele:\" => take words 4 => get text\n\n$periodFrom = get line starting \"Od dnia\" => get words after \"Od dnia\" => take words 1 => get date \"yyyyMMdd\"\n$periodTo = get line starting \"Do dnia\" => get words after \"Do dnia\" => take words 1 => get date \"yyyyMMdd\"\n\n//@filtertext = get line containing \"Data waluty Typ transakcji Opis\" => get text\n//$closingBalance = get line containing @filtertext => bottom => get line below => bottom => get line below => take  last words 1 => get decimal\n$openingBalance = get line containing \"Data waluty Typ transakcji Opis\" => bottom => get line below => bottom => get line below => take  last words 1 => get decimal\n\ngo to page 1\n@transactionTop = get line containing \"Data waluty Typ transakcji Opis\" => bottom => get line below => bottom => get line below\n\n@transactionBottom = get last line containing \"Dokument elektroniczny\" => top => get line above\n\n//Closing balance\n@ClosingBottom = get last line containing \"Dokument elektroniczny\" => top\n$closingBalance = get text in box page.top @ClosingBottom 508 580 => take last words 1 => get decimal\n\ngo to page 1\nget last line containing \"Dokument elektroniczny\" => top => ignore footer Below\n\n//go to page 1\n//@top_1 = get last line containing \"Dokument elektroniczny\" => if not found then blank => bottom\n//$delfotter = delete text in box @top_1 0 0 page.right => get text\n\ngo to page 1\nget last line containing \"Typ transakcji Opis\" => top => ignore header above\ndelete all lines containing \"Data waluty Typ transakcji Opis\"\ndelete all lines starting \"Data\"\ndelete all lines starting \"operacji\"\ndelete all lines starting \"Dokument elektroniczny\"\ndelete all lines starting \"numer rachunku:\"\ndelete all lines containing \"data wydruku:\"\ndelete all lines containing \"+0,\"\ndelete all lines containing \",00+\"\n//ignore footer below 80\n\n$transactions = get multi page table @transactionTop @transactionBottom 10 120 185 280 428 508 580 => describe table false \"*Date[yyyyMMdd]\" - TransactionType Details #Credit #Balance','2026-01-07 06:33:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10772,'Umpqua_Bank_DateDescAmount','$source = \"Umpqua_Bank_DateDescAmount\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\nset negative marker \"-\"\n\n// Get account name & account number\n@AccountTop = get line starting \"Customer Service:\" => bottom\n@AccountBottom = get line starting \"Last statement:\" => top\n$accountName = get text in box @AccountTop @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get statement period\n$periodFrom = get line starting \"Last statement date\" => get words after \"Last statement date\" => take words 1 => get date \"M/d/yy\"\n$periodTo = get line starting \"This statement date\" => get words after \"This statement date\" => take words 1 => get date \"M/d/yy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => get decimal\n\nignore header above 722\nignore footer below 50\n\n@detailLeft = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 5\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"Page:\"\n\n// Deposits/ Additions table\ngo to page 1\n@creditsTop = get line starting \"deposits and additions\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"Total Additions:\" => if not found then blank => top => get line above\n@credits = get multi page table @creditsTop @creditsBottom 35 @detailLeft 480 580 => describe table false \"Date[MM-dd]\" Details *#Credit\n\n// Deposits/ Additions table\ngo to page 1\n@DebitsTop = get line starting \"withdrawals and deductions\" => if not found then blank => bottom => get line below\n@DebitsBottom = get line starting \"Total Deductions:\" => if not found then blank => top => get line above\n@Debits = get multi page table @DebitsTop @DebitsBottom 35 @detailLeft 480 580 => describe table false \"Date[MM-dd]\" Details *#Debit\n\n// Get start & end of cheques table\ngo to page 1\n@chequeTop = get line starting \"Check # Amount Date\" => if not found then blank => bottom => get line below\n@chequebottom = get line containing \"Skip in check sequence\" => if not found then blank => top => get line above\n\n@chequeLeft = get multi page table @chequeTop @chequebottom 50 125 235 275 => describe table false ChequeNumber *#Debit \"Date[MM-dd]\"\n@chequeRight = get multi page table @chequeTop @chequebottom 310 400 485 560 => describe table false ChequeNumber *#Debit \"Date[MM-dd]\"\n\n$transactions = combine described tables @credits @Debits @chequeLeft @chequeRight','2025-08-20 07:24:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10773,'FirstTech_Card','$source = \"FirstTech_Card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$PeriodBufferDays = \"31\"\n\n$accountName = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\ndelete text in box page.top page.bottom 280 page.right\ndelete text in box on every page page.top page.bottom page.left 40\n\n@acctop = get line starting \"SUMMARY OF ACCOUNT ACTIVITY\" => bottom\n@accbottom = get line containing \"Days this Billing Cycle\" => top\n$accdetails = get text in box @acctop @accbottom 0 280\n\n$openingbalance = get words after $accdetails \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get words after $accdetails \"New Balance\" => take words 1 =>  get decimal\n\n$PeriodTo = get line containing \"Statement Closing Date\" => get words after \"Statement Closing Date\" => take words 1 => get date \"MM/dd/yyyy\"\n$PeriodFrom = get line containing \"Date Date Description Number Amount\" => bottom => get line below => bottom => get line below => take words 1 => get date \"MM/dd\"\n\ngo to page 1\n// Get start & end of Deposits and Credits table\n@TransactionTop = get line starting \"Date Date Description Number Amount\" => bottom => get line below\n@TransactionBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\ndelete all lines starting \"Account\"\ndelete all lines starting \"Tran Post\"\ndelete all lines starting \"Date Date\"\ndelete all lines starting \"Account Number\"\ndelete all lines starting \"TRANSACTIONS\"\ndelete all lines starting \"FEES\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\ndelete all lines starting \"INTEREST CHARGED\"\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\n\nignore footer below 25\n\n$transactions = get multi page table @TransactionTop @TransactionBottom 30 60 95 320 500 600 => describe table false - \"*Date[MM/dd]\" TransactionType Details #Credit','2025-08-20 07:24:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10774,'Aldermore_Bank','$source = \"Aldermore_Bank\"\r\nset negative marker \"-\"\r\n\r\n// Get Account Details\r\ngo to page 1\r\n$AccountName = get text in box page.top 600 page.left page.middleX => take words 3 => get text\r\n$Accountnumber = get text in box page.top 600 page.middleX page.right => skip words 1 => take words 1 => get text\r\n\r\n// Get statement date\r\n$PeriodTo = get text in box 650 575 page.left page.middleX => take last words 1 => get date \"dd/MM/yyyy\"\r\n$PeriodFrom = get text in box 650 575 page.left page.middleX => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n//Get opening & closing Balance\r\n@Balancetop = get last line containing \"The Deposit Guarantee Scheme\" => top => get line above => top => get line above => top => get line above => top => get line above => top\r\n@Balancebottom = get last line containing \"The Deposit Guarantee Scheme\" => top\r\n$OpeningBalance = get text in box @Balancetop @Balancebottom page.left page.middleX => take words 1 => get decimal\r\n$closingBalance = get text in box page.top 600 page.middleX page.right => skip words 2 => take words 1 => get decimal\r\n\r\n// Delete unwanted text\r\ndelete text in box page.top 600 page.left page.middleX\r\n\r\n// Get top & bottom of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Account\" => bottom => get line below\r\n@transactionsBottom = get line containing \"The Deposit Guarantee Scheme\" => top => get line above => top => get line above => top => get line above => top => get line above => top => get line above\r\n\r\n// Read the transactions\r\ngo to page 1\r\n@DateRight = get line containing \"Account\" => bottom => get line below => take words 1 => right => add 10\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @DateRight 300 370 450 560 => describe table false \"*Date[dd/MM/yyyy]\" Details #Debit #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10775,'GeorgeBank_CreditCard_New','$source = \"GeorgeBank_CreditCard_New\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 30\n\nset negative marker \"CR\"\n\n// Delete vertical text\ndelete rotated words\ndelete white words\ndelete tiny words\n\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\n\n$accountName = get line containing \"Account Name\" => get words after \"Account Name\" => get text\n\n$periodFromText = get line containing \"(from\" => get words after \"(from\"\n$periodFrom = take words $periodFromText 1 => get date \"d/M/yyyy\"\n\n$periodTo = get words after $periodFromText \"to\" => take words 1 => get date \"d/M/yyyy\"\n\n$openingBalance = get line starting \"Opening Balance\" => take last words 1 => get decimal\n\n$closingBalance = get line starting \"Closing Balance\" => take last words 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\n@transactionsBottom = get line starting \"Closing Balance\" => top => get line above\n\nignore header above 660\nignore footer below 68\ndelete all lines containing \"Page\"\ndelete all lines containing \"continued overleaf\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 110 450 560 => describe table false \"Date[d MMM]\" Details *#Credit','2025-08-20 07:26:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10776,'Walmart_card','$source = \"Walmart_card\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 20\n\n// Get period From and Period To\ngo to page 1\n@period = get line containing \"STATEMENT PERIOD\" => get words after \"STATEMENT PERIOD\" => take words 7\n$periodFrom = take words @period 3 => get date \"MMM dd, yyyy\"\n$periodTo = take last words @period 3 => get date \"MMM dd, yyyy\"\n\n// Get Account number and account name Details\n@accountNoLinetop = get line containing \"Account number\" => top => add 2\n@accountNoLinebottom = get line containing \"Account number\" => bottom => subtract 2\n$accountNumber = get text in box @accountNoLinetop @accountNoLinebottom 200 544 => get words after \"Account number\" => get text\n$accountName = get text in box @accountNoLinetop @accountNoLinebottom 200 544 => get words after \"Account number\" => get text\n\n// deleted First page footer\n@accountNoLinetop = get line containing \"Account number\" => top => get line above => top => get line above => top\ndelete text in box @accountNoLinetop page.bottom page.left page.right\n\n// deleted left and right side of page\ndelete text in box on every page page.top page.bottom page.left 50\ndelete text in box on every page page.top page.bottom 415 page.right\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Total new balance\" => get words after \"Total new balance\" => take words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"NO DATE DATE ACTIVITY DESCRIPTION AMOUNT\" => bottom => get line below\n\n// Get end of table\n@lastTransactionPage = get last line containing \"NO DATE DATE ACTIVITY DESCRIPTION AMOUNT\"\n@transactionsBottom = get line above 20\n\n// Delete extra lines\ndelete all lines containing \"ITEM TRANS POSTING\"\ndelete all lines containing \"NO DATE DATE ACTIVITY DESCRIPTION AMOUNT\"\ndelete all lines containing \"**** **** ****\"\n\n// deleted headers of 1st and 2nd page\ngo to page 1\n@1page = get line containing \"Details of your transactions\" => bottom\n$dbox2 = delete text in box page.top @1page page.left page.right\n\n@2page = get line containing \"Details of your transactions\" => if not found then blank => bottom => get line below => top\n$dbox3 = delete text in box page.top @2page page.left page.right\n\n// deleted footer of 1st\ngo to page 1\n@3page = get line containing \"Message centre\" => top\n$dbox4 = delete text in box @3page page.bottom page.left page.right\n\n// deleted no transaction line with complete page to avoid execution of no transaction files\ngo to page 1\n@4page = get line containing \"No transaction activity this period\" => top\n$dbox5 = delete text in box @4page page.bottom page.left page.right\n\ndelete all lines containing \"Details of your transactions\"\ndelete all lines containing \"Transactions continued\"\n\n// Ignore footer lines below Y-coordinate 20 (PDF units)\nignore footer below 20\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 75 115 152 370 369 420 => describe table false  - \"*Date[MMM dd]\" Details - #Credit','2025-10-29 06:18:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10777,'CitiBank_SAVINGS_ACTIVITY','$source = \"CitiBank_SAVINGS_ACTIVITY\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n// Get account Accounts\n$accountname = get text in box 710 678 0 page.middleX => get text\n$accountnumber = get line containing \"Statement Period\" => top => get line above  => take words 1 => get text\n// Get statement period\ngo to page 1\n@period = get line containing \"Statement Period\" => get words after \"Period\" => take last words 6\n$periodto = take last words @period 3 => get date \"MMM dd, yyyy\"\n$periodfrom = take words @period 2 => get date \"MMM dd\"\n\n$openingbalance = get line containing \"Beginning Balance:\" => get words after \"Beginning Balance:\" => take words 1 => get decimal\n$closingbalance = get last line containing \"Ending Balance:\" => get words after \"Ending Balance:\" => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount Subtracted Amount Added Balance\" => get text\n@dateleft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n@detailsleft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 5\n@debitleft  =  get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 5\n@creditleft  = get line containing @tranactionColumns => get words after \"Subtracted\" => take words 1 => left => subtract 5\n@balanceleft  = get line containing @tranactionColumns => take last words 2 => take words 1 => right => add 5\n@balanceright = get line containing @tranactionColumns => take last words 1 => right => add 10\ngo to page 1\n// Read the transactions\n@transactionsTop = get line starting \"Date Description Amount Subtracted Amount Added Balance\" => bottom => get line below\n@transactionsbottom = get line containing \"Total Subtracted/Added\" => top => get line above\n\ngo to page 1\n@top_1 = get line starting \"Overdraft and Returned\" => if not found then blank => bottom\n@deltext = delete text in box @top_1 0 0 page.right => get text\n\ngo to page 1\n@top = get line starting \"CUSTOMER SERVICE INFORMATION\" => if not found then blank => bottom\n@deltext = delete text in box @top 0 0 page.right => get text\n\ngo to page 1\ndelete all lines starting \"Date Description\"\ndelete all lines containing \"Amount Subtracted Amount Added Balance\"\ndelete all lines starting \"Account Activity\"\ndelete all lines starting \"Trans Date Post Date Reference\"\ndelete all lines containing \"Year-to-Date\"\ndelete all lines starting \"Account Number:\"\ndelete all lines containing \"Period:\"\ndelete all lines starting \"PAYMENTS AND CREDITS\"\ndelete all lines starting \"PURCHASES\"\ndelete all lines starting \"INTEREST CHARGED\"\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines starting \"Total fees\"\ndelete all lines starting \"Total interest\"\ndelete all lines starting \"All transaction times\"\ndelete all lines starting \"CUSTOMER SERVICE INFORMATION\"\ndelete all lines starting \"SAVINGS ACTIVITY\"\ndelete all lines starting \"Statement Period -\"\ndelete all lines starting \"Overdraft and Returned\"\ndelete all lines containing \"Statement Period\"\ndelete all lines starting \"Total\"\nignore header above 700\n$transactions = get multi page table @transactionsTop @transactionsbottom @dateleft @detailsleft @debitleft @creditleft @balanceleft @balanceright => describe table false  \"*Date[MM/dd]\" Details #Debit #Credit #Balance','2025-08-20 07:26:31',0);
