INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10779,'FNB_PREMIER_CREDIT','$source = \"FNB_PREMIER_CREDIT\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n$periodBufferDays = 31\n\n// Transactions with Kt text are negative\nset negative marker \"Kt\"\n\n// Get account number\n$accountNumber = get line containing \"FNB PREMIER CREDIT\" => get words after \"CREDIT\" => get text\n\n// Get account name\n$accountName = get text in box 720 660 0 400 => take words 3  => get text\n\nset culture \"pap-029\"\n\n// Get period from/to\ngo to page 1\n$periodTo = get line containing \"Datum van Staat\" => get words after \"Datum van Staat\" => take words 3 => get date \"dd MMMM yyyy\"\n@top = get line containing \"Datum Fasiliteit Fasiliteit\" => bottom\n$periodFrom = get text in box @top page.bottom 0 54 => take words 2 => get date \"dd MMM\"\n\n// Get opening and closing balances\ngo to page 2\n\n@openingBalanceTop = get line containing \"Aanvangsaldo\" => top\n@openingBalanceBottom = get line containing \"Aanvangsaldo\" => bottom\n@openingBalancebox = get text in box @openingBalanceTop @openingBalanceBottom 0 page.right\n$openingBalance = get line containing \"Aanvangsaldo\" => get words after \"Aanvangsaldo\" => get decimal\n\n@pageHeader = get last line containing \"Afsluitingsaldo\" => top\n@pageFooter = get last line containing \"Afsluitingsaldo\" => bottom\n@infoLast = get text in box @pageHeader @pageFooter 50 390\n$closingBalance = get words after @infoLast \"Afsluitingsaldo\" => get decimal\n\ndelete all lines containing \"Bladsy\"\ndelete all lines containing \"Totale waarde\"\ndelete all lines containing \"FNB PREMIER CREDIT\"\ndelete all lines containing \"Aanvangsaldo\"\ndelete all lines starting \"Kaartnr.\"\ndelete all lines containing \"Kaart Totaal\"\ndelete all lines containing \"****\"\n// Deleting March month transactions because march format date not supported in the culture\ndelete all lines containing