INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10780,'SharonBank','$source = \"SharonBank\"\r\n\r\n// Get account number\r\n@accnt_top = get line containing \"Account Type Account Number\" => bottom\r\n@accnt_bottom = get line containing \"Account Type Account Number\" => bottom => get line below => bottom\r\n$accountNumber = get text in box @accnt_top @accnt_bottom 320 440 => get text\r\n\r\n//get statement period\r\ngo to page 1\r\n$periodto = get line containing \"Statement Ending\" => get words after \"Statement Ending\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$accountName = get line containing \"Statement Ending\" => bottom => get line below => take words 3 => get text\r\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n\r\n//get opening/closing balance\r\n$openingbalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line starting \"Post Date Description\" => bottom => get line below => bottom => get line below\r\n\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\r\n\r\n//ignore header\r\nget last line containing \"Post Date Description\" => bottom => ignore header above\r\n\r\n//ignore footer\r\nignore footer below 30\r\n\r\n//delete extra pages\r\ndelete all pages containing \"IN CASE OF ERRORS OR QUESTIONS ABOUT YOUR\"\r\n\r\ngo to page 1\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 90 320 425 500 585 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10781,'Capitec_Bank_Category','$source = \"Capitec_Bank_Category\"\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Get Account Name\n$accountName = get text in box 750 718 page.left page.middleX => take words 2 => get text\n\n// Get Account Number\n$AccountNumber = get line containing \"VAT Registration Number\" => get words before \"VAT Registration Number\" => take last words 1 => get text\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"Opening Balance:\" => get words after \"Opening Balance:\" =>  take words 2 => get decimal\n$closingbalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" =>  take words 2 => get decimal\n\n//Get dates\ngo to page 1\n$PeriodFrom = get line containing \"From Date:\" => get words after \"From Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n$periodTo = get line containing \"To Date:\" => get words after \"To Date:\" => take words 1 => get date \"dd/MM/yyyy\"\n\ngo to page 1\n@transactionstop = get line containing \"Date Description Category Money In Money Out Fee* Balance\" => bottom => get line below\n\ndelete all lines containing \"Date Description Category Money In Money Out Fee* Balance\"\ndelete all lines starting \"*\"\n\n@transactionsbottom = get last line containing \"24hr Client Care Centre\" => top => get line above\n\ndelete all lines containing \"24hr Client Care Centre\"\n//delete all lines containing \"Start balance\"\nignore header above 815\nignore footer below 50\n\n$transactions = get multi page table @transactionstop @transactionsbottom 30 82 295 375 485 530 => describe table false \"*Date[dd/MM/yyyy]\" Details - #Credit TransactionType','2025-08-20 07:29:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10782,'Latitude_card','$source = \"Latitude_card\"\n$periodBufferDays = 20\n$features = \"CREDIT_CARD\"\n\n// delete left side text to grab account number and statement period\ndelete text in box on every page page.top page.bottom 580 800\ngo to page 1\n@leftsummarryBottom = get line containing \"Opening balance:\" => top\ndelete text in box page.top @leftsummarryBottom 0 310\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => get text\n$accountName = get line containing \"Account number:\" => get words after \"Account number:\" => get text\n\n// Get statement period\n@statementPeriod = get line containing \"Statement period:\" => get words after \"Statement period:\" => take words 3\n$periodFrom = take words @statementPeriod 1 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @statementPeriod 1 => get date \"dd/MM/yyyy\"\n\n// Get statement openingBalance and closingBalance\ndelete text in box page.top page.bottom 310 page.right\n$openingBalance = get line containing \"Opening balance:\"  => get words after \"Opening balance:\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing balance:\"  => get words after \"Closing balance:\" => take words 1 => get decimal\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line containing \"Date Card Description Debits Credits\" => bottom => get line below\n@transactionsBottom = get last line starting \"Closing balance\" => top => get line above\n\n// Discard unwanted lines\ndelete all lines starting \"Transactions this statement period\"\ndelete all lines starting \"Statement date\"\ndelete all lines starting \"Page\"\n\ndelete all lines containing \"Date Card Description Debits Credits\"\ndelete all lines starting \"Your promotional offers\"\n\ngo to page 1\n@Footer1 = get line starting \"Your payment options\" => top\ndelete text in box @Footer1 page.bottom 0 page.right\n\nignore footer below 50\nget last line starting \"Your transactions\" => top => ignore header above\ndelete all lines starting \"Your transactions\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 120 450 520 585 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit #Debit','2025-08-20 07:29:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10783,'GesaCreditUnion_Card','$source = \"GesaCreditUnion_Card\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 28\n\n//get Accounts\n$accountName = get line containing \"Cardholder Name\" => bottom => get line below => take words 4 => get text\ndelete all lines containing \"Name and Account Number\"\ngo to page 1\n$accountNumber = get  line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\ndelete all lines containing \"XXXX-XXXX\"\n$deleterightArea = delete text in box page.top 0 578 page.right\n\n//Get Balances\ngo to page 1\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n//Get Periods\n\n$periodFrom = get line starting \"Post Date Trans Date\" => bottom => get line below => take words 1 => get date \"MM/dd\"\ngo to page 1\n$periodTo = get line starting \"Statement Closing Date\" => get words after \"Closing Date\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n// Get transactions Column\n@detailsleft = get line starting \"Post Date Trans Date Reference\" => top => get line above => take words 1 => left => subtract 3\n@tranactionColumns = get line starting \"Post Date Trans Date Reference\" => get text\n@dateleft =  get line containing @tranactionColumns => take words 1 => left => subtract 5\n@date1left =  get line containing @tranactionColumns => get words after \"Post Date\" => take words 1 => left => subtract 5\n@paymentType = get line containing @tranactionColumns => get words after \"Trans\" => take words 1 => right => add 2\n@amountleft  = get line containing @tranactionColumns => get words after \"Description\" => left => subtract 15\n@amountright = get line containing @tranactionColumns => get words after \"Description\" => right => add 35\n\n// Get start & end of all transactions table\n@transactionsTop = get line starting \"Post Date Trans Date Reference\" => bottom => get line below\n@transactionsBottom = get line starting \"Fees\" => top => get line above\n\ngo to page 1\ndelete all lines starting \"Transactions\"\ndelete all lines starting \"Post Date Trans Date Reference\"\ndelete all lines starting \"Fees\"\ndelete all lines starting \"TOTAL FEES FOR THIS PERIOD\"\n\ngo to page 1\n@InterestChargedDetailsleft = get line starting \"Interest Charged\" => take words 1 => left => subtract 5\n// Get start & end of all InterestCharged table\n@InterestChargedTop = get line containing \"Interest Charged\" => if not found then blank => bottom => get line below\n@InterestChargedBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => if not found then blank => top => get line above\n@InterestCharged = get multi page table @InterestChargedTop @InterestChargedBottom @dateleft @date1left  @InterestChargedDetailsleft @amountleft @amountright => describe table false \"*Date[MM/dd]\" -  Details #Credit\n\ndelete all lines starting \"Interest Charged\"\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\n$transaction = get multi page table @transactionsTop @transactionsBottom @dateleft @date1left @paymentType @detailsleft @amountleft @amountright => describe table false \"*Date[MM/dd]\" - TransactionType Details #Credit\n$transactions = combine described tables $transaction @InterestCharged\n\n','2025-08-20 07:29:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10784,'UnitedBusinessBank','$source = \"UnitedBusinessBank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\n\n// Get Account name & number\n@AccountBottom = get line starting \"BUSINESS ACCOUNT ANALYSIS\" => top\n$accountname = get text in box page.top @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n// Get statement period\n$periodFrom = get line containing \"Period:\" => get words after \"Period:\" => take words 1 => get date \"M/d/yy\"\n$periodTo = get line containing \"Period:\" => get words after \"Period:\" => take last words 1 => get date \"M/d/yy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take last words 1 => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take last words 1 => get decimal\n\n// Get top & bottom of checks table\ngo to page 1\n@checkstop = get line starting \"Date Check No Amount\" => if not found then blank => bottom => get line below\n@checksbottom = get line containing \"break in check\" => if not found then blank => top => get line above\n\ndelete all lines containing \"Date Check No Amount\"\nignore header above 575\nignore footer below 30\n\n//Get checks table\n@checksLeft = get multi page table @checkstop @checksbottom 0 90 150 220 => describe table false \"*Date[M/d]\" ChequeNumber #Debit\n@checksMiddle = get multi page table @checkstop @checksbottom 220 275 330 400 => describe table false \"*Date[M/d]\" ChequeNumber #Debit\n@checksRight = get multi page table @checkstop @checksbottom 400 460 520 585 => describe table false \"*Date[M/d]\" ChequeNumber #Debit\n\n// Delete check tables\ngo to page 1\n@deletecheckstop = get line starting \"CHECKS\" => if not found then blank => bottom\n@deletechecksbottom = get line containing \"break in check\" => if not found then blank => top\n$deleteChecks = delete text in box @deletecheckstop @deletechecksbottom page.left page.right => get text\ndelete all lines starting \"CHECKS\"\ndelete all lines containing \"break in check\"\n\n// DEPOSITS AND OTHER CREDITS table\ngo to page 1\n@creditsTop = get line containing \"OTHER CREDITS\" => if not found then blank => bottom => get line below\n@creditsBottom = get line containing \"OTHER DEBITS\" => if not found then blank => top => get line above\n\ndelete all lines containing \"OTHER CREDITS\"\ndelete all lines containing \"Date Amount Activity Description\"\n@credits = get multi page table @creditsTop @creditsBottom 0 100 180 500 => describe table false \"*Date[M/d]\" #Credit Details\n\n// OTHER DEBITS AND WITHDRAWALS\ngo to page 1\n@debitsTop = get line containing \"OTHER DEBITS\" => if not found then blank => bottom => get line below\n@debitsBottom = get last line containing \"BALANCE SUMMARY\" => if not found then blank => top => get line above\ndelete all lines containing \"OTHER DEBITS\"\n@debits = get multi page table @debitsTop @debitsBottom 0 100 180 500 => describe table false \"*Date[M/d]\" #Debit Details\n\n// Combine all tables\n$transactions = combine described tables @credits @checksLeft @checksMiddle @checksRight @debits','2026-01-07 06:33:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10785,'Calmony_Bank','$source = \"Calmony_Bank\"\n$periodBufferDays = 45\n\n// Get Account Name\n$accountName = get text in box page.top 88 page.middleX page.right => take words 2 => get text\n\n// Get Account Number\n$AccountNumber = get line containing \"Account no\" => get words after \"Account no\" => take words 1 => get text\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"Start balance\" => get words after \"Start balance\" =>  take words 1 => get decimal\n$closingbalance = get line containing \"End balance\" => get words after \"End balance\" =>  take words 1 => get decimal\n\n//Get dates\ngo to page 1\n@PeriodFromTop = get line containing \"Date Type Description Money out £ Money in £ Balance £\" => bottom\n$PeriodFromBox = get text in box @PeriodFromTop page.bottom 15 102\n$PeriodFrom = take words $PeriodFromBox 2 => get date \"dd MMM\"\n$periodTo = get line containing \"At a glance\" => bottom => get line below => get words after \"-\" => get date \"dd MMM yyyy\"\n\ngo to page 1\n@transactionstop = get line containing \"Date Type Description Money out £ Money in £ Balance £\" => bottom => get line below => bottom => get line below => bottom => get line below\ndelete all lines containing \"Date Type Description Money out £ Money in £ Balance £\"\n@transactionsbottom = get last line containing \"Balance carried\" => top => get line above\ndelete all lines containing \"Balance carried\"\ndelete all lines containing \"Start balance\"\nignore header above 825\nignore footer below 95\n\n$transactions = get multi page table @transactionstop @transactionsbottom 20 100 290 380 465 530 => describe table false \"Date[dd MMM yyyy]\" Details #Debit #Credit *#Balance','2025-08-20 07:29:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10786,'MBNA_AmazonCard_French','$source = \"MBNA_AmazonCard_French\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 28\nset culture \"fr-FR\"\n\ndelete text in box on every page page.top 0 0 55\ngo to page 1\ndelete text in box page.top 0 0 415 => get text\n\n@Summarytop = get line containing \"Période du relevé :\" => bottom\n@Summarybottom = get line starting \"Titulaire principal de\" => bottom => get line below => bottom\n@Summary = get text in box @Summarytop @Summarybottom 420 590\n\n$periodFrom = get words after @Summary \"Période du relevé :\" => get words between \"Période du relevé :\" \"à\" => take last words 1 => get date \"d/M/yy\"\n$periodTo = get words after @Summary \"à\"  => get words between \"à\" \"Numéro de compte\" => get date \"d/M/yy\"\n\n$accountNumber = get words after @Summary \"de compte :\"  => get words between \"de compte :\" \"Titulaire principal\"  => get text\n$accountName = get words after @Summary \"de la carte :\" => take words 2 => get text\n\n@transactionsTop = get line containing \"Montant ($)\" => bottom => get line below\n$OpeningBalance = get line starting \"Solde du relevé précédent\" => get words after \"Solde du relevé précédent\" => get decimal\n\ndelete all lines starting \"Solde du relevé précédent\"\ndelete all lines starting \"PAIEMENTS\"\ndelete all lines starting \"INTÉRÊTS FACTURÉS\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"ACHATS\"\ndelete all lines starting \"Sous-total de l’activité\"\ndelete all lines starting \"suite à la page suivante\"\n\n@transactionsBottom = get last line starting \"Nouveau solde\" => top => get line above\n$closingBalance = get last line starting \"Nouveau solde\" => get words after \"Nouveau solde\" => get decimal\n\nignore footer below 35\nignore header above 630\n\n//$transactions = get multi page table @transactionsTop @transactionsBottom 105 150 480 515 590 => describe table false \"*Date[d/M/yy]\" Details TransactionType #Credit\n$transactions = get multi page table @transactionsTop @transactionsBottom 105 150 515 590 => describe table false \"*Date[d/M/yy]\" Details #Credit','2025-08-20 07:29:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10787,'Webster_DateDescriptionAmount','$source = \"Webster_DateDescriptionAmount\"\n$periodBufferDays = 7\n\n// Get Account name & Account number\n$accountNumber = get line containing \"ACCOUNT TYPE ACCOUNT NUMBER\" => bottom => get line below => get words before \"$\" => take last words 1 => get text\n$accountName = get line starting \"Statement Ending\" => bottom => get line below => take words 3 => get text\n\n// Get statement period\ngo to page 1\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n$periodTo = get line containing \"Ending Balance\" => get words before \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\n\ngo to page 1\n// Get opening and closing balances\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\n\nremove page 2\ndelete all lines containing \"Date Description Amount\"\n\n// Delete extra summary\ngo to page 1\n@InfoBottom = get line containing \"Account Summary\" => top\n$deleteInfo = delete text in box page.top @InfoBottom page.middleX page.right => get text\n\ngo to page 1\n// Get start & end of Deposits\n@creditsTop = get line containing \"Ending Balance\" => if not found then blank => bottom => get line below => bottom => get line below\n@creditsBottom = get line ending \"Debits\" => if not found then blank => top => get line above\n\n// Get start & end of Electronic Debits\ngo to page 1\n@debitsTop = get line ending \"Debits\" => if not found then blank => bottom => get line below\n@debitsBottom = get line containing \"Daily Balances\" => if not found then blank => top => get line above\n\n// Get start & end of CHECKS\ngo to page 1\n@checksTop = get line starting \"Checks Cleared\" => if not found then blank => bottom => get line below => bottom => get line below\n@checksBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\ndelete all lines containing \"Indicates skipped\"\n\n// Get checks tables\n@checksLeft = get multi page table @checksTop @checksBottom 38 120 210 330 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n@checksRight = get multi page table @checksTop @checksBottom 330 415 500 580 => describe table false  ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\n\n// Delete Checks\ngo to page 1\n@checksTop2 = get line starting \"Checks Cleared\" => if not found then blank => bottom\n@checksBottom2 = get line starting \"Daily Balances\" => if not found then blank => top\n$deleteCheck = delete text in box @checksTop2 @checksBottom2 page.left page.right => get text\n\n// Delete Unwanted Lines\ndelete all lines starting \"Check Nbr Date Amount\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Other Credits\"\ndelete all lines containing \"Electronic Debits\"\ndelete all lines containing \"Deposits\"\ndelete all lines containing \"Electronic Credits\"\ndelete all lines containing \"Other Debits\"\ndelete all lines containing \"Checks Cleared\"\n\n// Delete extra headers & footers\nignore footer below 25\nignore header above 655\n\n// Debit & Credit tables\n@deposits = get multi page table @creditsTop @creditsBottom 0 90 500 600 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\n@debits = get multi page table @debitsTop @debitsBottom 0 90 500 600 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\n\n// Combine tables (Debits,Credits & Checks)\n$transactions = combine described tables @deposits @debits @checksLeft @checksRight','2026-01-07 06:33:14',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10788,'Bank_of_Hawaii','$source = \"Bank_of_Hawaii\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\n\n//Get Account name & Account number\n@AccountTop = get line containing \"www.boh.com/agreements\" => bottom\n@AccountBottom = get line containing \"Beginning balance\" => top\n$accountname = get text in box @AccountTop @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 1 => get text\ndelete text in box page.top @AccountBottom page.middleX page.right\n\n// Get statement period\n$periodFrom = get line containing \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMM dd, yyyy\"\n$periodTo = get line containing \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMM dd, yyyy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take last words 1 => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take last words 1 => get decimal\n\n// Get start & end of checks table\ngo to page 1\n@checkstop = get line starting \"Number Date Amount\" => if not found then blank => bottom => get line below\n@checksbottom = get line starting \"Date Description\" => if not found then blank => top => get line above\n\ndelete all lines starting \"DEBITS\"\ndelete all lines containing \"CREDITS\"\ndelete all lines containing \"Number Date Amount\"\nignore header above 660\nignore footer below 40\n\n@checksLeft = get multi page table @checkstop @checksbottom 45 135 220 296 => describe table false ChequeNumber \"*Date[MM-dd]\" #Debit\ndelete all lines containing \"Skip in\"\n@checksRight = get multi page table @checkstop @checksbottom 296 350 445 560 => describe table false ChequeNumber \"*Date[MM-dd]\" #Debit\n\n// DEBITS\ngo to page 1\n@debitsTop = get line containing \"Description Subtractions\" => if not found then blank => bottom => get line below\n@debitsBottom = get line containing \"Description Additions\" => if not found then blank => top => get line above\ndelete all lines containing \"Description Subtractions\"\n@debits = get multi page table @debitsTop @debitsBottom 50 125 425 550 => describe table false \"*Date[MM-dd]\" Details #Debit\n\n//CREDITS\ngo to page 1\n@creditsTop = get line containing \"Description Additions\" => if not found then blank => bottom => get line below\n@creditsBottom = get line containing \"DAILY BALANCES\" => if not found then blank => top => get line above\n\ndelete all lines containing \"Description Additions\"\n@credits = get multi page table @creditsTop @creditsBottom 50 125 425 550 => describe table false \"*Date[MM-dd]\" Details #Credit\n\n$transactions = combine described tables @checksLeft @checksRight @debits @credits','2025-10-29 06:16:25',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10789,'DBS_Multi_CurrencyAccount','$source = \"DBS_Multi_CurrencyAccount\"\n$periodBufferDays = 14\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n//Discard hidden text\ndelete white words\ndelete tiny words\n//delete rotated words\ndelete text in box on every page page.top 0 584 page.right\n// Get account Name\n$accountname = get line starting \"Account Statement\" => bottom => get line below  => bottom => get line below => get text\n\n// Get account Number\n$accountnumber = get line containing \"Account No:\" => get words after \"Account No:\" => get text\n\n// Get Period From/to dates\n//@periodText = get line starting \"Details Of Your DBS\" => bottom => get line below => get words before \"Account No:\"\n@periodText = get line containing \"Account No:\" => get words before \"Account No:\"\n//$periodto = take last words @periodText 1 => get date \"dd MMM yyyy\"\n$periodfrom = take words @periodText 1 => get date \"dd MMM yyyy\"\n$periodto = get last line containing \"Account No:\" => get words before \"Account No:\" => take last words 1 => get date \"dd MMM yyyy\"\n\ngo to page 1\n// Get opening/closing balance\n$openingbalance = get line starting \"Balance Brought Forward\" => get words after \"Balance Brought Forward\" => get decimal\n$closingbalance = get last line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => get decimal\n\ngo to page 1\ndelete all lines starting \"Page\"\n@gettexttop1 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop1\n@gettexttop2 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop2\n@gettexttop3 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop3\n@gettexttop4 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop4\n@gettexttop5 = get line starting \"Account Statement\" => bottom => get line below => get text\ndelete all lines starting @gettexttop5\ndelete all lines starting \"Indicative in SGD @\"\n// Get top and bottom of the transaction table\ngo to page 1\n@transactionsTop = get line containing \"Withdrawal Deposit Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Balance Carried Forward\" => top => get line above\n\ngo to page 1\ndelete all pages containing \"Messages For You\"\n\ngo to page 1\n//ignore header above 640\nignore header above 570\n\ndelete all lines starting \"Transaction Value Transaction Withdrawal\"\ndelete all lines containing \"Date Deposit\"\ndelete all lines containing \"Withdrawal Deposit Balance\"\n//delete all lines starting \"Balance Brought Forward\"\ndelete all lines containing \"Account No:\"\ndelete all lines starting \"Total\"\n//delete all lines containing \"Balance Carried Forward\"\ndelete all lines containing \"Account\"\ndelete all lines starting \"Continue on the next page\"\ndelete all lines starting \"Account Statement\"\ndelete all lines starting \"Details Of Your DBS Current Account\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 120 350 450 510 585 => describe table false Details #Debit #Credit *TransactionType','2025-10-29 06:16:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10790,'Opus_Bank','$source = \"Opus_Bank\"\n\n//Get account name\n@accnt_top = get line starting \"RETURN SERVICE REQUESTED\" => bottom\n@accnt_bottom = get line starting \"Summary of Accounts\" => top\n$accountName = get text in box @accnt_top @accnt_bottom 0 page.middleX => take words 3 => get text\n\n//Get account number\n$accountNumber = get line containing \"BUSINESS ANALYZED CHECKING -\" => get words before \"$\" => take last words 1 => get text\n\n//get statement period\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => get date \"MM/d/yyyy\"\n$periodTo = get line containing \"Ending Balance $\" => get words before \"Ending Balance $\" => get date \"MM/d/yyyy\"\n\n\n//Get closing Balance\ngo to page 1\n$closingBalance = get line containing \"BUSINESS ANALYZED CHECKING -\" => take last words 1 => get decimal\n\n\n//Get opening Balance\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"Date Description Amount\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Daily Balances\" => top => get line above\n\n\n//ignore header\nget last line containing \"BUSINESS ANALYZED CHECKING - NW\" => top => ignore header above\n\n//ignore footer below\nignore footer below 45\n\n//delete extra lines/text\ndelete all pages containing \"IMPORTANT INFORMATION ABOUT YOUR CREDIT LINE IF ANY\"\ndelete all lines containing \"Date Description Amount\"\ndelete all lines starting \"***** Other Debits *****\"\ndelete all lines starting \"***** Other Credits *****\"\ndelete all lines starting \"Total Other\"\ndelete all lines starting \"Total Deposits:\"\ndelete all lines starting \"Total Credit:\"\ndelete all lines starting \"*****\"\ndelete all lines starting \"BUSINESS ANALYZED CHECKING - NW\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 95 430 560 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit','2025-10-29 06:16:30',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10791,'BankofScotland_PRIVATE','$source = \"BankofScotland_PRIVATE\"\n\n//get statement period\n@period = get line starting \"From\" => get words after \"From\"\n$periodFrom = take words @period 1 => get date \"dd/MM/yyyy\"\n$periodTo = take last words @period 1 => get date \"dd/MM/yyyy\"\n\n//delete extra text/lines\n$rght_del = delete text in box 550 520 300 page.right => get text\n\n//Get account name\n@bottom = get line starting \"Account:\" => top\n$accountName = get text in box page.top @bottom 0 page.middleX => take words 3 => get text\n\n\n//Get account number\n$accountNumber = get line containing \"Account:\" => get words after \"Account:\" => get text\n\n\n//Get opening Balance\ngo to page 1\n$openingBalance = get line containing \"BALANCE BROUGHT FORWARD\" => take last words 2 => get decimal\n\n//Get closing Balance\n$closingBalance = get line containing \"CLOSING BALANCE\" => take last words 2 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line containing \"CLOSING BALANCE\" => top => get line above\n\n//ignore header\nget last line containing \"Entry Date Value Date\" => top => ignore header above\n\n\n//delete extra lines/texts\ndelete all lines containing \"Entry Date Value Date\"\n\n\n//ignore footer\ngo to page 1\nget line containing \"Eligible deposits with us are protected\" => bottom => ignore footer below\n\ndelete all lines containing \"Eligible deposits with us are protected\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 110 160 350 480 550 => describe table false \"*Date[d-MMM-yy]\" Details #Credit #Balance ','2025-10-29 06:16:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10792,'FAB_Bank','$source = \"FAB_Bank\"\n\n\n//Get account name\n@bottom = get line containing \"DATE VALUE DATE DESCRIPTION\" => top\n$accountName = get text in box page.top @bottom 0 page.middleX => take words 3 => get text\n\n//Get account number\n$accountNumber = get line containing \"AC-NUM\" => get words after \"AC-NUM\" => get text\n\n\n//Get opening Balance\ngo to page 1\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\n\n//Get closing Balance\n$closingBalance = get line containing \"Closing Statement Balance\" => get words after \"Closing Statement Balance\" => get decimal\n\n\n//Get statementperiod\ngo to page 1\n\n@period = get line containing \"Account Statement FROM\" => get words after \"Account Statement FROM\"\n\n$periodFrom = take words @period 3 => get date \"dd MMM yyyy\"\n$periodTo = take last words @period 3 => get date \"dd MMM yyyy\"\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"DATE VALUE DATE DESCRIPTION\" => bottom => get line below => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line containing \"Closing Statement Balance\" => top => get line above\n\n//ignore header\nget last line containing \"DATE VALUE DATE DESCRIPTION DEBIT\" => top => ignore header above\n\n\n//ignore footer\ngo to page 1\nget line containing \"Balance carried forward\" => bottom => ignore footer below\n\n//delete extra lines/texts\ndelete all lines containing \"Balance brought forward\"\ndelete all lines containing \"DATE VALUE DATE DESCRIPTION\"\ndelete all lines containing \"Balance carried forward\"\n\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 10 70 140 320 410 490 580 => describe table false \"*Date[dd MMM yyyy]\" - Details #Debit #Credit #Balance','2025-10-29 06:16:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10793,'UBS_Current_Accountno','$source = \"UBS_Current_Accountno\"\n\n// Get Account Name\n$accountName = get text in box 720 685 page.left page.middleX => take words 3 => get text\n\n// Get Account Number\n@actop = get line containing \"IBAN\" => top\n@acbottom = get line containing \"BIC\" => bottom\n$accountNumber = get text in box @actop @acbottom 330 page.right => get words after \"Account no.\" => take words 1 => get text\n\n// Get period From/to dates\n@periodtxt = get line containing \"Date Information\" => top => get line above\n$periodFrom = take words @periodtxt 1 => get date \"dd.MM.yyyy\"\n$periodTo = take words @periodtxt 3 => take last words 1 => get date \"dd.MM.yyyy\"\n\n// Get balances\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\n$closingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"Date Information Debits\" => bottom => get line below => bottom => get line below\n\nignore header above 685\nignore footer below 55\ndelete all lines starting \"Turnover total\"\n\n@transactionsBottom = get line containing \"Closing balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 80 270 350 425 480 580 => describe table false \"*Date[dd.MM.yy]\" Details #Debit #Credit - #Balance','2025-10-29 06:16:36',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10794,'HSBC_Malta','$source = \"HSBC_Malta\"\n$periodBufferDays = 14\n\n// Get Account Name\n$accountName = get line starting \"Page\" => bottom => get line below => take words 3 => get text\n\n// Get Account Number\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"NUMBER\" => get text\n\n// Get Period/From To\n$periodFrom = get line containing \"BALANCE BROUGHT FORWARD\" => take words 1 => get date \"ddMMMyyyy\"\n$periodTo = get line containing \"STATEMENT DATE\" => get words after \"STATEMENT DATE\" => take words 1 => get date \"ddMMMyyyy\"\n\n// Opening and Closing Balance\n$openingbalance = get line containing \"BALANCE BROUGHT FORWARD\" => get words after \"BROUGHT FORWARD\" => take last words 1 => get decimal\n$closingbalance = get last line containing \"BALANCE CARRIED FORWARD\" => get words after \"CARRIED FORWARD\" => take last words 1 => get decimal\n\ngo to page 1\n// Get top of the transactions table\n@transactionstop = get line containing \"BALANCE BROUGHT FORWARD\" => bottom => get line below\n\n// delete unwanted lines\ndelete all lines containing \"BALANCE BROUGHT FORWARD\"\ndelete all lines containing \"Date Details Withdrawals\"\ndelete all lines containing \"Account Number\"\ndelete all lines containing \"DR=Debit\"\ndelete all lines containing \"Page\"\ndelete all lines containing \"Registered Office:\"\ndelete all lines containing \"Website:\"\ndelete all lines containing \"WITHDRAWALS\"\n\n@transactionsbottom = get last line containing \"BALANCE CARRIED FORWARD\" => top => get line above\ndelete all lines containing \"BALANCE CARRIED FORWARD\"\nignore header above 545\n\n// Read the transactions\n$transactions = get multi page table @transactionstop @transactionsbottom 30 100 310 405 500 580 => describe table false \"Date[ddMMMyyyy]\" Details **#Debit **#Credit #Balance','2025-10-29 06:16:37',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10795,'BMO_Card_French','$source = \"BMO_Card_French\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\n$periodBufferDays = 40\n\n// Get Account Name\n$accountName = get line containing \"Nom du titulaire du compte :\" => get words after \"Nom du titulaire du compte :\" => take words 1 => get text\n\n// Get Card number\n$accountNumber = get line containing \"Numéro de compte :\" => get words after \"Numéro de compte :\" => take words 1 => get text\n\ngo to page 1\n// Get Statement periodTo\n//$periodfrom = get line containing \"TOTAL DES CRÉDITS\" => bottom => get line below => bottom => get line below  => bottom => get line below => take words 1 => get date \"MM/dd\"\n$periodto = get line containing \"Date du relevé\" => get words after \"Date du relevé (mm/jj/aaaa) :\" => take words 1 => get date \"MM/dd/yyyy\"\n\n// Get opening/closing Balance\n// deleted left summary panel to get opening and closing balance from right side\n@summaryRight = get line containing \"Solde précédent :\" => get words before \"précédent\" => take last words 1 => left\n@SummaryBottom = get line containing \"Détail des transactions :\" => top\ndelete text in box page.top @SummaryBottom page.left @summaryRight\n$openingBalance = get line containing \"Solde précédent :\" => get words after \"Solde précédent :\" => get decimal\n$closingBalance = get line containing \"Nouveau solde de compte :\" => get words after \"Nouveau solde de compte :\" => get decimal\n\ngo to page 1\n// Get top of the transaction table\ndelete all lines starting \"Numéro de la carte\"\n@transactionsTop = get line containing \"Détail des transactions :\" => bottom => get line below\n\n// Get Statement period From\n$periodfromTop = get line containing \"Détail des transactions :\" => bottom => get line below => bottom => get line below => top\n$periodfrom = get text in box $periodfromTop page.bottom 35 80 => take words 1 => get date \"MM/dd\"\n\n// Get bottom of the transaction table\n@transactionsBottom = get last line starting \"TOTAL DES CRÉDITS\" => top => get line above\n\n//delete header text(page no line)\ngo to page 1\n@page2BottomTop = get line containing \"Page 1 sur\" => top\n@page2Bottom = get line containing \"Page 1 sur\" => bottom\ndelete text in box on every page @page2BottomTop @page2Bottom 520 page.right\n\n// delete some extra text\ndelete all lines containing \"Date trans.\"\ndelete all lines containing \"N° de trans\"\n\ndelete all lines containing \"TOTAL DES CRÉDITS\"\ndelete all lines containing \"TOTAL DES FRAIS\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 80 160 410 530 590 => describe table false \"*Date[MM/dd]\" - Details - #Credit','2025-10-29 06:16:42',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10796,'Frost_Bank','$source = \"Frost_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 29\n\n$accountName = get line containing \"ACCOUNT NO.\" => get words after \"ACCOUNT NO.\" => take words 2 => get text\n$accountNumber =  get line containing \"ACCOUNT NO.\" => get words after \"ACCOUNT NO.\" => take words 2 => get text\n$openingBalanceText = get line containing \"BALANCE LAST STATEMENT\" => bottom => get line below\n\n$openingBalance = take words $openingBalanceText 1 => get decimal\n$closingBalance = take last words $openingBalanceText 2 => get decimal\n$periodtext = get line containing \"STATEMENT ISSUED\" => bottom => get line below\n$periodto = take last words $periodtext  1 => get date \"M-d-yyyy\"\n\ngo to page 1\n$dlttop1 = get line containing \"Please notify us of any\" => top\n$dltbot1 = get line containing \"Deposit Account Agreement\" => bottom\n$getdlt1 = delete text in box $dlttop1 $dltbot1 page.left page.right\n\ndelete all lines containing \"______\"\ndelete all lines containing \"| |\"\n$periodfromtexttop = get line containing \"DATE BALANCE | DATE BALANCE | DATE BALANCE\" => bottom => get line below\n$periodfrom = take words $periodfromtexttop 1 => get date \"M-d\"\n\ngo to page 1\n\n@deptop = get line containing \"DEPOSITS/CREDITS\" => if not found then blank => bottom => get line below\n@depbot = get line containing \"OTHER WITHDRAWALS/DEBITS\" => if not found then blank => top => get line above\n\n@othertop = get line containing \"OTHER WITHDRAWALS/DEBITS\" => if not found then blank => bottom => get line below\n@otherbot = get line containing \"DAILY BALANCE\" => if not found then blank => top => get line above\n\ngo to page 1\n$dlttop = get line containing \"Please notify us of any\" => top\n$dltbot = get line containing \"Deposit Account Agreement\" => bottom\n$getdlt = delete text in box $dlttop $dltbot page.left page.right\n\ndelete all lines containing \"DEPOSITS/CREDITS\"\ndelete all lines containing \"OTHER WITHDRAWALS/DEBITS\"\ndelete all lines containing \"DATE AMOUNT TRANSACTION\"\nignore header above 563\nignore footer below 36\n\n@deposit = get multi page table @deptop @depbot 15 45 133 270 565 => describe table false \"Date[M-d]\" #Credit TransactionType Details\n@other = get multi page table @othertop @otherbot 15 45 133 270 565 => describe table false \"Date[M-d]\" #Debit TransactionType Details\n\n$transactions = combine described tables @deposit @other','2025-10-29 06:16:44',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10797,'Shopify_CreditCard','$source = \"Shopify_CreditCard\"\n$features = \"CREDIT_CARD\"\n$periodBufferDays = 30\n\n//set negative marker \"-\"\n$accountNumber = get line containing \"To be automatically\" => get words after \"account ending in\" => take words 1 => get text\n\n$accountName = get line containing \"To be automatically\" => get words after \"account ending in\" => take words 1 => get text\n\n$openingBalance = get line containing \"Outstanding balance\" => take last words 1 => get decimal\n\n$closingBalance = get line containing \"Amount due\" => take last words 2 => take words 1 => get decimal\n\n$periodFromText = get line containing \"Transaction Date Posting Date\" => bottom => get line below\n\n$periodFrom = take words $periodFromText 3 => get date \"MMM d, yyyy\"\n\n$periodTo = get last line starting \"If you have any questions\" => top => get line above => take words 3 => get date \"MMM d, yyyy\"\n\n\ngo to page 1\n@transactionsTop = get line starting \"Transaction Date Posting Date Description\" => bottom => get line below\n@transactionsBottom = get last line starting \"If you have any questions\" => top => get line above\n\ndelete all lines containing \"Transaction Date Posting Date Description\"\ndelete all lines containing \"Page\"\n\ngo to page 1\n$transactions = get multi page table @transactionsTop @transactionsBottom 100 165 466 580 => describe table false \"*Date[MMM d, yyyy]\"  Details #Credit','2025-10-29 06:16:45',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10798,'RIVER_BANK_TRUST','$source = \"RIVER_BANK_TRUST\"\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.middleX => take words 4 => get text\n$accountNumber = get line containing \"Account No\" => get words after \"Account No\" => take words 2 => get decimal\n\n//Get Periods\n$periodFrom = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" => take words 1 => get date \"MM/dd/yy\"\n$periodTo = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" => take words 1 => get date \"MM/dd/yy\"\n\n//Get Balances\n$openingBalance = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" => take last words 1 => get decimal\n\ngo to page 1\n//Get start and end check\n@checksTop = get line starting \"Date Check # Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\ndelete all lines starting \"CHECKS AND OTHER DEBITS\"\ndelete all lines containing \"indicates a gap in the check numbers\"\n@ChecksL = get multi page table @checksTop @checksBottom 20 100 160 218  => describe table false \"Date[MM/dd/yy]\" Details #Debit\n@ChecksM = get multi page table @checksTop @checksBottom 220 270 330 394 => describe table false  \"Date[MM/dd/yy]\" Details #Debit\n@ChecksR = get multi page table @checksTop @checksBottom 395 468 510 600 => describe table false  \"Date[MM/dd/yy]\" Details #Debit\n\ngo to page 1\n// Get start & end of all Debits table\n@debitsTop = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line below\n@debitsBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\n//delete check tables\n@chkTop = get line starting \"Date Check # Amount\" => if not found then blank => bottom\n@chkBottom = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top\n@delchecks =  delete text in box @chkTop  @chkBottom 0 page.right => get text\ndelete all lines starting \"Date Check # Amount\"\n\ngo to page 1\n// Get start & end of all ALL CREDIT ACTIVITY table\n@creditsActivityTop = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\n@creditsActivityBottom = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Date Type Amount\"\ndelete all lines starting \"Continued\"\n@creditsActivityleft = get multi page table @creditsActivityTop @creditsActivityBottom 25 94 150 218 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n@creditsActivitymiddle = get multi page table @creditsActivityTop @creditsActivityBottom 220 267 330 392   => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n@creditsActivityright = get multi page table @creditsActivityTop @creditsActivityBottom 394 442 500 590 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n\n//delete ALL CREDIT ACTIVITY tables\ngo to page 1\n@activitytop = get line starting \"ALL CREDIT ACTIVITY\" => if not found then blank => bottom\n@activitybottom = get line starting \"Date Description Amount\" => if not found then blank => top\n@delCreditAcrivityTable = delete text in box @activitytop @activitybottom 0 page.right => get text\n\n//ignore header above\nget last line starting \"Statement Date:\" => top => ignore header above\n\ngo to page 1\n// Get start & end of all Credits table\n@creditsTop = get line starting \"ALL CREDIT ACTIVITY\" => if not found then blank => bottom => get line below\n@creditsBottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line above\n\ndelete all lines starting \"ALL CREDIT ACTIVITY\"\ndelete all lines starting \"Date Description Amount\"\ndelete all lines starting \"Statement Date:\"\ndelete all lines containing \"Account No.:\"\ndelete all lines starting \"Continued\"\n@credits = get multi page table @creditsTop @creditsBottom 20 120 466 600 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\n\ndelete all lines starting \"ELECTRONIC DEBITS\"\ndelete all lines containing \"DAILY BALANCE SUMMARY\"\n@debits = get multi page table @debitsTop @debitsBottom 20 94 466 600 => describe table false \"Date[MM/dd/yy]\" Details *#Debit\n\n// Read the transactions\n$transactions = combine described tables @creditsActivityleft @creditsActivitymiddle @creditsActivityright @credits @debits @ChecksL @ChecksM @ChecksR','2025-10-29 06:16:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10799,'KootenaySavings_CreditUnion','$source = \"KootenaySavings_CreditUnion\"\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\n\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.middleX => take words 4 => get text\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n//Get Periods\n$periodTo = get line starting \"Date Description Amount Balance\" => bottom => get line below => take words 1 => get date \"dd-MMM-yyyy\"\n@periodTop = get last line starting \"Date Description Amount Balance\" => bottom\n@periodLeft = get last line starting \"Date Description Amount Balance\" => take words 1 => left => subtract 5\n@periodRight = get last line starting \"Date Description Amount Balance\" => take words 2 =>  take last words 1 => left => subtract 5\n$periodFrom = get text in box @periodTop 0 @periodLeft @periodRight => take words 1 => get date \"dd-MMM-yyyy\"\n\ngo to  page 1\n//Get closing Balance with No_opening Balance\n$closingBalance = get line starting \"Date Description Amount Balance\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Description Amount Balance\" => get text\n@dateLeft = get line containing @tranactionColumns => take words 1 => left => subtract 10\n@detailsLeft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 10\n@amountLeft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 20\n@amountRight = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => right => add 10\n@balanceRight = get line containing @tranactionColumns => take last words 1 => right => add 10\n\ngo to page 1\n//Get start and end of table\n@transactionsTop = get line starting \"Date Description Amount Balance\" => top => get line above\n$gotolastTransBottom = get last line starting \"Date Description Amount Balance\"\n@transactionsBottom = get line above 0 => top => get line above\n\ngo to page 1\ndelete all lines starting \"Kootenay\"\ndelete all lines ending \"LTD\"\ndelete all lines starting \"MASTERPLAN BUSINESS\"\ndelete all lines starting \"Account Number\"\ndelete all lines starting \"Current Interest Rate\"\ndelete all lines starting \"Interest Earned YTD\"\ndelete all lines starting \"Interest Charged Last Year\"\ndelete all lines starting \"Interest Earned Last Year\"\n\nget last line starting \"Date Description Amount Balance\" => top => ignore header above\ndelete all lines starting \"Date Description Amount Balance\"\n\nignore footer below 50\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailsLeft @amountLeft @amountRight @balanceRight => describe table false \"*Date[dd-MMM-yyyy]\" Details #Credit #Balance\n','2025-10-29 06:16:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10800,'Wamo_Bank','$source = \"Wamo_Bank\"\n\n//Get Accounts\n$accountName = get line containing \"Account name\" => get words after \"Account name\" => get text\n$accountNumber = get line containing \"IBAN\" => get words after \"IBAN\" => take words 1 => get text\n\n//Get Balance\n$openingBalance = get line starting \"Opening balance\" => get words after \"Opening balance\" => get decimal\n$closingBalance = get line starting \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\n//Get Periods\n@periodText = get line starting \"Transactions from\" => get words after \"Transactions from\" => get text\n$periodFrom = get line containing @periodText => get words before \"to\" => take last words 3 => get date \"MMM d, yyyy\"\n$periodTo = get line containing @periodText => get words after \"to\" => take words 3 => get date \"MMM d, yyyy\"\n\ngo to page 1\n// Get transactions Column\n@tranactionColumns = get line starting \"Date Type Description Money\" => get text\n@dateLeft = get line containing @tranactionColumns => take words 1 => left => subtract 5\n@typeLeft = get line containing @tranactionColumns => get words after \"Date\" => take words 1 => left => subtract 5\n@detailsLeft = get line containing @tranactionColumns => get words after \"Type\" => take words 1 => left => subtract 10\n@creditLeft = get line containing @tranactionColumns => get words after \"Description\" => take words 1 => left => subtract 10\n@creditRight = get line containing @tranactionColumns => get words before \"Money out\" => take last words 1 => right => add 5\n@debitRight = get line containing @tranactionColumns => get words before \"Balance\" => take last words 1 => right => add 5\n@balanceRight = get line containing @tranactionColumns => take last words 1 => right => add 10\n\ngo to page 1\n//Get start and end of table\n@transactionsTop = get line starting \"Date Type Description Money\" => if not found then blank => top => get line above\n@transactionsBottom = get last line starting \"© wamo\" => if not found then blank => top => get line above\ngo to page 1\ndelete all lines starting \"Transactions from\"\ndelete all lines starting \"Date Type Description Money\"\ndelete all lines starting \"Opening balance\"\ndelete all lines starting \"Money in\"\ndelete all lines starting \"Money out\"\ndelete all lines starting \"Closing balance\"\nget last line starting \"© wamo\" => top => ignore footer below\ndelete all lines starting \"© wamo\"\n\nignore header above 760\n//ignore footer below 30\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @typeLeft @detailsLeft @creditLeft @creditRight @debitRight @balanceRight => describe table false \"*Date[MMM d, yyyy]\" TransactionType Details #Credit #Debit #Balance\n','2025-10-29 06:16:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10801,'YuroPay_NoOpeningBalance','$source = \"YuroPay_NoOpeningBalance\"\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\nset culture \"de-LU\"\n//Get Accounts\n$accountName = get line starting \"Kontoauszug\" => top => get line above => get text\n$accountNumber = get line containing \"Von:\" => get words after \"An:\" => take last words 1 => get text\n\n//Get Periods\n$periodFrom = get line starting \"Von:\" => get words after \"Von:\" => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get line starting \"Von:\" => get words after \"An:\" => take words 3 => get date \"d MMM yyyy\"\n\n//Get Balances\n$openingBalance = get line containing \"ID Datum\" => bottom => get line below => take last words 1 => get decimal\n\ngo to page 1\n@closingTop = get last line containing \"ID Datum\" => bottom\n$closingBalance = get text in box @closingTop 0 486 550 => take last words 1 => get decimal\n//$closingBalance = get line above 0 => take last words 1 => get decimal\n\ngo to page 1\n\n@tranactionColumns = get line containing \"ID Datum\" => get text\n@dateLeft = get line containing @tranactionColumns => get words before \"Datum\" => take last words 1 => right => add 1\n@detailsLeft = get line containing @tranactionColumns => get words after \"Datum\" => take words 1 => left => subtract 2\n\ngo to page 1\n//Get start and end of table\n@transactionstop = get line containing \"ID Datum\" => bottom => get line below\n@transactionsbottom = get last line starting \"Gedruckt:\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"ID Datum\"\ndelete all lines starting \"Von:\"\ndelete all lines starting \"Karte\"\ndelete all lines starting \"Kontoauszug\"\ndelete all lines starting \"Online-Konto\"\nignore header above 820\nget last line starting \"Gedruckt:\" => if not found then blank => bottom => ignore footer below\ndelete all lines starting \"Gedruckt:\"\ndelete all lines containing \"Seite\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom @dateLeft @detailsLeft 288 420 486 550 => describe table false \"*Date[dd-MM-yyyy]\" Details - #Credit #Balance\n','2025-10-29 06:16:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10802,'YuroPay_OpeningBalance','$source = \"YuroPay_OpeningBalance\"\nset culture \"de-LU\"\n//Get Accounts\n$accountName = get line starting \"Kontoauszug\" => top => get line above => get text\n$accountNumber = get line containing \"Von:\" => get words after \"An:\" => take last words 1 => get text\n\n//Get Periods\n$periodFrom = get line starting \"Von:\" => get words after \"Von:\" => take words 3 => get date \"d MMM yyyy\"\n$periodTo = get line starting \"Von:\" => get words after \"An:\" => take words 3 => get date \"d MMM yyyy\"\n\n//Get Balances\n$openingBalance = get line starting \"Anfangssaldo\" => get words after \"Anfangssaldo\" => take last words 1 => get decimal\n\ngo to page 1\n//@closingTop = get last line containing \"ID Datum\" => bottom\n//$closingBalance = get text in box @closingTop 0 486 550 => take last words 1 => get decimal\n//$closingBalance = get line above 0 => take last words 1 => get decimal\n$closingBalance =  get line containing \"Endsaldo\" => get words after \"Endsaldo\" => take last words 1 => get decimal\ngo to page 1\n@tranactionColumns = get line containing \"ID Datum\" => get text\n@dateLeft = get line containing @tranactionColumns => get words before \"Datum\" => take last words 1 => right => add 1\n@detailsLeft = get line containing @tranactionColumns => get words after \"Datum\" => take words 1 => left => subtract 2\n\ngo to page 1\n//Get start and end of table\n@transactionstop = get line containing \"ID Datum\" => bottom => get line below\n@transactionsbottom = get last line starting \"Gedruckt:\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"ID Datum\"\ndelete all lines starting \"Von:\"\ndelete all lines starting \"Karte\"\ndelete all lines starting \"Kontoauszug\"\ndelete all lines starting \"Online-Konto\"\nignore header above 820\nget last line starting \"Gedruckt:\" => if not found then blank => bottom => ignore footer below\ndelete all lines starting \"Gedruckt:\"\ndelete all lines containing \"Seite\"\ndelete all lines starting \"Anfangssaldo\"\ndelete all lines starting \"Verf\"\ndelete all lines containing \"Endsaldo\"\n\n$transactions = get multi page table @transactionstop @transactionsbottom @dateLeft @detailsLeft 288 470 550 => describe table false \"*Date[dd-MM-yyyy]\" Details - #Credit\n','2025-10-29 06:16:50',0);
