=> add 10\n\ngo to page 1\n//Get start and end of table\n//@transactionsTop = get line starting \"PREVIOUS BALANCE:\" => if not found then blank => top => get line above => top => get line above\n@transactionsTop = get line starting \"PREVIOUS BALANCE:\" => if not found then blank => top => get line above\n@transactionsBottom = get last line containing \"ENDING BALANCE:\" => if not found then blank => top => get line above\ngo to page 1\ndelete all lines starting \"PREVIOUS BALANCE\"\ndelete all lines containing \"Description Deposits Withdrawals Balance\"\ndelete all lines starting \"Tran Eff\"\ndelete all lines starting \"ENDING BALANCE:\"\ndelete all lines starting \"Annual Percentage\"\ndelete all lines starting \"Dividend Year to Date\"\ndelete all lines containing \"Total Deposits\"\ndelete all lines containing \"Total Withdrawals\"\nget last line starting \"Page\" => top => ignore footer below\ndelete all lines starting \"Page\"\nignore header above 738\n//ignore footer below 30\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @creditLeft @creditRight @debitRight  => describe table false Details *#Credit *#Debit\n','2025-10-29 06:16:51',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10804,'Netwest_MettleBank_AccountNo','$source = \"Netwest_MettleBank_AccountNo\"\n\n// Get account details\n$accountName = get text in box 772 723 29 page.middleX => get text\n$accountNumber = get line starting \"Account number\" => bottom => get line below => take words 1 => get text\n\n// Get balances\n$openingBalance = get line starting \"Account number\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Balance on\" => take last words 1 => get decimal\n\n// Get periods\ngo to page 1\n\n@period = get line containing \"Statement\" => bottom => get line below\n$periodFrom = get words before @period \"to\" => take last words  3 => get date \"d MMM yyyy\"\n//$periodFrom = take words @period 3 => get date \"d MMM yyyy\"\n$periodTo = take last words @period 3 =>  get date \"d MMM yyyy\"\n\n// Get start and end of table\n@transactionsTop = get line starting \"DATE DESCRIPTION £ IN £ OUT\" => bottom => get line below\n\n$goToLastpage = get last line starting \"DATE DESCRIPTION £ IN £ OUT\" => bottom\n@transactionsBottom = get line above 0\n\n// discards\n//ignore header above 680\nget last line starting \"DATE DESCRIPTION £ IN £ OUT\" => top => ignore header above\n\nignore footer below 80\ndelete all lines starting \"DATE DESCRIPTION £ IN £ OUT\"\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 90 355 435 500 560 => describe table false \"*Date[d MMM yyyy]\" Details #Credit #Debit #Balance','2025-10-29 06:16:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10805,'ABN-AMRO_Bank_Dutch','$source = \"ABN-AMRO_Bank_Dutch\"\n$periodBufferDays = 28\nset culture \"nl-NL\"\n\n//Get Accounts\n@accountText = get line containing \"Rekeninghouder\" => get words after \"Rekeninghouder\" => get text\n$accountName = get line containing @accountText => get words after \"Rekeninghouder\" => take words  4  => get text\n\n$accountNumber = get line containing \"Ondernemersrekenin\" => get words after \"Ondernemersrekenin\" => take words 1 => get decimal\n\n//Get Periods\n$periodFrom = get line starting \"Periode\" => get words before \"t/m\" => take last words 1 => get date \"d-M-yyyy\"\n$periodTo = get line starting \"Periode\" => get words after \"t/m\" => take words 1 => get date \"d-M-yyyy\"\n\n//Get Balances\n@deleteBottom = get line starting \"Datum Omschrijving\" => top\ndelete text in box page.top @deleteBottom page.middleX page.right\n$openingBalance = get line starting \"Periode\" => bottom => get line below => take words 4 => take last words 1 => get decimal\n$closingBalance = get line starting \"Datum Omschrijving\" => top => get line above => take words 4 => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@transactionColumns = get line starting \"Datum Omschrijving Bedrag af Bedrag bij\" => get text\n@dateleft = get line containing @transactionColumns => take words 1 => left => subtract 10\n@detailsleft = get line containing @transactionColumns => take words 2 => take last words 1 => left => subtract 6\n@debitleft = get line containing @transactionColumns => take words 3 => take last words 1 => left => subtract 12\n@creditleft = get line containing @transactionColumns => get words after \"Bedrag af\" => take words 1 => left => subtract 12\n@creditright = get line containing @transactionColumns => take last words 1 => right => add 20\n\ngo to page 1\n// Get start & end of transactions\n@transactionTop = get line starting \"Datum Omschrijving Bedrag af Bedrag bij\" => bottom => get line below\n@transactionBottom = get last line starting \"Aantal afschrijvingen\" => top => get line above\n\ndelete all lines starting \"Datum Omschrijving Bedrag af Bedrag bij\"\n\nignore header above 700\nignore footer below 10\n$transactions = get multi page table @transactionTop @transactionBottom @dateleft @detailsleft @debitleft @creditleft @creditright => describe table false \"Date[d-M-yyyy]\" Details *#Debit *#Credit\n','2025-10-29 06:17:22',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10806,'ANZBank_PaymentsPurchases','$source = \"ANZBank_PaymentsPurchases\"\n$features = \"REVERSE_ORDER SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 15\n\n//Get Account name & Account number\ngo to page 1\n@AccountTop = get line below page.top => top\n@AccountBottom = get line starting \"Date Processed CardDetails\" => top\n$accountname = get text in box @AccountTop @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get text in box @AccountTop @AccountBottom 0 page.middleX => take last words 1 => get text\n\n// Get statement period\n$periodFrom = get line containing \"Transactions between\" => get words after \"Transactions between\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line containing \"Transactions between\" => get words after \"and\" => take words 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n@BalanceBottom = get line containing \"Account Balance Available Funds\" => top\n\n// Get opening balance (taken both balances are 0 because of not having in statements)\n$openingBalance = 0\n$closingBalance = 0\n\n// DEBITS\ngo to page 1\n@transactionsTop = get line containing \"Date Processed CardDetails\" => bottom => get line below\n@transactionsBottom = get last line containing \"All rights reserved\" => if not found then blank => top => get line above\n\nignore footer below 50\ndelete all lines starting \"Date Processed CardDetails\"\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 100 150 170 425 510 580 => describe table false \"*Date[dd MMM yyyy]\" - TransactionType Details #Credit #Debit\n','2025-10-29 06:17:23',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10807,'Preferred_Bank','$source = \"Preferred_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 7\nset negative marker \"-\"\ndelete all pages containing \"CHECKS OUTSTANDING\"\n\ngo to page 1\n//Get Account name & Account number\n@AccountBottom = get line starting \"Account Number\" => top\n$accountname = get text in box page.top @AccountBottom 0 page.middleX => take words 3 => get text\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n// Get statement period\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\n\n// Get opening balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\n// Get closing balance\n$closingBalance = get line containing \"Current Balance\" => get words after \"Current Balance\" => take words 1 => get decimal\n\ndelete all lines starting \"Date Description Amount\"\ndelete all lines containing \"(Continued)\"\nignore header above 585\n\n// DEBITS\ngo to page 1\n@debitsTop = get line containing \"***DEBITS***\" => if not found then blank => bottom => get line below\n@debitsBottom = get line containing \"DAILY BALANCE\" => if not found then blank => top => get line above\n@debits = get multi page table @debitsTop @debitsBottom 25 70 300 500 => describe table false \"*Date[M/dd]\" Details #Debit\n\ngo to page 1\n@DeleteTop = get last line containing \"***DEBITS***\" => if not found then blank => bottom\n@DeleteBottom = get line containing \"DAILY BALANCE\" => if not found then blank => top\n$delete1 = delete text in box @DeleteTop @DeleteBottom 0 page.right => get text\n\n//CREDITS\ngo to page 1\n@creditsTop = get line containing \"***CREDITS***\" => if not found then blank => bottom => get line below\nget last line containing \"***CREDITS***\"\n@creditsBottom = get line above 10\n\ngo to page 1\nget line containing \"***DEBITS***\" => if not found then blank => bottom => ignore footer below\ndelete all lines containing \"***DEBITS***\"\n@DeleteTop = get line containing \"DAILY BALANCE\" => if not found then blank => top\n$delete1 = delete text in box @DeleteTop page.bottom 0 page.right => get text\n@credits = get multi page table @creditsTop @creditsBottom 25 70 300 500 => describe table false \"*Date[M/dd]\" Details #Credit\n\n$transactions = combine described tables @debits @credits','2025-10-29 06:17:24',0);
