INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10809,'Australia_Post_Card','$source = \"Australia_Post_Card\"\n$features = \"REVERSE_ORDER SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n$periodBufferDays = 45\n// Get Account Name\n$accountName = get line containing \"Cardholder Name\" => get words after \"Cardholder Name\" => take words 1 => get text\n// Get Account Number\n$AccountNumber = get line containing \"Card Number\" => get words after \"Card Number\" => take words 1 => get text\n//Get dates\n$PeriodFrom = get line containing \"Statement for Period\" => get words between \"Statement for Period\" \"to\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line containing \"Statement for Period\" => get words after \"to\" => take words 3 => get date \"dd MMM yyyy\"\n// Opening and Closing Balance\n$openingbalance = 0\n$closingbalance = 0\ngo to page 1\n@transactionstop = get line containing \"Card Merchant Currency Date Transaction\" => bottom => get line below\ndelete all lines containing \"Exchange rate\"\n@transactionsbottom = get last line containing \"Mastercard Prepaid Management Services Australia\" => top => get line above\nignore header above 790\nignore footer below 90\ndelete all lines containing \"Card Merchant Currency Multi-Currency Date Transaction\"\ndelete all lines containing \"Mastercard Prepaid Management Services Australia\"\n\n$transactions = get multi page table center aligned @transactionstop @transactionsbottom 2.5 20 58 120 250 420 465 => describe table false - \"Date[dd-MM-yyyy]\" TransactionType Details #Credit','2025-10-29 06:17:29',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10810,'StarlingBank_Summary_Balance','$source = \"StarlingBank_Summary_Balance\"\r\n$periodbufferdays = 10\r\n\r\n// Get account name\r\n//$accountname = get line containing \"Account Name:\" => take words 2 => get text\r\n$accountname = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\n// Get Statement_Periods\r\n$periodfrom = get line containing \"Summary\" => get words before \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n$periodto = get last line containing \"Summary\" => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n// Get Opening balance\r\ngo to page 1\r\n$openingbalance = get line starting \"Opening Balance\" => take last words 1 => get decimal\r\n$closingBalance = get line starting \"Closing Balance\" => take last words 1 => get decimal\r\n\r\nremove page 1\r\n// get table start and end\r\ngo to page 1\r\n@transactionstop = get line starting \"Opening Balance\" => bottom => get line below\r\n@transactionsbottom = get line containing \"We charge interest\" => top => get line above => top => get line above\r\n//deleted extra lines\r\nignore header above 503\r\nignore footer below 60\r\n\r\ndelete all lines containing \"We charge interest\"\r\ndelete all lines containing \"We calculate interest\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 20 125 260 507 495 588 715 815 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details - *#Credit *#Debit #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10811,'HDFC_Bank','$source = \"HDFC_Bank\"\n$periodBufferDays = 45\n// Get Account Name\n$accountName = get text in box page.top 735 page.left 290 => take words 2 => get text\n// Get Account Number\n$accountnumber = get line containing \"Account No :\" => get words after \"Account No :\" => take words 1 => get text\n// Get period from/to\n$periodFrom = get line containing \"Date Narration\" => bottom => get line below => take words 1 => get date \"dd/MM/yy\"\n$periodTo = get line containing \"To :\" => get words after \"To :\" => take words 1 => get date \"dd/MM/yyyy\"\n$openingbalance = get line containing \"Opening Balance Dr Count\" => bottom => get line below => take words 1 => get decimal\n$closingbalance = get line containing \"Opening Balance Dr Count\" => bottom => get line below => take last words 1 => get decimal\ngo to page 1\n//Transaction table top and bottom\n@transactionsTop = get line containing \"Date Narration Chq./Ref.No.\" => bottom => get line below\n@transactionsBottom = get last line starting \"STATEMENT SUMMARY\" => top => get line above\n// Discard page header\nignore header above 611\ndelete all lines containing \"Date Narration Chq./Ref.No.\"\ndelete all lines containing \"STATEMENT SUMMARY\"\nignore footer below 57\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 66 282 360 402 488 562 630 => describe table false - TransactionType Details \"*Date[dd/MM/yy]\" #Debit #Credit #Balance','2025-10-29 06:17:32',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10812,'Ladysmith_Bank','$source = \"Ladysmith_Bank\"\n\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n// Get account number\n$accountNumber = get line containing \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => take last words 1 => get text\n\n// Get statement period\n@period = get line containing \"Statement Period\" => get words after \"Statement Period\"\n$periodFrom = take words @period 1 => get date \"d/MM/yyyy\"\n$periodTo = take last words @period 1 => get date \"d/MM/yyyy\"\n\n\n// Get opening Balance\ngo to page 1\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n\n// Get closing Balance\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\n\n\n// Get account name\n@top = get line starting \"Please detach this portion and return\" => bottom\n@bottom = get line starting \"Please detach this portion and return\" => bottom => get line below => bottom => get line below => bottom\n$accountName = get text in box @top @bottom 0 page.middleX => take words 3 => get text\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line containing \"TOTAL INTEREST FOR THIS PERIOD\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get line containing \"TOTALS YEAR-TO-DATE\" => top => get line above\n\n\n// Get start of table\ngo to page 1\n@INTERESTtop = get line containing \"TRANSACTIONS\" => bottom => get line below\n// Get end of table\n@INTERESTbottom = get line containing \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\n\n\n// Delete extra lines/texts\ndelete all lines starting \"FEES\"\ndelete all lines starting \"TOTAL XX XXXXXXXXX\"\ndelete all lines starting \"INTEREST\"\ndelete all lines containing \"TOTAL INTEREST FOR THIS PERIOD\"\ndelete all lines containing \"Tran Post Reference\"\ndelete all lines containing \"Description Number Amount\"\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\n\n// Read the transactions\n@debits = get multi page table @transactionsTop @transactionsBottom 80 115 490 600 => describe table false \"*Date[d/MM]\" Details #Credit\n@interest = get multi page table @INTERESTtop @INTERESTbottom 80 115 490 600 => describe table false \"*Date[d/MM]\" Details #Credit\n\n$transactions = combine described tables @debits @interest','2025-10-29 06:17:33',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10813,'StGeorgeReverse','$source = \"StGeorgeReverse\"\n\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n\n//Get account number\n$accountNumber = get line containing \"Available balance:\" => get words before \"Available balance:\" => take last words 3 => get text\n\n//Get account name\n$accountName = get line containing \"Account Type\" => get words after \"Account Type\" => get text\n\n//get statement period\n@periodtop = get line starting \"Date Description Debit\" => bottom\n$periodTo = get text in box @periodtop page.bottom 30 75 => take words 1 => get date \"d/MM/yyyy\"\n\n@fromtop = get last line starting \"Date Description Debit\" => bottom\n@frombottom = get last line containing \"Prev\" => top\n$periodFrom = get text in box @fromtop @frombottom 30 75 => take last words 1 => get date \"d/MM/yyyy\"\n\n//delete extra line\ndelete all lines containing \"Opening Balance\"\n\n//Get opening Balance\ngo to page 1\n@closingtop = get last line starting \"Date Description Debit\" => bottom\n@closingbottom = get last line containing \"Prev\" => top\n$closingBalance = get text in box @closingtop @closingbottom 450 545 => take last words 1 => get decimal\n\n\ngo to page 1\n//get closing Balance\n@openingtop = get line starting \"Date Description Debit\" => bottom\n$openingBalance = get text in box @openingtop page.bottom 470 545 => take words 1 => get decimal\n\n\n// Get start of table\ngo to page 1\n@transactionsTop = get line starting \"Date Description Debit\" => bottom => get line below\n\n// Get end of table\n@transactionsBottom = get last line containing \"Prev\" => top => get line above\n\ngo to page 1\n//ignore header\nget last line containing \"Date Description Debit\" => bottom => ignore header above\n\n//delete extra text/lines\ndelete all lines containing \"ibanking.stgeorge.com\"\ndelete all lines starting \"Closing Balance\"\n\n\ngo to page 1\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 7 30 75 335 390 450 545 => describe table false \"*Date[d/MM/yyyy]\" Details #Debit #Credit #Balance','2025-10-29 06:17:34',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10814,'TymeBank','$source = \"TymeBank\"\n\nset negative marker \"-\"\n\n// Get account name\n$accountName = get line containing \"Tax invoice number\" => take words 2 => get text\n\n// Get account number\n$accountNumber = get line containing \"Account Num.\" => get words after \"Account Num.\" => take words 1 => get text\n\n// Get period From/To\n$periodfrom = get line containing \"Period\" => get words after \"Period\" => take words 3 => get date \"dd MMM yyyy\"\n$periodto = get line containing \"Period\" => get words after \"-\" => take words 3 => get date \"dd MMM yyyy\"\n\n// Get Balances\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n$closingBalance = get last line starting \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\ngo to page 1\n// Get top of the transactions table\n@transactionsTop = get line starting \"Date Description Fees Money Out\" => bottom => get line below\n\n// Ignore all content below vertical position 135 (PDF coordinate for footer region)\nignore footer below 135\n\ndelete all lines starting \"Date Description Fees Money Out\"\ndelete all lines starting \"Opening Balance\"\n\n@transactionsBottom = get last line starting \"Closing Balance\" => top => get line above\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 90 300 460 525 580 => describe table false \"*Date[dd MMM yyyy]\" Details #Debit #Credit #Balance','2025-10-29 06:17:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10815,'Bnz_KiwiBusiness','$source = \"Bnz_KiwiBusiness\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"OD\"\n\n$accountNameText = get line containing \"FOR THE PERIOD\" => get words before \"FOR THE PERIOD\"\n$accountName = take last words $accountNameText 1 => get text\n\n$accountNumber = take last words $accountNameText 1 => get text\n\n$periodtext = get line containing \"FOR THE PERIOD\" => get words after \"FOR THE PERIOD\"\n\n$periodfrom = take words $periodtext 3 => get date \"d MMM yyyy\"\n$periodto = take last words $periodtext 3 => get date \"d MMM yyyy\"\n\n$openingBalanceText = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\"\n\n$openingBalance = take words $openingBalanceText 2 => get decimal\n\n\n$closingBalanceText = get last line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\"\n\n$closingBalance = take words $closingBalanceText 2 => get decimal\n\n\ngo to page 1\n@transactionsTop = get line containing \"Date Name of Other Party Type Particulars\" => top => get line below\n@transactionsBottom = get line containing \"CLOSING BALANCE\" => top => get line above\n\nget line containing \"Page\" => if not found then blank => top => ignore footer below\n\ndelete all lines containing \"CARRIED FORWARD\"\ndelete all lines containing \"Date Name of Other Party Type Particulars\"\n\n// Ignore header lines above Y-coordinate 431 (PDF units)\nignore header above 431\n\ngo to page 1\n// transactions set to Center Aligned\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 5 15 68 317 475 590 698 819 => describe table false \"Date[d MMM]\" TransactionType Details #Debit #Credit #Balance','2025-10-29 06:18:01',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10816,'Vectra_Bank','$source = \"Vectra_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n\ngo to page 1\n$top = get line containing \"Last Statement\" => bottom\n$bot = get line containing \"Account\" => bottom\n$topbot = get text in box $top 702 430 page.right => get words after \"Account\"\n\n$accountName = get words after $topbot \"Account\" => take last words 1 => get text\n$accountNumber = get words after $topbot \"Account\" => take last words 1 => get text\n\n$periodFromText = get line containing \"Last Statement:\" => get words after \"Last Statement:\"\n$periodFrom = take words $periodFromText 3 => get date \"MMMM d,yyyy\"\n$periodToText = get line containing \"This Statement:\" => get words after \"This Statement:\"\n$periodTo = take words $periodToText 3 => get date \"MMMM d,yyyy\"\n\ndelete all lines containing \"Count:\"\n\n$OpeningText = get line containing \"Previous Balance Deposits/Credits\" => bottom => get line below\n$openingBalance = get words after $OpeningText \"Amount:\"  =>  take words 1 => get decimal\n$closingBalance = take last words $OpeningText 1 => get decimal\n\n\ngo to page 1\n// Get start & end of DEPOSITS/CREDITS table\n@DepositsTop = get line containing \"DEPOSITS/CREDITS\" => if not found then blank => bottom => get line below\n@DepositsBottom = get line containing \"CHARGES/DEBITS\" => if not found then blank => top => get line above\n\n\ndelete all lines containing \"Posting Effective\"\ndelete all lines containing \"Amount Description\"\nignore footer below 45\nignore header above 688\n\n$Deposits = get multi page table @DepositsTop @DepositsBottom 40 75 125 202 510 => describe table false \"Date[M/d]\" - #Credit Details\n\ngo to page 1\n//set negative marker \"-\"\n@debitstop = get line containing \"CHARGES/DEBITS\" => if not found then blank => bottom => get line below\n@debitsbot = get line containing \"ACTIVITY COUNT\" => if not found then blank => top => get line above\n\ngo to page 1\n$dlttop1 = get line containing \"CHECKS PROCESSED\" => top\n$dltbot1 = get line containing \"Not in check sequence\" => bottom\n$dlt1 = delete text in box $dlttop1 $dltbot1 page.left page.right\n\n$dlttop = get line containing \"CHECKS PROCESSED\" => top\n$dltbot = get line containing \"ACTIVITY COUNT\" => bottom\n$dlt = delete text in box $dlttop $dltbot page.left page.right\n\ndelete all lines containing \"There were no transactions\"\n\n$debits = get multi page table @debitstop @debitsbot 40 75 125 198 510 => describe table false \"Date[M/d]\" - #Credit Details\n\n$transactions = combine described tables $Deposits $debits','2025-10-29 06:18:02',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10817,'MoneyCorp_Bank','$source = \"MoneyCorp_Bank\"\n\n$features = \"REVERSE_ORDER\"\n\n$top = get line containing \"Client reference :\" => get words after \"reference : \" => top\n$bot = get line containing \"Currency \" => bottom\n$topbot = get text in box $top $bot page.left page.right\n$accountName = take words $topbot 5 => get text\n\n$accountNumber = take words $topbot 5 => get text\n$periodtext = get line containing \"Date range :\" => get words after \"Date range :\"\n\n$periodto = take last words $periodtext 3 => get date \"d MMM yyyy\"\n$periodfrom = take words $periodtext 3 => get date \"d MMM yyyy\"\n\n\ngo to page 1\n\n$type_left = get line containing \"ID DATE TRANSACTION\" => get words before \"DATE\" => take last words 1 => left => subtract 10\n$type_right = get line containing \"ID DATE TRANSACTION\" => get words after \"ID\" => left => subtract 5\n$Date_right = get line containing \"ID DATE TRANSACTION\" => get words after \"DATE\" => left => subtract 5\n$Description_right = get line containing \"ID DATE TRANSACTION\" => get words after \"TRANSACTION\" => left => subtract 35\n$Paidin_right = get line containing \"ID DATE TRANSACTION\" => get words before \"DEBIT\" => take last words 1 => right => add 10\n$PaidOut_right = get line containing \"ID DATE TRANSACTION\" => get words after \"DEBIT\" => take words 1 => left => subtract 5\n$empty_right = get line containing \"ID DATE TRANSACTION\" => get words after \"DEBIT\" => take last words 1 => left => subtract 20\n$Balance_right = get line containing \"ID DATE TRANSACTION\" => get words after \"DEBIT\" => take last words 1 => right => add 5\n\n\n$openingBalanceText = get  line containing \"ID DATE TRANSACTION\" => top => get line below => top\n$openbot = get  line containing \"moneycorp is the trading\" => top => get line below => bottom\n$get = get text in box $openingBalanceText $openbot $empty_right $Balance_right\n$openingBalance = take words $get 1 => get decimal\n\n\n$closingBalanceText = get last line containing \"Opening balance\" => top\n$closingBalanceTextbot = get last line containing \"moneycorp is the trading\" => top\n$getopen1 = get text in box $closingBalanceText $closingBalanceTextbot $empty_right $Balance_right\n$closingBalance = take last words $getopen1 1 => get decimal\n\ngo to page 1\n@transactionsTop = get line containing \"ID DATE TRANSACTION CREDIT \" => top => get line below\n\n@transactionsBottom = get line containing \"Opening balance\" => top => get line above\n\n//delete all lines containing \"ID DATE TRANSACTION\"\n\n// Ignore footer lines below Y-coordinate 108 (PDF units)\nignore footer below 108\n// Ignore header lines above Y-coordinate 506 (PDF units)\nignore header above 506\n\ngo to page 1\n\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 $type_left $type_right $Date_right $Description_right $Paidin_right $PaidOut_right $empty_right $Balance_right => describe table false TransactionType \"Date[d MMM yyyy]\" Details #Credit #Debit - #Balance','2025-10-29 06:18:04',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10818,'BankOfCyprus_TpanezaKunpov','$source = \"BankOfCyprus_TpanezaKunpov\"\n\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.middleX => take words 6 => get text\n$accountNumber = get line starting \"Account Number\" => get words after \" Account Number\" => take words 1 => get text\n\n//Get Periods\n$periodFrom  = get line starting \"Statement Period\" => get words before \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\n$periodTo  = get line starting \"Statement Period\" => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\n\n//Get Balances\n$openingBalance = get line containing \"Balance brought forward\" => get words after \"Balance brought forward\" => take last words 1 => get decimal\n$closingBalance = get last line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => take last words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@transactionColumns = get line containing \"Transaction Details Debit Credit Balance\" => get text\n@dateLeft = get line containing @transactionColumns => take words 1 => left => subtract 5\n@date1Left = get line containing @transactionColumns => get words before \"Value\" => take words 1 => right => add 1\n@detailsLeft = get line containing @transactionColumns => get words before \"Details\" => take last words 1 => left => subtract 2\n@debitLeft = get line containing @transactionColumns => get words after \"Details\" => take words 1 => left => subtract 30\n@debitRight = get line containing @transactionColumns => get words after \"Details\" => take words 1 => right => add 10\n@CreditRight = get line containing @transactionColumns => get words before \"Balance\" => take last words 1 => right => add 10\n@balanceRight = get line containing @transactionColumns => take last words 1 => right => add 15\n\ngo to page 1\n@transLeft = get line starting \"Tran\"  => take words 1 => left => subtract 2\n@delLeftSide  = delete text in box on every page page.top 0 0 @transLeft => get text\n\ngo to page 1\n//Get start and end of table\n@transactionsTop = get line containing \"Transaction Details Debit Credit Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Balance Carried Forward\" => top => get line above\n\ngo to page 1\ndelete all lines containing \"Balance Carried Forward\"\ndelete all lines containing \"Balance brought forward\"\ndelete all lines starting \"Total\"\ndelete all lines starting \"From Prev\"\nget last line containing \"Transaction Details Debit Credit Balance\" => top => ignore header above\ndelete all lines containing \"Transaction Details Debit Credit Balance\"\ndelete all lines starting \"Date\"\ndelete all lines starting \"Tran\"\ndelete all lines starting \"Page\"\ndelete all lines starting \"Please review the present statement\"\ndelete all lines containing \"Continue on next Page\"\n\nignore footer below 88\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @date1Left @detailsLeft @debitLeft @debitRight @CreditRight @balanceRight => describe table false - \"Date[dd/MM/yyyy]\" Details #Debit #Credit *#Balance\n','2025-10-29 06:18:05',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10819,'SaintLucia_Bank','$Source = \"SaintLucia_Bank\"\nset negative marker \"OD\"\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\n\n//Get Periods\n$periodFrom = get line starting  \"Previous Balance on\" => get words after \"Previous Balance on\" => take words 1 => get date \"M/dd/yy\"\n$periodTo = get line starting \"Current Balance on\" => get words after \"Current Balance on\" => take words 1 => get date \"M/dd/yy\"\n\n//Get Balance\n$openingBalance = get line starting  \"Previous Balance on\" => get words after \"Previous Balance on\" => take last words 1 => get decimal\n$closingBalance = get line starting \"Current Balance on\" => get words after \"Current Balance on\" => take last words 1 => get decimal\n\ngo to page 1\n// Get start & end of all Checking Account Transactions\n@creditsDebitsTop = get line starting \"Checking Account Transactions\" => if not found then blank => bottom => get line below\n@creditsDebitsBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\ndelete all lines starting \"----\"\ndelete all lines starting \"Page\"\ndelete all lines containing \"Continued On Next Page\"\ndelete all lines starting \"Continued\"\ndelete all lines starting \"Choiseul\"\ndelete all lines containing \"Page Number:\"\ndelete all lines containing \"Statement Date:\"\ndelete all lines containing \"Account Number:\"\nignore header above 620\nignore footer below 70\n\ngo to page 1\n//Get start and end check last table\n@checksTop = get last line starting \"Check # Date Paid Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\n\n@ChecksL = get multi page table @checksTop @checksBottom 40 97 170 250  => describe table false ChequeNumber \"Date[M/dd/yy]\" #Debit\n@ChecksM = get multi page table @checksTop @checksBottom 290 354 424 500  => describe table false ChequeNumber \"Date[M/dd/yy]\" #Debit\n\n//delete check last table\ngo to page 1\n@chksTop = get last line starting \"Check # Date Paid Amount\" => top\n@delchecks =  delete text in box @chksTop 0 0 page.right => get text\n\n\n//Get start and end of first check table\ngo to page 1\n@checksTop1 = get line starting \"Check # Date Paid Amount\" => if not found then blank => bottom => get line below\n@checksBottom1 = get line starting \"DAILY BALANCE SUMMARY\" => top => get line above\n@ChecksL1 = get multi page table @checksTop1 @checksBottom1 40 97 170 250  => describe table false ChequeNumber \"Date[M/dd/yy]\" #Debit\n@ChecksM1 = get multi page table @checksTop1 @checksBottom1 290 354 424 500  => describe table false ChequeNumber \"Date[M/dd/yy]\" #Debit\n\n//delete check first table\ngo to page 1\n@chksTop_ = get line starting \"Check # Date Paid Amount\" => top\n@delchecks1 =  delete text in box @chksTop_ 0 0 page.right => get text\n\ndelete all lines starting \"Check # Date Paid Amount\"\ndelete all lines starting \"Checking Account Transactions\"\n\n@creditsDebits = get multi page table @creditsDebitsTop @creditsDebitsBottom 0 63 59 455 450 550  => describe table false \"*Date[M/dd/yy]\" - Details - #Credit\n\n$transactions = combine described tables @creditsDebits @ChecksL1 @ChecksM1 @ChecksL @ChecksM','2025-10-29 06:18:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10820,'LETTERKENNY_CREDIT_UNION','$source = \"LETTERKENNY_CREDIT_UNION\"\n\n//Get Accounts\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\n@accountTop = get line containing \"Account Number\" => top\n$accountNumber = get text in box @accountTop 0 150  250 => get words after \"Account Number\" => take words 1 => get text\n\n//Get Periods\n@periodTop = get line containing \"Closing Balance\" => bottom\n@periodBottom = get line starting \"Account Name\" => top\n\n$periodFrom = get text in box @periodTop @periodBottom 0 150 => get words before \"to\" => take last words 2 => get date \"dd MMMM\"\n$periodTo = get text in box @periodTop @periodBottom 0 150 => get words after \"to\" => take words 3 => get date \"dd MMMM yyyy\"\n\ngo to page 1\n//Get Opening/Closing Balance\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\n$closingBalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\ngo to page 1\n// Get transactions Column\n@transactionColumns = get line starting \"Date Description Paid Out Paid In Balance\" => get text\n@dateLeft = get line containing @transactionColumns => take words 1 => left => subtract 10\n@detailsLeft = get line containing @transactionColumns => get words after \"Date\" => take words 1 => left => subtract 10\n@debitLeft = get line containing @transactionColumns => get words after \"Description\" => take words 1 => left => subtract 5\n@debitRight = get line containing @transactionColumns => get words before \"Paid In\" => take last words 1 => right => add 10\n@creditRight = get line containing @transactionColumns => get words before \"Balance\" => take last words 1 => right => add 10\n@balanceRight = get line containing @transactionColumns => take last words 1 => right => add 10\n\ngo to page 1\n//Get start and end of table\n@transactionsTop = get line starting \"Date Description Paid Out Paid In Balance\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\nget last line starting \"Date Description Paid Out\" => top => ignore header above\nget last line starting \"Page\" => top => ignore footer below\n\ngo to page 1\ndelete all lines starting \"Date Description Paid Out Paid In Balance\"\ndelete all lines containing \"Opening Balance\"\ndelete all lines containing \"Closing Balance\"\ndelete all lines starting \"LETTERKENNY CREDIT UNION\"\ndelete all lines starting \"Your Mycu\"\ndelete all lines starting \"Page\"\n//ignore header above 650\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailsLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"Date[dd MMM yy]\" Details #Debit #Credit *#Balance\n','2025-10-29 06:18:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10821,'AustraliaPost_Bank','$source = \"AustraliaPost_Bank\"\n//$features = \"REVERSE_ORDER CREDIT_CARD\"\n$features = \"REVERSE_ORDER\"\n\n//Get Accounts\n$accountName = get line starting \"Cardholder Name\" => get words after \"Cardholder Name\" => take words 3 => get text\n$accountNumber = get line starting \"Card Number\" => get words after \"Card Number\" => take words 1 => get text\n\n//Get Opening Closing Balance\n$closingBalance = get line starting \"Opening Balance\" => bottom => get line below => take words 1 => get decimal\n$openingBalance = get line starting \"Closing Balance\" => bottom => get line below => take words 1 => get decimal\n\n//Get Periods\ngo to page 1\n$periodFrom = get line starting \"Statement for Period\" => get words before \"to\" => take last words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line starting \"Statement for Period\" => get words after \"to\" => take words 3 => get date \"dd MMM yyyy\"\n\ngo to page 1\n//Get start and end of table\n@transactionsTop = get line containing \"Date Transaction Description\" => bottom => get line below\n@transactionsBottom = get last line starting \"Mastercard Prepaid Management Services Australia Pty Ltd\" => top => get line above\n\nget last line starting \"Mastercard Prepaid\" => top => ignore footer below\ngo to page 1\ndelete all lines starting \"Card\"\ndelete all lines containing \"Date Transaction Description\"\ndelete all lines containing \"Merchant Name/ Address Merchant Currency\"\ndelete all lines ending \"Amount\"\ndelete all lines starting \"Exchange rate\"\ndelete all lines starting \"Mastercard Prepaid\"\ndelete all lines starting \"Page\"\nignore header above 815\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 114 244 408 495 => describe table false \"*Date[dd-MM-yyyy]\" TransactionType Details #Credit\n','2025-10-29 06:18:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10822,'XACE_Bank','$source = \"XACE_Bank\"\nset negative marker \"-\"\n$periodBufferDays = 28\n\n// ---------------- Account details ----------------\n$accountName = get text in box page.top 0 0 page.middleX => take words 4 =>  get text\n@statementLine = get line containing \"Statement Number:\" => get words before \"Number:\"\n@accountTop = take last words @statementLine 1 => bottom\n@accountLeft = take last words @statementLine 1 => left => subtract 5\n$accountNumber = get text in box @accountTop 0 @accountLeft page.right => get words after \":\" => take words 1 => get text\n\n// ---------------- Periods ----------------\n@periodLine = get line containing \"Statement Period:\"\n$periodFrom =  get words before @periodLine \"To:\" => take last words 1 => get date \"d-M-yy\"\n$periodTo = get words after @periodLine \"To:\" => take words 1 => get date \"d-M-yy\"\n\n// ---------------- Balances ----------------\n$openingBalance = get line containing \"Opening Balance:\" => get words after \"Opening Balance:\" => take words 1 => get decimal\n$closingBalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" => take words 1 => get decimal\n\n// ---------------- Header & column coordinates ----------------\ngo to page 1\n@header = get line starting \"Date Counterpart Paid Out Paid In Balance\"\n\n// Column coordinates\n@dateLeft =  take words @header 1 => left => subtract 10\n@dateRight =  take words @header 1 => right => add 30\n@detailsLeft =  get words after @header \"Date\" => take words 1 => left => subtract 5\n@detailsRight =  take words @header 3 => take last words 1 => left => add 3\n@debitLeft =  take words @header 3 => take last words 1 => left => subtract 10\n@creditLeft =  get words after @header \"Paid Out\" => take words 1 => left => subtract 10\n@balanceLeft =  take last words @header 1 => left => subtract 10\n@balanceRight =  take last words @header 1 => right => add 30\n\n// ---------------- Transaction anchors ----------------\n@transactionTop = get line containing \"Date Counterpart Paid Out Paid In Balance\" =>  bottom => get line below\n\n// Bottom anchor from last page footer\nget last line containing \"Xace\"\n@transactionbottom = get line above 0 => top => get line above\n\ngo to page 1\n// Remove footers, header repeats, noise lines, page numbers.\n\n@footerTop =  get last line starting \"Xace Limited | www.xace.io\" => top\n@delfooter = delete text in box @footerTop 0 0 page.right\n\n@footerTop1 =  get last line starting \"Xace | https://xace.io\" => top\n@delfooter1 = delete text in box @footerTop1 0 0 page.right\n\ndelete all lines starting \"Xace\"\ndelete all lines starting \"Date Counterpart Paid Out Paid In Balance\"\ndelete all lines starting \"Street\"\ndelete all lines starting \"1 of\"\ndelete all lines starting \"2 of\"\ndelete all lines starting \"3 of\"\ndelete all lines starting \"4 of\"\ndelete all lines starting \"5 of\"\ndelete all lines starting \"6 of\"\ndelete all lines starting \"7 of\"\ndelete all lines starting \"8 of\"\ndelete all lines starting \"9 of\"\ndelete all lines starting \"10 of\"\ndelete all lines starting \"11 of\"\ndelete all lines starting \"12 of\"\ndelete all lines starting \"13 of\"\ndelete all lines starting \"14 of\"\ndelete all lines starting \"15 of\"\ndelete all lines starting \"16 of\"\ndelete all lines starting \"17 of\"\ndelete all lines starting \"18 of\"\ndelete all lines starting \"19 of\"\ndelete all lines starting \"20 of\"\ndelete all lines starting \"21 of\"\ndelete all lines starting \"22 of\"\ndelete all lines starting \"23 of\"\ndelete all lines starting \"24 of\"\ndelete all lines starting \"25 of\"\ndelete all lines starting \"1 /\"\ndelete all lines starting \"2 /\"\ndelete all lines starting \"3 /\"\ndelete all lines starting \"4 /\"\ndelete all lines starting \"5 /\"\ndelete all lines starting \"6 /\"\ndelete all lines starting \"7 /\"\ndelete all lines starting \"8 /\"\ndelete all lines starting \"9 /\"\ndelete all lines starting \"10 /\"\ndelete all lines starting \"11 /\"\ndelete all lines starting \"12 /\"\ndelete all lines starting \"13 /\"\ndelete all lines starting \"14 /\"\ndelete all lines starting \"15 /\"\ndelete all lines starting \"16 /\"\ndelete all lines starting \"17 /\"\ndelete all lines starting \"18 /\"\ndelete all lines starting \"19 /\"\ndelete all lines starting \"20 /\"\ndelete all lines starting \"21 /\"\ndelete all lines starting \"22 /\"\ndelete all lines starting \"23 /\"\ndelete all lines starting \"24 /\"\ndelete all lines starting \"25 /\"\n\n// Extract transactions table\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @dateRight @detailsLeft @detailsRight @debitLeft  @creditLeft  @balanceLeft @balanceRight => describe table false \"*Date[d-M-yy]\" - Details - #Debit  #Credit #Balance\n','2026-01-07 06:33:06',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10823,'ServusCU_MasterCard','$source = \"ServusCU_MasterCard\"\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\n\n//Get accounts\ngo to page 1\n$accountnameText = get line containing \"Account Number:\" => get words after \"Account Number:\"\n$accountname = take last words $accountnameText 4 => take words 1 => get text\n$accountnumber = take last words $accountnameText 4 => take words 1 => get text\n\n//Get Periods\n$periodfrom = take last words $accountnameText 3 => take words 1  => get date \"M/d/yyyy\"\n$periodto = take last words $accountnameText 1 => get date \"M/d/yyyy\"\n\n//Get Opening and Closing Balance\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\n$closingBalance = get line containing \"NEW BALANCE\" => get words after \"NEW BALANCE\" => take words 1 => get decimal\n\n//Get Dynamic Co-ordinates\ngo to page 1\n$Date_left1 = get line containing \"Trans Date Post Date\" => get words before \"Date\" => take words 1 => left => subtract 5\n$Date_right1 = get line containing \"Trans Date Post Date\" => get words after \"Trans\" => take words 1 => right => add 3\n$PostDate_right1 = get line containing \"Trans Date Post Date\" => get words after \"Post\" => take words 1 => right => add 3\n$Description_right1 = get line containing \"Trans Date Post Date\" => get words after \"Description\" => left => subtract 20\n$Paidout_right1 = get line containing \"Trans Date Post Date\" => get words after \"Description\" => right => add 25\n\n//First Table Transactions\ngo to page 1\n@transactionsTop = get line starting \"Trans Date Post Date\" => if not found then blank => bottom => get line below\n@transactionBottom = get line containing \"PLEASE DETACH THE REMITTANCE\" => if not found then blank => top => get line above\n\n$transactions1 = get multi page table @transactionsTop @transactionBottom  $Date_left1 $Date_right1 $PostDate_right1 $Description_right1 $Paidout_right1 => describe table false - \"*Date[M/d]\" Details *#Credit\n\n//Second Table Starts here\ngo to page 2\n$Date_left = get line containing \"Trans Date Post Date\" => get words before \"Date\" => take words 1 => left => subtract 5\n$Date_right = get line containing \"Trans Date Post Date\" => get words after \"Trans\" => take words 1 => right => add 3\n$PostDate_right = get line containing \"Trans Date Post Date\" => get words after \"Post\" => take words 1 => right => add 3\n$Description_right = get line containing \"Trans Date Post Date\" => get words after \"Description\" => left => subtract 20\n$Paidout_right = get line containing \"Trans Date Post Date\" => get words after \"Description\" => right => add 25\n\n@transactionsTop1 = get line starting \"Trans Date Post Date\" => if not found then blank => bottom => get line below\n@transactionBottom1 = get line starting \"Circle Rewards Bonus\" => if not found then blank => top => get line above\n\ngo to page 1\n$top = get line containing \"ACCOUNT STATEMENT DISCLOSURE\" => top\n$bot = get line containing \"Account Agreement: Please \" => bottom\n$dlt = delete text in box $top $bot page.left page.right => get text\n\n\n$text1 = get line starting \"Cardholder Account Detail\" => top => get line above => take words 2 => get text\ndelete all lines starting $text1\n\n$text2 = get line starting \"Cardholder Account Detail\" => top => get line above => take words 2 => get text\ndelete all lines starting $text2\n\n$text3 = get line starting \"Cardholder Account Detail\" => top => get line above => take words 2 => get text\ndelete all lines starting $text3\n\n\ndelete all lines containing \"Trans Date Post Date\"\ndelete all lines containing \"Detail\"\ndelete all lines containing \"Continued\"\ndelete all lines containing \"Page\"\nignore footer below 20\n\n\ngo to page 1\n$transactions2 = get multi page table @transactionsTop1 @transactionBottom1  $Date_left $Date_right $PostDate_right $Description_right $Paidout_right => describe table false - \"*Date[M/d]\" Details *#Credit\n\n$transactions = combine described tables $transactions1 $transactions2','2026-01-07 06:33:07',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10824,'eFirstBank_US','$source = \"eFirstBank_US\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n\n//Get Accounts\n$accountName = get line starting \"ACCOUNT\" => get words after \"ACCOUNT\" => take words 1 => get text\n$accountNumber = get line starting \"ACCOUNT\" => get words after \"ACCOUNT\" => take words 1 => get text\n\ngo to page 1\n//get Periods\n$periodFromText = get line containing \"PREVIOUSSTATEMENT\" => get words after \"DATE:\"\n$periodFrom = take words $periodFromText 1 => get date \"M-d-yyyy\"\n$openingBalance = take last words $periodFromText 1 => get decimal\n$periodToText = get line containing \"THISSTATEMENT\" => get words after \"DATE:\"\n$periodTo = take words $periodToText 1 => get date \"M-d-yyyy\"\n$closingBalance = take last words $periodToText 1 => get decimal\n\ngo to page 1\n$chequestop = get line starting \"CHECKSANDOTHERWITHDRAWALS\" => if not found then blank => bottom => get line below\n$chequesbottom = get line containing \"ELECTRONICANDMISCELLANEOUSWITHDRAWALS\" => top => get line above\n\ndelete all lines containing \"NOCHECKSWITHSERIALNUMBERSTHISCYCLE\"\ndelete all lines containing \"DATE\"\n\n$checksleft = get multi page table $chequestop $chequesbottom 70 100 183 210 => describe table false ChequeNumber #Debit \"*Date[M-d]\"\n$checksright = get multi page table $chequestop $chequesbottom 235 257 345 372 => describe table false ChequeNumber #Debit \"*Date[M-d]\"\n$checksright2 = get multi page table $chequestop $chequesbottom 397 416 506 532 => describe table false ChequeNumber #Debit \"*Date[M-d]\"\n\ngo to page 1\n$chequestop1 = get line starting \"CHECKSCONVERTEDTOELECTRONICTRANSACTIONS\" => if not found then blank => bottom => get line below\n$chequesbottom1 = get line containing \"ELECTRONICANDMISCELLANEOUSWITHDRAWALS\" => if not found then blank => top => get line above\n\n$checksconverted = get multi page table $chequestop1 $chequesbottom1 70 105 170 260 465 => describe table false ChequeNumber \"*Date[M-d]\" #Debit Details\n\ngo to page 1\n$debitstop = get line containing \"ELECTRONICANDMISCELLANEOUSWITHDRAWALS\" => if not found then blank => bottom => get line below\n$debitsbottom = get line containing \"ELECTRONICANDMISCELLANEOUSADDITIONS\" => if not found then blank => top => get line above\n\ndelete all lines containing \"DESCRIPTION\"\ndelete all lines containing \"ELECTRONICANDMISCELLANEOUSADDITIONS\"\ndelete all lines containing \"CONTINUED\"\ndelete all lines containing \"DATE\"\n\n$debits = get multi page table $debitstop $debitsbottom 70 105 154 390 465 => describe table false \"*Date[M-d]\" #Debit TransactionType Details\n\ngo to page 1\n$creditstop = get line starting \"DEPOSITSANDOTHERADDITIONS\" => bottom => get line below\n$creditsbottom = get line containing \"DAILYBALANCESUMMARY\" => top => get line above\n\ndelete all lines containing \"CONTINUEDONNEXTPAGE\"\ndelete all lines containing \"ELECTRONICANDMISCELLANEOUSADDITIONS\"\n$credits = get multi page table $creditstop $creditsbottom 70 105 154 390 465 => describe table false \"*Date[M-d]\" #Credit TransactionType Details\n\n\n$transactions = combine described tables $checksleft $checksright $checksright2 $checksconverted $debits $credits','2026-01-07 06:33:08',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10825,'ArizonaFinancial_CreditUnion','$source = \"ArizonaFinancial_CreditUnion\"\n$periodBufferDays = 30\n\n//Account Number\n@accountNumberTop = get line containing \"Account No.\" => bottom\n$accountNumberBox = get text in box @accountNumberTop 725 page.middleX page.right\n$accountNumber = take words $accountNumberBox 1 => get text\n\n//account Name\n$accountNameBox = get text in box 645 610 0 page.middleX\n$accountName = take words $accountNameBox 2 => get text\n\n//Period From and Period\n$periodFrom = take words $accountNumberBox 2 => take last words 1 => get date \"MM/dd/yy\"\n$periodTo = take words $accountNumberBox 4 => take last words 1 => get date \"MM/dd/yy\"\n\n//Opening Balance and Closing Balance\n$openingBalance = get line containing \"BALANCE FORWARD\" => get words after \"BALANCE FORWARD\" => take last words 1 => get decimal\n$closingBalance = get line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => take last words 1 => get decimal\n\n//Define transaction table markers\ngo to page 1\n@transactionsTop = get line containing \"BALANCE FORWARD\" => bottom => get line below\n\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\n\nignore header above 675\nignore footer below 35\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 81 118 390 520 580 => describe table false - \"Date[MM/dd/yy]\" Details *#Credit #Balance','2026-01-07 06:33:09',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10826,'Coast_Capital_Savings','$source = \"Coast_Capital_Savings\"\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\n$periodBufferDays = 30\n\n// Get Account Number\n\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n\n// Get Account Name\n\n$accountName = get line containing \"Help Headquarters\" => top => get line above => take words 3 => get text\nignore footer below 111\n//Get PeriodInBOx\n\n@PeriodToTop = get line containing \"Trans. Date Value date Description\" => bottom\n$PeriodToBox = get text in box @PeriodToTop 0 120 180\n$PeriodTo = take words $PeriodToBox 1 => get date \"MMM-dd-yyyy\"\n\ngo to last page\n@PeriodToTop = get line containing \"Trans. Date Value date Description\" => bottom\n$PeriodToBox = get text in box @PeriodToTop 0 120 180\n$PeriodFrom = take last words $PeriodToBox 1 => get date \"MMM-dd-yyyy\"\n\ngo to page 1\n@TEXTBOXTop = get line containing \"Trans. Date Value date Description\" => bottom\n$TEXTBOX = get text in box @TEXTBOXTop 0 385 page.right\n$openingBalance = take words $TEXTBOX 1 => get decimal\n\ngo to last page\n@TEXTBOXTop2 = get line containing \"Trans. Date Value date Description\" => bottom\n$TEXTBOX2 = get text in box @TEXTBOXTop2 0 385 450\n$closingBalance = take last words $TEXTBOX2 1 => get decimal\n\ngo to page 1\n@transactionstop = get line containing \"Trans. Date Value date Description\" => bottom => get line below\ngo to last page\n@transactionsbottom = get text in box 111 page.bottom page.left page.right => top => get line above\n\ndelete all lines starting \"Trans. Date Value date Description\"\n\nignore header above 680\n\n$transactions = get multi page table center aligned @transactionstop @transactionsbottom 4.5 50 122 185 325 390 448 => describe table false - \"Date[MMM-dd-yyyy]\" Details #Credit #Balance','2026-01-07 06:33:11',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10827,'Crown_Agents_Bank','$source = \"Crown_Agents_Bank\"\n\n// Account Name\n$accountName = get line containing \"Account Name:\" => get words after \"Account Name:\" => get text\n\n// Account Number\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\n\n// Period From & To\n$periodFrom = get line containing \"Value date Tran. Date Tran. Type Reference\" => top => get line above => get words before \"-\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line containing \"Value date Tran. Date Tran. Type Reference\" => top => get line above => get words after \"-\" => take words 3 => get date \"dd MMM yyyy\"\n\n// Opening Balance\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\n\n// Closing Balance\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\n\n// Transaction Table Markers\ngo to page 1\n@transactionsTop = get line starting \"Value date Tran. Date Tran. Type\" => bottom => get line below\ndelete all lines containing \"Opening Balance\"\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n// Cleanup Commands\ndelete all lines starting \"Value date Tran. Date\"\nignore header above 658\nignore footer below 90\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 78 132 190 328 465 535 585 => describe table false \"*Date[dd-MMM-yy]\" - TransactionType - Details #Credit #Balance','2026-01-07 06:33:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10828,'BOQ_DateProcessedDescription','$source = \"BOQ_DateProcessedDescription\"\n$features = \"NO_TRANSACTION_YEAR\"\nset negative marker \"-\"\ndelete text in box on every page page.top page.bottom page.left 30\n\n// Get account number\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\n@AccountTop = get line containing \"Statement period\" => bottom => get line below => bottom\n@AccountBottom = get line containing \"Account summary\" => top\n$accountName = get text in box @AccountTop @AccountBottom page.left page.middleX => take words 3 => get text\n\n// Get period from/to\n$periodFrom = get line containing \"Statement period\" => bottom => get line below => get words before \"-\" => get date \"d MMM yyyy\"\n$periodTo = get line containing \"Statement period\" => bottom => get line below => get words after \"-\" => get date \"d MMM yyyy\"\n\n// Get opening and closing balances\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\n$closingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\n\n// Get start and end of table\ngo to page 1\n@transactionsTop = get line containing \"Date Processed Description\" => bottom => get line below => bottom => get line below\n@transactionsBottom = get line containing \"Keeping your account safe\" => top => get line above\n\n// Delete unwanted lines\ndelete all lines containing \"continues over\"\ndelete all lines containing \"Everyday Account Statement\"\ndelete all lines starting \"Transactions\"\ndelete all lines containing \"Date Processed Description\"\ndelete all lines containing \"Bank of Queensland\"\ndelete all lines starting \"202\"\n\n// Get Transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 90 160 289 360 480 560 => describe table false \"*Date[dd-MMM]\" - Details #Debit #Credit #Balance','2026-01-07 06:33:13',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10829,'BankOfHope_PostDateDescriptionDebitsCreditsBalance','$source = \"BankOfHope_PostDateDescriptionDebitsCreditsBalance\"\n$features = \"NO_TRANSACTION_YEAR\"\n$periodBufferDays = 14\n\n// Get account name & number\n$accountName = get line containing \"Statement Ending\" => bottom => get line below => take words 3 => get text\n$accountNumber = get line containing \"Customer Number:\" => get words after \"Customer Number:\" => get text\n\ngo to page 1\ndelete all lines ending \"Ending Balance\"\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\n@TEXTBOXBottom = get line containing \"Ending Balance\" => bottom\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 0 350\n\n// Get statement period\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\n\n// Get opening & closing balance\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\n\n// Get transactions table\n@transactionTop = get line starting \"Post Date Description Debits\" => bottom => get line below\n@transactionBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\n\nignore header above 685\n\n// Delete unwanted lines\ndelete all lines containing \"Post Date Description Debits\"\ndelete all lines containing \"(continued)\"\ndelete all lines containing \"Date Processed Description\"\ndelete all lines containing \"Beginning Balance\"\ndelete all lines containing \"Ending Balance\"\n\n$transactions = get multi page table @transactionTop @transactionBottom 35 95 320 425 500 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2026-01-07 06:33:15',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10830,'Affinity_CreditUnion','$source = \"Affinity_CreditUnion\"\n\ndelete all lines containing \"statement of accounts\"\n\ngo to page 1\n@Datesbottom = get line containing \"Date\" => bottom\n@Dates = get text in box page.top @Datesbottom page.middleX 600\n\n$periodFrom = get words before @Dates \"Date\" => take words 3 => get date \"MMMM d, yyyy\"\n$periodTo = get words after @Dates \"to\" => take last words 3 => get date \"MMMM d, yyyy\"\n\n$accountName = get text in box page.top page.middleY 0 page.middleX => take words 3 => get text\n\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\n\n@transactionsTop = get line starting \"Date Description Withdrawals Deposits\" => bottom => get line below => bottom => get line below\n\n$openingBalance = get line containing \"Balance Forward\" => get words after \"Balance Forward\" => get decimal\n\n@transactionsBottom = get last line starting \"Total\" => top => get line above\n\n@closingbalanceBottom = get line starting \"Total\" => top\n@closingbalanceTop = get text in box page.top @closingbalanceBottom 505 600 => take last words 1 => top => get line above => bottom\n$closingbalance =  get text in box @closingbalanceTop @closingbalanceBottom 505 600 => get decimal\n\n$transactions = get multi page table @transactionsTop @transactionsBottom 45 95 365 440 505 600 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance','2026-01-07 06:33:16',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10831,'CentralBankTrustCo','$source = \"CentralBank&TrustCo\"\n$features = \"NO_TRANSACTION_YEAR\"\n\ngo to page 1\n@Summarytop = get line containing \"FOR ACCOUNT NUMBER:\" => top\n@Summarybottom = get line containing \"FOR STATEMENT PERIOD:\" => bottom => get line below => bottom\n@Summary = get text in box @Summarytop @Summarybottom page.middleX page.right\n\n$accountNumber = get words after @Summary \"NUMBER:\" => get words between \"NUMBER:\" \"FOR STATEMENT\" => get text\n$periodFrom = get words after @Summary \"STATEMENT PERIOD\" => get words between \"PERIOD:\" \"TO\" => get date \"MM/dd/yy\"\n$periodTo = get words after @Summary \"TO\"  => take last words 1 => get date \"MM/dd/yy\"\n$accountName = get text in box @Summarytop @Summarybottom 0 page.middleX => take words 3 => get text\n\n@Balancestop = get line containing \"Beginning\" => bottom => get line below => bottom\n@Balancesbottom = get line containing \"Beginning\" => bottom => get line below => bottom => get line below => bottom\n$OpeningBalance = get text in box @Balancestop @Balancesbottom 0 125 => get words after \"Balance\" => get decimal\n$closingBalance = get text in box @Balancestop @Balancesbottom 500 580 => get words after \"Balance\" => get decimal\n\n@DepositsTop = get line starting \"Deposits & Other Credits\" => if not found then blank => bottom => get line below\n@DepositsBottom = get last line starting \"Deposits & Other Credits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\ngo to page 1\n@WithdrawalsTop = get line starting \"Withdrawals & Charges\" => if not found then blank => bottom => get line below\n@WithdrawalsBottom = get last line starting \"Withdrawals & Charges\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\n\ngo to page 1\n@checksTop = get line starting \"Date Check Amount\" => if not found then blank => bottom => get line below\n@checksBottom = get last line containing \"Break in Check Sequence\" => if not found then blank => top => get line above\n\ndelete all lines starting \"Date Amount\"\ndelete all lines starting \"Deposits & Other Credits\"\ndelete all lines starting \"Withdrawals & Charges\"\ndelete all lines starting \"Date Check Amount\"\ndelete all lines starting \"Check Activity\"\n\ngo to page 1\nignore header above 728\n\n$Credits = get multi page table @DepositsTop @DepositsBottom 50 120 240 600 => describe table false \"*Date[MM/dd]\" #Credit Details\n$Debits = get multi page table @WithdrawalsTop @WithdrawalsBottom 50 120 240 600 => describe table false \"*Date[MM/dd]\" #Debit Details\n$checksLeft = get multi page table @checksTop @checksBottom 50 120 170 225 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n$checksMiddle = get multi page table @checksTop @checksBottom 225 270 330 380 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n$checksRight = get multi page table @checksTop @checksBottom 380 425 490 600 => describe table false \"*Date[MM/dd]\" ChequeNumber #Debit\n\n$transactions = combine described tables $Credits $Debits $checksLeft $checksMiddle $checksRight','2026-01-07 06:33:17',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10832,'ING_InterimStatement','$source = \"ING_InterimStatement\"\n$periodBufferDays = 30\n\n//Account Number\n$accountNumber = get line containing \"ACC:\" => get words after \"ACC:\" => take words 1 => get text\n\n// Get Account Name\n$accountName = get text in box 722 710 page.left page.middleX => take words 2 => get text\n\n//Period\n$periodFrom = get line containing \"Statement Start Date\" => get words after \"Statement Start Date\" => take words 3 => get date \"dd MMM yyyy\"\n$periodTo = get line containing \"Statement End Date\" => get words after \"Statement End Date\" => take words 3 => get date \"dd MMM yyyy\"\n\n//Opening Balance\n$openingBalance = get line containing \"Brought Forward\" => get words after \"Brought Forward\" => take words 1 => get decimal\n\n//Closing Balance\n$closingBalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\n\n// Define Transaction Table Markers\ngo to page 1\n@transactionsTop = get line starting \"Brought Forward\" => bottom => get line below\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\n\n// Cleanup Commands\ndelete all lines starting \"Date Description Amount\"\nignore header above 788\nignore footer below 100\n\n// Read the transactions\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 130 340 505 570 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit #Balance','2026-01-07 06:33:18',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10833,'MechanicsBank','$source = \"MechanicsBank\"\r\n\r\ndelete tiny words\r\ndelete rotated words\r\ndelete white words\r\n\r\n@TEXTBOXBottom = get line containing \"Summary of Accounts\" => top\r\n// Get account name\r\n$accountName = get text in box 700 @TEXTBOXBottom 0 348 => take words 3 => get text\r\n$accountNumber = get line containing \"Account Type Account Number\" => bottom => get line below => get words before \"$\" => take last words 1 => get text\r\ngo to page 1\r\ndelete all lines ending \"Ending Balance\"\r\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\r\n@TEXTBOXBottom1 = get line containing \"Ending Balance\" => bottom\r\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom1 0 350\r\n\r\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\r\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\r\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\r\n\r\nremove page 2\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@DepositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\r\n//@DepositsBottom = get line ending \"Electronic Credits\" => if not found then blank => top => get line above\r\n@DepositsBottom = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\r\n\r\ngo to page 1\r\n// Get start & end of Deposits continued table\r\n@DepositscontinuedTop = get line starting \"Deposits (continued)\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@DepositscontinuedBottom = get line starting \"Deposits (continued)\" => if not found then blank => bottom => get line below => bottom => get break below => get line at\r\n\r\ngo to page 1\r\n// Get start & end of credits table\r\n@creditsTop = get line ending \"Credits\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@creditsBottom = get line ending \"Debits\" => if not found then blank => top => get line above\r\n\r\n//@creditsTop1 = get line starting \"Other Credits\" => if not found then blank => bottom => get line below => bottom => get line below\r\n//@creditsBottom1 = get line ending \"Debits\" => if not found then blank => top => get line above\r\n\r\nignore header above 736\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines containing \"Other Credits\"\r\ndelete all lines containing \"Electronic Credits\"\r\n//delete all lines containing \"RETURNED STOP PAY ITEM\"\r\n\r\ngo to page 1\r\n// Get start & end of debits table\r\n@debitsTop = get line starting \"Electronic Debits\" => bottom => get line below\r\n//@debitsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\r\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\r\ndelete all lines containing \"Other Debits\"\r\n\r\n// Get start & end of cheques table\r\ngo to page 1\r\n@chequeTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\r\n@chequebottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Check Nbr Date Amount\"\r\n@checkconttop = get line starting \"Checks Cleared (continued)\" => top\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines starting \"* Indicates skipped check number\"\r\n\r\n$chequeLeft = get multi page table @chequeTop @chequebottom 55 91 150 210 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n$chequeMiddle = get multi page table @chequeTop @chequebottom 210 273 335 410 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n$chequeRight = get multi page table @chequeTop @chequebottom 410 459 515 580 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n\r\n// Deleted check tables\r\ndelete text in box @checkconttop page.bottom page.left page.right\r\ngo to page 1\r\n@checktop = get line starting \"Checks Cleared\" => top\r\ndelete text in box @checktop page.bottom page.left page.right\r\n\r\ndelete all lines containing \"item(s) totaling\"\r\n\r\n$Deposits = get multi page table @DepositsTop @DepositsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n$Depositscontinued = get multi page table @DepositscontinuedTop @DepositscontinuedBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n$credits = get multi page table @creditsTop @creditsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n//@creditother = get multi page table @creditsTop1 @creditsBottom1 35 90 510 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n$debits = get multi page table @debitsTop @debitsBottom 35 90 515 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\r\n\r\n\r\n$transactions = combine described tables $Deposits $Depositscontinued $credits $debits $chequeLeft $chequeMiddle $chequeRight','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10834,'Stock_Yard_Bank','$source = \"Stock_Yard_Bank\"\n$features = \"NO_TRANSACTION_YEAR\"\n\n//Get Accounts\n$accountName = get line starting \"Primary Account:\" => get words after \"Primary Account:\" => take words 1 => get text\n$accountNumber = get line starting \"Primary Account:\" => get words after \"Primary Account:\" => take words 1 => get text\n\n//get Periods\ngo to page 1\n$top = get line containing \"LAST STATEMENT\" => top\n$bot = get line starting \"TOTAL DAYS\" => bottom\n$periodtext = get text in box $top $bot page.left page.right\n$openingBalance = get words after $periodtext \"LAST STATEMENT\" => take words 2 => take last words 1 => get decimal\n$closingBalance = get words after $periodtext \"THIS STATEMENT\" => take words 2 => take last words 1 => get decimal\n\n$periodFrom = get words after $periodtext \"STATEMENT PERIOD\" => take words 1 => get date \"M/d/yy\"\n$periodTo = get words after $periodtext \"THROUGH\" => take words 1 => get date \"M/d/yy\"\n\n//Get Deposit Table\ngo to page 1\n$deposittop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below\n$depositbottom = get line containing \"OTHER CREDITS\" => if not found then blank => top => get line above\n\ndelete all lines containing \"REF # DATE\"\n$deopositleft = get multi page table $deposittop $depositbottom 37 70 133 200 => describe table false ChequeNumber \"*Date[M/d]\" #Credit\n$depositright = get multi page table $deposittop $depositbottom 225 257 322 387 => describe table false ChequeNumber \"*Date[M/d]\" #Credit\n$depositright2 = get multi page table $deposittop $depositbottom 400 445 508 575 => describe table false ChequeNumber \"*Date[M/d]\" #Credit\n\n//Get Credits Table\ngo to page 1\n$creditstop = get line starting \"OTHER CREDITS\" => bottom => get line below\n$creditsbottom = get line containing \"CHECKS\" => top => get line above\n\ndelete all lines containing \"DESCRIPTION\"\ndelete all lines containing \"OTHER CREDITS\"\ndelete all lines containing \"Page:\"\ndelete all lines containing \"Statement Date:\"\ndelete all lines containing \"Primary Account:\"\n\n$credits = get multi page table $creditstop $creditsbottom 37 450 483 575 => describe table false Details \"*Date[M/d]\" #Credit\n\n//Get Checks Table\ngo to page 1\n$chequestop = get line containing \"CHECK # DATE AMOUNT\" => if not found then blank => bottom => get line below\n$chequesbottom = get line containing \"OTHER DEBITS\" => if not found then blank => top => get line above\n\ndelete all lines containing \"INDICATES A GAP\"\ndelete all lines containing \"CHECK #\"\n\n$checksleft = get multi page table $chequestop $chequesbottom 37 85 133 200 => describe table false ChequeNumber \"*Date[M/d]\" #Debit\n$checksright = get multi page table $chequestop $chequesbottom 225 257 322 387 => describe table false ChequeNumber \"*Date[M/d]\" #Debit\n$checksright2 = get multi page table $chequestop $chequesbottom 400 445 508 575 => describe table false ChequeNumber \"*Date[M/d]\" #Debit\n\n//Get Debits Table\ngo to page 1\n$debitstop = get line containing \"OTHER DEBITS\" => if not found then blank => bottom => get line below\n$debitsbottom = get line containing \"DAILY BALANCE\" => if not found then blank => top => get line above\n\n$debits = get multi page table $debitstop $debitsbottom 37 450 483 575 => describe table false Details \"*Date[M/d]\" #Debit\n\n$transactions = combine described tables $deopositleft $depositright $depositright2 $credits $checksleft $checksright $checksright2 $debits','2026-01-07 06:33:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10835,'FiveBank','$source = \"FiveBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n@TEXTBOXAcctRight = get line containing \"Summary\" => left\r\n@TEXTBOXAcctBottom = get line containing \"Date Transaction Description\" => top => get line above => top\r\n@TEXTBOXAcctTop = get line containing \"Summary\" => bottom\r\n\r\n//Get Account name and number\r\n$accountName = get text in box @TEXTBOXAcctTop @TEXTBOXAcctBottom 0 370 => get text\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\r\n\r\n//Get Periods\r\n$periodFrom = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 3 => get date \"MMM dd yyyy\"\r\n$periodTo = get line containing \"Statement Date:\" => get words after \"thru\" => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n//Get Opening and Closing BALANCE\r\n$openingBalance = get line containing \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => take words 1 => get decimal\r\n$closingBalance = get line starting \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => get decimal\r\n\r\n// trans1 table Transactions\r\ngo to page 1\r\n@transactionsTop = get line starting \"BEGINNING BALANCE\" => bottom => get line below\r\n\r\n@transactionsBottom = get line starting \"ENDING BALANCE\" => top => get line above\r\nignore header above 672\r\nignore footer below 20\r\n\r\ndelete all lines starting \"(Continued)\"\r\ndelete all lines containing \"Electronic Check AMERICAN PAYMENT\"\r\ndelete all lines containing \"PAYMENT WLK IN PAY\"\r\ndelete all lines starting \"Date Transaction Description Withdrawal\"\r\n\r\ndelete all pages containing \"In Case Of Errors\"\r\n\r\nset negative marker \"-\"\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 78 367 460 520 580 => describe table false \"*Date[MMM dd]\" Details #Debit #Credit #Balance','2026-05-14 09:56:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10844,'Zip_Pay_CreditCard','$source = \"Zip_Pay_CreditCard\"\r\n\r\n$periodBufferDays = 30\r\n\r\n$features = \"CREDIT_CARD\"\r\n\r\nset negative marker \"($\"\r\n\r\n// Account Name\r\n\r\n$accountName = get line containing \"Statement\" => bottom => get line below => take words 2 => get text\r\n\r\n$accountNumber = get line containing \"Account ID\" => get words after \"Account ID\" => take words 1 => get text\r\n\r\n// Period From and To\r\n\r\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\n$periodTo   = get line containing \"Statement Period\" => get words after \"-\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\n// Opening & Closing Balances (get decimal per your rule)\r\n\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\r\n\r\n$closingBalance = get line containing \"C l o s i n g B a l a n c e\" => get words after \"C l o s i n g B a l a n c e\" => take words 1 => get decimal\r\n\r\n// Transaction Table\r\ngo to page 1\r\n@transactionsTop = get line starting \"D a t e D e s c r i p t i o n A m o u n t\" => bottom => get line below => bottom => get line below\r\n\r\n@transactionsBottom = get last line containing \"C l o s i n g B a l a n c e\" => top => get line above\r\n\r\nignore header above 800\r\n\r\nignore footer below 25\r\n\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 32 105 450 550 => describe table false \"Date[d MMM yyyy]\" Details *#Credit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10845,'CynergyBank_PostedValue_TopAligned','$source = \"CynergyBank_PostedValue_TopAligned\"\r\n$periodBufferDays = 14\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\n\r\n// Get Account Details\r\n$accountnumber = get line starting \"Account:\" => get words after \"Account:\" => take words 1 => get text\r\n$accountname = get line starting \"Account name:\" => get words after \"Account name:\" => take words 2 => get text\r\n\r\n// Get Statement Period\r\n$periodfrom = get line starting \"Period:\" => get words after \"Period:\" => get words before \"-\" => get date \"dd/MM/yyyy\"\r\n$periodto = get line starting \"Period:\" => get words after \"Period:\" => get words after \"-\" => get date \"dd/MM/yyyy\"\r\n\r\n// Get Opening & Closing Balance\r\ngo to page 1\r\n$openingbalance = get line starting \"Posted Value\" => bottom => get line below => take last words 1 => get decimal\r\n@closingbalanceTop = get last line starting \"Posted Value\" => bottom\r\n$closingbalance = get text in box @closingbalanceTop page.bottom 475 page.right => take last words 1 => get decimal\r\n\r\n// Get Transactions table top & bottom\r\ngo to page 1\r\n@transactionsTop = get line starting \"Posted Value\" => bottom => get line below\r\nget last line starting \"Posted Value\"\r\n@transactionsBottom = get line above 25\r\n\r\n// Remove unnecessary text\r\nignore footer below 24\r\nget line starting \"Posted Value\" => bottom => ignore header above\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 100 190 300 375 475 560 => describe table false \"Date[dd/MM/yyyy]\" - Details #Debit #Credit *#Balance','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10846,'PublicBank_Card','$source = \"PublicBank_Card\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\nset negative marker \"CR\"\r\n\r\n// Get Statement period\r\n@periodToTop = get line containing \"Statement Date\" => top => add 10\r\n@periodToBottom = get line containing \"Statement Date\" => bottom => subtract 10\r\n$periodto = get text in box @periodToTop @periodToBottom 450 page.right => get date \"dd MMM yy\"\r\n\r\n@periodFromTop = get line containing \"Previous Stmt Date\" => top => add 10\r\n@periodFromBottom = get line containing \"Previous Stmt Date\" => bottom => subtract 10\r\n$periodFrom = get text in box @periodFromTop @periodFromBottom 450 page.right => get date \"dd MMM yy\"\r\n\r\n// Get Account name\r\n$accountName = get text in box @periodFromTop @periodFromBottom page.left page.middleX => take words 2 => get text\r\n\r\n//Get Account Number\r\n@accountNumberTop = get line containing \"Account Number\" => top => add 10\r\n@accountNumberBottom = get line containing \"Account Number\" => bottom => subtract 10\r\n$CardNumber = get text in box @accountNumberTop @accountNumberBottom 450 page.right => take words 1 => get text\r\n$accountNumber = get text in box @accountNumberTop @accountNumberBottom 450 page.right => get text\r\n\r\n// Get Opening and Closing balances\r\n@openingBalanceTop = get line containing \"Opening Balance\" => top => add 10\r\n@openingBalanceBottom = get line containing \"Opening Balance\" => bottom => subtract 10\r\n$openingBalance = get text in box @openingBalanceTop @openingBalanceBottom 450 page.right  => get decimal\r\n$closingBalance = get line containing \"TOTAL DUE\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n// delete whole summary info page\r\ngo to page 1\r\n@InfoPageTop = get line containing \"MAKLUMAT PENTING / IMPORTANT INFORMATION\" => top\r\ndelete text in box @InfoPageTop page.bottom page.left page.right\r\n\r\n// Get Start & End of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Transaction Description\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get line containing \"Total for this account\" => top => get line above\r\n\r\nignore header above 700\r\nignore footer below 40\r\n\r\ndelete all lines starting \"Tarikh Bil\"\r\ndelete all lines containing \"Huraian Urusniaga\"\r\ndelete all lines containing \"Transaction Description\"\r\ndelete all lines containing \"Posting Date\"\r\ndelete all lines containing \"Total for this card\"\r\ndelete all lines containing \"STATEMENT DATE\"\r\ndelete all lines starting $CardNumber\r\n\r\n// Read the Transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 155 500 600 => describe table false \"Date[dd MMM]\" - Details *#Credit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10847,'SEB_Bank_AccountNumber','$source = \"SEB_Bank_AccountNumber\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Delete unused non-transactional lines\r\ndelete all lines starting \"Account Statement\"\r\n\r\n// Get account name\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line starting \"Account Currency\" => bottom => get line below => take words 1 => get text\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take last words 1 => get decimal\r\n$closingBalance = get last line starting \"Closing Book Balance\" => get words after \"Closing Book Balance\" => take last words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n@periodText = get line starting \"Account Currency IBAN Date Number\" => get words after \"IBAN\" => take words 2\r\n@periodLeft = take words @periodText 1 => left => subtract 2\r\n@periodRight = take words @periodText 2 => take last words 1 => left\r\n@periodTop = take words @periodText 1 => bottom\r\n$periodFrom = get line starting \"Opening Balance\" =>  bottom => get line below => take words 1 => get date \"d/M\"\r\n\r\n// Set culture for parsing PeriodTo\r\ngo to page 1\r\nset culture \"sv-SE\"\r\n$periodTo = get text in box @periodTop 0 @periodLeft @periodRight => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Set culture for the decimal separator in transactions\r\nset culture \"en-US\"\r\n\r\n//Header & column coordinates\r\ngo to page 1\r\n@header = get line starting \"Entry Narrative Reference\"\r\n\r\n// Column coordinates\r\n@dateLeft =  take words @header 1 => left => subtract 5\r\n@detailsLeft =  get words after @header \"Entry\" => take words 1 => left => subtract 5\r\n@referenceLeft =  take words @header 3 => take last words 1 => left => add 10\r\n@debitLeft =  take last words @header 4 => take words 1 => right => add 10\r\n@debitRight =  take last words @header 3 => take words 1 => right => add 10\r\n@creditRight =  take last words @header 2 => take words 1 => right => add 10\r\n\r\n// Get start and end of transaction table\r\ngo to page 1\r\n@transactionTop = get line starting \"Entry Narrative Reference\" => if not found then blank => bottom => get line below\r\n@transactionbottom = get last line starting \"Closing Book Balance\" => if not found then blank => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Entry Narrative Reference\" => top => add 5 => ignore header above\r\nget last line ending \")\" => top => ignore footer below\r\n\r\n// deleted some extra lines from transaction\r\ngo to page 1\r\ndelete all lines starting \"Account\"\r\ndelete all lines starting \"Entry Narrative Reference\"\r\ndelete all lines starting \"Opening Balance\"\r\ndelete all lines starting \"Balance Forward\"\r\ndelete all lines starting \"Closing Book Balance\"\r\ndelete all lines starting \"Closing Available Balance\"\r\ndelete all lines starting \"Intermediate Balance\"\r\ndelete all lines ending \")\"\r\ndelete all lines starting \"Address:\"\r\n\r\n// Extract transactions table\r\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @detailsLeft @referenceLeft @debitLeft @debitRight @creditRight => describe table false \"*Date[d/M]\" Details - #Debit  #Credit\r\n','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10848,'CIMB_CenterAligned','$source = \"CIMB_CenterAligned\"\r\n$periodBufferDays = 14\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\n\r\n// Get Account Details\r\n@accountnumberTop = get line starting \"Account Details\" => bottom\r\n@accountnumberBottom = get line containing \"Account Type\" => top\r\n$accountnumber = get text in box @accountnumberTop @accountnumberBottom 0 250 => skip words 2 => get words before \"Protected\" => get text\r\n@accountnameTop = get line starting \"Account Type\" => bottom\r\n@accountnameBottom = get line containing \"Date Transaction Details\" => top\r\n$accountname = get text in box @accountnameTop @accountnameBottom 300 415 => get text\r\n\r\n// Get Statement Period\r\nget last line containing \"MYR\"\r\n$periodfrom = get text in box page.top page.bottom 0 120 => take last words 3 => get date \"dd MMM yyyy\"\r\ngo to page 1\r\n@periodtoTop = get line starting \"Date Transaction Details\" => bottom\r\n$periodto = get text in box @periodtoTop page.bottom 0 120 => take words 3 => get date \"dd MMM yyyy\"\r\n\r\n// Get Opening & Closing Balance\r\ngo to page 1\r\n@openingbalanceTop = get line starting \"Date Transaction Details\" => bottom\r\n$openingbalance = get text in box @openingbalanceTop page.bottom 475 page.right => skip words 1 => take words 2 => get decimal\r\nget last line containing \"MYR\"\r\n$closingbalance = get text in box page.top page.bottom 475 page.right => take last words 3 => get decimal\r\n\r\n// Get Transactions table top & bottom\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transaction Details\" => bottom => get line below\r\ngo to last page\r\n@transactionsBottom = get line above 30\r\n\r\n// Remove unnecessary text\r\nignore footer below 20\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 25 25 120 340 410 496 560 => describe table false \"Date[dd MMM yyyy]\" Details #Credit #Debit #Balance','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10849,'United_Bank','$source = \"United_Bank\"\r\n\r\n$periodBufferDays = 31\r\n\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\ndelete white words\r\n\r\ndelete text in box on every page page.top 0 0 50\r\n\r\ngo to page 1\r\n$accountName = get text in box 659 647 50 page.middleX => get text\r\n\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Number:\" => get text\r\n\r\n@panelTop = get line containing \"Beginning Balance as of\" => top\r\n@panelBottom = get line containing \"Ending Balance as of\" => bottom\r\n@panelWords = get text in box @panelTop @panelBottom 50 570\r\n\r\n$periodFrom = get words after @panelWords \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n$openingBalance = skip words @panelWords 5 => take words 1 => get decimal\r\n\r\n$periodTo = get words after @panelWords \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n$closingBalance = get words after @panelWords \"Ending Balance as of\" => take last words 1 => get decimal\r\n\r\nignore header above 644\r\nignore footer below 17\r\n\r\nremove page 2\r\n\r\ngo to page 1\r\n@TransactionsTop = get line containing \"Date Description\" => bottom => get line below\r\n@TransactionsBottom = get line containing \"Balance By Date\" => top => get line above\r\n\r\ndelete all lines containing \"Transaction Detail\"\r\ndelete all lines starting \"(Continued)\"\r\ndelete all lines containing \"Date Description\"\r\n\r\n$transactions = get multi page table @TransactionsTop @TransactionsBottom 50 90 380 570 => describe table false \"*Date[MMMdd]\" Details #Credit','2026-04-30 08:38:48',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10850,'AlpineBank','$source = \"AlpineBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n$AccountName = get line containing \"Account Name:\" => get words after \"Name:\" => take words 4 => get text\r\n\r\n@Summarytop = get line containing \"Account Number\" => top\r\n@Summarybottom = get line containing \"Previous Balance\" => bottom\r\n@Summary = get text in box @Summarytop @Summarybottom 50 330\r\n\r\n$AccountNumber = get words after @Summary \"Account Number\" => get words between \"Number\" \"Previous\" => get text\r\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get decimal\r\n\r\n@Closingtop = get line containing \"Current Balance\" => top\r\n@Closingbottom = get line containing \"Current Balance\" => bottom\r\n$ClosingBalance = get text in box @Closingtop @Closingbottom 50 330 => get words after \"Current Balance\" => get decimal\r\n\r\n@AccountNameTop = get line containing \"Account Name:\" => top\r\ndelete text in box @AccountNameTop @Closingbottom 50 330\r\n\r\ngo to page 1\r\n@Datestop = get line containing \"Statement Dates\" => top\r\n@Datesbottom = get line containing \"Statement Dates\" => bottom\r\n@Dates = get text in box @Datestop @Datesbottom 330 600\r\n\r\n$periodFrom = get words after @Dates \"Statement Dates\" => get words between \"Dates\" \"thru\" => get date \"M/d/yy\"\r\n$periodTo = get words after @Dates \"thru\" => get date \"M/d/yy\"\r\n\r\n@transactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"Date Description Amount\" => bottom => get break below => get line at\r\n\r\ngo to page 1\r\n@checksTop = get line containing \"Date Check No\" => if not found then blank => bottom => get line below\r\n@checkBottom = get last line containing \"* Denotes missing check\" => if not found then blank => top => get line above\r\n\r\nignore header above 511\r\nignore footer below 60\r\ndelete all lines starting \"DEPOSITS AND ADDITIONS\"\r\ndelete all lines starting \"WITHDRAWALS AND OTHER TRANSACTIONS\"\r\ndelete all lines starting \"Date Description Amount\"\r\ndelete all lines starting \"(Continued)\"\r\ndelete all lines starting \"CHECKS IN NUMBER ORDER\"\r\ndelete all lines starting \"Date Check No\"\r\ndelete all lines containing \"* Denotes missing check\"\r\n\r\n@DrCrtransactions = get multi page table @transactionsTop @transactionsBottom 50 125 395 600 => describe table false \"*Date[M/d]\" Details #Credit\r\n\r\n@chequeLeft = get multi page table @checksTop @checkBottom 50 130 200 335 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\r\n@chequeright = get multi page table @checksTop @checkBottom 335 380 450 600 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\r\n\r\n$transactions = combine described tables @DrCrtransactions @chequeLeft @chequeright','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10851,'CommunityBank_Georgia','$source = \"CommunityBank_Georgia\"\r\n\r\n//Get Accounts\r\n$accountName = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\n//Get Periods\r\n$PeriodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 1 => get date \"M/d/yyyy\"\r\n@TEXTBOXBottom = get line containing \"Statement Period\" => bottom => get line below\r\n$periodTo =  take last words @TEXTBOXBottom 1 => get date \"M/d/yyyy\"\r\n\r\n//Get Balances\r\n@TEXTBOX = get line containing \"Balance Number Deposits\" => bottom => get line below\r\n$openingBalance = take words @TEXTBOX 2 => get decimal\r\n$closingBalance = take last words @TEXTBOX 2 => get decimal\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@DepositsTop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@DepositsBottom = get line containing \"DEPOSITS\" => if not found then blank => top => get line above => bottom => get break below => get line at\r\n\r\n@deposits = get multi page table @DepositsTop @DepositsBottom 58 110 176 320 => describe table false \"*Date[M/d/yyyy]\" #Credit Details\r\n@depositright = get multi page table @DepositsTop @DepositsBottom 345 400 468 545 => describe table false \"*Date[M/d/yyyy]\" #Credit Details\r\n\r\ngo to page 1\r\n// Get start & end of Other Credit table\r\n@creditsTop = get line starting \"OTHER CREDITS\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@creditsBottom = get line starting \"OTHER CREDITS\" => if not found then blank => top => get line above => bottom => get break below => get line at\r\n\r\n@othercredits = get multi page table @creditsTop @creditsBottom 80 132 217 380 => describe table false \"*Date[M/d/yyyy]\" #Credit Details\r\n\r\n// Get start & end of cheques table\r\ngo to page 1\r\n@chequeTop = get line starting \"CHECK NO DATE AMOUNT\" => if not found then blank => bottom => get line below\r\n@chequebottom = get line containing \"denotes missing check\" => if not found then blank => top => get line above\r\n\r\nignore header above 655\r\ndelete all lines containing \"CHECK NO\"\r\n@chequeLeft = get multi page table @chequeTop @chequebottom 90 155 220 295 => describe table false ChequeNumber \"Date[M/d/yyyy]\" *#Debit\r\n@chequeRight = get multi page table @chequeTop @chequebottom 410 442 506 580 => describe table false ChequeNumber \"Date[M/d/yyyy]\" *#Debit\r\n\r\ngo to page 1\r\n// Get start & end of Debit table\r\n@debitstop = get line starting \"OTHER DEBITS\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@debitsbottom = get line containing \"DAILY BALANCE INFORMATION\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"OTHER DEBITS\"\r\ndelete all lines containing \"DATE AMOUNT DESCRIPTION\"\r\n\r\n@debits = get multi page table @debitstop @debitsbottom 78 130 212 390 => describe table false \"*Date[M/d/yyyy]\" #Debit Details\r\n\r\n//Read Transactions\r\n$transactions = combine described tables @deposits @depositright @othercredits @chequeLeft @chequeRight @debits','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10852,'Cecilian_Bank','$source = \"Cecilian_Bank\"\r\n$periodBufferDays = 14\r\n\r\n@TEXTBOXBottom = get line starting \"Statement Date:\" => top\r\n\r\n// Get account name & number\r\n$accountName = get text in box page.top @TEXTBOXBottom 0 350 => take words 2 => get text\r\n$accountNumber = get line containing \"Account No.:\" => get words after \"Account No.:\" => take words 1 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"Balance Forward From\" => get words after \"From\" => take words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get line containing \"Ending Balance On\" => get words after \"On\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n// Get opening & closing balance\r\n$openingBalance = get line containing \"Balance Forward From\" => get words after \"From\" => skip words 1 => take words 1 => get decimal\r\n$closingBalance = get line containing \"Ending Balance On\" => get words after \"On\" => skip words 1 => take words 1 => get decimal\r\n\r\n//ignore header above 685\r\nignore footer below 40\r\n\r\n// Get credits table\r\ngo to page 1\r\n@transactionTop1 = get line starting \"Date Type Amount\" => if not found then blank => bottom => get line below\r\n@transactionBottom1 = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\r\n\r\n@CreditLeft = get multi page table @transactionTop1 @transactionBottom1 35 90 150 218 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\r\n@CreditMiddle = get multi page table @transactionTop1 @transactionBottom1 218 265 335 394 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\r\n@CreditRight = get multi page table @transactionTop1 @transactionBottom1 394 442 520 580 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\r\n\r\ngo to page 1\r\n@DelTop1 = get line starting \"Date Type Amount\" => if not found then blank => bottom\r\n@DelBottom1 = get line starting \"Date Description Amount\" => if not found then blank => top\r\n$del1 = delete text in box @DelTop1 @DelBottom1 0 page.right => get text\r\n\r\n// Delete unwanted lines\r\ndelete all lines containing \"Date Description Amount\"\r\ndelete all lines containing \"(cont.)\"\r\ndelete all lines containing \"Statement Date:\"\r\ndelete all lines containing \"Account No.:\"\r\ndelete all lines containing \"Date Type Amount\"\r\n\r\n// Get Credits table\r\ngo to page 1\r\n@transactionTop2 = get line starting \"ALL CREDIT ACTIVITY\" => if not found then blank => bottom => get line below\r\n@transactionBottom2 = get line ending \"DEBITS\" => if not found then blank => top => get line above\r\n\r\n@Credits = get multi page table @transactionTop2 @transactionBottom2 25 90 520 580 => describe table false \"*Date[MM/dd/yy]\" Details #Credit\r\n\r\n// Get checks table\r\ngo to page 1\r\n@transactionTop3 = get line containing \"CHECKS AND OTHER DEBITS\" => if not found then blank => bottom => get line below\r\n@transactionBottom3 = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\r\ndelete all lines containing \"Date Check # Amount\"\r\n\r\n@ChecksLeft = get multi page table @transactionTop3 @transactionBottom3 35 100 160 218 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\r\n@ChecksMiddle = get multi page table @transactionTop3 @transactionBottom3 218 275 335 394 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\r\n@ChecksRight = get multi page table @transactionTop3 @transactionBottom3 394 442 520 580 => describe table false \"*Date[MM/dd/yy]\" ChequeNumber #Debit\r\n\r\n// Get debits Top & Bottom\r\ngo to page 1\r\n@transactionTop4 = get line containing \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line below\r\n@transactionBottom4 = get line containing \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\r\n\r\ngo to page 1\r\n@DelTop2 = get line containing \"CHECKS AND OTHER DEBITS\" => if not found then blank => bottom\r\n@DelBottom2 = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top\r\n$del2 = delete text in box @DelTop2 @DelBottom2 0 page.right => get text\r\n\r\ngo to page 1\r\n@DelTop2 = get line containing \"CHECKS AND OTHER DEBITS\" => if not found then blank => bottom\r\n$del2 = delete text in box @DelTop2 page.bottom 0 page.right => get text\r\ndelete all lines containing \"CHECKS AND OTHER DEBITS\"\r\n\r\n// Get Debits Table\r\n@Debits = get multi page table @transactionTop4 @transactionBottom4 25 90 520 580 => describe table false \"*Date[MM/dd/yy]\" Details #Debit\r\n\r\n// Combine Tables\r\n$transactions = combine described tables @CreditLeft @CreditMiddle @CreditRight @Credits @Debits @ChecksLeft @ChecksMiddle @ChecksRight','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10853,'BMO_Transaction_description','$source = \"BMO_Transaction_description\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Set negative marker for debit column amounts which contains - or ()\r\nset negative marker \"(\"\r\n\r\n// Get Account Name\r\n$accountName = get text in box 655 625 page.left page.middleX => take words 2 => get text\r\n\r\n// Get Account Number\r\n$accountNumber = get line containing \"Primary Account Number\" => bottom => get line below => take last words 1 => get text\r\n\r\n@PeriodBottom = get line containing \"Primary Account Number\" => top\r\ndelete text in box page.top @PeriodBottom page.left page.middleX\r\n\r\n// Get Period From/To\r\n@PeriodTop = get line ending \"Date\" => bottom\r\n\r\n@Period = get text in box @PeriodTop @PeriodBottom 400 page.right\r\n$periodFrom = take words @Period 3 => get date \"MMMM dd yyyy\"\r\n$periodTo = take last words @Period 3 => get date \"MMMM dd yyyy\"\r\n\r\n// Get Opening/Closing\r\n$openingBalance = get line containing \"BEGINNING BALANCE AS\" => bottom => get line below => bottom => get line below => take words 1 => get decimal\r\n$closingBalance = get line containing \"BEGINNING BALANCE AS\" => bottom => get line below => bottom => get line below => take last words 1 => get decimal\r\n\r\n// Get transaction table Start and End\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transaction description Withdrawal Deposit Balance\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"ENDING BALANCE\" => top => get line above\r\n\r\ndelete all lines containing \"BEGINNING BALANCE\"\r\ndelete all lines containing \"Transaction description\"\r\ndelete all lines containing \"CONTINUED ON NEXT PAGE\"\r\ndelete all lines containing \"Monthly Activity Details\"\r\ndelete all lines containing \"FOR YOUR PROTECTION\"\r\ndelete all lines containing \"Examine this statement promptly\"\r\ndelete all lines containing \"account must be reported within\"\r\n\r\nignore header above 670\r\nignore footer below 45\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 120 330 520 600 => describe table false \"*Date[MMM dd]\" Details #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10854,'RHB_Bank','$source = \"RHB_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get Account Name\r\n@accountNameText = get line starting \"Account Name\" => get text\r\n@accountNameTop = get line containing @accountNameText => bottom\r\n@accountNameRight = get line containing @accountNameText => get words after \"Account Name\" => take words 1 => left\r\n@accountNameBottom = get line containing @accountNameText => bottom => get line below => bottom\r\n$accountName = get text in box @accountNameTop @accountNameBottom 0 @accountNameRight => get text\r\n\r\n// Get Account Number\r\n@accountNumberText = get line containing \"Date Description Cheque\" => top => get line above\r\n$accountNumber  = get words after @accountNumberText \"ACCOUNT\" => take words 2 => take last words 1 => get text\r\n\r\n// Get Period/From To\r\ngo to page 1\r\n$periodFrom = get line containing \"Statement Period\" => get words before \"-\" => take last words 3 => get date \"d MMM yy\"\r\n$periodTo = get line containing \"Statement Period\" => get words after \"-\" => take words 3 => get date \"d MMM yy\"\r\n\r\n// Get Opening/Closing balance\r\n$openingBalance = get line containing \"B/F BALANCE\" => get words after \"B/F BALANCE\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"C/F BALANCE\" => get words after \"C/F BALANCE\" => take last words 1 => get decimal\r\n\r\n//Header & column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Description Cheque\"\r\n\r\n// Column coordinates\r\n@dateLeft =  take words @header 1 => left => subtract 12\r\n@dateRight =  take words @header 1 => right => add 5\r\n@detailsRight =  get words after @header \"Date\" => take words 1 => right => add 10\r\n@typeRight =  get words before @header \"Debit\" => take last words 1 => right => add 10\r\n@debitRight =  get words before @header \"Credit\" => take last words 1 => right => add 10\r\n@creditRight =  take last words @header 2 => take words 1 => right => add 10\r\n@balanceRight =  take last words @header 1 => take words 1 => right => add 10\r\n\r\n// Get start and end of transaction table\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Description Cheque\" => if not found then blank => bottom => get line below\r\n@transactionbottom = get last line containing \"C/F BALANCE\" => if not found then blank => top => get line above\r\n\r\n// Delete footer\r\ngo to page 1\r\n@transactionFooterTop = get line starting \"Member\" => if not found then blank => bottom\r\n@deleteFooter = delete text in box @transactionFooterTop 0 0 page.right\r\n\r\n// Discard header and footer\r\nget last line starting \"Date Description\" => top => add 5 => ignore header above\r\nignore footer below 100\r\n\r\n// Delete extra lines from transactions\r\ngo to page 1\r\ndelete all lines starting \"Date Description Cheque\"\r\ndelete all lines starting \"Tarikh Diskripsi\"\r\ndelete all lines containing \"B/F BALANCE\"\r\ndelete all lines containing \"C/F BALANCE\"\r\ndelete all lines starting \"ACCOUNT ACTIVITY\"\r\ndelete all lines starting \"COMMODITY\"\r\ndelete all lines starting \"Member of PIDM\"\r\ndelete all lines starting \"DEPOSIT ACCOUNT SUMMARY\"\r\ndelete all lines starting \"Account Name\"\r\ndelete all lines starting \"IMPORTANT ANNOUNCEMENTS\"\r\ndelete all lines starting \"RHB Islamic Bank Berhad\"\r\ndelete all lines starting \"Account Statement\"\r\ndelete all lines starting \"Page No\"\r\ndelete all lines starting \"Statement Period\"\r\n\r\n// Extract transactions table\r\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @dateRight @detailsRight @typeRight @debitRight @creditRight @balanceRight => describe table false \"*Date[d MMM]\" TransactionType Details #Debit #Credit #Balance\r\n\r\n','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10855,'Fluid_CreditCard','$source = \"Fluid_CreditCard\"\r\n$features = \"CREDIT_CARD\"\r\n\r\n$periodbufferdays = 30\r\n\r\n// Get account name\r\n$accountName = get line containing \"Available to spend\" => bottom => get line below  => take words 2 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 4 => get text\r\n\r\ngo to page 2\r\ndelete all lines containing \"Your monthly statement\"\r\n\r\n// Get dates and opening/closing balances\r\n$PeriodFrom = get line starting \"Opening Balance\" => bottom => get line below  => take words 3 => get date \"dd MMM yyyy\"\r\n$openingBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\r\n$PeriodTo = get last line starting \"Your new balance\" => top => get line above => take words 3 => get date \"dd MMM yyyy\"\r\n$closingBalance = get last line containing \"Your new balance\" => get words after \"Your new balance\" => take last words 1 => get decimal\r\n\r\n//ignore footer below 150\r\ndelete all lines containing \"Your account in detail\"\r\n\r\ngo to page 1\r\n// Get top of the transaction table\r\n@transactionsTop = get line starting \"Opening Balance\" => bottom => get line below\r\n\r\n// Get bottom of the transaction table\r\n@transactionsBottom = get line starting \"Your new balance\" => top => get line above\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 20 90 500 580 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10856,'Chime_Bancorp_Bank','$source = \"Chime_Bancorp_Bank\"\r\n$features = \"REVERSE_ORDER\"\r\n$periodBufferDays = 30\r\n\r\n//Get Accounts\r\n$accountNameText = get line starting \"Account number\" => top => get line below\r\n$accountName = take words $accountNameText 1 => get text\r\n$accountNumber = take words $accountNameText 1 => get text\r\n\r\n//Get Balances and Perioda\r\n$openingBalanceText = get line starting \"Beginning balance\" => get words after \"Beginning balance\"\r\n$periodfrom = get words after  $openingBalanceText  \"on\" => take words 3 => get date \"MMMM d,yyyy\"\r\n$closingBalance =  take last words $openingBalanceText  1 => get decimal\r\n\r\n$closingBalanceText = get line starting \"Ending balance\" => get words after \"Ending balance\"\r\n$periodto = get words after  $closingBalanceText \"on\" => take words 3 => get date \"MMMM d,yyyy\"\r\n$openingBalance =  take last words $closingBalanceText 1 => get decimal\r\n\r\n//Get Transactions\r\ngo to page 1\r\n\r\n$Date_left = get line containing \"TRANSACTION DATE DESCRIPTION\" => get words before \"DESCRIPTION\" => left => subtract 5\r\n$Date_right = get line containing \"TRANSACTION DATE DESCRIPTION\" => get words after \"DATE\" => left => subtract 5\r\n$Description_right = get line containing \"TRANSACTION DATE DESCRIPTION\" => get words after \"DESCRIPTION\" => left => subtract 5\r\n$Type_right = get line containing \"TRANSACTION DATE DESCRIPTION\" => get words after \"TYPE\" => left => subtract 10\r\n$Paidout_right = get line containing \"TRANSACTION DATE DESCRIPTION\" => get words after \"AMOUNT\" => left => subtract 10\r\n\r\n\r\n@transactionsTop = get line containing \"TRANSACTION DATE DESCRIPTION\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get line starting \"Yearly Summary\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Page\"\r\n\r\n//Read Transactions\r\n$trans = get multi page table @transactionsTop @transactionsBottom $Date_left $Date_right $Description_right $Type_right $Paidout_right  => describe table false \"*Date[M/d/yyyy]\" Details TransactionType #Credit\r\n\r\n//Get Yearly Summary Transactions\r\ngo to page 1\r\n@yearTop = get line containing \"Yearly Summary\" => if not found then blank => bottom => get line below\r\n@yearBottom = get line starting \"Page\" => if not found then blank => top => get line above\r\n$trans2 = get multi page table @yearTop @yearBottom 25 200 235   => describe table false Details #Credit\r\n\r\n$transactions = combine described tables $trans $trans2','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10857,'CalPrivate_Bank','$source = \"CalPrivate_Bank\"\r\n$periodBufferDays = 30\r\n\r\n//Get account name\r\n\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n//Get account number\r\n\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\n//Get opening Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 2 => take last words 1 => get decimal\r\n\r\n//Get closing Balance\r\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take words 2 => take last words 1 => get decimal\r\n\r\n//Get statementperiod\r\ngo to page 1\r\n$PeriodFrom = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get line containing \"Ending balance\" => get words after \"Ending balance\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n\r\n//Get start & end of Debit table\r\ngo to page 1\r\n$CreditsTop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below\r\n$CreditsBottom = get last line starting \"Number of Deposits\" => top => get break below => get line at\r\n\r\n//Get start & end of Credit table\r\ngo to page 1\r\n$eDebitsTop = get line starting \"WITHDRAWALS\" => if not found then blank => bottom => get line below\r\n$eDebitsBottom = get last line starting \"Number of Withdrawals\" => top => get break below => get line at\r\nignore header above 645\r\ndelete all lines containing \"Description\"\r\ndelete all lines containing \"Total Deposits\"\r\ndelete all lines containing \"WITHDRAWALS\"\r\ndelete all lines containing \"Total Withdrawals\"\r\n$credits = get multi page table $CreditsTop $CreditsBottom 35 160 500 570 => describe table false \"*Date[MM/d/yyyy]\" Details #Credit\r\n$debits = get multi page table $eDebitsTop $eDebitsBottom 35 160 500 570 => describe table false \"*Date[MM/d/yyyy]\" Details #Debit\r\n$transactions = combine described tables $credits $debits','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10858,'Zopa_Bank','$source = \"Zopa_Bank\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n\r\n$periodBufferDays = 30\r\n// Extract Account Number\r\n$accountNumber = get line containing \"Account no:\" => get words after \"Account no:\" => take words 1 => get text\r\n\r\n// Extract Account Name\r\ngo to page 1\r\n$accountName = get text in box 675 655 page.left page.middleX => take words 2 => get text\r\n\r\n//Get dates\r\ngo to page 1\r\n$PeriodFrom = get line containing \"Your Zopa Credit Card Statement for\" => get words after \"Your Zopa Credit Card Statement for\" => take words 2 => get date \"dd MMM\"\r\n$periodTo = get line containing \"Your Zopa Credit Card Statement for\" => get words after \"-\" => take words 3 => get date \"dd MMM yyyy\"\r\n\r\n// Opening & Closing Balances\r\n\r\n$openingBalance = get line containing \"Your previous balance\" => get words after \"Your previous balance\" => take words 1 => get decimal\r\n\r\n$closingBalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line containing \"Date Description Money in £ Money out £\" => bottom => get line below\r\n\r\ndelete all lines containing \"Date Description Money in £ Money out £\"\r\ndelete all lines containing \"Previous statement balance\"\r\n\r\n@transactionsbottom = get last line containing \"Your new balance on\" => top => get line above\r\n\r\n//ignore footer below 25\r\n//ignore header above 760\r\n\r\n$transactions = get multi page table @transactionstop @transactionsbottom 60 115 385 465 540 => describe table false \"*Date[dd MMM]\" Details #Debit #Credit ','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10859,'Brex_AccountStatement','$source = \"Brex_AccountStatement\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number\r\n@accountText = get line starting \"Account Number:\"\r\n$accountNumber = get words after @accountText \"Account Number:\" => take words 1 => get text\r\n\r\n// Get account name\r\n@accountTop =   take words @accountText 1 => bottom\r\n$accountName = get text in box @accountTop 0 0 page.middleX => take words 3 => get text\r\n\r\ngo to page 1\r\n// Get period from/to\r\n@periodTop = take words @accountText 1 => top\r\n@periodText = get text in box page.top @periodTop 0 page.middleX => get text\r\n$periodFrom = get line containing @periodText =>  get words before \"-\" => take last words 2 => get date \"MMM d\"\r\n$periodTo = get line containing @periodText =>  get words after \"-\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line starting \"Beginning\" => get words after \"Beginning\" => take last words 2 => take words 1 => get decimal\r\n$closingBalance = get line starting \"Ending\" => get words after \"Ending\" => take last words 2 => take words 1 => get decimal\r\ndelete all lines containing \"Onward Jets LLC\"\r\n\r\n// Get start and end of credits table\r\ngo to page 1\r\n@creditsTop = get line starting \"Activity - Deposits & Credits\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get last line starting \"Total Deposits & Credits\" => if not found then blank => top => get line above\r\n\r\n//Header & column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date From Method Amount\"\r\n\r\n// Column coordinates\r\n@dateLeft =  take words @header 1 => left => subtract 10\r\n@detailsLeft =  get words after @header \"Date\" => take words 1 => left => subtract 5\r\n@typeLeft =  take words @header 3 => take last words 1 => left => subtract 5\r\n@amountLeft =  take last words @header 1 => take last words 1 => left => subtract 50\r\n@amountRight =  take last words @header 1 => take last words 1 => right => add 10\r\n\r\n// Get start and end of debits table\r\ngo to page 1\r\n@debitsTop = get line starting \"Activity - Withdrawals & Debits\" => if not found then blank => bottom => get line below\r\ndelete all lines containing \"Method Amount\"\r\n@debitsBottom = get last line starting \"Total Withdrawals & Debits\" => if not found then blank => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Account Number:\" => bottom => ignore header above\r\nget last line starting \"Page\" => top => add 10 => ignore footer below\r\n\r\n// Delete non-transaction lines\r\ngo to page 1\r\ndelete all lines starting \"Date From Method Amount\"\r\ndelete all lines starting \"Activity\"\r\ndelete all lines starting \"Total\"\r\ndelete all lines starting \"Page\"\r\n\r\n// Read transactions in credits table\r\n@creditsTable = get multi page table @creditsTop @creditsBottom @dateLeft @detailsLeft @typeLeft @amountLeft @amountRight => describe table false \"*Date[M/d]\" Details TransactionType #Credit\r\n\r\n// Read transactions in debits table\r\n@debitsTable = get multi page table @debitsTop @debitsBottom @dateLeft @detailsLeft @typeLeft @amountLeft @amountRight => describe table false \"*Date[M/d]\" Details TransactionType #Credit\r\n\r\n// Combine transactions\r\n$transactions = combine described tables @creditsTable @debitsTable','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10860,'Conexus_Collabria_CreditCard','$source = \"Conexus_Collabria_CreditCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get account details\r\n$accountNumber = get line starting \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => take words 1 => get text\r\n$accountName = \"CONEXUS CREDIT UNION\"\r\n\r\n// Get periods\r\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Statement Period\" => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\ngo to page 1\r\n// Get balances\r\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@header = get line starting \"Tran Post\"\r\n@header1 = get line containing \"Date Description\"\r\n\r\n// Column coordinates\r\n@date1Left = take words @header 1 => left => subtract 10\r\n@date1Right = take words @header 1 => right => add 10\r\n@date2Right = take words @header 2 => take last words 1 => right => add 7\r\n@detailRight = get words after @header1 \"Description\" => take words 1 => left => subtract 10\r\n@typeRight = take last words @header1 1 => left => subtract 10\r\n@amountRight = take last words @header1 1 => right => add 50\r\n\r\ngo to page 1\r\n// Get start and end of Fees table\r\n@transactionFeesTop = get line starting \"FEES\" => if not found then blank => bottom => get line below\r\n@transactionFeesBottom = get line starting \"TOTAL FEES FOR THIS PERIOD\" => if not found then blank => top => get line above\r\n@transactionFeesTable = get multi page table @transactionFeesTop @transactionFeesBottom @date1Left @date1Right @date2Right @detailRight @typeRight @amountRight => describe table false - \"*Date[dd/MM]\" TransactionType Details #Credit\r\n\r\n// Remove Fees section from document\r\n@transactionFees_Top = get line starting \"FEES\" => if not found then blank => bottom\r\n@transactionFees_Bottom = get line starting \"TOTAL FEES FOR THIS PERIOD\" => if not found then blank => bottom\r\n@delTransactionFees = delete text in box @transactionFees_Top @transactionFees_Bottom 0 page.right => get text\r\n\r\ngo to page 1\r\n// Get start and end of Interest table\r\n@transactionInterestTop = get line starting \"INTEREST\" => if not found then blank => bottom => get line below\r\n@transactionInterestbottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => if not found then blank => top => get line above\r\n@transactionInterestTable = get multi page table @transactionInterestTop @transactionInterestbottom @date1Left @date1Right @date2Right @detailRight @typeRight @amountRight => describe table false - \"*Date[dd/MM]\" TransactionType Details #Credit\r\n\r\n// Remove Interest section from document\r\n@transactionInterest_Top = get line starting \"INTEREST\" => if not found then blank => bottom\r\n@transactionInterest_Bottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => if not found then blank => bottom\r\n@delTransactionInterest = delete text in box @transactionInterest_Top @transactionInterest_Bottom 0 page.right => get text\r\n\r\ngo to page 1\r\n// Get start and end of main transactions table\r\n@transactionTop = get line starting \"Tran Post\" => bottom => get line below\r\n@transactionbottom = get last line containing \"TOTALS YEAR-TO-DATE\" => top => get line above\r\n\r\n// Delete header lines from the body\r\ndelete all lines starting \"Tran Post\"\r\ndelete all lines containing \"Date Description\"\r\n\r\n// Delete extra TOTAL XX blocks from transactions\r\ngo to page 1\r\n@top = get line starting \"TOTAL XX\" => top => get line above => top\r\n@bottom = get line starting \"TOTAL XX\" => bottom\r\n@delextraLine = delete text in box @top @bottom 0 page.right => get text\r\n\r\n// Remove remaining total/section labels that might break the main table\r\ndelete all lines starting \"TOTAL\"\r\ndelete all lines starting \"TRANSACTIONS\"\r\ndelete all lines starting \"FEES\"\r\ndelete all lines starting \"INTEREST\"\r\ndelete all lines containing \"PAGE\"\r\nignore footer below 17\r\n\r\n// Build main transactions table\r\n@transactionsTable = get multi page table @transactionTop @transactionbottom @date1Left @date1Right @date2Right @detailRight @typeRight @amountRight => describe table false - \"*Date[dd/MM]\" TransactionType Details #Credit\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @transactionsTable @transactionFeesTable @transactionInterestTable','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10861,'AppleSaving_Bank','$source = \"AppleSaving_Bank\"\r\n\r\n//Get Periods\r\n$periodtext = get line starting \"Account\" => top => get line above => take last words 7\r\n$periodfrom = take words $periodtext 3 => get date \"MMM d,yyyy\"\r\n$periodto = take last words $periodtext 3 => get date \"MMM d,yyyy\"\r\n\r\n//Get Accounts\r\n$accountName = get line starting \"Account\" => get words after \"Account\" => take words 1 => get text\r\n$accountNumber = get line starting \"Account\" => get words after \"Account\" => take words 1 => get text\r\n\r\n//Get Balances\r\ndelete text in box page.top 518 300 page.right => get text\r\n\r\n$openingBalance = get line starting \"Beginning Balance\" => take last words 1 => get decimal\r\n$closingBalance = get line starting \"Ending Balance\" => take last words 1 => get decimal\r\n\r\n//Get Transactions\r\ngo to page 1\r\n\r\n$Date_left = get line containing \"Date Description Amount\" => get words before \"Description\" => left => subtract 5\r\n$Date_right = get line containing \"Date Description Amount\" => get words after \"Date\" => left => subtract 5\r\n$Description_right = get line containing \"Date Description Amount\" => get words after \"Description\" => left => subtract 20\r\n$Paidout_right = get line containing \"Date Description Amount\" => get words after \"Amount\" => left => subtract 20\r\n$Balance_right = get line containing \"Date Description Amount\" => get words after \"Amount\" => right => add 5\r\n\r\n@transactionsTop = get line containing \"Date Description Amount\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get line starting \"Closing Balance\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Opening Balance\"\r\ndelete all lines containing \"Date Description Amount\"\r\n\r\nignore footer below 40\r\nignore header above 646\r\n\r\n//Read Transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Date_right $Description_right $Paidout_right $Balance_right => describe table false \"*Date[M/d/yyyy]\" Details #Credit #Balance','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10862,'Airwallex_Bank','$source = \"Airwallex_Bank\"\r\n\r\n// Extract Account Number\r\n$accountNumber = get line containing \"Account Details\" => bottom => get line below => get words after \":\" => take words 1 => get text\r\n\r\n// Extract Account Name\r\n$accountName = get line containing \"Account Holder\" => top => get line below => take words 2 => get text\r\n\r\n// Get Periods\r\n\r\n$periodFrom = get line containing \"Starting balance on\" => get words after \"Starting balance on\" => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n$periodTo   = get line containing \"Ending balance on\" => get words after \"Ending balance on\" => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n// Opening & Closing Balances\r\n\r\n$openingBalance = get line containing \"Date Details Credit Debit Balance\" => top => get line below => get words after \"Starting balance\" => take words 1 => get decimal\r\n\r\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take last words 2 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line containing \"Date Details Credit Debit Balance\" => bottom => get line below => bottom => get line below\r\n\r\n//@header = get last line containing \"Date Details Credit Debit Balance\" => top\r\n//ignore header above @header\r\n$a = get last line containing \"Date Details Credit Debit Balance\" => top => get line above => take last words 2 => get text\r\n$b = get last line containing \"Date Details Credit Debit Balance\" => top => get line above => top => get line above => take last words 2 => get text\r\n$c = get last line containing \"Date Details Credit Debit Balance\" => top => get line above => top => get line above => top => get line above => take last words 2 => get text\r\ndelete all lines containing \"Account Holder\"\r\n$d = get last line containing \"Date Details Credit Debit Balance\" => top => get line above => top => get line above => top => get line above => top => get line above => take last words 2 => get text\r\ndelete all lines starting \"Web:\"\r\ndelete all lines starting \"Labs House\"\r\ndelete all lines ending $a\r\ndelete all lines ending $b\r\n//delete all lines ending $c\r\ndelete all lines ending $d\r\ndelete all lines starting \"Starting balance\"\r\ndelete all lines starting \"Ending balance\"\r\ndelete all lines containing \"Email:\"\r\ndelete all lines containing \"Web:\"\r\ndelete all lines containing \"Continued\"\r\ndelete all lines containing \"Account number:\"\r\n\r\n@transactionsbottom = get last line containing \"Ending balance\" => top => get line above\r\n\r\ndelete all lines containing \"Date Details Credit Debit Balance\"\r\n\r\n@footer = get line starting \"Page\" => top\r\nignore footer below @footer\r\n//ignore footer below 25\r\n//ignore header above 760\r\n\r\n$transactions = get multi page table center aligned @transactionstop @transactionsbottom 15.5 35 100 290 390 490 565 => describe table false \"Date[MMM dd yyyy]\" Details #Credit #Debit #Balance','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10863,'FNB_CreditCard','$source = \"FNB_CreditCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 14\r\n\r\n// Transactions with CR text are negative\r\nset negative marker \"Cr\"\r\n\r\n// Get account name\r\n\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 4 => take last words 3 => get text\r\n\r\n// Get account number\r\n$accountnumber = get line containing \"Account Number\" => get words after \"Account Number\" => take last words 1 => get text\r\n\r\n// Get Period\r\n$periodFrom =  get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodTo =  get line containing \"Statement Period\" => get words after \"Statement Period\" => take last words 3 => get date \"dd MMMM yyyy\"\r\n\r\n// Get Opening/Closing balance\r\n$openingBalance = get line containing \"Opening Balance as at\" => get words after \"GBP\" => get decimal\r\n$closingBalance = get line containing \"Closing Balance as at\" => get words after \"GBP\" => get decimal\r\n\r\n// Get start of table\r\n@transactionsTop = get line containing \"Date Description Amount Balance\" => bottom => get line below => bottom => get line below\r\n\r\n// Discard page footer\r\nignore footer below 60\r\n\r\ndelete all lines starting \"Date Description Amount Balance\"\r\n\r\n// Get bottom of table\r\n@transactionsBottom = get last line containing \"Closing Balance as at\" => top => get line above\r\n\r\n// Read the transactions\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 65 120 355 460 560 => describe table false \"*Date[dd MMM yyyy]\" Details #Credit','2026-04-30 08:38:49',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10864,'UnityTrustBank','$source = \"UnityTrustBank\"\r\n\r\ndelete text in box on every page page.top page.bottom 0 20\r\n\r\n@Summarytop = get line containing \"Name of account\" => top\r\n@Summarybottom = get line starting \"Account number\" => bottom\r\n@Summary = get text in box @Summarytop @Summarybottom 0 210\r\n$accountName = get words after @Summary \"Name of account\" => get words between \"Name of account\" \"Date\" => get text\r\n$periodTo = get words after @Summary \"Date\" => get words between \"Date\" \"Account number\" => get date \"d MMMM yyyy\"\r\n$accountNumber = get words after @Summary \"Account number\" => get text\r\n\r\n@transactionsTop = get line containing \"Date Details Payments Receipts\" => bottom => get line below\r\n\r\n@firstrow = get line starting \"Date Details Payments Receipts\" => bottom => get line below\r\n$openingbalance = get words after @firstrow \"forward\" => get decimal\r\n$periodFrom = get words before @firstrow \"Balance\" => get date \"d MMM yy\"\r\n\r\n@transactionsBottom = get last line containing \"Balance carried forward\" => top => get line above\r\n$closingBalance = get last line containing \"Balance carried forward\" => get words after \"Balance carried forward\" => get decimal\r\n\r\ngo to page 1\r\nignore footer below 88\r\nignore header above 735\r\ndelete all lines containing \"Date Details Payments Receipts\"\r\ndelete all lines containing \"Balance brought forward\"\r\ndelete all lines containing \"Balance carried forward\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 120 313 380 460 600 => describe table false \"*Date[d MMM yy]\" Details #Debit #Credit #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10865,'Fidelity_Bank','$source = \"Fidelity_Bank\"\r\n$periodBufferDays = 14\r\n\r\n// Get account name & number\r\n$accountName = get line containing \"Statement Ending\" => bottom => get line below => take words 2 => get text\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => get text\r\n\r\ngo to page 1\r\ndelete all lines ending \"Ending Balance\"\r\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\r\n@TEXTBOXBottom = get line containing \"Ending Balance\" => bottom\r\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 0 350\r\n\r\n// Get statement period\r\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\r\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening & closing balance\r\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// Delete unwanted words\r\ndelete all lines containing \"item(s) totaling\"\r\ndelete all lines containing \"Date Description Amount\"\r\ndelete all lines containing \"Check Nbr Date Amount\"\r\ndelete all lines containing \"Indicates skipped check number\"\r\ndelete all lines containing \"(continued)\"\r\nignore header above 685\r\nignore footer below 30\r\n\r\n// Get credits table\r\ngo to page 1\r\n@transactionTop1 = get line starting \"Deposits\" => if not found then blank => bottom => get line below\r\n@transactionBottom1 = get line starting \"Debits To Your Account\" => if not found then blank => top => get line above\r\n@Credits = get multi page table @transactionTop1 @transactionBottom1 25 90 475 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit\r\n\r\n// Get debits table\r\ngo to page 1\r\n@transactionTop2 = get line starting \"Debits To Your Account\" => if not found then blank => bottom => get line below\r\n@transactionBottom2 = get line starting \"Checks Paid From Your Account\" => if not found then blank => top => get line above\r\n@Debits = get multi page table @transactionTop2 @transactionBottom2 25 90 475 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit\r\n\r\n// Get checks table\r\ngo to page 1\r\n@transactionTop3 = get line starting \"Checks Paid From Your Account\" => if not found then blank => bottom => get line below\r\n@transactionBottom3 = get line containing \"Daily Balances\" => if not found then blank => top => get line above\r\n\r\n@ChecksLeft = get multi page table @transactionTop3 @transactionBottom3 35 90 150 215 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\r\n@ChecksMiddle = get multi page table @transactionTop3 @transactionBottom3 215 274 335 410 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\r\n@ChecksRight = get multi page table @transactionTop3 @transactionBottom3 410 457 520 580 => describe table false ChequeNumber \"*Date[MM/dd/yyyy]\" #Debit\r\n\r\n// Combine Tables\r\n$transactions = combine described tables @Credits @Debits @ChecksLeft @ChecksMiddle @ChecksRight','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10866,'Woodforest_DateAmountTransactions','$source = \"Woodforest_DateAmountTransactions\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n// Delete left corners to remove QR texts\r\n$Delete_text = delete text in box on every page page.top page.bottom 0 45 => get text\r\n\r\n//get account Name\r\ngo to page 1\r\n$accountName = get line containing \"ACCOUNT TYPE AND NUMBER\" => bottom => get line below => bottom => get line below => take last words 1 => get text\r\n\r\n//get account number\r\n$accountNumber = get line containing \"ACCOUNT TYPE AND NUMBER\" => bottom => get line below => bottom => get line below => take last words 1 => get text\r\n\r\n//get statement period\r\n$periodFrom = get line containing \"Statement Period:\" => get words after \"Period:\" => get words before \"-\" => get date \"MMM dd\"\r\n$periodTo = get line containing \"Statement Period:\" => get words after \"Period:\" => get words after \"-\" => get date \"MMM d, yyyy\"\r\n\r\n@TEXTBOXTop1 = get line containing \"FORWARD DEBITS CREDITS BALANCE\" => bottom\r\n@TEXTBOXBottom1 = get line containing \"FORWARD DEBITS CREDITS BALANCE\" => bottom => get line below => bottom => get line below => top\r\n\r\n//get opening & closing balance\r\n$openingBalance = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 270 page.right => take words 1 => get decimal\r\n$closingBalance = get text in box @TEXTBOXTop1 @TEXTBOXBottom1 270 page.right => take last words 1 => get decimal\r\n\r\n// Remove unwanted text\r\ngo to page 1\r\ndelete all lines containing \"Date Amount Transactions\"\r\ndelete all lines containing \"(continued)\"\r\n\r\n// Credit top  & bottom\r\ngo to page 1\r\n@transactionsTop1 = get line containing \"Deposits and Other Credits\" => if not found then blank => bottom => get line below\r\n@transactionsBottom1 = get last line containing \"Withdrawals and Other Debits\" => if not found then blank => top => get line above\r\n\r\n// Debit top & bottom\r\ngo to page 1\r\n@transactionsTop2 = get line containing \"Withdrawals and Other Debits\" => if not found then blank => bottom => get line below\r\n@transactionsBottom2 = get last line containing \"Account Summary\" => top => get line above\r\n\r\n// Remove extra header & footer text\r\nignore header above 690\r\nignore footer below 22\r\n\r\n//Get Credits & Debits\r\n@Credits = get multi page table @transactionsTop1 @transactionsBottom1 46 100 186 560  => describe table false \"*Date[MM-dd]\" #Credit Details\r\n@Debits = get multi page table @transactionsTop2 @transactionsBottom2 46 100 186 560  => describe table false \"*Date[MM-dd]\" #Debit Details\r\n\r\n// Combine Tables\r\n$transactions = combine described tables @Credits @Debits','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10867,'BNP_Paribas_French','$source = \"BNP_Paribas_French\"\r\n\r\n// Parse month and amount in French\r\nset culture \"fr-CA\"\r\n\r\n// Get Account Name\r\n$AccountName = get line containing \"Titulaire du compte :\" => bottom => get line below => take words 1 => get text\r\n\r\n// Get Account Number\r\n@AccountNumberTop = get line containing \"RIB\" => top\r\n@AccountNumberBottom = get line containing \"RIB\" => bottom\r\n$AccountNumber = get text in box @AccountNumberTop @AccountNumberBottom page.left page.middleX => get words after \"RIB :\" => get text\r\n\r\n// Get Periodfrom/Periodto\r\n$periodfrom = get line starting \"PERIODE DU\" => get words after \"PERIODE DU\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodto = get line starting \"PERIODE DU\" => get words after \"PERIODE DU\" => take last words 3 => get date \"dd MMMM yyyy\"\r\n\r\n// Get opening and closing balance\r\n@OpeningBalanceTop = get line containing \"Solde au\" => bottom => get line below => top\r\n@OpeningBalanceBottom = get line containing \"Solde au\" => bottom => get line below => bottom\r\n$OpeningBalance = get text in box @OpeningBalanceTop @OpeningBalanceBottom 50 200 => get decimal\r\n$ClosingBalance = get text in box @OpeningBalanceTop @OpeningBalanceBottom 400 600 => get decimal\r\n\r\ngo to page 1\r\n// Get start of table\r\n@transactionsTop = get line containing \"DATE NATURE DES OPERATIONS\" => bottom => get line below => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsBottom = get line starting \"TOTAL DES OPERATIONS\" => top => get line above\r\n\r\nignore header above 610\r\nignore footer below 70\r\n\r\n// deleted some header lines\r\ndelete all lines starting \"RIB :\"\r\ndelete all lines starting \"IBAN :\"\r\ndelete all lines starting \"PERIODE DU\"\r\ndelete all lines containing \"NATURE DES OPERATIONS\"\r\ndelete all lines ending \"COMPTABLE VALEUR\"\r\n\r\n// deleted some extra lines from transaction\r\ndelete all lines starting \"VIREMENTS\"\r\ndelete all lines containing \"AMORTISSEMENTS DE PRETS\"\r\ndelete all lines containing \"Sous total.\"\r\ndelete all lines starting \"PAIEMENTS PAR CARTES\"\r\ndelete all lines starting \"RETRAITS D\'ESPECES\"\r\ndelete all lines containing \"CARTE N°\"\r\ndelete all lines containing \"AUTRES OPERATIONS DEBIT\"\r\ndelete all lines starting \"REMISES DE CHEQUES\"\r\n\r\ndelete all lines containing \"Opération exonérée de la commission de compte\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 115 350 410 480 550 => describe table false \"*Date[dd.MM.yy]\" Details \"Valeur[dd.MM.yy]\" #Debit #Credit','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10868,'Nordstrom_CreditCard','$source = \"Nordstrom_CreditCard\"\r\n$periodBufferDays = 30\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n\r\n// Account NameNumber\r\n\r\n$accountName = get line containing \"Account number:\" => top => get line above => take words 2 => get text\r\n\r\n$accountNumber = get line containing \"Account number\" => get words after \":\" => take words 4 => get text\r\n\r\n// Period\r\n\r\n$periodFrom = get line containing \"Account number:\" => top => get line above => top => get line above => take words 2 => get date \"MMMM dd\"\r\n\r\n$periodTo   = get line containing \"Account number:\" => top => get line above => top => get line above => take last words 3 => get date \"MMMM dd , yyyy\"\r\n\r\n// Opening and Closing Balances\r\n\r\n$openingBalance = get line containing \"Your previous month\'s balance\" => get words after \"Your previous month\'s balance\" => take words 2 => get decimal\r\n\r\n$closingBalance = get line containing \"New balance\" => get words after \"New balance\" => take words 1 => get decimal\r\n\r\n// Transaction Table\r\n\r\n@transactionsTop = get line starting \"DETAILS OF YOUR TRANSACTIONS\" => bottom => get line below => bottom => get line below\r\n\r\n@transactionsBottom = get line starting \"TOTAL FEES AND INTEREST CHARGED FOR THE YEAR TO DATE\" => top => get line above => top => get line above\r\n\r\n\r\nignore header above 635\r\n\r\nignore footer below 35\r\n\r\ndelete all lines containing \"Date Description Amount ($)\"\r\ndelete all lines containing \"NON-NORDSTROM PURCHASES AND CREDITS\"\r\ndelete all lines containing \"Date Merchant Amount ($)\"\r\ndelete all lines starting \"FEES\"\r\ndelete all lines starting \"Total fees for this period\"\r\ndelete all lines containing \"DETAILS OF YOUR TRANSACTIONS (CONTINUED)\"\r\ndelete all lines containing \"Date Store Amount ($)\"\r\ndelete all lines starting \"INTEREST CHARGED\"\r\ndelete all lines starting \"Description Amount ($)\"\r\ndelete all lines starting \"Total interest for this period\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 85 390 437 => describe table false \"Date[MMM dd]\" Details *#Credit','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10869,'SocieteGenerale_Bank','$source = \"SocieteGenerale_Bank\"\r\n\r\ndelete rotated words\r\ndelete tiny words\r\ndelete text in box on every page page.top page.bottom 565 page.right\r\n\r\n//Get Accounts\r\n$account = get line containing \"VOS CONTACTS\" => top => get line above\r\n$accountName = take last words $account 2 => get text\r\n$accountNumber = take last words $account 2 => get text\r\n\r\n//Get Periods\r\n$periodtext = get line containing \"VOS CONTACTS\" => get words after \"du\"\r\n$periodfrom = take words $periodtext 1 => get date \"d/M/yyyy\"\r\n$periodto = take last words $periodtext 1 => get date \"d/M/yyyy\"\r\n\r\n//Get Balances\r\nset culture \"fr-CA\"\r\n$openingBalance = get line containing \"SOLDE PRÉCÉDENT AU\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"NOUVEAU SOLDE AU\" => take last words 1 => get decimal\r\n\r\n//Get Transactions\r\ngo to page 1\r\n@transactionsTop = get line starting \"SOLDE PRÉCÉDENT\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"NOUVEAU SOLDE\" => top => get line above\r\n\r\n//delete extra lines\r\ndelete all lines containing \"tarif au\"\r\ndelete all lines containing \"Pour toute insatisfaction\"\r\ndelete all lines containing \"votre premier interlocuteur\"\r\ndelete all lines containing \"Le Service Relations Clientèle\"\r\ndelete all lines containing \"Reclamations@socgen.com\"\r\ndelete all lines containing \"le Médiateur de la FBF\"\r\ndelete all lines containing \"sur le site lemediateur\"\r\ndelete all lines containing \"Date Valeur Nature\"\r\ndelete all lines containing \"TOTAUX DES\"\r\ndelete all lines containing \"Depuis l\"\r\nignore footer below 45\r\nignore header above 720\r\n\r\n//Read Transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 29 73 118 399 483 565 => describe table false  \"*Date[d/M/yyyy]\" - Details #Debit #Credit','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10870,'Pulse_CreditCard','$source = \"Pulse_CreditCard\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 28\r\nset negative marker \"cr\"\r\n\r\n// Get account details\r\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\r\n@accountTop = get line starting \"Account number\" => take words 1 => top\r\n$accountName = get text in box @accountTop 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get periods\r\n$periodFrom = get line starting \"Opening Balance\" => bottom => get line below => take words 3 => get date \"d MMM yyyy\"\r\ngo to page 1\r\n$periodTo = get line starting \"Statement date:\" => get words after \"Statement date:\" => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get balances\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\r\n$closingBalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => get decimal\r\n\r\n// Header anchor\r\ngo to page 1\r\n@header = get line starting \"Opening Balance\"\r\n\r\n// Column coordinates\r\n@dateLeft =  take words @header 1 => left => subtract 10\r\n@dateRight =  take words @header 2 => take last words 1 => right => add 1\r\n@amountLeft =  take last words @header 1 => left => subtract 50\r\n@amountRight =  take last words @header 1 => right => add 10\r\n\r\ngo to page 1\r\n// Get start and end of table\r\n@transactionTop = get line starting \"Opening Balance\" =>  bottom => get line below\r\n@transactionbottom = get last line containing \"Your new balance\" => top => get line above\r\n\r\n// Cleanup: remove header/footer\r\ndelete all lines starting \"Opening Balance\"\r\ndelete all lines starting \"Your new balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionbottom @dateLeft @dateRight @amountLeft @amountRight => describe table false \"*Date[d MMM yyyy]\" Details #Credit','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10871,'WestAmerica_Bank','$source = \"WestAmerica_Bank\"\r\n$periodBufferdays = 14\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n//Get Accounts\r\n$accountName = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => take words 1 => get text\r\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => take words 1 => get text\r\n\r\n//Get Opening and closing balance\r\n@TEXTBOX = get line containing \"PREVIOUS BALANCE NUMBER AMOUNT\" => bottom => get line below\r\n$openingBalance = take words @TEXTBOX 1 => get decimal\r\n$closingBalance = take last words @TEXTBOX 1 => get decimal\r\n\r\n//Get Periods\r\n@TEXTBOXBottom = get line containing \"STATEMENT DATE\" => bottom => get line below\r\n$periodto = take words @TEXTBOXBottom  1 => get date \"M/d/yy\"\r\n$periodFrom = get line starting \"DATE DESCRIPTION AMOUNT\" => bottom => get line below => take words 1 => get date \"M/d\"\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@DepositsTop = get line starting \"DATE DESCRIPTION AMOUNT\" => if not found then blank => bottom => get line below\r\n@DepositsBottom = get line containing \"WITHDRAWALS-FEES-CHARGES\" => if not found then blank => top => get line above\r\n\r\nignore header above 531\r\ndelete all lines containing  \"DATE DESCRIPTION AMOUNT\"\r\ndelete all lines containing \"THANK YOU FOR\"\r\n\r\ndelete text in box page.top page.bottom 405 page.right\r\n@deposits = get multi page table @DepositsTop @DepositsBottom 55 88 320 396 => describe table false \"*Date[M/d]\" Details #Credit\r\n\r\ngo to page 1\r\n// Get start & end of Debit table\r\n@debitstop = get line containing \"WITHDRAWALS-FEES-CHARGES\" => if not found then blank => bottom => get line below\r\n@debitsbottom = get line containing \"ITEM DATE AMOUNT\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"WITHDRAWALS-FEES-CHARGES\"\r\ndelete all lines containing \" - CHECKS -\"\r\n\r\n@debits = get multi page table @debitstop @debitsbottom 55 88 320 397 => describe table false \"*Date[M/d]\" Details #Debit\r\n\r\n// Get start & end of cheques table\r\ngo to page 1\r\n@chequeTop = get line starting \"ITEM DATE AMOUNT\" => if not found then blank => bottom => get line below\r\n@chequebottom = get line containing \"INDICATES GAP IN CHECK\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \" - CHECKS -\"\r\ndelete all lines containing \"ITEM DATE AMOUNT\"\r\n@chequeLeft = get multi page table @chequeTop @chequebottom 70 105 146 224 => describe table false ChequeNumber \"Date[M/d]\" *#Debit\r\n@chequeRight = get multi page table @chequeTop @chequebottom 244 276 313 395 => describe table false ChequeNumber \"Date[M/d]\" *#Debit\r\n\r\n$transactions = combine described tables @deposits @debits @chequeLeft @chequeRight','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10872,'FAB_Bank1','$source = \"FAB_Bank1\"\r\n$periodBufferDays = 30\r\n\r\n//Get account name\r\n@bottom = get line containing \"DATE VALUE DATE DESCRIPTION\" => top\r\n$accountName = get text in box page.top @bottom 0 page.middleX => take words 3 => get text\r\n\r\n//Get account number\r\n\r\n$accountNumber = get line containing \"AC-NUM :\" => get words after \"AC-NUM :\" => take last words 1 => get text\r\n\r\n//Get opening Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\r\n\r\n//Get closing Balance\r\n$closingBalance = get line containing \"Closing Statement Balance\" => get words after \"Closing Statement Balance\" => get decimal\r\n\r\n//Get statementperiod\r\ngo to page 1\r\n//$PeriodFrom = get line containing \"Account Statement\" => get words between \"FROM\" \"TO\" => get date \"dd/MM/yyyy\"\r\n@PeriodFromTop = get line containing \"DATE VALUE DATE DESCRIPTION DEBIT\" => bottom\r\n$PeriodFromBox = get text in box @PeriodFromTop 0 15 70\r\n$PeriodFrom = take words $PeriodFromBox 3 => get date \"dd MMM yyyy\"\r\n\r\n$periodTo = get line containing \"Account Statement\" => get words after \"TO\" => get date \"dd/MM/yyyy\"\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"DATE VALUE DATE DESCRIPTION\" => bottom => get line below => bottom => get line below\r\n\r\n// Get end of table\r\n@transactionsBottom = get line containing \"Closing Statement Balance\" => top => get line above\r\n\r\n//ignore header\r\nget last line containing \"DATE VALUE DATE DESCRIPTION DEBIT\" => top => ignore header above\r\n\r\n//ignore footer\r\ngo to page 1\r\nget line containing \"Balance carried forward\" => bottom => ignore footer below\r\n\r\n//delete extra lines/texts\r\ndelete all lines containing \"Balance brought forward\"\r\ndelete all lines containing \"DATE VALUE DATE DESCRIPTION\"\r\ndelete all lines containing \"Balance carried forward\"\r\ndelete all lines containing \"As On\"\r\ndelete all lines containing \"Opening balance\"\r\ndelete all lines containing \"END OF STATEMENT\"\r\ndelete all lines containing \"Closing Statement Balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 10 70 140 320 410 490 580 => describe table false \"*Date[dd MMM yyyy]\" - Details #Debit #Credit #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10873,'TSB_Serial','$source = \"TSB_Serial\"\r\n\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\n\r\n$periodBufferDays = 30\r\n\r\n// Get Account Name\r\n\r\n$accountName = get line containing \"Date Serial Transaction details\" => top => get line above => top => get line above => take words 2 => get text\r\n\r\n// Get Account Number\r\n\r\n$accountNumber = get line containing \"Date Serial Transaction details\" => top => get line above => take words 1 => get text\r\n\r\n\r\n//Get PeriodInBOx\r\n\r\n$PeriodFrom = get line containing \"Date Range\" => get words after \"Date Range\" => get words after \"Date Range\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\n$PeriodTo = get line containing \"Date Range\" => get words after \"Date Range\" => get words after \"Date Range\" => take last words 3 => get date \"d MMM yyyy\"\r\n\r\ngo to page 1\r\n$openingBalance = get line containing \"Date Serial Transaction details Withdrawals Deposits Balance\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n//go to last page\r\n@TEXTBOXTop2 = get last line containing \"Date Serial Transaction details Withdrawals Deposits Balance\" => bottom\r\n$TEXTBOX2 = get text in box @TEXTBOXTop2 45 500 580\r\n$closingBalance = take last words $TEXTBOX2 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line containing \"Date Serial Transaction details Withdrawals Deposits Balance\" => bottom => get line below\r\n\r\n@transactionsbottom = get last line containing \"Page\" => top => get line above\r\ndelete all lines containing \"Date Serial Transaction details Withdrawals Deposits Balance\"\r\nignore header above 720\r\nignore footer below 45\r\n\r\n$transactions = get multi page table @transactionstop @transactionsbottom 25 90 131 350 441 500 580 => describe table false \"*Date[d MMM yyyy]\" TransactionType Details #Debit #Credit #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10874,'JMMB_Bank','$source = \"JMMB_Bank\"\r\n$periodBufferDays = 28\r\nset negative marker \"-\"\r\n\r\n// Get account name/number\r\n$accountName = get text in box page.top 0 0 250 => take words 3 => get text\r\n$accountNumber = get line containing \"Account No\" => get words after \"Account No\" => take words 1 => get text\r\n\r\n// Get period from/to\r\n$periodFrom = get line containing \"For Period\" => get words before \"to\" => take last words 1 => get date \"dd-MMM-yyyy\"\r\n$periodTo = get line containing \"For Period\" => get words after \"to\" => take words 1 => get date \"dd-MMM-yyyy\"\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line containing \"Balance Brought Forward\" => get words after \"Balance Brought Forward\" => take last words 1 => get decimal\r\n@closingTop = get line containing \"Closing Balance\" => get words before \"Balance\" => take last words 1 => bottom\r\n@closingLeft = get line containing \"Closing Balance\" => get words before \"Balance\" => take last words 1 => left\r\n@closingRight = get line containing \"Closing Balance\" => get words after \"Closing\" => take words 1 => right => add 5\r\n$closingBalance = get text in box @closingTop 0 @closingLeft @closingRight => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Post Date Description\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailsLeft = get words after @header \"Post Date\" => take words 1 => left => subtract 10\r\n@categoryLeft = get words after @header \"Description\" => take words 1 => left => subtract 10\r\n@chequeLeft = get words before @header \"Debits\" => take last words 1 => left => subtract 10\r\n@chequeRight = get words before @header \"Debits\" => take last words 1 => right => subtract 10\r\n@debitsRight = get words before @header \"Credits\" => right => add 10\r\n@creditsRight = get words before @header \"Balance\" => right => add 10\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\ngo to page 1\r\n// Get the start and end of the transaction category table\r\n@transactionCategoryTop = get line starting \"Post Date Description Category Cheque\" => if not found then blank => bottom => get line below\r\n@transactionCategoryBottom = get last line starting \"Summary\" => if not found then blank => top => get line above\r\n\r\ngo to page 1\r\n// Get the start and end of the transaction table without category\r\n@transactionTop = get line starting \"Post Date Description Cheque\" => if not found then blank => bottom => get line below\r\n@transactionBottom = get last line starting \"Summary\" => if not found then blank => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Post Date Description\" => bottom => ignore header above\r\nget last line starting \"Page\" => top => ignore footer below\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines containing \"Balance Brought Forward\"\r\ndelete all lines starting \"Account No\"\r\ndelete all lines starting \"For Period\"\r\ndelete all lines starting \"This statement\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Summary\"\r\ndelete all lines starting \"Account Statement\"\r\ndelete all lines starting \"Post Date Description\"\r\n\r\n@transactionCategoryTable = get multi page table @transactionCategoryTop @transactionCategoryBottom @dateLeft @detailsLeft @categoryLeft @chequeLeft @chequeRight @debitsRight @creditsRight @balanceRight => describe table false \"*Date[dd-MMM-yyyy]\" TransactionType Details ChequeNumber #Debit #Credit #Balance\r\n@transactionTable = get multi page table @transactionTop @transactionBottom @dateLeft @detailsLeft @chequeLeft @chequeRight @debitsRight @creditsRight @balanceRight => describe table false \"*Date[dd-MMM-yyyy]\" Details ChequeNumber #Debit #Credit #Balance\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @transactionCategoryTable @transactionTable','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10875,'InvestecBank_CurrencyAccount_TransDate','$source = \"InvestecBank_CurrencyAccount_TransDate\"\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\n$periodBufferDays = 30\r\n\r\n// Get account name\r\n@AccountNameBottom = get line containing \"for the period\" => top\r\n$accountName = get text in box page.top @AccountNameBottom 0 page.middleX => skip words 3 => take words 2 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Account number\" => get words after \"number\" => take words 1 => get text\r\n\r\n// Get dates\r\n$periodFrom = get line containing \"for the period\" => get words after \"period\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodTo = get line containing \"for the period\" => get words after \"period\" => take last words 3 => get date \"dd MMMM yyyy\"\r\n\r\n// Get Balances\r\ngo to page 1\r\n@TEXTBOXTop = get line containing \"Posting date Transaction date Transaction details\" => bottom\r\n$TEXTBOX = get text in box @TEXTBOXTop 0 500 page.right\r\n$openingBalance = take words $TEXTBOX 1 => get decimal\r\n\r\ngo to page 1\r\n// Get top of the transaction table\r\n@transactionsTop = get line containing \"Posting date Transaction date Transaction details\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"Total\" => top => get line above\r\n\r\ndelete all lines starting \"Investec Bank plc\"\r\ndelete all lines containing \"Financial Conduct Authority\"\r\ndelete all lines containing \"London Stock Exchange\"\r\n\r\n$lastTotal = get last line containing \"Total\" => top => get line above => bottom\r\n$TEXTBOX2 = get text in box page.top $lastTotal 500 page.right\r\n$closingBalance = take last words $TEXTBOX2 1 => get decimal\r\ndelete all lines containing \"Total\"\r\nignore footer below 35\r\n// Read the transactions\r\n$transactions  = get multi page table @transactionsTop @transactionsBottom 30 110 180 370 428 500 570 => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10876,'TDCanadaTrust_TransactionDescription','$source = \"TDCanadaTrust_TransactionDescription\"\r\n$features = \"OPENING_BALANCE_FROM_FIRST_ROW\"\r\n$periodBufferDays = 30\r\n\r\n// Get account name\r\n@AccountNameBottom = get line containing \"Transaction Description\" => top\r\n$accountName = get text in box page.top @AccountNameBottom 0 page.middleX => take words 3 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"ACCOUNT NUMBER:\" => get words after \"ACCOUNT NUMBER:\" => take words 1 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"FROM DATE:\" => get words after \"FROM DATE:\" => take words 1 => get date \"yyyy-MM-dd\"\r\n$periodTo = get line containing \"TO DATE:\" => get words after \"TO DATE:\" => take words 1 => get date \"yyyy-MM-dd\"\r\n\r\n// Get opening balance\r\ngo to page 1\r\n@TEXTBOXTop = get line starting \"Transaction Description Withdrawal Amount Deposit Amount Date Balance\" => bottom\r\n$TEXTBOX = get text in box @TEXTBOXTop 0 500 page.right\r\n$openingBalance = take words $TEXTBOX 1 => get decimal\r\n\r\nignore header above 540\r\nignore footer below 40\r\n\r\n// Get closing balance\r\ngo to last page\r\n@LastBalanceLine = get last line containing \"Transaction Description Withdrawal Amount Deposit Amount Date Balance\" => bottom\r\n$TEXTBOX2 = get text in box @LastBalanceLine 0 500 page.right\r\n$closingBalance = take last words $TEXTBOX2 1 => get decimal\r\n\r\n// Get transaction table bounds\r\ngo to page 1\r\n@transactionsTop = get line starting \"Transaction Description Withdrawal Amount Deposit Amount Date Balance\" => bottom => get line below\r\ngo to last page\r\n@transactionsBottom = get line above 0\r\ndelete all lines containing \"Transaction Description\"\r\n\r\n// Read the transactions\r\n$transactions  = get multi page table @transactionsTop @transactionsBottom 50 202 305 418 500 570 => describe table false Details #Debit #Credit \"*Date[MM/dd/yyyy]\" #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10877,'Taekus_Bank','$source = \"Taekus_Bank\"\r\n$periodBufferDays = 7\r\nset negative marker \"-\"\r\n\r\n//Get Account name & Account number\r\ngo to page 1\r\n@AccountTop = get line ending \"Account Number\" => bottom\r\n@AccountBottom = get line containing \"Statement Period\" => top\r\n$accountNumber = get text in box @AccountTop @AccountBottom page.middleX page.right => take words 1 => get text\r\n$accountName = get text in box page.top @AccountBottom 0 page.middleX => take words 3 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line starting \"Beginning Balance\" => get words after \"as of\" => take words 3 => get date \"MMM d, yyyy\"\r\ngo to page 1\r\n$periodTo = get line containing \"Ending Balance\" => get words after \"as of\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n// Get opening balance\r\n$openingBalance = get line starting \"Beginning Balance\" => get words after \"as of\" => skip words 3 => take words 1 => get decimal\r\n\r\n// Get closing balance\r\n$closingBalance = get line containing \"Ending Balance\" => get words after \"as of\" => skip words 3 => take words 1 => get decimal\r\n\r\n// transactions top & bottom\r\ngo to page 1\r\n@transactionsTop = get line containing \"Posted Date Description Type\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get last line containing \"End Balance\" => if not found then blank => top => get line above\r\n\r\n// Discard unwanted text\r\nignore footer below 28\r\n\r\n// Get transactions\r\n//$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 3 0 69 330 390 451 512 565 => describe table false \"Date[M/d/yyyy]\" Details TransactionType #Credit #Debit #Balance\r\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 3 0 80 320 380 440 510 565 => describe table false \"Date[M/d/yyyy]\" Details TransactionType #Credit #Debit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10878,'myPOS','$source = \"myPOS\"\r\n$periodBufferDays = 28\r\n$features = \"REVERSE_ORDER\"\r\n\r\n// Get account number/name\r\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 2 => get decimal\r\n$accountName = get line containing \"Account name:\" => get words after \"Account name:\" => take words 3 => get text\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line starting \"Closing balance:\" => get words after \"Closing balance:\" => take words 1 => get decimal\r\n$closingBalance = get line starting \"Opening balance:\" => get words after \"Opening balance:\" => take words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n@periodText = get line containing \"Type Description Exch. Rate Debit Credit\"\r\n@periodLeft = get words before @periodText \"date\" => take last words 1 => left => subtract 5\r\n@periodRight = get words after @periodText \"Value\" => take words 1 => right => add 5\r\n@periodTop = get words after @periodText \"Value\" => take words 1 => bottom\r\n$periodTo = get text in box @periodTop 0 @periodLeft @periodRight => take words 1 => get date \"ddMMyyyy\"\r\n\r\n// Discard header\r\nignore header above 750\r\ndelete all lines starting \"Monthly statement\"\r\n\r\n// Get the last transaction footer position\r\n@periodFromBottom = get last line starting \"myPOS\" => top => get line above => bottom\r\n$periodFrom = get text in box page.top @periodFromBottom @periodLeft @periodRight => take last words 1 => get date \"ddMMyyyy\"\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line containing \"Type Description Exch. Rate Debit Credit\"\r\n\r\ngo to page 1\r\n// Get start & end of the transaction\r\n@transactionTop = get line containing \"Type Description Exch. Rate Debit Credit\" => bottom => get line below\r\n@transactionBottom = get last line starting \"myPOS\" => top => get line above\r\n\r\n// Column coordinates\r\n@dateLeft = get words before @header \"date\" => take last words 1 => left => subtract 5\r\n@dateRight = get words after @header \"Value\" => take words 1 => Right => add 5\r\n@typeLeft = get words before @header \"Description\" => take last words 1 => left => subtract 3\r\n@detailLeft = get words after @header \"Type\" => take words 1 => left => subtract 10\r\n@detailRight = get words after @header \"Description\" => take words 1 => left => subtract 5\r\n@debitLeft = get words before @header \"Credit\" => take last words 1 => left => subtract 15\r\n@debitRight = get words before @header \"Credit\" => take last words 1 => right => add 10\r\n@creditRight = get words after @header \"Debit\" => take words 1 => right => add 10\r\n\r\n//Ignore footer\r\nget last line starting \"myPOS\" => top => add 10 => ignore footer below\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines containing \"Type Description Exch. Rate Debit Credit\"\r\ndelete all lines starting \"Value date\"\r\ndelete all lines starting \"Opening balance:\"\r\ndelete all lines starting \"Closing balance:\"\r\ndelete all lines starting \"Operation type Amount\"\r\ndelete all lines starting \"Fee\"\r\ndelete all lines starting \"Outgoing bank transfer\"\r\ndelete all lines starting \"Payment\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionTop @transactionBottom 5 @dateLeft @dateRight @typeLeft @detailLeft @detailRight @debitLeft @debitRight @creditRight => describe table false \"Date[ddMMyyyy]\" - TransactionType Details - #Debit #Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10879,'Branch_CreditCard','$source = \"Branch_CreditCard\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number/name\r\n$accountNumber = get line containing \"ACCOUNT NUMBER\" => get words after \"ACCOUNT NUMBER\" => take words 2 => get decimal\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take last words 1 => get decimal\r\n$closingBalance = get line starting \"Ending Balance on\" => get words after \"Ending Balance on\" => take last words 1 => get decimal\r\n\r\n// Get periods\r\ngo to page 1\r\n$periodFrom = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take words 3 => get date \"MMM d, yyyy\"\r\n$periodTo = get line starting \"Ending Balance on\" => get words after \"Ending Balance on\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\ngo to page 1\r\n// Header & column coordinates\r\n@header = get line starting \"Posted Date Description Category\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@dateRight = get words before @header \"Description\" => take last words 1 => right => add 2\r\n@detailsRight = get words after @header \"Description\" => take words 1 => right => add 2\r\n@amountRight = get words before @header \"Balance\" => take last words 1 => right => add 2\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\ngo to page 1\r\n// Get start & end of the transaction\r\n@transactionTop = get line starting \"Posted Date Description Category\" => bottom => get line below\r\ngo to last page\r\n@transactionBottom = get line above 0\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Transactions\"\r\ndelete all lines starting \"Posted Date Description Category\"\r\ndelete all lines containing \"ACCOUNT NUMBER:\"\r\ndelete all lines ending \"days)\"\r\ndelete all lines ending \"Statement Range:\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @dateRight @detailsRight @amountRight @balanceRight => describe table false \"*Date[M/d/yyyy]\" Details #Credit #Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10880,'ChaseBank_US_Spanish_DETALLE','$source = \"ChaseBank_US_Spanish_DETALLE\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\nset culture \"es-US\"\r\n\r\n// Delete vertical text\r\ndelete rotated words\r\n\r\n// Get Account Number\r\n@accountNumberText = get line containing \"Número De Cuenta:\" => get words after \"Número De Cuenta:\"\r\n$accountNumber = take words @accountNumberText 1 => get text\r\n//accountNumber and accountName can have same output as only accountNumber is getting check at runtime\r\n$accountName = take words @accountNumberText 1 => get text\r\n// Get bank details\r\n@summaryLine = get line containing \"INFORMACIÓN PARA ATENCIÓN AL CLIENTE\" => top\r\n$panelDetails = get text in box page.top @summaryLine page.left page.right\r\n//$accountName = get words before $panelDetails \"Número De Cuenta:\" => skip words 7 => take words 3 => get text\r\n$statementPeriod = get words before $panelDetails \"Número De Cuenta:\" => take words 7\r\n$PeriodFrom =  take words $statementPeriod 3 => get date \"MMMM dd, yyyy\"\r\n$PeriodTo = take last words $statementPeriod 3 => get date \"MMMM dd, yyyy\"\r\ndelete text in box page.top @summaryLine page.left page.right\r\n\r\n// Get opening and closing balances\r\n$openingBalanceText = get line starting \"Saldo inicial\" => skip words 2\r\n$openingBalance = get decimal $openingBalanceText\r\n$closingBalanceText = get line starting \"Saldo final\" => take last words 1\r\n$closingBalance = get decimal $closingBalanceText\r\n\r\n\r\n// Discard page footer\r\nget line above 0 => top => ignore footer below\r\ngo to page 1\r\ndelete text in box on every page page.top page.bottom 537 page.right\r\n\r\n@transactionstop = get line starting \"FECHA DESCRIPCIÓN\" => bottom => get line below\r\n@transactionsbottom = get last line starting \"Saldo final\" => top => get line above\r\n\r\n$Date_left = get line containing \"FECHA DESCRIPCIÓN\" => get words before \"DESCRIPCIÓN\" => left => subtract 3\r\n$Date_right = get line containing \"FECHA DESCRIPCIÓN\" => get words after \"FECHA\" => take words 1 => left => subtract 5\r\n$Desc_right = get line containing \"FECHA DESCRIPCIÓN\" => get words after \"FECHA DESCRIPCIÓN\" => take words 1 => left => subtract 10\r\n$Credit_right = get line containing \"FECHA DESCRIPCIÓN\" => get words after \"FECHA DESCRIPCIÓN\" => take words 1 => right => add 6\r\n$Balance_right = get line containing \"FECHA DESCRIPCIÓN\" => get words after \"CANTIDAD\" => take words 1 => right => add 3\r\n\r\n// Remove unwanted lines\r\ndelete all lines starting \"FECHA DESCRIPCIÓN\"\r\ndelete all lines starting \"*end\"\r\ndelete all lines starting \"*start\"\r\ndelete all lines starting \"Página\"\r\ndelete all lines containing \"continuación\"\r\ndelete all lines containing \"Saldo inicial\"\r\n\r\nignore header above 682\r\n\r\n// Read the transactions\r\n\r\n$transactions = get multi page table @transactionstop @transactionsbottom $Date_left $Date_right $Desc_right $Credit_right $Balance_right => describe table false \"*Date[M/d]\" Details *#Credit *#Balance','2026-04-30 08:38:50',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10881,'SterlingFederal_Bank','$source = \"SterlingFederal_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n//Get Periods\r\ngo to page 1\r\n$periodFromText = get line containing \"Period:\" => get words after \"Period:\"\r\n$periodFrom = take words $periodFromText 3 => get date \"MMM d, yyyy\"\r\n$periodTo = take last words $periodFromText 3 => get date \"MMM d, yyyy\"\r\n\r\n//Get Accounts, accountname and accountnumber can have same logic\r\n$accountname = get line containing \" ACCOUNT #:\" => get words after \"ACCOUNT #: CK -\" => take words 1 => get text\r\n$accountNumber = get line containing \" ACCOUNT #:\" => get words after \"ACCOUNT #: CK -\" => take words 1 => get text\r\n\r\n//Get Opening and Closing Balances\r\ngo to page 1\r\n$openingbalance = get line containing \"Beginning Balance\" => bottom => get line below => take last words 1 => get decimal\r\n$closingbalance = get line containing \"Ending Balance\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n//Transaction tables starts here\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Check# Description\" =>  bottom => get line below\r\n@transactionsBottom = get line containing \"Check Information\" => top => get line above\r\n\r\n//delete extra lines\r\ndelete all lines containing \"Date Check# Description\"\r\ndelete all lines containing \"Check# Description\"\r\n//ignore pdf co-ordinates\r\nignore header above 602\r\n\r\n// Read the transactions\r\ngo to page 1\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 33 71 136 356 417 514 => describe table false \"*Date[M/d]\" TransactionType Details #Credit #Balance','2026-04-30 08:38:50',0);
