INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10885,'Commerce_Bank','$source = \"Commerce_Bank\"\r\n$periodBufferDays = 5\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Get account holder name\r\n@nameBottom = get line containing \"Primary Account Number:\" => top\r\n$accountName = get text in box page.top @nameBottom 0 page.middleX => take words 1 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line containing \"Primary Account Number:\" => get words after \"Primary Account Number:\" => take words 1 => get text\r\n\r\n// Get statement period\r\n$periodTo = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 3 => get date \"MMMM d, yyyy\"\r\n\r\n// Get Period from\r\n$periodFrom = get line containing \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take words 3 => get date \"MMMM d, yyyy\"\r\n\r\n// Get opening balance\r\n$openingBalance = get line containing \"Beginning Balance on\" => take last words 1 => get decimal\r\n\r\n// Get closing balance\r\n$closingBalance = get line containing \"Ending Balance on\" => take last words 1 => get decimal\r\n\r\n// delete summary\r\n@SummaryBottom = get line containing \"Ending Balance on\" => top\r\ndelete text in box page.top @SummaryBottom page.left page.right\r\n\r\n// delete header line\r\ndelete all lines containing \"Primary Account Number:\"\r\ndelete all lines containing \"Statement Date:\"\r\ndelete all lines containing \"Page Number:\"\r\n\r\n// delete transaction headers\r\ndelete all lines ending \"Date\"\r\ndelete all lines containing \"Description Credited Amount\"\r\ndelete all lines containing \"Description Date Paid Amount\"\r\ndelete all lines containing \"Page Number:\"\r\ndelete all lines containing \"(Cont.)\"\r\n\r\n// Header cleanup\r\nignore header above 705\r\n\r\ngo to page 1\r\n// Start and End of Deposits & Other Credits Table\r\n@Deposits&OtherCrTop = get line containing \"Deposits & Other Credits Account #\" => if not found then blank => bottom => get line below\r\n@Deposits&OtherCrBottom = get line containing \"Total Deposits & Other Credits\" => if not found then blank => top => get line above\r\n@Deposits&OtherCrTransactions = get multi page table @Deposits&OtherCrTop @Deposits&OtherCrBottom 40 240 440 520 590 => describe table false TransactionType Details \"*Date[MM-dd]\" #Credit\r\n\r\ngo to page 1\r\n// Start and End of Debit Card Purchases & Debits Table\r\n@DrCardPurchasesTop = get line containing \"Debit Card Purchases & Debits\" => if not found then blank => bottom => get line below\r\n@DrCardPurchasesBottom = get line containing \"Total Debit Card Purchases & Debits\" => if not found then blank => top => get line above\r\n@DrCardPurchasesTransactions = get multi page table @DrCardPurchasesTop @DrCardPurchasesBottom 40 240 440 480 520 590 => describe table false TransactionType Details \"*Date[MM-dd]\" - #Debit\r\n\r\ngo to page 1\r\n// Start and End of ATM Withdrawals & Debits Table\r\ndelete all lines containing \"Transaction date is when the item was authorized\"\r\ndelete all lines containing \"the transaction to process.\"\r\n@ATMWithdrawalsTop = get line containing \"ATM Withdrawals & Debits\" => if not found then blank => bottom => get line below\r\n@ATMWithdrawalsBottom = get line containing \"Total ATM Withdrawals & Debits\" => if not found then blank => top => get line above\r\n@ATMWithdrawalsTransactions = get multi page table @ATMWithdrawalsTop @ATMWithdrawalsBottom 40 240 440 480 520 590 => describe table false TransactionType Details \"*Date[MM-dd]\" - #Debit\r\n\r\ngo to page 1\r\n// Start and End of Withdrawals & Other Debits Table\r\n@Withdrawals&OtherDrTop = get line containing \"Withdrawals & Other Debits\" => if not found then blank => bottom => get line below\r\n@Withdrawals&OtherDrBottom = get line containing \"Total Withdrawals & Other Debits\" => if not found then blank => top => get line above\r\n@Withdrawals&OtherDrTransactions = get multi page table @Withdrawals&OtherDrTop @Withdrawals&OtherDrBottom 40 240 440 480 520 590 => describe table false TransactionType Details \"*Date[MM-dd]\" - #Debit\r\n\r\ndelete all lines containing \"Date Check Reference\"\r\ndelete all lines containing \"Paid Number Amount\"\r\n\r\n// Get start and end of checks table\r\n@checksTop = get line starting \"Checks Paid\" => if not found then blank => bottom => get line below\r\n@checksBottom = get line starting \"Total Checks Paid\" => if not found then blank => top => get line above\r\n@checks1 = get multi page table @checksTop @checksBottom 40 100 160 240 233 315 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit - Details\r\n@checks2 = get multi page table @checksTop @checksBottom 315 370 440 510 503 590 => describe table false \"Date[MM-dd]\" ChequeNumber *#Debit - Details\r\n\r\n$transactions = combine described tables @DrCardPurchasesTransactions @ATMWithdrawalsTransactions @Withdrawals&OtherDrTransactions @Deposits&OtherCrTransactions @checks1 @checks2','2026-05-14 09:56:58',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10886,'Discover_Card_WithoutSummary','$source = \"Discover_Card_WithoutSummary\"\r\n\r\n$periodBufferDays = 15\r\n$features = \"CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n\r\n// Get Account Name\r\n$accountName = get line containing \"Acct Ending\" => get words before \"Acct Ending\" => take words 1 => get text\r\n\r\n// Get Account Number\r\n$accountNumber = get line containing \"Acct Ending\" => get words after \"Acct Ending\" => take words 1 => get text\r\n\r\n//Get dates\r\n$periodFrom = get line starting \"Activity Period:\" => get words between \"Activity Period:\" \"-\" => take words 2 => get date \"MMM d\"\r\n$periodTo = get line starting \"Activity Period:\" => get words after \"Activity Period:\" => get words after \"-\" => get date \"MMM d, yyyy\"\r\n\r\n// Get Opening and Closing Balances (not given in statements)\r\n$OpeningBalance = 0\r\n$closingBalance = 0\r\n\r\n// Dynamic Coordinates for transaction table\r\n$Date_Right = get line containing \"Description Amount Category\" => get words before \"Amount\" => take last words 1 => left => subtract 2\r\n$Description_Left = get line containing \"Description Amount Category\" => get words before \"Amount\" => take last words 1 => left => subtract 10\r\n$Amount_Left = get line containing \"Description Amount Category\" => get words before \"Category\" => take last words 1 => left => subtract 2\r\n$Amount_Right = get line containing \"Description Amount Category\" => get words after \"Amount\" => take last words 1 => left => subtract 1\r\n$Category_Left = get line containing \"Description Amount Category\" => get words after \"Amount\" => take last words 1 => left => subtract 5\r\n\r\n// Get start and end of table\r\n@TransactionsTop = get line containing \"Description Amount Category\" => bottom => get line below\r\n@TransactionsBottom = get last line containing \"Statement Balance is the total of all