INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10887,'AmericanExpress_Card_EqualsNewBalance','$source = \"AmericanExpress_Card_EqualsNewBalance\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 15\r\n\r\nset negative marker \"CR\"\r\n\r\n//Get account name and number\r\n$accountNumber = get line containing \"Account Ending\" => get words after \"Account Ending\" => take words 1 => get text\r\n$accountName = get line containing \"Account Ending\" => top => get line above => take words 1 => get text\r\n\r\n// Get period to\r\n$periodTo = get line starting \"Closing Date\" => get words after \"Closing Date\" => take words 1 =>  get date \"MM/dd/yy\"\r\n\r\n// Get Opening and Closing Balance\r\n@BalancesTop = get line containing \"Account Total\" => bottom\r\ndelete text in box page.top @BalancesTop 0 page.right\r\n@BalancesBottom = get line containing \"Equals New Balance\" => bottom\r\n@Balances = get text in box @BalancesTop @BalancesBottom 0 page.middleX\r\n$openingBalance = get words after @Balances \"Previous Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after @Balances \"Equals New Balance\" => take words 1 => get decimal\r\n\r\n// Dynamic Coordinates for transaction table\r\n@Date_Right = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 3\r\n@Description_Left = get line containing \"Date Description\" => get words after \"Date\" => take words 1 => left => subtract 9\r\n\r\ndelete all lines containing \"*Indicates posting date\"\r\ndelete all lines containing \"Card Ending\"\r\n\r\n// Get start & end of Credits Details transactions\r\ngo to page 3\r\n@creditsTop = get line starting \"Credits Details\" => if not found then blank => bottom => get line below  => bottom => get line below => bottom => get line below  => bottom => get line below\r\n@creditsBottom = get last line starting \"New Charges Summary\" => if not found then blank => top => get line above\r\n$credits = get multi page table @creditsTop @creditsBottom  30 @Date_Right @Description_Left 380 452 530 600 => describe table false \"*Date[MM/dd/yy]\" - Details TransactionType - #Credit\r\n\r\n// Delete Credits Details transactions\r\n@creditsTop0 = get line starting \"Credits Details\" => top\r\n@creditsBottom0 = get last line starting \"New Charges Summary\" => top\r\ndelete text in box @creditsTop0 @creditsBottom0  page.left page.right => get text\r\n\r\n// Get start & end of Payments Details transactions\r\ngo to page 3\r\nget line starting \"Payments Details\"\r\n@PaymentsTop = get line starting \"Payments Details\" => if not found then blank => bottom => get line below  => bottom => get line below\r\n@PaymentsBottom = get last line starting \"New Charges Summary\" => if not found then blank => top => get line above\r\n\r\ngo to page 1\r\n@delTop = get line starting \"New Charges\" => top\r\n@delbottom = get line starting \"Total New Charges\" => bottom\r\ndelete text in box @delTop @delbottom  page.left page.right => get text\r\n\r\n// Get period from\r\ngo to page 3\r\n$periodFrom = get line starting \"Date Description Type Foreign Spend Amount\" => bottom => get line below => take words 1 => get date \"MM/dd/yy\"\r\n\r\n// Get Start of DEBIT transactions\r\n@debitsTop = get line starting \"Date Description Type Foreign Spend Amount\" => if not found then blank => bottom => get line below\r\n@debitsBottom = get last line starting \"Fees\" => if not found then blank => top => get line above\r\n\r\n// Get start & end of Fees table\r\ngo to page 3\r\n@FeesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\r\n@FeesBottom = get last line starting \"Total Fees for this Period\" => if not found then blank => top => get line above\r\n\r\n// Get start & end of interest table\r\ngo to page 3\r\n@interestTop = get line starting \"Interest Charged\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@interestBottom = get line starting \"Total Interest Charged for this Period\" => if not found then blank => top => get line above\r\n\r\n// Discard page footer\r\nignore footer below 25\r\n\r\n// Remove unwanted lines\r\ndelete all lines containing \"Date Description\"\r\ndelete all lines containing \"Date Account Name Description\"\r\ndelete all lines starting \"Cash Advances\"\r\ndelete all lines containing \"Total Cash Advances for this Period\"\r\ndelete all lines starting \"Total\"\r\ndelete all lines starting \"Card Ending\"\r\n\r\n// Read the transactions\r\n$Payments = get multi page table @PaymentsTop @PaymentsBottom 30 @Date_Right @Description_Left 530 600 => describe table false \"*Date[MM/dd/yy]\" - Details #Credit\r\n$debits = get multi page table @debitsTop @debitsBottom 30 @Date_Right @Description_Left 385 380 452 530 600 => describe table false \"*Date[MM/dd/yy]\" - Details - TransactionType - #Credit\r\n$Fees = get multi page table @FeesTop @FeesBottom 30 @Date_Right @Description_Left 440 530 600 => describe table false \"*Date[MM/dd/yy]\" - Details TransactionType #Credit\r\n$interest = get multi page table @interestTop @interestBottom 30 @Date_Right @Description_Left 530 600 => describe table false \"*Date[MM/dd/yy]\" - Details #Credit\r\n\r\n$transactions = combine described tables $Payments $credits $debits $Fees $interest','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10888,'FirstCitizens_Bank','$source = \"FirstCitizens_Bank\"\r\n$periodBufferDays = 30\r\nset negative marker \"DEBIT\"\r\n\r\n// Get account name\r\n@AccountNameBottom = get line containing \"DATE DESCRIPTION CHEQUE # ACTIVITY TYPE AMOUNT BALANCE\" => top\r\n$accountName = get text in box page.top @AccountNameBottom 0 245 => take words 3 => get text\r\n\r\n$accountNumber = get line containing \"CIF# A/C# ACCOUNT TYPE\" => bottom => get line below => take words 2 => take last words 1 => get text\r\n\r\n$periodFrom = get line containing \"CIF# A/C# ACCOUNT TYPE\" => bottom => get line below => get words before \"To\" => take last words 1 => get date \"yyyy-MM-dd\"\r\n\r\n$periodTo = get line containing \"CIF# A/C# ACCOUNT TYPE\" => bottom => get line below => get words after \"To\" => take words 1 => get date \"yyyy-MM-dd\"\r\n\r\n$closingBalance = get line containing \"Ending balance as of\" => get words after \"Ending balance as of\" => take last words 1 => get decimal\r\n\r\n$openingBalance = get line containing \"Beginning balance as of\" => get words after \"Beginning balance as of\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"DATE DESCRIPTION CHEQUE # ACTIVITY TYPE AMOUNT BALANCE\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"STATEMENT SUMMARY\" => top => get line above\r\ndelete all lines containing \"DATE DESCRIPTION CHEQUE # ACTIVITY TYPE AMOUNT BALANCE\"\r\ndelete all lines starting \"STATEMENT SUMMARY\"\r\n\r\nignore header above 1010\r\nignore footer below 90\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 100 290 380 590 670 => describe table false \"*Date[yyyy-MM-dd]\" TransactionType Details #Credit #Balance','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10889,'Bourso_Bank','$source = \"Bourso_Bank\"\r\n$periodBufferDays = 30\r\nset culture \"fr-FR\"\r\n\r\ngo to page 1\r\n$accountName = get line containing \"BOURSOBANK\" => bottom => get line below => take words 2 => get text\r\n$accountNumber = get line containing \"Banque Guichet N° de compte Clé RIB\" => bottom => get line below => take words 4 => take last words 1 => get text\r\n\r\n$periodFrom = get line containing \"Banque Guichet N° de compte Clé RIB\" => bottom => get line below => get words after \"du\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Banque Guichet N° de compte Clé RIB\" => bottom => get line below => get words after \"au\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n$openingBalance = get line containing \"SOLDE AU :\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Nouveau solde en EUR :\" => take last words 1 => get decimal\r\ngo to page 1\r\n@transactionsTop = get line containing \"SOLDE AU :\" => bottom => get line below\r\ngo to last page\r\n@transactionsBottom = get line containing \"Nouveau solde en EUR :\" => top => get line above\r\n\r\ndelete all lines starting \"SOLDE AU :\"\r\ndelete all lines containing \"Nouveau solde en EUR :\"\r\n\r\nignore header above 622\r\nignore footer below 158\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 94 380 440 504 550 => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10890,'City_National_Bank','$source = \"City_National_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 30\r\n\r\n@TEXTBOXTop = get line containing \"Last statement:\" => bottom\r\n@TEXTBOXBottom = get line containing \"Personal Checking Account\" => top\r\n// Get account name\r\n$accountName = get text in box @TEXTBOXTop @TEXTBOXBottom 0 page.middleX => take words 3 => get text\r\n// Get account Number\r\n$accountNumber = get line containing \"Account #:\" => get words after \"Account #:\" => take words 1 => get text\r\n// Get Periods\r\n$periodFrom = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take words 1 => get date \"M/dd/yyyy\"\r\n$periodTo = get line containing \"Ending balance\" => get words after \"Ending balance\" => take words 1 => get date \"M/dd/yyyy\"\r\n// Get OpenningClosingBalance\r\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get start & end of credits table\r\n$creditsTop = get line containing \"Date Description Credits\" => if not found then blank => bottom => get line below\r\n$creditsBottom = get last line ending \"Credits\" => if not found then blank => bottom => get break below => get line at\r\n\r\nignore header above 630\r\ndelete all lines starting \"Date Description Credits\"\r\ndelete all lines containing \"ELECTRONIC CREDITS (Continued)\"\r\ndelete all lines containing \"ELECTRONIC DEBITS\"\r\n\r\ngo to page 1\r\n// Get start & end of debits table\r\n$debitsTop = get line containing \"Date Description Debits\" => if not found then blank => bottom => get line below\r\n$debitsBottom = get line containing \"DAILY BALANCES\" => top => get line above\r\n\r\ndelete all lines containing \"OTHER DEBITS\"\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines containing \"DAILY BALANCES\"\r\n\r\n$credits = get multi page table $creditsTop $creditsBottom 20 62 500 575 => describe table false \"*Date[M-d]\" Details #Credit\r\n\r\n$debits = get multi page table $debitsTop $debitsBottom 20 62 500 575 => describe table false \"*Date[M-d]\" Details #Debit\r\n\r\n$transactions = combine described tables $credits $debits','2026-05-21 09:43:20',1);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10891,'Exchange_Bank','$source = \"Exchange_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 30\r\n\r\n@TEXTBOXBottom = get line containing \"Business Checking\" => top\r\n// Get account name\r\n$accountName = get text in box page.top @TEXTBOXBottom page.left page.middleX => take words 2 => get text\r\n\r\n// Get account Number\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\r\n// Get Periods\r\n$periodFrom = get line containing \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMMM dd yyyy\"\r\n$periodTo = get line containing \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMMM dd yyyy\"\r\n// Get OpenningClosingBalance\r\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take last words 1 => get decimal\r\n\r\n\r\n//get checks table left\r\n@leftChecksTransactionTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below\r\n@leftChecksTransactionBottom = get line starting \"DEBITS\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Number Date Amount\"\r\n\r\n//get debits transactions\r\n@transactionsLeftChecks = get multi page table @leftChecksTransactionTop @leftChecksTransactionBottom 100 185 265 315 => describe table false Details \"*Date[MM-dd]\" #Debit\r\n\r\n\r\n//get checks table right\r\n@rightChecksTransactionTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below\r\n@rightChecksTransactionBottom = get line starting \"DEBITS\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Skip\"\r\n\r\n\r\n//get debits transactions\r\n@transactionsRightChecks = get multi page table @rightChecksTransactionTop @rightChecksTransactionBottom 320 390 475 520 => describe table false Details \"*Date[MM-dd]\" #Debit\r\n\r\ngo to page 1\r\n// Get start & end of debit table\r\n$debitsTop = get line starting \"DEBITS\" => if not found then blank => bottom => get line below\r\n$debitsBottom = get last line ending \"Subtractions\" => if not found then blank => bottom => get break below => get line at\r\n\r\nignore header above 650\r\ndelete all lines ending \"Date Description Subtractions\"\r\ndelete all lines containing \"Date Description\"\r\n\r\ngo to page 1\r\n// Get start & end of credits table\r\n$creditsTop = get line starting \"CREDITS\" => if not found then blank => bottom => get line below\r\n$creditsBottom = get line containing \"DAILY BALANCES\" => top => get line above\r\n\r\ndelete all lines ending \"Additions\"\r\ndelete all lines containing \"DAILY BALANCES\"\r\n\r\n$credits = get multi page table $creditsTop $creditsBottom 100 150 460 520 => describe table false \"*Date[MM-dd]\" Details #Credit\r\n\r\n$debits = get multi page table $debitsTop $debitsBottom 100 150 460 520 => describe table false \"*Date[MM-dd]\" Details #Debit\r\n\r\n$transactions = combine described tables $debits $credits @transactionsLeftChecks @transactionsRightChecks','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10892,'AviatorBusiness_Card','$source = \"AviatorBusiness_Card\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n//Get account name\r\n$accountName = get line containing \"Individual Cardholder Activity\" => bottom => get line below => take words 2 => get text\r\n\r\n//Get account number\r\ngo to page 1\r\n$accountNumber = get line containing \"Account number ending in\" => take last words 1 => get text\r\n\r\n//Get Period To\r\n$PeriodTo = get last line containing \"Statement Closing Date\" => get words after \"Date\" => take words 3 => get date \"MMMM d, yyyy\"\r\n\r\n//GetPeriod From\r\n$periodFrom = get last line containing \"Date Date Reference Number\" => bottom => get line below => skip words 1 => take words 1 => get date \"M-d\"\r\n\r\n// Get opening and closing balances\r\ngo to page 1\r\n$openingBalance = get last line containing \"Previous Balance\" => get words after \"Balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Current Balance\" => get words after \"Balance\" => take words 1 => get decimal\r\n\r\n//Delete Extra Text\r\n@TextBoxTop1 = get line containing \"Finance Charge Summary\" => if not found then blank => bottom\r\n@TextBoxBottom1 = get last line starting \"Purchases\" => if not found then blank => top\r\n\r\n//Delete AccountDetails box\r\n$text1 = delete text in box @TextBoxTop1 @TextBoxBottom1 0 page.right => get text\r\n\r\n//Get start & end of Finance Charge Summary transactions table\r\ngo to page 1\r\n@transactionsTop1 = get line containing \"Finance Charge Summary\" => if not found then blank => bottom => get line below\r\n@transactionsBottom1 = get last line containing \"The Daily Periodic Rate\" => top => get line above => top => get line above\r\n@transactions1  = get multi page table @transactionsTop1 @transactionsBottom1 0 150 545 590 => describe table false Details - *#Credit\r\n\r\n//Delete Extra Text\r\n@TextBoxTop1 = get line containing \"Finance Charge Summary\" => if not found then blank => bottom\r\n@TextBoxBottom1 = get last line containing \"For Customer Service\" => top\r\n$text2 = delete text in box @TextBoxTop1 @TextBoxBottom1 0 page.right => get text\r\n\r\n//Get start & end of transactions table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Date Reference Number\"  => bottom => get line below\r\n@transactionsBottom = get last line containing \"For Customer Service\" => top => get line above\r\n\r\n//Discard page header\r\nignore header above 735\r\n\r\n//Discard page footer\r\nget line starting \"For Customer Service\" => top => ignore footer below\r\n\r\n//Remove unwanted lines\r\ndelete all lines containing \"Finance Charge Summary\"\r\ndelete all lines containing \"Transaction Post\"\r\ndelete all lines containing \"Date Date Reference Number\"\r\ndelete all lines containing \"Company Transaction Summary\"\r\ndelete all lines containing \"Payment Summary\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines containing \"For Customer Service\"\r\n\r\n//Read the transactions\r\n@transactions2  = get multi page table @transactionsTop @transactionsBottom 70 135 270 500 590 => describe table false \"Date[MM-dd]\" TransactionType Details *#Credit\r\n\r\n//Combine the transactions\r\n$transactions = combine described tables @transactions1 @transactions2','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10893,'FREMONT_BANK','$source = \"FREMONT_BANK\"\r\n$periodBufferDays = 28\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Get left and right coordinates of the table\r\ngo to page 1\r\n@tableHeader = get line containing \"Description Transaction Amount Date Balance\"\r\n@tableLeft = take words @tableHeader 1 => left => subtract 5\r\n@tableRight = take last words @tableHeader 1 => right => add 5\r\n\r\n// Delete rotated words\r\n@deleteLeftSide_rotatedWord = delete text in box on every page page.top 0 0 @tableLeft => get text\r\n@deleteRightSide_rotatedWord = delete text in box on every page page.top 0 @tableRight page.right => get text\r\n\r\n// Get account number/name\r\ngo to page 1\r\n@accountText = get line containing \"ACCOUNT NUMBER\"\r\n@accountTop = get words after @accountText \"ACCOUNT\" => take words 1 => bottom\r\n@accountRight = get words after @accountText \"ACCOUNT\" => take words 1 => right\r\n@accountLeft = get words before @accountText \"NUMBER\" => take last words 1 => left\r\n$accountNumber = get text in box @accountTop 0 @accountLeft @accountRight => take words 1 => get text\r\n$accountName = get text in box 660 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get periods\r\ngo to page 1\r\n$periodFrom = get line containing \"STATEMENT PERIOD\" => get words after \"PERIOD\" => take words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get line containing \"STATEMENT PERIOD\" => get words after \"THROUGH\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line starting \"BALANCE LAST STATEMENT\" => get words after \"BALANCE LAST STATEMENT\" => take words 2 => take last words 1 => get decimal\r\n$closingBalance = get line ending \"Balance This Statement\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line containing \"Description Transaction Amount Date Balance\"\r\n\r\n// Column coordinates\r\n@detailLeft = take words @header 1 => left => subtract 5\r\n@detailRight = take words @header 2 => take last words 1 => left => add 5\r\n@amountRight = get words before @header \"Date\" => take last words 1 => right => add 2\r\n@dateRight = get words after @header \"Amount\" => take words 1 => right => add 3\r\n@balanceRight = take last words @header 1 => right => add 5\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line containing \"Description Transaction Amount Date Balance\" => bottom => get line below\r\n@transactionBottom = get last line starting \"BALANCE THIS STATEMENT\" => top => get line above\r\n\r\n// Discard header and footer\r\ngo to page 1\r\nget line containing \"Continued on Next Page\" => top => ignore footer below\r\nget last line containing \"Description Transaction Amount Date Balance\" => top => ignore header above\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines ending \"ACCOUNT NUMBER\"\r\ndelete all lines starting \"STATEMENT DATE\"\r\ndelete all lines starting \"Phone:\"\r\ndelete all lines starting \"Website:\"\r\ndelete all lines starting \"Page:\"\r\ndelete all lines starting \"Business Plus Checking\"\r\ndelete all lines containing \"Description Transaction Amount Date Balance\"\r\ndelete all lines starting \"BALANCE LAST STATEMENT\"\r\ndelete all lines starting \"BALANCE THIS STATEMENT\"\r\ndelete all lines containing \"Continued on Next Page\"\r\ndelete all lines starting \"TOTAL\"\r\ndelete all lines starting \"ITEMIZATION OF SERVICE CHARGE PAID THIS PERIOD\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @detailLeft @detailRight @amountRight @dateRight @balanceRight => describe table false Details #Credit \"*Date[MMdd]\" #Balance','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10894,'HomeState_Bank','\r\n$source = \"HomeState_Bank\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => take last words 2 => take words 1 => get text\r\n$accountName = get text in box 690 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get periods\r\ngo to page 1\r\n$periodFrom = get line containing \"Beginning Balance\" => get words before \"Beginning Balance\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get last line containing \"Ending Balance\" => get words before \"Ending Balance\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get last line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Post Date Description Debits Credits Balance\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = get words after @header \"Date\" => take words 1 => left => subtract 5\r\n@debitLeft = get words after @header \"Description\" => take words 1 => left => subtract 28\r\n@debitRight = get words after @header \"Description\" => take words 1 => right => add 5\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Post Date Description Debits Credits Balance\" => bottom => get line below\r\n@transactionBottom = get last line containing \"Ending Balance\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Post Date Description Debits Credits Balance\" => top => ignore header above\r\nIgnore footer below 120\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Statement Ending\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines containing \"Beginning Balance\"\r\ndelete all lines containing \"Ending Balance\"\r\ndelete all lines starting \"Post Date Description Debits Credits Balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit  #Balance','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10895,'Raiffeisenlandes_Bank','$source = \"Raiffeisenlandes_Bank\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number/name\r\n$accountNumber = get line starting \"Konto:\" => get words after \"Konto:\" => take words 3 => take last words 1 => get text\r\n$accountName = get line starting \"Inhaber:\" => get words after \"Inhaber:\" => take words 3 => get text\r\n\r\n// Get periods\r\ngo to page 1\r\n$periodFrom = get line starting \"Datum Buchungstext Wert Betrag\" => bottom => get line below => take words 1 => get date \"dd.MM.yyyy\"\r\n$periodTo = get last line starting \"Kontostand per\" => get words after \"Kontostand per\" => take words 1 => get date \"dd.MM.yyyy\"\r\n\r\n// Set culture\r\ngo to page 1\r\nset culture \"nl-NL\"\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line starting \"Alter Kontostand\" => get words after \"Alter Kontostand\" => take words 1 => get decimal\r\n$closingBalance = get last line starting \"Kontostand per\" => get words after \"Kontostand per\" => take last words 2 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Datum Buchungstext Wert Betrag\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = get words after @header \"Datum\" => take words 1 => left => subtract 5\r\n@date2Top = take words @header 1 => bottom\r\n@date2Left = get words after @header \"Buchungstext\" => take words 1 => left => subtract 15\r\n@betragLeft = get words after @header \"Wert\" => take words 1 => left => subtract 10\r\n@date2Right = get text in box @date2Top 0 @date2Left @betragLeft  => take words 1 => right => add 5\r\n@amountRight = get words after @header \"Wert\" => take words 1 => right => add 2\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Datum Buchungstext Wert Betrag\" => bottom => get line below\r\n@transactionBottom = get last line starting \"Kontostand per\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Datum Buchungstext Wert Betrag\" => top => ignore header above\r\nget last line starting \"erstellt\" => if not found then blank => bottom => ignore footer below\r\nIgnore footer below 40\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"K O N T O A U S Z U G\"\r\ndelete all lines starting \"Raiffeisen\"\r\ndelete all lines starting \"Auszugsnr.:\"\r\ndelete all lines starting \"Raiffeisen\"\r\ndelete all lines starting \"Konto:\"\r\ndelete all lines starting \"Inhaber:\"\r\ndelete all lines starting \"Datum Buchungstext Wert Betrag\"\r\ndelete all lines starting \"Alter Kontostand\"\r\ndelete all lines starting \"Gutschriften\"\r\ndelete all lines starting \"Lastschriften\"\r\ndelete all lines starting \"Kontostand per\"\r\ndelete all lines containing \"gedruckt am\"\r\ndelete all lines starting \"erstellt\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @detailLeft @date2Left @date2Right @amountRight => describe table false \"*Date[dd.MM.yyyy]\" Details - #Credit','2026-05-14 09:56:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10896,'Eco_Bank','$source = \"Eco_Bank\"\r\n$periodBufferDays = 30\r\n\r\n//Get account name\r\n\r\n$accountName = get line containing \"Account Name :\" => get words after \"Account Name :\" => take words 3 => get text\r\n\r\n//Get account number\r\n$accountNumber = get line containing \"Account :\" => get words after \"Account :\" => take words 1 => get text\r\n\r\n//Get opening Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening Book Balance :\" => get words after \"Opening Book Balance :\" => take words 2 => take last words 1 => get decimal\r\n//Get closing Balance\r\n$closingBalance = get line containing \"Closing Book Balance :\" => get words after \"Closing Book Balance :\" => take words 2 => take last words 1 => get decimal\r\n\r\n//Get statementperiod\r\ngo to page 1\r\n$PeriodFrom = get line containing \"Statement Period : BETWEEN\" => get words after \"Statement Period : BETWEEN\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get line containing \"Statement Period : BETWEEN\" => get words after \"Statement Period : BETWEEN\" => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"S.No. Posting Date Narration Value Date Debit Credit Running Balance\" => bottom => get line below\r\n// Get end of table\r\n@transactionsBottom = get line containing \"End of Report\" => top => get line above\r\n\r\nignore header above 422\r\nignore footer below 30\r\n\r\n//delete extra lines/texts\r\ndelete all lines containing \"S.No. Posting Date Narration Value Date\"\r\ndelete all lines containing \"End of Report\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 80 170 320 425 560 700 780 => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10897,'BarclaysNet_Bank','$source = \"BarclaysNet_Bank\"\r\n$periodBufferDays = 30\r\n// Extract Account Number\r\n$accountNumber = get line containing \"IBAN\" => top => get line above => take words 1 => get text\r\n\r\n// Extract Account Name\r\n$accountName = get line containing \"IBAN\" => top => get line above => take words 4 => take last words 3 => get text\r\n\r\n// Get Periods\r\n$periodFrom = get line containing \"Statement Date: Absolute From:\" => get words after \"Absolute From:\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo   = get line containing \"Statement Date: Absolute From:\" => get words after \"Absolute From:\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Opening & Closing Balances\r\n$openingBalance = get line containing \"Balance Brought Forward\" => get words after \"Balance Brought Forward\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Balance Carried Forward\" => get words after \"Balance Carried Forward\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line containing \"Balance Brought Forward\" => bottom => get line below\r\n@transactionsbottom = get last line containing \"Balance Carried Forward\" => top => get line above\r\n\r\ndelete all lines containing \"Balance Brought Forward\"\r\ndelete all lines containing \"Balance Carried Forward\"\r\n\r\nignore header above 792\r\nignore footer below 20\r\n\r\n$transactions = get multi page table center aligned @transactionstop @transactionsbottom 5.0 35 78 204 290 340 405 468 => describe table false \"Date[dd/MM/yyyy]\" Details TransactionType #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10898,'Synchrony_Bank','$source = \"Synchrony_Bank\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 28\r\nset negative marker \"($\"\r\n\r\n// Get account name\r\n$accountName = get text in box page.top 0 0 page.right => take words 4 => take last words 2 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line starting \"Account Number :\" => get words after \"Account Number :\" => get text\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line starting \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\r\n$closingBalance = get line starting \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodTo = get line starting \"Statement Closing Date:\" => get words after \"Statement Closing Date:\" => take words 1 => get date \"M/d/yyyy\"\r\n$periodFrom = get line starting \"Tran Date Post Date\" => bottom => get line below => take words 1 => get date \"M/d/yyyy\"\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Tran Date Post Date\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 5\r\n@date1Left = get words before @header \"Post\" => take last words 1 => right => add 5\r\n@typeLeft = get words after @header \"Post Date\" => take words 1 => left => subtract 5\r\n@detailsLeft = take last words @header 2 => take words 1 => left => subtract 5\r\n@amountLeft = take last words @header 1 => take words 1 => left => subtract 20\r\n@amountRight = take last words @header 1 => bottom => get line below => take last words 1 => right => add 10\r\n\r\n// Get start and end of transaction table\r\ngo to page 1\r\n@transactionTop = get line starting \"Tran Date Post Date\" => bottom => get line below\r\n@transactionBottom = get last line containing \"Totals Year-to-Date\" => top => get line above\r\n\r\n// Delete extra lines from transactions\r\ngo to page 1\r\ndelete all lines starting \"Tran Date Post Date\"\r\ndelete all lines starting \"FEES\"\r\ndelete all lines starting \"TOTAL\"\r\ndelete all lines starting \"INTEREST CHARGED\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @date1Left @typeLeft @detailsLeft @amountLeft @amountRight => describe table false - \"*Date[M/d/yyyy]\" Details TransactionType #Credit','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10899,'BancOfCalifornia','$source = \"BancOfCalifornia\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get account name\r\n@accountNameTop = get line containing \"Banc Of California\" => bottom\r\n$accountName = get text in box @accountNameTop 0 page.middleX page.right => take words 8 => get text\r\n\r\n// Get account number\r\n$accountNumber = get line starting \"Account number\" => get words after \"Account number\" => take words 1 => get text\r\n\r\n//Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Beginning balance\" => get words after \"Beginning balance\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Ending balance\" => get words after \"Ending balance\" => take last words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line starting \"Last statement:\" => get words after \"Last statement:\" => take words 3 => get date \"MMMM d,yyyy\"\r\n$periodTo = get line starting \"This statement:\" => get words after \"This statement:\" => take words 3 => get date \"MMMM d,yyyy\"\r\n\r\n// Header & column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Description\"\r\n\r\n// Column coordinates\r\n@dateLeft =  take words @header 1 => left => subtract 5\r\n@detailsLeft =  get words after @header \"Date\" => take words 1 => left => subtract 10\r\n@amountLeft =  take last words @header 1 => take words 1 => left => subtract 25\r\n@amountRight =  take last words @header 1 => take words 1 => right => add 30\r\n\r\n// Get start & end of debits table\r\ngo to page 1\r\n@debitsTop = get line starting \"DEBITS\" => if not found then blank => bottom => get line below\r\n@debitsBottom = get last line starting \"Date Description Subtractions\" => if not found then blank => bottom => get break below => get line at\r\n\r\n// Get start and end of credit table\r\n@creditsTop = get line starting \"CREDITS\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get last line starting \"Date Description Additions\" => if not found then blank => bottom => get break below => get line at\r\n\r\n// Discard header and footer\r\ngo to page 2\r\nget line starting \"Date Description\" => top => ignore header above\r\nignore footer below 90\r\n\r\ndelete all lines starting \"Date Description Subtractions\"\r\ndelete all lines starting \"Date Description Additions\"\r\ndelete all lines starting \"CREDITS\"\r\ndelete all lines starting \"TRANSBORDER\"\r\ndelete all lines starting \"CORP\"\r\n\r\n@debits = get multi page table @debitsTop @debitsBottom @dateLeft @detailsLeft @amountLeft @amountRight => describe table false \"Date[MM-dd]\" Details *#Debit\r\n@credits = get multi page table @creditsTop @creditsBottom @dateLeft @detailsLeft @amountLeft @amountRight => describe table false \"Date[MM-dd]\" Details *#Credit\r\n\r\ngo to page 1\r\n//Get start and end check\r\n@checksTop = get line starting \"CHECKS\" => if not found then blank => bottom => get line below\r\n@checksBottom = get line starting \"DEBITS\" => if not found then blank => top => get line above\r\ndelete all lines starting \"CHECKS\"\r\ndelete all lines starting \"DEBITS\"\r\ndelete all lines starting \"Number Date Amount\"\r\n\r\n@ChecksL = get multi page table @checksTop @checksBottom 35 160 240 315 => describe table false ChequeNumber \"Date[MM-dd]\"  #Debit\r\ndelete all lines containing \"Skip in check sequence\"\r\n@ChecksM = get multi page table @checksTop @checksBottom 320 370 470 525 => describe table false ChequeNumber \"Date[MM-dd]\"  #Debit\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @debits @ChecksL @ChecksM @credits','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10900,'CapeCodFive_Bank','$source = \"CapeCodFive_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 7\r\nset negative marker \"-\"\r\n\r\ngo to page 1\r\n//Get Account name & Account number\r\n@accountBottom = get line containing \"Account Number\" => top\r\n$accountname = get text in box page.top @accountBottom 0 page.middleX => take words 3 => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Ending\" => take words 1 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\r\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\r\n\r\n// Get opening balance\r\n$openingBalance = get line containing \"Beginning Balance\" => get words after \"Beginning Balance\" => take words 1 => get decimal\r\n\r\n// Get closing balance\r\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// transactions top & bottom\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Description Debit\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get line containing \"CHECKS IN NUMBER ORDER\" => if not found then blank => top => get line above\r\n\r\n// Discard unwanted text\r\ndelete all lines starting \"Date Description Debit\"\r\ndelete all lines containing \"(Continued)\"\r\ndelete all lines containing \"DAILY ACTIVITY\"\r\nignore header above 590\r\nignore footer below 28\r\n\r\n// Get transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 60 245 317 400 500 => describe table false \"*Date[M/dd]\" Details #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10901,'Vancity_MultiAcct_Bank','$source = \"Vancity_MultiAcct_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n$periodBufferDays = 28\r\n\r\n// Remove extra text\r\ndelete tiny words\r\ndelete all lines containing \"TOLL-FREE\"\r\ndelete all lines containing \"vancity.com\"\r\n\r\n// Removing left vertical text\r\ngo to page 1\r\ndelete text in box on every page page.top page.bottom page.left 50\r\n\r\n// Account Details\r\ngo to page 1\r\n$accountName = get text in box 658 620 110 page.middleX => get text\r\n$accountNumber = get line starting \"BUSINESS PRIME PRO\" => get words after \"PRIME\" => take words 2 => get text\r\n\r\n// Statement Period\r\n$periodFrom = get line starting \"STATEMENT PERIOD:\" => get words after \"PERIOD:\" => get words before \"to\" => get date \"dd MMM yyyy\"\r\n$periodTo = get line starting \"STATEMENT PERIOD:\" => get words after \"to\" => get date \"dd MMM yyyy\"\r\n\r\n// Get Opening Balance\r\n$openingBalance = get line starting \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\r\n\r\n// Get Closing Balance\r\n@columnHeader = get line starting \"DATE DESCRIPTION WITHDRAWALS\" => get text\r\n@balance_left = get line containing @columnHeader => take last words 1 => left => subtract 5\r\n@balance_right = get line containing @columnHeader => take last words 1 => right => add 5\r\n@balance_bottom = get line containing @columnHeader => take last words 1 => top\r\n$closingBalance = get text in box page.top @balance_bottom @balance_left @balance_right => take last words 1 => get decimal\r\n\r\n// Get start of table\r\n@transactionsTop = get line containing \"DATE DESCRIPTION WITHDRAWALS\" => top => get line above\r\ndelete all lines starting \"OPENING BALANCE\"\r\n\r\n// Get end of table\r\n@transactionsBottom = get last line starting \"Please review your statement and report\" => top => get line above\r\n\r\n// Discard page header\r\ngo to page 1\r\n//get last lines starting \"DATE DESCRIPTION WITHDRAWALS\" => bottom => ignore header above\r\n\r\n$lastSummaryBottom = get line starting \"STATEMENT PERIOD:\" => if not found then blank => top\r\n$delLastSummary = delete text in box page.top $lastSummaryBottom 0 page.middleX => get text\r\n\r\ngo to page 1\r\n@lastFt_top = get last line starting \"Please review your statement and report\" => if not found then blank => bottom\r\n$lastFt_del = delete text in box @lastFt_top 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@Text_top1 = get line below page.top => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => get text\r\n@Text_top2 = get line below page.top => bottom => get line below => bottom => get line below => bottom => get line below => bottom => get line below => get text\r\n@Text_top3 = get line below page.top => bottom => get line below => bottom => get line below => bottom => get line below => get text\r\n@Text_top4 = get line below page.top => bottom => get line below => bottom => get line below => get text\r\n@Text_top5 = get line below page.top => bottom => get line below => get text\r\n@Text_top6 = get line below page.top => get text\r\n@Text_top7 = get line below page.top => top => get line above => get text\r\n@Text_top8 = get line containing \"INTEREST SUMMARY:\" => if not found then blank => bottom => get line below => get text\r\n\r\n// Discard extra text\r\ndelete all lines starting \"SHARES\"\r\ndelete all lines starting \"OPENING BALANCE\"\r\ndelete all lines starting \"Note: Shares\"\r\ndelete all lines starting \"CLASS\"\r\ndelete all lines starting \"Please review your statement and report\"\r\ndelete all lines starting \"DATE DESCRIPTION WITHDRAWALS\"\r\ndelete all lines starting \"BORROWING\"\r\ndelete all lines starting \"LOANS\"\r\ndelete all lines containing \"LINE OF CREDIT DETAILS\"\r\ndelete all lines starting \"APPROVED LIMIT:\"\r\ndelete all lines starting \"INTEREST SUMMARY:\"\r\ndelete all lines starting \"MINIMUM PAYMENT:\"\r\ndelete all lines starting \"TOTAL DUE:\"\r\ndelete all lines starting \"TOTAL INTEREST PAID FOR\"\r\ndelete all lines containing \"(CONT.)\"\r\ndelete all lines starting @Text_top1\r\ndelete all lines starting @Text_top2\r\ndelete all lines starting @Text_top3\r\ndelete all lines starting @Text_top4\r\ndelete all lines starting @Text_top5\r\ndelete all lines starting @Text_top6\r\ndelete all lines starting @Text_top7\r\ndelete all lines starting @Text_top8\r\n\r\n// Discard page footer\r\nignore footer below 50\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 355 440 505 570 => describe table false Details **#Debit **#Credit','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10902,'Thread_Bank','$source = \"Thread_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get account name\r\n@accountText = get line containing \"Account\"\r\n@accountLeft = take words @accountText 1 => left\r\n$accountName = get text in box page.top 0 0 @accountLeft => take words 3 => get text\r\n\r\n// Get account number\r\n$accountNumber = get text in box page.top 0 @accountLeft page.middleX => take words 2 => take last words 1 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line starting \"Statement Period\" => bottom => get line below => get words before \"-\" => take last words 3 => get date \"MMM dd yyyy\"\r\n$periodTo = get line starting \"Statement Period\" => bottom => get line below => get words after \"-\" => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\r\n$closingBalance = get last line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"DATE DESCRIPTION WITHDRAWALS\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 5\r\n@detailsLeft = take words @header 2 => take last words 1 => left => subtract 5\r\n@debitLeft = take words @header 3 => take last words 1 => left => subtract 5\r\n@creditLeft = get words after @header \"WITHDRAWALS / DEBIT\" => take words 1 => left => subtract 5\r\n@balanceLeft = get words after @header \"DEPOSITS / CREDIT\" => take words 1 => left => subtract 10\r\n@balanceRight = take last words @header 1 => take words 1 => right => add 10\r\n\r\n// Get start and end of transaction table\r\ngo to page 1\r\n@transactionTop = get line starting \"DATE DESCRIPTION WITHDRAWALS\" => bottom => get line below\r\n@transactionBottom = get last line containing \"Closing Balance\" => top => get line above\r\n\r\n// Discard header and footer\r\ngo to page 1\r\nget last line starting \"DATE DESCRIPTION WITHDRAWALS\" => top => ignore header above\r\nignore footer below 10\r\n\r\n// Delete extra lines from transactions\r\ngo to page 1\r\nget line starting \"DATE DESCRIPTION WITHDRAWALS\" => bottom\r\n@totalTop = get line starting \"Total\" => if not found then blank => bottom\r\n@deleteFooter = delete text in box @totalTop 0 0 page.right => get text\r\n\r\ndelete all lines starting \"Total\"\r\ndelete all lines containing \"Opening Balance\"\r\ndelete all lines starting \"DATE DESCRIPTION WITHDRAWALS\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @detailsLeft @debitLeft @creditLeft @balanceLeft @balanceRight => describe table false \"*Date[MMM dd]\" Details #Debit #Credit #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10903,'CIMB_ISLAMIC','$source = \"CIMB_ISLAMIC\"\r\n$periodBufferDays = 31\r\n\r\n$accountName = get text in box 746 728 page.left page.middleX => take words 3 => get text\r\n$accountNumber = get line containing \"Account No\" => take last words 1 => get text\r\n\r\n//Get Periods\r\n$periodFrom = get line starting \"OPENING BALANCE\" => bottom => get line below => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 4 => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\n//Opening_Closing BALANCE\r\ngo to page 1\r\n$openingBalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@deletetablestop = get line containing \"Important Notice / Notis Penting\" => top\r\n@deletetablesbottom = get line containing \"at www.cimbbank.com.my or www.cimbislamic.com.my\" => bottom\r\ndelete text in box @deletetablestop @deletetablesbottom page.left page.right\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"OPENING BALANCE\" => bottom => get line below\r\n@transactionsBottom = get line containing \"CLOSING BALANCE\" => top => get line above\r\n\r\n\r\ndelete all lines containing \"OPENING BALANCE\"\r\ndelete all lines containing \"CLOSING BALANCE\"\r\ndelete all lines containing \"Statement Date\"\r\ndelete all lines containing \"CONTINUE NEXT PAGE\"\r\n\r\n\r\nignore header above 670\r\nignore footer below 46\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 80 249 315 380 440 502 555 => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #Debit #Credit - #Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10904,'Banco_Popular_Spanish','$source = \"Banco_Popular_Spanish\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\nset culture \"es-US\"\r\n\r\n//delete words to fetch PeriodFrom and PeriodTo\r\n$dlt = get line containing \"Desde\" => bottom => get line below  => take last words 5\r\n$dltleft = take words $dlt 3 => get words before \"de\" => right => add 1\r\n$dltright = take words $dlt 3 => get words after \"de\" => left => subtract 1\r\ndelete text in box on every page page.top page.bottom $dltleft $dltright\r\n\r\n$dltleft1 = take last words $dlt 3 => get words before \"de\" => right => add 1\r\n$dltright1 = take last words $dlt 3 => get words after \"de\" => left => subtract 1\r\ndelete text in box on every page page.top page.bottom $dltleft1 $dltright1\r\n\r\n$periodfrom = get line containing \"Desde\" => bottom => get line below  => take last words 3 => get date \"d MMMM yyyy\"\r\n$periodto = get line containing \"Hasta:\" => bottom => get line below  => take last words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get account number\r\n$accountnumber = get line containing \"Número de Cuenta\" => bottom => get line below => take last words 1 => get text\r\n$accountname = get line containing \"Número de Cuenta\" => bottom => get line below => take last words 1 => get text\r\n\r\n// Get opening and closing balance\r\n$openingbalance = get line containing \"Balance Inicial\" => get words after \"Inicial\" => take words 1 => get decimal\r\n$closingbalance = get line containing \"Balance Final\" => get words after \"Final\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get start & end of Cargo table\r\n@cargoDebittop = get line containing \"Créditos y Débitos Miscelaneos\" => if not found then blank => bottom => get line below\r\n@cargoDebitBottom = get line starting \"Balance Final\" => if not found then blank => top => get line above\r\n\r\n@cargo = get multi page table @cargoDebittop @cargoDebitBottom 43 155 380 426 => describe table false Details - #Debit\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@DepositsTop = get line starting \"Fecha Referencia Descripción\" => if not found then blank => bottom => get line below\r\n@DepositsBottom = get line starting \"Retiros\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Fecha Referencia\"\r\ndelete all lines containing \"Total de otros depósitos\"\r\ndelete all lines containing \"Total de depósitos\"\r\ndelete all lines containing \"Total de hojas\"\r\ndelete all lines containing \"Otros Créditos\"\r\n\r\n//delete extra top and bottom in pdf\r\nignore header above 603\r\nignore footer below 43\r\n@Deposits = get multi page table @DepositsTop @DepositsBottom 47 113 170 380 430 => describe table false \"*Date[MM-d]\" TransactionType Details #Credit\r\n\r\n// Get start & end of cheques table\r\ngo to page 1\r\n//delete extra words in right side of page\r\ndelete text in box on every page page.top page.bottom 432 700\r\n\r\n@chequeTop = get line starting \"Cheques Pagados\" => if not found then blank => bottom => get line below\r\n@chequeBottom = get line starting \"Otros Débitos\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Cheques Pagados\"\r\ndelete all lines starting \"Cheque Cheque \"\r\ndelete all lines starting \"Número de Fecha\"\r\ndelete all lines starting \"Retiros\"\r\n\r\n@chequeLeft = get multi page table @chequeTop @chequeBottom 47 92 123 176 227 => describe table false ChequeNumber \"Date[MM-d]\" Details *#Debit\r\n@chequeMiddle = get multi page table @chequeTop @chequeBottom 245 290 322 373 425 => describe table false ChequeNumber \"Date[MM-d]\" Details *#Debit\r\n\r\ngo to page 1\r\n// Get start & end of Debit table\r\n@DebitTop = get line containing \"Otros Débitos\" => if not found then blank => bottom => get line below\r\n@DebitBottom = get line containing \"Total de otros\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Otros Débitos\"\r\ndelete all lines containing \"Fecha de\"\r\ndelete all lines containing \"Total de otros retiros\"\r\ndelete all lines containing \"Total de retiros\"\r\ndelete all lines containing \"Descripción\"\r\n\r\n@debits = get multi page table @DebitTop @DebitBottom 47 113 170 380 430 => describe table false \"*Date[MM-d]\" TransactionType Details #Debit\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@otherDepositsTop = get line starting \"Efectividad\" => if not found then blank => bottom => get line below\r\n@otherDepositsBottom = get line starting \"Total de créditos\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Descripción\"\r\ndelete all lines containing \"Efectividad\"\r\ndelete all lines containing \"Total de créditos\"\r\n\r\n@otherDeposits = get multi page table @otherDepositsTop @otherDepositsBottom 47 113 170 380 430 => describe table false \"*Date[MM-d]\" TransactionType Details #Credit\r\n\r\n//Read all Tables Combined\r\n$transactions = combine described tables @Deposits @chequeLeft @chequeMiddle @debits @cargo @otherDeposits','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10905,'Emirates_NBD','$source = \"Emirates_NBD\"\r\n\r\n//Get Periods\r\ngo to page 1\r\ndelete text in box page.top 713 200 page.right\r\n\r\n$periodFromtext = get line containing \"From\" => get words after \"From\"\r\n$periodFrom = take words $periodFromtext  1 => get date \"d/MM/yyyy\"\r\n$periodTo = get line starting \"From\" => get words after \"to\"  => take last words 1 => get date \"d/MM/yyyy\"\r\n\r\n//Get Accounts\r\ngo to page 1\r\n$accountNumber = get line containing \"Account N\" => get words after \"Account N\" => take words 1 => get text\r\n$accountname = get line containing \"Account N\" => get words after \"Account N\" => take words 1 => get text\r\n\r\n//Get Balances\r\n$openingbalance = get line containing \"BROUGHT FORWARD\" => take last words 1 => get decimal\r\n$closingbalance = get last line containing \"CARRIED FORWARD\" => take last words 1 => get decimal\r\n\r\n//Transaction Table starts here\r\ngo to page 1\r\n\r\n$Date_left = get line containing \"BROUGHT FORWARD\" => get words before \"BROUGHT\" => left => subtract 20\r\n$Date_right = get line containing \"BROUGHT FORWARD\" => get words before \"BROUGHT \" => right => add 8\r\n$Description_right = get line containing \"Date Description Debits\" => get words after \"Description\" => left => subtract 50\r\n$Paidout_right = get line containing \"Date Description Debits\" => get words after \"Debits\" => left => subtract 30\r\n$Paidin_right = get line containing \"Date Description Debits\" => get words before \"Balance\" => right => add 30\r\n$Balance_right = get line containing \"Date Description Debits\" => get words after \"Credits\" => right => add 35\r\n\r\ngo to page 1\r\n$transactionsTop = get line containing \"BROUGHT FORWARD\" => bottom => get line below\r\n$transactionsBottom = get last line starting \"CARRIED FORWARD\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"BROUGHT FORWARD\"\r\ndelete all lines containing \"CARRIED FORWARD\"\r\n//delete extra words in footer and header of page\r\nignore footer below 217\r\nignore header above 820\r\n\r\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Date_right $Description_right $Paidout_right $Paidin_right $Balance_right => describe table false \"Date[dMMMyy]\" Details #Debit #Credit **#Balance','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10906,'Lloyds_Commercial_Bank_Cardv2','$source = \"Lloyds_Commercial_Bank_Cardv2\"\r\n\r\n$features = \"CREDIT_CARD\"\r\nset negative marker \"CR\"\r\n\r\n@accountDetailsBottom = get line containing \"Statement date:\" => top\r\n$accountName = get text in box page.top @accountDetailsBottom 0 page.middleX => take words 2 => get text\r\n\r\n$accountNumber = get line containing \"Card ending\" => get words after \"Card ending\" => get text\r\n\r\n$openingBalance = get line starting \"Balance carried forward\" => get words after \"Balance carried forward\" => get decimal\r\n\r\n$closingBalance = get line starting \"Statement balance\" => get words after \"Statement balance\" => get decimal\r\n\r\n@transactionsTop = get line containing \"Date Description\" => bottom => get line below => bottom => get line below\r\n\r\n@periodFromTop = top @transactionsTop\r\n$periodFrom = get text in box @periodFromTop 0 0 105 => take words 1 => get date \"dMMyyyy\"\r\n\r\n@transactionsBottom = get last line starting \"Page\" => top => get line above\r\n\r\n@transactionsBottomLastLine = bottom @transactionsBottom\r\n$periodTo = get text in box page.top @transactionsBottomLastLine 0 105 => take last words 1 => get date \"dMMyyyy\"\r\n\r\ndelete all lines starting \"Page\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 105 385 475 580 => describe table false \"*Date[dMMyyyy]\" TransactionType Details #Credit','2026-05-21 09:43:20',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10907,'Kroo_Bank','$source = \"Kroo_Bank\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n@periodText = get line starting \"Account transactions\"\r\n@periodTop = take words @periodText 1 => bottom\r\n@periodBottom = get line starting \"Date Description\" => top\r\n\r\n$periodFrom = get text in box @periodTop @periodBottom 0 page.middleX  => take words 3 => get date \"d MMM yyyy\"\r\n$periodTo = get text in box @periodTop @periodBottom 0 page.middleX  => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take words 1 => get decimal\r\n$closingBalance = get last line containing \"Closing balance\" => get words after \"Closing balance\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Description\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = get words after @header \"Date\" => take words 1 => left => subtract 5\r\n@debitLeft = get words after @header \"Description\" => take words 1 => left => subtract 30\r\n@debitRight = get words after @header \"Description\" => take words 1 => right => add 5\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Description\" => bottom => get line below\r\n@transactionBottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Date Description\" => top => ignore header above\r\nget last line starting \"Kroo Bank\" => top => ignore footer below\r\nignore footer below 150\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Account transactions\"\r\ndelete all lines starting \"If something\"\r\ndelete all lines containing \"Opening balance\"\r\ndelete all lines containing \"Closing balance\"\r\ndelete all lines starting \"Date Description\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionTop @transactionBottom 5 @dateLeft @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"Date[d MMM yyyy]\" Details #Debit #Credit #Balance','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10908,'Synergy_CreditUnion','$source = \"Synergy_CreditUnion\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\nset negative marker \"-\"\r\n\r\n// Get account details\r\n@accountBottom = get line starting \"Date Description Debits\" => top => get line above => top\r\n$accountName = get text in box page.top @accountBottom 0 page.middleX => take words 2 => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n\r\n// Delete account address text from the header section\r\n@accountRight = get line containing \"Period Beginning\" => get words before \"Beginning\" => take last words 1 => left\r\n@deleteAccountNameText = delete text in box page.top @accountBottom 0 @accountRight => get text\r\n\r\ngo to page 1\r\n// Get statement period (From / To)\r\n$periodFrom = get line containing \"Period Beginning\" => get words after \"Beginning\" => get date \"MMM dd yyyy\"\r\n@periodText = get line containing \"Period Beginning\" => get words after \"Period\"\r\n@periodLeft = take words @periodText 1 => right => add 3\r\n$periodTop = take words @periodText 1 => bottom\r\n$periodTo = get text in box $periodTop 0 @periodLeft page.right => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n// Get opening and closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Balance Forward\" => take last words 1 => get decimal\r\n$closingBalance = 0\r\n\r\ngo to page 1\r\n@InterestRateLastSummaryTop = get last line starting \"Interest Rate Summary\" => top\r\n@InterestRateLastSummaryBottom = get line starting \"If this statement\" => top\r\n@deleteInterestRateLastSummary = delete text in box @InterestRateLastSummaryTop @InterestRateLastSummaryBottom 0 page.right => get text\r\n\r\n// Get the start of the transaction\r\ngo to page 1\r\n@transactionsTop = get line containing \"No. of Enclosures\" => bottom => get line below => bottom => get line below\r\n\r\n// Discard header\r\nignore header above 710\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines containing \"Lost or Stolen\"\r\ndelete all lines starting \"Total Debits\"\r\ndelete all lines starting \"Total Credits\"\r\ndelete all lines starting \"There is no activity\"\r\ndelete all lines starting \"Interest\"\r\ndelete all lines starting \"Interest Principal\"\r\ndelete all lines containing \"credit union inquiries\"\r\ndelete all lines containing \"amalgamated as\"\r\ndelete all lines containing \"deemed to refer\"\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section\r\n@InterestRateSummaryTop = get line containing \"Interest Rate Summary\" => top\r\n@InterestRateSummaryBottom = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary = delete text in box @InterestRateSummaryTop @InterestRateSummaryBottom 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 1\r\n@InterestRateSummaryTop1 = get line containing \"Interest Rate Summary\" => top\r\n@InterestRateSummaryBottom1 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary1 = delete text in box @InterestRateSummaryTop1 @InterestRateSummaryBottom1 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 2\r\n@InterestRateSummaryTop2 = get line containing \"Interest Rate Summary\" => top\r\n@InterestRateSummaryBottom2 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary2 = delete text in box @InterestRateSummaryTop2 @InterestRateSummaryBottom2 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 3\r\n@InterestRateSummaryTop3 = get line containing \"Interest Rate Summary\" => top\r\n@InterestRateSummaryBottom3 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary3 = delete text in box @InterestRateSummaryTop3 @InterestRateSummaryBottom3 0 page.right => get text\r\n\r\ndelete all lines starting \"Interest Rate Summary\"\r\ndelete all lines starting \"Unauthorized\"\r\n\r\n//Get the end of the transaction\r\n@transactionsBottom = get last line starting \"If this statement\" => top => get line above\r\n\r\n// Delete non-transaction lines\r\ndelete all lines starting \"Deposit Account Interest\"\r\ndelete all lines starting \"Date Rate Date\"\r\ndelete all lines starting \"Servus and connectFirst\"\r\ndelete all lines starting \"If this statement\"\r\ndelete all lines containing \"Account Number:\"\r\ndelete all lines containing \"Page:\"\r\ndelete all lines starting \"Interest Paid YTD\"\r\ndelete all lines starting \"Interest Payments\"\r\ndelete all lines starting \"Principal Payments\"\r\ndelete all lines starting \"Interest Rate Summary\"\r\ndelete all lines starting \"There is no activity for this account\"\r\n\r\ngo to page 1\r\n// Remove Credit Union inquiries section\r\n@creditUnionInquiriesTop = get line starting \"For all credit union inquiries\" => if not found then blank => bottom\r\n$deleteCUInquiriesBox = delete text in box @creditUnionInquiriesTop 0 0 page.right => get text\r\ndelete all lines starting \"For all credit union inquiries\"\r\ndelete all lines containing \"Balance Forward\"\r\ndelete all lines starting \"Date Description\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 315 420 500 => describe table false Details *#Debit *#Credit','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10909,'Flagstar','$source = \"Flagstar\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n@SummaryTop = get line starting \"Previous Balance as of\" => top\r\n@SummaryBottom = get line starting \"Ending Balance as of\" => bottom\r\n@Summary = get text in box @SummaryTop @SummaryBottom 0 page.right\r\n\r\n$PeriodFrom = get words after @Summary \"Previous Balance as of\" => take words 3 => get date \"MMMM d yyyy\"\r\n$PeriodTo = get words after @Summary \"Ending Balance as of\" => take words 3 => get date \"MMMM d yyyy\"\r\n\r\n$OpeningBalance = get words after @Summary \"Previous Balance as of\" => skip words 3 => take words 1 => get decimal\r\n$ClosingBalance = get words after @Summary \"Ending Balance as of\" => skip words 3 => take words 1 => get decimal\r\n\r\n$AccountName = get text in box page.top page.middleY page.left page.middleX => take words 3 => get text\r\n$AccountNumber = get line containing \"Account:\" => get words after \"Account:\" => take words 1 => get text\r\n\r\n@ChecksTop = get line starting \"Checks by Serial Number\" => if not found then blank => bottom => get line below\r\n@ChecksBottom = get last line starting \"Daily Balances\" => top => get line above\r\n$Checks = get multi page table @ChecksTop @ChecksBottom 30 90 150 250 => describe table false \"Date[MMMd]\" #ChequeNumber *#Debit\r\n\r\ngo to page 1\r\n@DeleteChecksTop = get line starting \"Checks by Serial Number\" => top\r\n@DeleteChecksBottom = get last line starting \"Daily Balances\" => top\r\n$DeleteChecks = delete text in box @DeleteChecksTop @DeleteChecksBottom 0 page.right => get text\r\n\r\ngo to page 1\r\n@CreditsTop = get line starting \"Deposits and Other Credits\" => if not found then blank => bottom => get line below\r\n@CreditsBottom = get last line starting \"Deposits and Other Credits\" => if not found then blank => bottom => get break below => get line at\r\n\r\n@DebitsTop = get line starting \"Withdrawals and Other Debits\" => if not found then blank => bottom => get line below\r\n//@DebitsBottom = get last line starting \"Account:\" => if not found then blank => bottom => get break below => get line at\r\n@DebitsBottom = get last line starting \"Daily Balances\" => top => get line above\r\n\r\nget line containing \"Account:\" => bottom => ignore header above\r\nignore footer below 90\r\n\r\n$Credits = get multi page table @CreditsTop @CreditsBottom 30 80 490 600 => describe table false \"Date[MMMd]\" Details *#Credit\r\n\r\n$Debits = get multi page table @DebitsTop @DebitsBottom 30 80 490 600 => describe table false \"Date[MMMd]\" Details *#Debit\r\n\r\n$transactions = combine described tables $Credits $Debits $Checks','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10910,'Carrollton_Bank','$source = \"Carrollton_Bank\"\r\n$periodBufferDays = 28\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n// Get account number/name\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\n$accountName = get line containing \"Account Owner(s):\" => get words after \"Account Owner(s):\" => take words 3 => get text\r\n// Get periods\r\ngo to page 1\r\n$periodFrom = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get last line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 2 => take last words 1 => get decimal\r\n$closingBalance = get last line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 2 => take last words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Description Deposits Withdrawals Balance\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 3\r\n@detailLeft = get words after @header \"Date\" => take words 1 => left => subtract 2\r\n@debitLeft = get words after @header \"Description\" => take words 1 => left => subtract 28\r\n@debitRight = get words after @header \"Description\" => take words 1 => right => add 5\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 10\r\n@deleteWords = delete text in box on every page page.top 0 0 @dateLeft\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Description Deposits Withdrawals Balance\" => bottom => get line below\r\n@transactionBottom = get last line containing \"ENDING BALANCE\" => top => get line above\r\n\r\n// Discard header and footer\r\nIgnore header above 670\r\nIgnore footer below 25\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines containing \"BEGINNING BALANCE\"\r\ndelete all lines containing \"Date Description Deposits Withdrawals Balance\"\r\ndelete all lines containing \"ENDING BALANCE\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"*Date[MMM dd]\" Details #Credit #Debit #Balance','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10911,'First_Saving_Bank','$source = \"First_Saving_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n//delete vertical text on left and right side of page\r\ndelete text in box on every page page.top page.bottom 1 49\r\n\r\n// Get account name\r\n$accountName = get line containing \"Account Number\" => get words after \"Account Number\" => take last words 1 => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take last words 1 => get text\r\n\r\n//Get Periods, Opening and Closing Balance\r\n$accTop = get line containing \"Balance Summary\" => bottom => get line below\r\n$periodFrom = get words after $accTop \"as of\" => take words 1 => get date \"MM/d/yyyy\"\r\n$openingBalance = get words after $accTop \"as of\" => take words 2 => skip words 1 => get decimal\r\n\r\n$periodToText = get line containing \"Ending Balance\" => get words after \"Ending Balance as of\"\r\n$periodTo = take words $periodToText 1 => get date \"MM/d/yyyy\"\r\n$closingBalance = take words $periodToText 2 => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get start & end of ATM/POS table\r\n@atmTop = get line containing \"ATM/POS TRANSACTION\" => bottom => get line below\r\n@atmBottom = get line containing \"CHECKS PAID\" => if not found then blank => top => get line above\r\ndelete all lines containing \"Date Description\"\r\nignore header above 683\r\nignore footer below 35\r\n\r\n@atm = get multi page table @atmTop @atmBottom 52 93 450 480 565 => describe table false \"*Date[MMM d]\" Details #Credit #Debit\r\n\r\n// Get start & end of cheques table\r\ngo to page 1\r\n@chequeTop = get line starting \"Date Check No.\" => if not found then blank => bottom => get line below\r\n@chequeBottom = get line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => top => get line above\r\n\r\nignore header above 683\r\nignore footer below 35\r\n\r\ndelete all lines containing \"Indicates a Skip\"\r\ndelete all lines starting \"Date Check No\"\r\ndelete all lines starting \"CHECKS PAID\"\r\n\r\n@chequeLeft = get multi page table @chequeTop @chequeBottom 52 92 160 220 => describe table false  \"Date[MMM d]\" ChequeNumber *#Debit\r\n@chequeMiddle = get multi page table @chequeTop @chequeBottom 227 259 288 390 => describe table false \"Date[MMM d]\" ChequeNumber *#Debit\r\n@chequeRight = get multi page table @chequeTop @chequeBottom 397 433 467 565 => describe table false \"Date[MMM d]\" ChequeNumber *#Debit\r\n\r\ngo to page 1\r\n// Get start & end of Deposits table\r\n@DepositsTop = get line starting \"DEPOSITS AND OTHER CREDIT\" => if not found then blank => bottom => get line below\r\n@DepositsBottom = get line starting \"DEBITS AND OTHER WITHDRAWALS\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Date Description\"\r\nignore header above 683\r\nignore footer below 35\r\n@Deposits = get multi page table @DepositsTop @DepositsBottom 52 93 515 565 => describe table false \"*Date[MMM d]\" Details #Credit\r\n\r\ngo to page 1\r\n// Get start & end of Debit table\r\n@DebitTop = get line starting \"DEBITS AND OTHER WITHDRAWALS\" => if not found then blank => bottom => get line below\r\n@DebitBottom = get line starting \"ATM/POS TRANSACTION\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Date Description\"\r\n\r\n@debits = get multi page table @DebitTop @DebitBottom 52 93 515 565 => describe table false \"*Date[MMM d]\" Details #Debit\r\n\r\n//Combine all Tables here\r\n$transactions = combine described tables @Deposits @debits @atm @chequeLeft @chequeMiddle @chequeRight','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10912,'PremierValleyBank','$source = \"PremierValleyBank\"\r\n\r\ndelete tiny words\r\ndelete rotated words\r\ndelete white words\r\n\r\n@TEXTBOXBottom = get line containing \"Summary of Accounts\" => top\r\n// Get account name\r\n$accountName = get text in box 700 @TEXTBOXBottom 0 348 => take words 3 => get text\r\n$accountNumber = get line containing \"Account Number\" => bottom => get line below => get words before \"$\" => take last words 1 => get text\r\ngo to page 1\r\ndelete all lines ending \"Ending Balance\"\r\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\r\n@TEXTBOXBottom1 = get line containing \"Ending Balance\" => bottom\r\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom1 0 350\r\n\r\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\r\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\r\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\r\n\r\n//Get Credits table\r\ngo to page 1\r\n// Get start & end of credits table\r\n@creditsTop = get line starting \"Other Credits\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get line starting \"Checks Cleared\" => if not found then blank => top => get line above\r\n\r\n\r\ndelete all pages containing \"FOR A CHANGE OF NAME\"\r\n//Deleted extra lines\r\ndelete all lines containing \"BUSINESS CHECKING\"\r\ndelete all lines containing \"continued\"\r\ndelete all lines containing \"Statement Ending\"\r\ndelete all lines containing \"item(s) totaling\"\r\ndelete all lines containing \"Date Description\"\r\n$credits = get multi page table @creditsTop @creditsBottom 35 90 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n\r\n// Get Checks table\r\ngo to page 1\r\n@chequeTop = get line starting \"Check Nbr Date Amount\" => if not found then blank => bottom => get line below\r\n@chequebottom = get line starting \"Daily Balances\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Check Nbr Date Amount\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines starting \"* Indicates skipped check number\"\r\n\r\n$chequeLeft = get multi page table @chequeTop @chequebottom 55 91 150 210 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n$chequeMiddle = get multi page table @chequeTop @chequebottom 210 273 335 410 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n$chequeRight = get multi page table @chequeTop @chequebottom 410 459 515 580 => describe table false ChequeNumber \"Date[MM/dd/yyyy]\" *#Debit\r\n\r\n$transactions = combine described tables $credits $chequeLeft $chequeMiddle $chequeRight','2026-06-02 12:08:43',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10913,'Capitol_CreditCard','$source = \"Capitol_CreditCard\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 45\r\n\r\n// Account Details\r\n$accountNumber = get line starting \"Statement for EFG\" => get words after \"Statement for EFG\" => take last words 1 => get text\r\ngo to page 1\r\n@AcctBottom = get line starting \"Your card transactions\" => top\r\n$accountname = get text in box page.top @AcctBottom page.left page.middleX => take words 2 => get text\r\n\r\n// Statement Period\r\n$periodFrom = get line containing \"Opening balance\" => get words before \"Opening balance\" => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Closing balance\" => get words before \"Closing balance\" => get date \"dd/MM/yyyy\"\r\n\r\n// Opening & Closing Balance\r\ngo to page 1\r\n$openingbalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\r\n$closingbalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => get decimal\r\n\r\n// Delete Unwanted Text\r\ndelete all lines containing \"Opening balance\"\r\n\r\n// Table Top & Bottom\r\ngo to page 1\r\n@transactionstop = get line containing \"DATE DESCRIPTION PLACE\" => bottom => get line below\r\n@transactionsbottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\n// Read Transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 0 100 480 560 => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10914,'DOLORES_STATE_BANK','$source = \"DOLORES_STATE_BANK\"\r\n\r\n//Get Account Details\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n$accountNumber = get line containing \"Account No.:\" => get words after \"Account No.:\" => take words 1 => get text\r\n\r\n//Get Statement Period\r\n$periodFrom = get line starting \"Balance Forward From\" => get words after \"Balance Forward From\" => take words 1 => get date \"MM/dd/yy\"\r\n$periodTo = get line starting \"Ending Balance On\" => get words after \"Ending Balance On\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n//Get Opening & Closing Balances\r\n@openingTop = get line starting \"Balance Forward From\" => top\r\n@openingBottom = get line starting \"Balance Forward From\" => bottom\r\n$openingBalance = get text in box @openingTop @openingBottom 0 page.right => skip words 4 => get decimal\r\n\r\n@ClosingTop = get line starting \"Ending Balance On\" => top\r\n@ClosingBottom = get line starting \"Ending Balance On\" => bottom\r\n$closingBalance = get text in box @ClosingTop @ClosingBottom 0 page.right => skip words 4 => get decimal\r\n\r\n//Delete Headers\r\ngo to page 1\r\n@HeadersBottom = get line containing \"ALL CREDIT ACTIVITY\" => if not found then blank => top\r\n$delHeaders =  delete text in box page.top @HeadersBottom page.left page.right => get text\r\n\r\n// Get ALL CREDIT ACTIVITY Tables\r\ngo to page 1\r\n@creditsActivityTop = get line starting \"ALL CREDIT ACTIVITY\" => if not found then blank => bottom => get line below\r\n@creditsActivityBottom = get line starting \"Date Description Amount\" => if not found then blank => top => get line above\r\ndelete all lines starting \"Date Type Amount\"\r\ndelete all lines starting \"Continued\"\r\n@creditsActivityleft = get multi page table @creditsActivityTop @creditsActivityBottom 25 94 150 218 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\r\n@creditsActivitymiddle = get multi page table @creditsActivityTop @creditsActivityBottom 220 267 330 392   => describe table false \"Date[MM/dd/yy]\" Details *#Credit\r\n@creditsActivityright = get multi page table @creditsActivityTop @creditsActivityBottom 394 442 500 590 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\r\n\r\n//Ignore Header\r\nget last line starting \"Statement Date:\" => top => ignore header above\r\n\r\n// Get start & end of all Credits table\r\ngo to page 1\r\n@creditsTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"ALL CREDIT ACTIVITY\"\r\ndelete all lines starting \"Statement Date:\"\r\ndelete all lines containing \"Account No.:\"\r\ndelete all lines starting \"Continued\"\r\n@credits = get multi page table @creditsTop @creditsBottom 20 120 466 600 => describe table false \"Date[MM/dd/yy]\" Details *#Credit\r\n\r\n// Get start & end of all Debits table\r\ngo to page 1\r\n@debitsTop = get line starting \"ELECTRONIC DEBITS\" => if not found then blank => bottom => get line below\r\n@debitsBottom = get line starting \"CHECKS AND OTHER DEBITS\" => if not found then blank => top => get line above\r\ndelete all lines starting \"Date Description Amount\"\r\ndelete all lines containing \"(#) denotes fee for\"\r\ndelete all lines containing \"ELECTRONIC DEBITS (cont.)\"\r\n@debits = get multi page table @debitsTop @debitsBottom 20 94 466 600 => describe table false \"Date[MM/dd/yy]\" Details *#Debit\r\n\r\n//Get Start & End of Checks Table\r\ngo to page 1\r\n@checksTop = get line starting \"Date Check # Amount\" => if not found then blank => bottom => get line below\r\n@checksBottom = get line starting \"ITEMIZED SERVICE CHARGE\" => if not found then blank => top => get line above => top => get line above\r\ndelete all lines starting \"CHECKS AND OTHER DEBITS\"\r\ndelete all lines containing \"indicates a gap in the check numbers\"\r\ndelete all lines containing \"Date Check # Amount\"\r\n@ChecksL = get multi page table @checksTop @checksBottom 50 105 175 220  => describe table false \"*Date[MM/dd/yy]\" Details #Debit\r\n@ChecksM = get multi page table @checksTop @checksBottom 222 278 350 391 => describe table false  \"*Date[MM/dd/yy]\" Details #Debit\r\n@ChecksR = get multi page table @checksTop @checksBottom 396 450 520 570 => describe table false  \"*Date[MM/dd/yy]\" Details #Debit\r\n\r\n//Get Start & End of Fee Table\r\n@FeeTop = get line containing \"TOTAL SERVICE CHARGE\" => if not found then blank\r\n@FeeBottom = get line containing \"TOTAL SERVICE CHARGE\" => if not found then blank\r\n\r\n//Delete Check Tables\r\n@chkTop = get line starting \"Date Check # Amount\" => if not found then blank => bottom\r\n@chkBottom = get line containing \"TOTAL SERVICE CHARGE\" => if not found then blank => top => get line above => top\r\n@delchecks =  delete text in box @chkTop  @chkBottom 0 page.right => get text\r\ndelete all lines starting \"Date Check # Amount\"\r\n\r\n//Get Fee Table\r\n@Fee = get multi page table @FeeTop @FeeBottom 45 100 520 580 => describe table false \"Date[MM/dd/yy]\" Details *#Debit\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @creditsActivityleft @creditsActivitymiddle @creditsActivityright @credits @debits @ChecksL @ChecksM @ChecksR @Fee','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10915,'Qonto_AccountStatement','$source = \"Qonto_AccountStatement\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\nset negative marker \"-\"\r\n\r\n// Get account name/number\r\ngo to page 1\r\n@accountNameTop = get line starting \"Du\" => bottom\r\n@accountNameBottom = get line starting \"IBAN:\" => top\r\n$accountName = get text in box @accountNameTop @accountNameBottom 0 300 => get text\r\n\r\n@accountNumberTop = get line starting \"IBAN:\" => top\r\n@accountNumberBottom = get line starting \"IBAN:\" => bottom\r\n$accountNumber = get text in box @accountNumberTop @accountNumberBottom 0 385 => get words after \"IBAN:\" => take words 7 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line starting  \"Relevés de compte\" => bottom => get line below  => get words after \"Du\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line starting  \"Relevés de compte\" => bottom => get line below  => get words after \"au\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\ndelete all lines starting \"Relevés de compte\"\r\n@openingBalanceTop = get line containing \"Solde\" => top\r\n@closingBalanceBottom  = get line starting \"Date de valeur Transactions Débit Crédit\" => top\r\n@balanceText = get text in box @openingBalanceTop @closingBalanceBottom page.middleX page.right\r\n$openingBalance =  get words before @balanceText \"Entrées\" => take last words 3 => get decimal\r\n$closingBalance = get words after  @balanceText \"Solde au\" => take last words 3 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date de valeur Transactions Débit Crédit\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = get words before @header \"Débit\" => take last words 1 => left => subtract 5\r\n@debitLeft = get words before @header \"Crédit\" => take last words 1 => left => subtract 30\r\n@debitRight = get words before @header \"Crédit\" => take last words 1 => right => add 5\r\n@creditRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date de valeur Transactions Débit Crédit\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"Toutes les cartes de votre compte Qonto\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Date de valeur Transactions Débit Crédit\" => top => ignore header above\r\nignore footer below 50\r\n\r\n// Delete extra lines from transactions\r\ngo to page 1\r\n@footerTop = get line starting \"Toutes les cartes de votre compte Qonto\" => if not found then blank => bottom\r\n@deleteFooter = delete text in box @footerTop 0 0 page.right => get text\r\n\r\ndelete all lines starting \"Toutes les cartes de votre compte Qonto\"\r\ndelete all lines starting \"Date de valeur Transactions Débit Crédit\"\r\ndelete all lines starting \"Qonto\"\r\ndelete all lines starting \"IBAN:\"\r\ndelete all lines starting \"BIC:\"\r\ndelete all lines starting \"Du\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailLeft @debitLeft @debitRight @creditRight => describe table false \"*Date[dd/MM]\" Details #Debit #Credit\r\n','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10916,'HSBC_UK_Dyddiad','$source = \"HSBC_UK_Dyddiad\"\r\nset culture \"cy-GB\"\r\ndelete white words\r\ngo to page 1\r\n@accountLine = get line starting \"Enw \'r Cyfrif\" => bottom => get line below\r\n$accountNumber = take last words @accountLine 2 => take words 1 => get text\r\n\r\n@accountNameTop = top @accountLine\r\n@accountNameRight = take last words @accountLine 3 => left\r\n@accountNameBottom = bottom @accountLine\r\n$accountName = get text in box @accountNameTop @accountNameBottom 0 @accountNameRight => get text\r\n\r\n@periodtoBottom = get last line starting \"Enw \'r Cyfrif\" => top\r\n@periodtoTop = add @periodtoBottom 80\r\n$periodFrom = get text in box @periodtoTop @periodtoBottom 0 page.middleX => take words 2 => get date \"d MMMM\"\r\n$periodTo = get text in box @periodtoTop @periodtoBottom 0 page.middleX => take last words 3 => get date \"d MMMM yyyy\"\r\ngo to page 1\r\n$openingBalance = get line containing \"BALANS A DDYGWYD YMLAEN\" => get words after \"BALANS A DDYGWYD YMLAEN\" => take last words 1 => get decimal\r\n\r\n@closingBalanceRaw = get last line containing \"Balans Terfynol\" => skip words 2\r\n$closingBalance = get decimal @closingBalanceRaw\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Dyddiad Math o daliad\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get last line containing \"BALANS A GARIWYD YMLAEN\" => top => get line above\r\n\r\ndelete all lines containing \"BALANS A DDYGWYD YMLAEN\"\r\ndelete all lines containing \"BALANS A GARIWYD YMLAEN\"\r\ndelete all lines containing \"Dyddiad Math o daliad\"\r\nignore header above 622\r\nignore footer below 35\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 110 340 415 510 560 => describe table false \"Date[dd MMM yy]\" Details **#Debit **#Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10917,'Shopify_CashbackNew_CreditCard','$source = \"Shopify_CashbackNew_CreditCard\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\n// Get Accounts\r\n$accountNumberTextTop = get line containing \"account\" => top\r\n$accountNumberTextBottom = get line containing \"summary\" => top\r\n$accountNumberText = get text in box $accountNumberTextTop $accountNumberTextBottom page.left page.right\r\n$accountNumber = get words after $accountNumberText \"account ending in\" => take words 1 => get text\r\n$accountName = get words after $accountNumberText \"account ending in\" => take words 1 => get text\r\n\r\n//Get Closing Balance\r\n$closingBalance = get line containing \"New balance\" => get words after \"New balance\" => take words 1 => get decimal\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalanceTop = get line containing \"summary\" => bottom\r\n$openingBalanceBottom = get line containing \"Previous balance\" => bottom\r\n$openingBalanceText = get text in box $openingBalanceTop $openingBalanceBottom page.middleX page.right\r\n$openingBalance = get words after $openingBalanceText \"balance\" => take words 1 => get decimal\r\n\r\n// Get Periods\r\n$periodFromText = get line containing \"Transaction Date Post\" => bottom => get line below\r\n$periodFrom = take words $periodFromText 3 => get date \"MMM d, yyyy\"\r\n$periodTo = get last line starting \"If you have any questions\" => top => get line above => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n// Get Others Table Transactions\r\ngo to page 1\r\n@otherTop = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\r\n@otherBottom = get last line containing \"If you have any questions\" => if not found then blank => top => get line above\r\n\r\n// Deleted Extra Lines\r\nignore footer below 42\r\ndelete all lines starting \"Date Description\"\r\n$other = get multi page table @otherTop @otherBottom 30 96 510 580 => describe table false \"*Date[MMM d, yyyy]\" Details *#Credit\r\n\r\n// Get Purchase Table Transactions\r\ngo to page 1\r\n@purchaseTop = get line starting \"Transaction Date\" => if not found then blank => bottom => get line below\r\n@purchaseBottom = get line starting \"Other transactions\" => if not found then blank => top => get line above\r\n\r\n// Deleted Extra Lines\r\ndelete text in box on every page 35 page.bottom page.left page.right\r\ndelete all lines containing \"Transaction Date Post\"\r\ndelete all lines containing \"Purchases from card\"\r\ndelete all lines containing \"questions or concerns,\"\r\n\r\n$purchase = get multi page table @purchaseTop @purchaseBottom 30 96 175 510 580 => describe table false - \"*Date[MMM d, yyyy]\" Details #Credit\r\n// Combine both tables\r\n$transactions = combine described tables $other $purchase','2026-08-25 09:33:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10918,'Reliance_Bank','$source = \"Reliance_Bank\"\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalanceTop = get line containing \"Opening Balance\" => top\r\n$openingBalanceBottom = get line containing \"Closing Balance\" => bottom\r\n$openingBalanceText = get text in box $openingBalanceTop $openingBalanceBottom page.middleX page.right\r\n$openingBalance = get words after $openingBalanceText \"Opening Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after $openingBalanceText \"Closing Balance\" => take words 1 => get decimal\r\n\r\n// Get Accounts\r\n$accountNumberText = get line containing \"Account Number\" => get words after \"Account Number\"\r\n$accountNumber = take words $accountNumberText 1 => get text\r\n$accountName = take words $accountNumberText 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodTo = get line starting \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"d MMMM yyyy\"\r\n$periodFromText = get line starting \"Date Code Description\" => bottom => get line below\r\n$periodFrom = take words $periodFromText 3 => get date \"d MMM yy\"\r\n\r\n//Transaction Table starts here with dynamic coordinates\r\ngo to page 1\r\n$Date_left = get line containing \"Date Code Description\" => get words before \"Code\" => left => subtract 20\r\n$Date_right = get line containing \"Date Code Description\" => get words after \"Date\" => take words 1 => left => subtract 5\r\n$Type_right = get line containing \"Date Code Description\" => get words after \"Code\" => take words 1 => left => subtract 5\r\n$Description_right = get line containing \"Date Code Description\" => get words after \"Description\" => take words 1 => left => subtract 20\r\n$Paidout_right = get line containing \"Date Code Description\" => get words before \"Paid in\" => right => add 30\r\n$Paidin_right = get line containing \"Date Code Description\" => get words before \"Balance\" => right => add 30\r\n$Balance_right = get line containing \"Date Code Description\" => get words after \"Paid in\" => right => add 100\r\n\r\n$transactionsTop = get line containing \"Date Code Description\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line containing \"Balance to Sheet no\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Balance from Sheet\"\r\ndelete all lines containing \"Balance to Sheet\"\r\nignore footer below 51\r\nignore header above 628\r\n\r\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Date_right $Type_right $Description_right  $Paidout_right $Paidin_right $Balance_right => describe table false \"*Date[d MMM yy]\" TransactionType Details #Debit #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10919,'Intuit_GreenDotBank','$source = \"Intuit_GreenDotBank\"\r\n$periodbufferdays = 15\r\n\r\n@AccountDetailsTop = get line containing \"ACCOUNT NUMBER\" => top\r\n@SummaryTop = get line containing \"Beginning Balance on\" => top\r\n\r\n$AccountName = get text in box @AccountDetailsTop @SummaryTop 0 page.right => take words 2 => get text\r\n\r\ndelete text in box @AccountDetailsTop @SummaryTop 0 490\r\n\r\n@AccountDetailsBottom = get line containing \"ACCOUNT NUMBER\" => bottom => get line below => bottom\r\n$accountNumber = get text in box @AccountDetailsTop @AccountDetailsBottom 490 page.right => get words after \"ACCOUNT NUMBER\" => get text\r\n\r\n@SummaryBottom = get line containing \"Ending Balance on\" => bottom\r\n\r\n@Summary = get text in box @SummaryTop @SummaryBottom 0 page.right\r\n$periodFrom = get words after @Summary \"Beginning Balance on\" => take words 3 => get date \"MMM dd yyyy\"\r\n$periodTo = get words after @Summary \"Ending Balance on\" => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n@DeleteSummaryTop = get line containing \"Beginning Balance on\" => bottom\r\n@DeleteSummaryBottom = get line containing \"Ending Balance on\" => top\r\ndelete text in box @DeleteSummaryTop @DeleteSummaryBottom 0 page.right\r\n\r\n@SummaryAfterDeletion = get text in box @SummaryTop @SummaryBottom 0 page.right\r\n\r\n$OpeningBalance = get words after @SummaryAfterDeletion \"Beginning Balance on\" => get words before \"Ending Balance on\" => skip words 3 => get decimal\r\n$ClosingBalance = get words after @SummaryAfterDeletion \"Ending Balance on\" => skip words 3 => get decimal\r\n\r\n@Header = get line starting \"DATE DESCRIPTION AMOUNT\"\r\n@DateLeft = take words @Header 1 => left => subtract 5\r\n@DescLeft = get words after @Header \"DATE\" => take words 1 => left => subtract 5\r\n@AmountLeft = get words after @Header \"DESCRIPTION\" => take words 1 => left => subtract 130\r\n@AmountRight = get words after @Header \"DESCRIPTION\" => take words 1 => right => add 50\r\n\r\n@TransactionsTop = get line starting \"DATE DESCRIPTION AMOUNT\" => bottom => get line below\r\n@LastTransactionsPage = get last line starting \"DATE DESCRIPTION AMOUNT\"\r\n@TransactionsBottom = get line above 0\r\n\r\n@DelEnvelopesTop = get line starting \"ENVELOPES\" => top\r\n@DelEnvelopesBottom = get line containing \"DATE DESCRIPTION AMOUNT\" => bottom\r\n$DelEnvelopes = delete text in box @DelEnvelopesTop @DelEnvelopesBottom 0 page.right => get text\r\ngo to page 1\r\n@DelEnvelopes1Top = get line starting \"ENVELOPES\" => top\r\n@DelEnvelopes1Bottom = get line containing \"DATE DESCRIPTION AMOUNT\" => bottom\r\n$DelEnvelopes1 = delete text in box @DelEnvelopes1Top @DelEnvelopes1Bottom 0 page.right => get text\r\n\r\nignore header above 632\r\nignore footer below 85\r\ndelete all lines starting \"No Transactions\"\r\n\r\n$Transactions = get multi page table @TransactionsTop @TransactionsBottom @DateLeft @DescLeft @AmountLeft @AmountRight => describe table false \"*Date[MM/dd/yyyy]\" Details #Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10920,'FNBO_JalMasterCard','$source = \"FNBO_JalMasterCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 28\r\nset negative marker \"CR\"\r\n\r\n// Get account name/number\r\ngo to page 1\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 2 => get text\r\n$accountNumber = get line starting \"Account number\" => get words after \"ending in\" => take words 1 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n@periodText = get line starting  \"Trans Date Post Date\"\r\n@periodTop =  get words before @periodText \"Post Date\" => take words 1 => bottom\r\n@periodLeft = take words @periodText 1 => left\r\n@periodRight = get words before @periodText \"Post Date\" => take last words 1 => right\r\n$periodFrom = get text in box @periodTop 0 @periodLeft @periodRight => take words 1 => get date \"MM-dd\"\r\ngo to page 1\r\n$periodTo = get line containing  \"Statement Closing Date\" => get words after \"Statement Closing Date\" => take words 1 => get date \"MM/dd/yy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get text in box page.top 0 0 page.middleX => get words after \"Previous Balance\" => take words 1 => get decimal\r\n$closingBalance = get text in box page.top 0 0 page.middleX => get words after \"New Balance\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Trans Date Post Date\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@date1Left = get words after @header \"Trans Date\" => take words 1 => left => subtract 5\r\n@referenceLeft = get words after @header \"Post Date\" => take words 1 => left => subtract 10\r\n@detailLeft = get words after @header \"Reference Number\" => take words 1 => left => subtract 10\r\n@amountLeft = get words after @header \"Transaction Description\" => take words 1 => left => subtract 10\r\n@amountRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Trans Date Post Date\" => bottom => get line below\r\n@transactionBottom = get last line starting \"Fees Charged\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Trans Date Post Date\" => top => ignore header above\r\nignore footer below 40\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"TRANSACTION DETAIL\"\r\ndelete all lines starting \"Transactions\"\r\ndelete all lines starting \"Trans Date\"\r\ndelete all lines starting \"Debits\"\r\n\r\ngo to page 1\r\ndelete text in box page.top 0 page.middleX page.right\r\n\r\ngo to page 1\r\n// Get start & end of Fees Charged table\r\n@feesChargedTop = get line starting \"Fees Charged\" =>  top => get line above => bottom => get line below\r\n@feesChargedBottom = get line starting \"Fees Charged\" => bottom => get line below => top => get line above\r\n@feesCharged = get multi page table @feesChargedTop @feesChargedBottom 0 130 215 => describe table false Details *#Credit\r\n\r\n//Get start & end of Interest Charged table\r\n@interestChargedTop = get line starting \"Interest Charged\" =>  top => get line above => bottom => get line below\r\n@interestChargedBottom = get line starting \"Interest Charged\" => bottom => get line below => top => get line above\r\n@interestCharged = get multi page table @interestChargedTop @interestChargedBottom 0 130 215 => describe table false Details *#Credit\r\n\r\n// Read the transactions\r\n@debitCredit = get multi page table @transactionTop @transactionBottom  @dateLeft @date1Left @referenceLeft  @amountLeft @amountRight => describe table false \"Date[MM-dd]\" - Details *#Credit\r\n$transactions = combine described tables @debitCredit @feesCharged @interestCharged','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10921,'FirstBank_FarmersStateBank','$source = \"FirstBank_FarmersStateBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 31\r\n\r\n// Get Accounts\r\ngo to page 1\r\n$accountName = get text in box 630 620 page.left page.middleX => take words 3 => get text\r\n$accountNumberText = get line containing \"Account Number\" => get words after \"Account Number\"\r\n$accountNumber = take words $accountNumberText 3 => take last words 1 => get text\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalanceTop = get line containing \"Beginning Balance\" => top\r\n$openingBalanceBottom = get line containing \"Ending Balance\" => bottom\r\n$openingBalanceText = get text in box $openingBalanceTop $openingBalanceBottom page.left page.middleX\r\n$openingBalance = get words after $openingBalanceText \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after $openingBalanceText \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\r\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\r\n\r\n// Transaction Table\r\ngo to page 1\r\n\r\n$transactionsTop = get line containing \"Date Description Amount\" => bottom => get line below\r\n$transactionsBottom = get line containing \"DAILY BALANCE INFORMATION\" => top => get line above\r\n\r\n// Delete extra lines\r\ndelete all lines containing \"**CHECKS & OTHER DEBITS**\"\r\ndelete all lines containing \"Date Description Amount\"\r\nignore footer below 55\r\nignore header above 550\r\n\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 25 80 318 380 => describe table false \"Date[M/dd]\" Details *#Credit','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10922,'Bidvest_TransactionDateProcessed_Bank','$source = \"Bidvest_TransactionDateProcessed_Bank\"\r\n// Get Account\r\n$accountNumber = get line containing \"Account No\" => get words after \"Account No\" => take words 1 => get text\r\n$accountName = get text in box page.top page.middleY page.left page.middleX => take words 2 => get text\r\n\r\n// Get Opening & Closing Balances\r\n@getLineBroughtFoward = get line containing \"Transaction Description\" => bottom => get line below => get text\r\n@openingtop = get line containing @getLineBroughtFoward => top\r\n@openingbottom = get line containing @getLineBroughtFoward => bottom\r\n@openingleft = get line containing \"Transaction Description\" => get words before \"Balance\" => take  last words 1 => right => add 7\r\n$openingbalance = get text in box @openingtop @openingbottom @openingleft page.right => get decimal\r\n\r\ngo to page 1\r\n$closingbalance = get line containing \"Closing Balance:\" => get words after \"Closing Balance:\" => take words 2 => get decimal\r\n\r\n//Get Period\r\n$periodFrom  =  get line starting \"Statement for the period\" => get words after \"period\" => take words 1 => get date \"yyyy/MM/d\"\r\n$periodTo  =  get line starting \"Statement for the period\" => get words after \"to\" => take words 1 => get date \"yyyy/MM/d\"\r\n\r\ngo to page 1\r\n@date2Right = get line containing \"Statement Opening Balance\" => get words before \"Opening Balance\" => take last words 1 => left => subtract 3\r\n@detailRight = get line containing \"Transaction Description\" => get words before \"Balance\" => take last words 1 => left => subtract 35\r\n@balanceright  = get line containing \"Transaction Description\" => get words after \"Amount\" => take words 1 => right => add 20\r\n\r\ngo to page 1\r\n// Get Transactions\r\n@transactionstop = get line containing \"Transaction Description\" => if not found then blank => bottom => get line below\r\nget last line containing \"Transaction Description\"\r\n@transactionsbottom = get line starting \"Note:\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\ngo to page 1\r\ndelete all lines containing \"Transaction Description\"\r\ndelete all lines starting \"Transaction Effective\"\r\ndelete all lines containing \"Statement Opening Balance\"\r\ndelete all lines containing \"Balance Brought Forward\"\r\ndelete all lines starting \"Transaction Note:\"\r\nignore header above 790\r\n@footer = get last line containing \"Note:\" => if not found then blank => top\r\nignore footer below @footer\r\n\r\n//Read Transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 40 110 @date2Right @detailRight @openingleft @balanceright => describe table false *Date[yyyy/MM/d] - Details #Credit *#Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10923,'BankSA','$source = \"BankSA\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 14\r\n\r\n// Get account details\r\n$accountName = get line containing \"Account Number\" => get words after \"Account Number\" => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => get words before \"to\" => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Statement Period\" => get words after \"Statement Period\" => get words after \"to\" => get date \"dd/MM/yyyy\"\r\n\r\n// Get opening & closing balance\r\n$openingBalance = get line containing \"OPENING BALANCE\" => get words after \"OPENING BALANCE\" => get decimal\r\n$closingBalance = get line containing \"CLOSING BALANCE\" => get words after \"CLOSING BALANCE\" => get decimal\r\n\r\n// Get table top & bottom\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Transaction Description Debit\" => bottom => get line below\r\n@transactionBottom = get line containing \"CLOSING BALANCE\" => top => get line above\r\n\r\n// Remove headers & footers\r\nignore header above 630\r\nignore footer below 35\r\n\r\n// Delete unwanted lines\r\ndelete all lines containing \"SUB TOTAL CARRIED FORWARD TO NEXT PAGE\"\r\ndelete all lines containing \"Transaction Details continued\"\r\ndelete all lines containing \"Date Transaction Description\"\r\ndelete all lines containing \"OPENING BALANCE\"\r\ndelete all lines containing \"SUB TOTAL CARRIED FORWARD\"\r\n\r\n// Get transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom 25 72 320 400 475 580 => describe table false \"*Date[d MMM]\" Details #Debit #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10924,'Euro_Bank','$source = \"Euro_Bank\"\r\n$periodBufferDays = 28\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take last words 1 => get text\r\n$accountName = get line starting \"Account Holder(s) Name\" => bottom => get line below => get text\r\n\r\n$periodFrom = get line containing \"Date From\" => get words after \"Date From\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line containing \"Date To\" => get words after \"Date To\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line starting \"Balance B/F\" => get words after \"Balance B/F\" => take last words 1 => get decimal\r\n$closingBalance = get last line starting \"Closing Balance\" => get words after \"Closing Balance\" => take last words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Details Value\"\r\n@header1 = get line starting \"Balance B/F\"\r\n\r\n// Column coordinates\r\n@detailLeft =  take words @header1 1 => left => subtract 5\r\n@date1Left = get words after @header \"Details\" => take words 1 => left => subtract 3\r\n@debitLeft = get words after @header \"Value\" => take words 1 => right => add 5\r\n@debitRight = get words after @header \"Value Date\" => take words 1 => right => add 5\r\n@creditRight = get words after @header \"Debit\" => take words 1 => right => add 5\r\n@balanceRight = get words after @header \"Credit\" => take words 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Balance B/F\" => bottom => get line below\r\n@transactionBottom = get last line starting \"Closing Balance\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Date Details Value Date\" => top => ignore header above\r\ngo to page 1\r\n@closingBottomFooter = get last line starting \"Closing Balance\" => if not found then blank => bottom\r\n@deleteClosingBottom = delete text in box @closingBottomFooter 0 0 page.right => get text\r\n\r\nignore footer below 45\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Balance B/F\"\r\ndelete all lines starting \"Total Amounts\"\r\ndelete all lines starting \"Opening balance\"\r\ndelete all lines starting \"Closing Balance\"\r\ndelete all lines starting \"Date Details Value Date\"\r\ndelete all lines starting \"Ημερομηνία\"\r\ndelete all lines ending \"Debit Credit Balance\"\r\ndelete all lines ending \"Υπόλοιπο\"\r\ndelete all lines starting \"Accrued Debit Interest\"\r\ndelete all lines starting \"Δεδουλευμένοι\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom 0 @detailLeft @date1Left @debitLeft @debitRight @creditRight @balanceRight => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit #Balance','2026-06-23 09:27:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10925,'CapitalCityBank','$source = \"CapitalCityBank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n$accountName = get text in box page.top page.middleY 0 page.middleX => skip words 4 => take words 2 => get text\r\n\r\n@SummaryTop = get line containing \"Account Number\" => top\r\n@SummaryBottom = get line containing \"Previous Balance\" => bottom\r\n@Summary = get text in box @SummaryTop @SummaryBottom 0 550\r\n\r\n$AccountNumber = get words after @Summary \"Account Number\" => get words between \"Account Number\" \"Statement Dates\" => get text\r\n$PeriodFrom = get words after @Summary \"Statement Dates\" => get words between \"Statement Dates\" \"thru\" => get date \"M/d/yy\"\r\n$PeriodTo = get words after @Summary \"thru\" => get words between \"thru\" \"Previous Balance\" => get date \"M/d/yy\"\r\n$OpeningBalance = get words after @Summary \"Previous Balance\" => get words between \"Previous Balance\" \"Days in\" => get decimal\r\n\r\n@ClosingTop = get line containing \"Ending Balance\" => top\r\n@ClosingBottom = get line containing \"Ending Balance\" => bottom\r\n$ClosingBalance = get text in box @ClosingTop @ClosingBottom 0 245 => get words after \"Ending Balance\" => get decimal\r\n\r\n@TransactionsTop = get line starting \"Date Description Amount\" => bottom => get line below\r\n@TransactionsBottom = get last line starting \"Date Description Amount\" => bottom => get break below => get line at\r\n\r\n@ChecksTop = get line containing \"Date Check No\" => if not found then blank => bottom => get line below\r\ngo to page 1\r\n@CheckBottom = get last line containing \"* Denotes missing check\" => if not found then blank => top => get line above\r\n\r\ngo to page 1\r\nget line containing \"(Continued)\" => bottom => ignore header above\r\nignore footer below 60\r\ndelete all lines containing \"(Continued)\"\r\ndelete all lines starting \"OTHER DEBITS\"\r\ndelete all lines starting \"Date Description Amount\"\r\ndelete all lines starting \"DEPOSITS AND OTHER CREDITS\"\r\ndelete all lines starting \"Date Check No\"\r\ndelete all lines containing \"* Denotes missing check\"\r\ndelete all lines containing \"CHECKS IN NUMBER ORDER\"\r\n\r\n@DrCrTransactions = get multi page table @TransactionsTop @TransactionsBottom 25 80 310 550 => describe table false \"*Date[M/d]\" Details #Credit\r\n\r\n@ChequeLeft = get multi page table @ChecksTop @CheckBottom 25 72 120 247 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\r\n@ChequeRight = get multi page table @ChecksTop @CheckBottom 247 292 345 550 => describe table false \"*Date[M/d]\" #ChequeNumber #Debit\r\n\r\n$Transactions = combine described tables @DrCrTransactions @ChequeLeft @ChequeRight','2026-06-23 09:27:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10926,'Coles_CreditCards','$source = \"Coles_CreditCards\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 28\r\n\r\n// Transactions with Cr text are negative\r\nset negative marker \"Cr\"\r\n\r\n// Get Period From and To\r\ngo to page 1\r\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"dd MMM yy\"\r\n$periodTo = get line containing \"Statement Period\" => get words after \"Statement Period\" => take last words 3 => get date \"dd MMM yy\"\r\n\r\n// Get Accounts\r\ngo to page 1\r\n$accountName = get text in box 660 645 page.left page.middleX => take words 3 => get text\r\n$accountNumberText = get line containing \"Account Number\" => get words after \"Account Number\"\r\n$accountNumber = take words $accountNumberText 4 => get text\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalanceTop = get line containing \"Opening Balance\" => top\r\n$openingBalanceBottom = get line containing \"Closing Balance\" => bottom\r\n$openingBalanceText = get text in box $openingBalanceTop $openingBalanceBottom page.left page.middleX\r\n$openingBalance = get words after $openingBalanceText \"Opening Balance\" => get words between \"Opening Balance\" \"- Payments & credits received\" => get decimal\r\n$closingBalance = get words after $openingBalanceText \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\r\n\r\n// Get start & end of transactions table\r\n@transactionsTop = get line containing \"Processed Date Transaction Date Details Amount\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"How to identify the card to make a transaction:\" => top => get line above\r\n\r\n// Remove unwanted lines\r\ndelete all lines containing \"Processed Date Transaction Date Details Amount\"\r\ndelete all lines containing \"Primary Card Number:\"\r\ndelete all lines containing \"Card Number:\"\r\ndelete all lines containing \"How to identify the card to make a transaction:\"\r\nignore header above 715\r\nignore footer below 60\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 70 160 228 500 560 => describe table false \"Date[dd/MM/yy]\" - Details *#Credit','2026-06-23 09:27:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10927,'Coles_Mastercard','$source = \"Coles_Mastercard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Total Cash Limit:\" => top => get line above => take words 2 => take last words 1 => get decimal\r\n// AccountDetails\r\n$accountName = get line containing \"Account Name\" => get words after \"Account Name\" => take words 3 => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n// PeriodFrom and PeriodTo\r\n$periodFrom = get line containing \"Statement Begins\" => get words after \"Statement Begins\" => take words 3 => get date \"dd MMMM yyyy\"\r\n$periodTo = get line containing \"Statement Ends\" => get words after \"Statement Ends\" => take words 3 => get date \"dd MMMM yyyy\"\r\n// ClosingBalance\r\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n\r\n// Get start & end of transactions table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transaction Details Reference Number Amount\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"Closing Balance\" => top => get line above\r\n\r\n// Remove unwanted lines\r\ndelete all lines containing \"Date Transaction Details\"\r\ndelete all lines containing \"Card Number\"\r\ndelete all lines containing \"Continued next page\"\r\ndelete all lines containing \"Closing Balance\"\r\nignore header above 680\r\nignore footer below 445\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 115 500 575 => describe table false \"Date[MMM dd]\" Details *#Credit','2026-06-23 09:27:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10928,'Santander_Loan','$source = \"Santander_Loan\"\r\n$features = \"CREDIT_CARD\"\r\n\r\n// Get account name and number\r\n$accountnumberText = get line starting \"Account number:\" => bottom => get line below\r\n$AccountName = take last words $accountnumberText 1 => get text\r\n$AccountNumber = take last words $accountnumberText 1 => get text\r\n\r\n//Get Closing Balance\r\n$openingBalanceText = get line containing \"Opening Balance\"\r\n$periodFrom = get words before $openingBalanceText \"Opening Balance\"  => take words 3 => get date \"d MMM yyyy\"\r\n$openingBalance = get words after $openingBalanceText \"Opening Balance\"  => take words 1 => get decimal\r\n\r\n$ClosingBalanceText = get line containing \"Mortgage Loan Balance\"\r\n$closingBalance = get words after $ClosingBalanceText \"Mortgage Loan Balance\" => take words 1 => get decimal\r\n$periodTo = get words before $ClosingBalanceText \"Mortgage Loan Balance\"  => take words 3 => get date \"d MMM yyyy\"\r\n\r\ngo to page 1\r\n$Date_left = get line containing \"Date Transactions Credits\" => get words before \"Transactions\" => left => subtract 5\r\n$Date_right = get line containing \"Date Transactions Credits\" => get words after \"Date\" => take words 1 => left => subtract 5\r\n$Description_right = get line containing \"Date Transactions Credits\" => get words after \"Transactions\" => take words 1 => left => subtract 25\r\n$Paidin_right = get line containing \"Date Transactions Credits\" => get words after \"Transactions\" => take words 1 => right => add 20\r\n$Paidout_right = get line containing \"Date Transactions Credits\" => get words after \"Credits\" => take words 1 => right => add 20\r\n\r\ngo to page 1\r\n// Get start of table\r\n$transactionsTop = get line containing \"Date Transactions Credits\" => if not found then blank => bottom => get line below\r\n// Get end of table\r\n$transactionsBottom = get line containing \"Mortgage Loan Balance\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Opening Balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Date_right $Description_right $Paidin_right $Paidout_right => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit','2026-06-23 09:27:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10929,'Nevada_State_Bank','$source = \"Nevada_State_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n//Get Accounts\r\ngo to page 1\r\n$top = get line containing \"Last Statement\" => bottom\r\n$topbot = get text in box $top 702 430 page.right => get words after \"Account\"\r\n\r\n$accountName = get words after $topbot \"Account\" => take last words 1 => get text\r\n$accountNumber = get words after $topbot \"Account\" => take last words 1 => get text\r\n\r\n//Get Periods\r\n$periodFromText = get line containing \"Last Statement:\" => get words after \"Last Statement:\"\r\n$periodFrom = take words $periodFromText 3 => get date \"MMMM d,yyyy\"\r\n$periodToText = get line containing \"This Statement:\" => get words after \"This Statement:\"\r\n$periodTo = take words $periodToText 3 => get date \"MMMM d,yyyy\"\r\n\r\ndelete all lines containing \"Count:\"\r\n//Get Opening and Closing Balance\r\n$OpeningText = get line containing \"Previous Balance Deposits/Credits\" => bottom => get line below\r\n$openingBalance = get words after $OpeningText \"Amount:\"  =>  take words 1 => get decimal\r\n$closingBalance = take last words $OpeningText 1 => get decimal\r\n\r\n//GET TRANSACTIONS\r\ngo to page 1\r\n// Get start & end of DEPOSITS/CREDITS/WITHDRAWALS table\r\n@DepositsTop = get line containing \"Date Description Credits\" => if not found then blank => bottom => get line below\r\n@DepositsBottom = get line containing \"CHECKS PROCESSED\" => if not found then blank => top => get line above\r\n\r\n\r\ndelete all lines containing \"Date Description Credits\"\r\ndelete all lines containing \"Member FDIC\"\r\nignore footer below 22\r\nignore header above 668\r\nset negative marker \"-\"\r\n\r\n//READ TRANSACTIONS\r\n$transactions = get multi page table @DepositsTop @DepositsBottom 30 68 420 482 585  => describe table false \"Date[M/d]\" Details #Credit #Debit','2026-06-23 09:27:54',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10930,'Republic_Bank_RoutingNumber','$source = \"Republic_Bank_RoutingNumber\"\r\n\r\n// Get account name/number\r\n$accountName = get text in box 682 0 0 page.middleX => take words 3 => get text\r\n@accountNumberText = get line starting \"Account\" => take words 2\r\n@accountNumberTop = take words @accountNumberText 1 => bottom\r\n@accountNumberLeft = take words @accountNumberText 1 => left\r\n@accountNumberRight = take last words @accountNumberText 1 => left\r\n$accountNumber = get text in box @accountNumberTop 0 @accountNumberLeft @accountNumberRight => take words 1 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line containing \"Statement Date:\" => get words after \"Statement Date:\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get line containing \"Statement Date:\" => get words after \"thru\" => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n@balanceText = get line starting \"Account\"\r\n@balanceTop = take words @balanceText 1 => bottom\r\n@openingLeft = get words after @balanceText \"Type\" => take words 1 => left\r\n@openingRight = get words after @balanceText \"Type\" => take words 2 => take last words 1 => right => add 2\r\n$openingBalance = get text in box @balanceTop 0 @openingLeft @openingRight => take words 1 => get decimal\r\n\r\n@closingLeft = take last words @balanceText 2 => take words 1 => left\r\n@closingRight = take last words @balanceText 2 => take last words 1 => right\r\n$closingBalance = get text in box @balanceTop 0 @closingLeft @closingRight => take words 1 => get decimal\r\n\r\n// Format 1 - Get the start and end of the transaction (columns: Date, Description, Withdrawal, Deposit)\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Description Withdrawal Deposit\" => if not found then blank => bottom => get line below\r\n@transactionBottom = get last line ending \"Checks Paid\" => if not found then blank => top => get line above\r\n\r\n// Format 2 - Get the start and end of the transaction (columns: Date, Description, Amount)\r\ngo to page 1\r\n@transactionTop1 = get line starting \"Date Description Amount\" => if not found then blank => bottom => get line below\r\n@transactionBottom1 = get last line ending \"Checks Paid\" => if not found then blank => top => get line above\r\n\r\nget last line starting \"Account Details\" => top => ignore header above\r\n\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines starting \"Deposits\"\r\ndelete all lines starting \"Withdrawals\"\r\ndelete all lines starting \"Account\"\r\ndelete all lines starting \"Checks Paid\"\r\ndelete all lines starting \"Statement Date:\"\r\ndelete all lines starting \"Primary Account:\"\r\ndelete all lines starting \"Page:\"\r\n\r\n// Format 1 - table extraction (Withdrawal/Deposit layout)\r\n@transaction = get multi page table @transactionTop @transactionBottom 10 103 430 600 => describe table false \"*Date[M/d/yyyy]\" Details #Credit\r\n\r\n// Format 2 - table extraction (Amount layout)\r\n@transaction1 = get multi page table @transactionTop1 @transactionBottom1 10 98 520 600 => describe table false \"*Date[M/d/yyyy]\" Details #Credit\r\n\r\n// Combine both formats into a single transaction result\r\n$transactions = combine described tables @transaction @transaction1','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10931,'CIBC_SimpliiFinancial','$source = \"CIBC_SimpliiFinancial\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\n// Get account name/number\r\n$accountName = get text in box page.top 0 0 204 => take words 3 => get text\r\n$accountNumber = get line containing \"account number:\" => get words after \"account number:\" => take words 1 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line containing \"statement period:\" => get words after \"statement period:\" => take words 3 => get date \"MMMM d, yyyy\"\r\n$periodTo = get line containing \"statement period:\" => get words after \"-\" => take words 3 => get date \"MMMM d, yyyy\"\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line containing \"BALANCE FORWARD\" => get words after \"BALANCE FORWARD\" => take last words 1 => get decimal\r\n$closingBalance = get line starting \"closing balance\" => get words after \"closing balance\" => take last words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line containing \"transaction funds out funds in balance\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@date1Left = take words @header 1 => right => add 25\r\n@detailLeft = get words before @header \"funds out\" => take last words 1 => left => subtract 5\r\n@debitLeft = get words after @header \"transaction\" => take words 1 => left => subtract 25\r\n@debitRight = get words before @header \"funds in\" => take last words 1 => right => add 5\r\n@creditRight = get words before @header \"balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line ending \"transaction funds out funds in balance\" => bottom => get line below\r\n@transactionBottom = get last line starting \"closing balance\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line ending \"transaction funds out funds in balance\" => top => ignore header above\r\nget last line starting \"page\" => top => ignore footer below\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"total\"\r\ndelete all lines containing \"BALANCE FORWARD\"\r\ndelete all lines starting \"closing balance\"\r\ndelete all lines starting \"date\"\r\ndelete all lines ending \"balance\"\r\ndelete all lines containing \"continue in the next page\"\r\ndelete all lines containing \"end of transactions\"\r\ndelete all lines starting \"statement period:\"\r\ndelete all lines starting \"statement date:\"\r\ndelete all lines starting \"account number:\"\r\ndelete all lines starting \"details\"\r\ndelete all lines starting \"your no fee chequing account\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @date1Left @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"*Date[MMM d]\" - Details #Debit #Credit #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10932,'BRED_Banque_Populaire_Bank','$source = \"BRED_Banque_Populaire_Bank\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\nset culture \"fr-BE\"\r\nset negative marker \"Débit\"\r\n\r\n// Get account name/number\r\n@accountText = get line starting \"Date N° de compte\"\r\n@accountTop = take words @accountText 1 => bottom\r\n@accountNumberLeft = get words after @accountText \"Date\" => take words 1 => left\r\n@accountNumberRight = get words after @accountText \"N° de compte\" => take words 1 => left => subtract 2\r\n$accountNumber = get text in box @accountTop 0 @accountNumberLeft @accountNumberRight => take words 1 => get decimal\r\n\r\n@accountNameLeft = get words before @accountText \"N° de relevé\" => take last words 1 => right\r\n@accountNameRight = get words after @accountText \"N° de compte\" => take words 1 => right\r\n$accountName = get text in box @accountTop 0 @accountNameLeft @accountNameRight => take words 5 => get text\r\n\r\n// Get period from/to\r\n$periodFrom = get line starting \"Date Référence Débit Crédit Valeur\" => bottom => get line below => take words 1 => get date \"dd.MM\"\r\n$periodTo = get line starting \"Date N° de compte\" => bottom => get line below => take words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n@openingBalanceTop = get line containing \"Solde précédent\" => top => get line above => top\r\n@openingBalanceBottom = get line containing \"Solde précédent\" => bottom\r\n@openingBalanceLeft = get line containing \"Solde précédent\" => get words after \"Solde précédent\" => left => subtract 40\r\n@openingBalanceRight = get line containing \"Solde précédent\" => get words after \"Solde précédent\" => right\r\n$openingBalance = get text in box @openingBalanceTop @openingBalanceBottom @openingBalanceLeft @openingBalanceRight => get decimal\r\n\r\ngo to page 1\r\n@closingBalanceTop = get line containing \"Nouveau solde\" => top\r\n@closingBalanceBottom = get line containing \"Nouveau solde\" => bottom\r\n@closingBalanceLeft = get line containing \"Nouveau solde\" => take last words 1 => left => subtract 170\r\n@closingBalanceRight = get line containing \"Nouveau solde\" => get words after \"Nouveau solde\" => right\r\nset negative marker \"Nouveau solde\"\r\n$closingBalance = get text in box @closingBalanceTop @closingBalanceBottom @closingBalanceLeft @closingBalanceRight => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line containing \"Solde précédent\"\r\n@header1 = get line starting \"Date Référence Débit Crédit Valeur\"\r\n\r\n// Column coordinates\r\n@dateRight = take words @header 1 => left => add 2\r\n@detailRight = take last words @header 2 => take words 1 => right => add 4\r\n@creditLeft = get words before @header1 \"Valeur\" => take last words 1 => left => subtract 10\r\n@creditRight = take last words @header1 1 => left => subtract 3\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n//added a line before transactionTop so that it will not execute only single period from multi period statements\r\nget last line starting \"Poste principal\"\r\n\r\n@transactionTop = get line starting \"Date Référence Débit Crédit Valeur\" => bottom => get line below\r\ngo to page 1\r\n@transactionBottom = get line containing \"Nouveau solde\" => top => get line above\r\n\r\n// Discard header and footer\r\n//get last line starting \"Date Référence Débit Crédit\" => top => ignore header above\r\nignore header above 700\r\nget last line starting \"BRED Banque Populaire\" => top => ignore footer below\r\nignore footer below 40\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Date N° de compte\"\r\ndelete all lines starting \"Date Référence Débit Crédit\"\r\ndelete all lines starting \"Total\"\r\ndelete all lines containing \"Solde précédent\"\r\ndelete all lines containing \"Nouveau solde\"\r\ndelete all lines starting \"Relevé d\'opérations\"\r\ndelete all lines starting \"Relevé de comptes\"\r\ndelete all lines starting \"BRED Banque Populaire\"\r\ndelete all lines containing \"Pour information\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom 0 73 @dateRight @detailRight @creditLeft @creditRight => describe table false \"*Date[dd.MM]\" - Details #Debit #Credit','2026-09-15 10:10:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10933,'Arbuthnot_Latham_Card','$source = \"Arbuthnot_Latham_Card\"\r\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE CREDIT_CARD\"\r\n\r\nset negative marker \"CR\"\r\n\r\n// Get Closing Balance\r\ngo to page 1\r\n$closingBalanceTopText = get line starting \"Payment Received\" => bottom => get line below\r\n$closingBalance = take words $closingBalanceTopText 2 => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n// Get Accounts\r\n$accountNumberText = get line containing \"Card Number:\" => get words after \"Card Number:\"\r\n$accountNumber = take words $accountNumberText 1 => get text\r\n$accountName = take words $accountNumberText 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFromText = get line starting \"Statement Period:\" => get words after \"Statement Period:\" => take words 3\r\n$periodFrom = take words $periodFromText 1 => get date \"d-MMM-yy\"\r\n$periodTo = take last words $periodFromText 1 => get date \"d-MMM-yy\"\r\n\r\n//Transaction Table starts here with dynamic coordinates\r\ngo to page 1\r\n$Date_left = get line containing \"Transaction Date Process Date\" => get words after \"Transaction Date\" => left => subtract 10\r\n$Date_right = get line containing \"Transaction Date Process Date\" => get words after \"Process Date\" => take words 1 => left => subtract 10\r\n$Description_right = get line containing \"Transaction Date Process Date\" => get words after \"Transaction Description\" => take words 1 => left => subtract 30\r\n$Paidout_right = get line containing \"Transaction Date Process Date\" => get words after \"Transaction Description Debits\" => take words 1 => left => subtract 30\r\n$Paidin_right = get line containing \"Transaction Date Process Date\" => get words after \"Transaction Description Debits\" => right => add 30\r\n\r\n$transactionsTop = get line containing \"Transaction Date Process Date\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line containing \"Number of transactions\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Transaction Date Process Date\"\r\nignore footer below 144\r\nignore header above 670\r\n\r\n$transactions = get multi page table $transactionsTop $transactionsBottom $Date_left $Date_right $Description_right $Paidout_right $Paidin_right => describe table false \"*Date[d-MMM-yy]\" Details #Credit #Debit','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10934,'Rogers_Bank_CreditCard','$source = \"Rogers_Bank_CreditCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 28\r\nremove page 2\r\n\r\n// Get Period\r\ngo to page 1\r\n$periodFrom = get line containing \"Statement Period\" => get words after \"Statement Period\" => take words 3 => get date \"MMM d, yyyy\"\r\n$periodTo = get line containing \"Statement Period\" => get words after \"-\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n// Get Accounts\r\ngo to page 1\r\n$accountName = get line containing \"Account Holder\" => get words after \"Account Holder\" => take words 2 => get text\r\n$accountNumberText = get line containing \"Account Number\" => get words after \"Account Number\"\r\n$accountNumber = take words $accountNumberText 4 => get text\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n\r\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"New Balance\" => get words after \"New Balance\" => take words 1 => get decimal\r\n\r\ngo to page 1\r\n@HeadersTop = get line containing \"AMOUNT NEW MINIMUM PAYMENT AMOUNT\" => if not found then blank => top\r\n$delHeaders = delete text in box @HeadersTop 0 page.left page.right => get text\r\n\r\n// Get start & end of transactions table\r\n@transactionsTop = get line containing \"Date Description Amount ($)\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get last line containing \"Interest Rate Chart\" => top => get line above\r\n\r\n// Remove unwanted lines\r\ndelete all lines containing \"Date Description Amount ($)\"\r\ndelete all lines containing \"Interest Rate Chart\"\r\ndelete all lines containing \"Card Number XXXX\"\r\ndelete all lines containing \"AMOUNT PAID\"\r\n\r\nignore header above 700\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 55 90 320 375 => describe table false \"Date[MMM d]\" Details *#Credit','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10935,'StandardBankAccountHolder_ReverseOrder','$source = \"StandardBankAccountHolder_ReverseOrder\"\r\n$features = \"REVERSE_ORDER NO_OPENING_BALANCE\"\r\n\r\nset culture \"en-ZA\"\r\n//$periodBufferDays = 45\r\n\r\n// Get account name and number\r\n$accountnumber = get line starting \"Account:\" => take last words 1 => get text\r\n$accountname = get line starting \"Account holder:\" => get words after \"Account holder:\" => get text\r\n\r\n// Get period from/to\r\n$periodfromTop = get line starting \"Transaction date\" => top\r\n$periodToBottom = get line starting \"Available balance\" => top\r\n$period = get text in box $periodfromTop $periodToBottom 122 390\r\n$periodFrom = get words before $period \"-\" => take last words 3 => get date \"d MMMM yyyy\"\r\n$periodTo = get words after $period \"-\" => take last words 3 => get date \"d MMMM yyyy\"\r\n\r\n//Get Closing Balance\r\n$closingBalanceTop = get line containing \"In (R) Out (R) Bank fees (R)\" => bottom => get line below => top\r\n$closingBalanceBottom =  get line containing \"In (R) Out (R) Bank fees (R)\" => bottom => get line below => bottom\r\n$closingBalanceText = get text in box $closingBalanceTop $closingBalanceBottom 485 page.right\r\n$closingBalance = take words $closingBalanceText 3 => get decimal\r\n\r\ngo to page 1\r\n// Get start of table\r\n@transactionsTop = get line containing \"In (R) Out (R) Bank fees (R)\" => if not found then blank => bottom => get line below\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"# These fees are zero rated\" => if not found then blank => top => get line above\r\n\r\nset negative marker \"-\"\r\n\r\n// Discard header and footer\r\ndelete all lines containing \"## These fees include VAT at the applicable\"\r\ndelete all lines containing \"Please verify all transactions reflected\"\r\ndelete all lines containing \"The Standard Bank of South Africa Limited\"\r\ndelete all lines starting \"Banking Practice of the Banking Association South Africa\"\r\ndelete all lines starting \"# These fees are zero rated\"\r\n\r\n// Read the transactions\r\n$transactions =  get multi page table center aligned @transactionsTop @transactionsBottom 4.5 40 105 305 360 425 488 600 => describe table false \"Date[dd MMMM yyyy]\" Details #Credit #Debit - #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10936,'FIRST_NATIONAL_BANK_PostDate','$source = \"FIRST_NATIONAL_BANK_PostDate\"\r\n$periodBufferDays = 31\r\nremove page 2\r\ndelete white words\r\n//Get Account Name\r\n$accountName = get text in box 662 650 0 page.middleX => take words 3 => get text\r\n\r\n// Get Account Number\r\n$accountNumber = get line containing \"Primary Account Number:\" => get words after \"Primary Account Number:\" => take words 1 => get text\r\n\r\n//Get periods\r\ngo to page 1\r\n$periodFrom = get line starting \"Post Date Description\" => bottom => get line below => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n$periodTo = get last line containing \"Balance This Statement\" => get words before \"Balance This Statement\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n//Get OpeningClosing Balance\r\ngo to page 1\r\n\r\n$openingBalance = get line starting \"Post Date Description\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n$closingBalance = get last line containing \"Balance This Statement\" => get words after \"Balance This Statement\" => take words 1 => get decimal\r\n\r\n//Get start of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Post Date Description Debits\" => bottom => get line below => bottom => get line below\r\n//Get end of table\r\n@transactionsBottom = get last line containing \"Balance This Statement\" => top => get line above\r\n\r\n//Discard header and footer\r\ndelete all lines starting \"Post Date Description Debits\"\r\ndelete all lines containing \"Balance Last Statement\"\r\ndelete all lines containing \"Balance This Statement\"\r\ndelete all lines containing \"(continued)\"\r\n\r\nignore header above 705\r\nignore footer below 40\r\n\r\n//Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 95 355 420 515 585 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10937,'Handelsbanken_Descending_MoneyInOut','$source = \"Handelsbanken_Descending_MoneyInOut\"\r\n$features = \"REVERSE_ORDER\"\r\n\r\n@summarytop = get line starting \"Account:\" => top\r\n@summarybottom = get line starting \"Date range:\" => bottom\r\n@summary = get text in box @summarytop @summarybottom 20 page.middleX\r\n\r\n$accountnumber = get words after @summary \"Account:\" => get words between \"Account:\" \"Account name:\" => get text\r\n$accountname = get words after @summary \"Account name:\" => take words 2 => get text\r\n\r\n$periodfrom = get words after @summary \"Date range:\" => get words between \"range:\" \"-\" => get date \"d MMM yyyy\"\r\n$periodto = get words after @summary \"-\"  => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n@infotop = get line starting \"Date Transaction details\" => bottom\r\n@infobottom = get line starting \"Date Transaction details\" => bottom => get line below => bottom\r\n$openingbalance = get text in box @infotop @infobottom 495 600 => get decimal\r\n\r\ngo to page 1\r\n@transactionstop = get line starting \"Date Transaction details Money out\" => bottom => get line below\r\n\r\n$closingbalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => get decimal\r\n\r\n@transactionsbottom = get line containing \"Opening balance\" => top => get line above\r\n\r\nignore footer below 32\r\nignore header above 702\r\n\r\n$transactions = get multi page table @transactionstop @transactionsbottom 20 80 345 400 495 600 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10938,'First_Northern_Bank','$source = \"First_Northern_Bank\"\r\n$periodBufferDays = 14\r\n\r\n// Get account details\r\ngo to page 1\r\n$accountName = get line containing \"Statement Ending\" => bottom => get line below => take words 3 => get text\r\n$accountNumber = get line containing \"Customer Number:\" => get words after \"Customer Number:\" => take words 1 => get text\r\n\r\n// Delete unwanted text\r\ngo to page 1\r\ndelete all lines ending \"Ending Balance\"\r\n@TEXTBOXTop = get line containing \"Beginning Balance\" => top\r\n@TEXTBOXBottom = get line containing \"Ending Balance\" => bottom\r\n@TEXTBOX = get text in box @TEXTBOXTop @TEXTBOXBottom 0 350\r\n\r\n// Get statement period\r\n$periodFrom = get words before @TEXTBOX \"Beginning Balance\" => take words 1  => get date \"MM/dd/yyyy\"\r\n$periodTo = get words before @TEXTBOX \"Ending Balance\"  => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\n// Get opening & closing Balance\r\n$openingBalance = get words after @TEXTBOX \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after @TEXTBOX \"Ending Balance\" => take words 1 => get decimal\r\n\r\nremove page 2\r\n\r\n// Get start & end of deposits table\r\ngo to page 1\r\n@depositsTop = get line starting \"Deposits\" => if not found then blank => bottom => get line below => bottom => get line below\r\n@depositsBottom = get line starting \"Other Credits\" => if not found then blank => top => get line above\r\n\r\n// Delete extra text\r\nignore header above 736\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines containing \"Customer Number:\"\r\ndelete all lines containing \"Statement Ending\"\r\ndelete all lines containing \"INTENTIONALLY BLANK\"\r\nignore footer below 15\r\n\r\n// Get deposits table\r\n@deposits = get multi page table @depositsTop @depositsBottom 30 90 500 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n\r\n// Get start & end of credits table\r\ngo to page 1\r\n@creditsTop1 = get line starting \"Other Credits\" => if not found then blank => bottom => get line below\r\n@creditsBottom1 = get line ending \"Debits\" => if not found then blank => top => get line above\r\n\r\n// Get credits table\r\n@credits = get multi page table @creditsTop1 @creditsBottom1 30 90 500 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n\r\n// Get start & end of debits table\r\ngo to page 1\r\n@debitsTop = get line ending \"Debits\" => bottom => get line below\r\n@debitsBottom = get line starting \"Daily Balances\" => if not found then blank => bottom => get line above\r\n\r\n// Delete extra text\r\ndelete all lines containing \"Other Debits\"\r\n\r\n// Get debits table\r\n@debits = get multi page table @debitsTop @debitsBottom 30 90 500 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\r\n\r\n// Combine transactions\r\n$transactions = combine described tables @deposits @credits @debits','2026-07-22 09:18:03',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10939,'Oxbury_Bank','$source = \"Oxbury_Bank\"\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\ndelete all lines starting \"Your Statement\"\r\n$accountName = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n@periodBottom = get line starting \"Date Type Description\" => take words 1 => top\r\n@periodText = get text in box page.top @periodBottom 0 page.middleX\r\n$periodFrom = get words before @periodText \"to\" => take last words 1 => get date \"dd-MM-yyyy\"\r\n$periodTo = get words after @periodText \"to\" => take last words 1 => get date \"dd-MM-yyyy\"\r\n\r\n// Get opening/closing balance\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Type Description\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@typeLeft = get words after @header \"Date\" => take words 1 => left => subtract 5\r\n@detailLeft = get words after @header \"Type\" => take words 1 => left => subtract 5\r\n@creditLeft = get words after @header \"Description\" => take words 1 => left => subtract 20\r\n@creditRight = get words before @header \"Paid Out\" => take last words 1 => right => add 5\r\n@debitRight = get words before @header \"Balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Date Type Description\" => bottom => get line below\r\n@goToLastPage = get last line starting \"Date Type Description\" => bottom\r\n@transactionBottom = get line above 0\r\n\r\n// Discard header and footer\r\nget last line starting \"Date Type Description\" => top => ignore header above\r\nignore footer below 90\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Date Type Description\"\r\ndelete all lines starting \"Oxbury Farm Credit\"\r\ndelete all lines starting \"Frontier Farm Credit\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionTop @transactionBottom @dateLeft @typeLeft @detailLeft @creditLeft @creditRight @debitRight @balanceRight => describe table false \"*Date[dd-MM-yyyy]\" TransactionType Details #Credit #Debit #Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10940,'Rocky_CreditUnion','$source = \"Rocky_CreditUnion\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\nset negative marker \"-\"\r\n\r\n// Get account details\r\n@accountBottom = get line starting \"Date Description Debits\" => top => get line above => top\r\n$accountName = get text in box page.top @accountBottom 0 page.middleX => take words 2 => get text\r\n@accountNumberTop = get line containing \"Account Number\" => get words after \"Account\" => top\r\n@accountNumberBottom = get line containing \"Account Number\" => get words after \"Account\" => bottom\r\n$accountNumber = get text in box @accountNumberTop @accountNumberBottom page.middleX page.right => take words 3 => get text\r\n\r\n// Delete account address text from the header section\r\n@accountRight = get line containing \"Period Beginning\" => get words before \"Beginning\" => take last words 1 => left\r\n@deleteAccountNameText = delete text in box page.top @accountBottom 0 @accountRight => get text\r\n\r\ngo to page 1\r\n// Get statement period (From / To)\r\n$periodFrom = get line containing \"Period Beginning\" => get words after \"Beginning\" => get date \"MMM dd yyyy\"\r\n@periodText = get line containing \"Period Beginning\" => get words after \"Period\"\r\n@periodLeft = take words @periodText 1 => right => add 3\r\n$periodTop = take words @periodText 1 => bottom\r\n$periodTo = get text in box $periodTop 0 @periodLeft page.right => take words 3 => get date \"MMM dd yyyy\"\r\n\r\n// Get opening and closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Balance Forward\" => take last words 1 => get decimal\r\n$closingBalance = 0\r\n\r\ngo to page 1\r\n@InterestRateLastSummaryTop = get last line starting \"Interest Rate Summary\" => top\r\n@InterestRateLastSummaryBottom = get line starting \"If this statement\" => top\r\n@deleteInterestRateLastSummary = delete text in box 