op\r\n@deleteInterestRateSummary2 = delete text in box @InterestRateSummaryTop2 @InterestRateSummaryBottom2 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 3\r\n@InterestRateSummaryTop3 = get line containing \"Date Rate Date\" => top\r\n@InterestRateSummaryBottom3 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary3 = delete text in box @InterestRateSummaryTop3 @InterestRateSummaryBottom3 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 4\r\n@InterestRateSummaryTop4 = get line containing \"Date Rate Date\" => top\r\n@InterestRateSummaryBottom4 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary4 = delete text in box @InterestRateSummaryTop4 @InterestRateSummaryBottom4 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 5\r\n@InterestRateSummaryTop5 = get line containing \"Date Rate Date\" => top\r\n@InterestRateSummaryBottom5 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary5 = delete text in box @InterestRateSummaryTop5 @InterestRateSummaryBottom5 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 6\r\n@InterestRateSummaryTop6 = get line containing \"Date Rate Date\" => top\r\n@InterestRateSummaryBottom6 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary6 = delete text in box @InterestRateSummaryTop6 @InterestRateSummaryBottom6 0 page.right => get text\r\n\r\ngo to page 1\r\n// Delete Interest Rate Summary section 7\r\n@InterestRateSummaryTop7 = get line containing \"Date Rate Date\" => top\r\n@InterestRateSummaryBottom7 = get line containing \"Date Rate Date\" => bottom => get line below => bottom => get line below => top\r\n@deleteInterestRateSummary7 = delete text in box @InterestRateSummaryTop7 @InterestRateSummaryBottom7 0 page.right => get text\r\n\r\ndelete all lines starting \"Interest Rate Summary\"\r\ndelete all lines starting \"Unauthorized\"\r\n\r\n//Get the end of the transaction\r\n@transactionsBottom = get last line starting \"If this statement\" => top => get line above\r\n\r\n// Delete non-transaction lines\r\ndelete all lines starting \"Deposit Account Interest\"\r\ndelete all lines starting \"Date Rate Date\"\r\ndelete all lines starting \"Servus and connectFirst\"\r\ndelete all lines starting \"If this statement\"\r\ndelete all lines containing \"Account Number:\"\r\ndelete all lines containing \"Page:\"\r\ndelete all lines starting \"Interest Paid YTD\"\r\ndelete all lines starting \"Interest Payments\"\r\ndelete all lines starting \"Principal Payments\"\r\ndelete all lines ending \"Interest Rate Summary\"\r\ndelete all lines starting \"There is no activity for this account\"\r\ndelete all lines ending \".000\"\r\n\r\ngo to page 1\r\n// Remove Credit Union inquiries section\r\n@creditUnionInquiriesTop = get line starting \"For all credit union inquiries\" => if not found then blank => bottom\r\n$deleteCUInquiriesBox = delete text in box @creditUnionInquiriesTop 0 0 page.right => get text\r\ndelete all lines starting \"For all credit union inquiries\"\r\ndelete all lines containing \"Balance Forward\"\r\ndelete all lines starting \"Date Description\"\r\ndelete all lines starting \"Rocky Credit Union\"\r\ndelete all lines starting \"For Lost or Stolen\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @details 370 420 500  => describe table false *TransactionType Details #Debit #Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10941,'CoastVisa_Card','$source = \"CoastVisa_Card\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR NO_OPENING_BALANCE\"\r\n\r\n//Get Periods\r\n$periodFromText = get line containing \"Payment Due:\" => top => get line above\r\n$periodFrom = take words $periodFromText 2 => get date \"MMM d\"\r\n$periodTo = get line containing \"Payment Due:\" => get words after \"Payment Due:\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n//Account details\r\n$accountName = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\r\n$accountNumber = get line containing \"Account number:\" => get words after \"Account number:\" => take words 1 => get text\r\n\r\ngo to page 1\r\n//Get Closing Balance\r\n$top = get line containing \"Total Outstanding Balance\" => top\r\n$bottom = get line containing \"Payments Applied to Previous\" => bottom\r\n$closingBalanceText = get text in box $top $bottom 510 page.right\r\n$closingBalance = take last words $closingBalanceText 2 => take words 1 => get decimal\r\n\r\ngo to page 1\r\n//Purchase Table Starts here\r\n@purchaseTop = get line starting \"Date User Vehicle\" => if not found then blank => bottom => get line below\r\n@purchaseBottom = get line starting \"Fees\" => if not found then blank => top => get line above\r\n\r\n//Fees Table Starts here\r\n@feesTop = get line starting \"Fees\" => if not found then blank => bottom => get line below\r\n@feesBottom = get line starting \"Total\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Date Type\"\r\n\r\n//Payments Table Starts here\r\n@paymentsTop = get line starting \"Payments\" => if not found then blank => bottom => get line below\r\n@paymentsBottom = get line starting \"Total\" => if not found then blank => top => get line above\r\n\r\n//Credits Table Starts here\r\n@creditsTop = get line starting \"Credits and Rewards\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get line starting \"Total\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Total\"\r\ndelete all lines containing \"Statement Period:\"\r\n\r\n$credits = get multi page table @creditsTop @creditsBottom 30 90 520 590 => describe table false \"Date[MMM d]\" Details *#Credit\r\n$purchase = get multi page table @purchaseTop @purchaseBottom 30 90 520 590 => describe table false \"Date[MMM d]\" Details *#Credit\r\n$fees = get multi page table @feesTop @feesBottom 30 90 520 590 => describe table false \"Date[MMM d]\" Details *#Credit\r\n$payments = get multi page table @paymentsTop @paymentsBottom 30 90 520 590 => describe table false \"Date[MMM d]\" Details *#Credit\r\n\r\n\r\n//Combined Transactions of all tables\r\n$transactions = combine described tables $purchase $fees $payments $credits','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10942,'JohnLewis_FinanceCard','$source = \"JohnLewis_FinanceCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n\r\n//Account details\r\n$accountName = get line containing \"Account number\" => get words after \"Account number\" => get text\r\n$accountNumber = get line containing \"Account number\" => get words after \"Account number\" => get text\r\n\r\n//Get Opening and Closing Balance\r\n$openingBalance = get line containing \"Previous balance\" => get words after \"Previous balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Your new balance\" => get words after \"Your new balance\" => take words 1 => get decimal\r\n\r\n//Get Periods\r\n$periodFrom = get line containing \"Previous balance -\" => get words after \"Previous balance -\" => take words 3 => get date \"d MMM yyyy\"\r\n$periodTo = get line containing \"New balance -\" => get words after \"New balance -\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\n//Transactions Table Starts here\r\n@transactionstop = get line starting \"Spend date Date processed\" => bottom => get line below\r\n@transactionsbottom = get line starting \"Your messages\" => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines starting \"John Lewis\"\r\ndelete all lines containing \"Page\"\r\nignore header above 702\r\ndelete all lines containing \"Transaction details\"\r\ndelete all lines containing \"Spend date Date processed\"\r\n\r\nset negative marker \"CR\"\r\n//Transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 115 182 258 498 570 => describe table false \"Date[d MMM]\" TransactionType Details *#Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10943,'ALTURA_CREDIT_UNION','$source = \"ALTURA_CREDIT_UNION\"\r\n$periodBufferDays = 31\r\nremove page 2\r\n// Get Accounts\r\ngo to page 1\r\n$AccountName = get text in box 625 610 page.left page.middleX => take words 3 => get text\r\n\r\ngo to page 1\r\n$AccountNumberTop = get line containing \"Account No. Statement Period\" => bottom\r\n$AccountNumberBottom = get line containing \"ACCOUNT SUMMARY\" => top\r\n$AccountNumberText = get text in box $AccountNumberTop $AccountNumberBottom page.middleX page.right\r\n$AccountNumber = take words $AccountNumberText 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFrom = take words $AccountNumberText 2 => take last words 1 => get date \"MM/dd/yy\"\r\n$periodTo = take words $AccountNumberText 4 => take last words 1 => get date \"MM/dd/yy\"\r\n\r\n//Get Closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Beginning Balance Deposits/Credits Withdrawals/Debits\" => bottom => get line below => take words 2 => get decimal\r\n$closingBalance = get line containing \"BASIC BUSINESS CHECKING\" => take last words 1 => get decimal\r\n//ignore header above 705\r\ndelete all lines containing \"Thru\"\r\ndelete all lines containing \"Account No.\"\r\n// Get start of table\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Withdrawal Deposit Balance Transaction Description\" => bottom => get line below\r\n// Get end of table\r\n@transactionsBottom = get last line containing \"Reporting Information for\" => if not found then blank => top => get line above\r\n// Discard header and footer\r\ngo to page 1\r\ndelete all lines containing \"Date Withdrawal Deposit Balance Transaction Description\"\r\ndelete all lines containing \"Reporting Information for\"\r\ndelete all lines containing \"BASIC BUSINESS CHECKING\"\r\ndelete all lines containing \"Transaction\"\r\ndelete all lines containing \"Posting\"\r\ndelete all lines containing \"Total Interest Paid Year to Date:\"\r\ndelete all lines containing \"(continued)\"\r\ndelete all lines containing \"Tray1\"\r\ndelete all lines containing \"P.O.\"\r\ndelete all lines containing \"Riverside,\"\r\ndelete all lines containing \"Phone:\"\r\ndelete all lines containing \"To inquire\"\r\nignore footer below 22\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 25 80 140 255 305 570 => describe table false - \"Date[MM/dd/yy]\" #Credit *#Balance Details','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10944,'IbSettle_Bank','$source = \"IbSettle_Bank\"\r\n\r\n// Get Accounts\r\n$accountNumber = get line starting \"Account\" => get words between \"Account\" \"(\" => get text\r\n$accountName = get line starting \"Account\" => get words between \"Account\" \"(\" => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFromText = get line containing \"Period:\" => get words after \"from\"\r\n$periodFrom = take words $periodFromText 1 => get date \"yyyy-M-d\"\r\n$periodTo = take last words $periodFromText 1 => get date \"yyyy-M-d\"\r\n\r\n// Get Opening Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening balance:\" => get words after \"Opening balance:\" => get decimal\r\n$closingBalance = get line containing \"Closing balance:\" => get words after \"Closing balance:\" => get decimal\r\n\r\n//Transactions Tables starts here\r\ngo to page 1\r\n$transactionsTop = get line containing \"Reference No Date Account\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line starting \"Page\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\nignore footer below 50\r\nignore header above 760\r\n\r\nset negative marker \"-\"\r\n//Read Transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 50 115 208 365 440 560 => describe table false \"*Date[yyyy-M-d]\" TransactionType Details #Debit #Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10945,'MandT_CreditCard','$source = \"MandT_CreditCard\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\n@DeletePanelLeft = get line containing \"Payment Information\" => get words before \"Information\" => take last words 1 => left\r\n@DeletePanel = delete text in box page.top 0 @DeletePanelLeft 650\r\n\r\n$AccountNumber = get line containing \"Account Number Ending:\" => get words after \"Ending:\" => get text\r\n\r\ngo to page 1\r\n$AccountName = get line starting \"Previous Balance\" => top => get line above => top => get line above => top => get line above => get text\r\n$OpeningBalance = get line starting \"Previous Balance\" => get words after \"Balance\" => get decimal\r\n$ClosingBalance = get line starting \"New Balance\" => get words after \"Balance\" => get decimal\r\n$PeriodTo = get line starting \"Closing Date\" => get words after \"Date\" => get date \"M d yyyy\"\r\n\r\n$PeriodFrom = get line containing \"Post Tran Reference\" => bottom => get line below  => bottom => get line below => skip words 1 => take words 1 => get date \"MM d\"\r\n@TransactionsTop = get line containing \"Post Tran Reference\" => bottom => get line below\r\n@TransactionsBottom = get last line containing \"Year-to-Date Totals\" => top => get line above\r\n\r\ndelete all lines containing \"Ending in:\"\r\ndelete all lines starting \"Subtotal:\"\r\ndelete all lines starting \"Interest Charged\"\r\ndelete all lines starting \"TOTAL INTEREST FOR THIS PERIOD\"\r\n\r\nignore footer below 35\r\nignore header above 709\r\n\r\n$transactions = get multi page table @TransactionsTop @TransactionsBottom 45 72 102 450 650 => describe table false \"*Date[MM d]\" - Details #Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10946,'MFC_NedBank','$source = \"MFC_NedBank\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 45\r\n\r\n// Get Accounts\r\n$AccountName = get line containing \"MFC, a division of Nedbank\" => get words before \"MFC\" => take words 3 => get text\r\n$AccountNumber = get line containing \"Account no:\" => get words after \"Account no:\" => take words 1 => get text\r\n\r\n// Get Periods\r\n$PeriodFrom = get line containing \"Statement period:\" => get words after \"Statement period:\" => take words 1 => get date \"yyyy/MM/dd\"\r\n$PeriodTo = get line containing \"Statement period:\" => get words after \"Statement period:\" => take last words 1 => get date \"yyyy/MM/dd\"\r\n\r\n// Get opening and closing balances\r\n$OpeningBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take last words 1 => get decimal\r\n$ClosingBalance = get line containing \"Closing balance\" => get words after \"Closing balance\" => take last words 1 => get decimal\r\n\r\n//Transaction Table starts here with dynamic coordinates\r\ngo to page 1\r\n$Date_left = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words before \"Transactions\" => left => subtract 20\r\n$Description_left = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words after \"Date\" => take words 1 => left => subtract 20\r\n$Debit_left = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words after \"Transactions\" => take words 1 => left => subtract 20\r\n$Credit_left = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words after \"Debit(R)\" => left => subtract 20\r\n$Balance_left = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words after \"Credit(R)\" => left => subtract 30\r\n$Balance_right = get line containing \"Date Transactions Debit(R) Credit(R) Balance(R)\" => get words after \"Credit(R)\" => right => add 50\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transactions Debit(R)\" => bottom => get line below\r\ndelete all lines containing \"Opening balance\"\r\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\nignore header above 660\r\nignore footer below 80\r\n\r\ndelete all lines containing \"Closing balance\"\r\ndelete all lines containing \"Authorised financial services and registered credit provider\"\r\ndelete all lines containing \"Page\"\r\ndelete all lines containing \"Date Transactions Debit(R)\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom $Date_left $Description_left $Debit_left $Credit_left $Balance_left $Balance_right => describe table false \"*Date[yyyy/MM/dd]\" Details #Credit #Debit #Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10947,'SkylightPayCard','$source = \"SkylightPayCard\"\r\n\r\n$periodBufferDays = 45\r\n\r\n// Get Accounts\r\n$AccountName = get text in box page.top 685 480 page.right => take words 2 => get text\r\n$AccountNumber = get line containing \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\n// Get Periods\r\n$PeriodFrom = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take words 3 => get date \"MMM d, yyyy\"\r\n$PeriodTo = get line starting \"Ending Balance on\" => get words after \"Ending Balance on\" => take words 3 => get date \"MMM d, yyyy\"\r\n\r\n// Get opening and closing balances\r\n$OpeningBalance = get line starting \"Beginning Balance on\" => get words after \"Beginning Balance on\" => take last words 1 => get decimal\r\n$ClosingBalance = get line starting \"Ending Balance on\" => get words after \"Ending Balance on\" => take last words 1 => get decimal\r\n\r\n// Get start & end of Deposits and Credits\r\ngo to page 1\r\n@creditsTop = get last line starting \"Deposits and Credits\" => bottom => get line below => bottom => get line below\r\n@creditsBottom = get last line starting \"Total Deposits and Credits\" => top => get line above\r\n@credits = get multi page table @creditsTop @creditsBottom 40 92 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Credit\r\n\r\n// Get start & end of Withdrawals and Debits\r\ngo to page 1\r\n@debitsTop = get last line starting \"Withdrawals and Debits\" => bottom => get line below => bottom => get line below\r\n@debitsBottom = get last line starting \"Total Withdrawals and Debits\" => top => get line above\r\n@debits = get multi page table @debitsTop @debitsBottom 40 92 525 580 => describe table false \"Date[MM/dd/yyyy]\" Details *#Debit\r\n\r\n// Discard header and footer\r\nignore header above 750\r\nignore footer below 50\r\ndelete all lines containing \"Deposits and Credits\"\r\ndelete all lines containing \"Total Deposits and Credits\"\r\ndelete all lines containing \"Withdrawals and Debits\"\r\ndelete all lines containing \"Total Withdrawals and Debits\"\r\ndelete all lines containing \"Description Amount\"\r\ndelete all lines containing \"Posted\"\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @credits @debits','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10948,'Regions_CreditCard','$source = \"Regions_CreditCard\"\r\n$features = \"CREDIT_CARD NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 45\r\nset negative marker \"CR\"\r\n\r\n// Account Details\r\ngo to page 1\r\n@AcctTop = get line starting \"with Relationship Rewards\" => bottom\r\n@AcctBottom = get line starting \"Company Summary\" => top\r\n$accountname = get text in box @AcctTop @AcctBottom page.left 225 => take words 2 => get text\r\n$accountNumber = get text in box @AcctTop @AcctBottom page.left 225 => get words after \"Number\" => take words 4 => get text\r\n\r\n// Statement Period\r\n$periodto = get line containing \"Company Summary\" => top => get line above => get words after \"-\" => get date \"MMM d yyyy\"\r\n$periodfrom = get line containing \"Company Summary\" => top => get line above => get words before \"-\" => get date \"MMM d\"\r\n\r\n// Opening & Closing Balance\r\ngo to page 1\r\n$openingbalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => get decimal\r\n$closingbalance = get line containing \"New Balance\" => get words after \"New Balance\" => get decimal\r\n\r\n// Delete Unwanted Text\r\ngo to page 1\r\n@deleteTop = get line starting \"Cardholder New Activity Summary\" => bottom\r\n@deleteBottom = get line containing \"Total Activity\" => top\r\ndelete text in box @deleteTop @deleteBottom 0 page.right\r\n@deleteTop2 = get line containing \"Upcoming Changes\" => bottom\r\n@deleteBottom2 = get line containing \"choosing Regions\" => top\r\ndelete text in box @deleteTop2 @deleteBottom2 0 page.right\r\n\r\n// Table Top & Bottom\r\ngo to page 1\r\n@transactionstop = get line containing \"Category Reference Number\" => bottom => get line below\r\nget last line containing \"Category Reference Number\"\r\n@transactionsbottom = get line above 10\r\n\r\n// Delete Unwanted Text\r\ndelete all lines containing \"Cardholder New Activity Summary\"\r\ndelete all lines containing \"Total Activity\"\r\ndelete all lines containing \"Account Number\"\r\ndelete all lines containing \"Credit Limit\"\r\ndelete all lines containing \"Tran Post\"\r\ndelete all lines containing \"Category Reference Number\"\r\ndelete all lines containing \"Upcoming Changes\"\r\ndelete all lines containing \"choosing Regions\"\r\ndelete all lines containing \"(continued)\"\r\nignore header above 744\r\n\r\n// Read Transactions\r\n$transactions = get multi page table @transactionstop @transactionsbottom 48 80 115 450 570 => describe table false \"*Date[MM/dd]\" - Details #Credit','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10949,'Fire_Bank','$source = \"Fire_Bank\"\r\nset negative marker \"(\"\r\n\r\n// Get account details\r\ngo to page 1\r\n@TEXTBOXBottom = get line containing \"Opening Balance\" => top => get line above => top\r\n@TEXTBOX = get text in box page.top @TEXTBOXBottom 0 page.middleX\r\n$accountName = get words before @TEXTBOX \"IBAN:\" => take words 2 => get text\r\n$accountNumber = get words after @TEXTBOX \"IBAN:\" => take words 1 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"DESCRIPTION AMOUNT CHARGES\" => bottom => get line below => get words after \"DAY,\" => get date \"MMMM d yyyy\"\r\n$periodTo = get last line containing \"DAY,\" => get words after \"DAY,\" => get date \"MMMM d yyyy\"\r\n\r\n// Get opening & closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => get decimal\r\n$closingBalance = get line starting \"Closing Balance\" => get words after \"Closing Balance\" => get decimal\r\n\r\n// Get start & end of transactions table\r\ngo to page 1\r\n@transactionsTop = get line starting \"DESCRIPTION AMOUNT CHARGES\" => bottom => get line below\r\n@transactionsBottom = get last line starting \"Fire Financial Services Limited\" => top => get line above\r\n\r\n// Delete extra text\r\nignore header above 712\r\nignore footer below 40\r\n\r\n// Combine transactions\r\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 7.9 0 300 445 515 580 => describe table false Details - #Credit #Balance','2026-08-10 09:09:52',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10950,'NedBank_SouthAfrika','$source = \"NedBank_SouthAfrika\"\r\n$periodBufferDays = 30\r\n\r\n//Account Details\r\ngo to page 1\r\n$accountName = get text in box 745 730 page.left page.middleX => take words 3 => get text\r\n$accountnumber = get line containing \"Rekeningnommer\" => bottom => get line below => take last words 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodfrom = get line containing \"Tydperk van staat:\" => get words after \"Tydperk van staat:\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodto = get line containing \"Tydperk van staat:\" => get words after \"Tydperk van staat:\" => take words 3 => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\n//OpeningClosingBalance\r\n$openingbalance = get line containing \"Beginsaldo\" => get words after \"Beginsaldo\" => take last words 1 => get decimal\r\n$closingbalance = get line containing \"Eindsaldo\" => get words after \"Eindsaldo\" => take last words 1 => get decimal\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line starting \"Tran-lys-nr Datum Beskrywing Geld (R) Debiete (R) Krediete (R) Saldo (R)\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get line containing \"Eindsaldo\" => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Tran-lys-nr Datum Beskrywing Geld (R) Debiete (R) Krediete (R) Saldo (R)\"\r\ndelete all lines containing \"Beginsaldo\"\r\ndelete all lines containing \"Eindsaldo\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 90 140 295 364 434 520 570 => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10951,'MUFG_Bank','$source = \"MUFG_Bank\"\r\n$periodBufferDays = 30\r\nset culture \"de-DE\"\r\n\r\n//Account Details\r\ngo to page 1\r\n$accountnumber = get line containing \"Kontonummer\" => get words after \"Kontonummer\" => take words 1 => get text\r\n$accountname = get line containing \"Kontonummer\" => top => get line above => take words 3 => take last words 2 => get text\r\n\r\n//OpeningClosingBalance\r\n$openingbalance = get line containing \"Vorheriger Kontosaldo\" => get words after \"Vorheriger Kontosaldo\" => take last words 1 => get decimal\r\n$closingbalance = get line containing \"Aktueller Kontosaldo\" => get words after \"Aktueller Kontosaldo\" => take last words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodfromTop = get line containing \"Vorheriger Kontosaldo\" => top\r\n$periodFrom = get text in box $periodfromTop 0 50 90 => take words 1 => get date \"dd MM yy\"\r\ngo to last page\r\n$periodToBottom = get last line containing \"Aktueller Kontosaldo\" => top\r\n$periodTo = get text in box page.top $periodToBottom 50 90 => take last words 1 => get date \"dd MM yy\"\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line starting \"Buchungsdatum Valutadatum Buchungsinformation Umsatz\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get line containing \"Aktueller Kontosaldo\" => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Buchungsdatum Valutadatum Buchungsinformation Umsatz\"\r\ndelete all lines containing \"Aktueller Kontosaldo\"\r\ndelete all lines containing \"Vorheriger Kontosaldo\"\r\n\r\n//Get transactions\r\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 2.5 55 115 159 500 565 => describe table false \"Date[dd MM yy]\" - Details #Credit','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10952,'Banistmo_Bank','$source = \"Banistmo_Bank\"\r\n$periodbufferdays = 14\r\n// Get Accounts\r\n$accountNumberText = get line starting \"CUENTA:\" => get words after \"CUENTA:\"\r\n$accountNumber = take words $accountNumberText 1  => get text\r\n$accountName = take words $accountNumberText 1  => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFromText = get line containing \"DESDE:\" => get words after \"DESDE:\"\r\n$periodFrom = take words $periodFromText 1 => get date \"yyyy-M-d\"\r\n$periodToText = get line containing \"HASTA:\" => get words after \"HASTA:\"\r\n$periodTo = take words $periodToText 1 => get date \"yyyy-M-d\"\r\n\r\n// Get Opening and Closing Balance\r\n$BalanceText = get line containing \"SALDO INICIAL:\" => get words after \"SALDO INICIAL:\"\r\n$OpeningBalance = take words $BalanceText 1 => get decimal\r\n$ClosingBalance = take last words $BalanceText 1 => get decimal\r\n\r\n//Transactions Tables starts here\r\ngo to page 1\r\n$transactionsTop = get line containing \"FECHA DESCRIPCIÓN DÉBITO\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line starting \"SALDO INICIAL:\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\nignore header above 615\r\ndelete all lines containing \"FECHA DESCRIPCIÓN\"\r\n\r\n//Read Transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 17 78 228 309 390 450 => describe table false \"*Date[yyyy-M-d]\" Details #Debit #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10953,'Banesco_Contigo_Bank','$source = \"Banesco_Contigo_Bank\"\r\n\r\n// Get account number/name\r\n$accountNumber = get line starting \"Numero de cuenta:\" => get words after \"Numero de cuenta:\" => take words 1 => get text\r\n$accountName = get line starting \"Nombre cliente:\" => get words after \"Nombre cliente:\" => take words 1 => get text\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Saldo inicial\" => get words after \"Saldo inicial\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Saldo al final del periodo\" => get words after \"Saldo al final del periodo\" => take words 1 => get decimal\r\n\r\n// Get statement period from\r\n@periodFromText = get line starting \"Fecha Referencia Descripción\"\r\n@periodFromTop = take words @periodFromText 1 => bottom\r\n@periodFromRight = take words @periodFromText 1 => right => add 3\r\n$periodFrom = get text in box @periodFromTop 0 0 @periodFromRight => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Fecha Referencia Descripción\"\r\n\r\n// Column coordinates\r\n@dateRight = take words @header 1 => right => add 3\r\n@referenceRight = get words after @header \"Fecha\" => take words 1 => right => add 12\r\n@detailsRight = get words after @header \"Descripción\" => take words 1 => left => subtract 2\r\n@checkRight = get words before @header \"Débito\" => take last words 1 => right => add 5\r\n@creditLeft = get words after @header \"Débito\" => take words 1 => left => subtract 5\r\n@balanceLeft = take last words @header 1 => left => subtract 5\r\n@balanceRight = take last words @header 1 => right => add 50\r\n\r\ngo to page 1\r\n@deleteFooterTop = get last line starting \"N° Impuestos\" => if not found then blank => bottom\r\n@deleteFooter = delete text in box @deleteFooterTop 0 0 page.right => get text\r\ndelete all lines starting \"N° Impuestos\"\r\n\r\n// Get statement period to\r\ngo to page 1\r\n@periodToText = get last line starting \"Fecha Referencia\"\r\n@periodToTop = take words @periodToText 1 => bottom\r\n@periodToRight = take words @periodToText 1 => right => add 3\r\n$periodTo = get text in box @periodToTop 0 0 @periodToRight => take last words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionTop = get line starting \"Fecha Referencia Descripción\" => bottom => get line below\r\n@goTransactionBottom = get last line starting \"Fecha Referencia Descripción\" => bottom => get line below\r\n@transactionBottom = get line above 0\r\n\r\n// Discard header and footer\r\nget last line starting \"Fecha Referencia Descripción\" => top => ignore header above\r\nget last line starting \"Página\" => top => ignore footer below\r\nignore footer below 90\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Fecha Referencia Descripción\"\r\ndelete all lines starting \"Detalle de cuenta\"\r\ndelete all lines starting \"Página\"\r\ndelete all lines ending \"www.banesco.com.pa\"\r\ndelete all lines starting \"Numero de cuenta:\"\r\ndelete all lines starting \"Nombre cliente:\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionTop @transactionBottom 5 0 @dateRight @referenceRight @detailsRight @checkRight @creditLeft @balanceLeft @balanceRight => describe table false \"*Date[dd/MM/yyyy]\" TransactionType Details #ChequeNumber #Debit #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10954,'Barclays_AccountStatements','$source = \"Barclays_AccountStatements\"\r\n\r\n@SummaryBottom = get line starting \"Transaction Summary\" => top\r\n@Summary = get text in box page.top @SummaryBottom 0 page.middleX\r\n\r\n$AccountName = get words before @Summary \"-\" => take words 3 => get text\r\n$AccountNumber = get words after @Summary \"-\" => take words 1 => get text\r\n\r\n@AccountNumberText = get words after @Summary \"-\" => take words 1\r\n@PeriodFromTop = bottom @AccountNumberText\r\n@PeriodFromBottom = bottom @AccountNumberText => get line below => bottom\r\n@Dates = get text in box @PeriodFromTop @PeriodFromBottom 0 page.middleX\r\n\r\n$PeriodFrom = get words before @Dates \"-\" => get date \"d MM yyyy\"\r\n$PeriodTo = get words after @Dates \"-\" => get date \"d MM yyyy\"\r\n\r\n@Header = get line starting \"Description Transaction Type Transaction\"\r\n@DescriptionLeft = take words @Header 1 => left => subtract 10\r\n@TransactionTypeLeft = get words after @Header \"Description\" => take words 1 => left => subtract 2\r\n@TransactionDateLeft = get words after @Header \"Transaction Type\" => take words 1 => left => subtract 5\r\n@StatementDateLeft = get words after @Header \"Type Transaction\" => take words 1 => left => subtract 5\r\n@StatementDateRight = get words after @Header \"Type Transaction\" => take words 1 => right => add 10\r\n@CreditRight = get words after @Header \"Statement\" => take words 1 => right => add 5\r\n@DebitRight = get words after @Header \"Credit\" => take words 1 => right => add 5\r\n@BalanceRight = get words after @Header \"Debit\" => take words 1 => right => add 5\r\n\r\n$OpeningBalance = get line starting \"Opening Balance\" => get words after \"Opening Balance\" => skip words 1 => take words 1 => get decimal\r\n\r\n@TransactionsTop = get line starting \"Opening Balance\" => bottom => get line below\r\n\r\n$ClosingBalance = get line starting \"Closing Balance\" => get words after \"Closing Balance\" => skip words 1 => take words 1 => get decimal\r\n\r\n@TransactionsBottom = get last line starting \"Closing Balance\" => top => get line above\r\n\r\ndelete all lines starting \"Description Transaction Type\"\r\ndelete all lines starting \"Date Date\"\r\nignore header above 480\r\nignore footer below 78\r\n\r\n$Transactions = get multi page table @TransactionsTop @TransactionsBottom @DescriptionLeft @TransactionTypeLeft @TransactionDateLeft @StatementDateLeft @StatementDateRight @CreditRight @DebitRight @BalanceRight => describe table false Details TransactionType \"*Date[d MM yyyy]\" - #Credit #Debit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10955,'Security_State_Bank_And_Trust','$source = \"Security_State_Bank_And_Trust\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$PeriodBufferDays = 30\r\nremove page 2\r\n\r\n//Account Details\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n$accountName = get line containing \"Account Owner(s):\" => get words after \"Account Owner(s):\" => get text\r\n\r\n// Get Periods\r\n$periodFrom = get line containing \"Beginning Balance as of\" => get words after \"Beginning Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get line containing \"Ending Balance as of\" => get words after \"Ending Balance as of\" => take words 1 => get date \"MM/dd/yyyy\"\r\n\r\n//OpeningClosingBalance\r\n$openingBalance = get line containing \"Beginning Balance as of\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Ending Balance as of\" => take last words 1 => get decimal\r\ndelete text in box on every page page.top page.bottom 0 49\r\nignore header above 691\r\nignore footer below 25\r\n// Get start & end of Credits\r\ngo to page 1\r\n@CreditsTop = get line starting \"DEPOSITS AND OTHER CREDITS\" => if not found then blank => bottom => get line below\r\ndelete all lines containing \"DEPOSITS AND OTHER CREDITS\"\r\ndelete all lines containing \"Date Description Deposits\"\r\ndelete all lines containing \"Helping Build Communities We Call\"\r\n@CreditsBottom = get line containing \"DEBITS AND OTHER WITHDRAWALS\" => if not found then blank => top => get line above\r\n$Credits = get multi page table @CreditsTop @CreditsBottom 50 85 505 575 => describe table false \"*Date[MMM dd]\" Details #Credit\r\n\r\n// Get start & end of Debits\r\ngo to page 1\r\n@DebitsTop = get line starting \"DEBITS AND OTHER WITHDRAWALS\" => if not found then blank => bottom => get line below\r\ndelete all lines containing \"DEBITS AND OTHER WITHDRAWALS\"\r\ndelete all lines containing \"Date Description Withdrawals\"\r\n\r\n@DebitsBottom = get line containing \"ATM/POS TRANSACTION SUMMARY\" => if not found then blank => top => get line above\r\n$Debits = get multi page table @DebitsTop @DebitsBottom 50 85 505 575 => describe table false \"*Date[MMM dd]\" Details #Debit\r\n\r\n\r\n// Get Transactions\r\ngo to page 1\r\n@TransactionsTop = get line starting \"ATM/POS TRANSACTION SUMMARY\" => if not found then blank => bottom => get line below\r\ndelete all lines containing \"ATM/POS TRANSACTION SUMMARY\"\r\ndelete all lines containing \"Date Description Deposits Withdrawals\"\r\n\r\n@TransactionsBottom = get line containing \"CHECKS PAID\" => if not found then blank => top => get line above\r\n$ATMPOS = get multi page table @TransactionsTop @TransactionsBottom 50 85 433 500 575 => describe table false \"*Date[MMM dd]\" Details #Credit #Debit\r\n\r\n//Checks\r\n\r\ngo to page 1\r\n@checksTop = get line starting \"CHECKS PAID\" => if not found then blank => bottom => get line below\r\ndelete all lines containing \"Date Check No. Amount\"\r\ndelete all lines containing \"CHECKS PAID\"\r\n@checksBottom = get last line containing \"DAILY BALANCE SUMMARY\" => top => get line above\r\ndelete all lines containing \"DAILY BALANCE SUMMARY\"\r\ngo to page 1\r\n$checksLeft = get multi page table @checksTop @checksBottom 50 105 175 215 => describe table false \"*Date[MMM dd]\" ChequeNumber #Debit\r\n$checksMiddle = get multi page table @checksTop @checksBottom 225 275 345 390 => describe table false \"*Date[MMM dd]\" ChequeNumber #Debit\r\n$checksRight = get multi page table @checksTop @checksBottom 400 450 520 570 => describe table false \"*Date[MMM dd]\" ChequeNumber  #Debit\r\n\r\n$transactions = combine described tables $Credits $Debits $ATMPOS $checksLeft $checksMiddle $checksRight','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10956,'LCL_French','$source = \"LCL_French\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 30\r\nset culture \"fr-CA\"\r\n//Account Details\r\ngo to page 1\r\n$AccountName = get line containing \"Titulaire du compte\" => bottom => get line below => take words 3 => get text\r\n$AccountNumber = get line containing \"Banque Indicatif N° de compte Clé\" => bottom => get line below => take words 4 => take last words 2 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFrom = get line containing \"RELEVE DE COMPTE COURANT\" => top => get line below => get words after \"du\" => take words 1 => get date \"dd.MM.yyyy\"\r\n$periodTo = get line containing \"RELEVE DE COMPTE COURANT\" => top => get line below => get words after \"au\" => take words 1 => get date \"dd.MM.yyyy\"\r\n\r\n//Opening Closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"ANCIEN SOLDE\" => get words after \"ANCIEN SOLDE\" => get decimal\r\n$closingBalance = get line containing \"SOLDE EN EUROS\" => get words after \"SOLDE EN EUROS\" => get decimal\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line starting \"DATE LIBELLE VALEUR DEBIT CREDIT\" => bottom => get line below => bottom => get line below\r\ndelete all lines containing \"ANCIEN SOLDE\"\r\ndelete all lines containing \"TOTAUX\"\r\ndelete all lines containing \"SOLDE INTERMEDIAIRE A FIN\"\r\n@transactionsBottom = get line containing \"SOLDE EN EUROS\" => top => get line above\r\n\r\nignore header above 670\r\nignore footer below 45\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"DATE LIBELLE VALEUR DEBIT CREDIT\"\r\ndelete all lines containing \"SOLDE EN EUROS\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 35 68 360 430 500 565 => describe table false \"*Date[dd.MM]\" Details - #Debit #Credit','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10957,'Horse_Racing_Ireland','$source = \"Horse_Racing_Ireland\"\r\n$periodBufferDays = 30\r\n\r\n//Account Details\r\ngo to page 1\r\n$accountName = get text in box 790 775 page.left page.middleX => take words 3 => get text\r\n$accountNumber = get line containing \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFrom = get line containing \"Brought Forward Balance\" => top => get line below => take words 3 => get date \"dd MMM yyyy\"\r\n$periodTo = get line containing \"Statement Date\" => get words after \"Statement Date\" => take words 3 => get date \"dd MMM yyyy\"\r\n\r\n//Opening Closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Brought Forward Balance\" => get words after \"Brought Forward Balance\" => take last words 1 => get decimal\r\n$closingBalance = get line containing \"Balance Carried Forward €\" => get words after \"Balance Carried Forward €\" => take last words 1 => get decimal\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date Transaction Details Debit € Credit € Balance €\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get line containing \"Balance Carried Forward €\" => top => get line above\r\n\r\nignore header above 620\r\nignore footer below 95\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Date Transaction Details Debit € Credit € Balance €\"\r\ndelete all lines containing \"Brought Forward Balance\"\r\ndelete all lines containing \"Balance Carried Forward €\"\r\ndelete all lines containing \"Subtotal €\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 15 100 400 460 530 600 => describe table false \"Date[dd MMM yyyy]\" Details #Debit #Credit *#Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10958,'INTEGRITY_Bank','$source = \"INTEGRITY_Bank\"\r\n\r\n// Get Accounts\r\n$accountNumberText = get line starting \"Account No.\" => bottom => get line below\r\n$accountNumber = take words $accountNumberText 1 => get text\r\n$accountName = take words $accountNumberText 1 => get text\r\n\r\n// Get Periods\r\ndelete text in box on every page page.top page.bottom page.left 50\r\n//delete text in box page.top page.bottom page.left 50\r\n\r\ngo to page 1\r\n$top = get line containing \"Balance Forward\" => top\r\n$bottom = get line containing \"Ending Balance\" => bottom\r\n$BalDetails = get text in box $top $bottom page.left page.right\r\n\r\n$periodFrom = get words after $BalDetails \"Balance Forward From\" => take words 1 => get date \"M/d/yy\"\r\n$openingBalance = get words after $BalDetails \"Balance Forward From\" => take words 2 => take last words 1 => get decimal\r\n\r\n$periodTo = get words after $BalDetails \"Ending Balance On\" => take words 1 => get date \"M/d/yy\"\r\n$closingBalance = get words after $BalDetails \"Ending Balance On\" => take words 2 => take last words 1 => get decimal\r\n\r\n//Transactions Tables starts here\r\ngo to page 1\r\n$transactionsTop = get line containing \"Amount Balance\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line starting \"DAILY BALANCE SUMMARY\" => if not found then blank => bottom => get line above\r\n\r\n$dlttop = get line containing \"CHECKS AND OTHER DEBITS\" => top\r\n$dltbot = get line starting \"DAILY BALANCE SUMMARY\" => top\r\n$dlt = delete text in box $dlttop $dltbot page.left page.right\r\n\r\n//Delete extra lines\r\nignore footer below 33\r\nignore header above 692\r\ndelete all lines containing \"Check/Description\"\r\n\r\n//Read Transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 51 120 445 500 590 => describe table false \"*Date[M/d/yy]\" Details #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10959,'BNP_Paribas_CashFlow','$source = \"BNP_Paribas_CashFlow\"\r\n\r\n// Get account name/number\r\n$accountName = get line containing \"Bank name\" => get words after \"Bank name\" => take words 3 => get text\r\n@accountNameLine = get line containing \"Bank name\" => bottom => get line below\r\n$accountNumber = get words after @accountNameLine \"Account\" => take words 1 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodFrom = get line starting \"ACCOUNT STATEMENT\" => get words before \"-\" => take last words 1 => get date \"dd/MM/yyyy\"\r\n$periodTo = get line starting \"ACCOUNT STATEMENT\" => get words after \"-\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Opening balance\" => get words after \"Opening balance\" => take last words 1 => get decimal\r\n$closingBalance = get last line containing \"Closing balance\" => get words after \"Closing balance\" => take last words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Entry date Value date Description\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@date1Left = get words after @header \"Entry date\" => take words 1 => left\r\n@detailLeft = get words after @header \"Value date\" => take words 1 => left => subtract 5\r\n@typeLeft = get words after @header \"Description\" => take words 1 => left => subtract 5\r\n@amountLeft = take last words @header 2 => take words 1 => left => subtract 10\r\n@amountRight = take last words @header 2 => take words 1 => right => add 10\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Entry date Value date Description\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Entry date Value date Description\" => top => ignore header above\r\nget last line starting \"BNP Paribas\" => top => add 3 => ignore footer below\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Account statement\"\r\ndelete all lines containing \"Printed on:\"\r\ndelete all lines starting \"Entry date Value date Description\"\r\ndelete all lines containing \"Opening balance\"\r\ndelete all lines containing \"Closing balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table center aligned @transactionsTop @transactionsBottom 10 @dateLeft @date1Left @detailLeft @typeLeft @amountLeft @amountRight @balanceRight => describe table false \"Date[dd/MM/yyyy]\" - Details TransactionType #Credit #Balance','2026-08-10 09:09:53',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10960,'AmericanExpress_Corp_Card','$source = \"AmericanExpress_Corp_Card\"\r\n$features = \"CREDIT_CARD\"\r\n$periodBufferDays = 30\r\n\r\n// Get Accounts\r\n$accountNumberText = get line starting \"Prepared For\" => get words after \"Prepared For\"\r\n$accountNumber = take last words $accountNumberText 2 => take words 1 => get text\r\n$accountName = take last words $accountNumberText 2 => take words 1 => get text\r\n\r\n// Get Period To\r\n$periodTo = get line starting \"Prepared For\" => get words after \"Prepared For\" => take last words 1 => get date \"M/d/yy\"\r\n\r\n// Get Opening and Closing Balance\r\ngo to page 1\r\ndelete text in box page.top page.bottom 480 page.right\r\n//Get Opening and Closing Balance\r\n@bal = get line starting \"Previous Balance\" => bottom => get line below\r\n$openingBalance = take words @bal 1 => get decimal\r\n$closingBalance = take last words @bal 1 => get decimal\r\n\r\n//Get Period From\r\n$periodFrom = get line containing \"Card Number\" => bottom => get line below => take words 1 => get date \"M/d/yy\"\r\n\r\n//Get transaction table\r\n@transactionsTop = get line containing \"Card Number\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get last line starting \"Total for\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\nignore header above 728\r\ndelete all lines containing \"Continued\"\r\n\r\n//Read Transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 47 87 400 470 570 => describe table false \"*Date[M/d/yy]\" TransactionType Details #Credit','2026-08-17 09:10:59',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10961,'Indian_Bank','$source = \"Indian_Bank\"\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodFromText = get line starting \"For period:\" => get words after \"For period:\"\r\n$periodFrom = take words $periodFromText 3 => get date \"d MMM yyyy\"\r\n$periodTo = take last words $periodFromText 3 => get date \"d MMM yyyy\"\r\n\r\n// Get Accounts\r\n$accountNumberText = get line containing \"Account Number\" => get words after \"Number\"\r\n$accountNumber = take words $accountNumberText 1 => get text\r\n$accountName = take words $accountNumberText 1 => get text\r\n\r\n// Get Opening and Closing Balance\r\ngo to page 1\r\n$openingBalanceTop = get line starting \"Opening Balance\" => top\r\n$openingBalanceBottom = get line starting \"Ending Balance\" => bottom\r\n$openingBalanceText = get text in box $openingBalanceTop $openingBalanceBottom 345 page.right\r\n$openingBalance = get words after $openingBalanceText \"Opening Balance\" => take words 2 => get decimal\r\n$closingBalance = get words after $openingBalanceText \"Ending Balance\" => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n$transactionsTop = get line containing \"Date Transaction Details\" => if not found then blank => bottom => get line below\r\n$transactionsBottom = get last line containing \"Ending Balance\" => if not found then blank => top => get line above\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Date Transaction Details\"\r\ndelete all lines containing \"Balance to Sheet\"\r\nignore footer below 30\r\n\r\n//Read Transactions\r\n$transactions = get multi page table $transactionsTop $transactionsBottom 70 125 280 360 440 535 => describe table false \"*Date[d MMM yyyy]\" Details #Debit #Credit #Balance','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10962,'AllyBank_COMBINED_CUSTOMER_STATEMENT','$source = \"AllyBank_COMBINED_CUSTOMER_STATEMENT\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\nset negative marker \"-\"\r\n\r\n// Get account details\r\n$accountName = get line containing \"Summary For:\" => get words after \"Summary For:\" => take words 2 => get text\r\n$accountNumber = get line starting \"Account Number:\" => get words after \"Account Number:\" => take words 1 => get text\r\n\r\ngo to page 1\r\n// Get statement period\r\n$periodFrom = get line containing \"Beginning Balance, as of\" => get words after \"as of\" => take words 1 => get date \"M/d/yyyy\"\r\n$periodTo = get line containing \"Ending Balance, as of\" => get words after \"as of\" => take words 1 => get date \"M/d/yyyy\"\r\n\r\n// Get opening and closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Beginning Balance, as of\" => get words after \"as of\" => skip words 1 => take words 1 => get decimal\r\n$closingBalance = get line containing \"Ending Balance, as of\" => get words after \"as of\" => skip words 1 => take words 1 => get decimal\r\n\r\n// Delete extra pages\r\ndelete all pages containing \"Equal Housing Lender\"\r\n\r\n// Get the start of the transaction\r\ngo to page 1\r\n@transactionsTop = get line containing \"Summary For:\" => bottom => get line below\r\n\r\n// Get the end of the transaction\r\ngo to page 1\r\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\r\n\r\n// Delete unwanted text\r\nignore header above 670\r\nignore footer below 40\r\ndelete all lines containing \"Joint Savings Account\"\r\ndelete all lines containing \"Summary For:\"\r\ndelete all lines containing \"www.ally.com\"\r\ndelete all lines containing \"Beginning Balance\"\r\ndelete all lines containing \"Ending Balance\"\r\ndelete all lines starting \"Product:\"\r\ndelete all lines starting \"Summary\"\r\ndelete all lines starting \"Beginning Balance, as\"\r\ndelete all lines starting \"Deposits and Other Credits\"\r\ndelete all lines starting \"Interest Paid This Period\"\r\ndelete all lines starting \"Withdrawals and Other Debits\"\r\ndelete all lines starting \"Ending Balance, as of\"\r\ndelete all lines starting \"Overdraft Fee Summary\"\r\ndelete all lines starting \"Overdraft Items Paid\"\r\ndelete all lines starting \"Overdraft Items Returned\"\r\ndelete all lines starting \"Activity\"\r\ndelete all lines starting \"Date Description Credits\"\r\ndelete all lines starting \"Account Ownership:\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 100 328 400 500  => describe table false *TransactionType Details #Credit #Debit','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10963,'CreditMutuel_Bank','$source = \"CreditMutuel_Bank\"\r\nset culture \"nl-NL\"\r\n\r\n// Delete left side rotated words\r\n@pageRight = get line starting \"SOLDE CREDITEUR AU\" => bottom => get line below => take words 1 => left => subtract 2\r\ndelete text in box on every page page.top 0 0 @pageRight => get text\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountnumber = get line containing \"N°\" => get words after \"PRO N°\" => take words 1 => get text\r\n$accountname = get text in box page.top 0 0 page.right => take words 3 => get text\r\n\r\n// Get opening/closing balance\r\n$openingbalance = get line starting \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => take last words 1 => get decimal\r\n$closingbalance = get last line containing \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => take last words 1 => get decimal\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodfrom = get line starting \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodto = get last line containing \"SOLDE CREDITEUR AU\" => get words after \"SOLDE CREDITEUR AU\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Date valeur Opération Débit\"\r\n@header1 = get line starting \"SOLDE CREDITEUR AU\" => bottom => get line below\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header1 1 => left => subtract 12\r\n@dateRight = take words @header1 1 => right => add 10\r\n@detailLeft = take words @header1 2 => take last words 1 => right => subtract 4\r\n@debitLeft = get words after @header \"Date valeur\" => take words 2 => take last words 1 => left => subtract 2\r\n@creditLeft = get words after @header \"Débit EUROS\" => take words 1 => left => subtract 1\r\n@creditRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date Date valeur Opération Débit\" => bottom => get line below\r\ndelete all lines starting \"Total des mouvements\"\r\n@transactionsBottom = get last line containing \"SOLDE CREDITEUR AU\" => top => get line above\r\n\r\n// Discard header and footer\r\ngo to page 1\r\nignore header above 702\r\nget line starting \"Information\" => if not found then blank => bottom => ignore footer below\r\nget last line ending \">>\" => if not found then blank => bottom => ignore footer below\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"RELEVE ET INFORMATIONS\"\r\ndelete all lines containing \"N°\"\r\ndelete all lines starting \"TAI LOONG\"\r\ndelete all lines starting \"Date Date valeur Opération\"\r\ndelete all lines containing \"SOLDE CREDITEUR AU\"\r\ndelete all lines starting \"Information\"\r\ndelete all lines ending \">>\"\r\ndelete all lines starting \"C/C\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @dateRight @detailLeft @debitLeft @creditLeft @creditRight => describe table false \"*Date[dd/MM/yyyy]\" - Details #Debit #Credit','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10964,'Libra_CreditUnion','$source = \"Libra_CreditUnion\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n\r\n// Delete left side rotated words\r\n@pageRight = get line containing \"Date Account Activity\" => get words before \"Account\" => take last words 1 => left => subtract 2\r\ndelete text in box on every page page.top 0 0 @pageRight => get text\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountnumber = get line containing \"Owner Number:\" => get words after \"Owner\" => take words 2 => get text\r\n$accountname = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n\r\n// Get period from/to\r\n$periodfrom = get line containing \"Balance Forward\" => get words before \"Balance Forward\" => take last words 1 => get date \"ddMMMyyyy\"\r\n$periodto = get last line containing \"Period Ending:\" => get words after \"Period Ending:\" => take words 1 => get date \"dd-MMM-yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Balance Forward\" => take last words 1 => get decimal\r\n$closingBalance = 0\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Account Activity Withdrawals\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = take words @header 2 => take last words 1 => left => subtract 5\r\n@debitLeft = get words before @header \"Deposits\" => take last words 1 => left => subtract 15\r\n@debitRight = get words before @header \"Deposits\" => take last words 1 => right => add 5\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 5\r\n@balanceRight = take last words @header 1 => right => add 12\r\n\r\ndelete all lines starting \"Date Account Activity\"\r\n\r\ngo to page 2\r\n@summaryTop = get line containing \"Number of cheques enclosed\" => top\r\n@summaryBottom = get line containing \"SUMMARY\" => if not found then blank => bottom\r\n@checkSummary = delete text in box @summaryTop @summaryBottom 0 page.right => get text\r\n\r\ngo to last page\r\n@summaryTop1 = get line containing \"Number of cheques enclosed\" => top\r\n@summaryBottom1 = get line containing \"SUMMARY\" => if not found then blank => bottom\r\n@checkSummary1 = delete text in box @summaryTop1 @summaryBottom1 0 page.right => get text\r\n\r\ngo to page 1\r\n@accountBusinessBasicSubTop = get line starting \"Business Basic, Sub\" => top\r\n@accountBusinessBasicSubBottom = get line starting \"Business Basic, Sub\" => if not found then blank => bottom\r\n@deleteBusinessSub = delete text in box @accountBusinessBasicSubTop @accountBusinessBasicSubBottom 0 page.right => get text\r\n\r\n// Get start & end of DEPOSITS table\r\ngo to page 1\r\n@depositsTop = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below\r\ndelete all lines ending \"www.libro.ca\"\r\ndelete all lines containing \"Statement Number:\"\r\ndelete all lines containing \"Period Ending:\"\r\ndelete all lines containing \"Owner Number:\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"1-\"\r\n@depositsBottom = get line starting \"Account Totals\" => if not found then blank => bottom => get line above\r\n\r\n@deposits = get multi page table @depositsTop @depositsBottom @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@varAgriInvestSubTop = get line starting \"AgriInvest, Sub\" => top\r\n@varAgriInvestSubBottom = get line starting \"AgriInvest, Sub\" => if not found then blank => bottom\r\n@deletevarAgriInvestSub = delete text in box @varAgriInvestSubTop @varAgriInvestSubBottom 0 page.right => get text\r\n\r\n// Get start & end of AgriInvest table\r\ngo to page 1\r\n@agriInvestSubTop = get line starting \"AgriInvest, Sub\" => if not found then blank => top => get line above => bottom => get line below\r\n@agriInvestSubBottom = get line starting \"AgriInvest, Sub\" => if not found then blank => bottom => get break below => get line at => top => get line above\r\n@agriInvestSub = get multi page table @agriInvestSubTop @agriInvestSubBottom @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@varspecialAccountSubTop = get line starting \"Special Account, Sub\" => top\r\n@varspecialAccountBottom = get line starting \"Special Account, Sub\" => if not found then blank => bottom\r\n@varspecialAccountSub = delete text in box @varspecialAccountSubTop @varspecialAccountBottom 0 page.right => get text\r\n\r\n// Get start & end of Special Account table\r\ngo to page 1\r\n@specialAccountSubTop = get line starting \"Special Account, Sub\" => if not found then blank => top => get line above => bottom => get line below\r\n@specialAccountBottom = get line starting \"Special Account, Sub\" => if not found then blank => bottom => get break below => get line at => top => get line above\r\n@specialAccount = get multi page table @specialAccountSubTop @specialAccountBottom @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@varRetailInstalmentLoanSubTop = get line starting \"Retail Instalment Loan, Sub\" => top\r\n@varRetailInstalmentLoanSubBottom = get line starting \"Retail Instalment Loan, Sub\" => if not found then blank => bottom\r\ndelete text in box @varRetailInstalmentLoanSubTop @varRetailInstalmentLoanSubBottom 0 page.right => get text\r\n\r\n// Get start & end of Retail Instalment Loan table\r\ngo to page 1\r\n@retailInstalmentLoanTop = get line starting \"LOANS\" => if not found then blank => bottom => get line below\r\n@retailInstalmentLoanBottom = get line starting \"Retail Instalment Loan, Sub\" => if not found then blank => bottom => get break below => get line at => top => get line above\r\n@retailInstalmentLoan = get multi page table @retailInstalmentLoanTop @retailInstalmentLoanBottom 0 315 400 500 @balanceRight => describe table false Details #Credit - *TransactionType\r\n\r\ngo to page 1\r\n@varTFSVariableSubTop = get line containing \"TFS Variable, Sub\" => top\r\n@varTFSVariableSubBottom = get line containing \"TFS Variable, Sub\" => if not found then blank => bottom\r\n@deleteTFSVariable = delete text in box @varTFSVariableSubTop @varTFSVariableSubBottom 0 page.right => get text\r\n\r\ngo to page 2\r\ndelete all lines starting \"Contract Number\"\r\ndelete all lines starting \"Annuitant\"\r\ndelete all lines starting \"Primary Beneficiaries\"\r\n@tFSVariableSubTop = get line starting \"TFS Variable, Sub\" => if not found then blank => bottom => get line above\r\n@tFSVariableSubBottom = get line above 0 => top => get line above\r\n@tFSVariableSub = get multi page table @tFSVariableSubTop @tFSVariableSubBottom @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@tFSVariableTop = get line containing \"TAX FREE SAVINGS PLANS\" => if not found then blank => bottom\r\ndelete text in box @tFSVariableTop 0 0 page.right\r\ndelete all lines containing \"TAX FREE SAVINGS PLANS\"\r\n\r\n// Get start & end of SHARES table\r\ngo to page 1\r\n@shareTop = get line starting \"SHARES\" => if not found then blank => bottom => get line below\r\n@shareBottom = get line above 0\r\n@share = get multi page table @shareTop @shareBottom @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@LoanVarTop = get line starting \"LOANS\" => top\r\n@LoanVarBottom = get line starting \"LOANS\" => if not found then blank => bottom\r\ndelete text in box @LoanVarTop @LoanVarBottom 0 page.right => get text\r\n\r\n// Get start & end of LOANS table 2\r\ngo to page 1\r\n@LoanTop = get line starting \"LOANS\" => if not found then blank => bottom => get line below\r\n@LoanBottom = get line starting \"Account Totals\" => if not found then blank => top => get line above\r\n@Loan1 = get multi page table @LoanTop @LoanBottom 0 315 400 500 @balanceRight => describe table false Details #Credit - *TransactionType\r\n\r\ngo to page 1\r\n@depositsVarTop = get line starting \"DEPOSITS\" => top\r\n@depositsVarBottom = get line starting \"DEPOSITS\" => if not found then blank => bottom\r\ndelete text in box @depositsVarTop @depositsVarBottom 0 page.right => get text\r\n\r\n// Get start & end of DEPOSITS table 2\r\ngo to page 1\r\n@depositsTop1 = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below\r\n@depositsBottom1 = get line starting \"Account Totals\" => if not found then blank => bottom => get line above\r\n@deposits1 = get multi page table @depositsTop1 @depositsBottom1 @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\ngo to page 1\r\n@depositsVar1Top = get line starting \"DEPOSITS\" => top\r\n@depositsVar1Bottom = get line starting \"DEPOSITS\" => if not found then blank => bottom\r\ndelete text in box @depositsVar1Top @depositsVar1Bottom 0 page.right => get text\r\n\r\n// Get start & end of DEPOSITS table 3\r\ngo to page 1\r\n@depositsTop2 = get line starting \"DEPOSITS\" => if not found then blank => bottom => get line below\r\n@depositsBottom2 = get line starting \"Account Totals\" => if not found then blank => bottom => get line above\r\n@deposits2 = get multi page table @depositsTop2 @depositsBottom2 @dateLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false Details #Debit #Credit *TransactionType\r\n\r\n// Read the transactions\r\n$transactions = combine described tables @deposits @specialAccount @agriInvestSub @retailInstalmentLoan @share @tFSVariableSub @Loan1 @deposits1 @deposits2','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10965,'TheHomeDepot_Card_US','$source = \"TheHomeDepot_Card_US\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n$periodBufferDays = 14\r\ndelete white words\r\n\r\n//Get Account details\r\ngo to page 1\r\n@accountDetailsBottom = get line containing \"Payment Information\" => top\r\n$accountNumber = get text in box page.top @accountDetailsBottom 400 page.right => take last words 1 => get text\r\n$accountName = get text in box 100 0 30 page.middleX => take words 2 => get text\r\n\r\n//Get Balances\r\n@summaryTop = get line containing \"Summary of Account Activity\" => bottom\r\n@summaryBottom = get line starting \"New Balance\" => bottom\r\n@summary = get text in box @summaryTop @summaryBottom 0 290\r\n$openingBalance = get words after @summary \"Previous Balance\" => get words between \"Previous Balance\" \"Payments\" => get decimal\r\n$closingBalance = get words after @summary \"New Balance\" => get decimal\r\n\r\n//Get dates\r\ngo to page 1\r\n@datesTop = get line containing \"Amount Over Credit Limit\" => top\r\n@datesBottom = get line containing \"Statement Closing Date\" => bottom\r\n@dates = get text in box @datesTop @datesBottom 45 280\r\ngo to page 1\r\n$periodFrom = get line starting \"Trans Date Description Reference #\" => bottom => get line below => bottom => get line below => take words 1 => get date \"MM/dd\"\r\ngo to page 1\r\n$periodTo = get words before @dates \"Next\" => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\ngo to page 1\r\n\r\n//Get start and end of table\r\n@transactionsTop = get line starting \"Trans Date Description Reference #\" => bottom => get line below => bottom => get line below\r\ndelete all lines containing \"Trans Date Description Reference #\"\r\ndelete all lines containing \"TOTAL CARD ENDING\"\r\ndelete all lines containing \"INTEREST CHARGED\"\r\ndelete all lines containing \"TOTAL FEES FOR THIS PERIOD\"\r\ndelete all lines containing \"FEES\"\r\n@transactionsBottom = get line starting \"TOTAL INTEREST FOR THIS PERIOD\" => top => get line above\r\n\r\nignore header above 735\r\nignore footer below 20\r\ndelete all lines containing \"ACTIVITY AND PROMOTIONS DETAIL\"\r\ndelete all lines containing \"PROMOTIONAL PURCHASE:\"\r\ndelete all lines containing \"TOTAL INTEREST FOR THIS PERIOD\"\r\ndelete all lines containing \"THIS PAGE INTENTIONALLY LEFT BLANK\"\r\ndelete all lines containing \"Account number ending in\"\r\n\r\n//Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 40 85 405 520 585 => describe table false \"*Date[MM/dd]\" TransactionType Details #Credit','2026-08-17 09:11:00',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10966,'BMO_Ligne_French','$source = \"BMO_Ligne_French\"\r\n$periodBufferdays = 14\r\nset culture \"fr-MA\"\r\n\r\n//Get Account details\r\ngo to page 1\r\n$accountName = get text in box 646 605 70 page.middleX => take words 3 => get text\r\ngo to page 1\r\n$AccountNumberTop = get line containing \"Placements autogérés de BMO Ligne\" => top\r\n$AccountNumberBottom = get line containing \"Dernier relevé au\" => bottom\r\n$AccountNumberText = get text in box $AccountNumberTop $AccountNumberBottom 400 page.right\r\n$accountNumber = get words after $AccountNumberText \"Compte non enregistré\" => take words 1 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n$periodfrom = get words after $AccountNumberText \"Dernier relevé au\" => take words 3 => get date \"dd MMM yyyy\"\r\n$periodto = get words before $AccountNumberText \"Dernier relevé au\" => take last words 3 => get date \"dd MMM yyyy\"\r\n\r\n//Get Balances\r\ngo to page 1\r\n$OpeningBalance = get line containing \"Date Activité Description\" => bottom => get line below => bottom => get line below => get words after \"Solde en espèces à\" => get decimal\r\n$closingBalance = get line containing \"Solde en espèces à la clôture\" => get words after \"Solde en espèces à la clôture\" => get decimal\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line containing \"Solde en espèces à\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get last line containing \"Solde en espèces à la clôture\" => top => get line above\r\n\r\nignore header above 600\r\nignore footer below 40\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Date Activité Description Quantité\"\r\ndelete all lines containing \"Solde en espèces à la clôture\"\r\ndelete all lines containing \"Solde en espèces à\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 60 135 210 380 520 590 => describe table false \"*Date[d MMM yyyy]\" TransactionType Details - #Credit','2026-08-25 09:33:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10967,'CentralStateBank_DateDescriptionAmountRef','$source = \"CentralStateBank_DateDescriptionAmountRef\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n$periodBufferDays = 7\r\n\r\n// Account name & Account number\r\ngo to page 1\r\n@AccountBottom = get line starting \"Account Number\" => top\r\n$accountname = get text in box 675 @AccountBottom 0 page.middleX => take words 3 => get text\r\n$accountNumber = get line starting \"Account Number\" => get words after \"Account Number\" => take words 1 => get text\r\n\r\n// Statement period\r\n$periodFrom = get line containing \"Statement Dates\" => get words after \"Statement Dates\" => take words 1 => get date \"M/dd/yy\"\r\n$periodTo = get line containing \"Statement Dates\" => get words after \"thru\" => take words 1 => get date \"M/dd/yy\"\r\n\r\n// Opening Balance\r\n$openingBalance = get line containing \"Previous Balance\" => get words after \"Previous Balance\" => take words 1 => get decimal\r\n\r\n// Closing Balance\r\n$closingBalance = get line containing \"Ending Balance\" => get words after \"Ending Balance\" => take words 1 => get decimal\r\n\r\n// Delete unwanted text\r\ndelete all lines containing \"(Continued)\"\r\ndelete all lines containing \"Date Check No Amount\"\r\ndelete all lines containing \"Denotes missing check numbers\"\r\ndelete all lines containing \"Checks and Withdrawals\"\r\ndelete all lines containing \"Primary Account:\"\r\nignore header above 645\r\n\r\n// Checks\r\ngo to page 1\r\n@ChecksTop = get line containing \"CHECKS IN NUMBER ORDER\" => if not found then blank => bottom => get line below\r\n@ChecksBottom = get last line containing \"Daily Balance\" => top => get line above\r\n$checks = get multi page table @ChecksTop @ChecksBottom 50 100 200 310 => describe table false \"Date[M/d]\" #ChequeNumber *#Debit\r\n\r\n// Delete Checks\r\ngo to page 1\r\n@DeleteChecksTop = get line containing \"CHECKS IN NUMBER ORDER\" => top\r\n@DeleteChecksBottom = get last line containing \"Daily Balance\" => top\r\n$DeleteChecks = delete text in box @DeleteChecksTop @DeleteChecksBottom 0 page.right => get text\r\n\r\n// Credits & Debits in single table\r\ngo to page 1\r\n@creditsTop = get line containing \"Date Description Amount\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get last line starting \"Daily Balance\" => if not found then blank => top => get line above\r\ndelete all lines starting \"Date Description Amount\"\r\n$credits = get multi page table @creditsTop @creditsBottom 50 100 340 430 560 => describe table false \"*Date[M/d]\" Details #Credit TransactionType\r\n\r\n// Combine transactions\r\n$transactions = combine described tables $credits $checks','2026-08-25 09:33:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10968,'Alliance_Bank','$source = \"Alliance_Bank\"\r\n$periodBufferDays = 7\r\n\r\n// Account name & Account number\r\ngo to page 1\r\n$accountname = get line containing \"Account No.\" => top => get line above => take words 2 => get text\r\n$accountNumber = get line containing \"Account No.\" => take last words 1 => get text\r\n\r\n// Statement period\r\ngo to page 1\r\n$periodFrom = get line containing \"BEGINNING BALANCE\" => get words before \"BEGINNING BALANCE\" => get date \"dd MM yy\"\r\n$periodTo = get line containing \"ENDING BALANCE\" => get words before \"ENDING BALANCE\" => get date \"dd MM yy\"\r\n\r\n// Opening & Closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"BEGINNING BALANCE\" => get words after \"BEGINNING BALANCE\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"ENDING BALANCE\" => get words after \"ENDING BALANCE\" => take words 1 => get decimal\r\n\r\n// Transactions Top & Bottom\r\ngo to page 1\r\n@TransactionsTop = get line containing \"BEGINNING BALANCE\" => if not found then blank => bottom => get line below\r\n@TransactionsBottom = get line containing \"ENDING BALANCE\" => if not found then blank => top => get line above\r\n\r\n// Delete unwanted text\r\ndelete all lines starting \"Date Transaction Details\"\r\ndelete all lines starting \"Tarikh Keterangan\"\r\ndelete all lines starting \"BEGINNING BALANCE\"\r\ndelete all lines starting \"ENDING BALANCE\"\r\ndelete all lines starting \"The items and balances\"\r\ndelete all lines starting \"Fourteen (14) days\"\r\ndelete all lines containing \"balance in Ringgit Malaysia\"\r\ndelete all lines starting \"Segala butiran dan\"\r\ndelete all lines containing \"puluh satu (21) hari\"\r\ndelete all lines containing \"tukaran mungkin turun\"\r\ndelete all lines containing \"aktifkan sebarang akaun\"\r\nignore header above 707\r\nignore footer below 105\r\n\r\n// Transactions\r\n$transactions = get multi page table @TransactionsTop @TransactionsBottom 50 95 300 350 420 490 560 => describe table false \"*Date[dd MM yy]\" Details TransactionType #Debit #Credit #Balance','2026-08-25 09:33:27',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10969,'CIBC_Costco_Card','$source = \"CIBC_Costco_Card\"\r\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD\"\r\n\r\n// Parse dates in French\r\nset culture \"fr-MA\"\r\nset negative marker \"CR\"\r\n$periodBufferDays = 15\r\n\r\n//Get account name and number\r\n$accountName = get line containing \"Numéro de compte\" => bottom => get line below => take words 4 => get text\r\n$accountNumber = get line containing \"Numéro de compte\" => bottom => get line below => take words 4 => get text\r\n\r\n//Get period from/to\r\n@Period = get line containing \"Date du relevé\" => bottom => get line below\r\n$periodFrom =  get line containing \"Opérations\" => get words after \"Opérations\" => take words 2 => get date \"d MMMM\"\r\n$periodTo = take words @Period 3 => get date \"d MMM yyyy\"\r\n\r\ngo to page 1\r\n//delete barcode area\r\ndelete text in box page.top page.bottom page.left 67\r\ndelete text in box page.top page.bottom 417 page.right\r\n\r\n//Get opening and closing balances\r\n$openingBalance = get line containing \"Solde antérieur\" => get words after \"Solde antérieur\" => take words 4 => get decimal\r\n$closingBalance = get line containing \"Solde total =\" => get words after \"Solde total =\" => take last words 4 => get decimal\r\n\r\n// Get start of Debit table\r\ngo to page 1\r\n@creditsTop = get line containing \"Description Montant\" => if not found then blank => bottom => get line below\r\n@creditsBottom = get line containing \"Total des\" => if not found then blank => top => get line above\r\n\r\ndelete all lines starting \"Vos nouveaux frais\"\r\ndelete all lines containing \"Indique les opérations\"\r\ndelete all lines containing \"Tout retour ou\"\r\ndelete all lines containing \"No de carte\"\r\ndelete all lines containing \"Date Date\"\r\n\r\n$credits = get multi page table @creditsTop @creditsBottom 75 109 490 550  => describe table false \"*Date[MMM d]\" Details #Debit\r\n\r\n// Get start of Interest table\r\ngo to page 1\r\n@intTop = get line containing \"annuel Montant\" => if not found then blank => bottom => get line below\r\n@intBottom = get line containing \"intérêts pour la\" => if not found then blank => top => get line above\r\n\r\n$interest = get multi page table @intTop @intBottom 75 105 490 550  => describe table false \"*Date[MMM d]\" Details #Credit\r\n\r\ngo to page 1\r\n@transactionsTop = get line containing \"Description Catégories\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get line containing \"Total pour\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing  \"Description\"\r\n\r\n$trans = get multi page table @transactionsTop @transactionsBottom 75 109 118 490 550  => describe table false \"*Date[MMM d]\" - Details #Credit\r\n\r\n// combine the transactions\r\n$transactions = combine described tables $credits $interest $trans','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10970,'CazenoveCapital','$source = \"CazenoveCapital\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n\r\n// Get account name/number\r\ngo to page 1\r\n$accountname = get text in box page.top 0 0 page.middleX => take words 3 => get text\r\n$accountnumber = get line containing \"Account No\" => take last words 3 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodfrom = get line containing \"Initial Balance\" => get words before \"Initial Balance\" => take last words 1 => get date \"dd.MM.yy\"\r\n$periodto = get last line containing \"Final Balance\" => get words before \"Final Balance\" => take words 1 => get date \"dd.MM.yy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Initial Balance\" => take last words 1 => get decimal\r\n$closingBalance = 0\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Posting Date\"\r\n\r\n// Column coordinates\r\n@detailLeft = get words before @header \"Transactions\" => take last words 1 => right => add 10\r\n@debitLeft = get words before @header \"Credit\" => take last words 1 => left => subtract 32\r\n@debitRight = get words before @header \"Credit\" => take last words 1 => right => add 10\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 10\r\n\r\ndelete all lines starting \"Report\"\r\ndelete all lines starting \"Investment\"\r\ndelete all lines starting \"Reference\"\r\ndelete all lines starting \"Statement of Account\"\r\ndelete all lines containing \"IBAN No\"\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Posting Date\" => top => get line above\r\n@transactionsBottom = get last line containing \"Final Balance\" => bottom => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Posting Date\" => top => get line above => top => ignore header above\r\nignore footer below 50\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Value Date\"\r\ndelete all lines containing \"Final Balance\"\r\n\r\ngo to page 1\r\n@InterestRatesTop = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates = delete text in box @InterestRatesTop 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@InterestRatesTop1 = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates1 = delete text in box @InterestRatesTop1 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@InterestRatesTop2 = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates2 = delete text in box @InterestRatesTop2 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@InterestRatesTop3 = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates3 = delete text in box @InterestRatesTop3 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@InterestRatesTop4 = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates4 = delete text in box @InterestRatesTop4 0 0 page.right => get text\r\n\r\ngo to page 1\r\n@InterestRatesTop5 = get line starting \"Interest Rates\" => top\r\n@deleteInterestRates5 = delete text in box @InterestRatesTop5 0 0 page.right => get text\r\n\r\ndelete all lines starting \"Interest Rates\"\r\ndelete all lines starting \"Eff Date\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 0 @detailLeft @debitLeft @debitRight @creditRight => describe table false TransactionType Details *#Debit *#Credit','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10971,'TriCountries_Bank_AccountActivity','$source = \"TriCountries_Bank_AccountActivity\"\r\n$periodBufferDays = 31\r\nremove page 2\r\ndelete white words\r\n\r\n//Account Details\r\ngo to page 1\r\n$accountNumber = get line containing \"Account Type Account Number Ending Balance\" => bottom => get line below => take last words 2 => take words 1 => get text\r\n$accountName = get text in box 665 645 50 page.middleX => take words 3 => get text\r\n\r\n// Get Periods\r\ngo to page 1\r\n@accountDetailstop = get line starting \"Account Summary\" => bottom\r\n@accountDetailsbottom = get line starting \"Ending Balance\" => bottom\r\n$accountDetails = get text in box @accountDetailstop @accountDetailsbottom 20 340\r\n$periodFrom = get words before $accountDetails \"Beginning Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\r\n$periodTo = get words before $accountDetails \"Ending Balance\" => take last words 1 => get date \"MM/dd/yyyy\"\r\n\r\n//Get Balances\r\ngo to page 1\r\n$openingBalance = get words after $accountDetails \"Beginning Balance\" => take words 1 => get decimal\r\n$closingBalance = get words after $accountDetails \"Ending Balance\" => take words 1 => get decimal\r\n\r\n//Get transactions TopBottom\r\ngo to page 1\r\n@transactionsTop = get line containing \"Post Date Description Withdrawals Deposits Balance\" => bottom => get line below => bottom => get line below\r\n@transactionsBottom = get last line containing \"Ending Balance\" => top => get line above\r\n\r\nignore header above 645\r\nignore footer below 38\r\n\r\n//Delete extra lines\r\ndelete all lines containing \"Post Date Description Withdrawals Deposits Balance\"\r\ndelete all lines containing \"Beginning Balance $\"\r\ndelete all lines containing \"Ending Balance\"\r\n\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 30 95 350 440 530 580 => describe table false \"*Date[MM/dd/yyyy]\" Details #Debit #Credit #Balance','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10972,'MCB_InternetBankingPro','$source = \"MCB_InternetBankingPro\"\r\n$periodBufferDays = 7\r\n$features = \"REVERSE_ORDER OPENING_BALANCE_FROM_FIRST_ROW\"\r\ndelete all pages containing \"According to Section 58\"\r\n\r\n// Account name & Account number\r\ngo to page 1\r\n$accountname = get line containing \"Account Name:\" => take last words 1 => get text\r\n$accountNumber = get line containing \"Account Name:\" => take last words 1 => get text\r\n\r\n// Statement period\r\ngo to page 1\r\n$periodFrom = get line containing \"Date Range:\" => get words after \"Date Range:\" => get words before \"-\" => get date \"d MMM yyyy\"\r\n$periodTo = get line containing \"reference & Description\" => bottom => get line below => skip words 1 => take words 1 => get date \"d/M/yyyy\"\r\n\r\n// Opening & Closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"reference & Description\" => bottom => get line below => take last words 1 => get decimal\r\n\r\ngo to page 1\r\n@closingBalanceTop = get last line containing \"reference & Description\" => bottom\r\n@closingBalanceBottom = get line containing \"The Mauritius Commercial Bank Ltd.\" => top\r\n$closingBalance = get text in box @closingBalanceTop @closingBalanceBottom 475 page.right => take last words 1 => get decimal\r\n\r\n// Transactions Top & Bottom\r\ngo to page 1\r\n@TransactionsTop = get line containing \"reference & Description\" => if not found then blank => bottom => get line below\r\n@TransactionsBottom = get last line containing \"The Mauritius Commercial Bank Ltd.\" => top => get line above\r\n\r\n// Delete unwanted text\r\ndelete all lines starting \"Internet Banking Pro\"\r\ndelete all lines starting \"Account Name:\"\r\ndelete all lines starting \"IBAN:\"\r\ndelete all lines starting \"BBAN:\"\r\ndelete all lines starting \"Currency:\"\r\ndelete all lines starting \"Date Range:\"\r\ndelete all lines starting \"Transaction Value Date\"\r\ndelete all lines containing \"reference & Description\"\r\nignore footer below 75\r\n\r\n// Transactions\r\n$transactions = get multi page table @TransactionsTop @TransactionsBottom 125 190 362 420 475 560 => describe table false \"*Date[d/M/yyyy]\" Details #Debit #Credit #Balance','2026-08-25 09:33:28',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10973,'Nevada_State_Bank_DateAmountDescription','$source = \"Nevada_State_Bank_DateAmountDescription\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\nremove page 2\r\n\r\n// Get account details\r\ngo to page 1\r\n$accountName = get line containing \"Primary Account\" => get words after \"Primary Account\" => take last words 1 => get text\r\n$accountNumber = get line containing \"Primary Account\" => get words after \"Primary Account\" => take last words 1 => get text\r\n\r\n// Get statement period\r\n$periodFrom = get line containing \"Last Statement:\" => get words after \"Last Statement:\" => get date \"MMMM d,yyyy\"\r\n$periodTo = get line containing \"This Statement:\" => get words after \"This Statement:\" => get date \"MMMM d,yyyy\"\r\n\r\n// Get Opening and Closing Balance\r\n$openingBalance = get line containing \"Previous Balance Deposits/Credits\" => bottom => get line below => take words 1 => get decimal\r\n$closingBalance = get line containing \"Previous Balance Deposits/Credits\" => bottom => get line below => take last words 1 => get decimal\r\n\r\n// Remove extra text\r\ndelete all lines containing \"Date Amount Description\"\r\ndelete all lines starting \"Continued ...\"\r\ndelete all lines starting \"Number.....\"\r\ndelete all lines containing \"Amount Number\"\r\n\r\nignore footer below 22\r\nignore header above 695\r\n\r\n// Get DEPOSITS/CREDITS table\r\ngo to page 1\r\n@CreditsTop = get line containing \"DEPOSITS/CREDITS\" => if not found then blank => bottom => get line below\r\n@CreditsBottom = get line containing \"CHARGES/DEBITS\" => if not found then blank => top => get line above\r\n@Credits = get multi page table @CreditsTop @CreditsBottom 30 90 175 580  => describe table false \"*Date[M/d]\" #Credit Details\r\n\r\n// Get CHARGES/DEBITS table\r\ngo to page 1\r\n@DebitsTop = get line containing \"CHARGES/DEBITS\" => if not found then blank => bottom => get line below\r\n@DebitsBottom = get line containing \"CHECKS PROCESSED\" => if not found then blank => top => get line above\r\n@Debits = get multi page table @DebitsTop @DebitsBottom 30 90 175 580  => describe table false \"*Date[M/d]\" #Debit Details\r\n\r\n// Get CHECKS PROCESSED table\r\ngo to page 1\r\n@CheckTop = get line containing \"CHECKS PROCESSED\" => if not found then blank => bottom => get line below\r\n@CheckBottom = get line containing \"Not in check sequence\" => if not found then blank => top => get line above\r\n@ChecksLeft = get multi page table @CheckTop @CheckBottom 30 90 150 218  => describe table false ChequeNumber \"*Date[M/d]\" #Debit\r\n@ChecksMiddle = get multi page table @CheckTop @CheckBottom 218 275 330 405  => describe table false ChequeNumber \"*Date[M/d]\" #Debit\r\n@ChecksRight = get multi page table @CheckTop @CheckBottom 405 460 530 595  => describe table false ChequeNumber \"*Date[M/d]\" #Debit\r\n\r\n// Combine all Tables\r\n$transactions = combine described tables @Credits @Debits @ChecksLeft @ChecksMiddle @ChecksRight','2026-09-08 10:16:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10974,'NewcastlePermanent','$source = \"NewcastlePermanent\"\r\n\r\n@headerLeft = get line starting \"Process date Effective date\" => take words 1 => left => subtract 2\r\n@deleteRotatedWords = delete text in box on every page page.top 0 0 @headerLeft => get text\r\n\r\n// Get account number/name\r\ngo to page 1\r\n$accountnumber = get line containing \"Account number\" => get words after \"Account number\" => take words 1 => get text\r\n$accountname = get line containing \"Account name\" => get words after \"Account name\" => take words 7 => get text\r\n\r\n// Get period from/to\r\ngo to page 1\r\n$periodfrom = get line containing \"Period:\" => get words after \"Period:\" => take words 3 => get date \"d MMMM yyyy\"\r\n$periodto = get line containing \"Period:\" => get words after \"to\" => take last words 3 => get date \"d MMMM yyyy\"\r\n\r\n// Get opening/closing balance\r\ngo to page 1\r\n$openingBalance = get line starting \"Opening account balance\" => get words after \"Opening account balance\" => take words 2 => get decimal\r\n$closingBalance = get line starting \"Closing account balance\" => get words after \"Closing account balance\" => take words 2 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Process date Effective date Card no Transaction details\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 5\r\n@date2Left = get words after @header \"Process date\" => take words 1 => left => subtract 1\r\n@cardNoLeft = get words after @header \"Effective date\" => take words 1 => left => subtract 1\r\n@detailLeft  = get words after @header \"Card no\" => take words 1 => left => subtract 3\r\n@debitLeft = get words after @header \"details\" => take words 1 => left => subtract 25\r\n@debitRight = get words before @header \"Credit\" => take last words 1 => right => add 10\r\n@creditRight = get words before @header \"Balance\" => take last words 1 => right => add 10\r\n@balanceRight = take last words @header 1 => right => add 10\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Process date Effective date Card no Transaction details\" => top => get line above\r\n@transactionsBottom = get last line starting \"Closing account balance\" => bottom => get line above\r\n\r\n// Discard header and footer\r\nget last line starting \"Process date Effective date Card no Transaction details\" => top => get line above => top => ignore header above\r\nignore footer below 35\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Your transactions\"\r\ndelete all lines starting \"Process date Effective date Card no Transaction details\"\r\ndelete all lines starting \"Opening account balance\"\r\ndelete all lines starting \"Transaction Totals\"\r\ndelete all lines starting \"Closing account balance\"\r\ndelete all lines starting \"Account number\"\r\ndelete all lines starting \"Statement number\"\r\ndelete all lines starting \"Page\"\r\ndelete all lines starting \"Here for good\"\r\ndelete all lines containing \"Totals\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @date2Left @cardNoLeft @detailLeft @debitLeft @debitRight @creditRight @balanceRight => describe table false \"*Date[d MMM yy]\" - TransactionType Details #Debit #Credit #Balance\r\n','2026-09-08 10:16:46',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10975,'Wealthtime','$source = \"Wealthtime\"\r\n$features = \"SKIP_MISSING_CLOSING_BALANCE_CHECK\"\r\n\r\n// Get account name/number\r\n$accountname = get text in box page.top 0 page.middleX page.right => take words 4 => get text\r\n$accountnumber = get line starting \"Investor Number\" => get words after \"Investor Number\" => take last words 1 => get text\r\n\r\n// Get period from/to\r\n$periodfrom = get line starting \"Statement Period\" => get words after \"Statement Period\" => take words 1 => get date \"dd/MM/yyyy\"\r\n$periodto = get line starting \"Statement Period\" => get words after \"to\" => take words 1 => get date \"dd/MM/yyyy\"\r\n\r\n// Opening and Closing Balance\r\n$openingbalance = 0\r\n$closingbalance = 0\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Date Transaction Transaction Amount\"\r\n\r\n// Column coordinates\r\n@dateLeft = take words @header 1 => left => subtract 10\r\n@detailLeft = get words after @header \"Date\" => take words 1 => left => subtract 5\r\n@amountLeft = get words after @header \"Date Transaction\" => take words 1 => left => subtract 15\r\n@amountRight = take last words @header 1 => right => add 15\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Date Transaction Transaction Amount\" => top => get line above\r\n@transactionsBottom = get last line starting \"Date Transaction Transaction Amount\" => bottom => get break below => get line at => top => get line above\r\n\r\ngo to page 1\r\n@nonTransactionEntryLine = get line starting \"Please note\"\r\n@nonTransactionTop = top @nonTransactionEntryLine => get line above => if not found then blank => bottom\r\n@nonTransactionBottom = top @nonTransactionEntryLine => get line above => if not found then blank => bottom => get line below => bottom => get line below => bottom\r\n@deleteNonTransactionEntry = delete text in box @nonTransactionTop @nonTransactionBottom 0 page.right => get text\r\n\r\n// Discard footer\r\ngo to page 1\r\nignore footer below 66\r\n\r\n// Delete extra lines from transactions\r\ndelete all lines starting \"Date Transaction Transaction Amount\"\r\ndelete all lines starting \"Investments\"\r\ndelete all lines starting \"Money\"\r\ndelete all lines starting \"Withdrawals\"\r\ndelete all lines starting \"Wealthtime\"\r\ndelete all lines starting \"Adviser\"\r\ndelete all lines starting \"Discretionary\"\r\ndelete all lines ending \"Charges\"\r\ndelete all lines starting \"Total\"\r\ndelete all lines starting \"Please note:\"\r\ndelete all lines starting \"Statement\"\r\ndelete all lines ending \"Statement\"\r\ndelete all lines starting \"Corporate Actions\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailLeft @amountLeft @amountRight => describe table false \"*Date[dd/MM/yyyy]\" Details #Credit','2026-09-08 10:16:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10976,'DynaMoney_Card','$source = \"DynaMoney_Card\"\r\n\r\n// can not take $features = \"CREDIT_CARD\" because balance have negative sign\r\n\r\n// Get Balances\r\n$openingBalance = get line containing \"Opening Balance\" => get words after \"Opening Balance\" => take words 1 => get decimal\r\n$closingBalance = get line containing \"Closing Balance\" => get words after \"Closing Balance\" => take words 1 => get decimal\r\n\r\n\r\n// Get Accounts and Periods\r\n$accountNumberText = get line starting \"Account Statement\" => get words after \"Account Number\"\r\n$accountNumber = take words $accountNumberText 1 => get text\r\n$accountName = take words $accountNumberText 1 => get text\r\n\r\n// Get statement period\r\n$PeriodFromText = get words after $accountNumberText \"Statement Period\"\r\n$PeriodFrom = take words $PeriodFromText 1 => get date \"d/M/yyyy\"\r\n$PeriodTo = take last words $PeriodFromText 1 => get date \"d/M/yyyy\"\r\n\r\n//Get transaction table\r\n@transactionsTop = get line containing \"Date Card Description Amount\" => if not found then blank => bottom => get line below\r\n@transactionsBottom = get last line containing \"Page\" => if not found then blank => top => get line above\r\n\r\ndelete all lines containing \"Call\"\r\n\r\n//Read Transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 27 80 158 463 540 => describe table false \"Date[d/M/yyyy]\" Details TransactionType *#Credit','2026-09-08 10:16:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10977,'CommonWealthBank_HomeLoan','$source = \"CommonWealthBank_HomeLoan\"\r\n$features = \"NO_TRANSACTION_YEAR\"\r\n\r\nset negative marker \"DR\"\r\n\r\ndelete white words\r\n// Discard rotated text on the left\r\n$panelData11 = delete text in box on every page page.top page.bottom 0 49 => get text\r\n\r\n// Discard headings in top left of page 1\r\n@panelTop = get line starting \"Your Statement\" => bottom => get line below => bottom\r\n@panelBottom = get line containing \"Enquiries\" => top\r\n$panelData = get text in box @panelTop @panelBottom 350 page.right\r\n\r\n// Get account number\r\n$accountNumber = get words after $panelData \"Account number\" => take words 1 => get text\r\n$accountName = get words after $panelData \"Account number\" => take words 1 => get text\r\n\r\n// Get period from/to\r\n@statementPeriod = get words after $panelData \"Statement period\" => take words 7\r\n$periodFrom = take words @statementPeriod 3 => get date \"d MMM yyyy\"\r\n$periodTo = get words before $panelData \"Required\" => take last words 3 => get date \"d MMM yyyy\"\r\n\r\n// Get Balances\r\n@openingBalance = get last line containing \"Opening balance\" => take last words 2\r\n$openingBalance = get decimal @openingBalance\r\n\r\n@closingBalance = get last line containing \"Closing balance\" => take last words 2\r\n$closingBalance = get decimal @closingBalance\r\n\r\n// Transactions Table starts here\r\ngo to page 1\r\n@transactionsTop = get line containing \"Date Transaction description Debits\" => bottom => get line below\r\n@transactionsBottom = get last line containing \"Closing balance\" => top => get line above\r\n\r\n\r\ndelete all lines containing \"Change in interest\"\r\ndelete all lines containing \"We confirm\"\r\ndelete all lines starting \"effective\"\r\ndelete all lines starting \"Interest rate\"\r\ndelete all lines containing \"Your Direct Debit\"\r\ndelete all lines containing \"per month from\"\r\ndelete all lines containing \"Your elected Direct\"\r\ndelete all lines containing \"remains unchanged\"\r\ndelete all lines containing \"commencing\"\r\ndelete all lines containing \"Required monthly\"\r\ndelete all lines containing \"Loan Term\"\r\ndelete all lines containing \"account number\"\r\ndelete all lines containing \"Interest rate as\"\r\ndelete all lines containing \"Opening balance\"\r\n\r\nignore header above 697\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom 50 90 87 315 395 380 455 560 => describe table false \"Date[d MMM]\" - Details #Debit - #Credit **#Balance','2026-09-08 10:16:47',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10978,'Nedbank_za_Van_Tot','$source = \"Nedbank_za_Van_Tot\"\r\ndelete rotated words\r\nset culture \"af-ZA\"\r\n\r\n//delete right side rotated word\r\n@getBalanceText = get line starting \"Tran Lys Nr Datum Beskrywing\"\r\n@saldoRight = bottom @getBalanceText => get line below => take last words 1 => right => add 1\r\n@deleteRotatedWords = delete text in box on every page page.top 0 @saldoRight page.right => get text\r\n\r\n// Get account name/number\r\n$accountname = get text in box page.top 0 page.middleX page.right => take words 4 => get text\r\n$accountnumber = get line containing \"Rekeningnommer:\" => get words after \"Rekeningnommer:\" => take words 1 => get text\r\n\r\n// Get period from/to\r\n$periodfrom = get text in box page.top 0 page.middleX page.right => get words after \"Van :\" => take words 3 => get date \"d MMM yyyy\"\r\n$periodto = get text in box page.top 0 page.middleX page.right => get words after \"Tot :\" => take words 3 => get date \"d MMM yyyy\"\r\n\r\nset culture \"en-US\"\r\n// Get opening/closing balance\r\n$openingbalance = bottom @getBalanceText => get line below => take last words 1 => get decimal\r\n$closingbalance = get last line starting \"Eindsaldo\" => get words after \"Eindsaldo\" => take words 1 => get decimal\r\n\r\n// Header and column coordinates\r\ngo to page 1\r\n@header = get line starting \"Tran Lys Nr Datum Beskrywing\"\r\n\r\n// Column coordinates\r\n@dateLeft = get words before @header \"Beskrywing\" => take last words 1 => left => subtract 5\r\n@detailLeft = get words after @header \"Datum\" => take words 1 => left => subtract 2\r\n@detailsRight = get words after @header \"Beskrywing\" => take words 1 => left => subtract 5\r\n@debitLeft = get words before @header \"Krediete\" => take last words 1 => left => subtract 3\r\n@creditLeft = get words after @header \"Debiete\" => take words 1 => left => subtract 5\r\n@balanceLeft = get words after @header \"Krediete\" => take words 1 => left => subtract 2\r\n@balanceRight = bottom @header => get line below => take last words 1 => right => add 5\r\n\r\n// Get the start and end of the transaction\r\ngo to page 1\r\n@transactionsTop = get line starting \"Tran Lys Nr Datum Beskrywing\" => top => get line below\r\n@transactionsBottom = get last line containing \"Eindsaldo\" => bottom => get line above\r\n\r\n// Discard header and footer\r\nignore footer below 50\r\nget last line containing \"Tran Lys Nr Datum Beskrywing\" => top => ignore header above\r\n\r\n//Delete extra lines\r\ndelete all lines starting \"Tran Lys Nr Datum Beskrywing\"\r\ndelete all lines containing \"Saldo oorgedra\"\r\ndelete all lines containing \"Saldo oorgebring\"\r\ndelete all lines containing \"Beginsaldo\"\r\ndelete all lines containing \"Eindsaldo\"\r\ndelete all lines ending \"Saldo\"\r\ndelete all lines starting \"Totale\"\r\ndelete all lines starting \"Soort rekening:\"\r\ndelete all lines ending \"bladsye :\"\r\ndelete all lines starting \"Van\"\r\ndelete all lines starting \"Tot\"\r\ndelete all lines starting \"Totale getal bladsye :\"\r\ndelete all lines starting \"Tydperk van staat\"\r\ndelete all lines starting \"Frekwensie :\"\r\ndelete all lines starting \"Datum van staat :\"\r\ndelete all lines containing \"Opening Balance\"\r\n\r\n// Read the transactions\r\n$transactions = get multi page table @transactionsTop @transactionsBottom @dateLeft @detailLeft @detailsRight @debitLeft @creditLeft @balanceLeft @balanceRight => describe table false \"*Date[dd/MM/yyyy]\" Details - #Debit #Credit #Balance','2026-09-15 10:10:56',0);
INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (10979,'UBS_Current_BookingdateDescriptionDebit','$source = \"UBS_Current_BookingdateDescriptionDebit\"\r\n$features = \"REVERSE_ORDER\"\r\n\r\n//Remove summary\r\n@delBottom = get line containing \"Account transactions\" => top\r\ndelete text in box page.top @delBottom 380 page.right\r\n\r\n//Get Account Number\r\n$accountNumber = get line containing \"IBAN\" => get text\r\n\r\n// Get Account Name\r\n$accountName = get line containing \"Account for Private Clients\" => top => get line above => take words 2 => get text\r\n\r\n//Get statement Period\r\ngo to page 1\r\n$periodFrom = get line containing \"Opening balance\" => top => get line above => top => get line above => take words 1 => get date d.MM.yyyy\r\ngo to page 1\r\n$periodTo = get line containing \"Closing balance\" => bottom => get line below => take words 1 => get date d.MM.yyyy\r\n\r\n// Get opening & closing Balance\r\ngo to page 1\r\n$openingBalance = get line containing \"Closing balance\" => take last words 1 => get decimal\r\n$closingBalance = get last line containing \"Opening balance\" => take last words 1 => get decimal\r\n\r\n//Get start & end of Transactions\r\ngo to page 1\r\n@TransactionTop = get line containing \"Trade date\" => bottom => get line below\r\n@TransactionBottom = get line containing \"Opening balance\" => top => get line above\r\n\r\n// Delete extra text\r\ndelete all lines starting \"Closing balance\"\r\ndelete all lines starting \"Opening balance\"\r\nignore header above 750\r\nignore footer below 45\r\n\r\n//Transactions\r\n$transactions = get multi page table @TransactionTop @TransactionBottom 35 112 300 272 407 476 560 => describe table false TransactionType Details - #Credit - *#Balance','2026-09-15 10:10:56',0);
